ns:RegisterQuestData({
[1578] = {id=1578,name="Supplying the Front",level=5,requiredLevel=5,faction="alliance",sharable=false,expansion=7,zoneID=38,mapID=48,description="The mountaineers of Loch Modan are fighting troggs, and having a busy time of it! They need constant supplies of new armor and weapons if we're ever to get a handle on those troggs. That's why my colleague Thorvald is there, trying to keep the mountaineers in good gear. So if you were to make some copper axes and copper chain belts and bring them to Thorvald, he would be obliged. He might even share his knowledge with you. Thorvald is in Loch Modan's southern guard tower.",rewardXP=740,rewardItems={33792},starts={{npcID=6031}},ends={{npcID=6030}},mapCandidates={npc={48,87},zone={38}},questType="standard"},
[1582] = {id=1582,name="Moonglow Vest",level=0,requiredLevel=0,faction="alliance",sharable=false,expansion=7,zoneID=1657,mapID=89,description="We in Darnassus, especially we craftsman, are quite busy. Young adventurers are eager to test themselves in the wilderness, and are in constant need of supplies. If you can help me fill my orders of leather goods, then perhaps I can teach you an advanced leatherworking technique.",rewardItems={6710},starts={{npcID=6034}},ends={{npcID=6034}},mapCandidates={npc={89},zone={1657}},questType="standard"},
[11650] = {id=11650,name="Just a Few More Things...",level=10,requiredLevel=10,faction="alliance",sharable=false,expansion=7,zoneID=4273,mapID=114,series={11645},description="As you may have noticed, we created the airstrip on the southern border of a magnataur den! The old man has put me in charge of finding a... ahem... creative solution to this situation: if we don't deal with them soon, they'll come down here and tear us limb from limb! That's where you come in. I want you to get me everything on this shopping list. Please.",rewardGold=105000,rewardXP=1415,starts={{npcID=25477}},ends={{npcID=25477}},mapCandidates={npc={114},zone={4273}},questType="standard",sourceQuests={11645},questLines={{id=530,name="Borean Tundra",orderIndex=118,flags=0}}},
[11679] = {id=11679,name="Reforging the Key",level=10,requiredLevel=10,faction="both",categories={},flags={"loremaster"},sharable=false,expansion=7,zoneID=3537,mapID=114,storyline={11559,11560,11561,11562,11563,11564,11565,11566,11569,11570,11571,11576,11582,11585,11587,11590,11595,11596,11597,11598,11599,11600,11601,11602,11603,11604,11613,11614,11615,11616,11618,11619,11620,11624,11625,11626,11627,11628,11629,11630,11631,11633,11634,11635,11636,11637,11638,11642,11643,11644,11645,11646,11648,11649,11650,11651,11652,11653,11658,11663,11670,11671,11672,11674,11675,11677,11678,11679,11680,11681,11682,11683,11684,11685,11686,11687,11689,11692,11693,11694,11695,11697,11698,11699,11700,11701,11703,11705,11706,11708,11710,11712,11713,11715,11716,11717,11718,11719,11720,11721,11722,11723,11725,11726,11727,11728,11733,11788,11789,11790,11791,11792,11793,11794,11795,11796,11797,11798,11864,11865,11868,11869,11870,11871,11872,11873,11876,11878,11879,11881,11884,11889,11890,11892,11893,11894,11895,11896,11897,11899,11901,11902,11903,11904,11906,11907,11908,11909,11912,11913,11914,11916,11918,11919,11929,11930,11931,11932,11936,11938,11941,11942,11943,11944,11946,11949,11950,11951,11956,11957,11961,11962,11963,11965,11967,11968,11969,12019,12035,12086,12088,12728},series={11574,11575,11587,11590,11646,11648,11663,11671},description="Delays, delays... the one thing we cannot afford right now! As much as I hate to disturb Lord Surristrasz , he's our only hope of saving our beloved Evanor. Bring him the key fragments and hope that his mood is favorable. Hurry, <class>, our assault team is waiting.",objectivesText="Donathan wants you to speak to Surristrasz on Amber Ledge. Progress: You dare approach me, mortal? For the sake of your unborn children, pray that your cause is worthwhile.",rewardItems={34909},starts={{npcID=25262}},ends={{npcID=24795}},mapCandidates={npc={114},zone={3537}},questType="standard",sourceQuests={11671},questLines={{id=530,name="Borean Tundra",orderIndex=83,flags=0}},db2PoiMapID=571,db2PoiUiMapID=114},
[11797] = {id=11797,name="The Siege",level=10,requiredLevel=10,faction="alliance",sharable=false,expansion=7,zoneID=3537,mapID=114,series={11727,11889,11897},description="Well, well, well. It's good to see Arlos bring out the big guns. Don't get me wrong - our lads are doing the best they can, but someone of your renown fighting alongside them could really turn the tides for us. I'm not sure how much longer we can hold out against these undead Nerubians. What do you say you get out there and kill me some creepers? Show these boys how it's done.",rewardGold=297900,rewardXP=1415,rewardChoices={36883,38208,36878,36881,36879,36880},starts={{npcID=25816}},ends={{npcID=25816}},mapCandidates={npc={114},zone={3537}},questType="standard",sourceQuests={11727},questLines={{id=530,name="Borean Tundra",orderIndex=2,flags=0}}},
[12047] = {id=12047,name="Something That Doesn't Melt",level=15,requiredLevel=15,faction="both",sharable=false,expansion=7,zoneID=65,mapID=115,series={12045,12046},description="No no no! Those ice shards didn't work at all! They'll melt before they even do any damage. That's the last time I'll trust Narf's word on materials. This means we need something else entirely for the shrapnel. I know! I'm brilliant. Bone splinters. There are some bones all around here that the jormungar have been gnawing on pretty thoroughly. Go check them out and see if you can find me some splintered bone that I can use.",rewardGold=105000,rewardXP=2090,rewardItems={36730},rewardChoices={37948,37991,38035,38080,38072},starts={{npcID=26661}},ends={{npcID=26661}},mapCandidates={npc={115},zone={65}},questType="standard",sourceQuests={12046},questLines={{id=529,name="Dragonblight",orderIndex=139,flags=0}}},
[12076] = {id=12076,name="Messy Business",level=15,requiredLevel=15,faction="both",sharable=false,expansion=7,zoneID=65,mapID=115,series={12112,12075,12077},description="Even at first glance, the sample you brought me shows obvious signs of some kind of corrosive spit. It would be a natural assumption that the same substance these worms use to burrow through the ground has allowed them a formidable weapon against the Ice Giants. Take this scraper and pick a fight with some of the worms. When they spit on you, use the scraper to remove it and bring it back to me. Get me a couple samples - I'm going to have to use it as the base for an elixir.",rewardGold=105000,rewardXP=2090,starts={{npcID=26659}},ends={{npcID=26659}},mapCandidates={npc={115},zone={65}},questType="standard",sourceQuests={12075},questLines={{id=529,name="Dragonblight",orderIndex=144,flags=0}}},
[12151] = {id=12151,name="Wanton Warlord",level=15,requiredLevel=15,faction="both",sharable=false,expansion=7,zoneID=65,mapID=115,series={12146,12147,12148,12149,12150},description="There's no reason to suspect Dregmar's words are anything but true. Whether Grom'thar defeats you or is defeated by you, he can wash his hands of this. Follow his instructions... take the horn that you brought me earlier, travel to the ring of torches south of the Azure Dragonshrine, and blow it to announce your challenge. When Grom'thar the Thunderbringer arrives, kill him and bring me his head.",rewardGold=315000,rewardXP=3135,rewardItems={36853},rewardChoices={38156,38157,38155,38154,38130,38224},starts={{npcID=26983}},ends={{npcID=26983}},mapCandidates={npc={115},zone={65}},questType="standard",sourceQuests={12150}},
[12469] = {id=12469,name="Return to Sender",level=15,requiredLevel=15,faction="both",sharable=false,expansion=7,zoneID=65,mapID=115,series={12044},description="Upon closer examination, the goblin appears to have been running a pack full of explosives across the wastes for delivery. The harpy feathers half-buried in the snow nearby suggest how he met his ill fate. It appears that the goblin was bringing the explosives towards the Wrath Gate from somewhere to the east. It seems most prudent to follow the ridge back to the east and inform the sender of their runner's fate.",rewardGold=10500,rewardXP=260,starts={{npcID=26896}},ends={{npcID=26660}},mapCandidates={npc={115},zone={65}},questType="standard",nextQuests={12044}},
[12507] = {id=12507,name="Strange Mojo",level=20,requiredLevel=20,faction="both",sharable=false,expansion=7,zoneID=66,mapID=121,series={12510,12514},description="This bottle of strange mojo may be the key to what is truly going on here. The Zandalari troll Hexxer Ubungo , back at The Argent Stand, may want to take a look at it.",rewardGold=26250,rewardXP=690,ends={{npcID=28062}},mapCandidates={npc={121},zone={66}},questType="standard",questLines={{id=536,name="Zul'Drak",orderIndex=47,flags=0}}},
[12517] = {id=12517,name="Rogues Deck",level=1,requiredLevel=1,faction="both",requiredProfessions={"inscription"},categories={"seasonal"},flags={"loremaster"},sharable=false,event="Darkmoon Faire",expansion=7,storyline={12517},description="Now that you have gathered all of the Rogue cards together into a deck, another card appears on top. It depicts a fortune teller that seems to stare at you no matter how you hold the card. You feel the card could be used to communicate with someone or something.",objectivesText="Use the Rogues Deck to summon a Darkmoon Fortune Teller and give the deck to them. Progress: I see that you have managed to collect a deck of Rogues! I'm impressed.",rewardXP=50,rewardItems={37140,37143,37156,37163,38318,39354,39507,39509,43039,43103,43115,71634,71638,131276},starts={{npcID=30481}},mapCandidates={npc={},zone={}},questGiverID=30481,questType="standard",startItems={37163}},
[12518] = {id=12518,name="Mages Deck",level=1,requiredLevel=1,faction="both",requiredProfessions={"inscription"},categories={"seasonal"},flags={"loremaster"},sharable=false,event="Darkmoon Faire",expansion=7,storyline={12518},description="Now that you have gathered all of the Mage cards together into a deck, another card appears on top. It depicts a fortune teller that seems to stare at you no matter how you hold the card. You feel the card could be used to communicate with someone or something.",objectivesText="Use the Mages Deck to summon a Darkmoon Fortune Teller and give the deck to them. Progress: I see that you have managed to complete a deck of Mages! Congratulations!",rewardXP=50,rewardItems={3358,3818,3819,3821,43105,43119,44148,44184,44213,44215},starts={{npcID=30481}},mapCandidates={npc={},zone={}},questGiverID=30481,questType="standard",startItems={44148}},
[12524] = {id=12524,name="Venture Co. Misadventure",level=20,requiredLevel=20,faction="both",sharable=false,expansion=7,zoneID=3711,mapID=119,series={12525},description="Ever since we arrived, the Venture Company has hampered our efforts to secure our campsite and survey the area. Normally, we wouldn't care what they were up to, but they've started antagonizing our scouts and shooting down supply flights. We can't allow this insult to stand. Hemet Nesingwary's expedition came here to hunt, and hunt it shall. Go to Swindlegrin's Dig, on the far side of the crystal pillar to the northeast, and kill any Venture Company employee you see!",rewardGold=105000,rewardXP=2765,starts={{npcID=28032}},ends={{npcID=28032}},mapCandidates={npc={119},zone={3711}},questType="standard",questLines={{id=534,name="Sholazar Basin",orderIndex=2,flags=0}}},
[12597] = {id=12597,name="Something for the Pain",level=20,requiredLevel=20,faction="both",categories={},flags={"loremaster"},sharable=false,expansion=7,zoneID=66,mapID=121,storyline={12504,12505,12506,12507,12508,12510,12512,12514,12516,12552,12553,12554,12555,12557,12583,12584,12596,12597,12598,12599,12606,12623,12627,12628,12629,12630,12631,12632,12633,12637,12638,12642,12643,12646,12647,12648,12649,12653,12661,12663,12664,12665,12666,12667,12668,12669,12672,12674,12675,12676,12677,12684,12685,12712,12713,12721,12729,12730,12740,12859,12861,12883,12884,12894,12901,12902,12903,12904,12912,12914,12916,12919,12932,12933,12934,12935,12936,12948,12954},description="Gritty as my men are, they're still mortal. Wounds and pain diminish their ability to perform their missions. No amount of training changes that simple fact of life. Thankfully, one of our alchemists has developed a recipe for a salve that binds to our bandages and greatly reduces the pain our soldiers experience. The salve requires a special poppy these trolls cultivate just west of here. Go to Drak'Sotra Fields and harvest some of them to keep our stockpiles from running out.",objectivesText="Captain Brandon at Drak'Sotra wants you to collect 5 Mature Water-Poppies from Drak'Sotra Fields. Progress: Have you collected the water-poppies, <name>?",rewardGold=26250,rewardXP=690,rewardItems={38552},starts={{npcID=28042}},ends={{npcID=28042}},mapCandidates={npc={121},zone={66}},questType="standard",sourceQuests={12740},questLines={{id=536,name="Zul'Drak",orderIndex=32,flags=0}},db2PoiMapID=571,db2PoiUiMapID=121},
[12712] = {id=12712,name="The Key of Warlord Zol'Maz",level=20,requiredLevel=20,faction="both",sharable=false,expansion=7,zoneID=66,mapID=121,series={12721},description=", we need a key to unlock the chains of the rhino god, Akali. Even now he is being prepared for the slaughter. The Drakkari warlord, Zol'Maz, carries the key. Hearing of your exploits, he has secluded himself and his family at their stronghold up the steps to the northeast. The warlord is strong and you will need help. If you were to combine the tiki, sword and incantation of his family members, you would be able to summon such help as you challenge him before his home's gate.",rewardXP=3455,starts={{npcID=28401}},ends={{npcID=28401}},mapCandidates={npc={121},zone={66}},questType="standard",sourceQuests={12685},questLines={{id=536,name="Zul'Drak",orderIndex=75,flags=0}}},
[12713] = {id=12713,name="Betrayal",level=20,requiredLevel=20,faction="both",sharable=false,expansion=7,zoneID=66,mapID=121,series={12631,12633,12637,12638,12629,12643,12648,12649,12661,12669,12677,12676},description="The time has come to end this charade, . As valuable as your information has been, we must bring Drakuru down and bring his project to an end before his freaks are unleashed. We've modified your scepter for the job. When the time is right, you will be able to use it on Drakuru's Blightbloods and turn them against him. It's your only hope of defeating him. Fight well.",rewardGold=315000,rewardXP=4150,rewardItems={39664,40425},rewardChoices={39655,39653,39652},starts={{npcID=28518}},ends={{npcID=28518}},mapCandidates={npc={121},zone={66}},questType="standard",sourceQuests={12652,12676},questLines={{id=536,name="Zul'Drak",orderIndex=28,flags=0}}},
[12798] = {id=12798,name="Swords Deck",level=1,requiredLevel=1,faction="both",requiredProfessions={"inscription"},categories={"seasonal"},flags={"loremaster"},sharable=false,event="Darkmoon Faire",expansion=7,storyline={12798},description="Now that you have gathered all of the Swords cards together into a deck, another card appears on top. It depicts a fortune teller that seems to stare at you no matter how you hold the card. You feel the card could be used to communicate with someone.",objectivesText="Use the Swords Deck to summon a Darkmoon Fortune Teller and give the deck to them. Progress: I see that you have managed to complete a deck of Swords. Excellent.",rewardXP=50,rewardItems={3355,3356,3357,3369,37164,39894,39895,39897,42922,43104,43117,44142,131277},starts={{npcID=30481}},mapCandidates={npc={},zone={}},questGiverID=30481,questType="standard",startItems={37164}},
[12819] = {id=12819,name="Just Around the Corner",level=25,requiredLevel=25,faction="both",sharable=false,expansion=7,zoneID=67,mapID=120,series={12818,12826,12820},description="Blast it! Where are my tools? I had them here just a moment ago. Oh! I probably forgot them when I was setting up that minefield in the west. That's mildly inconvenient. I'd be quite appreciative if you could go get them for me. You'll need to watch your step though... you should be able to use the same path that I did to get out. Oh, and don't try to fly in... I had the presence of mind to set up turrets to shoot down anything that might fly, and they aren't very discerning in who they target.",rewardGold=105000,rewardXP=3440,starts={{npcID=29431}},ends={{npcID=29431}},mapCandidates={npc={120},zone={67}},questType="standard",sourceQuests={12818},questLines={{id=535,name="The Storm Peaks",orderIndex=1,flags=0}}},
[12890] = {id=12890,name="If Size Mattered...",level=1,requiredLevel=1,faction="alliance",sharable=false,expansion=7,zoneID=67,mapID=120,mapCandidates={npc={},zone={67}},questType="standard"},
[12980] = {id=12980,name="The Armor's Secrets",level=25,requiredLevel=25,faction="both",sharable=false,expansion=7,zoneID=67,mapID=120,series={12979},description="The presence of that armor plate is disorienting, but we need to find out all we can from it. It could be part of one of Valduran's schemes. He's dedicated an extraordinary amount of effort to mining, refining, smithing, and testing this metal. To the east, along the northern mountain face, is a building called Mimir's Workshop. It hasn't been used in quite some time, but if we're lucky, some of its attendants are still functional. Take your armor plate there and learn what you can from it.",rewardGold=280900,rewardXP=3440,starts={{npcID=30152}},ends={{npcID=30152}},mapCandidates={npc={120},zone={67}},questType="standard",sourceQuests={12979},questLines={{id=535,name="The Storm Peaks",orderIndex=43,flags=0}}},
[13011] = {id=13011,name="Culling Jorcuttar",level=25,requiredLevel=25,faction="both",sharable=false,expansion=7,zoneID=67,mapID=120,description="The jormungar are a nuisance best dealt with quickly. If given any quarter, they breed like hares and spread like fire. They have appeared southwest of here, in the Hibernal Cavern. If their spawnmother is not slain soon, they will gain a foothold in our region. She cannot refuse food. Take this knife and get the flank of a bear corpse from their cave. Place it near her crater and kill her as she feeds.",rewardGold=105000,rewardXP=3440,starts={{npcID=30105}},ends={{npcID=30105}},mapCandidates={npc={120},zone={67}},questType="standard"},
[13058] = {id=13058,name="Changing the Wind's Course",level=25,requiredLevel=25,faction="horde",sharable=false,expansion=7,zoneID=67,mapID=120,description="At last, we have all that we need to right the wrongs of the North Wind and its followers. You have attuned the Lorehammer to Stormhoof's time and his persona. Take the hammer again, head to the Temple of Life in the plains to the northwest. Use the hammer to assume the role of Stormhoof. Face the North Wind as Stormhoof, but realize that for the timeline to be restored, Stormhoof must die as the North Wind weakens. Then, you must find and use the Horn of Elemental Fury to destroy the North Wind.",rewardGold=210000,rewardXP=4300,rewardChoices={43186,43185},starts={{npcID=30381}},ends={{npcID=30381}},mapCandidates={npc={120},zone={67}},questType="standard",sourceQuests={13048,13049},questLines={{id=535,name="The Storm Peaks",orderIndex=70,flags=0}}},
[13270] = {id=13270,name="Cloth Scavenging",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=3537,mapID=114,rewardXP=175,starts={{npcID=26969}},ends={{npcID=26969}},mapCandidates={npc={114},zone={3537}},questType="standard"},
[13272] = {id=13272,name="Cloth Scavenging",level=10,requiredLevel=10,faction="both",sharable=false,expansion=7,zoneID=4395,mapID=125,rewardXP=175,starts={{npcID=28699}},ends={{npcID=28699}},mapCandidates={npc={},zone={4395}},questGiverID=28699,questTurnInID=28699,questType="standard"},
[13311] = {id=13311,name="Demons Deck",level=1,requiredLevel=1,faction="both",requiredProfessions={"inscription"},categories={"seasonal"},flags={"loremaster"},sharable=false,event="Darkmoon Faire",expansion=7,storyline={13311},description="Now that you have gathered all of the Demon cards together into a deck, another card appears on top. It depicts a fortune teller that seems to stare at you no matter how you hold the card. You feel the card could be used to communicate with someone or something.",objectivesText="Use the Demons Deck to summon a Darkmoon Fortune Teller and give the deck to them. Progress: I see that you have managed to complete a deck of Demons! Congratulations!",rewardXP=50,rewardItems={44158,44185,44217,44218,44219},starts={{npcID=30481}},mapCandidates={npc={},zone={}},questGiverID=30481,questType="standard",startItems={44158}},
[13528] = {id=13528,name="Buzzbox 723",level=5,requiredLevel=5,faction="alliance",sharable=false,expansion=7,zoneID=148,mapID=62,series={13521,13527,13554},description="There are a couple other forms of wildlife that we've verified infected. It's actually good news that the crabs appear to have caught this from the bears - hopefully that means this all stems from one source. We need to focus our attention on those bears now. Buzzbox 723 is near the waterfalls to the east. It's going to be messy work, but it's necessary - I'll need you to bring some fresh bear guts to that buzzbox for analysis. We'll go from there once I have the information.",rewardGold=280900,rewardXP=740,rewardItems={44913},starts={{npcID=32977}},ends={{npcID=194122}},mapCandidates={npc={62},zone={148}},questType="standard",sourceQuests={13527},questLines={{id=510,name="Darkshore",orderIndex=4,flags=0}}},
[13566] = {id=13566,name="Ritual Materials",level=5,requiredLevel=5,faction="alliance",sharable=false,expansion=7,zoneID=148,mapID=62,series={13569},description="While we tend to Grimclaw, I would like you to peacefully gather some ritual materials for me from the nearby wildlife. I need whiskers from the moonstalkers to the west- pluck them from the sleeping ones and move away quickly. I need hair from the doe to the east, just avoid the stags. Finally, I need fur from the bears along the water to the northeast. Wait until they catch a fish, then get the sample quickly and get away before they finish eating. Please do not harm any of them.",rewardGold=280900,rewardXP=740,rewardItems={44969,45027,45885},starts={{npcID=33048}},ends={{npcID=33048}},mapCandidates={npc={62},zone={148}},questType="standard",sourceQuests={13564},questLines={{id=510,name="Darkshore",orderIndex=9,flags=0}}},
[13871] = {id=13871,name="Security!",level=7,requiredLevel=7,faction="horde",sharable=false,expansion=7,zoneID=331,mapID=63,description="It's not as like I haven't got enough to think about here! Keeping this place operational is hard enough without constant elf and draenei harassment. Now, on top of everything, there's an assassin lurking around the camp who's killed an important diplomat... on my watch! Whoever it is couldn't have gotten far, . Scour the camp until you find her and then avenge the diplomat! At least I can bring the assassin's head with me when I have to answer to Hellscream.",rewardGold=105000,rewardXP=1010,rewardItems={46147},rewardChoices={56718,56719,56720,131308},starts={{npcID=17304}},ends={{npcID=17304}},mapCandidates={npc={63},zone={331}},questType="standard",sourceQuests={13870},questLines={{id=516,name="Ashenvale, Horde",orderIndex=15,flags=0}}},
[14138] = {id=14138,name="Taking Care of Business",level=1,requiredLevel=1,faction="horde",requiredRaces={9},categories={},flags={"loremaster"},sharable=false,expansion=7,zoneID=4737,mapID=194,storyline={14069,14070,14071,14075,14109,14110,14113,14115,14116,14120,14121,14122,14123,14124,14125,14126,14138,14153,24488,24502,24503,24520,24567,25473,26711,26712,28349,28414,90869},description="With all of the troubles down in the Kaja'mine, Foreman Dampwick 's been going crazy trying to find you. He said something about some 'defiant trolls'. The kaja'mite that our trolls are mining is critical ingredient in Kaja'Cola. That bubbly stuff is making us a fortune, and it's going to get you a promotion to Trade <Prince/Princess>! But first, we have to get production flowing again. You'll find the foreman to the east. Here, give him this as an incentive to get his act together.",objectivesText="Deliver Sassy's Incentive to Foreman Dampwick at KTC Headquarters on Kezan . Progress: Um... everything's going great. Yeah. What's that?",rewardXP=25,rewardItems={60203},starts={{npcID=34668}},ends={{npcID=34872}},mapCandidates={npc={194},zone={4737}},questType="standard",questLines={{id=5439,name="Bilgewater Port",orderIndex=0,flags=0}},db2PoiMapID=648,db2PoiUiMapID=194},
[24952] = {id=24952,name="Rocket Boot Boost",level=1,requiredLevel=1,faction="horde",requiredRaces={9},categories={"campaign"},flags={"loremaster"},sharable=false,expansion=7,zoneID=4720,mapID=174,storyline={14001,14014,14019,14021,14031,14233,14234,14235,14236,14237,14238,14239,14240,14241,14242,14243,14244,14248,14303,14326,14445,14473,14474,24671,24741,24744,24816,24817,24856,24858,24859,24864,24868,24897,24901,24924,24925,24929,24937,24940,24942,24945,24946,24952,24954,24958,25024,25058,25066,25093,25098,25099,25100,25109,25110,25122,25123,25125,25184,25200,25201,25202,25203,25204,25207,25213,25214,25243,25244,25251,25265,25267},series={24925,24929,24937,24940,24942,24954,24958,25023,25024},description="You need to get those boots down into the caldera to Hobart Grapplehammer . Now that they're infused with the leftover rockin' powder, they should have enough thrust to get you all the way there on one shot. When you're ready, activate the boots. Don't worry, they're automatically set to land you safely. I think.",objectivesText="Use the Rockin' Powder Infused Rocket Boots and deliver them to Hobart Grapplehammer . Progress: Well there you are!",rewardGold=7150,rewardXP=25,rewardItems={52032,52912,52936,52958,131842},starts={{npcID=38738}},ends={{npcID=38120}},mapCandidates={npc={174},zone={4720}},questType="standard",sourceQuests={24942,24945,24946},questLines={{id=571,name="The Lost Isles",orderIndex=43,flags=0}},campaigns={{id=314,title="Siren Isle",questLineID=571,questLineOrder=0},{id=316,title="Dragonflight Intro - Alliance",questLineID=571,questLineOrder=0}},db2PoiMapID=648,db2PoiUiMapID=174},
[25473] = {id=25473,name="Kaja'Cola",level=1,requiredLevel=1,faction="horde",requiredRaces={9},categories={},flags={"loremaster"},sharable=false,expansion=7,zoneID=4737,mapID=194,storyline={14069,14070,14071,14075,14109,14110,14113,14115,14116,14120,14121,14122,14123,14124,14125,14126,14138,14153,24488,24502,24503,24520,24567,25473,26711,26712,28349,28414,90869},series={14069,14071,14075,24488,24502,24503,24520,24567,28349,28414},description="Sassy's been riding me to supply some Kaja'cola for the party that's being thrown in your honor later today. Oops, was it supposed to be a surprise? You didn't hear it from me! Anywho, with production down these last few days, this is all that I managed to get made. Would you take it to her?",objectivesText="Deliver the Six-Pack of Kaja'Cola to Sassy Hardwrench at KTC Headquarters on Kezan . Progress: <Sassy eyes the six-pack warily, as if she expects it to explode as soon as you hand it to her.> We need more Kaja'Cola than this! I swear I'm going to fire Dampwick if I don't kill him first!",rewardGold=5350,rewardXP=25,rewardItems={49884,54453},starts={{npcID=34872}},ends={{npcID=34668}},mapCandidates={npc={194},zone={4737}},questType="standard",sourceQuests={14069,14075},questLines={{id=5439,name="Bilgewater Port",orderIndex=3,flags=0}},db2PoiMapID=648,db2PoiUiMapID=194},
[25552] = {id=25552,name="Brood of Evil",level=30,requiredLevel=30,faction="both",sharable=false,expansion=7,zoneID=616,mapID=198,series={25644,25553},description="This egg you recovered is an alarming sign, . The Twilight dragons are usually raised from stolen eggs from other dragonflights, which are then modified through dark magic. This \"natural\" egg is evidence that one of their matriarchs has become a viable broodmother. We must destroy her before her brood spreads. Go to the Ascendant's Rise where they claim these aberrations are kept and slay one of the juvenile drakes. We will use its skull to lure out its mother.",rewardGold=137400,rewardXP=4115,rewardItems={54973},starts={{npcID=40816}},ends={{npcID=40816}},mapCandidates={npc={198},zone={616}},questType="standard",sourceQuests={25644},questLines={{id=542,name="Mount Hyjal",orderIndex=113,flags=0}}},
[26393] = {id=26393,name="A Swift Message",level=1,requiredLevel=1,faction="alliance",requiredRaces={1,32},categories={},flags={"loremaster"},sharable=false,expansion=7,zoneID=12,mapID=37,storyline={26393},series={26394,26395,26396},description="Although we don't get much aid from Stormwind directly, I do have a contact in the city who helps supply us with armor. His name is Osric Strang. His shop, Limited Immunity, is in the Old Town of Stormwind. Our supply of armor dwindles, and I must contact Osric for more. Can you take him this note? The fastest way to Stormwind is through Bartlett the Brave , our gryphon master. He's just outside of the smithy; bring him my note, and then take a gryphon to Stormwind.",objectivesText="Bring Argus' Note to Bartlett the Brave the gryphon master. Progress: You look like you're in a hurry. Well, then you came to the right place!",rewardXP=50,rewardItems={58364},starts={{npcID=514}},ends={{npcID=42983}},mapCandidates={npc={37},zone={12}},questType="standard"},
[26415] = {id=26415,name="Questflag for Captain's Log",level=0,requiredLevel=0,faction="both",sharable=false,expansion=7,zoneID=5042,mapID=207,mapCandidates={npc={},zone={5042}},questType="standard"},
[26453] = {id=26453,name="A Helping Hand",level=7,requiredLevel=7,faction="alliance",sharable=false,expansion=7,zoneID=331,mapID=63,series={26454},description="Under the supervision of Architect Nemos and Vindicator Vedaar, my people are revitalizing an old night elf outpost in the eastern part of Ashenvale . The task of building won't be easy, , for the challenges and enemies they face are many. I know Architect Nemos and his compatriots at Forest Song would appreciate any help they can get, and he has asked me to send any interested his way. Speak to me again and I will arrange for fast transport for you to their location.",rewardXP=505,starts={{npcID=17106}},ends={{npcID=17291}},mapCandidates={npc={63},zone={331}},questType="standard",nextQuests={26454}},
[26630] = {id=26630,name="Looks Like a Tauren Pirate to Me",level=10,requiredLevel=10,faction="both",categories={},flags={"loremaster"},sharable=true,expansion=7,zoneID=5287,mapID=210,storyline={26630},description="Firallon wants MY head? Now that's interesting. But it's nothing we can't work around. This Yancey character probably doesn't know my face too well. Most non-tauren find us tauren indistinguishable from one another. In fact... most non-tauren find us indistinguishable from... a certain four-legged farm creature. Rikqiz the leatherworker keeps one of these creatures here in Booty Bay, and Narkk is my chief supplier for pirate hats. Get a replacement head and a hat, then return with both.",objectivesText="Obtain a Cow Head and an Oversized Pirate Hat , then bring them back to Fleet Master Seahorn . Progress: You should know that most tauren would find this shameful. I find it... amusing.",rewardItems={59146,59147,59148},starts={{npcID=2487}},ends={{npcID=2487}},mapCandidates={npc={210},zone={5287}},questType="standard"},
[26710] = {id=26710,name="Lost In The Deeps",level=30,requiredLevel=30,faction="both",sharable=false,expansion=7,zoneID=5042,mapID=207,description="Pebble has gotten himself lost again, somewhere deep in the Crumbling Depths. He's fortunate that his size makes him unworthy of the effort for those gyreworms, but it's only a matter of time before he stumbles too close to one and gets eaten. Whatever he's so intent on down there is certainly not worth it. He seems to like you. Please, go and find him and bring him out of those tunnels to safer playing grounds.",rewardGold=137400,rewardXP=4115,starts={{npcID=44945,mapID=207,x=0.5537,y=0.1414}},ends={{npcID=44945}},mapCandidates={npc={207},zone={5042}},questType="standard",sourceQuests={26709}},
[26755] = {id=26755,name="Keep Them off the Front",level=30,requiredLevel=30,faction="both",sharable=false,expansion=7,zoneID=5042,mapID=207,series={27126,26632,26762,26834},description="Oh good, you brought another catapult with you! Clay might be older than dirt, but he makes a mean war machine. Well, you didn't bring it all the way out here for your health, flesh bag. Get in one of those things and bombard the fungal terrors and reinforcements streaming out of Needlerock Slag. We have to keep them off the front!",rewardGold=137400,rewardXP=4115,starts={{npcID=43897}},ends={{npcID=43897}},mapCandidates={npc={207},zone={5042}},questType="standard",sourceQuests={26632},questLines={{id=543,name="Deepholm, War & Gunships",orderIndex=22,flags=0}}},
[26871] = {id=26871,name="A Rock Amongst Many",level=30,requiredLevel=30,faction="both",categories={},flags={"loremaster"},sharable=true,expansion=7,zoneID=5042,mapID=207,storyline={26312,26313,26314,26315,26326,26328,26375,26376,26377,26426,26436,26437,26438,26439,26440,26441,26507,26575,26576,26577,26578,26579,26580,26581,26582,26583,26584,26585,26656,26657,26658,26659,26750,26752,26827,26828,26829,26831,26832,26833,26869,26871,26875,26971},series={26376,26377,26426,26869},description="<The ground trembles slightly, and the low, familiar voice of Diamant speaks as if from the stone itself.> You've done as I've asked. Turn back and escape the cave in one piece. Don't forget the gemstone.",objectivesText="Return to Diamant at Lorthuna's Gate with the Painite Chunk . Progress: You're alive. This is good. Is the gemstone with you?",rewardXP=4115,rewardItems={60504,61427,61428,61429,65907},rewardChoices={61428,61427,61429},ends={{npcID=42467}},startObjects={{objectID=204959,mapID=207,x=0.663,y=0.207}},coords={mapID=207,source="quest_giver",x=0.565,y=0.425},mapCandidates={npc={207},zone={5042}},questType="standard",sourceQuests={26869},questLines={{id=544,name="Deepholm, The Stone Throne",orderIndex=11,flags=0}},db2PoiMapID=646,db2PoiUiMapID=207},
[26876] = {id=26876,name="The World Pillar Fragment",level=30,requiredLevel=30,faction="both",categories={},flags={"loremaster"},sharable=true,expansion=7,zoneID=5042,mapID=207,storyline={26244,26245,26246,26247,26248,26249,26250,26251,26254,26255,26256,26258,26259,26260,26261,26409,26410,26411,26413,26427,26484,26499,26500,26501,26502,26537,26564,26591,26625,26632,26755,26762,26766,26768,26770,26771,26791,26792,26834,26835,26836,26857,26861,26876,27007,27010,27061,27126,27135,27931,27932,27933,27934,27935,27936,27937,27938},series={26766,26768,26771,26857},description="It is time, <name>. We have spotted Abyssion making his way to the lair. The Twilight's Hammer might've thought the fragment would be safe if a dragon guarded it, but I've met enough dragons to know their one weakness. Pride. Abyssion's not going to run from a fight with us puny mortals. Place the banner of the Earthen Ring in the middle of his lair. Once we defeat him, bring the fragment to Maruut. We need to repair the World Pillar as soon as possible.",objectivesText="Place the Earthen Ring Banner in the center of Abyssion's Lair, slay him and obtain the Upper World Pillar Fragment . Progress: <name>! You've returned!",rewardGold=274800,rewardXP=5145,rewardItems={60574,60810,61472,61473,61474},rewardChoices={61474,61473,61472},starts={{npcID=44010}},ends={{npcID=43065}},mapCandidates={npc={207},zone={5042}},questType="standard",sourceQuests={26857,26861},questLines={{id=543,name="Deepholm, War & Gunships",orderIndex=56,flags=0}},db2PoiMapID=646,db2PoiUiMapID=207},
[27742] = {id=27742,name="A Little on the Side",level=30,requiredLevel=30,faction="both",categories={},flags={"loremaster"},sharable=true,expansion=7,zoneID=4922,mapID=241,storyline={26293,26294,26311,26324,26335,26337,26358,26361,26372,26374,26388,26538,26539,26540,26549,26608,26619,26621,26622,26784,26786,26788,26798,26830,26840,27177,27178,27299,27300,27301,27302,27303,27338,27341,27366,27376,27377,27378,27379,27380,27433,27468,27485,27486,27490,27491,27492,27493,27494,27495,27496,27497,27498,27499,27500,27501,27502,27503,27504,27505,27506,27507,27508,27509,27514,27515,27516,27537,27538,27545,27564,27576,27583,27584,27586,27588,27590,27606,27607,27608,27609,27610,27611,27621,27622,27636,27637,27638,27639,27640,27641,27642,27643,27644,27645,27646,27647,27648,27649,27650,27651,27652,27653,27654,27655,27657,27658,27659,27660,27661,27662,27688,27689,27690,27695,27696,27700,27701,27702,27703,27719,27720,27742,27743,27744,27745,27747,27750,27751,27752,27753,27754,27784,27786,27787,27788,27798,27803,27804,27805,27806,27807,27808,27809,27810,27811,27812,27813,27814,27815,27816,27817,27861,27862,27863,27864,27865,27866,27867,27868,27929,27945,27947,27951,27954,27955,27999,28041,28043,28090,28091,28092,28093,28094,28097,28101,28103,28104,28107,28108,28109,28123,28133,28171,28173,28175,28176,28191,28211,28212,28215,28233,28234,28238,28241,28242,28243,28244,28247,28248,28249,28280,28281,28282,28294,28346,28377,28378,28379,28407,28408,28409,28410,28411,28413,28583,28584,28586,28588,28589,28590,28591,28592,28593,28594,28595,28596,28597,28598,28599,28655,28712,28758,28832,28849,28885},series={27743,27744,27745},description="You know, it's our moral obligation to save all of this Elementium from the shale spiders. Those creepy things eat the stuff! What a waste! So, what do you say? 90/10 my way?",objectivesText="Collect 6 Elementium Shards . Progress: How much do you think you can carry?",rewardGold=195720,rewardXP=4115,rewardItems={62331,63712,63713,63714,166846},rewardChoices={63713,63712,63714},starts={{npcID=46513}},ends={{npcID=46513}},mapCandidates={npc={},zone={5892}},questGiverID=46513,questTurnInID=46513,questType="standard",sourceQuests={27720,28885},questLines={{id=546,name="Twilight Highlands",orderIndex=228,flags=0}},db2PoiUiMapID=241},
[27787] = {id=27787,name="Skullcrusher the Mountain",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=4922,mapID=241,series={27782,27784},description="It was a trap! Cho'gall lured you in with the Hammer of Twilight so that his gronn could finish you off. Survive and slay Skullcrusher the Mountain !",rewardGold=842700,rewardXP=6175,rewardChoices={63708,63707,63706,63705},starts={{npcID=46717}},ends={{npcID=45668}},mapCandidates={npc={241},zone={4922}},questType="standard",sourceQuests={27784},questLines={{id=546,name="Twilight Highlands",orderIndex=234,flags=0}}},
[28162] = {id=28162,name="Swamp Bait",level=35,requiredLevel=35,faction="alliance",categories={},flags={"daily","loremaster","repeatable"},sharable=true,expansion=7,zoneID=5095,mapID=244,storyline={28162},description="Supplies are never easy to find in a place like this, <class>. We have been scouting since we captured the island but things are not looking good. Fortunately, we just received a scouting report that a swamp full of crocs is just west of our base camp here. The hides off those crocs will come in handy for our leatherworkers. Bring back as many as you can.",objectivesText="You have been tasked with collecting 8 Crocolisk Hides from the Baradin Crocolisks on Tol Barad . The crocolisks can be found in the swamp, just west of Baradin Hold. Progress: You cleared out that swamp yet?",rewardGold=561800,rewardXP=4790,rewardItems={63103},rewardCurrencies={{id=391,amount=1}},starts={{npcID=48066}},ends={{npcID=48066},{npcID=52015}},mapCandidates={npc={244,245},zone={5095}},questType="standard"},
[28608] = {id=28608,name="The Shadow Grave",level=1,requiredLevel=1,faction="horde",requiredRaces={5},categories={},flags={"loremaster"},sharable=false,expansion=7,zoneID=6454,mapID=18,storyline={24959,24960,24961,24970,24971,24972,24973,25089,26799,26800,26801,26802,28608,28651,28652,28653,28672},series={24959,24960,24961,24970,24971,24973,25089,26799,26800,26801,26802,28651,28652,28653,28672},description="I'm pleased to see that you're up and walking around, <name>. You've held up nicely, especially after being dead for so long! Others weren't as lucky. If you wouldn't mind, I need you to fetch my embalming fluid and some twine to stitch up these bodies. You'll find both in the Shadow Grave, the building just behind me. Here, Darnell will join you. He knows the way.",objectivesText="Obtain the Thick Embalming Fluid and the Corpse-Stitching Twine from the Shadow Grave in Deathknell . Progress: You will find the items within the Shadow Grave. I believe I left them on my work table.",rewardGold=2000,rewardXP=200,rewardItems={64581,64582},starts={{npcID=1568}},ends={{npcID=1568}},mapCandidates={npc={18},zone={6454}},questType="standard",sourceQuests={24959},questLines={{id=5406,name="Deathknell",orderIndex=1,flags=0}},db2PoiUiMapID=465},
[28658] = {id=28658,name="Swamp Bait",level=35,requiredLevel=35,faction="horde",categories={},flags={"daily","loremaster","repeatable"},sharable=true,expansion=7,zoneID=5095,mapID=244,storyline={28658},description="Supplies are never easy to find in a place like this, <class>. We have been scouting since we captured the island but things are not looking good. Fortunately, we just received a scouting report that a swamp full of crocs is just west of our base camp here. The hides off those crocs will come in handy for our leatherworkers. Bring back as many as you can.",objectivesText="You have been tasked with collecting 8 Crocolisk Hides from the Baradin Crocolisks on Tol Barad . The crocolisks can be found in the swamp, just west of Baradin Hold. Progress: You cleared out that swamp yet?",rewardGold=561800,rewardXP=4790,rewardItems={63103},rewardCurrencies={{id=391,amount=1}},starts={{npcID=48069}},ends={{npcID=48069},{npcID=52016}},mapCandidates={npc={244,245},zone={5095}},questType="standard"},
[28661] = {id=28661,name="The Imprisoned Archmage",level=35,requiredLevel=35,faction="horde",categories={},flags={"daily","loremaster","repeatable"},sharable=true,expansion=7,zoneID=5095,mapID=244,storyline={28661},description="We have been trying to clear out the Cursed Depths cellblock since we landed on Tol Barad . It seems that everytime we get close, that archmage shows up and pushes us back. Now that we have claimed the island, it's time we take another shot. Head down there and bring me back his staff as proof that you have finished the job.",objectivesText="You must kill Archmage Galus and return with his Staff from the Cursed Depths, just east of Baradin Hold. Progress: Have you been able to take out the Archmage?",rewardGold=274800,rewardXP=4790,rewardItems={63033},rewardCurrencies={{id=391,amount=1}},starts={{npcID=48071}},ends={{npcID=48071},{npcID=52016}},mapCandidates={npc={244,245},zone={5095}},questType="standard"},
[28664] = {id=28664,name="Svarnos",level=35,requiredLevel=35,faction="horde",categories={},flags={"daily","loremaster","repeatable"},sharable=true,expansion=7,zoneID=5095,mapID=244,storyline={28664},description="Excellent work on the island capture, <class>. Now that we have claimed the island, we need to make these cellblocks useable for prisoners. D-Block has been especially hard to clear out. Unfortunately it has become overrun with demons of all sorts. We have been able to thin out the demons but a large core hound has broken its way out of its cell and is wreaking havoc down there. I need you to kill him and bring back his collar.",objectivesText="You must kill Svarnos in the D-Block and return with his Cursed Collar. Svarnos can be found in the D-Block, just northwest of Baradin Hold. Progress: Is the core hound dead?",rewardGold=274800,rewardXP=4790,rewardItems={63143},rewardCurrencies={{id=391,amount=1}},starts={{npcID=48070}},ends={{npcID=48070},{npcID=52016}},mapCandidates={npc={244,245},zone={5095}},questType="standard"},
[28665] = {id=28665,name="Cursed Shackles",level=35,requiredLevel=35,faction="horde",categories={},flags={"daily","loremaster","repeatable"},sharable=true,expansion=7,zoneID=5095,mapID=244,storyline={28665},description="Have you been down in the D-Block yet, <name>? Every time we clear that infested cellblock out, the demons seem to return rather quickly. We learned that they regenerate from the cursed shackles scattered around the area. That's where you come in to the picture <name>. I need you to retrieve as many of those shackles as you can and bring them back to me. We will destroy them immediately.",objectivesText="You have been asked to recover 8 Cursed Shackles from the D-Block, just northwest of Baradin Hold. Progress: Did you find many shackles? Reports mentioned that they were all over the place down there.",rewardGold=274800,rewardXP=4790,rewardItems={63149},rewardCurrencies={{id=391,amount=1}},starts={{npcID=48070}},ends={{npcID=48070},{npcID=52016}},mapCandidates={npc={244,245},zone={5095}},questType="standard"},
[28669] = {id=28669,name="The Warden",level=35,requiredLevel=35,faction="horde",categories={},flags={"daily","loremaster","repeatable"},sharable=true,expansion=7,zoneID=5095,mapID=244,storyline={28669},description="We have almost finished clearing out the revolting prisoners in the hole, but one last problem remains. The warden. Warden Silva is their master and they will do anything for him. If we take him out, we take them all out. Finish him off and bring me back his keys. We can use those keys to explore deeper into the cellblock and possibly gain access to the water supply here on the island.",objectivesText="You must kill Warden Silva in The Hole and return with his keys. The Hole is just southwest of Baradin Hold. Progress: Is the warden dead yet?",rewardGold=274800,rewardXP=4790,rewardItems={63309},rewardCurrencies={{id=391,amount=1}},starts={{npcID=48062}},ends={{npcID=48062},{npcID=52016}},mapCandidates={npc={244,245},zone={5095}},questType="standard"},
[28670] = {id=28670,name="Food From Below",level=35,requiredLevel=35,faction="horde",categories={},flags={"daily","loremaster","repeatable"},sharable=true,expansion=7,zoneID=5095,mapID=244,storyline={28670},description="Supplies are running low here in camp, <name>. We have recently learned that the cellblock just southwest of here has a number of rations remaining from years of use. We need you to gather as many of those as you can and bring them back to camp. One more thing, the entire cellblock is overrun with prisoners so be careful.",objectivesText="You have been asked to recover 12 Cellblock Rations from The Hole, just southwest of Baradin Hold. Progress: Were you able to recover the rations? Reports mentioned that they could be found all over the place down there.",rewardGold=274800,rewardXP=4790,rewardItems={63315},rewardCurrencies={{id=391,amount=1}},starts={{npcID=48062}},ends={{npcID=48062},{npcID=52016}},mapCandidates={npc={244,245},zone={5095}},questType="standard"},
[28712] = {id=28712,name="Enter the Dragon Queen",level=30,requiredLevel=30,faction="both",sharable=false,expansion=7,zoneID=4922,mapID=241,description="Hello, . I wish we could meet in more favorable circumstances. The world hangs by a thread, and all that the Titans have wrought may be in jeopardy. It saddens me greatly, but my judgment is final. Deathwing - the horrific creature that was once the Earth Warder and once my friend - must be destroyed. I have prepared a site atop the Highlands, to the west of the Vermillion Redoubt, where I can bring about his end. Seek out the Circle of Life and speak with Lirastrasza within. I will join you there.",rewardGold=138100,rewardXP=2060,starts={{npcID=47603}},ends={{npcID=49417}},mapCandidates={npc={241},zone={4922}},questType="standard",sourceQuests={28093,28109},questLines={{id=546,name="Twilight Highlands",orderIndex=174,flags=0}}},
[28732] = {id=28732,name="This Can Only Mean One Thing...",level=30,requiredLevel=30,faction="both",sharable=false,expansion=7,zoneID=25,series={28735},description="Raz and I were enlisted by the Guardians of Hyjal to investigate the re-emergence of Ragnaros into our world. Let me go ahead and confirm that he is back and he is angry! We also have evidence that these Twilight's Hammer cultists are moving elementals from here to Blackrock Caverns , over in the Eastern Kingdoms. Raz and I were about to head over there to investigate. We've got room for another in the mole machine if you're interested. Just meet us on the inside and we'll begin our journey.",rewardXP=515,starts={{npcID=49444}},ends={{npcID=49444}},mapCandidates={npc={198},zone={25}},questTurnInID=49444,questType="standard",nextQuests={28735}},
[28755] = {id=28755,name="Annals of the Silver Hand",level=15,requiredLevel=15,faction="both",categories={},flags={"loremaster"},sharable=true,expansion=7,zoneID=2017,mapID=23,storyline={28755},description="Do you know who the Knights of the Silver Hand were? They were the original paladins of the Light, and from their ranks came knights who would later join the Argent Dawn or the Scarlet Crusade. Though many have gone astray, they still possess valuable relics of the Silver Hand. Deep in Stratholme , under the watchful eye of Instructor Galford, volumes of the Annals of the Silver Hand survive. Any volumes you could recover would be a fitting addition to the rededicated Light's Hope Chapel.",objectivesText="Recover a lost volume of the Annals of the Silver Hand from Stratholme . Progress: Have you recovered any of the lost histories of the Silver Hand?",rewardItems={13379,43381,61379,65615},starts={{npcID=49856}},ends={{npcID=49856}},mapCandidates={npc={23},zone={139}},questType="dungeon",sourceQuests={27464}},
[28869] = {id=28869,name="Pebble",level=30,requiredLevel=30,faction="both",sharable=false,expansion=7,zoneID=5042,mapID=207,series={26440,26441},description="If you hadn't noticed, there's a very small elemental that has taken a liking to you. If you stay on the ground for even a few moments, I'm sure you'll spot him. You seem to be quite adept at making friends down here. A good talent to have.",rewardGold=13740,rewardXP=515,starts={{npcID=42469}},ends={{npcID=42469}},mapCandidates={npc={},zone={5042}},questGiverID=42469,questTurnInID=42469,questType="standard",sourceQuests={26437,26438,26439},nextQuests={26440}},
[28876] = {id=28876,name="To the Mor'shan Rampart",level=7,requiredLevel=7,faction="horde",sharable=false,expansion=7,zoneID=17,mapID=10,series={28493,13612},description="Kadrak at the Mor'shan Rampart to the north is calling for aid. The rampart rests on the border between the Northern Barrens and Ashenvale . It is the front line in the fight against the Alliance. We're driving the night elves out of the forest. We'll claim its resources for the Horde! To get there, take the Gold Road north out of the Crossroads. Destiny calls!",rewardXP=125,starts={{npcID=3429}},ends={{npcID=8582}},mapCandidates={npc={10},zone={17}},questType="standard"},
[29123] = {id=29123,name="Rage Against the Flames",level=32,requiredLevel=32,faction="both",sharable=false,expansion=7,zoneID=616,mapID=198,description="Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight. Kill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.",rewardGold=137400,rewardXP=4385,rewardCurrencies={{id=416,amount=1}},starts={{npcID=52669}},ends={{npcID=52669}},mapCandidates={npc={198},zone={616}},questType="standard",sourceQuests={29198}},
[29127] = {id=29127,name="Rage Against the Flames",level=32,requiredLevel=32,faction="both",sharable=false,expansion=7,zoneID=616,mapID=198,description="Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight. Kill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.",rewardGold=137400,rewardXP=4385,rewardCurrencies={{id=416,amount=1}},starts={{npcID=52669}},ends={{npcID=52669}},mapCandidates={npc={198},zone={616}},questType="standard",sourceQuests={29198}},
[29149] = {id=29149,name="Rage Against the Flames",level=32,requiredLevel=32,faction="both",sharable=false,expansion=7,zoneID=616,mapID=198,description="Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight. Kill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.",rewardGold=289300,rewardXP=4385,rewardCurrencies={{id=416,amount=1}},starts={{npcID=52669}},ends={{npcID=52669}},mapCandidates={npc={198},zone={616}},questType="standard",sourceQuests={29198}},
[29163] = {id=29163,name="Rage Against the Flames",level=32,requiredLevel=32,faction="both",sharable=false,expansion=7,zoneID=616,mapID=198,description="Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight. Kill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.",rewardGold=137400,rewardXP=4385,rewardCurrencies={{id=416,amount=1}},starts={{npcID=52669}},ends={{npcID=52669}},mapCandidates={npc={198},zone={616}},questType="standard",sourceQuests={29198}},
[29255] = {id=29255,name="Embergris",level=32,requiredLevel=32,faction="both",categories={},flags={"repeatable","loremaster","daily"},sharable=false,expansion=7,zoneID=5733,storyline={29255},description="The Crimson Lasher has developed some cracking blisters on its vines. Without treatment, this condition could be life threatening. Luckily, the Charred Soldiers and Charred Vanquishers in the area produce a waxy substance known as Embergris , which should soothe the Lasher's pain. Bring me some of this substance, and kill those nasty fire elementals while you're at it.",objectivesText="Retrieve 5 Embergris from Charred Soldiers and Charred Vanquishers. Progress: The Lasher is growing quite quickly.",rewardGold=137400,rewardXP=4385,rewardItems={2608,69722},rewardCurrencies={{id=416,amount=1}},starts={{npcID=52489}},ends={{npcID=52489}},mapCandidates={npc={},zone={5733}},questGiverID=52489,questTurnInID=52489,questType="standard",sourceQuests={29254}},
[29257] = {id=29257,name="Steal Magmolias",level=32,requiredLevel=32,faction="both",categories={},flags={"repeatable","loremaster","daily"},sharable=false,expansion=7,zoneID=5733,storyline={29257},description="We've discovered a new species of flower growing in the Magma Springs to the north. Amazingly, they sustain themselves in pure molten lava! Please go and retrieve some specimens for me. I'm sure that further study of these plants will shed some light on your little friend here. Speaking of which, he seems quite eager to go with you. Let's hope he behaves himself.",objectivesText="Collect 8 Magmolias from the Magma Springs to the north. Progress: Fascinating! The more time I spend in the Firelands, the more I see there is an ecosystem at work here.",rewardGold=137400,rewardXP=4385,rewardItems={69725},rewardCurrencies={{id=416,amount=1}},starts={{npcID=52489}},ends={{npcID=52489}},mapCandidates={npc={},zone={5733}},questGiverID=52489,questTurnInID=52489,questType="standard",sourceQuests={29254}},
[29265] = {id=29265,name="Fire Flowers",level=32,requiredLevel=32,faction="both",categories={},flags={"repeatable","loremaster","daily"},sharable=true,expansion=7,zoneID=5733,storyline={29265},description="My fellow druid, Choluna , has asked us to collect any specimens of plant life that we might find here in the Firelands... ...I don't know whose idea it was to bring scholars to a warfront. Nevertheless, you will already be in the cave - killing things - so be on the lookout for anything growing out of the ground.",objectivesText="Obtain 5 Luciferns . Progress: They could be growing anywhere. Keep your eyes open.",rewardGold=137400,rewardXP=4385,rewardItems={69765},rewardCurrencies={{id=416,amount=2}},starts={{npcID=52444}},ends={{npcID=52444}},mapCandidates={npc={},zone={5733}},questGiverID=52444,questTurnInID=52444,questType="standard",sourceQuests={29206}},
[29270] = {id=29270,name="Time Grows Short",level=35,requiredLevel=35,faction="both",sharable=false,expansion=7,zoneID=3537,mapID=114,series={29240,29269,29285},description="Tarecgosa is bound to you, , but only temporarily. An aspect's power is required to permanently seal her essence. Malygos's successor will not be chosen until Azeroth's moons next eclipse, and the bond you share will not last until then. Fortunately, there is a way to buy us the time we need. Powerful elements exist that can extend the ritual's effects. Some of these can be found in the Plane of Fire, with which you've become familiar. Obtain them, , and sustain Tarecgosa until the eclipse.",rewardGold=137400,rewardXP=4790,rewardItems={69815},starts={{npcID=53210}},ends={{npcID=53215}},mapCandidates={npc={114},zone={3537}},questType="raid",sourceQuests={29269}},
[29281] = {id=29281,name="Additional Armaments",level=32,requiredLevel=32,faction="both",sharable=false,expansion=7,zoneID=616,mapID=198,description="These druids be lackin' the tools ta properly handle the job out 'ere. I got meself a buddy back at day ol' stag shrine through the portal though. If we were ta be gettin' reunited, we'd sure have some real toys ta use against ol' Ragboy and 'is cronies. Take some of dem mark things an' go find Matoclaw . Ask her fer Ricket. We need'r here so we can be causin' some real trouble.",rewardGold=274800,rewardXP=5480,starts={{npcID=53214}},ends={{npcID=52669}},mapCandidates={npc={198},zone={616}},questType="standard",sourceQuests={29181,29214}},
[46700] = {id=46700,name="Armor of the Ancients",level=45,requiredLevel=45,faction="both",requiredClasses={1,2,6},requiredProfessions={"blacksmithing"},categories={},flags={},sharable=false,expansion=7,zoneID=7543,mapID=646,storyline={46700},series={46697,46698,46699,46701},description="It is not just the hammers and my careful research that we need, <name>. We also need a lot of the very highest quality of ancient metal to make the final hammer. Enemies across Broken Shore that are able to wear armor often collect bits of Ancient Demonsteel here and there. Collect enough of it in your battles for our purposes.",objectivesText="Obtain 100 Ancient Demonsteel from humanoids in Broken Shore. Progress: Do you have the Ancient Demonsteel that we need?",rewardGold=202200,rewardXP=6140,rewardItems={146708,146709},starts={{npcID=120221}},ends={{npcID=120221}},mapCandidates={npc={646},zone={7543}},questType="standard",sourceQuests={46696}},
[46701] = {id=46701,name="Hammer of Forgotten Heroes",level=45,requiredLevel=45,faction="both",requiredClasses={1,2,6},requiredProfessions={"blacksmithing"},categories={},flags={},sharable=false,expansion=7,zoneID=7543,mapID=646,storyline={46701},series={46697,46698,46699,46700},description="<name>, this is exciting, I have to admit. I've put everything you've gathered into this chest of supplies and the only place with the power and magic to handle the creation of the final hammer is the Firmament Stone. I believe that blacksmiths of your rarified skills will know it? I realize that there are dwarf stereotypes out there about smithing but I really don't care for all of the banging and heat. Suppose that is why I followed the scholarly path. Good luck to you!",objectivesText="Go to the Firmament Stone in Highmountain and forge the Hammer of Forgotten Heroes . Progress: Be sure to take the chest of supplies I've given you to the Firmament Stone and forge the final hammer. Bring it back to me for inspection when you have done so.",rewardGold=202200,rewardXP=6140,rewardItems={146667,146714,147207,147443},starts={{npcID=120221}},ends={{npcID=120221}},mapCandidates={npc={646},zone={7543}},questType="standard",sourceQuests={46697,46698,46699,46700}},
[46705] = {id=46705,name="Retaliation",level=45,requiredLevel=45,faction="both",requiredClasses={8},categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=7637,mapID=680,storyline={44766,44768,44770,45207,45251,45437,45586,45614,46000,46043,46290,46335,46338,46339,46345,46351,46705},series={44766,45207,45437,46335,46338},description="Of course I will help you! Although to be honest, I am not certain where a new arcane shield generator can be found these days. So many of our craftspeople have been executed... I will think on it. Would you mind helping me as well? I have been observing a nearby group of Felborne for some time. Their activities have become increasingly brazen of late. I think it's time to teach them how it feels to be violently suppressed.",objectivesText="Kill 7 Felborne Insurgents.",rewardGold=202200,rewardXP=6140,starts={{npcID=121357}},ends={{npcID=121358}},mapCandidates={npc={680},zone={7637}},questType="standard",sourceQuests={45207},questLines={{id=5871,name="Rise of the Tirisgarde IV",orderIndex=5,flags=0}},campaigns={{id=297,title="Mage Order Hall",questLineID=5871,questLineOrder=4,stallText="Complete the quest Armies of Legionfall in Dalaran to continue the campaign."}},campaignLockText="Complete the quest Armies of Legionfall in Dalaran to continue the campaign.",db2PoiMapID=1220,db2PoiUiMapID=681},
[46707] = {id=46707,name="Minion! Kill That One Too!",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=7543,mapID=646,storyline={46707},objectivesText="Investigate Curious Fel Energy",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={7543}},questType="world",db2Objectives={{text="Investigate Curious Fel Energy",amount=1,type=0,objectID=120127,orderIndex=0}},worldTaskTitle="Minion! Kill That One Too!",db2PoiMapID=1220,db2PoiUiMapID=646,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[46719] = {id=46719,name="Amal'thazad's Message",level=45,requiredLevel=45,faction="both",requiredClasses={6},categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=7543,mapID=646,storyline={46719,46720,46812,46813},description="Deathlord, Amal'thazad has requested your presence at Acherus. He has been in contact with the Lich King, and making improvements on the citadel. For his benefit, or yours, I know not.",objectivesText="Speak with Amal'thazad in Acherus.",rewardGold=20220,rewardXP=770,starts={{npcID=117573}},ends={{npcID=117573}},mapCandidates={npc={646},zone={7543}},questTurnInID=117573,questType="standard",sourceQuests={46050},questLines={{id=351,name="Class Mount: Death Knight",orderIndex=0,flags=0}},campaigns={{id=302,title="Death Knight Order Hall",questLineID=351,questLineOrder=5,stallText="Complete the quest Armies of Legionfall in Dalaran to continue the campaign."}},campaignLockText="Complete the quest Armies of Legionfall in Dalaran to continue the campaign.",db2PoiMapID=1220,db2PoiUiMapID=648},
[46720] = {id=46720,name="Frozen Memories",level=45,requiredLevel=45,faction="both",requiredClasses={6},categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=7543,mapID=648,storyline={46719,46720,46812,46813},description="Close your eyes, Deathlord. Can't you feel his presence already? <The Lich King's icy presence is inside your mind in an instant.> Stand in the rune circle atop Acherus, Deathlord. I will show you what I have seen. <The presence fades.>",objectivesText="Take the portal to the top of Acherus, listen to the Lich King's plan, then witness his vision in Icecrown.",rewardGold=20220,rewardXP=770,rewardItems={142231},starts={{npcID=93555}},ends={{npcID=93555}},mapCandidates={npc={},zone={7543}},questGiverID=93555,questTurnInID=93555,questType="standard",sourceQuests={46719},questLines={{id=351,name="Class Mount: Death Knight",orderIndex=1,flags=0}},campaigns={{id=302,title="Death Knight Order Hall",questLineID=351,questLineOrder=5,stallText="Complete the quest Armies of Legionfall in Dalaran to continue the campaign."}},campaignLockText="Complete the quest Armies of Legionfall in Dalaran to continue the campaign.",db2PoiMapID=1220,db2PoiUiMapID=648},
[46722] = {id=46722,name="Nothing Up My Sleeve",level=45,requiredLevel=45,faction="both",requiredClasses={8},categories={},flags={},sharable=true,expansion=7,zoneID=7879,mapID=734,storyline={45615,45630,46722,46723,46724},description="Now, you may think that a sack of gold would be a good reward for your troubles, but I've got something better in mind for you. I'm gonna teach you my best trick! I know, I know, I'm a very generous goblin. Let me show you how it's done!",objectivesText="Use Akazamzarak's Hat to perform a magic trick. Progress: You gonna do the trick or not?",rewardGold=28300,rewardXP=770,starts={{npcID=103092}},ends={{npcID=103092}},mapCandidates={npc={},zone={7879}},questGiverID=103092,questTurnInID=103092,questType="standard",sourceQuests={45630},questLines={{id=314,name="Champion: Akazamzarak",orderIndex=2,flags=0}},db2PoiMapID=1513,db2PoiUiMapID=734},
[46723] = {id=46723,name="Down the Rabbit Hole",level=45,requiredLevel=45,faction="both",requiredClasses={8},categories={},flags={},sharable=true,expansion=7,zoneID=7879,mapID=734,storyline={45615,45630,46722,46723,46724},description="Alright, bub. I'm gonna need you to go in there and find out what's going wrong. I'd go in myself, but... well, it's complicated. Anyway, we got no time to lose! Just jump in the hat and find out what's goin on. I'll be ready to pull you out once you've got everything handled.",objectivesText="Enter Akazamzarak's Hat and find out what's happening to his rabbits. Progress: Don't just stand there, get in the hat and help the poor bunnies!",rewardGold=141800,rewardXP=3070,rewardItems={147838},starts={{npcID=103092}},ends={{npcID=103092}},mapCandidates={npc={},zone={7879}},questGiverID=103092,questTurnInID=103092,questType="standard",sourceQuests={46722},questLines={{id=314,name="Champion: Akazamzarak",orderIndex=3,flags=0}},db2PoiMapID=1513,db2PoiUiMapID=734},
[46724] = {id=46724,name="Champion: The Great Akazamzarak",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=7502,mapID=735,storyline={45615,45630,46722,46723,46724},description="You know, you're a useful <fella/dame> to have around, <name>. Tell ya what, I think I'll accompany you on your adventures. Seems to be good gold in it, and I think it'll be a good way to scout out some new business opportunities around the Broken Isles. What do you say?",starts={{npcID=103092}},ends={{npcID=103092}},mapCandidates={npc={},zone={7502}},questGiverID=103092,questTurnInID=103092,questType="standard",sourceQuests={46723},questLines={{id=314,name="Champion: Akazamzarak",orderIndex=4,flags=0}},db2PoiMapID=1513,db2PoiUiMapID=735},
[46725] = {id=46725,name="Power Outage",level=45,requiredLevel=45,faction="both",requiredClasses={12},requiredRaces={4,10},categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=7543,mapID=646,storyline={45301,45329,45330,45339,45385,45391,45764,45798,46159,46266,46725},description="Kor'vass asked for a bunch of other stuff, but it won't hurt her to learn a bit of patience. Don't you agree? She did mentioned that the ship'ss weaponss array is severely damaged and dangerously low on power. Knowing her, I'm sure that'ss an exaggeration. I suppose you may as well take this power core I confiscated. You can replenish it from those disgusting Legion geyserss and energy globess floating around the Tomb.",objectivesText="Refill the Fel Hammer's Power Core with fel energy.",rewardGold=202200,rewardXP=6140,rewardItems={95416,146797},starts={{npcID=117709}},ends={{npcID=117709}},mapCandidates={npc={646},zone={7543}},questType="standard",sourceQuests={45385},questLines={{id=5891,name="Destiny of the Illidari IV",orderIndex=7,flags=0}},campaigns={{id=301,title="Demon Hunter Order Hall",questLineID=5891,questLineOrder=4,stallText="Complete the quest Armies of Legionfall in Dalaran to continue the campaign."}},campaignLockText="Complete the quest Armies of Legionfall in Dalaran to continue the campaign.",db2PoiMapID=1220,db2PoiUiMapID=646},
[46727] = {id=46727,name="Battle for Azeroth: Tides of War",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=1519,mapID=84,storyline={46727,46728,46729,47098,47099,47186,47189,51341},series={46728,46729,47098,47099,51341,57766,58983,59641,60362},description="Champion! An urgent War Council is underway. Your presence is requested in Stormwind Keep.",objectivesText="Attend the War Council in Stormwind Keep. Progress: Thank you for coming.",rewardGold=25740,rewardXP=175,rewardItems={158075,160326,178941,178942},starts={{npcID=49748},{npcID=142930}},ends={{npcID=120756}},mapCandidates={npc={84},zone={1519}},questType="standard",questLines={{id=589,name="A Nation Divided",orderIndex=0,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=0,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=589,questLineOrder=2,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2DetailThemeID=6,db2PoiUiMapID=84},
[46728] = {id=46728,name="The Nation of Kul Tiras",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=1519,mapID=84,storyline={46727,46728,46729,47098,47099,47186,47189,51341},series={46727,46729,47098,47099,51341,57766,58983,59641,60362},description="Kul Tiras is the greatest naval power in Azeroth, and a former ally. But we've had little contact with them since Jaina's father, Lord Admiral Daelin Proudmoore, was defeated at Theramore. Many have criticized Jaina's decision that day, saying she believed so deeply in the promise of peace between the Alliance and Horde that she betrayed her own father. Perhaps she feels the time has come to atone for this. Loath as I am to put Jaina in harm's way... Kul Tiras must join the Alliance. Good luck.",objectivesText="Speak with Lady Jaina Proudmoore in Stormwind Harbor.",rewardGold=68700,rewardXP=710,rewardItems={158075,160326},starts={{npcID=120756},{npcID=165395}},ends={{npcID=120922}},mapCandidates={npc={84,1161},zone={1519}},questType="standard",sourceQuests={46727},questLines={{id=589,name="A Nation Divided",orderIndex=1,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=1,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=589,questLineOrder=2,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiUiMapID=84},
[46729] = {id=46729,name="The Old Knight",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=1161,storyline={46727,46728,46729,47098,47099,47186,47189,51341},series={46727,46728,47098,47099,51341,57766,58983,59641,60362},description="These days Cyrus is the Harbormaster, but he used to be one of Daelin Proudmoore's most trusted knights! I lost my mother when the Scourge hit Lordaeron. My father sent me here to be raised away from the war. I don't know much about him... just that he was a Stormwind knight who gave his life fighting the Lich King. Daelin hand-picked Cyrus to raise me and forced him to take a desk job. It's the only reason he wasn't at Theramore. He's probably checking in that other Alliance ship. Let's go!",objectivesText="Meet with Cyrus Crestfall . Progress: Sorry, I should have mentioned he can be a bit... long-winded at times.",rewardGold=128700,rewardXP=710,rewardItems={158075,160326},starts={{npcID=124630}},ends={{npcID=121235}},mapCandidates={npc={1161},zone={8568}},questGiverID=124630,questType="standard",sourceQuests={47099},questLines={{id=589,name="A Nation Divided",orderIndex=5,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=5,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=589,questLineOrder=2,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[46730] = {id=46730,name="Armies of Legionfall",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={"loremaster"},sharable=true,expansion=7,zoneID=7502,mapID=627,storyline={46244,46245,46246,46247,46248,46249,46250,46251,46252,46286,46730,46734,46769,46832,46845,47137,47139},series={46734},description="Thanks to your leadership, the <class> order has grown even mightier than I had dared hope. Alongside champions of the other orders, we now have a fighting force capable of driving the Burning Legion from our world. It's time to end this invasion! Using the Pillars of Creation, we will dissipate the Felstorm and seal the Tomb of Sargeras.",objectivesText="Escort Archmage Khadgar at Krasus' Landing in Dalaran.",rewardGold=101100,rewardXP=3070,rewardItems={146796},starts={{npcID=120215}},ends={{npcID=120215}},mapCandidates={npc={},zone={7502}},questGiverID=120215,questTurnInID=120215,questType="standard",sourceQuests={45727},questLines={{id=309,name="Legionfall Campaign",orderIndex=0,flags=0}},campaigns={{id=290,title="Legionfall Campaign",questLineID=309,questLineOrder=0,stallText="Complete the quest Uniting the Isles in Dalaran."}},campaignLockText="Complete the quest Uniting the Isles in Dalaran.",db2PoiMapID=1220,db2PoiUiMapID=627},
[46732] = {id=46732,name="The Prophet's Gambit",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={46297,46732,46816,46839,46840,46841,46842,46843,46938,47589,47627,47641,48483,48500},description="I can feel their presence just ahead. It is as faint as the lightest breeze that once rolled across these hills, but it is not of the Legion, of that I am certain. We must see if these broken are potential allies. It is a great risk, but our numbers are too few to ignore the chance.",objectivesText="Follow Prophet Velen .",rewardGold=50550,rewardXP=770,starts={{npcID=121345}},ends={{npcID=121345}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={47641},questLines={{id=345,name="Assault on Argus",orderIndex=6,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=345,questLineOrder=1,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[46734] = {id=46734,name="Assault on Broken Shore",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=7502,mapID=646,storyline={46244,46245,46246,46247,46248,46249,46250,46251,46252,46286,46730,46734,46769,46832,46845,47137,47139},series={46730},description="It has been a long and costly war, <name>. It is time we put an end to it. We will drive the Burning Legion from their seat of power and close their gateway into Azeroth. Our first step is to gain a foothold on the Broken Shore. Divided, the Alliance and Horde faced defeat. But united as the Armies of Legionfall, we will claim victory!",objectivesText="Complete the Assault on Broken Shore scenario.",rewardGold=202200,rewardXP=6140,rewardCurrencies={{id=1342,amount=25}},starts={{npcID=120215}},ends={{npcID=116302}},mapCandidates={npc={646},zone={7502}},questGiverID=120215,questType="standard",sourceQuests={46730},questLines={{id=309,name="Legionfall Campaign",orderIndex=1,flags=0}},campaigns={{id=290,title="Legionfall Campaign",questLineID=309,questLineOrder=0,stallText="Complete the quest Uniting the Isles in Dalaran."}},campaignLockText="Complete the quest Uniting the Isles in Dalaran.",db2PoiMapID=1220,db2PoiUiMapID=646},
