[46743] = {id=46743,name="Supplies From Highmountain",level=45,requiredLevel=45,faction="both",categories={"emissary","paragon"},flags={},sharable=false,expansion=7,zoneID=7503,storyline={46743},description="Champion, your help to our people has far exceeded any of our expectations, and has provided us some much needed breathing space. Please, take these supplies to aid you in the war against the Legion. With your continued aid, we should be able to gather more and prepare them for you.",objectivesText="Speak with Ransa Greyfeather in Highmountain for your reward.",rewardItems={152104},starts={{npcID=106902}},ends={{npcID=106902}},mapCandidates={npc={},zone={7731}},questGiverID=106902,questTurnInID=106902,questType="standard",worldSystems={paragonReputation={{factionID=2085,threshold=10000}}}},
[46745] = {id=46745,name="Supplies From the Court",level=45,requiredLevel=45,faction="both",categories={"emissary","paragon"},flags={},sharable=false,expansion=7,zoneID=7334,mapID=630,storyline={46745},description="Prince Farondis has asked me to thank you for your continued efforts to aid our lands. Please take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.",objectivesText="Speak with Veredis Fallon in Azsuna for your reward.",rewardItems={152102,180648},starts={{npcID=107376}},ends={{npcID=107376}},mapCandidates={npc={630},zone={7334}},questGiverID=107376,questType="standard",worldSystems={paragonReputation={{factionID=2087,threshold=10000}}}},
[46746] = {id=46746,name="Supplies From the Valarjar",level=45,requiredLevel=45,faction="both",categories={"emissary","paragon"},flags={},sharable=false,expansion=7,zoneID=7541,mapID=634,storyline={46746},description="Greetings, little hero. The mighty Odyn has proclaimed that you should receive these gifts of war. At every turn you continue to prove your valor and your efforts to aid the Valarjar have not gone unnoticed. For the Valarjar! For Odyn! For <name>!",objectivesText="Speak with Valdemar Stormseeker in Stormheim for your reward.",rewardItems={152106},starts={{npcID=106904}},ends={{npcID=106904}},mapCandidates={npc={634},zone={7541}},questGiverID=106904,questType="standard",worldSystems={paragonReputation={{factionID=2086,threshold=10000}}}},
[46747] = {id=46747,name="Supplies From the Dreamweavers",level=45,requiredLevel=45,faction="both",categories={"emissary","paragon"},flags={},sharable=false,expansion=7,zoneID=7558,mapID=641,storyline={46747},description="Hero! Your dedication to defending Val'sharah",objectivesText="Speak with Sylvia Hartshorn in Val'sharah for your reward.",rewardItems={152103},starts={{npcID=106901}},ends={{npcID=106901}},mapCandidates={npc={641},zone={7558}},questGiverID=106901,questType="standard",worldSystems={paragonReputation={{factionID=2088,threshold=10000}}}},
[46748] = {id=46748,name="Supplies From the Nightfallen",level=45,requiredLevel=45,faction="both",categories={"emissary","paragon"},flags={},sharable=false,expansion=7,zoneID=7637,mapID=680,storyline={46748},description="Outlander, I have some supplies for you. These goods are yours, earned by your continued efforts to our forces here in Suramar . I shall set aside similar treasures should you choose to aid our people more. You have my deepest thanks.",objectivesText="Speak with First Arcanist Thalyssra in Suramar for your reward.",rewardItems={152105},starts={{npcID=97140}},ends={{npcID=97140},{npcID=115736}},mapCandidates={npc={680},zone={7637}},questGiverID=97140,questType="standard",worldSystems={paragonReputation={{factionID=2089,threshold=10000}}}},
[46749] = {id=46749,name="Supplies From the Wardens",level=45,requiredLevel=45,faction="both",categories={"emissary","paragon"},flags={"loremaster"},sharable=false,expansion=7,zoneID=7334,mapID=630,storyline={46749},description="Your dedication to our efforts has yielded results. We have supplies for you. Continue your dedication and there will be more.",objectivesText="Speak with Marin Bladewing in Azsuna for your reward.",rewardItems={152107},starts={{npcID=107379}},ends={{npcID=107379}},mapCandidates={npc={630},zone={7334}},questGiverID=107379,questType="standard",worldSystems={paragonReputation={{factionID=2090,threshold=10000}}}},
