[46765] = {id=46765,name="The Broken Shore: Investigating the Legion",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=7543,mapID=646,storyline={44782,44821,46765,47000},series={44781,44782,44821,45030,45033,45037,45043,45045,45050,45052,45053,45054,45059,45060,45061,47000},description="While we focus efforts on the Broken Shore, we must be careful to guard against other threats. We have been getting disturbing reports on the Legion starting or supporting indirect threats to Azeroth. While you are on the Broken Shore, please keep an eye out for strange objects or intelligence that could give us a clue as to what and where these threats are. I know it is not a lot to go on, we will do our best from here as well.",objectivesText="Discover a hidden Legion threat while on the Broken Shore. Progress: Found something?",rewardGold=202200,rewardXP=6140,rewardItems={142396,147430,147860},starts={{npcID=116302}},ends={{npcID=116302}},mapCandidates={npc={646},zone={7543}},questType="standard",sourceQuests={46734},questLines={{id=278,name="The Council's Challenge",orderIndex=0,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=646},
[46766] = {id=46766,name="Ulgthax",level=10,requiredLevel=10,faction="none",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=7558,mapID=641,storyline={46766},rewardGold=929400,rewardXP=2125,mapCandidates={npc={},zone={7558}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=120310}},worldTaskTitle="Ulgthax",db2PoiMapID=1220,db2PoiUiMapID=641,db2QuestInfoID=142,db2QuestInfoName="Legion Invasion Elite World Quest"},
[46769] = {id=46769,name="Relieved of Their Valuables",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=7543,mapID=646,storyline={46244,46245,46246,46247,46248,46249,46250,46251,46252,46286,46730,46734,46769,46832,46845,47137,47139},description="Not all demons on this shore stomp around in the open. Some slink about in the shadows, finding more subtle ways to advance the Legion's cause. I have been observing the behavior of smaller demons, these wyrmtongues. They seem to spend considerable time acquiring objects of power. We cannot allow them to use these items against us. The wyrmtongues stash their goods in chests spread around the Broken Shore. I suggest you relieve them of their ill-gotten gain.",objectivesText="Find 3 Hidden Wyrmtongue Caches on the Broken Shore. Progress: Have you found the wyrmtongue caches?",rewardGold=404400,rewardXP=7675,rewardItems={45072,147811},starts={{npcID=116302}},ends={{npcID=116302}},mapCandidates={npc={646},zone={7543}},questType="standard",sourceQuests={46252},questLines={{id=309,name="Legionfall Campaign",orderIndex=13,flags=0}},campaigns={{id=290,title="Legionfall Campaign",questLineID=309,questLineOrder=0,stallText="Complete the quest Uniting the Isles in Dalaran."}},campaignLockText="Complete the quest Uniting the Isles in Dalaran.",db2PoiMapID=1220,db2PoiUiMapID=646},
[46772] = {id=46772,name="The Mage Tower",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=7543,mapID=646,storyline={46772,46773,46774},description="Well done <name>. In testament to the efforts of all forces fighting here, we have come together to complete the construction of the Mage Tower. All that remains is for you to inspect our work, and complete the construction.",objectivesText="Complete the construction of the Mage Tower. Progress: Inspect the <class> Tower, and complete its construction.",rewardItems={152654},starts={{npcID=120183}},ends={{npcID=120183}},mapCandidates={npc={646},zone={7543}},questType="standard",sourceQuests={46245},questLines={{id=344,name="Deliverance Point",orderIndex=1,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=646},
