[46804] = {id=46804,name="Fashion History and a Philosophy of Style",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=7796,mapID=646,storyline={46804},description="Greetings, <name>. I am a fashion historian and I have astonishing advancements in tailoring, leatherworking, and blacksmithing that I must share with you. Why? A true legend is only as good as their ability to form an epic silhouette on the battlefield and--let's be honest--this is not where you shine. Speak to me again if you wish to learn.",objectivesText="Learn from Eliezer Hammerbeard how to create \"flair and drama\" in your wardrobe. Progress: Let me know when you are ready to begin your education. You sorely need it!",rewardXP=770,rewardItems={146659,146712,146713,147451},starts={{npcID=120221}},ends={{npcID=120221}},mapCandidates={npc={646},zone={7543}},questType="standard",sourceQuests={46774}},
[46805] = {id=46805,name="The Deceiver's Downfall",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=7543,mapID=646,storyline={46805},description="Once he was as a brother to me. Then he bartered the soul of my world for his own power. Hounded my people across the stars. Twisted my son into a monster. Now he has come to oversee the final assault on Azeroth. To end this world as he has countless others. Kil'jaeden. We must ensure he does not escape our grasp this time, <name>. Storm the tomb. Break the Legion's hold. End the Deceiver's reign.",objectivesText="Enter the Tomb of Sargeras and defeat Kil'jaeden. Progress: Give no quarter. The Deceiver must fall.",starts={{npcID=120372},{npcID=122800}},ends={{npcID=120372},{npcID=122800}},mapCandidates={npc={619,646},zone={7543}},questType="standard",sourceQuests={46734}},
[46808] = {id=46808,name="Ship - Highmountain",level=0,requiredLevel=0,faction="both",sharable=false,expansion=7,zoneID=7334,mapID=630,mapCandidates={npc={},zone={7334}},questType="standard"},
[46811] = {id=46811,name="The Broodmother's Wrath",level=45,requiredLevel=45,faction="none",categories={},flags={"rare"},sharable=false,expansion=7,zoneID=7543,mapID=646,storyline={46811},objectivesText="Daumyr mounted Demons killed",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={7543}},questType="standard",db2Objectives={{text="Daumyr mounted",amount=1,type=0,objectID=120492,orderIndex=0},{text="Demons killed",amount=100,type=0,objectID=116313,orderIndex=1}},worldTaskTitle="The Broodmother's Wrath",db2PoiMapID=1220,db2PoiUiMapID=646,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
[46812] = {id=46812,name="Draconic Secrets",level=45,requiredLevel=45,faction="both",requiredClasses={6},sharable=false,expansion=7,zoneID=8672,mapID=115,description="Arthas never found the prize he sought, Deathlord. It is ours by right. The dragons must know where the resting place of their kin resides. Find a member of the bronze flight, the tenders of history. Do not be merciful.",rewardGold=20220,rewardXP=770,startObjects={{mapID=118,x=0.447,y=0.044}},endObjects={{mapID=118,x=0.447,y=0.044}},coords={mapID=118,x=0.447,y=0.044},mapCandidates={npc={},zone={8672}},questType="standard",sourceQuests={46720},questLines={{id=351,name="Class Mount: Death Knight",orderIndex=2,flags=0}},campaigns={{id=302,title="Death Knight Order Hall",questLineID=351,questLineOrder=5,stallText="Complete the quest Armies of Legionfall in Dalaran to continue the campaign."}},campaignLockText="Complete the quest Armies of Legionfall in Dalaran to continue the campaign."},
[46813] = {id=46813,name="The Lost Glacier",level=45,requiredLevel=45,faction="both",requiredClasses={6},categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8676,mapID=871,storyline={46719,46720,46812,46813},description="Do you know why the red dragonflight seeks to prevent us from finding our prize? The bones of a great red dragon teem with the essence of life, even decades after its passing. You will consume this life essence, blight it, and turn it to undeath. And then you will raise a dragon. Fly now into the north. Find this glacier, and your destiny.",objectivesText="Travel to the Lost Glacier. Progress: Go, now, and find your frozen destiny.",rewardGold=202200,rewardXP=6140,rewardItems={142223,142224,142225,142227,142231,142232,143489,143493,143502,143638},mapCandidates={npc={},zone={8676}},questType="standard",sourceQuests={46812},questLines={{id=351,name="Class Mount: Death Knight",orderIndex=3,flags=0}},campaigns={{id=302,title="Death Knight Order Hall",questLineID=351,questLineOrder=5,stallText="Complete the quest Armies of Legionfall in Dalaran to continue the campaign."}},campaignLockText="Complete the quest Armies of Legionfall in Dalaran to continue the campaign.",db2LabelIDs={4785},db2PoiMapID=1738,db2PoiUiMapID=871},
[46814] = {id=46814,name="Call of the Frostwyrm",level=45,requiredLevel=45,faction="none",categories={},flags={"rare"},sharable=false,expansion=7,zoneID=7543,mapID=646,storyline={46814},objectivesText="Demons slain",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={7543}},questType="standard",db2Objectives={{text="Demons slain",amount=25,type=0,objectID=116313,orderIndex=0}},worldTaskTitle="Call of the Frostwyrm",db2PoiMapID=1220,db2PoiUiMapID=646,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
[46815] = {id=46815,name="Eredath, Jewel of Argus",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={46815,46818,46834,46941,47066,47685,47686,47687,47688,47689,47690,47882,47883,48081,48107},description="The shattered ruin below us is all that remains of Eredath . We called it the Jewel of Argus. It was here that my fellows in the triumvirate guided our people to prosperity. That was a long time ago. <Velen lapses into a moment of silence.> Join me on the surface. We will begin our search for the Crown of the Triumvirate.",objectivesText="Descend to Eredath with Velen.",rewardGold=50550,rewardXP=770,rewardItems={29106,31307,32649,108897},starts={{npcID=128725}},ends={{npcID=120533}},mapCandidates={npc={882},zone={8701}},questGiverID=128725,questType="standard",sourceQuests={48081},questLines={{id=366,name="The Crown of the Triumvirate",orderIndex=1,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=366,questLineOrder=5,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[46816] = {id=46816,name="Rendezvous",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={46297,46732,46816,46839,46840,46841,46842,46843,46938,47589,47627,47641,48483,48500},description="There is much to be done before this nightmare can end, but we need to regroup before we draw more attention from the Legion. I managed to retain a signal crystal during the crash used to call transport beacons from the Xenedar. With luck, we should be able to use it to establish a link between here and your forces as well.",objectivesText="Use the Signal Crystal to call down a Lightforged Beacon from the Vindicaar. Progress: We must establish a link to your vessel before we can press on.",rewardGold=77400,rewardXP=770,starts={{npcID=120529}},ends={{npcID=120529}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={46732},questLines={{id=345,name="Assault on Argus",orderIndex=7,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=345,questLineOrder=1,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[46817] = {id=46817,name="Infernal Downfall",level=45,requiredLevel=45,faction="none",categories={},flags={"rare"},sharable=false,expansion=7,zoneID=7543,mapID=646,storyline={46817},objectivesText="First Infernal ritual stopped Second Infernal ritual stopped Third Infernal ritual stopped",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={7543}},questType="standard",db2Objectives={{text="First Infernal ritual stopped",amount=1,type=0,objectID=120283,orderIndex=0},{text="Second Infernal ritual stopped",amount=1,type=0,objectID=120398,orderIndex=1},{text="Third Infernal ritual stopped",amount=1,type=0,objectID=120399,orderIndex=2}},worldTaskTitle="Infernal Downfall",db2PoiMapID=1220,db2PoiUiMapID=646,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
[46818] = {id=46818,name="Defenseless and Afraid",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={46815,46818,46834,46941,47066,47685,47686,47687,47688,47689,47690,47882,47883,48081,48107},description="This is the battle that raged while I awaited the Genedar. So many ran to join me, but Kil'jaeden inspired still more to stand in their way. My people were slaughtered without mercy. To cover our retreat I ordered for this arena's defenses to be activated. It is clear that they were unable. To turn the tide in this battle, to give these spirits rest, we must do what they could not. Find a way to activate the pylons.",objectivesText="Collect Stolen Pylon Cores from enemies in Triumvirate's End and use them to activate 3 Ancient Pylons . Progress: I will hold this position. The spirits may be only echoes of their former selves, but they do not know that.",rewardGold=212700,rewardXP=6140,rewardItems={152408,153052},starts={{npcID=120533}},ends={{npcID=120533}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={46815},questLines={{id=366,name="The Crown of the Triumvirate",orderIndex=2,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=366,questLineOrder=5,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
