[46827] = {id=46827,name="Meld Into the Shadows",level=45,requiredLevel=45,faction="horde",requiredClasses={4},categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=7543,mapID=646,storyline={45073,45571,45576,45629,45848,46322,46323,46324,46326,46827},description="We should meet back up with the rest of the council and tell them of what we have achieved this day. At your leisure, return to us. We shall be waiting.",objectivesText="Return to the Hall of Shadows, and meet Lord Jorach Ravenholdt .",rewardGold=238680,rewardXP=6140,rewardItems={147474},starts={{npcID=117259}},ends={{npcID=117259}},mapCandidates={npc={646},zone={7543}},questTurnInID=117259,questType="standard",sourceQuests={45629},questLines={{id=5856,name="Saga of the Shadowblade IV",orderIndex=15,flags=0}},campaigns={{id=294,title="Rogue Order Hall",questLineID=5856,questLineOrder=4,stallText="Complete the quest Armies of Legionfall in Dalaran to continue the campaign."}},campaignLockText="Complete the quest Armies of Legionfall in Dalaran to continue the campaign.",db2PoiMapID=1220,db2PoiUiMapID=627},
