[46832] = {id=46832,name="Aalgen Point",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=7543,mapID=646,storyline={46244,46245,46246,46247,46248,46249,46250,46251,46252,46286,46730,46734,46769,46832,46845,47137,47139},series={46845},description="You wanna hold territory on this chunder puddle of an island, right? Right. That means linkin' up with camps on the outskirts, mate. I know this bloke called Heidirk. Scrappy fella, loves to get into the thick of it. Headed out to the eastern coast with those drakes of his. Have a look for him. Remind him he owes me a pint or two!",objectivesText="Speak with Heidirk the Scalekeeper at Aalgen Point.",rewardGold=101100,rewardXP=3070,rewardCurrencies={{id=1226,amount=100}},starts={{npcID=120183}},ends={{npcID=120118}},mapCandidates={npc={646},zone={7543}},questType="standard",sourceQuests={46734},questLines={{id=309,name="Legionfall Campaign",orderIndex=5,flags=0}},campaigns={{id=290,title="Legionfall Campaign",questLineID=309,questLineOrder=0,stallText="Complete the quest Uniting the Isles in Dalaran."}},campaignLockText="Complete the quest Uniting the Isles in Dalaran.",db2PoiMapID=1220,db2PoiUiMapID=646},
[46833] = {id=46833,name="Nature Unshackled",level=45,requiredLevel=45,faction="none",categories={},flags={"rare"},sharable=false,expansion=7,zoneID=7543,mapID=646,storyline={46833},objectivesText="Plans disrupted Demons slain Captured Druid freed",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={7543}},questType="standard",db2Objectives={{text="Plans disrupted",amount=1,type=15,objectID=0,orderIndex=0},{text="Demons slain",amount=20,type=0,objectID=120709,orderIndex=1},{text="Captured Druid freed",amount=13,type=0,objectID=120735,orderIndex=3}},worldTaskTitle="Nature Unshackled",db2PoiMapID=1220,db2PoiUiMapID=646,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
[46834] = {id=46834,name="Khazaduum, First of His Name",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={46815,46818,46834,46941,47066,47685,47686,47687,47688,47689,47690,47882,47883,48081,48107},description="The Argunite Matrix that powered this part of Eredath was shattered by a hulking beast. We had never seen another like him. He was called Khazaduum and he was a most faithful servant of the Legion. He volunteered to undergo an experimental transformation to become the first of his kind. His arrival was the end of this battle. As a prize he took the Argunite Keystone from the shattered matrix. Take it back and we can finally end this bloodshed.",objectivesText="Retrieve the Argunite Keystone from the Echo of Khazaduum. Progress: Please, they should not be made to suffer any longer.",rewardGold=202200,rewardXP=6140,rewardItems={152407},starts={{npcID=120533}},ends={{npcID=120533}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={46815},questLines={{id=366,name="The Crown of the Triumvirate",orderIndex=3,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=366,questLineOrder=5,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[46835] = {id=46835,name="Whispers of a Frightened World Tracking",level=1,requiredLevel=1,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=7502,mapID=627,storyline={46835},rewardItems={151789},mapCandidates={npc={},zone={7502}},questType="standard"},
[46839] = {id=46839,name="From Darkness",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={46297,46732,46816,46839,46840,46841,46842,46843,46938,47589,47627,47641,48483,48500},description="I'm afraid it's only a matter of time before our presence is known. We must begin our preparations at once.",objectivesText="Walk with High Exarch Turalyon .",rewardGold=50550,rewardXP=770,rewardItems={84060,84061,84062,84063,84064,257143,265106,265631},starts={{npcID=120529}},ends={{npcID=120760}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={46816},questLines={{id=345,name="Assault on Argus",orderIndex=8,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=345,questLineOrder=1,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[46840] = {id=46840,name="Prisoners No More",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={46297,46732,46816,46839,46840,46841,46842,46843,46938,47589,47627,47641,48483,48500},description="Hatuun's people have endured arduous times. Their numbers dwindle as those ripped from beyond the walls of their sanctuary become servants to the annihilan lords in the pits just beyond, sentenced to a life of labor, torture and ultimately, death. Seek out these captives, release them from their bonds and show our allies we stand as one against the Burning Legion.",objectivesText="Rescue 10 Darkfallen Slaves from the Annihilan Pits.",rewardGold=101100,rewardXP=6140,starts={{npcID=120760}},ends={{npcID=120953}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={46839},questLines={{id=345,name="Assault on Argus",orderIndex=10,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=345,questLineOrder=1,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[46841] = {id=46841,name="Threat Reduction",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={46297,46732,46816,46839,46840,46841,46842,46843,46938,47589,47627,47641,48483,48500},description="In time, Hatuun and his people will set aside their bitterness and become valuable allies. But their trust must be earned. He says their village is beset by a demon called Aggonar and his cruel kin. We need these fiends out of the way before we can seek out Alleria and the others. The chieftain lent us his horn. Use it to call down his people's vengeance upon the demon lieutenants while I carve a path to Aggonar's lair.",objectivesText="Slay Kar'aaz , Xeth'tal , and Magraloth in the Annihilan Pits. Progress: Has the threat been dealt with?",rewardGold=202200,rewardXP=6140,rewardItems={152700},starts={{npcID=120760}},ends={{npcID=120953}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={46839},questLines={{id=345,name="Assault on Argus",orderIndex=9,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=345,questLineOrder=1,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[46842] = {id=46842,name="A Strike at the Heart",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={46297,46732,46816,46839,46840,46841,46842,46843,46938,47589,47627,47641,48483,48500},description="These pits have long been a blight upon the lives of our new allies. The demons hunt them down and torture the poor souls for sport. <Turalyon shakes his head with disgust, fixing his gaze upon the beast before him.> It is time to make them pay for their cruelty and restore hope to this Light-forsaken place. We strike on your mark, <name>.",objectivesText="Slay Aggonar . Progress: No rest until the deed is done.",rewardGold=202200,rewardXP=6140,starts={{npcID=120953}},ends={{npcID=120738},{npcID=124995}},mapCandidates={npc={830},zone={8574}},questType="group",sourceQuests={46840,46841},questLines={{id=345,name="Assault on Argus",orderIndex=11,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=345,questLineOrder=1,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[46843] = {id=46843,name="Return to the Vindicaar",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={46297,46732,46816,46839,46840,46841,46842,46843,46938,47589,47627,47641,48483,48500},description="That pit lord won't trouble our new allies any longer. <Turalyon's brow furrows.> Until another takes its place, at least. If there's one thing I've learned in our endless war against the Legion, it's to savor victories as you find them. Come, let us take a moment to regroup back at your vessel. Alleria and I have been waiting a long time for a reunion with our son.",objectivesText="Return to the Vindicaar.",rewardGold=50550,rewardXP=770,starts={{npcID=120738},{npcID=124995}},ends={{npcID=120738}},mapCandidates={npc={830},zone={8574}},questTurnInID=120738,questType="standard",sourceQuests={46842},questLines={{id=345,name="Assault on Argus",orderIndex=12,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=345,questLineOrder=1,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=831},
[46844] = {id=46844,name="Cathedral of Eternal Night: Mistress of Blades",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8527,mapID=646,storyline={46844},objectivesText="Larithia Slain Mephistroth Slain",rewardGold=309800,rewardXP=6140,mapCandidates={npc={},zone={8527}},questType="standard",sourceQuests={46773},db2Objectives={{text="Larithia Slain",amount=1,type=0,objectID=120712,orderIndex=0},{text="Mephistroth Slain",amount=1,type=0,objectID=116944,orderIndex=1}},worldTaskTitle="Cathedral of Eternal Night: Mistress of Blades",db2PoiMapID=1220,db2PoiUiMapID=646,db2QuestInfoID=145,db2QuestInfoName="Legionfall Dungeon World Quest"},
[46845] = {id=46845,name="Vengeance Point",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={"loremaster"},sharable=true,expansion=7,zoneID=7543,mapID=646,storyline={46244,46245,46246,46247,46248,46249,46250,46251,46252,46286,46730,46734,46769,46832,46845,47137,47139},series={46832},description="On my way here, I ran across a squad of demon hunters headed northwest to Vengeance Point. You can bet the Legion will try to stop them from establishing a forward position. I spoke to an elf named Izal Whitemoon . Not the friendliest sort, but I'm sure she'd be grateful if you lent the Illidari a hand... whether she admits it or not.",objectivesText="Defeat the Legion siege on Vengeance Point and report to Izal Whitemoon . Progress: This siege is disabling my bats from their scouting duties.",rewardGold=101100,rewardXP=3070,rewardCurrencies={{id=1226,amount=100}},starts={{npcID=120118}},ends={{npcID=111323}},mapCandidates={npc={646},zone={7543}},questType="standard",sourceQuests={46832},questLines={{id=309,name="Legionfall Campaign",orderIndex=6,flags=0}},campaigns={{id=290,title="Legionfall Campaign",questLineID=309,questLineOrder=0,stallText="Complete the quest Uniting the Isles in Dalaran."}},campaignLockText="Complete the quest Uniting the Isles in Dalaran.",db2PoiMapID=1220,db2PoiUiMapID=646},
[46846] = {id=46846,name="The Word of Zul",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8670,mapID=1165,series={48176},description="I have a mundane task for you. Our esteemed Prophet Zul has words to distribute to very specific individuals in de port. And he requested you be de one to deliver dem. Don't ask me why he didn't just have you deliver these when you were here de first time. De prophet is notorious for not sharing all of his visions.",rewardGold=257400,rewardXP=1415,starts={{npcID=126684}},ends={{npcID=126684}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={47514},questLines={{id=5389,name="Unrest in Zuldazar",orderIndex=32,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
