[46924] = {id=46924,name="The Wolf's Tale",level=45,requiredLevel=45,faction="both",requiredClasses={11},categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=493,mapID=80,storyline={44869,44877,44888,44921,45425,45426,45498,45528,45532,46044,46674,46675,46676,46677,46924},series={45426,45498,45528,46674},description="Goldrinn sure didn't take any time getting out of here, did he? Let's go see if we can find him outside.",objectivesText="Find Goldrinn outside of the Stormrage Barrow Dens.",rewardGold=101100,rewardXP=3070,starts={{npcID=120032}},ends={{npcID=115750}},mapCandidates={npc={80},zone={493}},questGiverID=120032,questType="standard",sourceQuests={45498,45528},questLines={{id=5886,name="The Eternal Dream IV",orderIndex=7,flags=0}},campaigns={{id=300,title="Druid Order Hall",questLineID=5886,questLineOrder=9,stallText="Complete the quest Armies of Legionfall in Dalaran to continue the campaign."}},campaignLockText="Complete the quest Armies of Legionfall in Dalaran to continue the campaign.",db2PoiMapID=1,db2PoiUiMapID=80},
[46926] = {id=46926,name="Shakedown",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,series={50835},description="Where are de guards? Princess Talanji has convinced King Rastakhan to permit outsiders in our port. For de first time in centuries, we have allowed non-trolls to set foot on our shores and peddle their wares. And now trolls of lesser tribes seem to think dey can take advantage of these merchants? I will not allow dis sort of behavior. While I investigate why de merchants are not protected, I want you to work your way through de bazaar and slay any thugs you find. Send dem a message.",rewardGold=257400,rewardXP=1415,starts={{npcID=135441}},ends={{npcID=135441}},mapCandidates={npc={1165},zone={8499}},questType="standard",sourceQuests={50835},questLines={{id=594,name="Port of Zandalar",orderIndex=0,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=31,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[46927] = {id=46927,name="Punishment of Tal'aman",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8670,mapID=1165,description="Look, Zolani is going about dis all wrong. If you want de Amani, or anyone, to pay attention, take out their leaders. Go into Tal'aman and look for their mighty gong. Challenge four of their disciples to combat and slay dem.",rewardGold=514800,rewardXP=1770,starts={{npcID=126684}},ends={{npcID=126684}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={46846},questLines={{id=594,name="Port of Zandalar",orderIndex=1,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=34,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[46928] = {id=46928,name="Punishment of Tal'farrak",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8670,mapID=1165,description="De Sandfury tribe may have had a hand in some crime around here, but it is really their false belief system dat makes dem do dis sort of thing. Enter Tal'farrak, bang de gong within, and face de hydra dey keep as a sacred pet. Bring me dis thing's tongues.",rewardGold=514800,rewardXP=1770,starts={{npcID=126684}},ends={{npcID=126684}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={46926},questLines={{id=594,name="Port of Zandalar",orderIndex=2,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=35,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[46929] = {id=46929,name="Deterrent",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="General Jakra'zet had orders to ensure dis place had protection. Guard protection. I see none of dat. Jakra'zet is a stubborn general, and one I have had my eye on for a while now. Regardless, we must remind dese lesser tribes who rules dis city with a message dey will understand. I charge you with collecting heads. Enter Tal'farrak and Tal'aman, and collect a quota of heads.",rewardGold=243360,rewardXP=1415,rewardChoices={155305,155267,155268,155269,155270},starts={{npcID=135441}},ends={{npcID=135441}},mapCandidates={npc={1165},zone={8499}},questType="standard",sourceQuests={46926},questLines={{id=594,name="Port of Zandalar",orderIndex=3,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=33,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[46930] = {id=46930,name="Rastakhan",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8670,mapID=1165,description="You stand before General Jakra'zet , lord of de armies of Zandalar, enforcer of her seas and bringer of war. And I do not like you. It took years to earn my place here after your Horde laid waste to my people. You will not undo what I have built. I will see you kneel before King Rastakhan . I will watch you beg as he lets me take your head for a trophy. I will fling your corpse into de wastes of Vol'dun. Her \"Highness\" may object... but she is not queen yet. Come. Let us fly to your fate.",rewardGold=257400,rewardXP=1415,starts={{npcID=122661}},ends={{npcID=120740}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={46957},questLines={{id=318,name="Welcome to Zandalar",orderIndex=1,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=3,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=318,questLineOrder=3,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},
[46931] = {id=46931,name="Speaker of the Horde",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="Your Horde has grown powerful, eclipsing some of de troll empires in its magnitude. For saving my daughter, you have earned de right to a presence in my city. Since my daughter has taken such a fondness to you, you may join her in de Great Seal beneath us. De servants there will answer to you now. Talanji seems excited by whatever she has planned for your people. I look forward to being amused by it later. Zolani can show you a way down dat does not involve falling.",rewardGold=257400,rewardXP=1415,starts={{npcID=120740}},ends={{npcID=120168},{npcID=133050}},mapCandidates={npc={1165},zone={8499}},questType="standard",sourceQuests={46930},questLines={{id=318,name="Welcome to Zandalar",orderIndex=2,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=4,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=318,questLineOrder=3,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},
