[46935] = {id=46935,name="The Shadow of the Sentinax",level=45,requiredLevel=45,faction="both",categories={},flags={"loremaster"},sharable=false,expansion=7,zoneID=7543,mapID=646,storyline={46935},description="This device appears to be used to relay messages to the large demon ship up above. Unfortunately, it is cracked and unresponsive. Perhaps someone at Deliverance Point will know more about these beacons.",objectivesText="Bring the Broken Sentinax Beacon to Warmage Kath'leen in Deliverance Point. Provided item:",rewardGold=202200,rewardXP=6140,rewardItems={146903,146905,146906,146907,146908,146909,146910,146911,146912,146913,146914,146915,146916,146917,146918,146919,146920,146921,146922,146923,147355,147356},ends={{npcID=120898}},coords={mapID=646,source="quest_giver",x=0.444,y=0.622},mapCandidates={npc={646},zone={7543}},questType="standard",sourceQuests={46734},startItems={147356}},
[46938] = {id=46938,name="Alone in the Abyss",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={46297,46732,46816,46839,46840,46841,46842,46843,46938,47589,47627,47641,48483,48500},series={47589},description="Champion, we will suffer the same fate as the Army of the Light if the Legion fires that infernal weapon upon us. We must descend into the siege camp below and destroy it while we still can!",objectivesText="Speak to Grand Artificer Romuul to disembark the Vindicaar.",rewardGold=50550,rewardXP=1535,rewardItems={152593,152626},starts={{npcID=126307}},ends={{npcID=119543}},mapCandidates={npc={830},zone={8574}},questGiverID=126307,questType="standard",sourceQuests={48440},questLines={{id=345,name="Assault on Argus",orderIndex=0,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=345,questLineOrder=1,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[46941] = {id=46941,name="The Path Forward",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={46815,46818,46834,46941,47066,47685,47686,47687,47688,47689,47690,47882,47883,48081,48107},description="<Velen stares beyond the arena for a time.> We must continue on, but I feel Eredath is far from finished with us. We should take advantage of this relative safety while we still can. I will place a signal beacon that will allow the Vindicaar to lock onto our location. Romuul will send us our means of returning to the Vindicaar if there is a need.",objectivesText="Call down a Lightforged Beacon. Progress: Much remains to be seen, <name>. Argus has not forgotten us.",rewardGold=101100,rewardXP=6140,rewardItems={210455,211313},starts={{npcID=120533}},ends={{npcID=120533}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={47066},questLines={{id=366,name="The Crown of the Triumvirate",orderIndex=5,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=366,questLineOrder=5,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
