[47000] = {id=47000,name="The Council's Call",level=45,requiredLevel=45,faction="both",categories={},flags={"loremaster"},sharable=false,expansion=7,zoneID=7543,mapID=646,storyline={44782,44821,46765,47000},series={44781,44782,44821,45030,45033,45037,45043,45045,45050,45052,45053,45054,45059,45060,45061,46765},description="I'm sorry that I haven't kept your apprised of the situation. We needed more actionable information before bringing the matter before you. The Council of the Six has been investigating Legion threats outside of the Broken Shore. I believe this scroll to be the final piece of information we need. Meet me in Dalaran at the Violet Citadel. We will need the other members of the Council.",objectivesText="Seek out the Council of Six in the Violet Citadel.",rewardGold=20220,rewardXP=770,starts={{npcID=116302}},ends={{npcID=116302}},mapCandidates={npc={646},zone={7543}},questTurnInID=116302,questType="standard",sourceQuests={46765},questLines={{id=278,name="The Council's Challenge",orderIndex=1,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=627},
[47001] = {id=47001,name="Rare Elite 21",level=1,requiredLevel=1,faction="both",categories={},flags={"repeatable","daily"},sharable=false,expansion=7,zoneID=7543,mapID=646,storyline={47001},rewardGold=309800,rewardXP=1415,rewardItems={246936,249400,254267,254579,264675},starts={{npcID=121046,mapID=646,x=0.79,y=0.408}},ends={{npcID=121046}},mapCandidates={npc={},zone={7543}},questTurnInID=121046,questType="standard",db2VignetteID=1948,db2VignetteName="Brother Badatin"},
[47002] = {id=47002,name="The Crown of the Triumvirate",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={47002},description="We begin our search now, . The Crown of the Triumvirate was created to spread the Light's touch to all. With it, our culture thrived. When I fled Argus with the Draenei, I took one shard of the Crown with me to ensure that it would not fall into the wrong hands. Kil'jaeden and Archimonde's fragments are still here. I will seek them out, but you will need to safeguard me while I search. Stay close, my friend.",objectivesText="Protect Velen while he locates fragments of the Crown of the Triumvirate.",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8701}},questType="standard"},
[47003] = {id=47003,name="Restoration: The Bradensbrook Investigation",level=45,requiredLevel=45,faction="alliance",requiredClasses={7},categories={},flags={},sharable=true,expansion=7,zoneID=7502,mapID=641,storyline={45864,46079,46080,46082,46106,46107,46200,47003},series={46078,46079,46080,46082,47004,47005,47006,47027,47029},description="We have uncovered forged orders from the Shore. They have a fel influence about them. They guide the reader to believe they are legitimate. It orders Black Rook Hold to attack a \"demonic enclave\" just south of their walls. There's only one enclave they could be talking about, Bradensbrook! Is it possible these would be able to convince the undead to attack Bradensbrook? You should head there immediately and either warn them, or render aid. Specialization: Restoration Shaman",objectivesText="Go to Bradensbrook in Val'sharah.",rewardGold=20220,rewardXP=770,starts={{npcID=90418}},ends={{npcID=118752}},mapCandidates={npc={641},zone={7502}},questGiverID=90418,questType="standard",sourceQuests={44821,47027},questLines={{id=304,name="The Black Rook Threat",orderIndex=4,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=641},
