[47018] = {id=47018,name="Beast Mastery: Rumblings Near Feltotem",level=45,requiredLevel=45,faction="alliance",requiredClasses={3},categories={},flags={},sharable=true,expansion=7,zoneID=7502,mapID=650,storyline={45564,45575,45587,45726,45796,45841,45842,47018},series={45560,45564,45575,45587,45726,45796,47019,47020,47031,47035},description="The Highmountain have passed along a dire warning from their drogbar allies. The Feltotem are spreading their demonic corruption into the wildlife around them, infecting the land itself. We believe this is something that should be looked into sooner rather than later. The drogbar chieftain, Navarrogg , is handling this personally and we'd like you to meet him near the Feltotem village. Specialization: Beast Mastery Hunter",objectivesText="Find Navarrogg at the Misty Coast in Highmountain.",rewardGold=20220,rewardXP=770,starts={{npcID=90418}},ends={{npcID=117225}},mapCandidates={npc={650},zone={7502}},questGiverID=90418,questType="standard",sourceQuests={44821,47031},questLines={{id=296,name="The Fel Worm Menace",orderIndex=3,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=650},
[47019] = {id=47019,name="Windwalker: Rumblings Near Feltotem",level=45,requiredLevel=45,faction="alliance",requiredClasses={10},categories={},flags={},sharable=true,expansion=7,zoneID=7502,mapID=650,storyline={45564,45575,45587,45726,45796,45841,45842,47019},series={45560,45564,45575,45587,45726,45796,47018,47020,47031,47035},description="The Highmountain have passed along a dire warning from their drogbar allies. The Feltotem are spreading their demonic corruption into the wildlife around them, infecting the land itself. We believe this is something that should be looked into sooner rather than later. The drogbar chieftain, Navarrogg , is handling this personally and we'd like you to meet him near the Feltotem village. Specialization: Windwalker Monk",objectivesText="Find Navarrogg at the Misty Coast in Highmountain.",rewardGold=20220,rewardXP=770,starts={{npcID=90418}},ends={{npcID=117225}},mapCandidates={npc={650},zone={7502}},questGiverID=90418,questType="standard",sourceQuests={44821,47031},questLines={{id=296,name="The Fel Worm Menace",orderIndex=2,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=650},
