[47037] = {id=47037,name="Balance: The Twisted Twin",level=45,requiredLevel=45,faction="alliance",requiredClasses={11},sharable=false,expansion=7,zoneID=7543,mapID=646,description="I have a request from an old friend, Karam Magespear , to help find his brother, Raest. Karam fears that Raest is dealing with dark powers, and wishes to stop him. Originally Raest trained with the Kirin Tor, but such were his aspirations of power that he turned to the forbidden art of Necromancy. He was discovered and expelled from our order. Find Karam in the Legerdemain Lounge and see if you can lend a hand. Specialization: Balance Druid",rewardGold=20220,rewardXP=770,starts={{npcID=90463}},ends={{npcID=116175}},mapCandidates={npc={646},zone={7543}},questGiverID=90463,questType="standard",sourceQuests={44821,47034},questLines={{id=312,name="Twins Challenge",orderIndex=0,flags=0}}},
