[47043] = {id=47043,name="Havoc: The Thieving Apprentice",level=45,requiredLevel=45,faction="both",requiredClasses={12},sharable=false,expansion=7,zoneID=16,mapID=76,description="The Focusing Iris has been stolen from the Dalaran Vaults! The thief was a mage of some skill, but we've been unable to track him. Fortunately, the thief dropped a note from his master, addressing him as one of his \"apprentici.\" I know of only one mage who uses that particular pluralization - Archmage Xylem. I'll need you to investigate. In Azshara you will find his tower where he trains his apprentices. Go there, and see what Xylem is up to. Specialization: Havoc Demon Hunter",rewardGold=20220,rewardXP=770,starts={{npcID=105081}},ends={{npcID=115791}},mapCandidates={npc={76},zone={16}},questGiverID=105081,questType="standard",sourceQuests={44821,47032},questLines={{id=313,name="Xylem Challenge",orderIndex=1,flags=0}}},
