[47049] = {id=47049,name="Demonology: Fate of the Tideskorn",level=45,requiredLevel=45,faction="both",requiredClasses={9},categories={},flags={},sharable=true,expansion=7,zoneID=7502,mapID=634,storyline={45486,45522,45523,45524,45525,45862,46340,47049},description="A scout from Stormheim arrived yesterday with a significant discovery - these ancient scrolls. Within they contain a Valkyra prophecy of a new vrykul ruler - one who could turn the Tideskorn against the Legion. It complicates matters that this vrykul may in fact be Skovald's heir. Take the scrolls, find the heir, and bring her to the Valkyra. I think the outcasts they refer to are the vrykul of Jandvik, so that would be a good place to start. Specialization: Demonology Warlock",objectivesText="Search Jandvik for the vrykul mentioned in the scrolls.",rewardGold=20220,rewardXP=770,rewardItems={144457},starts={{npcID=90417}},ends={{npcID=116568}},mapCandidates={npc={634},zone={7502}},questGiverID=90417,questType="standard",sourceQuests={44821,47033},questLines={{id=310,name="God-Queen Challenge",orderIndex=1,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=680},
[47050] = {id=47050,name="Enhancement: Fate of the Tideskorn",level=45,requiredLevel=45,faction="both",requiredClasses={7},categories={},flags={},sharable=true,expansion=7,zoneID=7502,mapID=634,storyline={45486,45522,45523,45524,45525,45862,46340,47050},description="A scout from Stormheim arrived yesterday with a significant discovery - these ancient scrolls. Within they contain a Valkyra prophecy of a new vrykul ruler - one who could turn the Tideskorn against the Legion. It complicates matters that this vrykul may in fact be Skovald's heir. Take the scrolls, find the heir, and bring her to the Valkyra. I think the outcasts they refer to are the vrykul of Jandvik, so that would be a good place to start. Specialization: Enhancement Shaman",objectivesText="Search Jandvik for the vrykul mentioned in the scrolls.",rewardGold=20220,rewardXP=770,rewardItems={144457},starts={{npcID=90417}},ends={{npcID=116568}},mapCandidates={npc={634},zone={7502}},questGiverID=90417,questType="standard",sourceQuests={44821,47033},questLines={{id=310,name="God-Queen Challenge",orderIndex=2,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=680},
