[47055] = {id=47055,name="Fire: The Folly of Levia Laurence",level=45,requiredLevel=45,faction="alliance",requiredClasses={8},categories={},flags={},sharable=true,expansion=7,zoneID=7502,mapID=627,storyline={45125,45126,45127,45861,45916,45917,46327,47055},description="Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good. Levia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands. She was last seen at the Scribe's Sacellum. Ask around there and see if you can pick up her trail. Specialization: Fire Mage",objectivesText="Ask around the city for information on Levia Laurence. Progress: Have you found any clues to Levia's disappearance?",rewardGold=297900,rewardXP=6140,starts={{npcID=90418}},ends={{npcID=90418}},mapCandidates={npc={},zone={7502}},questGiverID=90418,questTurnInID=90418,questType="standard",sourceQuests={44821,47035},questLines={{id=311,name="Imp Mother Challenge",orderIndex=3,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=627},
[47056] = {id=47056,name="Fury: The Folly of Levia Laurence",level=45,requiredLevel=45,faction="alliance",requiredClasses={1},categories={},flags={},sharable=true,expansion=7,zoneID=7502,mapID=627,storyline={45125,45126,45127,45861,45916,45917,46327,47056},description="Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good. Levia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands. She was last seen at the Scribe's Sacellum. Ask around there and see if you can pick up her trail. Specialization: Fury Warrior",objectivesText="Ask around the city for information on Levia Laurence. Progress: Have you found any clues to Levia's disappearance?",rewardGold=202200,rewardXP=6140,starts={{npcID=90418}},ends={{npcID=90418}},mapCandidates={npc={},zone={7502}},questGiverID=90418,questTurnInID=90418,questType="standard",sourceQuests={44821,47035},questLines={{id=311,name="Imp Mother Challenge",orderIndex=2,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=627},
[47057] = {id=47057,name="Unholy: The Folly of Levia Laurence",level=45,requiredLevel=45,faction="alliance",requiredClasses={6},categories={},flags={},sharable=true,expansion=7,zoneID=7502,mapID=627,storyline={45125,45126,45127,45861,45916,45917,46327,47057},description="Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good. Levia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands. She was last seen at the Scribe's Sacellum. Ask around there and see if you can pick up her trail. Specialization: Unholy Death Knight",objectivesText="Ask around the city for information on Levia Laurence.",rewardGold=202200,rewardXP=6140,starts={{npcID=90418}},ends={{npcID=90418}},mapCandidates={npc={},zone={7502}},questGiverID=90418,questTurnInID=90418,questType="standard",sourceQuests={44821,47035},questLines={{id=311,name="Imp Mother Challenge",orderIndex=4,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=627},
[47058] = {id=47058,name="Outlaw: The Folly of Levia Laurence",level=45,requiredLevel=45,faction="alliance",requiredClasses={4},categories={},flags={},sharable=true,expansion=7,zoneID=7502,mapID=627,storyline={45125,45126,45127,45861,45916,45917,46327,47058},description="Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good. Levia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands. She was last seen at the Scribe's Sacellum. Ask around there and see if you can pick up her trail. Specialization: Outlaw Rogue",objectivesText="Ask around the city for information on Levia Laurence.",rewardGold=202200,rewardXP=6140,starts={{npcID=90418}},ends={{npcID=90418}},mapCandidates={npc={},zone={7502}},questGiverID=90418,questTurnInID=90418,questType="standard",sourceQuests={44821,47035},questLines={{id=311,name="Imp Mother Challenge",orderIndex=1,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=627},
[47059] = {id=47059,name="Feral: The Folly of Levia Laurence",level=45,requiredLevel=45,faction="alliance",requiredClasses={11},categories={},flags={},sharable=true,expansion=7,zoneID=7502,mapID=627,storyline={45125,45126,45127,45861,45916,45917,46327,47059},description="Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good. Levia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands. She was last seen at the Scribe's Sacellum. Ask around there and see if you can pick up her trail. Specialization: Feral Druid",objectivesText="Ask around the city for information on Levia Laurence. Progress: Have you found any clues to Levia's disappearance?",rewardGold=202200,rewardXP=6140,starts={{npcID=90418}},ends={{npcID=90418}},mapCandidates={npc={},zone={7502}},questGiverID=90418,questTurnInID=90418,questType="standard",sourceQuests={44821,47035},questLines={{id=311,name="Imp Mother Challenge",orderIndex=0,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=627},
[47061] = {id=47061,name="Apocron",level=45,requiredLevel=45,faction="none",sharable=false,expansion=7,zoneID=7543,mapID=646,starts={{npcID=121124,mapID=646,x=0.6,y=0.628}},mapCandidates={npc={},zone={7543}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=121124}},worldTaskTitle="Apocron",db2QuestInfoID=144,db2QuestInfoName="Legionfall World Quest"},
[47066] = {id=47066,name="Consecrating Ground",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={46815,46818,46834,46941,47066,47685,47686,47687,47688,47689,47690,47882,47883,48081,48107},description="We have everything we need. In the alcove below you will find the shattered remains of the Argunite Matrix . Replacing the Keystone will restore it to full capacity. The pylons you activated will then be able to repel those who still hunt my people. At long last this battle will be over. I hope it brings them peace.",objectivesText="Repair the Argunite Matrix beneath Triumvirate's End. Progress: Hurry <name>, we cannot let this continue any longer.",rewardGold=151650,rewardXP=6140,starts={{npcID=120533}},ends={{npcID=120533}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={46818,46834},questLines={{id=366,name="The Crown of the Triumvirate",orderIndex=4,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=366,questLineOrder=5,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47068] = {id=47068,name="Rare Elite 25",level=1,requiredLevel=1,faction="both",categories={},flags={"repeatable","daily"},sharable=false,expansion=7,zoneID=7543,mapID=646,storyline={47068},rewardGold=309800,rewardXP=1415,rewardItems={246936,249400,254267,254579,264675},starts={{npcID=116166,mapID=646,x=0.6519,y=0.316}},ends={{npcID=116166}},mapCandidates={npc={},zone={7543}},questTurnInID=116166,questType="standard",db2VignetteID=1970,db2VignetteName="Eye of Gurgh"},
[47097] = {id=47097,name="A Walk to Remember",level=45,requiredLevel=45,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=7543,mapID=646,storyline={46268,46272,46274,46275,46282,47097,47112,47202},description="It's good to have you at my side, <name>. I've come to the Broken Shore to see, for myself, the price that my father... that the Alliance has paid to protect our world. As long as I am blind to the suffering and sacrifices of my people, I will never be able to lead them to peace. Time is short, we should move onward.",objectivesText="Escort King Anduin to Soul Ruin at the Broken Shore.",rewardXP=6140,starts={{npcID=121224}},ends={{npcID=121226}},mapCandidates={npc={646},zone={7543}},questType="standard",sourceQuests={47202},questLines={{id=347,name="The King's Path",orderIndex=5,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=646},
[47098] = {id=47098,name="Out Like Flynn",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={46727,46728,46729,47098,47099,47186,47189,51341},series={46727,46728,46729,47099,51341,57766,58983,59641,60362},description="I'm relieved you woke up! Having to carry you would have made this job far less appealing. The name's Flynn, and my client in Boralus is paying me a king's bounty to break you out of here. You, my friend, are incarcerated in Tol Dagor. Used to be a legit prison... 'til the Ashvane Trading Company bought it. Now it's Priscilla's own personal fortress, riddled with scum on both sides of the bars. Wasn't hard to bribe my way into this cell. Now we just have to get out. Not to worry. I have a plan!",objectivesText="Escape Tol Dagor with Flynn. Progress: Is that the new powder Flynn was talking about? I'll take it for safekeeping.",rewardGold=514800,rewardXP=1770,rewardItems={52019,158075,160326},starts={{npcID=121239}},ends={{npcID=121235}},mapCandidates={npc={895,1161},zone={8978}},questType="standard",sourceQuests={51341},questLines={{id=589,name="A Nation Divided",orderIndex=3,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=3,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=589,questLineOrder=2,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=1161},
[47099] = {id=47099,name="Get Your Bearings",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=1161,storyline={46727,46728,46729,47098,47099,47186,47189,51341},series={46727,46728,46729,47098,51341,57766,58983,59641,60362},description="I think a proper introduction is in order! My name is Taelia , member of the Proudmoore Guard and squire of Sir Cyrus Crestfall. < Taelia salutes firmly.> Cyrus asked me and Flynn to break you out of that Ashvane prison and get you settled in here at the market, but he neglected to mention that you're with the Alliance. I must say, it's an honor. Let's get you up to speed.",objectivesText="Visit the Ferry Dock, the Snug Harbor Inn, the Tradewinds Counting House, and the Flight Master in Tradewinds Market. Progress: I'll bring you to Cyrus after a brief tour of the market.",rewardGold=128700,rewardXP=710,rewardItems={158075,160326},starts={{npcID=121235}},ends={{npcID=121235}},mapCandidates={npc={1161},zone={8568}},questTurnInID=121235,questType="standard",questLines={{id=589,name="A Nation Divided",orderIndex=4,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=4,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=589,questLineOrder=2,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[47100] = {id=47100,name="Arkhaan's Pain",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={40761,47100,47101,47180,47183,47184,47203,47217,47218,47219,47220,47238,47654},description="Darkness envelops us... the Light has gone from this place... < Arkhaan mumbles to himself before noticing you are still talking to him.> Arkhaan could not save them. Brothers. Sisters. Whispers twisted them. The Light cannot see them. It turns away from us. Arkhaan failed. < Arkhaan stares off into space.>",objectivesText="Slay 12 Broken in Oronaar Collapse. Progress: < Arkhaan mutters incoherently to himself.>",rewardGold=101100,rewardXP=6140,rewardCurrencies={{id=1508,amount=50}},starts={{npcID=121518}},ends={{npcID=121518}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={40761,47101},questLines={{id=368,name="Shadow of Eredath",orderIndex=3,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=368,questLineOrder=8,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47101] = {id=47101,name="Arkhaan's Prayers",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={40761,47100,47101,47180,47183,47184,47203,47217,47218,47219,47220,47238,47654},description="<As you near the statue, a somber voice fills your mind.> \"You must resist the shadow's pull. Come to me, brothers and sisters. Be whole within the Light. Let Arkhaan show you the way home.\" <The rest of the message is garbled, though the nearby broken seem to be gnawing on pieces of the statue.>",objectivesText="Collect 5 Fragmented Prayers . Progress: Did you find anything interesting?",rewardGold=50550,rewardXP=6140,rewardItems={147763},rewardCurrencies={{id=1508,amount=50}},ends={{npcID=121230}},startObjects={{objectID=271103,mapID=882,x=0.467,y=0.688}},coords={mapID=882,source="quest_giver",x=0.357778,y=0.541556},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={47238},questLines={{id=368,name="Shadow of Eredath",orderIndex=2,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=368,questLineOrder=8,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47102] = {id=47102,name="The Mysterious Missive",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={47102},series={47104,47134,47182,47554},description="<On the body, you find a missive emblazoned with the seal of the Army of the Light. If the messenger was killed to prevent the letter's delivery, its contents must be of great import.>",objectivesText="Search near the Xenedar for someone with knowledge of the Sealed Missive . Progress: Our fight goes on, champion. Argus must fall. What is that you've found?",rewardGold=101100,rewardXP=6140,rewardItems={147491,147496},starts={{npcID=121260}},ends={{npcID=121519}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={47994}},
[47103] = {id=47103,name="Journey to Nazmir",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=9598,mapID=1165,series={48535,47105},description="It is time to put an end to de blood trolls in Nazmir before their monstrous horde descends upon Zuldazar. My most loyal followers are willing to come with me to dat cursed place. But it will not be enough. I am relieved dat you and de Horde are willing to help. Rokhan and his darkspears are getting ready to leave. I will finish my preparations here. Meet with Rokhan and make your way to Nazmir , I will see you there.",rewardGold=30900,rewardXP=345,starts={{npcID=133050}},ends={{npcID=126549}},mapCandidates={npc={1165},zone={9598}},questType="standard",sourceQuests={47512},questLines={{id=320,name="Nazmir, the Dark Jungle",orderIndex=0,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=1,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47104] = {id=47104,name="Imprisoned Inquisitor",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={47104,47134,47182,47287,47554},series={47102,47134,47182,47554},description="This report states that the Legion seeks to free an imprisoned Legion inquisitor called Raalgar, a demon from here on Argus who cannot be killed because of a secret magic he alone possesses. Because of his immortality, he is held in the Arcatraz in Tempest Keep. The Light Mother told us of that naaru stronghold, but I've never set eyes upon it myself, <name>. Turalyon mentioned the Vindicaar has some connection to Tempest Keep. Perhaps your ship's engineer knows more.",objectivesText="Travel to the Vindicaar and ask Grand Artificer Romuul about High Inquisitor Raalgar.",rewardGold=179010,rewardXP=6140,starts={{npcID=121519}},ends={{npcID=121519}},mapCandidates={npc={830},zone={8574}},questTurnInID=121519,questType="standard",sourceQuests={47554},questLines={{id=355,name="The Legion Jailbreak",orderIndex=1,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=886},
[47105] = {id=47105,name="Into The Darkness",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47103,48535},description="We are in Nazmir to stop de blood trolls from destroying Zuldazar. Dis is de start of our campaign to end dem. Dese monsters want my kingdom and its people destroyed. We are going destroy dem first. My father thinks de blood troll threat will go away on its own, like it did in de past. But things are different now. Rokhan and de others are moving north of here to establish a camp for us to stay in, den dey will join us in de fight. Are you ready?",rewardGold=25740,rewardXP=345,starts={{npcID=120904}},ends={{npcID=130844}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={48535},questLines={{id=320,name="Nazmir, the Dark Jungle",orderIndex=2,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=4,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47112] = {id=47112,name="Lost Souls",level=45,requiredLevel=45,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=7543,mapID=646,storyline={46268,46272,46274,46275,46282,47097,47112,47202},description="Never in my life have I beheld such destruction... such misery. The very ground we walk on us paved with the bones of our allies. Even now I can see the lost spirits of Alliance soldiers wandering the ruins. I cannot leave this place without putting the souls of our brave soldiers to rest. We owe them... I owe them that much.",objectivesText="Release 10 Lost Souls .",rewardGold=122850,rewardXP=6140,rewardItems={181478,181549,181552,181646,181648,181650,181743,184149,184379,184380,184763,184764},starts={{npcID=121226}},ends={{npcID=121237}},mapCandidates={npc={646},zone={7543}},questType="standard",sourceQuests={47097},questLines={{id=347,name="The King's Path",orderIndex=6,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=646},
