[47118] = {id=47118,name="Tomb of Sargeras: Free The Tormented",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8524,mapID=646,storyline={47118},description="The souls inside the Tomb are being twisted by an Engine of Horror. Destroy it, and free them from this torment.",objectivesText="Defeat the Desolate Host in the Tomb of Sargeras . Progress: How are you finding the challenges of the Tomb of Sargeras ?",rewardItems={147501,147518,147519,147520,147521},starts={{npcID=93787,mapID=24,x=0.5344,y=0.7863}},ends={{npcID=120183}},coords={mapID=646,source="quest_giver",x=0.445,y=0.631},mapCandidates={npc={646},zone={7543}},questType="raid",startItems={147501}},
