[47130] = {id=47130,name="Improper Burial",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="De blood trolls are gathering de corpses of my people for their blood magic. Dis ends today. I will take care of de corpses here. Take dis torch. Its fires are blessed by priests of Bwonsamdi, de loa of death. Burn any corpses of my people dat you see. Each corpse burned means less power for dese monsters' blood magic.",rewardGold=257400,rewardXP=2765,rewardChoices={155327,155328,155329,155330,155319,155320,155321,155322},starts={{npcID=121241},{npcID=130844}},ends={{npcID=121241}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47105},questLines={{id=320,name="Nazmir, the Dark Jungle",orderIndex=4,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=5,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47132] = {id=47132,name="Fel Fire and Ice",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=7543,mapID=646,storyline={47132},objectivesText="Threat extinguished",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={7543}},questType="world",db2Objectives={{text="Threat extinguished",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Fel Fire and Ice",db2PoiMapID=1220,db2PoiUiMapID=646,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[47134] = {id=47134,name="Foiling the Legion's Jailbreak",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8574,mapID=886,storyline={47104,47134,47182,47287,47554},series={47102,47104,47182,47554},description="High Inquisitor Raalgar has some connection to the fel here on Argus that makes him unkillable. Long ago, the naaru imprisoned him on the Arcatraz. When the forces of Kael'thas Sunstrider attacked the citadel, we were forced to flee on the Exodar. Some Legion prisoners escaped the Arcatraz when last the Legion invaded Azeroth, but Raalgar did not. Stop them from freeing him and I will study the source of his immortality so it can be broken. I can get you close. The rest is up to you.",objectivesText="Find High Inquisitor Raalgar before the Legion frees him. Progress: We must stop High Inquisitor Raalgar!",rewardGold=151650,rewardXP=6140,rewardItems={152962},starts={{npcID=121263}},ends={{npcID=121263}},mapCandidates={npc={},zone={8899}},questGiverID=121263,questTurnInID=121263,questType="standard",sourceQuests={47104},questLines={{id=355,name="The Legion Jailbreak",orderIndex=2,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=886},
[47135] = {id=47135,name="For Their Own Good",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={47135},objectivesText="Frenzied Marsuul Kits calmed",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8574}},questType="world",db2Objectives={{text="Frenzied Marsuul Kits calmed",amount=12,type=0,objectID=123763,orderIndex=0}},worldTaskTitle="For Their Own Good",db2PoiMapID=1669,db2PoiUiMapID=882,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[47137] = {id=47137,name="Champions of Legionfall",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=7543,mapID=646,storyline={46244,46245,46246,46247,46248,46249,46250,46251,46252,46286,46730,46734,46769,46832,46845,47137,47139},description="The battle to reclaim the Broken Shore is straining our resources. We cannot afford to relent, lest the Legion undo all that we have accomplished. The members of your order have given much, but more is needed. Rally your champions and do what you must to bolster their ranks. There may be untapped power in this land that will turn the tide of war in our favor.",objectivesText="Return to your class order hall and recruit a new champion.",rewardGold=404400,rewardXP=7675,starts={{npcID=116576}},ends={{npcID=116576}},mapCandidates={npc={646},zone={7543}},questType="standard",sourceQuests={43359,43407,43409,43412,43414,43415,43418,43420,43422,43423,43424,43425,46734},questLines={{id=309,name="Legionfall Campaign",orderIndex=8,flags=0}},campaigns={{id=290,title="Legionfall Campaign",questLineID=309,questLineOrder=0,stallText="Complete the quest Uniting the Isles in Dalaran."}},campaignLockText="Complete the quest Uniting the Isles in Dalaran.",db2PoiMapID=1220,db2PoiUiMapID=646},
[47139] = {id=47139,name="Mark of the Sentinax",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=7543,mapID=646,storyline={46244,46245,46246,46247,46248,46249,46250,46251,46252,46286,46730,46734,46769,46832,46845,47137,47139},description="The Sentinax rains down terror upon the Broken Shore, unleashing hordes of demons that menace our forces. The fiends seek to stop us from taking the Tomb. They will fail. Lure out the strongest among their vile ranks. Slay them and seize the marks they bear. Make the Legion fear our strength!",objectivesText="Collect 50 Marks of the Sentinax . Progress: The Sentinax is well defended, but we will crush everything it sends against us.",rewardGold=404400,rewardXP=7675,rewardItems={146127,146903,146905,146906,146907,146909,146910,147356,147582,147775,147891,147892},starts={{npcID=117873}},ends={{npcID=117873}},mapCandidates={npc={646},zone={7543}},questType="standard",sourceQuests={46251},questLines={{id=309,name="Legionfall Campaign",orderIndex=10,flags=0}},campaigns={{id=290,title="Legionfall Campaign",questLineID=309,questLineOrder=0,stallText="Complete the quest Uniting the Isles in Dalaran."}},campaignLockText="Complete the quest Uniting the Isles in Dalaran.",db2PoiMapID=1220,db2PoiUiMapID=646},
[47148] = {id=47148,name="Something Different",level=90,requiredLevel=90,faction="both",categories={},flags={"loremaster","weekly","repeatable"},sharable=true,expansion=7,zoneID=15969,mapID=2393,storyline={47148},description="Even the most bloodthirsty combatants eventually grow weary and turn their backs to the unending struggle of war. They seek a new way to test their mettle and destroy their enemies. Join the Brawl in progress and fight your opponents in a limited time event that tosses traditional rules aside.",objectivesText="Win a PvP Brawl. Progress: Even I could not foresee the strange ways in which you would fight your enemies <name>.",rewardItems={137642,139781,147203},rewardCurrencies={{id=1602,amount=110},{id=1792,amount=250},{id=1602,amount=65}},starts={{npcID=254971}},ends={{npcID=144383},{npcID=144384},{npcID=196191},{npcID=219260},{npcID=254971}},mapCandidates={npc={1161,1165,2112,2339,2393},zone={15969}},questType="standard"},
[47180] = {id=47180,name="The Pulsing Madness",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={40761,47100,47101,47180,47183,47184,47203,47217,47218,47219,47220,47238,47654},description="This broken still retains some of his sanity, though not all of it. I can sense some Void influence nearby, but it is isolated to small pockets. Dispelling these manifestations should help our friend here clear his mind. Perhaps we can use the prayer fragments you found, as they still contain some Light energy. I will try and make sense of his chattering in the meantime. Maybe we can learn something about what is happening here.",objectivesText="Dispel 5 Void Manifestations .",rewardGold=101100,rewardXP=6140,rewardItems={151563,152712},rewardCurrencies={{id=1508,amount=50}},starts={{npcID=121230}},ends={{npcID=121230}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={40761,47101},questLines={{id=368,name="Shadow of Eredath",orderIndex=4,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=368,questLineOrder=8,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47181] = {id=47181,name="The Smoking Gun",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={47181,47485,47486,47487,47488,50531,50573,53041},description="The Ashvane Company doesn't know it yet, but throwing you into Tol Dagor was the biggest mistake they've ever made. That new powder we swiped could be the key to bringing them down. First, how about we give everyone a little demonstration of just how powerful this stuff is? <Flynn loads a pinch of the glittering powder into his pistol.> Go ahead, take a shot at that barrel over there.",objectivesText="Fire Flynn's Pistol at the Water Barrel in the Harbormaster's Office. Progress: Don't worry, it won't hurt anyone. I think.",rewardGold=13090,rewardXP=1060,rewardItems={158065,158066,163032,163034},starts={{npcID=121239}},ends={{npcID=121239}},mapCandidates={npc={895},zone={8978}},questType="standard",sourceQuests={47960},questLines={{id=585,name="The Ashvane Trading Company",orderIndex=0,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=10,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[47182] = {id=47182,name="Long Overdue",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8574,mapID=886,storyline={47104,47134,47182,47287,47554},series={47102,47104,47134,47554},description="I have learned much. High Inquisitor Raalgar has moved to a base near the Legion citadel across the mountains. This is where he keeps the Fel Heart of Argus , the source of his immortality, and it is powered by wells leading directly to the core of Argus. He is preparing to attack so you will strike first. Mark the location of the wells and I will rain holy fire upon them with the Vindicaar's guns. With that connection to the fel on Argus broken, Raalgar can be killed and the Fel Heart retrieved.",objectivesText="Mark the Argussian Heartwells for the Vindicaar's guns, kill the Legion garrison, and retrieve the Fel Heart of Argus from High Inquisitor Raalgar. Progress: Have you dealt with High Inquisitor Raalgar yet?",rewardGold=202200,rewardXP=6140,rewardItems={147906},starts={{npcID=121263}},ends={{npcID=121263}},mapCandidates={npc={},zone={8574}},questGiverID=121263,questTurnInID=121263,questType="standard",sourceQuests={47134},questLines={{id=355,name="The Legion Jailbreak",orderIndex=3,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=886},
[47183] = {id=47183,name="Arkhaan's Plan",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={40761,47100,47101,47180,47183,47184,47203,47217,47218,47219,47220,47238,47654},description="Arkhaan remembers. He remembers something that will... yes... will save us. Follow Arkhaan . Isolon calls! We will offer soft words to the Light. The Light will banish the darkness. < Arkhaan eyes Alleria warily.> Arkhaan will watch that one closely.",objectivesText="Follow Arkhaan to Isolon.",rewardGold=101100,rewardXP=6140,rewardCurrencies={{id=1508,amount=50}},starts={{npcID=121518}},ends={{npcID=121230}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={47100,47180},questLines={{id=368,name="Shadow of Eredath",orderIndex=5,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=368,questLineOrder=8,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47184] = {id=47184,name="Arkhaan's Peril",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={40761,47100,47101,47180,47183,47184,47203,47217,47218,47219,47220,47238,47654},description="Whatever called to him, it cannot have good intentions. We need to go in after him. Before we step through this portal, <name>... ensure you are prepared to fight. The Void's influence is rarely peaceful.",objectivesText="Enter the Void Tear and deal with Arkhaan . Progress: We must address this threat.",rewardGold=151650,rewardXP=6140,rewardCurrencies={{id=1508,amount=100}},starts={{npcID=121230}},ends={{npcID=121230}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={47183},questLines={{id=368,name="Shadow of Eredath",orderIndex=6,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=368,questLineOrder=8,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47186] = {id=47186,name="Sanctum of the Sages",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=1161,storyline={46727,46728,46729,47098,47099,47186,47189,51341},series={47189},description="Sounds like you'll be working with us for awhile. Cyrus will charter a naval transport between here and Stormwind, but I expect you'll want something a bit faster for day to day use. Head back upstairs and take a left when you get outside. You'll find an old study where the Tidesages used to conduct their magic rituals. Surely your Alliance mages have already sensed its power. Inform them they may open their portals there. The harbor guards will keep the room secure.",objectivesText="Speak with a 7th Legion Mage in the Sanctum of the Sages. Progress: The Tidesages abandoned that place months ago when they pulled back to their monasteries. We still don't know why.",rewardGold=154900,rewardXP=710,rewardItems={158075,160326},starts={{npcID=120788},{npcID=121235}},ends={{npcID=120788},{npcID=121235}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={46729},questLines={{id=589,name="A Nation Divided",orderIndex=6,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=7,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=589,questLineOrder=2,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[47188] = {id=47188,name="The Aid of the Loa",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47262,47263},description="De blood trolls are stronger than ever, thanks to dis G'huun... and now dey are empowering a giant construct! We need a plan to destroy dat construct, G'huun, and de blood trolls. It is not going to be easy. But I have an idea.",rewardGold=119340,rewardXP=1385,starts={{npcID=121288}},ends={{npcID=121288}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47263},questLines={{id=320,name="Nazmir, the Dark Jungle",orderIndex=7,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=8,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47189] = {id=47189,name="A Nation Divided",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=1161,storyline={46727,46728,46729,47098,47099,47186,47189,51341},series={47186},description="Kul Tiras must be unified before it can be of any help to the Alliance. Let's get you briefed on the current situation in each of our major territories. Then you can take a look at the map behind me and make the call on where you want to go first.",objectivesText="Inspect the Scouting Map in the Harbormaster's Office. Progress: Have you figured out your next move? Use the planning map to help you decide.",rewardGold=25740,rewardXP=175,rewardItems={158075,160326},starts={{npcID=121235}},ends={{npcID=121235}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={47186},questLines={{id=589,name="A Nation Divided",orderIndex=7,flags=0},{id=615,name="Mission from the King",orderIndex=6,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=8,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=589,questLineOrder=2,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[47193] = {id=47193,name="Battle for Azsuna",level=0,requiredLevel=0,faction="both",sharable=false,expansion=7,zoneID=7334,mapID=630,mapCandidates={npc={},zone={7334}},questType="standard"},
[47194] = {id=47194,name="Battle for Highmountain",level=0,requiredLevel=0,faction="both",sharable=false,expansion=7,zoneID=7334,mapID=630,mapCandidates={npc={},zone={7334}},questType="standard"},
[47195] = {id=47195,name="Battle for Stormheim",level=0,requiredLevel=0,faction="both",sharable=false,expansion=7,zoneID=7334,mapID=630,mapCandidates={npc={},zone={7334}},questType="standard"},
[47196] = {id=47196,name="Battle for Val'sharah",level=0,requiredLevel=0,faction="both",sharable=false,expansion=7,zoneID=7334,mapID=630,mapCandidates={npc={},zone={7334}},questType="standard"},
[47198] = {id=47198,name="They Want Us Alive",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47198,47200,47201,47204,47205,47229},description="Blood troll poisons are made to paralyze, not kill. See, dey want us alive. I do not feel good thinking about why. I am making antitoxins as quickly as I can, but I need someone like yourself to get out dere and test dem. Take what I have made so far and see if we can get those soldiers back on their feet.",objectivesText="Cure 8 Wounded Captives .",rewardGold=257400,rewardXP=1415,rewardItems={147833},starts={{npcID=121599}},ends={{npcID=121599}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47199},questLines={{id=795,name="Blood Gate",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47199] = {id=47199,name="The Blood Gate",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47199},series={47200},description="We just received word that the Northern border is under heavy attack by an army of blood trolls. King Rastakhan has called for reinforcements. You are more familiar with that threat than any of us. Go and do what you can to help them.",objectivesText="Journey to the Blood Gate.",rewardGold=25740,rewardXP=175,starts={{npcID=141555}},ends={{npcID=121599}},mapCandidates={npc={862},zone={9598}},questGiverID=141555,questType="standard",sourceQuests={49426,51244},nextQuests={47198,47200},questLines={{id=864,name="Blood Gate",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47200] = {id=47200,name="Ticks",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47198,47200,47201,47204,47205,47229},series={47199},description="Kill those bloodbellies before dey take off with all of my soldiers! I will have my troops prepare for a flanking charge.",objectivesText="Slay 6 Bloodbelly Fliers. Progress: We are losing too many, too quickly.",rewardGold=257400,rewardXP=1415,starts={{npcID=121599}},ends={{npcID=121599}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47199},questLines={{id=795,name="Blood Gate",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47201] = {id=47201,name="Rokhan",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47198,47200,47201,47204,47205,47229},description="My scouts have informed me dat your Darkspear shadow hunter, Rokhan , has returned from Nazmir. He is pinned down at de far side of de gate. We need to break dis onslaught with a flanking maneuver. Old Rotana is in position. Mount up and smash through de side of those blood troll ranks. Once down dere, try to find Rokhan . Oh, and $p, be careful. A lot of dark magic is being tossed around down dere.",objectivesText="Ride the Old Rotana into the fray and then find Rokhan .",rewardGold=193050,rewardXP=1060,starts={{npcID=121599}},ends={{npcID=121601}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47198,47200},questLines={{id=795,name="Blood Gate",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47202] = {id=47202,name="A Personal Message",level=45,requiredLevel=45,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=1519,mapID=84,storyline={46268,46272,46274,46275,46282,47097,47112,47202},description="The time has come for me to travel to the Broken Shore and see, for myself, the place where my father died. If I am to be the king my father was... the king Stormwind deserves, I must know firsthand the threat my people face. Please tell my advisors that I've gone to the Broken Shore. If I told them myself they'd only try and stop me. I'll wait for you at Deliverance Point. Farewell.",objectivesText="Speak with Prophet Velen .",rewardXP=4605,starts={{npcID=120268}},ends={{npcID=119340}},mapCandidates={npc={84},zone={1519}},questType="standard",sourceQuests={46275},questLines={{id=347,name="The King's Path",orderIndex=4,flags=0}},db2PoiUiMapID=84},
[47203] = {id=47203,name="Throwing Shade",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={10339,10384,10385,10406,10408,10437,10439,47203,47217,47218,47219,63855,63895,63976,63977,63979,63980,63982,63983,63984,63985,85027,85028,85029,85035,85036},description="That was Locus-Walker. He taught me all that I know about the Void, and he still has more to teach me. If he is here, then the ethereals' presence only intrigues me further. I had thought him the only one of his kind, but now that I have seen another tangling with the Void... Come, we must play his game if we want to learn what he knows. He appears to have gone toward the Umbra Hollows to the north.",objectivesText="Investigate the Umbra Hollows with Alleria and Locus-Walker. Progress: Move quickly, or we may lose him.",rewardGold=101100,rewardXP=6140,rewardCurrencies={{id=1508,amount=50}},starts={{npcID=121230}},ends={{npcID=121230}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={47184},questLines={{id=368,name="Shadow of Eredath",orderIndex=7,flags=0},{id=5691,name="Lorewalking: Ethereals",orderIndex=9,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=368,questLineOrder=8,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."},{id=268,title="Lorewalking: The Ethereals",questLineID=5691,questLineOrder=0}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47204] = {id=47204,name="The New Frontline",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47198,47200,47201,47204,47205,47229},series={47205,47229},description="Kill anything ya see dat not a Zandalari!",objectivesText="Slay Blood Troll forces.",rewardGold=238680,rewardXP=1415,starts={{npcID=121601}},ends={{npcID=121601}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47201},questLines={{id=795,name="Blood Gate",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47205] = {id=47205,name="Warmother",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47198,47200,47201,47204,47205,47229},series={47204,47229},description="Old Rotana be cursed by da warmother dese vile blood trolls brought with dem. We need to take her down so we can get dis old direhorn back in da field.",objectivesText="Slay Warmother Shazraka .",rewardGold=514800,rewardXP=1770,rewardItems={158653,162453},rewardChoices={162453,158653},starts={{npcID=121601}},ends={{npcID=121601}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47201},questLines={{id=795,name="Blood Gate",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[47217] = {id=47217,name="Sources of Darkness",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={10339,10384,10385,10406,10408,10437,10439,47203,47217,47218,47219,63855,63895,63976,63977,63979,63980,63982,63983,63984,63985,85027,85028,85029,85035,85036},description="I think I understand what he was trying to show us, <name>. I feel a surge of power building ahead. They must be cultivating the Void, calling it here. We need to stop them before they plunge this entire city into shadow. Find the source and cut it off by any means necessary. Locus-Walker and I have unfinished business to attend to.",objectivesText="Deactivate 5 Void Harvesters . Progress: Locus-Walker and I have some unfinished business to attend to.",rewardGold=101100,rewardXP=6140,rewardCurrencies={{id=1508,amount=50}},starts={{npcID=121230}},ends={{npcID=121230}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={47203},questLines={{id=368,name="Shadow of Eredath",orderIndex=8,flags=0},{id=5691,name="Lorewalking: Ethereals",orderIndex=11,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=368,questLineOrder=8,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."},{id=268,title="Lorewalking: The Ethereals",questLineID=5691,questLineOrder=0}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47218] = {id=47218,name="The Shadowguard Incursion",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={10339,10384,10385,10406,10408,10437,10439,47203,47217,47218,47219,63855,63895,63976,63977,63979,63980,63982,63983,63984,63985,85027,85028,85029,85035,85036},description="As you have surely gathered by now, a certain subset of my people have tragically succumbed to the call of the Void. I had hoped to find more who possess the necessary strength of mind. I am disappointed to find such an utter lack of resistance. It cannot be helped. To advance your cause, and mine, we will need to eradicate these weak-willed beings.",objectivesText="Slay 15 Shadowguard Ethereals. Progress: Walking the razor's edge does have risks, <name>.",rewardGold=151650,rewardXP=6140,rewardCurrencies={{id=1508,amount=100}},starts={{npcID=121597}},ends={{npcID=121597}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={47203},questLines={{id=368,name="Shadow of Eredath",orderIndex=9,flags=0},{id=5691,name="Lorewalking: Ethereals",orderIndex=10,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=368,questLineOrder=8,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."},{id=268,title="Lorewalking: The Ethereals",questLineID=5691,questLineOrder=0}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47219] = {id=47219,name="A Vessel Made Ready",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={10339,10384,10385,10406,10408,10437,10439,47203,47217,47218,47219,63855,63895,63976,63977,63979,63980,63982,63983,63984,63985,85027,85028,85029,85035,85036},description="After some consideration, I have decided to allow Alleria another opportunity to pursue her destiny. I suppose you want to know what that means, mortal. < Locus-Walker laughs.> Meet us deep in the Shadowguard camp ahead- my brethren are preparing a summons that will provide adequate energy for Windrunner to begin again. Witness what happens when you harness the Void's power.",objectivesText="Defeat Nhal'athoth and collect his heart. Progress: I see the path clearly, <name>.",rewardGold=202200,rewardXP=6140,rewardItems={151088,152713},rewardCurrencies={{id=1508,amount=150}},starts={{npcID=121597}},ends={{npcID=121230}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={47217,47218},questLines={{id=368,name="Shadow of Eredath",orderIndex=10,flags=0},{id=5691,name="Lorewalking: Ethereals",orderIndex=12,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=368,questLineOrder=8,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."},{id=268,title="Lorewalking: The Ethereals",questLineID=5691,questLineOrder=0}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47220] = {id=47220,name="A Beacon in the Dark",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={40761,47100,47101,47180,47183,47184,47203,47217,47218,47219,47220,47238,47654},description="That was... an intense experience. <Alleria rubs her forehead.> It is difficult to focus. I need you to return to Velen. Give him this. <She places something cold and dense in your palm.> I feel as though he should have it, though I am not sure why. Tell him all that we have learned. I am sure Romuul will have been watching our progress. With any luck, a beacon is already headed our way.",objectivesText="Take the Remnant of Nhal'athoth to Velen on the Vindicaar. Progress: What is this? Such darkness...",rewardGold=101100,rewardXP=6140,rewardItems={152602},rewardCurrencies={{id=1508,amount=50}},starts={{npcID=121230}},ends={{npcID=121230}},mapCandidates={npc={882},zone={8701}},questTurnInID=121230,questType="standard",sourceQuests={47219},questLines={{id=368,name="Shadow of Eredath",orderIndex=11,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=368,questLineOrder=8,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=886},
[47221] = {id=47221,name="The Hand of Fate",level=45,requiredLevel=45,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8574,mapID=84,storyline={47221,47222,47223,47224,48440,48506},series={47222,47223,47224,47835,47867,48506,48507},description="$p, We have won many battles against the Burning Legion, but it is time to end this war once and for all. Final preparations have begun to depart for Argus. Make haste to Stormwind Harbor. A ship awaits you there to grant you and your allies passage to Azuremyst.",objectivesText="Meet your escort to the Exodar at Stormwind Harbor.",rewardGold=20220,rewardXP=770,rewardItems={132120},ends={{npcID=121754}},coords={mapID=84,source="quest_giver",x=0.215,y=0.305},mapCandidates={npc={84},zone={1519}},questType="standard",questLines={{id=346,name="To Argus!",orderIndex=1,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=346,questLineOrder=0,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2DetailThemeID=3,db2PoiMapID=1750,db2PoiUiMapID=892},
[47222] = {id=47222,name="Two If By Sea",level=45,requiredLevel=45,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=1519,mapID=84,storyline={47221,47222,47223,47224,48440,48506},series={47221,47223,47224,47835,47867,48506,48507},description="The Tomb of Sargeras was only the beginning. If we do not destroy the Legion utterly, they will return even stronger. We will travel to Azuremyst by sea to avoid drawing unnecessary attention. The less time the Legion has to react to our assault, the better. Just say the word when you are ready to depart.",objectivesText="Speak to Vereesa Windrunner to set sail for the Exodar.",rewardGold=20220,rewardXP=770,rewardItems={55015,58216,131354},starts={{npcID=121754}},ends={{npcID=121754}},mapCandidates={npc={84},zone={1519}},questTurnInID=121754,questType="standard",sourceQuests={47221,48506},questLines={{id=346,name="To Argus!",orderIndex=2,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=346,questLineOrder=0,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1750,db2PoiUiMapID=891},
[47223] = {id=47223,name="Light's Exodus",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8840,mapID=892,storyline={47221,47222,47223,47224,47835,47867,48440,48506,48507},series={47221,47222,47224,47835,47867,48506,48507},description="Prophet Velen and the others have gathered within the Vault of Lights below. There is an entrance just down this path. We should find the Prophet at once so that we do not stall the invasion.",objectivesText="Meet Prophet Velen in the Vault of Lights in the Exodar.",rewardGold=20220,rewardXP=770,starts={{npcID=121756}},ends={{npcID=121756}},mapCandidates={npc={},zone={8840}},questGiverID=121756,questTurnInID=121756,questType="standard",sourceQuests={47222},questLines={{id=346,name="To Argus!",orderIndex=6,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=346,questLineOrder=0,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1750,db2PoiUiMapID=892},
[47224] = {id=47224,name="The Vindicaar",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8574,mapID=893,storyline={47221,47222,47223,47224,47835,47867,48440,48506,48507},series={47221,47222,47223,47835,47867,48506,48507},description="Everything is prepared for our assault. We need only establish the beacon to transport us to the vessel. Once the beacon arrives, place your hand upon its surface to board the Vindicaar, the instrument of our retribution.",objectivesText="Board the Vindicaar. Progress: Today marks the beginning of the Legion's downfall.",rewardGold=20220,rewardXP=770,starts={{npcID=120977}},ends={{npcID=120977}},mapCandidates={npc={},zone={8840}},questGiverID=120977,questTurnInID=120977,questType="standard",sourceQuests={47223},questLines={{id=346,name="To Argus!",orderIndex=7,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=346,questLineOrder=0,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1750,db2PoiUiMapID=893},
[47226] = {id=47226,name="The Orphaned Hatchling",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47226,47259,47261,47272,47310,47311,47312,47418,48527,48581,51990,51998},description="<The surviving hatchling bleats piteously as it gazes at its mother's corpse. It inspects you hopefully and seems to want to follow you. Perhaps you can find someone in Warbeast Kraal who can care for it?>",objectivesText="Find someone in Warbeast Kraal who cares for young direhorn.",rewardGold=25740,rewardXP=175,starts={{npcID=122939}},ends={{npcID=121706}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50538},questLines={{id=5402,name="Warbeast Kraal",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47228] = {id=47228,name="Xibalan Ecology",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47228,47235,47329,48317,48399,48400,50043},description="I had really hoped this area would be more hospitable. The Zandalari have been no help whatsoever in clearing this space for archaeological exploration. Before we can even begin to uncover Xibala's secrets, we must make it safe for those less combat savvy to do their work. You will find the ruins ahead infested with all manner of carnivorous beasts. The few intrepid explorers who ventured within have all failed to return. Local ecology will not stand in the way of progress, <name>. Understand?",objectivesText="Slay 8 Xibalan predators.",rewardGold=257400,rewardXP=1415,starts={{npcID=131582}},ends={{npcID=131582}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47329},questLines={{id=5403,name="Fossil Extraction",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47229] = {id=47229,name="Bulwark of Torcali",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47198,47200,47201,47204,47205,47229},series={47204,47205},description="We got Old Rotana up on her feet again. Load up an' take her reins. Give us some cover so Talanji can fight her way in from her side.",objectivesText="Ride Old Rotana into battle against the blood trolls .",rewardGold=514800,rewardXP=1770,starts={{npcID=121601}},ends={{npcID=135708}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47204,47205},questLines={{id=795,name="Blood Gate",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47235] = {id=47235,name="Scrying for the Eye",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47228,47235,47329,48317,48399,48400,50043},description="On behalf of the Horde we seek a relic called the Eye of Xibala. The locals have been no help whatsoever and Miss Tae'shara insists that we use her survey equipment. I abhor guesswork. Instead we shall use a more direct method: scrying. I will mark three locations on your map. I would like you to place a scrying vessel at each of them. I will use their measurements to isolate the relic's location and we will be on our way.",objectivesText="Place 3 Scrying Vessels in Xibala.",rewardGold=257400,rewardXP=1415,rewardItems={143536},starts={{npcID=131580}},ends={{npcID=131580}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47329},questLines={{id=5403,name="Fossil Extraction",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47238] = {id=47238,name="The Seat of the Triumvirate",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={40761,47100,47101,47180,47183,47184,47203,47217,47218,47219,47220,47238,47654},description="Even with the Sigil of Awakening in hand, the Crown cannot save us until it is whole. That is why we must enter the Seat of the Triumvirate, even knowing that L'ura awaits us there. This is a dire task, one that I would not ask if it were not completely necessary. We will descend together. Come.",objectivesText="Seek the Crest of Knowledge. Progress: Such a task I cannot undertake alone. Your help is greatly appreciated, <name>.",rewardGold=70225,rewardXP=770,rewardItems={152241,152242,152243,152244,152939,246936,249400,254267,254579},starts={{npcID=128735}},ends={{npcID=120533}},mapCandidates={npc={882},zone={8701}},questGiverID=128735,questType="standard",sourceQuests={47416},questLines={{id=368,name="Shadow of Eredath",orderIndex=0,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=368,questLineOrder=8,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=883},
[47241] = {id=47241,name="The Shadow of Death",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="We have four loa, but we only know where one is: Bwonsamdi. As uncomfortable as it makes me, I am prepared to do anything to stop de blood trolls... even if it means dealing with de loa of death. Ages ago, Bwonsamdi had a temple here in Nazmir . My scrying has revealed a few locations to de north where I sense a magical presence. Search dem for clues. Hurry, . Zuldazar will fall if we cannot obtain Bwonsamdi's help!",rewardGold=257400,rewardXP=2765,starts={{npcID=121288}},ends={{npcID=122102}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47188},questLines={{id=596,name="The Spirits of Zo'bal",orderIndex=0,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=9,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47244] = {id=47244,name="A Culling of Souls",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Only two types enter Bwonsamdi's temple anymore: those looking to make a deal with death, and de dead. You do not stink, so I guess you are de former. I am headed to de temple myself, so how about a trade? See de land across de bridge? Dere is a witch named Najima dat I have been tracking. De blood trolls are corrupt to de core, but their souls are useful as offerings to Bwonsamdi. She is too strong for me to deal with, but if you can slay her, I will take you to de temple. I give you my word.",rewardGold=477360,rewardXP=3455,starts={{npcID=122102}},ends={{npcID=124428}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47241},questLines={{id=596,name="The Spirits of Zo'bal",orderIndex=1,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=10,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47245] = {id=47245,name="Getting the Message",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47631,47597},description="Da loa be powerful, but we be needin' soldiers if we gonna have a chance of stopping dem blood trolls from building dat giant of theirs. If we not be able ta destroy dat thing before it be finished, den Zuldazar and all of our people gonna be dead! We need da help of da Horde! Word of da situation already be sent to da warchief. As soon as we be hearin' her reply, we can mov-- Wait... what be dat noise?",rewardGold=135750,rewardXP=1385,starts={{npcID=121289},{npcID=131213}},ends={{npcID=131213}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49902},questLines={{id=354,name="An Explosive Delivery",orderIndex=0,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=45,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47246] = {id=47246,name="Remnants of the Damned",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Ever since da spirits have begun calling upon this \"G'huun\" me temple has been covered with the unbearable taint of the undead. Da undead be an abomination, but da bloodstones that create them be powerful. They could be of use ta Bwonsamdi. If you wish ta show me your fervor, then cleanse me temple of their filth and bring me their bloodstones.",rewardGold=238680,rewardXP=2765,mapCandidates={npc={},zone={8500}},questType="standard",questLines={{id=5390,name="Lost in Nazmir",orderIndex=15,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47247] = {id=47247,name="That Which Haunts the Dead",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Bwonsamdi knows why ya be here. Ya be seekin' me favor. Bwonsamdi ponders you silently.> A test, ta see if ya be worth Bwonsamdi 's time. Dere be spirits whose prayers sing of something called \"G'huun.\" Dey pay me homage no more. I will not allow da desecration of me own temple! Go and subdue da strongest of da ancient spirits. If ya do dis for me, ya may be worth da trouble after all.",rewardGold=514800,rewardXP=3455,rewardChoices={159051,159049,159052,159050,155336,155337,155338,155339},starts={{npcID=122688}},ends={{npcID=122688}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47880},questLines={{id=335,name="A Pact with Death",orderIndex=2,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=14,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47248] = {id=47248,name="'Til Death Do Us Part",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={47248},description="I don't know who you are, but I need your help. My precious Valjabu always told me he didn't care dat he took de vows of a priest... we would be together forever. Well, my time came to pass, and I knew I'd not be able to go on without him. I came back and have been waiting in dis spot for... it seems forever, and Valjabu never showed! I've been walking around dis world for far too long. Please, I beg you, bring a memento of my Valjabu back to me!",objectivesText="Obtain Valjabu's Tusk Ring . Progress: Did you find Valjabu yet? His urn is around here somewhere.",rewardGold=257400,rewardXP=2765,rewardItems={150754},starts={{npcID=122706}},ends={{npcID=122706}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47880}},
[47249] = {id=47249,name="Soulbound",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47250},description="Ya did well with me tasks. I be thinkin' ya show promise. Ya might be worthy of a deal. Very well, I pledge ta lend ya me powers ta use against ya foes. In exchange, ya be sendin' one million souls ta Bwonsamdi ! No need ta look shocked, ya be plenty capable of doing dis. Come, meet with me at da Court of Spirits. Dere, we will finalize our agreement.",rewardGold=772200,rewardXP=4150,rewardChoices={155346,155350,155351,155344,155348,155369,155347,155365},starts={{npcID=122688}},ends={{npcID=122766}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47491,49348,49432},questLines={{id=335,name="A Pact with Death",orderIndex=6,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=19,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47250] = {id=47250,name="We'll Meet Again",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47249},description="Now, it be time for ya ta leave. Dere be many of dem blood troll souls for ya ta be sendin' to da Other Side for Bwonsamdi , and ya not gonna find any more of dem here.",rewardGold=25740,rewardXP=345,starts={{npcID=122766}},ends={{npcID=127004}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47249},questLines={{id=335,name="A Pact with Death",orderIndex=7,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=20,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47251] = {id=47251,name="Interesting Times",level=1,requiredLevel=1,faction="horde",categories={},flags={"loremaster"},sharable=false,expansion=7,zoneID=440,mapID=85,storyline={47251},description="<name>, I don't mean to alarm you, but we may be experiencing some... temporal disturbances. Have you ever heard the phrase 'I hope the past doesn't come back to haunt you?' Come visit me in the Valley of Spirits and we can speak more.",objectivesText="Meet with Historian Ju'Pa in the Valley of Spirits of Orgrimmar.",rewardGold=238680,rewardXP=200,rewardItems={128507,147880,147881},ends={{npcID=110035}},startObjects={{mapID=85,x=0.364,y=0.744}},coords={mapID=85,source="quest_giver",x=0.365,y=0.7445},mapCandidates={npc={85},zone={440}},questType="standard",db2QuestSortName="Nightborne",startItems={147881}},
[47252] = {id=47252,name="Interesting Times",level=1,requiredLevel=1,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=440,mapID=84,storyline={47252},description="<name>, I don't mean to alarm you, but we may be experiencing some... temporal disturbances. Have you ever heard the phrase 'I hope the past doesn't come back to haunt you?' Come visit me in the Stormwind Royal Library and we can speak more.",objectivesText="Meet with Historian Llore in the Royal Library of Stormwind.",rewardGold=312800,rewardXP=200,rewardItems={147876,147880,162636},ends={{npcID=110034}},startObjects={{mapID=84,x=0.846,y=0.25}},coords={mapID=84,source="quest_giver",x=0.845,y=0.253},mapCandidates={npc={84},zone={440}},questType="standard",db2QuestSortName="Nightborne",startItems={147880}},
[47254] = {id=47254,name="The Originals",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=440,mapID=85,storyline={47254},description="Long ago, great terrors walked our lands, and drove even the smallest to flights of heroism. I speak, of course, about Lord Kazzak , Azuregos , and the Dragons of Nightmare. Legends have it that so sought after were their treasures, that armies would camp overnight to hunt them down. The dragons have felt disturbances in the timeways, coincidentally located where these giants once roamed. They have tasked me with finding champions to investigate.",objectivesText="Defeat Lord Kazzak in Blasted Lands, Azuregos in Azshara, and the Dragon of Nightmare at one of the portals to the Emerald Dream. Progress: They're just memories, right?",rewardGold=1366400,rewardXP=8230,rewardItems={14344,63207,65274,139552,139590,150393,150417,232877,233014},rewardCurrencies={{id=1166,amount=150}},starts={{npcID=110035},{npcID=223882}},ends={{npcID=110035},{npcID=223882}},mapCandidates={npc={71,85},zone={440}},questType="standard",db2LabelIDs={4063},db2QuestSortName="Nightborne"},
[47257] = {id=47257,name="The Bones of Xibala",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47257},series={47329},description="Far to the south you will find the bones of an ancient creature. This is Xibala, the progenitor, first of the devilsaurs. She was mother to Rezan, mother to all that came after. The Zandalari do not live there, as it belongs to beasts now. I have heard rumors of some of your Horde arriving in search of something among her bones. This is ill advised. Look into it, won't you?",objectivesText="Travel to Xibala and speak with Examiner Tae'shara Bloodwatcher .",rewardGold=25740,rewardXP=175,starts={{npcID=120168}},ends={{npcID=131582}},mapCandidates={npc={862},zone={9598}},questGiverID=120168,questType="standard",sourceQuests={49426},nextQuests={47329}},
[47258] = {id=47258,name="Prepare for a Siege",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47258},description="It would seem we must make ready for a siege. For now, return to your Horde in Dazar'alor. Prepare for de coming conflict. Should de forces of Nazmir surge, I will send word.",objectivesText="Speak with Baine Bloodhoof .",rewardGold=257400,rewardXP=1415,starts={{npcID=135890}},ends={{npcID=135890}},mapCandidates={npc={862},zone={8499}},questTurnInID=135890,questType="standard",sourceQuests={47229}},
[47259] = {id=47259,name="Direhorn Daycare",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47226,47259,47261,47272,47310,47311,47312,47418,48527,48581,51990,51998},description="Handler Bazkoji had a real gift with de little ones. If dis hatchling is following you, it must mean Bazkoji is dead. I don't have time to find another handler. Are you up to de task? It's a lot of work, and de little ones get attached real fast. If you're going to care for it, it will be a commitment. That baby will be depending on you. I hope you will be up to de task of feeding and protecting it. First things first: food. Dere is plenty of fodder in de pens and river below.",objectivesText="Feed your hatchling.",rewardGold=257400,rewardXP=1415,starts={{npcID=121706}},ends={{npcID=121706}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47226},questLines={{id=5402,name="Warbeast Kraal",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47260] = {id=47260,name="Side Effects May Include...",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47260},description="<Your direhorn companion hiccoughs repeatedly. Each time, it either shrinks or grows by a perceptible amount. It whines at you in distress. You could use some help.>",objectivesText="Speak to Beastlord L'kala in Warbeast Kraal.",rewardGold=23400,rewardXP=850,starts={{npcID=141952}},ends={{npcID=121706}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47310}},
[47261] = {id=47261,name="How to Train Your Direhorn",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47226,47259,47261,47272,47310,47311,47312,47418,48527,48581,51990,51998},description="I have to get some of whatever you fed your baby! Wow! Now dat it's bigger, it is time to teach it to be a reliable battle companion. Let's see how it does against a tougher challenge, hmm? Talk to Kraal Master B'khor when you are ready to begin.",objectivesText="Talk to Kraal Master B'khor and choose to train your direhorn. Progress: How did de training go?",rewardGold=514800,rewardXP=1770,starts={{npcID=121706}},ends={{npcID=122009}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47418},questLines={{id=5402,name="Warbeast Kraal",orderIndex=9,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47262] = {id=47262,name="Ending the Blood Trolls",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47263,47188},description="De loa are smiling on us today. De \"matriarch\" of dese blood trolls, a sick monster named Ateena, is up ahead. We have a change in plans, . We will end dis threat now. We kill Ateena and de blood trolls will be thrown into chaos. She is a powerful hexxer. Go start de fight and I will ambush and catch her off guard. Let us get moving. We will be back in Zuldazar before de day is over.",rewardGold=257400,rewardXP=2765,starts={{npcID=121241}},ends={{npcID=130844}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47130,47264},questLines={{id=320,name="Nazmir, the Dark Jungle",orderIndex=3,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=3,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47263] = {id=47263,name="A Time of Revelation",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47262,47188},description="I can feel Ateena's dark voodoo up ahead. We need to stop whatever she is planning with dis \"G'huun\". Be ready for anything, . We do not know what power Ateena truly has. I do know one thing. If G'huun is threatening my people, den it will die, just like Ateena.",rewardGold=238680,rewardXP=2765,starts={{npcID=130844}},ends={{npcID=121288}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47262},questLines={{id=320,name="Nazmir, the Dark Jungle",orderIndex=6,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=7,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47264] = {id=47264,name="Leave None Standing",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Now you see what my father refuses to acknowledge. De blood trolls are slaughtering us, and dey need to be stopped. Our plan is simple, . We will go out dere and kill as many of dese blood trolls as we can. You go east, I go north. Meet with me after and we will see what is left to do. We will teach dese blood trolls to fear de Zandalari!",rewardGold=238680,rewardXP=2765,starts={{npcID=130844}},ends={{npcID=121241}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47105},questLines={{id=320,name="Nazmir, the Dark Jungle",orderIndex=5,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=6,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47272] = {id=47272,name="Direhorn Growth Hormone",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47226,47259,47261,47272,47310,47311,47312,47418,48527,48581,51990,51998},series={47418},description="Nice little critter you got there. Seems a tad too small to be much more than a nuisance though. Wanna help a friend make a profit? There's an abundance of opportunity here, but these trolls won't listen to me! Tell you what, I can make a supplement of sorts that'll make hair grow on your chest! Er, your hatchling's chest! I know direhorn are vegetarians and all, but there's a reason all the biggest predators eat meat! Rapid growth requires protein. LOTS of protein. You interested?",objectivesText="Collect 10 Steaming Fresh Carrion . Progress: So? Did you get everything I need?",rewardGold=257400,rewardXP=1415,rewardItems={150347},starts={{npcID=122129}},ends={{npcID=122129}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47259,48527},questLines={{id=5402,name="Warbeast Kraal",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47283] = {id=47283,name="Chop, Chop!",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=9439,mapID=14,storyline={47283},description="Throm-ka, . I'm always looking for someone who thinks they can swing an axe with the best of them. If you can remove that sapling without much trouble, I'm sure we can find a better use for your skills.",objectivesText="Pick up a Sturdy Axe , then gather 5 Freshly-Chopped Wood from the nearby Sapling. Progress: Hmm?",rewardGold=280900,rewardXP=3410,rewardItems={67163,67180,67197,67213,87399,108439,155127,155128,155131,155136,155139,155150,155153,156514,156531,158641,166846,166970,166971,242241,246697},rewardCurrencies={{id=1540,amount=10}},starts={{npcID=129107}},ends={{npcID=129107}},mapCandidates={npc={14},zone={9439}},questType="standard"},
[47287] = {id=47287,name="The Vindicaar Matrix Core",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8574,mapID=886,storyline={47104,47134,47182,47287,47554},description="Much has happened on Argus that concerns me but none moreso than Xe'ra's fate. I wonder sometimes if we are doing the right thing? But we must carry on. I can rig the Matrix Core that powers the Vindicaar to allow you to call on the power of our guns when you have need of them on the planet. Go to the Matrix Core in the room at the heart of our ship. Once linked, whatever powers the core has installed now and in the future will be at your disposal.",objectivesText="Link Light's Judgment into the Vindicaar Matrix Core. Progress: Have you linked Light's Judgment into the Vindicaar Matrix Core?",rewardGold=101100,rewardXP=3070,starts={{npcID=121263}},ends={{npcID=121263}},mapCandidates={npc={},zone={8899}},questGiverID=121263,questTurnInID=121263,questType="standard",sourceQuests={47743},questLines={{id=355,name="The Legion Jailbreak",orderIndex=4,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=886},
[47288] = {id=47288,name="Valuable Fossils",level=1,requiredLevel=1,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={47288},rewardItems={152419},mapCandidates={npc={},zone={8574}},questType="standard"},
[47289] = {id=47289,name="Teddies and Tea",level=20,requiredLevel=20,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={44785,45079,47289,47428,53464,53465},description="There's nobody to play with here anymore. But you'll play with me, right <mister/lady>? It's time for tea! Help me find the other guests, please!",objectivesText="Gather Mr. Munchykins , Trunksy , and Mayor Striggs for the tea party. Progress: This is going to be the best tea party ever!",rewardGold=257400,rewardXP=2765,rewardItems={154874,154875,154894,166808},starts={{npcID=121603}},ends={{npcID=121603}},mapCandidates={npc={896},zone={8721}},questTurnInID=121603,questType="standard",sourceQuests={48622},questLines={{id=5447,name="A Tea Party",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[47290] = {id=47290,name="World Event Dungeon - Hummel",level=1,requiredLevel=1,faction="none",categories={},flags={},sharable=false,expansion=7,storyline={47290},rewardGold=683200,rewardXP=400,mapCandidates={npc={},zone={}},questType="standard"},
[47310] = {id=47310,name="Naptime",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47226,47259,47261,47272,47310,47311,47312,47418,48527,48581,51990,51998},description="Your not-so-little guy is looking a bit ragged after such an exciting day. I bet you both need a rest, hm? Come back later when you're a bit stronger.",objectivesText="Stable your direhorn in the Beast Pen. Progress: I bet you and your direhorn need a bit of rest, hm?",rewardGold=25740,rewardXP=175,starts={{npcID=121706}},ends={{npcID=121706}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={48581},questLines={{id=5402,name="Warbeast Kraal",orderIndex=11,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47311] = {id=47311,name="Headbutting 101",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47226,47259,47261,47272,47310,47311,47312,47418,48527,48581,51990,51998},description="Your beast is looking well fed. Good. Try and keep it dat way. Now, next you need to teach your little one to defend itself. Direhorns in de wild are prey for much larger creatures and de young are easy pickings for saurid and their like. Go out into de Savagelands and show your little one how to fend dem off. It's all in de horn, <name>.",objectivesText="Assist your hatchling in fighting 12 creatures.",rewardGold=257400,rewardXP=1415,starts={{npcID=121706}},ends={{npcID=121706}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47259,48527},questLines={{id=5402,name="Warbeast Kraal",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47312] = {id=47312,name="Queenfeather",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47226,47259,47261,47272,47310,47311,47312,47418,48527,48581,51990,51998},description="Ah, so you are de one who inherited Bazkoji's herd. What is left of it, anyway. I know what killed him, and I tried to warn him. Queenfeather is a vicious ravasaur, bigger than de rest and smarter as well. Most of de eggs around here are hers. Usually I praise de strength of such a beast, but she has become a nuisance. You will find her guarding her nests in de feeding grounds. Kill her and bring back one of her head feathers as proof dat de deed is done.",objectivesText="Slay Queenfeather and claim one of her feathers. Progress: Does Queenfeather still stalk us?",rewardGold=514800,rewardXP=1770,rewardItems={160945},starts={{npcID=125486}},ends={{npcID=125486}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47259,48527},questLines={{id=5402,name="Warbeast Kraal",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47313] = {id=47313,name="Discreet Discussions",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=1165,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="General Jakra'zet cannot be trusted. He is up to something, but I do not know what. Any who question his actions earn demselves a trip to de sands. As long as he remains in power, my city will never be safe. Speak to his guards. See what you can find out, but be discreet. We do not want to alert Jakra'zet to our actions.",objectivesText="Question Enforcers within Dazar'alor. Progress: It is not safe to ask questions about de general around here.",rewardGold=118170,rewardXP=2060,starts={{npcID=133050}},ends={{npcID=122817}},mapCandidates={npc={1165},zone={8670}},questGiverID=133050,questType="standard",sourceQuests={47513},questLines={{id=605,name="Unlikely Allies",orderIndex=0,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=1,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47314] = {id=47314,name="Rumors of Exile",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=1165,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="Talanji sent you, didn't she? De princess needs to know dat it is no longer safe to ask such questions so openly. Warguard Rakera spoke out, and no one has heard from her since. Rumor has it she was exiled to Vol'dun .",objectivesText="Follow Bladeguard Kaja .",rewardGold=30900,rewardXP=515,rewardItems={179384},rewardChoices={179384},starts={{npcID=122817}},ends={{npcID=122320}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={47313},questLines={{id=605,name="Unlikely Allies",orderIndex=1,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=2,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[47315] = {id=47315,name="Into the Dunes",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=1165,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="Whatever Rakera uncovered, it was important enough to earn her a death sentence to de sands. We must head into Vol'dun to find her. We cannot let whatever she knows about Jakra'zet die with her in de dunes.",objectivesText="Fly into the deserts of Vol'dun and search for Warguard Rakera .",rewardGold=257400,rewardXP=4115,starts={{npcID=122320}},ends={{npcID=130455}},mapCandidates={npc={864,1165},zone={8670}},questType="standard",sourceQuests={47314},questLines={{id=605,name="Unlikely Allies",orderIndex=2,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=3,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47316] = {id=47316,name="Secrets in the Sand",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47316,47317,47319,47320,47321,47959,48549,48550,51574},description="I found this journal buried in the sand. Kiro tried to toss it in the fire. \"Our wagon has no space for a diary, Meerah . What practical use does it have?\" Don't tell him I said so, but I think it's fascinating! Can you imagine what kinds of secrets it holds? Quite a few pages are missing, but I bet you can recover them out on the dunes!",objectivesText="Recover the journal's missing pages. Progress: What have you found?",rewardGold=257400,rewardXP=4115,rewardItems={151346},starts={{npcID=122583}},ends={{npcID=130341}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47320},questLines={{id=606,name="Dangers in the Desert",orderIndex=4,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=14,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47317] = {id=47317,name="Searching for Survivors",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47316,47317,47319,47320,47321,47959,48549,48550,51574},description="It is good to see you are safe, but what of de others? Have dey been lost to de sands? You need to head back to de crash site and see if de others survived. I will ask around and see if these fox people can tell us anything about Rakera.",objectivesText="Search for survivors near the crash site.",rewardGold=176280,rewardXP=4115,starts={{npcID=130341}},ends={{npcID=130341}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47320},questLines={{id=606,name="Dangers in the Desert",orderIndex=3,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=12,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47319] = {id=47319,name="Restorative Venom",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={"loremaster"},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47316,47317,47319,47320,47321,47959,48549,48550,51574},description="Meerah here found your friend in the dunes. The lightning strike nearly killed her. It might still, without treatment. The wasps within the grove have a painful sting, but their venom also has restorative properties. I can extract what I need from their glands. With an ample amount of venom, we should be able to soothe your friend's wounds.",objectivesText="Collect 15 Sandstinger Venom Glands . Progress: Have you brought the glands? We can't heal your friend without them.",rewardGold=257400,rewardXP=4115,rewardItems={160441},starts={{npcID=123586}},ends={{npcID=123586}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51364},questLines={{id=606,name="Dangers in the Desert",orderIndex=0,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=9,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47320] = {id=47320,name="A Balm to Calm",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47316,47317,47319,47320,47321,47959,48549,48550,51574},description="As promised, here is the balm that should remedy your companion's injuries. Apply it liberally to any bits of exposed flesh. Its effects should be felt immediately.",objectivesText="Use the Restorative Balm on Bladeguard Kaja .",rewardGold=128700,rewardXP=2060,rewardItems={150759},starts={{npcID=123586}},ends={{npcID=130341}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47319,51574},questLines={{id=606,name="Dangers in the Desert",orderIndex=2,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=11,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47321] = {id=47321,name="Knickknack Takeback",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47316,47317,47319,47320,47321,47959,48549,48550,51574},description="Nisha told me you came here in search of an exile. One named Rakera? We don't know her, but we might be able to help you find her. You help us, and we help you. Deal? We survive by scavenging. We trade what we find, but the sethrak that raided our burrows made away with many of our knickknacks . I always knew they were ruthless, but never imagined they'd be so greedy. Take back what the sethrak have taken, and I'll see that you are provided safe passage through the dunes.",objectivesText="Collect 6 Knickknacks from sethrak within The Serpent's Maw. Progress: You help us, and we help you. Deal?",rewardGold=176280,rewardXP=4115,rewardItems={151273,151278},starts={{npcID=123586}},ends={{npcID=123586}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47320},questLines={{id=606,name="Dangers in the Desert",orderIndex=5,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=15,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47322] = {id=47322,name="Aided Escape",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47322},description="The sethrak may be strong, but we're quick. Well, at least Mekaru and I are. We just barely made it back to the wagon with our tails attached. The others weren't so lucky, I guess. We've been waiting a while, and still no sign of them. If you're headed into the thick of it, would you mind looking for our friends?",objectivesText="Free Hakasi and Kipp from within The Serpent's Maw. Progress: We abandoned our scavenging as soon as the sethrak showed up. Not all of us made it to safety...",rewardGold=257400,rewardXP=4115,rewardItems={155388,155389,155390,155391,155409,155410,155411,155412},rewardChoices={155388,155389,155390,155391,155409,155410,155411,155412},starts={{npcID=137631}},ends={{npcID=137631}},mapCandidates={npc={864},zone={8501}},questType="standard",startItems={151342}},
[47324] = {id=47324,name="Unlikely Allies",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="I believe this is one of the Keepers' keys! Only Vorrik would know for sure. We need to head to the temple at once. My pterrordax can take us there when you're ready, but we need to hurry.",objectivesText="Fly to the Sanctuary of the Devoted.",rewardGold=128700,rewardXP=2060,starts={{npcID=134533}},ends={{npcID=128687}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50561},questLines={{id=609,name="The Three Keepers",orderIndex=0,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=42,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47327] = {id=47327,name="Answering Their Attacks",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="The sethrak's attacks on our burrows cannot go unanswered. They need to learn that not all within the desert will give up so easily. The only thing the sethrak understand is blood, so that's the language we'll use to teach them. < Nisha pauses and looks at you, skeptical that you understood her.> I'm saying we need to kill the sethrak here. All of them.",objectivesText="Kill sethrak in the Abandoned Burrows. Progress: The sethrak will answer for what they have done.",rewardGold=257400,rewardXP=4115,starts={{npcID=130455}},ends={{npcID=130455}},mapCandidates={npc={864},zone={8501}},questTurnInID=130455,questType="standard",sourceQuests={51357},questLines={{id=605,name="Unlikely Allies",orderIndex=5,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=6,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47329] = {id=47329,name="The Bloodwatcher Legacy",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47228,47235,47329,48317,48399,48400,50043},series={47257},description="Greetings, <name>. I have been sent on behalf of my father, High Examiner Tae'thelan Bloodwatcher, to oversee the extraction of all fossils, relics, and artifacts from this area. My sources inform me that an object that could advance the Horde's cause may be buried beneath this very site. I will require your help extracting it. You see, these nightborne are not precisely good with their hands. Nor do they enjoy getting dirty. Could you be a dear and set a good example?",objectivesText="Help Examiner Tae'shara Bloodwatcher recover a Xibalan fossil. Progress: By all means, let us assist young Tae'shara. Such enthusiasm is to be rewarded.",rewardGold=128700,rewardXP=710,starts={{npcID=131582}},ends={{npcID=131580}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47257},questLines={{id=5403,name="Fossil Extraction",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47330] = {id=47330,name="Whispers of a Frightened World",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=7502,mapID=627,storyline={47330},description="Champion, Magni needs your help! The Speaker has a message for you, perhaps from Azeroth herself. He seems to be having trouble understanding her, but I'm sure he can explain everything better. He said he was in Sholazar Basin, in Northrend. He should be contacting you shortly.",objectivesText="Meet Magni in Sholazar Basin and hear the warning. Progress: Yes, <name>? What news do you bring?",rewardGold=202200,rewardXP=6140,rewardItems={151789},starts={{npcID=90417}},ends={{npcID=90417}},mapCandidates={npc={},zone={7502}},questGiverID=90417,questTurnInID=90417,questType="standard",questLines={{id=350,name="Azeroth's Warning",orderIndex=0,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=627},
[47332] = {id=47332,name="Your Next Move",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={47332,51770,51771,52746,52749,53079,53333},description="Princess Talanji plans to travel north to Nazmir. The blood trolls there are a threat she believes her father refuses to acknowledge. General Jakra'zet detests the Horde and cannot be trusted. As long as he remains in power, the city will never be safe. You will also need to win over King Rastakhan here in Zuldazar . This city is vast and has many secrets. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(47332)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(47332))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Choose your next move in Zandalar.",rewardGold=30900,rewardXP=175,mapCandidates={npc={},zone={8499}},questType="standard",questLines={{id=618,name="Mission from the Warchief",orderIndex=6,flags=0},{id=793,name="Zandalar Zone Choice",orderIndex=0,flags=0}}},
[47416] = {id=47416,name="Shadow of the Triumvirate",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={47416,47691,47853,47854,47855,47856,47995,48344,48345},description="Talgath's words carry more gravity than I think he knew. In an attempt to hurt me one final time, he has given us the answer. The Crest of Knowledge is hidden away in the Seat of the Triumvirate, and it is not unguarded. If my suspicions are correct, we may be facing a greater threat than any of us dared imagine. A dark naaru. Let us return to the Vindicaar. We will plan our next steps there.",objectivesText="Return to the Vindicaar.",rewardGold=101100,rewardXP=6140,rewardItems={152711},starts={{npcID=120533}},ends={{npcID=120533}},mapCandidates={npc={882},zone={8701}},questTurnInID=120533,questType="standard",sourceQuests={47856},questLines={{id=367,name="Across the Universe",orderIndex=8,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=367,questLineOrder=7,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2LabelIDs={4784},db2PoiMapID=1669,db2PoiUiMapID=883},
[47418] = {id=47418,name="Growing Pains",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47226,47259,47261,47272,47310,47311,47312,47418,48527,48581,51990,51998},series={47272},description="These trolls are missing a real opportunity here! They complain about not having enough beasts to go around, yet have they really tried to mass produce them? Nope! With my Direhorn Growth Hormone , they'll be able to fill these pens to overflowing! Sure, the overcrowding might lead to disease and excess waste issues, but I'm sure those are solvable. Ha ha ha this is gonna be great!",objectivesText="Feed the Direhorn Growth Hormone to your hatchling. Progress: Well? Did your hatchling try the DGH yet?",rewardGold=25740,rewardXP=175,rewardItems={147897},starts={{npcID=122129}},ends={{npcID=122129}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51990,51998},questLines={{id=5402,name="Warbeast Kraal",orderIndex=8,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47422] = {id=47422,name="Dire Situation",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8670,mapID=1165,series={47438},description="Good news, we found de source of de corruption. De bad news, it is a ritual on de apex of Zanchul. Blood magic wielding heretics are empowering some sort of dire troll up dere. How it made it all de way to de apex without us catching it is something I am sure Raal and I will be arguing about for de next year. Come, let us stop dis heresy.",rewardGold=514800,rewardXP=1770,rewardChoices={159102,159100,159099,159098,159101,159097,159104,159103},starts={{npcID=126560}},ends={{npcID=126560},{npcID=127101}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={47437},questLines={{id=338,name="The Zanchuli Council",orderIndex=5,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=24,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47423] = {id=47423,name="Forbidden Practices",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8670,mapID=1165,series={47445,47433},description="You come at a good time, $p. I have need of a weapon such as yourself. Yazma's spies say dere are blood cultists in our ranks. King Rastakhan has charged me with tracking down any trolls guilty of practicing blood magic and purging dem. Take dis totem, route out those with de stench of blood magic, and cleanse dem from dis holy place. When you are done, tell dat lazy Hexlord Raal to get off his perch and help keep dis place secure.",rewardGold=22600,rewardXP=1415,starts={{npcID=126560}},ends={{npcID=126564}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={47445},questLines={{id=338,name="The Zanchuli Council",orderIndex=0,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=19,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47428] = {id=47428,name="Kitty?",level=20,requiredLevel=20,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={44785,45079,47289,47428,53464,53465},description="You have to find our last guest before it's time for tea! Smoochums really likes the woods, I bet we'll find him there!",objectivesText="Find Smoochums in Glenbrook Woods.",rewardGold=25740,rewardXP=345,rewardItems={88704,88705,88706,88707,88708},starts={{npcID=122169}},ends={{npcID=121684}},mapCandidates={npc={896},zone={8721}},questGiverID=122169,questType="standard",sourceQuests={47289},questLines={{id=5447,name="A Tea Party",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[47430] = {id=47430,name="Moonkin Monitoring",level=1,requiredLevel=1,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=493,mapID=80,storyline={47430},description="< Makkaw motions for you to observe the other moonkin in the area.>",objectivesText="Observe the nearby dancing, moonfiring, and napping Moonkin Hatchlings and see what you can learn.",rewardGold=312800,rewardXP=200,starts={{npcID=122134}},ends={{npcID=122134}},mapCandidates={npc={80},zone={493}},questType="standard"},
[47431] = {id=47431,name="Gathering Light",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={40238,46213,47431,47508,47526,47541,47652,47653,47743,47754,47771,48559,49143},description="Alleria and I long for more time with our son, but we cannot afford to wait any longer, <name>. We must strike now. The Army of the Light is scattered, but not defeated. Any survivors should have stayed near the crash site of the Xenedar. If there is any hope of victory, we must rally them and rescue Xe'ra. With the pit lords dealt with, we should have a safer route to the Xenedar. Meet me in the krokul hovel as soon as you can.",objectivesText="Meet Turalyon in the Krokul Hovel.",rewardGold=50550,rewardXP=770,starts={{npcID=122378}},ends={{npcID=122621}},mapCandidates={npc={830},zone={8574}},questGiverID=122378,questType="standard",sourceQuests={48500},questLines={{id=348,name="The Light Mother",orderIndex=0,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=348,questLineOrder=2,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[47432] = {id=47432,name="The Bargain is Struck",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8670,mapID=1165,description="Now dat you have declared a patron loa for your time here in Zuldazar , you should inform de king of your decision. He will appreciate dat you chose to follow de great Pa'ku.",rewardGold=25740,rewardXP=175,rewardCurrencies={{id=1553,amount=125},{id=1553,amount=150}},starts={{npcID=127489}},ends={{npcID=120740}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={47440},questLines={{id=338,name="The Zanchuli Council",orderIndex=9,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=28,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47433] = {id=47433,name="Offensively Defensive",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8670,mapID=1165,series={47445,47423},description="Let me guess, Loti had you kill any trolls dat smelled of blood magic, yes? Well, dat is barely a half measure. See, blood magic comes from de old ways, and our people have only been giving in to its allure since de walls fell on our northern border. Come, we will go for a little ride and patrol de border to Nazmir. Dat is where all dese bad ideas are coming from.",rewardGold=257400,rewardXP=1415,rewardChoices={155246,155247,155248,155249,155263,155264,155265,155266},starts={{npcID=126564}},ends={{npcID=126560}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={47423},questLines={{id=338,name="The Zanchuli Council",orderIndex=1,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=20,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47434] = {id=47434,name="Restraining Order",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8670,mapID=1165,description="\"Something feels different\"? Dat was all Raal said? His flock of pterrordaxes have swarmed de courtyard of Zanchul. Dey are being driven mad. Shoo dem away before dey hurt demselves or others.",rewardGold=257400,rewardXP=1415,starts={{npcID=126560}},ends={{npcID=126564}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={47433},questLines={{id=338,name="The Zanchuli Council",orderIndex=2,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=21,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47435] = {id=47435,name="Pterrortorial Dispute",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8726,mapID=1165,description="De courtyard of Zanchul has been overrun by pterrordaxes driven mad by some dark ritual. Power is coalescing here, and it is hard to tell who or what is causing it. I need to track down de source. In de meantime, you take dis, de power of Gonk, and call his allies to help you in battle. Slay dese maddened pterrordaxes. When you are done, tell Raal to get his flock under control.",rewardGold=257400,rewardXP=1415,starts={{npcID=126560}},ends={{npcID=126564}},mapCandidates={npc={1165},zone={8726}},questType="standard",sourceQuests={47433},questLines={{id=338,name="The Zanchuli Council",orderIndex=3,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=22,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47437] = {id=47437,name="Competitive Devotion",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8726,mapID=1165,description="Okay, I know dis situation is serious, but she gave you de power of her loa? Sounds to me like Loti is more big on recruiting than on dealing with dis blood troll threat. Inside de temple behind me are three guardians. When I walked in dere, de things tried to kill me. Me! Someone has corrupted our own guardians. Here, I will lend you de voice of my own loa, Pa'ku, de pterrordax. Use it to crush dis corruption.",rewardGold=514800,rewardXP=1770,starts={{npcID=126564}},ends={{npcID=126560}},mapCandidates={npc={1165},zone={8726}},questType="standard",sourceQuests={47434,47435},questLines={{id=338,name="The Zanchuli Council",orderIndex=4,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=23,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47438] = {id=47438,name="Picking a Side",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8670,mapID=1165,series={47422},description="Look, dis has gone on long enough, $p. I am not one to hold a grudge, but I will be damned if I let you double dip with Raal's loa and my own. Time has come to pick a loa. De loa are not de sharing type.",rewardGold=257400,rewardXP=1415,starts={{npcID=126560}},ends={{npcID=126560}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={47422},questLines={{id=338,name="The Zanchuli Council",orderIndex=6,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=25,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47439] = {id=47439,name="Gonk, Lord of the Pack",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="You can find Gonk in his lair west of here, in de Garden of the Loa. You should be able to see his totems. Run near dem to improve your speed. I will continue to purge de heretics from dis temple. Mind your manners around de loa, or he may rip your throat out.",rewardGold=514800,rewardXP=1770,starts={{npcID=126560}},ends={{npcID=127576}},mapCandidates={npc={1165},zone={8499}},questType="standard",sourceQuests={47438},questLines={{id=338,name="The Zanchuli Council",orderIndex=7,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=26,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47440] = {id=47440,name="Pa'ku, Master of Winds",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="Come, ride Ata de Winglord with me, and he will take us to Pa'ku . Oh, and mind your manners around dat loa. Pa'ku has been known to drop followers she is not fond of from a really great height onto really hard stone.",rewardGold=514800,rewardXP=1770,starts={{npcID=126564}},ends={{npcID=127489}},mapCandidates={npc={1165},zone={8499}},questType="standard",sourceQuests={47438},questLines={{id=338,name="The Zanchuli Council",orderIndex=8,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=27,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47441] = {id=47441,name="Pests",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=1165,storyline={47441},series={47442},description="Let me guess, de saurid stole something of yours as well, eh? Look, I don't have de time to run down every little thing dese ankle-biters snap off with. You want some coin? Help me kill some of dese snappers. Otherwise, leave me be.",objectivesText="Slay 8 Thieving Snappers in the Zocalo.",rewardGold=257400,rewardXP=1415,starts={{npcID=127665}},ends={{npcID=126334}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[47442] = {id=47442,name="Curse of Jani",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=1165,storyline={47442},series={47441},description="Thief and killer, know dat ya be standin' before da Patron of Scavengers, da Lord of Thieves, da God of Garbage, Master of Minions, and da Keeper of Secrets. Ya be standin' before me in raiment worth entire kingdoms of gold, bearin' weapons dat cost more than even me most devout and renowned followers will ever earn. I tink now be a good time ta teach ya a lesson. Maybe show ya high and mighty greatness what it means ta be snappin' in da gutters.",objectivesText="Survive the Trial of Jani . Progress: You be bitin' that ratmon yet?",rewardGold=257400,rewardXP=1415,rewardItems={168970},rewardCurrencies={{id=1553,amount=75}},starts={{npcID=126334}},ends={{npcID=126334}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={47441}},
[47445] = {id=47445,name="The Zanchuli Council",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8670,mapID=1165,series={47423,47433},description="You there, Speaker of de Horde. My spies have told me of dark heresies being practiced in our sacred temple of Zanchul. De king sent Loti and Raal to deal with de situation, but those two bickering council members are soft on their own followers. We need someone more... ruthlessly neutral. Go meet Wardruid Loti down at de Zocalo and she can tell you de rest.",rewardGold=25740,rewardXP=175,starts={{npcID=122641}},ends={{npcID=126560}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={47514},questLines={{id=5389,name="Unrest in Zuldazar",orderIndex=18,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47456] = {id=47456,name="Calming the Void",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={47456},objectivesText="Frenzied Wurms calmed",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8574}},questType="world",db2Objectives={{text="Frenzied Wurms calmed",amount=15,type=0,objectID=122433,orderIndex=0}},worldTaskTitle="Calming the Void",db2PoiMapID=1669,db2PoiUiMapID=882,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[47473] = {id=47473,name="Sizing Up The Opposition",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8899,mapID=885,storyline={47473,48199,48200,48201,48202,48929},description="Turalyon was no doubt hoping for better news, but I fear I cannot provide it. Attempting to drive into the heart of the Legion now would cost us everything. There must be another way. I do not know what it is, but I trust that we will find it. Best not keep Turalyon waiting. We must move forward.",objectivesText="Speak with Turalyon.",rewardGold=70225,rewardXP=6140,starts={{npcID=127033}},ends={{npcID=127033}},mapCandidates={npc={885},zone={8899}},questTurnInID=127033,questType="standard",sourceQuests={48201},questLines={{id=371,name="The Heart of Argus",orderIndex=4,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=371,questLineOrder=3,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=886},
[47485] = {id=47485,name="The Ashvane Trading Company",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={47181,47485,47486,47487,47488,50531,50573,53041},series={47486,47488,47489,50531,50573,53041},description="So, Ashvane's goons are walking around with a new powder that can blow a galleon clean in half and the military has no idea. We need to find out how much of this powder they have and where it's going. An old buddy of mine works the ferry down by the Ashvane Foundry. He may know something about this. You can take the ferry from Tradewinds Market to Eastpoint Station. Once you get there, look for a man named Cagney . Tell him I sent you. He owes me a favor.",objectivesText="Speak with Cagney at Eastpoint Station. Take the ferry from Will Melborne in Tradewinds Market.",rewardGold=25740,rewardXP=175,rewardItems={158065,158066,163032,163034},starts={{npcID=122370}},ends={{npcID=122671}},mapCandidates={npc={895},zone={8568}},questGiverID=122370,questType="standard",sourceQuests={47181},questLines={{id=585,name="The Ashvane Trading Company",orderIndex=1,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=11,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[47486] = {id=47486,name="Suspicious Shipments",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={47181,47485,47486,47487,47488,50531,50573,53041},series={47485,47488,47489,50531,50573,53041},description="Normally I wouldn't tell you nothin'... but I'll spill it for Cyrus. Ashvane's onto somethin' big. They got guys workin' round the clock in there. Even brought in some muscle to keep everyone uh... \"motivated.\" I don't know anything about what they're makin', but I know it ain't passin' through here to Boralus. If I were dumb enough to go snooping around in there, I'd look at the goods themselves. See if they got shipping labels. But I ain't that dumb, so you gotta do it.",objectivesText="Inspect 5 Marked Goods in the Ashvane Foundry.",rewardGold=257400,rewardXP=1415,rewardItems={158065,158066,163032,163034},rewardCurrencies={{id=1553,amount=100}},starts={{npcID=122671}},ends={{npcID=121239}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={47485},questLines={{id=585,name="The Ashvane Trading Company",orderIndex=2,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=12,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[47487] = {id=47487,name="Labor Dispute",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={47181,47485,47486,47487,47488,50531,50573,53041},description="The Ashvane Company has been workin' their people so hard they even tried to strike! The company brought in a bunch of goons to break it up and get everyone back to work. Heard they even shot a couple guys who tried to walk off the job. What say you give 'em a taste of their own brutality while you're in there?",objectivesText="Slay 10 Company Watchmen, Company Enforcers , or Company Fusiliers .",rewardGold=257400,rewardXP=1415,rewardItems={158065,158066,163032,163034},starts={{npcID=122671}},ends={{npcID=122671}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={47485},questLines={{id=585,name="The Ashvane Trading Company",orderIndex=3,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=13,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[47488] = {id=47488,name="Small Haulers",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={47181,47485,47486,47487,47488,50531,50573,53041},series={47485,47486,47489,50531,50573,53041},description="<sniff> They said they would feed us. Said they'd keep us warm. < Olive runs the sleeve of her coat across her nose.> But they were mean! And it was really hard work. And when we tried to rest, they yelled at us! <sniff> I got away, but my friends are still in there.",objectivesText="Free 6 Urchin Workers from the Ashvane Foundry.",rewardGold=257400,rewardXP=1415,rewardItems={158065,158066,163032,163034},starts={{npcID=122672}},ends={{npcID=121239}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={47485},questLines={{id=585,name="The Ashvane Trading Company",orderIndex=4,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=14,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[47489] = {id=47489,name="Stow and Go",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={47489,48419,48505,48539,48558,48773,49239,49398,49399,49400,49401,49404},series={47485,47486,47488,50531,50573,53041},description="<Flynn lifts his collar to hide his face and speaks to you under his breath.> You see that ship? I know that ship. Let's just say her captain and I have a little history. It's a smuggling vessel. Our illegal weapons are on there for sure. I'd bet my coat on it... and I love this coat. We need to find out where it's going... How are you in tight spaces?",objectivesText="Stow away on The Maiden's Virtue.",rewardGold=257400,rewardXP=1415,rewardItems={158065,158066,163032,163034,245271,252386,252400,252403,252406,252653,252654,252754},starts={{npcID=134166}},ends={{npcID=128377}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={53041},questLines={{id=587,name="Freehold",orderIndex=0,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=18,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[47491] = {id=47491,name="Remnants of the Damned",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Ever since da spirits have begun calling upon dis \"G'huun,\" me temple has been covered with da unbearable taint of da undead. Da undead be an abomination, but da bloodstones dat create dem be powerful. Dey could be of use ta Bwonsamdi . If ya wish ta show me ya fervor, den cleanse me temple of their filth and bring me their bloodstones.",rewardGold=257400,rewardXP=2765,starts={{npcID=122688}},ends={{npcID=122688}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47880},questLines={{id=335,name="A Pact with Death",orderIndex=3,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=16,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47493] = {id=47493,name="A Lonely Spirit",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={49432},description="Da spirit of a child named Keula be wanderin' me temple grounds. Her ma'da gave her child up ta me long ago, she be thinkin' that a great sacrifice would spare her from me call, from going to da other side. Well she be right, I not claim her yet. But she be wrong too. Her child be da one to decide when ta be reunited with her ma'da, and it seem ta me dat da child be no longer be content ta wait. Dey both belong in my realm. Go, bring da child to her ma'da.",rewardGold=25740,rewardXP=345,starts={{npcID=122688}},ends={{npcID=126588}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47247,47491,49348},nextQuests={49432},questLines={{id=5390,name="Lost in Nazmir",orderIndex=87,flags=1}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47496] = {id=47496,name="Bunker Buster",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8911,mapID=830,storyline={47496},objectivesText="Vindicaar Targets marked Legion Garrison slain",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8911}},questType="world",db2Objectives={{text="Vindicaar Targets marked",amount=3,type=0,objectID=123964,orderIndex=0},{text="Legion Garrison slain",amount=8,type=0,objectID=121987,orderIndex=2}},worldTaskTitle="Bunker Buster",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[47497] = {id=47497,name="Meet the Goldtusk Gang",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47497,47498,47501,47502,47503,47564,47638,48320,48321,48322,48840,50328,51717,51718},series={48327},description="Greetings, traveler, and welcome to de Goldtusk Inn! Unless you're here to kill us... In which case, get out. Otherwise, sit down and enjoy de mess! I mean, don't mind de mess. EAT DE MESS! No, don't eat de mess. Ignore it! < Rhan'ka turns to the skull with the eyepatch and shouts furiously in Zandalari.> Ha, don't mind him. All exiles are welcome to rest at de Goldtusk Inn, de only luxury lodge in dese harsh dunes. Come, let me introduce you to de staff.",objectivesText="Meet the staff of the Goldtusk Inn. Progress: My friends are waiting... Don't be rude.",rewardGold=128700,rewardXP=2060,starts={{npcID=122723}},ends={{npcID=122723}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48327},questLines={{id=5426,name="Goldtusk Inn",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47498] = {id=47498,name="Rhan'ka's Lost Friend",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47497,47498,47501,47502,47503,47564,47638,48320,48321,48322,48840,50328,51717,51718},description="When you head up to Dead Man's Pass, be sure to say hello to Zulsan. He's my best friend, even if he doesn't want to be near me most of de time. Ha! Seriously, though, he's been up on de cliffs for days. If you find him, convince him to come back down to de inn. We need him to restock our breakfast buffet. Oh, and a completely unrelated question dat has nothing to do with you not being able to find Zulsan and my needing to replace him: How wide is ya head?",objectivesText="Find Zulsan in Dead Man's Pass. Progress: Did you find Zulsan yet?",rewardGold=283700,rewardXP=4115,rewardItems={150916},rewardCurrencies={{id=1553,amount=100}},starts={{npcID=122723},{npcID=138749}},ends={{npcID=138749}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47497},questLines={{id=5426,name="Goldtusk Inn",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47499] = {id=47499,name="The Grinning Idols",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47499,48324,48326,48327,51053,51054,51055,51056,51057,51059,51060,51061,51062},series={51057,51059},description="Before de curse, we were a loyal crew to a good captain. But de curse corrupted Pirate-King Zem'lan, made him cruel and controlling. Now, he treats us more like slaves than crewmates. Forced to fight and die for his gain, no treasure for ourselves. No speakin' up without punishment. Well, us four, we ain't gonna be his slaves no more. A few of de crew hold onto de idols dat Zem'lan used to curse us. Kill dem and take de idols. I wanna see if we can break dem. Just for fun.",objectivesText="Collect the Idol of Binding , Idol of Immortality , and Idol of Sacrifice . Progress: I'd hoped I'd never have to see those idols again.",rewardGold=514800,rewardXP=5145,rewardItems={151021,153351,153352,155456,159976},rewardChoices={155456,159976},starts={{npcID=136309}},ends={{npcID=136309},{npcID=136310}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51055,51056},questLines={{id=5427,name="Port of Zem'lan",orderIndex=8,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47501] = {id=47501,name="Dirty Work for Dirty Drinks",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47497,47498,47501,47502,47503,47564,47638,48320,48321,48322,48840,50328,51717,51718},description="Guests gotta earn their keep at de Goldtusk Inn. What say you help me clear out some scorpids at one of our off-site excursion locations? De delightful Dead Man's Pass! Normally, you'd need to purchase our Warlord Package to be allowed access, but I'll make an exception dis time. I'll even throw in our Scorpid King Package. Unlimited scorpid blood drinks all day, every day! Dere's one catch: we're out of scorpid blood. Bring some back and I'll whip up a batch of drinks for us.",objectivesText="Collect 20 Caustic Scorpid Blood from deathsnap scorpids in Dead Man's Pass. Progress: My scorpid blood drinks are famous in de Goldtusk Gang!",rewardGold=283700,rewardXP=4115,rewardItems={150923},starts={{npcID=122723},{npcID=138749}},ends={{npcID=138749}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47497},questLines={{id=5426,name="Goldtusk Inn",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47502] = {id=47502,name="The Great Cranium Caper",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47497,47498,47501,47502,47503,47564,47638,48320,48321,48322,48840,50328,51717,51718},series={47638},description="Sandfury thugs attacked de inn after you left and kidnapped de whole Goldtusk Gang! We gotta get dem back. Man'zul was usually de brains behind our thefts back in Zuldazar, but I'll try to come up with a plan to get dem outta dis mess. < Rhan'ka thinks for awhile.> I got it! You rescue 'em all!",objectivesText="Rescue the kidnapped members of the Goldtusk Gang in the Sandfury Hideout. Progress: We nothin' without our gang.",rewardGold=245700,rewardXP=4115,rewardItems={151218,151219,151220,161176,161177,161178,161179,161180},rewardChoices={161176,161177,161178,161179,161180},starts={{npcID=122723},{npcID=138749}},ends={{npcID=122723}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47498,47501},questLines={{id=5426,name="Goldtusk Inn",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47503] = {id=47503,name="Gozda'kun the Slaver",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47497,47498,47501,47502,47503,47564,47638,48320,48321,48322,48840,50328,51717,51718},description="Dat's it. De Sandfury are officially banned from de Goldtusk Inn! You can't just ransack a place, kidnap its staff, and mock its owner with an assortment of fruits and vegetables and expect to get away with it! We gotta teach those thugs what happens when you mess with de Goldtusk Gang! Gozda'kun de Slaver was bossing around de rest of de Sandfury during de attack. Take him out, and leave some Sandfury behind to spread de word.",objectivesText="Kill Gozda'kun the Slaver in the Sandfury Hideout.",rewardGold=514800,rewardXP=5145,starts={{npcID=138749}},ends={{npcID=122723}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47498,47501},questLines={{id=5426,name="Goldtusk Inn",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47506] = {id=47506,name="REUSE",level=1,requiredLevel=1,faction="alliance",categories={},flags={},sharable=true,expansion=7,storyline={47506},rewardGold=154000,rewardXP=50,rewardItems={71083,128823,133803,133804,142342,181368,181377,181585,181605,181610,181611,181703,181704,181745,184294,184362,184363,184765,184766,184767,184768,184839,184841,190456,198048,200453,204075,204743,204744,204747,204748,204750,204752,204754,204758,204759,204761,204766,204769,204774,204780,204787,204896,204898},mapCandidates={npc={},zone={}},questType="standard"},
[47507] = {id=47507,name="Khazaduum",level=45,requiredLevel=45,faction="none",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={47507},rewardGold=606600,rewardXP=9210,rewardItems={152743,153164},mapCandidates={npc={},zone={8574}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=125824}},worldTaskTitle="Khazaduum",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[47508] = {id=47508,name="Fire At Will",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={40238,46213,47431,47508,47526,47541,47652,47653,47743,47754,47771,48559,49143},series={40129,40238},description="Look out there, the wings of the bats fill the sky. We must offer what ranged support we can, but our hands are full here. It looks like the Legion has not yet destroyed all of the artillery batteries. If you can get to one, you should be able to show those flying fiends the Light.",objectivesText="Enter a Lightforged Battery and slay 30 Frenzied Plaguewings . Progress: Those bats are always a nuisance to deal with. This method will be more... efficient, I believe.",rewardGold=202200,rewardXP=6140,rewardItems={152707},starts={{npcID=121578}},ends={{npcID=121578}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={40238,46213,47541},questLines={{id=348,name="The Light Mother",orderIndex=4,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=348,questLineOrder=2,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[47509] = {id=47509,name="Terrace of the Chosen",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=9598,mapID=1165,description="This betrayal has cut deep into the heart of Zandalar. Half of the Zanchuli Council and their followers have sided with Zul and his... blood god. Lucky for us not all of Zandalar is behind this betrayal. We need to topple Zul's cultists before they can rally too many to their cause. Zanchul is the place to start. Go and see if you can muster any of the Zandalari still loyal to their king.",rewardGold=25740,rewardXP=175,starts={{npcID=141555}},ends={{npcID=141555}},mapCandidates={npc={},zone={9598}},questGiverID=141555,questTurnInID=141555,questType="standard",sourceQuests={49310},questLines={{id=5389,name="Unrest in Zuldazar",orderIndex=46,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47512] = {id=47512,name="Nazmir",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=9598,mapID=1165,description="The blood trolls within the cursed swamp Nazmir threaten to destroy all of Zuldazar . Princess Talanji wants the Horde's help in an expedition to strike at the heart of the blood trolls and end their threat to Zuldazar .",rewardGold=30900,rewardXP=345,starts={{npcID=135775}},ends={{npcID=133050},{npcID=146335}},mapCandidates={npc={1165},zone={9598}},questGiverID=135775,questType="standard",questLines={{id=5390,name="Lost in Nazmir",orderIndex=0,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47513] = {id=47513,name="Vol'dun",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8499,mapID=1165,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="General Jakra'zet detests the Horde and cannot be trusted. As long as he remains in power, the city will never be safe. We are not alone in our suspicions. Speak to Princess Talanji to follow up.",objectivesText="Speak with Princess Talanji .",rewardGold=30900,rewardXP=515,starts={{npcID=135775}},ends={{npcID=146335}},mapCandidates={npc={1165},zone={8670}},questGiverID=135775,questType="standard",sourceQuests={46931},questLines={{id=5391,name="Dunes of Vol'dun",orderIndex=0,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2AdventureMapPoiID=42,db2PoiMapID=1642,db2PoiUiMapID=862},
[47514] = {id=47514,name="Zuldazar",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=9598,mapID=1165,description="King Rastakhan is an ancient ruler who is not quick to trust new allies. We must earn his trust if we are to earn his fleet. Zuldazar is the seat of power for the Zandalar empire and a good place to start in winning over these potential allies.",rewardGold=200,rewardXP=175,starts={{npcID=135775}},ends={{npcID=133050}},mapCandidates={npc={1165},zone={9598}},questGiverID=135775,questType="standard",sourceQuests={46931},questLines={{id=5389,name="Unrest in Zuldazar",orderIndex=5,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47518] = {id=47518,name="Raal",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8726,mapID=1165,series={47521,47522},description="Crazzak is a traitor in priest's clothing who thinks if he tortures enough of us it will hurt our loa. Dey even have my husband Raal up on de apex of Zanchul. Normally I would say dey could have him, but dey are using his connection to Pa'ku to weaken de loa. Can't have dat. Let's get to de top of Zanchul and rescue my worthless husband.",rewardGold=514800,rewardXP=1770,rewardChoices={158399,158400,158401,158402,158668,158669,158670,158671},starts={{npcID=123335},{npcID=133302}},ends={{npcID=133324}},mapCandidates={npc={1165},zone={8726}},questType="standard",sourceQuests={47897,47915},questLines={{id=595,name="Web of Lies",orderIndex=2,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=49,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47520] = {id=47520,name="Walls Have Ears",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8726,mapID=1165,description="Yazma, mistress of spies. Bah! A traitor who is into creepy crawlies. She chose to side with Zul, and she uses de children of her loa, Shadra, to watch and track everything we do. We have to kill all de spiders we see, or dat traitor Yazma will know every move we make.",rewardGold=257400,rewardXP=1415,starts={{npcID=123335},{npcID=133302}},ends={{npcID=133302}},mapCandidates={npc={1165},zone={8726}},questType="standard",sourceQuests={47897,47915},questLines={{id=595,name="Web of Lies",orderIndex=3,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=50,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47521] = {id=47521,name="Midnight in the Garden of the Loa",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,series={47518,47522},description="Yazma and her henchtroll Vol'kaal have pulled most of their forces back to de Garden of de Loa. Something bad is afoot, I can feel it in my spirit. Pa'ku is in danger, along with all de loa who have followers dere. Come, let's fly dere and put an end to dese heresies.",rewardGold=25740,rewardXP=175,starts={{npcID=133324}},ends={{npcID=122760}},mapCandidates={npc={862,1165},zone={8499}},questType="standard",sourceQuests={47518,47520},questLines={{id=595,name="Web of Lies",orderIndex=4,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=51,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47522] = {id=47522,name="The Hunter",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,series={47518,47521},description="Gonk is in danger. I can hear his call. My loa has saved my life so many times, it is about time I return de favor. Come, join me at de Lair of Gonk on de west side of de Garden of the Loa, and we will save a god.",rewardGold=257400,rewardXP=1415,starts={{npcID=122760}},ends={{npcID=124827}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47521},questLines={{id=595,name="Web of Lies",orderIndex=5,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=52,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47523] = {id=47523,name="Disturbance Detected: Black Temple",level=30,requiredLevel=30,faction="both",categories={},flags={"weekly","repeatable"},sharable=true,expansion=7,zoneID=3959,mapID=111,storyline={47523},description="<name>, right on time, as always. Good news first, because they're happening at the same time for me anyway. Thanks to the various timewarped objects past and future you discovered, we've figured out how to detect when a new one turns up. The bad news is, we know our technique works because something has changed in the Black Temple , and it's wreaking havoc across the timescape! We need you to ensure the fateful raid turns out exactly like it did before, and to remove the source of this disturbance.",objectivesText="Relive the assault on the Black Temple . Progress: Be extra careful the raid on the temple turns out exactly like it did before. One extra flap of dragonfly wings, and you might end up killing Illidan for real! Then imagine the mess we'd be in!",rewardGold=341600,rewardXP=4115,rewardItems={32458,97554,97555,122110,122112,133543,150436,150442,150490,150496,150504,150507,150512,150527,150531,150571,150774,171897,171914,208091,224547},rewardCurrencies={{id=1166,amount=300},{id=1166,amount=500}},starts={{npcID=123252}},ends={{npcID=123252}},mapCandidates={npc={111},zone={3959}},questType="standard"},
[47525] = {id=47525,name="Staying Hidden",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47659},description="Dere be trouble brewin', mon. Da blood trolls be on da move! Dey set up a large camp nearby and have been sending a small force to da isle south of here. If dey discover our position while we be havin' no defenses, it gonna be game over! We need ta see what dey be up to and get rid of dem. Our best bet be ta investigate da isle south a here. Ya want ta join me? I be ready ta head out.",rewardGold=25740,rewardXP=345,starts={{npcID=122991}},ends={{npcID=124376}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49902},questLines={{id=522,name="The Lord of Frogs",orderIndex=0,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=54,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47526] = {id=47526,name="Bringing the Big Guns",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={40238,46213,47431,47508,47526,47541,47652,47653,47743,47754,47771,48559,49143},series={46213,47771},description="Light's Judgment has a security feature to prevent it from falling into enemy hands. We can trigger its recall mechanism, which will teleport it back to a vessel. With the Xenedar out of commission, the gun should recall to your ship instead. You can make good use of its firepower. The process takes time, though, and will likely attract the Legion's attention. Be on your guard.",objectivesText="Locate and secure Light's Judgment .",rewardGold=202200,rewardXP=6140,starts={{npcID=121517}},ends={{npcID=121517}},mapCandidates={npc={830},zone={8574}},questTurnInID=121517,questType="standard",sourceQuests={47771},questLines={{id=348,name="The Light Mother",orderIndex=6,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=348,questLineOrder=2,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[47527] = {id=47527,name="Rituals of Heresy",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={47527},objectivesText="Disrupt the blood rituals Voodoo Pile smashed",rewardGold=455280,rewardXP=1415,mapCandidates={npc={},zone={8499}},questType="standard",db2Objectives={{text="Disrupt the blood rituals",amount=1,type=15,objectID=0,orderIndex=0},{text="Voodoo Pile smashed",amount=10,type=2,objectID=272401,orderIndex=2}},worldTaskTitle="Rituals of Heresy",db2PoiMapID=1642,db2PoiUiMapID=862},
[47528] = {id=47528,name="Mistress of Lies",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="If you are done dealing with dese peasant loa, den perhaps you can help with my own loa: Shadra. My \"high\" priestess, Yazma , is behind all of dis. If she is having her minions slay other loa, den I can only guess she is also trying to sacrifice my own loa as well. Shadra's shrine is on de northwest side of de Garden of the Loa. You must stop her from slaying de Mistress of Spies.",rewardGold=491400,rewardXP=1770,rewardChoices={159105,159106,159107,159108,159109,159110,159111,159112},starts={{npcID=124749}},ends={{npcID=122760}},mapCandidates={npc={862},zone={8499}},questGiverID=124749,questType="standard",sourceQuests={47522,47963},questLines={{id=595,name="Web of Lies",orderIndex=7,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=53,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47529] = {id=47529,name="Supernatural Support",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={47529},description="The loa can bestow powerful boon's to their followers, aid that can be the difference between victory or defeat in our efforts here. Think carefully which of the two you would like to ask for their blessing. The loa will not give their assistance to those who are currently pledged to another loa.",objectivesText="Choose which loa you wish to obtain a blessing from.",rewardGold=20220,rewardXP=345,mapCandidates={npc={},zone={8500}},questType="standard"},
[47540] = {id=47540,name="Totemic Restoration",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47621,47622,47696},description="I am fed and my body is prepared. I can now be instilled with my power of old and for a time will be immune to their blood curses and leeching powers. Use the magic of the glowflies to channel my power from the totems into me. Soon you will see me restored. Then we will destroy the army that prepares across the river to take all that is mine by force.",rewardGold=128700,rewardXP=1385,starts={{npcID=120551}},ends={{npcID=120551}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47621,47622},questLines={{id=522,name="The Lord of Frogs",orderIndex=7,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=61,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47541] = {id=47541,name="The Best Prevention",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={40238,46213,47431,47508,47526,47541,47652,47653,47743,47754,47771,48559,49143},description="If you've brought the High Exarch back to us, you are a welcome ally indeed. More is needed of you. You see our soldiers out there, fighting against all odds? Defend them. Slay the enemy. Strong words for a priest, perhaps, but every dead man'ari is one less blade at our throats. Show them that the Light protects its chosen even as it scorches the unfaithful. When you are finished, seek out Y'mera. She will have fewer troops, and more need of your abilities.",objectivesText="Slay 20 attackers in the Shattered Fields.",rewardGold=151650,rewardXP=6140,starts={{npcID=121520}},ends={{npcID=121578}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={47431},questLines={{id=348,name="The Light Mother",orderIndex=2,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=348,questLineOrder=2,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[47542] = {id=47542,name="Siegemaster Voraan",level=45,requiredLevel=45,faction="none",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={47542},rewardGold=606600,rewardXP=9210,mapCandidates={npc={},zone={8574}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=120393}},worldTaskTitle="Siegemaster Voraan",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[47543] = {id=47543,name="The Day That Chromie Dies",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=65,mapID=115,storyline={47543,47545,47550,47904,47906},series={47545,47550},description="Oh, <name>! I was just thinking about you! Talk about being at the right time in the right place! I was just reviewing some aberrations in the timeways, when I discovered something... unexpected. Something not-so-great. I'm going to die in the near future. Bad times. I was just about to jump ahead and see if I can figure out why, how, who... but I'd feel better with |5<race> like you by my side. Care to join me?",objectivesText="Speak with Chromie , then travel to the future to find out how she dies. Progress: I'm sure I just fall into a hole or something. This wouldn't be the first time!",rewardGold=202200,rewardXP=6140,rewardItems={150938,150939,150940,150941,150943,150945,150946,151141,151166,151167,151168,151370,151692,151693,151694,151695},rewardCurrencies={{id=1166,amount=50}},starts={{npcID=27856}},ends={{npcID=27856}},mapCandidates={npc={115},zone={65}},questType="standard",questLines={{id=352,name="The Deaths of Chromie",orderIndex=0,flags=0}},db2PoiMapID=571,db2PoiUiMapID=115},
[47545] = {id=47545,name="Rewind",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=65,mapID=115,storyline={47543,47545,47550,47904,47906},series={47543,47550},description="Now we know when the attack happens, and vaguely where it's coming from. Progress! All we need to do now is to find out more details and stop that attack! Let me know when you're ready to try again.",objectivesText="Speak with Chromie again, then travel to the future and gather information from the other Wyrmrest emissaries. Progress: I sure hope we don't cause a paradox!",rewardGold=202200,rewardXP=6140,rewardItems={150938,150939,150940,150941,150943,150945,150946,151141,151166,151167,151168,151370,151692,151693,151694,151695,166846,166970,166971,204196,208390,246697},rewardCurrencies={{id=1166,amount=50}},starts={{npcID=27856}},ends={{npcID=27856}},mapCandidates={npc={115},zone={65}},questType="standard",sourceQuests={47543},questLines={{id=352,name="The Deaths of Chromie",orderIndex=1,flags=0}},db2PoiMapID=571,db2PoiUiMapID=115},
[47550] = {id=47550,name="The Many Advantages of Being a Time Dragon",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=65,mapID=115,storyline={47543,47545,47550,47904,47906},series={47543,47545},description="Well, unfortunately for... whomever is fixated on blasting me into oblivion, I am a fairly skilled master of the timeways! We have the advantage of trying that again, and again, and again, until I'm not dead anymore. We're going to need a little more than a few seconds to stop this attack. How does four hours sound?",objectivesText="Speak with Chromie a third time, then travel to the future and attempt to save her again.",rewardGold=202200,rewardXP=6140,rewardItems={150938,150939,150940,150941,150943,150945,150946,151141,151166,151167,151168,151370,151692,151693,151694,151695},rewardCurrencies={{id=1166,amount=50}},starts={{npcID=27856}},ends={{npcID=27856}},mapCandidates={npc={115},zone={65}},questTurnInID=27856,questType="standard",sourceQuests={47545},questLines={{id=352,name="The Deaths of Chromie",orderIndex=2,flags=0}},db2PoiMapID=1756,db2PoiUiMapID=897},
[47551] = {id=47551,name="Lessons of Fire and Pain",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={47551},objectivesText="Tome of Torment destroyed",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8574}},questType="world",db2Objectives={{text="Tome of Torment destroyed",amount=5,type=0,objectID=122937,orderIndex=1}},worldTaskTitle="Lessons of Fire and Pain",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[47552] = {id=47552,name="Mistress Il'thendra",level=45,requiredLevel=45,faction="none",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={47552},rewardGold=606600,rewardXP=9210,mapCandidates={npc={},zone={8899}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=122947}},worldTaskTitle="Mistress Il'thendra",db2PoiMapID=1669,db2PoiUiMapID=885,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[47554] = {id=47554,name="Intercepting the Legion's Plans",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={47104,47134,47182,47287,47554},series={47102,47104,47134,47182},description="Our scout Skara writes in the missive that she learned of a major Legion initiative. She was after two encoded orders held by Legion troops near us to get the details and this must be when she was killed. The Legion splits their messages into encoded parts so that we cannot read them. Skara also writes that her partner Brae, a codebreaker, was slain trying to reach our lines with a code book that we will need to translate the Legion's orders. It is vital you find the orders and that code book!",objectivesText="Search the battlefield for Legion troops and kill them to get their Enigmatic Legion Orders . Retrieve the Army of the Light Code Book to decipher the orders. Progress: Have you found the orders and the code book?",rewardGold=101100,rewardXP=6140,rewardItems={150993,150995},starts={{npcID=121519}},ends={{npcID=121519}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={47102},questLines={{id=355,name="The Legion Jailbreak",orderIndex=0,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=830},
[47557] = {id=47557,name="Smoldering Chronoshard",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,storyline={47557},description="This shard of crystal is hot to the touch. The void creature that carried it wasn't a wielder of flame in any noticeable way, so perhaps the chronoshard is related to fire in some other way.",objectivesText="Bring the Smoldering Chronoshard to Wyrmrest to unlock a time portal.",startObjects={{mapID=897,x=0.566,y=0.661}},endObjects={{mapID=897,x=0.566,y=0.661}},coords={mapID=897,x=0.566,y=0.661},mapCandidates={npc={},zone={}},questType="standard",sourceQuests={47645},startItems={150943}},
[47558] = {id=47558,name="Fel-Touched Chronoshard",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,storyline={47558},description="This shard of crystal is scarred with deep rivets of green, malevolent energy. Being held by a dreadlord will do that to you.",objectivesText="Bring the Fel-Touched Chronoshard to Wyrmrest to unlock a time portal.",startObjects={{mapID=897,x=0.379,y=0.311}},endObjects={{mapID=897,x=0.379,y=0.311}},coords={mapID=897,x=0.379,y=0.311},mapCandidates={npc={},zone={}},questType="standard",sourceQuests={47644},startItems={150944}},
[47559] = {id=47559,name="Gleaming Chronoshard",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,storyline={47559},description="This shard of crystal glitters with a metallic sheen. Based on Chromie 's reaction, it may be used to connect you to another time and place.",objectivesText="Bring the Gleaming Chronoshard to Wyrmrest to unlock a time portal.",startObjects={{mapID=897,x=0.639,y=0.726}},endObjects={{mapID=897,x=0.639,y=0.726}},coords={mapID=897,x=0.639,y=0.726},mapCandidates={npc={},zone={}},questType="standard",sourceQuests={47643},startItems={150945}},
[47560] = {id=47560,name="Frozen Chronoshard",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,storyline={47560},description="This shard of crystal is encased in a thin, frigid layer of permafrost. It still has that distinctive lich smell to it.",objectivesText="Bring the Frozen Chronoshard to Wyrmrest to unlock a time portal.",startObjects={{mapID=897,x=0.476,y=0.488}},endObjects={{mapID=897,x=0.476,y=0.488}},coords={mapID=897,x=0.476,y=0.488},mapCandidates={npc={},zone={}},questType="standard",sourceQuests={47642},startItems={150946}},
[47561] = {id=47561,name="Blistermaw",level=45,requiredLevel=45,faction="none",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={47561},rewardGold=929400,rewardXP=9210,rewardItems={152790,152814,152844,152903,152904,152905},mapCandidates={npc={},zone={8899}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=122958}},worldTaskTitle="Blistermaw",db2PoiMapID=1669,db2PoiUiMapID=885,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[47563] = {id=47563,name="Spirits of the Fallen",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={47563},objectivesText="Demons slain Spirit released",rewardGold=309800,rewardXP=6140,rewardItems={152995},mapCandidates={npc={},zone={8899}},questType="world",db2Objectives={{text="Demons slain",amount=12,type=0,objectID=119383,orderIndex=0},{text="Spirit released",amount=6,type=0,objectID=122974,orderIndex=1}},worldTaskTitle="Spirits of the Fallen",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[47564] = {id=47564,name="Restocking the Buffet",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47497,47498,47501,47502,47503,47564,47638,48320,48321,48322,48840,50328,51717,51718},description="Imagine for a moment, $p. You wake up in de Goldtusk Inn after a long day of drinking scorpid blood, slaughtering Sandfury, and sharing jokes with your best friend Zulsan . Ya not fully awake yet, and not feeling ya best. What do you need most at dat exact moment? An all-you-can-eat breakfast buffet, of course! I'm working on it, but I need some fruit to balance out my menu. Luckily, I've seen some in de oasis outside. Bring me some, and I'll give you lifetime access to de buffet.",objectivesText="Collect 10 Whistlebloom Juicy Fruit . Progress: Dis buffet is going to be a disaster if we don't get dat fruit!",rewardGold=245700,rewardXP=4115,rewardItems={151022},starts={{npcID=122725}},ends={{npcID=122725}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47638},questLines={{id=5426,name="Goldtusk Inn",orderIndex=10,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47566] = {id=47566,name="Gar'zoth",level=45,requiredLevel=45,faction="none",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={47566},rewardGold=606600,rewardXP=9210,mapCandidates={npc={},zone={8899}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=122999}},worldTaskTitle="Gar'zoth",db2PoiMapID=1669,db2PoiUiMapID=885,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[47570] = {id=47570,name="Hidden Motives",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47570,47571,47573,47574,47576,47577,47578,47580,47581,47928,47943,47965},description="I do not understand why the naga would bother attacking a small fishing village. Why waste their time on our simple tribe? The naga seek power and we have none. It makes no sense! They must be after something else entirely... Search Darkwood Shoal and learn of their plans. Whatever the naga are after, it must be quite powerful. Perhaps if we find it first, we can use it against them!",objectivesText="Locate the naga invasion plans . Progress: Have you uncovered their plans?",rewardGold=514800,rewardXP=5145,rewardItems={157866},rewardCurrencies={{id=1553,amount=125}},starts={{npcID=134098}},ends={{npcID=134098}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51772},questLines={{id=5429,name="Kimbul's Wrath",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47571] = {id=47571,name="The Elder's Wisdom",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47570,47571,47573,47574,47576,47577,47578,47580,47581,47928,47943,47965},description="The naga are searching for a powerful artifact called the Ring of Tides. According to the invasion plans, the ring was lost long ago in a battle with Eraka no Kimbul, the great tiger loa. The temple of Eraka no Kimbul is just to the north. If the loa was strong enough to defeat the naga before, maybe he can do it again! We must let the tribe know what we've found! Take the invasion plans to Elder Kuppaka . He is the oldest, and wisest member of our tribe. He will know what to do.",objectivesText="Deliver the Invasion Plans to Elder Kuppaka . Progress: Elder Kuppaka will know what to do.",rewardGold=25740,rewardXP=515,starts={{npcID=134098}},ends={{npcID=123063}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47570,47577,47943},questLines={{id=5429,name="Kimbul's Wrath",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47573] = {id=47573,name="Jungleweb Infestation",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47570,47571,47573,47574,47576,47577,47578,47580,47581,47928,47943,47965},description="The walls of the temple could provide us with vital protection against the naga, but the temple is overrun with jungle spiders. We'll need to clear out the infestation before the tribe can take refuge at the temple. Venture into the lower ruins and lay waste to the spiders that have nested there.",objectivesText="Slay 6 Jungleweb Crawlers and 30 Jungleweb Hatchlings .",rewardGold=257400,rewardXP=4115,starts={{npcID=134134}},ends={{npcID=134134}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47965},questLines={{id=5429,name="Kimbul's Wrath",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47574] = {id=47574,name="All Webbed Up",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47570,47571,47573,47574,47576,47577,47578,47580,47581,47928,47943,47965},description="The lower ruins of the temple are covered in thick webs and spider egg sacs. Some of our tribesman went down to the lower ruins to clear out the spiders, but they haven't come back. I fear for their safety. Please head into the lower ruins and free our brethren before it's too late.",objectivesText="Free 8 Tortaka Tribesman .",rewardGold=257400,rewardXP=4115,starts={{npcID=134134}},ends={{npcID=134134}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47965},questLines={{id=5429,name="Kimbul's Wrath",orderIndex=6,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47576] = {id=47576,name="Wrath of the Tiger",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47570,47571,47573,47574,47576,47577,47578,47580,47581,47928,47943,47965},description="The Tortaka shall have my protection. Even as we speak, an army of the naga have risen from the depths to attack my temple. How soon the naga have forgotten their previous defeat! They seek to reclaim the Ring of Tides, a powerful artifact that I took as my trophy when I killed Azshara's previous champion, Mepjila. I will send you to the battlefield as my avatar to rain destruction upon the naga. They have forgotten what happens to those who trespass against my followers. Remind them.",objectivesText="Defeat the naga invasion. Progress: Send the naga army back to the sea!",rewardGold=257400,rewardXP=4115,rewardItems={161183,161184,161185,161186,161187},rewardChoices={161183,161184,161185,161186,161187},starts={{npcID=123052}},ends={{npcID=123052}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47580},questLines={{id=5429,name="Kimbul's Wrath",orderIndex=10,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47577] = {id=47577,name="They Came From The Sea",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47570,47571,47573,47574,47576,47577,47578,47580,47581,47928,47943,47965},series={51772},description="You are free to rest your weary legs in our camp, but I'm afraid we have little more to offer you. Naga have driven us from our village by the sea. We can no longer fish or hunt crabs. I fear we may not survive long if we cannot take back our lagoon. But taking back the lagoon will not be enough. We must find out why the naga attacked us. What is it they are looking for? Take this ancient scroll and use it summon the spirits of the naga. They will only speak truth while under its spell.",objectivesText="Question 8 Naga Spirits.",rewardGold=257400,rewardXP=4115,rewardItems={121427,121428,121429,121430,132903,132904,132905,132906,160585},starts={{npcID=134098}},ends={{npcID=134098}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51772},questLines={{id=5429,name="Kimbul's Wrath",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47578] = {id=47578,name="Mark of the Loa",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47570,47571,47573,47574,47576,47577,47578,47580,47581,47928,47943,47965},description="You have proven worthy of my blessing, <name>. This means should you choose me as your loa, you can call upon my power when needed. Commune at my shrine and make your decision. Know that whatever you choose, you will always be welcome within these walls.",objectivesText="Commune at Kimbul 's Shrine. Progress: I bestow my blessing upon my followers.",rewardGold=128700,rewardXP=2060,starts={{npcID=123052}},ends={{npcID=123052}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47576},questLines={{id=5429,name="Kimbul's Wrath",orderIndex=11,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47580] = {id=47580,name="The Curse of Mepjila",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47570,47571,47573,47574,47576,47577,47578,47580,47581,47928,47943,47965},description="Centuries ago, the sea witch Mepjila attacked my temple with an army of naga invaders. My followers fought bravely, but I arrived too late to save them. I defeated the naga army with ease. But as I closed my jaws around Mepjila, she placed a curse upon the spirits of my followers, locking them in an eternal battle they can never win. This mask will give you the power to enter the spirit realm and end their nightmare. Defeat the spirit of Mepjila and the curse will be broken.",objectivesText="Defeat the spirit of Mepjila. Progress: You must break the curse and free the captive souls of my followers.",rewardGold=514800,rewardXP=5145,rewardItems={151826},starts={{npcID=123052}},ends={{npcID=123052}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47928},questLines={{id=5429,name="Kimbul's Wrath",orderIndex=9,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47581] = {id=47581,name="Blessing of Kimbul",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47570,47571,47573,47574,47576,47577,47578,47580,47581,47928,47943,47965},description="The entrance to the temple is sealed by a magical barrier. According to my scrolls, the barrier can only be lowered by one who has gained the Ring of Tides . There is a statue somewhere in the temple grounds with the power to bestow the ring, but the ruins are overrun with jungle spiders. Tulu and I are not strong enough to explore the lower ruins ourselves. If you can gain the Ring of Tides and enter the temple, we may finally be able to face the naga head on!",objectivesText="Acquire the Ring of Tides . Progress: The statue is somewhere within the temple ruins.",rewardGold=257400,rewardXP=4115,rewardItems={155450,160657},rewardChoices={155450},starts={{npcID=134133}},ends={{npcID=134133}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47965},questLines={{id=5429,name="Kimbul's Wrath",orderIndex=7,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47583] = {id=47583,name="Die, Die, Diemetradon",level=10,requiredLevel=10,faction="both",categories={},flags={"loremaster"},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47583,47584,47585,47586,47587,47588},description="We are competing, you and I and these other savages. I find this... amusing. South of here you will find a number of diemetradons. I challenge you, <class>, to slay more of these creatures than I. Do you accept my wager?",objectivesText="Slay 8 Venomous Diemetradons .",rewardGold=257400,rewardXP=1415,starts={{npcID=123022}},ends={{npcID=123022}},mapCandidates={npc={862},zone={8499}},questTurnInID=123022,questType="standard",sourceQuests={49768},questLines={{id=5411,name="Hunting with Nesingwary",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47584] = {id=47584,name="A Thorn in the Side",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47583,47584,47585,47586,47587,47588},description="You fools speak of \"big game\" hunting like it is a thing of wonder. Bah! None know big game hunting like my kin. Mastery of the hunt, passed down from parent to child, for generations. I am here to prove it. I wager that you could not slay more than eleven of the ankylodon beasts that wander this region.",objectivesText="Slay 12 Ankylodons in the Preserve.",rewardGold=257400,rewardXP=1415,starts={{npcID=123026}},ends={{npcID=123026}},mapCandidates={npc={862},zone={8499}},questTurnInID=123026,questType="standard",sourceQuests={49768},questLines={{id=5411,name="Hunting with Nesingwary",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47585] = {id=47585,name="Predatory",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47583,47584,47585,47586,47587,47588},description="<There is a wound in his back, possibly from a knife. It seems more than the wildlife is fighting back out here.>",objectivesText="Find 2 more hunters in the Preserves. Progress: You found some dead ones? Did you bring back de loot?",rewardGold=257400,rewardXP=1415,starts={{npcID=123118}},ends={{npcID=123019}},mapCandidates={npc={862},zone={8499}},questType="standard",questLines={{id=5411,name="Hunting with Nesingwary",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47586] = {id=47586,name="Hunting the Hunter",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47583,47584,47585,47586,47587,47588},series={49768,50466},description="Your hunter king, Nesingwary, is a mighty fine bit of prey here. I even thought of hunting him myself. But someone else is on his trail now. And dat hunter, he is a dangerous one. If you wish to save your hunter king, you best start tracking quickly. If he made camp, you may be too late already. You cannot paint a target and wonder why you were shot! I believe he was last seen heading west...",objectivesText="Track down Hemet Nesingwary .",rewardGold=257400,rewardXP=1415,rewardItems={246492},starts={{npcID=123019}},ends={{npcID=138669}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47583,47584,47585,50466},questLines={{id=5411,name="Hunting with Nesingwary",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[47587] = {id=47587,name="Headhunter Jo",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47583,47584,47585,47586,47587,47588},description="He said he's hunting you. I'm not the prey, I'm the bait! Behind ye!",objectivesText="Slay Headhunter Jo . Progress: He's a sly one!",rewardGold=514800,rewardXP=1770,rewardItems={159114,159115,159116,159117,159118,159119,159120,159121,159122},rewardChoices={159114,159115,159116,159117,159118,159119,159120,159121,159122},starts={{npcID=138669}},ends={{npcID=138669}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47586},questLines={{id=5411,name="Hunting with Nesingwary",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[47588] = {id=47588,name="King of the Hunt",level=10,requiredLevel=10,faction="none",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47583,47584,47585,47586,47587,47588},rewardGold=309800,rewardXP=6140,rewardItems={246727},mapCandidates={npc={},zone={8499}},questType="standard",questLines={{id=5411,name="Hunting with Nesingwary",orderIndex=5,flags=0}}},
[47589] = {id=47589,name="Righteous Fury",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={46297,46732,46816,46839,46840,46841,46842,46843,46938,47589,47627,47641,48483,48500},series={46938},description="The devastators bombarding our forces prevent us from advancing any further. I can only protect us from their blasts for so long. Champion, you must pierce their lines and remove the barriers protecting the devastators. If you can destroy the anchors that maintain the shields, I can cleanse them from afar.",objectivesText="Destroy 3 Legion Devastators. Progress: Unless the anchors are destroyed, the devastators cannot be touched.",rewardGold=151650,rewardXP=6140,starts={{npcID=119543}},ends={{npcID=123149}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={46938},questLines={{id=345,name="Assault on Argus",orderIndex=2,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=345,questLineOrder=1,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[47591] = {id=47591,name="Wanna Buy a Lamp?",level=10,requiredLevel=10,faction="both",requiredClasses={4},categories={},flags={},sharable=true,expansion=7,zoneID=7502,storyline={47591},description="Ey dere, wanna buy a lamp? You be not regrettin' it.",objectivesText="Purchase the Dubious Lamp from Griftah . Progress: I promise ya don' regret dis.",rewardItems={113575,120857,138954,151131,151143,151144,151146,151165,151180,151569,151633,151749,151877},starts={{npcID=103792,mapID=626,x=0.4554,y=0.2759}},ends={{npcID=103792}},mapCandidates={npc={},zone={7502}},questGiverID=103792,questTurnInID=103792,questType="standard"},
[47592] = {id=47592,name="Shine Bright Like a Diamond",level=10,requiredLevel=10,faction="both",requiredClasses={4},categories={},flags={},sharable=true,expansion=7,zoneID=7502,storyline={47592},description="Oh, I be sorry. Dat lamp look like it could use some shinin'. I happen to have just da ting.",objectivesText="Purchase a Certified Organic Lamp Shining Kit from Griftah and use it to shine the Grimy Lamp. Progress: I'm sure dis will all be worth it.",rewardItems={151181},starts={{npcID=103792}},ends={{npcID=103792}},mapCandidates={npc={},zone={7502}},questGiverID=103792,questTurnInID=103792,questType="standard",sourceQuests={47591}},
[47594] = {id=47594,name="I'll Take Those, Thanks!",level=10,requiredLevel=10,faction="both",requiredClasses={4},categories={},flags={"weekly","repeatable"},sharable=true,expansion=7,zoneID=7502,storyline={47594},description="These coins, dey be vanishin' inta air ya say? Dat be soundin' perfect, as I have jus the fella ta give dem to.",objectivesText="Obtain 10,000 Coins of Air for Griftah . Progress: Oh man, I can't wait to use these. I be thankin' you.",rewardGold=16176000,rewardItems={151163},starts={{npcID=103792}},ends={{npcID=103792}},mapCandidates={npc={},zone={7502}},questGiverID=103792,questTurnInID=103792,questType="standard",sourceQuests={47605}},
[47595] = {id=47595,name="I Don't Need Them, But I'll Take Them",level=10,requiredLevel=10,faction="both",requiredClasses={4},categories={},flags={},sharable=true,expansion=7,zoneID=7502,storyline={47595},description="If you wanna collect more, Griftah not gonna argue with dat. Dat bein' said, I don't need dem as much anymore, so I be givin' you less for dem.",objectivesText="Collect 10,000 Coins of Air for Griftah . Progress: Another batch, huh? You be really enthusiastic about dese.",rewardGold=656493,starts={{npcID=103792}},ends={{npcID=103792}},mapCandidates={npc={},zone={7502}},questGiverID=103792,questTurnInID=103792,questType="standard",sourceQuests={47594}},
[47596] = {id=47596,name="There Is No Plan \"B\"",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47599},description="Look, I'll be honest with you. Our mech, the A.M.O.D., was the best we've ever made. It was mobile. It was powerful. It was one of a kind! What I'm trying to say is, without it, our whole plan is ruined! We have to salvage and rebuild it! That big oaf of a sea giant broke the A.M.O.D. apart and scattered its pieces all over the shore. Find its parts and I'll try to hammer them back together.",rewardGold=257400,rewardXP=2765,starts={{npcID=123548}},ends={{npcID=123548}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47597,47599},questLines={{id=354,name="An Explosive Delivery",orderIndex=4,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=49,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47597] = {id=47597,name="No Goblin Left Behind",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47245,47631},description="Our mission is dead in the water unless we move fast! I've found the perfect spot for a new base. While I secure the location, I need you to rescue the team and bring them back. We've trained for this a million times. Just direct them toward the rendezvous point and they'll find the way. We don't have much time, let's go!",rewardGold=257400,rewardXP=2765,starts={{npcID=123178}},ends={{npcID=123544}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47631},questLines={{id=354,name="An Explosive Delivery",orderIndex=2,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=47,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47598] = {id=47598,name="Pilfering and Fencing",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Our ships are sunk. Our A.M.O.D.'s gone. We've lost a LOT on this mission... and the Bilgewater Cartel don't offer insurance. The debt collectors will be all over us! We gotta make up for these losses. The beach is swarmin' with naga tryin' to collect artifacts from the ruins. How 'bout we grab some of that treasure and make back our money? I'm sure we could find a buyer willing to take 'em off our hands. We'll split the proceeds 80/20. Sounds fair to me.",rewardGold=257400,rewardXP=2765,starts={{npcID=123545}},ends={{npcID=123545}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47597,47599},questLines={{id=354,name="An Explosive Delivery",orderIndex=6,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=51,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47599] = {id=47599,name="Revenge: Served Hot",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47596},description="Look, the boss might be keeping a level head here, but we should show these naga what happens when you mess with the Gob Squad. Don't you agree? The naga are sending their behemoths to destroy what's left of our ship. Why don't you take my rocket launcher and make an example out of them. That'll send the message loud and clear!",rewardGold=257400,rewardXP=2765,rewardChoices={159077,159000,159001,159002,159003},starts={{npcID=123436},{npcID=123526}},ends={{npcID=123548}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47631},questLines={{id=354,name="An Explosive Delivery",orderIndex=3,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=48,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47601] = {id=47601,name="Field Evaluation",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47711,47602},description="We got the A.M.O.D. back together. It's a fine piece of equipment, but we're gonna have to give it a tune up. We don't want to end up digging shrapnel out of our rears. Lucky for us, there are a few naga camps remaining along with the giant that broke the gun in the first place. They'll be great for target practice. We'll deploy the A.M.O.D. just outside the building here. After we deploy, go man it. I'll have you fire a few rounds while I tune its gun. Everything'll be fine... unless it isn't.",rewardGold=514800,rewardXP=3455,rewardChoices={155382,158991,158992,158993,158994},starts={{npcID=123544}},ends={{npcID=123878}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47596,47598,47711},questLines={{id=354,name="An Explosive Delivery",orderIndex=7,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=52,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47602] = {id=47602,name="Ready For Action",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47711,47601},description="It's gonna take a bit to get the gun chassis set up. Who knew lifting big equipment could be so hard? In the meantime, why don't you go check back with your friends. Make sure everything's ready on their end. I'd hate to drive this gun into ANOTHER ambush because they're not ready.",rewardGold=23870,rewardXP=345,starts={{npcID=123878}},ends={{npcID=126213}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47601},questLines={{id=354,name="An Explosive Delivery",orderIndex=8,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=53,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47603] = {id=47603,name="The Mysterious, Magnificent Al'Abas",level=10,requiredLevel=10,faction="both",requiredClasses={4},categories={},flags={},sharable=true,expansion=7,zoneID=7502,storyline={47603},description="I see you, puny mortal! I appreciate your concern for my lamp!",objectivesText="Speak to Al'Abas . Progress: The very world trembles, trembles with the weight of magic. Their pockets are full of it.",rewardItems={151197},starts={{npcID=123087}},ends={{npcID=123087}},mapCandidates={npc={},zone={7502}},questGiverID=123087,questTurnInID=123087,questType="standard",sourceQuests={47592}},
[47604] = {id=47604,name="In the Land of Magic",level=10,requiredLevel=10,faction="both",requiredClasses={4},categories={},flags={},sharable=true,expansion=7,zoneID=7502,storyline={47604},description="I think I see the problem. Your puny eyes are too weak to detect the mana-infused finery that these elves have spread throughout the land. They've been wearing jewelry the entire time, and you simply couldn't see it. I propose a partnership, my newly minted associate. My lamp currently suffers from an embarrassing lack of magic and could always use more beautiful decorations. I propose a trade. I shall pierce this sinister veil, and you shall give me the spoils of your theft.",objectivesText="Speak to Al'Abas ... again.",starts={{npcID=123087}},ends={{npcID=123087}},mapCandidates={npc={},zone={7502}},questGiverID=123087,questTurnInID=123087,questType="standard",sourceQuests={47603}},
[47605] = {id=47605,name="Coins of Air",level=10,requiredLevel=10,faction="both",requiredClasses={4},categories={},flags={},sharable=true,expansion=7,zoneID=7502,storyline={47605},description="I would be much interested in these magical trinkets that reside in the pockets of the denizens of this land, and humbly offer my services in helping you acquire them, <name>. However, I sadly cannot pay you in the coin of this realm. What I can offer are ephemera - coins of purest air. They're better than nothing, though! Carry my lamp with you. Drop the treasures you steal within, and I will grant you these coins. Perhaps the former owner of my lamp would have a use for them.",objectivesText="Speak to Al'Abas yet again.",rewardItems={151131},starts={{npcID=123087},{npcID=103792}},ends={{npcID=123087}},mapCandidates={npc={},zone={7502}},questGiverID=123087,questTurnInID=123087,questType="standard",sourceQuests={47604}},
[47606] = {id=47606,name="Loyalty Is Its Own Reward",level=10,requiredLevel=10,faction="both",requiredClasses={4},categories={},flags={},sharable=true,expansion=7,zoneID=7502,storyline={47606},description="I offer you a challenge, mortal. Obtain a thousand of my coins, and I believe that I can empower my lamp and the vision within.",objectivesText="Obtain a thousand Coins of Air . Progress: My goodness, already!?",rewardItems={151131,151143,151158,151159,151160,151161,151162,151163,151165},starts={{npcID=123087},{npcID=103792}},ends={{npcID=123087}},mapCandidates={npc={},zone={7502}},questGiverID=123087,questTurnInID=123087,questType="standard",sourceQuests={47605}},
[47607] = {id=47607,name="High Fash-Djinn",level=10,requiredLevel=10,faction="both",requiredClasses={4},categories={},flags={"loremaster"},sharable=true,expansion=7,zoneID=7502,storyline={47607},description="With my newly empowered lamp, I sense further, more valuable trinkets in the pockets of these elves and demons. Fetch them for me!",objectivesText="Find rare treasures in the pockets of the denizens of the Broken Isles. Progress: Well, well, well. You continue to amuse and amaze, mortal.",rewardItems={151143,151144,151158,151159,151160,151161,151162,151163,151164},starts={{npcID=123087},{npcID=103792}},ends={{npcID=123087}},mapCandidates={npc={},zone={7502}},questGiverID=123087,questTurnInID=123087,questType="standard",sourceQuests={47606}},
[47621] = {id=47621,name="A True Loa Feast",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47622,47540,47696},description="The blood troll attacks have not stopped until now. They have weakened me significantly and I need to get my strength back. My followers used to bring me offerings of meat from the nearby lands. Go and bring back a mighty feast. My strength will return and we will stop these attacks once and for all.",rewardGold=257400,rewardXP=2765,starts={{npcID=120551}},ends={{npcID=120551}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47623},questLines={{id=522,name="The Lord of Frogs",orderIndex=5,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=59,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47622] = {id=47622,name="A Magical Glow",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47621,47540,47696},description="Long ago when the trolls began listening to the whispering darkness, I instilled portions of my power into the totems that surround my lair. I need that power now. In the swamps north of here are glowflies. Their magical essence will aid me in drawing the stored power from the totems. Collect them and return. Then you will see what I was capable of at the height of my strength.",rewardGold=257400,rewardXP=2765,rewardChoices={158972,158975},starts={{npcID=120551}},ends={{npcID=120551}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47623},questLines={{id=522,name="The Lord of Frogs",orderIndex=6,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=60,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47623] = {id=47623,name="The Last Witch Doctor of Krag'wa",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="I am Krag'wa, the once mighty. Curse the blood trolls and their dark god! They have slain my worshippers until only Zentimo remained, and now even he is gone. I want revenge on the blood trolls, but first I must honor the last of my witch doctors. As I have no others, I must request you perform the ritual. Then we can talk of revenge.",rewardGold=128700,rewardXP=1385,starts={{npcID=120551}},ends={{npcID=120551}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47659,47660},questLines={{id=522,name="The Lord of Frogs",orderIndex=4,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=58,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47624] = {id=47624,name="Bury It",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={47624},rewardGold=202200,rewardXP=6140,rewardItems={36888,36937,36938,37555,151061,264289,264290,264291,264292},mapCandidates={npc={},zone={8574}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=12,objectID=151061},{orderIndex=1,type=0,amount=1,objectID=124452}},worldTaskTitle="Bury It",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[47625] = {id=47625,name="The Ritual We Share",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={47625},objectivesText="Eredar ritualists slain",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8899}},questType="world",db2Objectives={{text="Eredar ritualists slain",amount=8,type=0,objectID=123130,orderIndex=0}},worldTaskTitle="The Ritual We Share",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[47627] = {id=47627,name="Vengeance",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={46297,46732,46816,46839,46840,46841,46842,46843,46938,47589,47627,47641,48483,48500},description="The Army of the Light will not have fallen in vain. Our forces will assault the main encampment while we destroy their siege weapon. This will be but the beginning of our vengeance.",objectivesText="Destroy the siege weapon at the Crown of Destruction. Progress: Until their weapon is no longer a threat, we are cornered here like vermin.",rewardGold=202200,rewardXP=6140,rewardItems={25919,25920,25921,41826,41829,41844,41845,41846,44408,44409,44410,44411,44412,49448,49449,49546,49562,50387,50401,50402,52253,56644,56645,62869,62870,62871,62879,62880,62881,62882,66901,66902,66903,84528,84529,84530,84531,84532,84533,84534,84535,84536,117509,117510,117511,117512,128832,131295,131667,131821,131822,141678,175446,175459,175460,175461,180901,180902,180903,180904,197110,252655,264479,264480,264481},starts={{npcID=123148}},ends={{npcID=119535},{npcID=123148}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={46297,47589,48483},questLines={{id=345,name="Assault on Argus",orderIndex=4,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=345,questLineOrder=1,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[47631] = {id=47631,name="Rendezvous with the Libation",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47245,47597},description="I be honest wit' ya, mon. I be havin' little patience for goblins and their antics. Go meet with their leader and ensure dat his crew and da weapon be ready for da assault. Zuldazar gonna be overrun by da blood trolls if we fail. Good luck, !",rewardGold=25740,rewardXP=345,starts={{npcID=131213}},ends={{npcID=123178}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47245},questLines={{id=354,name="An Explosive Delivery",orderIndex=1,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=46,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47638] = {id=47638,name="Powerful Spirits",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47497,47498,47501,47502,47503,47564,47638,48320,48321,48322,48840,50328,51717,51718},series={47502},description="You prove your worth, $p. We be willin' to initiate you into de ranks of de Goldtusk Gang, if you wanna join. De ritual drink is ready. Boiled scorpid blood spiked with bilewing honey! Don't mind de smell, it's mostly delicious. It's not terrible. It won't kill you. Usually. When you are ready to join de Goldtusk Gang, let me know. I'll unite you with de whole gang. It's time you see what we see.",objectivesText="Participate in the Goldtusk Gang initiation ritual. Progress: Embrace de spirits.",rewardGold=128700,rewardXP=2060,starts={{npcID=122723}},ends={{npcID=122723}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47502,47503,50328},questLines={{id=5426,name="Goldtusk Inn",orderIndex=8,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47641] = {id=47641,name="Signs of Resistance",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={46297,46732,46816,46839,46840,46841,46842,46843,46938,47589,47627,47641,48483,48500},description="Our forces sustained heavy losses defending the Vindicaar, <name>. We require allies. The Army of the Light was known to take in survivors of the Legion's crusade to bolster their ranks. We must do the same. I sense the presence of the Legion slaves you freed nearby. I suspect that they have carved out a resistance against their masters. I would appreciate your company, $p.",objectivesText="Search for signs of resistance.",rewardGold=50550,rewardXP=770,starts={{npcID=119543},{npcID=123149}},ends={{npcID=121345}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={47627},questLines={{id=345,name="Assault on Argus",orderIndex=5,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=345,questLineOrder=1,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[47642] = {id=47642,name="Soul Crystal",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,storyline={47642},description="Keep the Ruby Shrinewardens occupied. I shall carry out our master's attack from within the great tree itself.",objectivesText="Seek out the lich hidden within the Ruby Dragonshrine's tree.",rewardItems={150938,150939,150940,150941,150943,150945,150946,151141,151166,151167,151168,151370,151692,151693,151694,151695},mapCandidates={npc={},zone={}},questType="standard",startItems={150940}},
[47643] = {id=47643,name="The Ancients' Wisdom",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,storyline={47643},description="The three ancients left three clues: \"...the great nightmare...\" \"...by the water...\" \"...within the dragon's palm...\" Perhaps Chromie 's attacker lies in the place the ancients describe?",objectivesText="Seek out the satyr hidden in the Emerald Dragonshrine.",rewardItems={150938,150939,150940,150941,150943,150945,150946,151141,151166,151167,151168,151370,151692,151693,151694,151695},mapCandidates={npc={},zone={}},questType="standard"},
[47644] = {id=47644,name="Demonic Corestone",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,storyline={47644},description="Yes, master. It shall be done, at the exact time that you specified. The bronze dragon will see nothing. One shot from outside the Obsidian Dragonshrine is all I require.",objectivesText="Uncover the dreadlord hidden near the entrance to the Obsidian Dragonshrine's cave.",rewardItems={150938,150939,150940,150941,150943,150945,150946,151141,151166,151167,151168,151370,151692,151693,151694,151695},mapCandidates={npc={},zone={}},questType="standard",startItems={150938}},
[47645] = {id=47645,name="Voidcallers' Scroll",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,storyline={47645},description="The time is nigh. The invocation will take place above the azure shrine. The void will swallow the bronze dragon. Our master has spoken, and we obey.",objectivesText="Seek out the creature of void hidden above the Azure Dragonshrine.",rewardItems={150938,150939,150940,150941,150943,150945,150946,151141,151166,151167,151168,151370,151692,151693,151694,151695},mapCandidates={npc={},zone={}},questType="standard",startItems={150941}},
[47646] = {id=47646,name="Rope Around",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={47646},objectivesText="Panthara slain Wild Cragscaler returned",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8574}},questType="world",db2Objectives={{text="Panthara slain",amount=10,type=0,objectID=123076,orderIndex=0},{text="Wild Cragscaler returned",amount=3,type=0,objectID=123089,orderIndex=1}},worldTaskTitle="Rope Around",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[47647] = {id=47647,name="Monsters of Zem'lan",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={47647},objectivesText="Assault the Port of Zem'lan",rewardGold=455280,rewardXP=1415,mapCandidates={npc={},zone={8501}},questType="standard",sourceQuests={51054},db2Objectives={{text="Assault the Port of Zem'lan",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Monsters of Zem'lan",db2PoiMapID=1642,db2PoiUiMapID=864},
[47652] = {id=47652,name="The Light Mother",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={40238,46213,47431,47508,47526,47541,47652,47653,47743,47754,47771,48559,49143},series={47653,47743},description="We must know for sure whether the Light Mother survived, <name>. Xe'ra was weakened by sending her heart to Azeroth, but she is the prime naaru. She is the Light, and she cannot fade. Let's head into the Xenedar and look for her. Light willing, she will return to guide us once more.",objectivesText="Find Xe'ra within the Xenedar. Progress: Light Mother... you must have survived...",rewardGold=151650,rewardXP=6140,starts={{npcID=122621}},ends={{npcID=122621}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={47754},questLines={{id=348,name="The Light Mother",orderIndex=8,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=348,questLineOrder=2,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[47653] = {id=47653,name="Light's Return",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={40238,46213,47431,47508,47526,47541,47652,47653,47743,47754,47771,48559,49143},series={47652,47743},description="Xe'ra has been saved! We have won an important victory here. The Light Mother should be back on the Vindicaar. No doubt she will want to speak with you. There is so much to explain... Romuul should be able to teleport us back to the ship now. Let me know when you are ready.",objectivesText="Speak with Turalyon to return to the Vindicaar.",rewardGold=404400,rewardXP=6140,starts={{npcID=122621}},ends={{npcID=122621}},mapCandidates={npc={830},zone={8574}},questTurnInID=122621,questType="standard",sourceQuests={47652},questLines={{id=348,name="The Light Mother",orderIndex=9,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=348,questLineOrder=2,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=831},
[47654] = {id=47654,name="Seat of the Triumvirate: The Crest of Knowledge",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8910,mapID=882,storyline={40761,47100,47101,47180,47183,47184,47203,47217,47218,47219,47220,47238,47654},description="We have all that we need now, <name>. Alleria Windrunner awaits your arrival at the Seat of the Triumvirate . Do not go alone, my friend. You will need allies to recover the Crest of Knowledge ... and endure what L'ura has become. I will prepare the Vindicaar and await your return. Light be with you in that dark place.",objectivesText="Slay L'ura and retrieve the Crest of Knowledge . Progress: It is a heavy burden I have placed upon you, <name>. I have faith you will not fail.",rewardGold=404400,rewardXP=6140,rewardItems={151090},rewardCurrencies={{id=1508,amount=300}},starts={{npcID=120533}},ends={{npcID=120533}},mapCandidates={npc={882},zone={8701}},questTurnInID=120533,questType="dungeon",sourceQuests={47220},questLines={{id=368,name="Shadow of Eredath",orderIndex=12,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=368,questLineOrder=8,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2LabelIDs={4784},db2PoiMapID=1669,db2PoiUiMapID=883},
[47659] = {id=47659,name="Hunt the Hunter",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47525},description="Please, help us. De Frogmarsh is under siege! My master, de great loa, Krag'wa, is not willing to bend to de will of de blood trolls and their dark god. So now, dey are taking his power by force! Dey are slaying his children and taking his totems of power. Dey will even take Krag'wa and sacrifice him if we are not able to end dis madness! Stop dem! Slay their leader. Perhaps dat will slow dem down for a while. It will give me time to find a more permanent solution.",rewardGold=514800,rewardXP=3455,rewardChoices={155383,159038,159039,159040,159041},starts={{npcID=124376}},ends={{npcID=120551}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47525},questLines={{id=522,name="The Lord of Frogs",orderIndex=1,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=55,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47660] = {id=47660,name="Fallen Idols",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="De blood trolls seek to weaken Krag'wa and take his power. Dey steal his idols of power to crack open and feed their magic. Salvage what idols you can. Dey will be needed to make Krag'wa strong. Strong enough to fight dem off once and for all.",rewardGold=257400,rewardXP=2765,starts={{npcID=124376}},ends={{npcID=120551}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47525},questLines={{id=522,name="The Lord of Frogs",orderIndex=2,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=57,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47663] = {id=47663,name="A Timely Summons from Shattrath",level=1,requiredLevel=1,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=3703,mapID=111,storyline={47663},description="The blazing star holds a peculiar alignment this cycle, calling out across the heavens. Seek out the sage Vormu in Shattrath City , and lend her your aid.",objectivesText="Meet with Vormu in Shattrath. Progress: I foresee you will need the strength of many allies to walk this path.",rewardGold=34100,rewardXP=25,starts={{npcID=111246}},ends={{npcID=123252}},mapCandidates={npc={111},zone={7502}},questGiverID=111246,questType="standard"},
[47685] = {id=47685,name="Gatekeeper's Challenge: Cunning",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={46815,46818,46834,46941,47066,47685,47686,47687,47688,47689,47690,47882,47883,48081,48107},description="Archimonde expected greatness from his pupils. Only the most imaginative minds, the most adroit of intellects, could ever truly fathom the deepest reaches of our magic. I doubt you can relate. The path to the left will take you to a set of three statues. Use them to collect a Mark of Cunning. To preserve the integrity of this trial, I will not be able to provide hints. If you do, by some miracle, happen to succeed, I will formally recognize your... brilliance.",objectivesText="Collect a Fragment of Acuity , Wit, and Guile and combine them into a Mark of Cunning. Progress: Display the Mark of Cunning or leave me alone.",rewardGold=151650,rewardXP=6140,rewardItems={70161,116689,116690,116691,116692,129956,151126,151127,151128,194057,194058},starts={{npcID=124070}},ends={{npcID=124070}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={47883},questLines={{id=366,name="The Crown of the Triumvirate",orderIndex=11,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=366,questLineOrder=5,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47686] = {id=47686,name="Not-So-Humble Beginnings",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={46815,46818,46834,46941,47066,47685,47686,47687,47688,47689,47690,47882,47883,48081,48107},description="Now we may begin our search for the Crown of the Triumvirate. We will start with the fragment Archimonde carried: the Sigil of Awakening. To the east and north you will find all that remains of the greatest school of magic on Argus. It was there that Archimonde gained his mastery of the arcane. I can think of no other place he would stow his treasures. It will be guarded, no doubt. We will leverage the expertise of Fareeya's forces here to follow this trail.",objectivesText="Meet Archmage Y'mera at the Conservatory of the Arcane.",rewardGold=50550,rewardXP=6140,starts={{npcID=120533}},ends={{npcID=123413}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={46941},questLines={{id=366,name="The Crown of the Triumvirate",orderIndex=6,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=366,questLineOrder=5,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47687] = {id=47687,name="Gatekeeper's Challenge: Mastery",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={46815,46818,46834,46941,47066,47685,47686,47687,47688,47689,47690,47882,47883,48081,48107},description="Archimonde was an individual consumed by the pursuit of power. Only those who could match his lust would fare well under his tutelage. You will fight what remains of Archimonde's greatest pupils. These three once held such power in their own disciplines that the Conservatory remembers them now. Their echoes will try to kill you. Best all three with all your limbs intact and I will recognize your strength.",objectivesText="Defeat Grand Vizier Jarasum , Arc-Consul Velara , and High Wakener Aargon .",rewardGold=151650,rewardXP=6140,rewardItems={137246},starts={{npcID=124070}},ends={{npcID=124070}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={47883},questLines={{id=366,name="The Crown of the Triumvirate",orderIndex=12,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=366,questLineOrder=5,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47688] = {id=47688,name="Invasive Species",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={46815,46818,46834,46941,47066,47685,47686,47687,47688,47689,47690,47882,47883,48081,48107},description="We should seek out an alternate source of energy just in case I am wrong about the conduits. Luckily enough, I think I know where we can find one. The panthara native to Argus are solitary creatures, but it seems whatever magic the Wakeners possessed has drawn them here in great numbers. This is no time to be gentle with the environment--panthara devour energy to survive. Slay them and see if you cannot reclaim some of the power they have consumed.",objectivesText="Collect 30 Partially Digested Arcana . Progress: There is always room for a backup plan. Did you find what we seek?",rewardGold=151650,rewardXP=6140,rewardItems={151366},starts={{npcID=123413}},ends={{npcID=123413}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={47686},questLines={{id=366,name="The Crown of the Triumvirate",orderIndex=8,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=366,questLineOrder=5,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47689] = {id=47689,name="Gatekeeper's Challenge: Tenacity",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={46815,46818,46834,46941,47066,47685,47686,47687,47688,47689,47690,47882,47883,48081,48107},description="My master Archimonde was not known for his willingness to suffer indecision. He preferred to teach by rewarding frustration with more frustration-- punishment with more punishment. Absolute conviction was required to succeed under him. At the opposite end of the Conservatory you will find a large structure. Once inside, your goal is to overcome all the obstacles placed before you. Emerge unscathed and I will be forced to consider your will strong enough to proceed.",objectivesText="Overcome the Trial of Tenacity. Progress: Take all the time you need. Failure is an art, I hear.",rewardGold=151650,rewardXP=6140,rewardItems={152098},starts={{npcID=124070}},ends={{npcID=124070}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={47883},questLines={{id=366,name="The Crown of the Triumvirate",orderIndex=10,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=366,questLineOrder=5,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47690] = {id=47690,name="The Defiler's Legacy",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={46815,46818,46834,46941,47066,47685,47686,47687,47688,47689,47690,47882,47883,48081,48107},description="It seems you are not so easily deterred. Very well. Your deeds qualify you to seek the Sigil. To be clear, I am only permitting you to move on. This does not guarantee your success. The greatest of your challenges lies before you. You must go to the Praetorium and face Archimonde himself. Only by defeating the master of the Conservatory will you be worthy of the Sigil. Few have overcome this obstacle. I hope he does not make too much of a mess of you.",objectivesText="Defeat Archimonde and retrieve the Sigil of Awakening . Progress: Archimonde himself... what have we gotten ourselves into?",rewardGold=404400,rewardXP=6140,rewardItems={151476,152710},starts={{npcID=124070}},ends={{npcID=123413}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={47685,47687,47689},questLines={{id=366,name="The Crown of the Triumvirate",orderIndex=13,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=366,questLineOrder=5,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47691] = {id=47691,name="A Non-Prophet Organization",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={47416,47691,47853,47854,47855,47856,47995,48344,48345},description="I have complete faith that Velen is nearby. We would know if he had been captured. All the same, we must not delay. The Legion has a vested interest in finding him after all he has done to resist them. I shudder to think what they might do, given the chance. That is why I am going with you. We will find Velen and help him track down the Crest of Knowledge. We must have faith in his mission or all will be lost.",objectivesText="Locate Velen.",rewardGold=151650,rewardXP=6140,rewardItems={245422},starts={{npcID=124312}},ends={{npcID=120533}},mapCandidates={npc={882},zone={8701}},questGiverID=124312,questType="standard",sourceQuests={48344},questLines={{id=367,name="Across the Universe",orderIndex=1,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=367,questLineOrder=7,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47695] = {id=47695,name="Sound the Alarm",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={47695},description="Sirens are nothing but trouble! All they do is capture our men, never to be seen again. How is anybody supposed to get their goods to Boralus quickly with them around? Since you're already going down there... mind culling their numbers a bit?",objectivesText="Kill 8 Wailing Sirens in Fogcliff Strand.",rewardGold=257400,rewardXP=1415,mapCandidates={npc={},zone={8567}},questType="standard"},
[47696] = {id=47696,name="Krag'wa the Terrible",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47621,47622,47540},description="Your previous attack has angered the blood trolls. They now send an army to take everything. They are too late! I am Krag'wa! I will not be eaten, I do the eating! Meet me at the edge of Razorjaw River. You will bear witness to my power, and I will bear witness to yours.",rewardGold=514800,rewardXP=3455,rewardChoices={159013,159014,159015,159016,158983,158984,158985,158986},starts={{npcID=120551}},ends={{npcID=120551}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47540},questLines={{id=522,name="The Lord of Frogs",orderIndex=8,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=62,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47697] = {id=47697,name="Krag'wa's Aid",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Well done, ! Before we left, I heard dat Princess Talanji be headed ta Gloom Hollow . She should be dere by now. We better be headin' back. She would want ta hear da tale of ya success!",rewardGold=25740,rewardXP=345,starts={{npcID=124641}},ends={{npcID=126213}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47696},questLines={{id=522,name="The Lord of Frogs",orderIndex=9,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=63,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47704] = {id=47704,name="Ranishu Feeding Frenzy",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8501,mapID=864,mapCandidates={npc={},zone={8501}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=8,objectID=137208},{orderIndex=1,type=0,amount=40,objectID=137194,text="Ranishu Grub stomped"}},worldTaskTitle="Ranishu Feeding Frenzy",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[47705] = {id=47705,name="Behind Legion Lines",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={47705},objectivesText="Lightforged Scout healed",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8701}},questType="world",db2Objectives={{text="Lightforged Scout healed",amount=3,type=0,objectID=125926,orderIndex=0}},worldTaskTitle="Behind Legion Lines",db2PoiMapID=1669,db2PoiUiMapID=882,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[47706] = {id=47706,name="Hunt for King K'tal",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47706},description="Hunters! Dis challenge be for de King of de Preserves. King K'tal is a mighty predator, smart and fast. Gold and honor await de hunter who brings me de head of de King.",objectivesText="Recover the Skull of K'tal . Progress: Good hunting.",rewardGold=514800,rewardXP=1770,rewardItems={151169},ends={{npcID=123019}},startObjects={{objectID=271706,mapID=862,x=0.674,y=0.179}},coords={mapID=862,source="quest_giver",x=0.674,y=0.176},mapCandidates={npc={862},zone={8499}},questType="group"},
[47707] = {id=47707,name="Melting Down",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={47707},objectivesText="Clear the fel contamination Deactivated Spreader",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8574}},questType="world",db2Objectives={{text="Clear the fel contamination",amount=1,type=15,objectID=0,orderIndex=0},{text="Deactivated Spreader",amount=10,type=0,objectID=125251,orderIndex=4}},worldTaskTitle="Melting Down",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[47709] = {id=47709,name="The Great Gnomeregan Run",level=1,requiredLevel=1,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=6457,mapID=469,storyline={47709},description="Ready for the big race today, <name>? Every year, gnomes from near and far gather to run all the way from Gnomeregan to Booty Bay! It reminds us that no goal is too tall, even for us! Whether you run fast or slow, alone or with friends, you'll make it as long as you keep trying! So make sure to stretch, then get out there and show the world what we gnomes are made of!",objectivesText="Race to Booty Bay.",rewardGold=477360,rewardXP=250,rewardCurrencies={{id=3008,amount=10}},starts={{npcID=124280}},ends={{npcID=124257},{npcID=156018}},mapCandidates={npc={210,469},zone={6457}},questType="standard",questLines={{id=447,name="The Great Gnomeregan Run",orderIndex=0,flags=0}},db2PoiMapID=369,db2PoiUiMapID=499},
[47711] = {id=47711,name="Head of the Viper",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47601,47602},description="While I was scouting out the area, I saw a big armored naga bossing the rest of the snakes around. Call it a hunch, but I'm pretty sure he's their leader. As long as the Naga have a commander our operations here will be threatened. Take him out.",rewardGold=514800,rewardXP=3455,starts={{npcID=123544}},ends={{npcID=123544}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47597,47599},questLines={{id=354,name="An Explosive Delivery",orderIndex=5,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=50,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47712] = {id=47712,name="The Devastator",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={47712},objectivesText="Activate the Fel Devastator Face the cannon towards Kil'jaeden's Ship Fire the Fel Devastator",rewardGold=309800,rewardXP=6140,rewardItems={151188},mapCandidates={npc={},zone={8574}},questType="world",db2Objectives={{text="Activate the Fel Devastator",amount=1,type=0,objectID=125934,orderIndex=1},{text="Face the cannon towards Kil'jaeden's Ship",amount=1,type=0,objectID=125880,orderIndex=2},{text="Fire the Fel Devastator",amount=1,type=0,objectID=123569,orderIndex=3}},worldTaskTitle="The Devastator",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[47716] = {id=47716,name="Searching the Ruins",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47716,48313,48314,48315,48896,50539,50561,50770},description="Dese dunes are crawling with assassins. Nowhere is safe, but we must press on. De ruins aren't far from here. Let's continue our search on foot.",objectivesText="Find Julwaba within Zul'Ahjin.",rewardGold=128700,rewardXP=2060,starts={{npcID=129514}},ends={{npcID=134162}},mapCandidates={npc={864},zone={8501}},questGiverID=129514,questType="standard",sourceQuests={48896},questLines={{id=608,name="A City of Secrets",orderIndex=1,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=35,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47720] = {id=47720,name="Eternal Vengeance",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={47720},objectivesText="Demons slain",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8574}},questType="world",db2Objectives={{text="Demons slain",amount=12,type=0,objectID=119606,orderIndex=0}},worldTaskTitle="Eternal Vengeance",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[47724] = {id=47724,name="Besieged",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={47724},objectivesText="Southern Devastator destroyed Western Devastator destroyed Eastern Devastator destroyed Cannon A destroyed Cannon B destroyed Cannon C destroyed",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8574}},questType="world",db2Objectives={{text="Southern Devastator destroyed",amount=1,type=0,objectID=123049,orderIndex=0},{text="Western Devastator destroyed",amount=1,type=0,objectID=128719,orderIndex=1},{text="Eastern Devastator destroyed",amount=1,type=0,objectID=128720,orderIndex=2},{text="Cannon A destroyed",amount=3,type=0,objectID=123048,orderIndex=3},{text="Cannon B destroyed",amount=3,type=0,objectID=123065,orderIndex=4},{text="Cannon C destroyed",amount=3,type=0,objectID=123066,orderIndex=5}},worldTaskTitle="Besieged",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[47725] = {id=47725,name="Tomb of Sargeras: Aegwynn's Path",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8524,storyline={47725},description="As we sealed the tomb, I entrusted the final piece of Sargeras' prison to the Maiden of Vigilance. If you had it you could move freely throughout the tomb, but I know not what became of the keeper and fear the worst.",objectivesText="Collect 4 Fragment of the Guardian's Seal from the Maiden of Vigilance in the Tomb of Sargeras on Normal Difficulty. Progress: Without the power of the seal we cannot bypass my wards.",rewardGold=404400,rewardXP=7675,rewardItems={151248},starts={{npcID=119723}},mapCandidates={npc={},zone={8524}},questGiverID=119723,questType="raid"},
[47726] = {id=47726,name="Tomb of Sargeras: Aegwynn's Path",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8524,storyline={47726},description="As we sealed the tomb, I entrusted the final piece of Sargeras' prison to the Maiden of Vigilance. If you had it you could move freely throughout the tomb, but I know not what became of the keeper and fear the worst.",objectivesText="Collect 4 Fragment of the Guardian's Seal from the Maiden of Vigilance in the Tomb of Sargeras on Heroic Difficulty. Progress: Without the power of the seal we cannot bypass my wards.",rewardGold=404400,rewardXP=7675,rewardItems={151249},starts={{npcID=119723}},mapCandidates={npc={},zone={8524}},questGiverID=119723,questType="raid"},
[47727] = {id=47727,name="Tomb of Sargeras: Aegwynn's Path",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8524,storyline={47727},description="As we sealed the tomb, I entrusted the final piece of Sargeras' prison to the Maiden of Vigilance. If you had it you could move freely throughout the tomb, but I know not what became of the keeper and fear the worst.",objectivesText="Collect 4 Fragment of the Guardian's Seal from the Maiden of Vigilance in the Tomb of Sargeras on Mythic Difficulty. Progress: Without the power of the seal we cannot bypass my wards.",rewardGold=404400,rewardXP=7675,rewardItems={151250},starts={{npcID=119723}},mapCandidates={npc={},zone={8524}},questGiverID=119723,questType="raid"},
[47728] = {id=47728,name="Talestra the Vile",level=45,requiredLevel=45,faction="none",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={47728},rewardGold=606600,rewardXP=9210,mapCandidates={npc={},zone={8574}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=123689}},worldTaskTitle="Talestra the Vile",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[47733] = {id=47733,name="The Loa-Speaker's Betrayal",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="Listen, stranger. I don't have a lot of time left. I was in de village when Zolani brought de king to us. Said to keep it a secret, or else Zul would find us. Look around. Dey found us! But I know... I know it was not de prophet's doing. Our loa-speaker gave Zolani her pretty words, said she would help, then turned around and sold us out. It is Kihara's fault dat we are dying now. She brought dis upon us! Kill her... Make her pay!",rewardGold=257400,rewardXP=1415,starts={{npcID=138520}},ends={{npcID=124083}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51680},questLines={{id=349,name="Among the People",orderIndex=1,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=59,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47734] = {id=47734,name="Partners in Heresy",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="Rezan struggles against his bonds, but we cannot reach him. De mogu dat Zul called here have raised a shield dat rejects my magic. Find and kill de creatures dat stand between me and my loa. I must gather myself for de fight to come. They will know de wrath of TWO kings before dis day is done.",rewardGold=514800,rewardXP=1770,starts={{npcID=124655}},ends={{npcID=124655}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47736,47740},questLines={{id=349,name="Among the People",orderIndex=13,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=68,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47735] = {id=47735,name="Ancient Tortollan Remedies",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,series={51101,51680},description="Ah, yes, the situation is urgent. We must act quickly, but not hastily. There is a way to save Rastakhan, but it will require three very specific ingredients. Listen well, young one. The first, foam bubbling from the mouth of a crab. The older, the better. The second, the spine of a puffer fish. Venomous! The third, a brutosaur scale . Why? These are the secrets of my people, . Longevity is cultivated like the rarest of flowers... carefully, and with much practice.",rewardGold=257400,rewardXP=1415,starts={{npcID=124063}},ends={{npcID=124063}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51680},questLines={{id=349,name="Among the People",orderIndex=3,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=57,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47736] = {id=47736,name="Heads Will Roll",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="Zul's forces try to lay claim to de loa of kings's temple. You must teach dese traitors de meaning of their actions. Sweep de temple of de filth dat defiles it. Destroy those who spit in de face of de loa. Bring me their heads so I may remind others of what happens to those who betray their faith and their king. When you are finished dealing with de unworthy, come find us. Rezan's altar lies deep within de temple grounds. In Rastakhan's name, heads will roll!",rewardGold=257400,rewardXP=1415,starts={{npcID=124656}},ends={{npcID=124656}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47737},questLines={{id=349,name="Among the People",orderIndex=11,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=66,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47737] = {id=47737,name="The Temple of Rezan",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,series={47738,47742,51678,51679},description="De chronicler's words are dire. If Zul truly does wish to sacrifice Rezan... Dis will not come to pass! I will defend my loa with my life. Come, , we go to de Temple of Rezan. We must stop dis heresy at once!",rewardGold=25740,rewardXP=175,starts={{npcID=124062}},ends={{npcID=124655}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47742,51678,51679},questLines={{id=349,name="Among the People",orderIndex=10,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=65,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47738] = {id=47738,name="The Will of the Loa",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,series={47742,51678,51679,47737},description="Jol's remedy healed Rastakhan's flesh. But his spirit is still lost. Dere is only one thing stopping him now. Death. He is walking in Bwonsamdi's shadow. For most, dere would be nothing to be done. But... he is bound to another loa. A loa who gives life to his faithful. You must call on Rezan , loa of kings, and ask him to claim back Rastakhan's soul. Up de path, you will find my tent. Place dis idol and wait dere. If we are lucky, he will aid us. If not... It was nice knowing you.",rewardGold=514800,rewardXP=1770,starts={{npcID=132637}},ends={{npcID=124062}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51677},questLines={{id=349,name="Among the People",orderIndex=6,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=61,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47739] = {id=47739,name="The Scent of Vengeance",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="I know my king, and I know he is not weak willed. His spirit struggles under de weight of dis betrayal, and confusion roots his spirit too close to death for my comfort. We will need to remind him of his purpose. His anger. I have heard shouts of terror from de village below. Zul's followers torment Zeb'ahari while dey hunt for him. Slay those who would harm his people and bring me their blood. Perhaps de scent of vengeance can revive de devilsaur inside ol' Rastakhan.",rewardGold=257400,rewardXP=1415,starts={{npcID=132637}},ends={{npcID=132637}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51680},questLines={{id=349,name="Among the People",orderIndex=2,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=56,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47740] = {id=47740,name="House of the King",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="I hear Rezan's call. I will answer, but first you must help me. Our loa give us many boons, and we repay dem in worship. Offerings, sacrifices, and idols are our tools to earn favor, but dey are much more to our loa. Dey are sources of strength. Zul's dogs have begun to corrupt de great golden statues dedicated to Rezan. Even now, I can feel his power dwindling. Stop dem. Cleanse de idols to de great hunter. Teach dem to respect de house of de king.",rewardGold=257400,rewardXP=1415,starts={{npcID=124655}},ends={{npcID=124655}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47737},questLines={{id=349,name="Among the People",orderIndex=12,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=67,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47741] = {id=47741,name="To Sacrifice a Loa",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="Rezan 's power is fading. My usurpers have nearly completed their task. I have read of de horrors of Zul'Drak, and I have seen de results of dese acts. To think one of my own people would bring dis heresy here is... unimaginable. Come! We will end dis traitor who spits in de face of all loa! Di chuka Rezan !",rewardGold=514800,rewardXP=1770,rewardCurrencies={{id=1553,amount=100}},starts={{npcID=124655}},ends={{npcID=124948}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47734},questLines={{id=349,name="Among the People",orderIndex=14,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=69,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47742] = {id=47742,name="Zul's Mutiny",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=9772,mapID=862,series={47738,51678,51679,47737},description="A ship such as Rastakhan's Might does not readily sail without her crew. Dat means de Zandalari aboard have succumbed to Zul's machinations and have betrayed their king as surely as he has. Board my ship. Kill those who think to rise against their king. We will take no prisoners. De punishment for de crime of mutiny is death!",rewardGold=257400,rewardXP=1415,starts={{npcID=124062}},ends={{npcID=124062}},mapCandidates={npc={862},zone={9772}},questType="standard",sourceQuests={47738},questLines={{id=349,name="Among the People",orderIndex=9,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=64,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47743] = {id=47743,name="The Child of Light and Shadow",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=831,storyline={40238,46213,47431,47508,47526,47541,47652,47653,47743,47754,47771,48559,49143},series={47652,47653},description="It is time, <name>. Xe'ra is returned to us. We have Light's Heart. We have her Chosen One. Come, let us restore her. Let us forge a bright new path against our foes. Speak to me when you are ready to begin.",objectivesText="Speak with Turalyon to revive Xe'ra. Progress: Xe'ra...",rewardGold=606600,rewardXP=6140,starts={{npcID=122378}},ends={{npcID=122378}},mapCandidates={npc={},zone={8574}},questGiverID=122378,questTurnInID=122378,questType="standard",sourceQuests={47653},questLines={{id=348,name="The Light Mother",orderIndex=10,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=348,questLineOrder=2,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=831},
[47744] = {id=47744,name="Smoke, Meat, and Pretty Flowers",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9051,storyline={47744},series={47745},description="Back of town's on lockdown, kid. And yes, I do have a key, but you're a stranger. <Emery pats his pocket gingerly.> Listen, I'd like to help you out. You've got an honest look to you. Fetch me some venison, some pipe tobacco, and a bundle o' yellow flowers, and I might be able to make an exception.",objectivesText="Obtain some Salted Venison Jerky , Grimm's Special Pipe Blend , and a Marigold Bouquet . Progress: You're not in a hurry, are you?",rewardItems={151280,151281,151287,151493},starts={{npcID=123781}},ends={{npcID=123781}},mapCandidates={npc={},zone={9051}},questGiverID=123781,questTurnInID=123781,questType="standard"},
[47745] = {id=47745,name="Yeah, Definitely for the Kids",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9051,storyline={47745},series={47744},description="I don't know if you've ever seen Orphan Matron Meliana before, but she is a goddess come down to humble Lordaeron. Her hair, those cheekbones, and... ...and anyhow, these flowers are for the kids at the orphanage where she works. Tell Meliana that they're from me. For the kids.",objectivesText="Deliver the Marigold Bouquet to Orphan Matron Meliana . Progress: What's this?",rewardItems={151287},starts={{npcID=123781}},ends={{npcID=123781}},mapCandidates={npc={},zone={9051}},questGiverID=123781,questTurnInID=123781,questType="standard",sourceQuests={47744}},
[47746] = {id=47746,name="Holing Up",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9051,storyline={47746},series={47747,47750},description="Did... did you see that? Prince Arthas just struck that person down in cold blood! Right in the middle of the street! <Meliana regains her composure.> I need to protect the children. Please, help us, visitors. I need a gun, bandages, and some venison jerky. Children! Everybody, get into the house!",objectivesText="Obtain a Refurbished Military Rifle , Basic Cloth Bandages , and Salted Venison Jerky . Progress: The children are priority one.",rewardItems={151281,151282,151283,151493},starts={{npcID=123790}},ends={{npcID=123790}},mapCandidates={npc={},zone={9051}},questGiverID=123790,questTurnInID=123790,questType="standard",sourceQuests={47745}},
[47747] = {id=47747,name="Fight Plague with Fire",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9051,storyline={47747},series={47746,47750},description="One final request of you, stranger. I've seen what's happening outside, and I've heard about this \"plague\". I don't want to go down without a fight. I have enough rum in the back of this bar to set this whole tavern on fire, but I don't have the tools to do it safely. Fetch me a flint and some rope, and I'll give you my key to the backstreets of Stratholme.",objectivesText="Obtain a Flinty Firestarter and some Heavy Straw Rope . Progress: Mad Prince or drooling zombie - nobody's going to take this bar away from me without a fight!",rewardItems={151284,151286,151347},starts={{npcID=123781},{npcID=122344}},ends={{npcID=123781}},mapCandidates={npc={},zone={9051}},questGiverID=123781,questTurnInID=123781,questType="standard",sourceQuests={47750}},
[47748] = {id=47748,name="FLAG - Holing Up Complete",level=1,requiredLevel=1,faction="both",categories={},flags={},sharable=true,expansion=7,storyline={47748},rewardItems={151282,151283},mapCandidates={npc={},zone={}},questType="standard"},
[47749] = {id=47749,name="FLAG - Fight Plague With Fire Complete",level=1,requiredLevel=1,faction="both",categories={},flags={},sharable=true,expansion=7,storyline={47749},rewardItems={151282,151283},mapCandidates={npc={},zone={}},questType="standard"},
[47750] = {id=47750,name="For Emery",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9051,storyline={47750},series={47746,47747},description="We do have plenty of food here, however. If you're braving the streets, please deliver this venison to that big dummy at the tavern. Tell him it's from the kids.",objectivesText="Deliver the Salted Venison Jerky to Emery Neill . Progress: Say, what've you got there?",rewardItems={151281},starts={{npcID=123790}},ends={{npcID=123790}},mapCandidates={npc={},zone={9051}},questGiverID=123790,questTurnInID=123790,questType="standard",sourceQuests={47746}},
[47751] = {id=47751,name="A Winter Veil Gift",level=10,requiredLevel=10,faction="none",categories={"seasonal"},flags={},sharable=true,event="Feast of Winter Veil",expansion=7,storyline={47751},rewardItems={34426,43504,46740,67443,70938,90892,104319,116761,116762,128636,128653,139341,151349,151350,162644,172224,178528,187561,192094,209871,218311,244908},startObjects={{objectID=187236}},mapCandidates={npc={},zone={}},questType="standard"},
[47754] = {id=47754,name="Lightly Roasted",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={40238,46213,47431,47508,47526,47541,47652,47653,47743,47754,47771,48559,49143},description="Can you hear me, <name>? Good. Light's Judgment has been installed on the Vindicaar. We should be able to harness its power immediately. We can use it both to clear the rubble blocking the Xenedar as well as destroy our enemies. As with any new piece of technology, we should test it out. Thoroughly. I trust you have plenty of targets down there.",objectivesText="Use Light's Judgment to destroy the rubble blocking the entrance to the Xenedar.",rewardGold=101100,rewardXP=6140,starts={{npcID=124906}},ends={{npcID=122621}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={47526},questLines={{id=348,name="The Light Mother",orderIndex=7,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=348,questLineOrder=2,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[47755] = {id=47755,name="Captured and Enraptured",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={47755,50002,50005,50026,50059},description="You gotta help me! Me and my crew were running late on a delivery, so we decided to take a detour through this grotto ahead. Boy... that was a mistake. This place is crawling with sirens! If there's one thing my men like more than women, it's grog! Here, take some. Use it to bring them back to their senses. Might be best to rough 'em up a bit to weaken the enchantment.",objectivesText="Free 6 Enthralled Sailors in Fogcliff Strand. Progress: Were you able to free my men? Without them, I'm stranded!",rewardGold=257400,rewardXP=1415,rewardItems={151135},starts={{npcID=123415}},ends={{npcID=123415}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={50026},questLines={{id=5437,name="A Sirens Song",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[47756] = {id=47756,name="The Libation's Liberation",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={47756},objectivesText="Vilescale Naga defeated Sailors Freed",rewardGold=455280,rewardXP=1415,mapCandidates={npc={},zone={8500}},questType="standard",sourceQuests={47631},db2Objectives={{text="Vilescale Naga defeated",amount=1,type=15,objectID=0,orderIndex=0},{text="Sailors Freed",amount=20,type=0,objectID=123539,orderIndex=1}},worldTaskTitle="The Libation's Liberation",db2PoiMapID=1642,db2PoiUiMapID=863},
[47767] = {id=47767,name="Death Metal Knight",level=1,requiredLevel=1,faction="both",sharable=false,expansion=7,zoneID=7541,mapID=634,starts={{npcID=122899,mapID=407,x=0.6579,y=0.6841}},mapCandidates={npc={},zone={7541}},questType="standard"},
[47771] = {id=47771,name="Locating the Longshot",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={40238,46213,47431,47508,47526,47541,47652,47653,47743,47754,47771,48559,49143},series={46213,47526},description="We're going to need a bigger gun if we hope to free Xe'ra. One of the other bunkers crashed closer to the Xenedar. If Baraat was on it, he will have already begun surveying the area. Perhaps he's found the main cannon of the ship. If you head over that way, make sure he hasn't died, will you?",objectivesText="Find Baraat the Longshot .",rewardGold=50550,rewardXP=6140,starts={{npcID=121578}},ends={{npcID=121517}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={47508},questLines={{id=348,name="The Light Mother",orderIndex=5,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=348,questLineOrder=2,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[47772] = {id=47772,name="Sky Ablaze With Cannonfire",level=45,requiredLevel=45,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9051,storyline={47772},description="Oh! It's me! And <name>, was it? I remember this! I seem to have found myself in the middle of a battle between the Horde and the Alliance, which wouldn't USUALLY be a big deal, except for that enormous cannon that seems to be trained on me anytime I try to fly away. Think you could take it out for me?",objectivesText="Destroy the Horde Siege Cannon. Progress: Any luck? I just need the Horde cannon taken disabled if I want to escape.",rewardItems={6364,33820,118391,133755,150938,150939,150940,150941,150943,150945,150946,151141,151166,151167,151168,151368,151369,151370,151493,151692,151693,151694,151695},starts={{npcID=124154}},ends={{npcID=124154}},mapCandidates={npc={},zone={9051}},questGiverID=124154,questTurnInID=124154,questType="standard",sourceQuests={47559}},
[47773] = {id=47773,name="Sky Ablaze With Cannonfire",level=45,requiredLevel=45,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=9051,storyline={47773},description="Oh! It's me! And <name>, was it? I remember this! I seem to have found myself in the middle of a battle between the Horde and the Alliance, which wouldn't USUALLY be a big deal, except for that enormous cannon that seems to be trained on me anytime I try to fly away. Think you could take it out for me?",objectivesText="Destroy the Alliance Siege Cannon. Progress: Any luck? I just need the Alliance cannon taken disabled if I want to escape.",rewardItems={151368,151369,151370,151493},starts={{npcID=124154}},ends={{npcID=124154}},mapCandidates={npc={},zone={9051}},questGiverID=124154,questTurnInID=124154,questType="standard",sourceQuests={47559}},
[47797] = {id=47797,name="Occupation Hazard",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={47797},objectivesText="Liberate the Temple of Rezan.",rewardGold=455280,rewardXP=1415,startObjects={{mapID=862,x=0.736,y=0.263}},endObjects={{mapID=862,x=0.736,y=0.263}},coords={mapID=862,x=0.736,y=0.263},mapCandidates={npc={},zone={8499}},questType="standard",sourceQuests={47737},db2Objectives={{text="Liberate the Temple of Rezan.",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Occupation Hazard",db2PoiMapID=1642,db2PoiUiMapID=862},
[47807] = {id=47807,name="Worried About My Friends",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9051,storyline={47807},description="I've heard about some trouble over at the black dragonshrine. I know, I'm a bronze dragon, but still! I worry about them sometimes! They weren't ALWAYS so grumpy. If you're going there anyways, would you mind taking care of... whatever's causing so much of a disturbance?",objectivesText="Slay Zorathides at the Obsidian Dragonshrine. Progress: I don't know what I'd do without my aspect. Must be tough.",rewardItems={151493},starts={{npcID=122510}},ends={{npcID=122510}},mapCandidates={npc={},zone={9051}},questGiverID=122510,questTurnInID=122510,questType="standard"},
[47808] = {id=47808,name="The Dead Walk",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9051,storyline={47808},description="Greetings, <race>. I know you are here in the service of the bronze, but I have a request of you. The Ruby Dragonshrine is plagued by undead. My shrine's wardens were unprepared, and we risk losses if an intervention is not done quickly. Would you assist us?",objectivesText="Slay Talar Icechill at the Ruby Dragonshrine. Progress: Thank you for hearing my request.",rewardGold=309800,rewardXP=1415,rewardItems={35884,35885,35886,35887,151493},starts={{npcID=122511}},ends={{npcID=122511}},mapCandidates={npc={},zone={9051}},questGiverID=122511,questTurnInID=122511,questType="standard"},
[47809] = {id=47809,name="Darkness in the Ley",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9051,storyline={47809},description="A strange, dark disturbance perturbs the ley lines in my flight's dragonshrine. Do you have the time to investigate?",objectivesText="Slay the Void Gargantuan at the Azure Dragonshrine. Progress: < Kalecgos eyes you cautiously.>",rewardItems={151493},starts={{npcID=122514}},ends={{npcID=122514}},mapCandidates={npc={},zone={9051}},questGiverID=122514,questTurnInID=122514,questType="standard"},
[47810] = {id=47810,name="Darkened Dreams",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9051,storyline={47810},description="The ancients at the Emerald Dragonshrine suffer in their dreams. With Ysera gone, I am shorthanded and unable to investigate the matter myself. Would you help me cleanse the nightmare from the Emerald Dragonshrine?",objectivesText="Slay Thalas Vylethorn at the Emerald Dragonshrine. Progress: I appreciate you taking the time to listen to my concern, <race>.",rewardItems={151493},starts={{npcID=122513}},ends={{npcID=122513}},mapCandidates={npc={},zone={9051}},questGiverID=122513,questTurnInID=122513,questType="standard"},
[47828] = {id=47828,name="Memories of the Fallen",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={47828},rewardGold=202200,rewardXP=6140,rewardItems={151555},mapCandidates={npc={},zone={8701}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=30,objectID=151555}},worldTaskTitle="Memories of the Fallen",db2PoiMapID=1669,db2PoiUiMapID=882,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
