[47833] = {id=47833,name="Shadowcaster Voruun",level=45,requiredLevel=45,faction="none",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={47833},rewardGold=606600,rewardXP=9210,mapCandidates={npc={},zone={8701}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=122838}},worldTaskTitle="Shadowcaster Voruun",db2PoiMapID=1669,db2PoiUiMapID=882,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[47835] = {id=47835,name="The Hand of Fate",level=45,requiredLevel=45,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8574,mapID=1,storyline={47223,47224,47835,47867,48440,48507},series={47221,47222,47223,47224,47867,48506,48507},description="$p, We have won many battles against the Burning Legion, but it is time to end this war once and for all. Final preparations have begun to depart for Argus. Make haste to Bladefist Bay. A ship awaits you there to grant you and your allies passage to Azuremyst.",objectivesText="Meet your escort to the Exodar at Bladefist Bay.",rewardGold=20220,rewardXP=770,ends={{npcID=122065}},coords={mapID=1,source="quest_giver",x=0.582,y=0.12},mapCandidates={npc={1},zone={14}},questType="standard",questLines={{id=346,name="To Argus!",orderIndex=4,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=346,questLineOrder=0,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2DetailThemeID=3,db2PoiMapID=1,db2PoiUiMapID=1},
[47844] = {id=47844,name="Recurring Madness",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={47844},objectivesText="Talk to Grand Lector Enaara Void Manifestations cleansed",rewardGold=202200,rewardXP=6140,rewardItems={151570},mapCandidates={npc={},zone={8701}},questType="world",db2Objectives={{text="Talk to Grand Lector Enaara",amount=1,type=0,objectID=123667,orderIndex=0},{text="Void Manifestations cleansed",amount=5,type=0,objectID=124398,orderIndex=1}},worldTaskTitle="Recurring Madness",db2PoiMapID=1669,db2PoiUiMapID=882,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[47851] = {id=47851,name="Sealing Fate: Marks of Honor",level=45,requiredLevel=45,faction="both",categories={},flags={"weekly","repeatable"},sharable=false,expansion=7,zoneID=7502,storyline={47851},objectivesText="Progress: These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Killing others isn't honorable, and yet you collect marks for honor? I suppose I can use those marks for an additional treasure. That is the offer I present. Remember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.",rewardItems={137642},rewardCurrencies={{id=1273,amount=1}},starts={{npcID=111243}},ends={{npcID=111243}},mapCandidates={npc={},zone={7502}},questGiverID=111243,questTurnInID=111243,questType="standard"},
[47853] = {id=47853,name="Flanking Maneuvers",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={47416,47691,47853,47854,47855,47856,47995,48344,48345},description="I will take command of Fareeya's lieutenants and we will escort Velen to the Crest of Knowledge. His mission must not fail. We face an old foe-- one the Army of the Light has encountered on numerous occasions. Talgath will try to block us in and prevent our retreat. You must not let that happen. Find out how he is bringing in his forces and cut them off. All we need is time to get in and get out. We are counting on you.",objectivesText="Close 3 Legion Portals .",rewardGold=202200,rewardXP=6140,starts={{npcID=124312}},ends={{npcID=120533}},mapCandidates={npc={882},zone={8701}},questGiverID=124312,questType="standard",sourceQuests={47691,47854,47995},questLines={{id=367,name="Across the Universe",orderIndex=4,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=367,questLineOrder=7,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47854] = {id=47854,name="Wrath of the High Exarch",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={47416,47691,47853,47854,47855,47856,47995,48344,48345},description="Where the Legion is concerned, violence is always the answer. <Turalyon hefts his blade with a grim expression.> They are between us and Velen. Nothing will stop them from finding him unless we act. Now is not the time to hold back. Together we will sow chaos among their ranks.",objectivesText="Disrupt the Legion forces in Arinor Gardens.",rewardGold=151650,rewardXP=6140,starts={{npcID=124312}},ends={{npcID=124312}},mapCandidates={npc={},zone={8701}},questGiverID=124312,questTurnInID=124312,questType="standard",sourceQuests={48344},questLines={{id=367,name="Across the Universe",orderIndex=2,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=367,questLineOrder=7,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47855] = {id=47855,name="What Might Have Been",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={47416,47691,47853,47854,47855,47856,47995,48344,48345},description="<Velen continues to stare at the statue as he speaks.> Thousands of years ago, when I was young, I made a choice. A choice that allowed my world to fall to ruin. A choice that made my people exiles. A choice that forever separated me from my beloved brothers. <Velen shakes his head.> I cannot leave, not yet. Not until I have had a chance to reflect.",objectivesText="Witness Velen's memory. Progress: Memory roots me in place, more surely than the heaviest stone.",rewardGold=101100,rewardXP=6140,starts={{npcID=120533}},ends={{npcID=120533}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={47853,48345},questLines={{id=367,name="Across the Universe",orderIndex=6,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=367,questLineOrder=7,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47856] = {id=47856,name="Across the Universe",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={47416,47691,47853,47854,47855,47856,47995,48344,48345},description="Talgath . There was a time I called him an ally, a friend. I put my trust in him when it came time to leave Argus. I asked him to call out to the others who would join me. I gave him all that he needed to betray me and slaughter my followers. I do not know what brought this hatred to lurk in his heart, but his machinations repeatedly forced my people to flee world after world. He made it his mission to hunt us across the universe. This must end, <name>. Talgath must die.",objectivesText="Defeat Talgath .",rewardGold=404400,rewardXP=6140,starts={{npcID=120533}},ends={{npcID=120533}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={47855},questLines={{id=367,name="Across the Universe",orderIndex=7,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=367,questLineOrder=7,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47857] = {id=47857,name="REUSE ME",level=1,requiredLevel=1,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={47857},description="Hey you've finished part 1 of the Velen arc. Stop here. Nothing past this point is done.",objectivesText="Stop here. Do not pass go. Do not collect 200 dollars.",rewardGold=194000,rewardXP=200,rewardItems={71083,128823,133803,133804,142342,181368,181377,181585,181605,181610,181611,181703,181704,181745,184294,184362,184363,184765,184766,184767,184768,184839,184841,190456,198048,200453,204075,204743,204744,204747,204748,204750,204752,204754,204758,204759,204761,204766,204769,204774,204780,204787,204896,204898},mapCandidates={npc={},zone={8701}},questType="standard"},
[47858] = {id=47858,name="Security: Engaged",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={47858},objectivesText="Household Vigilant activated",rewardGold=202200,rewardXP=6140,rewardItems={152357},mapCandidates={npc={},zone={8701}},questType="world",db2Objectives={{text="Household Vigilant activated",amount=3,type=0,objectID=125842,orderIndex=0}},worldTaskTitle="Security: Engaged",db2PoiMapID=1669,db2PoiUiMapID=882,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[47864] = {id=47864,name="Sealing Fate: Additional Marks of Honor",level=45,requiredLevel=45,faction="both",categories={},flags={"weekly","repeatable"},sharable=false,expansion=7,zoneID=7502,storyline={47864},objectivesText="Progress: These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Killing others isn't honorable, and yet you collect marks for honor? I suppose I can use those marks for an additional treasure. That is the offer I present. Remember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.",rewardItems={137642},rewardCurrencies={{id=1273,amount=1}},starts={{npcID=111243}},ends={{npcID=111243}},mapCandidates={npc={},zone={7502}},questGiverID=111243,questTurnInID=111243,questType="standard"},
[47865] = {id=47865,name="Sealing Fate: Piles of Marks of Honor",level=45,requiredLevel=45,faction="both",categories={},flags={"weekly","repeatable"},sharable=false,expansion=7,zoneID=7502,storyline={47865},objectivesText="Progress: These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Killing others isn't honorable, and yet you collect marks for honor? I suppose I can use those marks for an additional treasure. That is the offer I present. Remember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.",rewardItems={137642},rewardCurrencies={{id=1273,amount=1}},starts={{npcID=111243}},ends={{npcID=111243}},mapCandidates={npc={},zone={7502}},questGiverID=111243,questTurnInID=111243,questType="standard"},
[47867] = {id=47867,name="Two If By Sea",level=45,requiredLevel=45,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=14,mapID=1,storyline={47223,47224,47835,47867,48440,48507},series={47221,47222,47223,47224,47835,48506,48507},description="The draenei have crafted a vessel to take us to Argus safely. They are gathering the invasion force on Azuremyst Isle as we speak. We will join them there by sea. The Legion is no doubt keeping a close eye on the gateway to their world. We must retain the element of surprise. Let me know when you are ready.",objectivesText="Speak to Lady Liadrin to set sail for the Exodar.",rewardGold=20220,rewardXP=770,rewardItems={55015,58216,131354},starts={{npcID=122065}},ends={{npcID=122065}},mapCandidates={npc={1},zone={14}},questTurnInID=122065,questType="standard",sourceQuests={47835,48507},questLines={{id=346,name="To Argus!",orderIndex=5,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=346,questLineOrder=0,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1750,db2PoiUiMapID=891},
[47868] = {id=47868,name="The Necropolis",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47880},description="A deal is a deal, and I pay my debts. Bwonsamdi is a mighty loa and you are going to need a powerful ritual to obtain his attention. You are in luck. I already know exactly what needs to be done. Bwonsamdi's temple, de Necropolis, is just to de north. Meet me in de courtyard and we shall see about obtaining an audience with de loa of death.",rewardGold=23870,rewardXP=345,starts={{npcID=124428}},ends={{npcID=124513}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49278},questLines={{id=335,name="A Pact with Death",orderIndex=0,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=12,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47870] = {id=47870,name="Dead Men Tell No Tales",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47870,47871,47873,51810},series={51773},description="I'm an employee of the Ashvane Company. We're number one in the Azerite trade. When I took this job, no one told me it would be a one-way trip! I'd do just about anything to escape these dunes, including working with you. Maybe we can help each other out? I'd be willing to part with the code to the captain's lockbox, if you're willing to help me escape this wretched desert. For my plan to succeed, my expedition party needs to die. Can't have them telling anyone I'm missing...",objectivesText="Kill the remaining members of Randall's expedition party.",rewardGold=257400,rewardXP=4115,rewardItems={160000,160001,160002,160003,160735,161168,161169,161170,161171},rewardChoices={161168,161169,161170,161171,160000,160001,160002,160003},starts={{npcID=124468}},ends={{npcID=124468}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51773},questLines={{id=5423,name="Ashvane Antics",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47871] = {id=47871,name="Seafaring Necessities",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47870,47871,47873,51810},description="She might not be much to look at, but this boat will take me back to Boralus. Before my voyage can begin, I'll need a few seafaring necessities. Luckily, everything I need can be found in the Ashvane encampment.",objectivesText="Collect a Seafaring Hat , Nautical Map , and Weathered Spyglass . Progress: Have you had any luck securing those items I asked for?",rewardGold=257400,rewardXP=4115,rewardItems={151628,151629,151631,160735},starts={{npcID=124468}},ends={{npcID=124468}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51773},questLines={{id=5423,name="Ashvane Antics",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47873] = {id=47873,name="The Captain's Cache",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47870,47871,47873,51810},description="Well, I'm sure you've figured it out by now, eh? I never was fixing to abandon the crew, I just wanted to move up the ranks. You've helped me out a great deal in that respect. Speaking of respect, I believe there's the matter of Captain Hartford's lockbox ... Here's the code, courtesy of the fallen captain. Just as I promised. It's all yours! Now, don't go telling anyone about our little arrangement, okay? I wouldn't want something like that to spoil such a profitable partnership!",objectivesText="Loot Captain Hartford's cache.",rewardXP=2060,rewardItems={160735},rewardCurrencies={{id=1553,amount=75}},starts={{npcID=139070}},ends={{npcID=139070}},mapCandidates={npc={864},zone={8501}},questTurnInID=139070,questType="standard",sourceQuests={51810},questLines={{id=5423,name="Ashvane Antics",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47874] = {id=47874,name="Clearing the Fog",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="Did you lead Kaja here? I told her not to come after me. It isn't safe... My mind remains fogged, but de memories are slowly returning. Jakra'zet... de weapon... Come, let us find some fresh air. I will tell you what I've discovered.",objectivesText="Follow Warguard Rakera .",rewardGold=128700,rewardXP=2060,rewardItems={245417},rewardCurrencies={{id=1560,amount=50}},starts={{npcID=130660}},ends={{npcID=130667}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50913},questLines={{id=607,name="The Warguard's Fate",orderIndex=15,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=33,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47880] = {id=47880,name="A Tribute for Death",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47868},description="Everything for de ritual is together. Now, it is time to begin. For dis to work, I must chant de words of old. It is an exhausting task, so I need you to take my mojo fetish and draw de ritual circle, then beat upon de drums. If all goes well, Bwonsamdi may invite us into de temple. If not, our souls are forfeit. Let's not make any mistakes.",rewardGold=257400,rewardXP=2765,starts={{npcID=124513}},ends={{npcID=122688}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47868},questLines={{id=335,name="A Pact with Death",orderIndex=1,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=13,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[47882] = {id=47882,name="Conservation of Magic",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={46815,46818,46834,46941,47066,47685,47686,47687,47688,47689,47690,47882,47883,48081,48107},description="I have an idea. This construct will be of use to us. We simply need to jolt it awake. We once stored great quantities of energy in conduits throughout the Conservatory. They are still functional, but only just. Take this. <Y'mera hands you a brightly glowing crystal.> It will provide a small burst of magic that should help stabilize an erratic conduit. I think I have enough stored for eight or so. Stabilizing a few should allow us to access the whole network.",objectivesText="Stabilize 8 Erratic Power Conduits .",rewardGold=151650,rewardXP=6140,rewardItems={151624,152709},starts={{npcID=123413}},ends={{npcID=123413}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={47686},questLines={{id=366,name="The Crown of the Triumvirate",orderIndex=7,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=366,questLineOrder=5,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47883] = {id=47883,name="The Longest Vigil",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={46815,46818,46834,46941,47066,47685,47686,47687,47688,47689,47690,47882,47883,48081,48107},description="It was a good thing we sought two sources of energy. Even with the conduits active, the construct has not stirred. It has likely been inactive a long while. Perhaps as long as Eredath has floated above Argus. What a long, lonely vigil it must have been. <Y'mera is silent for a moment as she peers at the construct.> Go ahead and jostle it a little. That combined with one last burst of magic ought to do the trick.",objectivesText="Wake the Gatekeeper.",rewardGold=101100,rewardXP=6140,starts={{npcID=123413}},ends={{npcID=124070}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={47688,47882},questLines={{id=366,name="The Crown of the Triumvirate",orderIndex=9,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=366,questLineOrder=5,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47889] = {id=47889,name="The Speaker Calls",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={47889,47890,47891,47892,47986,47987,47988,47989,47990,47991,47992,47993,47994},description="Magni sent for you to meet him in the Krokul Hovel. He has found something that he believes could help us overcome the Legion's infinite armies. We need every advantage we can muster if we are to see this war through. You should seek him out.",objectivesText="Meet Magni in the Krokul Hovel.",rewardGold=20220,rewardXP=770,starts={{npcID=124312}},ends={{npcID=124595}},mapCandidates={npc={830},zone={8574}},questGiverID=124312,questType="standard",sourceQuests={47473,48929},questLines={{id=353,name="Nath'raxas Assault",orderIndex=0,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=353,questLineOrder=4,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[47890] = {id=47890,name="Visions of Torment",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={47889,47890,47891,47892,47986,47987,47988,47989,47990,47991,47992,47993,47994},description="I've been hearin' whispers ever since we got to Argus. They're just like Azeroth's, only... they ain't hers. I'm convinced that Argus has a titan of its own that's reachin' out to us! The broken have a relic stowed away that's darn near holy to 'em. Hatuun says they hear whispers from it... I think it might have some sort o' link to Argus itself! It's just in this chamber. Let's see what we can learn.",objectivesText="Activate the Sacred Stone to witness Argus' vision with Magni. Progress: I know, I know, it's a lot to ask, but we need all the help we can get lad!",rewardGold=20220,rewardXP=770,starts={{npcID=124595}},ends={{npcID=124595}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={47889},questLines={{id=353,name="Nath'raxas Assault",orderIndex=1,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=353,questLineOrder=4,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[47891] = {id=47891,name="Dire News",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={47889,47890,47891,47892,47986,47987,47988,47989,47990,47991,47992,47993,47994},series={47892},description="Azeroth was right in sendin' us here, <name>. We have to stop whatever it is Sargeras is plannin', or we may not have a home left to save when this is all over. Ye should go back to Turalyon and let him know what ye've seen. I'll stay here and see if I can't glean anything else that might help us.",objectivesText="Return to Turalyon on the Vindicaar.",rewardGold=20220,rewardXP=770,starts={{npcID=124595}},ends={{npcID=124595}},mapCandidates={npc={830},zone={8574}},questTurnInID=124595,questType="standard",sourceQuests={47890},questLines={{id=353,name="Nath'raxas Assault",orderIndex=2,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=353,questLineOrder=4,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=886},
[47892] = {id=47892,name="Storming the Citadel",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={47889,47890,47891,47892,47986,47987,47988,47989,47990,47991,47992,47993,47994},series={47891},description="We have already secured ground near Nath'raxas Hold. It is one of the Legion's chief military fortifications on Argus. Striking it now, and hard, may be our only opportunity to tip the scales in our favor.",objectivesText="Travel to Destiny Point.",rewardGold=20220,rewardXP=6140,starts={{npcID=124312}},ends={{npcID=120763}},mapCandidates={npc={830},zone={8574}},questGiverID=124312,questType="standard",sourceQuests={47891},questLines={{id=353,name="Nath'raxas Assault",orderIndex=3,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=353,questLineOrder=4,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[47895] = {id=47895,name="Bert's Bots",level=1,requiredLevel=1,faction="both",categories={},flags={"repeatable","daily"},sharable=false,expansion=7,zoneID=1,mapID=27,storyline={47895},description="If I'm going to clean up Gnomeregan, I've got to be ready to battle all manner of rat, roach, and potentially even the dreaded mutant rat-roach. What I'm saying is that I need to put these bots to the test! A real, live-action field demo. Are your pets up for a code review?",objectivesText="Defeat Bert in a pet battle. Progress: Better bots, by Bert!",rewardGold=341600,rewardXP=200,rewardItems={151638,151645},mapCandidates={npc={},zone={1}},questType="standard",db2QuestSortName="Epic"},
[47897] = {id=47897,name="Zanchuli Traitors",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="Dey are trying to cast down our loa, claiming dem to be false gods. Dey have turned to de old ways of blood, sacrifice, and subjugation. I cannot even begin to say how offensive dis is. Kill any of dese traitors you find.",rewardGold=257400,rewardXP=1415,starts={{npcID=124629}},ends={{npcID=123335},{npcID=133302}},mapCandidates={npc={1165},zone={8499}},questType="standard",sourceQuests={47509},questLines={{id=595,name="Web of Lies",orderIndex=0,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=47,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47904] = {id=47904,name="Preserve the True Future",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=65,mapID=115,storyline={47543,47545,47550,47904,47906},series={47906},description="I know how this looks, <name>. I'm not asking for your help simply because I don't want to get killed. I need your help because this isn't how I'm SUPPOSED to die. I will die - I've seen it! - but it happens much later than this. Besides, meddling with the timeways for personal reasons - well, it goes against pretty much everything my dragonflight stands for. Let's stop all four of the dragonshrine attacks. That should do the trick.",objectivesText="Stop the attacks from the Obsidian, Ruby, Azure, and Emerald Dragonshrines in one attempt of the Deaths of Chromie scenario.",rewardGold=606600,rewardXP=9210,rewardItems={150938,150939,150940,150941,150943,150945,150946,151141,151166,151167,151168,151370,151482,151493,151550,151554,151692,151693,151694,151695,151828,151829},rewardCurrencies={{id=1166,amount=250}},starts={{npcID=27856}},ends={{npcID=27856}},mapCandidates={npc={115},zone={65}},questType="standard",sourceQuests={47550},questLines={{id=352,name="The Deaths of Chromie",orderIndex=3,flags=0}},db2PoiMapID=571,db2PoiUiMapID=115},
[47906] = {id=47906,name="The Deaths of Chromie",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=65,mapID=115,storyline={47543,47545,47550,47904,47906},series={47904},description="It looks like we're going to have to stop all eight attacks on me. In one fifteen-minute span. Even to me, that doesn't seem like a lot of time. Still, if anybody can do it, it's us. Are you ready, <name>?",objectivesText="Stop all eight attacks on Chromie in one attempt in the Deaths of Chromie scenario.",rewardGold=606600,rewardXP=9210,rewardItems={124634,124635,124636,124637,124638,150938,150939,150940,150941,150943,150945,150946,151141,151166,151167,151168,151370,151482,151493,151546,151549,151550,151554,151692,151693,151694,151695,151828,151829},rewardChoices={151692,151693,151694,151695},rewardCurrencies={{id=1166,amount=50}},starts={{npcID=27856}},ends={{npcID=27856}},mapCandidates={npc={115},zone={65}},questType="standard",sourceQuests={47904},questLines={{id=352,name="The Deaths of Chromie",orderIndex=4,flags=0}},db2PoiMapID=571,db2PoiUiMapID=115},
[47915] = {id=47915,name="Rescuing the Taken",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8726,mapID=1165,description="We are doing our best to contain de fighting in Zanchul and not let it spill out into de other terraces, but we can't hold for long. If you are going to help, start by freeing Wardruid Loti . Dey are trying to break her on de platform above with a dark ritual. Her soul is bound to a fetish. You must find dat fetish if you are going to free her.",rewardGold=514800,rewardXP=1770,starts={{npcID=124629}},ends={{npcID=123335},{npcID=133302}},mapCandidates={npc={1165},zone={8726}},questType="standard",sourceQuests={47509},questLines={{id=595,name="Web of Lies",orderIndex=1,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=48,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47918] = {id=47918,name="To Serve Krag'wa",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={47918},description="There are other forces who seek to disturb my frogs. The vile naga attack my shores and drain my frogs of their magic! They seek to use my followers as a feast for their thirst for mana. It must be stopped! A powerful shadow hunter named Narez is currently fighting them. You must go aid her and stop the naga from feasting on my frogs!",objectivesText="Meet Shadow Hunter Narez in the Upper Frogmarsh.",rewardGold=25740,rewardXP=345,starts={{npcID=120551}},ends={{npcID=125317}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47696},nextQuests={48090,48092}},
[47919] = {id=47919,name="Just Say No to Cannibalism",level=20,requiredLevel=20,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={47919,47924,47925,47998},description="Of course the Natha'vor trolls have Shoak! Why would it be easy? I'm sick and tired of running from these trolls. That's why you're going in to end this. The Natha'vor trolls have three powerful troll witch doctors called \"corpse mongers\". Take them out and you'll send the tribe into disarray. Of course, this could all fail spectacularly and make my terrible day even worse.",objectivesText="Kill Corpse Mongers Jal'aka, Yon'gi, and Nog'shra",rewardGold=514800,rewardXP=3455,starts={{npcID=124933},{npcID=125024}},ends={{npcID=125024}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47924},questLines={{id=5413,name="A Bloody Meal",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[47924] = {id=47924,name="Profanity Filter",level=20,requiredLevel=20,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={47919,47924,47925,47998},description="I hate this place! I just want to go home, but I can't because that oaf, Shoak, is missing. Listen, <race>t, I'll make it worth your while if you help me find that dunce. I've got a way to find Shoak, but of COURSE these stupid totems are blocking my magic! Why wouldn't they? Take this scroll and use its magic to burn these totems. I'm going to look around to see if that bonehead is just sleeping somewhere.",objectivesText="Destroy 5 Profane Totems with Kajosh 's scroll of inferno . Progress: You destroy those totems yet?",rewardGold=257400,rewardXP=2765,rewardItems={151849},starts={{npcID=124666}},ends={{npcID=124933}},mapCandidates={npc={863},zone={8500}},questType="standard",questLines={{id=5413,name="A Bloody Meal",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[47925] = {id=47925,name="Shoak's on the Menu",level=20,requiredLevel=20,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={47919,47924,47925,47998},description="I don't know what stupid thing Shoak did to get captured by the Natha'vor trolls, we'll find out once you rescue him. I bet they're getting ready to make a meal out of Shoak . You need to work fast and get him out! Shoak 's one of the largest oafs that I know, those trolls won't be happy that you're taking their \"meal\" away.",objectivesText="Rescue Shoak from the Natha'vor trolls.",rewardGold=257400,rewardXP=2765,rewardItems={158955,158956,158957,158958,158964,158965,158966,158967},rewardChoices={158955,158956,158957,158958,158964,158965,158966,158967},starts={{npcID=124933},{npcID=125024}},ends={{npcID=124737}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47924},questLines={{id=5413,name="A Bloody Meal",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[47928] = {id=47928,name="Offering for the Loa",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47570,47571,47573,47574,47576,47577,47578,47580,47581,47928,47943,47965},description="The time has come for you to make contact with the great loa Eraka no Kimbul . I can only imagine what it will be like to be in the presence of such an ancient and powerful deity. You have earned the Ring of Tides, so it must be you that addresses the loa. Please present the loa with this offering from our tribe. Tell him of our plight against the naga. Eraka no Kimbul is our only hope of survival now.",objectivesText="Meet with Eraka no Kimbul . Progress: You must meet with the loa. Are you ready?",rewardGold=128700,rewardXP=2060,starts={{npcID=134133}},ends={{npcID=123052}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47573,47574,47581},questLines={{id=5429,name="Kimbul's Wrath",orderIndex=8,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47939] = {id=47939,name="If the Key Fits...",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47939},description="These Ashvane are unreasonable. I've tried to bargain for my release, but they refuse any offer I bring to the table. All they want is whatever's bubbling up in that mine. My kind know better than to go near that stuff. It's volatile. There are prisoners in the mine being forced to extract it. Us in the cages? We're back up. When someone dies in the mines, they just send another in. If you release me, I'll make sure you're rewarded! We just need to find the right key for this cage...",objectivesText="Collect 6 Ashvane Trader Keys . Progress: We need to find the right key to open this cage.",rewardGold=257400,rewardXP=4115,rewardItems={151777,160735},starts={{npcID=128422}},ends={{npcID=128422}},mapCandidates={npc={864},zone={8501}},questType="standard"},
[47943] = {id=47943,name="Crab Trapping",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47570,47571,47573,47574,47576,47577,47578,47580,47581,47928,47943,47965},description="We are trapped here with little in the way of food and supplies. The territorial sethrak control the land to the west, and the spiteful naga the waters to the east. We are caught between a barren desert and a hostile ocean. If you are headed to the lagoon to face the naga, will you bring us back some crabs to eat? I fear that our tribe will soon perish without food...",objectivesText="Catch 8 Clampclaw Clackers. Progress: Do you have a case of crabs?",rewardGold=257400,rewardXP=4115,rewardItems={151763},starts={{npcID=134128}},ends={{npcID=134128}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51772},questLines={{id=5429,name="Kimbul's Wrath",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47945] = {id=47945,name="To Market, To Market",level=20,requiredLevel=20,faction="alliance",categories={},flags={"loremaster"},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47945},description="Thanks heaps for getting us out of that pickle, mainlander. I'd hate to ask, but would you be willing to help with another matter? Even before this curse struck the village, our sausage shipments from Carver's Harbor started slowing down. If we don't get them sausages, I won't be able to feed my family! Can you help an honest sausage merchant out? Carver's Harbor is just down the road from here.",objectivesText="Meet Thomas Staughton at Carver's Harbor.",rewardGold=26680,rewardXP=345,rewardItems={155812,160009,160010,160011,160012,160021,160022,160023,160024,198608},starts={{npcID=128467}},ends={{npcID=124786}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={47982},nextQuests={47946,47947,47948,47949}},
[47946] = {id=47946,name="Save Their Bacon",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47946,47947,47948,47949,47950},description="This is going to sound strange, <class>, but some of my workers were turned into pigs! Lucky I was out on an errand, or I'd have been caught too! Now my people are tied up awaiting... processing. <Thomas suppresses the urge to retch.> I can't get past those monsters, but you look like the sort who could. Not sure if this helps, but I coulda sworn I heard some wild cackling coming from the warehouse. Please... save my people!",objectivesText="Untie Trevor Hightide , Kyle Sailford , Travis Daybreak and Burke Stevenson .",rewardGold=257400,rewardXP=2765,rewardItems={103786},starts={{npcID=124786}},ends={{npcID=124786}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={47945},questLines={{id=5440,name="Carver's Harbor",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[47947] = {id=47947,name="Big Bad Wolves",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47946,47947,47948,47949,47950},description="Wolves with strange, glowing eyes have taken over the area! I don't know what they are or why they're glowing but it cannot mean anything good. They have to be removed! Please, <class>, slay them before more of my friends are killed.",objectivesText="Slay 10 Hexed Howlers in Carver's Harbor.",rewardGold=257400,rewardXP=2765,starts={{npcID=124786}},ends={{npcID=124786}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={47945},questLines={{id=5440,name="Carver's Harbor",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[47948] = {id=47948,name="Pork Chop",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47946,47947,47948,47949,47950},description="Roland Hacksaw was the best butcher I've ever worked with... but he's gone insane! He's still processing pigs into sausage! You have to stop him!",objectivesText="Slay Roland the Butcher.",rewardGold=514800,rewardXP=3455,rewardItems={155127,155128,155131,155136,155139,155150,155153,158641},rewardChoices={155150,158641,155139,155153,155131,155127,155128,155136},starts={{npcID=124786}},ends={{npcID=124786}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={47945},questLines={{id=5440,name="Carver's Harbor",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[47949] = {id=47949,name="That's Not My Fetish",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47946,47947,47948,47949,47950},description="<The glassy eyes of the pig fetish seem to follow you as you approach. The dark power emanating from the witch's fetish must be what is keeping the workers transformed. Perhaps Thomas Staughton might have some idea what to do with it.>",objectivesText="Bring the Pig Fetish to Thomas Staughton . Provided item:",rewardGold=257400,rewardXP=2765,rewardItems={151793},ends={{npcID=124786}},startObjects={{objectID=277459,mapID=896,x=0.633,y=0.301}},coords={mapID=896,source="quest_giver",x=0.632,y=0.27},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={47945},questLines={{id=5440,name="Carver's Harbor",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[47950] = {id=47950,name="Cured Ham",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47946,47947,47948,47949,47950},description="That foul thing has to be what's keeping my men transformed into pigs. Hmm. Well there isn't too much that can withstand a good cleansing fire! I say we burn it! Toss it into the campfire!",objectivesText="Toss the Pig Fetish into the campfire. Progress: Into the flames with that foul thing!",rewardGold=25740,rewardXP=345,rewardItems={151793,153432},starts={{npcID=124786}},ends={{npcID=124786}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={47949},questLines={{id=5440,name="Carver's Harbor",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[47952] = {id=47952,name="The Missing Fleet",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="The tidesage order has a sizable monastery right here in Boralus. I say we start our search for the fleet there. Someone there has to know something, right? You don't just lose the entire legendary Kul Tiran fleet on accident! We'll need to take a ferry over to the monastery. Make sure you bring your pass with you!",rewardGold=25740,rewardXP=515,starts={{npcID=121235}},ends={{npcID=137866}},mapCandidates={npc={942,1161},zone={9042}},questType="standard",sourceQuests={47962},questLines={{id=442,name="A House in Peril",orderIndex=0,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=1,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[47953] = {id=47953,name="Tereck the Selector",level=45,requiredLevel=45,faction="none",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={47953},rewardGold=929400,rewardXP=9210,mapCandidates={npc={},zone={8574}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=124804}},worldTaskTitle="Tereck the Selector",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[47959] = {id=47959,name="The Warguard's Trail",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47316,47317,47319,47320,47321,47959,48549,48550,51574},description="Rakera's journal suggested she moved south. It's de only lead we have. Meerah is headed dat way, and has invited us to travel with her. These vulpera know de desert better than any troll I've ever met. Our chances of survival are highest if we travel together.",objectivesText="Travel with Meerah's Caravan in search of Warguard Rakera.",rewardGold=128700,rewardXP=2060,starts={{npcID=130341}},ends={{npcID=126696}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47316,47317,47321},questLines={{id=606,name="Dangers in the Desert",orderIndex=6,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=16,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47960] = {id=47960,name="Tiragarde Sound",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={"loremaster"},sharable=true,expansion=7,zoneID=8567,mapID=1161,storyline={47960,47961,47962},description="We must convince Katherine Proudmoore to pledge Kul Tiras to the Alliance. Flynn believes the Ashvane Trading Company's new gunpowder is our best lead.",objectivesText="Offer to investigate the Ashvane Trading Company.",rewardGold=30900,rewardXP=175,rewardItems={158065,158066,163032,163034},starts={{npcID=139522}},ends={{npcID=121235}},mapCandidates={npc={1161},zone={8568}},questGiverID=139522,questType="standard",sourceQuests={47189},questLines={{id=742,name="Kul Tiras",orderIndex=0,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=9,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2AdventureMapPoiID=43,db2PoiMapID=1643,db2PoiUiMapID=895},
[47961] = {id=47961,name="Drustvar",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=1161,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="The stalwart protectors of House Waycrest hold fast along the western border, but recently all contact with them has been lost. We must secure their aid in order to bring Kul Tiras together under the Proudmoore banner.",objectivesText="Offer to make contact with House Waycrest.",rewardGold=30900,rewardXP=345,starts={{npcID=139522}},ends={{npcID=121235}},mapCandidates={npc={1161},zone={8568}},questGiverID=139522,questType="standard",sourceQuests={47189},nextQuests={48622},questLines={{id=742,name="Kul Tiras",orderIndex=1,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=0,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2AdventureMapPoiID=44,db2PoiMapID=1643,db2PoiUiMapID=895},
[47962] = {id=47962,name="Stormsong Valley",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=8568,mapID=1161,description="The Kul Tiran fleet has been lost at sea. The tidesages of Stormsong, with their mystical oceanic magic, may be our only way to locate the fleet of legend.",rewardGold=30900,rewardXP=515,starts={{npcID=139522}},ends={{npcID=121235}},mapCandidates={npc={1161},zone={8568}},questGiverID=139522,questType="standard",sourceQuests={47189},nextQuests={47952},questLines={{id=5371,name="Secrets of Stormsong Valley",orderIndex=0,flags=0},{id=742,name="Kul Tiras",orderIndex=2,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[47963] = {id=47963,name="The Ancient One",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="Dis is far worse than I thought. Pa'ku is crying out in my mind. Dey are doing something to her. Something old and terrible, smelling of de old ways. She is nearby, just south of here. Come, $p, meet me at Pa'ku 's roost and we'll rescue her.",rewardGold=257400,rewardXP=1415,starts={{npcID=133653}},ends={{npcID=124756}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47521},questLines={{id=595,name="Web of Lies",orderIndex=6,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=54,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[47965] = {id=47965,name="The Ruined Temple",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47570,47571,47573,47574,47576,47577,47578,47580,47581,47928,47943,47965},description="The loa may be our only hope against the naga, but the temple lies abandoned and broken. Two of my tribe have gone ahead to scout the ruins. They may be able to help you make contact with Eraka no Kimbul. If the spirit of the loa remains at the temple, we must find a way for him to hear our plight.",objectivesText="Speak with Teekcha .",rewardGold=25740,rewardXP=515,starts={{npcID=123063}},ends={{npcID=134133}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47571},questLines={{id=5429,name="Kimbul's Wrath",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[47967] = {id=47967,name="An Argus Roper",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={47967,48441,48442,48443,48445,48446,48447,48448,48453,48455,48544,48600,48601,48654},description="My warriors stand no chance against even the smallest of the Legion's forces without our Cragscalers. If you can capture a few and bring them here, my warriors can better defend our people.",objectivesText="Return 3 Wild Cragscalers to Lead Rider Jerek . Progress: We need those talbuk!",rewardGold=151650,rewardXP=6140,rewardItems={152095,152096,152097,152575},starts={{npcID=126160}},ends={{npcID=126160}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={48460},questLines={{id=365,name="Petrified Forest",orderIndex=0,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=830},
[47968] = {id=47968,name="Signs and Portents",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="<The bulletin that Mayor White was posting at the time he was struck by the spell indicates that there have been some strange happenings in the town lately. It is likely these events are connected to whatever cast this spell on the village. Perhaps there might be records from other villagers that could shed some light on the source of this magic.>",objectivesText="Investigate the villagers' writings in Fallhaven. Progress: <The town's ledger lists a record of the comings and goings of people and goods through the city of Fallhaven.>",rewardGold=257400,rewardXP=2765,rewardItems={179385},rewardChoices={179385},startObjects={{objectID=272179,mapID=896,x=0.561,y=0.352}},endObjects={{objectID=272179,mapID=896,x=0.561,y=0.352}},coords={mapID=896,x=0.561,y=0.352},mapCandidates={npc={},zone={8721}},questType="standard",sourceQuests={48622},questLines={{id=381,name="Fallhaven",orderIndex=1,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=2,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[47969] = {id=47969,name="Fallhaven's Curse",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={47969},objectivesText="Combat the curse",rewardGold=455280,rewardXP=1415,mapCandidates={npc={},zone={8721}},questType="standard",sourceQuests={47968},db2Objectives={{text="Combat the curse",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Fallhaven's Curse",db2PoiMapID=1643,db2PoiUiMapID=896},
[47978] = {id=47978,name="The Wayward Crone",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="<The ledger indicates that an old woman named Helena Gentle recently took up residence in a house down the road from the town. The villagers' writings point to her being involved somehow with a variety of maladies that struck the village recently. It's possible that she may know what's behind this spell, if it hasn't afflicted her as well.>",objectivesText="Confront Helena Gentle in her home outside of Fallhaven.",rewardGold=30900,ends={{npcID=124922}},startObjects={{objectID=278669,mapID=896,x=0.556,y=0.3573}},coords={mapID=896,source="quest_giver",x=0.605,y=0.316},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={47968},questLines={{id=381,name="Fallhaven",orderIndex=2,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=3,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=895},
[47979] = {id=47979,name="Witch Hunt",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="A curse on the villagers? Oh my, how dreadful! Although, to be honest, there have been some strange happenings around Fallhaven of late. I wonder if these could be culprit? Take a seat and have a spot of tea. I'll tell you all that I know.",objectivesText="Listen to Helena Gentle 's story in the Shrouded Foothills.",rewardGold=514800,rewardXP=3455,starts={{npcID=124922}},ends={{npcID=124922}},mapCandidates={npc={896},zone={8721}},questTurnInID=124922,questType="standard",sourceQuests={47978},questLines={{id=381,name="Fallhaven",orderIndex=3,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=4,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[47980] = {id=47980,name="Furious Familiars",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47968,47978,47979,47980,47981,47982,48622},description="<The wildlife in the foothills appear to be under Helena's spell, and this villager appears to be one of their victims. They must be the cause of the recent disappearances from Fallhaven. Perhaps if their numbers were cut down, they would pose less of a threat to the townspeople.>",objectivesText="Kill 10 enthralled animals in the Shrouded Foothills.",rewardGold=264448,rewardXP=2765,starts={{npcID=125093}},ends={{npcID=125093}},mapCandidates={npc={896},zone={8721}},questTurnInID=125093,questType="standard",sourceQuests={47979},questLines={{id=381,name="Fallhaven",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[47981] = {id=47981,name="Cracking the Curse",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="<In her haste, it looks like Helena left her spellbook behind. The pages of this book detail the ritual that she used to entrap the villagers of Fallhaven. It seems the effigy holding the spell in the village is protected by smaller ones surrounding the town. If these are destroyed, you may be able to affect the one holding the spell on the townsfolk.>",objectivesText="Destroy the 4 Lesser Effigies in the Shrouded Foothills.",rewardGold=257400,rewardXP=2765,startObjects={{objectID=272422,mapID=896,x=0.605,y=0.314}},endObjects={{objectID=272422,mapID=896,x=0.605,y=0.314}},coords={mapID=896,x=0.605,y=0.314},mapCandidates={npc={},zone={8721}},questType="standard",sourceQuests={47979},questLines={{id=381,name="Fallhaven",orderIndex=4,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=5,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[47982] = {id=47982,name="The Final Effigy",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="<The effigy's protection has been broken. All that remains is to break the effigy itself.>",objectivesText="Destroy the Cursed Effigy in Fallhaven.",rewardGold=514800,rewardXP=3455,rewardItems={155108,155109,155110,155111,155121,155122,155123,155124},rewardChoices={155109,155111,155110,155108,155121,155124,155123,155122},ends={{npcID=124417}},startObjects={{objectID=278675,mapID=896,x=0.558,y=0.35}},coords={mapID=896,source="quest_giver",x=0.558,y=0.35},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={47981},questLines={{id=381,name="Fallhaven",orderIndex=6,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=6,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[47986] = {id=47986,name="Scars of the Past",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={47889,47890,47891,47892,47986,47987,47988,47989,47990,47991,47992,47993,47994},description="The Army of the Light's warframes have won countless battles on Argus. Despite their power, not all who descend into the fray return. My modifications to this frame should give us the edge we need, but several critical components are still missing. There are remains of battles past in Nath'raxas that we can still scavenge. If you can find the pieces I need, the Legion will feel our fury yet.",objectivesText="Recover an Invocation Array , Vindicator Plating , and a Judgment Core . Progress: Do you have the components?",rewardGold=151650,rewardXP=6140,rewardItems={151837,151838,151839},starts={{npcID=124975}},ends={{npcID=124975}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={47892},questLines={{id=353,name="Nath'raxas Assault",orderIndex=4,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=353,questLineOrder=4,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[47987] = {id=47987,name="Preventive Measures",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={47889,47890,47891,47892,47986,47987,47988,47989,47990,47991,47992,47993,47994},description="There is no end to the Legion's depravity. Every battle won, every world conquered, yields more souls to fuel their war machine. They have not yet defiled all of the fallen warriors in the hold, but I fear it is only a matter of time. Please, take this talisman with you into the hold and use it to sanctify any corpses you encounter. They deserve a better fate.",objectivesText="Use the Talisman of the Prophet to sanctify 9 fallen Army of the Light warriors.",rewardGold=151650,rewardXP=6140,rewardItems={152110,152706},starts={{npcID=124974}},ends={{npcID=124974}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={47892},questLines={{id=353,name="Nath'raxas Assault",orderIndex=5,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=353,questLineOrder=4,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[47988] = {id=47988,name="Chaos Theory",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={47889,47890,47891,47892,47986,47987,47988,47989,47990,47991,47992,47993,47994},description="Despite their strength and their numbers, even the Burning Legion requires order to fight. Disrupt that order... and they fall like the rabble they are. The plan is simple. Let chaos reign in their ranks, and the day will be ours.",objectivesText="Kill 12 Nath'raxxan Fleshcarvers , Nath'raxxan Doomshots , or Ravenous Soulhunters , and 1 Nathrezim Banelord . Progress: We must do whatever it takes to see this done.",rewardGold=151650,rewardXP=6140,starts={{npcID=124972}},ends={{npcID=124972}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={47892},questLines={{id=353,name="Nath'raxas Assault",orderIndex=6,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=353,questLineOrder=4,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[47989] = {id=47989,name="Heralds of Apocalypse",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={47889,47890,47891,47892,47986,47987,47988,47989,47990,47991,47992,47993,47994},description="We've been presented with a rare opportunity. Our scouts have spotted two shivarra priestesses in the western fel pools enhancing the Legion's war effort. The inner circle of Sargeras' chosen never leave the walls of Antorus. If we take them out, we might be able to sow fear among those closest to the Dark Titan.",objectivesText="Slay Lady Heretica and Mistress Apostriss .",rewardGold=202200,rewardXP=6140,rewardItems={153048},starts={{npcID=125443}},ends={{npcID=125443}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={47986,47987,47988},questLines={{id=353,name="Nath'raxas Assault",orderIndex=7,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=353,questLineOrder=4,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[47990] = {id=47990,name="A Touch of Fel",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={47889,47890,47891,47892,47986,47987,47988,47989,47990,47991,47992,47993,47994},description="Our warframe is almost operational! It just needs a good jolt to revitalize its systems. Warlocks in the pools below infuse pieces of Argus with fel energy to create living siege weapons. If you can extract one, we can use it to jumpstart the warframe's Judgment Core!",objectivesText="Collect an Immaculate Felcore . Progress: Remember - immaculate!",rewardGold=202200,rewardXP=6140,rewardItems={151851},starts={{npcID=124975}},ends={{npcID=124975}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={47986,47987,47988},questLines={{id=353,name="Nath'raxas Assault",orderIndex=8,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=353,questLineOrder=4,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[47991] = {id=47991,name="Dark Machinations",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={47889,47890,47891,47892,47986,47987,47988,47989,47990,47991,47992,47993,47994},description="Eredar are adept at manipulating the fel that courses through this world. Those who do not shape it into living weapons build other armaments, like the Spires of Woe. The spires will make it difficult for even a small force to penetrate the main stronghold. We must dismantle enough of them to clear the way before we advance upon it.",objectivesText="Dismantle 3 Spires of Woe. Progress: We do not have time for failure.",rewardGold=202200,rewardXP=6140,starts={{npcID=124972}},ends={{npcID=124972}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={47986,47987,47988},questLines={{id=353,name="Nath'raxas Assault",orderIndex=9,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=353,questLineOrder=4,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[47992] = {id=47992,name="Dawn of Justice",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={47889,47890,47891,47892,47986,47987,47988,47989,47990,47991,47992,47993,47994},series={47993},description="Thanks to your efforts, our enemy is in disarray and their defenses inoperable. We must take the ground at the spire's base and tighten the noose around their commander's neck. You have more than earned the honor to take the warframe into battle. We will follow your lead once the way is clear.",objectivesText="Use the Lightforged Warframe to take control of the Court of the Avenger.",rewardGold=404400,rewardXP=6140,starts={{npcID=120763}},ends={{npcID=120763}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={47989,47990,47991},questLines={{id=353,name="Nath'raxas Assault",orderIndex=10,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=353,questLineOrder=4,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[47993] = {id=47993,name="Lord of the Spire",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={47889,47890,47891,47892,47986,47987,47988,47989,47990,47991,47992,47993,47994},series={47992},description="Lord Nath'raxas rules over this hold as thanks for his role in delivering Argus to the Legion many years ago. Make no mistake, he is powerful, but he has also grown overconfident in his seat. Take advantage of his hubris and make use of the warframe's firepower while you can. We will storm the courtyard shortly!",objectivesText="Defeat Lord Nath'raxas .",rewardGold=606600,rewardXP=6140,starts={{npcID=120763}},ends={{npcID=120763}},mapCandidates={npc={830},zone={8574}},questTurnInID=120763,questType="standard",sourceQuests={47992},questLines={{id=353,name="Nath'raxas Assault",orderIndex=11,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=353,questLineOrder=4,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=831},
[47994] = {id=47994,name="Forming a Bond",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={47889,47890,47891,47892,47986,47987,47988,47989,47990,47991,47992,47993,47994},rewardGold=20220,rewardXP=770,starts={{npcID=121263}},ends={{npcID=121263}},mapCandidates={npc={830},zone={8899}},questGiverID=121263,questTurnInID=121263,questType="standard",sourceQuests={47993},questLines={{id=353,name="Nath'raxas Assault",orderIndex=12,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=353,questLineOrder=4,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2LabelIDs={4784},db2PoiMapID=1669,db2PoiUiMapID=886},
[47995] = {id=47995,name="Overt Ops",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={47416,47691,47853,47854,47855,47856,47995,48344,48345},description="My soldiers are out there, <name>. I need you to find Baraat, Sorvos, and Telaamon. They were in the process of securing this area for Velen when the Legion came down on top of our heads. Inform them that their orders are to regroup with the Prophet at once. The time for subtlety has passed. There is a small army between us and them. Do what you must. Light keep you safe.",objectivesText="Locate Baraat the Longshot , Grand Vindicator Sorvos , and Blademaster Telaamon .",rewardGold=151650,rewardXP=6140,starts={{npcID=123668}},ends={{npcID=123668}},mapCandidates={npc={},zone={8701}},questGiverID=123668,questTurnInID=123668,questType="standard",sourceQuests={48344},questLines={{id=367,name="Across the Universe",orderIndex=3,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=367,questLineOrder=7,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=882},
[47996] = {id=47996,name="Mawfiend Extermination",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={47996},objectivesText="Mawfiend threat elimated",rewardGold=455280,rewardXP=1415,mapCandidates={npc={},zone={8500}},questType="standard",sourceQuests={47924},db2Objectives={{text="Mawfiend threat elimated",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Mawfiend Extermination",db2PoiMapID=1642,db2PoiUiMapID=863},
[47998] = {id=47998,name="Killing Cannibals",level=20,requiredLevel=20,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={47919,47924,47925,47998},description="Shoak and I have had a few run-ins with the Natha'vor trolls. Must be why they wanted to capture that idiot. The women in that tribe actually eat the men... and anyone else they can get their hands on. I'm sure they're getting ready to eat Shoak. Do us all a favor and kill some of those cannibals. The world would be a better place without them.",objectivesText="Kill 10 Natha'vor Cannibals . Progress: Well? Did you take care of those cannibals?",rewardGold=257400,rewardXP=2765,starts={{npcID=124933}},ends={{npcID=125024}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47924},questLines={{id=5413,name="A Bloody Meal",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[48002] = {id=48002,name="Limited Supplies",level=45,requiredLevel=45,faction="both",requiredProfessions={"alchemy"},categories={},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={48002,48013,48016},series={48013,48016},description="Hello, <name>. It's good to see a fellow alchemist again. I've been supplying our camp with necessary potions to deal with the demons, but lately I've been running low on supplies. Normally when scouting parties go out, they return with empty vials, but as of late fewer have been returning. I try to recycle as much as I can, so you see, those vials are precious to me. If you'd be willing to go out and retrieve them, I could show you what I've been making to help combat the demons.",objectivesText="Go to the Petrified Forest and reclaim 12 Used Vials . Progress: How goes the search? Any luck on finding my vials?",rewardItems={151608,151845},starts={{npcID=125346}},ends={{npcID=125346}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={46816},questLines={{id=357,name="Legion Alchemy",orderIndex=0,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=830},
[48003] = {id=48003,name="The Lord's Behest",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48003,48004,48005,48077,48080,48087,48088,48089,48195,48196,48597,48616,48670},description="Lord Norwington will want to thank you for saving his son himself. Why don't you come to the estate? We're preparing for a festival, and everybody's welcome. We'll go ahead and tell him of all that has happened. See you there!",objectivesText="Meet Lord Aldrius Norwington at the Norwington Estate.",rewardGold=257400,rewardXP=1415,rewardItems={151913,152109,152642,152643,152670,152671,152675,152678,153357},rewardCurrencies={{id=1553,amount=75}},starts={{npcID=127144}},ends={{npcID=124802}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48195,48196,48597},questLines={{id=591,name="The Norwington Estate",orderIndex=7,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48004] = {id=48004,name="Beginner Equitation",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48003,48004,48005,48077,48080,48087,48088,48089,48195,48196,48597,48616,48670},series={48005},description="You may know how to ride already, but you don't know how to ride like a Kul Tiran! We'll let you borrow a horse for the festivities. Take one of our lesson masters, Cooper . He's trained many a beginner in his day! Mount up, get in the ring, and show us what you've got! I'm sure you'll be a quick learner!",objectivesText="Mount Cooper and practice your Kul Tiran riding skills. Progress: Kul Tiran riding is a true show of mastery and sport!",rewardGold=257400,rewardXP=1415,rewardItems={151913,152109,152642,152643,152670,152671,152675,152678,153357},starts={{npcID=124802}},ends={{npcID=124802}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48005},questLines={{id=591,name="The Norwington Estate",orderIndex=9,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48005] = {id=48005,name="Be Our Guest",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48003,48004,48005,48077,48080,48087,48088,48089,48195,48196,48597,48616,48670},series={48004},description="My dear friend <name>, I do hope you enjoy the festival. I throw it every year to bring riders from all over Kul Tiras together for a grand celebration of the sport! In fact, you deserve the whole nine yards. Please, tour the estate at your leisure and partake in the delicious food and drink, introduce yourself to the people. I insist!",objectivesText="Tour the estate and partake in the festivities. Progress: Have you taken your tour yet? Take a break from adventuring and relax!",rewardGold=257400,rewardXP=1415,rewardItems={2562,151913,152109,152642,152643,152670,152671,152675,152678,153357},starts={{npcID=124802}},ends={{npcID=124802}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48003},questLines={{id=591,name="The Norwington Estate",orderIndex=8,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48008] = {id=48008,name="Dangerous Cargo",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48008,48009,48347,48348,48352,48353,48354,48355,48356,48365,48366,48367,48368,48370,48372,48540,49268,49292,49299,49302},description="By the time I realized what was happening, it was too late. People had been acting strange, but I thought nothing of it. After all, they seemed to still be doing their jobs. While inspecting some of the cargo, this grub jumped out in an attempt to latch onto my face. I managed to take it out, but it was too late. All of the shipments are infected. Take this torch. Destroy them.",objectivesText="Burn 5 Infested Cargo . Progress: If I had only noticed sooner, perhaps some of this could be avoided.",rewardGold=257400,rewardXP=1415,starts={{npcID=125962}},ends={{npcID=125962}},mapCandidates={npc={895},zone={8567}},questType="standard",questLines={{id=592,name="The Shadow Over Anglepoint",orderIndex=11,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48009] = {id=48009,name="Betrayal of the Guard",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48008,48009,48347,48348,48352,48353,48354,48355,48356,48365,48366,48367,48368,48370,48372,48540,49268,49292,49299,49302},description="My boys have gotten in too deep. They've given in to whatever dark forces are at work here. Do not hesitate to do what you need to and put them down. They knew what they were signing up for when they picked the wrong side.",objectivesText="Kill 10 Mind-Addled Enforcers.",rewardGold=257400,rewardXP=1415,rewardItems={152401,152585,152586,153486,153513},starts={{npcID=126308}},ends={{npcID=126308}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48354,48355},questLines={{id=592,name="The Shadow Over Anglepoint",orderIndex=10,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48013] = {id=48013,name="Tracking the Trackers",level=45,requiredLevel=45,faction="both",requiredProfessions={"alchemy"},categories={},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={48002,48013,48016},series={48002,48016},description="<name>, have I told you about my tracking potion? Our scouts use it to track demons, especially their \"fiends\". Those particular creatures tend to consume the astral glory in the area, making it difficult to replenish our stores of the herb. If you could help thin their numbers out, it would greatly help us from having to search elsewhere for supplies. You can find many of them in the Annihilan Pits. I could also teach you the recipe for this potion for your effort.",objectivesText="Kill 14 Feflame Scavengers at the Annihilan Pits.",rewardItems={151609},starts={{npcID=125346}},ends={{npcID=125346}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={46816},questLines={{id=357,name="Legion Alchemy",orderIndex=1,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=830},
[48014] = {id=48014,name="Clear the Riffraff",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={48014,48015,48025,48026,49969,51538},description="The naga sent their tiny, foul, muck-smelling minions into our camp. They are quite bothersome. If we do nothing, and their numbers continue to grow, they could pose a threat. You look quick and handy. Could you perhaps expunge a few for us?",objectivesText="Slay 6 Gilblins at the Scavenger's Strand.",rewardGold=257400,rewardXP=1415,rewardItems={156871},starts={{npcID=125047}},ends={{npcID=125039}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50331},questLines={{id=5410,name="The Sunken City",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[48015] = {id=48015,name="The Scrolls of Gral",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={48014,48015,48025,48026,49969,51538},series={49769},description="These gilblins are ridiculous! They are like a swarm of angry bees, buzzing around. Hmm, maybe not bees. Bees are useful, and make honey, and don't steal things. They ransacked our scrolls. Most were unusable, but there were three that are quite... potent. It would be most unfortunate if those made it back to their masters, the naga. Please clean up their mess and bring back our scrolls.",objectivesText="Collect the 3 Tortollan Scrolls. Progress: Ah, <race>. I was always fascinated by your native language.",rewardGold=257400,rewardXP=1415,rewardItems={151852,151853,151854,156871},starts={{npcID=125047}},ends={{npcID=125041}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49769,50331},questLines={{id=5410,name="The Sunken City",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[48016] = {id=48016,name="Ascending Alchemy",level=45,requiredLevel=45,faction="both",requiredProfessions={"alchemy"},categories={},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={48002,48013,48016},series={48002,48013},description="I've seen other alchemists come through our camp carrying interesting looking trinkets. I believe they refer to them as... \"alchemist stones\"? I can sense the power they radiate, but they appear fel-tainted. The herb that grows on this planet is particularly good at cleansing corruption. I use it to purify the primal sargerite that's often found amongst the herbs. I'm certain that if we used a purified sargerite with one of those stones, we could elevate the power within it.",objectivesText="Bring Funen 75 Astral Glory , 5 Primal Sargerite and a Bound Infernal Alchemist Stone . Progress: I know it's a lot of materials to ask for, but it's necessary.",rewardItems={127842,127906,151565,151568,164379,164380},starts={{npcID=125346}},ends={{npcID=125346}},mapCandidates={npc={830},zone={8574}},questType="standard",questLines={{id=357,name="Legion Alchemy",orderIndex=2,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=830},
[48021] = {id=48021,name="Chromie",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=7502,storyline={48021},description="<name>. Is that you? I'm convinced that something unusual has happened in the timelines. I need your help! Come find me at Wyrmrest Temple, in Dragonblight, and I'll show you.",objectivesText="Reach \"Timehopper\" friendship rank with Chromie in Dragonblight. Progress: Any luck traversing the timeways?",rewardGold=202200,rewardXP=6140,rewardItems={150938,150939,150940,150941,150943,150944,150945,150946,151141,151166,151167,151168,151484,151485,151486,151491,151493,151692,151693,151694,151695,151700,232877,233014},starts={{npcID=90417}},ends={{npcID=90417}},mapCandidates={npc={},zone={7502}},questGiverID=90417,questTurnInID=90417,questType="standard"},
[48023] = {id=48023,name="Orders Received",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48023},description="We need ta be knowin' who be leadin' da naga in snatchin' all dese cute frogs. Dey got chests around here dat have some kind of scroll dey be readin'. Da ladies be tellin' da men to remember dem orders. Get me some of dem scrolls so we can be seein' who be callin' da shots.",objectivesText="Recover 5 Explicit Orders .",rewardGold=238680,rewardXP=2765,rewardItems={151928},mapCandidates={npc={},zone={8500}},questType="standard"},
[48025] = {id=48025,name="Saving for Later",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={48014,48015,48025,48026,49969,51538},description="We need time to recover the artifacts from this place. Time the naga will not let us have. However, we do have a plan. We simply hide what we don't want them to find, and then come back in a decade or two. They will have forgotten about this place by then. Take this illusion scroll and use it to conceal the notable artifacts of power.",objectivesText="Conceal the antiquities of Gral. Progress: How is that scroll working out?",rewardGold=257400,rewardXP=1415,rewardItems={151859,156871},starts={{npcID=125041}},ends={{npcID=125041}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={48014,48015},questLines={{id=5410,name="The Sunken City",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[48026] = {id=48026,name="Beneath the Waves",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={48014,48015,48025,48026,49969,51538},series={51538},description="Those witches dare! In my temple? Siavass is stretching past the realm of that which she can comprehend. There is a darkness seeking them, and they call to it! Her kind will become no more than a hollow tool to those who may answer. I feel it moving beneath us, around us. I feel it like a tremor through my being. There is a pressure there, it has a weight greater than that of the deepest ocean. We must stop them. They are not welcome here!",objectivesText="Slay Summoner Siavass and the Whispering Horror .",rewardGold=514800,rewardXP=1770,rewardItems={155308,156871,159765},rewardChoices={155308,159765},starts={{npcID=131475}},ends={{npcID=131475}},mapCandidates={npc={},zone={8499}},questGiverID=131475,questTurnInID=131475,questType="standard",sourceQuests={49969},questLines={{id=5410,name="The Sunken City",orderIndex=6,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[48027] = {id=48027,name="The Glory of Argus",level=45,requiredLevel=45,faction="both",requiredProfessions={"herbalism"},categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={48027},description="<Amazed that anything so pure could continue to grow on this planet, you pick the flower from the ground. You feel a small power radiate from it and then vanish.> <As it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.>",objectivesText="Find someone on Argus who might be able to train you on how to handle Astral Glory. Provided item:",rewardItems={151856},ends={{npcID=125346}},coords={mapID=830,source="quest_giver",x=0.562,y=0.668},mapCandidates={npc={830},zone={8574}},questType="standard",startItems={151856}},
[48028] = {id=48028,name="Youthful Resistance",level=45,requiredLevel=45,faction="both",requiredProfessions={"herbalism"},categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={48028},description="<As you begin to gather the flowers, you realize that some of the younger blooms are still resistant to your approach and refuse to yield. Perhaps Funen might know more about how to handle the herb in its adolescent stages.>",objectivesText="Ask Funen about how to handle the younger Astral Glories. Provided item:",rewardItems={151568,151857},ends={{npcID=125346}},coords={mapID=830,source="quest_giver",x=0.562,y=0.668},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={48027},startItems={151857}},
[48029] = {id=48029,name="The Heart of It",level=45,requiredLevel=45,faction="both",requiredProfessions={"herbalism"},categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={48029},description="<Having handled astral glory for a while now, you've picked up on something interesting about its roots. Tightly wound in a cocoon, small flecks of light permeate through the cracks creating a shimmering effect.> <Perhaps Funen might be able to expand on the nature of these lights.>",objectivesText="Ask Funen about the shimmering roots of the Astral Glory. Provided item:",rewardGold=619600,rewardXP=100,rewardItems={6948,25712,25713,25714,36739,50375,50376,50377,50378,50384,50386,50387,50388,50397,50398,50399,50400,50401,50402,50403,50404,52569,52570,52571,52572,54921,54922,57320,57321,57322,58991,58992,58993,60709,60710,64507,64508,64509,64510,64511,64512,64513,64514,112603,112604,112605,112606,129250,129251,129252,129253,129254,129255,129256,129257,131300,131417,131557,147442,151858,156932,159901,159902,159903,159904,159905,159906,159907,159908,160906,160907,160908,160909,160910,160911,160912,160913,160914,160915,160916,160917,160918,160919,160920,160921,175648,175649,175650,175651,175713,175740,176832,176921,176922,179500,179508,179517,179537,179547,179562,179584,179604,180944,181368,181377,181407,181409,181410,181418,181422,181423,181424,181425,181430,181457,181458,181459,181477,181479,181506,181541,181569,181577,181587,181591,181603,181605,181627,181632,181633,181635,181636,181637,181702,181704,181738,181745,182128,182203,182385,182480,182649,182675,182736,182743,183167,183402,183468,183469,183473,183481,183482,183486,183489,184294,184362,184373,184374,184381,184382,184383,184384,184587,184765,184766,184767,184768,189865,198002,198003,198004,198006,198009,198034,198105,198612,200597,204581,204589,204597,204605,219764,219765,251547,253021},ends={{npcID=125346}},coords={mapID=830,source="quest_giver",x=0.562,y=0.668},mapCandidates={npc={830},zone=