[48034] = {id=48034,name="Empyrium Deposit Chunk",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48034},description="<As you swing your pickaxe into the ore, it hits with a resounding thud, sending a small chunk of it to the ground. At this rate, it would take you all day to get a sufficient amount of ore from this deposit.> <Perhaps someone can give you some insight into how to mine this deposit properly.>",objectivesText="Find someone on the Vindicaar who might be able to train you on how to mine an empyrium deposit. Provided item:",rewardItems={151860,151861},mapCandidates={npc={},zone={8899}},questType="standard",startItems={151860}},
[48035] = {id=48035,name="Angling For a Better Strike",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48035},description="empyrium dust from taking down this deposit, you wonder if there's a way to prevent part of the deposit from shattering with each impact.> Khamir will know something further that he can share with you.>",objectivesText="Speak with Khamir and see if there's a better way to mine empyrium deposits. Provided item:",rewardItems={151861},mapCandidates={npc={},zone={8899}},questType="standard",sourceQuests={48034},startItems={151861}},
[48036] = {id=48036,name="Precision Perfected",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48036},description="Khamir might be needed to correct this problem.>",objectivesText="Speak with Khamir and see if there's an even better way to mine empyrium deposits. Provided item:",rewardItems={151862},mapCandidates={npc={},zone={8899}},questType="standard",sourceQuests={48035},startItems={151862}},
[48037] = {id=48037,name="Empyrium Seam Chunk",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48037},description="<At first you thought the ore to have a mirrored surface, reflecting the starry space above you. After breaking off a chunk, you realize that the ore itself has a starry quality all of its own.> <Perhaps someone back at the Vindicaar can give you some insight on how to better extract these seams more efficiently.>",objectivesText="Find someone at the Vindicaar who might be able to train you on how to mine empyrium seams. Provided item:",rewardItems={151863},mapCandidates={npc={},zone={8899}},questType="standard",startItems={151863}},
[48038] = {id=48038,name="Don't Just Pick At It",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48038},description="Khamir can show you a way to remove the ore from these sections of the seam.>",objectivesText="Speak with Khamir about a way to extract more ore from empyrium seams. Provided item:",rewardItems={151864},mapCandidates={npc={},zone={8899}},questType="standard",sourceQuests={48037},startItems={151864}},
[48039] = {id=48039,name="Balancing the Break",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48039},description="Khamir might know a way to prevent this from happening.>",objectivesText="Speak with Khamir about a way to extract even more ore from empyrium seams. Provided item:",rewardItems={151865},mapCandidates={npc={},zone={8899}},questType="standard",sourceQuests={48038},startItems={151865}},
[48040] = {id=48040,name="Tainted Scraps",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48040},description="<As you begin to carefully remove the skin from the corpse, you notice it quickly becoming corrupted by the decay of the creature.> <Pulling away, you were only able to extract a small amount of leather and something foul smelling. Perhaps someone on the Vindicaar might know more about this foul hide.>",objectivesText="Find someone at the Vindicaar who might be able to train you on how to skin fiendish leather. Provided item:",rewardItems={151866},mapCandidates={npc={},zone={8899}},questType="standard",startItems={151866}},
[48041] = {id=48041,name="A Larger Cut",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48041},description="Enstraa might have a better idea of how to remove more of the hide before it becomes tainted.>",objectivesText="Speak with Enstraa about a better way to remove fiendish leather. Provided item:",rewardItems={151867},mapCandidates={npc={},zone={8899}},questType="standard",sourceQuests={48040},startItems={151867}},
[48042] = {id=48042,name="Order of Operations",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48042},description="Enstraa back at the Vindicaar.>",objectivesText="Speak with Enstraa about a better way to dissect the beasts of Argus. Provided item:",rewardItems={151566,151868},mapCandidates={npc={},zone={8899}},questType="standard",sourceQuests={48041},startItems={151868}},
[48043] = {id=48043,name="FLAG - Plating Cleared",level=1,requiredLevel=1,faction="both",categories={},flags={},sharable=true,expansion=7,storyline={48043},rewardItems={151282,151283},mapCandidates={npc={},zone={}},questType="standard"},
[48044] = {id=48044,name="FLAG - Shields Cleared",level=1,requiredLevel=1,faction="both",categories={},flags={},sharable=true,expansion=7,storyline={48044},rewardItems={151282,151283},mapCandidates={npc={},zone={}},questType="standard"},
[48053] = {id=48053,name="Weigh Anchor",level=45,requiredLevel=45,faction="alliance",requiredProfessions={"blacksmithing"},categories={},flags={},sharable=true,expansion=7,zoneID=7502,mapID=84,storyline={48053},description="<name>, I was hoping to ask you for a small favor. The naval fleet at Stormwind Harbor have been requesting large amounts of felslate to help construct supplies for their ships. I'm pretty busy here coordinating the gathering efforts and all my couriers are still out. I was wondering if you wouldn't mind taking that shipment over there to them? I heard there's a portal to Stormwind in the Greyfang Enclave here in Dalaran so it shouldn't be a long trip or anything.",objectivesText="Bring the Crate of Felslate to Walcott Sutton at Stormwind Harbor. Progress: Did Alard send you?",rewardItems={151871},starts={{npcID=92183}},ends={{npcID=125210}},mapCandidates={npc={84},zone={7502}},questGiverID=92183,questType="standard",sourceQuests={38499},questLines={{id=360,name="Legion Blacksmithing",orderIndex=0,flags=0}},db2PoiUiMapID=84},
[48054] = {id=48054,name="Weigh Anchor",level=45,requiredLevel=45,faction="horde",requiredProfessions={"blacksmithing"},categories={},flags={},sharable=true,expansion=7,zoneID=7502,mapID=76,storyline={48054},description="<name>, I was hoping to ask you for a small favor. The naval fleet at Bilgewater Harbor have been requesting large amounts of felslate to help construct supplies for their ships. I'm pretty busy here coordinating the gathering efforts and all my couriers are still out. I was wondering if you wouldn't mind taking that shipment over there to them? I heard there's a portal to Orgrimmar in the Windrunner's Sanctuary here in Dalaran so it shouldn't be a long trip or anything.",objectivesText="Bring the Crate of Felslate to Kruda Thunderhand at Bilgewater Harbor. Progress: Did Vridiel send you?",rewardItems={151871},starts={{npcID=106655}},ends={{npcID=125216}},mapCandidates={npc={76},zone={7502}},questGiverID=106655,questType="standard",sourceQuests={38499},questLines={{id=364,name="Legion Blacksmithing",orderIndex=0,flags=0}},db2PoiMapID=1,db2PoiUiMapID=76},
[48055] = {id=48055,name="Empyrial Strength",level=45,requiredLevel=45,faction="both",requiredProfessions={"blacksmithing"},categories={},flags={},sharable=true,expansion=7,zoneID=8899,mapID=887,storyline={48055},description="I see my armor's caught your interest. It's made from the finest material on Argus: empyrium. I actually specialize in crafting breastplates. I could show you how to craft one, but you'll need to bring your own supplies, I'm afraid. Our stores of the ore are low and we need all that we have. But here are the plans so you'll know what you need to find...",objectivesText="Craft an Empyrial Breastplate . You can find the materials from gathering the ore from Argus, from other players, or from the auction house. Progress: I hope those plans weren't too complicated for you to understand.",rewardItems={151564,151568,151576,151872,151923,151924,151925},starts={{npcID=125341}},ends={{npcID=125341}},mapCandidates={npc={},zone={8899}},questGiverID=125341,questTurnInID=125341,questType="standard",sourceQuests={47743},questLines={{id=358,name="Legion Blacksmithing",orderIndex=0,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=887},
[48056] = {id=48056,name="A Harsh Mistress",level=45,requiredLevel=45,faction="both",requiredProfessions={"engineering"},categories={},flags={},sharable=true,expansion=7,zoneID=7502,mapID=627,storyline={48056,48065,48069},description="So there I was thinkin' about how to get everyone ready for movin' around Argul or whatever it's called, since I figure its gravity is different than ours, and I come up with a design for a device you slip onto your shoes, or hooves or whatever you're wearin' down there. Next thing I hear, the gravity on that planet? Completely the same as ours! Regardless, I figure I could get the prototype workin'. Mind givin' me a hand? Maybe when we're done you can like, sell 'em to kids or somethin'.",objectivesText="Help Hobart calibrate the Prototype Gravitational Reduction Slippers around Dalaran. Progress: This is gonna be fun... to watch!",rewardItems={151927},starts={{npcID=93539}},ends={{npcID=93539}},mapCandidates={npc={},zone={7502}},questGiverID=93539,questTurnInID=93539,questType="standard",sourceQuests={48069},questLines={{id=359,name="Legion Engineering",orderIndex=0,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=627},
[48065] = {id=48065,name="Extraterrestrial Exploration",level=45,requiredLevel=45,faction="both",requiredProfessions={"engineering"},categories={},flags={},sharable=true,expansion=7,zoneID=7502,mapID=627,storyline={48056,48065,48069},series={48069},description="<name>, I hear you've been over to that large green planet in the sky already. Swarming with demons too, I hear. I was thinking maybe we could put together another wormhole generator for it. Make it easier to zip around the planet. Problem is we need to get readings on the landscape, and I'd go, but uh... well I need to stay here and run the shop. Can't leave it to these bozos to handle. Here, take this and get some readings for me, will ya?",objectivesText="Use the Ionized Geographical Recorder at the locations marked on your map. Return to Didi when you're finished.",rewardItems={151926},starts={{npcID=93520}},ends={{npcID=93520}},mapCandidates={npc={},zone={7502}},questGiverID=93520,questTurnInID=93520,questType="standard",sourceQuests={48069},questLines={{id=359,name="Legion Engineering",orderIndex=1,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=627},
[48066] = {id=48066,name="A Feast for Our Kin",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=1637,mapID=85,storyline={41764,41799,41800,41815,41840,41841,41882,41884,48066,48067,48079,48185,48190,48403,48433,48434,48435,49756},description="Ah, the Highmountain tauren. They have been our allies ever since we felled the Legion. Are you interested in hearing how they joined the Horde? It is quite the tale! It all began with Baine Bloodhoof and Mayla Highmountain. Baine was hosting a great feast in Thunder Bluff to welcome the Highmountain tauren...",objectivesText="Meet Baine Bloodhoof at Thunder Bluff in Mulgore.",rewardGold=341600,rewardXP=5465,starts={{npcID=125285},{npcID=133523}},ends={{npcID=93844}},mapCandidates={npc={85,88},zone={1637}},questType="standard",sourceQuests={50242},questLines={{id=377,name="Allies of the Horde: Highmountain",orderIndex=8,flags=0}},db2PoiMapID=1,db2PoiUiMapID=88},
[48067] = {id=48067,name="Shadow Over Thunder Bluff",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=1638,mapID=88,storyline={41764,41799,41800,41815,41840,41841,41882,41884,48066,48067,48079,48185,48190,48403,48433,48434,48435,49756},series={48079,49756},description="A dark force has descended upon us. I refuse to believe that the Highmountain are behind it. The cacophony out there is disturbingly familiar. Could it be... No! The minions of the Old Gods are attacking! We must fight for Thunder Bluff, <name>!",objectivesText="Slay 4 Dark Tendrils and 12 Shadows of Uul in Thunder Bluff. Progress: For the Old Gods to manifest even these fledgling minions is troubling.",rewardGold=312800,rewardXP=5465,starts={{npcID=129914}},ends={{npcID=129914}},mapCandidates={npc={88},zone={1638}},questTurnInID=129914,questType="standard",sourceQuests={48066},questLines={{id=377,name="Allies of the Horde: Highmountain",orderIndex=9,flags=0}},db2PoiMapID=1,db2PoiUiMapID=88},
[48069] = {id=48069,name="The Wrench Calls",level=45,requiredLevel=45,faction="both",requiredProfessions={"engineering"},categories={},flags={},sharable=true,expansion=7,zoneID=8899,mapID=627,storyline={48056,48065,48069},series={48065},description="<name>, Didi the Wrench is looking for you back in Dalaran. You might want to see what she's working on. Pretty fancy stuff from what I heard.",objectivesText="Meet with Didi the Wrench in Dalaran.",starts={{npcID=125525}},mapCandidates={npc={},zone={8899}},questGiverID=125525,questType="standard",sourceQuests={46941},questLines={{id=359,name="Legion Engineering",orderIndex=2,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=627},
[48070] = {id=48070,name="The Norwington Festival",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48070},series={48077,51199},description="To whomever receives this invitation, You are cordially invited to the 15th annual Norwington Equestrian and Hunt Festival! People of all walks of life from across Kul Tiras shall gather to delight in life's greatest competitions, equestrianism and hunting, while meeting those of like minds and fine tastes. Hunting events shall start first, led by Abbey Watkins in Foxhollow Woods. They shall be followed by equestrian events at the Norwington Estate. We hope to see you there posthaste!",objectivesText="Meet Abbey Watkins at the edge of Foxhollow Woods.",rewardGold=128700,rewardXP=710,rewardItems={151913,152109,152642,152643,152670,152671,152675,152678,153357},ends={{npcID=125309}},startObjects={{objectID=281230,mapID=895,x=0.671,y=0.248}},coords={mapID=895,source="quest_giver",x=0.554,y=0.246},mapCandidates={npc={895},zone={8567}},questType="standard",nextQuests={48077,48080,48616}},
[48074] = {id=48074,name="Looming Over Me",level=45,requiredLevel=45,faction="both",requiredProfessions={"tailoring"},categories={},flags={},sharable=true,expansion=7,zoneID=8899,mapID=887,storyline={48074},description="When I rallied to the Xenedar, I left behind a valuable tool. My lightweave loom . Without it, I'm forced to labor for much longer to make garments of power for our allies. But you are powerful, much more so than I. Perhaps you could do me a favor. Should you happen to be in the Arinor Gardens, could you retrieve my loom and return it to me? I'd be more than willing to share my knowledge of sewing lightweave with you.",objectivesText="Go to the Arinor Gardens and retrieve Khaela 's Lightweave Loom . Progress: Any luck in finding my loom?",rewardItems={151874},startObjects={{mapID=884,x=0.428,y=0.618}},endObjects={{mapID=884,x=0.428,y=0.618}},coords={mapID=884,x=0.428,y=0.618},mapCandidates={npc={},zone={8899}},questType="standard",sourceQuests={46941},questLines={{id=363,name="Legion Tailoring",orderIndex=0,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=887},
[48075] = {id=48075,name="A Colorful Key",level=45,requiredLevel=45,faction="both",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8899,mapID=887,storyline={48075,48076},description="<name>, I hear you're a jewelcrafter. I too am a master cutter, but I fear my designs will be lost to the Legion. I hurried out of my home with the intention of returning, but I fear that may not be a possibility. You see, I left my most prized possession, a book of jewelcrafting designs. But you, you're strong, you could fight your way into my home and recover my book! However, I locked it away in a special chest that requires the gems of this land to unlock. You'll need one of each to open it.",objectivesText="Travel to Vorel 's home and unlock his chest using each of the six gems that come from prospecting empyrium. Recover his jewelcrafting book and return to him on the Vindicaar. Progress: The combination isn't that difficult, just put the gems in their appropriate settings.",rewardItems={151564,151568,151579,151580,151583,151584,151585,151718,151719,151720,151721,151722,151876,152726},starts={{npcID=125343}},ends={{npcID=125343}},mapCandidates={npc={},zone={8899}},questGiverID=125343,questTurnInID=125343,questType="standard",sourceQuests={46941},questLines={{id=361,name="Legion Jewelcrafting",orderIndex=0,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=887},
[48076] = {id=48076,name="A Crowning Achievement",level=45,requiredLevel=45,faction="both",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8899,mapID=887,storyline={48075,48076},description="With my book nearly being lost forever, it occurs to me that I shouldn't keep all this knowledge in one place. I would like to pass it along to you, <name>. My most recent designs are ones that I am particularly proud of. I call them Empyrial Crowns . Each one uses a different combination of gems to render different effects of power. Let me show you how to construct one and then I'll show you how different combinations of gems create different results.",objectivesText="Craft an Empyrial Crown for Vorel . You can find the materials from gathering and prospecting the ore from Argus, from other players, or from the auction house. Progress: Perhaps in time you too will find a student whom you may pass all your knowledge unto.",rewardItems={151568,151587,151588,151589,151590,151878},starts={{npcID=125343}},ends={{npcID=125343}},mapCandidates={npc={},zone={8899}},questGiverID=125343,questTurnInID=125343,questType="standard",sourceQuests={48075},questLines={{id=361,name="Legion Jewelcrafting",orderIndex=1,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=887},
[48077] = {id=48077,name="The Stoat Hunt",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48003,48004,48005,48077,48080,48087,48088,48089,48195,48196,48597,48616,48670},series={48070,51199},description="One of the greatest hunting sports amongst the nobles of Boralus is the stoat hunt. It is a sport of determination, patience, and skill. Do you think you can rise to the challenge? Stoats are agile, sneaky, and sharp. They're next to impossible to catch out in the forest, so the best way to find one is to find its burrow and scare it out. Find their burrows and bring back their pelts. Their fur is soft and much loved amongst the nobles.",objectivesText="Collect 5 Soft Stoat Pelts from Faintstep Stoats. Progress: Have you collected enough stoat pelts?",rewardGold=257400,rewardXP=1415,rewardItems={151913,152109,152642,152643,152670,152671,152675,152678,153357,158246,158247,158248,158249,158276,158277,158278,158279},rewardChoices={158247,158249,158248,158246,158276,158279,158278,158277},starts={{npcID=125309}},ends={{npcID=125309}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48070},questLines={{id=591,name="The Norwington Estate",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48078] = {id=48078,name="Counterbalancing",level=45,requiredLevel=45,faction="both",requiredProfessions={"leatherworking"},categories={},flags={},sharable=true,expansion=7,zoneID=8574,mapID=887,storyline={48078},description="In the past, I was able to make glorious items from the beasts of this land. But then the Legion came and wiped out all those amazing beasts. Now I'm forced to use their polluted hides to craft armor for my allies. I have, however, found a way to remove their taint. The cloth we use is made from special thread infused with Light energy. I devised an oil which when combined with the cloth purifies the leather and makes it usable. Here, take my oil and see for yourself.",objectivesText="Gather Fiendish Leather and Lightweave Cloth and use Enstraa's Tanning Oil to create 12 Purified Fiendish Leather . Progress: I often dream of working with unsullied leather again. But who knows when that will ever be...",rewardItems={151566,151567,151568,151879,151880},starts={{npcID=125349}},ends={{npcID=125349}},mapCandidates={npc={},zone={8574}},questGiverID=125349,questTurnInID=125349,questType="standard",sourceQuests={47743},questLines={{id=362,name="Legion Leatherworking",orderIndex=0,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=887},
[48079] = {id=48079,name="Return to Highmountain",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=7503,mapID=750,storyline={41764,41799,41800,41815,41840,41841,41882,41884,48066,48067,48079,48185,48190,48403,48433,48434,48435,49756},series={48067,49756},description="Spiritwalker Ebonhorn remains in great danger. He and Mayla have returned to Highmountain, but I believe they still need our aid. Let us journey to Thunder Totem and do whatever we can to mend Ebonhorn. Perhaps our deeds will strengthen the bond between our peoples.",objectivesText="Meet Mayla Highmountain at Thunder Totem in Highmountain.",rewardGold=250380,rewardXP=5465,starts={{npcID=130773}},ends={{npcID=130773}},mapCandidates={npc={},zone={7503}},questGiverID=130773,questTurnInID=130773,questType="standard",sourceQuests={49756},questLines={{id=377,name="Allies of the Horde: Highmountain",orderIndex=10,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=750},
[48080] = {id=48080,name="An Element of Danger",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48003,48004,48005,48077,48080,48087,48088,48089,48195,48196,48597,48616,48670},description="These nobles really think killing weasels is the mark of a good hunter? Ha! It ain't hunting if there isn't a bit of danger involved. There are boars in these woods. That's more our speed out in the mountains! Why don't you kill some of those, then bring me their tusks as proof?",objectivesText="Collect 8 Rugged Boar Tusks . Progress: Boars actually present some semblance of challenge to the hunter.",rewardGold=257400,rewardXP=1415,rewardItems={151913,152109,152642,152643,152670,152671,152675,152678,153357},starts={{npcID=125398}},ends={{npcID=125398}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48070},questLines={{id=591,name="The Norwington Estate",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48081] = {id=48081,name="A Floating Ruin",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=883,storyline={46815,46818,46834,46941,47066,47685,47686,47687,47688,47689,47690,47882,47883,48081,48107},description="We knew the Legion to be a formidable foe, but recent events demonstrate that we do not possess the necessary strength to continue. We have come too far to fail at this critical moment. I know of a relic on Eredath , my ancient home, that may be our salvation. We must take the Vindicaar beyond the surface of Argus, to the floating ruin suspended above us. Perhaps there we will find the salvation we so desperately need.",objectivesText="Travel to Eredath .",rewardGold=50550,rewardXP=770,starts={{npcID=126307}},ends={{npcID=126307}},mapCandidates={npc={},zone={8899}},questGiverID=126307,questTurnInID=126307,questType="standard",sourceQuests={47994},questLines={{id=366,name="The Crown of the Triumvirate",orderIndex=0,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=366,questLineOrder=5,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=883},
[48087] = {id=48087,name="Equine Retrieval",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48003,48004,48005,48077,48080,48087,48088,48089,48195,48196,48597,48616,48670},series={48088},description="I like the cut of your jib, friend! I'll tell you what. The rest of the partygoers should be arriving any time now. Would you do me the honor of retrieving my favorite horse from the estate on the hill? Imagine, our guests' first impression of you to be on the most regal horse in all of Tiragarde! Wondrous!",objectivesText="Retrieve Lord Norwington's favorite horse Rose from his hilltop estate. Progress: <name>! The troggs have invaded!",rewardGold=128700,rewardXP=710,rewardItems={151913,152109,152642,152643,152670,152671,152675,152678,153357},starts={{npcID=124802}},ends={{npcID=127559}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48004},questLines={{id=591,name="The Norwington Estate",orderIndex=10,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48088] = {id=48088,name="No Party Like a Trogg Party",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48003,48004,48005,48077,48080,48087,48088,48089,48195,48196,48597,48616,48670},series={48087},description="Troggs? At my party? My grandfather pushed them back to that cleft years ago to build this estate. To think that they would attack in such force after all these years? This is just what we needed to make this year's festival the greatest ever! Show us your heroism firsthand, <name>! Mount Cooper and defeat these troggs! Drag them behind you, jab them with your harpoon... whatever it takes!",objectivesText="Kill 20 Grimestone troggs in Norwington Estate.",rewardGold=257400,rewardXP=1415,rewardItems={151913,152109,152642,152643,152670,152671,152675,152678,153357,155054,155062,155065,155068,155070,155075,155076,158294,158297},rewardChoices={155065,155068,155075,155054,155070,155062,155076,158297,158294},starts={{npcID=127559}},ends={{npcID=127559}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48087},questLines={{id=591,name="The Norwington Estate",orderIndex=11,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48089] = {id=48089,name="Mountain Sounds",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48003,48004,48005,48077,48080,48087,48088,48089,48195,48196,48597,48616,48670},description="Kul Tirans won't go down without a fight! Take this horn. We use it in the mountains to warn each other of danger and lead the charge into battle. Use it to rally our allies against the troggs!",objectivesText="Use the Horn of the Mountain to rally 8 Kul Tirans. Progress: We are stronger together!",rewardGold=89550,rewardXP=1415,rewardItems={151913,152109,152642,152643,152670,152671,152675,152678,153357,252392},starts={{npcID=125042}},ends={{npcID=125042}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48087},questLines={{id=591,name="The Norwington Estate",orderIndex=12,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48090] = {id=48090,name="Krag'wa's Chosen",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48090},description="Dis be a real mess, <name>. Da naga be drainin' da magic of Krag'wa's frogs ta feed demselves! Dere be three frogs, Krag'wa's champions, dat dey be torturin' as we speak. Take dis potion, it be returnin' da power of dem noble frogs. Dey deserve better dan bein' drained by dese snake bastards. I be stayin' here. Da naga got in some lucky hits on me. All me life, I wanted ta see Krag'wa, and I let meself get hurt by some naga!",objectivesText="Rescue Krol'dra the Wise , Wok'grug the Clever , and Wag'shash the Bold .",rewardGold=257400,rewardXP=2765,rewardItems={158071},starts={{npcID=125317}},ends={{npcID=125317}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47918}},
[48091] = {id=48091,name="Vagath the Betrayed",level=45,requiredLevel=45,faction="none",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={48091},rewardGold=606600,rewardXP=9210,starts={{npcID=125388,mapID=830,x=0.6084,y=0.1974}},mapCandidates={npc={},zone={8574}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=125388}},worldTaskTitle="Vagath the Betrayed",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[48092] = {id=48092,name="Vengeance of the Frogs",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48092},description="Da naga here be led by a priestess, Zaldraxia. She be da one dat figured out how ta drain da frogs of their magic. Zaldraxia be stoppin' at nothin' ta drain every frog here. Do what I could not, and kill dis priestess. Show da naga dat Krag'wa ain't a loa ta be takin' lightly. I be prayin' ta Krag'wa for ya success.",objectivesText="Defeat Priestess Zaldraxia .",rewardGold=514800,rewardXP=3455,rewardCurrencies={{id=1553,amount=100}},starts={{npcID=125317}},ends={{npcID=125317}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47918}},
