[48106] = {id=48106,name="No Love Lost",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={48106},objectivesText="Shadowguard slain",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8701}},questType="world",db2Objectives={{text="Shadowguard slain",amount=13,type=0,objectID=121670,orderIndex=0}},worldTaskTitle="No Love Lost",db2PoiMapID=1669,db2PoiUiMapID=882,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[48107] = {id=48107,name="The Sigil of Awakening",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={46815,46818,46834,46941,47066,47685,47686,47687,47688,47689,47690,47882,47883,48081,48107},description="This relic is too powerful to keep it out in the open. We must return to the Vindicaar at once. The Prophet will know what to do. I did want to thank you, <name>. Without you this would not be possible. Quoram would have ensured I never got near the Sigil. Perhaps some day I will share that story with you.",objectivesText="Return to the Vindicaar and secure the Sigil of Awakening. Progress: Did you recover the Sigil of Awakening?",rewardGold=202200,rewardXP=6140,rewardItems={151476},starts={{npcID=123413}},ends={{npcID=120533}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={47690},questLines={{id=366,name="The Crown of the Triumvirate",orderIndex=14,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=366,questLineOrder=5,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2LabelIDs={4784},db2PoiMapID=1669,db2PoiUiMapID=886},
[48108] = {id=48108,name="The Waycrest Daughter",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={"loremaster"},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="You seek House Waycrest? Oh, your timing could not be worse! I had just received a raven regarding Lord Waycrest's daughter, Lucille, shortly before this... curse came upon us. They apprehended her in Fletcher's Hollow and are taking her to trial. They say she is a witch, herself! If she's found guilty, she will surely hang! You must make haste to Hangman's Point. With what you've seen here, maybe you can convince them of her innocence.",objectivesText="Meet with Constable Henry Framer at Hangman's Point in Drustvar .",rewardGold=30900,rewardXP=345,rewardItems={151934,151935},starts={{npcID=124417}},ends={{npcID=125394}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={47982},questLines={{id=382,name="Hangman's Point",orderIndex=0,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=7,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48109] = {id=48109,name="The Woods Have Eyes",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="The sooner I can return the lady Waycrest to Highroad Gate the better, but I will honor her wishes if we can assure her safety. There are dark things happening in these lands that you don't fully understand. If we must dally, then there are measures that need be taken. First, the wildlife here can serve as eyes to dark powers. Kill them.",objectivesText="Kill 4 Watchful Ravens and 6 Darkmaw Prowlers in the Watchman's Wood. Progress: Has our foe been sufficiently blinded?",rewardGold=309800,rewardXP=2765,rewardItems={151934,151935},rewardCurrencies={{id=1553,amount=50}},starts={{npcID=125385}},ends={{npcID=125385}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48283},questLines={{id=382,name="Hangman's Point",orderIndex=2,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=9,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48110] = {id=48110,name="In Case of Ambush",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="There is more to worry about in these woods than simple beasts. Our enemy employs constructs of wicker and bone that can rip a man apart. Fortunately for us, these constructs are not very perceptive. Take these traps and set them up throughout the woods behind us. If our enemies do seek to ambush us here, at least these will slow their minions down.",objectivesText="Place 6 traps in the Watcher's Wood. Progress: We must be prepared. Anywhere can harbor an ambush here.",rewardGold=309800,rewardXP=2765,rewardItems={151934,151935},starts={{npcID=125385}},ends={{npcID=125385}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48283},questLines={{id=382,name="Hangman's Point",orderIndex=3,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=10,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48111] = {id=48111,name="Trial by Superstition",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="Witchcraft has long lived in the superstitions of the people here. It is only recently that some of these superstitions have become reality. According to tradition, one who is tried for witchcraft is allowed to choose the means by which they are tested from among the requests of her peers. The villagers here no doubt have some strange beliefs of what witches can and cannot do. Speak with them, and see what we can do to prove my innocence.",objectivesText="Question 5 Fletcher's Hollow Villagers in Hangman's Point. Progress: What have you learned from the villagers?",rewardGold=154900,rewardXP=1385,rewardItems={151934,151935},starts={{npcID=125380}},ends={{npcID=125380}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48109,48110},questLines={{id=382,name="Hangman's Point",orderIndex=4,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=11,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48113] = {id=48113,name="A Pungent Solution",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="The first test should be simple enough. While I may not do so often, I am certainly capable of crying. Though to be honest, I've never had to cry on cue. Maybe you could help with that, though. Nearby there is an onion field that belonged to one of the local farmers. It's abandoned, and most of it is dried up by now, but you might be able to find one onion ripe enough in there to cause some tears.",objectivesText="Collect a Juicy Onion from Hawthorne's Plot near Hangman's Point. Progress: Have you had any luck at the onion field?",rewardGold=257400,rewardXP=2765,rewardItems={151934,151935},starts={{npcID=125380}},ends={{npcID=125380}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48111},questLines={{id=382,name="Hangman's Point",orderIndex=5,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=12,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48165] = {id=48165,name="Harmful If Swallowed",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="This last test I am not looking forward to, but it is certainly better than being set on fire. They say that a witch can't get sick. We will prove to them that I can. A venom comes from the saurolisks nearby that is used by our healers when a child swallows something they shouldn't. When ingested, it will make you immediately ill, emptying the contents of the stomach. You'll need several of their venom glands to get enough venom for an appropriate dose. Removing them intact may prove difficult.",objectivesText="Collect 5 Intact Venom Glands from the Shallows Saurolisks near Hangman's Point. Progress: Is the deed done?",rewardGold=309800,rewardXP=2765,rewardItems={151934,151935},starts={{npcID=125380}},ends={{npcID=125380}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48111},questLines={{id=382,name="Hangman's Point",orderIndex=7,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=14,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48170] = {id=48170,name="Once Bitten, Twice Shy",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="I am all too familiar with the bloodfly's bite. We had them all over the fields surrounding Waycrest Manor. Though I'm loath to subject myself to them on purpose, if it will help convince these people, I am willing to deal with that nuisance. Find a jar and collect as many bloodflies as you can. They are common in these parts, and shouldn't be hard to find.",objectivesText="Find an Empty Jar and use it to catch 6 Hovering Bloodflies near Hangman's Point.",rewardGold=257400,rewardXP=2765,rewardItems={151934,151935},starts={{npcID=125380}},ends={{npcID=125380}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48111},questLines={{id=382,name="Hangman's Point",orderIndex=6,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=13,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48171] = {id=48171,name="The Curse of Fletcher's Hollow",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="It's obvious the constable won't be swayed until we discover what happened at Fletcher's Hollow. I know very little myself--only that the village has been overrun by monstrous creatures. I must ask that you travel there in my stead and try to uncover what befell the village. I'm sure Marshal Reade will prevent the constable from harming me while you're away. Do this for me, and I will help you as I can.",objectivesText="Speak with Evelyn Pare at the Timbered Strand in Drustvar .",rewardGold=30900,rewardXP=345,rewardItems={152587,152590},starts={{npcID=125380}},ends={{npcID=126310}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48198},questLines={{id=383,name="Fletcher's Hollow",orderIndex=0,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=17,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48175] = {id=48175,name="Hidden in the Hollows",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={48175},objectivesText="Enter the Void Tear Ethereal activities disrupted",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8701}},questType="world",db2Objectives={{text="Enter the Void Tear",amount=1,type=0,objectID=127500,orderIndex=0},{text="Ethereal activities disrupted",amount=8,type=0,objectID=127498,orderIndex=1}},worldTaskTitle="Hidden in the Hollows",db2PoiMapID=1669,db2PoiUiMapID=882,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[48176] = {id=48176,name="Big Trouble in Little Tortolla",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={48176},series={46846},description="I received a message asking for a sword hand in Little Tortolla. The Tortollan Seekers there are greatly admired by King Rastakhan and have special privileges assigned to them. Go see what they want and you will have the favor of the King. And $p, be respectful. Tortollans live long enough they can hold your children's children accountable for your actions.",objectivesText="Speak with Toki in Little Tortolla.",rewardGold=23870,rewardXP=175,mapCandidates={npc={},zone={8499}},questType="standard"},
[48179] = {id=48179,name="Rescue Rangers",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48179,48180,48182,48183,52074,52075,53110},description="We're barely holding off those monsters here. If it hadn't been for the Thornspeakers, we'd surely be dead. I was worried Rebecca hadn't made it! You've brought Rebecca's supplies just in time. We have many injured out in the field, Thornspeaker, ranger, and companion alike. I'll hold the line here. Go into the ruins and heal as many of the wounded as you can!",objectivesText="Save 10 injured Thornspeakers , rangers, and pets.",rewardGold=257400,rewardXP=2765,rewardItems={155466,155474,155482,155490,158607,158608,158609,158610},rewardChoices={158607,158608,158609,158610,155466,155474,155482,155490},starts={{npcID=139912}},ends={{npcID=139912}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={52074},questLines={{id=5441,name="Drustvar Ruins",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48180] = {id=48180,name="Really Big Problem",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48179,48180,48182,48183,52074,52075,53110},description="Hey! Mainlander! I know I'm supposed to be trying to knock over cairns and hauling out lost rangers, but d'you see that massive stone monster? I'm thinking that's gonna be a problem. You look like you know how to handle yourself. Think between the two of us we can take it down?",objectivesText="Defeat the Ancient Sentinel .",rewardGold=486720,rewardXP=3455,starts={{npcID=140048}},ends={{npcID=139926}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48622,52074},questLines={{id=5441,name="Drustvar Ruins",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48181] = {id=48181,name="Nooooope",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={48181},objectivesText="Kill spiders and egg sacs",rewardGold=455280,rewardXP=1415,mapCandidates={npc={},zone={8721}},questType="standard",db2Objectives={{text="Kill spiders and egg sacs",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Nooooope",db2PoiMapID=1643,db2PoiUiMapID=896},
[48182] = {id=48182,name="Total Cairnage",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48179,48180,48182,48183,52074,52075,53110},description="My mentor sensed the activation of ancient powers here. We came to stop them but were too late. We banded together with the rangers for mutual protection, but our task remains unfinished. There is a set of ancient cairns here. These help empower the Drust constructs. Destroying them will also help to settle the undead stirring from the land. Destroy the cairns and we'll be able to bring sanity to this place.",objectivesText="Destroy the Ancient Cairns. Progress: Power within those cairns does not bode well for anyone in Drustvar .",rewardGold=241020,rewardXP=2765,starts={{npcID=139926}},ends={{npcID=139926}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={52074},questLines={{id=5441,name="Drustvar Ruins",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48183] = {id=48183,name="The Hills Are Alive",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48179,48180,48182,48183,52074,52075,53110},description="The Drust constructs are drawn from the land, but the heart of these constructs is a runic power core . We have been trying to collect and destroy as many of these cores as we can. We know of a way to disrupt the magic in the core. Doing so will prevent more of these monstrosities from being created around the dark hearts and protect the land and all living in this region. Bring me as many Runic Power Cores as you can find and the Thornspeakers will see they are put to good use.",objectivesText="Collect 6 Runic Power Cores from Awoken Guardians. Progress: We would appreciate any runic power cores from the Awoken Guardians you might find.",rewardGold=241020,rewardXP=2765,rewardItems={152394},starts={{npcID=139926}},ends={{npcID=139926}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={52074},questLines={{id=5441,name="Drustvar Ruins",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48184] = {id=48184,name="Pieces of History",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48184,48504,48517,49890,49896},description="There is an opportunity here. Learning more about the Drust can not only help us understand the texts that Lady Lucille found, we might be able to discover greater details about how they and their constructs were finally defeated. Filling in the gaps of history could be key to victory now. This was one of their settlements before it became the place of their final defeat. Let's look for clues in the ruins.",objectivesText="Search the ruins for information about the Drust.",rewardGold=257400,rewardXP=2765,starts={{npcID=129983}},ends={{npcID=129983}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48504},questLines={{id=600,name="Gol Osigr",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48185] = {id=48185,name="Shadow of the Sepulcher",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=7503,mapID=650,storyline={41764,41799,41800,41815,41840,41841,41882,41884,48066,48067,48079,48185,48190,48403,48433,48434,48435,49756},series={41764,41799,41800,41884,48190,48434,48435},description="Ebonhorn spoke of another ward safeguarding the lands of the Skyhorn tribe. Somewhere close to the Sepulcher of the Sky, he said. It was there that this \"Darkness\" once manifested. Meet me there, <name>. I will show you how to walk in the memories of a great Skyhorn hero.",objectivesText="Meet Spiritwalker Graysky in Sepulcher of the Sky.",rewardGold=303800,rewardXP=5465,starts={{npcID=125454}},ends={{npcID=125459}},mapCandidates={npc={650},zone={7503}},questType="standard",sourceQuests={41764},questLines={{id=377,name="Allies of the Horde: Highmountain",orderIndex=11,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=650},
[48190] = {id=48190,name="Huln's Mountain",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=7503,mapID=650,storyline={41764,41799,41800,41815,41840,41841,41882,41884,48066,48067,48079,48185,48190,48403,48433,48434,48435,49756},series={41764,41799,41800,41884,48185,48434,48435},description="We have made progress reactivating the wards, but more must be done. I sense Ebonhorn's struggle. Though he fights with all his strength, he is slipping away. Should this \"Darkness\" emerge into our realm, I fear our friend will be lost. Ebonhorn spoke of another ward somewhere within Snowblind Mesa. Meet me there, so that I might guide you along another journey into the memories of the past.",objectivesText="Meet Spiritwalker Graysky at Snowblind Mesa.",rewardGold=312800,rewardXP=5465,starts={{npcID=125459}},ends={{npcID=125466}},mapCandidates={npc={650},zone={7503}},questType="standard",sourceQuests={41799},questLines={{id=377,name="Allies of the Horde: Highmountain",orderIndex=12,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=650},
[48192] = {id=48192,name="Tar Spitter",level=45,requiredLevel=45,faction="none",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={48192},rewardGold=606600,rewardXP=9210,mapCandidates={npc={},zone={8574}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=125479}},worldTaskTitle="Tar Spitter",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[48195] = {id=48195,name="Troublesome Troglodytes",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48003,48004,48005,48077,48080,48087,48088,48089,48195,48196,48597,48616,48670},description="Troggs are base creatures. They barely have any brain process, living mostly on survival instinct alone. They are pests through and through, and need to be dealt with. The fewer of them there are, the better.",objectivesText="Kill 8 Grimestone Bullies and 3 Grimestone Throwers in Mistfall Cleft.",rewardGold=257400,rewardXP=1415,rewardItems={151913,152109,152642,152643,152670,152671,152675,152678,153357},starts={{npcID=127144}},ends={{npcID=127144}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48670},questLines={{id=591,name="The Norwington Estate",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48196] = {id=48196,name="Following Eddie's Trail",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48003,48004,48005,48077,48080,48087,48088,48089,48195,48196,48597,48616,48670},description="My life is equestrian. I'm not a fighter. I could maybe take a trogg or two, but not a whole tribe. Please, go into Mistfall Cleft and see if you can find Eddie. Lord Norwington would be furious if something happened to him, and nobody wants to bear witness to that!",objectivesText="Follow the trail of Eddie Norwington . Progress: Are... are you here to save me?",rewardGold=772200,rewardXP=1770,rewardItems={151913,152109,152642,152643,152670,152671,152675,152678,153357},starts={{npcID=127144}},ends={{npcID=127091}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48670},questLines={{id=591,name="The Norwington Estate",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48198] = {id=48198,name="The Burden of Proof",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="I think we have everything we need to conduct three of the villagers' tests. Let us hope this is enough to convince them. I'm sure Constable Framer is champing at the bit to proceed with his trial, and I would prefer it if you were the one to administer the tests. I may not know you well, but I trust you farther than the constable. Speak with him when you're ready to begin. ...and do me a favor. Make this quick.",objectivesText="Administer the tests to prove Lucy Waycrest's innocence in Hangman's Point.",rewardGold=25740,rewardXP=345,rewardItems={151934,151935,155100,155101,155102,155103,155570},rewardChoices={155102,155100,155103,155101,155570},starts={{npcID=125380}},ends={{npcID=125380}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48113,48165,48170},questLines={{id=382,name="Hangman's Point",orderIndex=9,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=15,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48199] = {id=48199,name="The Burning Heart",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8899,mapID=886,storyline={47473,48199,48200,48201,48202,48929},description="The loss of Xe'ra is a blow, especially to Turalyon. But even the Light Mother could not be allowed to force destiny upon us. I wish Illidan had found another way to refuse her... but I too have had choices imposed upon me by the naaru. This must not distract us from our mission. Now that we have the Army of the Light survivors with us, it is time to press our attack. We need a foothold on the Antoran Wastes from which we can assault the Burning Throne. It is time to deprive Sargeras of his prize!",objectivesText="Use the Navigation Console to travel to the Antoran Wastes .",rewardGold=50550,rewardXP=6140,starts={{npcID=126307}},ends={{npcID=126307}},mapCandidates={npc={},zone={8574}},questGiverID=126307,questTurnInID=126307,questType="standard",sourceQuests={48559},questLines={{id=371,name="The Heart of Argus",orderIndex=0,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=371,questLineOrder=3,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=886},
[48200] = {id=48200,name="Securing a Foothold",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8899,mapID=886,storyline={47473,48199,48200,48201,48202,48929},description="Alleria and I have scouted this area before, alongside some of our best soldiers. We stationed encampments on either side of our current position, but I fear they will have come under heavy attack. They need reinforcements. Our first order of business is to set up a teleportation beacon directly below the Vindicaar. From there, we will have access to both fronts. Speak to Romuul when you are ready to head down to the surface.",objectivesText="Travel to the Antoran Wastes and place the Lightforged Beacon. Progress: We need that teleportation beacon set up if we are to reinforce our positions.",rewardGold=20220,rewardXP=6140,starts={{npcID=126954}},ends={{npcID=126954}},mapCandidates={npc={},zone={8899}},questGiverID=126954,questTurnInID=126954,questType="standard",sourceQuests={48199},questLines={{id=371,name="The Heart of Argus",orderIndex=1,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=371,questLineOrder=3,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=886},
[48201] = {id=48201,name="Reinforce Light's Purchase",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8899,mapID=885,storyline={47473,48199,48200,48201,48202,48929},description="Now that we have established a foothold, we need to rendezvous with our soldiers in the field. We have an Army of the Light encampment to the south, near where the Legion is keeping their strongest warriors in some sort of stasis. Alleria went to scout the area. Find her, and see what information she has gathered.",objectivesText="Speak with Alleria at Light's Purchase. Progress: The camp lies to the south. When you find the large stasis capsules, look for a passage on the left.",rewardGold=50550,rewardXP=6140,starts={{npcID=126954}},ends={{npcID=127033}},mapCandidates={npc={885},zone={8899}},questGiverID=126954,questType="standard",sourceQuests={48200},questLines={{id=371,name="The Heart of Argus",orderIndex=2,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=371,questLineOrder=3,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=885},
[48202] = {id=48202,name="Reinforce the Veiled Den",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8899,mapID=885,storyline={47473,48199,48200,48201,48202,48929},description="The foothold you established allows us to check in with our field operatives. On our last mission here, we set up a bastion to the northeast. It should be defensible for now, but that could change at any moment. Illidan has gone ahead to assess the situation. I suggest you go there and see if he needs a hand.",objectivesText="Speak with Illidan at the Veiled Den. Progress: The camp lies to the northeast. It may appear hidden at first glance, but you can find the Light shining in the darkest places.",rewardGold=50550,rewardXP=6140,starts={{npcID=126954}},ends={{npcID=127051}},mapCandidates={npc={885},zone={8899}},questGiverID=126954,questType="standard",sourceQuests={48200},questLines={{id=371,name="The Heart of Argus",orderIndex=3,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=371,questLineOrder=3,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=885},
[48203] = {id=48203,name="The Burning Throne",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8899,storyline={48203},description="The time has come, <name>, to begin our assault upon Antorus. Everything we have fought for, everything our friends and family have sacrificed, has brought us to this moment. We will fire Light's Judgment upon the walls of the accursed citadel and storm their seat of power. We will end the Legion. After all you have done, it is fitting that you have the honor. Activate the Crown of the Triumvirate and let us finish our mission.",objectivesText="Use the Crown of the Triumvirate while above the Antoran Wastes to open the way to Antorus. Progress: We have not come this far to stop now.",rewardGold=202200,rewardXP=6140,rewardItems={152626,152984,246936,249400,254267,254579,264675},starts={{npcID=124312}},ends={{npcID=124312}},mapCandidates={npc={},zone={8701}},questGiverID=124312,questTurnInID=124312,questType="standard",sourceQuests={47654}},
[48230] = {id=48230,name="Fragment of the Past",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={48230},description="Captain Fareeya would be able to tell you more about the crystal.>",objectivesText="Take the Glowing Key Fragment to Captain Fareeya .",rewardGold=101100,rewardXP=6140,rewardItems={142460,152204,152241,152242,152243,152244},mapCandidates={npc={},zone={8701}},questType="standard",sourceQuests={47654},startItems={152204}},
[48231] = {id=48231,name="The Seat of the Triumvirate: Armor of the Triumvirate",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8910,mapID=830,storyline={48231},description="This reforged key will grant entry into the armory inside the Seat of the Triumvirate . Locked away inside is the Armor of the Triumvirate , crafted in the days before Sargeras brought ruin to our world. We cannot let this armor be stolen by the Void's forces. Once the armor is in your possession, please bring it to Archivist Ionaa . He has collected our most sacred relics in the cave just up the path. No doubt he would be very glad to receive it.",objectivesText="Secure the Armor of the Light and bring it to Archivist Ionaa . Progress: Have you brought me something, <class>?",rewardGold=404400,rewardXP=7675,rewardItems={152202,152203,152204,152241,152242,152243,152244,152939},rewardChoices={152241,152242,152243,152244},starts={{npcID=125246}},ends={{npcID=125247}},mapCandidates={npc={830},zone={8574}},questType="dungeon",sourceQuests={48803}},
[48261] = {id=48261,name="The Power to Reforge",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8701,mapID=830,storyline={48261},description="I forged the key using a pristine argunite crystal. Unfortunately, the only ones remaining are used by the Army of the Light's defenses. Hmm... dendrite clusters might be an alternative. They were used by the elite of Eredath to power simple devices. If enough of the city ruins are still intact, I'd wager the fallen magi or the broken may still have some in their possession. Of course, I would need a great many clusters to reforge the key. It seems you have your work cut out for you.",objectivesText="Obtain a stockpile of Dendrite Clusters . Progress: Were you able to find enough clusters?",rewardGold=202200,rewardXP=6140,rewardItems={152200,152204,152241,152242,152243,152244,152937},starts={{npcID=125246}},ends={{npcID=125246}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={48864}},
[48271] = {id=48271,name="Recovering the Pieces",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8701,mapID=830,storyline={48271},description="The fragment you found is only one part of the key. I fear the other pieces have fallen into the hands of these ethereal beings you speak of... the Shadowguard. We must recover them all. The Shadowguard leaders and lieutenants in and around the Seat of the Triumvirate may well have the fragments in their possession. Get those key fragments, <name>... any way you have to.",objectivesText="Secure the missing key fragments from the ethereals around the Seat of the Triumvirate. Progress: Did you find all the fragments?",rewardGold=202200,rewardXP=6140,rewardItems={140394,152098,152201,152204,152241,152242,152243,152244,152938},starts={{npcID=125246}},ends={{npcID=125246}},mapCandidates={npc={830},zone={8574}},questType="group",sourceQuests={48864}},
[48272] = {id=48272,name="Visions of Fear",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={48272},description="I've done it, <lad/lass>. I've reached him again! Oh, but it's so painful. So painful! He's not doin' well, not one bit! You'll have to listen on in with me to understand.",objectivesText="Witness Argus' vision with Magni. Progress: It's a lot to take in, I know, but it might help us while we can still be helped.",rewardGold=50550,starts={{npcID=124595}},ends={{npcID=124595}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={48273}},
[48273] = {id=48273,name="The Speaker Listens",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={48273},description="Magni has sent for you in Krokul Hovel once more. He seems to have made a new breakthrough in trying to reach Argus. I suggest you find him immediately. His last vision foretold Aggramar's coming, and there is still so much we do not know of Sargeras' plans.",objectivesText="Meet Magni in the Krokul Hovel.",rewardGold=50550,starts={{npcID=124312}},ends={{npcID=124595}},mapCandidates={npc={830},zone={8574}},questGiverID=124312,questType="standard",sourceQuests={48560}},
[48277] = {id=48277,name="The Speaker Seeks",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={48277},description="Our forces are ready for battle, but we still do not know where Eonar's spirit lies. You should seek Magni out at once and see if you can find her while we still have a chance. If she falls, nothing we muster will be able stand against Sargeras.",objectivesText="Meet Magni in the Krokul Hovel.",rewardGold=50550,starts={{npcID=124312}},ends={{npcID=124595}},mapCandidates={npc={830},zone={8574}},questGiverID=124312,questType="standard",sourceQuests={48272}},
[48278] = {id=48278,name="Fate of the Life-Binder",level=1,requiredLevel=1,faction="both",sharable=false,expansion=7,zoneID=8574,mapID=830,description="I don't even want to think about what happens if Aggramar can find Eonar's spirit before we do. The fate of far more'n Azeroth may hinge on her safety. Let Turalyon know what we saw right away. We're going to need to bring all we can to bear to save her.",rewardGold=48500,mapCandidates={npc={},zone={8574}},questType="standard"},
[48280] = {id=48280,name="Visions of Another",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={48280},description="Whoever's tryin' to reach us now might give us the information we need to find Eonar. We need to see what's goin' on right away!",objectivesText="Witness Argus' vision with Magni. Progress: Eonar's still out there somewhere, but I don't know how much longer she'll last.",rewardGold=50550,starts={{npcID=124595}},ends={{npcID=124595}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={48277}},
[48282] = {id=48282,name="Imp Mother Laglath",level=45,requiredLevel=45,faction="none",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={48282},rewardGold=606600,rewardXP=9210,mapCandidates={npc={},zone={8574}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=125820}},worldTaskTitle="Imp Mother Laglath",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[48283] = {id=48283,name="Standing Accused",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="So you wish to speak with the accused? I see no reason why not. Be quick about it, though. I will not have our trial delayed. This woman will answer for the fate of our village!",objectivesText="Speak with Lucy Waycrest in Hangman's Point. Progress: What is your business here, mainlander?",rewardGold=30900,rewardXP=345,rewardItems={151934,151935},starts={{npcID=125394}},ends={{npcID=125385}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48108},questLines={{id=382,name="Hangman's Point",orderIndex=1,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=8,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48284] = {id=48284,name="Reap the Fields",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={48284},objectivesText="Attackers slain",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8574}},questType="world",db2Objectives={{text="Attackers slain",amount=30,type=0,objectID=123109,orderIndex=0}},worldTaskTitle="Reap the Fields",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[48285] = {id=48285,name="Aerial Superiority",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={48285},rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8574}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=30,objectID=122833}},worldTaskTitle="Aerial Superiority",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[48286] = {id=48286,name="Crystal Methods",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={48286},rewardGold=202200,rewardXP=6140,rewardItems={129749},mapCandidates={npc={},zone={8574}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=40,objectID=129749}},worldTaskTitle="Crystal Methods",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[48287] = {id=48287,name="Harvesters of Sorrow",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={48287},objectivesText="Western Soul Harvester destroyed Eastern Soul Harvester destroyed Northern Soul Harvester destroyed",rewardGold=238680,rewardXP=6140,mapCandidates={npc={},zone={8574}},questType="world",db2Objectives={{text="Western Soul Harvester destroyed",amount=1,type=0,objectID=126766,orderIndex=0},{text="Eastern Soul Harvester destroyed",amount=1,type=0,objectID=126784,orderIndex=1},{text="Northern Soul Harvester destroyed",amount=1,type=0,objectID=126785,orderIndex=2}},worldTaskTitle="Harvesters of Sorrow",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[48288] = {id=48288,name="Antoran High Command",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8638,mapID=739,storyline={48288},description="The Legion has spent over 10,000 years planning their invasion of Azeroth. Defeat their leaders so they can never threaten our world again.",objectivesText="Defeat the Antoran High Command in Antorus, the Burning Throne . Progress: Have you vanquished the enemy in Antorus?",rewardItems={152313,153501,153502,153503,153504},starts={{npcID=93787,mapID=24,x=0.5344,y=0.7863}},ends={{npcID=103023}},coords={mapID=739,source="quest_giver",x=0.4345,y=0.4665},mapCandidates={npc={739},zone={139}},questType="raid",startItems={152313}},
[48292] = {id=48292,name="The Soulhunter",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8638,mapID=739,storyline={48292},description="Imonar is the deadliest bounty hunter the Twisting Nether has ever produced. Find a pit to throw him down.",objectivesText="Defeat Imonar the Soulhunter in Antorus, the Burning Throne . Progress: Have you vanquished the enemy in Antorus?",rewardItems={152317,153501,153502,153503,153504},starts={{npcID=93787,mapID=24,x=0.5344,y=0.7863}},ends={{npcID=103023}},coords={mapID=739,source="quest_giver",x=0.4345,y=0.4665},mapCandidates={npc={739},zone={139}},questType="raid",startItems={152317}},
[48293] = {id=48293,name="The Burning Coven",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8638,mapID=739,storyline={48293},description="Not even a Titan can endure their torture. Bring an end to the Coven of Shivarra.",objectivesText="Defeat the Coven of Shivarra in Antorus, the Burning Throne . Progress: Have you vanquished the enemy in Antorus?",rewardItems={152321,153501,153502,153503,153504},starts={{npcID=93787,mapID=24,x=0.5344,y=0.7863}},ends={{npcID=103023}},coords={mapID=739,source="quest_giver",x=0.4345,y=0.4665},mapCandidates={npc={739},zone={139}},questType="raid",startItems={152321}},
[48294] = {id=48294,name="The Unmaker",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8638,mapID=739,storyline={48294},description="Argus is Sargeras' solution for existence; an end to all things. For everyone that might ever live, bring an end to the Unmaker.",objectivesText="Defeat Argus the Unmaker in Antorus, the Burning Throne . Progress: Have you vanquished the enemy in Antorus?",rewardItems={152325,153501,153502,153503,153504},starts={{npcID=93787,mapID=24,x=0.5344,y=0.7863}},ends={{npcID=103023}},coords={mapID=739,source="quest_giver",x=0.4345,y=0.4665},mapCandidates={npc={739},zone={139}},questType="raid",startItems={152325}},
