[48363] = {id=48363,name="Work Order: Florid Malachite",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=885,storyline={48363},objectivesText="Progress: Are you here to deliver supplies?",rewardItems={151568,151722},rewardCurrencies={{id=1220,amount=340}},starts={{npcID=128370}},ends={{npcID=128370}},mapCandidates={npc={885},zone={8899}},questType="standard",db2Objectives={{orderIndex=0,type=1,amount=1,objectID=151722}},worldTaskTitle="Work Order: Florid Malachite",db2PoiMapID=1669,db2PoiUiMapID=885,db2QuestInfoID=125,db2QuestInfoName="Jewelcrafting World Quest"},
[48364] = {id=48364,name="Work Order: Hesselian",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=885,storyline={48364},objectivesText="Progress: Are you here to deliver supplies?",rewardItems={151568,151718,151721},rewardCurrencies={{id=1220,amount=325},{id=1220,amount=380},{id=1220,amount=425},{id=1220,amount=440}},starts={{npcID=128370}},ends={{npcID=128370}},mapCandidates={npc={885},zone={8899}},questType="standard",db2Objectives={{orderIndex=0,type=1,amount=1,objectID=151721}},worldTaskTitle="Work Order: Hesselian",db2PoiMapID=1669,db2PoiUiMapID=885,db2QuestInfoID=125,db2QuestInfoName="Jewelcrafting World Quest"},
[48365] = {id=48365,name="The Young Lord Stormsong",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48008,48009,48347,48348,48352,48353,48354,48355,48356,48365,48366,48367,48368,48370,48372,48540,49268,49292,49299,49302},description="When the town fell, I got separated from my charge. Lord Stormsong is being held hostage in his own house. I should've been there to protect him. When you go in there, succeed where I failed. Bring him back safely.",objectivesText="Kill Brother Conway , then rescue Lord Brannon Stormsong from Anglepoint Packing District.",rewardGold=514800,rewardXP=1770,rewardItems={152401,152585,152586,153486,153513},rewardCurrencies={{id=1553,amount=75}},starts={{npcID=126308}},ends={{npcID=126308}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48354,48355},questLines={{id=592,name="The Shadow Over Anglepoint",orderIndex=9,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48366] = {id=48366,name="Paddle to Safety",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48008,48009,48347,48348,48352,48353,48354,48355,48356,48365,48366,48367,48368,48370,48372,48540,49268,49292,49299,49302},description="Perhaps... perhaps I can still help my people. I overheard conversations between the foreman and his men. It sounds as if the source of this corruption comes from the deeper waters, where the Stormriggers do their monster hunting. Please, assist me in investigating this. I can still redeem myself and this operation.",objectivesText="Use the Escape Rowboat to travel to Outrigger Post. Progress: I can't sit idly by anymore.",rewardGold=257400,rewardXP=1415,rewardItems={152401,152585,152586,153486,153513},starts={{npcID=126298}},ends={{npcID=126298}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48009,48356,48365},questLines={{id=592,name="The Shadow Over Anglepoint",orderIndex=13,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48367] = {id=48367,name="Those Aren't Fish Eggs",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48008,48009,48347,48348,48352,48353,48354,48355,48356,48365,48366,48367,48368,48370,48372,48540,49268,49292,49299,49302},description="Corruption has seeped into the sea. Part of our job is to keep the monsters of these parts under control. A cruel magic has taken over many of the beasts. I take the challenge of the hunt with pride, but too many and we are overrun! Monster eggs are scattered across the breeding grounds, pulsing with a dark energy. Get your stompin' boots on.",objectivesText="Break 30 Corrupted Eggs in Krakenbane Cove. Progress: Ah, the satisfying squish of a monster egg under your boot. What a feeling!",rewardGold=257400,rewardXP=1415,rewardItems={152401,152585,152586,153486,153513},starts={{npcID=128679}},ends={{npcID=128679}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48366},questLines={{id=592,name="The Shadow Over Anglepoint",orderIndex=14,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48368] = {id=48368,name="Deep Sea Defilement",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48008,48009,48347,48348,48352,48353,48354,48355,48356,48365,48366,48367,48368,48370,48372,48540,49268,49292,49299,49302},description="The sea... I understand its screams now. It is as if a veil has been lifted, revealing the chaos that has taken hold. Corrupting such a vast swath of sea cannot be done with simple spells. The cultists must have erected some sort of structures to channel their dark magics through... You must find and destroy them, <name>. Only then can we hope to restore the waters to balance.",objectivesText="Destroy the three Corrupting Pylons in the underwater caves in Krakenbane Cove. Progress: My mind is bursting with the tide's cries. It is almost too much to bear.",rewardGold=257400,rewardXP=1415,rewardItems={133755,152401,152585,152586,153486,153513},starts={{npcID=125922}},ends={{npcID=125922}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48366},questLines={{id=592,name="The Shadow Over Anglepoint",orderIndex=15,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48369] = {id=48369,name="Emergent Strategy",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48369,49450,49451,49452,49454,49465,49467,49468},description="My son went where? Chasing our workers into the woods once again? That boy is too soft-hearted. No matter what I do, he will never be strong enough to take over the family business. I demand he come back this instant. He's got better ways to spend his time than going on wild goose chases for our employees!",objectivesText="Find Benjamin Algerson near Fernwood Ridge.",rewardGold=257400,rewardXP=1415,starts={{npcID=129613}},ends={{npcID=129669}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49451,49452,49465},questLines={{id=5436,name="A Lumbering Mess",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48370] = {id=48370,name="Death in the Depths",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48008,48009,48347,48348,48352,48353,48354,48355,48356,48365,48366,48367,48368,48370,48372,48540,49268,49292,49299,49302},description="My own people have fallen to the mad whispers of the voices of the deep, deep sea. Cultists inhabit caves in the ocean, spreading hysteria deeper and deeper into Tiragarde with their mad rituals. We must put an end to them, <name>, before they get even more out of hand.",objectivesText="Kill 8 Deepwarden Followers in Krakenbane Cove.",rewardGold=257400,rewardXP=1415,rewardItems={152401,152585,152586,153486,153513},starts={{npcID=126308}},ends={{npcID=126298}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48366},questLines={{id=592,name="The Shadow Over Anglepoint",orderIndex=16,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48372] = {id=48372,name="Eldritch Invocations",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48008,48009,48347,48348,48352,48353,48354,48355,48356,48365,48366,48367,48368,48370,48372,48540,49268,49292,49299,49302},description="This is my fault, my friend. The leader of these cultists is none other than Director Deepwarden , a man who I once trusted as an advisor and business partner. It seems he did not approve of how I ran our operation... to a ludicrous degree. He gave his humanity for power, using his frustration to overthrow the village from the inside. Who knows what he plans next. I can no longer stand idly by. Take out Deepwarden. Show him that Anglepoint will not fall to his madness.",objectivesText="Kill Director Deepwarden in Krakenbane Cove.",rewardGold=514800,rewardXP=1770,rewardItems={152401,152585,152586,153486,153513},starts={{npcID=126298}},ends={{npcID=126298}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48366},questLines={{id=592,name="The Shadow Over Anglepoint",orderIndex=17,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48373] = {id=48373,name="Work Order: Lightweave Cloth",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=885,storyline={48373},objectivesText="Progress: Are you here to deliver supplies?",rewardItems={151567,151568},rewardCurrencies={{id=1220,amount=450},{id=1220,amount=475},{id=1533,amount=5},{id=1533,amount=11}},starts={{npcID=128370}},ends={{npcID=128370}},mapCandidates={npc={885},zone={8899}},questType="standard",db2Objectives={{orderIndex=0,type=1,amount=40,objectID=151567}},worldTaskTitle="Work Order: Lightweave Cloth",db2PoiMapID=1669,db2PoiUiMapID=885,db2QuestInfoID=121,db2QuestInfoName="Tailoring World Quest"},
[48374] = {id=48374,name="Supplies Needed: Lightweave Cloth",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=885,storyline={48374},objectivesText="Progress: Are you here to deliver supplies?",rewardItems={150970,151567},rewardCurrencies={{id=1220,amount=310},{id=1508,amount=30},{id=1508,amount=35},{id=1508,amount=45}},starts={{npcID=128370}},ends={{npcID=128370}},mapCandidates={npc={885},zone={8899}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=40,objectID=151567}},worldTaskTitle="Supplies Needed: Lightweave Cloth",db2PoiMapID=1669,db2PoiUiMapID=885,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[48375] = {id=48375,name="Primal Obliterum",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=7502,storyline={48375},objectivesText="Progress: Oh ho, whatcha got there? Primal Sargerite ? Sounds fancy! I bet if we mash some 'o that stuff with Obliterum , we can make it beefier! Give it more of a punch when you apply it to yer armor. Whaddya say, want ta give it a try?",rewardItems={124125,151568,152296},starts={{npcID=114719}},ends={{npcID=114719}},mapCandidates={npc={},zone={7502}},questGiverID=114719,questTurnInID=114719,questType="standard",sourceQuests={41778}},
[48376] = {id=48376,name="Mass Primal Obliterum",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=7502,storyline={48376},objectivesText="Progress: Oh ho, whatcha got there? Primal Sargerite ? Sounds fancy! I bet if we mash some 'o that stuff with Obliterum , we can make it beefier! Give it more of a punch when you apply it to yer armor. Heck, I bet if we smash a bunch of it together at once, we can make a whole batch 'o the stuff! Whaddya say, wanna give it a try?",rewardItems={124125,151568,152296},starts={{npcID=114719}},ends={{npcID=114719}},mapCandidates={npc={},zone={7502}},questGiverID=114719,questTurnInID=114719,questType="standard",sourceQuests={41778}},
[48386] = {id=48386,name="Jed'hin Tournament",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={48386},objectivesText="Participate in a Jed'hin Match",rewardGold=238680,rewardXP=6140,mapCandidates={npc={},zone={8701}},questType="world",db2Objectives={{text="Participate in a Jed'hin Match",amount=1,type=0,objectID=127759,orderIndex=0}},worldTaskTitle="Jed'hin Tournament",db2PoiMapID=1669,db2PoiUiMapID=882,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[48395] = {id=48395,name="Whispers from the Shadows",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=true,expansion=7,zoneID=7503,mapID=650,storyline={48395},description="Hero, we have a problem. The ancient Necrodark cult has returned. When Dargrul was the Underking he would quell these cultists whenever they appeared, keeping them from exploring the vault of Neltharion. But now, with Dargrul gone, they are sieging the vault in force. We must stop them before they find what they are looking for.",objectivesText="Help Navarrogg defeat the Necrodark.",mapCandidates={npc={},zone={7503}},questType="standard"},
[48399] = {id=48399,name="A Dark (Iron) Tide",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47228,47235,47329,48317,48399,48400,50043},description="Their red eyes... flaming beards... dark, dusky skin. These can only be Dark Iron dwarves. I have never seen one before this day. It is my understanding that they have been sent here on an errand for the Alliance. Given my people's allegiance, I believe we are now placed in a position to better demonstrate our loyalty to the Horde. The Dark Iron must die. See that they do not claim so much as an inch more of this beach.",objectivesText="Slay 7 Dark Iron dwarves.",rewardGold=257400,rewardXP=1415,starts={{npcID=131580}},ends={{npcID=131580}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={48317},questLines={{id=5403,name="Fossil Extraction",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[48400] = {id=48400,name="Grand Theft Telemancy",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47228,47235,47329,48317,48399,48400,50043},description="They must not keep the Eye, <name>. Fortunately I am more than an archaeologist. I am a telemancer. Chief Telemancer Oculeth himself trained the woman who trained my master. I can retrieve the relic with these arts. All you need to do is place a telemancy beacon near the Eye. I can then retrieve both it AND you safely back to camp. The Alliance will find themselves empty-handed. While you're at it, do deliver my \"thanks\" to the individual responsible for snatching the Eye out from under us.",objectivesText="Slay Urda Direflame and then place a telemancy beacon near the Eye of Xibala. Progress: Did you find the source of the disruption?",rewardGold=514800,rewardXP=1770,rewardItems={155310,158419,158420,158421,158422},rewardChoices={155310,158419,158420,158421,158422},starts={{npcID=131580}},ends={{npcID=131580}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={48317},questLines={{id=5403,name="Fossil Extraction",orderIndex=6,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[48402] = {id=48402,name="A Poisonous Touch",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48402},description="You... I saw you speak with Zentimo. Please, I don't have much time left... These trolls, they came for our blood. I was already nearly bled dry before this one succumbed to my poison. Search it's body, the blowgun and darts should still be there. Dip the darts into my blood and use them to weaken as many of their number as you can. I will not let my death be in vain! If these trolls want our blood so badly, then they shall have it!",objectivesText="Use the blowgun to weaken 5 Bloodhunter trolls.",rewardGold=278548,rewardXP=2765,starts={{npcID=126039}},ends={{npcID=120551}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47525}},
[48403] = {id=48403,name="The Darkness",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=7503,mapID=650,storyline={41764,41799,41800,41815,41840,41841,41882,41884,48066,48067,48079,48185,48190,48403,48433,48434,48435,49756},series={41815,41839,41840,41841,41882},description="For thousands of years, the Darkness was held at bay. The wards stood... protecting Highmountain. Now they are gone, and evil is free once more. The Darkness that haunted our dreams... that even the kobolds spoke of only in frightened whispers... has come. Uul'gyneth , herald of the Old Gods, paves the way for his masters. Unless we stand together and defeat him, all is lost. You must hold nothing back, champion. None of us can.",objectivesText="Defeat Uul'gyneth the Darkness.",rewardGold=341600,rewardXP=5465,rewardItems={25549,26010,26024,26036,38734,39033,39060,39098,42846,42861,42870,42881,42895,44018,44039,44041,44042,44043,62849,62850,62851,64594,64604,64613,64620,64625,64629,64632,64634,65623,65631,65632,65641,65644,65645,65646,65647,65648,65813,65814,84060,84061,84062,84063,84064,98133,113169,113170,113171,113172,113173,113174,113175,113176,119036,131271,131640,151493,157013,169905,171354,171355,174288,175713,175740,179513,179517,179532,181398,181407,181408,181409,181410,181411,181412,181413,181422,181423,181424,181425,181426,181427,181428,181429,181459,181477,181479,181541,182624,183396,183473,183491,184165,184378,184381,184382,184383,184384,184519,237890,237893,245345,246951,257143,263282,263461,265106,265631},starts={{npcID=105213}},ends={{npcID=104997}},mapCandidates={npc={650},zone={7503}},questType="standard",sourceQuests={41841},questLines={{id=377,name="Allies of the Horde: Highmountain",orderIndex=13,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=650},
[48404] = {id=48404,name="The Scamps",level=10,requiredLevel=10,faction="horde",categories={},flags={"loremaster"},sharable=true,expansion=7,zoneID=8499,mapID=1165,storyline={48404},series={48405},description="You there! You have legs and a need for money? I wish to hire you. Confounded, despicable, parentless children have been stealing my scrolls again. Those scrolls are dangerous in the wrong hands. What is worse, I believe these junior vagabonds to be organized. Find these street scamps and relieve them of their bounty, and I shall pay you for it.",objectivesText="Stop 5 Street Scamps from stealing. Progress: The little rascals are crawling all over these accursed docks.",rewardGold=257400,rewardXP=1415,rewardItems={156871},starts={{npcID=125312}},ends={{npcID=125312}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={52472}},
[48405] = {id=48405,name="Mista Nice",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=1165,storyline={48405},series={48404},description="I am normally not a violent tortollan, but if there is one thing I cannot abide, it is a scoundrel using children for his own profit. The street scamps appear to be working at the behest of a ring leader. I do believe they call him \" Mista Nice \" though I suspect the name to be sarcastic in nature. I have a scroll here that can let you move among the scamps and see if they lead you back to Mista Nice . If they do, slay him and I shall pay you a bounty.",objectivesText="Find and slay Mista Nice . Progress: Any luck finding that voice of corruption for the youth of tomorrow?",rewardGold=514800,rewardXP=1770,rewardItems={156871},rewardCurrencies={{id=1553,amount=75}},starts={{npcID=125312}},ends={{npcID=125312}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={48404}},
[48419] = {id=48419,name="Lured and Allured",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={47489,48419,48505,48539,48558,48773,49239,49398,49399,49400,49401,49404},series={48505,48539},description="Lookin' for a friend from the wreck, eh? If he survived he may have wandered up the path to our camp. Now if he ain't up there toastin' his buns by the fire, well... lotta poor souls fall victim to the song of the sirens. You should check the camp before you go wadin' out into the tideway. Ask our leader, Stabby Jane . She'd know for sure if a new survivor showed up!",objectivesText="Search for Flynn Fairwind .",rewardGold=22600,rewardXP=1415,rewardItems={152514,153185,153186,153187,153348},starts={{npcID=128377}},ends={{npcID=126158}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={47489},questLines={{id=587,name="Freehold",orderIndex=1,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=19,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48421] = {id=48421,name="Blood in the Tides",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={48421,49178,49218,49226,49230},description="Curse these slimy wenches! Their singin' sets men's hearts afire and their brains adrift. My ship's aground. My cargo's lost. Nothin' for it now but to fight!",objectivesText="Slay 8 Wailing Sirens .",rewardGold=27750,rewardXP=1415,rewardItems={152514,153185,153186,153187,153348,155023,155024,155025,155026,155086},rewardChoices={155024,155026,155025,155023,155086},starts={{npcID=125342}},ends={{npcID=125342}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={47489},questLines={{id=586,name="Castaways and Cutouts",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48433] = {id=48433,name="Together We Are the Horde!",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=1637,mapID=650,storyline={41764,41799,41800,41815,41840,41841,41882,41884,48066,48067,48079,48185,48190,48403,48433,48434,48435,49756},description="What began with a simple feast led to a battle against an ancient evil seeking to consume the world. My kind of day! Your deeds have helped secure an alliance between Orgrimmar and Highmountain. These tauren will make a valuable addition to the Horde. The Warchief will be pleased.",objectivesText="Speak with Ji Firepaw at the Orgrimmar Embassy to hear the end of this tale.",rewardGold=341600,rewardXP=5465,rewardItems={63207,63353,65274,110560,128353,155662},starts={{npcID=126134}},ends={{npcID=126065},{npcID=133523}},mapCandidates={npc={85,650},zone={1637}},questType="standard",sourceQuests={48403},questLines={{id=377,name="Allies of the Horde: Highmountain",orderIndex=14,flags=0}},db2PoiMapID=1,db2PoiUiMapID=85},
[48434] = {id=48434,name="How Fares Ebonhorn?",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=7503,mapID=650,storyline={41764,41799,41800,41815,41840,41841,41882,41884,48066,48067,48079,48185,48190,48403,48433,48434,48435,49756},series={41764,41799,41800,41884,48185,48190,48435},description="Three of the ancient wards are restored. The mountain is not yet secure, but we may have done enough to break Ebonhorn free of the shadows gripping him. Let us return to Thunder Totem and see how he fares. Hopefully Ebonhorn can tell us more about what is happening with the Necrodark and the insidious master they serve.",objectivesText="Return to Thunder Totem and check on Ebonhorn.",rewardGold=341600,rewardXP=5465,starts={{npcID=125466}},ends={{npcID=125466}},mapCandidates={npc={650},zone={7503}},questTurnInID=125466,questType="standard",sourceQuests={41800},questLines={{id=377,name="Allies of the Horde: Highmountain",orderIndex=15,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=750},
[48435] = {id=48435,name="The Spiritwalkers",level=40,requiredLevel=40,faction="none",categories={},flags={},sharable=false,expansion=7,mapID=750,storyline={41764,41799,41800,41815,41840,41841,41882,41884,48066,48067,48079,48185,48190,48403,48433,48434,48435,49756},series={41764,41799,41800,41884,48185,48190,48434},description="Ebonhorn is in the care of Spiritwalker Graysky. A cure is proving elusive... he has asked for your help. Please speak with him at once, . The spiritwalkers are the keepers of our past. I pray the answer lies somewhere in the ancient truths they hold.",objectivesText="Speak with Spiritwalker Graysky at Thunder Totem in Highmountain.",rewardGold=286500,rewardXP=5465,mapCandidates={npc={},zone={}},questType="standard",questLines={{id=377,name="Allies of the Horde: Highmountain",orderIndex=16,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=750},
[48440] = {id=48440,name="Into the Night",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=831,storyline={47221,47222,47223,47224,47835,47867,48440,48506,48507},description="What we do this day, we do for Azeroth. For the countless souls lost to the Legion's foul crusade. Once you are ready we will take the Vindicaar into the very heart of the Legion. Argus awaits.",objectivesText="Travel to Argus aboard the Vindicaar.",rewardGold=20220,rewardXP=770,starts={{npcID=120977}},ends={{npcID=120977}},mapCandidates={npc={},zone={8840}},questGiverID=120977,questTurnInID=120977,questType="standard",sourceQuests={47224},questLines={{id=346,name="To Argus!",orderIndex=8,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=346,questLineOrder=0,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2LabelIDs={4784},db2PoiMapID=1669,db2PoiUiMapID=831},
[48441] = {id=48441,name="Remnants of Darkfall Ridge",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={47967,48441,48442,48443,48445,48446,48447,48448,48453,48455,48544,48600,48601,48654},description="My riders have talbuk, but my people need supplies. Food. Tools. Weapons. For millennia, we have migrated from one hovel to the next, moving each time the Legion discovered us. Never able to flee with our possessions, we left them behind. You are powerful, your followers are capable, but you do not know Argus. The landscape will dispatch you as mercilessly as the Legion. Recover our supplies from Darkfall Ridge, and I will order my people to guide your forces through the Argus Wastes.",objectivesText="Use the Scouting Map and complete the mission, \"Darkfall Ridge Supplies\".",rewardItems={152095,152096,152097,152430,152439},starts={{npcID=119388}},ends={{npcID=119388}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={48544},questLines={{id=365,name="Petrified Forest",orderIndex=4,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=830},
[48442] = {id=48442,name="Nath'raxas Hold: Preparations",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={47967,48441,48442,48443,48445,48446,48447,48448,48453,48455,48544,48600,48601,48654},description="One of two fates await krokul prisoners taken to Nath'raxas Hold. Consume the fel, and become a willing soldier in the infinite army, or be mutated into a disfigured abomination. An ur'zul. While the Army of the Light occupies the Legion's attention, I am presented with an opportunity to save my people. I ask for your aid. Before we begin, your forces must be adequately equipped.",objectivesText="Raise 6 Champions to 900 Item Level.",rewardItems={151842,152095,152096,152097},starts={{npcID=119388}},ends={{npcID=119388}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={48441},questLines={{id=365,name="Petrified Forest",orderIndex=5,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=830},
[48443] = {id=48443,name="Nath'raxas Hold: Rescue Mission",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={47967,48441,48442,48443,48445,48446,48447,48448,48453,48455,48544,48600,48601,48654},description="Your forces are adequately equipped for the mission to save my people from Nath'raxas. Order your champions to bolster my assault, and together we will dismantle the Legion's stranglehold over the region.",objectivesText="Use the Scouting Map and complete the mission, \"Nath'raxas Breakout\".",rewardItems={152095,152096,152097},starts={{npcID=119388}},ends={{npcID=119388}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={48910},questLines={{id=365,name="Petrified Forest",orderIndex=6,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=830},
[48445] = {id=48445,name="The Ruins of Oronaar",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={47967,48441,48442,48443,48445,48446,48447,48448,48453,48455,48544,48600,48601,48654},description="Many krokul wander the city below, shrouded in shadow. I will not accept that they are all beyond redemption. Arkhaan was a leader, once. Some among his followers may still reside in the ruins of Oronaar, straddling the thin divide between reason and oblivion. Enlist the aid of your order. Scour the ruins for any that can be saved.",objectivesText="Use the Scouting Map and complete the mission, \"Inches from Madness.\"",rewardItems={152095,152096,152097},starts={{npcID=121230}},ends={{npcID=121230}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={48443},questLines={{id=365,name="Petrified Forest",orderIndex=7,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=883},
[48446] = {id=48446,name="Relics of the Ancient Eredar",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={47967,48441,48442,48443,48445,48446,48447,48448,48453,48455,48544,48600,48601,48654},description="I failed Arkhaan. I won't fail again. If there is to be any hope of freeing the krokul, the ethereal threat must be removed from Eredath . L'ura has been vanquished, but the void clings heavily near the Shadowguard Incursion. Before we commence, ensure your forces are protected from the shadow. Your champions should seek ancient eredar armaments in the nearby ruins.",objectivesText="Raise 6 Champions to 925 Item Level.",rewardItems={151090,151843,152095,152096,152097},starts={{npcID=121230}},ends={{npcID=121230}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={48445},questLines={{id=365,name="Petrified Forest",orderIndex=8,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=883},
[48447] = {id=48447,name="Shadowguard Dispersion",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={47967,48441,48442,48443,48445,48446,48447,48448,48453,48455,48544,48600,48601,48654},description="Lend me the aid of your order once again, that we might end the Shadowguard threat permanently. While you confront the Legion, we will face the void. The attack commences once your forces arrive.",objectivesText="Use the Scouting Map and complete the mission, \"Shadowguard Dispersion\".",rewardItems={152095,152096,152097},starts={{npcID=121230}},ends={{npcID=121230}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={48446,48654},questLines={{id=365,name="Petrified Forest",orderIndex=10,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=883},
[48448] = {id=48448,name="Hindering the Legion War Machine",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8899,mapID=886,storyline={47967,48441,48442,48443,48445,48446,48447,48448,48453,48455,48544,48600,48601,48654},description="<class>t, I could use your help. The Army of the Light is coordinating an attack against the Spirit Crucible, Terminus, and Shaper's Rise to cripple the Legion's ability to wage war outside of the Antoran Wastes . We do not have enough soldiers to defend our footholds and execute this operation. Will you approach the <class>s on our behalf? This gambit could succeed with them fighting by our side. We can paralyze the Legion war machine.",objectivesText="Use the Scouting Map and complete the mission, \"Gambit in the Wastes.\"",rewardItems={152095,152096,152097,152449,153132},starts={{npcID=124312}},ends={{npcID=124312}},mapCandidates={npc={},zone={8701}},questGiverID=124312,questTurnInID=124312,questType="standard",sourceQuests={48446,48654},questLines={{id=365,name="Petrified Forest",orderIndex=11,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=886},
[48452] = {id=48452,name="The Red Market",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8670,mapID=1165,series={48454},description="You came with de Princess Talanji? I need a hand with a most unsavory task. Crimson cultists have made demselves a market for blood magic. Dis is bad, mon. Dis is very bad indeed. I need you to go down dese steps and bring back any evidence you can of blood practices. And destroy their chalice. Big chalice. Don't forget de chalice.",rewardGold=243360,rewardXP=1415,starts={{npcID=126148}},ends={{npcID=126148}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={49615}},
[48453] = {id=48453,name="Strike Back",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={47967,48441,48442,48443,48445,48446,48447,48448,48453,48455,48544,48600,48601,48654},description="As you may have seen, the ritualists in this forest kidnap our people and perform heinous rituals on them. The souls of our fallen now roam as twisted creatures. This sin cannot go unpunished. Kill as many ritualists as you are able, but be sure to strike at the dark demon that leads them.",objectivesText="Kill 8 Eredar ritualists and Lady Shahrazad in the Petrified Forest.",rewardGold=202200,rewardXP=6140,rewardItems={122457,152095,152096,152097,152575},starts={{npcID=126160}},ends={{npcID=126160}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={48460},questLines={{id=365,name="Petrified Forest",orderIndex=2,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=830},
[48454] = {id=48454,name="Evidence of Evil",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=1165,storyline={48454},series={48452},description="Jakra'zet refused to patrol dis area. Yazma's spies did not warn us of de evil lurking beneath our city. And Zul did not foresee blood magics festering under our noses. These are serious allegations, and de evidence is in your hands. Present dem to Zolani , Blade of the King. She will know best their meaning and how best to present dem to de king.",objectivesText="Speak with Zolani , Blade of the King.",rewardGold=25740,rewardXP=175,rewardCurrencies={{id=1553,amount=100}},starts={{npcID=126148}},ends={{npcID=122915},{npcID=135441}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={48452}},
[48455] = {id=48455,name="Duskcloak Problem",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={47967,48441,48442,48443,48445,48446,48447,48448,48453,48455,48544,48600,48601,48654},description="Here in this forest, species of talbuk and panthara still roam. However, the balance has been disrupted and now the panthara risk hunting the talbuk to extinction. To ensure their survival, we must decrease the number of panthara. Do not let their suffering linger. A swift death is the most merciful.",objectivesText="Kill 10 panthara within the Petrified Forest.",rewardGold=202200,rewardXP=6140,rewardItems={152095,152096,152097,152575,153046},starts={{npcID=126160}},ends={{npcID=126160}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={48460},questLines={{id=365,name="Petrified Forest",orderIndex=1,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=830},
[48460] = {id=48460,name="The Wranglers",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={48460},description="Great evil exists on Argus and our forests house some of the worst of it. My wranglers are at the edge of the forest and are waiting for reinforcements. That would be you. Seek out Lead Rider Jerek , he will tell you more.",objectivesText="Speak to Lead Rider Jerek in the Petrified Forest.",rewardGold=50550,rewardXP=6140,rewardItems={152095,152096,152097},starts={{npcID=119388}},ends={{npcID=126160}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={46732},nextQuests={47967,48453,48455}},
[48461] = {id=48461,name="Where They Least Expect It",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=885,storyline={48461,48513},description="The Legion's fanatical crusade leaves them spread thin. As they focus their defenses on Argus, we are free to tear into their forces on other worlds. Travel through an Invasion Point on Argus and show the Legion that there is no hiding from death.",objectivesText="Enter an Invasion Point and defeat a Legion Commander. Progress: No demon is safe while I draw breath.",rewardCurrencies={{id=1508,amount=100}},starts={{npcID=127051}},ends={{npcID=127051}},mapCandidates={npc={885},zone={8899}},questType="standard",sourceQuests={48107},questLines={{id=369,name="Invasion Rifts",orderIndex=0,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=369,questLineOrder=6,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=886},
[48465] = {id=48465,name="Vrax'thul",level=45,requiredLevel=45,faction="none",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48465},rewardGold=606600,rewardXP=9210,rewardItems={152790,152814,152844,152903,152904,152905},mapCandidates={npc={},zone={8899}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=126199}},worldTaskTitle="Vrax'thul",db2PoiMapID=1669,db2PoiUiMapID=885,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[48466] = {id=48466,name="Ven'orn",level=45,requiredLevel=45,faction="none",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48466},rewardGold=716040,rewardXP=9210,mapCandidates={npc={},zone={8899}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=126115}},worldTaskTitle="Ven'orn",db2PoiMapID=1669,db2PoiUiMapID=885,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[48467] = {id=48467,name="Puscilla",level=45,requiredLevel=45,faction="none",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48467},rewardGold=929400,rewardXP=9210,rewardItems={152790,152814,152844,152903,152904,152905},mapCandidates={npc={},zone={8899}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=126040}},worldTaskTitle="Puscilla",db2PoiMapID=1669,db2PoiUiMapID=885,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[48468] = {id=48468,name="Bwonsamdi's Deliverance",level=20,requiredLevel=20,faction="both",categories={},flags={"loremaster"},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48468,48473,48478,48479,48480},description="We be havin' a task from Bwonsamdi, da loa a death, ta purge dis place of its undead. Dey be controlled by a monster called Kel'vax. Can ya help? Dere be zombies destroyin' Bwonsamdi's temple over dere, and we no have da strength ta fight 'em all. Take dis torch. Kill dem zombies, den burn them corpses with da torch. It should be deliverin' their souls ta Bwonsamdi. Ya do dat, and we be one step closer ta stoppin Kel'vax.",objectivesText="Burn 10 defiled troll corpses with the cremation torch .",rewardGold=257400,rewardXP=2765,rewardItems={153178},starts={{npcID=126080},{npcID=130481}},ends={{npcID=126080}},mapCandidates={npc={863},zone={8500}},questType="standard",questLines={{id=5414,name="Bwonswamdi",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[48473] = {id=48473,name="Respecting the Rites",level=20,requiredLevel=20,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48468,48473,48478,48479,48480},description="If we be deliverin' Kel'vax's soul ta Bwonsamdi, we need ta be doin' it properly. We need ta be doin' two things. First, dere be torches remainin' around da temple nearby. Light dem with da torch I gave ya. Da torches used ta be our way ta show dat we be deliverin' a spirit ta Bwonsamdi. Kel'vax will be knowin' it be his time. Second, I be needin' special ritual powder dat be deep within da temple. It be da key ta stoppin' Kel'vax. Go now, I be prayin' Bwonsamdi be favorin' us.",objectivesText="Light 5 Ritual Torches and recover Shinga Deathwalker 's Ritual Powder . Progress: Light dem torches and get da powder so we be gettin' Bwonsamdi's favor.",rewardGold=257400,rewardXP=2765,rewardItems={157793},starts={{npcID=130481}},ends={{npcID=126080}},mapCandidates={npc={863},zone={8500}},questType="standard",questLines={{id=5414,name="Bwonswamdi",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[48474] = {id=48474,name="Crypt Keepers",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={48474},objectivesText="Cemetery cleansed",rewardGold=455280,rewardXP=1415,mapCandidates={npc={},zone={8721}},questType="standard",sourceQuests={48475},db2Objectives={{text="Cemetery cleansed",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Crypt Keepers",db2PoiMapID=1643,db2PoiUiMapID=896},
[48475] = {id=48475,name="Seeing Spirits",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48475},description="The spirits in the cemetery are riled up! I'd ask 'em direct but I don't have any of the necessary salve I use to commune with the dead. My family's been making it for ages! The herbs and tools I use to make it are inside, but I can't get over there! Some of those spirits are beyond reason and attack me on sight! Why don't you go collect those herbs, make the salve with my tools, and ask one of the calmer spirits what's going on. Aaron Cresterly is a good spirit to look for.",objectivesText="Collect Gravebloom , create and use salve, then find Aaron Cresterly . Progress: Stranger, lend me your aid! I am ensnared in a witch's foul magic and I do not know how much longer I can resist! Destroy the circle binding me!",rewardGold=257400,rewardXP=2765,rewardItems={152480},starts={{npcID=126210}},ends={{npcID=126225}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48622}},
[48476] = {id=48476,name="Split Party",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48476},description="In life my compatriots and I were valiant champions as you are. In death we are potent souls to make the witch's accursed minions even more powerful. With your help I have resisted thus far, but this foul witch pulled brave Bridget from her justly won rest. She is now trapped in one of these macabre constructs. This witch intends to use Bridget to bring death upon the lands she was oathsworn to protect! Free Bridget Fairwater 's soul from the construct which entraps her!",objectivesText="Free Bridget Fairwater 's soul.",rewardGold=514800,rewardXP=3455,starts={{npcID=126225}},ends={{npcID=126240}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48475}},
[48477] = {id=48477,name="Looking For One More",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48477},description="Our loathsome foe, 'Sister' Westwood, yet continues her work. After subjugating myself, she set her malicious sights on my companion, fair Mercy. Of us three, Mercy was most kind and possessing of uncommon inner strength, yet I fear for her. Corrupting such a soul would make for a fearsome creature, indeed. Stop the vile ritual before Mercy is taken. Allow the dead their rest. Slay Sister Westwood and free us from her grasp!",objectivesText="Slay Sister Westwood .",rewardGold=514800,rewardXP=3455,rewardCurrencies={{id=1553,amount=75}},starts={{npcID=126240}},ends={{npcID=126253}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48476}},
[48478] = {id=48478,name="Kel'vax's Home",level=20,requiredLevel=20,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48468,48473,48478,48479,48480},description="Kel'vax's soul be bound ta three phylacteries, protected by his voodoo. Even if ya destroy him, he just be reformin' in dem. Me old power be returnin' after ya lit dem torches. I be able ta enchant dis powder dat allow ya ta go through Kel'vax's voodoo. Find dese phylacteries and bring 'em ta me. We gonna look Kel'vax in da eye when we destroy 'em. I should warn ya... dis powder might be messin' with ya head. Ya may have some... visions after ya use it. Be careful.",objectivesText="Use Shinga Deathwalker 's Spirit Powder to take Kel'vax's Ancient, Repaired, and Pristine Phylacteries . Progress: We need dem phylacteries if we be havin' a chance ta destroy Kel'vax.",rewardGold=257400,rewardXP=2765,rewardItems={152468,154130,154136,154137,155341,155343,155519,155521,158943,158944,158945,158946},rewardChoices={158943,158944,158945,158946,155519,155343,155521,155341},starts={{npcID=126080}},ends={{npcID=126080}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={48468,48473},questLines={{id=5414,name="Bwonswamdi",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[48479] = {id=48479,name="Bones for Protection",level=20,requiredLevel=20,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48468,48473,48478,48479,48480},description="Kel'vax be havin' powerful voodoo on his side, da kind dat could kill ya instantly if ya not careful. I know how we can be stoppin' dis magic, but we need bones. Lots a them. We be lucky, Kel'vax be havin' a large skeleton army. I need ya ta be goin' out dere and collectin' their bones. Bring 'em ta me and I'll prepare 'em ta be used against his voodoo.",objectivesText="Collect 40 Cursed Bones . Progress: Did ya get them bones? We need 'em if we gonna stop Kel'vax's voodoo.",rewardGold=257400,rewardXP=2765,rewardItems={153346},starts={{npcID=126079}},ends={{npcID=126079}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={48468,48473},questLines={{id=5414,name="Bwonswamdi",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[48480] = {id=48480,name="The Fall of Kel'vax",level=20,requiredLevel=20,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48468,48473,48478,48479,48480},description="We be ready ta kill Kel'vax and send his soul ta Bwonsamdi for judgment. Ya should know someting before ya go in. Kel'vax was our son. Dat be why Bwonsamdi chose us ta stop dis madness. I not be knowin' why Kel'vax chose ta forsake everyting we believed in centuries ago... but here we are. Even without his undead, Kel'vax be very powerful. Be prepared... dis be our shot to end him and find our rest.",objectivesText="Defeat Kel'vax Deathwalker . Progress: Ya must destroy Kel'vax once and for all!",rewardGold=514800,rewardXP=3455,starts={{npcID=126080}},ends={{npcID=126080}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={48478,48479},questLines={{id=5414,name="Bwonswamdi",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[48483] = {id=48483,name="A Stranger's Plea",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={46297,46732,46816,46839,46840,46841,46842,46843,46938,47589,47627,47641,48483,48500},description="My people... enslaved... Beaten... within death's grasp... <The cowled figure weakly raises his arm, handing you a small liquid skin.> Help... us...",objectivesText="Heal 8 Felbound Drudges .",rewardGold=151650,rewardXP=6140,rewardItems={152472},starts={{npcID=126239}},ends={{npcID=123149}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={46938},questLines={{id=345,name="Assault on Argus",orderIndex=3,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=345,questLineOrder=1,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=830},
[48489] = {id=48489,name="The Spires of Home",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=true,expansion=7,storyline={48489},description="My sister Vereesa told me of the events that led to the high... excuse me, \"blood\" elves joining the Horde. Part of me still can't accept it. Prince Kael'thas led my people down a dark path. I have to believe the majority of sin'dorei would shrug off the Horde if given the choice. The last time I spoke to Lor'themar, we served together in the Farstriders. He was a fine ranger and a good man. I pray the years have not changed that. Come. We must not keep the regent waiting. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(48489)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(48489))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Meet Alleria Windrunner on the Isle of Quel'Danas.",mapCandidates={npc={},zone={}},questType="standard"},
[48492] = {id=48492,name="Getting a Leg Up",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48492,48496,48497,48498,48499,49479},series={49477},description="I seem to be in a bit of a... predicament. My squad was scouting on behalf of Lady Sylvanas when we were ambushed by some snake men calling themselves \"sethrak\". As you can see, my legs have been separated from my body in the ambush. It's just a flesh wound, luckily. Care to help me get re-attached? Then we can get down to this business of vengeance against these sethrak.",objectivesText="Recover Chadwick Paxton 's legs.",rewardGold=25740,rewardXP=345,starts={{npcID=126289}},ends={{npcID=126346}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49477},questLines={{id=5418,name="Cooking with Sethrak",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[48496] = {id=48496,name="Reuniting the Company",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48492,48496,48497,48498,48499,49479},description="Right, then. First order of business, rescue the remnants of my company. These sethrak kept yelling about expanding their empire and conquering Azeroth as they attacked us. Lovely, really. They killed most of my company and took some hostages. I assume they're being told how grand the sethrak empire is. I'd like the remnants of my company back, if you please. I'll put in a good word with Lady Sylvanas, once this is all over. ...not that someone like you needs it.",objectivesText="Rescue the remnants of Chadwick Paxton 's squad.",rewardGold=257400,rewardXP=2765,rewardItems={155340,155342,155520,155522,158947,158948,158949,158950},rewardChoices={158947,158948,158949,158950,155340,155342,155520,155522},starts={{npcID=126346}},ends={{npcID=126346}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={48492},questLines={{id=5418,name="Cooking with Sethrak",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[48497] = {id=48497,name="Show of Force",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48492,48496,48497,48498,48499,49479},description="These things called the sethrak think that we're easily handled. That's only because we were ambushed and not ready for a fight. Well, all right, perhaps we were easily handled. But that doesn't mean we won't strike back. Kill as many of those sethrak as you can. I don't know who they are or what they want, but I do know one thing. They signed their death warrants when they attacked my squad and cut me in half.",objectivesText="Defeat 10 Sethrak.",rewardGold=257400,rewardXP=2765,starts={{npcID=126346}},ends={{npcID=126346}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={48492},questLines={{id=5418,name="Cooking with Sethrak",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[48498] = {id=48498,name="No Mercy for Sithis",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48492,48496,48497,48498,48499,49479},description="Heh heh... thanks for the rescue! I could use your help in a little plan that I have. The commander of this place is a sethrak called Sithis. He's got this thing called a \" skycaller gem .\" Word is they're looking for some sort of shadow magic in Nazmir to try and really power this thing up. Heh heh... luckily, yours truly has her own shadow magic to do just that! Maybe you do, too. I don't keep up on what powers you keep getting. Get the gem from Sithis and we'll have some REAL fun afterwards.",objectivesText="Recover the Skycaller Gem from Fangcaller Sithis. Progress: Do you have Ingrid's gem? Please tell me you do... she's been absolutely insufferable about it.",rewardGold=257400,rewardXP=2765,rewardItems={154892},starts={{npcID=126377}},ends={{npcID=126346}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={48496},questLines={{id=5418,name="Cooking with Sethrak",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[48499] = {id=48499,name="Return to Dust",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48492,48496,48497,48498,48499,49479},description="It appears the sethrak are quite serious about keeping this gem. I do wonder where they found it in the first place. Hrm... perhaps Lady Sylvanas would be interested in this as well. Something to ponder. Ingrid believes this gem can unleash lightning and shadow magic of, her words not mine, epic proportions. I do believe it would be best for everyone if you tested it out on the small sethrak army currently looking for us.",objectivesText="Defeat 20 Enraged Sethrak with the Skycaller Gem . Progress: Would you please hurry and deal with the sethrak? I'd prefer to get everyone's bloodlust dealt with before heading out.",rewardGold=257400,rewardXP=2765,rewardItems={87361,87362,87363,87364,87365,87366,87367,87368,87369,153519},rewardCurrencies={{id=1553,amount=75}},starts={{npcID=126346}},ends={{npcID=126346}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49479},questLines={{id=5418,name="Cooking with Sethrak",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[48500] = {id=48500,name="A Moment of Respite",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8574,mapID=831,storyline={46297,46732,46816,46839,46840,46841,46842,46843,46938,47589,47627,47641,48483,48500},description="For all we have seen, we must remember not to dwell on the past, but to look forward and prepare for what is to come. Take this opportunity to familiarize yourself with the Vindicaar.",objectivesText="Speak with Artificer Shela'na , Thelbus Wimblenod and High Priestess Ishanah . Progress: Light guide your path.",rewardGold=101100,rewardXP=3070,starts={{npcID=126307}},ends={{npcID=126307}},mapCandidates={npc={},zone={8574}},questGiverID=126307,questTurnInID=126307,questType="standard",sourceQuests={46843},questLines={{id=345,name="Assault on Argus",orderIndex=13,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=345,questLineOrder=1,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2LabelIDs={4784},db2PoiMapID=1669,db2PoiUiMapID=831},
[48502] = {id=48502,name="Naroua, King of the Forest",level=45,requiredLevel=45,faction="none",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={48502},rewardGold=606600,rewardXP=9210,rewardItems={152840,152841,152842,152843,152844,153054,153055,153190,153191},mapCandidates={npc={},zone={8574}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=126419}},worldTaskTitle="Naroua, King of the Forest",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[48504] = {id=48504,name="Through the Old Roads",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48184,48504,48517,49890,49896},description="Lady Waycrest has entrusted me with securing the town of Falconhurst and the services of Master Alchemist Ashton who lives there. However, I have found out no one has heard from Falconhurst in some time. The skies above the forest are impassable, so we must travel the old roads through Drust ruins in the mountains. A small capable party has a better chance to bypass the growing forces of the witches and to help secure Master Alchemist Ashton. To that end, I ask you to assist me.",objectivesText="Meet with Inquisitor Cleardawn at Gol Osigr.",rewardGold=23400,rewardXP=345,starts={{npcID=135021}},ends={{npcID=129983}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={49926},questLines={{id=600,name="Gol Osigr",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48505] = {id=48505,name="Lovesick and Lost",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={47489,48419,48505,48539,48558,48773,49239,49398,49399,49400,49401,49404},series={48419,48539},description="Ugh. My head. My HEART. Feels like a good hangover and a bad breakup put together. On the bright side, I think I know where we are. And where that ship was headed. Freehold. It's a... free town. For, uh... free folk. The only rule is that there are no rules. Lotta guys with peg legs and eye patches and exotic pets. Catch my drift? There's a trail through the hills that'll take us there. Pretty sure I remember the way... Let's get moving. Gotta walk off that damn siren's witchery.",objectivesText="Escort Flynn to Freehold.",rewardGold=257400,rewardXP=1415,rewardItems={152514,153185,153186,153187,153348},starts={{npcID=126158}},ends={{npcID=126620}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48419},questLines={{id=587,name="Freehold",orderIndex=2,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=20,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48506] = {id=48506,name="The Hand of Fate",level=45,requiredLevel=45,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=84,storyline={47221,47222,47223,47224,48440,48506},series={47221,47222,47223,47224,47835,47867,48507},description="Ever since the Legion invaded the Exodar, the draenei have been hard at work preparing to return to Argus. At long last they have a vessel that can take us there. With the way to that dreadful world open, we simply could not ask for a better opportunity to strike. Prophet Velen called for you quite specifically to join the assault force. You should make your way to Stormwind Harbor right away. Arrangements have been made for a ship there to take you to Azuremyst.",objectivesText="Meet your escort to the Exodar at Stormwind Harbor.",rewardGold=20220,rewardXP=770,starts={{npcID=90417}},ends={{npcID=121754}},mapCandidates={npc={84},zone={7502}},questGiverID=90417,questType="standard",sourceQuests={46734},questLines={{id=346,name="To Argus!",orderIndex=0,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=346,questLineOrder=0,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiUiMapID=84},
[48507] = {id=48507,name="The Hand of Fate",level=45,requiredLevel=45,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=1,storyline={47223,47224,47835,47867,48440,48507},series={47221,47222,47223,47224,47835,47867,48506},description="Ever since the Legion invaded the Exodar, the draenei have been hard at work preparing to return to Argus. At long last they have a vessel that can take us there. With the way to that dreadful world open, we simply could not ask for a better opportunity to strike. Prophet Velen called for you quite specifically to join the assault force. You should make your way to Bladefist Bay right away. Arrangements have been made for a ship there to take you to Azuremyst.",objectivesText="Meet your escort to the Exodar at Bladefist Bay. Progress: It seems fate has conspired to bring us together, <name>.",rewardGold=20220,rewardXP=770,starts={{npcID=90417}},ends={{npcID=122065}},mapCandidates={npc={1},zone={7502}},questGiverID=90417,questType="standard",sourceQuests={46734},questLines={{id=346,name="To Argus!",orderIndex=3,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=346,questLineOrder=0,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1,db2PoiUiMapID=1},
[48509] = {id=48509,name="Commander Sathrenael",level=45,requiredLevel=45,faction="none",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={48509},rewardGold=606600,rewardXP=9210,mapCandidates={npc={},zone={8574}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=122912}},worldTaskTitle="Commander Sathrenael",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
