[48512] = {id=48512,name="Sister Subversia",level=45,requiredLevel=45,faction="none",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={48512},rewardGold=606600,rewardXP=9210,mapCandidates={npc={},zone={8574}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=123464}},worldTaskTitle="Sister Subversia",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[48513] = {id=48513,name="Invasion Point Offensive",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9024,mapID=885,storyline={48461,48513},description="The invasion points are key to cutting off Legion reinforcements to Argus. Defeating their armies within the lesser portals will allow us to assault larger invasion points and extinguish the Legion presence within.",objectivesText="Complete 3 Invasion Points . Progress: The offensive continues.",rewardCurrencies={{id=1508,amount=250}},starts={{npcID=127051}},ends={{npcID=127051}},mapCandidates={npc={885},zone={8899}},questType="standard",sourceQuests={48440},questLines={{id=369,name="Invasion Rifts",orderIndex=1,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=369,questLineOrder=6,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=886},
[48514] = {id=48514,name="Slumbering Behemoths",level=45,requiredLevel=45,faction="none",categories={},flags={"rare"},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48514},rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8899}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=126164},{orderIndex=1,type=0,amount=1,objectID=126196}},worldTaskTitle="Slumbering Behemoths",db2PoiMapID=1669,db2PoiUiMapID=885,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
[48515] = {id=48515,name="Silver Blades",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48515},description="<This drust warrior was felled by a silvered blade long ago. This blade is still good despite the ages. Perhaps these weapons could be brought into service of fighting the Drust once more.>",objectivesText="Collect 6 Tarnished Blades from the Fallen Defenders.",rewardGold=238680,rewardXP=2765,rewardItems={34334,155906},mapCandidates={npc={},zone={8721}},questType="standard"},
[48516] = {id=48516,name="Toxic Community",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={48516},description="A traveler? Nobody uses this trail unless they got a death wish. The only thing more poisonous than the marrowflies are the saurolisks that eat 'em all day. That marrowfly toxin is what I'm here for. Y'see, I'm a purveyor of, uh... specialty goods. And my clients are just dyin' for more of my product. Heh. You bring me their stingers, I pay you. Simple as that. You can even find 'em in the saurolisks, if you don't mind gettin' your hands dirty.",objectivesText="Gather 50 Toxic Stingers . Progress: You got them stingers?",rewardGold=257400,rewardXP=1415,rewardItems={152514,153185,153186,153187,153348},starts={{npcID=126511}},ends={{npcID=126511}},mapCandidates={npc={895},zone={8567}},questType="standard"},
[48517] = {id=48517,name="Honorable Discharge",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48184,48504,48517,49890,49896},description="Some of the spirits on the battlefield are too weary to go on. These were brave Kul Tirans. They have more than earned their rest but their sense of duty holds them here. Order the most weary spirits off the field of battle. Hopefully they will be convinced to rest.",objectivesText="Dismiss 10 Weary Spirits from the battlefield.",rewardGold=245700,rewardXP=2765,starts={{npcID=129983}},ends={{npcID=129983}},mapCandidates={npc={896},zone={8721}},questTurnInID=129983,questType="standard",sourceQuests={48504},questLines={{id=600,name="Gol Osigr",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48518] = {id=48518,name="Save Who We Can",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="These things seem intent on capturing our people... but we're not quite sure what for. The ones in the town might be too tough to reach right now, but we might be able to save some of the woodsmen who work along the strand. Head to the lumber fields just east of here, and see if there's anyone still alive out there. We can shelter them here until we can arrange safe passage out of here.",objectivesText="Rally 6 Frightened Woodsmen in the Timbered Strand.",rewardGold=309800,rewardXP=2765,rewardItems={152587,152590},starts={{npcID=126310}},ends={{npcID=126310}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48171},questLines={{id=383,name="Fletcher's Hollow",orderIndex=1,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=18,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48519] = {id=48519,name="Hope They Can't Swim",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="We've got a small boat docked right across the way there. If we can get these villagers safely on board, they should be able to make it to Fallhaven by river. You're a capable fighter, no doubt. Can I count on you to fend off any attackers while we get them to safety?",objectivesText="Defend the villagers as they board the boat in the Timbered Strand. Progress: We can begin evacuating on your mark.",rewardGold=514800,rewardXP=3455,rewardItems={152587,152590,155117,155118,155119,155120,155158},rewardChoices={155118,155120,155119,155117,155158},starts={{npcID=126310}},ends={{npcID=126310}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48518,49295},questLines={{id=383,name="Fletcher's Hollow",orderIndex=3,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=20,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48520] = {id=48520,name="The Three Sisters",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="If you're looking to absolve Miss Waycrest of this mess, you'll need to head into the town. Recently, I've seen some oddly dressed women among the creatures, who seem to be calling the shots. It's likely that they're the key to this whole nightmare, but we can't get in to question them. Their minions don't seem to slow you down, though. If you can get to them, you might be able to find some answers for the both of us. Be careful, though. They likely aren't very friendly.",objectivesText="Confront Sister Ashwell , Sister Early , and Sister Mooring in Fletcher's Hollow.",rewardGold=514800,rewardXP=3455,rewardItems={152587,152590},starts={{npcID=126310}},ends={{npcID=126310}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48519},questLines={{id=383,name="Fletcher's Hollow",orderIndex=4,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=21,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48521] = {id=48521,name="Charming the Lifeless",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="<You've seen a charm like this in Fallhaven being used to control a wicker construct. If you can figure out how to use it, you may be able to take control of one of the coven's wicker constructs.>",objectivesText="Test the Wicker Charm on Dormant Ravagers in Fletcher's Hollow until you successfully control one. Progress: What's this?",rewardGold=257400,rewardXP=2765,rewardItems={152587,152590},ends={{npcID=126310}},startObjects={{objectID=273814,mapID=896,x=0.7,y=0.628}},coords={mapID=896,source="quest_giver",x=0.7,y=0.602},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48519},questLines={{id=383,name="Fletcher's Hollow",orderIndex=5,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=22,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48522] = {id=48522,name="A Revealing Missive",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="<The strange woman possessed a letter from someone calling herself \"Matron Levae\" which appears to have orders to take the town of Fletcher's Hollow. This could be the evidence needed to absolve Lucille Waycrest. Mayor Pare should be interested in seeing this.>",objectivesText="Return to Evelyn Pare .",rewardGold=30900,rewardXP=345,rewardItems={152587,152590},ends={{npcID=126310}},coords={mapID=896,source="quest_giver",x=0.7,y=0.602},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48520},questLines={{id=383,name="Fletcher's Hollow",orderIndex=6,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=23,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896,startItems={152587}},
[48523] = {id=48523,name="The Murderous Matron",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="I know that you've got what you came for, but I need to ask you one more favor. This town won't be safe until this Matron Levae is taken care of. According to the letter, she must be holed up in that cave. None of our people have been able to enter it, but I know I've seen their constructs go in! This charm you found might be the key. If you can take control of one of these wicker men and send it after her, we might have a shot!",objectivesText="Control the Dormant Ravager to defeat Matron Levae in the Elderstone Mine. Progress: Is she gone?",rewardGold=514800,rewardXP=3455,rewardItems={152587,152590},rewardCurrencies={{id=1553,amount=100}},starts={{npcID=126310}},ends={{npcID=126310}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48520,48521,48522},questLines={{id=383,name="Fletcher's Hollow",orderIndex=8,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=24,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48524] = {id=48524,name="Culling the Coven",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48171,48518,48519,48520,48521,48522,48523,48524,48525,48538,49295},description="If the mine really was their objective, I can only imagine they'd have even more forces in there. My men and I may be able to take care of the remnants out here, but if an even bigger force comes out of that mine, we're not going to stand a chance. While you're hunting down the matron with this wicker contraption, do you think you could... you know... soften them up a bit?",objectivesText="Kill 25 of Matron Levae's minions in the Elderstone Mine.",rewardGold=257400,rewardXP=2765,rewardItems={152587,152590},starts={{npcID=126310}},ends={{npcID=126310}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48520,48521,48522},questLines={{id=383,name="Fletcher's Hollow",orderIndex=9,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48525] = {id=48525,name="Break Them to Splinters",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={48171,48518,48519,48520,48521,48522,48523,48524,48525,48538,49295},objectivesText="Reclaim Fletcher's Hollow",rewardGold=455280,rewardXP=1415,rewardItems={152587,152590},mapCandidates={npc={},zone={8721}},questType="standard",sourceQuests={48519},questLines={{id=383,name="Fletcher's Hollow",orderIndex=7,flags=0}},db2Objectives={{text="Reclaim Fletcher's Hollow",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Break Them to Splinters",db2PoiMapID=1643,db2PoiUiMapID=896},
[48526] = {id=48526,name="Scuttled",level=45,requiredLevel=45,faction="none",categories={},flags={"rare"},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48526},objectivesText="Northern bomb planted Central bomb planted Southern bomb planted Get to a safe distance",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8899}},questType="standard",db2Objectives={{text="Northern bomb planted",amount=1,type=0,objectID=126535,orderIndex=0},{text="Central bomb planted",amount=1,type=0,objectID=126572,orderIndex=1},{text="Southern bomb planted",amount=1,type=0,objectID=126573,orderIndex=2},{text="Get to a safe distance",amount=1,type=0,objectID=126555,orderIndex=3}},worldTaskTitle="Scuttled",db2PoiMapID=1669,db2PoiUiMapID=885,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
[48527] = {id=48527,name="Ravenous Landsharks",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47226,47259,47261,47272,47310,47311,47312,47418,48527,48581,51990,51998},description="Warbeast Kraal is important to de empire. All de beasts dat haul our goods, carry our armies, and fight our wars are born and bred here. If you want Rastakhan's support, you had better impress us. I have some thoughts on where you can start. We have ourselves a diemetradon problem. Usually nothing to worry about, but dey had a big hatching dis year. Now dey're breaking into de pens and eating our eggs. Kill diemetradons, protect our beasts, and we will see about de rest.",objectivesText="Kill 9 Ravenous Diemetradon. Progress: Were you able to kill any diemetradon?",rewardGold=257400,rewardXP=1415,rewardItems={158387,158388,158389,158390,159764},rewardChoices={158387,158388,158389,158390,159764},starts={{npcID=121706}},ends={{npcID=121706}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47226},questLines={{id=5402,name="Warbeast Kraal",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[48529] = {id=48529,name="Hungry Mouths To Feed",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48529,48530,48531,48532,48533,48534,48585,48655,48656,48657,48790,48846,48847,48850,51573,51602,51668},description="We don't have much in de way of supplies right now. Mojambo and his gang will be back to finish us off, of dat I'm sure. But without food and supplies, dere will be none of us alive for dem to kill. Our cook is looking for someone to help gather supplies so we can feed de camp. Speak with him and see if you can find what he's looking for.",objectivesText="Speak with Sezahjin .",rewardGold=25740,rewardXP=515,starts={{npcID=126576}},ends={{npcID=126108}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51573},questLines={{id=5424,name="Champion of the Arena",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[48530] = {id=48530,name="I Heard You Lost the Herd",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48529,48530,48531,48532,48533,48534,48585,48655,48656,48657,48790,48846,48847,48850,51573,51602,51668},description="Our herd of alpacas went missing dis morning. It may seem like we have more pressing matters to worry about, but de meat and milk de alpacas provide are essential to our survival. Those alpacas won't survive long on de dunes. Speak with Mugjabu and help him find de alpacas before it's too late!",objectivesText="Speak with Mugjabu .",rewardGold=25740,rewardXP=515,starts={{npcID=126576}},ends={{npcID=126085}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51573},questLines={{id=5424,name="Champion of the Arena",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[48531] = {id=48531,name="Mystery Meat",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48529,48530,48531,48532,48533,48534,48585,48655,48656,48657,48790,48846,48847,48850,51573,51602,51668},description="Mojambo's gang may be coming to kill us, but we've still got to eat. And when you live in a harsh wasteland, you make do with what you've got. Sometimes fresh meat is hard to find. Dat's how I came up with de idea for my famous mystery meat pie. De secret ingredient is dung beetle, but with enough seasoning you can't even tell! Our food supplies are dangerously low right now. I need someone to go beetle hunting as soon as possible!",objectivesText="Collect 8 Dung Beetle Innards . Progress: Do you have de \"mystery ingredient\" for de mystery meat pie?",rewardGold=257400,rewardXP=4115,rewardItems={152566,163841},starts={{npcID=126108}},ends={{npcID=126108}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48529},questLines={{id=5424,name="Champion of the Arena",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[48532] = {id=48532,name="Alpacas Gone Wild",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48529,48530,48531,48532,48533,48534,48585,48655,48656,48657,48790,48846,48847,48850,51573,51602,51668},description="Our herd of alpacas escaped dis morning. Dey're out dere wandering de dunes as we speak. Probably for de best, if you ask me. We'll all be dead soon once Mojambo comes back. Since you seem to care so much, take dis alpaca whistle and use it to round dem up. I blow de whistle every day at feeding time, so de alpacas should come running home when dey hear de sound.",objectivesText="Round up 6 Alpacas.",rewardGold=257400,rewardXP=4115,rewardItems={152570},starts={{npcID=126085}},ends={{npcID=126085}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48530},questLines={{id=5424,name="Champion of the Arena",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[48533] = {id=48533,name="Vol'duni Fried Chicken",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48529,48530,48531,48532,48533,48534,48585,48655,48656,48657,48790,48846,48847,48850,51573,51602,51668},description="Have you ever tried my delicious Vol'duni fried chicken? Me neither! Probably because dere aren't any chickens in Vol'dun . Dere are plenty of vultures, though. Why don't you see if you can find some tasty vulture meat? De secret to delicious fried chicken is to roast de meat before you fry it, but it only works if de meat is fresh. I've soaked dese arrows in alpaca fat. If you ignite de arrows and shoot down de birds, dey'll start cooking before dey're even dead!",objectivesText="Collect 8 Roasted Buzzard . Progress: Do you have de buzzard meat?",rewardGold=257400,rewardXP=4115,rewardItems={42491,152571,152572,163208},rewardCurrencies={{id=1553,amount=75}},starts={{npcID=126108}},ends={{npcID=126108}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48529},questLines={{id=5424,name="Champion of the Arena",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[48534] = {id=48534,name="Snarltooth's Last Laugh",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48529,48530,48531,48532,48533,48534,48585,48655,48656,48657,48790,48846,48847,48850,51573,51602,51668},description="It's not just Mojambo's gang we have to worry about. We also need to keep a watchful eye at night due to frequent hyena attacks. De most dangerous of de hyenas is Snarltooth. He ambushes us at night, laughing maniacally as he slaughters his prey. I need you to slay de beast once and for all! Snarltooth's den is just south of de arena in de Arid Basin.",objectivesText="Retrieve Snarltooth's Head . Progress: Did you take care of Snarltooth?",rewardGold=514800,rewardXP=5145,rewardItems={152573},starts={{npcID=126085}},ends={{npcID=126085}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48531,48533},questLines={{id=5424,name="Champion of the Arena",orderIndex=8,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[48535] = {id=48535,name="Nazmir, the Forbidden Swamp",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={47103,47105},description="Da Horde promised Princess Talanji dat we be dealin' with dese blood trolls in Nazmir before dey can attack Zuldazar. Grab a pterrordax and get over ta Talanji's camp in Nazmir . We be waitin' for ya there. Make sure ya ready, . Dere be no civilization in Nazmir , just us and whatever be lurkin' dere.",rewardGold=25740,rewardXP=345,rewardChoices={179383},starts={{npcID=126549}},ends={{npcID=120904}},mapCandidates={npc={863,1165},zone={8500}},questType="standard",sourceQuests={47103},nextQuests={47105},questLines={{id=320,name="Nazmir, the Dark Jungle",orderIndex=1,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=2,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[48538] = {id=48538,name="An Airtight Alibi",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="It'll take us a while to clean up the beasts that are left over, but I'm confident we'll be able to take back Fletcher's Hollow--thanks to you, of course. Here, take this letter to the constable. It should be enough to clear Miss Waycrest's name. I'm sorry you had to witness all of this, mainlander. We are good people, but these are terrible times.",objectivesText="Deliver Evelyn Pare 's letter to Constable Henry Framer at Hangman's Point.",rewardGold=23870,rewardXP=345,rewardItems={152587,152590},starts={{npcID=126310}},ends={{npcID=125394}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48523},questLines={{id=383,name="Fletcher's Hollow",orderIndex=10,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=25,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48539] = {id=48539,name="Freehold",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={47489,48419,48505,48539,48558,48773,49239,49398,49399,49400,49401,49404},series={48419,48505},description="Well, there she is: Freehold. You can get anything you want there, provided you can pay for it. Whether you pay with gold or steel is up to you. Take a look.",objectivesText="Use Flynn's Spyglass. Progress: Look, I'm worldly, but I don't have anything you can catch from my eyes. Just use the spyglass, would ya?",rewardGold=257400,rewardXP=1415,rewardItems={152719,152720,152721,152722,153509,153680,153681,153682},starts={{npcID=126620}},ends={{npcID=126620}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48505},questLines={{id=587,name="Freehold",orderIndex=3,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=21,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48540] = {id=48540,name="Aiding the Wharf",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48008,48009,48347,48348,48352,48353,48354,48355,48356,48365,48366,48367,48368,48370,48372,48540,49268,49292,49299,49302},series={48347},description="We have read the tides, and never before have I seen them in such turmoil. They call to the tidesages, begging for help. A debilitating sickness is running rampant amongst the villagers, and it comes from the sea. We are but few. There is only so much we can do! Please, take this list and gather the listed reagents from around the pier while I attempt to calm these folks. I should be able to create a tonic that will help. I hope.",objectivesText="Collect a Satchel of Seaweed, a Bundle of Vellum , and some Seal Blubber from around Anglepoint Wharf.",rewardGold=128700,rewardXP=710,rewardItems={152401,152585,152586,153486,153513},starts={{npcID=125922}},ends={{npcID=125922}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48347},questLines={{id=592,name="The Shadow Over Anglepoint",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48542] = {id=48542,name="Strike Back",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8574,mapID=830,storyline={48542},description="The scroll details a dark spell which steals the souls from the neighboring Krokul to create a new demon, the Ur'zul. The scroll is signed by Lady Shahrazad .",objectivesText="Kill 8 Eredar ritualists and Lady Shahrazad in the Petrified Forest.",rewardGold=202200,rewardXP=6140,rewardItems={122457,152575},ends={{npcID=126160}},startObjects={{mapID=830,x=0.712,y=0.642}},coords={mapID=830,source="quest_giver",x=0.644,y=0.625},mapCandidates={npc={830},zone={8574}},questType="standard",startItems={152575}},
[48544] = {id=48544,name="Woah, Nelly!",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={47967,48441,48442,48443,48445,48446,48447,48448,48453,48455,48544,48600,48601,48654},description="<name>, you have my thanks. My Wranglers should be able to take it from here. If I can ask one more favor, would you pass a message to Chieftain Hatuun ? Tell him the forest is secure once again. I'm sure he will reward you for all of your effort. I'll loan you one of my fastest Cragscalers for the trip. Make sure to look both ways before crossing that path outside this forest, there's a giant Legion Obliterator that patrols there. Good luck!",objectivesText="Return to Chieftain Hatuun in Krokul Hovel.",rewardGold=151650,rewardXP=6140,rewardItems={152095,152096,152097},starts={{npcID=126160}},ends={{npcID=119388}},mapCandidates={npc={830},zone={8574}},questType="standard",sourceQuests={47967,48453,48455},questLines={{id=365,name="Petrified Forest",orderIndex=3,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=830},
[48545] = {id=48545,name="Strange Ecologies",level=1,requiredLevel=1,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=9102,storyline={48545},description="The local fauna here seem very docile and are attracted to some strange fauna on the caps above. Why don't you try riding one? See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(48545)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(48545))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Use the bats to get to the top of the mushroom caps.",mapCandidates={npc={},zone={9102}},questType="world"},
[48547] = {id=48547,name="Quest",level=1,requiredLevel=1,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=9102,storyline={48547},rewardGold=309800,rewardXP=1415,rewardItems={6797,6798,61487,61488,61489,81787,81788,81789,81790,81791,81792,81793,81794,81795,94219,94220,95622,95623},mapCandidates={npc={},zone={9102}},questType="dungeon"},
[48548] = {id=48548,name="Quest",level=1,requiredLevel=1,faction="both",categories={},flags={},sharable=false,expansion=7,storyline={48548},description="Armed with these energized spores, you feel compelled to slam them down on the spore stalks below... See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(48548)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(48548))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Use your Dive ability to crush the spore stalks below you.",rewardGold=309800,rewardXP=1415,rewardItems={6797,6798,61487,61488,61489,81787,81788,81789,81790,81791,81792,81793,81794,81795,94219,94220,95622,95623},mapCandidates={npc={},zone={}},questType="dungeon"},
[48549] = {id=48549,name="Grozztok the Blackheart",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47316,47317,47319,47320,47321,47959,48549,48550,51574},description="A group of us were dropped off here and left to die. Our first night at camp, I was jolted from sleep by de gurgling cries of my fellow exiles. Jakra'zet sent assassins to our camp, looking for Rakera. Their leader, Grozztok, came for me, but Rakera intervened. She chased him into de dunes, but dat was days ago. If you cross paths with Grozztok, don't hesitate to drive a blade into his black heart.",objectivesText="Kill Grozztok within Atul'Aman.",rewardGold=514800,rewardXP=5145,starts={{npcID=126696}},ends={{npcID=122289}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47959},questLines={{id=606,name="Dangers in the Desert",orderIndex=7,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=25,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[48550] = {id=48550,name="Stolen Satchels",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47316,47317,47319,47320,47321,47959,48549,48550,51574},description="One within our group spoke of a temple in de mountains dat welcomes exiles, though none are permitted to enter without an offering to their loa. I would have given anything to find some solace in dis wasteland, but now I have nothing, thanks to those thieving assassins. Each of us had a satchel dat carried de last of our possessions. We didn't have much, but it was more than one troll would need. If you search de dunes looking for your friend, could you keep an eye out for our satchels?",objectivesText="Collect 5 Weathered Satchels from Sandfury Assassins. Progress: Have you recovered our belongings?",rewardGold=257400,rewardXP=4115,rewardItems={152660,155400,155401,155402,155403,161269,161271,161273,161275},rewardChoices={155400,155401,155402,155403,161269,161271,161273,161275},starts={{npcID=126696}},ends={{npcID=126696}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47959},questLines={{id=606,name="Dangers in the Desert",orderIndex=8,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=17,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[48551] = {id=48551,name="Wither Without Water",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48551},description="The flora in this area weren't always so aggressive. Without water, the thistlevines wither and waste until they become something unrecognizable and angry. Take my watering can and wet the withering thistlevines to prevent them from becoming carnivorous.",objectivesText="Use Ranah's Watering Can to water 10 Withered Thistlevines .",rewardGold=257400,rewardXP=4115,rewardItems={152630},starts={{npcID=126814}},ends={{npcID=126814}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51829}},
[48553] = {id=48553,name="Let it Flow",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48553},description="The fountains here have seen better days. They're currently incapable of holding water, but we can fix that! You can use my spare tools to repair the cracks. With a little luck and elbow grease, the fountains will be flowing again in no time!",objectivesText="Repair the fountains within Withering Gulch. Progress: Getting the fountains working again is my top priority.",rewardGold=257400,rewardXP=4115,rewardItems={152813},starts={{npcID=126814}},ends={{npcID=126814}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51829}},
[48554] = {id=48554,name="The Source of the Problem",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48554},description="I checked my work twice when working on this fountain. I made no mistakes. There must be something wrong at the source. The fountain draws water from a modest reservoir above the terrace. Would you mind checking it out?",objectivesText="Help Ranah determine the cause of the malfunctioning fountain within the Withering Terrace. Progress: There's no good reason why this fountain should be malfunctioning.",rewardGold=257400,rewardXP=5145,rewardItems={152813,155392,155393,155394,155395,155448,159975,163036,163514,245263},rewardChoices={155392,155393,155394,155395,155448,159975},starts={{npcID=126814}},ends={{npcID=126814}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48551,48553,48555}},
[48555] = {id=48555,name="We Can Salvage the Seeds",level=30,requiredLevel=30,faction="horde",sharable=false,expansion=7,zoneID=16365,mapID=2512,description="I've studied the flora within the terrace extensively. Once a thistlevine completely dries out, it's too late for the plant to be saved. Its seeds are still viable, however. Under the right conditions, they can be used to cultivate new, healthy thistlevines. Salvage seeds from the carnivorous thistlevines that can no longer be saved, and plant them within the fertile mounds of dirt. The thistlevine plant is extremely quick to sprout, so the terrace should be filled with seedlings in no time!",rewardGold=257400,rewardXP=4115,starts={{npcID=126814}},ends={{npcID=126814}},mapCandidates={npc={864},zone={16365}},questType="standard",sourceQuests={51829}},
[48557] = {id=48557,name="Sowing Saplings",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48557},description="Algerson destroys the forests and leaves nothing remaining! It is up to us to take care of Azeroth, to help her live and grow as she was meant to! Take these seeds, find the soil that calls for them, and help our planet recapture her grace and vitality!",objectivesText="Plant seeds in 4 Loamy Soil .",rewardGold=257400,rewardXP=1415,starts={{npcID=129670}},ends={{npcID=129670}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={50699}},
[48558] = {id=48558,name="The Irontide Crew",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={47489,48419,48505,48539,48558,48773,49239,49398,49399,49400,49401,49404},description="You see those salty looking guys in red? That's the Irontide crew. They're the worst of the worst. Cutthroats and brigands, to a man. Irontide wouldn't be guarding the docks if they didn't stand to gain something... Lighten their pockets. See what kinda hardware they've got.",objectivesText="Collect 3 Azerite Cutlasses and 2 Horns of Azerite Powder from Irontide Cutthroats and Irontide Trickshots. Progress: What have you found?",rewardGold=257400,rewardXP=1415,rewardItems={152719,152720,152721,152722,153509,153680,153681,153682,155052,155058,155063,155066,155071,155073,155077,155080},rewardChoices={155077,155071,155080,155066,155058,155063,155073,155052},starts={{npcID=126620}},ends={{npcID=126620}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48539},questLines={{id=587,name="Freehold",orderIndex=4,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=22,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48559] = {id=48559,name="An Offering of Light",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=831,storyline={40238,46213,47431,47508,47526,47541,47652,47653,47743,47754,47771,48559,49143},description="I sense it. The nobility in Xe'ra's heart. Her relentless defiance of the Legion. Let this be her legacy. In building the Vindicaar, we fashioned the Netherlight Crucible to harness the tremendous powers at play on Argus. I believe Xe'ra's essence is one key to that potential. Yet the Light alone is not enough. Without balance, there can be no harmony, no cohesion. Infuse this essence into the crucible, champion. It is the first step in unlocking the strength needed to end the Burning Crusade.",objectivesText="Infuse the Essence of Light into the Netherlight Crucible.",rewardGold=202200,rewardXP=6140,rewardItems={152593},starts={{npcID=126307}},ends={{npcID=126307}},mapCandidates={npc={},zone={8574}},questGiverID=126307,questTurnInID=126307,questType="standard",sourceQuests={49143},questLines={{id=348,name="The Light Mother",orderIndex=12,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=348,questLineOrder=2,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2LabelIDs={4784},db2PoiMapID=1669,db2PoiUiMapID=831},
[48560] = {id=48560,name="An Offering of Shadow",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={48560},description="Can you sense it, <name>? The darkness within this essence is palpable. In the past, I might have shunned such power, even denied its very existence. But what have we learned throughout our long struggle, if not that Light and shadow must coexist? This may prove to be exactly what we need to bring balance to the Netherlight Crucible. To give us the edge we need against the Legion. Infuse this essence into the crucible, champion. Draw one step closer to realizing your weapon's full potential.",objectivesText="Infuse the Essence of Shadow into the Netherlight Crucible. Progress: Light and shadow... forces that shape our very existence.",rewardGold=202200,rewardXP=6140,rewardItems={152594},starts={{npcID=120533}},ends={{npcID=120533}},mapCandidates={npc={882},zone={8701}},questTurnInID=120533,questType="standard",sourceQuests={47220}},
[48573] = {id=48573,name="Crocolisk Life",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48573,48574,48576,48577,48578,48584,48590,48591,48669},description="I need my shaman mojo back if we are going to kill Urok. He beat me bad de last time I tried to put him down. You help me get my power back, and I help you make Urok dead. Deal? First step, I need you to use dis dagger to absorb what is left of de life force of any crocolisk you kill. When de dagger seems full, come find me. Heh heh, dat's right Sur'jan . Dey gonna help us, den Urok will see who de strongest is!",objectivesText="Absorb essence of 8 primal snapjaw corpses with Sur'jan's Ritual Dagger .",rewardGold=257400,rewardXP=2765,rewardItems={152596},rewardCurrencies={{id=1553,amount=50}},starts={{npcID=126713}},ends={{npcID=126713}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={48669},questLines={{id=5417,name="Urok, Terror of the Wetlands",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[48574] = {id=48574,name="Pulling Fangs",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48573,48574,48576,48577,48578,48584,48590,48591,48669},description="I need more things to help me get strong. I need you to get me some saurid teeth . No, Sur'jan , you're not trusting <him/her> TOO much. Just enough. I won't be betrayed again. I need dese teeth for a ritual I'm gonna perform to help me get my power back. Once I'm not so weak, you and I are gonna take down dis undead monster.",objectivesText="Recover 40 Saurid Teeth . Progress: You got enough teeth for me?",rewardGold=257400,rewardXP=2765,rewardItems={152595},starts={{npcID=126713}},ends={{npcID=126713}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={48669},questLines={{id=5417,name="Urok, Terror of the Wetlands",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[48576] = {id=48576,name="Safe Flying",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48573,48574,48576,48577,48578,48584,48590,48591,48669},description="I'm feeling... stronger! But I need more power before we take down Urok. No, Sur'jan , YOU are scared of Urok more than me. I'm not scared of nothing! You got an attachment to me now after dat ritual. I need you to go kill de skyterrors nearby. Their deaths will fuel my strength. Take my grappling hook. You can drag de skyterrors down from de sky with it, and it'll put de hurt on dem too.",objectivesText="Kill 8 Primal Skyterrors .",rewardGold=257400,rewardXP=2765,rewardItems={152610},starts={{npcID=126713}},ends={{npcID=126713}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={48573,48574},questLines={{id=5417,name="Urok, Terror of the Wetlands",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[48577] = {id=48577,name="Terrorizing their Eggs",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48573,48574,48576,48577,48578,48584,48590,48591,48669},description="Sur'jan , I should be doing dis! What do you mean, I need to recover? Bah, fine. I need more power, and de skyterrors have eggs nearby. I need you to bash some of their eggs to fuel my energy. Those eggs got lots of life force in dem. You destroy dem, and I will feel de energy coming back to me. Come on, Sur'jan , dis will be easy! I can do dis! Hmph... well, you make a good point. You always were de smarter one out of us.",objectivesText="Destroy 5 Skyterror eggs .",rewardGold=257400,rewardXP=2765,starts={{npcID=126713}},ends={{npcID=126713}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={48573,48574},questLines={{id=5417,name="Urok, Terror of the Wetlands",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[48578] = {id=48578,name="There's No Eye in Skyterror",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48573,48574,48576,48577,48578,48584,48590,48591,48669},description="There's a real big skyterror dat I name Jarkadiax. I need his tongue... What's dat, Sur'jan ? Not his tongue? His eye? You sure? Hrm. I need his eye for my next ritual. I know what you're thinking. De tongue makes more sense. Dat's what I-- Look, Sur'jan , I still think it's his tongue. We'll see which of us is right! Go get Jarkadiax's eye and bring it back to me for de next ritual.",objectivesText="Recover Jarkadiax's Eye . Progress: I need dat eye. You get it yet?",rewardGold=514800,rewardXP=3455,rewardItems={152600,155377,159074},rewardChoices={155377,159074},starts={{npcID=126713}},ends={{npcID=126713}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={48573,48574},questLines={{id=5417,name="Urok, Terror of the Wetlands",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[48581] = {id=48581,name="A Good Spanking",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47226,47259,47261,47272,47310,47311,47312,47418,48527,48581,51990,51998},description="Pinky is contained in de direhorn pen for now, but de handlers are having a real hard time with him! Dis calls for some tough love. Will you help dem?",objectivesText="Help the handlers subdue Pinky.",rewardGold=514800,rewardXP=1770,rewardItems={158408,158409,158410,158411,158431,158432,158433,158434},rewardChoices={158431,158432,158433,158434,158408,158409,158410,158411},starts={{npcID=122009}},ends={{npcID=121706}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47261},questLines={{id=5402,name="Warbeast Kraal",orderIndex=10,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[48584] = {id=48584,name="The Blood of My Enemies",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48573,48574,48576,48577,48578,48584,48590,48591,48669},description="I feel my power returning, but we aren't done yet. We need more power to kill dis undead Urok. We'll be pushing in to Urok's lair. Dreadticks are swarming in de area. I want you to bring me their blood for de final ritual. Take dis. It's my trusty dreadtick gasser. Throw it in de area, dreadticks sniff it... den DIE! Hahaha! Now get going! ... Sur'jan , you keep telling me to let <him/her> do dis sorta work, but I could do it too! Fine, I'll just work on getting de ritual ready.",objectivesText="Collect 45 Coagulated Dreadtick Blood . Progress: You get me dat blood yet?",rewardGold=280900,rewardXP=2765,rewardItems={152611,156618},starts={{npcID=126713}},ends={{npcID=126713}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={48576,48577,48578},questLines={{id=5417,name="Urok, Terror of the Wetlands",orderIndex=7,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[48585] = {id=48585,name="Wasteland Survivor",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48529,48530,48531,48532,48533,48534,48585,48655,48656,48657,48790,48846,48847,48850,51573,51602,51668},description="<The leather has become dry and cracked in the sun, but the supplies inside are mostly intact. It's unknown what gruesome death befell the backpack 's former owner, but supplies like these are in high demand among the outcasts. The desert has claimed many lives... perhaps there are more supplies to be found among the dunes. >",objectivesText="Collect 10 Scavenged Supplies . Progress: What do you have for me?",rewardGold=257400,rewardXP=4115,rewardItems={152601},ends={{npcID=126576}},startObjects={{objectID=273854,mapID=864,x=0.404,y=0.736}},coords={mapID=864,source="quest_giver",x=0.434,y=0.747},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50794},questLines={{id=5424,name="Champion of the Arena",orderIndex=6,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[48588] = {id=48588,name="Purge the Infection",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={48588},objectivesText="Infected saurolisks and eggs destroyed",rewardGold=352560,rewardXP=1415,mapCandidates={npc={},zone={8500}},questType="standard",sourceQuests={48584,48590},db2Objectives={{text="Infected saurolisks and eggs destroyed",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Purge the Infection",db2PoiMapID=1642,db2PoiUiMapID=863},
[48590] = {id=48590,name="My Head and Shoulders",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48573,48574,48576,48577,48578,48584,48590,48591,48669},description="If we're going to fight Urok, I will need my gear back. It was all lost when I was running from Urok de first time. Shut UP, Sur'jan ! I had to ditch it in order to run faster. Bring my gear back to me, and I'll be ready to fight Urok with you.",objectivesText="Recover Sur'jan 's head and shoulder gear. Progress: You got my gear?",rewardGold=257400,rewardXP=2765,rewardItems={156619,156620,156621},starts={{npcID=126713}},ends={{npcID=126713}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={48576,48577,48578},questLines={{id=5417,name="Urok, Terror of the Wetlands",orderIndex=8,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[48591] = {id=48591,name="Urok's True Death",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48573,48574,48576,48577,48578,48584,48590,48591,48669},description="This is it! My power is back; we are ready to put down Urok . He used to be a noble beast, you know. Big, strong. Now Urok is just a mindless undead. It isn't right. We'll put him to rest. I'm going to run up ahead. When you get near Urok , I'll hop out to ambush him. Let's do dis! Shut up, Sur'jan . Of course we're going to win! If we don't, I'll just find another <class> to help me out.",objectivesText="Defeat Urok .",rewardGold=514800,rewardXP=3455,rewardCurrencies={{id=1553,amount=50}},starts={{npcID=131872}},ends={{npcID=131872}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={48584,48590},questLines={{id=5417,name="Urok, Terror of the Wetlands",orderIndex=9,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[48592] = {id=48592,name="Holding the Spire",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={48592},objectivesText="Take control of the Lightforged Warframe Reinforcements slain Nath'raxxan Rift closed",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8574}},questType="world",db2Objectives={{text="Take control of the Lightforged Warframe",amount=1,type=0,objectID=124987,orderIndex=0},{text="Reinforcements slain",amount=60,type=0,objectID=125184,orderIndex=1},{text="Nath'raxxan Rift closed",amount=3,type=0,objectID=126741,orderIndex=2}},worldTaskTitle="Holding the Spire",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[48597] = {id=48597,name="Saurolisk Escape",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48003,48004,48005,48077,48080,48087,48088,48089,48195,48196,48597,48616,48670},description="You cautiously approach a saurolisk tied to a post. It doesn't snap at you, but looks at you with defeat in its eyes. The troggs seem to be keeping these saurolisks against their will. They should be freed before they are abused further.",objectivesText="Free 6 Trapped Saurolisks .",rewardGold=257400,rewardXP=1415,rewardItems={151913,152109,152642,152643,152670,152671,152675,152678,153357},starts={{npcID=126804}},ends={{npcID=127144}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48670},questLines={{id=591,name="The Norwington Estate",orderIndex=6,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48600] = {id=48600,name="Take the Edge Off",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8899,mapID=886,storyline={47967,48441,48442,48443,48445,48446,48447,48448,48453,48455,48544,48600,48601,48654},description="The demons streaming out of Antorus equip themselves at Felfire Armory. We need to deny those weapons. Will your <class>s fight alongside the Army of the Light once again? Before the assault, gather materials. My smiths will craft your soldiers more powerful armor. The Legion won't give up Felfire without a fight.",objectivesText="Raise 6 Champions to 950 Item Level. Progress: Make your preparations, <name>.",rewardItems={152095,152096,152097},starts={{npcID=124312}},ends={{npcID=124312}},mapCandidates={npc={},zone={8899}},questGiverID=124312,questTurnInID=124312,questType="standard",sourceQuests={48448},questLines={{id=365,name="Petrified Forest",orderIndex=12,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=886},
[48601] = {id=48601,name="Felfire Shattering",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8899,mapID=886,storyline={47967,48441,48442,48443,48445,48446,48447,48448,48453,48455,48544,48600,48601,48654},description="A thin series of stone bridges connects the Burning Breach to Felfire Armory over Fiend's Run. The Army of the Light will stem Legion reinforcements while your people deal with the armory itself. Work swiftly.",objectivesText="Use the Scouting Map and complete the mission, \"Assault on Felfire Armory.\"",rewardItems={152095,152096,152097,153130},starts={{npcID=124312},{npcID=93787}},ends={{npcID=124312}},mapCandidates={npc={},zone={8899}},questGiverID=124312,questTurnInID=124312,questType="standard",questLines={{id=365,name="Petrified Forest",orderIndex=13,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=886},
[48604] = {id=48604,name="Home Again, Home Again",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48604},description="I can't thank you enough for the help here! You showed up just in time. Here is Elijah's sausage order. Don't worry, it's just regular sausage- nothing questionable. Now if you'll excuse me I have to see to my workers.",objectivesText="Return to Elijah Eggleton in Fallhaven. Provided item:",rewardGold=23870,rewardXP=345,rewardItems={152629},mapCandidates={npc={},zone={8721}},questType="standard"},
[48605] = {id=48605,name="Commander's Downfall",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9024,mapID=885,storyline={48605},description="A champion of the Legion is vulnerable within an invasion point ! Track it down and destroy it before it can return to fight on Argus.",objectivesText="Complete a Greater Invasion Point scenario. Progress: The Legion must fall.",starts={{npcID=127051}},ends={{npcID=127051}},mapCandidates={npc={885},zone={8899}},questType="standard",sourceQuests={48513}},
[48606] = {id=48606,name="Loaded for Bear",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={48606},description="<This glittering cannonball stands out from the others. You notice the familiar sheen of Azerite across the surface. You can't help but notice the nearby cannon, conveniently pointed at the ships loaded with stores of Ashvane Company weapons.>",objectivesText="Use the Ashvane Cannon to destroy 6 Ashvane Co. Supplies . Azerite Cannonballs are required to fire the cannon.",rewardGold=257400,rewardXP=1415,rewardItems={152628},rewardCurrencies={{id=1560,amount=50}},ends={{npcID=127537}},startObjects={{objectID=276488,mapID=895,x=0.786,y=0.778}},coords={mapID=895,source="quest_giver",x=0.792,y=0.764},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48539}},
[48614] = {id=48614,name="Woeful Implications",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={48614},objectivesText="Felspawn slain Spire of Woe dismantled",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8574}},questType="world",db2Objectives={{text="Felspawn slain",amount=20,type=0,objectID=125109,orderIndex=0},{text="Spire of Woe dismantled",amount=5,type=0,objectID=126857,orderIndex=1}},worldTaskTitle="Woeful Implications",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[48615] = {id=48615,name="War Never Changes",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={48615},objectivesText="Lightforged Armament recovered",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8574}},questType="world",db2Objectives={{text="Lightforged Armament recovered",amount=6,type=0,objectID=126871,orderIndex=0}},worldTaskTitle="War Never Changes",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[48616] = {id=48616,name="Bolas and Birds",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48003,48004,48005,48077,48080,48087,48088,48089,48195,48196,48597,48616,48670},description="Up in the mountains we know the value of a good hunting companion. We use bolas to shoot down our flying prey, then our retrievers go and bring us our kill! You want to take a shot? Nickel can accompany you. Shoot down some of the falcons in the woods. My dog will finish the job.",objectivesText="Shoot down 6 Hollowbeak Falcons with the Bola Launcher .",rewardGold=257400,rewardXP=1415,rewardItems={151913,152109,152642,152643,152670,152671,152675,152678,153357},starts={{npcID=125398}},ends={{npcID=125398}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48070},questLines={{id=591,name="The Norwington Estate",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48620] = {id=48620,name="Greater Invasion Point: Mistress Alluradel",level=45,requiredLevel=45,faction="none",categories={"invasion"},flags={},sharable=false,expansion=7,zoneID=9300,storyline={48620},rewardXP=6140,rewardItems={151568,152351,153278},mapCandidates={npc={},zone={9300}},questType="standard",worldSystems={invasions={{id=19,name="Greater Invasion Point: Mistress Alluradel",scenarioID=1422,areaID=9300}}}},
[48622] = {id=48622,name="The Vanishing Lord",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8721,mapID=1161,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="Unfortunately, we don't have any contacts within House Waycrest, so our efforts in Drustvar will have to start from the ground up. We have arranged for a ferry to take you to Fallhaven - a farming village in eastern Drustvar . The mayor there, Cyril White , is a longtime friend of the Proudmoores, and I think he can help us get in touch with someone from the house. I hope you can get to the bottom of their absence, <name>. Their martial might is invaluable to the Kul Tiran fleet.",objectivesText="Meet with Cyril White in Fallhaven in Drustvar .",rewardGold=23400,rewardXP=345,starts={{npcID=121235}},ends={{npcID=121235}},mapCandidates={npc={1161},zone={8568}},questTurnInID=121235,questType="standard",sourceQuests={47961},questLines={{id=381,name="Fallhaven",orderIndex=0,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=1,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48624] = {id=48624,name="Who Let The Dogs Out?",level=45,requiredLevel=45,faction="none",categories={},flags={"rare"},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48624},objectivesText="Soldiers rescued",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8899}},questType="standard",db2Objectives={{text="Soldiers rescued",amount=6,type=0,objectID=126917,orderIndex=0}},worldTaskTitle="Who Let The Dogs Out?",db2PoiMapID=1669,db2PoiUiMapID=885,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
[48632] = {id=48632,name="Void Extract",level=1,requiredLevel=1,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={48632},description="The void calls to its own. When they are destroyed, powerful creatures of shadow leave behind vast amounts of undiluted void. It's lure is powerful enough to draw out the noxious influence polluting my brethren. Not all survive the purge, but the alternative is worse than death - you've seen the voidscarred roaming Oranaar. Destroy a powerful agent of shadow, collect its essence, and bring it to me. I will use it draw out the corruption.",objectivesText="Gather an Orb of Undiluted Void.",rewardItems={152096},mapCandidates={npc={},zone={8701}},questType="standard"},
[48634] = {id=48634,name="Further Supplying Krokuun",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={48634},description="This desolate place offers little for my people. Every hour is spent scraping together enough to survive. If I had more supplies, I could offer you another ridgestalker. What say you, offworlder?",objectivesText="Collect 900 Order Hall Resources. Progress: You seek the aid of another ridgestalker?",rewardItems={152095},starts={{npcID=119388}},ends={{npcID=119388}},mapCandidates={npc={830},zone={8574}},questGiverID=119388,questType="standard",sourceQuests={48443,48910}},
[48635] = {id=48635,name="More Void Inoculation",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={48635},description="All entities touched by shadow leave behind traces of void when they are defeated, If you collect enough in your travels through the city, return to me, and I will distill it into its undiluted form. We can save more of my kin.",objectivesText="Collect 100 Fragments of Condensed Void. Progress: Many of my brethren are deeply touched by shadow. It will take a tremendous effort to free them. Will you help?",rewardItems={152096},starts={{npcID=127037}},ends={{npcID=127037}},mapCandidates={npc={882},zone={8701}},questGiverID=127037,questType="standard",sourceQuests={48911}},
[48636] = {id=48636,name="Fueling the Antoran Campaign",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8899,storyline={48636},description="The Legion requires raw materials from conquered words to fuel their crusade. Travel through Legion portals, destroy demons you encounter, and deny them the resources required to maintain their war machine.",objectivesText="Complete 10 Invasion Points. Progress: War is costly work. Have you gathered additional supplies for our efforts here?",rewardItems={152097},starts={{npcID=124312}},ends={{npcID=124312}},mapCandidates={npc={},zone={8574}},questGiverID=124312,questTurnInID=124312,questType="standard",sourceQuests={48912}},
[48637] = {id=48637,name="Cleansing Fire",level=45,requiredLevel=45,faction="none",categories={},flags={"rare"},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48637},objectivesText="Spiders killed Spider Nests burned",rewardGold=202200,rewardXP=6140,rewardItems={152648},mapCandidates={npc={},zone={8899}},questType="standard",db2Objectives={{text="Spiders killed",amount=10,type=0,objectID=126986,orderIndex=0},{text="Spider Nests burned",amount=6,type=0,objectID=127557,orderIndex=1}},worldTaskTitle="Cleansing Fire",db2PoiMapID=1669,db2PoiUiMapID=885,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
