[48653] = {id=48653,name="A Bejeweled Prison",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48653},description="Nazmir and return the gem to it's rightful resting place, wherever that may be.>",objectivesText="Return the Restored Eye of Eternity to its resting place within the Dreadmire.",rewardGold=101100,rewardXP=1385,mapCandidates={npc={},zone={8500}},questType="standard",startItems={152655}},
[48654] = {id=48654,name="Beneath Oronaar",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={47967,48441,48442,48443,48445,48446,48447,48448,48453,48455,48544,48600,48601,48654},description="The krokul we found beneath Oranaar did not wish to leave. Could you speak with him, <name>? Convince him to board the Vindicaar.",objectivesText="Speak with the krokul beneath Oranaar.",rewardItems={152095,152096,152097},starts={{npcID=121230}},ends={{npcID=127037}},mapCandidates={npc={882},zone={8701}},questType="standard",sourceQuests={48445},questLines={{id=365,name="Petrified Forest",orderIndex=9,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=882},
[48655] = {id=48655,name="The Chef's Apprentice",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48529,48530,48531,48532,48533,48534,48585,48655,48656,48657,48790,48846,48847,48850,51573,51602,51668},description="< Sezahjin rummages through his cooking ingredients in frustration.> Where is Junji ? I sent him to scavenge for vulture eggs, but he hasn't returned. < Sezahjin pauses for a moment.> He was just going on about de size of saurolisk eggs, but those oversized lizards are far too dangerous for a boy! He can't possibly be so foolish... If he has gone to de saurolisk breeding grounds... he may already be dead. Please find him before it's too late!",objectivesText="Locate Junji .",rewardGold=10500,rewardXP=515,starts={{npcID=126108}},ends={{npcID=126108}},mapCandidates={npc={864},zone={8501}},questTurnInID=126108,questType="standard",sourceQuests={48531,48533},questLines={{id=5424,name="Champion of the Arena",orderIndex=7,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[48656] = {id=48656,name="Savage Saurolisks",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48529,48530,48531,48532,48533,48534,48585,48655,48656,48657,48790,48846,48847,48850,51573,51602,51668},description="Please, help me! I'm trapped in dis box and I can't make it out alone! I came here to collect eggs. I knew it was a bad idea, but I thought I could sneak around and grab de eggs before de saurolisks noticed. I was wrong... I hid underneath dis crate to avoid being eaten! Can you clear out de saurolisks and tell me when it's safe to come out? Please, don't leave me here!",objectivesText="Slay 8 Scaleclaw Saurolisks in the Arid Basin. Progress: Are de saurolisks gone yet?",rewardGold=257400,rewardXP=4115,startObjects={{objectID=276187,mapID=864,x=0.433,y=0.786}},endObjects={{objectID=276187,mapID=864,x=0.433,y=0.786}},coords={mapID=864,x=0.433,y=0.786},mapCandidates={npc={},zone={8501}},questType="standard",sourceQuests={48655},questLines={{id=5424,name="Champion of the Arena",orderIndex=9,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[48657] = {id=48657,name="They Might Be Delicious",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48529,48530,48531,48532,48533,48534,48585,48655,48656,48657,48790,48846,48847,48850,51573,51602,51668},description="Saurolisk eggs are de most delicious eggs in de desert! I mean, I've never tried dem myself... but look at de size of them! Dey're huge! Bigger is better, right? If I go back to camp empty handed, Sezahjin is going to kill me! We have to get some of those eggs! You sound a lot older and stronger than I am. Gather up de eggs so we can take dem back for everyone to eat. Don't worry about me, I'll wait for you here. It's not like I'm going anywhere...",objectivesText="Gather 10 saurolisk eggs from the Arid Basin. Progress: Do you have de saurolisk eggs ?",rewardGold=257400,rewardXP=4115,rewardItems={152647,159978,159996,159997,159998,159999},rewardChoices={159978,159996,159997,159998,159999},startObjects={{objectID=276187,mapID=864,x=0.433,y=0.786}},endObjects={{objectID=276187,mapID=864,x=0.433,y=0.786}},coords={mapID=864,x=0.433,y=0.786},mapCandidates={npc={},zone={8501}},questType="standard",sourceQuests={48655},questLines={{id=5424,name="Champion of the Arena",orderIndex=10,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[48662] = {id=48662,name="Short Fuses",level=45,requiredLevel=45,faction="none",categories={},flags={"rare"},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48662},objectivesText="Legion Hullbreaker fuses replaced",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8899}},questType="standard",db2Objectives={{text="Legion Hullbreaker fuses replaced",amount=6,type=0,objectID=127058,orderIndex=0}},worldTaskTitle="Short Fuses",db2PoiMapID=1669,db2PoiUiMapID=885,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
[48668] = {id=48668,name="Lightforged Beacon: City Center",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8701,mapID=882,storyline={48668},description="Hail, friend! Captain Fareeya sent us ahead to secure this area. We were just about to call down a beacon and report back to the Vindicaar. We would be honored if you would help us complete our mission. The signal beacon just needs a light touch. The Grand Artificer will do the rest.",objectivesText="Activate the Vindicaar Beacon . Progress: Grand Artificer Romuul is a reliable soul. We would be lost on this planet without him.",rewardGold=50550,starts={{npcID=127083}},ends={{npcID=127083}},mapCandidates={npc={882},zone={8701}},questType="standard",questLines={{id=370,name="Lightforged Beacon: City Center",orderIndex=0,flags=0}},db2PoiMapID=1669,db2PoiUiMapID=882},
[48669] = {id=48669,name="Urok, Terror of the Wetlands",level=20,requiredLevel=20,faction="horde",categories={},flags={"loremaster"},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48573,48574,48576,48577,48578,48584,48590,48591,48669},description="You! You can help me! I know, Sur'jan , <he/she> looks like a <class>, but I know we can trust <him/her>. Urok, de terror of de wetlands, is undead now. We have to put it down before it tries to destroy dis entire place. Just give me a minute, and you will see dat Urok is bad news. Shhh, Sur'jan , dey gonna see, dey are all gonna see!",objectivesText="See Urok, Terror of the Wetlands. Progress: Just give me a chance and you'll see!",rewardGold=25740,rewardXP=345,starts={{npcID=126713}},ends={{npcID=126713}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47188},questLines={{id=5417,name="Urok, Terror of the Wetlands",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[48670] = {id=48670,name="Runaway Rider",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48003,48004,48005,48077,48080,48087,48088,48089,48195,48196,48597,48616,48670},description="Lord Norwington demanded I take Eddie out riding in the woods, but I knew it was too soon! I just knew it! We've got to go find him. Meet me across the river!",objectivesText="Meet Melissa Kenny near Mistfall Cleft.",rewardGold=25740,rewardXP=175,rewardItems={151913,152109,152642,152643,152670,152671,152675,152678,153357},starts={{npcID=127006}},ends={{npcID=127144}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48077,48080,48616},questLines={{id=591,name="The Norwington Estate",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48677] = {id=48677,name="Wicker Worship",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48677,48678,48679,48682,48683},description="Hail, traveler! You look like just the sort who might be able to help me out with a predicament! It's my son Edwin, you see. We were travelling through Drustvar to ply our wares when the damned fool ran off to join some cult here in Autumnvale! Since then we haven't seen a trace of him, and the brown-robed loons won't speak a word of his whereabouts! Could you see if you could persuade them to talk? His poor mother is worried sick!",objectivesText="Meet Lord Autumnvale in Autumnvale.",rewardGold=21490,starts={{npcID=127296}},ends={{npcID=127080}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48622},questLines={{id=5448,name="Wicker Rituals",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48678] = {id=48678,name="Questionable Offerings",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48677,48678,48679,48682,48683},description="So the traders sent you? As I told them, I only discuss the happenings of our family with those who understand our cause. If you wish to know his whereabouts, you must prove that you do. Behind us are several items gathered for offering to the Wicker Man. Bring us the items you feel will most appease it, so that it might give us its blessing. Choose the correct offerings, and we will know your intent.",objectivesText="Bring the correct offerings to the Wicker Man in Autumnvale. Progress: You must bring the correct offerings if you wish to show us your understanding.",rewardGold=257400,rewardXP=2765,starts={{npcID=127080}},ends={{npcID=127080}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48677},questLines={{id=5448,name="Wicker Rituals",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48679] = {id=48679,name="Mind the Hives",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48677,48678,48679,48682,48683},description="The one called Edwin came to us not long ago, seeking to earn the blessings of the Wicker Man. He wandered off into the hills looking for his own offering. Unfortunately, he managed to disturb one of the nearby beehives, causing the insects to become rather frenzied. That was the last I saw of him, I'm afraid.",objectivesText="Find Edwin Maldus in Barbthorn Ridge. Progress: Yes?",rewardGold=257400,rewardXP=2765,starts={{npcID=127080}},ends={{npcID=127396}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48678},questLines={{id=5448,name="Wicker Rituals",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48680] = {id=48680,name="Not the Bees!",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={48680},objectivesText="Drive back the Barbthorn Swarm",rewardGold=455280,rewardXP=1415,mapCandidates={npc={},zone={8721}},questType="standard",sourceQuests={48678},db2Objectives={{text="Drive back the Barbthorn Swarm",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Not the Bees!",db2PoiMapID=1643,db2PoiUiMapID=896},
[48682] = {id=48682,name="A Simple Sacrifice",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48677,48678,48679,48682,48683},description="You must hurry! Lord Autumnvale brought Edwin off to that cave right when he returned, saying something about \"an offering of blood!\" I think they mean to sacrifice him to appease the Wicker Man! Just what kind of crazy cult is this?!",objectivesText="Rescue Edwin Maldus from the Wickerite cultists in Autumnvale. Progress: Help me!",rewardGold=514800,rewardXP=3455,starts={{npcID=127396}},ends={{npcID=127418}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48679},questLines={{id=5448,name="Wicker Rituals",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48683] = {id=48683,name="Changing Seasons",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48677,48678,48679,48682,48683},description="I appreciate you saving me again, but we should do something to prevent this from happening to anyone else. So long as that Wicker Man stands, it will attract more like Autumnvale to it. We should destroy it! Are you with me?",objectivesText="Burn the Wicker Man in Autumnvale. Progress: The Wicker Man must be destroyed!",rewardGold=128700,rewardXP=1385,rewardItems={158592,158594,158615,158616,158617,158618},rewardChoices={158592,158594,158615,158616,158617,158618},starts={{npcID=127418}},ends={{npcID=126979}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48682},questLines={{id=5448,name="Wicker Rituals",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[48684] = {id=48684,name="On the Move",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},series={48895},description="Jorak 's wounds have healed enough for him to travel. He has agreed to guide us to de temple. De sooner we leave, de better. Rakera won't survive in dis desert for long.",objectivesText="Travel with Meerah's Caravan in search of Warguard Rakera.",rewardGold=128700,rewardXP=2060,rewardItems={182180,184948,184949,184950,184951,184952,184953,184954,184955,184956,186201,186205,186206,187328,187334,187336,187466},starts={{npcID=122289}},ends={{npcID=127691}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48549,48550},questLines={{id=607,name="The Warguard's Fate",orderIndex=0,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=18,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
