[48699] = {id=48699,name="Sneaking into Zalamar",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="I know you might think nothing has changed, but trust me, de voodoo worked... I think. You should transform into one of de blood trolls when you are near Zalamar, one of their villages. Jo'chunga should be dere somewhere, most likely near a large gathering of blood trolls. Find Jo'chunga and tell him I have sent you, den see what he knows about de situation dere.",rewardGold=128700,rewardXP=1385,starts={{npcID=122795}},ends={{npcID=127391}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49440},questLines={{id=374,name="The Loa of Bats",orderIndex=1,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=22,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
