[48715] = {id=48715,name="Akunda Awaits",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="I've spoken to every troll out here, asking if they've seen Rakera. As you might have guessed, Akunda is de only name dey know. Let's hope someone within de temple will be able to tell us something useful.",objectivesText="Investigate the Temple of Akunda.",rewardGold=128700,rewardXP=2060,starts={{npcID=127570}},ends={{npcID=135066}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48894},questLines={{id=607,name="The Warguard's Fate",orderIndex=8,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=26,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
