[48929] = {id=48929,name="Sizing Up The Opposition",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8899,mapID=885,storyline={47473,48199,48200,48201,48202,48929},description="No doubt your High Exarch will fret at the news that we lack the resources to assault Antorus. He is not used to believing his vaunted Army of the Light to be inadequate. His pride is no concern of mine. While he plots a new strategy, I will bathe the ground in demon blood. Go. There is much to be done before we can achieve our final victory.",objectivesText="Speak with Turalyon.",rewardGold=50550,rewardXP=6140,starts={{npcID=127051}},ends={{npcID=127051}},mapCandidates={npc={885},zone={8899}},questTurnInID=127051,questType="standard",sourceQuests={48202},questLines={{id=371,name="The Heart of Argus",orderIndex=5,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=371,questLineOrder=3,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2LabelIDs={4784},db2PoiMapID=1669,db2PoiUiMapID=886},
[48931] = {id=48931,name="Behemoths Awakened",level=45,requiredLevel=45,faction="none",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48931},objectivesText="Hadrox slain Radix slain",rewardGold=238680,rewardXP=6140,rewardItems={212778},mapCandidates={npc={},zone={8899}},questType="standard",db2Objectives={{text="Hadrox slain",amount=1,type=0,objectID=127670,orderIndex=0},{text="Radix slain",amount=1,type=0,objectID=127671,orderIndex=1}},worldTaskTitle="Behemoths Awakened",db2PoiMapID=1669,db2PoiUiMapID=885,db2QuestInfoID=111,db2QuestInfoName="Elite World Quest"},
[48934] = {id=48934,name="Mark of the Damned",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={48934},objectivesText="Corrupted Spirits disrupted Ancient Spirits slain",rewardGold=455280,rewardXP=1415,mapCandidates={npc={},zone={8500}},questType="standard",sourceQuests={47247,47491},db2Objectives={{text="Corrupted Spirits disrupted",amount=1,type=15,objectID=0,orderIndex=0},{text="Ancient Spirits slain",amount=34,type=0,objectID=123039,orderIndex=1}},worldTaskTitle="Mark of the Damned",db2PoiMapID=1642,db2PoiUiMapID=863},
[48936] = {id=48936,name="Slithon the Last",level=45,requiredLevel=45,faction="none",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=8701,mapID=882,storyline={48936},rewardGold=606600,rewardXP=9210,mapCandidates={npc={},zone={8701}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=126913}},worldTaskTitle="Slithon the Last",db2PoiMapID=1669,db2PoiUiMapID=882,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[48937] = {id=48937,name="Create Netherwalker's Portal Generator",level=1,requiredLevel=1,faction="none",categories={},flags={},sharable=true,expansion=7,storyline={48937},rewardGold=312800,rewardXP=200,rewardItems={152891},mapCandidates={npc={},zone={}},questType="standard"},
[48939] = {id=48939,name="Show Me What You've Got",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48939},description="It looks like you understand the basics. Now it's time to put everything together. Head for the ring. Once you hear the starting pistol, you will have one minute to score as high as possible. Gnolls are worth one point. Run 'em through with the harpoon! If you see a paper zeppelin, bag it with your bolas for fifty points! Leaping fences gives you style. Style gives you more points when you skewer gnolls or down zeppelins. It's super important, so don't forget to keep jumping fences!",objectivesText="Mount Cooper to begin your show and score at least 150 points. Progress: Kul Tiran riding is a true show of mastery and sport!",rewardGold=257400,rewardXP=1415,rewardItems={151913,152109,152642,152643,152670,152671,152675,152678,153357},starts={{npcID=124802}},ends={{npcID=124802}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48004}},
[48941] = {id=48941,name="A Slight Detour",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48941,48942,48943,48944,48945,48946,48963,49259},description="If this coven is drawing its power from these ancient ruins, then I may just know of something that could help us fight back. Meet me at the first fork along the Highroad Pass. There is something there I want you to see.",objectivesText="Meet with Lucille Waycrest at Highroad Pass in Drustvar .",rewardGold=23870,rewardXP=345,rewardItems={153053,159748},starts={{npcID=125380}},ends={{npcID=127715}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={49259},questLines={{id=384,name="Alpine Rise",orderIndex=1,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=26,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48942] = {id=48942,name="Yeti to Rumble",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48941,48942,48943,48944,48945,48946,48963,49259},description="It would seem that the guard have been lax in patrolling the Highroad Pass. The mountain yetis have taken advantage of their absence, and now lie directly in our path. I am no soldier, <class>, so I will need to ask that you take care of them while I try to sneak past. If we can drive them off the road, at least it will make the pass safe again for travelers.",objectivesText="Kill 8 Chillfur Yetis in Alpine Rise. Progress: We should drive the yetis back from the road. Having a major trade route cut off by monsters isn't going to help our fight against the coven.",rewardGold=257400,rewardXP=2765,rewardItems={153053,159748},starts={{npcID=127715}},ends={{npcID=127715}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48941},questLines={{id=384,name="Alpine Rise",orderIndex=2,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=27,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48943] = {id=48943,name="Salvage Rights",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48941,48942,48943,48944,48945,48946,48963,49259},description="This poor trader was set upon by the yetis. There's nothing we can do for him now, but we would be remiss to let his supplies be laid to waste by these brutes. See if you can find any supplies worth salvaging. You can use Bella as a pack horse. Don't worry, she's a brave mare. She won't spook easily.",objectivesText="Recover the Wrapped Supplies, Cask of Salted Fish, Hardened Lockbox, and Bucket of Grain from Alpine Rise. Progress: Have you found anything salvageable?",rewardGold=309800,rewardXP=2765,rewardItems={153053,159748},rewardCurrencies={{id=1560,amount=50}},starts={{npcID=127715}},ends={{npcID=127715}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48941},questLines={{id=384,name="Alpine Rise",orderIndex=3,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=28,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48944] = {id=48944,name="Unlocking History",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48941,48942,48943,48944,48945,48946,48963,49259},description="I'm sure you're wondering why I've brought you here. Located somewhere inside this cottage is a hidden door. If we can find a way to access it, the answer to your questions, and possibly our survival against the coven, should lie beyond. Help me search for it, <class>.",objectivesText="Find the secret passageway in the Forgotten Lodge. Progress: The opening must be here somewhere...",rewardGold=257400,rewardXP=2765,rewardItems={153053},starts={{npcID=127715}},ends={{npcID=127715}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48963},questLines={{id=384,name="Alpine Rise",orderIndex=5,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=30,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48945] = {id=48945,name="The Ruins of Gol Var",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={48941,48942,48943,48944,48945,48946,48963,49259},description="What lies beyond are more ruins, much like those the coven sought. However, these ruins served a different purpose, one that established the legacy of House Waycrest thousands of years ago. Let us head inside, and I will explain.",objectivesText="Escort Lucille Waycrest into Gol Var. Progress: Just a little further...",rewardGold=772200,rewardXP=4150,rewardItems={153053},starts={{npcID=127715}},ends={{npcID=127715}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48944},questLines={{id=384,name="Alpine Rise",orderIndex=6,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=31,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48946] = {id=48946,name="The Order of Embers",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48941,48942,48943,48944,48945,48946,48963,49259},description="The Order of Embers was the name given to those who took up these arms against the Drust. Using the tools and methods uncovered by the scholars, they were able to counter the Drust's magic, and ensure our victory in the war. If the coven wants to use the Drust's magic against us, then we'll use the order's weapons against them. The knowledge of the order rests here, but without a hand to wield it, it will do us no good. Will you be that hand, <class>? Will you revive the Order of Embers?",objectivesText="Take the Tome of Silver and Ash in Gol Var. Progress: What say you?",rewardGold=257400,rewardXP=2765,rewardItems={153053},rewardCurrencies={{id=1553,amount=100}},starts={{npcID=127715}},ends={{npcID=127715}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48945},questLines={{id=384,name="Alpine Rise",orderIndex=7,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=32,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48947] = {id=48947,name="Gol Koval",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48947},description="A group of hunters went up into the hills awhile ago and we haven't heard back from them. My niece is up there and it isn't like her to be out of touch for so long! Would you please find her? She was headed towards Gol Koval.",objectivesText="Find Rebecca Hale in Gol Koval.",rewardGold=23870,rewardXP=345,starts={{npcID=127743}},ends={{npcID=125457}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={49259},nextQuests={52074}},
[48948] = {id=48948,name="The North Pass Caverns",level=20,requiredLevel=20,faction="alliance",categories={},flags={"loremaster"},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48948},description="Please, you must help! My grandson got lost around the caves to the north, and I'm so afraid that the troggs might have got him! My husband went after him, but he's getting on in years, and I fear he imagines himself tougher than he really is. Could you help them? You should be able to catch up with Thaddeus along the northern road.",objectivesText="Find Thaddeus Rifthold near the North Pass Caverns.",rewardGold=26680,rewardXP=345,starts={{npcID=128457}},ends={{npcID=127015}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={47982},nextQuests={48792,48793}},
[48949] = {id=48949,name="Weeds of the Mire",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={48949},description="Help me... weak... can't heal... Graveweed... help... more... please...",objectivesText="Collect 6 sprigs of Graveweed from the Dreadmire.",rewardGold=202200,rewardXP=2765,rewardItems={152895},mapCandidates={npc={},zone={8500}},questType="standard"},
[48951] = {id=48951,name="Seat of the Triumvirate: Voidmaw",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8910,mapID=882,storyline={48951},objectivesText="Voidmaw slain L'ura slain",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8910}},questType="standard",db2Objectives={{text="Voidmaw slain",amount=1,type=0,objectID=122456,orderIndex=0},{text="L'ura slain",amount=1,type=0,objectID=124729,orderIndex=1}},worldTaskTitle="Seat of the Triumvirate: Voidmaw",db2PoiMapID=1669,db2PoiUiMapID=882,db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
[48952] = {id=48952,name="Throw Them a Bone",level=45,requiredLevel=45,faction="none",categories={},flags={"rare"},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48952},objectivesText="Slave Traps disarmed",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8899}},questType="standard",db2Objectives={{text="Slave Traps disarmed",amount=3,type=0,objectID=127722,orderIndex=1}},worldTaskTitle="Throw Them a Bone",db2PoiMapID=1669,db2PoiUiMapID=885,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
[48953] = {id=48953,name="Seat of the Triumvirate: Darkcaller",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8910,mapID=882,storyline={48953},objectivesText="Darkcaller slain L'ura slain",rewardGold=309800,rewardXP=6140,mapCandidates={npc={},zone={8910}},questType="standard",db2Objectives={{text="Darkcaller slain",amount=1,type=0,objectID=122457,orderIndex=0},{text="L'ura slain",amount=1,type=0,objectID=124729,orderIndex=1}},worldTaskTitle="Seat of the Triumvirate: Darkcaller",db2PoiMapID=1669,db2PoiUiMapID=882,db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
[48954] = {id=48954,name="Blood of a Titan",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=7502,mapID=627,storyline={48954},description="<Before your eyes, a trickle of blood from the fallen titan Argus congeals into a flawless gemstone. Holding it in your palm, you sense an almost unfathomable power emanating from within... along with echoes of pain and sorrow. It is the last remnant of a battle that should not have been winnable. An impossible achievement. Yet, as with all victories, this one came at tremendous cost. You realize immediately to whom you must convey this prize.>",objectivesText="Bring the blood of Argus the Unmaker to Khadgar in Dalaran. Provided item:",rewardXP=1535,rewardItems={104246,128422,152900,152901},mapCandidates={npc={},zone={7502}},questType="standard",startItems={152900}},
[48957] = {id=48957,name="Seat of the Triumvirate: Void-Blade Zedaat",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8910,mapID=882,storyline={48957},objectivesText="Void-Blade Zedaat slain L'ura slain",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8910}},questType="standard",db2Objectives={{text="Void-Blade Zedaat slain",amount=1,type=0,objectID=127911,orderIndex=0},{text="L'ura slain",amount=1,type=0,objectID=124729,orderIndex=1}},worldTaskTitle="Seat of the Triumvirate: Void-Blade Zedaat",db2PoiMapID=1669,db2PoiUiMapID=882,db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
[48958] = {id=48958,name="Ritual Interruption",level=45,requiredLevel=45,faction="none",categories={},flags={"rare"},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48958},objectivesText="Banish the Everburning Doombringer",rewardGold=202200,rewardXP=6140,rewardItems={152465},mapCandidates={npc={},zone={8899}},questType="standard",db2Objectives={{text="Banish the Everburning Doombringer",amount=1,type=0,objectID=127811,orderIndex=1}},worldTaskTitle="Ritual Interruption",db2PoiMapID=1669,db2PoiUiMapID=885,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
[48959] = {id=48959,name="Seat of the Triumvirate: Dark Fissures",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8910,mapID=882,storyline={48959},objectivesText="Dark Fissure closed L'ura slain",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8910}},questType="standard",db2Objectives={{text="Dark Fissure closed",amount=4,type=0,objectID=127767,orderIndex=0},{text="L'ura slain",amount=1,type=0,objectID=124729,orderIndex=1}},worldTaskTitle="Seat of the Triumvirate: Dark Fissures",db2PoiMapID=1669,db2PoiUiMapID=882,db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
[48962] = {id=48962,name="Telogrus Rift",level=40,requiredLevel=40,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=1519,mapID=84,storyline={48962,49787},description="Umbric and his blood elves were cast out of their home for their pursuit of understanding. I know the dangers of the void better than most. We should lend them our aid and ensure they don't do anything too foolhardy. This rift will take us to their current location. I hope we are not too late to help them.",objectivesText="Travel to Telogrus Rift and complete the scenario.",rewardGold=319000,rewardXP=5465,rewardItems={155656,156486},starts={{npcID=130919}},ends={{npcID=126301},{npcID=126332},{npcID=234616}},mapCandidates={npc={84},zone={1519}},questGiverID=130919,questType="standard",sourceQuests={49787},questLines={{id=532,name="Allies of the Alliance: Void Elf",orderIndex=1,flags=0},{id=5697,name="Lorewalking: Elves",orderIndex=8,flags=0}},campaigns={{id=274,title="Lorewalking:Elves",questLineID=5697,questLineOrder=0}},db2PoiMapID=530,db2PoiUiMapID=95},
[48963] = {id=48963,name="Diversionary Tactics",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48941,48942,48943,48944,48945,48946,48963,49259},description="Our destination is that cottage up ahead. I know it doesn't look like much, but a great deal of history is hidden inside. First, though, we'll need to deal with that massive yeti camped just outside. I'd hate to ask it of you, but I'll need you to draw his attention so I can slip inside. Once you've taken care of him, I'll meet you within.",objectivesText="Defeat Frostmange in Alpine Rise. Progress: I'll meet you inside, <class>.",rewardGold=619600,rewardXP=3455,rewardItems={153053,159748},starts={{npcID=127715}},ends={{npcID=127715}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48942,48943},questLines={{id=384,name="Alpine Rise",orderIndex=4,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=29,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48964] = {id=48964,name="Immortal Ace",level=1,requiredLevel=1,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8899,mapID=885,storyline={48964},description="An effigy. The Many-Faced One requires it. Steal from the Imps. Steal from the Fiends. Steal from the Ur'zul. He comes.",objectivesText="Collect bones from the Antoran Wastes to form a bone effigy.",rewardGold=194000,rewardXP=200,rewardItems={152786},mapCandidates={npc={},zone={8899}},questType="standard"},
[48965] = {id=48965,name="Settle the Score",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48965},description="A year ago I lost my daughter to the largest boar in the forest. I have tracked him since, trading blows back and forth. But this time... Let's just say I don't have much time left. All I wish for is vengeance. Please <class>, avenge us so that my soul can leave this plane and join my daughter, wherever she may be.",objectivesText="Kill Chartusk in Foxhollow Woods. Progress: Though my lifeblood drains, all I yearn for is vengeance.",rewardGold=514800,rewardXP=1770,rewardItems={39676,39678,39679,39680},starts={{npcID=127803}},ends={{npcID=127803}},mapCandidates={npc={895},zone={8567}},questType="standard"},
[48973] = {id=48973,name="Paragon of Argussian Reach",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48973},description="Your allies among the Argussian Reach have requested your presence. They wish to reward you for your continued efforts on their behalf.",objectivesText="Speak with Toraan the Revered on the Vindicaar.",ends={{npcID=127151}},mapCandidates={npc={830},zone={8899}},questType="standard"},
[48974] = {id=48974,name="Paragon of the Army of the Light",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48974},description="Your allies in the Army of the Light would like to thank you for your continued support. They await you on the Vindicaar.",objectivesText="Speak with Vindicator Jaelaana on the Vindicaar.",ends={{npcID=127120}},mapCandidates={npc={830},zone={8899}},questType="standard"},
[48976] = {id=48976,name="Supplies From the Argussian Reach",level=45,requiredLevel=45,faction="both",categories={"emissary","paragon"},flags={},sharable=false,expansion=7,zoneID=8899,storyline={48976},description="<class>t, thanks to your efforts, our forces have been able to locate resources and prevent them from falling into the Legion's hands. With your continued assistance, we will be able to provide additional resources.",objectivesText="Speak with Toraan the Revered on the Vindicaar.",rewardItems={152922},starts={{npcID=127151}},ends={{npcID=127151}},mapCandidates={npc={},zone={8574}},questGiverID=127151,questTurnInID=127151,questType="standard",worldSystems={paragonReputation={{factionID=2167,threshold=10000}}}},
[48977] = {id=48977,name="Supplies From the Army of the Light",level=45,requiredLevel=45,faction="both",categories={"emissary","paragon"},flags={},sharable=false,expansion=7,zoneID=8899,storyline={48977},description="Archenon poros, champion. The Army of the Light wishes to thank you for your aid against the Legion's forces on Argus. Please accept these supplies with our gratitude. Your continued support brings us ever closer to our ultimate goal of eradicating the Legion once and for all.",objectivesText="Speak with Vindicator Jaelaana on the Vindicaar for your reward.",rewardItems={152923,153043,153044},starts={{npcID=127120}},ends={{npcID=127120}},mapCandidates={npc={},zone={8574}},questGiverID=127120,questTurnInID=127120,questType="standard",worldSystems={paragonReputation={{factionID=2166,threshold=10000}}}},
[48983] = {id=48983,name="Mining Regulation",level=45,requiredLevel=45,faction="none",categories={},flags={"rare"},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={48983},objectivesText="Stop the Legion Mining Effort",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8899}},questType="standard",db2Objectives={{text="Stop the Legion Mining Effort",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Mining Regulation",db2PoiMapID=1669,db2PoiUiMapID=885,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
[48985] = {id=48985,name="Seat of the Triumvirate: Twilight-Harbinger Tharuul",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8910,mapID=882,storyline={48985},objectivesText="Twilight-Harbinger Tharuul slain L'ura slain",rewardGold=202200,rewardXP=6140,mapCandidates={npc={},zone={8910}},questType="standard",db2Objectives={{text="Twilight-Harbinger Tharuul slain",amount=1,type=0,objectID=127906,orderIndex=0},{text="L'ura slain",amount=1,type=0,objectID=124729,orderIndex=1}},worldTaskTitle="Seat of the Triumvirate: Twilight-Harbinger Tharuul",db2PoiMapID=1669,db2PoiUiMapID=882,db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
[48986] = {id=48986,name="Take the High Road",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48986,49443,49803,49804,49805,49806,49807},description="Let us continue to Arom's Stand. It will take some time to parse the knowledge of the tome and train more inquisitors for our cause. If the order's weapons are as effective against the coven as they were against the Drust, we may stand a chance of rescuing my family and restoring this land to its former glory. I will make my way there on foot. Until we meet again, <class>.",objectivesText="Meet with Lucille Waycrest at Arom's Stand in Drustvar .",rewardGold=30900,rewardItems={156515,156518,156532,163607},starts={{npcID=127715}},ends={{npcID=129642}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48946},questLines={{id=597,name="Arom's Stand",orderIndex=0,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=33,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[48987] = {id=48987,name="Valley of Sorrows",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="Your friend's memories are gone. Dat is Akunda's gift to us. He takes away our painful memories, but a lot more than dat has gone missing lately. I can't even remember what I had for breakfast, and it's getting worse by de day. Something's not right. Meijani and I had a plan. We were going to do... something... in de Valley of Sorrows. It's where Akunda keeps de forgotten memories. If you're looking for answers, finding Meijani is de best place to start.",objectivesText="Find Meijani in the Valley of Sorrows.",rewardGold=25740,rewardXP=515,starts={{npcID=127980}},ends={{npcID=127989}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48715},questLines={{id=607,name="The Warguard's Fate",orderIndex=9,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=27,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[48988] = {id=48988,name="Memory Breach",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="De memories of Akunda's followers rest within dis valley. Most are best left forgotten, but dey may be our only chance to find out what happened to Akunda. Look back upon de memories here. See if you can find any clues about what happened to our loa. Be warned. Dis task is not for de weak. What you witness in dese memories can't be unseen.",objectivesText="Look for clues within Unwanted Memories. Progress: Peer into de memories. See what you can find.",rewardGold=257400,rewardXP=4115,starts={{npcID=127989}},ends={{npcID=127989}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48987},questLines={{id=607,name="The Warguard's Fate",orderIndex=10,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=28,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[48991] = {id=48991,name="Vile Infestation",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="Redemption must be earned. We do good works to show Akunda we are worthy of his blessing. De ranishu are a plague upon these lands. Dey devour everything in sight, with no regard for taste or texture. If dey go unchecked, those vile pests will eat their way straight to de temple. Rid de mesa of their presence. Show Akunda you are worthy of his gift.",objectivesText="Slay 12 ranishu in Redrock Mesa.",rewardGold=257400,rewardXP=4115,starts={{npcID=127992}},ends={{npcID=127992}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48895},questLines={{id=607,name="The Warguard's Fate",orderIndex=4,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=21,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[48992] = {id=48992,name="Sacred Remains",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="Dis area was once a lush jungle, home to many great and powerful thunder lizards. De bones of those ancient and powerful creatures are still buried around de temple. Great power lingers within those ancient remains... you will need such power to call upon Akunda. Search de area and return to me with de ancient bones of de thunder lizards.",objectivesText="Collect 6 Sacred Remains . Progress: Have you found de ancient bones?",rewardGold=257400,rewardXP=4115,rewardItems={153028},starts={{npcID=127992}},ends={{npcID=127992}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48895},questLines={{id=607,name="The Warguard's Fate",orderIndex=3,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=20,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[48993] = {id=48993,name="Powerful Conductors",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="Akunda offers us a chance to start anew. Through a sacred ritual, de loa enters our mind and removes de memories dat cause us pain. If you seek Akunda's blessing, den you must first prepare for de ritual. De pests dat feed on de wildlife here have antennae dat are great conductors for magic. De larger, de better. Their leader's antennae should do de trick. He's easily three times de size of de normal ranishu.",objectivesText="Retrieve Rorgog's Antennae . Progress: Do you have de antennae?",rewardGold=257400,rewardXP=4115,rewardItems={153029,155451,159979},rewardChoices={159979,155451},starts={{npcID=127992}},ends={{npcID=127992}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48895},questLines={{id=607,name="The Warguard's Fate",orderIndex=2,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=13,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[48996] = {id=48996,name="Ending the Madness",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="Akunda the Exalted is not who he seems. He poisoned the eternal spring, sickening all who drank from it. Even I was not immune to his abhorrent alchemy. Now he drains my power, abusing my gift to wipe the minds of all who might try to stop him. We will not let him succeed. What little power I have left, I will lend to you. Use it to call the storm and end the madness that has taken over my temple.",objectivesText="Defeat Akunda the Exalted .",rewardGold=772200,rewardXP=6175,rewardItems={155385,155386,155387,155404,155405,155406,155407,155408},rewardChoices={155385,155386,155387,155404,155405,155406,155407,155408},starts={{npcID=138382}},ends={{npcID=128152}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48889},questLines={{id=607,name="The Warguard's Fate",orderIndex=13,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=31,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49001] = {id=49001,name="Inconvenient Spirits",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48330,48331,48332,48334,48335,49001,49139},series={48322,48335,48840},description="The sethrak have oppressed vulpera like me for countless generations. You can't fight 'em. Trust me, $pr. My caravan tried. I took that beating as a lesson, and then I found a new pack to run with. Here, we keep our distance from the sethrak and scavenge ruins like this one for anything valuable we can use or trade. You want in? We could use a fourth. This one's protected by nasty spirits that keep harassing us. Take them out and you're in.",objectivesText="Kill 8 Tortured Spirits . Progress: I've never met a spirit that made my day better.",rewardGold=257400,rewardXP=4115,starts={{npcID=129453}},ends={{npcID=129453}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48840},questLines={{id=5425,name="Court of Zak'rajan",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49002] = {id=49002,name="Forced Grounding",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48329,49002,49437,49667,49668,49669,50749,50757},description="<This is one of the spears that Faithless trappers use to pull pterrordaxes to the ground. It has a long chain attached to its base. With good aim, you could use it to pull a Faithless pterrordax rider to the ground so you could fight them.>",objectivesText="Use the Faithless Trapper's Spear to pull Fangcaller Hrillik 's pterrordax down from the sky above you, and kill him. Progress: <Rakjan lifts his head proudly.>",rewardGold=514800,rewardXP=5145,rewardItems={137663,154893,161166,161167},rewardChoices={161166,161167},ends={{npcID=129763}},startObjects={{objectID=278447,mapID=864,x=0.471,y=0.388}},coords={mapID=864,source="quest_giver",x=0.472,y=0.392},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50746},questLines={{id=5428,name="Sethrak Fortress",orderIndex=7,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49003] = {id=49003,name="Vengeance From Above",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},series={49141},description="Emperor Korthek hides deep in his stolen temple below ground. We must create such chaos that he has no choice but to emerge to face us. The vulpera riot is a good start, but it will not be enough. Alone, they are no match for the Faithless army. Thankfully, they are not alone. We will ride the mighty Rakjan through the skies. While you throw lightning bombs, I'll use my charged staff to blast the Faithless armies below. Let us hope that is enough to lure out Korthek. I am eager to finish this.",objectivesText="Ride Rakjan the Unbroken and kill Faithless.",rewardGold=514800,rewardXP=5145,starts={{npcID=135110}},ends={{npcID=135111}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={49141,50748},questLines={{id=610,name="Storming the Spire",orderIndex=8,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=55,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49005] = {id=49005,name="Shattered and Broken",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="Something is terribly wrong. Unwanted memories have been released from their magical confines. Akunda's power is supposed to keep dem sealed away... De physical manifestation of our most haunting memories have no place in dis world. Dey must be destroyed.",objectivesText="Kill Fractured and Distorted Memories .",rewardGold=257400,rewardXP=4115,rewardItems={155455,161268,161270,161272,161274},rewardChoices={155455,161268,161270,161272,161274},starts={{npcID=127989}},ends={{npcID=127989}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48987},questLines={{id=607,name="The Warguard's Fate",orderIndex=11,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=29,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49007] = {id=49007,name="Commander on Deck!",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=true,expansion=7,zoneID=8899,mapID=885,storyline={49007},description="Vishax's portal in the Antoran Wastes .> See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(49007)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(49007))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Use Vishax's Portal .",rewardItems={152890,152891,152940,152941,152965},mapCandidates={npc={},zone={8899}},questType="standard",startItems={152965}},
[49013] = {id=49013,name="A Jolt of Power",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={49013},description="I have you to thank for removing that usurper. My strength is returning, unfortunately, the damage to my children has already been done. They are weak and dying. I need you to restore them. My blessing will give you power over the storms. Use it to save my children, as you have saved me.",objectivesText="Use the Blessing of Akunda to revive Stormhide Lizards.",mapCandidates={npc={},zone={8501}},questType="world",db2Objectives={{text="Stormhide Lizards revived",amount=6,type=0,objectID=134743,orderIndex=0},{text="Ranishu killed",amount=8,type=0,objectID=133565,orderIndex=1}},worldTaskTitle="A Jolt of Power",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[49014] = {id=49014,name="The Burning Throne",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8899,storyline={49014},description="The time has come, <name>, to begin our assault upon Antorus. Everything we have fought for, everything our friends and family have sacrificed, has brought us to this moment. We will fire Light's Judgment upon the walls of the accursed citadel and storm their seat of power. We will end the Legion. After all you have done, it is fitting that you have the honor. Speak to Romuul and let us finish our mission.",objectivesText="Speak with Grand Artificer Romuul while above the Antoran Wastes to open the way to Antorus.",rewardGold=202200,rewardXP=6140,rewardItems={152593,152626,152984,246936,249400,254267,254579,264675},starts={{npcID=124312}},ends={{npcID=124312}},mapCandidates={npc={},zone={8899}},questGiverID=124312,questTurnInID=124312,questType="standard",sourceQuests={48559}},
[49015] = {id=49015,name="Antorus, the Burning Throne: The Death of a Titan",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8638,mapID=882,storyline={49015},description="There is no way to express the depth of my sorrow. My rage. What Sargeras has done... Argus, my home world, holds the soul of a titan. It has been twisted and corrupted beyond redemption, its power harnessed to fuel the Legion's infinite army. We must do the impossible... breach the depths of Antorus and sever the Legion's connection to the world soul. Please, <name>. End its pain, its suffering. In striking down the dark heart of Argus, we will defeat the Legion... and redeem the soul of my world.",objectivesText="Strike down the soul of Argus in Antorus, the Burning Throne . Progress: Argus... what could have been...",rewardItems={152593,152626,152984,154172},starts={{npcID=120533}},ends={{npcID=120533}},mapCandidates={npc={882},zone={8574}},questType="raid",sourceQuests={49014}},
[49027] = {id=49027,name="Targets of Opportunity: Terminus",level=45,requiredLevel=45,faction="none",categories={},flags={"weekly","repeatable"},sharable=true,expansion=7,zoneID=8899,mapID=885,storyline={49027},description="Those Legion ships are a problem, . Even now they dock perilously close to the Vindicaar, threatening us with their presence. Sometimes when fighting the Legion it is better to go straight to the top rather than thinning their numbers. Go to the shipyards of Terminus and slay their officers and commanders. That should rattle their forces and put them back on the defensive.",objectivesText="Slay $1oa Rare Elites in Terminus.",rewardGold=238680,rewardXP=6140,rewardItems={152733,152737,152740},rewardChoices={152733,152737,152740},mapCandidates={npc={},zone={8899}},questType="standard"},
[49028] = {id=49028,name="A Sweater for Rupert",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={49028},description="The nights are cold in this area, and I am worried my poor dog will freeze to death. I wish to sew him a sweater, but I have no materials to make one with. I would pay anyone who brings me a pair of porcupine quills and four raccoon tails. - Kolta",objectivesText="Collect Kolta 's materials. Progress: Is there something you need from me?",rewardGold=257400,rewardXP=1415,rewardItems={152800,152986,152988},ends={{npcID=127217}},startObjects={{objectID=277199,mapID=895,x=0.761,y=0.654}},coords={mapID=895,source="quest_giver",x=0.766,y=0.65},mapCandidates={npc={895},zone={8567}},questType="standard"},
[49029] = {id=49029,name="Invasion of Space",level=45,requiredLevel=45,faction="none",categories={},flags={"weekly","repeatable"},sharable=true,expansion=7,zoneID=8899,mapID=885,storyline={49029},description="We are on the Legion home world, but we must not let ourselves get caught unawares. These invasion points can bolster their forces and ruin our plans. By defeating them on their territory we also damage their command and infrastructure. Slay the commanders and stop their invading forces. The fight to push the Legion back begins now!",objectivesText="Defeat any $1oa commanders in Invasion Points.",rewardGold=238680,rewardXP=6140,rewardItems={152733,152737,152740},rewardChoices={152733,152737,152740},mapCandidates={npc={},zone={8899}},questType="standard"},
[49030] = {id=49030,name="Fragments of the Abyss",level=45,requiredLevel=45,faction="none",categories={},flags={"weekly","repeatable"},sharable=true,expansion=7,zoneID=8899,mapID=885,storyline={49030},description="Our scouts have delivered a disturbing report, champion. Some of the more powerful creatures of the Void are carrying powerful crystals that augment their abilities. They now pose a greater threat than before, and we can no longer ignore them. Find these void-tainted monstrosities and take their crystals. We will find a way to dispose of them safely.",objectivesText="Collect $1oa <PH SHADOW CRYSTAL THINGS> from Rare Elites on Argus.",rewardGold=238680,rewardXP=6140,rewardItems={152733,152737,152740},rewardChoices={152733,152737,152740},mapCandidates={npc={},zone={8899}},questType="standard"},
[49031] = {id=49031,name="Out With The Inquisitors",level=45,requiredLevel=45,faction="none",categories={},flags={"weekly","repeatable"},sharable=true,expansion=7,zoneID=8899,mapID=885,storyline={49031},description="Of all of the demons at the Legion's disposal, the inquisitors are some of the most terrible. Even feared by some of the lesser demons, these monsters delight in cruelty and torturing their captives. Inquisitors revel in the terror they cause, but perhaps we can make that work to our advantage. Find the most powerful inquisitors you can and defeat them. Their deaths will not only improve the morale of our troops, but also send a message to their lesser forces.",objectivesText="Slay $1oa Rare Elite inquisitors on Argus.",rewardGold=238680,rewardXP=6140,rewardItems={152733,152737,152740},rewardChoices={152733,152737,152740},mapCandidates={npc={},zone={8899}},questType="standard"},
[49032] = {id=49032,name="Antorus, the Burning Throne: Dark Passage",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8638,storyline={49032},description="Despite the dangerous energies pulsing out from the heart of Argus, the Soulhunter travels unhindered through the Burning Throne. Our scouts report that his vessel harnesses the power of demonic runes to safely reach the Hallowed Felworks. If we obtain those runes, it would allow the Vindicaar to follow the same route. This could save our forces valuable time.",objectivesText="Collect 4 Runes of Passage from Imonar the Soulhunter in Antorus, the Burning Throne on Normal Difficulty. Progress: Without the runes, we must face Sargeras' army head on.",rewardGold=404400,rewardXP=7675,rewardItems={152902},starts={{npcID=125512}},mapCandidates={npc={},zone={8638}},questGiverID=125512,questType="raid"},
[49033] = {id=49033,name="REUSE ME",level=1,requiredLevel=1,faction="both",categories={},flags={},sharable=true,expansion=7,storyline={49033},rewardGold=996000,rewardXP=200,rewardItems={71083,128823,133803,133804,142342,181368,181377,181585,181605,181610,181611,181703,181704,181745,184294,184362,184363,184765,184766,184767,184768,184839,184841,190456,198048,200453,204075,204743,204744,204747,204748,204750,204752,204754,204758,204759,204761,204766,204769,204774,204780,204787,204896,204898},mapCandidates={npc={},zone={}},questType="standard"},
[49036] = {id=49036,name="Best In Show",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={49036},description="Now that the troggs have been taken care of, let's get on with the real show! You've more than proven yourself as a capable rider - ready to get back in the ring and go big? See if you can beat three hundred points!",objectivesText="Mount Cooper to begin your show and score at least 300 points. Progress: Some people say you cannot simply ride the horse - you must BECOME the horse. That's poppycock. Just ride the horse.",rewardGold=257400,rewardXP=1415,rewardItems={158220},rewardChoices={158220},starts={{npcID=124802}},ends={{npcID=124802}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48088,48089}},
[49039] = {id=49039,name="The Start of a Monster Hunt",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48873,48874,48879,48909,49039,49066,49072},description="This is the closest I've been to a dead body, how exciting! What do you think murdered him? Regardless, it is my duty to ensure the safety of individuals under my employ. With a combination of my wit and bravery, and your practical skills, we should be able to track it down. This will be a tale for the ages! Let's start with looking around the camp, see if you can find any clues.",objectivesText="Investigate the camp wreckage. Progress: Did you find anything? I'm still caught up in examining this poor fellow.",rewardGold=124440,rewardXP=1415,rewardItems={153010},starts={{npcID=127481}},ends={{npcID=127481}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49072},questLines={{id=5433,name="A Mountain Retreat",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49040] = {id=49040,name="Fond Farewells",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={49040},description="Dis is where we part ways, <name>. I'm going to take de name Akunda, and start a new life here. When you find Rakera, and I know you will, give her my thanks. She saved my life, and I'm going to make sure to live a life dat was worth saving. If you find yourself back in de city, could you deliver dis note for me? I trust you not to open it, though I doubt you could read my scrawls anyway.",objectivesText="Deliver Jorak 's Note to B'wizati in Zuldazar. Progress: What is dis?",rewardGold=257400,rewardXP=2060,rewardItems={153016},starts={{npcID=127691}},ends={{npcID=127664}},mapCandidates={npc={864,1165},zone={8501}},questType="standard",sourceQuests={48895}},
[49041] = {id=49041,name="Ruinhoof",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={49041},objectivesText="Defeat Ruinhoof",rewardXP=6140,rewardItems={153040},mapCandidates={npc={},zone={8574}},questType="standard",db2Objectives={{text="Defeat Ruinhoof",amount=1,type=12,objectID=2095,orderIndex=0}},worldTaskTitle="Ruinhoof",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[49042] = {id=49042,name="Foulclaw",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8574,mapID=830,storyline={49042},objectivesText="Defeat Foulclaw",rewardXP=6140,rewardItems={153040},mapCandidates={npc={},zone={8574}},questType="standard",db2Objectives={{text="Defeat Foulclaw",amount=1,type=12,objectID=2096,orderIndex=0}},worldTaskTitle="Foulclaw",db2PoiMapID=1669,db2PoiUiMapID=830,db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
