[49059] = {id=49059,name="The Bones of Xibala",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49059},series={49274,49276},description="Our allies in the Explorers' League have alerted us to an exciting find. They have set up camp in the Xibala region of Zuldazar . Make your way to the camp and help them uncover anything that may advance our cause.",objectivesText="Travel to Xibala and meet with Acadia Chistlestone.",rewardGold=25740,rewardXP=175,mapCandidates={npc={},zone={8499}},questType="standard"},
[49060] = {id=49060,name="Xibalan Ecology",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49060},description="I want to take me boys out and really dig our picks in, but every scout I've sent into the ruins just came back half mauled to death. Some didn't come back at all. From what I can tell, the ruins are home to more'n just these spiky grass-eaters. Do you think you could be a peach an' thin their numbers a bit? I'd caution ye against tamperin' with the local ecology an' all, but in the interest of not gettin' eaten I think I'll let ye make the call.",objectivesText="Slay 12 Xibalan predators.",rewardGold=257400,rewardXP=1415,starts={{npcID=131777}},ends={{npcID=131777}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49276}},
[49064] = {id=49064,name="Torga, the Turtle Loa",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Name's Lashk . We're not here to join any cause, we just want to hear Torga's legendary stories. I don't know if he'll help, but you can try persuading Torga, loa of the turtles, and see if he'll help you fight these blood trolls. You can join on our pilgrimage to Torga, just keep quiet. Follow the path and find Kisha , she'll tell you where to go.",rewardGold=25740,rewardXP=345,starts={{npcID=127958},{npcID=127960}},ends={{npcID=127961}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49185},questLines={{id=375,name="Go East, Old Tortollan",orderIndex=1,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=31,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49066] = {id=49066,name="Encase of Emergency",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48873,48874,48879,48909,49039,49066,49072},description="The cliffs here are well known for the crystal clear ice which forms at their base, and even more so for the elementals that are responsible for such. The hunters in my lodge use shards from the primal bodies to keep their stock frozen for transport. More importantly, think of how useful it could be for making and serving drinks! Let's see if we can't find some elementals and gather shards from them.",objectivesText="Collect 20 Pristine Ice Chunks from ice elementals. Progress: I've heard that destroying some of the larger ice structures in the area angers them, so do what you do best and destroy any that you come across!",rewardGold=257400,rewardXP=1415,rewardItems={153020},starts={{npcID=127481}},ends={{npcID=127646}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49039},questLines={{id=5433,name="A Mountain Retreat",orderIndex=6,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49067] = {id=49067,name="Beseeching Bwonsamdi",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="We must talk to Torga's spirit and find out what exactly happened here... and how we can stop it. Hrm, you mentioned dat you are linked to Bwonsamdi now. It is time to test dat link. We need Bwonsamdi to get us Torga's spirit.",rewardGold=25740,rewardXP=345,starts={{npcID=127961}},ends={{npcID=127961}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49064},questLines={{id=375,name="Go East, Old Tortollan",orderIndex=2,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=32,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49068] = {id=49068,name="Quelling the Cove",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,mapCandidates={npc={},zone={8499}},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Dreadpearl Disrupted"},{orderIndex=1,type=0,amount=13,objectID=127833},{orderIndex=2,type=0,amount=20,objectID=127835},{orderIndex=3,type=0,amount=20,objectID=127836},{orderIndex=4,type=0,amount=20,objectID=127839},{orderIndex=5,type=0,amount=100,objectID=129433},{orderIndex=6,type=0,amount=13,objectID=128632},{orderIndex=7,type=0,amount=10,objectID=129707},{orderIndex=8,type=0,amount=13,objectID=128604}},worldTaskTitle="Quelling the Cove",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[49069] = {id=49069,name="WANTED: Ol' Frostclaw",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={49069},description="Old Frostclaw has once again been spotted near the edge of the pass. Hunters in the area are advised to keep caution. This larger than average bear has killed four people to date, I'd hate for you to make it a fifth. Any individual who kills the beast will be rewarded, regardless of their occupation. -Alanna <Below the huntmistress' signature is a child's drawing of a bear with the words \"Ol' Frostclaw\" above it.>",objectivesText="Slay Old Frostclaw . Progress: Is this about the wanted sign? You better hurry, a good number of hunters are after it as well.",rewardGold=772200,rewardXP=2125,rewardItems={158242,158243,158244,158245,158272,158273,158274,158275},rewardChoices={158243,158245,158244,158242,158272,158275,158274,158273},ends={{npcID=127161}},startObjects={{objectID=277199,mapID=895,x=0.761,y=0.654}},coords={mapID=895,source="quest_giver",x=0.758,y=0.658},mapCandidates={npc={895},zone={8567}},questType="group"},
[49070] = {id=49070,name="Souls for the Death Loa",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Dere be blood trolls swarmin' all over dis place. Dey really be pickin' Torga clean, even eatin' his meat. Dat be dark, even for me. Da souls of dese blood trolls be corrupted by eatin' a loa. Somethin' ya should be rememberin' for future reference. Dese souls be worth a lot ta me, more dan just da normal souls of dese blood trolls. Get me da corrupted souls of dese blood trolls and I be callin' da spirit of Torga to ya.",rewardGold=257400,rewardXP=2765,starts={{npcID=128096}},ends={{npcID=128096}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49067},questLines={{id=375,name="Go East, Old Tortollan",orderIndex=3,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=33,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49071] = {id=49071,name="Dreadtick Combustion",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="This whole thing is crazy, you know that? I don't think any story can top this one... Bah! Do you hear that insufferable sound? It's those stupid dreadticks sucking on Torga's meat. Makes my skin crawl! What? You can't hear it? Meh, trust me, they're around, and they need to be taken care of. Here, take this scroll. We've had to deal with these dumb insects in the past. Read it near them and it'll cause them to explode.",rewardGold=257400,rewardXP=2765,starts={{npcID=127960}},ends={{npcID=127960}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49067},questLines={{id=375,name="Go East, Old Tortollan",orderIndex=4,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=34,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49072] = {id=49072,name="Westward Noble",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48873,48874,48879,48909,49039,49066,49072},description="While I am loath to involve you in this further, I don't have the men to afford an escort for Lord Kennings . If he gets hurt, we'll all be out of a job. Can you make sure he at least made it to the west camp?",objectivesText="Find Lord Kennings .",rewardGold=257400,rewardXP=175,starts={{npcID=127161}},ends={{npcID=127481}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48873,48874,48879},questLines={{id=5433,name="A Mountain Retreat",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49073] = {id=49073,name="Ritualistic Denial",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={49073},description="I can't believe we're dealing with a death loa, a DEAD loa, and blood trolls. This isn't what I had planned today! Look, some of the other tortollans have said there are some blood rituals going on. They were spooked and started heading for the coast when they saw it. Take this scroll and read it near any blood rituals . It should cause it to disperse. Be careful with my scroll! It's old and they don't make them like they used to.",objectivesText="Disrupt 3 blood rituals with Kisha's scroll of purging .",rewardGold=202200,rewardXP=2765,rewardItems={153025},mapCandidates={npc={},zone={8500}},questType="standard"},
[49075] = {id=49075,name="Antorus, the Burning Throne: Dark Passage",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8638,storyline={49075},description="Despite the dangerous energies pulsing out from the heart of Argus, the Soulhunter travels unhindered through the Burning Throne. Our scouts report that his vessel harnesses the power of demonic runes to safely reach the Hallowed Felworks. If we obtain those runes, it would allow the Vindicaar to follow the same route. This could save our forces valuable time.",objectivesText="Collect 4 Runes of Passage from Imonar the Soulhunter in Antorus, the Burning Throne on Heroic Difficulty. Progress: Without the runes, we must face Sargeras' army head on.",rewardGold=404400,rewardXP=7675,rewardItems={152906},starts={{npcID=125512}},mapCandidates={npc={},zone={8638}},questGiverID=125512,questType="raid"},
[49076] = {id=49076,name="Antorus, the Burning Throne: Dark Passage",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8638,storyline={49076},description="Despite the dangerous energies pulsing out from the heart of Argus, the Soulhunter travels unhindered through the Burning Throne. Our scouts report that his vessel harnesses the power of demonic runes to safely reach the Hallowed Felworks. If we obtain those runes, it would allow the Vindicaar to follow the same route. This could save our forces valuable time.",objectivesText="Collect 4 Runes of Passage from Imonar the Soulhunter in Antorus, the Burning Throne on Mythic Difficulty. Progress: Without the runes, we must face Sargeras' army head on.",rewardGold=404400,rewardXP=7675,rewardItems={152907},starts={{npcID=125512}},mapCandidates={npc={},zone={8638}},questGiverID=125512,questType="raid"},
[49077] = {id=49077,name="Moments of Reflection",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8638,mapID=920,storyline={49077},description="<The crystal calls to you, resonating with sorcerous magic. As you take hold of it, you hear the echo of a message left behind, a duty Illidan entrusted to you.>",objectivesText="Bring Illidan's crystal to the people and places closest to him.",rewardGold=202200,rewardXP=6140,rewardItems={153555},starts={{npcID=129429}},mapCandidates={npc={},zone={}},questGiverID=129429,questType="standard",questLines={{id=440,name="Moments of Reflection",orderIndex=0,flags=0}},db2PoiMapID=1712,db2PoiUiMapID=920},
[49078] = {id=49078,name="Poisoning the Brood",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Now we have room for our plan to kill Hir'eek. You see, , my specialty is in making potions and poisons. I am working on a poison to use on Hir'eek, when de time comes. I have no idea if it will work or not. I want you to take what I already made and use it on de bats around here. It should kill dem instantly. If it works, den I can make it stronger with my voodoo and give us a chance at killing Hir'eek.",rewardGold=238680,rewardXP=2765,starts={{npcID=127391}},ends={{npcID=127391}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={48801,48890},questLines={{id=374,name="The Loa of Bats",orderIndex=4,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=25,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49079] = {id=49079,name="Hir'eek, the Bat Loa",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={49081,49082},description="Hir'eek knows we are here. If my knowledge of Hir'eek is correct, he will personally kill us after we present ourselves. It is time, den. You and I will walk out dere into a horde of blood trolls who want to watch their loa kill us. Take dis dagger. It is coated with de poison I made. I trust you to survive longer than me to use it. You pretend to cower to Hir'eek , and I will do de talking. On my signal, you jump on Hir'eek and start stabbing! ...And den we hope for de best.",rewardGold=257400,rewardXP=2765,starts={{npcID=129378}},ends={{npcID=128276}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={48800,49078},questLines={{id=374,name="The Loa of Bats",orderIndex=6,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=27,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49080] = {id=49080,name="Cease all Summoning",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="I feel something dark and powerful being summoned in de husk of Torga. You need to stop it! Dere must be a summoner using Torga's blood to finish a ritual. Do what you can to stop dem. I will stay here to keep dese tortollans safe from de blood trolls.",rewardGold=257400,rewardXP=2765,rewardChoices={158974,158979,158980,158981,158982},starts={{npcID=127961}},ends={{npcID=127961}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49067},questLines={{id=375,name="Go East, Old Tortollan",orderIndex=5,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=35,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49081] = {id=49081,name="To Kill a Loa",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={49079,49082},description="I am badly hurt... I don't think I can move. Don't worry, I have some potions dat can heal me... slowly. Hir'eek is just down de cavern dere. De poison injured him, but he is a loa, and it will take more than dat to take him down. I can't believe we... YOU are going kill a loa. It's just not someting we do... but Hir'eek serves G'huun. We have no choice! It's all up to you, now. Kill Hir'eek and end dis madness!",rewardGold=772200,rewardXP=4150,rewardChoices={155312,155313,155314,155323,155324,155325,155326,155510},starts={{npcID=128276}},ends={{npcID=128276}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49079},questLines={{id=374,name="The Loa of Bats",orderIndex=7,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=28,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49082] = {id=49082,name="Upward and Onward",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={49079,49081},description="It is sad dat Hir'eek had to die, but at least de blood trolls are weaker now. My potions are healing me up nicely. I did some looking around and came across dis guy. He's skittish, but not hostile. I think you can use him to get out of here. Hurry up and jump on, before he breaks de rope! I'll find my own way out; you don't have to worry.",rewardGold=25740,rewardXP=345,starts={{npcID=128276}},ends={{npcID=122795}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49081},questLines={{id=374,name="The Loa of Bats",orderIndex=8,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=29,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49091] = {id=49091,name="Invasion Point: Val",level=45,requiredLevel=45,faction="none",categories={"invasion"},flags={},sharable=false,expansion=7,storyline={49091},rewardXP=6140,mapCandidates={npc={},zone={}},questType="standard",worldSystems={invasions={{id=11,name="Invasion Point: Val",scenarioID=1406,areaID=9127},{id=24,name="Invasion Point: Val",scenarioID=1406,areaID=9127}}}},
