[49098] = {id=49098,name="Invasion Point: Cen'gar",level=45,requiredLevel=45,faction="none",categories={"invasion"},flags={},sharable=false,expansion=7,storyline={49098},rewardXP=6140,mapCandidates={npc={},zone={}},questType="standard",worldSystems={invasions={{id=14,name="Invasion Point: Cen'gar",scenarioID=1404,areaID=9126},{id=22,name="Invasion Point: Cen'gar",scenarioID=1404,areaID=9126}}}},
[49099] = {id=49099,name="Invasion Point: Bonich",level=45,requiredLevel=45,faction="none",categories={"invasion"},flags={},sharable=false,expansion=7,storyline={49099},rewardXP=6140,mapCandidates={npc={},zone={}},questType="standard",worldSystems={invasions={{id=15,name="Invasion Point: Bonich",scenarioID=1409,areaID=9180},{id=27,name="Invasion Point: Bonich",scenarioID=1409,areaID=9180}}}},
[49120] = {id=49120,name="Speaking with the Dead",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Ya be livin' up ta ya part of da bargain. I be ready ta show ya what remains of Torga's soul. I gonna need a little part of ya ta act as a conduit ta be summonin' Torga. Don't worry, I be givin' ya all back. Mostly. After we be done, I be headin' out. Ya always welcome ta call on me again... but only if ya got another deal ready.",rewardGold=128700,rewardXP=1385,starts={{npcID=128096}},ends={{npcID=127961}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49070,49071,49080},questLines={{id=375,name="Go East, Old Tortollan",orderIndex=6,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=36,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49122] = {id=49122,name="A Port in Peril",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="A group of mogu have taken hold of Warport Rastari and now threaten to encroach further into my city. It would seem Zul is losing his grip over his pets. Dat port is vital to our military fleet. If de brutes succeed, Zuldazar will fall, and dere won't be a fleet to aid your precious Horde. You wish to prove yourself an ally of de Zandalari? Meet my blade and shield at de port and clean up dis mess.",rewardGold=25740,rewardXP=175,starts={{npcID=120740}},ends={{npcID=127815}},mapCandidates={npc={862,1165},zone={8499}},questType="standard",sourceQuests={47432,48897,49663,50881},questLines={{id=373,name="Warport Rastari",orderIndex=0,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=37,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[49123] = {id=49123,name="Killer Crawgs",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={49123},description="You heard Torga. We need to be taking de fight to de blood trolls if we want to stop dis herald of G'huun. De blood trolls have monstrous crawgs in a camp nearby. We destroy dem, we weaken de blood trolls! De rest of us will move ahead to find out what else de blood trolls have planned around dis place.",objectivesText="Kill 12 Blood Crawgs or their riders.",rewardGold=257400,rewardXP=2765,mapCandidates={npc={},zone={8500}},questType="standard"},
[49124] = {id=49124,name="Tortollan Rescue",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={49124},description="If Torga wants us to help you kill the herald of G'huun, then I guess we'll help. First, we need to rescue our people. I found out that the blood trolls are draining the blood of our friends nearby and then feeding them to crawgs! This is no way for a tortollan to die, not after hundred of years gathering stories on Azeroth. Take this scroll. It'll purge whatever blood magic the blood trolls using on my friends. Be careful with my scroll! I want it back in one piece.",objectivesText="Rescue 6 Tortollan Captives from the blood trolls using Lashk's Scroll of Purging .",rewardGold=202200,rewardXP=2765,rewardItems={153049},mapCandidates={npc={},zone={8500}},questType="standard"},
[49125] = {id=49125,name="Negative Blood",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Okay, you want to kill the herald of a blood god? We can figure something out. There's corrupted blood nearby that's feeding this monster's power. Lucky for you, I've heard stories of this sort of thing before. Take this scroll, but be careful with it! It'll destroy the corrupted blood that's feeding Jungo. Oh, and I need you to find a scroll Holbruk was carrying, called the Scroll of Fate's Hand. It's REALLY powerful. We'll need it.",rewardGold=257400,rewardXP=2765,starts={{npcID=127958}},ends={{npcID=127958}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49120},questLines={{id=375,name="Go East, Old Tortollan",orderIndex=7,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=37,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49126] = {id=49126,name="Forcing Fate's Hand",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="I got some good news and bad news for you about this whole quest to destroy the herald of G'huun. Bad news first. There's an entire army of skeletons between us and the next area. I'm guessing they used Torga's blood to animate them. Good news is that scroll you recovered from Holbruk can summon the powerful Hand of Fate . ...and the bad news is that the scroll got damaged when Holbruk died and is only good for one more use. Meh. Take this scroll and destroy that skeleton army!",rewardGold=257400,rewardXP=2765,rewardChoices={158973},starts={{npcID=127958}},ends={{npcID=127958}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49125},questLines={{id=375,name="Go East, Old Tortollan",orderIndex=8,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=38,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49130] = {id=49130,name="Loa-Free Diet",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Princess Talanji thinks we're almost ready to kill this herald of G'huun. Maybe she's right, maybe we're all dead, who knows? What I do know is the blood trolls here are... are carving and carrying away parts of Torga . Ugh! From what I can tell, they're using poor Torga's meat to power their blood rituals. This has to stop! Go out there and steal those pieces of meat from the blood trolls. I'll figure out a way to dispose of it.",rewardGold=257400,rewardXP=2765,starts={{npcID=127958}},ends={{npcID=127958}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49126},questLines={{id=375,name="Go East, Old Tortollan",orderIndex=9,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=39,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49131] = {id=49131,name="Sanctifying Ground",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="We are so close to weakening dis herald, . Dis is our final push. De nearby area is brimming with blood magic. While you were fighting, I was working on creating totems dat can cleanse de area of blood magic. Take dese totems and place dem nearby. Dey should drain some of de blood magic out of de area. De herald should be weak enough for us to actually kill after all dis.",rewardGold=257400,rewardXP=2765,starts={{npcID=127961}},ends={{npcID=127961}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49126},questLines={{id=375,name="Go East, Old Tortollan",orderIndex=10,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=40,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49132] = {id=49132,name="Crushing the Skullcrushers",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Look, , I'll be happy once we've killed this herald and we can have things go back to normal. Until then, you need to deal with these monstrous blood trolls called \"skullcrushers\". Lovely, right? As far as I can tell, these things have some sort of connection to this herald, might be why they're so huge. You kill these skullcrushers and maybe we weaken this herald a bit more. Or maybe it gets even angrier and kills us all. We'll have to see.",rewardGold=257400,rewardXP=2765,starts={{npcID=127960}},ends={{npcID=127960}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49126},questLines={{id=375,name="Go East, Old Tortollan",orderIndex=11,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=41,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49133] = {id=49133,name="Antorus, the Burning Throne: The Heart of Argus",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8638,storyline={49133},description="Hatuun tells me that after Argus fell, Sargeras ordered a temple of darkness to be built deep within the planet's core. Little is known of it, for only the titan's most devoted acolytes are given sigils that permit entrance. If we lay claim to these sigils, they could be infused into the Vindicaar. This would allow our forces to stage a direct assault upon the fetid heart of Argus.",objectivesText="Collect 4 Sigils of the Dark Titan from Aggramar in Antorus, the Burning Throne on Normal Difficulty. Progress: Have you located the sigils?",rewardGold=404400,rewardXP=7675,rewardItems={152908},starts={{npcID=125682}},mapCandidates={npc={},zone={8638}},questGiverID=125682,questType="raid",sourceQuests={49032}},
[49134] = {id=49134,name="Antorus, the Burning Throne: The Heart of Argus",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8638,storyline={49134},description="Hatuun tells me that after Argus fell, Sargeras ordered a temple of darkness to be built deep within the planet's core. Little is known of it, for only the titan's most devoted acolytes are given sigils that permit entrance. If we lay claim to these sigils, they could be infused into the Vindicaar. This would allow our forces to stage a direct assault upon the fetid heart of Argus.",objectivesText="Collect 4 Sigils of the Dark Titan from Aggramar in Antorus, the Burning Throne on Heroic Difficulty. Progress: Have you located the sigils?",rewardGold=404400,rewardXP=7675,rewardItems={152909},starts={{npcID=125682}},mapCandidates={npc={},zone={8638}},questGiverID=125682,questType="raid",sourceQuests={49075}},
[49135] = {id=49135,name="Antorus, the Burning Throne: The Heart of Argus",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8638,storyline={49135},description="Hatuun tells me that after Argus fell, Sargeras ordered a temple of darkness to be built deep within the planet's core. Little is known of it, for only the titan's most devoted acolytes are given sigils that permit entrance. If we lay claim to these sigils, they could be infused into the Vindicaar. This would allow our forces to stage a direct assault upon the fetid heart of Argus.",objectivesText="Collect 4 Sigils of the Dark Titan from Aggramar in Antorus, the Burning Throne on Mythic Difficulty. Progress: Have you located the sigils?",rewardGold=404400,rewardXP=7675,rewardItems={152910},starts={{npcID=125682}},mapCandidates={npc={},zone={8638}},questGiverID=125682,questType="raid",sourceQuests={49076}},
[49136] = {id=49136,name="Jungo, Herald of G'huun",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Dis is it, . De blood magic is weakened enough dat we can actually hurt de herald of G'huun. It is going to take all of us fighting dis thing to stop it. We will meet you inside of Torga. We cannot lose here. If de blood trolls control Torga's blood, den dere will be no way for us to stop dem.",rewardGold=772200,rewardXP=4150,rewardCurrencies={{id=1553,amount=100}},starts={{npcID=127961}},ends={{npcID=127961}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49130,49131,49132},questLines={{id=375,name="Go East, Old Tortollan",orderIndex=12,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=42,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49138] = {id=49138,name="Captain Gulnaku's Treasure",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,storyline={49138},description="<This map is poorly drawn and covered in stains, but appears to identify three possible locations where a pirate captain may have buried treasure around the Port of Zem'lan. The treasure could be at any of the three locations. At the bottom of the map, someone scrawled an order: Set traps!>",objectivesText="Search for Captain Gulnaku's treasure chest. Progress: <It's firmly locked. You'll need the captain's key to open this.>",rewardGold=514800,rewardXP=5145,rewardItems={153419,163633},startObjects={{objectID=289728,mapID=864,x=0.35,y=0.804}},endObjects={{objectID=289728,mapID=864,x=0.35,y=0.804}},coords={mapID=864,x=0.35,y=0.804},mapCandidates={npc={},zone={8501}},questType="standard",sourceQuests={51055,51056},startItems={153359}},
[49139] = {id=49139,name="An Army's Arsenal",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48330,48331,48332,48334,48335,49001,49139},series={48330,48332},description="It's my job to scout out the ruins to identify threats and figure out the best way in. Two storehouses contain the majority of the valuable weaponry in the ruins. Unfortunately, they're guarded by specters, powerful Zandalari spirits bound to this place. I... we need those weapons. Take out the specters so I... we can get to them.",objectivesText="Kill the specters of Mugabu and Jam'jen, so Omi can ransack the storehouses.",rewardGold=514800,rewardXP=4115,starts={{npcID=129451}},ends={{npcID=129451}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48332,48334,49001},questLines={{id=5425,name="Court of Zak'rajan",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49141] = {id=49141,name="Diplomacy and Dominance",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},series={49003},description="May I entrust you with my staff, $p? I do not offer this lightly, so do not accept it lightly either. We will need every advantage when we face Emperor Korthek, and I've identified an opportunity to increase the power at our disposal. The Faithless maintain a series of suppression spires on the ridge above us to subjugate the pterrordax. My staff can drain power from the spires to bolster its own potency. Meanwhile, I will recruit a much-needed ally for the next stage of our mission.",objectivesText="Use Vorrik's Staff to drain power from 6 Faithless Suppression Spires.",rewardGold=257400,rewardXP=4115,rewardItems={160510},starts={{npcID=135172}},ends={{npcID=135110}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50746},questLines={{id=610,name="Storming the Spire",orderIndex=6,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=53,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864,startItems={154895}},
[49143] = {id=49143,name="Essence of the Light Mother",level=45,requiredLevel=45,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8574,mapID=831,storyline={40238,46213,47431,47508,47526,47541,47652,47653,47743,47754,47771,48559,49143},description="This is a crucial moment, <name>. Our campaign must not lose momentum. Though she has fallen, I still sense Xe'ra's presence all around us. The Light that shone within her heart can yet be a source of strength for our cause. No doubt the loss of Xe'ra has deeply wounded Turalyon. I will do what I can to ease his troubled spirit while you gather the vestiges of the naaru that remain.",objectivesText="Collect 3 Vestiges of Light . Progress: Though Xe'ra is gone, her essence can still aid us in our struggle.",rewardGold=50550,rewardXP=770,rewardItems={153125},starts={{npcID=126307}},ends={{npcID=126307}},mapCandidates={npc={},zone={8574}},questGiverID=126307,questTurnInID=126307,questType="standard",sourceQuests={47743},questLines={{id=348,name="The Light Mother",orderIndex=11,flags=0}},campaigns={{id=291,title="Shadows of Argus",questLineID=348,questLineOrder=2,stallText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign."}},campaignLockText="Continue the Legionfall Campaign to unlock the Shadows of Argus campaign.",db2PoiMapID=1669,db2PoiUiMapID=831},
[49144] = {id=49144,name="Wrath of the Zandalari",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="Dere is no reasoning with de mogu. Dey only value one thing: strength. Dat is something de Zandalari have like no other, but our forces are spread thin. We are simply not prepared to fight dem. You have proven yourself a capable warrior, for |5 . Would you be our \"ambassador\" to dese brutes? Show dem dat de Zandalari do not stand alone!",rewardGold=257400,rewardXP=1415,starts={{npcID=127815}},ends={{npcID=127815}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49122},questLines={{id=373,name="Warport Rastari",orderIndex=1,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=38,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[49145] = {id=49145,name="No Troll Left Behind",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="Dis is de primary port for de Zandalari fleet. Thankfully most of our ships were out when de mogu came, but Rastari is still an active fortification for de city. De mogu did not land on abandoned shores, . Dere are all manner of brave warriors stationed here, fighting for their lives. Take dis whistle and rally all you can. Our warriors will hear its scream and know dat dey are not alone.",rewardGold=257400,rewardXP=1415,starts={{npcID=127814}},ends={{npcID=127814}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49122},questLines={{id=373,name="Warport Rastari",orderIndex=2,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=39,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[49146] = {id=49146,name="Spirits' Belongings",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="You are no Zandalari, but your spirit burns with a passion I have not seen in many years. I am de wavebinder. It is through me dat de loa bless our ships. I will not see my home tainted by dese talking rocks. Gather my bijous, my grimoire, and some of our fallen I set aside for just such an occasion. De brutes think dey have won. Dey will answer to Bwonsamdi soon enough.",rewardGold=257400,rewardXP=1415,starts={{npcID=127837}},ends={{npcID=127837}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49122},questLines={{id=373,name="Warport Rastari",orderIndex=3,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=40,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[49147] = {id=49147,name="Show of Strength",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="Their leader's time is coming soon now, but we need to dispose of his lieutenants first. Our momentum will be lost if dey reform ranks. Jao-Ti is de first. Legend has it Lei Shen himself said he showed a great connection to de storms. He is leading de mogu's stormbinders. De other is Subjugator Zheng , a slaver dat would make de Kul Tirans blush. You have never seen depravity like his. Kill dem both, and make dem suffer. De mogu are no strangers to war, but neither are we.",rewardGold=514800,rewardXP=1770,rewardChoices={155304,158412,158413,158414,158415},starts={{npcID=127814},{npcID=129087},{npcID=129088}},ends={{npcID=127837}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49144,49145,49146},questLines={{id=373,name="Warport Rastari",orderIndex=4,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=41,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[49148] = {id=49148,name="Crumbling Apart",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="De mogu army grows with each passing moment thanks to their animated stone warriors. It is only a matter of time before their forces are back at full strength. A thousand curses upon Zul. He was forbidden from bringing his pets here--and from resurrecting de Thunder King in Pandaria. We are de only thing standing between dem and de city. We've got to stop dis while we still can!",rewardGold=257400,rewardXP=1415,starts={{npcID=127815}},ends={{npcID=127837}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49144,49145,49146},questLines={{id=373,name="Warport Rastari",orderIndex=5,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=42,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[49149] = {id=49149,name="Embrace the Voodoo",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="Dese heathens think we are weak. Dey think we are broken. But Zandalari never truly die. I've blessed dat skull Habutu gave you with a bit of voodoo dat will let it break through to de Other Side. You will need to use my spirit obelisks to channel its power. Dey will take it from dere.",rewardGold=257400,rewardXP=1415,starts={{npcID=127837}},ends={{npcID=127837}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49144,49145,49146},questLines={{id=373,name="Warport Rastari",orderIndex=6,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=43,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[49160] = {id=49160,name="Torga's Eternal Return",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Well, we did it. Doesn't make the plan we had any less crazy. But there's still one more thing left to do. I've been visiting Torga for years. He told me stories of powerful scrolls, one in particular that he said was meant to be used to put a loa's spirit to rest. I think you should be the one to read it. I mean, if you're SMART enough to read it. Bah! Just take the scroll and read it before I have second thoughts.",rewardGold=28300,rewardXP=345,starts={{npcID=127960}},ends={{npcID=127958}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49136},questLines={{id=375,name="Go East, Old Tortollan",orderIndex=13,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=43,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49178] = {id=49178,name="My Favorite Things",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48421,49178,49218,49226,49230},description="It's tough out here. Pirates. Deadly monsters. Hungry Sam 's seemingly endless battle with indigestion. Nothing sets the nerves at ease like an old keepsake. Somethin' to remind you of home. Somethin' to keep you going. Ask around the camp. Find out what folks might have lost out there in the tideways. If you can bring any of it back, it'd be a mighty kind gesture. Me? Oh... I had a locket... Never mind, it's too small, you'd never find it. It's nothing. Don't worry about it.",objectivesText="Ask Friendly Pete , Hungry Sam and Handy Bill about their missing keepsakes, then collect those items from the Wailing Tideway. Progress: We've all lost something in the tides. Some more than others.",rewardGold=53500,rewardXP=1415,rewardItems={152514,153185,153186,153187,153348},starts={{npcID=128229}},ends={{npcID=128229}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49218},questLines={{id=586,name="Castaways and Cutouts",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49181] = {id=49181,name="Glimmering Locket",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={49181},description="<A glint of metal catches your eye among the gently bobbing flotsam. Digging into the tangled seaweed, you discover a locket of simple, yet sturdy design. Opening the locket reveals a hand-drawn picture of a woman with fiery red bangs. Her arm is around a woman with short-cropped auburn hair, and the two are proudly displaying warm smiles for the artist.>",objectivesText="Return the Glimmering Locket to Stabby Jane . Progress: Hm? What's that you've got there?",rewardGold=27750,rewardXP=1415,rewardItems={153184},ends={{npcID=128229}},startObjects={{objectID=277373,mapID=895,x=0.88,y=0.749}},coords={mapID=895,source="quest_giver",x=0.854,y=0.808},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49178}},
[49185] = {id=49185,name="Catching Up",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Good to see you in one piece, . Nazmir is a place of nightmares, but you seem to be surviving. Rokhan and I convinced your Horde dat we need more support. He is getting ready to meet with reinforcements. We still need to get de loa's aid. What happened with Bwonsamdi and Hir'eek?",rewardGold=25740,rewardXP=345,starts={{npcID=127961}},ends={{npcID=127961}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47250,49082},questLines={{id=375,name="Go East, Old Tortollan",orderIndex=0,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=30,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49189] = {id=49189,name="Intact Demon Eyes",level=1,requiredLevel=1,faction="both",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={49189},objectivesText="Progress: What's this? An offering?",rewardGold=19400,rewardItems={153021,153069,153071,153219,153226},starts={{npcID=128134}},ends={{npcID=128134}},mapCandidates={npc={885},zone={8899}},questType="standard"},
