[49199] = {id=49199,name="Greater Invasion Point: Matron Folnuna",level=45,requiredLevel=45,faction="none",categories={"invasion"},flags={},sharable=false,expansion=7,zoneID=9295,storyline={49199},rewardXP=6140,rewardItems={151568,153278},mapCandidates={npc={},zone={9295}},questType="standard",worldSystems={invasions={{id=16,name="Greater Invasion Point: Matron Folnuna",scenarioID=1412,areaID=9295}}}},
[49200] = {id=49200,name="Yet More Intact Demon Eyes",level=1,requiredLevel=1,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8899,mapID=885,storyline={49200},rewardGold=19400,rewardItems={153021,153226},starts={{npcID=128134}},ends={{npcID=128134}},mapCandidates={npc={885},zone={8899}},questType="standard"},
[49218] = {id=49218,name="The Castaways",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={48421,49178,49218,49226,49230},description="I see the sirens have made another catch. You're lucky they haven't stripped your bones yet. If you need to trade supplies or just warm yourself by the fire, there's a camp up the hill behind me. Everyone there washed up in the tides, just like you. Figure we've got folks from at least four or five shipwrecks now. All banded together, just tryin' to survive. Talk to Stabby Jane . Don't worry about her nickname, she's actually real nice.",objectivesText="Speak with Stabby Jane at Castaway Point.",rewardGold=25740,rewardXP=175,rewardItems={152514,153185,153186,153187,153348},starts={{npcID=128377}},ends={{npcID=128229}},mapCandidates={npc={895},zone={8567}},questType="standard",nextQuests={49178,49226,49230},questLines={{id=586,name="Castaways and Cutouts",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49223] = {id=49223,name="The Long Con",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=1161,storyline={49223},description="Hello again my young friend! I have good news. Our mutual acquaintance Carentan -- the man who scammed us in Freehold -- has finally come out of hiding. I have been communicating with him in letters delivered by various middlemen and even completed a few proxy trades to earn his trust. In our last correspondence, he agreed to meet for an in-person trade. He thinks he is meeting with a Ms. Pixy Spindlespark, gnomish hairdresser with a weakness for poached furs. But he'll be meeting you instead.",objectivesText="Slay Carentan . Progress: Don't let him get away this time!",rewardGold=702000,rewardXP=10225,starts={{npcID=129940}},ends={{npcID=129940}},mapCandidates={npc={1161},zone={8568}},questType="group",sourceQuests={49523}},
[49224] = {id=49224,name="The Netherlight Crucible",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=9359,storyline={49224},description="The crucible thrums with power. Soon our weapons will shine like the stars themselves! We will need that strength if we are to have any hope of defeating the Legion here. <name>, you have endured great hardship to bring us to this moment. The honor of first tapping the crucible's power must be yours.",objectivesText="Imbue a relic with Netherlight Fortification using the Netherlight Crucible. Progress: We need every advantage we can muster if we are to see the Legion's end.",rewardGold=20220,rewardXP=770,starts={{npcID=126389}},ends={{npcID=126389}},mapCandidates={npc={},zone={9359}},questGiverID=126389,questTurnInID=126389,questType="standard",sourceQuests={48560}},
[49225] = {id=49225,name="Chasing the Leader",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={49225,49229,49232,49233,49234,49260},series={50700,51151},description="The locals and the league have been working together tae reclaim relics in this here cave up the hill. But it seems that we've angered the previous residents. I think the marines can keep the expedition safe fer now, but I dinna how long they can keep it up. We need yer help before things go south! Find Hilde Firebreaker , the leader of our expedition. She ran back into the cave fer somethin' or another.",objectivesText="Find Hilde Firebreaker .",rewardGold=25740,rewardXP=175,starts={{npcID=128381}},ends={{npcID=128381}},mapCandidates={npc={895},zone={8567}},questTurnInID=128381,questType="standard",sourceQuests={50700,51151},questLines={{id=5432,name="Cave Diving",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49226] = {id=49226,name="Silencing the Sisters",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48421,49178,49218,49226,49230},description="The sirens in this tideway have drawn countless ships to their doom. Wiping them out would be a boon to all seafaring folk. But you can't very well kill all of them. Only a fool would try that. The real dangerous ones are the elders. The \"sisters\" as they're known. Bigger, smarter, and stronger than the younger ones. Their voices carry far out to sea and bring in all the big \"catches.\" I managed to track two of them to a den at the northern end of the tideway, but I can't take them alone.",objectivesText="Slay Patheope and Nolpe . Progress: Sirens can be handled with relative ease. The older ones take a bit more work.",rewardGold=257400,rewardXP=1415,rewardItems={152514,153185,153186,153187,153348},rewardCurrencies={{id=1553,amount=100}},starts={{npcID=128229}},ends={{npcID=128229}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49218},questLines={{id=586,name="Castaways and Cutouts",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49227] = {id=49227,name="The Master Key",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={49227},description="None of the keys you found were the right fit! We're going to need another plan... I've heard that Overseer Morrison has a master key that can open any lock in the compound. It's dangerous, but I need you to get that key for me! You'll find her running the mining operation inside the cave. Once you get the key, make sure you rescue any vulpera captives that you find. Once you've rescued my friends, meet me back here and release me. Good luck!",objectivesText="Obtain Morrison's Master Key and use it to free 8 Vulpera Captives. Progress: You keep your end of the bargain, and I'll keep mine.",rewardGold=514800,rewardXP=5145,rewardItems={153420,160735},starts={{npcID=128422}},ends={{npcID=128422}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47939}},
[49229] = {id=49229,name="The Ruins Fought Back",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={49225,49229,49232,49233,49234,49260},description="Something set off a trap in the cave, and then the ruins themselves came tae life. I expect that most of our lads still in that cave aren't in fightin' form. Could ye clear out some of the livin' ruins tae help them escape?",objectivesText="Kill 6 Ancient Protectors .",rewardGold=257400,rewardXP=1415,starts={{npcID=128381}},ends={{npcID=128381}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={50700},questLines={{id=5432,name="Cave Diving",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49230] = {id=49230,name="Local Flavor",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48421,49178,49218,49226,49230},description="I'm STARVING. Not actually starving, like when I first got here, but you know... Emotionally starving. Haven't had any luck with the oysters lately, and seaweed soup really upsets my guts. If I eat any more of that stuff, I think the other castaways might actually feed me to the sharks. How about them tidelurkers? They look pretty juicy. Bet you could steam those up real nice. Can you get me some? I'm not much of a hunter. But I'll share it with you!",objectivesText="Gather 5 Juicy Lurker Tails . Progress: <Sam's stomach growls audibly.>",rewardGold=257400,rewardXP=1415,rewardItems={152514,153185,153186,153187,153348,154888,202268},starts={{npcID=128228}},ends={{npcID=128228}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49218},questLines={{id=586,name="Castaways and Cutouts",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49232] = {id=49232,name="Salvaging a Disaster",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={49225,49229,49232,49233,49234,49260},description="Birch and I are helping out the expedition with field studies. I'm not much of a fighter, but I can't make another mistake, they might demote me! Could you recover some of the relics we packed up in boxes around the cave?",objectivesText="Gather 6 Drust Relics . Progress: Did you find enough relics?",rewardGold=257400,rewardXP=1415,rewardItems={153349},starts={{npcID=128353}},ends={{npcID=128353}},mapCandidates={npc={},zone={8956}},questGiverID=128353,questTurnInID=128353,questType="standard",questLines={{id=5432,name="Cave Diving",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49233] = {id=49233,name="I'm a Druid, Not a Priest",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={49225,49229,49232,49233,49234,49260},description="The remains of previous trespassers also arose when we set off the main trap. Cranklefuse here has been demanding that I help them, and while I can't say I'm too familiar with turning the undead, I believe I have found a solution. I've modified my staff to remove their curse. Take it and see if you can't help them.",objectivesText="Free 5 cursed raiders. Progress: Have you tried out that staff yet?",rewardGold=257400,rewardXP=1415,rewardItems={153350},starts={{npcID=128354}},ends={{npcID=128354}},mapCandidates={npc={},zone={8956}},questGiverID=128354,questTurnInID=128354,questType="standard",questLines={{id=5432,name="Cave Diving",orderIndex=6,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49234] = {id=49234,name="A Marine Out of Water",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={49225,49229,49232,49233,49234,49260},description="A giant one of those stone creatures killed quite a few marines while we were trying to evacuate the cave. It didn't chase us too far, but ignoring it outright is too big of a risk. It needs to fall!",objectivesText="Kill the Awakened Guardian .",rewardGold=514800,rewardXP=1770,rewardItems={158250,158251,158252,158253,158254,158255,158256,158257},rewardChoices={158255,158256,158257,158254,158251,158253,158252,158250},starts={{npcID=130101}},ends={{npcID=130101}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={50700},questLines={{id=5432,name="Cave Diving",orderIndex=7,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49239] = {id=49239,name="Dress to Impress",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={47489,48419,48505,48539,48558,48773,49239,49398,49399,49400,49401,49404},description="Freehold used to be open to anyone, but now it seems the Irontide Raiders have declared themselves the owners. They're locking the place down and turning away anyone who isn't part of the crew. Fortunately, they're also hiring. Put this on. Don't think about where it came from. We'll pose as new recruits, get in, gather some information, and be back in Boralus in time for supper! Cyrus may be salty, but he's a decent cook.",objectivesText="Put on the Irontide Hat and enter Freehold with Flynn.",rewardGold=257400,rewardXP=1415,rewardItems={152719,152720,152721,152722,153355,153509,153680,153681,153682},starts={{npcID=126620}},ends={{npcID=126620}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48558,48773},questLines={{id=587,name="Freehold",orderIndex=6,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=24,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49242] = {id=49242,name="Quill or Be Quilled",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48108,48109,48110,48111,48113,48165,48170,48198,48283,49242},description="Oh, hello there. Sorry, we don't get many mainlanders in these parts. This plot was my husband Sam's farm. He used to tend to the onion fields every day before the curse befell Glenbrook and took him with it. With my husband gone, this farm is all I have left, and these quillrats are making sure I don't get even that. I'd hate to bother a perfect stranger, but could you help quell this infestation?",objectivesText="Kill 6 Territorial Quillrats in Hawthorne's Plot. Progress: These quillrats are truly a menace!",rewardGold=257400,rewardXP=2765,starts={{npcID=128494}},ends={{npcID=128494}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48111},questLines={{id=382,name="Hangman's Point",orderIndex=8,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[49259] = {id=49259,name="And Justice For All",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48941,48942,48943,48944,48945,48946,48963,49259},description="Thank you for helping to redeem me in the eyes of my people, <class>. I am in your debt, and I will be sure to let my father know. In the mean time, I think we should find out what this Heartsbane Coven is, and what they are doing in our lands. I hope the marshal will be able to enlighten us. First thing's first, though. Care to undo these ropes? They're starting to chafe.",objectivesText="Leave Hangman's Point with Lucille Waycrest . Progress: Shall we?",rewardGold=283700,rewardXP=2765,rewardItems={21395,21396,21397,33271,39770,39776,39778,39818,39833,57829,118154,118155,118156,118157,153053,155126,155130,155143,155148,155152,155583,155584,156976,158646,158647,159536,174294,177055,178158,179945,191604,197661,197662,197663,197664,225946},rewardChoices={155126,155152,155148,155583,158647,155130,155584,158646,155143,159536},starts={{npcID=125380}},ends={{npcID=125380}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48538},questLines={{id=384,name="Alpine Rise",orderIndex=0,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=16,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[49260] = {id=49260,name="Backup While I Pack Up",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={49225,49229,49232,49233,49234,49260},description="I came in here tae try an' reclaim as many relics as possible. Sneakin' in was easy, but I'm worried about things noticin' me while I pack up. Mind watching me back while I get the relics stored in a safe place in my bag?",objectivesText="Protect Archaeologist Firebreaker.",rewardGold=257400,rewardXP=1415,rewardCurrencies={{id=1553,amount=50}},starts={{npcID=128349}},ends={{npcID=128349}},mapCandidates={npc={},zone={8956}},questGiverID=128349,questTurnInID=128349,questType="standard",sourceQuests={49225},questLines={{id=5432,name="Cave Diving",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49261] = {id=49261,name="Crabby Crew Stew",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={49261},description="Shouldn't you be in the mines? Look, I won't tell Morrison if you won't. I wouldn't want to be stuck in those mines, either. We could use a hand out here, though. The crew is getting crabby. We've been eating nothing but slop and the occasional rat for weeks. I hear one of the deckhands makes a marvelous crab stew. Can I count on you to secure the meat?",objectivesText="Collect Lumpy Crab Meat from Sand Scuttlers. Progress: It'll be nice to eat something other than rat for a change.",rewardGold=257400,rewardXP=4115,rewardItems={151627,160735},starts={{npcID=128618}},ends={{npcID=128618}},mapCandidates={npc={864},zone={8501}},questType="standard"},
[49262] = {id=49262,name="Gang Bustin'",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={49262},description="It's difficult to run a tight ship when you're so far from home. The crew has a tendency to get restless when they've been landlocked for too long. I've heard reports of deckhands sneakin' around and stealin' supplies. If the crew thinks they can steal from our employer on my watch, they've got another thing comin'! I need someone to crack down on these shady deals and send a message to the crew. Thievin' won't be tolerated!",objectivesText="Confront 8 Shady Deckhands. Progress: We murder mutineers 'round here.",rewardGold=257400,rewardXP=4115,rewardItems={160735},starts={{npcID=128618}},ends={{npcID=128618}},mapCandidates={npc={864},zone={8501}},questType="standard"},
[49266] = {id=49266,name="Forge of Aeons",level=40,requiredLevel=40,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=9359,mapID=940,storyline={49266,49698,50071},series={49698},description="The Lightforged have long stood as a beacon of hope against the Legion. But few truly know what it takes to become the embodiment of Light's wrath. These few champions among the Army of the Light are ready to undergo their final trial. Will you do us the honor of bearing witness?",objectivesText="Bear witness to the ritual of the Lightforged. Progress: It fills me with hope that we have found allies such as you.",rewardGold=312800,rewardXP=5465,rewardItems={155656,156486},starts={{npcID=130549}},ends={{npcID=130549}},mapCandidates={npc={},zone={9359}},questGiverID=130549,questTurnInID=130549,questType="standard",sourceQuests={49698},questLines={{id=533,name="Allies of the Alliance: Lightforged Draenei",orderIndex=1,flags=0}},db2PoiMapID=1860,db2PoiUiMapID=940},
[49268] = {id=49268,name="Sharks in the Water",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48008,48009,48347,48348,48352,48353,48354,48355,48356,48365,48366,48367,48368,48370,48372,48540,49268,49292,49299,49302},description="Recently a large gam of sharks has moved into the shallower water in the harbor. I have dealt with minor illnesses before that were caused by creatures carrying foreign contaminants to shore. Perhaps the sharks have brought something in from the deeper waters? Cull some of the sharks that have wandered too close to the pier. I shall read the tides for any changes.",objectivesText="Kill 6 Invading Dreadmaws .",rewardGold=257400,rewardXP=1415,rewardItems={152401,152585,152586,153486,153513},starts={{npcID=125922}},ends={{npcID=125922}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48540},questLines={{id=592,name="The Shadow Over Anglepoint",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49274] = {id=49274,name="Morgrum's Survey",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49274},series={49059,49276},description="Oi. Since yer hands are already dirty, what do ye say we make a deal? To give it to ye straight, there's a relic here called the Breath of Xibala. I don't know who Xibala is or why the Alliance wants its breath, but there's a hefty sum of gold in it fer me if we deliver. That means there's somethin' in it for you, too, if ye get my meanin'. I started a survey with me equipment but haven't got me results yet. Go on out into the ruins an' give the boxes you see a little kick to hurry things along.",objectivesText="Check on Excavator Morgrum Emberflint 's survey equipment in the Ruins of Xibala. Progress: I'll be countin' me own gold if ye don't want to lend a hand.",rewardGold=257400,rewardXP=1415,starts={{npcID=131763}},ends={{npcID=131763}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49276}},
[49276] = {id=49276,name="The Thrill of Exploration",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={49276},series={49059,49274},description="Name's Acadia, Acadia Chistlestone ! I represent the interests of the Explorers' League at this site. Where there's dirt to be turned, we're happy to do the digging! <Acadia's smile falters.> These Dark Iron, though, they're keen on delving deeper and faster than I'm comfortable with. Since you're a strong, capable member of the Alliance, do you think you could ah... lead by example? Go on, there's a fresh fossil here that could use some attention.",objectivesText="Help Acadia Chistlestone recover a Xibalan fossil. Progress: Acadia tells me you're in charge, now. We'll see about that.",rewardGold=128700,rewardXP=710,starts={{npcID=131777}},ends={{npcID=131763}},mapCandidates={npc={862},zone={8499}},questType="standard"},
[49278] = {id=49278,name="Spiritual Restoration",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Dis is a sacred place to Bwonsamdi, but now it is little more than a ruin. Even de spirits are unable to escape de passage of time and have faded away, leaving only their drained husks behind. We will return dem to life. Here, I have been collecting de souls from my hunt into dis charm. Use it on de drained spirits , and we will bring dis place back to what it once was.",rewardGold=119340,rewardXP=1385,rewardCurrencies={{id=1560,amount=50}},starts={{npcID=124428}},ends={{npcID=124428}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47244},questLines={{id=596,name="The Spirits of Zo'bal",orderIndex=2,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=11,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49282] = {id=49282,name="Morgrum's Extended Survey",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49282},series={49428},description="I've looked over the readings my little boxes gave an' I think I know where to look next. The Ashes of Xibala are practically mine. Ye'll want to meet me in the middle of the ruins, under that big ol' leerin' skull on the mountainside, to continue my survey. Readin' these contraptions is hard work, an' I don't think we'll be alone up there. Think ye can watch me back?",objectivesText="Assist Excavator Morgrum Emberflint with a survey.",rewardGold=257400,rewardXP=1415,starts={{npcID=131763}},ends={{npcID=131763}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49060,49274,50044}},
[49283] = {id=49283,name="Who Seeks the Seekers?",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=1165,storyline={49283},series={49284},description="Let me tell you, Zandalar is filled to the brim with ancient secrets. It's quite fascinating. We heard tales of a region, to the southeast, where ships were losing their way. Some even vanished! Raku, along with a team of particularly curious Seekers, has been exploring a cove near there for some time. Shipwrecks and mysteries, what isn't to like? We should have heard back by now. We tortollans may not be fast, but we are reliable. Will you check on them, and make sure they are well?",objectivesText="Locate the Seekers down the coast, to the southeast, and speak to Batu .",rewardGold=25740,rewardXP=175,rewardItems={156871},starts={{npcID=128909}},ends={{npcID=129586}},mapCandidates={npc={862,1165},zone={8670}},questType="standard",sourceQuests={49310},nextQuests={49284,49285}},
[49284] = {id=49284,name="Perfect Tidings",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49284,49285,49286,49287,49288,49289,51407},series={49283},description="Your timing is most convenient, <class>. Our team had a check-in planned for this place, two days past. None have yet returned. I did not want to be brash and send word to the city too soon. However, I cannot leave this place empty, nor can I abandon young Koba. Take this scroll. See who, or what, you can find. Bring back those you can.",objectivesText="Use the attuned Scroll of the Missing to track and find the lost explorers.",rewardGold=257400,rewardXP=1415,rewardItems={154704,156871},starts={{npcID=129586}},ends={{npcID=128889}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49283},questLines={{id=5409,name="Dreadpearl Tidings",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862,startItems={153516}},
[49285] = {id=49285,name="Tiny Treasures",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49284,49285,49286,49287,49288,49289,51407},description="My adults are in the field doing some research. So I stay here, patiently waiting, as they told me to do. These monsters came and took my special treasures! They took my best friend in the whole world, my slug, Spitzy ! They took them all. They ran far. I do not move fast... Could you please get them back, and find my family?",objectivesText="Collect all of Koba 's treasures. Progress: My hatchling... if they laid a finger on him...",rewardXP=1415,rewardItems={156865,156866,156869,156871},starts={{npcID=128888}},ends={{npcID=133417}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49283},questLines={{id=5409,name="Dreadpearl Tidings",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[49286] = {id=49286,name="Caged Wisdom",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49284,49285,49286,49287,49288,49289,51407},description="Oh, hello, friend. It seems there is more here than for what we prepared. We sought. We found. We studied... and then we were taken. There are naga here. We did not expect this. There is a nasty fellow in this cave. If you could get the key from him, it would help us greatly. No need to fret, we'll wait here.",objectivesText="Take the key from Sli'thrus. Progress: Were we asking too much?",rewardGold=514800,rewardXP=1770,rewardItems={154708,156871},starts={{npcID=128889}},ends={{npcID=128889}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49284,49285},questLines={{id=5409,name="Dreadpearl Tidings",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[49287] = {id=49287,name="Lost Chelonians",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49284,49285,49286,49287,49288,49289,51407},description="Tidemistress Nazesh has been channeling on a rock they found in one of the pools above. She has been trying for days. They grow desperate. The rest of my team was taken and locked up in cages. They want secrets from us that we do not know. When they realize we tortollan cannot be coerced, I expect the naga will do something most dire. Release the Seekers. We will thwart the naga plans together.",objectivesText="Rescue tortollans captured by the Nazeshi.",rewardGold=257400,rewardXP=1415,rewardItems={156871},starts={{npcID=128889}},ends={{npcID=128925}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49286},questLines={{id=5409,name="Dreadpearl Tidings",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[49288] = {id=49288,name="Scrollhunters",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49284,49285,49286,49287,49288,49289,51407},description="When they captured us, they took everything we had - including our wonderful scrolls! Those naga witches are building storms. They try to hide what they do here, and seek power for their queen. We see past their madness, they are driven for a purpose. Retrieve our work from the Nazeshi Tempest-Wielders, else they may use them for nefarious gains.",objectivesText="Collect 5 Seeker scrolls. Progress: I really need to invest in some more scroll cases...",rewardGold=257400,rewardXP=1415,rewardItems={153022,156871},starts={{npcID=128889}},ends={{npcID=128925}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49286},questLines={{id=5409,name="Dreadpearl Tidings",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[49289] = {id=49289,name="A Special Stone",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49284,49285,49286,49287,49288,49289,51407},description="Tidemistress Nazesh is right up this hill, <name>. There is something there. Something Azshara wants very badly. The naga must not succeed. If you can get a little piece of that stone, though, bring it back for us. Take this scroll with you, it will help you in your fight. It is time we push her forces, back into the waves for good.",objectivesText="Defeat Tidemistress Nazesh and discover why the naga were sent here. Progress: What have you found?",rewardXP=1770,rewardItems={156871,157539,157543,157554,158440,158441,158442,158443,159151},rewardChoices={159151,158440,158441,158442,158443},starts={{npcID=128925}},ends={{npcID=128925}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49287,49288},questLines={{id=5409,name="Dreadpearl Tidings",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[49290] = {id=49290,name="Aged to Perfection",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={49290},series={49407},description="Greetings, young one. I am Roko . I trade in specialty goods and exotic wares. < Roko pulls a small wooden cask from beneath his shell.> This bourbon is one hundred years old. I know, because I bought it one hundred years ago. A man in Freehold is prepared to trade me a rare scroll for this, but alas I am barred from entering. It seems this town is not so \"free\" anymore. If you can get in, perhaps you could make the trade on my behalf? I would be in your debt.",objectivesText="Deliver the Hundred Year Bourbon to Carentan in Freehold. Progress: Are you with the Irontide? I've already paid you people! Leave me alone!",rewardGold=64350,rewardXP=355,rewardItems={153507},starts={{npcID=128702}},ends={{npcID=128903}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48558,48773}},
[49292] = {id=49292,name="Algae Shakes",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48008,48009,48347,48348,48352,48353,48354,48355,48356,48365,48366,48367,48368,48370,48372,48540,49268,49292,49299,49302},series={48352},description="Now that I have properly developed my tonic, it is of utmost importance that we dispense it amongst the ill at once. Please, take this tankard and distribute the remedy to the sick. I will try to calm the rest.",objectivesText="Dispense the Cleansing Tonic to 6 Nauseated Villagers in Anglepoint Wharf.",rewardGold=257400,rewardXP=1415,rewardItems={152401,152585,152586,153486,153513},starts={{npcID=125922}},ends={{npcID=125922}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48348,48352,49268},questLines={{id=592,name="The Shadow Over Anglepoint",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49293] = {id=49293,name="Invasion Onslaught",level=45,requiredLevel=45,faction="both",categories={},flags={"weekly","repeatable"},sharable=true,expansion=7,zoneID=9024,mapID=885,storyline={49293},description="We must not yield even a single world to the Legion. Continue our Invasion Point offensive and crush the Legion beneath your heel.",objectivesText="Complete 3 standard Invasion Points . Progress: The offensive continues.",rewardCurrencies={{id=1508,amount=200}},starts={{npcID=127051}},ends={{npcID=127051}},mapCandidates={npc={885},zone={8899}},questType="standard",sourceQuests={48605}},
[49295] = {id=49295,name="Clear-Cutting",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="We've managed to hold this hill, but the wicker creatures have moved in to surround us. We're not going to be able to move into the town if we don't get them off our flanks. This is where you come in, <class>. See if you can clear out some of their numbers in the lumber fields. That way, when we move in, we only need to worry about one front.",objectivesText="Kill 8 Curseformed Familiars in the Timbered Strand.",rewardGold=257400,rewardXP=2765,rewardItems={152587,152590},starts={{npcID=126310}},ends={{npcID=126310}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48171},questLines={{id=383,name="Fletcher's Hollow",orderIndex=2,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=19,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[49299] = {id=49299,name="Enemy Within",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48008,48009,48347,48348,48352,48353,48354,48355,48356,48365,48366,48367,48368,48370,48372,48540,49268,49292,49299,49302},description="I won't sugarcoat it, kid. It's a madhouse here. The leadership has fallen, selling their own souls as well as the souls of the workers to some darker forces. I will not give in. Overseer Bates surrendered the guard in his hunger for power. Show him that he is a fool.",objectivesText="Kill Overseer Bates . Progress: After the guard fell, it was easy to get to everybody else.",rewardGold=514800,rewardXP=1770,rewardItems={160083,160084,160085,160086,160093,160094,160095,160096},rewardChoices={160083,160084,160085,160086,160093,160094,160095,160096},starts={{npcID=125962}},ends={{npcID=125962}},mapCandidates={npc={895},zone={8567}},questType="standard",questLines={{id=592,name="The Shadow Over Anglepoint",orderIndex=12,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[49300] = {id=49300,name="Creature Corruption",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={49300},objectivesText="Purge the corruption",rewardGold=455280,rewardXP=1415,mapCandidates={npc={},zone={9042}},questType="standard",sourceQuests={48366},db2Objectives={{text="Purge the corruption",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Creature Corruption",db2PoiMapID=1643,db2PoiUiMapID=895},
[49302] = {id=49302,name="The Deadliest Catch",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={48008,48009,48347,48348,48352,48353,48354,48355,48356,48365,48366,48367,48368,48370,48372,48540,49268,49292,49299,49302},description="Oi! No time to waste! Seems Deepwarden had one more thing up his sleeve... and it's the catch of the day! This'll be a hunt for the ages, and I won't let ya miss out. Okri will fly you out to the wall. Get ready!",objectivesText="Accompany Okri to the sea gate, then kill Viq'Goth . Progress: I've never seen a monster with such dark energy. We can't let it get through!",rewardGold=257400,rewardXP=1415,rewardItems={152401,152585,152586,153486,153513,155053,155057,155059,155064,155072,155079,158295,158296,158298},rewardChoices={155053,155079,155072,155059,158298,155057,158296,158295,155064},starts={{npcID=128679}},ends={{npcID=126298}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48367,48368,48370,48372},questLines={{id=592,name="The Shadow Over Anglepoint",orderIndex=18,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49309] = {id=49309,name="Thunder's Fall",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="Warlord Kao commands de mogu from dis warship. It is time to put an end to dis incursion. I should be able to hold off any stragglers dat may come to Kao's aid, but I can only maintain dis barrier for so long. Be careful. Kao was one of de Thunder King's top generals. He will not fall without a fight.",rewardGold=514800,rewardXP=1770,starts={{npcID=127837}},ends={{npcID=127837}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49147,49148,49149},questLines={{id=373,name="Warport Rastari",orderIndex=7,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=44,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[49310] = {id=49310,name="The Prophet's Ploy",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=9598,mapID=1165,description="King Rastakhan's life is in grave danger. Zul is far more powerful than he appears. We do not have much time. You have to warn de king before Zul can act. Habutu and Zolani can take you dere. Now go!",rewardGold=25740,rewardXP=175,rewardChoices={155250,155251,155252,155253,155259,155260,155261,155262},starts={{npcID=127837}},ends={{npcID=127837}},mapCandidates={npc={862},zone={9598}},questTurnInID=127837,questType="standard",sourceQuests={49309},questLines={{id=373,name="Warport Rastari",orderIndex=8,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=45,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[49314] = {id=49314,name="Hunting Zardrax",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={49314},description="<name>, maybe you be helpin' me wit' sometin'. Talanji said dat Shadow Hunter Da'jul and her retainer, Kal'dran, ran off ta hunt down a lich named Zardrax. They be goin' off ta a place called Burial Mound. I be worried dey be in over dere heads. Can ya check ta see if dey be needin' help? We can't be losin' any of our allies in dis place.",objectivesText="Find Shadow Hunter Da'jul in Burial Mound.",rewardXP=345,starts={{npcID=122795}},ends={{npcID=127215}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47250,49082},nextQuests={48854}},
[49315] = {id=49315,name="Dreadpearl Collusion",level=10,requiredLevel=10,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={49315},objectivesText="Cleanse the Dreadpearl Shallows",rewardGold=339600,rewardXP=1415,mapCandidates={npc={},zone={8499}},questType="standard",db2Objectives={{text="Cleanse the Dreadpearl Shallows",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Dreadpearl Collusion",db2PoiMapID=1642,db2PoiUiMapID=862},
[49327] = {id=49327,name="Push Them Back!",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="The faithless are laying siege to our home. This isn't the first time they've attacked, nor will it be the last, but we must protect the temple! Do whatever you can to disrupt their siege and push them back.",objectivesText="Disrupt the Faithless assault on the Sanctuary of the Devoted.",rewardGold=257400,rewardXP=4115,starts={{npcID=128696}},ends={{npcID=128696}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47324},questLines={{id=609,name="The Three Keepers",orderIndex=3,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=45,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49333] = {id=49333,name="Building Our Arsenal",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={49333},description="Our fight against the faithless is an uphill battle we're bound to lose. We are outnumbered and out armed. What few weapons we have aren't enough to outfit the entire temple. With a few more spears and daggers, we might stand a chance fighting them off until our loa can be returned to us.",objectivesText="Collect 20 Sethrak Weapons from within the Temple Incursion. Progress: We need weapons, <name>.",rewardGold=257400,rewardXP=4115,rewardItems={153556},starts={{npcID=128691}},ends={{npcID=128691}},mapCandidates={npc={864},zone={8501}},questType="standard"},
[49334] = {id=49334,name="A Powerful Prisoner",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="It appears the Faithless broke through our defenses while I was away. They must be after Vorrik 's key. It's the only reason they would have taken him alive. Please, <name>. You must secure our leader's safe return.",objectivesText="Find Vorrik and free him from his captors.",rewardGold=257400,rewardXP=4115,rewardItems={155454,155457},rewardChoices={155457,155454},starts={{npcID=128687}},ends={{npcID=129519}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47324},questLines={{id=609,name="The Three Keepers",orderIndex=1,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=43,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49335] = {id=49335,name="Skycaller Slaughter",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={49335},description="Some among the faithless are gifted with the ability to command the storm. They call themselves skycallers, and they use their magic to summon great spires that turn the earth into sand. Skycallers are the only ones capable of summoning these spires. If you kill the skycallers, you also kill the sethrak's ability to expand their warcamps.",objectivesText="Kill 6 Sethrak Skycallers at the Temple Incursion.",rewardGold=257400,rewardXP=4115,starts={{npcID=128691}},ends={{npcID=128691}},mapCandidates={npc={864},zone={8501}},questType="standard"},
[49340] = {id=49340,name="The Keepers' Keys",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="Serrik mentioned you might have uncovered something of significance at Zul'Ahjin? We don't have much time, I'm afraid. What is it you have found?",objectivesText="Speak to Vorrik and uncover the significance of Sulthis' Stone.",rewardGold=257400,rewardXP=4115,starts={{npcID=129519}},ends={{npcID=128694}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={49327,49334,50641},questLines={{id=609,name="The Three Keepers",orderIndex=4,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=46,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49345] = {id=49345,name="Buried Treasure",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={49345},rewardXP=2090,rewardItems={159828},mapCandidates={npc={},zone={8501}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=10,objectID=159828}},worldTaskTitle="Buried Treasure",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[49348] = {id=49348,name="A Desecrated Temple",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Da spirits of da faithful flock ta me temple. Ya see dem out dere, yes? Dey come ta enter da Other Side an' join me realm. However, spirits who've turned their backs upon Bwonsamdi , dey too have come to me temple grounds. Dey praise one called \"G'huun,\" and spread their blood magic desecration across da Necropolis. Dis ends now! Go out dere and remove da desecrations dat be infesting me temple.",rewardGold=257400,rewardXP=2765,starts={{npcID=122688}},ends={{npcID=122688}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47880},questLines={{id=335,name="A Pact with Death",orderIndex=4,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=17,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49354] = {id=49354,name="Remember the Sunwell",level=40,requiredLevel=40,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=3487,mapID=110,storyline={49354,49613,49614,49973},series={49613,49614},description="The Regent Lord intends to show First Arcanist Thalyssra our Sunwell. I do not know if he will allow Alleria Windrunner to attend the meeting, but we are invited to join them.",objectivesText="Complete the scenario, \"Remember the Sunwell.\"",rewardGold=341600,rewardXP=5465,starts={{npcID=130133}},ends={{npcID=130133}},mapCandidates={npc={110},zone={3487}},questType="standard",sourceQuests={49613},questLines={{id=531,name="Allies of the Horde: Nightborne",orderIndex=2,flags=0},{id=5697,name="Lorewalking: Elves",orderIndex=6,flags=0}},campaigns={{id=274,title="Lorewalking:Elves",questLineID=5697,questLineOrder=0}},db2PoiMapID=530,db2PoiUiMapID=110},
[49366] = {id=49366,name="Aid the Wounded",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={49366,49370,49376,49377,49378,49379,49380,49382},series={50934},description="<This Zandalari appears to be barely holding on. There is a broken dart lying on the ground next to him. He appears to have dropped this bottle before he collapsed. You grab the vial. Could it be some kind of antidote?>",objectivesText="Treat the wounded Zandalari.",rewardGold=128700,rewardXP=1385,rewardItems={153676,156566,198048,200454,204075,204732,204733,204745,204762,204764,204765,204766,204770,204772,204773,204775,204778,204779,204780,204785,204786,204898,204901},ends={{npcID=129165}},startObjects={{objectID=278197,mapID=863,x=0.64,y=0.503}},coords={mapID=863,source="quest_giver",x=0.632,y=0.528},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={50934},questLines={{id=5420,name="Crawgling Conundrum",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[49367] = {id=49367,name="Tracking Quest",expansion=7,mapID=863,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Blood Corruption Cleansed"},{orderIndex=1,type=0,amount=34,objectID=123039,text="Ancient Spirits slain"}},worldTaskTitle="Tracking Quest"},
