[49553] = {id=49553,name="Hero's Call: Sholazar Basin!",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=3711,mapID=125,storyline={28709,39204,39207,49551,49552,49553,49554,49555,60096,60962},series={12489,12521,39209,39212,49535},description="All able-bodied citizens of the Alliance are to report to Archmage Pentarus in Dalaran over Crystalsong Forest. Hemet Nesingwary, along with his expeditionary force, was sent to explore Sholazar Basin , but has gone missing. We do not know much about the lush landscape of Sholazar, but there might be secrets in the basin that can give us an advantage in our fight against the Lich King. Glory to the Alliance!",objectivesText="Speak with Archmage Pentarus in Dalaran over Crystalsong Forest.",rewardGold=10500,rewardXP=345,startObjects={{objectID=206111,mapID=84,x=0.261,y=0.383}},endObjects={{objectID=206111,mapID=84,x=0.261,y=0.383}},coords={mapID=84,x=0.261,y=0.383},mapCandidates={npc={},zone={4395}},questType="standard",nextQuests={12521},questLines={{id=5579,name="Wrath of the Lich King Chromie Time Breadcrumbs",orderIndex=7,flags=0}},db2PoiMapID=571,db2PoiUiMapID=125},
[49554] = {id=49554,name="Hero's Call: Storm Peaks!",level=25,requiredLevel=25,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=6611,mapID=501,storyline={28709,39204,39207,49551,49552,49553,49554,49555,60096,60962},series={12853,49536},description="All able-bodied citizens of the Alliance are to report to Rin Duoctane in Dalaran over Crystalsong Forest. The goblins of K3 have built a city in Storm Peaks and have sent their ambassador to recruit adventurers. Speak with Rin and see what the people of K3 need. They would make valuable allies in our fight against the Lich King. Glory to the Alliance!",objectivesText="Speak with Rin Duoctane in Dalaran over Crystalsong Forest.",rewardGold=10500,rewardXP=430,mapCandidates={npc={},zone={6611}},questType="standard",nextQuests={12853},questLines={{id=5579,name="Wrath of the Lich King Chromie Time Breadcrumbs",orderIndex=8,flags=0}},db2PoiMapID=571,db2PoiUiMapID=126},
[49555] = {id=49555,name="Hero's Call: Icecrown!",level=25,requiredLevel=25,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=210,mapID=125,storyline={28709,39204,39207,49551,49552,49553,49554,49555,60096,60962},series={13418},description="All able-bodied citizens of the Alliance are to report to Officer Van Rossem in Dalaran over Crystalsong Forest. The Valiance Expedition needs more adventurers to bolster their assault on assault Icecrown Citadel and Arthas himself. It is time to make the Lich King pay for his crimes. Glory to the Alliance!",objectivesText="Speak with Officer Van Rossem in Dalaran over Crystalsong Forest.",rewardGold=10500,rewardXP=430,startObjects={{objectID=206111,mapID=84,x=0.261,y=0.383}},endObjects={{objectID=206111,mapID=84,x=0.261,y=0.383}},coords={mapID=84,x=0.261,y=0.383},mapCandidates={npc={},zone={4395}},questType="standard",nextQuests={13418},questLines={{id=5579,name="Wrath of the Lich King Chromie Time Breadcrumbs",orderIndex=9,flags=0}},db2PoiMapID=571,db2PoiUiMapID=125},
[49556] = {id=49556,name="Hero's Call: Jade Forest!",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=5785,mapID=84,storyline={49556},series={29547,29548,31732,31733,60125},description="All able-bodied citizens of the Alliance are to report to Stormwind Keep in Stormwind. Grand Admiral Jes-Tereth is assembling a team for a high priority mission. Head to Stormwind Keep immediately to be briefed. Glory to the Alliance!",objectivesText="Report to Grand Admiral Jes-Tereth in Stormwind Keep.",rewardGold=13740,rewardXP=175,ends={{npcID=55789}},startObjects={{objectID=206111,mapID=84,x=0.261,y=0.383}},coords={mapID=84,source="quest_giver",x=0.791,y=0.396},mapCandidates={npc={84},zone={1519}},questType="standard",nextQuests={29548}},
[49557] = {id=49557,name="Hero's Call: Valley of the Four Winds!",level=15,requiredLevel=15,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=5805,mapID=376,storyline={49557},series={29907,29908,29909,29911,29912,29940,32018,32019,38935,49539},description="All able-bodied citizens of the Alliance are to report to Chen Stormstout in the Valley of the Four Winds . The adventuring spirit of the Stormstouts is something that the Alliance can learn from. Travel with the Stormstouts and discover what secrets Pandaria holds. Glory to the Alliance!",objectivesText="Speak with Chen Stormstout in the Valley of the Four Winds .",rewardGold=28090,rewardXP=260,ends={{npcID=56133}},startObjects={{objectID=206111,mapID=84,x=0.261,y=0.383}},coords={mapID=376,source="quest_giver",x=0.6065,y=0.46575},mapCandidates={npc={376},zone={5805}},questType="standard",nextQuests={29907}},
[49558] = {id=49558,name="Hero's Call: Krasarang Wilds!",level=15,requiredLevel=15,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=6134,mapID=376,storyline={49558},series={29873,30079,30081,49540},description="All able-bodied citizens of the Alliance are to report to Zhu's Watch in Krasarang Wilds . There have been rumors that the pandaren living in Krasarang Wilds are not their usual self. Speak with Ken-Ken at Zhu's Watch. Perhaps he has a better idea of what has happened to cause the pandaren to become lethargic.",objectivesText="Speak with Ken-Ken in Krasarang Wilds .",rewardGold=2775,rewardXP=260,ends={{npcID=56115}},startObjects={{objectID=206111,mapID=84,x=0.261,y=0.383}},coords={mapID=376,source="quest_giver",x=0.51,y=0.262},mapCandidates={npc={376},zone={6134}},questType="standard",nextQuests={30079}},
[49559] = {id=49559,name="Hero's Call: Kun-Lai Summit!",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=5841,mapID=371,storyline={49559},series={30457,31254,31255,38936,49541},description="All able-bodied citizens of the Alliance are to assist Lorewalker Cho in Kun-Lai Summit . Speak with a messenger grummle in Valley of the Four Winds. They will show you the way to Kun-Lai Summit . Glory to the Alliance!",objectivesText="Speak to the Messenger Grummle in Valley of the Four Winds.",rewardGold=13740,rewardXP=345,ends={{npcID=63778}},startObjects={{objectID=206111,mapID=84,x=0.261,y=0.383}},coords={mapID=371,source="quest_giver",x=0.458,y=0.438},mapCandidates={npc={371},zone={5785}},questType="standard",nextQuests={31254}},
[49560] = {id=49560,name="Hero's Call: Townlong Steppes!",level=25,requiredLevel=25,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=5842,mapID=388,storyline={49560},series={30814,31695,39127,49542},description="All able-bodied citizens of the Alliance are to report to Taran Zhu in Townlong Steppes . The Shado-Pan want to reclaim their land from the clutches of the yaungol, but lack the numbers to do so. Assist them with their assault against the yaungol. Glory to the Alliance!",objectivesText="Speak with Taran Zhu in Townlong Steppes .",rewardGold=13740,rewardXP=430,ends={{npcID=60688}},startObjects={{objectID=206111,mapID=84,x=0.261,y=0.383}},coords={mapID=388,source="quest_giver",x=0.712,y=0.565},mapCandidates={npc={388},zone={5842}},questType="standard",nextQuests={30814}},
[49561] = {id=49561,name="Hero's Call: Dread Wastes!",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=5840,mapID=390,storyline={49561},series={31001,31895,49543},description="All able-bodied citizens of the Alliance are to report to Bowmistress Li on the Serpent's Spine in the Vale of Eternal Blossoms. The Shado-Pan are attempting to stop the mantid army from invading the entirety of Pandaria. You can reach Bowmistress Li by securing a kite and flying to the Serpent's Spine. Glory to the Alliance!",objectivesText="Speak with Bowmistress Li on the Serpent's Spine.",rewardGold=13740,rewardXP=515,ends={{npcID=62112}},startObjects={{objectID=206111,mapID=84,x=0.261,y=0.383}},coords={mapID=390,source="quest_giver",x=0.142,y=0.77},mapCandidates={npc={390},zone={5840}},questType="standard",nextQuests={31001}},
[49562] = {id=49562,name="Hero's Call: Shadowmoon Valley!",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=6719,mapID=539,storyline={49562},series={34575,34582,34583},description="All able-bodied citizens of the Alliance are to report to Prophet Velen in Shadowmoon Valley on Draenor. The destruction of the Dark Portal has stopped the Iron Horde invasion of Azeroth, but now we must to take the fight to them. With Prophet Velen 's blessing, we will be able to establish a strategic position in Draenor to fight against the enemies of Azeroth. Glory to the Alliance!",objectivesText="Speak with Prophet Velen in Shadowmoon Valley on Draenor.",rewardGold=200,rewardXP=175,ends={{npcID=79206}},startObjects={{objectID=206111,mapID=84,x=0.261,y=0.383}},coords={mapID=539,source="quest_giver",x=0.27,y=0.08},mapCandidates={npc={539},zone={6719}},questType="standard",nextQuests={34582}},
[49564] = {id=49564,name="Hero's Call: Gorgrond!",level=15,requiredLevel=15,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=7078,mapID=543,storyline={49564},series={33255,33256,33533,35033,35050,35065,35556,36632},description="All able-bodied citizens of the Alliance are to report to Yrel in Gorgrond . Yrel and Maraad are requesting for a small expedition to be sent into the wilds of Gorgrond . We hope to gain a better understanding of the land in hopes that it will show us how to exploit weaknesses in the Iron Horde. Assist them with their expedition. Glory to the Alliance!",objectivesText="Speak with Yrel in Gorgrond .",rewardGold=30900,rewardXP=260,ends={{npcID=80978}},startObjects={{objectID=206111,mapID=84,x=0.261,y=0.383}},coords={mapID=543,source="quest_giver",x=0.584,y=0.584},mapCandidates={npc={543},zone={7078}},questType="standard",nextQuests={35033}},
[49565] = {id=49565,name="Hero's Call: Talador!",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=6662,mapID=535,storyline={49565},series={34558,34676,35702,36495,36576,37183,92692},description="All able-bodied citizens of the Alliance are to report to Foreman Eksos in Talador . The Iron Horde seek to control Talador . The area is perfect to send reinforcements to any other part of Draenor quickly and without resistance. Foreman Eksos is currently establishing an outpost in Talador . Travel there and stop the Iron Horde. Glory to the Alliance!",objectivesText="Speak with Foreman Eksos in Talador .",rewardGold=30900,rewardXP=345,ends={{npcID=79133}},startObjects={{objectID=206111,mapID=84,x=0.261,y=0.383}},coords={mapID=535,source="quest_giver",x=0.698,y=0.208},mapCandidates={npc={535},zone={6662}},questType="standard",nextQuests={34558}},
[49566] = {id=49566,name="Hero's Call: Spires of Arak!",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=6722,mapID=542,storyline={49566},series={34653,34655,34656,34657,34658,34659,34756,34805,35537,35554,35636,35668,35671,36951,49548},description="All able-bodied citizens of the Alliance are to report to Azik in Spires of Arak . There have been wingless arakkoa seen fleeing from Spires of Arak . Rumors suggest that they are running from an Iron Horde superweapon. We need to find out what is causing them to leave their homeland, and why their wings have withered. Glory to the Alliance!",objectivesText="Speak with Azik in the Spires of Arak .",rewardGold=28090,rewardXP=515,ends={{npcID=79539}},startObjects={{objectID=206111,mapID=84,x=0.261,y=0.383}},coords={mapID=542,source="quest_giver",x=0.378,y=0.18},mapCandidates={npc={542},zone={6722}},questType="standard",nextQuests={34655}},
[49567] = {id=49567,name="Hero's Call: Nagrand!",level=35,requiredLevel=35,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=6755,mapID=550,storyline={49567},series={34674,34675,34678,34682,37184},description="All able-bodied citizens of the Alliance are to report to Lieutenant Balfor in Nagrand on Draenor. Yrel is recommending that the Alliance establish an outpost in Nagrand to help in our fight against the Warsong clan. Secure a flight to Nagrand and meet up with Lieutenant Balfor and the supply caravan. Glory to the Alliance!",objectivesText="Speak with Lieutenant Balfor in Nagrand on Draenor.",rewardGold=30900,rewardXP=600,ends={{npcID=79263}},startObjects={{objectID=206111,mapID=84,x=0.261,y=0.383}},coords={mapID=550,source="quest_giver",x=0.864,y=0.662},mapCandidates={npc={550},zone={6755}},questType="standard",nextQuests={34675}},
[49569] = {id=49569,name="Down by the Riverside",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={50076},description="We have de aid of Krag'wa and de Gob Squad. We must get back to Zul'jan and begin our plan to stop de blood trolls. We have one problem. De Gob Squad are unable to move their mech fast enough in de jungle. We must take it by boat. De two of us will ride with dem and ensure de blood trolls do not destroy de mech. I will run ahead and get de boat ready near de riverbank. Meet us dere.",rewardGold=257400,rewardXP=2765,rewardItems={159827},starts={{npcID=126213}},ends={{npcID=121288}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47602,49985},questLines={{id=524,name="Bleeding the Blood Trolls",orderIndex=0,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=76,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49570] = {id=49570,name="A Rocky Start",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={49570,49571,49572,49573,49574,49575,49576,49577,49584,55585,55586,55590},series={49571,49574,49577},description="<As you thumb through the book, the pages are unusually thick and embedded on their surface are runic-shaped jewels. Samuel Colton notices you looking and approaches.> Ah, now that's a treasure I've had for many years. Beautiful, isn't it? No clue what it says, but I've always reveled at the thought of something being transcribed in jewels. Come to think of it, I wonder if Zooey Inksprocket would be able to decipher it. Say, <name>, would you mind taking it over to her and see if she can translate it?",objectivesText="Bring the book to Zooey Inksprocket and see if she can translate the text. Provided item:",rewardGold=23400,rewardXP=850,rewardItems={153716,155676},startObjects={{objectID=278570,mapID=1161,x=0.75,y=0.102}},endObjects={{objectID=278570,mapID=1161,x=0.75,y=0.102}},coords={mapID=1161,x=0.75,y=0.102},mapCandidates={npc={},zone={8568}},questType="standard",questLines={{id=887,name="8.1.5 Jewelcrafting - Alliance",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[49571] = {id=49571,name="Digging Through the Past",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={49570,49571,49572,49573,49574,49575,49576,49577,49584,55585,55586,55590},series={49570,49574,49577},description="Let's see, Jane Hudson probably still has her book on ancient runes and carvings. And I believe Tal'ana has a few scrolls he picked up from Ulduar. OH! And Toopa found what appeared to be some type of codex the last time he ventured out. I remember seeing the runes on it and they bear a striking resemblance to the ones in this book. If you could convince them to uh... lend us those items for a bit, I believe I just might be able to create a translation for you. I won't even charge you for it!",objectivesText="Ask Jane Hudson for her book of Primordial Races: Runes and Writings . Ask Tal'ana for his Scrolls of the Stonefather . And ask Toopa for the The Dungard Codex . Progress: How goes the translation?",rewardGold=58500,rewardXP=1705,rewardItems={155587,155588,155589,155678},starts={{npcID=130399}},ends={{npcID=130399}},mapCandidates={npc={},zone={8568}},questGiverID=130399,questTurnInID=130399,questType="standard",sourceQuests={49570},questLines={{id=887,name="8.1.5 Jewelcrafting - Alliance",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[49572] = {id=49572,name="The Shrine of the Sea",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=895,storyline={49570,49571,49572,49573,49574,49575,49576,49577,49584,55585,55586,55590},series={49575},description="This next shrine is right here, in Tiragarde Sound. According to the journal, the earthen mentions creating bluish hued jewels. I wonder if that's anything like the kyanite we have here. Go and see if the shrine still stands. Hopefully it's still in a usable state. I'll continue to study the journal for more information.",objectivesText="Investigate the Shrine of the Sea in Tiragarde Sound.",rewardGold=23400,rewardXP=850,starts={{npcID=130368}},ends={{npcID=130368}},mapCandidates={npc={},zone={8568}},questGiverID=130368,questTurnInID=130368,questType="standard",sourceQuests={55585},questLines={{id=887,name="8.1.5 Jewelcrafting - Alliance",orderIndex=8,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49573] = {id=49573,name="The Shrine of the Eventide",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=896,storyline={49570,49571,49572,49573,49574,49575,49576,49577,49584,55585,55586,55590},series={49576},description="There are two more shrines here on Kul Tiras. I believe this next one resides within Drustvar, near the Bleak Hills Mine, southeast of Corlain. Here are the notes on that shrine. Should it also need mending, I'm positive your skills with jewels can meet the challenge of repairing it.",objectivesText="Travel to the location marked on your map and investigate the shrine in Drustvar. Do what you can to repair the shrine, should the need arise.",rewardGold=23400,rewardXP=850,starts={{npcID=130368}},ends={{npcID=130368}},mapCandidates={npc={},zone={8568}},questGiverID=130368,questTurnInID=130368,questType="standard",sourceQuests={55585},questLines={{id=887,name="8.1.5 Jewelcrafting - Alliance",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[49574] = {id=49574,name="The Shrine of Storms",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=942,storyline={49570,49571,49572,49573,49574,49575,49576,49577,49584,55585,55586,55590},series={49570,49571,49577},description="Yes, I believe there are a few here in Kul Tiras. You should visit them, <name>, investigate them. See if what this book says is true. This particular shrine he mentions sounds like it may reside near Brennadam, in Stormsong Valley. It should be fairly easy to find. If my calculations are correct, it should be just north of that town. Here are the notes on that one. And I've marked its location for you on your map. Good luck, <name>.",objectivesText="Travel to the location marked on your map and investigate the shrine in Stormsong Valley. Do what you can to repair the shrine, should the need arise.",rewardGold=23400,rewardXP=850,starts={{npcID=130368}},ends={{npcID=130368}},mapCandidates={npc={},zone={8568}},questGiverID=130368,questTurnInID=130368,questType="standard",sourceQuests={49571},questLines={{id=887,name="8.1.5 Jewelcrafting - Alliance",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[49575] = {id=49575,name="Tol Dagor: Jewel of the Tides",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=9327,mapID=895,storyline={49570,49571,49572,49573,49574,49575,49576,49577,49584,55585,55586,55590},series={49572},description="<An absence you assume to be a mistake, you quickly survey the area for something that might fit there yet you find nothing. However, there appears to be a drunk here shouting at the shrine. Perhaps he might know the whereabouts of the shrine's missing piece.>",objectivesText="Speak with \"Slippery\" Salton and learn what you can about the missing centerpiece. Progress: <Perhaps finding the missing centerpiece will give you a clue into the shrine's operation?>",rewardGold=936000,rewardXP=13630,rewardItems={153716,155648},starts={{npcID=150893}},ends={{npcID=150893}},mapCandidates={npc={},zone={9327}},questGiverID=150893,questTurnInID=150893,questType="dungeon",sourceQuests={49572},questLines={{id=887,name="8.1.5 Jewelcrafting - Alliance",orderIndex=9,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49576] = {id=49576,name="High Prospects",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49570,49571,49572,49573,49574,49575,49576,49577,49584,55585,55586,55590},series={49573},description="<Checking your notes, you find that the earthen had extracted the gems from some earth elementals to the south. Looking at your map, you wonder if he was referring to the now ruins of a once ancient settlement that has become littered with constructs and undead. Perhaps investigating there will yield some clues as to where to find these jewels.>",objectivesText="Investigate Gol Osigr for clues about the jewels that were used to construct the shrine. Progress: <All of the cracked jewels will definitely need to be replaced.>",rewardGold=234000,rewardXP=6815,rewardItems={153716,155661,155830},starts={{npcID=150896}},ends={{npcID=150896}},mapCandidates={npc={},zone={8721}},questGiverID=150896,questTurnInID=150896,questType="standard",sourceQuests={49573},questLines={{id=887,name="8.1.5 Jewelcrafting - Alliance",orderIndex=6,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[49577] = {id=49577,name="Cracking the Surface",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,mapID=942,storyline={49570,49571,49572,49573,49574,49575,49576,49577,49584,55585,55586,55590},series={49570,49571,49574},description="<Checking your notes, the earthen mentions having prospected the jewels from a nearby mountain to the northwest. Perhaps you can prospect the earth in that area to find more of those jewels and repair the shrine.>",objectivesText="Go to the Windshorn Hills and gather 20 Shard of Golden Beryl . Progress: <The placement of the jewels on this shrine appear to be placed in a rather intricate fashion.>",rewardGold=234000,rewardXP=6815,rewardItems={153716,155590},starts={{npcID=150898}},ends={{npcID=150898}},mapCandidates={npc={},zone={}},questGiverID=150898,questTurnInID=150898,questType="standard",sourceQuests={49574},questLines={{id=887,name="8.1.5 Jewelcrafting - Alliance",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[49578] = {id=49578,name="REUSE ME",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,storyline={49578},series={49584},description="I've been to Zandalar before. Crazy place, full of dinosaurs and other unspeakable beasts. However one of the shrine's locations the journal speaks of sounds like a place they call Vol'dun. It's a foreboding desert, full of canyons, with a great pyramid in the center. If my calculations are correct though, the shrine ought to be around this area. I'll mark it for you on your map. And let's hope it's still in one piece.",objectivesText="Travel to the location marked on your map and investigate the shrine in Vol'dun. Do what you can to repair the shrine, should the need arise.",rewardGold=257400,rewardXP=200,rewardItems={71083,128823,133803,133804,142342,181368,181377,181585,181605,181610,181611,181703,181704,181745,184294,184362,184363,184765,184766,184767,184768,184839,184841,190456,198048,200453,204075,204743,204744,204747,204748,204750,204752,204754,204758,204759,204761,204766,204769,204774,204780,204787,204896,204898},mapCandidates={npc={},zone={}},questType="standard"},
[49579] = {id=49579,name="REUSE ME",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,storyline={49579},description="This next shrine might be a bit difficult to get to. It resides in Zandalar, the heart of the troll empire. Well, maybe not the main city itself, but close to it. Actually... Ah, it's not too far from (POI). I've heard there's been some strife there between the Horde and Alliance. Perhaps there's a camp there you can work out of. Here are you notes for the shrine and the location for it should be marked on your map.",objectivesText="Travel to the location marked on your map and investigate the shrine in Zandalar. Do what you can to repair the shrine, should the need arise.",rewardGold=257400,rewardXP=200,rewardItems={71083,128823,133803,133804,142342,181368,181377,181585,181605,181610,181611,181703,181704,181745,184294,184362,184363,184765,184766,184767,184768,184839,184841,190456,198048,200453,204075,204743,204744,204747,204748,204750,204752,204754,204758,204759,204761,204766,204769,204774,204780,204787,204896,204898},mapCandidates={npc={},zone={}},questType="standard"},
[49580] = {id=49580,name="REUSE ME",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,storyline={49580},description="The last shrine resides in Nazmir, a swamp infested with deadly creatures and home of the blood trolls. Luckily an ally of mine gave me a rather detailed map of that region and if my calculations are correct... It should be right there. Take note of its location and here are the notes for that shrine. Good luck, .",objectivesText="Travel to the location marked on your map and investigate the shrine in Nazmir. Do what you can to repair the shrine, should the need arise.",rewardGold=257400,rewardXP=200,rewardItems={71083,128823,133803,133804,142342,181368,181377,181585,181605,181610,181611,181703,181704,181745,184294,184362,184363,184765,184766,184767,184768,184839,184841,190456,198048,200453,204075,204743,204744,204747,204748,204750,204752,204754,204758,204759,204761,204766,204769,204774,204780,204787,204896,204898},mapCandidates={npc={},zone={}},questType="standard"},
[49581] = {id=49581,name="Sun-Speckled Dunes",level=50,requiredLevel=50,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,mapID=864,storyline={49581,49582,49583,49585,49586,49587,49588,49589,49599,55592,55594,55596},series={49588},description="<Looking at your notes, the earthen mentions coming across dunes sprinkled with orange gems. He said it reminded him of the soft sunlight in this area. Checking your notes, it appears that these dunes were located south of your current location.>",objectivesText="Go to the location on your map where you believe these gems to be and recover 8 of them. Polish and shape them when you've collected enough. Progress: <These gems have a very strong structure. Time, in addition to the winds, must have also taken its toll on them.>",rewardGold=234000,rewardXP=6815,rewardItems={153716,155664,155665},starts={{npcID=150895}},ends={{npcID=150895}},mapCandidates={npc={},zone={}},questGiverID=150895,questTurnInID=150895,questType="standard",sourceQuests={49588},questLines={{id=888,name="8.1.5 Jewelcrafting - Horde",orderIndex=6,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49582] = {id=49582,name="Atal'Dazar: Not All That Glitters...",level=50,requiredLevel=50,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=9028,mapID=862,storyline={49581,49582,49583,49585,49586,49587,49588,49589,49599,55592,55594,55596},series={49587},description="<You reference your notes on the shrine and discover that these jewels came from a \"golden sanctuary\". Given your location, that can only mean Atal'Dazar. Perhaps you could find a replacement from that ancient city.>",objectivesText="Travel to Atal'Dazar and find a replacement for the broken jewel. Progress: <When you're done replacing the central gem, you think you might still be able to sell the old one.>",rewardGold=936000,rewardXP=13630,rewardItems={155666},starts={{npcID=150894}},ends={{npcID=150894}},mapCandidates={npc={},zone={9028}},questGiverID=150894,questTurnInID=150894,questType="dungeon",sourceQuests={49587},questLines={{id=888,name="8.1.5 Jewelcrafting - Horde",orderIndex=9,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[49583] = {id=49583,name="Out With the Old",level=50,requiredLevel=50,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,mapID=863,storyline={49581,49582,49583,49585,49586,49587,49588,49589,49599,55592,55594,55596},series={49585,49586,49589},description="<It's clear though that time has had its way with these gems, some eroded and chipped in places. Repairing this shrine may be as simple as replacing the old gems with newer ones of the same type and cut.>",objectivesText="Cut 4 Natant Rubellites and replace the old ones with the new. Progress: <Interesting that the cut should be so similar, you wonder how the design has persisted all these years.>",rewardGold=23400,rewardXP=850,rewardItems={153714,153716,158639,158640,158642,158643,158644,158645,158648,158649,160207},starts={{npcID=150897}},ends={{npcID=150897}},mapCandidates={npc={},zone={}},questGiverID=150897,questTurnInID=150897,questType="standard",sourceQuests={49589},questLines={{id=888,name="8.1.5 Jewelcrafting - Horde",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[49584] = {id=49584,name="The Missing Chapter",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={49570,49571,49572,49573,49574,49575,49576,49577,49584,55585,55586,55590},series={49578},description="<Samuel puts down the journal and looks back up at you.> While trying to figure out where the shrines reside, I came across an entry that mentioned him exploring an area that sounds very similar to Dustwallow Marsh. He mentions hiding something of great importance there. It's a long shot, given when this earthen roamed Azeroth, but perhaps if you were to retrace his final steps you may find something. I'll mark the location on your map.",objectivesText="Travel to the location marked on your map and see what you can find. Progress: Who knows what you may find out there. Hopefully something...",rewardGold=468000,rewardXP=8520,rewardItems={5996,155668,155669},starts={{npcID=130368}},ends={{npcID=130368}},mapCandidates={npc={},zone={8568}},questGiverID=130368,questTurnInID=130368,questType="standard",sourceQuests={55586,55590},questLines={{id=887,name="8.1.5 Jewelcrafting - Alliance",orderIndex=11,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[49585] = {id=49585,name="A Rocky Start",level=50,requiredLevel=50,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={49581,49582,49583,49585,49586,49587,49588,49589,49599,55592,55594,55596},series={49583,49586,49589},description="<As you thumb through the book, you see odd-looking runes carved out of jewels embedded in the stone pages. Seshuli notices you looking and approaches you.> Ah, dat's been a treasure of mine for many years. Beautiful, isn't it? No clue what it says, but I've always reveled at de thought of something being written in jewels. Come to think of it, I wonder if Grazzul would know what it says. <name>, would you mind taking it over to him and see if he can translate it?",objectivesText="Bring the book to Grazzul and see if he can translate the text. Provided item:",rewardGold=23400,rewardXP=850,rewardItems={153716,155676},ends={{npcID=130901}},startObjects={{objectID=278570,mapID=1165,x=0.469,y=0.38}},coords={mapID=1165,source="quest_giver",x=0.422,y=0.395},mapCandidates={npc={1165},zone={8670}},questType="standard",questLines={{id=888,name="8.1.5 Jewelcrafting - Horde",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[49586] = {id=49586,name="Digging Through the Past",level=50,requiredLevel=50,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={49581,49582,49583,49585,49586,49587,49588,49589,49599,55592,55594,55596},series={49583,49585,49589},description="Let's see, Examiner Alerinda has a book on ancient runes and carvings. I think Koatini has a few scrolls he brought with him from Ulduar. OH! And Chronicler Shoopa found a codex de last time he ventured out. I remember seeing de runes on it and dey look a lot like de ones in dis book. Maybe you can convince dem to lend us dose books for a bit, and I think I can create a translation for you.",objectivesText="Ask Examiner Alerinda for her book of Primordial Races: Runes and Writings . Ask Koatini for his Scrolls of the Stonefather . And ask Chronicler Shoopa for the The Dungard Codex . Progress: How is de translation going?",rewardGold=58500,rewardXP=1705,rewardItems={155587,155588,155589,155678},starts={{npcID=130901}},ends={{npcID=122695}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={49585},questLines={{id=888,name="8.1.5 Jewelcrafting - Horde",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[49587] = {id=49587,name="The Shrine of Nature",level=50,requiredLevel=50,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={49581,49582,49583,49585,49586,49587,49588,49589,49599,55592,55594,55596},series={49582},description="Another shrine resides right here in Zuldazar. According to de journal, de earthen talks about creating green hued jewels dere. I wonder if dat's anything like de viridium we find in de ore we mine. Go and see if de shrine still stands. Hopefully, we can still make use of it. I'll continue to study de journal for more information.",objectivesText="Investigate the Shrine of Nature in Zuldazar.",rewardGold=23400,rewardXP=850,starts={{npcID=122695}},ends={{npcID=122695}},mapCandidates={npc={1165},zone={8670}},questTurnInID=122695,questType="standard",sourceQuests={55592},questLines={{id=888,name="8.1.5 Jewelcrafting - Horde",orderIndex=8,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[49588] = {id=49588,name="The Shrine of the Sands",level=50,requiredLevel=50,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={49581,49582,49583,49585,49586,49587,49588,49589,49599,55592,55594,55596},series={49581},description="Dere are two more shrines here on Zandalar. Dis next one resides within Vol'dun, near Bonetrail Gulch. Hopefully de Faithless haven't defiled de shrine. Here are de notes on dat location. Should dat shrine also need fixing, I think your skills with jewels will probably be enough to fix it.",objectivesText="Travel to the location marked on your map and investigate the shrine in Vol'dun. Do what you can to repair the shrine, should the need arise.",rewardGold=23400,rewardXP=850,starts={{npcID=122695}},ends={{npcID=122695}},mapCandidates={npc={1165},zone={8670}},questTurnInID=122695,questType="standard",sourceQuests={55592},questLines={{id=888,name="8.1.5 Jewelcrafting - Horde",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49589] = {id=49589,name="The Shrine of the Dawning",level=50,requiredLevel=50,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={49581,49582,49583,49585,49586,49587,49588,49589,49599,55592,55594,55596},series={49583,49585,49586},description="Yea, I believe there are a few here on Zandalar. You should find dem, <name>, investigate dem. See if what dis book says is true. Dis particular shrine sounds like it might be in Nazmir. If my calculations are correct, it should be just south of Torga's Rest. Dat loa was a mighty one. It is truly sad dat it is no longer with us. Here are de notes on dat one. And I've marked its location for you on your map. Loa be with you, <name>.",objectivesText="Travel to the location marked on your map and investigate the shrine in Nazmir. Do what you can to repair the shrine, should the need arise.",rewardGold=23400,rewardXP=850,starts={{npcID=122695}},ends={{npcID=122695}},mapCandidates={npc={1165},zone={8670}},questTurnInID=122695,questType="standard",sourceQuests={49586},questLines={{id=888,name="8.1.5 Jewelcrafting - Horde",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[49590] = {id=49590,name="REUSE ME",level=50,requiredLevel=50,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,storyline={49590},description="As you peer from one gem to the next, you realize that the shrine appears to be fine, yet no power radiates from it. Pulling out your jewelcrafting tools, you begin to inspect the central gem and realize that there is in fact a flaw. A small crack near the base of it that permeates through the gem towards the back. You reference your notes on the shrine and discover that this gem came from a \"golden sanctuary\". Perhaps someone back at the Explorer's League Campsite will know what this means. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(49590)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(49590))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Travel to the Reliquary Camp and ask around about the \"golden sanctuary\". Then find a replacement gem once you learn of its location.",rewardGold=996000,rewardXP=200,rewardItems={71083,128823,133803,133804,142342,181368,181377,181585,181605,181610,181611,181703,181704,181745,184294,184362,184363,184765,184766,184767,184768,184839,184841,190456,198048,200453,204075,204743,204744,204747,204748,204750,204752,204754,204758,204759,204761,204766,204769,204774,204780,204787,204896,204898},mapCandidates={npc={},zone={}},questType="dungeon"},
[49591] = {id=49591,name="REUSE ME",level=1,requiredLevel=1,faction="none",categories={},flags={},sharable=false,expansion=7,storyline={49591},description="Surveying the shrine, you believe that the sandy winds in this area have worn down the embedded gems, producing odd shapes and cracks in some. Looking at your notes, the earthen mentions coming across dunes sprinkled with orange gems. He said it reminded him of the soft sunlight in this area. Samuel added his own note saying he believes the location of these gems to be south of the shrine's location. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(49591)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(49591))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Go to the location on your map where you believe these gems to be and recover $1oa of them. Polish and shape them as you find them.",rewardGold=996000,rewardXP=200,rewardItems={71083,128823,133803,133804,142342,181368,181377,181585,181605,181610,181611,181703,181704,181745,184294,184362,184363,184765,184766,184767,184768,184839,184841,190456,198048,200453,204075,204743,204744,204747,204748,204750,204752,204754,204758,204759,204761,204766,204769,204774,204780,204787,204896,204898},mapCandidates={npc={},zone={}},questType="standard"},
[49592] = {id=49592,name="REUSE ME",level=50,requiredLevel=50,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,storyline={49592},description="Upon inspection of the shrine, you notice something... familiar. The cut of the gems looks like a primitive or simple version of the way you've learned to cut rubellites. It's clear though that time has had its way with these gems, some eroded and chipped in places. Repairing this shrine may be as simple as replacing the old gems with newer ones of the same type and cut. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(49592)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(49592))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Cut $1oa Insightful Rubellites and replace the old ones with the new.",rewardGold=996000,rewardXP=200,rewardItems={71083,128823,133803,133804,142342,181368,181377,181585,181605,181610,181611,181703,181704,181745,184294,184362,184363,184765,184766,184767,184768,184839,184841,190456,198048,200453,204075,204743,204744,204747,204748,204750,204752,204754,204758,204759,204761,204766,204769,204774,204780,204787,204896,204898},mapCandidates={npc={},zone={}},questType="standard"},
[49593] = {id=49593,name="REUSE ME",level=10,requiredLevel=10,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,storyline={49593},description="I once viisted Kul Tiras. Da humans dere not be too friendly to us Zandalari. However one of da shrines be dere, in Tiragarde Sound. Dat place have da most humans of all dat land. Ya need to be watchin' your back out dere, . I'll mark da location of it on your map for ya. And let's be hoping dem humans didn't mess wit it. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(49593)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(49593))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Travel to the location marked on your map and investigate the shrine in Tirigarde Sound. Do what you can to repair the shrine, should the need arise.",rewardGold=996000,rewardXP=200,rewardItems={71083,128823,133803,133804,142342,181368,181377,181585,181605,181610,181611,181703,181704,181745,184294,184362,184363,184765,184766,184767,184768,184839,184841,190456,198048,200453,204075,204743,204744,204747,204748,204750,204752,204754,204758,204759,204761,204766,204769,204774,204780,204787,204896,204898},mapCandidates={npc={},zone={}},questType="standard"},
[49594] = {id=49594,name="REUSE ME",level=10,requiredLevel=10,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,storyline={49594},description="Da next shrine be a in a place dey call Drustvar. From what I be hearin', dat place is full of witches. Dey use deir magics to bring tings ta life. But lookin at da map and where I tink dis shrine be, ya may not be needing to run into any of dem. It's pretty close ta da Smuggler's Cove. I'd make ya way dere and den find da shrine. I'll mark ya map for ya where I tink it is. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(49594)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(49594))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Travel to the location marked on your map and investigate the shrine in Drustvar. Do what you can to repair the shrine, should the need arise.",rewardGold=996000,rewardXP=200,rewardItems={71083,128823,133803,133804,142342,181368,181377,181585,181605,181610,181611,181703,181704,181745,184294,184362,184363,184765,184766,184767,184768,184839,184841,190456,198048,200453,204075,204743,204744,204747,204748,204750,204752,204754,204758,204759,204761,204766,204769,204774,204780,204787,204896,204898},mapCandidates={npc={},zone={}},questType="standard"},
[49595] = {id=49595,name="REUSE ME",level=10,requiredLevel=10,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,storyline={49595},description="Da last shrine in Kul Tiras be in a green place dey call Stormsong Valley. Da humans dere probably won't be givin' ya too much trouble. But da shrine be pretty dead center in da land, so ya probably gonna have ta do some travelin'. I'll mark it on ya map for ya. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(49595)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(49595))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Travel to the location marked on your map and investigate the shrine in Stormsong Valley. Do what you can to repair the shrine, should the need arise.",rewardGold=996000,rewardXP=200,rewardItems={71083,128823,133803,133804,142342,181368,181377,181585,181605,181610,181611,181703,181704,181745,184294,184362,184363,184765,184766,184767,184768,184839,184841,190456,198048,200453,204075,204743,204744,204747,204748,204750,204752,204754,204758,204759,204761,204766,204769,204774,204780,204787,204896,204898},mapCandidates={npc={},zone={}},questType="standard"},
[49596] = {id=49596,name="REUSE ME",level=50,requiredLevel=50,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,storyline={49596},description="As you peer at the rock altar in front of you, you can't help but revel at the construction of it. Seamlessly constructed with azure jewels placed just so in a radial pattern, collapsing towards a single point. A single, empty point. An absence you assume to be a mistake. Quickly surveying the area for something that might fit there, you find nothing. However, someone who had not been there before has shown up. Perhaps he might know the whereabouts of the shrine's missing piece. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(49596)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(49596))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Speak with \"Slippery Salton\" and learn what you can about the missing centerpiece.",rewardGold=996000,rewardXP=200,rewardItems={71083,128823,133803,133804,142342,181368,181377,181585,181605,181610,181611,181703,181704,181745,184294,184362,184363,184765,184766,184767,184768,184839,184841,190456,198048,200453,204075,204743,204744,204747,204748,204750,204752,204754,204758,204759,204761,204766,204769,204774,204780,204787,204896,204898},mapCandidates={npc={},zone={}},questType="dungeon"},
[49597] = {id=49597,name="REUSE ME",level=50,requiredLevel=50,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49597},rewardGold=996000,rewardXP=200,rewardItems={71083,128823,133803,133804,142342,155830,181368,181377,181585,181605,181610,181611,181703,181704,181745,184294,184362,184363,184765,184766,184767,184768,184839,184841,190456,198048,200453,204075,204743,204744,204747,204748,204750,204752,204754,204758,204759,204761,204766,204769,204774,204780,204787,204896,204898},mapCandidates={npc={},zone={8721}},questType="standard"},
[49598] = {id=49598,name="REUSE ME",level=50,requiredLevel=50,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,storyline={49598},description="Upon your investigation you discover that the shrine has several locations where jewels appeared to have been located, but no longer exist. Checking your notes, the earthen mentions having prospected the jewels from a nearby mountain to the north. Perhaps you can prospect the earth in that area to find more of those jewels. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(49598)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(49598))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Go to (NYI POI) and gather $1oa Jewel Shards.",rewardGold=996000,rewardXP=200,rewardItems={71083,128823,133803,133804,142342,181368,181377,181585,181605,181610,181611,181703,181704,181745,184294,184362,184363,184765,184766,184767,184768,184839,184841,190456,198048,200453,204075,204743,204744,204747,204748,204750,204752,204754,204758,204759,204761,204766,204769,204774,204780,204787,204896,204898},mapCandidates={npc={},zone={}},questType="standard"},
[49599] = {id=49599,name="The Missing Chapter",level=10,requiredLevel=10,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={49581,49582,49583,49585,49586,49587,49588,49589,49599,55592,55594,55596},description="< Seshuli puts down the journal and looks back up at you.> While trying to figure out where de shrines reside, I came across an entry dat mentioned him exploring an area dat sounds very similar to Dustwallow Marsh. It could be a long shot, given when dis earthen roamed Azeroth, but maybe if you retrace his final steps, you may find something. I'll mark his last location for you on your map.",objectivesText="Travel to the location marked on your map and see what you can find. Progress: Who knows what you'll find out dere. Hopefully something...",rewardGold=514800,rewardXP=1770,rewardItems={155668,155669},starts={{npcID=122695}},ends={{npcID=122695}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={55594,55596},questLines={{id=888,name="8.1.5 Jewelcrafting - Horde",orderIndex=11,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[49613] = {id=49613,name="Silvermoon City",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=7637,mapID=680,storyline={49354,49613,49614,49973},series={49354,49614},description="The nightborne have been isolated from the world for thousands of years. Now that they have reemerged, it is up to us to guide them along the right path. Regent Lord Theron has extended an invitation to the nightborne to meet with us in Silvermoon. Come, <name>, let us travel to Silvermoon with Thalyssra.",objectivesText="Meet with Lady Liadrin in Silvermoon City.",rewardGold=303800,rewardXP=5465,rewardItems={6948},starts={{npcID=131478}},ends={{npcID=130133}},mapCandidates={npc={110,680},zone={7637}},questType="standard",sourceQuests={49973},questLines={{id=531,name="Allies of the Horde: Nightborne",orderIndex=1,flags=0}},db2PoiMapID=530,db2PoiUiMapID=110},
[49614] = {id=49614,name="The Nightborne",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=1637,mapID=110,storyline={49354,49613,49614,49973},series={49354,49613},description="The Warchief will be pleased with our success. Thalyssra and her nightborne will prove strong allies, I am sure.",objectivesText="Return to Ji Firepaw in Orgrimmar to hear the end of this tale.",rewardGold=312800,rewardXP=5465,rewardItems={156487},starts={{npcID=130133}},ends={{npcID=126065},{npcID=133523}},mapCandidates={npc={85,110},zone={1637}},questType="standard",sourceQuests={49354},questLines={{id=531,name="Allies of the Horde: Nightborne",orderIndex=3,flags=0}},db2PoiMapID=1,db2PoiUiMapID=85},
[49615] = {id=49615,name="Trust of a King",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=9598,mapID=1165,description="Well, now dat you are settled in, you had best go speak with my father. You can find him up upon de throne, his advisors close at hand, pouring poison in his ear, no doubt. De lift behind you can take you to de Golden Throne above us.",rewardGold=25740,rewardXP=175,starts={{npcID=133050}},ends={{npcID=120740}},mapCandidates={npc={1165},zone={9598}},questType="standard",sourceQuests={47514},questLines={{id=334,name="Of Prophecies and Prophets",orderIndex=0,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=6,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[49661] = {id=49661,name="Locally Sourced Eggs",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={49661},description="There is nothing in the world greater than food made from the best, freshest ingredients! My good friend I am on a hunt. A hunt for the perfect eggs! I have heard tale of eel eggs. A delicate texture, a slight undersea saltiness... such a unique flavor profile! I must have them! The eels here lay their eggs on the land before returning to the sea. Please, gather these eggs for me so that I may create only the most elegant of omelets!",objectivesText="Collect 10 Coilscale Eggs from Coilscale Nests.",rewardGold=257400,rewardXP=1415,rewardItems={155660},mapCandidates={npc={},zone={8567}},questType="standard"},
[49662] = {id=49662,name="The Missing Key",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},series={49664,50745},description="Korthek has grown spiteful and arrogant over the years, but I realize now that he has grown mad as well. Mythrax will kill all of us if he is released. For too long, I've held out hope that I could convince Korthek peacefully to abandon his heresy. I was wrong. All of Zandalar is at risk while Korthek and his allies hold even one key to Mythrax's prison. Meet me outside his fortress in the north. We will confront my old friend \"Emperor\" Korthek and end this together.",objectivesText="Meet Vorrik at Bwoljin's Fall.",rewardGold=128700,rewardXP=2060,starts={{npcID=128694}},ends={{npcID=137970}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={49340},questLines={{id=610,name="Storming the Spire",orderIndex=0,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=47,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49663] = {id=49663,name="False Prophecies",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8670,mapID=1165,description="Now dat dis nuisance is out of de way, I can return my focus to de city. Zuldazar has languished while I was away. You should return to Rastakhan. Let de king know dat his will has been carried out and dat dis false prophet is no more. You might think to share Vol'jamba's prophecy with him, if you feel it worth his notice. I cannot say it will change anything at all.",rewardGold=25740,rewardXP=175,rewardCurrencies={{id=1553,amount=150}},starts={{npcID=129907}},ends={{npcID=120740}},mapCandidates={npc={862,1165},zone={8670}},questType="standard",sourceQuests={49905},questLines={{id=5389,name="Unrest in Zuldazar",orderIndex=17,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[49664] = {id=49664,name="Allies in Anarchy",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},series={49662,50745},description="Even after all these years, I can feel the ancient power of Sethraliss in this place. My loa endures. Our task ahead is great and I will need a clear, focused mind to accomplish it. Allow me a few moments to meditate here, like I did in ages past. In the meantime, you should help the vulpera stir up trouble however you can. They seem to know you, and a large enough disturbance will distract the Faithless from our mission. Meet me back here when you're done and we'll proceed together.",objectivesText="Speak with Nisha .",rewardGold=25740,rewardXP=515,starts={{npcID=135172}},ends={{npcID=135090}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50745},questLines={{id=610,name="Storming the Spire",orderIndex=2,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=49,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49665] = {id=49665,name="Ready to Riot",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="Do you remember how we met, $p? You were trapped in a Faithless cage, just like the ones in the crater below. Together, we slaughtered Faithless and earned your freedom in blood. The vulpera trapped in shackles below can do the same. They just need to be given the chance. Steal Faithless weapons and give them to the vulpera slaves below. They'll rise up and help you fight the Faithless. We're going to start a revolt right under their arrogant noses.",objectivesText="Free and arm 8 Vulpera Slaves in cages.",rewardGold=257400,rewardXP=4115,rewardItems={159470},rewardCurrencies={{id=1560,amount=50}},starts={{npcID=135090}},ends={{npcID=135090}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={49664},questLines={{id=610,name="Storming the Spire",orderIndex=3,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=50,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49666] = {id=49666,name="Make Them Fear Us",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="I carry this banner into every battle because I want the Faithless to fear it. To fear my people. If I die in the battlefield, surrounded by Faithless, I will die happy. On that day, I will not need a burial or prayers. But I will need someone to pick up my banner and carry it into the next battle. If you are of the same mind, plant these banners into the corpse of every Faithless you slay. Let the survivors know who's coming for them.",objectivesText="Plant 12 Vulpera Banners into dead Faithless.",rewardGold=257400,rewardXP=4115,rewardItems={158884},starts={{npcID=135090}},ends={{npcID=135090}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={49664},questLines={{id=610,name="Storming the Spire",orderIndex=4,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=51,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49667] = {id=49667,name="The Little Ones",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48329,49002,49437,49667,49668,49669,50749,50757},description="Just when I thought the Faithless couldn't get any worse, I find out that they're keeping vulpera children trapped down in that crater! The other vulpera we rescued told me that a big sethrak, Appraiser Versik , is inspecting them on the central platform to determine what he can sell them for. Selling vulpera kids! Oooh, those Faithless make me so angry! Please, $p. I'm no fighter. I can't rescue those kids. But if you bring them up here to me, I promise I'll get them out of here safely.",objectivesText="Kill Appraiser Versik and lead the vulpera kids back to Meerah .",rewardGold=514800,rewardXP=5145,rewardItems={71083,159992,159993,159994,159995,160017,160018,160019,160020},rewardChoices={160017,160018,160019,160020,159992,159993,159994,159995},starts={{npcID=135355}},ends={{npcID=135355}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50745},questLines={{id=5428,name="Sethrak Fortress",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49668] = {id=49668,name="Light Up the Gulch",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48329,49002,49437,49667,49668,49669,50749,50757},description="Don't mistake my caution for hesitance, $p. I will defend the vulpera with my dying breath... I'd just prefer to avoid taking that breath today. While Nisha rushes to the front line, I work behind them to ensure our success. Meet me at the Faithless beast pens if you'd like to help. Oh, and take this torch. You'll be going through their marketplace, where they auction off slaves. Starting a few well-placed and metaphorically poignant fires along your route will make things easier for all of us.",objectivesText="Torch the slave auction sites in Slithering Gulch.",rewardGold=257400,rewardXP=4115,rewardItems={158896},starts={{npcID=137981}},ends={{npcID=135099}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={49665,49666},questLines={{id=5428,name="Sethrak Fortress",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49669] = {id=49669,name="Unleash the Beasts",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48329,49002,49437,49667,49668,49669,50749,50757},description="The Faithless are arrogant hoarders, capturing people and beasts that can never be truly tamed. All to fuel their endless lust for war. I've even seen their slavers dragging blood trolls and other dark monsters from the swamps of Nazmir. I heard terrible noises coming out of a cave while I was scouting the feeding pits up ahead. Whatever monsters they are hiding in there, find a way to free them and let them exact revenge on the Faithless.",objectivesText="Kill Tamer Traskniss to release the crawgs.",rewardGold=514800,rewardXP=5145,rewardItems={161182},rewardChoices={161182},starts={{npcID=135099}},ends={{npcID=135099}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={49668},questLines={{id=5428,name="Sethrak Fortress",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49675] = {id=49675,name="Tracking Quest",expansion=7,mapID=863,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Blood Corruption Cleansed"},{orderIndex=1,type=0,amount=34,objectID=123039,text="Ancient Spirits slain"}},worldTaskTitle="Tracking Quest"},
[49676] = {id=49676,name="Dressed for Battle",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="Kiro's the leader of my caravan. He's always been far too passive. I warned him we needed to make a preemptive strike against the sethrak, but he insisted that we keep our heads down and continue to quietly do business. Look where that got us. Our caravan was completely unprepared for their attack. Now I'm ready to fight for what's ours, but I'm not exactly dressed for battle. Help me scavenge some suitable equipment here among our enemies. We will use their own tools against them.",objectivesText="Help Nisha find a war banner, a helmet, and explosives . Progress: Killing an enemy with their own sword is an even bigger insult, no?",rewardGold=257400,rewardXP=4115,rewardItems={155413,155414,155415,155416,159980,159981,159982,159983},rewardChoices={155413,155414,155415,155416,159980,159981,159982,159983},starts={{npcID=130455}},ends={{npcID=130455}},mapCandidates={npc={864},zone={8501}},questTurnInID=130455,questType="standard",sourceQuests={51357},questLines={{id=605,name="Unlikely Allies",orderIndex=4,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=5,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49677] = {id=49677,name="Plans for Attack",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="Before we were attacked, I had a plan to take the fight to the sethrak. It was devised with flawless intel. I know, because I gathered the information myself. I surveyed their entire compound and created a map based on my findings. My plan relies on that map, but it's now in the hands of Fangcaller Sraka, the brute who's leading this assault on my home. Help me kill her so I can take back what's mine!",objectivesText="Recover Nisha's Attack Plans from Fangcaller Sraka. Progress: My plan for attack is both detailed and dangerous.",rewardGold=514800,rewardXP=5145,rewardItems={35232,158651},starts={{npcID=130474}},mapCandidates={npc={},zone={8501}},questGiverID=130474,questType="standard",sourceQuests={49676},questLines={{id=605,name="Unlikely Allies",orderIndex=6,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=7,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49678] = {id=49678,name="I Spy a Spire",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49678},description="It is good you have come. Dol'watha be under attack by these snake-men. Soon as they arrived they started pulling these weird spire-things out de ground. I seen a bunch of snake-mons with feathers in their caps getting zapped by them, but they not be dying. If it not be bad for them, that means it's good for them. And that be bad for us. Destroy those spires. Hopefully whatever boon they be getting will go away and they will be easier to kill.",objectivesText="Destroy 4 Sethrak Spires .",rewardGold=257400,rewardXP=1415,starts={{npcID=130450}},ends={{npcID=130450}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49940}},
[49679] = {id=49679,name="The Sethrak Incursion",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49679},description="Dol'watha be a small village. Got a few farms, some beasts, and a decent view of a swamp. Loa know we not be ready for this... De snake-men popped out of de ground by de hundreds. Slaughtered my beasts, my family, my friends. One minute de earth rumbling, de next we be running for our lives. I heard about snake-men from de deserts of Vol'dun but I never believed I would see them in my life... Help us fight back. Kill as many of them as you can. Dol'watha won't be beaten that easily!",objectivesText="Slay 12 sethrak in Sandscar Breach.",rewardGold=257400,rewardXP=1415,starts={{npcID=131354}},ends={{npcID=131354}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49940}},
[49680] = {id=49680,name="Skycaller Soltok",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49680},description="As if snake-men with swords not be bad enough, they brought a powerful skycaller along. I hear skycallers can tempt great storms into being. They be to blame for de spires and lightning flying everywhere. There be one who wear a bigger feather than most, likely de leader. Calls herself Soltok or something equally hissy. Don't care. Kill her.",objectivesText="Slay Skycaller Soltok .",rewardGold=514800,rewardXP=1770,rewardItems={155309,155311},rewardChoices={155311,155309},starts={{npcID=130450}},ends={{npcID=130450}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49940}},
[49681] = {id=49681,name="Lil' Tika",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49681},description="<The tiny armored raptor scratches pitifully at the cage's wooden bars. As you approach, the miniscule reptile wiggles frantically and issues a piercing screech for help! Perhaps you can open the cage and let it free.>",objectivesText="Rescue Lil' Tika . Progress: My poor beasts...",rewardGold=257400,rewardXP=1415,rewardItems={161016,163036,163502},starts={{npcID=130468}},ends={{npcID=131354}},mapCandidates={npc={862},zone={8499}},questType="standard"},
[49694] = {id=49694,name="Turn to Drust",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"inscription"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=896,storyline={40537,49694,49876},series={40537},description="There are blood scribe masters all over the place who'll teach you what you need to know. The first master I'd recommend seeking out is Kronah . She's a bit... eccentric to say the least. One of the few tortollan who've experienced a thing or two. She's the one who taught me the blood contract I know how to invoke! She likes to hang out at the Smuggler's Cove on the western coast of Drustvar. Oh, and could you say hi for me when you see her?!",objectivesText="Seek out Kronah at the Smuggler's Cove in Drustvar.",rewardGold=1745,rewardXP=175,starts={{npcID=130399}},ends={{npcID=131386}},mapCandidates={npc={896},zone={8568}},questGiverID=130399,questType="standard",sourceQuests={40537},questLines={{id=901,name="8.1.5 Inscription - Alliance",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[49695] = {id=49695,name="Tracking Quest",expansion=7,mapID=863,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Blood Corruption Cleansed"},{orderIndex=1,type=0,amount=34,objectID=123039,text="Ancient Spirits slain"}},worldTaskTitle="Tracking Quest"},
[49698] = {id=49698,name="The Lightforged",level=40,requiredLevel=40,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=1519,mapID=84,storyline={49266,49698,50071},series={49266},description="Do you wish to hear how the Lightforged draenei joined the Alliance? It might be one of my favorite stories. Most likely since it involves seeing our beautiful world from space! It all began when High Exarch Turalyon invited members of the Alliance onto the Vindicaar...",objectivesText="Travel to the Vindicaar. Progress: This ritual has never been witnessed by an outsider.",rewardGold=169800,rewardXP=5465,rewardItems={155656,156486},starts={{npcID=126319},{npcID=126332}},ends={{npcID=126319}},mapCandidates={npc={84},zone={1519}},questTurnInID=126319,questType="standard",sourceQuests={50239},questLines={{id=533,name="Allies of the Alliance: Lightforged Draenei",orderIndex=0,flags=0}},db2PoiMapID=1860,db2PoiUiMapID=940},
[49703] = {id=49703,name="House Stormsong",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,series={49725},description="I have little information to offer, I'm afraid. I've scarcely left Brennadam as of late. What they said is true. Our militia now enter town only to collect rations rather than guard traders or keep the quilboar at bay. They say they are under orders, but those orders would only come from my brothers at the Shrine. We take oaths to serve our people... it simply does not add up. Brother Addington is nearby at Mariner's Strand. Perhaps he knows more than I.",rewardGold=25740,rewardXP=515,starts={{npcID=130576}},ends={{npcID=130714}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49725},questLines={{id=442,name="A House in Peril",orderIndex=7,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=8,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[49704] = {id=49704,name="Haywire Harvesters",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="See the golems down there? Farmers use their sharp claws to reap the harvest, but these are cutting timber... Why would they need them here when they have so many laborers on hand? I think the militia is using them to intimidate their own people! See if you can get ahold of an intact mainspring from one. I've helped repair a few back in Boralus. I should be able to figure out who is messing with their innards.",rewardGold=257400,rewardXP=4115,starts={{npcID=130715}},ends={{npcID=130715}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49703},questLines={{id=442,name="A House in Peril",orderIndex=8,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=9,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[49705] = {id=49705,name="Unnecessary Duress",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="Lord Stormsong has never taken kindly to dissent, but this is madness. These laborers are being worked to death! Addington was a good man. We cannot stand for such cruelty. Take this vial and apply it to the laborers. It contains blessed seawater that will rejuvenate their strength. Avoid engaging what troops you can. They are merely following orders. More death will only worsen matters.",rewardGold=257400,rewardXP=4115,rewardChoices={155175,155173,155176,155174,155170,155172,155171,155169},starts={{npcID=130714}},ends={{npcID=130714}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49703},questLines={{id=442,name="A House in Peril",orderIndex=9,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=10,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[49706] = {id=49706,name="Proclamation Investigation",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="My lord seldom leaves our holdings along the northern coast, and visitors are expressly forbidden. For most, tidesages like myself are their only connection to the house proper. Lord Stormsong usually delivers orders through proclamations posted throughout the valley. None have reached Brennadam, but if there are any posted here we may be able to find some answers.",rewardGold=257400,rewardXP=4115,starts={{npcID=130714}},ends={{npcID=130714}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49703},questLines={{id=442,name="A House in Peril",orderIndex=10,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=11,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[49710] = {id=49710,name="An Offering of Eggs",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={49393,49394,49395,49412,49417,49418,49419,49431,49433,49435,49439,49710,49719,49735},description="Our work isn't only to capture and tame gryphons, it's also to preserve them. Rescue any eggs remaining in nearby abandoned nests. Set them in one of the new nests we've built for the displaced gryphons. I am sure one of the gryphon females will adopt them.",objectivesText="Collect 4 Spotted Gryphon Eggs . Progress: You find a safe nest.",rewardGold=257400,rewardXP=1415,rewardItems={155828},starts={{npcID=129170}},ends={{npcID=129170}},mapCandidates={npc={895},zone={8567}},questTurnInID=129170,questType="standard",sourceQuests={49394},questLines={{id=5435,name="A Mountain of Ice",orderIndex=7,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49715] = {id=49715,name="Trouble at Greystone Keep",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=1161,storyline={49715},series={49733},description="A friend of mine, a fellow military courier, had a job at Greystone Keep. The fort lies just outside of Boralus, so I would've expected him to be back by now. I have another job lined up, so could you go check out the fort for me? I'm probably just being paranoid.",objectivesText="Speak with Tallis Skyheart .",rewardGold=257400,rewardXP=1415,starts={{npcID=130377}},ends={{npcID=130375}},mapCandidates={npc={895,1161},zone={8568}},questType="standard",nextQuests={49733,51226}},
[49716] = {id=49716,name="A Lesson on Trust",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={49716,49720,49733,49734,50249,51226},description="The men in the fort were once under my command, and so, they are now my responsibility. Each of them should have a badge we use for identifying individuals under certain circumstances. I would ask you to bring back a number of these as proof of thinning their ranks. These men are no longer soldiers of Boralus, and as such, no longer deserve to carry the Proudmoore anchor.",objectivesText="Retrieve 8 Marine Identification Badges . Progress: Did you bring me those badges?",rewardGold=257400,rewardXP=1415,rewardItems={156599},starts={{npcID=130375}},ends={{npcID=130375}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49733,51226},questLines={{id=5431,name="Greystone Keep",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49719] = {id=49719,name="Getting Paid",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={49393,49394,49395,49412,49417,49418,49419,49431,49433,49435,49439,49710,49719,49735},description="Now that we got our mitts good and bloody, I think it's time we head back to camp. I'll run ahead, so you can finish up whatever business you got. Just remember to meet Tagart for your pay.",objectivesText="Meet with Tagart at the Roughneck Camp.",rewardGold=257400,rewardXP=1415,rewardCurrencies={{id=1553,amount=75}},starts={{npcID=129655}},ends={{npcID=129003}},mapCandidates={npc={895},zone={8567}},questGiverID=129655,questType="standard",sourceQuests={49433,49439},questLines={{id=5435,name="A Mountain of Ice",orderIndex=13,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49720] = {id=49720,name="Free Bird",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={49716,49720,49733,49734,50249,51226},description="Skyheart invited me here to teach some of his city boys how to train the local sea hawks. Some of my students went and sided with the mutiny force. Seems these soft marines have forgotten what the consequence is for betraying a Drustvar soldier. Worse yet, they've locked up quite a few of the younger birds we were training. I've got my hands full with these hawks, so if you could free a few of the young'uns while you're in the fort, I'd appreciate it.",objectivesText="Free 5 Juvenile Seahawks. Progress: Any luck? Hopefully they didn't nip you too much.",rewardGold=202200,rewardXP=1415,starts={{npcID=132720}},ends={{npcID=132720}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49733,51226},questLines={{id=5431,name="Greystone Keep",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49725] = {id=49725,name="A Risky Ploy",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,series={49703},description="Things are worse than we thought. These people are about to tear Brennadam apart! We'll never get a chance to talk to Brother Pike in this mess. I have an idea, but if it doesn't work, well... I hope you have your running boots on. Trust me?",rewardGold=154900,rewardXP=2060,starts={{npcID=129999}},ends={{npcID=130576}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51401},questLines={{id=442,name="A House in Peril",orderIndex=6,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=7,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[49730] = {id=49730,name="WANTED: Thundersnout",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49730},description="Thundersnout is the largest of the boars in the valley. She is wreaking havoc on the nearby farms and their crops. Mayor Roz of Brennadam has issued a bounty for proof of her demise. Thundersnout's location is near Briarback kraul, so be on the look out for quilboar!",objectivesText="Deliver Thundersnout's Snout to Mayor Roz . Progress: Yes?",rewardGold=772200,rewardXP=6175,rewardItems={158300},rewardCurrencies={{id=1553,amount=115}},ends={{npcID=130694},{npcID=134752}},startObjects={{objectID=287958,mapID=942,x=0.306,y=0.681}},coords={mapID=942,source="quest_giver",x=0.576,y=0.665},mapCandidates={npc={942},zone={9042}},questType="group"},
[49731] = {id=49731,name="Fond Farewells",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={49731},description="Dis is where we part ways, <name>. I'm going to take de name Akunda, and start a new life here. Rakera saved my life, and I'm going to make sure to live a life dat was worth saving. If you find yourself back in de city, could you deliver dis note for me? I trust you not to open it, though I doubt you could read my scrawls anyway.",objectivesText="Deliver Jorak 's Note to B'wizati in Zuldazar. Progress: What is dis?",rewardGold=257400,rewardXP=2060,rewardItems={153016},starts={{npcID=128339}},ends={{npcID=127664}},mapCandidates={npc={864,1165},zone={8501}},questType="standard",sourceQuests={48996}},
[49733] = {id=49733,name="Patching Up the Rear",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={49716,49720,49733,49734,50249,51226},series={49715},description="Most of my men were injured when we were escaping the fort, those that weren't were injured holding this position. <Tallis hands you a stack of stained cloth.> All of our better supplies are behind those walls, so we've been forced to make do with what we have. Everything that's not being worn on a soldier's person as we speak has been shredded for use as bandages. We don't have the staffing to take care of everyone. Head out and replace the worst of our injured's bandages.",objectivesText="Bandage 5 injured marines. Progress: My gratitude, that should help alleviate some of the soldiers' pain.",rewardGold=257400,rewardXP=1415,starts={{npcID=130375}},ends={{npcID=130375}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49715},questLines={{id=5431,name="Greystone Keep",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49734] = {id=49734,name="Targeting a Turncoat",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={49716,49720,49733,49734,50249,51226},description="The instigator of this mutiny is a man named Fernn. He has always shown discontent with House Proudmoore and his position here. But to betray the men he works with? That seems beyond even my expectations of him. Take him out, and show this mutiny the mistake of crossing truly loyal marines.",objectivesText="Slay Fernn the Turncoat .",rewardGold=404400,rewardXP=1770,rewardItems={155090,158266,158330},rewardChoices={155090,158266,158330},starts={{npcID=130375}},ends={{npcID=130375}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49733,51226},questLines={{id=5431,name="Greystone Keep",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49735] = {id=49735,name="Protect the Nests",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={49393,49394,49395,49412,49417,49418,49419,49431,49433,49435,49439,49710,49719,49735},description="Now that Tagart is done with your hazing... I mean... trials, you can start helping us with some of the work around here. Some of the nearby gryphon nests have been overrun with saurolisk. I fear that the gryphons will make new roosts elsewhere if we don't clear them out. Head up the road towards the waterfall and take out those saurolisks. Report to Shawn when you're done. He's posted as a lookout there.",objectivesText="Kill 7 Hungry Dewscale . Progress: Get bit?",rewardGold=257400,rewardXP=1415,starts={{npcID=129170}},ends={{npcID=129578}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49394},questLines={{id=5435,name="A Mountain of Ice",orderIndex=6,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49736] = {id=49736,name="For Kul Tiras!",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={49405,49736,49737,49738,49740,49869,50110,52431,52750},series={49738},description="Listen, I'll be frank with you; we're not at full strength here. Many of our soldiers recently left for Boralus on new orders. It's like they knew just when to hit us... But we're going to hit back! Every able-bodied man and woman in town has stepped up to mount a defense. Take this battle standard and remind them what they're fighting for!",objectivesText="Use the Proudmoore Battle Standard to inspire 15 Vigil Hill Marines or Militia.",rewardGold=257400,rewardXP=1415,rewardItems={141605,155085,156520,158234,158235,158236,158237,164762,252403},rewardChoices={155085,158235,158237,158236,158234},starts={{npcID=131048}},ends={{npcID=131048}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49738},questLines={{id=588,name="Defenders of Daelin's Gate",orderIndex=5,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=35,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49737] = {id=49737,name="Air Raid",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={49405,49736,49737,49738,49740,49869,50110,52431,52750},description="Those pirates have air support! They're torching our farms and splitting our attention away from the front lines. Take 'em outta the sky!",objectivesText="Slay 6 Irontide Skyriders .",rewardGold=309800,rewardXP=1415,rewardItems={156520},starts={{npcID=131048}},ends={{npcID=131048}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49869},questLines={{id=588,name="Defenders of Daelin's Gate",orderIndex=6,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=33,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49738] = {id=49738,name="Hands Off My Booty!",level=10,requiredLevel=10,faction="alliance",sharable=false,expansion=7,zoneID=8567,mapID=895,series={49736},description="We are dealing with lawless, no-account thugs. As soon as they gained ground, they started looting! Looting right in the middle of a battle! Well I, for one, am not giving up our booty that easily. Get up to the top of Vigil Hill and man the main cannon. Rain hellfire down on those blaggards! Dismissed!",rewardGold=309800,rewardXP=1415,rewardChoices={158268,158271,158270,158269,155092},starts={{npcID=131048}},ends={{npcID=131048}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49737,52750},questLines={{id=588,name="Defenders of Daelin's Gate",orderIndex=4,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=34,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}}},
[49739] = {id=49739,name="Enemies at the Gate",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={49739},objectivesText="Defend Daelin's Gate",rewardGold=455280,rewardXP=1415,rewardItems={156570},starts={{npcID=130697}},ends={{npcID=130697}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49736},db2Objectives={{text="Defend Daelin's Gate",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Enemies at the Gate",db2PoiMapID=1643,db2PoiUiMapID=895},
[49740] = {id=49740,name="Cease Fire!",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={49405,49736,49737,49738,49740,49869,50110,52431,52750},description="The enemy has turned our forward cannons around on us. Scuttle that equipment to stop the bombardments!",objectivesText="Destroy 4 Captured Cannons .",rewardGold=309800,rewardXP=1415,rewardItems={156520},rewardCurrencies={{id=1560,amount=50}},starts={{npcID=131048}},ends={{npcID=131048}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49738},questLines={{id=588,name="Defenders of Daelin's Gate",orderIndex=7,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=36,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49741] = {id=49741,name="Righteous Retribution",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={46727,46728,46729,47098,47099,47181,47186,47189,47485,47486,47487,47488,47489,47960,48419,48505,48539,48558,48773,49239,49398,49399,49401,49404,49405,49736,49737,49738,49740,49741,49869,50110,50531,50573,50787,50788,50789,50790,50795,50972,51341,52128,52431,52750,52787,53041,59641},series={50110,50787,50788,50789,50790,50795},description="Cyrus taught me how to deal with thugs, bullies, and scum like pirates. When they hit us, we hit back twice as hard. < Taelia 's hand finds the haft of her hammer and grips it tight.> It's time to hit back.",objectivesText="Help Taelia destroy the pirate ships in Daelin's Gate.",rewardGold=365520,rewardXP=1770,rewardItems={162522},starts={{npcID=142393}},ends={{npcID=142393}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49738,52787},questLines={{id=5372,name="Trouble in Tiragarde Sound",orderIndex=38,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49744] = {id=49744,name="Bombs, Away",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49744,49745,49746,49755},description="By the sea's foamy beard, what a blast! They've brought goblins, and if there's one thing I know about goblins it's that they like to blow things up. I saw a few of them carrying large bombs, and I presume that they are going to blow up the town. I would like to keep the town, so how about you head out there and steal as many of those explosives as you can find? After that, let's blow up their demolishers and stop this infernal bombardment!",objectivesText="Retrieve 8 Horde Explosives and use them against the Demolishers . Progress: Don't forget to check inside the buildings too!",rewardGold=257400,rewardXP=4115,rewardItems={33226,57434,57435,57436,57437,131881,133510,155824,155877,156577,156578,156648,157849,157850,160558,160561},starts={{npcID=130190}},ends={{npcID=130190}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51552},questLines={{id=582,name="Reclaiming Brennadam",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[49745] = {id=49745,name="You Have Their Orders",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49744,49745,49746,49755},description="The Horde is an army, make no mistake. And armies need orders. Someone must be giving orders here. They know the plan, and I want to know the plan too. Look for the people who seem to be in charge and see if you can uncover any intelligence so we know what to do next.",objectivesText="Find the Warchief's Orders . Progress: You find those orders?",rewardGold=514800,rewardXP=5145,rewardItems={133510,155824,155877,156577,156578,156648,157849,157850,160558,160561},starts={{npcID=130694}},ends={{npcID=130694}},mapCandidates={npc={942},zone={9042}},questType="standard",questLines={{id=582,name="Reclaiming Brennadam",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[49746] = {id=49746,name="Dousing the Flames",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49744,49745,49746,49755},description="The Horde have set fire to my town, <class>. I will make them pay for this. Stormsong Valley is the breadbasket of Kul Tiras, and our people need to be fed. The first thing we must do is damage control. Grab some buckets and help put those fires out!",objectivesText="Use the Water Bucket to put out 15 fires around the Ruins of Brennadam.",rewardGold=257400,rewardXP=4115,rewardItems={65281,65301,65320,65337,133510,155824,155877,156577,156578,156648,157849,157850,160558,160561},starts={{npcID=130694}},ends={{npcID=130694}},mapCandidates={npc={942},zone={9042}},questType="standard",questLines={{id=582,name="Reclaiming Brennadam",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[49754] = {id=49754,name="Not \"Only Zul\"",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49754},series={49758,49775},description="Our enemies here either follow de name of Zul, or dey want to use him to take Zandalar. He has the ego to allow either. Dey claim only Zul can lead us. Dissuade dem.",objectivesText="Purge Zul's forces. Progress: Did ya leave any breathing?",rewardGold=257400,rewardXP=1415,starts={{npcID=130821}},ends={{npcID=130821}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49775}},
[49755] = {id=49755,name="Heavy Artillery",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49744,49745,49746,49755},description="Bad news, friend. They're bringing in serious firepower now. We've spotted a tank on the northern hill by the windmill. They can reach the other side of the town from there. We can't let them set it up. What do you say to giving them a taste of their own medicine? If you can take out their commander, you'd have a fancy new tank all to yourself. Imagine the mayhem you could unleash on their invasion!",objectivesText="Slay Captain Wormwood and commandeer the Experimental War Machine . Progress: If that cannon can reach Brennadam, it can reach those zeppelins!",rewardGold=514800,rewardXP=5145,rewardItems={133510,155824,155877,156577,156578,156648,157849,157850,158689,158690,158691,158692,160361,160364,160367,160370,160558,160561},rewardChoices={160361,160364,160367,160370,158690,158692,158691,158689},starts={{npcID=130694}},ends={{npcID=130694}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49744,49745,49746},questLines={{id=582,name="Reclaiming Brennadam",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[49756] = {id=49756,name="Dark Forces",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=1638,mapID=88,storyline={41764,41799,41800,41815,41840,41841,41882,41884,48066,48067,48079,48185,48190,48403,48433,48434,48435,49756},series={48067,48079},description="The Old Gods have inflicted one of their faceless ones upon Thunder Bluff. The fiend desecrates my people's city! We must fight together to rid this place of such filth. I believe that destroying this herald will drive our enemies from Mulgore. May our weapons strike true, <name>!",objectivesText="Defeat Qy'telek , Herald of Uul'gyneth Progress: This herald of the Old Gods must be stopped.",rewardGold=341600,rewardXP=5465,starts={{npcID=130773}},ends={{npcID=130773}},mapCandidates={npc={},zone={1638}},questGiverID=130773,questTurnInID=130773,questType="standard",sourceQuests={48067},questLines={{id=377,name="Allies of the Horde: Highmountain",orderIndex=17,flags=0}},db2PoiMapID=1,db2PoiUiMapID=88},
[49757] = {id=49757,name="Cat on a Hot Copper Roof",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={49757},description="My parents said we have to go, but I won't leave Scratchy behind! She's so gentle and precious and pure and kind and soft and cuddly! She must be so scared up there on the balcony! Please help her!",objectivesText="Climb the burning house and rescue Scratchy . Progress: We can't leave Scratchy here!",rewardGold=257400,rewardXP=1415,rewardItems={118244,155858,163036},starts={{npcID=131654}},ends={{npcID=131654}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49869}},
[49758] = {id=49758,name="Send the Signal!",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=1165,storyline={49758},series={49754,49775},description="My crew is not on board with de word of Zul. We saw too much of who he really is. Far out in de harbor, Zul's traitors have joined with de mogu to try to take my ships! If we lose de fleet and de harbor, we lose de city! We must let Zuldazar know we stand strong. We take back de ships. We drive de villains out. You must light de towers with loa-blessed flame. Dey will always see dat de Bay of Kings belongs to Zandalar!",objectivesText="Get to the ship.",rewardGold=22130,rewardXP=175,starts={{npcID=140590}},ends={{npcID=135576}},mapCandidates={npc={862,1165},zone={8670}},questType="standard",sourceQuests={49310}},
[49766] = {id=49766,name="Your Next Move",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={47332,49766,49767},description="We have some thoughts on the best way to win over the Zandalari. The princess is heading to Nazmir to take the fight to the blood trolls. Her voice carries much weight with the council and her father. General Jakra'zet detests the Horde. Removing his voice from the Zanchuli Council will greatly improve our chances here. We should also keep working on winning over the King here in Zuldazar . This city is vast and has many secrets. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(49766)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(49766))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Choose your next move in Zandalar.",rewardGold=30900,rewardXP=175,mapCandidates={npc={},zone={8499}},questType="standard",questLines={{id=793,name="Zandalar Zone Choice",orderIndex=1,flags=0}}},
[49767] = {id=49767,name="Your Next Move",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={47332,49766,49767},description="We have some thoughts on the best way to win over the Zandalari. The princess is heading to Nazmir to take the fight to the blood trolls. Her voice carries much weight with the council and her father. General Jakra'zet detests the Horde. Removing his voice from the Zanchuli Council will greatly improve our chances here. We should also keep working on winning over the King here in Zuldazar . This city is vast and has many secrets.",objectivesText="Choose your next move in Zandalar.",rewardGold=23870,rewardXP=175,mapCandidates={npc={},zone={8499}},questType="standard",questLines={{id=793,name="Zandalar Zone Choice",orderIndex=2,flags=0}}},
[49768] = {id=49768,name="Nesingwary's Trek",level=10,requiredLevel=10,faction="horde",categories={},flags={"loremaster"},sharable=true,expansion=7,zoneID=8499,mapID=1165,storyline={49768},series={47586,50466},description="De greatest hunter from your lands, de dwarf Nesingwary, has come to participate in de Great Hunt. If you are enough of a hunter to join him, den travel to de Nesingwary Trek along de northeastern region of Zuldazar .",objectivesText="Speak with Hemet Nesingwary at Nesingwary's Trek.",rewardGold=25740,rewardXP=175,starts={{npcID=130785}},ends={{npcID=123005}},mapCandidates={npc={862,1165},zone={8670}},questType="standard",sourceQuests={49663},nextQuests={47583,47584,50466}},
[49769] = {id=49769,name="Wreckage of the Cataclysm",level=10,requiredLevel=10,faction="none",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49769},series={48015},description="In recent years one of the greatest Zandalari loa temples mysteriously fell into the sea. It is a topic of some debate what caused this, and what treasures might have been lost in the catastrophe. My cousin Rokor was in charge of the salvaging efforts. Within the temple were many great items of knowledge and power. I am sure he will have need of the services of someone like yourself with strong arms and working knees.",objectivesText="Find Rokor at Scavenger's Strand.",rewardGold=25740,rewardXP=175,mapCandidates={npc={},zone={8499}},questType="standard"},
[49772] = {id=49772,name="For the Alliance",level=10,requiredLevel=10,faction="alliance",requiredRaces={30},categories={},flags={},sharable=true,expansion=7,zoneID=9359,mapID=84,storyline={49772,50313},description="The Army of the Light was founded with one purpose: to defeat the Legion. Though we have achieved that goal, a new duty lies before us. Azeroth is a world beset by enemies. Use your training to battle the darkness and uphold the ideals of the Alliance. Go to Stormwind. Seek the king's ambassador at the embassy, then set out to spread the Light's justice across the land. Pheta thones gamera, <name>.",objectivesText="Meet Ambassador Moorgard at the Stormwind Embassy.",rewardGold=34100,rewardXP=175,rewardItems={23002,23007,23015,23022,37500,42792,42805,42817,42830,65618,65625,65639,65642,66073,94219,108908,108909,108910,108912,108913,108914,108918,108919,116202,151557,157022,157756,157758,161329,165010,165872,166883,168615,168850,169764,174068,174507,204616,204617,204618,204619,223907,241215},starts={{npcID=130993}},ends={{npcID=133362}},mapCandidates={npc={84},zone={9359}},questGiverID=130993,questType="standard",questLines={{id=578,name="Allies of the Alliance",orderIndex=0,flags=0}},db2PoiUiMapID=84},
[49773] = {id=49773,name="For the Horde",level=10,requiredLevel=10,faction="horde",requiredRaces={28},categories={},flags={},sharable=true,expansion=7,zoneID=7731,mapID=85,storyline={49773,50319},description="A new age dawns upon Highmountain, <name>. After centuries apart, the bond with our kin from Kalimdor has been reforged. And in the fight to save our land, we found new friends among the people of the Horde. To show the strength we bring to our allies, brave tauren like you must heed the call of adventure. You have been invited to Orgrimmar. Meet with the ambassador at the warchief's embassy, then begin your journey across Azeroth. Earthmother be with you, <name>.",objectivesText="Meet Ambassador Blackguard at the Orgrimmar Embassy.",rewardGold=34100,rewardXP=175,rewardItems={23002,23007,23015,23022,29928,29930,29931,29934,29938,29941,29943,29945,37956,37964,37998,38006,38041,38048,38081,38102,38110,57509,57510,57511,57512,65680,65701,65719,65728,66073,94220,111535,111536,111537,111538,111539,111540,111541,111542,116202,118761,118762,118763,118764,118765,131486,131696,131697,151557,155662,157028,157757,157759,161328,165001,165871,166883,167169,168615,168850,169765,174069,174508,223907,241215},starts={{npcID=93826}},ends={{npcID=133407}},mapCandidates={npc={85},zone={7731}},questGiverID=93826,questType="standard",questLines={{id=580,name="Allies of the Horde",orderIndex=0,flags=0}},db2PoiMapID=1,db2PoiUiMapID=85},
[49774] = {id=49774,name="Won't Leaf Him to Die",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={49774,49776,49777,49778,49779,49780,49781},description="I may have done some wicked things in my past, but I won't leave dis guard to die. Zulajin has taken a nasty bite outta Zaluto... and has also infected him with some weird voodoo. But don't worry, because today is our lucky day. I have a plan to cure him. Dere are sweetleaf bushes nearby! De leaves of dis bush are known for their healing properties. You get me some, and I will be able to save dis Zaluto. It's de only chance we have!",objectivesText="Gather 8 Sweetleaf . Progress: Did you get de sweetleaf ?",rewardGold=257400,rewardXP=2765,rewardItems={155912},starts={{npcID=131231}},ends={{npcID=131231}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={50933},questLines={{id=5419,name="This is the Pits",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[49775] = {id=49775,name="Key to the Brig",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49775},series={49754,49758},description="You can tell a lot about a troll by what they do when they learn who Zul truly is. That Garza is a mutinous, foul-tusked, ship stealin' traitor. She is the kind of zealot dat will follow de heretic into the maw of an Old God. I am more de type to rip out her tusks and beat her with dem. I'd settle for ya taking her key and getting our wavemaster and crew free!",objectivesText="Get the key from Quartermaster Garza. Progress: Did ya relieve her of de key?",rewardGold=514800,rewardXP=1770,rewardItems={155882,159942},rewardChoices={159942},rewardCurrencies={{id=1553,amount=100}},starts={{npcID=135576}},ends={{npcID=130821}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49758}},
[49776] = {id=49776,name="No Problem Tar Can't Solve",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={49774,49776,49777,49778,49779,49780,49781},description="I'm not going to lie... I did wicked things in my youth and I've been living with de shame ever since. But Zaluto is going to die without my healing, and we're all going to die if dat dino isn't taken care of. Dere is a lot of tar in dis area. I need it to cure Zaluto of whatever is infecting him here. Get me dat tar, and I'll be able to save Zaluto from dis fate.",objectivesText="Collect 6 Sticky Tar . Progress: We will need plenty of dat sticky tar !",rewardGold=257400,rewardXP=2765,rewardItems={155913},starts={{npcID=131231}},ends={{npcID=131231}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={50933},questLines={{id=5419,name="This is the Pits",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[49777] = {id=49777,name="On The Run",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={50933},description="We were... transporting prisoners when de ambush came... a giant devilsaur... tore through everything. Most of de prisoners escaped in de carnage... dese are hardened criminals. Dey cannot be allowed to roam free! I swore a blood oath dat I would deliver dem to Vol'dun... I am probably going to die here, but I will not die an oathbreaker! Find de escaped criminals and exile dem to Vol'dun.",rewardGold=257400,rewardXP=2765,rewardCurrencies={{id=1553,amount=75}},starts={{npcID=130930}},ends={{npcID=130930}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={50933},questLines={{id=5419,name="This is the Pits",orderIndex=0,flags=0}}},
[49778] = {id=49778,name="Don't Go into the Light",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={49774,49776,49777,49778,49779,49780,49781},description="Okay, dis is de moment of truth! We will see if my voodoo can cure Zaluto . I should have been honest with you... dere is a chance dis won't work. Voodoo isn't a science, you know. I need you to hold Zaluto down, because dis here is going to hurt. A lot.",objectivesText="Hold Zaluto down while Jin'Tiki cures him. Progress: We can't leave Zaluto to die.",rewardGold=128700,rewardXP=1385,rewardItems={156519},starts={{npcID=131231}},ends={{npcID=131231}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49774,49776,49777},questLines={{id=5419,name="This is the Pits",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[49779] = {id=49779,name="Bad To The Bone",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={49774,49776,49777,49778,49779,49780,49781},description="I will not leave here without killing Zulajin, or else it will just go after de next caravan dat comes through. I have a plan, but we must work together to pull it off. Dere are skeletal raptors roaming in de area. I do not know what voodoo brought dem here, but we need dem gone. We are going to need as much space as possible for my plan to kill Zulajin.",objectivesText="Slay 10 Bone Raptors . Progress: Did you take care of de skeletal raptors yet?",rewardGold=273848,rewardXP=2765,starts={{npcID=130930}},ends={{npcID=130930}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49778},questLines={{id=5419,name="This is the Pits",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[49780] = {id=49780,name="Recovering Ancient Fire",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={49774,49776,49777,49778,49779,49780,49781},description="Zaluto has a crazy plan to kill Zulajin. Never thought a guard could come up with something so clever. Dere is ancient mojo throughout dis place... who knows what it used to be? But I sense something I can use. De statues sinking in de tar pits have de fire mojo still burning in dem. We will need it to kill Zulajin. Take my fetish and use it to absorb what's left of de fire in dese statues. Just don't get dat fire too close to de tar!",objectivesText="Absorb fire mojo from 4 Nazmani statues. Progress: Do you have de fire yet?",rewardGold=273848,rewardXP=2765,rewardItems={156480},rewardCurrencies={{id=1553,amount=50}},starts={{npcID=131231}},ends={{npcID=131231}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49778},questLines={{id=5419,name="This is the Pits",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49781] = {id=49781,name="Catch Me if You Can",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={49774,49776,49777,49778,49779,49780,49781},description="Alright, de time has come for you to face Zulajin yourself! Jin'Tiki 's fetish has de power of some ancient fire in it now. You will ride my raptor here to lure Zulajin into de tar pits. After dat... you will use de fetish to light de tar pits on fire! Dat should be enough to kill Zulajin. ...and if not, well, den you will have to improvise. Good luck!",objectivesText="Ride Zulato's raptor to lure Zulajin into the tar pits and set it on fire.",rewardGold=514800,rewardXP=3455,rewardItems={155556,156481,159045,159046,159047,159048},rewardChoices={155556,159046,159048,159047,159045},starts={{npcID=130930}},ends={{npcID=130928}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49779,49780},questLines={{id=5419,name="This is the Pits",orderIndex=6,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[49782] = {id=49782,name="Heritage of the Lightforged",level=50,requiredLevel=50,faction="alliance",requiredRaces={30},categories={},flags={},sharable=false,expansion=7,zoneID=1519,storyline={49782},description="Your service to the Alliance has been most impressive, $p. I could not have done better myself. Well, I could... but not by much. Come, meet with me at the Vindicaar. It is time that we reward your diligence.",objectivesText="Meet Captain Fareeya aboard the Vindicaar. Progress: Welcome aboard, <name>.",rewardGold=341600,rewardXP=6815,rewardItems={170063,174077,203176,208476,210054,218105,218118,218119,242520},starts={{npcID=130993}},ends={{npcID=130993}},mapCandidates={npc={},zone={1519}},questGiverID=130993,questTurnInID=130993,questType="standard"},
[49783] = {id=49783,name="Heritage of Highmountain",level=50,requiredLevel=50,faction="horde",requiredRaces={28},categories={},flags={},sharable=false,expansion=7,zoneID=7503,storyline={49783},description="Your sojourn through Azeroth has been long, $p. And through it all, you have brought honor to Highmountain. Now Thunder Totem calls you home. It is time we thank you for all that you have done for us.",objectivesText="Meet Mayla Highmountain in Thunder Totem.",rewardGold=309800,rewardXP=6815,rewardItems={170063,174077,203176,208476,210054,218105,218118,218119,242520},starts={{npcID=93826}},ends={{npcID=93826}},mapCandidates={npc={},zone={7503}},questGiverID=93826,questTurnInID=93826,questType="standard"},
[49784] = {id=49784,name="Heritage of the Nightborne",level=50,requiredLevel=50,faction="horde",requiredRaces={27},categories={},flags={},sharable=false,expansion=7,zoneID=7637,mapID=680,storyline={49784},description="You are among the first shal'dorei to venture forth and explore the wilds of Azeroth. But now it is time to come home. Return to Suramar so that we may thank you for helping our people reclaim a place in this world.",objectivesText="Meet First Arcanist Thalyssra at the Nighthold.",rewardGold=309800,rewardXP=6815,rewardItems={156675,156676,156677,156678,156679,156680,156681,156685,170063,174077,203176,208476,210054,218105,218118,218119,242520},starts={{npcID=131326}},ends={{npcID=131326}},mapCandidates={npc={680},zone={7637}},questGiverID=131326,questType="standard"},
[49785] = {id=49785,name="Destroy the Weapon",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49785},series={49884},description="I did scout de next island. Rezan's Claw has a mighty weapon on board. I don't know what it is, but dey are confident in its ability to break de defenses of our home. Get to de ship. Destroy that weapon before dey can use it on Zuldazar !",objectivesText="Investigate the weapon.",rewardGold=514800,rewardXP=1770,starts={{npcID=130750}},ends={{npcID=130833}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49871}},
[49787] = {id=49787,name="The Ghostlands",level=40,requiredLevel=40,faction="both",sharable=false,expansion=7,zoneID=3433,mapID=95,description="Are you familiar with how the Void elves joined the Alliance? It began with Alleria Windrunner finding out about a blood elf named Umbric. He and his followers were banished from Silvermoon City for researching void magic. Alleria believed she could convince Umbric and his followers to join the Alliance and prevent the void from corrupting them. It all began when she opened up a portal to go into the Ghostlands...",rewardGold=280900,rewardXP=5465,starts={{npcID=126321},{npcID=126332}},ends={{npcID=126321}},mapCandidates={npc={84},zone={3433}},questTurnInID=126321,questType="standard",sourceQuests={50239},questLines={{id=532,name="Allies of the Alliance: Void Elf",orderIndex=0,flags=0},{id=5697,name="Lorewalking: Elves",orderIndex=7,flags=0}},campaigns={{id=274,title="Lorewalking:Elves",questLineID=5697,questLineOrder=0}}},
[49788] = {id=49788,name="For the Alliance",level=10,requiredLevel=10,faction="alliance",requiredRaces={29},categories={},flags={},sharable=true,expansion=7,zoneID=9415,mapID=84,storyline={49788,50305},series={50305,51486},description="Mastering the whispers requires constant focus and discipline. Your dedication inspires all who bear the name ren'dorei--for we have become children of the Void. You have learned many lessons here, but the time has come to venture beyond Telogrus Rift. Go to Stormwind, the heart of the Alliance. There, the king's ambassador will greet you and guide you along your journey. Azeroth must be defended. I can think of no one better suited to answer that call than you, $p.",objectivesText="Meet Ambassador Moorgard at the Stormwind Embassy.",rewardGold=200,rewardXP=175,rewardItems={23002,23007,23015,23022,37500,42792,42805,42817,42830,65618,65625,65639,65642,66073,94219,108908,108909,108910,108912,108913,108914,108918,108919,116202,151557,157022,157756,157758,161329,165010,165872,166883,168615,168850,169764,174068,174507,204616,204617,204618,204619,223907,241215},starts={{npcID=131345}},ends={{npcID=133362}},mapCandidates={npc={84},zone={9415}},questGiverID=131345,questType="standard",questLines={{id=579,name="Allies of the Alliance",orderIndex=0,flags=0}},db2PoiUiMapID=84},
[49789] = {id=49789,name="The Pledge",level=45,requiredLevel=45,faction="none",categories={},flags={},sharable=true,expansion=7,storyline={49789},description="The ethereals were lying in wait, anticipating someone strong enough in the void to be corrupted by the influence of the Old Gods. We arrived in time to save them, and I will help teach them how to resist the whispers. Umbric is ready to join the Alliance. Let us return to Stormwind and inform King Wrynn. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(49789)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(49789))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Return to Stormwind and speak with Anduin.",rewardGold=28090,rewardXP=4115,rewardItems={29294,29298,29302,29307},mapCandidates={npc={},zone={}},questType="standard"},
[49791] = {id=49791,name="Lost, Not Forgotten",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="I know not what madness has overtaken my people, but we must stop it together. Take this bell. It calls the souls of the recently deceased to it for later release. We Stormsong do not bury our dead in the earth. The tides claim all. If they will not answer to reason, then we must give them eternal peace. Fallen or not, they are Stormsong.",rewardGold=257400,rewardXP=4115,starts={{npcID=130714}},ends={{npcID=130714}},mapCandidates={npc={942},zone={9042}},questTurnInID=130714,questType="standard",sourceQuests={49704,49705,49706},questLines={{id=442,name="A House in Peril",orderIndex=11,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=12,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[49792] = {id=49792,name="Bound and Oppressed",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="We had our orders: ships, and lots of 'em. I led my boys as best I could. Everything changed when the tidesages showed up. We figured they was just checkin' on our progress, but the hood-wearin' bastards turned on us! These anchors bind us here, forcin' us to work to death. No one deserves a fate like that. You gotta free my boys!",rewardGold=257400,rewardXP=4115,starts={{npcID=130904}},ends={{npcID=131248}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49887},questLines={{id=5371,name="Secrets of Stormsong Valley",orderIndex=14,flags=0},{id=442,name="A House in Peril",orderIndex=15,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[49793] = {id=49793,name="Means to an End",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="In our haste to journey here I did not think to bring my ritual implements we tidesages use to augment our power. To be honest, I had never expected them necessary on what should have been a peaceful sojourn. Addington does not have his, either. I am sure the militia took him from his home before he had the chance to react. That means his implements should still be in the yard somewhere. We must find them before my power is of much real use.",rewardGold=309800,rewardXP=4115,starts={{npcID=130714}},ends={{npcID=130714}},mapCandidates={npc={942},zone={9042}},questTurnInID=130714,questType="standard",sourceQuests={49704,49705,49706},questLines={{id=442,name="A House in Peril",orderIndex=12,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=15,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[49794] = {id=49794,name="The Rising Tide",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="This mainspring wasn't altered by an engineer. These runes on the surface can only have come from a tidesage. Their aquatic magic is unmistakable. I'd bet whoever did this is also responsible for Addington's death. Whoever they are, they're likely still nearby. Keep an eye out... they won't be hard to find.",rewardGold=619600,rewardXP=5145,rewardChoices={155182,155184,155183,155181,155191,155193,155192,155190},starts={{npcID=130715}},ends={{npcID=131249}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49704,49705,49706},questLines={{id=442,name="A House in Peril",orderIndex=13,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=16,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[49800] = {id=49800,name="Atal'Dazar: Spiders!",level=50,requiredLevel=50,faction="none",sharable=false,expansion=7,zoneID=9028,mapID=862,mapCandidates={npc={},zone={9028}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=5,objectID=130903,text="Creepy Spiders squished"},{orderIndex=1,type=0,amount=1,objectID=122968}},worldTaskTitle="Atal'Dazar: Spiders!",db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
[49801] = {id=49801,name="Aggressive Mating Strategy",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49801,49810,49814,49870,50074,50150,50154,50252,50268,50297},description="Aggression is good. I agree with Jangalar that Ben'jin needs to be a lot less passive to succeed and I can prove science is the way to do it by making an injection for him. Alchemy tells us that, for this type of beast, aggression comes from a substance in their bile sacs. The local razorwings are invasive and, as such, have more than enough aggression for our purposes. Harvest some of their bile sacs and I'll make a treatment that will have our big boy ready to go again in no time.",objectivesText="Harvest 8 Bile Sacs from Invasive Razorwings. Progress: Did you get all of the bile sacs I need yet? Science is not supposed to be safe...",rewardGold=257400,rewardXP=1415,rewardItems={155904},starts={{npcID=130905}},ends={{npcID=130905}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49810},questLines={{id=5401,name="The Last of Their Kind",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[49803] = {id=49803,name="Changing of the Guard",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48986,49443,49803,49804,49805,49806,49807},description="I have no doubt that you're a quite capable <class>, mainlander, but we will need some help if we want to make it to Waycrest Manor in one piece. A small group would be ideal; strong enough to face the coven's threats, but small enough to remain largely unnoticed. <Reade produces a bundle of letters.> I have written new orders to some of my finest soldiers to join your Order of Embers. They will report to you and the lady Waycrest. Please deliver these to them, so they can be prepared to move out.",objectivesText="Deliver recruitment orders to Captain Cleardawn, Ensign Yorrick , Ensign Mace , Lieutenant Sterntide , and Falconer Notley in Arom's Stand. Progress: You will need to gather your recruits before we venture forth.",rewardGold=128700,rewardXP=1385,rewardItems={156515,156518,156532,163607},starts={{npcID=129643}},ends={{npcID=129643}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={49443},questLines={{id=597,name="Arom's Stand",orderIndex=3,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=36,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[49804] = {id=49804,name="Sharp Thinking",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48986,49443,49803,49804,49805,49806,49807},description="I have reason to believe that the coven has already infiltrated Arom's Stand. There are many unfamiliar faces here, with the refugees from Corlain, and we know they can use their magic to appear like one of us. This needle is fashioned of solid silver. If the witches are indeed vulnerable to silver, then a prick from this may be enough to break their spell. The refugees may not be keen on being prodded, but they must understand that this is for the good of the town... and perhaps all of Drustvar .",objectivesText="Use Lucille's Sewing Needle on 10 Corlain Refugees to reveal the hidden witches in Arom's Stand. Progress: I really hope this works...",rewardGold=257400,rewardXP=2765,rewardItems={156515,156517,156518,156532,163607},starts={{npcID=129642}},ends={{npcID=129642}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={49443},questLines={{id=597,name="Arom's Stand",orderIndex=2,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=35,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[49805] = {id=49805,name="Implements of Ill Intent",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48986,49443,49803,49804,49805,49806,49807},description="<It looks like some careless witch made a poor attempt to hide this grimoire from sight. No good could come of leaving the possessions of the coven for a hapless villager to find. It would probably be a good idea to destroy any trappings of the coven that you find in Arom's Stand.>",objectivesText="Destroy 12 Heartsbane objects in Arom's Stand.",rewardGold=257400,rewardXP=2765,ends={{npcID=129642},{npcID=131638}},startObjects={{objectID=292523,mapID=896,x=0.377,y=0.503}},coords={mapID=896,source="quest_giver",x=0.368,y=0.5},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={49443},questLines={{id=597,name="Arom's Stand",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[49806] = {id=49806,name="Hidden Dealings",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48986,49443,49803,49804,49805,49806,49807},description="<Among her possessions, the witch carried a crudely drawn map of Arom's Stand. A symbol marks what looks like the entrance to a cellar beneath one of the buildings. If this location is important to the coven, it might be worth scouting out.>",objectivesText="Explore the location marked on the Crude Map. Progress: What's this? A map?",rewardGold=514800,rewardXP=3455,rewardItems={156515,156517,156518,156532,163607},ends={{npcID=129642},{npcID=131638}},coords={mapID=896,source="quest_giver",x=0.368,y=0.5},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={49804},questLines={{id=597,name="Arom's Stand",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896,startItems={156517}},
[49807] = {id=49807,name="A New Order",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48986,49443,49803,49804,49805,49806,49807},description="Before we leave, I have one more task to ask of you. While you were busy recruiting our inquisitors and driving the coven away from Arom's Stand, I took the liberty of placing an order with the local tailor. Using some of the sketches within the tome, I had him put together some uniforms reminiscent of those worn by the ancient order. Since you will be leading our inquisitors, I think it's only fitting that you present them with their new regalia.",objectivesText="Give the Inquisitors Regalia to the recruits in Arom's Stand. Progress: You should be inducting them, not me!",rewardGold=122850,rewardXP=1385,rewardItems={156515,156518,156532,163607},rewardCurrencies={{id=1553,amount=150}},starts={{npcID=129642}},ends={{npcID=129642}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={49803,49804},questLines={{id=597,name="Arom's Stand",orderIndex=6,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=37,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[49809] = {id=49809,name="Atal'Dazar: From the Shadows",level=50,requiredLevel=50,faction="none",sharable=false,expansion=7,zoneID=9028,mapID=862,mapCandidates={npc={},zone={9028}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=130912},{orderIndex=1,type=0,amount=1,objectID=122968}},worldTaskTitle="Atal'Dazar: From the Shadows",db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
[49810] = {id=49810,name="Monstrous Matchmaker",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49801,49810,49814,49870,50074,50150,50154,50252,50268,50297},description="We have a problem, a matter of love, and you've come just in time. Two white brutosaurs, de male Ben'jin and de female Maka'fon, are de last of their kind. De rest have passed on. Dese two are not in de mood for love. If you can help my new friend Cala and myself, dis may be de only chance to give dem a future. Place my voodoo totem close to each one so dat I can feel what dey feel and learn how we can help.",objectivesText="Place Witch Doctor Jangalar's Voodoo Totem near both brutosaurs. Progress: Place de voodoo totem close to both of de brutosaurs and I will be able to sense what dey feel.",rewardGold=128700,rewardXP=710,rewardItems={155911},starts={{npcID=130929}},ends={{npcID=130929}},mapCandidates={npc={862},zone={8499}},questType="standard",questLines={{id=5401,name="The Last of Their Kind",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[49812] = {id=49812,name="Delas in Dalaran",level=10,requiredLevel=10,faction="both",requiredClasses={2},categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=139,mapID=627,storyline={43486,43487,43488,43489,43490,43491,43492,43493,43535,43540,43541,43933,43934,49812},series={43486,43487},description="Delas Moonfang needs our help. In-turn, she will aid us to decrypt the Codex of Command. I implore you to seek her out as soon as possible. She is known to enjoy the memorial dedicated to the fallen, great leader of the Kirin Tor, Antonidas.",objectivesText="Find Delas Moonfang at the Antonidas Memorial in Dalaran.",rewardXP=175,starts={{npcID=90251}},ends={{npcID=90251}},mapCandidates={npc={},zone={139}},questGiverID=90251,questTurnInID=90251,questType="standard",sourceQuests={43486},questLines={{id=5826,name="Path of the Light II",orderIndex=3,flags=1}},campaigns={{id=292,title="Paladin Order Hall",questLineID=5826,questLineOrder=2,stallText="Complete the quest Armies of Legionfall in Dalaran to continue the campaign."}},campaignLockText="Complete the quest Armies of Legionfall in Dalaran to continue the campaign.",db2PoiMapID=1220,db2PoiUiMapID=627},
[49814] = {id=49814,name="The Scent for a Brutosaur",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49801,49810,49814,49870,50074,50150,50154,50252,50268,50297},series={50150,50154},description="Mood is everything for love, and Maka'fon is not in de mood. Voodoo incense, specially formulated for brutosaurs by an expert witch doctor like myself, will surely spark de fire of de mother spirit in her heart. Certain fragrant rushes work best, and de jungle will provide. Zandalari rushes grow near de waters here. Get a good amount for me and I will make an incense bundle big enough to set de mood.",objectivesText="Find 7 Fragrant Rushes to make incense for Irritable Maka'fon. Progress: Look for de rushes near de life-giving waters dat I might use my voodoo to make incense for de brutosaurs.",rewardGold=257400,rewardXP=1415,rewardItems={155916},starts={{npcID=130929}},ends={{npcID=130929}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49810},questLines={{id=5401,name="The Last of Their Kind",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[49818] = {id=49818,name="Trouble at Fort Daelin",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49818},description="I was sent to Brennadam by my commanding officer to find a tidesage to help us at Fort Daelin to the west. The naga have started another attack on the bastion, and it's larger than any we have seen. Lieutenant Bauer is in the middle of helping out civilians at the village near the fort, and she could use any help possible.",objectivesText="Report to Lieutenant Bauer at Seabreeze Village.",rewardGold=25740,rewardXP=515,rewardItems={156472,156482,158181,158183,158200,158332,159752},starts={{npcID=131004}},ends={{npcID=131002}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49744,49745,49746},nextQuests={50616,50621}},
[49831] = {id=49831,name="From the Depths",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49831,50614,50616,50621,50635,50644,50645,50649,50653,50672,50679,50698,50705,50706,50773},description="We must prepare for an attack. Man the cannons! Defend the levee at all costs!",objectivesText="Defend the levee from the Azshara's assault.",rewardGold=514800,rewardXP=5145,rewardItems={155198,155211,155212,155217,155219,155226,156472,156482,158181,158183,158200,158332,159752,160519,160521},rewardChoices={160519,155219,160521,155198,155211,155217,155226,155212},starts={{npcID=131000}},ends={{npcID=131000}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50705,50706},questLines={{id=794,name="Defense of Fort Daelin",orderIndex=14,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[49832] = {id=49832,name="An Illegible Scroll",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49832},description="<Resting within the waterproof container is an illegible scroll of undetermined age and origin. Perhaps the tortollans along the coast will be able to decipher what is written upon the parchment?>",objectivesText="Take the scroll to the tortollans along the Windswept Coast.",rewardGold=25740,rewardXP=515,ends={{npcID=135794}},startObjects={{objectID=280576,mapID=942,x=0.322,y=0.4}},coords={mapID=942,source="quest_giver",x=0.405333,y=0.426667},mapCandidates={npc={942},zone={9042}},questType="standard",nextQuests={51339,51343}},
[49855] = {id=49855,name="Disaster at Mount Hyjal",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=616,mapID=85,storyline={49855},series={25316,25317,25319,27721,27726},description="Our brothers in the Cenarion Circle report that Deathwing's minions have launched a destructive offensive against the world tree and threaten to burn it to the ground! You can speak with Cenarion Emissary Blackhoof to gain entry into Moonglade. He is in the tauren district in the Valley of Wisdom in Orgrimmar.",objectivesText="Speak to Cenarion Emissary Blackhoof to secure transportation to Moonglade.",rewardGold=13740,rewardXP=515,starts={{npcID=45244}},ends={{npcID=39865}},mapCandidates={npc={80,85},zone={1637}},questType="standard",sourceQuests={28805},nextQuests={25316}},
[49869] = {id=49869,name="A Desperate Defense",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={49405,49736,49737,49738,49740,49869,50110,52431,52750},series={49399,49401,49404,49405,52431},description="The soldiers garrisoned here are doing their best to hold out, but they're struggling. Pirates haven't dared attack this gate in years, and never with such a large force. If you're handy in a fight, Lieutenant Tarenfold will want to meet you. He's organizing the militia up ahead.",objectivesText="Report to Lieutenant Tarenfold .",rewardGold=25740,rewardXP=175,rewardItems={156520},starts={{npcID=141078}},ends={{npcID=131048}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={52431},questLines={{id=588,name="Defenders of Daelin's Gate",orderIndex=2,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=31,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[49870] = {id=49870,name="Size Matters",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49801,49810,49814,49870,50074,50150,50154,50252,50268,50297},series={50268},description="So the unintended side-effect of Gentle Ben'jin being, shall we say 'fun-sized' is that he is now small enough to get into the cave where the alpha wind serpent is! The beast is called Gloomtail and if Ben'jin defeats it, he will feel like this territory is his and will want to fill it with little brutosaurs. So he will seek out a mate. If Maka'fon is receptive, everyone wins! Go give him another hit of the formula!",objectivesText="Administer the 'voodoo'-ed Aggression Formula to Ben'jin. Progress: Size isn't all dat matters. Ben'jin can get to more places if he's small... and fight dere!",rewardGold=514800,rewardXP=1770,rewardItems={156867,156922},starts={{npcID=130905}},ends={{npcID=130929}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50268},questLines={{id=5401,name="The Last of Their Kind",orderIndex=8,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[49871] = {id=49871,name="Against the Tide",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49871},description="De mogu are growin' desperate. Ha! Maybe dey hope to get away from here before de fury of de loa rain down on dem! De warlord's pet sorcerer set up blockers and dey have taken de tower. If you can avoid the sting, de lightning rods can have ya feelin' pretty good. One could even say energized. Get to Warlord Xiar and relieve him of his life privileges. Then let our people know we have taken back de Breath of Pa'ku! Dis mojo is empowered to ignite de tower with a mighty blast.",objectivesText="Kill Warlord Xiar , and light the signal fire.",rewardGold=514800,rewardXP=1770,rewardItems={52640,52644,52673,156473},starts={{npcID=130821}},ends={{npcID=130750}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49754}},
[49873] = {id=49873,name="Sacrificial Writes",level=10,requiredLevel=10,faction="both",requiredProfessions={"inscription"},categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49873,49874,49877,49878,49879,49881,49882},description="<As you peer inside the tome, you find a verse appear, glowing bright red.> \"For blood to bond, one strikes a deal, A sacrifce which will appeal. Seek out the lame, and never yield, For in return, you shall be healed.\" <As you finish reading the verse, you notice that a scroll has appeared in your hand. Written across the top it's titled, \" Writ of Sacrifice \". Various runes, unknown to you, appear on the rest of the scroll. Yet, there's no explanation as to what to do with the scroll...>",objectivesText="Ask Kronah about the Writ of Sacrifice . Follow her directions after she gives you the information you need.",rewardGold=257400,rewardXP=1415,rewardItems={156549,168046},ends={{npcID=131386}},startObjects={{objectID=279647,mapID=896,x=0.206,y=0.44}},coords={mapID=896,source="quest_giver",x=0.206,y=0.44},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={49694,49944},questLines={{id=903,name="8.1.5 Inscription - Alliance/Horde",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[49874] = {id=49874,name="By the Book",level=10,requiredLevel=10,faction="both",requiredProfessions={"inscription"},categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49873,49874,49877,49878,49879,49881,49882},description="As you open the book, you stare at a blank page, waiting for something to happen. Instinctively you flip to the next page only to find it blank as well. Perhaps your trial awaits you further into the book?",objectivesText="Investigate the Bloodshed Compendium further to begin your trial. Progress: I trust you to be careful inside the Bloodshed Compendium . I don't want to find any ripped pages from that weapon you wield.",rewardGold=257400,rewardXP=1415,rewardItems={94207,138840,138841,138842,138843,138844,138845,138846,138847,156509,166846,166970,166971,204985,205188,208888,246697},starts={{npcID=131657}},ends={{npcID=131386}},mapCandidates={npc={896},zone={8721}},questGiverID=131657,questType="standard",sourceQuests={49873},questLines={{id=903,name="8.1.5 Inscription - Alliance/Horde",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[49875] = {id=49875,name="First Impressions",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"inscription"},categories={},flags={},sharable=true,expansion=7,storyline={49875},series={49878,49879,49880,49881,49882,49945,49947,49948},description="This was all I had to offer you, young scribe. But your journey is not yet at the end. Go to your trainer and and inform them of your success here. I don't suppose you'd like to take some pickled crocolisk eggs with you for the road, would you? Fine, be that way. It's an acquired taste anyway. Takes thousands of years to train the palate. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(49875)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(49875))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Return to Zooey Inksprocket in Tiragarde Sound.",mapCandidates={npc={},zone={}},questType="standard"},
[49876] = {id=49876,name="Lines In the Sand",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"inscription"},categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={40537,49694,49876},description="This was all I had to offer you, young scribe. But your journey is not yet at an end. If you're up for some traveling, and interested in some of the deadlier blood contracts, you're going to have to travel to Zandalar. Once there, seek out a sethrak by the name of Veriss in an area known as Vol'dun. < Kronah grabs an odd-looking jar and opens it. The foulest odor you've ever smelled emanates from it and you reel in disgust.> Pickled crocolisk eggs are my favorite. Would you like some?",objectivesText="Seek out Veriss at the Terrace of the Devoted in Vol'dun to begin your blood trials there.",rewardGold=25740,rewardXP=175,starts={{npcID=131386}},ends={{npcID=150318}},mapCandidates={npc={864,896},zone={8721}},questType="standard",sourceQuests={49874},questLines={{id=901,name="8.1.5 Inscription - Alliance",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49877] = {id=49877,name="Temple of Sethraliss: Booking on a Favor",level=10,requiredLevel=10,faction="both",requiredProfessions={"inscription"},categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={49873,49874,49877,49878,49879,49881,49882},description="When the Faithless came to power, we Devoted fled our sacred temple and took shelter here. However, in the midst of our exodus, many of us were forced to abandon some of our belongings. I myself left a tome that is used to learn the Oblivion contract. If you wish to proceed with the trials, you must retrieve that book for me, <name>. I trust you won't disappoint me.",objectivesText="Recover the Tome of Oblivion from the Temple of Sethraliss. Progress: I'll admit, I'm a bit embarrassed to have left it behind. An oversight that I still regret to this day.",rewardGold=1029600,rewardXP=2830,rewardItems={156512,158075},starts={{npcID=150318}},ends={{npcID=150318}},mapCandidates={npc={864},zone={8501}},questType="dungeon",sourceQuests={49876,49946},questLines={{id=903,name="8.1.5 Inscription - Alliance/Horde",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49878] = {id=49878,name="Penning In Protection",level=10,requiredLevel=10,faction="both",requiredProfessions={"inscription"},categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={49873,49874,49877,49878,49879,49881,49882},series={49875,49879,49880,49881,49882,49945,49947,49948},description="<As you open the book, you turn each page and see portraits of champions standing alongside a large beast. Eventually you come to a blank portrait, and touch the page. Runes begin to appear in an ancient language, and quickly translate into words you can read.> \"The creature within, a guardian of men, A mixture of blood and of bone inked with pen. The blood from the scribe, the bone from the land, Milled to perfection, and signed by the hand.\"",objectivesText="Collect bones from Zem'lan pirates and mill them into a fine powder. Mix the powder with your blood to create a Vial of Ossein Ink . Then sign the Bloodguard Chronicles . Progress: You would think with all the blood you have to give up for these trials, that you would be white as a ghost at the end of them. Or maybe just passed out for a week.",rewardGold=257400,rewardXP=1415,rewardItems={156598,156600,156601},ends={{npcID=150318}},startObjects={{objectID=279646,mapID=864,x=0.276,y=0.522}},coords={mapID=864,source="quest_giver",x=0.276,y=0.522},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={49877},questLines={{id=903,name="8.1.5 Inscription - Alliance/Horde",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49879] = {id=49879,name="Brush With Death",level=10,requiredLevel=10,faction="both",requiredProfessions={"inscription"},categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={49873,49874,49877,49878,49879,49881,49882},series={49875,49878,49880,49881,49882,49945,49947,49948},description="<As you open the book, a sudden chill comes over you. You shake the sensation off as you read the verse.> \"A fatal bargain, in blood is struck, One inks their pledge, with strokes of luck. Stay true your lines, keep still your breath, Lest you stray too far, and summon death.\" <As you finish reading the incantation, a quill appears next to the book.>",objectivesText="Pick up the quill and begin your trial.",rewardGold=64350,rewardXP=355,ends={{npcID=150318}},startObjects={{objectID=279645,mapID=864,x=0.276,y=0.523}},coords={mapID=864,source="quest_giver",x=0.276,y=0.522},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={49877},questLines={{id=903,name="8.1.5 Inscription - Alliance/Horde",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49880] = {id=49880,name="Blood Bonded",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"inscription"},categories={},flags={},sharable=true,expansion=7,storyline={49880},series={49875,49878,49879,49881,49882,49945,49947,49948},description="Looks like you're all done here, . Thanks again for getting my book back, you can understand how that might appear for a master such as myself to lose something like that. But between you and me, this was the easy part. Just wait till you meet the grandmaster. I'll let your current trainer fill you in on that part. Good luck, ! See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(49880)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(49880))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Return to Zooey Inksprocket in Tiragarde Sound.",mapCandidates={npc={},zone={}},questType="standard"},
[49881] = {id=49881,name="The Final Verse",level=10,requiredLevel=10,faction="both",requiredProfessions={"inscription"},categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={49873,49874,49877,49878,49879,49881,49882},series={49875,49878,49879,49880,49882,49945,49947,49948},description="It appears you are finished here, <name>. Thank you again for getting my book back. But between you and I, this was the easy part. Just wait till you meet the grandmaster. If you haven't noticed already, you'll need a special quill to invoke those contracts. And he'll be the one who shows you how to craft it. His name is Miju and he lives out on an island off the southern coast of Zuldazar. Good luck, <name>!",objectivesText="Seek out Miju in southern Zuldazar to begin your final trial.",rewardGold=25740,rewardXP=175,rewardItems={81354},starts={{npcID=150318}},ends={{npcID=131397}},mapCandidates={npc={862,864},zone={8501}},questType="standard",sourceQuests={49878,49879},questLines={{id=903,name="8.1.5 Inscription - Alliance/Horde",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[49884] = {id=49884,name="Hope's Blue Light",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49884},series={49785},description="There is but one step left! De second tower means the fleet is ours again! Climb aboard and we will finish dis thing!",objectivesText="Fly with Captain Grez'ko to light the signal fire on the tower.",rewardGold=257400,rewardXP=1415,rewardItems={156473,158667,159124,159152,159153,159154,159155},rewardChoices={159152,159153,159154,159155,158667,159124},starts={{npcID=130833}},ends={{npcID=123000}},mapCandidates={npc={862,1165},zone={8499}},questType="standard",sourceQuests={49785}},
[49886] = {id=49886,name="Follow Your Nose",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49886},description="You there! I could use your help! The ground isn't safe. The quilboar have established a network of tunnels below us, allowing them to spring up to ambush people who aren't walking carefully. Luckily for us, Humphrey here has a nose for the Briarback, and can sniff 'em out even when they're underground. Root a few of them out and let's make the farms a little safer to walk through. There's a particularly large clump of them in the northeastern fields. Good hunting!",objectivesText="Use Humphrey to find and slay 5 Panicked Tunnelers .",rewardGold=257400,rewardXP=4115,starts={{npcID=131656}},ends={{npcID=131656}},mapCandidates={npc={942},zone={9042}},questType="standard"},
[49887] = {id=49887,name="Forced Labor",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="H... help... us... Please...",rewardGold=128700,rewardXP=2060,starts={{npcID=130904}},ends={{npcID=130904}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49704,49705,49706},questLines={{id=5371,name="Secrets of Stormsong Valley",orderIndex=13,flags=0},{id=442,name="A House in Peril",orderIndex=14,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[49888] = {id=49888,name="Atal'Dazar: A Little Mojo",level=50,requiredLevel=50,faction="none",sharable=false,expansion=7,zoneID=9028,mapID=862,mapCandidates={npc={},zone={9028}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=3,objectID=131123},{orderIndex=1,type=0,amount=1,objectID=122968}},worldTaskTitle="Atal'Dazar: A Little Mojo",db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
[49890] = {id=49890,name="Drustfall",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48184,48504,48517,49890,49896},description="I believe I see more carvings at the entrance to that cave over there. Come, we should see what else was left behind.",objectivesText="Investigate the ice cavern.",rewardGold=514800,rewardXP=3455,rewardItems={155573,158581},rewardChoices={158581,155573},starts={{npcID=130933}},ends={{npcID=130933}},mapCandidates={npc={},zone={8721}},questGiverID=130933,questTurnInID=130933,questType="standard",sourceQuests={48184,48517},questLines={{id=600,name="Gol Osigr",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[49896] = {id=49896,name="To Falconhurst!",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48184,48504,48517,49890,49896},description="Our time here was well spent. The guards in Arom's Stand can handle what few Drust forces remain and I suspect the Drust leader and his magic might have some greater part to play here. However we must continue on the mission to Falconhurst. The path on the far side of these ruins will take us there. I will ride ahead and meet you outside of town!",objectivesText="Meet Inquisitor Cleardawn outside of Falconhurst.",rewardGold=25740,rewardXP=2765,rewardItems={156710,156828},starts={{npcID=130933}},ends={{npcID=131879}},mapCandidates={npc={896},zone={8721}},questGiverID=130933,questType="standard",sourceQuests={49890},questLines={{id=600,name="Gol Osigr",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[49897] = {id=49897,name="Making Mysteries",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={49897},description="Do you know what people love? The unexplained! Problem is, everything here is explainable. So I have a plan to create our own phe-gnome-enon. There are stories that talk about some weird chicken-snake hybrids that can turn you to stone. I've already released the chickens, now we just need the snakes. The first problem can be solved easily. Just chase down the chickens, and stick one of these robotic tails on them.",objectivesText="Catch 5 Unassuming Chickens . Progress: How do my petrifyingly scary chickens look?",rewardGold=257400,rewardXP=1415,starts={{npcID=129858}},ends={{npcID=129858}},mapCandidates={npc={895},zone={8567}},questType="standard"},
[49898] = {id=49898,name="Clear Victory",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49898},description="<The ghostly captain continues to fight as she speaks, once more locked into the heat of battle, unaware the war has been over for centuries.> What are you doing standing around? We've ground them down to their final warriors and those damnable runic constructs, but the war isn't over yet! Colonel Waycrest needs us to hold this line! Kill as many of those Drust as you can and we might see the end of this war, today. Get back out there!",objectivesText="Slay 15 Drust Skeletons.",rewardGold=257400,rewardXP=2765,starts={{npcID=135085}},ends={{npcID=135085}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={49807}},
[49901] = {id=49901,name="Atal'Dazar: Yazma the Fallen Priestess",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=862,storyline={49901},description="Zul knows dat we cannot let de first king rise from his grave. Dazar would be more than a figure head for Zul's dream troll empire, he would be a force dat could rival de very loa. But I cannot just let Zul get away. I and mine will follow Zul, but I want you and yours to enter Atal'Dazar. Yazma is trying to buy time and keep de tombs sealed away. You will need to fight your way through to her and you will need some allies to do so. Slay her.",objectivesText="Defeat Yazma in Atal'Dazar. Progress: And here I always thought Yazma was just rude. I never expected just how far she had fallen.",rewardGold=1029600,rewardXP=2830,rewardCurrencies={{id=1553,amount=600}},starts={{npcID=129757}},ends={{npcID=146335}},mapCandidates={npc={862,1165},zone={8670}},questType="dungeon",sourceQuests={49426}},
[49902] = {id=49902,name="To Gloom Hollow",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="There's only one safe area in Nazmir that this Rokhan and your other Horde friends could be in. Gloom Hollow. Lucky for you, it's also close to Krag'wa's den. We used Gloom Hollow as a last stop on our pilgrimage. Make your way to Gloom Hollow along the path I've marked on your map, and tell any tortollans along the way to meet us there. They'll be interested in seeing the end of this story. We'll make our way there and grab anyone else we find.",rewardGold=25740,rewardXP=345,starts={{npcID=127958}},ends={{npcID=131213}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49160},questLines={{id=375,name="Go East, Old Tortollan",orderIndex=14,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=44,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49905] = {id=49905,name="Plot Twist",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="It is time to end Vol'jamba . I want to make one thing clear. He can still kill you. Your fate, moreso than mine, hangs on your ability to fight dis former student of mine. He will bring masks, and voodoo, and he will do everything within his power to end you. All we have done is taken away his ability to cheat. Good luck. For your sake, I hope you do not fail.",rewardGold=514800,rewardXP=1770,starts={{npcID=129907}},ends={{npcID=129907}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49495},questLines={{id=334,name="Of Prophecies and Prophets",orderIndex=10,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=16,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[49908] = {id=49908,name="Back to Brennadam",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49908},description="The naga are mostly cleared out thanks to your help. They'll think twice before attacking again. Can you return to Brennadam and tell Squire Augustus III to return to his normal station?",objectivesText="Report back to Squire Augustus III at Brennadam.",rewardGold=25740,rewardXP=515,rewardItems={156472,156482,158181,158183,158200,158332,159752},starts={{npcID=131000}},ends={{npcID=131004}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49831}},
[49917] = {id=49917,name="Kaja'mite? Kaja'must!",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49917},series={49919},description="I been waitin' to talk to the King for a while now, but he not be seein' me! And this pompous lackey not be listenin' either. We got a problem brewin' in the Village of the Vines, just outside de city. With all the Horde landin' in the Harbor, some goblins got wind of our old kaja'mite quarry. They split outta here like the teeth of Deathwing himself behind 'em. But that quarry be dangerous. Wicked dangerous. Think you can go to de village an' talk some sense into them goblins?",objectivesText="Travel to Village in the Vines.",rewardGold=25740,rewardXP=175,starts={{npcID=130932}},ends={{npcID=132267},{npcID=132617}},mapCandidates={npc={862},zone={8499}},questGiverID=130932,questType="standard",sourceQuests={49310},nextQuests={49919}},
[49918] = {id=49918,name="Gorilla Gorge",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={49918},objectivesText="Slay Da'kani gorillas",rewardGold=455280,rewardXP=1415,mapCandidates={npc={},zone={8499}},questType="standard",db2Objectives={{text="Slay Da'kani gorillas",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Gorilla Gorge",db2PoiMapID=1642,db2PoiUiMapID=862},
[49919] = {id=49919,name="Kaja'mite Ore Bust",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49919,49920,49922},series={49917},description="Kaja'mite! Just saying the name gives my big beautiful ears a buzz. These Zandalari were sitting on a huge deposit of it all these years. And they abandoned it just because of a few talking gorillas. By goblin law it's ours for the taking! Let's see how concentrated a deposit we're talking about. Get a good peek at those vents that are steaming out kaja'mite vapors. Go into the gorge and plant my scanners on those steam vents. They'll do the rest.",objectivesText="Scan Kaja'mite Steam Vents in Gorilla Gorge.",rewardGold=257400,rewardXP=1415,starts={{npcID=132267},{npcID=132617}},ends={{npcID=132267},{npcID=132617}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49917},questLines={{id=5400,name="Gorilla Greatness",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[49920] = {id=49920,name="Gorilla Warfare",level=10,requiredLevel=10,faction="horde",categories={},flags={"loremaster"},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49919,49920,49922},description="Your timing is most fortuitous, stranger. I thank you for your assistance. Things are not peaceful in Gorilla Gorge. The kaja'mite has given us great intelligence and wit. With intelligence has come war. My brethren are those who do not wish to fight. Neither the Zandalari trolls nor each other. But for our passivity we have been persecuted. Please free my comrades. They will be in cages all throughout the gorge and under guard. Make haste!",objectivesText="Rescue 6 Pacifist Gorillas.",rewardGold=257400,rewardXP=1415,rewardCurrencies={{id=1553,amount=75}},starts={{npcID=130947}},ends={{npcID=131258}},mapCandidates={npc={862},zone={8499}},questType="standard",questLines={{id=5400,name="Gorilla Greatness",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[49922] = {id=49922,name="King Da'ka",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49919,49920,49922},description="These Zandalari won't go near Gorilla Gorge. All because they're afraid! It's just a few talking gorillas. And one 'big mon' in particular as the Zandalari call him. All we need to do is take out King Da'ka and the villagers will probably throw us a parade! Or at least let us mine that kaja'mite. Think you can handle one big gorilla, chum?",objectivesText="Slay King Da'ka .",rewardGold=514800,rewardXP=1770,rewardItems={414,17005,17006,30009,30010,30011,30012,39676,39678,39679,39680,44358,44359,44360,44361,56706,56707,58984,58985,58986,65927,65935,65952,65959,65976,65983,65997,66018,66019,66027,66028,66036,66037,66043,79869,87342,87343,87344,87345,87346,87347,87348,87349,87350,87399,89125,91806,111660,114695,114696,114697,114698,118776,118777,118778,118779,118780,128870,131234,131490,147442,156688,181501,181502,181503,181507,181625,181626,181645,181647,181649,181650,181652,181653,181654,181661,181662,181663,181679,181680,181682,181694,184194,184305,184772,184773,184774,184775,184776,197381,201294,242386,244858,245631,246727},starts={{npcID=132267},{npcID=132617}},ends={{npcID=132267},{npcID=132617}},mapCandidates={npc={862},zone={8499}},questType="standard",questLines={{id=5400,name="Gorilla Greatness",orderIndex=0,flags=0}},packageItems={30013},db2PoiMapID=1642,db2PoiUiMapID=862},
[49926] = {id=49926,name="The Road to Corlain",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49926,50003,50149,50151,50173,50253,50446,50453,50457},description="Lord and Lady Waycrest lay trapped in Waycrest Manor. Before we can reach them, however, we must brave through the city of Corlain... which is firmly in the grasp of the Heartsbane. Our first course of action should be to set up a forward outpost. Our scouts have found that the tower at Watchman's Rise is only lightly guarded. I recommend we take the tower from them. This is now your command, Inquisitor. Say the word, and we ride.",objectivesText="Meet with Marshal Reade at Watchman's Rise in Drustvar .",rewardGold=30900,rewardXP=345,rewardItems={156722,156853,156855,157800},starts={{npcID=129643}},ends={{npcID=131636}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={49807},questLines={{id=598,name="Corlain",orderIndex=0,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=38,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[49928] = {id=49928,name="Heritage of the Void",level=50,requiredLevel=50,faction="alliance",requiredRaces={29},categories={},flags={"loremaster"},sharable=false,expansion=7,zoneID=9415,storyline={49928},description="Throughout your journeys across Azeroth, you have achieved mastery over the forces that constantly seek to control you. You have become a formidable weapon of the Alliance, $p. Return to the void rift so that we may honor your accomplishment.",objectivesText="Meet Alleria Windrunner at Telogrus Rift.",rewardGold=319000,rewardXP=6815,rewardItems={170063,174077,203176,208476,210054,218105,218118,218119,242520},starts={{npcID=131345}},ends={{npcID=131345}},mapCandidates={npc={},zone={9415}},questGiverID=131345,questTurnInID=131345,questType="standard"},
[49932] = {id=49932,name="Slumber No More",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="There's something you should look into. You've got the time anyway, those goblins aren't ready yet. There's a statue nearby. Only, it's not a statue to the trained tortollan eye. It's a deactivated titan keeper ! Noises have been coming from that thing ever since you helped Krag'wa. It must be trying to reactivate itself. I bet that titan-looking amulet of yours could help restart it. We'd be unstoppable against the blood trolls with a titan keeper's help. Go see if you can restart this titan!",rewardGold=128700,rewardXP=1385,starts={{npcID=131978}},ends={{npcID=131253}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47602,47697},questLines={{id=523,name="Titanic Revelations",orderIndex=0,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=64,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49933] = {id=49933,name="For the Horde",level=10,requiredLevel=10,faction="horde",requiredRaces={27},categories={},flags={},sharable=true,expansion=7,zoneID=7637,mapID=680,storyline={49933,50303},description="After ages standing alone, we are once again poised to become part of something greater. Our alliance with the Horde affords us a fresh start, a unique chance that must not be squandered. Go to Orgrimmar. From there, you will set out on a journey across Azeroth. Fight to defend this land, and claim a place for the shal'dorei within it. Show the world who we are, <class>. Bring honor to the Horde, for in so doing, you will bring honor to Suramar.",objectivesText="Meet Ambassador Blackguard at the Orgrimmar Embassy.",rewardGold=34100,rewardXP=175,rewardItems={23002,23007,23015,23022,29928,29930,29931,29934,29938,29941,29943,29945,37956,37964,37998,38006,38041,38048,38081,38102,38110,57509,57510,57511,57512,65680,65701,65719,65728,66073,94220,111535,111536,111537,111538,111539,111540,111541,111542,116202,118761,118762,118763,118764,118765,131486,131696,131697,151557,155662,157028,157757,157759,161328,165001,165871,166883,167169,168615,168850,169765,174069,174508,223907,241215},starts={{npcID=131326}},ends={{npcID=133407}},mapCandidates={npc={85,680},zone={7637}},questType="standard",questLines={{id=581,name="Allies of the Horde",orderIndex=0,flags=0}},db2PoiMapID=1,db2PoiUiMapID=85},
[49935] = {id=49935,name="How to Repair a Titan Keeper",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Major system repair possible within nearby structure. Preliminary goal: repair auxiliary systems. Scans detect three fallen titan keepers. Recover cores. Titan Keeper Hezrel able to retrieve data from cores. Titan Keeper Hezrel goal: reboot auxiliary systems, reach nearby structure, restore all primary systems, seal corruption. Result: corruption contained. Titan Keeper Hezrel able to aid against blood trolls. Blood troll definition not found in databanks.",rewardGold=514800,rewardXP=3455,rewardCurrencies={{id=1553,amount=75}},starts={{npcID=131253}},ends={{npcID=131253}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49932},questLines={{id=523,name="Titanic Revelations",orderIndex=1,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=65,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49937] = {id=49937,name="Recovering Remnants",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Scan of area indicates roaming spirits clad in armor plating. Purpose: defense of structure, animated by corruption. Detecting remnants of titan plating within spirits' armor. Request: recover remnants. Titan Keeper Hezrel capable of breaking down titan plating to reforge into weapon against forces drawn by corruption.",rewardGold=257400,rewardXP=2765,starts={{npcID=131253}},ends={{npcID=131253}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49932},questLines={{id=523,name="Titanic Revelations",orderIndex=2,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=66,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49938] = {id=49938,name="Corrupted Earth",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Unacceptable levels of corruption detected nearby. Scan indicates vegetation affected by corruption. All corruption must be eradicated. Request: destroy any vegetation affected by corruption.",rewardGold=257400,rewardXP=2765,starts={{npcID=131253}},ends={{npcID=131253}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49932},questLines={{id=523,name="Titanic Revelations",orderIndex=3,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=67,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49939] = {id=49939,name="So Long, Sister",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49939,50001,50036,50063,50090,50092,50172,50177,50238,50251,50903},description="We have given the defenders some breathing room, but these creatures continue to lay siege to the barricade! The witch behind the attack fled from the field when we defeated her forces. I saw her go into the mansion on the hill. I will help keep the defenses going here. You must go into the mansion and slay the witch!",objectivesText="Slay Sister Noella Briarwood . Progress: The witch must be slain!",rewardGold=514800,rewardXP=3455,rewardItems={156710,156828},starts={{npcID=131879}},ends={{npcID=131442}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50177},questLines={{id=5442,name="Falconhurst",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[49940] = {id=49940,name="Sandscar Breach",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49940},description="I heard some mutterings about sand and snakes. The plea comes from a tiny village on the very fringes of Zuldazar - hardly more than a few farms. Dol-something I think it was called. Don't know what they be calling it now. Go see what the fuss is about. Bladeguard Sonji was sent ahead some time ago. She should be able to get you up to speed on that... situation.",objectivesText="Meet Bladeguard Sonji at Sandscar Breach.",rewardGold=22130,rewardXP=175,starts={{npcID=131287}},ends={{npcID=130450}},mapCandidates={npc={862},zone={9598}},questGiverID=131287,questType="standard",sourceQuests={49426},nextQuests={49678,49679,49680}},
[49941] = {id=49941,name="Bone Procession",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Undead entities influenced by corruption surround nearby structure. Impossible to approach. Plan required. Calculating. Plan achieved. Large creatures designated reanimated monstrosities focal gathering point of corruption. Take titan weapon forged from plating recovered. Use it to weaken monstrosities and collect bones. Will run process to destroy bones, prevent creation of further monstrosities.",rewardGold=257400,rewardXP=2765,rewardChoices={159078},starts={{npcID=131253}},ends={{npcID=131253}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49935,49937,49938},questLines={{id=523,name="Titanic Revelations",orderIndex=4,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=69,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49943] = {id=49943,name="Drawing Blood",level=50,requiredLevel=50,faction="horde",requiredProfessions={"inscription"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={49943,49944,49946},series={49944},description="Hey, <name>! I have something exciting to tell you about, but I need you to keep it secret. Just between us scribes. <Grazzul gives you a nod and pulls out a large tome.> Dis is de Bloodbound Ledger. Signing your name in it let's you learn how to craft \"blood contracts\" which are rather dangerous, but worth de risk. I only know one of dem and it is quite de rush when I use it because it... well, you'll see. So what do you say? Interested?",objectivesText="Sign the Bloodbound Ledger.",rewardGold=23400,rewardXP=850,starts={{npcID=130901}},ends={{npcID=130901}},mapCandidates={npc={1165},zone={8670}},questType="standard",questLines={{id=902,name="8.1.5 Inscription - Horde",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[49944] = {id=49944,name="Turn to Drust",level=10,requiredLevel=10,faction="horde",requiredProfessions={"inscription"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={49943,49944,49946},series={49943},description="Dere are blood scribe masters all over de place who'll teach you what you need to know. De first master I'd recommend seeking out is Kronah . She's a bit... eccentric to say de least. One of de few tortollan who've experienced a thing or two. She's de one who taught me de blood contract I know how to invoke! She prefers to hang out at de Smuggler's Cove on de western coast of Drustvar.",objectivesText="Seek out Kronah at the Smuggler's Cove in Drustvar.",rewardGold=25740,rewardXP=175,starts={{npcID=130901}},ends={{npcID=131386}},mapCandidates={npc={896,1165},zone={8670}},questType="standard",sourceQuests={49943},questLines={{id=902,name="8.1.5 Inscription - Horde",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[49945] = {id=49945,name="First Impressions",level=10,requiredLevel=10,faction="horde",requiredProfessions={"inscription"},categories={},flags={},sharable=true,expansion=7,zoneID=10565,mapID=1670,storyline={49945},series={49875,49878,49879,49880,49881,49882,49947,49948},description="This was all I had to offer you, young scribe. But your journey is not yet at the end. Go to your trainer and and inform them of your success here. I don't suppose you'd like to take some pickled crocolisk eggs with you for the road, would you? Fine, be that way. It's an acquired taste any ways. Takes thousands of years to train the palette. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(49945)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(49945))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Return to Zooey Inksprocket in Tiragarde Sound.",mapCandidates={npc={},zone={10565}},questType="standard"},
[49946] = {id=49946,name="Lines In the Sand",level=10,requiredLevel=10,faction="horde",requiredProfessions={"inscription"},categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49943,49944,49946},description="This was all I had to offer you, young scribe. But your journey is not yet at an end. If you're up for some traveling, and interested in some of the deadlier blood contracts, you're going to have to travel to Zandalar. Once there, seek out a sethrak by the name of Veriss in an area known as Vol'dun. < Kronah grabs an odd-looking jar and opens it. The foulest odor you've ever smelled emanates from it and you reel in disgust.> Pickled crocolisk eggs are my favorite. Would you like some?",objectivesText="Seek out Veriss at the Terrace of the Devoted in Vol'dun to begin your blood trials there.",rewardGold=25740,rewardXP=175,starts={{npcID=131386}},ends={{npcID=150318}},mapCandidates={npc={864,896},zone={8721}},questType="standard",sourceQuests={49874},questLines={{id=902,name="8.1.5 Inscription - Horde",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[49947] = {id=49947,name="Blood Bonded",level=10,requiredLevel=10,faction="horde",requiredProfessions={"inscription"},categories={},flags={},sharable=true,expansion=7,storyline={49947},series={49875,49878,49879,49880,49881,49882,49945,49948},description="Looks like you're all done here, . Thanks again for getting my book back, you can understand how that might appear for a master such as myself to lose something like that. But between you and me, this was the easy part. Just wait till you meet the grandmaster. I'll let your current trainer fill you in on that part. Good luck, ! See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(49947)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(49947))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Return to Zooey Inksprocket in Tiragarde Sound.",mapCandidates={npc={},zone={}},questType="standard"},
[49948] = {id=49948,name="The Final Verse",level=10,requiredLevel=10,faction="horde",requiredProfessions={"inscription"},categories={},flags={},sharable=true,expansion=7,storyline={49948},series={49875,49878,49879,49880,49881,49882,49945,49947},description="Now dat you be done learnin' all da contracts, you be needin' one more ting ta learn. Dere be a special quill ya need to make in order to craft da contracts. And dere be one last trial ya must complete in order ta be worthy ta learn da design for da quill. Miju be da mastah in charge of da design. Pass his trial, and he'll be teachin' ya what'cha need ta know. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(49948)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(49948))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Seek out Miju in (Zone) to begin your final trial.",rewardGold=16980,rewardXP=175,mapCandidates={npc={},zone={}},questType="standard"},
[49949] = {id=49949,name="Unwelcome Undead",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Corruption reanimating dead creatures nearby. Morphing into monstrosities. Must be stopped. Cannot kill all, but can reduce numbers. Reduced numbers equates to less corruption outside of containment. Destroy undead in surrounding area. Keeper Hezrel's systems will continue rebooting while you do so. Reboot goal: recover data regarding nature of corruption.",rewardGold=257400,rewardXP=2765,starts={{npcID=131253}},ends={{npcID=131253}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49935,49937,49938},questLines={{id=523,name="Titanic Revelations",orderIndex=5,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=70,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49950] = {id=49950,name="Blood Purification",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,rewardGold=257400,rewardXP=2765,starts={{npcID=133941}},ends={{npcID=131253}},mapCandidates={npc={863},zone={8500}},questGiverID=133941,questType="standard",sourceQuests={49935,49937,49938},questLines={{id=523,name="Titanic Revelations",orderIndex=6,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=68,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49952] = {id=49952,name="The Essence of G'huun",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={49952},description="Analysis of blood-infused bones complete. Will be able to create synthetic essence similar to G'huun. Will take a moment to apply essence, allow you to walk past undead without combat. Must hurry. More forces of G'huun are around temple. Must get inside to reactivate containment protocols.",objectivesText="Have Titan Keeper Hezrel apply Synthetic Essence to allow safe passage past undead.",rewardGold=20220,rewardXP=345,mapCandidates={npc={},zone={8500}},questType="standard"},
[49955] = {id=49955,name="Not Fit for This Plane",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="System restoration in progress. Data recovered. Source of corruption is from an Old God entity. Multiple entities detected nearby, blocking goal of analyzing and containing corruption in Nazmir . Entities appear to be from the Void. Drawn here from Old God corruption. Request to destroy Void entities. Void presence inhibiting repair of systems.",rewardGold=58650,rewardXP=2765,starts={{npcID=131253}},ends={{npcID=131253}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49941,49949,49950},questLines={{id=523,name="Titanic Revelations",orderIndex=7,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=71,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49956] = {id=49956,name="Void is Prohibited",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Scans indicate errors in reality surrounding nearby structure. Portals directly to the Void. Current theory, corruption has Old God as source. Void attracted to Old God corruption. Portals must be sealed to contain entities lured here by Old God corruption. Take this device. Titan Keeper Hezrel has forged it thanks to help in powering up systems. Use device to seal Void portals , prevent more void entities from entering area.",rewardGold=257400,rewardXP=2765,starts={{npcID=131253}},ends={{npcID=131253}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49941,49949,49950},questLines={{id=523,name="Titanic Revelations",orderIndex=8,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=72,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49957] = {id=49957,name="Protocol Recovery",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="System repairs progressing. One key component needed: containment protocol . containment protocol will fully reboot defensive systems. Allow Titan Keeper Hezrel to properly maintain containment. Scans indicate large creature within temple has absorbed slab containing containment protocol . Creature exists between this plane and Void. Request: destruction of creature and retrieval of protocol.",rewardGold=117300,rewardXP=3455,starts={{npcID=131253}},ends={{npcID=131253}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49941,49949,49950},questLines={{id=523,name="Titanic Revelations",orderIndex=9,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=73,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49960] = {id=49960,name="Sic 'Em!",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49960},description="Humphrey's a good tracker, to be sure. He's also the orneriest, angriest, most dogged dog if he sets his eyes on a quilboar. This will certainly be useful. Below our very noses, the foreman organizes and directs the tunnelers to cause the most mayhem and destruction. If you can put an end to him, it should make things a lot easier for us to move around the farmlands. Humphrey looks a bit hungry, wouldn't you say? Why don't you bring him with you to take care of business?",objectivesText="Defeat Foreman Razorgnarl . Progress: If I could rate Humphrey, I'd give him at least a twelve out of ten.",rewardGold=514800,rewardXP=5145,rewardItems={21392,87399,154990,188658},rewardCurrencies={{id=1553,amount=75}},starts={{npcID=131656}},ends={{npcID=131656}},mapCandidates={npc={942},zone={9042}},questType="standard"},
[49965] = {id=49965,name="The Warpack",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,series={50433,51111,49421},description="Zul began a coup, but he did not secure de pyramid for himself. Nor has he done anything to rally more to his banner outside of those who were already conspiring with him. Dis concerns me more than if he had carved his face into Dazar'alor itself. We must learn what he is up to. Join de disciples of Gonk and ride ahead to de Temple of the Prophet. Look to Wardruid Loti for further orders when you arrive.",rewardGold=257400,rewardXP=1415,rewardCurrencies={{id=1597,amount=75}},starts={{npcID=129491}},ends={{npcID=129740}},mapCandidates={npc={862,1165},zone={8499}},questType="standard",sourceQuests={47528,47741,49421},questLines={{id=527,name="March of the Loa",orderIndex=1,flags=0},{id=6023,name="Lorewalking: Loa",orderIndex=1,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=72,flags=0}},campaigns={{id=320,title="Lorewalking: Loa",questLineID=6023,questLineOrder=0},{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[49969] = {id=49969,name="Awaken a God",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={48014,48015,48025,48026,49969,51538},description="You see the sinking ruins to the east? They were, not long ago, a temple to the shark loa, Gral. The naga tore down his temple and are stealing his secrets. If it is for something good, I'll be a rock's uncle. It would be wise to let Gral know what's going on here. I do not think he would approve. Gral was quite powerful, and when it came to his knowledge of the sea, none could compare. It never hurts to have a fellow like that on your side. Some fresh, bloody naga meat may just lure him out.",objectivesText="Gather chunks of naga flesh as an offering to Gral. Progress: <There is a feeling of anticipation emanating from the bowl.>",rewardGold=257400,rewardXP=1415,rewardItems={156539,156871},starts={{npcID=125039}},ends={{npcID=125039}},mapCandidates={npc={862},zone={8499}},questTurnInID=125039,questType="standard",sourceQuests={48014,48015},questLines={{id=5410,name="The Sunken City",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[49973] = {id=49973,name="Thalyssra's Estate",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=1637,mapID=85,storyline={49354,49613,49614,49973},description="Would you like to hear how the nightborne came to join the Horde? We earned their trust when we aided them in liberating Suramar from the tyranny of Grand Magistrix Elisande and the Burning Legion. Lor'themar Theron later asked them to join him in Quel'Thalas. Lady Liadrin made the journey to extend the invitation to First Arcanist Thalyssra...",objectivesText="Meet with Lady Liadrin at the Estate of the First Arcanist in Suramar.",rewardGold=309800,rewardXP=5465,starts={{npcID=126062},{npcID=133523}},ends={{npcID=131478}},mapCandidates={npc={85,680},zone={1637}},questType="standard",sourceQuests={50242},questLines={{id=531,name="Allies of the Horde: Nightborne",orderIndex=0,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=680},
[49975] = {id=49975,name="Rest in the Depths",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="This passage flows through the Shrine of the Storm out into the open sea. We will release the souls of the fallen here. Legends say that as our spirits pass through the Shrine, they aid in the great blessing rituals that all Kul Tiran ships undergo. In that way, we Stormsong never stop serving our people.",rewardGold=128700,rewardXP=2060,starts={{npcID=130714}},ends={{npcID=130714}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49791,49792,49793,49794},questLines={{id=442,name="A House in Peril",orderIndex=16,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=17,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[49980] = {id=49980,name="Containment Procedure",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Scans indicate structure has become inoperable. No possibility for repair. Titan Keeper Hezrel 's database fully restored. Believe solution may be within data. Require time to scan data, find solution to contain Old God corruption. Stand by while Titan Keeper Hezrel scans databanks for solution.",rewardGold=175950,rewardXP=4150,rewardChoices={159088,159085,159083,159084,159087,159082,159081,159086},starts={{npcID=131253}},ends={{npcID=131253}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49955,49956,49957},questLines={{id=523,name="Titanic Revelations",orderIndex=10,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=74,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49985] = {id=49985,name="Return to Gloom Hollow",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Old God G'huun behind destruction of this seal. Commanding blood trolls to destroy final one within Zuldazar. Titan Keeper Hezrel must aid in destruction of blood trolls. Cannot allow Zuldazar seal to be destroyed and G'huun to be freed. Must leave interior of Atul'nazman. Meet Titan Keeper Hezrel outside of temple, will help return to Gloom Hollow. When task is complete, Titan Keeper Herzrel must establish contact with other keeper within G'huun containment chamber.",rewardGold=119340,rewardXP=1385,rewardCurrencies={{id=1560,amount=50}},starts={{npcID=131253}},ends={{npcID=126213}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49980},questLines={{id=523,name="Titanic Revelations",orderIndex=11,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=75,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[49991] = {id=49991,name="Featherfeet's Fun Falling's Fun Fee!",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49991},description="Welcome to Zuldazar , my fine $pr friend! I've explored every inch of this wonderful city with my own two feet. And let me tell you, they're tired! That's why I've decided to provide a service to my powerful friends in the Horde: Featherfeet's Fun Falling! Now, I know what you're thinking. You nomrally associate falling with screams, pain, and an untimely death. BUT NOT WITH FEATHERFEET! For a small one-time fee, I'll make sure you always float down this ziggurat shrouded in safety and fun. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(49991)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(49991))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Pay 100 gold to Quinsy Featherfeet and he'll cast Slow Fall on you whenever you're nearby.",mapCandidates={npc={},zone={8499}},questType="standard"},
[49994] = {id=49994,name="Sliding with Style",expansion=7,mapID=895,questType="world",db2Objectives={{orderIndex=0,type=3,amount=1,objectID=131575,text="Talk to the Penguing Sledding Barker"},{orderIndex=1,type=0,amount=1,objectID=131573,text="Ride the pengling to the goal"}},worldTaskTitle="Sliding with Style",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[49995] = {id=49995,name="Fabricated Fabrications",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="There was somethin' off with the ship we were building in the yard. I never saw the blueprints, but I've built enough ships in my day to know it wasn't business as usual. They've kept all the pages under tight guard in the Brineworks up the road lately. Full on militia. If you can get your hands on enough of them pages, we oughta be able to figure out what Lord Stormsong and his boys are schemin'.",rewardGold=257400,rewardXP=4115,rewardCurrencies={{id=1560,amount=50}},starts={{npcID=131248}},ends={{npcID=131248}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49975},questLines={{id=442,name="A House in Peril",orderIndex=17,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=18,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[49996] = {id=49996,name="Rearmament",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="The people of this valley have true hearts, . They're eager to take back control of their home. We have to help them. The Brineworks up the road from here supplies most of House Stormsong's weapons. Our movement here could make great use of them. If you can collect enough to go around, I'll go over some basic training with our friends here.",rewardGold=257400,rewardXP=4115,rewardChoices={155209,155216,155204,155208,155199,155214,155221,155224},starts={{npcID=131249}},ends={{npcID=131249}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49975},questLines={{id=442,name="A House in Peril",orderIndex=18,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=19,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[49997] = {id=49997,name="Storm's Judgment",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="When I opened my mind to the currents during the ritual, I felt the presence of a member of Lord Stormsong's innermost circle. Wavespeaker Reid. If anyone can locate the missing fleet, it is him. I will not stand by while my brothers move against our own people. Oaths be damned. We must force Reid to see reason.",rewardGold=619600,rewardXP=5145,rewardCurrencies={{id=1553,amount=125}},starts={{npcID=130714}},ends={{npcID=130714}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49995,49996,50139},questLines={{id=442,name="A House in Peril",orderIndex=20,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=21,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[49998] = {id=49998,name="Voices Below",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="The others forged ahead to Port Fogtide. I doubt they will receive a warm welcome. We are to meet them there. However, there is something I must do first. Despite Reid's retreat I still feel a terrible darkness nearby; I wish to listen to the tides for answers. I would appreciate your joining me in case more danger strays into our path.",rewardGold=154900,rewardXP=2060,starts={{npcID=130714}},ends={{npcID=134639}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49997},questLines={{id=442,name="A House in Peril",orderIndex=21,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=22,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[50000] = {id=50000,name="Beastly Dealings",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=8721,mapID=896,mapCandidates={npc={},zone={8721}},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Destroy signs of witchcraft"},{orderIndex=1,type=0,amount=20,objectID=131373},{orderIndex=2,type=0,amount=17,objectID=132091},{orderIndex=3,type=0,amount=34,objectID=144260}},worldTaskTitle="Beastly Dealings",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50001] = {id=50001,name="Breaking Hag",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49939,50001,50036,50063,50090,50092,50172,50177,50238,50251,50903},description="The town is overrun! The guards have fallen back and what is worse, some of the villagers have been twisted by the witches' magic. They are little more than wretched beasts blindly following orders. We must release these poor souls and slay the monsters that twisted them! See what you can do to cut down the numbers of monsters in town!",objectivesText="Kill 15 Briarwood Creatures and Witches. Progress: We have a little breathing room.",rewardGold=257400,rewardXP=2765,rewardItems={156710,156828},starts={{npcID=131879}},ends={{npcID=131879}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={49896},questLines={{id=5442,name="Falconhurst",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50002] = {id=50002,name="A Very Precious Cargo",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={47755,50002,50005,50026,50059},description="We weren't the only ship in our convoy to get caught up in this mess. Our flagship ran aground to the east. It was holding a very precious cargo and I need you to bring it back here.",objectivesText="Find the \"Precious\" cargo in Fogcliff Strand.",rewardGold=193050,rewardXP=1060,starts={{npcID=123415}},ends={{npcID=131684}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={50026},questLines={{id=5437,name="A Sirens Song",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[50003] = {id=50003,name="The First Watch",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49926,50003,50149,50151,50173,50253,50446,50453,50457},description="As you can see, the coven has conscripted my own guardsmen into their service. Though I am loath to battle my own, these men are too corrupted by the coven's magic to be saved. For them, death is the only mercy we can give. The Inquisitors and I can handle the regiment stationed outside. We will need you to find and take out their leader. Your Inquisitors await your command, <class>. Are you ready to take the tower?",objectivesText="Defeat Sister Adela at Watchman's Rise. Progress: We assault the tower at your command.",rewardGold=514800,rewardXP=3455,rewardItems={155155,155156,155163,156722,156853,156855,157800},rewardChoices={155163,155156,155155},starts={{npcID=131636}},ends={{npcID=131636}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={49926},questLines={{id=598,name="Corlain",orderIndex=1,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=39,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50005] = {id=50005,name="Hold My Hand",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={47755,50002,50005,50026,50059},description="Take me to my daddy this instant! Waaaait! You have to hold my hand...",objectivesText="Escort Penny back to her father. Progress: Where is she? Don't tell me you lost her.",rewardGold=257400,rewardXP=1415,rewardItems={151135,158262,158263,158264,158265,160087},rewardChoices={158264,158262,158265,158263,160087},starts={{npcID=131684}},ends={{npcID=123415}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={50002},questLines={{id=5437,name="A Sirens Song",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[50009] = {id=50009,name="Shipwreck Recovery Crew",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={50009},description="Fogcliff Strand is swarming with Sirens and Saurolisks! Clear them out and grab any remaining cargo from the ships.",objectivesText="Kill Creatures and Collect Cargo",rewardGold=455280,rewardXP=1415,mapCandidates={npc={},zone={8567}},questType="standard",sourceQuests={50026},db2Objectives={{text="Kill Creatures and Collect Cargo",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Shipwreck Recovery Crew",db2PoiMapID=1643,db2PoiUiMapID=895},
[50026] = {id=50026,name="Save Our Shipmates",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={47755,50002,50005,50026,50059},description="Oh, thank the stars! Our ship ran aground and our men are in desperate need of help. Find Henry Hardwick down the hill at the shipwreck. He stayed behind to try and help the others.",objectivesText="Find Henry Hardwick in Fogcliff Strand.",rewardGold=128700,rewardXP=710,starts={{npcID=131627}},ends={{npcID=123415}},mapCandidates={npc={895},zone={8567}},questType="standard",questLines={{id=5437,name="A Sirens Song",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[50036] = {id=50036,name="A Weapon of Old",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49939,50001,50036,50063,50090,50092,50172,50177,50238,50251,50903},description="I've been studying the parchment Lady Lucille sent with you and have translated some of the older language. They called it \"Liquid Fire\" and it was used to \"burn away the Drust\". Using this as a basis I believe we can adapt it to our needs. This is a complex recipe, but it just so happens I have everything we need to make this potent alchemical weapon! I will need your assistance in creating this. Would you be so kind as to help?",objectivesText="Help Master Ashton create the Liquid Fire potion. Progress: We'd better get cooking!",rewardGold=257400,rewardXP=2765,rewardItems={156710,156828},starts={{npcID=131448}},ends={{npcID=131448}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50092},questLines={{id=5442,name="Falconhurst",orderIndex=8,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50041] = {id=50041,name="A Pocketful of Shells",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50041,50065,50069,50088},series={50157},description="You see the problem? No you don't. Problem isn't all these dang quilboar. Quilboar I can shoot all day. Been shootin' em all my life, since my pappy gave me my first gun. Problem is these pigs are tough. Tougher'n they've been before. Can't kill em like I used to, see? My new modified bullets just get stuck in them and they refuse to die! Here, take my knife. Go out there and kill some of the quilboar and get my ammo back. Then I can shoot the rest! I won't stop 'till there's none left to shoot!",objectivesText="Collect 20 Salvaged Azerite Ammunition . Progress: Pretty sure I'll have to start shootin' my dinnerware, and I only have three sets. Hurry up, will you?",rewardGold=257400,rewardXP=4115,rewardItems={133510,155824,155877,156577,156578,156583,156648,157849,157850,160558,160561},starts={{npcID=129808}},ends={{npcID=129808}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50157},questLines={{id=738,name="Goldfield's War",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50043] = {id=50043,name="Archaeological Efficiency",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47228,47235,47329,48317,48399,48400,50043},description="Miss Tae'shara and I share a passion for uncovering hidden secrets and a deep, abiding respect for this ancient land. That said! If we were to continue at the pace to which she is accustomed, the Alliance would overtake us before we could make a single discovery. It is time to expedite our survey. The ruins hide many fossils. Take a beacon and use it to summon one of my sweepers. It will clear away the topsoil and allow you to collect samples. Gather what you can- we can assemble them later.",objectivesText="Collect 50 Xibalan fossil fragments . Progress: I simply see no reason to dirty our hands, <name>.",rewardGold=257400,rewardXP=1415,rewardItems={156596,156597},starts={{npcID=131580}},ends={{npcID=131580}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47329},questLines={{id=5403,name="Fossil Extraction",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[50044] = {id=50044,name="Archaeological Efficiency",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={50044},description="Suppose I owe the lass her bones if I'm tae be monopolizin' yer time. And I will be. Go on out into the ruins an' use this here stone to call one of my rumbly elemental friends. They'll blast away any dirt 'tween you an' the fossils. We could go about this the ol' fashion way, but do you really want to spend all day digging? Course ye don't. Acadia will see that a little efficiency gets everyone what they want.",objectivesText="Use the Elemental Summoning Stone to expose Xibalan fossils. Bring 50 Xibalan Fossil Fragments to Acadia Chistlestone . Progress: <Acadia eyes Morgrum sourly.> I don't think he cares one lick about our expedition, <name>.",rewardGold=128700,rewardXP=710,rewardItems={156597,159640},starts={{npcID=131763}},ends={{npcID=131777}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49276}},
[50046] = {id=50046,name="It's a Sabotage",level=45,requiredLevel=45,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9310,mapID=81,storyline={49976,49981,50046,50047,50048,50049,50056,50057,50226,50227,50228,50371,50372,50373,50374},description="The Horde has wasted no time in shamelessly extracting this mysterious ore from the great wound. Luckily for us, goblin engineering is not nearly as sophisticated as what we create in Gnomeregan! All it takes is a little bit of old fashioned dynamite to completely disable a goblin shredder. What unsophisticated machinery! Take these dynamite bundles and plant them on the inactive shredders around the mining camp. It'll take those greedy goblins weeks to get back up and running again!",objectivesText="Plant 10 dynamite bundles .",rewardGold=202200,rewardXP=6140,rewardItems={29978,29979,29980,39811,39873,39875,39877,53225,53253,53255,57451,57452,57453,131384,131454,140255,220118,223440,223442,223451,223467},starts={{npcID=130030}},ends={{npcID=130030}},mapCandidates={npc={81},zone={1377}},questType="standard",questLines={{id=576,name="Silithus: The Wound",orderIndex=6,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[50047] = {id=50047,name="Free Samples",level=45,requiredLevel=45,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9310,mapID=81,storyline={49976,49981,50046,50047,50048,50049,50056,50057,50226,50227,50228,50371,50372,50373,50374},description="The crown has ordered SI:7 to infiltrate the goblin mining operation and collect any information we can find on this mysterious new substance. My agents have infiltrated the camp, but the clock is ticking and we need to get our hands on some extracted ore samples fast. In other words, I need someone who can take the direct approach. Someone who can handle a fight against overwhelming odds and come out alive. Take the ore samples to Khargus Stonemantle for analysis when you return.",objectivesText="Collect 8 Mysterious Ore samples. Progress: What have ye got for me?",rewardGold=202200,rewardXP=6140,rewardItems={156711},starts={{npcID=131963}},ends={{npcID=132192}},mapCandidates={npc={81},zone={1377}},questType="standard",sourceQuests={49981},questLines={{id=576,name="Silithus: The Wound",orderIndex=7,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[50048] = {id=50048,name="The Seething Shore",level=45,requiredLevel=45,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9136,mapID=81,storyline={49976,49981,50046,50047,50048,50049,50056,50057,50226,50227,50228,50371,50372,50373,50374},description="We've received reports of an island off the coast of Silithus that is ripe with Azerite deposits. It is vital that we secure the island before the Horde learns of its existence. Master Mathias Shaw is personally leading the expedition force and has requested that you report for duty. Good luck!",objectivesText="Complete the Seething Shore battleground.",rewardGold=202200,rewardXP=6140,ends={{npcID=131963}},coords={mapID=81,source="quest_giver",x=0.694,y=0.176},mapCandidates={npc={81},zone={1377}},questType="standard",sourceQuests={50372},questLines={{id=576,name="Silithus: The Wound",orderIndex=12,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[50049] = {id=50049,name="The Speaker's Perspective",level=45,requiredLevel=45,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9310,mapID=81,storyline={49976,49981,50046,50047,50048,50049,50056,50057,50226,50227,50228,50371,50372,50373,50374},description="Sargeras has left a scar upon our world, <name>. A scar that will not soon heal... It appears that the scars between the Alliance and Horde have yet to heal as well. Too many lives have already been lost fighting to save Azeroth from destruction. I will not stay and watch this world lose more. I have a request for you before I go. Take this letter to Magni Bronzebeard . He is in Silithus seeking a way to heal the wound. The letter contains information that may prove valuable to him.",objectivesText="Deliver Khadgar's letter to Magni Bronzebeard in Silithus.",rewardGold=202200,rewardXP=6140,starts={{npcID=130032}},ends={{npcID=130216}},mapCandidates={npc={81},zone={1377}},questType="standard",sourceQuests={50373},questLines={{id=576,name="Silithus: The Wound",orderIndex=22,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[50052] = {id=50052,name="No Spies Allowed",level=45,requiredLevel=45,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=9310,mapID=81,storyline={49977,49982,50052,50053,50054,50055,50057,50230,50231,50232,50300,50341,50358,50360,50364},description="Hey <name>, I'm glad you're here. I'm in way over my head! Killer bugs, a strange substance... that GIANT sword sticking outta the ground... I don't have a good feelin' about this place! To make matters worse, I've been gettin' reports of Alliance spies snoopin' around the camp! Look kid, the Dark Lady has plans for this mysterious ore and I ain't going to be the one to dissapoint her, know what I mean? Get over to the mining camp and take out those SI:7 spies before they ruin the whole operation!",objectivesText="Kill 10 SI:7 Operatives in Silithus.",rewardGold=202200,rewardXP=6140,starts={{npcID=132045}},ends={{npcID=132045}},mapCandidates={npc={81},zone={1377}},questType="standard",sourceQuests={49982},questLines={{id=576,name="Silithus: The Wound",orderIndex=9,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[50053] = {id=50053,name="Lazy Prospectors!",level=45,requiredLevel=45,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=9310,mapID=81,storyline={49977,49982,50052,50053,50054,50055,50057,50230,50231,50232,50300,50341,50358,50360,50364},description="I've been around long enough to know you can never trust a goblin with an orc's work. Gallywix and his cartel may be serving the warchief, but we need to keep a close eye on them if we're going to get anything done! I've already noticed many of the workers loafing about and sleeping on the job. The Horde does not tolerate laziness! Get out there and put those lazy prospectors in their place!",objectivesText="Motivate 10 Lazy Prospectors .",rewardGold=202200,rewardXP=6140,starts={{npcID=132147}},ends={{npcID=132147}},mapCandidates={npc={81},zone={1377}},questType="standard",sourceQuests={49982},questLines={{id=576,name="Silithus: The Wound",orderIndex=10,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[50054] = {id=50054,name="The Seething Shore",level=45,requiredLevel=45,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=9136,mapID=81,storyline={49977,49982,50052,50053,50054,50055,50057,50230,50231,50232,50300,50341,50358,50360,50364},description="We've received reports of an island off the coast of Silithus that is ripe with Azerite deposits. It is vital that we secure the island before the Alliance learns of its existence. Nathanos Blightcaller is personally leading the expedition force and has requested that you report for duty. Go with honor!",objectivesText="Complete the Seething Shore battleground.",rewardGold=202200,rewardXP=6140,ends={{npcID=132147}},coords={mapID=81,source="quest_giver",x=0.658,y=0.548},mapCandidates={npc={81},zone={1377}},questType="standard",sourceQuests={50358},questLines={{id=576,name="Silithus: The Wound",orderIndex=13,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[50055] = {id=50055,name="The Speaker's Perspective",level=45,requiredLevel=45,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=9310,mapID=81,storyline={49977,49982,50052,50053,50054,50055,50057,50230,50231,50232,50300,50341,50358,50360,50364},description="Sargeras has left a scar upon our world, <name>. A scar that will not soon heal... It appears that the scars between the Alliance and Horde have yet to heal as well. Too many lives have already been lost fighting to save Azeroth from destruction. I will not stay and watch this world lose more. I have a request for you before I go. Take this letter to Magni Bronzebeard . He is in Silithus seeking a way to heal the wound. The letter contains information that may prove valuable to him.",objectivesText="Deliver Khadgar's letter to Magni Bronzebeard in Silithus. Progress: What do ye have for me, <class>?",rewardGold=202200,rewardXP=6140,starts={{npcID=130033}},ends={{npcID=130216}},mapCandidates={npc={81},zone={1377}},questType="standard",sourceQuests={50360},questLines={{id=576,name="Silithus: The Wound",orderIndex=23,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[50058] = {id=50058,name="The Witch's Pet",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={50058},description="I've seen her! The witch! Every once in a while she comes down to the cave, checking on her pet. I've never seen a spider so large! She spreads her spell, cursing all of the animals in these woods to follow her command and attack us. The broodmother laid all these eggs, and they're hatching into more possessed beasts! Take her out, and perhaps the infestation will stop.",objectivesText="Kill the Mossfang Matriarch .",rewardGold=514800,rewardXP=1770,starts={{npcID=134325}},ends={{npcID=129669}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={48369}},
[50059] = {id=50059,name="Can't Hear A Thing",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={47755,50002,50005,50026,50059},description="These snake wenches show up and everyone loses their minds! All my men are head over heels for these things. Personally, I don't see it. I mean, I sort of get the appeal, but the wings for arms and snake tails are a big turn off. There's a big one in a cave to the east. She's got a whole heap of suitors. I need them back to work. Go give her a wallop and get everyone back here.",objectivesText="Kill Anthemusa .",rewardGold=257400,rewardXP=1415,rewardItems={160452},starts={{npcID=131775}},ends={{npcID=131775}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={50026},questLines={{id=5437,name="A Sirens Song",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[50063] = {id=50063,name="Fighting With Fire",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49939,50001,50036,50063,50090,50092,50172,50177,50238,50251,50903},description="Excellent! Now that we have these lovely Liquid Fire flasks prepared we have one last thing to do: Test them out! There are some of those large abominations lurking about in the woods above my home. I think they would make excellent test subjects for our little alchemical experiment, wouldn't you say?",objectivesText="Test the Liquid Fire flasks on 3 Briarwood Bulwarks . Progress: Help!",rewardGold=257400,rewardXP=2765,rewardItems={155159,155162,156710,156828},rewardChoices={155162,155159},starts={{npcID=131448}},ends={{npcID=131469}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50036},questLines={{id=5442,name="Falconhurst",orderIndex=9,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50064] = {id=50064,name="Don't Go in the Basement",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50064,50070,50161,50162,50165,50168,50264,50343,50359,50493,50504,50534,50553},description="We checked everywhere... well, <gulps> everywhere except the basement. B-b-but, dad told me never to go down there. He said it's dark, scary, and dangerous to go alone... I could be eaten by a brue! I don't even know what that is, but I don't wanna be eaten! <name>, do you think you could go down first?",objectivesText="Enter the basement.",rewardGold=257400,rewardXP=4115,rewardItems={160331,160346},rewardChoices={160331,160346},starts={{npcID=132017}},ends={{npcID=132647}},mapCandidates={npc={942},zone={9042}},questGiverID=132017,questType="standard",sourceQuests={50070,50359},questLines={{id=5451,name="Not the Bees!",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50065] = {id=50065,name="A Reason to Stay",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50041,50065,50069,50088},description="<You find a pocketwatch on the ground. It is dirty, but still works. It was taken care of well. Perhaps there are other objects that Goldfield wasn't able to grab before he had to hole up in his house. He might appreciate it if you brought them to him.>",objectivesText="Search the Goldfield Farmstead for additional keepsakes. Progress: For the last time, I'm not leaving! I was here first, THEY can leave!",rewardGold=257400,rewardXP=4115,rewardItems={133510,142555,155824,155877,156577,156578,156648,157849,157850,160558,160561},ends={{npcID=129808}},startObjects={{objectID=244983,mapID=942,x=0.498,y=0.735}},coords={mapID=942,source="quest_giver",x=0.507,y=0.75},mapCandidates={npc={942},zone={9042}},questType="standard",questLines={{id=738,name="Goldfield's War",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50069] = {id=50069,name="Goldfield's War",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50041,50065,50069,50088},description="I'm not leaving. I'm never leaving. Those quilboar, they killed them. I gave her the watch, told her to hurry. Grab our boy and get to the house while I got the gun... <Goldfield is choking back tears.> I won't leave. Our family has our roots here. They would want me to stay, don't you understand? This is our farm. My boy, he wanted to join the militia. I made him a sword... <Goldfield takes a deep breath.> Now you know. Help me retake my farm. Grab a gun and let's kill every last one.",objectivesText="Defeat the quilboar invaders. Progress: This is MY home!",rewardGold=514800,rewardXP=5145,rewardItems={133510,155824,155877,156577,156578,156648,157849,157850,160558,160561},starts={{npcID=129808}},ends={{npcID=129808}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50041,50065},questLines={{id=738,name="Goldfield's War",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50070] = {id=50070,name="Detective Mildenhall",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50064,50070,50161,50162,50165,50168,50264,50343,50359,50493,50504,50534,50553},description="Hmm... okay, okay, let's think. If you were my dad and you accidentally set loose a bunch of honey monsters all over the place, what would you do? Well, okay, you would probably beat all of them up. But he probably ran away. If he left in a hurry, maybe he left something for us to find.",objectivesText="Search the Mildenhall Meadery for clues. Progress: Did you find anything else?",rewardGold=257400,rewardXP=4115,rewardItems={156628},starts={{npcID=132017}},ends={{npcID=132017}},mapCandidates={npc={},zone={9042}},questGiverID=132017,questTurnInID=132017,questType="standard",sourceQuests={50343},questLines={{id=5451,name="Not the Bees!",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50071] = {id=50071,name="For the Light!",level=40,requiredLevel=40,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=1519,mapID=84,storyline={49266,49698,50071},description="The Lightforged Draenei will be happy to join the Alliance. Our cause is now yours, <name>. Let us return to Stormwind. Captain Fareeya will speak with our people.",objectivesText="Return to Stormwind and speak with Aysa Cloudsinger to hear the end of his tale.",rewardGold=341600,rewardXP=5465,rewardItems={155656,156486},starts={{npcID=130810}},ends={{npcID=126301},{npcID=126332}},mapCandidates={npc={84},zone={1519}},questGiverID=130810,questType="standard",sourceQuests={49266},questLines={{id=533,name="Allies of the Alliance: Lightforged Draenei",orderIndex=2,flags=0}},db2PoiMapID=1860,db2PoiUiMapID=940},
[50074] = {id=50074,name="Brutal Boost",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49801,49810,49814,49870,50074,50150,50154,50252,50268,50297},description="The Aggression Formula is ready and I need you to inject Ben'jin with it. Let's show the world, and the witch doctor, that well researched, dramatically overpowered, double-blind, peer-reviewed, super goblin science is the right way to do, uh, pretty much anything!",objectivesText="Administer the Aggression Formula to Gentle Ben'jin. Progress: This is exciting, isn't it?",rewardGold=257400,rewardXP=1415,rewardItems={156475},starts={{npcID=130905}},ends={{npcID=130905}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49801},questLines={{id=5401,name="The Last of Their Kind",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[50076] = {id=50076,name="Rally the Warriors",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={49569},description="We have learned so much and came so far thanks to you and de Horde, but all of it will amount to nothing if de blood trolls defeat us here. We've all worked hard since we first set foot within dis accursed swamp, without a chance to even get any sleep or have a decent meal. Dey are some of de finest soldiers I've ever encountered, but even dey have their limits. Let us remind dem what we are fighting for!",rewardGold=119340,rewardXP=1385,starts={{npcID=121288}},ends={{npcID=121288}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={49569},questLines={{id=524,name="Bleeding the Blood Trolls",orderIndex=1,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=77,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[50078] = {id=50078,name="Undying Totems",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="De blood trolls are putting up quite de fight. Dey are raising de very dead to go against us! Their necromancers are raising de dead with de help of totems fueled with blood magic. Destroying dem should take de pressure off our troops.",rewardGold=238680,rewardXP=2765,rewardCurrencies={{id=1553,amount=50}},starts={{npcID=132333}},ends={{npcID=132333}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={50076},questLines={{id=524,name="Bleeding the Blood Trolls",orderIndex=3,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=79,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[50079] = {id=50079,name="Boom goes the Bomb",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={50138,50081,50082},description="Just look at 'em... those blood trolls are holed up pretty good down there in that fortress of theirs. Multiple defensive lines, lots of equipment, they got everything. They're completely unprepared for us! I almost feel sorry for 'em! Let's start off by showing 'em what we think of their cute attempts at making barricades . Here, take these smoke grenades and put a signal right on top of them. We'll see how well they hold up to high explosives!",rewardGold=257400,rewardXP=2765,rewardItems={159827},starts={{npcID=132988}},ends={{npcID=133125}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={50078,50138},questLines={{id=524,name="Bleeding the Blood Trolls",orderIndex=4,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=80,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[50080] = {id=50080,name="Raiding the Raiders",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={50080},objectivesText="Assault Koramar",rewardGold=455280,rewardXP=1415,rewardItems={157029,159827},mapCandidates={npc={},zone={8500}},questType="standard",sourceQuests={50083},db2Objectives={{text="Assault Koramar",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Raiding the Raiders",db2PoiMapID=1642,db2PoiUiMapID=863},
[50081] = {id=50081,name="The Road of Pain",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={50138,50079,50082},description="My people continue to be captured and hauled into de blood trolls' village for de slaughter, to be used as fuel for their dark rituals. Just ahead, I can see some of de captives who fell along de path. I hear their cries as de blood trolls perform their vile rituals upon dem. We cannot leave my people to die in de swamp, ! Take dese bandages and save any Zandalari you encounter down dere.",rewardGold=257400,rewardXP=2765,starts={{npcID=132333}},ends={{npcID=132333},{npcID=133125}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={50078,50138},questLines={{id=524,name="Bleeding the Blood Trolls",orderIndex=5,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=81,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[50082] = {id=50082,name="Target of Opportunity",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={50138,50079,50081},description="It seems our actions here have not gone unnoticed, . I feel a dark presence ahead. Ateena is near! Dis is our chance! If we strike now, we can deal a huge blow to de blood trolls! We must move!",rewardGold=257400,rewardXP=2765,rewardChoices={159025,159026,159027,159028,159034,159035,159036,159037},starts={{npcID=133125}},ends={{npcID=133125}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={50079,50081},questLines={{id=524,name="Bleeding the Blood Trolls",orderIndex=6,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=82,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[50083] = {id=50083,name="The Crawg Ma'da",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={50083},series={50085},description="No matter what we do, as long as dem blood trolls have their village here, dey gonna be a threat. We gonna put an end to dat threat! Amaka be da strongest blood troll I ever seen, and she be right across da way there. She be feedin' da bodies of da Zandalari ta her pet crawgs, makin' dem big, fat, and deadly. It be time for revenge, and we be doin' it wit' da help of her own pets. Go kill a crawg and cut its poison gland out of its belly. With it, ya can weaken Amaka and put an end to her.",objectivesText="Obtain a Crawg Poison Gland and slay Amaka the Crawg Ma'da .",rewardGold=514800,rewardXP=3455,rewardItems={156868,159827},starts={{npcID=133471}},ends={{npcID=133338}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={50082}},
[50084] = {id=50084,name="Back On Your Feet, Soldier",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={50084},description="I figured any soldiers we be coming across might be wantin' some revenge, so I brought along some extra weapons just in case. See up ahead? Dem cages be full of trolls awaitin' der turn ta die. We gonna swoop in der and be da answers to der prayers! Go and arm as many of dem as ya can, revenge gonna be sweet!",objectivesText="Give weapons to 10 Zandalari Captives .",rewardGold=257400,rewardXP=2765,mapCandidates={npc={},zone={8500}},questType="standard"},
[50085] = {id=50085,name="A Message of Blood and Fire",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={50085},series={50083},description="Look at what I be findin' here. Dis one had a magic wand in his hand. < Rokhan shuts his eyes for a moment.> Mmmmm... it be warm. Mojo of fire be within. Perfect! Take dis ting an' give 'em a taste of their own firepower. Burn da whole village down!",objectivesText="Use the Wand of Embers to set ablaze 8 Blood Troll huts in Agwamar.",rewardGold=257400,rewardXP=2765,rewardItems={156931,159827},starts={{npcID=133338}},ends={{npcID=133475}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={50083},startItems={156939}},
[50087] = {id=50087,name="Ateena's Fall",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={50808},description="You have proven to be a much greater ally dan I could have ever hoped. Thanks to you and your Horde, we have come dis far. Now, there is only one thing dat remains. We must confront de leader of de blood trolls and put an end to their dark plot once and for all. Without Ateena's mojo to protect it, we can finally destroy dat monstrosity of theirs before it can be unleashed upon Zuldazar. You know what must be done. First, I must prepare myself. Go. I will join you when de battle has begun.",rewardGold=772200,rewardXP=4150,rewardChoices={155332,155333,155334,155335,159010,159011,159012,159029},rewardCurrencies={{id=1553,amount=150}},starts={{npcID=133476}},ends={{npcID=133480}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={52073},questLines={{id=524,name="Bleeding the Blood Trolls",orderIndex=8,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=84,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[50088] = {id=50088,name="Golden Fields Forever",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50041,50065,50069,50088},description="I can take care of the rest. That ettin would have given me trouble if I was by myself, so you have my thanks. I would ask you for one more favor. My wife, she loved the carnations that grow by the water's edge. If you could gather some, there's a nice spot under a tree by the river. We loved to go there when the sun set after our days in the fields. Our boy would run around, catching bugs, making reed whistles...",objectivesText="Lay Farmer Goldfield 's family to rest. Progress: That's that, then.",rewardGold=128700,rewardXP=2060,rewardItems={133510,155824,155877,156577,156578,156648,157849,157850,160558,160561},rewardCurrencies={{id=1553,amount=100}},starts={{npcID=129808}},ends={{npcID=129808}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50069},questLines={{id=738,name="Goldfield's War",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50090] = {id=50090,name="Building Defenses",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49939,50001,50036,50063,50090,50092,50172,50177,50238,50251,50903},description="We'll be able to push those monsters back now, but my defenders won't stand a chance unless we build a forward barricade for protection. There should be plenty of lumber to build a barricade near the entrance to town.",objectivesText="Collect lumber to build forward barricades. Progress: We've pushed the front line out. That will give us some room.",rewardGold=257400,rewardXP=2765,rewardItems={158611,158612,158613,158614,160189,160190,160191,160192},rewardChoices={160189,160190,160191,160192,158611,158612,158613,158614},starts={{npcID=131442}},ends={{npcID=131442}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50903},questLines={{id=5442,name="Falconhurst",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50091] = {id=50091,name="Village Repair",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={50091},objectivesText="Destroy signs of witchcraft",rewardGold=455280,rewardXP=1415,rewardItems={156710,156828},mapCandidates={npc={},zone={8721}},questType="standard",sourceQuests={49939},db2Objectives={{text="Destroy signs of witchcraft",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Village Repair",db2PoiMapID=1643,db2PoiUiMapID=896},
[50092] = {id=50092,name="Curiously Strong",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49939,50001,50036,50063,50090,50092,50172,50177,50238,50251,50903},description="I imagine the fires spread while I was down here, yes? First order of business then; making sure the town doesn't burn down! Help solve that problem and I shall be free to assist you in... whatever it is? Let's see... Yes! Here! Take these. They proved to be bit too... intense for most people, but you seem like a stout sort. Just be sure you're facing the fires when you use them, and I'm certain those fires will be out in no time!",objectivesText="Use the Frost Breath Potion to put out the fires. Progress: If we don't stop the fires, they could spread!",rewardGold=257400,rewardXP=2765,rewardItems={156710,156828},starts={{npcID=131448}},ends={{npcID=131448}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50903},questLines={{id=5442,name="Falconhurst",orderIndex=7,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50110] = {id=50110,name="Bearers of Bad News",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={49405,49736,49737,49738,49740,49869,50110,52431,52750},series={49741,50787,50788,50789,50790,50795},description="We must report this attack to Lord Admiral Katherine Proudmoore and prove to her that Lady Ashvane is behind it. It won't be easy... Lady Ashvane and Katherine Proudmoore have been close friends for years. Quickly, let us make for Boralus!",objectivesText="Return to Boralus with Taelia .",rewardGold=30900,rewardXP=175,rewardItems={162522},starts={{npcID=142393}},ends={{npcID=135259}},mapCandidates={npc={895,1161},zone={8567}},questType="standard",sourceQuests={49736,49740,49741},questLines={{id=588,name="Defenders of Daelin's Gate",orderIndex=8,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=39,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[50111] = {id=50111,name="Totems, Totems, Totems!",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50111},description="<This totem pulses with energy, releasing it into the nearby idols and thorns. It looks rather fragile... It would be a shame if something happened to it.>",objectivesText="Destroy the Brambleguard Totems in Briarback Kraul.",rewardGold=257400,rewardXP=4115,rewardItems={175199,175200,175201,175202,175231,175232,175233,175238},ends={{npcID=130190},{npcID=133953}},startObjects={{objectID=282457,mapID=942,x=0.44,y=0.724}},coords={mapID=942,source="quest_giver",x=0.576,y=0.665},mapCandidates={npc={942},zone={9042}},questType="standard"},
[50112] = {id=50112,name="Casting the First Stone",level=50,requiredLevel=50,faction="horde",requiredProfessions={"alchemy"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={50112,50113,50115,50116,50117,50118,50119,50120},description="Hey dere <name>, gimme a hand with dis, would ya? <Kumali motions you over to her.> I got dis recipe dat I've been trying to remember de rest of, but I'm having de hardest time coming up with de right ingredients. Ya see, my partner ran off with de other half of de recipe on account of a disagreement we had. But dis stone, it's a treasure like no other. Grab some vials and start mixing dese ingredients together. Let's see if dey are de right ones.",objectivesText="Craft a Potion of Durability and a Potion of Shifting States using the recipes given to you. You can find the ingredients you need in Kumali's shop. Progress: I will never ask for de other half of de recipe back from dat... dat... imbecile. I'll figure it out, ya see.",rewardGold=58500,rewardXP=1705,rewardItems={156653,156654,166371,166372,166373,166374},starts={{npcID=122703}},ends={{npcID=122703}},mapCandidates={npc={1165},zone={8670}},questType="standard",questLines={{id=900,name="8.1.5 Alchemy - Horde",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[50113] = {id=50113,name="Ocular Extracts",level=10,requiredLevel=10,faction="horde",requiredProfessions={"alchemy"},categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=1165,storyline={50112,50113,50115,50116,50117,50118,50119,50120},series={50115,50116},description="So dere's a creature in dese lands whose eyes are perfect for alchemical recipes. Dey might just be de thing we need to finish dis project. Although, I don't remember seeing dem on de full recipe list de last time I saw it, ya see... But my memory isn't quite what it used to be. Gah! I'm rambling too much. Get me some eyes, will ya, <name>?",objectivesText="Gather 10 Razorwing Eyes and return them to Kumali. Then observe as she tries to make the stone with them. Progress: Make sure to gather de eyes after de creature is dead, otherwise dey make de most horrible sound when ya try to take dem out.",rewardGold=257400,rewardXP=1415,rewardItems={156806},starts={{npcID=122703}},ends={{npcID=122703}},mapCandidates={npc={1165},zone={8499}},questType="standard",sourceQuests={50112},questLines={{id=900,name="8.1.5 Alchemy - Horde",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[50114] = {id=50114,name="Hammering Out Information",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"blacksmithing"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={50114,50123,50270,50275},series={50270},description="I guess you noticed it requires a special anvil to make it. And I suppose you want to know where to find a Khaz'gorian Smithing Anvil? Well, I don't know where you can find one, not to mention I never said you'd be able to actually craft the dang thing. Now if you wouldn't mind, I have more of these recipes to sell.",objectivesText="Press Grix Barlow for more information about where to find a Khaz'gorian Smithing Anvil. Progress: That recipe really is worth what you paid for it, regardless of whether you can craft it or not.",rewardGold=25740,rewardXP=175,starts={{npcID=133536}},ends={{npcID=133536}},mapCandidates={npc={},zone={8568}},questGiverID=133536,questTurnInID=133536,questType="standard",sourceQuests={50123},questLines={{id=896,name="8.1.5 Blacksmithing - Alliance",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[50115] = {id=50115,name="Changing the Scenery",level=10,requiredLevel=10,faction="horde",requiredProfessions={"alchemy"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={50112,50113,50115,50116,50117,50118,50119,50120},series={50113,50116},description="Or maybe de problem is dat we don't need regular reagents. Maybe we need something dat only comes from being transmuted. Anything's worth a shot at dis point. Here is a recipe my old partner left behind. He used to go out to de Slough and change de shrubs into bubbles, ya see. Why, you might ask? 'Cause he loved transmuting everything. Part of de reason we never saw eye to eye. Anyways, bring me back some of dose bubbles and we'll see if we can use dem to make dis stone.",objectivesText="Go to The Slough and transmute Barberry Shrubs into Shrubbery Bubbles and gather 6 of them. Bring them back to Kumali and observe as she tries to use them to make the stone. Progress: I've seen him using dem in lots of his projects, so there has to be some alchemical qualities to dem.",rewardGold=257400,rewardXP=1415,rewardItems={156660},starts={{npcID=122703}},ends={{npcID=122703}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={50112},questLines={{id=900,name="8.1.5 Alchemy - Horde",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[50116] = {id=50116,name="A Possible Solution",level=10,requiredLevel=10,faction="horde",requiredProfessions={"alchemy"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={50112,50113,50115,50116,50117,50118,50119,50120},series={50113,50115},description="None of dese things are working. I can't believe I'm saying dis, but I think you're gonna have to find Zukashi . Maybe you could convince him to give up de other half of de recipe. He's pretty full of himself, but he isn't unreasonable. Last time I heard, he's staying in Nazmir near Gloom Hollow. Maybe it's best to tell him dis isn't about me.",objectivesText="Travel to Nazmir and seek out Zukashi .",rewardGold=25740,rewardXP=175,starts={{npcID=122703}},ends={{npcID=132680}},mapCandidates={npc={863,1165},zone={8670}},questType="standard",sourceQuests={50113,50115},questLines={{id=900,name="8.1.5 Alchemy - Horde",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[50117] = {id=50117,name="A Deathly Draught",level=10,requiredLevel=10,faction="horde",requiredProfessions={"alchemy"},categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={50112,50113,50115,50116,50117,50118,50119,50120},series={50118,50119,50120},description="De first thing I'd like you to do for me is to gather some deathshroom . Don't worry if you're not skilled at herbalism, they're very easy to pick. Dey typically grow where death lingers in the air. I'd try to de Frogmarsh to de southeast. De trolls dere have been making sacrifices of de creature dat inhabit de area.",objectivesText="Collect 15 Deathshrooms . Progress: Have you finally acquired my mushrooms? It's a simple task, even for someone like you.",rewardGold=257400,rewardXP=1415,rewardItems={156658},starts={{npcID=132680}},ends={{npcID=132680}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={50116},questLines={{id=900,name="8.1.5 Alchemy - Horde",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[50118] = {id=50118,name="A Stone's Throw",level=10,requiredLevel=10,faction="horde",requiredProfessions={"alchemy"},categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={50112,50113,50115,50116,50117,50118,50119,50120},series={50117,50119,50120},description="Now dis ingredient you might have some fun getting, little mixah. I'm gonna give you dese stones. They're able to turn things into other things. Dose blood trolls, de ones giving de rest of us a bad name? Dey drink de weirdest things and it taints their bodies. I need their blood to finish my work here, but without de taint. Dese stones will turn dem into weaker creatures. Although, sometimes de stones turn dem into other things... Be careful with dem.",objectivesText="Use the Bag of Transmutation Stones on blood trolls and kill them. Collect 8 Vials of Altered Blood from them. Progress: Ya never know what you'll get with transmuting things until ya try. Ain't dat right?",rewardGold=257400,rewardXP=1415,rewardItems={156664,156831},starts={{npcID=132680}},ends={{npcID=132680}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={50116},questLines={{id=900,name="8.1.5 Alchemy - Horde",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[50119] = {id=50119,name="Chemically Compounded",level=10,requiredLevel=10,faction="horde",requiredProfessions={"alchemy"},categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={50112,50113,50115,50116,50117,50118,50119,50120},series={50117,50118,50120},description="Now dat I have everything I need, I can finish dis project. My latest transmuation will be my finest yet! But dis is not de place to test it. It could draw too much attention. If you want to see it for yourself, little mixah, meet me to de north. Dere is a cave dere dat should be a safe spot for testing dis out.",objectivesText="Meet Zukashi at the cave he mentioned. And be ready for anything to happen.",rewardGold=514800,rewardXP=1770,starts={{npcID=132680}},ends={{npcID=132680}},mapCandidates={npc={863},zone={8500}},questTurnInID=132680,questType="standard",sourceQuests={50117,50118},questLines={{id=900,name="8.1.5 Alchemy - Horde",orderIndex=6,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[50120] = {id=50120,name="A Recipe for Success",level=10,requiredLevel=10,faction="horde",requiredProfessions={"alchemy"},categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=1165,storyline={50112,50113,50115,50116,50117,50118,50119,50120},series={50117,50118,50119},description="Looking it over more closely, you're convinced that this must be the missing half of the recipe you came for. An odd signature completes the recipe, signed, \"Silas Darkmoon\". Kumali should be very pleased to see this once again.",objectivesText="Bring the torn paper back to Kumali.",rewardGold=25740,rewardXP=175,ends={{npcID=122703}},startObjects={{objectID=280957,mapID=863,x=0.629,y=0.289}},coords={mapID=1165,source="quest_giver",x=0.422,y=0.38},mapCandidates={npc={1165},zone={8500}},questType="standard",sourceQuests={50119},questLines={{id=900,name="8.1.5 Alchemy - Horde",orderIndex=7,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[50121] = {id=50121,name="Casting the First Stone",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"alchemy"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={50121,50122,50124,50125,50126,50127,50128,50129},description="Would you mind helping me out with something, <name>? <Elric motions you over to him.> You see, I have this recipe that, well, I only have half of currently. I've been trying to remember the other half but just can't seem to recall it. My EX-partner tore the recipe and ran off with the other half over a disagreement we were having. But the stone it makes is invaluable. How about you grab some vials and start mixing the ingredients on this list. Perhaps together we can figure this out.",objectivesText="Craft a Potion of Durability and a Potion of Shifting States using the recipes given to you. You can find the ingredients you need in Elric's shop. Progress: I wouldn't dare ask for the other half back, not after what Quintin said to me. I'll get this mystery figured out, you'll see.",rewardGold=58500,rewardXP=1705,rewardItems={156653,156654,166371,166372,166373,166374},starts={{npcID=132228}},ends={{npcID=132228}},mapCandidates={npc={1161},zone={8568}},questType="standard",questLines={{id=899,name="8.1.5 Alchemy - Alliance",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[50122] = {id=50122,name="Ocular Extracts",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"alchemy"},categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=1161,storyline={50121,50122,50124,50125,50126,50127,50128,50129},series={50124,50125},description="My next idea involves a creature whose eyes are useful for certain alchemical recipes. At least for potions they are. Hopefully they're just what we need for this and there aren't any further... miscalculations. Although, I don't entirely recall seeing them on the recipe's ingredient list... but my memory isn't exactly as good as it used to be. Oh, you caught me rambling. How about you get those eyes and I'll start making the preparations for them.",objectivesText="Gather 10 Highlands Mauler Eyes and return them to Elric. Progress: Oh, I do hope you gathered the eyes post mortem. Those creatures make the most awful sound if you try to extract them while they're still alive.",rewardGold=257400,rewardXP=1415,rewardItems={156657},starts={{npcID=132228}},ends={{npcID=132228}},mapCandidates={npc={1161},zone={9042}},questType="standard",sourceQuests={50121},questLines={{id=899,name="8.1.5 Alchemy - Alliance",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[50123] = {id=50123,name="A Recipe For the Ages",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"blacksmithing"},categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=1161,storyline={50114,50123,50270,50275},description="Yo, <name>, over here! You've look like you've been hammering away for a while. I can smell the flux on ya! <Grix gives you a wide grin.> Listen, I've got a recipe for the most amazing blacksmith hammer you've ever laid your eyes on. And I'd be willing to let it go for a bit of ore. Revlis ore to be exact. It's a little rare, but you can find plenty of it over in Gol Koval in Drustvar. The elementals there are practically made of it. Bring me back a haul of it, and the recipe's yours!",objectivesText="Bring Grix Barlow back 30 pieces of Revlis Ore from Gol Koval in Drustvar. Progress: This recipe is probably worth a thousand, no TEN thousand gold! Blacksmiths all over will be envious of you, you'll see.",rewardGold=234000,rewardXP=6815,rewardItems={152839,156875},starts={{npcID=133536}},ends={{npcID=133536}},mapCandidates={npc={},zone={8499}},questGiverID=133536,questTurnInID=133536,questType="standard",questLines={{id=896,name="8.1.5 Blacksmithing - Alliance",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[50124] = {id=50124,name="Changing the Scenery",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"alchemy"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={50121,50122,50124,50125,50126,50127,50128,50129},series={50122,50125},description="The stone this recipe becomes is a transmutation stone. What if the missing reagents to make it come from something that's gone through the transmutation process? I'm willing to try anything at this point. Here's an old recipe my ex-partner devised. He used to go out to Stormsong Valley, just south of the Highland Flats and change the shrubs there into bubbles. Bring back some of those bubbles and we'll see if they're what we've been missing.",objectivesText="Go to Stormsong Valley and transmute Barberry Shrubs into Shrubbery Bubbles and gather 6 of them. Bring them back to Elric and observe as he tries to use them to make the stone. Progress: I've seen him use those globes in some of his projects in the past, so there is clearly some alchemical properties to them.",rewardGold=17450,rewardXP=1415,rewardItems={156660},starts={{npcID=132228}},ends={{npcID=132228}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={50121},questLines={{id=899,name="8.1.5 Alchemy - Alliance",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[50125] = {id=50125,name="A Possible Solution",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"alchemy"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={50121,50122,50124,50125,50126,50127,50128,50129},series={50122,50124},description="Nothing appears to be working. I can't believe I'm proposing this but I actually think we need to contact Quintin. Well, you should, as I doubt he'll speak to me. Perhaps you could convince him to part with the other half of the recipe? Last time I heard, he was staying in Drustvar near Arom's Stand. There's a lot of alchemists in those parts, but he shouldn't be too hard to find. Best not to tell him I sent you. He may not be as forthcoming with the recipe.",objectivesText="Travel to Drustvar and seek out Quintin Whalgrene .",rewardGold=1745,rewardXP=175,starts={{npcID=132228}},ends={{npcID=132347}},mapCandidates={npc={896,1161},zone={8568}},questType="standard",sourceQuests={50122,50124},questLines={{id=899,name="8.1.5 Alchemy - Alliance",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50126] = {id=50126,name="A Deathly Draught",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"alchemy"},categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50121,50122,50124,50125,50126,50127,50128,50129},series={50127,50128,50129},description="The first thing I'd like you to do for me is to gather some deathshroom . Don't worry if you're not skilled at herbalism, they're very easy to pick. They typically grow where death lingers in the air. I'd try to the Crimson Forest to the south. The creatures that have overrun it seem to be covered in deathly magics.",objectivesText="Collect 15 Deathshrooms . Progress: Have you finally acquired my mushrooms? It's a simple task, even for someone like you.",rewardGold=257400,rewardXP=1415,rewardItems={156658},starts={{npcID=132347}},ends={{npcID=132347}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50125},questLines={{id=899,name="8.1.5 Alchemy - Alliance",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50127] = {id=50127,name="A Stone's Throw",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"alchemy"},categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50121,50122,50124,50125,50126,50127,50128,50129},series={50126,50128,50129},description="You may enjoy getting this next reagent for me. I have some special stones that have transmutative qualities, especially on living things. It's not too unlike the one you're trying to make. The witches that plague these lands are imbued with magic. As is their blood. I need their blood to finish my latest project, but in an altered form. These stones should turn them into weaker creatures. Although, sometimes the opposite occurs... I'd recommend handling them with care.",objectivesText="Use the Bag of Transmutation Stones on witches and kill them. Collect 8 Vials of Altered Blood from them. Progress: You never truly know what a transmutation will yield until you try it. Wouldn't you agree, apprentice?",rewardGold=257400,rewardXP=1415,rewardItems={156665,156687},starts={{npcID=132347}},ends={{npcID=132347}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50125},questLines={{id=899,name="8.1.5 Alchemy - Alliance",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50128] = {id=50128,name="Chemically Compounded",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"alchemy"},categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50121,50122,50124,50125,50126,50127,50128,50129},series={50126,50127,50129},description="That appears to be everything. This latest transmutation will be my finest yet. And your prize waits at its completion, apprentice. But I don't believe this is an appropriate place to test it out. It may draw too much attention. There's a cave not terribly far from here which would prove to be a more suitable setting for such a test. Meet me there when you're ready to witness why transmutation is the only branch of alchemy worth learning.",objectivesText="Meet Quintin at the cave he mentioned. And be ready for anything to happen. Progress: This seems to contain some of Quintin's things.",rewardGold=514800,rewardXP=1770,starts={{npcID=132347}},ends={{npcID=132347}},mapCandidates={npc={896},zone={8721}},questTurnInID=132347,questType="standard",sourceQuests={50126,50127},questLines={{id=899,name="8.1.5 Alchemy - Alliance",orderIndex=6,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50129] = {id=50129,name="A Recipe for Success",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"alchemy"},categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=1161,storyline={50121,50122,50124,50125,50126,50127,50128,50129},series={50126,50127,50128},description="Looking it over more closely, you're convinced that this must be the missing half of the recipe you came for. An odd signature completes the recipe, signed, \"Silas Darkmoon\". Elric should be very pleased to see this once again.",objectivesText="Bring the torn paper back to Elric.",rewardGold=25740,rewardXP=175,ends={{npcID=132228}},startObjects={{objectID=280755,mapID=896,x=0.629,y=0.289}},coords={mapID=1161,source="quest_giver",x=0.741,y=0.065},mapCandidates={npc={1161},zone={8721}},questType="standard",sourceQuests={50128},questLines={{id=899,name="8.1.5 Alchemy - Alliance",orderIndex=7,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[50130] = {id=50130,name="A Friendly Gesture",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=3521,mapID=102,storyline={9701,9702,9708,9709,9716,9718,9720,9724,9726,9728,9729,9731,9732,9739,9743,9747,9769,9770,9771,9772,9773,9774,9780,9781,9782,9783,9786,9787,9788,9790,9791,9801,9803,9814,9816,9820,9822,9823,9830,9833,9834,9835,9839,9841,9842,9845,9846,9847,9848,9894,9896,9898,9899,9901,9902,9903,9904,9905,9919,10096,10115,10118,50130,50131},description="Life in the marsh has not been easy, <name>. We want to live in harmony with those that call it home, but our enemies out here threaten our existence. Work with us. Help the people of Sporeggar thrive.",objectivesText="Reach Friendly with Sporeggar .",rewardXP=175,starts={{npcID=17924}},ends={{npcID=17924}},mapCandidates={npc={102},zone={3521}},questType="standard",sourceQuests={9919},questLines={{id=463,name="Zangarmarsh",orderIndex=39,flags=0}},db2PoiMapID=530,db2PoiUiMapID=102},
[50131] = {id=50131,name="An Outside Perspective",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=3521,mapID=102,storyline={9701,9702,9708,9709,9716,9718,9720,9724,9726,9728,9729,9731,9732,9739,9743,9747,9769,9770,9771,9772,9773,9774,9780,9781,9782,9783,9786,9787,9788,9790,9791,9801,9803,9814,9816,9820,9822,9823,9830,9833,9834,9835,9839,9841,9842,9845,9846,9847,9848,9894,9896,9898,9899,9901,9902,9903,9904,9905,9919,10096,10115,10118,50130,50131},description="Thank you for everything you have done for my people, but they are still scared of outsiders. Fight the bog lords and rescue the spore sacs in the Spawning Glen. The future of my people is at stake!",objectivesText="Reach Neutral with Sporeggar.",rewardXP=175,starts={{npcID=17923}},ends={{npcID=17923}},mapCandidates={npc={102},zone={3521}},questType="standard",sourceQuests={9739,9743},nextQuests={9919},questLines={{id=463,name="Zangarmarsh",orderIndex=37,flags=0}},db2PoiMapID=530,db2PoiUiMapID=102},
[50133] = {id=50133,name="Weed Whacking",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={50133},objectivesText="Farmlands cleared",rewardGold=455280,rewardXP=1415,rewardItems={133510,155824,155877,156577,156578,156648,157849,157850,160558,160561},mapCandidates={npc={},zone={9042}},questType="standard",sourceQuests={49755},db2Objectives={{text="Farmlands cleared",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Weed Whacking",db2PoiMapID=1643,db2PoiUiMapID=942},
[50134] = {id=50134,name="Gadgets and Gizmos Aplenty",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50134,50135,50136},description="The militia may have given up on us, but we haven't given up on me! I'm a bit of a tinker, and I find that my harvest golems are better than any hired help I've ever had. They just need regular maintenance to keep running. Of course the Briarback are now taking over my fields, and my farmhands have gone into disrepair. If you head out into the fields, can you grab the inner mechanisms from any of them that you find? That will stop them from exploding as well as help me plan my revenge.",objectivesText="Collect 10 Harvester Gizmos . Progress: Do you have the parts yet?",rewardGold=257400,rewardXP=4115,rewardItems={133510,155824,155877,156577,156578,156648,157849,157850,160558,160561},starts={{npcID=132118}},ends={{npcID=132118}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50158},questLines={{id=739,name="A Collapsing Crisis",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50135] = {id=50135,name="Stop Vining!",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50134,50135,50136},description="You may have noticed that the fields are a little... unstable right now. The Briarback have been busy, growing those large bramble vines and boring tunnels underneath the farm. The vines have always been an important part of their borders, and they're expanding! Go down into the lower area and see if you can find who or what is making those vines grow. There's no way that they're growing like that naturally. If we can stop the vines we can retake this area!",objectivesText="Slay the three Vinemasters.",rewardGold=257400,rewardXP=4115,rewardItems={133510,155824,155877,156577,156578,156648,157849,157850,160558,160561},starts={{npcID=132118}},ends={{npcID=132118}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50158},questLines={{id=739,name="A Collapsing Crisis",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50136] = {id=50136,name="Farming Stimulator",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50134,50135,50136},description="The plants have gone amok since you defeated their masters! Don't worry though, I've got a plan. I've been busy fixing up one of the farmhands that didn't go completely haywire. It should have enough juice for one more trip through the fields. We've got some serious technology in these harvesters. Their tools should be more than enough to take care of some small plants and even a couple quilboar. What do you say? You up for some farming the Stormsong way? Hop on in and get to work!",objectivesText="Use the Piloted Farmhand to slay 30 enemies. Progress: Take out as many of them as you can!",rewardGold=257400,rewardXP=4115,rewardItems={133510,155194,155195,155196,155197,155235,155824,155877,156577,156578,156648,157849,157850,160558,160561},rewardChoices={155235,155197,155194,155196,155195},starts={{npcID=132118}},ends={{npcID=132118}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50134,50135},questLines={{id=739,name="A Collapsing Crisis",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50138] = {id=50138,name="The Battle of Bloodfire Ravine",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,series={50079,50081,50082},description="It is time to strike out and end de blood troll threat once and for all! We travel back to Bloodfire Ravine, and dis time it is de blood trolls who will be sent running. Mount up, and together we will show dem we are a force to be reckoned with!",rewardGold=514800,rewardXP=3455,starts={{npcID=121288}},ends={{npcID=132333}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={50076},questLines={{id=524,name="Bleeding the Blood Trolls",orderIndex=2,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=78,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[50139] = {id=50139,name="The Missing Link",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="They are... everywhere... disguised... Encrypted... blueprints... Cipher... Pontus... watching me...",rewardGold=514800,rewardXP=5145,starts={{npcID=280727}},ends={{npcID=131248}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49975},questLines={{id=442,name="A House in Peril",orderIndex=19,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=20,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[50149] = {id=50149,name="A Weather Eye",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49926,50003,50149,50151,50173,50253,50446,50453,50457},description="It would be wise to get a lay of the land before we put together a plan of action. Inquisitor Notley is an expert falconer, and a reliable scout. He utilizes an ancient relic to see through the eyes of his falcon, allowing him to survey great distances. Unfortunately, Notley was injured during the fighting. Nothing serious, but it's left him unable to concentrate enough to control his falcon. Perhaps you could help?",objectivesText="Speak with Inquisitor Notley at Watchman's Rise to scout the areas surrounding Corlain. Progress: What news do you bring?",rewardGold=257400,rewardXP=2765,rewardItems={156722,156853,156855,157800},starts={{npcID=131636}},ends={{npcID=131636}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50003},questLines={{id=598,name="Corlain",orderIndex=2,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=40,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50150] = {id=50150,name="Setting the Mood",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49801,49810,49814,49870,50074,50150,50154,50252,50268,50297},series={49814,50154},description="De voodoo love incense and romantic meal are ready, <name>. Take dem and place dem at de feet of Maka'fon. Quickly, if you could. Dat smell is... overwhelmingly, horribly, disgusting. Could you move any faster? Away. From us. For de sake of de brutosaurs, of course.",objectivesText="Place and light the Voodoo Love Incense near Irritable Maka'fon and offer her the Romantic Brutosaur Meal. Progress: Best get dese stinking things over to Maka'fon soon, <name>. I guarantee it will get her in de mood.",rewardGold=128700,rewardXP=710,starts={{npcID=130929}},ends={{npcID=130929}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49814,50154},questLines={{id=5401,name="The Last of Their Kind",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[50151] = {id=50151,name="A Steady Ballast",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49926,50003,50149,50151,50173,50253,50446,50453,50457},description="The Armory presents us a ripe opportunity, <class>... one I suggest we take. If this battle were to draw out, we have little means to repair our arms and armor. A blacksmith is invaluable to any war effort, and Ballaster is one of our best. The Armory is but a short ride from here. I suggest you get to Ballaster before it's too late!",objectivesText="Find Angus Ballaster at the Corlain Armory. Progress: The blacksmith won't survive long with the coven hunting him down. I'd recommend leaving posthaste.",rewardGold=257400,rewardXP=2765,rewardItems={156722,156853,156855,157800},rewardCurrencies={{id=1553,amount=50}},starts={{npcID=131636}},ends={{npcID=131636}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50149},questLines={{id=598,name="Corlain",orderIndex=3,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=41,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50152] = {id=50152,name="Digging for Scraps",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50152,50447,50449,50450,50451,50452,50453,50454,50455,50456},description="Well met, <class>. I hope you don't mind that I took the liberty to scout ahead and assess the situation at the armory. The good news is that there still seems to be some salvageable arms left in the armory. The bad news, of course, is that the coven is after them as well. Additional weapons could be a great boon to our cause. I recommend we take all we can carry.",objectivesText="Collect 10 Quality Salvage from the Corlain Armory. Progress: What did you find at the armory?",rewardGold=257400,rewardXP=2765,rewardItems={156663},rewardCurrencies={{id=1560,amount=50}},starts={{npcID=131641}},ends={{npcID=131636}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50149},questLines={{id=5445,name="Caring about Corlain",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50154] = {id=50154,name="They Say It's a Delicacy",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49801,49810,49814,49870,50074,50150,50154,50252,50268,50297},series={49814,50150},description="A romantic meal is de way to set up an evening for love. Dis is true for us, so why not for Maka'fon? Bring her something rare and pleasing to her palate. Diemetrodons near de water eat hard seed pods and partially digest them. With a little voodoo, something magical can happen to de pods. It may be disgusting to you and I, but de brutosaurs consider it a rare delicacy. Such is life. Dere are plenty of diemetradons, so some must die dat de brutosaurs might live. Such is de purpose of death.",objectivesText="Obtain 25 Partially Digested Pods from the bellies of nearby diemetradons. Progress: De pods we need become edible only in de belly of de diemetradons. Watch your fingers in dere... de scales are sharp.",rewardGold=257400,rewardXP=1415,rewardItems={155917},starts={{npcID=130929}},ends={{npcID=130929}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49810},questLines={{id=5401,name="The Last of Their Kind",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[50157] = {id=50157,name="There's Gold in Them There Fields",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50157},series={50041},description="We've still got some folks missing, and I could use your help finding them. While Brennadam is now secure, I worry for some of our farms closer to the quilboar kraul. We relied on the militia in the past to keep the quilboar back, but now that they've retreated to the east I worry that our outlying farms are in danger. Goldfield's farm is almost directly south of us, up the hill by the falls. While it's not surprising that he hasn't left, I would feel better if you checked in.",objectivesText="Find Farmer Goldfield at his farm.",rewardGold=25740,rewardXP=515,starts={{npcID=130694}},ends={{npcID=129808}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49755},nextQuests={50041}},
[50158] = {id=50158,name="Checking Out the Collapse",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50158},description="If you've got a minute, there's a farmer out there who hasn't made it back yet. Name's Burton and he's out by a farm right next to Briarback Kraul. If the quilboar were to strike out, his farm is one of the first in their way. I haven't heard anything from Burton. He mostly relied on his mechanical farmers to help him, so we don't know the situation out there. Head to the west and keep an eye out for him, would you?",objectivesText="Find Farmer Burton at his farm.",rewardGold=25740,rewardXP=515,rewardItems={133510,155824,155877,156577,156578,156648,157849,157850,160558,160561},starts={{npcID=130694}},ends={{npcID=132118}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49755},nextQuests={50134,50135}},
[50161] = {id=50161,name="Recovering Raimond",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50064,50070,50161,50162,50165,50168,50264,50343,50359,50493,50504,50534,50553},description="The map we found earlier had some red markings, near the flower field. Do you think you could go up there and look for dad? I'm going to stay here and check out the rest of this stuff. I'd go with you... but, I'm sort of allergic to bees. Oh, and take his boot. Just in case!",objectivesText="Find Raimond Mildenhall . Progress: It is about time someone came looking for me!",rewardGold=257400,rewardXP=4115,rewardItems={156717,156808},starts={{npcID=132647}},ends={{npcID=132292}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50064},questLines={{id=5451,name="Not the Bees!",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50162] = {id=50162,name="Sticky Situation",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50064,50070,50161,50162,50165,50168,50264,50343,50359,50493,50504,50534,50553},description="The scientific breakthroughs I've made, marvelous, absolutely marvelous... I'm so close to perfecting the formula! The way the honey grows and crystallizes, simply beautiful. Well, as you can see, that's also part of my current predicament. Perhaps you can lend me a hand? Just fetch some royal jelly from the hives outside. Oh, don't worry about the bees, they are sweet, gentle things. They don't sting... much.",objectivesText="Collect 60 Royal Jelly . Progress: You get all the jelly yet?",rewardGold=257400,rewardXP=4115,rewardItems={156709},starts={{npcID=132292}},ends={{npcID=132292},{npcID=132355}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50161},questLines={{id=5451,name="Not the Bees!",orderIndex=6,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50164] = {id=50164,name="Polly Want A Cracker?",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={50164},objectivesText="Runaway Macaw fed",rewardItems={154878},mapCandidates={npc={},zone={8567}},questType="world",db2Objectives={{text="Runaway Macaw fed",amount=6,type=0,objectID=132339,orderIndex=0}},worldTaskTitle="Polly Want A Cracker?",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50165] = {id=50165,name="The Bee Team",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50064,50070,50161,50162,50165,50168,50264,50343,50359,50493,50504,50534,50553},description="We need to put things in order, and the next item on the list is these blasted wendigos terrorizing the farm. If we can cull their numbers, it should be enough to drive them off! I've synthesized a superb solution that might be just what we need to solvent this sticky situation! Toss these bottles at your foes and our friendly little apoideas should come to help. Whatever you do, please don't spill any on yourself...",objectivesText="Kill 12 Highland Maulers.",rewardGold=257400,rewardXP=4115,rewardItems={157851},starts={{npcID=134447}},ends={{npcID=134447}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50504},questLines={{id=5451,name="Not the Bees!",orderIndex=8,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50168] = {id=50168,name="Royal Succession",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50064,50070,50161,50162,50165,50168,50264,50343,50359,50493,50504,50534,50553},description="I know, I know, okay... the farm is overrun by living honey and the bees have grown to massive proportions. I'll admit, things didn't quite go according to plan, but, extraordinary advancements in science do not come without some risk! I've been up here attempting to reduce aggression in the hive, an unfortunate side effect of my miscalculation, but I need another favor... You're going to have to kill the Hive Mother and retrieve her stinger for me.",objectivesText="Retrieve the Hive Mother's Stinger . Progress: Oooh, ooh, do you have it!?",rewardGold=514800,rewardXP=5145,rewardItems={157839},rewardCurrencies={{id=1553,amount=50}},starts={{npcID=132292}},ends={{npcID=132292}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50161},questLines={{id=5451,name="Not the Bees!",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50172] = {id=50172,name="Into the Crimsonwood",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49939,50001,50036,50063,50090,50092,50172,50177,50238,50251,50903},series={50265},description="Master Ashton has been taken into the forest. He isn't the only one. Mayor Royston's headcount came up short. It seems our next steps are clear. We must go into the woods and save Master Ashton. Marten and I will sneak into the forest and meet you near some ruins further in.",objectivesText="Meet Inquisitor Cleardawn in the Crimson Forest.",rewardGold=25740,rewardXP=345,rewardItems={156859,156950,156951,157821,158064,158175},starts={{npcID=131879}},ends={{npcID=133098}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50063},questLines={{id=5442,name="Falconhurst",orderIndex=10,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50173] = {id=50173,name="Precious Metals",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49926,50003,50149,50151,50173,50253,50446,50453,50457},description="<class>, I have another objective we should consider. The Bleak Hills Mine is not too far from our location. Though the miners there principally extract iron, they do on occasion find silver among the veins. We do not know the current state of the mine, but it's unlikely that the coven has passed it over. However, it would be worth braving whatever dangers lie there to recover some silver to use against them.",objectivesText="Collect 10 Silver Nuggets from the Bleak Hills Mine. Progress: Did you have any luck with the mine?",rewardGold=257400,rewardXP=2765,rewardItems={156722,156853,156855,157800},rewardCurrencies={{id=1553,amount=75}},starts={{npcID=131638}},ends={{npcID=131638}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50149},questLines={{id=598,name="Corlain",orderIndex=4,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=42,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50174] = {id=50174,name="All Wrapped Up",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50174},description="While I was able to get out of the mine, some of my friends weren't so lucky. I saw those spiders wrap them up in their webs... probably to save them for a snack. It was terrible, but all I could do was run. Will you help them?",objectivesText="Destroy Writhing Cocoons to rescue 8 Bleak Hills Miners in the Bleak Hills Mine.",rewardGold=234000,rewardXP=2765,rewardItems={21191,21310},starts={{npcID=132374}},ends={{npcID=132374}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50149}},
[50175] = {id=50175,name="An Eight-Legged Curse",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50175},description="Some terrible old hag unleashed a swarm of these horrible spiders in the mine! I was barely able to make it out alive, but they've got me surrounded! You can't leave me here! Please kill those things!",objectivesText="Kill 20 Bilefang spiders in the Bleak Hills Mine.",rewardGold=234000,rewardXP=2765,starts={{npcID=132374}},ends={{npcID=132374}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50149}},
[50177] = {id=50177,name="Hold The Barricade!",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49939,50001,50036,50063,50090,50092,50172,50177,50238,50251,50903},description="<name> they're rallying for a heavy assault! We'll need to defend these barricades from attack! Are you with me?",objectivesText="Defend the barricades from attack! Progress: That earned us some breathing room.",rewardGold=257400,rewardXP=2765,rewardItems={156710,156828,158623,158624,158625,158626,160201,160202,160203,160204},rewardChoices={158623,158624,158625,158626,160201,160202,160203,160204},starts={{npcID=131879}},ends={{npcID=131879}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50001,50251},questLines={{id=5442,name="Falconhurst",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50178] = {id=50178,name="Trouble in the Rootway",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50178},objectivesText="Cull aggressive wildlife Feathered Viper slain Feathered Viper Eggs destroyed Feathered Viper Hatchling slain Wild Ravasaur slain",rewardGold=4000,rewardXP=1415,mapCandidates={npc={},zone={8499}},questType="standard",db2Objectives={{text="Cull aggressive wildlife",amount=1,type=15,objectID=0,orderIndex=0},{text="Feathered Viper slain",amount=17,type=0,objectID=132410,orderIndex=2},{text="Feathered Viper Eggs destroyed",amount=200,type=0,objectID=132413,orderIndex=3},{text="Feathered Viper Hatchling slain",amount=67,type=0,objectID=132412,orderIndex=4},{text="Wild Ravasaur slain",amount=17,type=0,objectID=123135,orderIndex=5}},worldTaskTitle="Trouble in the Rootway",db2PoiMapID=1642,db2PoiUiMapID=862},
[50195] = {id=50195,name="Bilgemaul's Brigade",level=1,requiredLevel=1,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={50195},description="Drustvar . Taking him out would deal a great blow to the Horde�s war effort, and might just put a halt to these ambushes.>",objectivesText="Defeat Captain Bilgemaul in the Brackish Coast and loot his War Spoils.",rewardGold=234000,rewardXP=200,mapCandidates={npc={},zone={8721}},questType="standard",startItems={156736}},
[50226] = {id=50226,name="The Source of Power",level=45,requiredLevel=45,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9310,mapID=81,storyline={49976,49981,50046,50047,50048,50049,50056,50057,50226,50227,50228,50371,50372,50373,50374},description="Although the silithid disappeared for a time immediately following the destruction of Silithus, they have recently returned from beneath the ground. These new silithid seem stronger than before! My hypothesis is that the silithid are feeding on some kind of power source beneath the blade of Sargeras. I've been tasked with studying the effects that this mysterious power is having on the silithid hives. Bring me as many intact silithid brains as you can carry and I'll begin the research!",objectivesText="Collect 10 Silithid Brains . Progress: Do you have the brains?",rewardGold=202200,rewardXP=6140,rewardItems={20384,20402,66908,66909,66910,156794},starts={{npcID=132606}},ends={{npcID=132606}},mapCandidates={npc={81},zone={1377}},questType="standard",sourceQuests={50372},questLines={{id=576,name="Silithus: The Wound",orderIndex=14,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[50227] = {id=50227,name="Larvae By The Dozen",level=45,requiredLevel=45,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9310,mapID=81,storyline={49976,49981,50046,50047,50048,50049,50056,50057,50226,50227,50228,50371,50372,50373,50374},description="How did the silithid survive the blade of Sargeras? I'm perplexed! I've never encountered a species that can adapt to changes in the environment as quickly as the silithid can. The larvae, or broodlings as they are often called, can evolve into a variety of silithid creature types based on the needs of the hive. Is it the hive mind that signals the evolutionary development of the larvae, or is some environmental factor at play? Science must find the answer!",objectivesText="Collect 12 Silithid Broodlings . Progress: Do you have the silithid larvae?",rewardGold=202200,rewardXP=6140,rewardItems={156795},starts={{npcID=132606}},ends={{npcID=132606}},mapCandidates={npc={81},zone={1377}},questType="standard",sourceQuests={50372},questLines={{id=576,name="Silithus: The Wound",orderIndex=16,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[50228] = {id=50228,name="The Twilight Survivor",level=45,requiredLevel=45,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9310,mapID=81,storyline={49976,49981,50046,50047,50048,50049,50056,50057,50226,50227,50228,50371,50372,50373,50374},description="Silithus used to be overrun with members of the Twilight's Hammer. The cult was presumed to be exterminated, but it has always survived in the shadows. Their numbers have dwindled, but the cult remains no less fanatical than at their peak. Most of the cultists here were destroyed by Sargeras in the attack, but a few still remain. Their leader, Michiel Voidstrider has been emboldened by the destruction of Silithus. We cannot let Michiel rally the remaining survivors to action. He must be stopped!",objectivesText="Retrieve Michiel Voidstrider's head . Progress: We cannot allow the Twilight's Hammer to regain their foothold in Silithus.",rewardGold=202200,rewardXP=6140,rewardItems={156796},starts={{npcID=131963}},ends={{npcID=131963}},mapCandidates={npc={81},zone={1377}},questType="standard",sourceQuests={50046,50047},questLines={{id=576,name="Silithus: The Wound",orderIndex=18,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[50229] = {id=50229,name="A Wee Bit O' Cloth",level=45,requiredLevel=45,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9310,storyline={50229},description="<name>, is that you I hear rustlin' about out there? It's me, Angus Stormbrew! There are cultists everywhere, so ye best keep yer voice down. Lean in close and cover yer nose while we talk! This is the only outhouse in all o' Silithus! Trust me I spent hours lookin' all through the night. I decided to sneak in for a wee drop-off before the cultists woke up, but I've got a uhh problem... There's no cloth to... you know... See if ye can find me a wee bit o' cloth and sneak it in through the door!",objectivesText="Collect 8 scraps of Twilight Silk . Progress: Did ye acquire \"the goods?\"",rewardGold=202200,rewardXP=6140,rewardItems={156797},startObjects={{objectID=280948,mapID=81,x=0.296,y=0.696}},endObjects={{objectID=280948,mapID=81,x=0.296,y=0.696}},coords={mapID=81,x=0.296,y=0.696},mapCandidates={npc={},zone={1377}},questType="standard"},
[50230] = {id=50230,name="The Source of Power",level=45,requiredLevel=45,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=9310,mapID=81,storyline={49977,49982,50052,50053,50054,50055,50057,50230,50231,50232,50300,50341,50358,50360,50364},description="The silithid are all riled up and stronger than ever! My guess is that they are feeding off of some kind of power beneath the ground. Probably near the blade of Sargeras! I've been ordered to study the effects that this mysterious power is having on the sillithid. Bring me as many intact silithid brains as you can carry and I'll begin the research!",objectivesText="Collect 10 Silithid Brains . Progress: Hey kid! You got the stuff?",rewardGold=202200,rewardXP=6140,rewardItems={20384,20402,66908,66909,66910,156794},starts={{npcID=132040}},ends={{npcID=132040}},mapCandidates={npc={81},zone={1377}},questType="standard",sourceQuests={50358},questLines={{id=576,name="Silithus: The Wound",orderIndex=15,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[50231] = {id=50231,name="Larvae By The Dozen",level=45,requiredLevel=45,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=9310,mapID=81,storyline={49977,49982,50052,50053,50054,50055,50057,50230,50231,50232,50300,50341,50358,50360,50364},description="How did the silithid survive the blade of Sargeras?! I've never encountered a species that can adapt to changes in the environment as quickly as the silithid! There's gotta be a way to tame these suckers! Harness their evolutionary biology for our profit! We gotta start training 'em young! Forget about the old crusty adults, we need babies! Steal me as many of the silithid larvae as you can carry, and I'll find a way to train 'em!",objectivesText="Collect 12 Silithid Broodlings . Progress: Do you have the silithid larvae?",rewardGold=202200,rewardXP=6140,rewardItems={156795},starts={{npcID=132040}},ends={{npcID=132040}},mapCandidates={npc={81},zone={1377}},questType="standard",sourceQuests={50358},questLines={{id=576,name="Silithus: The Wound",orderIndex=17,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[50232] = {id=50232,name="The Twilight Survivor",level=45,requiredLevel=45,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=9310,mapID=81,storyline={49977,49982,50052,50053,50054,50055,50057,50230,50231,50232,50300,50341,50358,50360,50364},description="This land was once overrun with members of the Twilight's Hammer. The cult was presumed to be exterminated, but darkness always survives in the shadows. Most of the cultists were destroyed by Sargeras in the attack, but a few yet live. Their leader, Michiel Voidstrider has been emboldened by the destruction of Silithus. We cannot let this fanatic rally the remaining survivors to action! Bring me his head!",objectivesText="Retrieve Michiel Voidstrider's head . Progress: We cannot allow the Twilight's Hammer to regain their foothold in Silithus!",rewardGold=202200,rewardXP=6140,rewardItems={156796},starts={{npcID=132147}},ends={{npcID=132147}},mapCandidates={npc={81},zone={1377}},questType="standard",sourceQuests={50053},questLines={{id=576,name="Silithus: The Wound",orderIndex=19,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[50234] = {id=50234,name="Crews of Freehold",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={50234},rewardItems={153680,153681,153682},mapCandidates={npc={},zone={8567}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=1,objectID=153680},{orderIndex=1,type=1,amount=1,objectID=153681},{orderIndex=2,type=1,amount=1,objectID=153682}},worldTaskTitle="Crews of Freehold",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50235] = {id=50235,name="No Safe Haven",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="I brought Rastakhan to Zeb'ahari to hide him, . I did not dream Zul's followers would find us so soon. De people of Zeb'ahari are being hunted by those who answer to de prophet. I have brought dis upon dem by keeping de king in their village. Help me save dem, . Gather those who can still walk and send dem to me. I can do nothing for those who died, but we can still rescue de living.",rewardGold=257400,rewardXP=1415,rewardCurrencies={{id=1560,amount=50}},starts={{npcID=124083}},ends={{npcID=124083}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51680},questLines={{id=349,name="Among the People",orderIndex=4,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=58,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[50238] = {id=50238,name="Bramblethorn",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49939,50001,50036,50063,50090,50092,50172,50177,50238,50251,50903},description="I was playing with Lord and Lady Sharptooth when Papa made me come with him. I dropped poor Lord Sharptooth and one of those big mean monsters grabbed him! Papa said he'd try to get him back but he's been gone a long time. I think he got busy. Mama and all the adults are busy doing stuff for Mayor Royston. Lady Sharptooth and I are really sad. Can you beat up that mean monster and save my dino?",objectivesText="Slay Bramblethorn and retrieve Lord Sharptooth . Progress: Did you find Lord Sharptooth ? I think one of the really big monsters has him.",rewardGold=257400,rewardXP=2765,rewardItems={156710,156830},starts={{npcID=132966}},ends={{npcID=132966}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={49939},questLines={{id=5442,name="Falconhurst",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50239] = {id=50239,name="A Choice of Allies",level=40,requiredLevel=40,faction="alliance",categories={"campaign"},sharable=false,expansion=7,zoneID=1519,mapID=84,description="I was chosen to act as an ambassador to our new allies due to my experience with the pandaren joining the Alliance. I've made some notes about some potential allies that may be willing to join the Alliance. Learn more about them, then speak with me.",starts={{npcID=126301},{npcID=126332}},ends={{npcID=126301},{npcID=126332}},mapCandidates={npc={84},zone={1519}},questType="standard",questLines={{id=6058,name="Allied Race Display",orderIndex=0,flags=0}}},
[50240] = {id=50240,name="A Slip of the Tongue",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=1165,storyline={50240},description="<As you approach, the blind Zandalari motions at you impatiently.> It sounds like ya be headed somewhere in a hurry, little weed! Sit down and share a tale with an old troll before ya head out on ya next adventa. I went on many adventas with my pterrordax when I was young. Explored dis whole valley! My pterrordax died many years ago, but... < Blind Tra'wala smiles mischievously.> Sometimes at night, I steal da guards' snacks to trick dese old pterrordaxes into lettin' me ride again. Ha!",objectivesText="Steal a Pack of Pterrordax Snacks and use them to ride a pterrordax deeper into the city.",rewardGold=128700,rewardXP=710,rewardItems={156839},starts={{npcID=132989}},ends={{npcID=132989}},mapCandidates={npc={1165},zone={8670}},questTurnInID=132989,questType="standard"},
[50242] = {id=50242,name="A Choice of Allies",level=40,requiredLevel=40,faction="horde",categories={"campaign"},flags={"important"},sharable=false,expansion=7,zoneID=1637,mapID=85,storyline={49930,50242},description="As ambassador, it is my duty to bolster the Horde's ranks and strengthen our numbers in the face of danger. Your adventures have led you to many different people who can aid the Horde if we can convince them to join our cause. I've kept a record of the most promising potential allies. The choice of which to approach first is yours.",objectivesText="Learn more about potential allies. Progress: Is there a problem with my notes?",rewardGold=34100,rewardXP=685,rewardItems={155662,156487,161330},starts={{npcID=126065},{npcID=133523}},ends={{npcID=126065},{npcID=133523}},mapCandidates={npc={85},zone={1637}},questType="standard",questLines={{id=574,name="Allies of the Horde",orderIndex=1,flags=0},{id=6057,name="Allied Race Display",orderIndex=0,flags=0}},db2PoiMapID=1,db2PoiUiMapID=85},
[50247] = {id=50247,name="The Mail Must Flow",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=7502,storyline={50247},description="Due to all of the recent shenanigans, I'm running short on mailementals to sort letters. It's a simple job, really - just toss the letter into the proper portal, where it will be whisked away to the far corners of Azeroth and beyond. I like to make a little game out of it. How many can you sort in one minute?",objectivesText="Help the Postmaster sort at least 15 letters within the time limit.",rewardGold=202200,rewardXP=1415,rewardItems={7912,45693,122340,134859,135463,156721,156833,156836},starts={{npcID=103976}},mapCandidates={npc={},zone={7502}},questGiverID=103976,questType="standard",sourceQuests={41395}},
[50249] = {id=50249,name="A Boralus Triple Threat",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={49716,49720,49733,49734,50249,51226},description="If Tallis honestly thinks that offing a few random soldiers is going to force us to give up Southwatch, he's in for a surprise. The reason why we haven't chased out the sorry troops in this camp is simply because we have more pressing plans. Fernn has his lieutenants facing the Watch's cannons straight at Boralus as we speak. Those three are the real driving force of the attack. <The marine gives you a concerned look as he realizes what he said.>",objectivesText="Take out Fernn's three lieutenants. Progress: What is it?",rewardGold=514800,rewardXP=1770,starts={{npcID=133035}},ends={{npcID=130375}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49733,51226},questLines={{id=5431,name="Greystone Keep",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[50250] = {id=50250,name="Posthaste",level=10,requiredLevel=10,faction="none",categories={},flags={},sharable=true,expansion=7,zoneID=7502,mapID=627,storyline={50250},rewardGold=238680,rewardXP=1415,mapCandidates={npc={},zone={7502}},questType="standard"},
[50251] = {id=50251,name="Spell Bound",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49939,50001,50036,50063,50090,50092,50172,50177,50238,50251,50903},description="<The villager is held captive by a binding rune. Destroying the rune should free the villager.>",objectivesText="Destroy 8 Binding Runes to free captive villagers .",rewardGold=257400,rewardXP=2765,starts={{npcID=131579}},ends={{npcID=131879}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50001},nextQuests={50177},questLines={{id=5442,name="Falconhurst",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50252] = {id=50252,name="Mating Season Halftime",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49801,49810,49814,49870,50074,50150,50154,50252,50268,50297},description="Cala and I have both failed. Voodoo and science did not work. I am at a loss. I hope dat you can help us find a better path forward. De brutosaurs deserve a chance! Please spend a little time with both of us. Perhaps you can find de way dat we cannot.",objectivesText="Strategize with Cala Cruzpot and Witch Doctor Janagalar on how to use voodoo and science to get the endangered brutosaurs to mate. Progress: Please strategize with both Cala and myself to find a new plan to help de brutosaurs.",rewardGold=64350,rewardXP=355,starts={{npcID=130929}},ends={{npcID=130929}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50074,50150},questLines={{id=5401,name="The Last of Their Kind",orderIndex=6,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[50253] = {id=50253,name="An Improvised Arsenal",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49926,50003,50149,50151,50173,50253,50446,50453,50457},description="I don't know much about blacksmithing, but I'm pretty sure this won't be enough silver to outfit all of the Inquisitors. We will need to find another way to use this. Let us hope that Ballaster can come up with something... creative.",objectivesText="Speak with Angus Ballaster to create a silver weapon at Watchman's Rise. Progress: What can ol' Angus do fer ye?",rewardGold=128700,rewardXP=1385,rewardItems={156722,156853,156855,157800},starts={{npcID=131638}},ends={{npcID=132193}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50151,50173},questLines={{id=598,name="Corlain",orderIndex=5,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=43,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50264] = {id=50264,name="Free the Farmhands",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50064,50070,50161,50162,50165,50168,50264,50343,50359,50493,50504,50534,50553},description="We were running around trying to get the farm under control, but the bees, oh my goodness, the bees! The giant monstrosities came out of nowhere and started dousing everyone in honey. I came up here to find Raimond, but before I knew it, I was covered too. Then, the strangest thing happened, the honey started growing around me! Please, the other farmhands are still in trouble, you've got to help them!",objectivesText="Rescue the Honey Encased Farmhands.",rewardGold=257400,rewardXP=4115,starts={{npcID=134028}},ends={{npcID=133204},{npcID=134447}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50504},questLines={{id=5451,name="Not the Bees!",orderIndex=9,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50265] = {id=50265,name="Saving Master Ashton",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50265,50306,50325,50327,50329,50370,50445,50481,50530,50533},series={50172},description="I believe I see Master Ashton in a cage. He must be freed! Those witches with the long masks appear to be in charge. I bet they would have the means to open his cage. I will remain here to protect Apprentice Webb and keep the area secure.",objectivesText="Take a key from a Hexwood Binder and free Master Ashton.",rewardGold=257400,rewardXP=2765,rewardItems={156859,156950,156951,157821,158064,158175},starts={{npcID=133098}},ends={{npcID=133098}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50172},questLines={{id=602,name="Crimson Forest",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50266] = {id=50266,name="Bittersweet",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50266},description="Hey! I need to get out of here and get back to Falconhurst! My husband and I were looking for my daughter's favorite toy when I was taken. Please, I need to get out of here! I need to know my family is safe. They took my gear. It's all around camp. Get me out of here then bring back my gear, please!",objectivesText="Free Samantha Sweet then recover her gear.",rewardGold=257400,rewardXP=2765,starts={{npcID=133101}},ends={{npcID=133252}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50265}},
[50268] = {id=50268,name="Give it a Little Juice",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49801,49810,49814,49870,50074,50150,50154,50252,50268,50297},series={49870},description="Well, I admit that I feel a little better about this. If Witch Doctor Jangalar's voodoo can make Ben'jin react correctly, as the science says he should, then what do we have to lose? Bless my formula or hex it or whatever they call it with Jangalar's voodoo cauldron.",objectivesText="Put some voodoo on Cala's formula using Witchdoctor Jangalar's cauldron. Progress: Will voodoo make it smell funny? Nevermind, idle musings.",rewardGold=25740,rewardXP=175,rewardItems={156860,160752},starts={{npcID=130905}},ends={{npcID=130905}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50252},questLines={{id=5401,name="The Last of Their Kind",orderIndex=7,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[50270] = {id=50270,name="Deep In the Core",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"blacksmithing"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=207,storyline={50114,50123,50270,50275},series={50114},description="Look, you're gonna have to travel to some place called Deepholm and find an earthen down there. The guy who sold the recipe to me said he got it from an earthen called...Ormhun! Ormhun something. I don't know too much about that place, but maybe you can ask the locals or something where he lives. Now if you don't mind, I have more recipes to sell.",objectivesText="Travel to Stormwind and take the portal to Deepholm. Seek out Ormhun Stonehammer when you arrive.",rewardGold=25740,rewardXP=175,starts={{npcID=133536}},ends={{npcID=133489}},mapCandidates={npc={207},zone={8568}},questGiverID=133536,questType="standard",sourceQuests={50114},questLines={{id=896,name="8.1.5 Blacksmithing - Alliance",orderIndex=2,flags=0}},db2PoiMapID=646,db2PoiUiMapID=207},
[50271] = {id=50271,name="Smash and Grab",level=10,requiredLevel=10,faction="both",requiredProfessions={"blacksmithing"},categories={},flags={},sharable=true,expansion=7,zoneID=5042,mapID=207,storyline={50271,50272,50274,50288},series={50272,50273,50274},description="Most of the materials we'll need can be found right down here in the Deepholm. We just need ta be discreet about it. If old Therazane catches wind of what we're up to, she might try ta put a stop ta it. But let's not worry 'bout that. The first thing you'll need is diaminium . There are pillars that grow in the Alabaster Shelf rich with 'em. Just use yer old blacksmithin' hammer and smash those pillars ta bits. Don't worry about breaking the diaminium . We'll meld it all back tagether.",objectivesText="Go to the Alabaster Shelf and smash Diaminium Pillars. Collect 60 Diaminium . Progress: This'll be fun! I haven't made one of those anvils in ages!",rewardGold=257400,rewardXP=1415,rewardItems={156887},starts={{npcID=133489}},ends={{npcID=133489}},mapCandidates={npc={207},zone={5042}},questType="standard",sourceQuests={50270,50278},questLines={{id=898,name="8.1.5 Blacksmithing - Alliance/Horde",orderIndex=0,flags=0}},db2PoiMapID=646,db2PoiUiMapID=207},
[50272] = {id=50272,name="An Ear to the Ground",level=10,requiredLevel=10,faction="both",requiredProfessions={"blacksmithing"},categories={},flags={},sharable=true,expansion=7,zoneID=5042,mapID=207,storyline={50271,50272,50274,50288},series={50271,50273,50274},description="The next reagent ya need comes from the bellies of worms that burrow through this realm. While ya can find plenty o' worms all over, there's a certain type you'll need ta find. They're rarely seen above ground, but there are ways of coaxing 'em out. Namely making enough racket to piss 'em off! Ha ha! When ya see 'em rumblin' around beneath ya, use this thumper to draw 'em out. Deliver a killin' blow and get that metal from their wee bellies!",objectivesText="Go to the Jagged Wastes and look for signs of worms. They usually kick up lots of dirt as they move around. Drop a thumper to make them surface, then kill them and collect 30 Endurite from them. Progress: It's been a while since I went worm huntin'. We used ta jump up and down ta rile them up before we made tha thumpers.",rewardGold=257400,rewardXP=1415,rewardItems={156886,157556},starts={{npcID=133489}},ends={{npcID=133489}},mapCandidates={npc={207},zone={5042}},questType="standard",sourceQuests={50270,50278},questLines={{id=898,name="8.1.5 Blacksmithing - Alliance/Horde",orderIndex=1,flags=0}},db2PoiMapID=646,db2PoiUiMapID=207},
[50273] = {id=50273,name="Atal'Dazar: Locking Horns",level=10,requiredLevel=10,faction="none",requiredProfessions={"blacksmithing"},categories={},flags={},sharable=true,expansion=7,zoneID=9028,mapID=862,storyline={50273},series={50271,50272,50274},description="We've got tha metal for tha base and tha body, but there's one last part... Tha horn of tha anvil was ta be made of ukrite. But that metal's been gone for ages. There is another metal tha's very close ta it in terms of its durability. A type of gold tha trolls mined in abundance. And I know where ye can find it. Tha trolls control an area called Atal'Dazar, a great city made o' tha stuff. If ye can find something horn-shaped in there, that'll save us tha trouble of shaping it from scratch.",objectivesText="Go to Atal'Dazar and recover The Golden Horn of Rezan .",rewardGold=257400,rewardItems={156920},mapCandidates={npc={},zone={9028}},questType="dungeon"},
[50274] = {id=50274,name="Titanic Forging",level=10,requiredLevel=10,faction="both",requiredProfessions={"blacksmithing"},categories={},flags={},sharable=true,expansion=7,zoneID=5042,mapID=207,storyline={50271,50272,50274,50288},series={50271,50272,50273},description="Are ya ready, <lad/lass>? You'll be doing the hammerin' while I take care of the last reagent we'll need.",objectivesText="Meet Ormhun near the Shuddering Spires and help him craft a Khaz'gorian Anvil.",rewardGold=59670,rewardXP=355,starts={{npcID=133489}},ends={{npcID=133489}},mapCandidates={npc={207},zone={5042}},questType="standard",sourceQuests={50271,50272},questLines={{id=898,name="8.1.5 Blacksmithing - Alliance/Horde",orderIndex=2,flags=0}},db2PoiMapID=646,db2PoiUiMapID=207},
[50275] = {id=50275,name="Anvil's Away",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"blacksmithing"},categories={},flags={},sharable=true,expansion=7,zoneID=5042,mapID=207,storyline={50114,50123,50270,50275},description="Take your anvil, and never speak of its methods of creation to anyone. Should I find out otherwise, you may find your next visit to my realm an unpleasant one.",objectivesText="Bring the anvil back to Grix Barlow in Boralus.",rewardGold=23870,rewardXP=175,starts={{npcID=133796}},ends={{npcID=133796}},mapCandidates={npc={207},zone={5042}},questTurnInID=133796,questType="standard",sourceQuests={50288},questLines={{id=896,name="8.1.5 Blacksmithing - Alliance",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[50276] = {id=50276,name="A Recipe For the Ages",level=50,requiredLevel=50,faction="horde",requiredProfessions={"blacksmithing"},categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=1165,storyline={50276,50277,50278,50279},description="Say, ya look like you been swingin' da hammah around quite a bit, <brudda/sista>. I can smell da flux on ya! <Zak'aal gives you a wide grin.> Listen, I've got a recipe for da most amazin' blacksmit hammah ya ever be layin' ya eyes on. And I'd be willing ta let it go for a bit of ore. Revlis ore ta be exact. It be a little rare, but ya can find some of it over at Atal'Gral. Da naga dere use it ta make deir weapons. Bring me back a haul of it, and da recipe be yours!",objectivesText="Bring Forgemaster Zak'aal 30 pieces of Revlis Ore from Atal'Gral in Zuldazar. Progress: Dis recipe probably be wort a tousand, no TEN tousand gold! Blacksmits all over will be envious of ya, brudda.",rewardGold=234000,rewardXP=6815,rewardItems={156875},starts={{npcID=127112}},ends={{npcID=127112}},mapCandidates={npc={1165},zone={8499}},questType="standard",questLines={{id=897,name="8.1.5 Blacksmithing - Horde",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[50277] = {id=50277,name="Hammering Out Information",level=10,requiredLevel=10,faction="horde",requiredProfessions={"blacksmithing"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={50276,50277,50278,50279},series={50278},description="Let me guess. You be lookin' at da recipe and noticed it require a Khaz'gorian Anvil ta make it. So now you be wantin' ta know where ta find a Khaz'gorian Smithing Anvil? Look, <brudda/sista>, I never said anyting about bein' able ta craft da hamma. Now if ya don't mind, I have more of dese recipes ta be sellin'.",objectivesText="Press Forgemaster Zak'aal for more information about where to find a Khaz'gorian Smithing Anvil. Progress: Dat recipe really be wort what ya paid for it, no mindin' if ya be able ta craft it or not.",rewardGold=23870,rewardXP=175,starts={{npcID=127112}},ends={{npcID=127112}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={50276},questLines={{id=897,name="8.1.5 Blacksmithing - Horde",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[50278] = {id=50278,name="Deep In the Core",level=10,requiredLevel=10,faction="horde",requiredProfessions={"blacksmithing"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={50276,50277,50278,50279},series={50277},description="Look, ya gonna have ta travel ta Deepholm and convince dem ta be givin' up deir secrets. Dat's where da last anvil was made, or so I be hearin'. And I only be knowin' of one earten down dere who might be willin' ta work wit ya. His name be Ormhun Stonehamma'. He be kind of an outcast, but not too hard ta find.",objectivesText="Travel to Orgrimmar and take the portal to Deepholm. Seek out Ormhun Stonehammer when you arrive.",rewardGold=25740,rewardXP=175,starts={{npcID=127112}},ends={{npcID=133489}},mapCandidates={npc={207,1165},zone={8670}},questType="standard",sourceQuests={50277},questLines={{id=897,name="8.1.5 Blacksmithing - Horde",orderIndex=2,flags=0}},db2PoiMapID=646,db2PoiUiMapID=207},
[50279] = {id=50279,name="Anvil's Away",level=10,requiredLevel=10,faction="horde",requiredProfessions={"blacksmithing"},categories={},flags={},sharable=true,expansion=7,zoneID=5042,mapID=207,storyline={50276,50277,50278,50279},description="Take your anvil, and never speak of its methods of creation to anyone. Should I find out otherwise, you may find your next visit to my realm an unpleasant one.",objectivesText="Bring the anvil back to Forgemaster Zak'aal in Zuldazar.",rewardGold=23870,rewardXP=175,starts={{npcID=133796}},ends={{npcID=127112}},mapCandidates={npc={207,1165},zone={5042}},questType="standard",sourceQuests={50288},questLines={{id=897,name="8.1.5 Blacksmithing - Horde",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[50287] = {id=50287,name="Unending Gorilla Warfare",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,mapCandidates={npc={},zone={8499}},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Disrupt Da'kani Gorillas"},{orderIndex=1,type=0,amount=17,objectID=130953,text="Da'kani Gorillas slain"},{orderIndex=2,type=0,amount=17,objectID=130954,text="Da'kani Gorillas slain"},{orderIndex=3,type=0,amount=13,objectID=130948,text="King Da'ka slain"},{orderIndex=4,type=0,amount=9,objectID=131476,text="Zayoos slain"},{orderIndex=5,type=0,amount=13,objectID=133404,text="Gorilla Totems destroyed"}},worldTaskTitle="Unending Gorilla Warfare",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50288] = {id=50288,name="Therazane's Choice",level=10,requiredLevel=10,faction="both",requiredProfessions={"blacksmithing"},categories={},flags={},sharable=false,expansion=7,zoneID=5042,mapID=207,storyline={50271,50272,50274,50288},description="<You explain that you meant no disrespect to Therazane or to steal their secrets.> Interesting... I have a wonderful idea on how to solve this issue. Would you like to hear it?",objectivesText="Listen to Therazane 's proposition. Progress: To think a creature such as yourself would be freely given our secrets. I suppose I'll have to keep a closer eye on the goings on within my realm.",rewardGold=25740,rewardXP=175,rewardItems={60816,167021},starts={{npcID=133796}},ends={{npcID=133796}},mapCandidates={npc={207},zone={5042}},questType="standard",sourceQuests={50274},questLines={{id=898,name="8.1.5 Blacksmithing - Alliance/Horde",orderIndex=3,flags=0}},db2PoiMapID=646,db2PoiUiMapID=207},
[50295] = {id=50295,name="Like Pulling Teeth",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={50295},objectivesText="Kill 25 wendigo.",rewardItems={161312},mapCandidates={npc={},zone={8567}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=25,objectID=161312},{orderIndex=1,type=0,amount=1,objectID=140404}},worldTaskTitle="Like Pulling Teeth",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50296] = {id=50296,name="Billy Goat Barber",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={50296},objectivesText="Use the Goat Shears on 6 Gentle Goats.",rewardItems={153596,155681},mapCandidates={npc={},zone={8567}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=6,objectID=155681}},worldTaskTitle="Billy Goat Barber",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50297] = {id=50297,name="The Head of Her Enemy",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={49801,49810,49814,49870,50074,50150,50154,50252,50268,50297},description="You have done a wonderful thing, <name>. With de destruction of Gloomtail, Maka'fon is no longer bothered by de presence of de razorwings. It seems dat Gloomtail destroyed her eggs some time ago. Take Gloomtail's head to Maka'fon as proof dat he is gone. When she finds de scent of Ben'jin on it, she will once again seek a worthy mate. When Ben'jin senses dat, he will approach and nature will take over.",objectivesText="Place Gloomtail's head in front of Maka'fon so that she knows her territory is safe and that Ben'jin is the reason. Progress: Take Gloomtail's head and offer it to Maka'fon. Let us see what happens next.",rewardGold=257400,rewardXP=1415,rewardItems={156925,158666,159123,159147,159148,159149,159150,163036},rewardChoices={159147,159148,159149,159150,158666,159123},starts={{npcID=130929}},ends={{npcID=130929}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49870},questLines={{id=5401,name="The Last of Their Kind",orderIndex=9,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[50299] = {id=50299,name="Gryphon Wranglin'",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={50299},objectivesText="Wild Gryphon wrangled",rewardItems={156928},mapCandidates={npc={},zone={8567}},questType="world",db2Objectives={{text="Wild Gryphon wrangled",amount=1,type=0,objectID=133323,orderIndex=0}},worldTaskTitle="Gryphon Wranglin'",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50303] = {id=50303,name="Stranger in a Strange Land",level=10,requiredLevel=10,faction="horde",requiredRaces={27},categories={},flags={},sharable=true,expansion=7,zoneID=1637,mapID=85,storyline={49933,50303},description="Hi. I'm Ambassador Blackguard . I am honored to welcome you to Orgrimmar, <race>. <He smiles unconvincingly.> As a lifetime of adventure unfolds before you, be assured that... uh... You know what? I've been saying this same greeting all day. Enough's enough. Talk to Chromie on top of the hourglass, then talk to your emissary. Run along.",objectivesText="Talk to Chromie in Orgrimmar. Progress: Not quite as beautiful as Suramar, is it?",rewardGold=34100,rewardXP=175,rewardItems={246740,246795},starts={{npcID=133407}},ends={{npcID=131328}},mapCandidates={npc={85},zone={1637}},questType="standard",sourceQuests={49933},questLines={{id=581,name="Allies of the Horde",orderIndex=1,flags=0}},db2PoiMapID=1,db2PoiUiMapID=85},
[50305] = {id=50305,name="Stranger in a Strange Land",level=10,requiredLevel=10,faction="alliance",requiredRaces={29},categories={},flags={},sharable=true,expansion=7,zoneID=1519,mapID=84,storyline={49788,50305},series={49788,51486},description="Welcome to Stormwind, <race>. I invite you to explore our fair city. Say, you look like someone who enjoys the night life. We have many popular taverns and a vibrant music scene! Ah, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things! After that, an emissary of the ren'dorei is waiting to welcome you to the city. Sounds like a busy day for you! Have a pleasant stay, <name>!",objectivesText="Talk to Chromie in Stormwind City. Progress: So, how does Stormwind suit you?",rewardGold=34100,rewardXP=175,rewardItems={246740,246795},starts={{npcID=133362}},ends={{npcID=131347}},mapCandidates={npc={84},zone={1519}},questType="standard",sourceQuests={49788},questLines={{id=579,name="Allies of the Alliance",orderIndex=1,flags=0}},db2PoiUiMapID=84},
[50306] = {id=50306,name="Odds and Ends",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50265,50306,50325,50327,50329,50370,50445,50481,50530,50533},description="Master Ashton's going to probably need something bracing once we get him free. I know of a quick potion guaranteed to get anyone to snap out of it, but I'm going to need a few things first. Those wicker dogs down there have some organic parts I can use and the witches are carrying bags of reagents. They'll almost certainly have what I need. Bring those to me and I'll handle the rest once we get Master Ashton back.",objectivesText="Collect 4 Organic Matter Samples and 3 Bags of Reagents. Progress: Did you have any luck?",rewardGold=245700,rewardXP=2765,rewardItems={156859,156950,156951,157821,158064,158175,158593,158595,160193,160194,160195,160196},rewardChoices={158593,158595,160193,160194,160195,160196},starts={{npcID=133126}},ends={{npcID=133126}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50172},questLines={{id=602,name="Crimson Forest",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50313] = {id=50313,name="Stranger in a Strange Land",level=10,requiredLevel=10,faction="alliance",requiredRaces={30},categories={},flags={},sharable=true,expansion=7,zoneID=1519,mapID=84,storyline={49772,50313},description="Welcome to Stormwind, <race>. I invite you to explore our fair city. Say, you look like the devout sort. We have a lovely cathedral that will no doubt be of interest! Ah, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things! After that, an emissary of the Lightforged is waiting to welcome you to the city. Sounds like a busy day for you! Have a pleasant stay, <name>!",objectivesText="Find Chromie in Stormwind City. Progress: I can feel the Light in this place.",rewardGold=200,rewardXP=175,rewardItems={246740,246795},starts={{npcID=133362}},ends={{npcID=131334}},mapCandidates={npc={84},zone={1519}},questType="standard",sourceQuests={49772},questLines={{id=578,name="Allies of the Alliance",orderIndex=1,flags=0}},db2PoiUiMapID=84},
[50315] = {id=50315,name="Not On the Itinerary",expansion=7,mapID=895,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Save the Resort Guests!"}},worldTaskTitle="Not On the Itinerary",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50316] = {id=50316,name="Disturbance Detected: Ulduar",level=30,requiredLevel=30,faction="both",categories={},flags={"repeatable","weekly"},sharable=true,expansion=7,zoneID=8161,storyline={50316},description="You're late. Don't you remember the last time we had to deal with the tampering that allowed Yogg-Saron to escape from his prison underneath Ulduar ? You were late then too. You should really try to be more punctual. Well, get going! Old gods! Keepers! Titan stuff! Get this one checked off your list so we can move on. We've got times and places to be. < Vormu gestures impatiently for you to leave.>",objectivesText="Relive the expedition to Ulduar . Progress: Exactly the same number of dwarves must be roasted as last time. Medium rare, of course - well done would be insanity.",rewardGold=341600,rewardXP=4115,rewardItems={157030,208094},rewardCurrencies={{id=1166,amount=500}},starts={{npcID=130654}},ends={{npcID=130654}},mapCandidates={npc={},zone={4273}},questGiverID=130654,questTurnInID=130654,questType="standard"},
[50318] = {id=50318,name="A Timely Summons from Northrend",level=1,requiredLevel=1,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=4395,storyline={50318},description="The blazing wanes in the shadow of a celestial mass, striking fear in to the seers. Seek out the sage Vormu in Dalaran , and lend her your aid. No, not this Dalaran , the other one. Yes I know, it's terribly confusing.",objectivesText="Meet with Vormu in Dalaran above Crystalsong Forest.",rewardGold=30900,rewardXP=25,starts={{npcID=111246}},ends={{npcID=111246}},mapCandidates={npc={},zone={7502}},questGiverID=111246,questTurnInID=111246,questType="standard"},
[50319] = {id=50319,name="Stranger in a Strange Land",level=10,requiredLevel=10,faction="horde",requiredRaces={28},categories={},flags={},sharable=true,expansion=7,zoneID=1637,mapID=85,storyline={49773,50319},description="Hi. I'm Ambassador Blackguard . I am honored to welcome you to Orgrimmar, <race>. <He smiles unconvincingly.> As a lifetime of adventure unfolds before you, be assured that... uh... You know what? I've been saying this same greeting all day. Enough's enough. Talk to Chromie on top of the hourglass, then talk to your emissary. Run along.",objectivesText="Talk to Chromie . Progress: Not quite as beautiful as Highmountain, is it?",rewardGold=34100,rewardXP=175,rewardItems={246740,246795},starts={{npcID=133407}},ends={{npcID=131201}},mapCandidates={npc={85},zone={1637}},questType="standard",sourceQuests={49773},questLines={{id=580,name="Allies of the Horde",orderIndex=1,flags=0}},db2PoiMapID=1,db2PoiUiMapID=85},
[50321] = {id=50321,name="Mojo Mischief",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={50321},description="De soldiers you rescued spoke of de raids on Zandalar. Blood troll raiders, frothing at de mouth and possessing supernatural strength, overwhelmed de defenders. Dey say dat their strength came from flasks of mojo dat de raiders drink before going into combat. We cannot allow de blood trolls to continue to possess them. Go down into de camp and destroy any of their flasks you may find.",objectivesText="Destroy 6 Flasks of Viscous Mojo.",rewardGold=245700,rewardXP=2765,mapCandidates={npc={},zone={8500}},questType="standard"},
[50322] = {id=50322,name="A Feathery Fad",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={50322},rewardItems={157538},mapCandidates={npc={},zone={8567}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=8,objectID=157538},{orderIndex=1,type=0,amount=1,objectID=141051}},worldTaskTitle="A Feathery Fad",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50324] = {id=50324,name="Picturesque Fizzsprings Resort",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={50324},objectivesText="Enriched Rockshell captured Resort Lodge captured Midland Fawn captured Secluded Spring captured",rewardItems={122674,157540},mapCandidates={npc={},zone={8567}},questType="world",db2Objectives={{text="Enriched Rockshell captured",amount=1,type=0,objectID=133479,orderIndex=0},{text="Resort Lodge captured",amount=1,type=0,objectID=133481,orderIndex=1},{text="Midland Fawn captured",amount=1,type=0,objectID=133484,orderIndex=2},{text="Secluded Spring captured",amount=1,type=0,objectID=133485,orderIndex=3}},worldTaskTitle="Picturesque Fizzsprings Resort",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50325] = {id=50325,name="Stopping the Grand Rite",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50265,50306,50325,50327,50329,50370,50445,50481,50530,50533},description="The witches of the Crimsonwood are planning a Grand Rite, a powerful ritual. They intend to rip open reality and bring their dark master through! I suspect they may be in communion with Gorak Tul. We cannot allow their ritual to succeed. I need you to be the tip of the spear while I protect Master Ashton and Marten. Cause havoc and disrupt their rituals!",objectivesText="Destroy the Ritual Foci. Progress: Destroy the Ritual Foci.",rewardGold=257400,rewardXP=2765,rewardItems={156859,156950,156951,157821,158064,158175},starts={{npcID=133098}},ends={{npcID=133098}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50370},questLines={{id=602,name="Crimson Forest",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50326] = {id=50326,name="Ain't No Place Like Home",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=9439,mapID=14,storyline={50326},description="Let me tell you, this is a big place, this Arathi Highlands, and I've no doubt at some point you are going to need to quick step it back to our lovely new base. How about I help you out with that?",objectivesText="Talk to Wistel Silversnitch",rewardItems={150733},ends={{npcID=131602}},mapCandidates={npc={14},zone={9439}},questType="standard"},
[50327] = {id=50327,name="A Little 'Pick Me Up'",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50265,50306,50325,50327,50329,50370,50445,50481,50530,50533},description="Now to mix this up. <Marten begins to combine the components in a mug> I'm using some rather strong grog as a base, a drop of chilli extract and a handful of hearthbloom... There! <Marten hands you a mug> It will taste worse than it smells, but it will bring Master Ashton to his senses. Please give this mug to him.",objectivesText="Give the mug to Master Ashton. Progress: <Ashton stares into the distance, eyes wide, muttering under his breath.>",rewardGold=25740,rewardXP=2765,rewardItems={156859,156950,156951,157821,158064,158175},starts={{npcID=133126}},ends={{npcID=133105}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50265,50306},questLines={{id=602,name="Crimson Forest",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50328] = {id=50328,name="Unconventional Aromatics",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47497,47498,47501,47502,47503,47564,47638,48320,48321,48322,48840,50328,51717,51718},description="A deal's a deal. You got the stingers for me, so here's that big batch of honey I promised. I hope you and Rhan'ka enjoy it... slowly. Seriously, do not eat this all at once. Oh, and I'm always looking to trade. Swing by anytime you got something to sell or want to pick up some more honey!",objectivesText="Deliver the Batch of Bilewing \"Honey\" to Rhan'ka at the Goldtusk Inn. Provided item:",rewardGold=25740,rewardXP=515,rewardItems={160665},starts={{npcID=133833}},ends={{npcID=122723}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51718},questLines={{id=5426,name="Goldtusk Inn",orderIndex=7,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50329] = {id=50329,name="Matrons of the Crimsonwood",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50265,50306,50325,50327,50329,50370,50445,50481,50530,50533},description="The witches in charge, the matrons... <Ashton shudders for a moment then composes himself.> The matrons are the ones leading the Grand Rite. They are fearsome but not invulnerable. Removing some of them from the equation will bolster our chances of stopping this. Take this potion. It will be able to weaken the matrons so you might have a better chance of dispatching them.",objectivesText="Kill Matrons Elsbeth Garrick, Stefania Denholm, and Wilona Blackwood. Progress: Did you kill them?",rewardGold=514800,rewardXP=3455,rewardItems={156859,156950,156951,157821,158064,158175},starts={{npcID=133105}},ends={{npcID=133105}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50370},questLines={{id=602,name="Crimson Forest",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50331] = {id=50331,name="A Different Outcome",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={50331},description="There is no way to know when these orders were sent, or received. Rokor took some Seekers north some time ago. They must be in that region by now. If the temple still stands, warn Gral and his followers. If it is lost, we must do what we can.",objectivesText="Find Rokor near Atal'Gral, to the north.",rewardGold=25740,rewardXP=175,rewardItems={156871},starts={{npcID=129717}},ends={{npcID=125047}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51407},nextQuests={48014,48015},startItems={157544}},
[50332] = {id=50332,name="Big Hunter Mon",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={50332},description="In these valleys, the Mon be kepin' beasts alive only to serve as sport. For his entertainment. The lives of others not be so cheap. Even the smallest creature can cause a whole lotta trouble. The Mon gonna be learnin' to respect that. I think this be a good time to teach this Big Hunter Mon a lesson, don't you? Be you my faithful messenger?",objectivesText="Survive Jani 's prank on Nesingwary. If you lose your saurid disguise, return to Jani for another. Progress: You taken my present to that big hunter mon yet, richmon?",rewardGold=257400,rewardXP=1415,starts={{npcID=133490}},ends={{npcID=133490}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47442,51145}},
[50335] = {id=50335,name="Grant Me Revenge",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=717,storyline={50335},description="I don't care who you pledge allegiance to, <race>. I need Hogger dead! He--and the other cretins in this Light-forsaken place--have slain my men. The Alliance and the Horde may not see eyes-to-eye, but you must know that murdering my people in cold blood cannot stand.",objectivesText="Defeat Randolph Moloch , Lord Overheat , and Hogger . Progress: Is it done? Is Hogger dead?",rewardGold=315000,rewardXP=1415,rewardItems={65915,65941,65965,65989,131683},starts={{npcID=46409}},mapCandidates={npc={},zone={717}},questGiverID=46409,questType="dungeon"},
[50336] = {id=50336,name="The G-Team",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=721,storyline={50336},description="I'd keep my distance from B.E Barechus and Murd Doc, neither is terribly stable. Let's get you to work! Go down into this tunnel until you get to Tinkers' Court. Hopefully you'll know what to do when you meet Mekgineer Thermaplugg . Our leader, Commando Hann Ibal waits somewhere in there. He'll reward you handsomely for all your work. Probably....",objectivesText="Kill Mekgineer Thermaplugg .",rewardGold=105000,rewardXP=1415,rewardItems={65913,65939,65963,65987,66004,131624,131625},rewardChoices={65987,66004,65963,65939,65913,131624,131625},starts={{npcID=44561}},mapCandidates={npc={},zone={721}},questGiverID=44561,questType="dungeon",sourceQuests={50337}},
[50337] = {id=50337,name="The G-Team",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=721,storyline={50337},series={26939,26941,26942,26943,26944,50338},description="That Murd Doc is crazy, <class>. Never, ever, let you find yourself in an aircraft with that gnome. Stealth usually isn't my thing, and it's certainly not going to be yours. Go down this hallway to the Launch Bay and dispose of the Electrocutioner 6000 . The Electrocutioner is in charge of the aircraft... ...and I hate aircraft. I'm not getting in any sort of aircraft! Use this parachute to drop down afterwards and speak with Commando Face for your next job.",objectivesText="Kill the Electrocutioner 6000 . Progress: Woah! How did you see me!?",rewardGold=105000,rewardXP=1415,rewardItems={60680,65913,65939,65963,65987,66004,131624,131625},starts={{npcID=44560}},mapCandidates={npc={},zone={721}},questGiverID=44560,questType="dungeon",sourceQuests={50338}},
[50338] = {id=50338,name="The G-Team",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=721,storyline={50338},series={26939,26941,26942,26943,26944,50337},description="How did you get in here, <name>? I'm Murd Doc of the G-Team and we could use the help of a <race> like you. Help us defeat the irradiated inhabatants that now call Gnomeregan home, and I'll make you an honorary G-Team Commando! Take this parachute, jump down into the Hall of Gears, and take out the Viscous Fallout . After you're done, report to Commando B.E Barechus by the west hallway. You two will get along great, I'm sure.",objectivesText="Kill the Viscous Fallout .",rewardGold=105000,rewardXP=1415,rewardItems={60680,65913,65939,65963,65987,66004,131624,131625},starts={{npcID=44556}},mapCandidates={npc={},zone={721}},questGiverID=44556,questType="dungeon"},
[50340] = {id=50340,name="Steal Them Back",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50340},description="<This empty crate of supplies is clearly marked with Kul Tiran signage. These must be the spoils of their raids on the farms of the valley. The citizens would probably like their supplies back if there are any left.>",objectivesText="Retrieve 5 Stolen Crates . Progress: Keep an eye out for anything useful. This place is very dangerous.",rewardGold=257400,rewardXP=4115,rewardItems={158735},rewardCurrencies={{id=1553,amount=75}},ends={{npcID=130190},{npcID=133953}},startObjects={{objectID=282478,mapID=942,x=0.463,y=0.77}},coords={mapID=942,source="quest_giver",x=0.576,y=0.665},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50353,50354}},
[50343] = {id=50343,name="Mayhem at Mildenhall Meadery",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50064,50070,50161,50162,50165,50168,50264,50343,50359,50493,50504,50534,50553},description="Ahhhh! <Sir/Miss>, please, I need some help! My dad hasn't come back from the meadery and, and... well, when I went to look, there were giant globs of honey everywhere. But... but, somehow, they were moving on their own. I even saw one eat a bunny, I swear! I'm scared to go back by myself, but I think dad is in trouble. Can you go with me?",objectivesText="Investigate the Mildenhall Meadery.",rewardGold=25740,rewardXP=515,starts={{npcID=131793}},ends={{npcID=131793}},mapCandidates={npc={942},zone={9042}},questTurnInID=131793,questType="standard",sourceQuests={51582},questLines={{id=5451,name="Not the Bees!",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50349] = {id=50349,name="An Overrun Mine",level=10,requiredLevel=10,faction="alliance",categories={},flags={"loremaster"},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={50349,50351,50352,50356},description="It was horrible! I was in the mine nearby, just picking away at a rock and it jumped up and bit me in the neck! Since when can rocks walk around and bite people? I hightailed it outta there, but some crazy fools are sticking around trying to take the mine back. If you're eager to punch rocks you can find them down the road to the south.",objectivesText="Find Chief Miner Theock at Winterdeep Mining Camp.",rewardGold=25740,rewardXP=175,starts={{npcID=133550}},ends={{npcID=133551}},mapCandidates={npc={895},zone={8567}},questType="standard",nextQuests={50351,50352},questLines={{id=5434,name="It's Mine",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[50350] = {id=50350,name="We Need a Chemist",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={50350},description="All this chaos started when we were picking at a large Azerite node deep in the mine. The mine began to rumble and all of these blasted creatures burst from the ground. If we could just get rid of that vein, I am sure we could retake the mine. First, we need a chemist. The best one we got is in his lab across the river. Find him and he'll give you more instructions.",objectivesText="Find Head Chemist Walters.",rewardGold=23870,rewardXP=175,mapCandidates={npc={},zone={8567}},questType="standard"},
[50351] = {id=50351,name="Miner Operation",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={50349,50351,50352,50356},description="The mine is in real trouble. We've been excavating for a short while, but never seen anything like this. Azerite doesn't just get up and walk around. If we are going to take the mine back, we're going to need more help. We'll need an engineer and an explosives expert. I have two in mind, sisters actually, but they are caught behind the river in all the chaos. Locate the sisters and they'll help you with the next phase of the plan.",objectivesText="Locate Civil Technician Alena and Ordnance Handler Prim .",rewardGold=257400,rewardXP=1415,starts={{npcID=133551}},ends={{npcID=133621}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={50349},questLines={{id=5434,name="It's Mine",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[50352] = {id=50352,name="Pinch of Azerite",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={50349,50351,50352,50356},description="I don't have time for idle chit chat! If you haven't noticed, rocks are running around doing who knows what?! How about you help out and retrieve my chemistry kit. While you're out, smash some of those creatures and collect their dust. Prim will need both of those for the next step of the plan. Maybe we can figure out what has animated the Azerite.",objectivesText="Collect 45 Azerite Dust and Walters' Chemistry Kit . Progress: Did you bring the dust?",rewardGold=257400,rewardXP=1415,rewardItems={157778,157857},starts={{npcID=133552}},ends={{npcID=133621}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={50349},questLines={{id=5434,name="It's Mine",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[50353] = {id=50353,name="Boaring Company",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50353,50354,50363,50365,50368,50622,50640,51354},description="I don't see her body anywhere. That means she could still be alive. The Briarback have been taking prisoners, and anyone who has ever been taken by them was never seen again. We have a single chance here and we need to take it! Come with me into the kraul and free as many of the survivors as you can. And if you can, find Farmer Deal . See if she's still alive.",objectivesText="Find and rescue 7 Captured Farmers and Farmer Deal . Progress: Please, find the prisoners!",rewardGold=257400,rewardXP=4115,rewardItems={133510,155824,155877,156577,156578,156648,157849,157850,160558,160561},rewardCurrencies={{id=1553,amount=75}},starts={{npcID=133953}},ends={{npcID=133953}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50622},questLines={{id=583,name="Storming the Kraul",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50354] = {id=50354,name="Look Out!",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9562,mapID=942,description="Some of these quilboar are clearly lookouts. Those horns make it obvious, almost like I could see their task floating above their heads. I was able to kill one, but not before he blew that horn of his and summoned backup. I suggest you keep them silent before they do the same with you. If we're going to get anywhere in there, you'll need to do it quietly. Here, Hobbs gave me a few of his sleeping darts. That should keep them quiet.",rewardGold=257400,rewardXP=4115,starts={{npcID=134752}},ends={{npcID=133953}},mapCandidates={npc={942},zone={9562}},questType="standard",sourceQuests={50622},questLines={{id=583,name="Storming the Kraul",orderIndex=2,flags=0}}},
[50356] = {id=50356,name="Rock Meet Dynamite",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={50349,50351,50352,50356},description="Thanks for your help out there, but we have to ask another favor from you. These elementals must be coming from somewhere in the mine and we need you to locate that source. You seem more than capable of handling yourself in there, but just for extra security I am going to send you with some of Prim's special dynamite. It has an extra kick from the Azerite dust that you gathered. Get in. Find the source. Put a stop to these elementals.",objectivesText="Eliminate the source of the Azerite creatures.",rewardGold=514800,rewardXP=1770,rewardCurrencies={{id=1553,amount=75}},starts={{npcID=134628}},ends={{npcID=133551}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={50351,50352},questLines={{id=5434,name="It's Mine",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[50358] = {id=50358,name="Desert Research",level=45,requiredLevel=45,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=9310,mapID=81,storyline={49977,49982,50052,50053,50054,50055,50057,50230,50231,50232,50300,50341,50358,50360,50364},description="The dark blade of Sargeras has cast a shadow of destruction over this land. It seemed that the silithid hives were destroyed in the attack, but I have received reports that the silithid are returning. If it were up to me, I'd burn those wretched hives once and for all! However, it is not up to me. The Dark Lady wants the surviving silithid dissected and studied. Pixni Rustbomb is conducting the research and is in need of a \"collector.\"",objectivesText="Speak with Pixni Rustbomb .",rewardGold=20220,rewardXP=770,starts={{npcID=132147}},ends={{npcID=132040}},mapCandidates={npc={81},zone={1377}},questType="standard",sourceQuests={50053},questLines={{id=576,name="Silithus: The Wound",orderIndex=11,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[50359] = {id=50359,name="Cleanup Duty",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50064,50070,50161,50162,50165,50168,50264,50343,50359,50493,50504,50534,50553},objectivesText="Kill 4 Flowing Honey and 4 Bubbling Mead .",rewardGold=309800,rewardXP=4115,starts={{npcID=132017}},ends={{npcID=132017}},mapCandidates={npc={},zone={9042}},questGiverID=132017,questTurnInID=132017,questType="standard",sourceQuests={50343},questLines={{id=5451,name="Not the Bees!",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50360] = {id=50360,name="Khadgar's Request",level=45,requiredLevel=45,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=9310,mapID=81,storyline={49977,49982,50052,50053,50054,50055,50057,50230,50231,50232,50300,50341,50358,50360,50364},description="Archmage Khadgar arrived while you were away. It seems that he is here to speak with you, <name>. Hurry and see what it is that he wants. I want him gone as soon as possible. The last thing we need is a human nosing around in Horde business!",objectivesText="Speak with Archmage Khadgar .",rewardGold=23870,rewardXP=770,starts={{npcID=132147}},ends={{npcID=130033}},mapCandidates={npc={81},zone={1377}},questType="standard",sourceQuests={50232},questLines={{id=576,name="Silithus: The Wound",orderIndex=21,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[50363] = {id=50363,name="War Pigs",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50353,50354,50363,50365,50368,50622,50640,51354},description="They look cute enough now, but that's a new herd of battleboars in training. Farmers don't like waste, and it would be a shame to get rid of such useful creatures. Either way, we could use those pigs, and I'd rather have them with us rather than face a bloodthirsty one in a few years. You should find them up on top of the cliffs overlooking the center of the kraul. Go round up as many piglets as you can take with you and we'll make good use of them.",objectivesText="Collect 8 Grazing Battle-Piglets .",rewardGold=257400,rewardXP=4115,rewardItems={133510,155824,155877,156577,156578,156648,157849,157850,160558,160561},starts={{npcID=133953}},ends={{npcID=133953}},mapCandidates={npc={942},zone={9562}},questType="standard",sourceQuests={50353,50354},questLines={{id=583,name="Storming the Kraul",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50364] = {id=50364,name="The Blood of Azeroth",level=45,requiredLevel=45,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=9310,mapID=81,storyline={49977,49982,50052,50053,50054,50055,50057,50230,50231,50232,50300,50341,50358,50360,50364},description="Do the leaders of the Alliance and Horde even know what they're fightin' over? This substance that is risin' up from the wound is the lifeblood of Azeroth! We need ta heal the wound, not exploit it fer power! Azeroth is the only home we've got. We cannot allow her ta die! I trust ye, <name>, and I know that yer voice carries great weight among the Horde. Ye must reason with 'em ta stop this madness! 'Tis the only hope our world has...",objectivesText="Deliver Magni Bronzebeard 's message.",rewardGold=202200,rewardXP=6140,starts={{npcID=130216}},ends={{npcID=132147}},mapCandidates={npc={81},zone={1377}},questType="standard",sourceQuests={50055},questLines={{id=576,name="Silithus: The Wound",orderIndex=25,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[50365] = {id=50365,name="Run For the Hills",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50353,50354,50363,50365,50368,50622,50640,51354},description="The quilboar are up to something, something big. You need to stop it! They've been busy bringing supplies up to the caves above their sanctum. Preserved thorns, cauldrons of venom, giant totems... They're preparing for war. Get up there and destroy those stockpiles before they can be used against the citizens of the valley!",objectivesText="Destroy the stockpiles of supplies.",rewardGold=257400,rewardXP=4115,rewardItems={133510,155824,155877,156577,156578,156648,157849,157850,160558,160561},starts={{npcID=133953}},ends={{npcID=133953}},mapCandidates={npc={942},zone={9562}},questType="standard",sourceQuests={50353,50354},questLines={{id=583,name="Storming the Kraul",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50367] = {id=50367,name="Anger in a Bottle",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={50367},description="<The bottle the quilboar was carrying contains a foul-smelling, orange liquid. You're not sure if it's safe to drink, but it can't hurt to gather some samples to bring back to the citizens of Brennadam. Maybe their alchemist can come up with an antidote to counter its effects.>",objectivesText="Collect 10 Foul-Smelling Samples . Progress: Do you have something for me?",rewardGold=257400,rewardXP=4115,rewardItems={133510,155824,155877,156577,156578,156648,157849,157850,160558,160561},ends={{npcID=133953}},startObjects={{mapID=942,x=0.428,y=0.697}},coords={mapID=942,source="quest_giver",x=0.487,y=0.683},mapCandidates={npc={942},zone={9562}},questType="standard",sourceQuests={50622},startItems={157849}},
[50368] = {id=50368,name="Terror of the Kraul",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50353,50354,50363,50365,50368,50622,50640,51354},description="By all the gods of the sea, what a monster! I can barely believe what I am seeing, <name>. This ettin has undergone the same ritual that the brutes do, and it seems even angrier! If he gets out of here, we won't stand a chance. I know I ask the impossible, but I must: kill this monstrosity and save the whole valley from its wrath! Here, take one of the potion samples you brought me. It's probably dangerous, but you might need it to defeat this beast.",objectivesText="Defeat Bramblefist the Maddened . Progress: We have to kill that thing!",rewardGold=491400,rewardXP=5145,rewardItems={133510,155200,155203,155205,155210,155218,155223,155225,155824,155877,156577,156578,156648,157849,157850,160520,160522,160558,160561},rewardChoices={155203,155218,160520,160522,155210,155223,155225,155205,155200},starts={{npcID=133953}},ends={{npcID=133953}},mapCandidates={npc={942},zone={9562}},questType="standard",sourceQuests={50363,50365,50367},questLines={{id=583,name="Storming the Kraul",orderIndex=6,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1183},
[50369] = {id=50369,name="Bruin Potions",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={50369},objectivesText="Bear Heart collected",rewardItems={157545,157546,160442},mapCandidates={npc={},zone={8721}},questType="world",db2Objectives={{text="Bear Heart collected",amount=6,type=1,objectID=157545,orderIndex=0}},worldTaskTitle="Bruin Potions",db2PoiMapID=1643,db2PoiUiMapID=896,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50370] = {id=50370,name="Deeper into the Woods",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50265,50306,50325,50327,50329,50370,50445,50481,50530,50533},description="We need to go deeper into the forest. The witches are clearly up to something even worse than I'd imagined. As much as I have a duty to return to Lady Lucille with Master Ashton, I also have a duty to find out more about this threat to our people, and stop it if I can. Going further into the forest is not without risk, but I believe it is one worth taking.",objectivesText="Travel with Cleardawn, Ashton, and Webb deeper into the forest. Progress: The risk has paid off",rewardGold=25740,rewardXP=345,rewardItems={156859,156950,156951,157821,158064,158175},starts={{npcID=133098}},ends={{npcID=133098}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50327},questLines={{id=602,name="Crimson Forest",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50372] = {id=50372,name="Desert Research",level=45,requiredLevel=45,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9310,mapID=81,storyline={49976,49981,50046,50047,50048,50049,50056,50057,50226,50227,50228,50371,50372,50373,50374},description="The dark blade of Sargeras has cast a shadow of destruction over this land. It seemed that the silithid hives were destroyed in the attack, but I have received reports that the silithid are returning. We need to find out how the silithid avoided destruction and what effect the blade is having on their hives. The crown wants the surviving silithid dissected and studied. Tammy Tinkspinner is conducting the research and is in need of a \"collector.\"",objectivesText="Speak with Tammy Tinkspinner .",rewardGold=20220,rewardXP=770,starts={{npcID=131963}},ends={{npcID=132606}},mapCandidates={npc={81},zone={1377}},questType="standard",sourceQuests={50046,50047},questLines={{id=576,name="Silithus: The Wound",orderIndex=8,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[50373] = {id=50373,name="A Recent Arrival",level=45,requiredLevel=45,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9310,mapID=81,storyline={49976,49981,50046,50047,50048,50049,50056,50057,50226,50227,50228,50371,50372,50373,50374},description="The situation in Silithus appears to be gaining more attention. Archmage Khadgar just arrived while you were away. It seems that he is here to speak with you, <name>. It appears urgent. I would speak with him as soon as possible.",objectivesText="Speak with Archmage Khadgar .",rewardGold=20220,rewardXP=770,starts={{npcID=131963}},ends={{npcID=130032}},mapCandidates={npc={81},zone={1377}},questType="standard",sourceQuests={50228},questLines={{id=576,name="Silithus: The Wound",orderIndex=20,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[50374] = {id=50374,name="The Blood of Azeroth",level=45,requiredLevel=45,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9310,mapID=81,storyline={49976,49981,50046,50047,50048,50049,50056,50057,50226,50227,50228,50371,50372,50373,50374},description="Do the leaders of the Alliance and Horde even know what they're fightin' over? This substance that is risin' up from the wound is the lifeblood of Azeroth! We need ta heal the wound, not exploit it fer power! Azeroth is the only home we've got. We cannot allow her ta die! I trust ye, <name>, and I know that yer voice carries great weight among the Alliance. Ye must reason with 'em ta stop this madness! 'Tis the only hope our world has...",objectivesText="Deliver Magni Bronzebeard 's message.",rewardGold=202200,rewardXP=6140,starts={{npcID=130216}},ends={{npcID=131963}},mapCandidates={npc={81},zone={1377}},questType="standard",sourceQuests={50049},questLines={{id=576,name="Silithus: The Wound",orderIndex=24,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[50375] = {id=50375,name="Ride With Me",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={50375},description="I have hunted many powerful foes, $p. My pack has defended this island and its people from countless outside threats and foreign invaders. But there is a darkness growing in Zandalar. A corruption so deep and relentless that it consumes the minds of the Zandalari. I cannot hunt intangible darkness, but I can hunt those who wield it against my people. Come, ride with me and my pack. I smell the foul stench of blood trolls nearby. We will see how well you hunt with the pack.",objectivesText="Ride Gonk as he investigates the source of corruption nearby.",rewardGold=101100,rewardXP=710,mapCandidates={npc={},zone={8499}},questType="standard"},
[50376] = {id=50376,name="Deadliest Cache: Reel Big Fish",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50376,50391,50418,52130},description="Can ye believe the nerve of these scallywags? Questioning the very Coxswain of this here wharf? Bah! Lend me your ear for a moment or three. I've got a tale that'll put brew in your mug and a quiver in your boots! It was the biggest, deadliest cache I ever did loot on these seas...",objectivesText="Listen to Coxswain Hook 's tale. Progress: Want to hear more?",rewardGold=514800,rewardXP=5145,starts={{npcID=133576}},ends={{npcID=133576}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={53045},questLines={{id=5450,name="Deadliest Cache",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50381] = {id=50381,name="The Great Hat Robbery",level=10,requiredLevel=10,faction="both",categories={},flags={"loremaster"},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={50381},description="Along this road the merchants ride. Taking dere wares from one place to another and lining them own pockets. One Big Mon named Tik'su be the worst of all. He charge arms and legs outright and it even take trolls some time to regrow them parts. His biggest pride? His hat. Go be my messenger, Rich-mon. Scare his burdened beast and knock off Tik'su . Then bring me his hat.",objectivesText="Successfully steal Tik'su 's Hat. If you lose your saurid disguise, return to Jani for another. Progress: You had a chat with Tik'su about his hat yet, richmon?",rewardGold=257400,rewardXP=1415,starts={{npcID=133612}},ends={{npcID=133612}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47442,51145}},
[50385] = {id=50385,name="Indefatigable Purpose",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50385,50386,50387,50388,50389,50417,53099,53105},description="Its grip weakens, if only briefly. We must claim this place anew! Flopping, nightmarish horrors have infested the caves amongst the cove. Take the sacred blessings. Venture forth into the dark and find their altars. Purge their blasphemous constructions from our lands!",objectivesText="Cleanse 3 Drowned Altars .",rewardGold=234000,rewardXP=6815,rewardItems={157771},starts={{npcID=133640},{npcID=143565}},ends={{npcID=133640},{npcID=143565}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={53105},questLines={{id=577,name="The Forgotten Cove",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50386] = {id=50386,name="Flush Them Out",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50385,50386,50387,50388,50389,50417,53099,53105},series={50417},description="They lurk in the shadows, in the salt-soaked caverns. The dark brine beneath the pure gleam of the surface. I have seen them. They plague my dreams, their whispers are maddening. They speak of their master, clawing at the barrier... Search the cliffs for their warrens. Find what lurks within and obliterate them all.",objectivesText="Investigate and defeat what lies within 4 structures in the Forgotten Cove. Progress: Ignorance of our enemy will invariably lead to defeat.",rewardGold=234000,rewardXP=6815,starts={{npcID=133640},{npcID=143565}},ends={{npcID=133640},{npcID=143565}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50417},questLines={{id=577,name="The Forgotten Cove",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50387] = {id=50387,name="Trinkets and Baubles",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50385,50386,50387,50388,50389,50417,53099,53105},description="Beneath the tides, these terrors do not see fit to stay within their warrens. They have emerged in the night, stealing away to the villages and indulging in their avarice. They will use the provisions against us, to serve in their rituals. Rituals of summoning and communion with powers too terrible to comprehend. The populace is no concern of mine anymore, but I would not see these briny thieves to have their way. Relieve them of their plunder, and let them learn a bitter lesson.",objectivesText="Recover 3 crates of Stolen Supplies . Progress: Where there is no peril, there can be no glory!",rewardGold=234000,rewardXP=6815,rewardItems={9172,116268,127840,152496,157784},starts={{npcID=133640},{npcID=143565}},ends={{npcID=133640},{npcID=143565}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={53097},questLines={{id=577,name="The Forgotten Cove",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50388] = {id=50388,name="The Weight of My Ambition",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50385,50386,50387,50388,50389,50417,53099,53105},description="As with the other settlements, I too relied on the services of sailors and watercraft to deliver supplies. They proved very useful in their diligence, and their silence. Predictably, they drew the attention of enemies, including those below the waves. Their anchor was hexed, dragging them beneath the ocean before they could so much as cry out. I have seen them, hoisting ethereal sails and singing shanties of the damned. If these waters are to be safe again, they must be silenced again. For good.",objectivesText="Defeat the Drowned Captain .",rewardGold=468000,rewardXP=8520,starts={{npcID=133640},{npcID=143565}},ends={{npcID=133640},{npcID=143565}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50387},questLines={{id=577,name="The Forgotten Cove",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50389] = {id=50389,name="Malign Inspiration",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50385,50386,50387,50388,50389,50417,53099,53105},description="A long time ago, there was a maiden. A precocious child fond of song, she made it her hobby to shadow my every move. Charming at first. Walking on the pier's edge, she became entangled within the ropes surrounding a leering idol. At that time a tremor ran through the waves, giving the small push needed to send them both beneath the surface. I can hear her song still. At first I thought it a passing fancy, music upon the waves. I realize now the voice comes with sinister purpose. She must die.",objectivesText="Kill the Enchanting Siren .",rewardGold=468000,rewardXP=8520,starts={{npcID=133640},{npcID=143565}},ends={{npcID=133640},{npcID=143565}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50385},questLines={{id=577,name="The Forgotten Cove",orderIndex=6,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50391] = {id=50391,name="Deadliest Cache: Gun Fishin'",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50376,50391,50418,52130},description="Hook's got a screw loose in her head, I tell ya. Sharks workin' together on somethin'... phooey! It does remind me of one of my favorite tales, though. Have I ever told ya 'bout the time I caught THE single largest, deadliest, most tentacled beast in all o' Azeroth?! Aye, I thought not. It's not a story I'd tell ya sober. It was a day unlike any other...",objectivesText="Listen to Master Gunner Line 's tale. Progress: Aye, lad?",rewardGold=514800,rewardXP=5145,rewardItems={157783},starts={{npcID=133577}},ends={{npcID=133577}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50376},questLines={{id=5450,name="Deadliest Cache",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50393] = {id=50393,name="A Child of Pa'ku",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50393},series={50394},description="<The pterrordax egg is warm and trembling. It will hatch soon.> Perhaps a certain pterrordax loa can help you.",objectivesText="Take the Pterrordax Egg to Pa'ku at Pterror Rise. Provided item:",rewardGold=23400,rewardXP=850,rewardItems={54981,54982,57277,57278,57279,57280,57458,57459,57460,66894,66896,66897,118938,128659,131351,131455,157782,159146,242386},ends={{npcID=127377}},coords={mapID=862,source="quest_giver",x=0.711,y=0.5},mapCandidates={npc={862},zone={8499}},questType="standard",startItems={157782}},
[50394] = {id=50394,name="Your Problem Now",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50394},series={50393},description="Hm. This egg does not belong to one of my brood, and I have no broodlings that need another sibling. < Pa'ku might be smiling or snarling. She is showing an awful lot of teeth.> You will care for this little one. And you had better hurry. It will hatch very soon. Oh, and a little advice. If you want the little one to like you, you had better be the first thing it sees upon hatching.",objectivesText="Place the Pterrordax Egg at the empty nest and wait for it to hatch.",rewardGold=117000,rewardXP=3410,rewardItems={157782,159146},starts={{npcID=127377}},ends={{npcID=133678}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50393}},
[50395] = {id=50395,name="The Call of the Skies",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50395},series={50401,50412},description="< Kua'fon turns his head toward the cliff and chirps eagerly. He spreads his tiny wings and flaps vigorously.> It is time to leave the nest.",objectivesText="Watch your hatchling take its first leap into the great unknown. Progress: What do you need, grounded one?",rewardGold=28300,rewardXP=850,rewardItems={157782,159146},starts={{npcID=133678}},ends={{npcID=127377}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={52305}},
[50396] = {id=50396,name="A Pterrible Fate",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50396},description="< Kua'fon peers longingly toward the horizon and gives a keening cry. You can take the pterrordax from the sky, but not the sky from the pterrordax. It's time to do something. Perhaps Pa'ku could offer some advice.>",objectivesText="Ask Pa'ku for help.",rewardGold=23400,rewardXP=850,starts={{npcID=133679}},ends={{npcID=127377}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={52447}},
[50397] = {id=50397,name="Aerial Aspirations",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50397},description="< Kua'fon studies you intensely. One single golden eye is trained on you, unwavering.> Skree. <He then turns his maw toward the horizon and spreads his wings wide.> Skree! <Is it finally time?>",objectivesText="Fly?",rewardGold=23400,rewardXP=850,starts={{npcID=133682}},ends={{npcID=133682}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={52748}},
[50401] = {id=50401,name="Fear of Falling",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50401},series={50395,50412},description="Some young find their wings sooner than others. At least yours had the sense to keep them open. I would not worry too much about its safety- little ones tend to bounce. As for this failure... the young must keep trying, and they must learn not to fear falling. It is now your task to teach it. <The loa smiles at you, all teeth.> If it is reluctant to learn, you might consider bribery.",objectivesText="Find your hatchling and convince it to return to the nest. Progress: < Kua'fon quivers in fear and chirps at you in distress. Perhaps a treat could soothe your hatchling?>",rewardGold=234000,rewardXP=6815,rewardItems={109076,157782,158885,159146},starts={{npcID=127377}},ends={{npcID=133678}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50395}},
[50402] = {id=50402,name="SKREEEEE!",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50402},description="< Kua'fon stares at you for a moment, then opens his maw and unleashes a continuous screech. You need help.>",objectivesText="Find out what is distressing your hatchling and address it. Progress: <The hatchling's gaze scours your person in search of anything edible. It may be best to keep your fingers out of reach.> Skree!? Skree!",rewardGold=234000,rewardXP=6815,rewardItems={141605,157779,157780,157781,157782,159146},starts={{npcID=133678}},ends={{npcID=133678}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50394}},
[50412] = {id=50412,name="Back to the Nest",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50412},series={50395,50401},description="< Kua'fon peers up at you trustingly.> Now would be a good time to take him back to the nest.",objectivesText="Return Kua'fon to his nest in Pterror Rise.",rewardGold=117000,rewardXP=3410,rewardItems={157782,159146},starts={{npcID=133678}},ends={{npcID=133678}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50401}},
[50417] = {id=50417,name="Ruin Has Come",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50385,50386,50387,50388,50389,50417,53099,53105},series={50386},description="There is a terror beneath the waves. It seeks to destroy my family, my house, and my legacy. You must come, claim your destiny and deliver us from the terrors of the deep! Find our estate to the east, among the isles. We lived opulently in the shadow of the great fortress. We believed the priests would deliver us from the darkness below. Now that darkness has bubbled to the surface, whispering madness in our dreams. Hurry. The air turns the darkest I have seen in my cursed existence.",objectivesText="Find the author of the Mysterious Letter.",rewardGold=23400,rewardXP=850,rewardItems={163017},ends={{npcID=133640},{npcID=143565}},startObjects={{objectID=281348,mapID=942,x=0.5,y=0.318}},coords={mapID=942,source="quest_giver",x=0.787,y=0.546},mapCandidates={npc={942},zone={9042}},questType="standard",questLines={{id=577,name="The Forgotten Cove",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50418] = {id=50418,name="Deadliest Cache: Sink and Swim",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50376,50391,50418,52130},description="Mph mph! Mph mph mph mph mph. Mph mph mph. Mph. Mph mph? Mph!",objectivesText="\"Listen\" to \"Sinker's\" \"tale\". Progress: Mph?",rewardGold=514800,rewardXP=5145,starts={{npcID=133578}},ends={{npcID=133578}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50391},questLines={{id=5450,name="Deadliest Cache",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50420] = {id=50420,name="A Gently Shaken Gift",level=10,requiredLevel=10,faction="none",categories={"seasonal"},flags={},sharable=true,event="Feast of Winter Veil",expansion=7,storyline={50420},rewardItems={21270,21271,116762,128652,128768,139337,139343,151343,151345,162974,172225,178529,187520,192093,210657,218309,244906},startObjects={{objectID=180746}},mapCandidates={npc={},zone={}},questType="standard"},
[50421] = {id=50421,name="Sparring on the Spar",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={50421},objectivesText="Climb the mast Push the opponent off the spar",rewardGold=421350,rewardXP=2090,mapCandidates={npc={},zone={8567}},questType="world",db2Objectives={{text="Climb the mast",amount=1,type=2,objectID=281297,orderIndex=0},{text="Push the opponent off the spar",amount=1,type=0,objectID=133810,orderIndex=1}},worldTaskTitle="Sparring on the Spar",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50432] = {id=50432,name="Titanic Innovation",level=45,requiredLevel=45,faction="both",sharable=false,expansion=7,zoneID=7502,mapID=627,rewardCurrencies={{id=1533,amount=5}},starts={{npcID=106655}},ends={{npcID=106655}},mapCandidates={npc={},zone={7502}},questGiverID=106655,questTurnInID=106655,questType="standard",questLines={{id=295,name="Titanic Innovation",orderIndex=0,flags=0}}},
[50433] = {id=50433,name="Zanchuli Disbanded",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=9598,mapID=1165,series={51111,49421,49965},description="I would like to say we are doing well, but we are not. De Zanchuli Council is broken. Raal and I are all dat remain who are still loyal to King Rastakhan. You best bring news to your Horde and tell dem what transpired here. Raal and I will rally what support we can and head for de Zocalo. And hero, thank you for saving my life and my loa.",rewardGold=25740,rewardXP=175,starts={{npcID=122760}},ends={{npcID=122760}},mapCandidates={npc={862},zone={9598}},questTurnInID=122760,questType="standard",sourceQuests={47528,47741},nextQuests={49421,51555},questLines={{id=595,name="Web of Lies",orderIndex=8,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=79,flags=1}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[50443] = {id=50443,name="Down to the Roots",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={50443},objectivesText="Bloodlasher Seedling destroyed",rewardGold=309800,rewardXP=1415,rewardItems={209910},mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{text="Bloodlasher Seedling destroyed",amount=15,type=0,objectID=133855,orderIndex=0}},worldTaskTitle="Down to the Roots",db2PoiMapID=1642,db2PoiUiMapID=863,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50444] = {id=50444,name="Taking the Loa Road",level=20,requiredLevel=20,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={50444},description="This road not be traveled much anymore. Except by those that serve the blood Loa. They be fools. I be wantin' my fun from those fools. Go to the spot I be markin' for you and plant this cursed coin . The silly blood trolls be seein' it and give us a laugh when they try to pick it up. Just be makin' sure that no other creature see you. Or else it be a quick trip back to the arms of Jani .",objectivesText="Survive Jani 's prank on the Amaki trolls. If you lose your saurid disguise, return to Jani for another. Progress: You taken that cursed coin to the pranking-place yet, richmon?",rewardGold=257400,rewardXP=2765,starts={{npcID=136608}},ends={{npcID=136608}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={47442,51145}},
[50445] = {id=50445,name="Controlling the Situation",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50265,50306,50325,50327,50329,50370,50445,50481,50530,50533},description="I have been observing this macabre army of, wood, flesh, and bone and how the witches and servitors control the lesser creations with charms. I believe I can craft an even more powerful charm - one we can use. In the hearts of the servitors are the very strongest charms. They are used to anchor the Ancient Drust into their physical forms. They are precisely what we need. Good luck. It is doubtful that they will part with them easily.",objectivesText="Collect 5 Control Charms from the Haunted Servitors. Progress: Were you able to collect enough charms?",rewardGold=257400,rewardXP=2765,rewardItems={156859,156950,156951,157821,158064,158175,158557},rewardChoices={158557},starts={{npcID=133105}},ends={{npcID=133105}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50370},questLines={{id=602,name="Crimson Forest",orderIndex=6,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50446] = {id=50446,name="Witchrending",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49926,50003,50149,50151,50173,50253,50446,50453,50457},description="A blunderbuss? I'd have to say, I wasn't quite expecting that. Nonetheless, now that we have a weapon, we have an advantage. I think it's time we take the fight directly to the coven. Marshal Reade informed me that several of their Matrons have been spotted throughout Corlain. Let's show them what happens to an enemy of House Waycrest.",objectivesText="Use Witchrend to defeat Matrons Ceridwen , Adeline, and Letitia in Corlain.",rewardGold=514800,rewardXP=3455,rewardItems={156722,156853,156855,157800,158584,158585,158586,158587,158627,158628,158629,158630},rewardChoices={158584,158585,158586,158587,158627,158628,158629,158630},starts={{npcID=131638}},ends={{npcID=131638}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50253},questLines={{id=598,name="Corlain",orderIndex=6,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=44,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50447] = {id=50447,name="Remembering the Fallen",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50152,50447,50449,50450,50451,50452,50453,50454,50455,50456},description="<This villager died clutching a brooch with what looks like a family crest. It looks like several villagers didn't survive the coven's occupation of Corlain. It might be possible to identify the fallen by the keepsakes they carried. The survivors would likely be grateful to learn the fate of their loved ones.>",objectivesText="Collect 8 Personal Keepsakes from fallen Corlain Villagers in Corlain. Progress: What's this?",rewardGold=257400,rewardXP=2765,rewardItems={157806},starts={{npcID=134009}},ends={{npcID=129642},{npcID=131638}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50253},questLines={{id=5445,name="Caring about Corlain",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50448] = {id=50448,name="Reclaiming Corlain",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={50448},objectivesText="Combat the Heartsbane Coven",rewardGold=455280,rewardXP=1415,mapCandidates={npc={},zone={8721}},questType="standard",sourceQuests={50253},db2Objectives={{text="Combat the Heartsbane Coven",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Reclaiming Corlain",db2PoiMapID=1643,db2PoiUiMapID=896},
[50449] = {id=50449,name="Reeking Refuge",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50152,50447,50449,50450,50451,50452,50453,50454,50455,50456},description="Oh good, maybe you can make sense of this. I was just carving through a swath of the coven's lackeys when I stumbled across this field. Something here has knocked these guys completely out of commission! I can't seem to find the source, but maybe you'll have better luck. I'm more used to hitting things than investigating them.",objectivesText="Investigate what is disabling the coven's minions in Hocking's Plot.",rewardGold=25740,rewardXP=345,starts={{npcID=131639}},ends={{npcID=133839}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50253},questLines={{id=5445,name="Caring about Corlain",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50450] = {id=50450,name="An Offensive Harvest",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50152,50447,50449,50450,50451,50452,50453,50454,50455,50456},description="So you're takin the fight to the coven with the Waycrest girl, eh? Ya might just be able to take advantage of their apparent onion aversion. While you're out rootin' in the field, keep an eye out for any onions bulging out of the ground. Those ones should be particularly aromatic, and should cause some fits in the coven's minions if you keep it on ya. Just try not to take too much, right? I need enough left in the fields to keep the farm safe.",objectivesText="Collect 7 Aromatic Onions from Hocking's Plot. Progress: Did ya find any good ones?",rewardGold=257400,rewardXP=2765,rewardItems={157807},starts={{npcID=133839}},ends={{npcID=133839}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50449},questLines={{id=5445,name="Caring about Corlain",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50451] = {id=50451,name="Eating Through the Defenses",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50152,50447,50449,50450,50451,50452,50453,50454,50455,50456},description="Not sure why and don't rightly care, but for some reason the coven can't come near my onion field. So long as my crop doesn't give out, I can hole up in here as long as it takes. Unfortunately, those boars got the same idea and now they're eatin' up my harvest! If they keep that up, soon there'll be nothin' keepin' the coven at bay! If you can do me a favor and thin them out, I'd be happy to let you take some of these onions with you.",objectivesText="Kill 8 Scavenging Boars in Hocking's Plot. Progress: How's the boar situation?",rewardGold=257400,rewardXP=2765,starts={{npcID=133839}},ends={{npcID=133839}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50449},questLines={{id=5445,name="Caring about Corlain",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50452] = {id=50452,name="Potent Protection",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50152,50447,50449,50450,50451,50452,50453,50454,50455,50456},description="Here ya go, I got them onions bundled up nicely for ya. Give my regards to Miss Waycrest, will ya? Her allies are welcome on my farm anytime.",objectivesText="Deliver the Sack of Aromatic Onions to Lucille Waycrest at Watchman's Rise. Provided item:",rewardGold=25740,rewardXP=345,rewardItems={155564,157846},rewardChoices={155564},starts={{npcID=133839}},ends={{npcID=129642},{npcID=131638}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50450,50451},questLines={{id=5445,name="Caring about Corlain",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50453] = {id=50453,name="Barrier Buster",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50152,50447,50449,50450,50451,50452,50453,50454,50455,50456},description="Oy, <name>! I think I might have a solution te that pesky barrier keepin ye out of Corlain proper! I took the silver we had left 'ere an' doctored up one o' these cannonballs. The walls surroundin' Corlain are festooned with defensive cannons. Get one pointed at the gate, ye can send this beauty right into the barrier! Ye'll need a hefty pinch of powder te get this thing movin', though - it's a bit on the heavy side. Ye can likely find some in the camp outside the walls.",objectivesText="Collect 5 Blasting Powder from Pikeman's Ridge and bring them to Inquisitor Sterntide outside the gate into Upper Corlain. Progress: I don't think these guys will be needin' this cannon anymore.",rewardGold=309800,rewardXP=2765,rewardItems={156722,156853,156855,157800},starts={{npcID=132193}},ends={{npcID=131642}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50446},questLines={{id=598,name="Corlain",orderIndex=7,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=45,flags=0},{id=5445,name="Caring about Corlain",orderIndex=6,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50454] = {id=50454,name="A Traitor's Death",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50152,50447,50449,50450,50451,50452,50453,50454,50455,50456},description="It has come to my attention that you intend to assault the camp outside of the walls. If this is so, I have a request. Though most of the guardsmen who fight against us were turned to the coven against their will, Captain Goodspeed and his brigade of halberdiers gave their souls willingly to the Heartsbane. They are traitors and an affront to the Waycrest Guard. You will find Goodspeed and his men stationed at the camp. I would consider it a personal favor if you would cut them down to the last.",objectivesText="Kill Captain Goodspeed . Progress: Is it done?",rewardGold=514800,rewardXP=3455,rewardItems={44358,44359,44360,44361,155462,155471,155479,155487,158599,158600,158601,158602},rewardChoices={158599,158600,158601,158602,155462,155471,155479,155487},starts={{npcID=131636}},ends={{npcID=131636},{npcID=137368}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50453},questLines={{id=5445,name="Caring about Corlain",orderIndex=7,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50455] = {id=50455,name="Leaving the Nest",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50152,50447,50449,50450,50451,50452,50453,50454,50455,50456},description="It looks like the coven hasn't managed to enthrall all of our falcons. I can see some untainted ones still in cages in the training yard. Our falcons are well trained, and should know to fly to one of our other yards if something happens to their handlers. If you can just release them from their cages, they should be able to make it to safety.",objectivesText="Open 5 Falcon Cages in the Corlain Aviary.",rewardGold=257400,rewardXP=2765,rewardItems={157840},starts={{npcID=131640}},ends={{npcID=131640}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50446},questLines={{id=5445,name="Caring about Corlain",orderIndex=9,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50456] = {id=50456,name="Hexed Hatchlings",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50152,50447,50449,50450,50451,50452,50453,50454,50455,50456},description="I've found where those evil witches have been tainting our falcons! You see those charms? <Notley motions toward the high perches and roofs nearby.> They're using those to infect our flock with their evil magic as they hatch. I think Winston can get up there to take out the charms, but someone will need to direct him. I'm not quite healed up enough to take on a whole camp of falconers. Can you help?",objectivesText="Use the Falconer's Whistle to destroy 7 bewitching charms in the Corlain Aviary. Progress: Have you taken care of the charms?",rewardGold=257400,rewardXP=2765,rewardItems={157845},starts={{npcID=131640}},ends={{npcID=131640}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50446},questLines={{id=5445,name="Caring about Corlain",orderIndex=8,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50457] = {id=50457,name="Break On Through",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49926,50003,50149,50151,50173,50253,50446,50453,50457},description="Cannon's ready, boss. Care to do the honors?",objectivesText="Use the Ramparts Cannon to break the barrier at the gate to Upper Corlain.",rewardGold=25740,rewardXP=345,rewardItems={156722,156853,156855,157800},starts={{npcID=131642}},ends={{npcID=131638}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50453},questLines={{id=598,name="Corlain",orderIndex=8,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=46,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50459] = {id=50459,name="Vugthuth",level=50,requiredLevel=50,faction="none",sharable=false,expansion=7,zoneID=8500,mapID=863,mapCandidates={npc={},zone={8500}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=128584}},worldTaskTitle="Vugthuth",db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[50461] = {id=50461,name="Zujothgul",level=50,requiredLevel=50,faction="none",sharable=false,expansion=7,zoneID=8500,mapID=863,mapCandidates={npc={},zone={8500}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=128578}},worldTaskTitle="Zujothgul",db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[50466] = {id=50466,name="He's Gone Mad!",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={50466},series={47586,49768},description="Ol' Wildtusk has withstood years of attacks by young hunters that are overeager and underskilled. None could take him. His wounds have finally done him in. He just won't go down. Find that crazy riverbeast bull, and help him let go of his mortal shell.",objectivesText="Kill Wildtusk .",rewardGold=514800,rewardXP=1770,rewardItems={158423,158424,158425,158426,158444,158445,158446,158447},rewardChoices={158423,158424,158425,158426,158444,158445,158446,158447},starts={{npcID=123005}},ends={{npcID=123019}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49768}},
