[50476] = {id=50476,name="The Warchief Awaits",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=1497,mapID=90,storyline={50476,50642,50646,50647,50738,50740,50772,50800,50823,50837,50878,50879,50880,52436,52437,52438,52806,52967,52970,52971,52981,53604,53605,53606,53608,53609,53610,53627},series={50642,50646,50647,50738},description="<name>, There are important matters I would like to discuss with you, but discretion is of the utmost importance. Meet me in my chambers in the Undercity where I can assure our privacy has not been compromised. Ensure that you are not followed; Orgrimmar has become riddled with SI:7 spies. It would seem that that King Anduin and Mathias Shaw are desperate to know what our next move is. How admirable.",objectivesText="Report to Warchief Sylvanas Windrunner in the Undercity.",rewardGold=200,rewardXP=175,rewardItems={157832,158075,158937,160251,163127,163128},starts={{npcID=10181}},ends={{npcID=134554}},mapCandidates={npc={62,90},zone={1497}},questType="standard",questLines={{id=584,name="The Warchief's Command",orderIndex=0,flags=0}},db2DetailThemeID=5,db2PoiUiMapID=90,startItems={157832}},
[50481] = {id=50481,name="In the Hall of the Drust King",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50265,50306,50325,50327,50329,50370,50445,50481,50530,50533},description="I've been watching a lot of activity going on at the ruins at the base of the massive tree by the lake. What Master Ashton reported is accurate - something important is going on down there. We've disrupted their rituals but I worry we might have been too late. We need to go over there. If there is anything remaining, we must destroy it.",objectivesText="Confront Gorak Tul . Progress: We must confront Gorak Tul .",rewardGold=514800,rewardXP=3455,rewardItems={156859,156950,156951,157821,158064,158175},starts={{npcID=133098}},ends={{npcID=133098}},mapCandidates={npc={896},zone={8721}},questTurnInID=133098,questType="standard",sourceQuests={50325,50329,50445,50530},questLines={{id=602,name="Crimson Forest",orderIndex=8,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
