[50550] = {id=50550,name="The Fall of Emperor Korthek",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="Korthek finally approaches. It's been many years since I've faced him in battle. When he first rose to power, I failed my people. I will not falter again. I am prepared to do what must be done. What I should have done long ago. We must kill Korthek and take his key to prevent him, Jakra'zet, or anyone else from ever resurrecting Mythrax. When you are prepared, we will face him together.",objectivesText="Defeat Emperor Korthek .",rewardGold=828600,rewardXP=6175,rewardItems={155417,155418,155434,155440,155444,160032,160033,160034},rewardChoices={155440,155434,160033,160034,160032,155417,155418,155444},starts={{npcID=138411}},ends={{npcID=135390},{npcID=138519}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50750,50752},questLines={{id=610,name="Storming the Spire",orderIndex=11,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=58,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50551] = {id=50551,name="Temple of Sethraliss: Avatar of the Loa",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={50551},description="We cannot let Mythrax bring his destruction upon this world once more. We need our loa now more than ever, but she has yet to return to us. The time of her rebirth has passed. Someone, or something, must be preventing her awakening. Enter her resting place and see what you can uncover.",objectivesText="Enter the Temple of Sethraliss and heal the avatar of the loa. Progress: We cannot let Mythrax bring his destruction upon this world once more.",rewardGold=954720,rewardXP=8230,rewardCurrencies={{id=1553,amount=600}},starts={{npcID=129588}},ends={{npcID=129588}},mapCandidates={npc={864},zone={8501}},questType="dungeon",sourceQuests={50702}},
[50553] = {id=50553,name="Back to the Lab",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50064,50070,50161,50162,50165,50168,50264,50343,50359,50493,50504,50534,50553},description="Our work here is done! Well, at least until another one of my humble experiments goes horribly awry, rapidly spiraling out of control into a chain reaction of catastrophic failures. But, let's worry about that another time, $p. I'll meet you back at my lab!",objectivesText="Meet Raimond Mildenhall in his Raimond's Laboratory.",rewardGold=25740,rewardXP=515,rewardItems={158558},rewardChoices={158558},starts={{npcID=134447}},ends={{npcID=133204}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50165,50493,50534},questLines={{id=5451,name="Not the Bees!",orderIndex=12,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50559] = {id=50559,name="Getting Out of Hand",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={50559},objectivesText="Undead destroyed",rewardItems={153058},mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{text="Undead destroyed",amount=40,type=0,objectID=127902,orderIndex=0}},worldTaskTitle="Getting Out of Hand",db2PoiMapID=1642,db2PoiUiMapID=863,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50561] = {id=50561,name="Sulthis' Stone",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47716,48313,48314,48315,48896,50539,50561,50770},description="<The ancient reliquary contains a single stone, humming with magic. Perhaps Serrik will know what it is?>",objectivesText="Deliver Sulthis' Stone to Serrik within Zul'Ahjin. Progress: What have you found?",rewardGold=257400,rewardXP=4115,rewardItems={157865,159984,159985,159986,159987,159988,159989,159990,159991},rewardChoices={159984,159985,159986,159987,159988,159989,159990,159991},ends={{npcID=134533}},startObjects={{objectID=281583,mapID=864,x=0.488,y=0.742}},coords={mapID=864,source="quest_giver",x=0.47,y=0.756},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48315},questLines={{id=608,name="A City of Secrets",orderIndex=7,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=41,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
