[50573] = {id=50573,name="Message from the Management",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={47181,47485,47486,47487,47488,50531,50573,53041},series={47485,47486,47488,47489,50531,53041},description="<This letter from Priscilla Ashvane to her employees appears to be posted all over the foundry. It sounds like Cagney's information was accurate, Ashvane is working their people around the clock. Priscilla mentions a Forgemaster Farthing and a Taskmaster Williams. They may have more information about her plans.>",objectivesText="Collect Priscilla's Orders from Forgemaster Farthing and Taskmaster Williams. Progress: Find anything useful in there?",rewardGold=257400,rewardXP=1415,rewardItems={155027,155028,155029,155030,155035,155036,155037,155038,158065,158066,163032,163034},rewardChoices={155036,155038,155037,155035,155029,155027,155030,155028},ends={{npcID=121239}},startObjects={{objectID=281647,mapID=895,x=0.789,y=0.457}},coords={mapID=895,source="quest_giver",x=0.6892,y=0.516},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={47485},questLines={{id=585,name="The Ashvane Trading Company",orderIndex=5,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=15,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
