[50583] = {id=50583,name="To the Other Side",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="It looks like the coven is using Corlain as a base of operations. There's no way we'll be able to cut through this many of them without the rest of the Inquisitors. They must still be stuck behind the wall. <class>, there are three smaller footmen gates along the walls into Corlain. See if you can get them open so our allies can make their way through.",objectivesText="Open the Eastern, Southern, and Western Gates in Upper Corlain. Progress: What news of the other inquisitors?",rewardGold=257400,rewardXP=2765,rewardItems={1804,1805,1806,1807,184374,184519},starts={{npcID=131638}},ends={{npcID=131638}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50457},questLines={{id=599,name="Upper Corlain",orderIndex=0,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=47,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50584] = {id=50584,name="Ruinous Rituals",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="Take a look in the city square, <class>. <Marshal Reade gestures toward a ritual being performed by some disciples in the distance.> It appears the coven has gone beyond dark constructs, and are now conjuring creatures of nightmare with their rituals. Let us not wait to see what these monsters are capable of. We should put an end to them right here. Fortunately, the disciples seem too focused on their spell to notice us. Maybe you can use that to your advantage.",objectivesText="Kill 4 Blighted Horrors in Upper Corlain. Progress: Have the monsters been abolished?",rewardGold=257400,rewardXP=2765,starts={{npcID=131636}},ends={{npcID=131636}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50457},questLines={{id=599,name="Upper Corlain",orderIndex=2,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=49,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50585] = {id=50585,name="Hexecutioner",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="It would appear that this is where the coven is training their new acolytes. Our efforts may be for naught if they continue to expand their numbers. I cannot leave Lucille's side in this place, but you have already shown yourself a formidable combatant. Cut them down.",objectivesText="Kill 13 witches of the Heartsbane Coven in Upper Corlain.",rewardGold=257400,rewardXP=2765,starts={{npcID=131636}},ends={{npcID=131636}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50457},questLines={{id=599,name="Upper Corlain",orderIndex=1,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=48,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50586] = {id=50586,name="The Fall of Corlain",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50586},description="<This discarded journal looks like it belonged to one of the residents of upper Corlain. Within it details some early signs of the Heartsbane's appearance in Corlain. If you can find more writings like this, you might be able to piece together the events that led to Corlain's current state.>",objectivesText="Examine 6 Corlain Citizen's Journals in Upper Corlain.",rewardGold=257400,rewardXP=2765,rewardItems={160109},ends={{npcID=129642},{npcID=131638}},startObjects={{objectID=281673,mapID=896,x=0.307,y=0.195}},coords={mapID=896,source="quest_giver",x=0.368,y=0.5},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50457}},
[50587] = {id=50587,name="Nagative Feedback",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Disrupt Naga Encampment"},{orderIndex=1,type=0,amount=25,objectID=125393},{orderIndex=2,type=0,amount=25,objectID=125392},{orderIndex=3,type=0,amount=100,objectID=125978},{orderIndex=4,type=0,amount=17,objectID=134372},{orderIndex=5,type=0,amount=7,objectID=125437},{orderIndex=6,type=0,amount=100,objectID=125952},{orderIndex=7,type=0,amount=25,objectID=125366},{orderIndex=8,type=0,amount=25,objectID=125363},{orderIndex=9,type=2,amount=20,objectID=287159}},worldTaskTitle="Nagative Feedback",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50588] = {id=50588,name="Storming the Manor",level=20,requiredLevel=20,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={47961,47968,47978,47979,47981,47982,48108,48109,48110,48111,48113,48165,48170,48171,48198,48283,48518,48519,48520,48521,48522,48523,48538,48622,48941,48942,48943,48944,48945,48946,48963,48986,49259,49295,49443,49803,49804,49807,49926,50003,50149,50151,50173,50253,50446,50453,50457,50583,50584,50585,50588},description="Now is our chance. Waycrest Manor is just up that hill, and hopefully inside we'll find my mother and father. If we also manage to find the \"Mother\" that's leading this horrible coven, then we will make her regret the day she ever set foot in Drustvar . Are you with me, <class>?",objectivesText="Follow Lucille Waycrest toward Waycrest Manor in Upper Corlain.",rewardGold=257400,rewardXP=2765,rewardItems={155093,155094,155095,155112,155113,155114,155115,155116},rewardChoices={155093,155094,155095,155112,155113,155114,155115,155116},starts={{npcID=131638}},ends={{npcID=131638}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50583,50584,50585},questLines={{id=599,name="Upper Corlain",orderIndex=3,flags=0},{id=5373,name="Darkness of Drustvar",orderIndex=50,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5373,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=896},
