[50593] = {id=50593,name="A Bloody Mess",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,rewardGold=257400,rewardXP=4115,ends={{npcID=134639}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49998},questLines={{id=442,name="A House in Peril",orderIndex=25,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=42,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[50594] = {id=50594,name="Beneath the Veil",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="We must board the Abyssal Melody and save the myriad souls in her decks before they too disappear into the Shrine. We will not be able to enter so long as the barrier surrounding it stands. The tidesages are using forbidden magic to summon extensions of their will. It is these grasps that maintain the barrier. Take my beacon and mark each grasp. I will rain vengeance down upon them from here.",rewardGold=257400,rewardXP=4115,rewardChoices={155229,155228,155231},starts={{npcID=134639}},ends={{npcID=134639}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49998},questLines={{id=442,name="A House in Peril",orderIndex=22,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=23,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[50595] = {id=50595,name="No Quarter",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="We arrived just in time. These abominations have already taken control of the docks; we're all that's left to keep them at bay! You need to cull their numbers before we're overwhelmed. We don't exactly have an army here!",rewardGold=257400,rewardXP=4115,starts={{npcID=134623}},ends={{npcID=134623}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49998},questLines={{id=442,name="A House in Peril",orderIndex=23,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=24,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[50596] = {id=50596,name="Exterminate the Vermin",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={50596},series={48872},description="On top of the fury of the overseer, and this \"key\" not being here, we have a pest problem. Sneaky little vulperan thieves keep ransacking our site. We have taken some prisoner. We have them around the upper level of the dig site, working off their misdeeds. However, I believe a more permanent solution would be preferred. Please, oh mighty cobra, give us the honor of getting rid of our prisoners with your most potent venom!",objectivesText="Rescue 3 captive excavators. Progress: They had what?",rewardGold=257400,rewardXP=4115,starts={{npcID=134408}},ends={{npcID=134164}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50536}},
