[50606] = {id=50606,name="Horde War Effort",level=50,requiredLevel=50,faction="horde",categories={"emissary","bounty"},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50606},description="Assist the Horde by completing 4 world quests on Kul Tiras or occupied warfront zones.",objectivesText="Complete 4 world quests on Kul Tiras or occupied warfront zones. Progress: Return to me when you have finished aiding the Horde, <name>.",rewardItems={165871},rewardCurrencies={{id=1553,amount=600},{id=1553,amount=3600},{id=1553,amount=400},{id=1560,amount=200}},starts={{npcID=135447}},ends={{npcID=135447}},mapCandidates={npc={862},zone={8499}},questGiverID=135447,questType="standard",worldSystems={bounties={{id=41,factionID=0,bountySetID=10}}}},
[50608] = {id=50608,name="Forbidden Rites",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="These k'thir have been hiding among us, sowing the seeds of their dark masters with us none the wiser. With the barrier around the Abyssal Melody lowered I can peer within; its bowels toil with my own people giving themselves to the shadow! Take my tidal kris ; its blade is now coated in purified tideblood. Put an end to these fiends and their foul rituals.",rewardGold=257400,rewardXP=4115,starts={{npcID=134639}},ends={{npcID=134639}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50593,50594,50595},questLines={{id=442,name="A House in Peril",orderIndex=26,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=26,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[50609] = {id=50609,name="From the Maw of Madness",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="Sam is still out there somewhere. We can't just leave him to die! If he wasn't in the assembly yard, he must be on that ship. You have to find him!",rewardGold=514800,rewardXP=5145,starts={{npcID=134623}},ends={{npcID=134641}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50593,50594,50595},questLines={{id=442,name="A House in Peril",orderIndex=27,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=27,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[50610] = {id=50610,name="Gathering Storm",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="This depravity goes against every oath we take as tidesages. To protect our people... to guide and sustain them... to make our ships strong. This is nothing but darkness. It must all be destroyed. Board the Abyssal Melody and place these focusing rods at any critical points you find. I will prepare the ritual.",rewardGold=257400,rewardXP=4115,starts={{npcID=134639}},ends={{npcID=134639}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50593,50594,50595},questLines={{id=442,name="A House in Peril",orderIndex=28,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=28,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[50611] = {id=50611,name="Storm's Vengeance",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="I know not what horrors await us ahead, but the Abyssal Melody must never follow its sister into the Shrine of the Storm. We will deny these monsters all that they have wrought here by burning it with the very magic they seek to corrupt. The ritual is ready, but requires a conduit to stabilize. If you are willing, I would have you guide my magic.",rewardGold=128700,rewardXP=2060,rewardItems={252655},rewardChoices={158681},starts={{npcID=134639}},ends={{npcID=134639}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50608,50609,50610},questLines={{id=442,name="A House in Peril",orderIndex=29,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=29,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[50612] = {id=50612,name="A House Divided",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="Not all of House Stormsong have followed my Lord down this dark path. They know not - I knew not - the truth of his depravity. Sagehold looms above us. It is where all tidesages study to wield the sea's power. We will build upon the Storm's Wake and make my shattered home whole once more. We will save all who are willing. The rest will perish.",rewardGold=30900,rewardXP=515,starts={{npcID=134639}},ends={{npcID=135534}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50611},questLines={{id=442,name="A House in Peril",orderIndex=30,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=30,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[50614] = {id=50614,name="Freedom for the Sea",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49831,50614,50616,50621,50635,50644,50645,50649,50653,50672,50679,50698,50705,50706,50773},description="The naga along this coast appear to be trying to push the shoreline up the hill here. We've been able to keep them back at the beach so far, but they've been binding more elementals than we can keep up with. Without a tidesage, we have no way to free the elementals from their bindings, but we cannot allow them to push forward anymore. The spirit of the sea should not be contained by anything. Slay them, and let them return to the ocean.",objectivesText="Slay 6 Bound Seasurges . Progress: For a people that live in the sea, the naga seem to have little respect for it.",rewardGold=257400,rewardXP=4115,rewardItems={156472,156482,158181,158183,158200,158332,159752},starts={{npcID=131002}},ends={{npcID=131002}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={52068,52070},questLines={{id=794,name="Defense of Fort Daelin",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50616] = {id=50616,name="A Bit of a Bind",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49831,50614,50616,50621,50635,50644,50645,50649,50653,50672,50679,50698,50705,50706,50773},description="The naga sorceress leading this excursion seems to be in the process of binding a larger elemental. If she succeeds, we will no doubt lose our foothold here. Strike out at her, perhaps you can catch her off guard and interrupt the ritual. Remove the head from these snakes.",objectivesText="Slay Binder Sa'thress . Progress: Is the seawitch dead?",rewardGold=257400,rewardXP=4115,rewardItems={156472,156482,158181,158183,158200,158332,159752,160345,160371,160374,160377,160380},rewardChoices={160345,160371,160374,160377,160380},starts={{npcID=131002}},ends={{npcID=131002}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49818},questLines={{id=794,name="Defense of Fort Daelin",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50617] = {id=50617,name="Atul'Aman",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={50617,50702,50703,50904},description="Jakra'zet and his troops attacked while we were away. Serrik fought well, but it wasn't enough. The keys are gone, and it's only a matter of time before the barrier is broken. Your friends have already given chase. Jakra'zet must not be allowed to resurrect Mythrax the Unraveler. He must be stopped before it's too late! We don't have much time. Meet me at Atul'Aman! We must catch up with Kaja and Rakera and stop the ritual!",objectivesText="Meet Vorrik at Atul'Aman.",rewardXP=515,starts={{npcID=129588}},ends={{npcID=135625}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50751},questLines={{id=611,name="Atul'Aman",orderIndex=0,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=60,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50619] = {id=50619,name="What Goes Up",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,mapCandidates={npc={},zone={8499}},questType="world",db2Objectives={{orderIndex=0,type=2,amount=8,objectID=293683,text="Traps set"}},worldTaskTitle="What Goes Up",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50621] = {id=50621,name="Caught in the Net",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49831,50614,50616,50621,50635,50644,50645,50649,50653,50672,50679,50698,50705,50706,50773},description="When the naga force first arrived, there were a handful of the local fishermen out on boats. One of our scouts reports that most of them have been captured and are currently being kept in cages around the beach. Free any of them you happen to find and point them back here. We'll get them armed and remind the naga that you don't mess with sailors!",objectivesText="Free 5 villagers.",rewardGold=257400,rewardXP=4115,rewardItems={156472,156482,158181,158183,158200,158332,159752},starts={{npcID=131002}},ends={{npcID=131002}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49818},questLines={{id=794,name="Defense of Fort Daelin",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50622] = {id=50622,name="Deal's Off",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50353,50354,50363,50365,50368,50622,50640,51354},description="There's one more farm left, far to the west. They're real close to the kraul. Deal works the land by herself. If anyone got hit bad, it'd be her. It's just past the worst part of the collapse, so keep an eye out for the quilboar.",objectivesText="Search the Deal Farmstead for any survivors.",rewardGold=25740,rewardXP=515,rewardItems={133510,155824,155877,156577,156578,156648,157849,157850,160558,160561},starts={{npcID=129808},{npcID=132118}},ends={{npcID=134752}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50088,50136},questLines={{id=583,name="Storming the Kraul",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50626] = {id=50626,name="LFGDungeons - BFA - Normal Random - 1st",level=10,requiredLevel=10,faction="none",categories={},flags={},sharable=false,expansion=7,storyline={50626},rewardGold=1029600,rewardXP=2830,mapCandidates={npc={},zone={}},questType="standard"},
[50627] = {id=50627,name="LFGDungeons - BFA - Heroic Random - 1st",level=50,requiredLevel=50,faction="none",categories={},flags={},sharable=false,expansion=7,storyline={50627},rewardGold=1404000,rewardXP=13630,mapCandidates={npc={},zone={}},questType="standard"},
[50632] = {id=50632,name="Battlefield Scavenging",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,storyline={50632},description="The battle rages on, but our inventory suffers. Scavenge the camps for supplies. I'll make use of what you find.",objectivesText="Gather supplies from Newstead, High Perch and the Circle of Elements.",rewardItems={158172,158174,158179,162140,162141,162142,162143,163125,163126},rewardChoices={158174,162143,158179},mapCandidates={npc={},zone={}},questType="group"},
[50633] = {id=50633,name="Pterrible Ingredients",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50633},objectivesText="Pterrordax Salivary Gland collected",rewardItems={158177},mapCandidates={npc={},zone={8499}},questType="world",db2Objectives={{text="Pterrordax Salivary Gland collected",amount=12,type=1,objectID=158177,orderIndex=0}},worldTaskTitle="Pterrible Ingredients",db2PoiMapID=1642,db2PoiUiMapID=862,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50634] = {id=50634,name="Save Our Scrolls!",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={50634},objectivesText="Intact Tortollan Scroll collected",rewardItems={158176},mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{text="Intact Tortollan Scroll collected",amount=12,type=1,objectID=158176,orderIndex=0}},worldTaskTitle="Save Our Scrolls!",db2PoiMapID=1642,db2PoiUiMapID=863,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50635] = {id=50635,name="The Shifting Tides",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49831,50614,50616,50621,50635,50644,50645,50649,50653,50672,50679,50698,50705,50706,50773},description="I'm no tidesage, but even I can tell that whatever you have there is probably not a good sign for the bastion. There's one of those Tortollans, Rikal , who's been helping us figure out a solution to whatever the naga are planning in front of the levee. He'd probably like to see this.",objectivesText="Speak with Rikal at Fort Daelin.",rewardGold=61425,rewardXP=1030,rewardItems={156472,156482,158181,158183,158200,158332,159752},starts={{npcID=131002}},ends={{npcID=131014}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50614,50616,50621},questLines={{id=794,name="Defense of Fort Daelin",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50636] = {id=50636,name="Ravoracious",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50636},objectivesText="Ravasaur Stomach Lining collected",rewardItems={159755},mapCandidates={npc={},zone={8499}},questType="world",db2Objectives={{text="Ravasaur Stomach Lining collected",amount=12,type=1,objectID=159755,orderIndex=0}},worldTaskTitle="Ravoracious",db2PoiMapID=1642,db2PoiUiMapID=862,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50639] = {id=50639,name="Waycrest Manor: The Fallen Mother",level=20,requiredLevel=20,faction="alliance",categories={},flags={"loremaster"},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50583,50584,50585,50588,50639},description="This is all a lot to process... The Marshal... gone? My mother... the leader of the coven? It's just too much... ...but we have come too far to turn back now. It is clear that my mother and father, as I knew them, are gone. It is time we cleansed the taint from this land. We must take the inquisitors and find them in Waycrest Manor. We will end this, once and for all.",objectivesText="Defeat Lady Waycrest in Waycrest Manor. Progress: This must be done.",rewardGold=1029600,rewardXP=5530,rewardCurrencies={{id=1553,amount=600}},starts={{npcID=131638}},ends={{npcID=129642}},mapCandidates={npc={896},zone={8721}},questType="dungeon",sourceQuests={50588},questLines={{id=599,name="Upper Corlain",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50640] = {id=50640,name="A Question of Quillpower",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50353,50354,50363,50365,50368,50622,50640,51354},description="I can't believe you managed to kill that thing. You're quite impressive, you know that? Either way, we should be getting back to Roz with our report. We're stuck in the middle of the kraul, surrounded by angry quilboar. But I have a plan! Some of the boars seem reasonable enough. I gave them a bit of my rations and they've been following me around. I bet we can use them to hitch a ride out of this place. You in?",objectivesText="Ride the Ornery Battleboar out of Briarback Kraul and report to Mayor Roz .",rewardGold=257400,rewardXP=4115,rewardItems={133510,155824,155877,156577,156578,156648,157849,157850,160558,160561},starts={{npcID=133953}},ends={{npcID=134752}},mapCandidates={npc={942},zone={9562}},questType="standard",sourceQuests={50368},questLines={{id=583,name="Storming the Kraul",orderIndex=7,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50641] = {id=50641,name="Break Their Ranks",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="This temple is our last bastion against the Faithless. We need every able fighter to defend its walls. If you're offering to help, we won't turn you away. Head into battle and do what you can to break their ranks!",objectivesText="Kill 10 Faithless attackers within the Temple Grounds. Progress: We must defend the temple at all costs!",rewardGold=257400,rewardXP=4115,starts={{npcID=128696}},ends={{npcID=128696}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47324},questLines={{id=609,name="The Three Keepers",orderIndex=2,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=44,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50642] = {id=50642,name="The Warchief Commands",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=331,mapID=62,storyline={50476,50642,50646,50647,50738,50740,50772,50800,50823,50837,50878,50879,50880,52436,52437,52438,52806,52967,52970,52971,52981,53604,53605,53606,53608,53609,53610,53627},series={50476,50646,50647,50738},description="Silithus. That has been the name of the game... or rather, that is what I wanted the Alliance to believe. Make no mistake, Azerite is just as powerful as it is rumored to be but I have bigger plans in mind. High Overlord Saurfang is leading an army towards Silithus. By now, he should be in the Northern Barrens. I want you to intercept him and notify him that the preparations are complete. Preparations for what, you ask? Why, we are going to capture the World Tree.",objectivesText="Find Saurfang in the Northern Barrens.",rewardGold=200,rewardXP=175,rewardItems={140192,158075,158937,160251,163127,163128},starts={{npcID=134554}},ends={{npcID=134574}},mapCandidates={npc={10,62},zone={331}},questType="standard",sourceQuests={50476},questLines={{id=584,name="The Warchief's Command",orderIndex=1,flags=0}},db2PoiMapID=1,db2PoiUiMapID=10},
[50644] = {id=50644,name="Facing the Invaders",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49831,50614,50616,50621,50635,50644,50645,50649,50653,50672,50679,50698,50705,50706,50773},description="While we try to figure out what to do with those channelers, we'll have to take shots where we can get them. Our men could use some assistance retaking parts of the lower walls. Kill some naga for me, would you?",objectivesText="Slay 15 of the naga forces invading Fort Daelin.",rewardGold=257400,rewardXP=4115,rewardItems={156472,156482,158181,158183,158200,158332,159752},starts={{npcID=131003}},ends={{npcID=131003}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50635},questLines={{id=794,name="Defense of Fort Daelin",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50645] = {id=50645,name="Eeling in a Big One",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49831,50614,50616,50621,50635,50644,50645,50649,50653,50672,50679,50698,50705,50706,50773},description="If you are up to it, I have an idea to give the naga an amusing surprise. < Rikal slowly pulls out a scroll and waves it in your face.> I need some teeth from marine predators to cast the spell though. Luckily, the naga brought some disgusting eels with them. Go gather their fangs, and bring them back to me.",objectivesText="Collect 16 Abyssal Fangs . Progress: I can't wait to see how this goes.",rewardGold=257400,rewardXP=4115,rewardItems={156472,156482,158181,158183,158200,158332,159752},starts={{npcID=131014}},ends={{npcID=131014}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50635},questLines={{id=794,name="Defense of Fort Daelin",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50646] = {id=50646,name="A Quick Diversion",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=331,mapID=10,storyline={50476,50642,50646,50647,50738,50740,50772,50800,50823,50837,50878,50879,50880,52436,52437,52438,52806,52967,52970,52971,52981,53604,53605,53606,53608,53609,53610,53627},series={50476,50642,50647,50738},description="I have halted our march until I received word that we were ready to divert. What comes next will be a coordinated, synchronized attack on key outposts in Ashenvale. If we act quickly, we will destroy the kaldorei's defenses and clear a path all the way to Darkshore. Stormwind will surely send reinforcements to stop us. We have to conquer Teldrassil before they arrive. I will divert the troops. Meet with our operative, Lorash , outside Astranaar for further instruction.",objectivesText="Find Lorash in Astranaar.",rewardGold=200,rewardXP=175,rewardItems={158075,158937,160251,163127,163128},starts={{npcID=134574}},ends={{npcID=134573}},mapCandidates={npc={10,63},zone={331}},questType="standard",sourceQuests={50642},questLines={{id=584,name="The Warchief's Command",orderIndex=2,flags=0}},db2PoiMapID=1,db2PoiUiMapID=63},
[50647] = {id=50647,name="Everybody Has a Price",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=331,mapID=63,storyline={50476,50642,50646,50647,50738,50740,50772,50800,50823,50837,50878,50879,50880,52436,52437,52438,52806,52967,52970,52971,52981,53604,53605,53606,53608,53609,53610,53627},series={50476,50642,50646,50738},description="Hundreds of rogues have already attacked kaldorei outposts in Ashenvale. On my signal, they will begin the next phase of this war: sowing chaos. My colleague died not far from here, <name>, so I could use your help. If we stay out of sight, the town won't even know it's under attack before we have all of its guards down. I have a poison that will kill them quickly and silently. If you signal to me which targets are safe to attack without being noticed, I will put them down. What do you say?",objectivesText="Work with Lorash to disarm Astranaar.",rewardGold=2000,rewardXP=1415,rewardItems={158075,158190,158937,160251,163127,163128},starts={{npcID=134573}},ends={{npcID=134573}},mapCandidates={npc={63},zone={331}},questType="standard",sourceQuests={50646},questLines={{id=584,name="The Warchief's Command",orderIndex=3,flags=0}},db2PoiMapID=1,db2PoiUiMapID=63},
[50648] = {id=50648,name="Bubbles and Trouble",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=5,objectID=127224},{orderIndex=1,type=0,amount=3,objectID=134583,text="Corruption source destroyed"}},worldTaskTitle="Bubbles and Trouble",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50649] = {id=50649,name="Filching from Thieves",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49831,50614,50616,50621,50635,50644,50645,50649,50653,50672,50679,50698,50705,50706,50773},description="The naga oft take what they want with little care for who they are taking it from. Perhaps we should do the same for them. The sorceresses use powerful beacons to assist with their spellcasting. I could use these relics to strengthen my own ritual.",objectivesText="Collect 7 Tidal Beacons . Progress: Make sure you don't drop any of the beacons. I cannot say I know what will happen.",rewardGold=257400,rewardXP=4115,rewardItems={156472,156482,158181,158183,158200,158332,159752},starts={{npcID=131014}},ends={{npcID=131014}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50635},questLines={{id=794,name="Defense of Fort Daelin",orderIndex=6,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50650] = {id=50650,name="Smashing Zalamar",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Zalamar Disrupted"},{orderIndex=1,type=0,amount=34,objectID=127142},{orderIndex=2,type=0,amount=100,objectID=127176},{orderIndex=3,type=2,amount=10,objectID=281835},{orderIndex=4,type=0,amount=34,objectID=128071}},worldTaskTitle="Smashing Zalamar",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50651] = {id=50651,name="Cut Off Potential",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50651},objectivesText="Preserves Beasts darted Zandalari Beastkeeper slain",rewardItems={158185},mapCandidates={npc={},zone={8499}},questType="world",db2Objectives={{text="Preserves Beasts darted",amount=8,type=0,objectID=134315,orderIndex=0},{text="Zandalari Beastkeeper slain",amount=1,type=0,objectID=134585,orderIndex=1}},worldTaskTitle="Cut Off Potential",db2PoiMapID=1642,db2PoiUiMapID=862,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50652] = {id=50652,name="Biting the Hand that Feeds Them",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={50652},objectivesText="Savagemane Hatchling Fed",rewardItems={158184},mapCandidates={npc={},zone={8670}},questType="world",db2Objectives={{text="Savagemane Hatchling Fed",amount=5,type=0,objectID=134619,orderIndex=0}},worldTaskTitle="Biting the Hand that Feeds Them",db2PoiMapID=1642,db2PoiUiMapID=862,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50653] = {id=50653,name="Reclaiming our Defenses",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49831,50614,50616,50621,50635,50644,50645,50649,50653,50672,50679,50698,50705,50706,50773},description="We were holding off the naga up until the latest attack. A few of our forces are still out there. The tidemaidens seem to be slowly torturing them to death. If you could save as many as you can find, we'd be one step closer to gaining the upper ground again.",objectivesText="Save 8 stranded battalion soldiers .",rewardGold=257400,rewardXP=4115,rewardItems={155232,156472,156482,158181,158183,158200,158332,159752,160334,160337,160340,160343},rewardChoices={155232,160334,160337,160340,160343},starts={{npcID=131003}},ends={{npcID=131003}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50635},questLines={{id=794,name="Defense of Fort Daelin",orderIndex=7,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50656] = {id=50656,name="Risky Rescue",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={50656},description="The Faithless incursion is just up ahead. We tried to get ahead of the siege by attacking their camp in the dead of night, but they knew we were coming. Our troops were quickly overwhelmed. We called for a retreat, but only a few of us made it out. The fate of those that didn't is unknown... We don't have the numbers to attempt a rescue ourselves. We can't afford to lose any more fighters. You're their only hope.",objectivesText="Free 4 Temple Defenders.",rewardGold=257400,rewardXP=4115,rewardCurrencies={{id=1553,amount=100}},starts={{npcID=134611}},ends={{npcID=134611}},mapCandidates={npc={864},zone={8501}},questType="standard"},
[50660] = {id=50660,name="Survival Strategy",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={50660},objectivesText="Saurid Feathers collected Diremaw Hide collected Pterrordax Claws collected",rewardItems={158191,158192,158193},mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{text="Saurid Feathers collected",amount=30,type=1,objectID=158191,orderIndex=0},{text="Diremaw Hide collected",amount=5,type=1,objectID=158193,orderIndex=1},{text="Pterrordax Claws collected",amount=3,type=1,objectID=158192,orderIndex=2}},worldTaskTitle="Survival Strategy",db2PoiMapID=1642,db2PoiUiMapID=863,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50665] = {id=50665,name="Cancel the Blood Troll Apocalypse",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=134758,text="Speak with Patch to board the A.F.M.O.D"},{orderIndex=1,type=0,amount=80,objectID=134664,text="Blood Trolls slain"}},worldTaskTitle="Cancel the Blood Troll Apocalypse",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50667] = {id=50667,name="Past Due",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=8,objectID=136316,text="Ancient Texts examined"}},worldTaskTitle="Past Due",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50672] = {id=50672,name="Any Ammo Will Do",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49831,50614,50616,50621,50635,50644,50645,50649,50653,50672,50679,50698,50705,50706,50773},description="I'll have some men move some cannons down to the sea wall in preparation of whatever ritual is going on down in that delta. We could use some extra ammo before we spread ourselves too thin though. Luckily, those naga harpoons work well enough with our mortars. Take down those lances and bring back any harpoons that you find.",objectivesText="Collect 20 Zeth'jir Harpoons on the coast south of Fort Daelin. Progress: We can use the naga's weapons against them!",rewardGold=257400,rewardXP=4115,rewardItems={156472,156482,158181,158183,158200,158332,159752},starts={{npcID=131003}},ends={{npcID=131003}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50644,50653},questLines={{id=794,name="Defense of Fort Daelin",orderIndex=9,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50674] = {id=50674,name="Two-Faced Pirate Scum",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50674,50675,50691,50696,50697,50704,50741,50742,50753,50774,50793,50802,50803,50810,50955,52132},series={50675,50810},description="We've been holding the Irontide off for days, but now they've brought in an ettin for reinforcements. We can't let him attack the town. A few of my best men just went up the hill to try and kill him. You look pretty capable, they could sure use your help?",objectivesText="Eliminate Two Face Tom. Progress: Hurry <name> you've got to kill the ettin.",rewardGold=514800,rewardXP=5145,rewardItems={158226,158635,158636,158724,160481,160668},starts={{npcID=134720}},ends={{npcID=134720}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51554},questLines={{id=740,name="Deadwash Line",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50675] = {id=50675,name="Treasure Hunting",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50674,50675,50691,50696,50697,50704,50741,50742,50753,50774,50793,50802,50803,50810,50955,52132},series={50674,50810},description="The workers are digging day and night out there to find the lost treasure. You'd get an equal share like everyone else, if ya wanna help out. Talk to Nedly about joining up.",objectivesText="Speak to Nedly.",rewardGold=25740,rewardXP=515,rewardItems={158226,158635,158636,158724,160481,160668},starts={{npcID=134720}},ends={{npcID=134702}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50674,50802,50810},questLines={{id=740,name="Deadwash Line",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50676] = {id=50676,name="River Toll",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=12,objectID=134737,text="Bloodhunter Trolls slain"},{orderIndex=1,type=0,amount=8,objectID=134740,text="Bloodhunter War Supplies destroyed"}},worldTaskTitle="River Toll",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50679] = {id=50679,name="Piercing the Shield",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49831,50614,50616,50621,50635,50644,50645,50649,50653,50672,50679,50698,50705,50706,50773},description="I've been talking with Rikal, and the tortollan says that our problem in the delta can probably be solved by turning the naga's magic back on them. A few of the sorceresses on the south coast have a channeling wand that we may be able to use to break the head priestesses' ritual channeling. Find one, and bring it back here.",objectivesText="Find an intact Zeth'jir Channeling Rod . Progress: We cannot allow this fort to fall!",rewardGold=257400,rewardXP=4115,rewardItems={156472,156482,158181,158183,158200,158332,159752,160360,160363,160366,160369,160885},rewardChoices={160885,160360,160363,160366,160369},starts={{npcID=131003}},ends={{npcID=131003}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50644,50653},questLines={{id=794,name="Defense of Fort Daelin",orderIndex=10,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50689] = {id=50689,name="It's the Pits",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={50689},objectivesText="Goblin Prospector rescued",rewardGold=1123600,rewardXP=25,mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{text="Goblin Prospector rescued",amount=4,type=0,objectID=134759,orderIndex=1}},worldTaskTitle="It's the Pits",db2PoiMapID=1642,db2PoiUiMapID=863,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50690] = {id=50690,name="A Flickering of Hope",level=80,requiredLevel=80,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=14838,mapID=2215,storyline={50690},description="This pervasive darkness continues to cast shadows over our fields, hindering our harvests. Check with Keyrra Flamestonge and see if you can help restore some order.",objectivesText="Check in with Keyrra Flamestonge .",rewardGold=30900,rewardXP=1470,rewardItems={206350,251719,251720,251721,251722},starts={{npcID=206528}},ends={{npcID=215527}},mapCandidates={npc={2215},zone={14838}},questType="standard",sourceQuests={76247,79108}},
[50691] = {id=50691,name="Not On Our Payroll",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50674,50675,50691,50696,50697,50704,50741,50742,50753,50774,50793,50802,50803,50810,50955,52132},description="The workers are complaining about elementals coming into the area while they're digging for treasure. Just this morning, I had two people crushed to death! It's slowing down the hunt! You can earn your share by getting rid of those elementals!",objectivesText="Eliminate 10 Restless Stones .",rewardGold=257400,rewardXP=4115,rewardItems={158226,158635,158636,158724,160481,160668},starts={{npcID=134702}},ends={{npcID=134702}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50675},questLines={{id=740,name="Deadwash Line",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50694] = {id=50694,name="A Bloody Mess",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="My order blesses every Kul Tiran ship within the halls of the Shrine of the Storm. Our blessings make our ships the strongest in all of Azeroth; the fleet of legend. The ritual requires a substance known as tideblood . It is a viscous, powerful substance dredged from the depths of the sea and infused into the very hull of each ship. Something has caused the tideblood here to become animate. Studying it may help us better understand our enemy.",rewardGold=309800,rewardXP=4115,starts={{npcID=134639}},ends={{npcID=134639}},mapCandidates={npc={942},zone={9042}},questType="standard",questLines={{id=442,name="A House in Peril",orderIndex=24,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=25,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[50695] = {id=50695,name="It's Never Time for Cannibalism",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=12,objectID=124688},{orderIndex=1,type=0,amount=4,objectID=134761,text="Zandalari Sacrifice rescued"}},worldTaskTitle="It's Never Time for Cannibalism",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50696] = {id=50696,name="Fun With Magnets",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50674,50675,50691,50696,50697,50704,50741,50742,50753,50774,50793,50802,50803,50810,50955,52132},description="My last time in Tol Barad I had to leave in a big hurry, but I grabbed a few gadgets on the way out. This device is one of my favorites, so don't break it! It'll suck the treasure right out of the mud. It may make you tingle some, that's just the radiation. Find lost coins using the metal collector near the signs I've placed.",objectivesText="Collect 60 Lost Coins . Progress: I like gold, let's find some!",rewardGold=257400,rewardXP=4115,rewardItems={158226,158635,158636,158724,160481,160668},rewardCurrencies={{id=1553,amount=75}},starts={{npcID=134710}},ends={{npcID=134710}},mapCandidates={npc={942},zone={9042}},questTurnInID=134710,questType="standard",sourceQuests={50675},questLines={{id=740,name="Deadwash Line",orderIndex=6,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50697] = {id=50697,name="Bomb Beats Rock",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50674,50675,50691,50696,50697,50704,50741,50742,50753,50774,50793,50802,50803,50810,50955,52132},description="I stole an old treasure map off an Irontide pirate. The map marks several caves on it with circles. The caves are blocked by boulders, but now that you're here, we're going to open them up. You get to do all the dangerous stuff, plant explosives, kill things, and cave exploring. I'll supervise.",objectivesText="East and West Caves blown open!",rewardGold=257400,rewardXP=4115,rewardItems={158226,158635,158636,158724,160481,160668},starts={{npcID=134710}},ends={{npcID=134710}},mapCandidates={npc={942},zone={9042}},questTurnInID=134710,questType="standard",sourceQuests={50675},questLines={{id=740,name="Deadwash Line",orderIndex=7,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50698] = {id=50698,name="Problem Solving with Gunpowder",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49831,50614,50616,50621,50635,50644,50645,50649,50653,50672,50679,50698,50705,50706,50773},description="Fort walls only go so far when it comes to defense. We've got cannons in position to fire if the naga get too close, but we need some fortifications further out. There should be a few good areas to set up some traps further down the beach. Those naga will never know what hit them!",objectivesText="Set 5 Explosive Traps.",rewardGold=257400,rewardXP=4115,rewardItems={156472,156482,158181,158183,158200,158332,159752},starts={{npcID=131003}},ends={{npcID=131003}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50644,50653},questLines={{id=794,name="Defense of Fort Daelin",orderIndex=11,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50699] = {id=50699,name="Worker's Rights",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={50699},series={49465},description="Hey, you! You lookin' for work? I ain't got a job for ya, but I can tell ya to stay away from Algerson Lumber! Algerson'll promise ya some solid labor work and decent pay, but it's a lie I tell ya! The conditions are terrible, we're gettin' attacked, and Algerson ain't even battin' an eye! He don't care 'bout us little people. I'd stay away if I were you!",objectivesText="Talk to Maynard Algerson at Algerson Lumber Yard.",rewardGold=25740,rewardXP=175,starts={{npcID=134776}},ends={{npcID=129613}},mapCandidates={npc={895},zone={8567}},questType="standard",nextQuests={48557,49451,49452,49453,49465}},
[50700] = {id=50700,name="Drust in Time",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={50700},series={49225,51151},description="A few days ago, a band of Alliance researchers that called themselves the \"Explorers' League\" took a contingent of Kul Tiran soldiers to the old Drust ruins down the road. We haven't really heard from them since, and I'm growing a bit concerned. I can't leave my post, so can you check up on the team?",objectivesText="Find the Explorers' League members at the Thovas Base-Camp.",rewardGold=25740,rewardXP=175,starts={{npcID=139089}},ends={{npcID=128381}},mapCandidates={npc={895},zone={8567}},questType="standard",nextQuests={49225,49229,49234}},
[50702] = {id=50702,name="Defeat Jakra'zet",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={50617,50702,50703,50904},description="Jakra'zet is summoning Mythrax the Unraveler! We cannot allow the ritual to continue. Jakra'zet must be stopped before it's too late! Lead the way, <name>. We'll be right behind you. Let's go!",objectivesText="Defeat Jakra'zet.",rewardGold=514800,rewardXP=6175,rewardItems={155396,155397,155398,155399,161158,161159,161160,161161},rewardChoices={155396,155397,155398,155399,161158,161159,161160,161161},starts={{npcID=134803}},ends={{npcID=135133}},mapCandidates={npc={864},zone={8501}},questGiverID=134803,questType="standard",sourceQuests={50904},questLines={{id=611,name="Atul'Aman",orderIndex=2,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=62,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50703] = {id=50703,name="Informing the Horde",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={50617,50702,50703,50904},description="General Jakra'zet has been defeated, but his plan to summon Mythrax succeeded despite our best efforts. Were it not for the mercy of Sethraliss, I doubt we would have made it out of Atul'Aman alive. We must inform our allies of what has transpired in Vol'dun . I'll speak with princess Talanji myself. You should go and speak with the Horde. We need all the help we can get now. I'm sure our paths will cross again, <name>. It was an honor fighting with you.",objectivesText="Speak with Baine Bloodhoof .",rewardGold=25740,rewardXP=515,starts={{npcID=135133}},ends={{npcID=135133}},mapCandidates={npc={864},zone={8501}},questTurnInID=135133,questType="standard",sourceQuests={50702},questLines={{id=611,name="Atul'Aman",orderIndex=3,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=63,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=862},
[50704] = {id=50704,name="Anchors Aweigh Too Much",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50674,50675,50691,50696,50697,50704,50741,50742,50753,50774,50793,50802,50803,50810,50955,52132},description="I got a little deal on the side, selling used ship parts to Addington Shipyards. While you're out looking for the treasure, see what sort of useful parts you can salvage from the mud: anchors, cannons, whatever! We'll sell them to Addington and cut you in for a share of the profits.",objectivesText="Find 12 Old Ship Parts . Progress: See what you can find out in the mud.",rewardGold=257400,rewardXP=4115,rewardItems={158226,158635,158636,158682,158684,158724,160332,160481,160668},rewardChoices={160332,158684,158682},starts={{npcID=134702}},ends={{npcID=134702}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50675},questLines={{id=740,name="Deadwash Line",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50705] = {id=50705,name="A Snake with Three Heads",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49831,50614,50616,50621,50635,50644,50645,50649,50653,50672,50679,50698,50705,50706,50773},description="Now that all of the preparation has been done, it's time to tackle the main threat. You can use the channeling rod you just found in conjunction with this scroll I got from Rikal to break the shields around the naga leaders in the delta. Hurry! Stop them before they finish their summoning!",objectivesText="Slay the three naga channelers.",rewardGold=257400,rewardXP=4115,rewardItems={156472,156482,158181,158183,158200,158332,159752,160429},starts={{npcID=131003}},ends={{npcID=131000}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50672,50679,50698},questLines={{id=794,name="Defense of Fort Daelin",orderIndex=12,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50706] = {id=50706,name="Clearing the Delta",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49831,50614,50616,50621,50635,50644,50645,50649,50653,50672,50679,50698,50705,50706,50773},description="The greatest of the Zeth'jir offensive sits within the delta as we speak, waiting for the summoning ritual to be finished. If we can clear out a number of them, we'll finally have the upper hand. Get down there and cause as much chaos as you can!",objectivesText="Kill 15 naga forces in the Eventide Delta. Progress: This fort will always stand in defense of Kul Tiras!",rewardGold=257400,rewardXP=4115,rewardItems={156472,156482,158181,158183,158200,158332,159752},starts={{npcID=131003}},ends={{npcID=131000}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50672,50679,50698},questLines={{id=794,name="Defense of Fort Daelin",orderIndex=13,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50717] = {id=50717,name="Don't Stalk Me, Troll",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={50717},objectivesText="Talanji's mojo potion used Blood Troll invaders slain",rewardItems={158324,158924},mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{text="Talanji's mojo potion used",amount=1,type=0,objectID=134879,orderIndex=0},{text="Blood Troll invaders slain",amount=12,type=0,objectID=134868,orderIndex=1}},worldTaskTitle="Don't Stalk Me, Troll",db2PoiMapID=1642,db2PoiUiMapID=863,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50718] = {id=50718,name="Agent of Death",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Assault on The Necropolis repelled"},{orderIndex=1,type=0,amount=25,objectID=134816,text="Corpse Rituals prevented"},{orderIndex=2,type=0,amount=34,objectID=134812},{orderIndex=3,type=0,amount=50,objectID=134841},{orderIndex=4,type=0,amount=20,objectID=135280},{orderIndex=5,type=0,amount=25,objectID=134856},{orderIndex=6,type=0,amount=10,objectID=134852},{orderIndex=7,type=0,amount=10,objectID=124460}},worldTaskTitle="Agent of Death",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50733] = {id=50733,name="A New Dawn",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=8568,mapID=1161,description="House Stormsong may be lost, but this valley still holds so much hope. Sam knew that from the beginning. We have to continue to help the Storm's Wake in any way we can. There are still remnants of the fallen house everywhere, and whoever turned them to this darkness is out there as well. Cyrus and the others will want to hear about everything that happened. We should tell them together.",rewardGold=30900,rewardXP=515,starts={{npcID=137692}},ends={{npcID=121235}},mapCandidates={npc={942,1161},zone={8568}},questType="standard",sourceQuests={50824},questLines={{id=5371,name="Secrets of Stormsong Valley",orderIndex=41,flags=0},{id=442,name="A House in Peril",orderIndex=42,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[50735] = {id=50735,name="Burial Detail",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={50735},objectivesText="Cracked Vessels purified Spirits helped Craven Spirits slain",rewardItems={152813},mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{text="Cracked Vessels purified",amount=6,type=0,objectID=134995,orderIndex=0},{text="Spirits helped",amount=99,type=0,objectID=135028,orderIndex=1},{text="Craven Spirits slain",amount=8,type=0,objectID=135032,orderIndex=2}},worldTaskTitle="Burial Detail",db2PoiMapID=1642,db2PoiUiMapID=863,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50737] = {id=50737,name="Silence the Speakers",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=8499,mapID=862,mapCandidates={npc={},zone={8499}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=12,objectID=134989,text="Speakers slain"}},worldTaskTitle="Silence the Speakers",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50738] = {id=50738,name="A Timely Arrival",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=331,mapID=63,storyline={50476,50642,50646,50647,50738,50740,50772,50800,50823,50837,50878,50879,50880,52436,52437,52438,52806,52967,52970,52971,52981,53604,53605,53606,53608,53609,53610,53627},series={50476,50642,50646,50647},description="My end of the bargain is done, <race>. I am going to check on the other outposts to make sure none of my brothers and sisters are in trouble. Meet with the Warchief and inform her that Astranaar has been secured. If everything has gone according to plan, she should be well on her way. Oh, and try not to hog all the glory, yeah? < Lorash smirks at you>.",objectivesText="Greet Warchief Sylvanas Windrunner in Astranaar.",rewardGold=200,rewardXP=175,rewardItems={52613,52637,131279,158075,158937,160251,163127,163128},starts={{npcID=134573}},ends={{npcID=135003}},mapCandidates={npc={62,63},zone={331}},questType="standard",sourceQuests={50647},questLines={{id=584,name="The Warchief's Command",orderIndex=4,flags=0}},db2PoiMapID=1,db2PoiUiMapID=63},
[50739] = {id=50739,name="Missing Business",level=30,requiredLevel=30,faction="horde",categories={},flags={"loremaster"},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={50739},description="Poor little Coda has been in quite the tizzy since his friends vanished. I found him here, out cold, after a sting from one of those awful wasps. Just a tiny bit of our sandstinger remedy got Coda right up, though! Take some with you, and keep an eye out for other little ones out there.",objectivesText="Rescue 7 Sable Polecats . Progress: Did you find them all?",rewardXP=4115,rewardItems={158464,159729},starts={{npcID=135012}},ends={{npcID=135012}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51364}},
[50740] = {id=50740,name="Zoram'gar Outpost",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=331,mapID=62,storyline={50476,50642,50646,50647,50738,50740,50772,50800,50823,50837,50878,50879,50880,52436,52437,52438,52806,52967,52970,52971,52981,53604,53605,53606,53608,53609,53610,53627},series={50772,50800},description="Saurfang shall establish our troops here, now that Astranaar is ours. I shall continue my hunt for the only creature that can stop our march to victory: Malfurion Stormrage. Our next order of business will be to establish a foothold at the base of Darkshore. Commander Grimfang of the Zoram'gar Outpost should be able to accommodate an incoming army. Inform him of our arrival and ensure the necessary preparations are made.",objectivesText="Make the necessary preparations at the Zoram'gar Outpost.",rewardGold=1000,rewardXP=710,rewardItems={158075,158937,160251,163127,163128},starts={{npcID=135003}},ends={{npcID=134574}},mapCandidates={npc={10,62},zone={331}},questType="standard",sourceQuests={50738},questLines={{id=584,name="The Warchief's Command",orderIndex=5,flags=0}},db2PoiMapID=1,db2PoiUiMapID=63},
[50741] = {id=50741,name="Don't Turtle",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50674,50675,50691,50696,50697,50704,50741,50742,50753,50774,50793,50802,50803,50810,50955,52132},description="There's a Tortollan who's trying to get our treasure! He's over on the west side of town. He's nosey and he may have found something! Talk to Moxie. Come up with a plan to get rid of him.",objectivesText="Speak with Moxie. Progress: You deal with that Tortollan yet?",rewardGold=128700,rewardXP=2060,rewardItems={158226,158635,158636,158724,160481,160668},starts={{npcID=134702}},ends={{npcID=135067}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50691,50696,50697,50704},questLines={{id=740,name="Deadwash Line",orderIndex=8,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50742] = {id=50742,name="All Laid Out For Us",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50674,50675,50691,50696,50697,50704,50741,50742,50753,50774,50793,50802,50803,50810,50955,52132},description="<This is all the treasure Calico McGee's found so far. Packed up and ready to move out. More like all laid out for you to take! You'll need a few extra hands to carry this much loot. There should be some Treasure Hunters from Deadwash around. Ask Big Find Balor , Toothless Eddard , and Chopper Darry to help.>",objectivesText="Get three treasure hunters to help you.",rewardGold=514800,rewardXP=5145,rewardItems={158226,158635,158636,158724,160481,160668},rewardCurrencies={{id=1553,amount=75}},ends={{npcID=134720}},startObjects={{objectID=290993,mapID=942,x=0.358,y=0.561}},coords={mapID=942,source="quest_giver",x=0.43,y=0.565},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50793},questLines={{id=740,name="Deadwash Line",orderIndex=15,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50743] = {id=50743,name="The Immediate Problem",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50743},description="I sent one of my lieutenants, a woman by the name of Bauer, to the fishermen's hamlet just down the road. We received a few reports of naga activity spreading down the coast in that direction. We need those forces back as soon as possible. I would ask that you join her in assisting the villagers of the hamlet.",objectivesText="Speak with Lieutenant Bauer.",rewardGold=25740,rewardXP=515,mapCandidates={npc={},zone={9042}},questType="standard"},
[50744] = {id=50744,name="Refresh Their Memory",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8670,mapID=1165,mapCandidates={npc={},zone={8670}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=4,objectID=120946,text="Amani Disciples defeated"}},worldTaskTitle="Refresh Their Memory",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50745] = {id=50745,name="Infiltrating the Empire",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},series={49662,49664},description="The heart of the Faithless empire rests just beyond this ridge. We will need to move swiftly and quietly to avoid detection once inside. Thankfully, my former dwelling is nearby. I know a passage that should allow us to advance into the fortress with minimal resistance. When you are ready, speak with me and I will show you the way. < Vorrik looks around suspiciously.> I expected the Faithless to patrol this area... Keep your eyes open for anything suspicious along the path.",objectivesText="Accompany Vorrik to his sanctum.",rewardGold=128700,rewardXP=2060,starts={{npcID=137970}},ends={{npcID=135172}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={49662},questLines={{id=610,name="Storming the Spire",orderIndex=1,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=48,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50746] = {id=50746,name="Crater Conquered",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="I can take it from here, $p. I'll rally these vulpera and march through the trenches creating chaos. Korthek and his armies will be forced to deal with us! If you and Vorrik are going to make a move, you should do it now.",objectivesText="Return to Vorrik .",rewardGold=25740,rewardXP=515,starts={{npcID=135090}},ends={{npcID=135172}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={49665,49666},questLines={{id=610,name="Storming the Spire",orderIndex=5,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=52,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50747] = {id=50747,name="No Good Amani",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=8670,mapID=1165,mapCandidates={npc={},zone={8670}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=4,objectID=120946,text="Amani Disciples defeated"}},worldTaskTitle="No Good Amani",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50748] = {id=50748,name="Don't Drop It... Yet",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="The Faithless are training pterrordaxes as mounts so that they can rain down death from the skies. Their skycallers have developed a means of storing volatile lightning magic into fragile crystals. Lightning bombs, in the simplest sense. The magic behind it is quite brilliant, really. The bombs will be exceptionally useful if we can secure the aid of Rakjan, the powerful and fierce pterrordax at the top of this mountain. Acquire as many as you can carry, while I will do my best to recruit Rakjan.",objectivesText="Collect 6 Volatile Lightning Bombs from Faithless. Progress: There are no end to the Faithless, so grab as many as you can carry.",rewardGold=257400,rewardXP=4115,rewardItems={154896},starts={{npcID=135172}},ends={{npcID=135110}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50746},questLines={{id=610,name="Storming the Spire",orderIndex=7,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=54,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50749] = {id=50749,name="Free Ride",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48329,49002,49437,49667,49668,49669,50749,50757},description="One thing I've learned during my time in Vol'dun is to not stay in one place for too long. And doubly so when the Faithless are involved. We've done our damage here. Let's move before we get caught. I procured a mount to take us back to Meerah and the others in Vorrik's Sanctum quickly. Don't worry, this Faithless won't be needing it anymore.",objectivesText="Steal the Battle Krolusk mount and return to Meerah.",rewardGold=128700,rewardXP=2060,starts={{npcID=135099}},ends={{npcID=137982}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={49669,50757},questLines={{id=5428,name="Sethrak Fortress",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50750] = {id=50750,name="Infuriating the Emperor",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="It seems I underestimated Korthek's cowardice. I expected him to be behind the barrier, ready to ambush us. Yet, still he hides. That allows us a few moments to prepare. We musn't waste them. While I siphon power off of these immense crystals, you must thin the numbers of the Faithless here. I will grant you a powerful boon to speed you in your task. When Korthek arrives, he will require our full attention.",objectivesText="Use Vorrik 's Bulwark to defeat 75 Faithless within the Sacred Sands.",rewardGold=283700,rewardXP=4115,starts={{npcID=135111}},ends={{npcID=135111}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={49003},questLines={{id=610,name="Storming the Spire",orderIndex=9,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=56,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50751] = {id=50751,name="Sanctuary Under Siege",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="I fear that Emperor Korthek was not lying when he boasted of his foolish plan. If General Jakra'zet attacked the Sanctuary of the Devoted while we were away, there is a good chance that he now has everything needed to resurrect Mythrax. We must hurry to the Sanctuary and stop Jakra'zet. Mythrax must not be reborn!",objectivesText="Meet Vorrik at the Sanctuary of the Devoted.",rewardGold=128700,rewardXP=2060,starts={{npcID=135390},{npcID=138519}},ends={{npcID=129588}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50550},questLines={{id=610,name="Storming the Spire",orderIndex=12,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=59,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50752] = {id=50752,name="Relics of Sethraliss",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="It may surprise you to learn that the Faithless hoard ancient relics of Sethraliss. I assure you that they do not do so out of reverence or respect, as is proper. Korthek's brood is driven only by greed and an insatiable lust for power. They rip whatever magic they can from the relics, even if it means destroying them in the process. Rescue the ancient artifacts of Sethraliss in the Sacred Sands nearby. We will honor and preserve them in the Sanctuary of the Devoted.",objectivesText="Recover the Skull of the First Skycaller , Rebirth Creed , Sethraliss Sight Stone , and Blood of the Fallen Loa . Progress: Do you have the artifacts?",rewardGold=283700,rewardXP=4115,rewardItems={158722,160526,160527,160528},starts={{npcID=135111}},ends={{npcID=135111}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={49003},questLines={{id=610,name="Storming the Spire",orderIndex=10,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=57,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50753] = {id=50753,name="Earl-E Bot Gets the Worm",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50674,50675,50691,50696,50697,50704,50741,50742,50753,50774,50793,50802,50803,50810,50955,52132},description="It could take you days to get that much meat, and I don't want to wait around. So, we'll use a Bot as bait! You send EARL-E towards any disturbances you see in the mud. He'll make enough noise to scare any worms out. Then kill the worms, get the meat. I'll watch from here.",objectivesText="Get Mud Worm Meat for Maokka . Progress: Do you have the meat yet?",rewardGold=257400,rewardXP=4115,rewardItems={158226,158635,158636,158724,160481,160514,160668},starts={{npcID=135067}},ends={{npcID=135033}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50741},questLines={{id=740,name="Deadwash Line",orderIndex=9,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50754] = {id=50754,name="To Have Loved and Lost",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={50754,50758,50759,50760,50761,50762,50763},description="I have a favor to ask you of a... personal nature. Whitegrove Chapel lies to the north, just past the town of Corlain. Someone... important to me rests in the graveyard on its grounds. I've been unable to visit his grave for some time, and I would like to pay my respects. If you come upon Whitegrove Chapel, could you lay these flowers next to his headstone? Just look for the most recent grave there...",objectivesText="Lay the Crimson Bouquet next to the Simple Gravestone in Whitegrove Chapel.",rewardGold=25740,rewardXP=345,rewardItems={163603},starts={{npcID=131638}},ends={{npcID=135200}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50253},questLines={{id=5444,name="Drustvar Chapel",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50755] = {id=50755,name="A Meal for Birds",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={50755},description="I don't know why I agreed to this. We weren't supposed to be scavenging. Kiro gave me specific instructions to head to the basin and feed the buzzards. I can't go back to camp until they eat, but I'm not heading into that basin while the sethrak are still swarming. Have you ever fed a buzzard? It's easy, I promise. You kill it, they eat it. That simple.",objectivesText="Kill wildlife within The Brine Basin so Mekaru 's buzzards can eat. Progress: They still look hungry to me.",rewardGold=257400,rewardXP=4115,rewardCurrencies={{id=1553,amount=100}},starts={{npcID=137629}},ends={{npcID=137629}},mapCandidates={npc={864},zone={8501}},questType="standard"},
[50756] = {id=50756,name="Subterranean Evacuation",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50756},objectivesText="Kul Tiran Captive freed",rewardItems={158652},mapCandidates={npc={},zone={8499}},questType="world",db2Objectives={{text="Kul Tiran Captive freed",amount=10,type=0,objectID=135122,orderIndex=0}},worldTaskTitle="Subterranean Evacuation",db2PoiMapID=1642,db2PoiUiMapID=862,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50757] = {id=50757,name="Untame Slaughter",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48329,49002,49437,49667,49668,49669,50749,50757},description="The Faithless rely on their krolusks for everything. They are mounts, battle companions, beasts of burden, and often even food to fuel the sethrak empire. If we can disrupt their krolusks, we'll disrupt their whole empire. One broken wheel stops the caravan, eh? Take out as many of their krolusk tamers as you can. That'll have a longer impact than just killing the krolusks.",objectivesText="Kill 8 Faithless within the Feeding Pits.",rewardGold=257400,rewardXP=4115,starts={{npcID=135099}},ends={{npcID=135099}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={49668},questLines={{id=5428,name="Sethrak Fortress",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50758] = {id=50758,name="Painful Memories",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={50754,50758,50759,50760,50761,50762,50763},description="A terrible thing happened in this place, and it has doomed me to an eternity of walking these grounds. All I remember is that Lucille and I were to be wed, but instead I met my end. If you have an ounce of sympathy in your heart, then I beg you to help me. Find out what happened that night, so I might leave here. I know my strongest memories are tied to the ring I bore for Lucy that day. Find it among my bones, and maybe it will lead you to the answer.",objectivesText="Search the Forgotten Bones for Treadward's Ring in Whitegrove Chapel.",rewardGold=257400,rewardXP=2765,rewardItems={158654,163603},starts={{npcID=135200}},ends={{npcID=134953}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50754},questLines={{id=5444,name="Drustvar Chapel",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50759] = {id=50759,name="Running Late",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={50754,50758,50759,50760,50761,50762,50763},description="I beg your pardon, but I am a little concerned at Lord Waycrest's tardiness. I'd hate to be a bother, but would you mind checking on him? The ceremony awaits his presence. You can find him in the bride's room, at the top of the tower.",objectivesText="Speak with Lord Arthur Waycrest in Whitegrove Chapel. Progress: It must be around here somewhere...",rewardGold=257400,rewardXP=2765,rewardItems={116052,151623,158719,163603},starts={{npcID=134953}},ends={{npcID=132994}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50758},questLines={{id=5444,name="Drustvar Chapel",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50760] = {id=50760,name="From This Day Forward",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={50754,50758,50759,50760,50761,50762,50763},description="Lord Waycrest is on his way? Excellent! You have my thanks, <sir/madam>. Please, take a seat.",objectivesText="Take a seat and observe the wedding ceremony in Whitegrove Chapel.",rewardGold=128700,rewardXP=1385,rewardItems={163603},starts={{npcID=134953}},ends={{npcID=132994}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50759},questLines={{id=5444,name="Drustvar Chapel",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50761] = {id=50761,name="Blood in the Chapel",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={50754,50758,50759,50760,50761,50762,50763},description="<Sir/Madam>, you have helped me before and I beseech you to do so again. My guards are clearly outnumbered by these brigands. I must stay here to protect Lucille, so I will need you to assist in protecting the guests. Are you able?",objectivesText="Defeat 10 Red Hand Assassins in Whitegrove Chapel. Progress: We must rout these knaves!",rewardGold=257400,rewardXP=2765,rewardItems={163603},starts={{npcID=132994}},ends={{npcID=132994}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50760},questLines={{id=5444,name="Drustvar Chapel",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50762] = {id=50762,name="The Lady's Fate",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={50754,50758,50759,50760,50761,50762,50763},description="Meredith never joined the ceremony. She might be in trouble! Lucy is in shock, and I cannot leave her here. You must go in my stead to the tower, and ensure the safety of your Lady. Do this for me, and you will be rewarded.",objectivesText="Find Lady Meredith Waycrest in Whitegrove Chapel. Progress: What have you found?",rewardGold=514800,rewardXP=3455,rewardItems={158914,163603},rewardCurrencies={{id=1553,amount=75}},starts={{npcID=132994}},ends={{npcID=135200}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50761},questLines={{id=5444,name="Drustvar Chapel",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50763] = {id=50763,name="One Last Request",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={50754,50758,50759,50760,50761,50762,50763},description="I can feel my bonds to this place slipping, and I have you to thank. I would like to ask one more favor of you though. Please bring the ring you found to Lucille. It was meant for her to hold, not my dusty bones. And <class>, do not tell her what has transpired here. She has enough tragedy weighing down her heart. I do not wish to add to it.",objectivesText="Bring Treadward's Ring to Lucille Waycrest at Watchman's Rise. Progress: What... what's this?",rewardGold=25740,rewardItems={133997,155564,158585,158587,158628,158630,158654,163603},rewardChoices={155564,158585,158587,158628,158630},rewardCurrencies={{id=1553,amount=600}},starts={{npcID=135200}},ends={{npcID=129642},{npcID=131638}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50762},questLines={{id=5444,name="Drustvar Chapel",orderIndex=6,flags=0}},packageItems={158584,158586,158627,158629},db2PoiMapID=1643,db2PoiUiMapID=896},
[50765] = {id=50765,name="Herding Children",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8670,mapID=1165,mapCandidates={npc={},zone={8670}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=3,objectID=135152,text="Orphans Chased"}},worldTaskTitle="Herding Children",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50767] = {id=50767,name="The Scrimshaw Gang",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={50767},rewardItems={141605,158677},mapCandidates={npc={},zone={8568}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=1,objectID=158677},{orderIndex=1,type=0,amount=1,objectID=138603}},worldTaskTitle="The Scrimshaw Gang",db2PoiMapID=1643,db2PoiUiMapID=1161,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50769] = {id=50769,name="The Stormwind Extraction",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=9598,mapID=1165,description="My lady is shrewd indeed. If we are to infiltrate Stormwind City, we will need the very best the Horde has to offer, and yet a team so small as to be able to infiltrate the heart of Alliance territory unseen. Yes, I see. The path ahead is clear. Speak to me when you are ready to undertake the Warchief's mission, .",rewardGold=772200,rewardXP=2125,rewardItems={160251},starts={{npcID=121210},{npcID=135205}},ends={{npcID=121210}},mapCandidates={npc={85,862},zone={9598}},questType="standard",sourceQuests={51443},questLines={{id=612,name="The Stormwind Extraction",orderIndex=1,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=1,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=612,questLineOrder=2,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},
[50770] = {id=50770,name="Effective Antivenom",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47716,48313,48314,48315,48896,50539,50561,50770},description="The salve is ready. I work fast. Hopefully faster than the scorpid poison. Take this antivenom to your friend and see that he swallows every last drop. You should know within moments if it's been effective.",objectivesText="Administer the Antivenom to Serrik .",rewardGold=128700,rewardXP=2060,rewardItems={158678},starts={{npcID=135154}},ends={{npcID=134533}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48313,48314},questLines={{id=608,name="A City of Secrets",orderIndex=4,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=38,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50771] = {id=50771,name="Calldown: Cleaner",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={50771,50775,50812,51991,52129},description="With these dust blowin' siro-ma-whosits all over this beach front, it's a pain to get our cleaners out onto the nodes. Some of the crew wanted to check somewhere else, but no way we're leaving without those rocks for Gallywix. Between you and me, <class>, we're gonna be gettin' some serious hazard pay for this gig.",objectivesText="Identify and mark 5 Azerite deposits for the extraction team. Progress: All the resources been harvested?",rewardGold=257400,rewardXP=4115,rewardItems={158725},starts={{npcID=135179}},ends={{npcID=135179}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50834},questLines={{id=5421,name="For Profit",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50772] = {id=50772,name="On The Prowl",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=331,mapID=10,storyline={50476,50642,50646,50647,50738,50740,50772,50800,50823,50837,50878,50879,50880,52436,52437,52438,52806,52967,52970,52971,52981,53604,53605,53606,53608,53609,53610,53627},series={50740,50800},description="Do you see all of the wisps about? I have seen this once before, when the demon Archimonde was felled by the sting of hundreds - no - thousands of wisps. This can mean only one thing. Malfurion is beckoning the aid of his ancestors. The Warchief has already taken a scouting party ahead to Darkshore to intercept him. Please, <name>. Find the Warchief and see if she has yet caught her prey. We have secured all of Ashenvale, but we must keep the pressure on.",objectivesText="Find Warchief Sylvanas Windrunner in Darkshore. Progress: You may approach, <name>.",rewardGold=200,rewardXP=175,rewardItems={158075,158937,160251,163127,163128},starts={{npcID=134574}},ends={{npcID=134554}},mapCandidates={npc={10,62},zone={331}},questType="standard",sourceQuests={50740},questLines={{id=584,name="The Warchief's Command",orderIndex=6,flags=0}},db2PoiMapID=1,db2PoiUiMapID=63},
[50773] = {id=50773,name="You're a Shark",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={49831,50614,50616,50621,50635,50644,50645,50649,50653,50672,50679,50698,50705,50706,50773},description="Have you ever been bitten by a shark? I have, numerous times. It stings. Murlocs don't usually survive shark attacks. The ritual I had in mind is ready to cast. Let me know when you're prepared.",objectivesText="Kill 20 murlocs. Progress: I can't wait to see how this goes.",rewardGold=257400,rewardXP=4115,rewardItems={52906,52952,156472,156482,158181,158183,158200,158332,158680,159752},rewardChoices={158680},starts={{npcID=131014}},ends={{npcID=131014}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50645,50649},questLines={{id=794,name="Defense of Fort Daelin",orderIndex=8,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50774] = {id=50774,name="No Bot Left Behind",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50674,50675,50691,50696,50697,50704,50741,50742,50753,50774,50793,50802,50803,50810,50955,52132},description="You left Earl-E behind, and a giant worm ate him! He's got sentimental, uh... monetary value. We don't leave any bots behind! Kill that worm and get Earl-E back.",objectivesText="Help Earl-E . Progress: What? Earl-E isn't going to help himself!",rewardGold=257400,rewardXP=4115,rewardItems={158226,158635,158636,158724,160481,160668},starts={{npcID=135067}},ends={{npcID=135067}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50753},questLines={{id=740,name="Deadwash Line",orderIndex=10,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50775] = {id=50775,name="Get Us Some Beach",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={50771,50775,50812,51991,52129},description="These guys are running out of \"ammo\" faster than we can replace it! I tells 'em, we're on a beach, you're in a sandblaster, suck it up! They says it's against the cleaner driver rules for their local chapter. I'm not buyin' it. Grab us some more sand. Them sand monsters have gotta be full of the stuff! We'll make it worth your time.",objectivesText="Collect 20 piles of sand. Progress: Ya get us the dirt yet?",rewardGold=257400,rewardXP=4115,rewardItems={158707},starts={{npcID=135179}},ends={{npcID=135179}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50834},questLines={{id=5421,name="For Profit",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50776] = {id=50776,name="False Prophets",expansion=7,mapID=895,questType="world",worldTaskTitle="False Prophets",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50777] = {id=50777,name="The Storm Awakens",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="I must watch over Samuel for now. I fear for the darkness assaulting his mind. The fallen men and women around us were defectors from the house. There will be more like them within Sagehold. Find them, and tell them 'the storm awakens'. Knowledge of our cause has spread; we need to bring all we can to our side.",rewardGold=257400,rewardXP=4115,starts={{npcID=135534}},ends={{npcID=136498}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50612},questLines={{id=442,name="A House in Peril",orderIndex=31,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=31,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[50778] = {id=50778,name="Twisted Intentions",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="Sails... in the fog... A light below... in the darkness. Water rising... given form... the pain... AHHHH, THE PAIN! Make it stop. Make it stop. Make the pain stop!",rewardGold=514800,rewardXP=5145,starts={{npcID=136053}},ends={{npcID=136498}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50612},questLines={{id=442,name="A House in Peril",orderIndex=32,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=32,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[50779] = {id=50779,name="A Clean Slate",expansion=7,mapID=942,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Purge the corruption"},{orderIndex=5,type=0,amount=20,objectID=135729,text="Lord Stormsong statue toppled"}},worldTaskTitle="A Clean Slate"},
[50780] = {id=50780,name="Oathbound",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="I took oaths, damn it. We all did. When Lord Stormsong sent the first orders... well, you saw what happened. What matters is that our oaths are to our people, not Lord \"Sells His Soul\". You won't find him here - he's deep in the Shrine by now, and no outsider will make it across the channel alive... Not without a Tideguard to open the way. The Rod of Tides is the key to the front door, and it's kept here. Retrieve it and I can get you to him.",rewardGold=283700,rewardXP=4115,starts={{npcID=135517}},ends={{npcID=136497}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50612},questLines={{id=442,name="A House in Peril",orderIndex=33,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=33,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[50781] = {id=50781,name="A Bridge Too Far",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="The bridge that once crossed this span is the only land route to the Shrine. It appears Lord Stormsong has sealed it to buy himself more time. We have been attempting to reopen the way to no avail. However, the Rod of Tides you recovered may prove our solace. Veteran tideguards use it as a key of sorts to maintain the Path of Storms across these dangerous waters. We will begin the ritual once more... if you will wield the rod.",rewardGold=128700,rewardXP=2060,starts={{npcID=136933}},ends={{npcID=136933}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50784},questLines={{id=442,name="A House in Peril",orderIndex=36,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=36,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[50782] = {id=50782,name="Word on the Streets",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=8670,mapID=1165,mapCandidates={npc={},zone={8670}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=135218,text="Kaldorei Agent found"},{orderIndex=1,type=0,amount=1000,objectID=135223}},worldTaskTitle="Word on the Streets",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50783] = {id=50783,name="The Abyssal Council",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="The tidesages have a leading council beneath Lord Stormsong. They each oversee a different aspect of the order's work. Wavespeaker Reid trains initiates here in the oldest form of tidesage magic: communing with the sea. These deaths are on his hands. It's up to us to take him down.",rewardGold=514800,rewardXP=5145,rewardChoices={158699,158702,158701,158700,155236},starts={{npcID=136498}},ends={{npcID=136339}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50777,50778},questLines={{id=442,name="A House in Peril",orderIndex=34,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=34,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[50784] = {id=50784,name="Eye of the Storm",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="If Lord Stormsong wasn't aware of you yet, he is now. Your best shot is to reach him at the Shrine of the Storm before more of his followers fall back to his defense. I can get you in, but you'll have to protect me. I'm in no shape to take down any more of these fiends. And try to keep a low profile. The closer we get to the Shrine, the more power Lord Stormsong has at his disposal.",rewardGold=257400,rewardXP=4115,starts={{npcID=136497}},ends={{npcID=136933}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50780,50783},questLines={{id=442,name="A House in Peril",orderIndex=35,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=35,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[50786] = {id=50786,name="Revenge of Krag'wa",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=134982,text="Meet Krag'wa outside Zal'amak"},{orderIndex=1,type=0,amount=150,objectID=123437,text="Blood Trolls Slain"}},worldTaskTitle="Revenge of Krag'wa",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50787] = {id=50787,name="Make Our Case",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=1161,storyline={50787,50788,50789,50790,50795,50972},series={49741,50110,50788,50789,50790,50795},description="Katherine has trusted Priscilla Ashvane as an advisor and a close friend for many years, even before they both lost their husbands at Theramore. She's heard the rumors about Ashvane, just like anyone. Whether by fear or loyalty, she's chosen to ignore them. It's time to finally open her eyes.",objectivesText="Reveal Lady Ashvane's treason to Katherine Proudmoore .",rewardGold=257400,rewardXP=1415,rewardItems={162522},starts={{npcID=135335}},ends={{npcID=135259}},mapCandidates={npc={1161},zone={8568}},questGiverID=135335,questType="standard",sourceQuests={50795},questLines={{id=590,name="Enemies Within",orderIndex=1,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=41,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[50788] = {id=50788,name="Enemies Within",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=1161,storyline={50787,50788,50789,50790,50795,50972},series={49741,50110,50787,50789,50790,50795},description="We need to get Katherine to safety. Help us take out some of these traitors!",objectivesText="Slay 6 Ashvane combatants in Unity Square.",rewardGold=514800,rewardXP=1415,rewardItems={162522},starts={{npcID=135259}},ends={{npcID=135259}},mapCandidates={npc={1161},zone={8568}},questTurnInID=135259,questType="standard",sourceQuests={50787},questLines={{id=590,name="Enemies Within",orderIndex=2,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=42,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[50789] = {id=50789,name="Clear the Air",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=1161,storyline={50787,50788,50789,50790,50795,50972},series={49741,50110,50787,50788,50790,50795},description="Looks like Priscilla had a backup plan. Her goons set off some kind of smokescreen to cover her escape. Clear out that smoke so the civilians can evacuate and we can secure the area!",objectivesText="Destroy 4 Smoking Payloads in Unity Square.",rewardGold=257400,rewardXP=1415,rewardItems={142279,142282,142283,162522},starts={{npcID=135259}},ends={{npcID=135259}},mapCandidates={npc={1161},zone={8568}},questTurnInID=135259,questType="standard",sourceQuests={50787},questLines={{id=590,name="Enemies Within",orderIndex=3,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=43,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[50790] = {id=50790,name="Hot Pursuit",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=1161,storyline={50787,50788,50789,50790,50795,50972},series={49741,50110,50787,50788,50789,50795},description="Priscilla's escaping on horseback! Grab one of our chargers and chase her down!",objectivesText="Mount a Proudmoore Charger and chase Priscilla Ashvane .",rewardGold=619600,rewardXP=1770,rewardItems={162522},starts={{npcID=135259}},ends={{npcID=135259}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={50788,50789},questLines={{id=590,name="Enemies Within",orderIndex=4,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=44,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[50791] = {id=50791,name="Skree...",level=50,requiredLevel=50,faction="horde",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50791},description="< Kua'fon rests with his head under his wing.> Skree... <Perhaps the little guy could use a display of affection to raise his spirits.>",objectivesText="Soothe Kua'fon by picking him up.",rewardGold=234000,rewardXP=6815,rewardItems={157782,159146},starts={{npcID=135272}},ends={{npcID=133678},{npcID=135272}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50402},db2VignetteID=2771,db2VignetteName="Kua'fon"},
[50792] = {id=50792,name="Taking Bribes",expansion=7,mapID=895,questType="world",db2Objectives={{orderIndex=0,type=0,amount=5,objectID=134847,text="Dubious Guard questioned"}},worldTaskTitle="Taking Bribes",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50793] = {id=50793,name="Cave Commotion",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50674,50675,50691,50696,50697,50704,50741,50742,50753,50774,50793,50802,50803,50810,50955,52132},description="Killing that worm stirred up a commotion in the caves below. The Irontide seem pretty excited. We better check it out. Nedly's on his way, meet us near the caves.",objectivesText="Meet up with Nedly and Moxie near the caves.",rewardGold=25740,rewardXP=515,rewardItems={158226,158635,158636,158724,160481,160668},starts={{npcID=135067}},ends={{npcID=135330}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50774},questLines={{id=740,name="Deadwash Line",orderIndex=11,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50794] = {id=50794,name="Seeking Shelter",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={50794},description="I must head back to de arena. Razgaji will want to know what happened here. If you seek shelter, you will find it at de outpost not too far from here. I will let our leader know you're coming. Be safe, <name>.",objectivesText="Find Razgaji at the Scorched Sands Outpost.",rewardGold=257400,rewardXP=515,starts={{npcID=134162}},ends={{npcID=126576}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50561},nextQuests={48585,51573}},
[50795] = {id=50795,name="Prepare for Trouble",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=1161,storyline={50787,50788,50789,50790,50795,50972},series={49741,50110,50787,50788,50789,50790},description="With the evidence you've gathered, we can prove that the Ashvane Company was behind the attack. I would have preferred to do this in private, but I don't think we'll have the luxury. Look around - company men everywhere. Priscilla's got something up her sleeve... Let's get some backup before we go in there and cause a scene.",objectivesText="Speak with 4 Proudmoore Guards in Unity Square.",rewardGold=189240,rewardXP=1415,rewardItems={162522},starts={{npcID=135259}},ends={{npcID=135259}},mapCandidates={npc={1161},zone={8568}},questTurnInID=135259,questType="standard",sourceQuests={50110},questLines={{id=590,name="Enemies Within",orderIndex=0,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=40,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[50796] = {id=50796,name="SKREEEEE!",level=50,requiredLevel=50,faction="horde",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50796},description="< Kua'fon opens his maw and issues a continuous screech.> SKREEEEEEEEEEEEE!!! <You know what to do.>",objectivesText="Feed Kua'fon . Progress: SKREEEEEEEEEEEEEEEEEEE!!",rewardGold=234000,rewardXP=6815,rewardItems={141605,157779,157780,157781,157782,159146},starts={{npcID=135279}},ends={{npcID=133678},{npcID=135279}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50402},db2VignetteID=2772,db2VignetteName="Kua'fon"},
[50797] = {id=50797,name="A Turtle's Invitation",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50797},description="You have been most helpful <race>. Please visit me and the other Tortollans along the Jeweled Coast. We'll discuss soup and other pressing matters.",objectivesText="Visit Maokka and the other Tortollans at the Jeweled Coast.",rewardGold=25740,rewardXP=515,starts={{npcID=135033}},ends={{npcID=136710}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50753},nextQuests={51343},startItems={158213}},
[50798] = {id=50798,name="Out on a Limb",level=50,requiredLevel=50,faction="horde",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50798},description="Ah, there you are. Kua'fon ran off into de jungle. I saw him head down de western path out of the Kraal but beyond that I could not say where he may have gone. This kind of thing happens with the young. Our winged companions have a keen sense of adventure! It would be helpful if yours could fly, but it is not yet time. I would check any reasonably high place that he could climb to, as a start.",objectivesText="Find and rescue Kua'fon in the Slough.",rewardGold=234000,rewardXP=6815,rewardItems={157782,159146},starts={{npcID=135308}},ends={{npcID=133678},{npcID=135296}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50402},db2VignetteID=2773,db2VignetteName="Kua'fon"},
[50800] = {id=50800,name="Into the Woods",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=148,mapID=62,storyline={50476,50642,50646,50647,50738,50740,50772,50800,50823,50837,50878,50879,50880,52436,52437,52438,52806,52967,52970,52971,52981,53604,53605,53606,53608,53609,53610,53627},series={50740,50772},description="Careful, <name> -- the forest is still brimming with Stormrage's forces... Look out behind you!",objectivesText="Defeat the Alliance ambush.",rewardGold=2000,rewardXP=1415,rewardItems={158075,158937,160251,163127,163128},starts={{npcID=134554}},ends={{npcID=134554}},mapCandidates={npc={62},zone={148}},questType="standard",sourceQuests={50772},questLines={{id=584,name="The Warchief's Command",orderIndex=7,flags=0}},db2PoiMapID=1,db2PoiUiMapID=63},
[50801] = {id=50801,name="A Nose for Ptrouble",level=50,requiredLevel=50,faction="horde",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50801},description="Ah, yes, I was wondering when you would come to check on your little one. As you have likely noticed, he is not here. Little ones are very curious and often seek to leave the nest before they are ready. It is often the brooding mother's job to keep them from wandering. What, did you think I was going to stop him? < Wingminder Goja laughs.> I heard some screeching to de west. Best hurry, or you may not have a hatchling to look after!",objectivesText="Find Kua'fon in the Slough and rescue him from danger.",rewardGold=234000,rewardXP=6815,rewardItems={157782,159146},starts={{npcID=135308}},ends={{npcID=133678},{npcID=135303}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50402},db2VignetteID=2774,db2VignetteName="Kua'fon"},
[50802] = {id=50802,name="Iron Low Tide",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50674,50675,50691,50696,50697,50704,50741,50742,50753,50774,50793,50802,50803,50810,50955,52132},description="A few years ago I tried to join the Irontide. They said I wasn't \"Irontide material\", not cruel or heartless enough! So I teamed up with Nedly and Moxie here in Deadwash, and we started looking for treasure on our own. Let's show these Irontide they're not \"Deadwash material\".",objectivesText="Kill 10 Irontide Pirates.",rewardGold=257400,rewardXP=4115,rewardItems={158226,158635,158636,158724,160481,160668},starts={{npcID=134720}},ends={{npcID=134720}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={52069},questLines={{id=740,name="Deadwash Line",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50803] = {id=50803,name="I Want It All Now",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50674,50675,50691,50696,50697,50704,50741,50742,50753,50774,50793,50802,50803,50810,50955,52132},description="These Irontide Raiders think they can just come in and take the treasure we've been hunting for months! By rights, that treasure is ours! Get in there and get our share of it, before it's gone. By share, I mean all of it!",objectivesText="Collect 12 Irontide Coin Bags . Progress: I want every piece of that treasure in there.",rewardGold=257400,rewardXP=4115,rewardItems={158226,158635,158636,158724,160481,160668},starts={{npcID=135330}},ends={{npcID=135330}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50793},questLines={{id=740,name="Deadwash Line",orderIndex=12,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50805] = {id=50805,name="Skycaller Shutdown",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={50805},objectivesText="Disrupt the Skycallers' Spire Destroy Crystal Pick Up Staff",rewardGold=455280,rewardXP=1415,mapCandidates={npc={},zone={8501}},questType="standard",sourceQuests={50751},db2Objectives={{text="Disrupt the Skycallers' Spire",amount=1,type=15,objectID=0,orderIndex=0},{text="Destroy Crystal",amount=20,type=2,objectID=282461,orderIndex=1},{text="Pick Up Staff",amount=20,type=0,objectID=140032,orderIndex=2}},worldTaskTitle="Skycaller Shutdown",db2PoiMapID=1642,db2PoiUiMapID=864},
[50808] = {id=50808,name="Halting the Empire's Fall",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=9598,mapID=1165,series={50087},description="Nazmir be havin' problem after problem, . I not be knowin' how it can get much worse dan an Old God tryin' ta take over. I be makin' me way back ta Zul'jan ta lead our efforts ta keep Nazmir safe. Ya should return ta Zuldazar and let Baine know what be goin' on here. Maybe he be likin' dis here underrot, who knows? I can get ya outta here and back ta Zul'jan, if ya be needin' it.",rewardGold=25740,rewardXP=345,rewardItems={245491},starts={{npcID=137113}},ends={{npcID=137113}},mapCandidates={npc={863},zone={9598}},questTurnInID=137113,questType="standard",sourceQuests={51244},questLines={{id=630,name="The Altar of Rot",orderIndex=2,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=86,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[50810] = {id=50810,name="Break 'Em Out",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50674,50675,50691,50696,50697,50704,50741,50742,50753,50774,50793,50802,50803,50810,50955,52132},series={50674,50675},description="An Irontide captain \"Calico McGee\" has been trying to scare us off for days now, but it's not working. He's ordered his men to lock everyone up and sell us as slaves! They've brought enough chains for everyone! Break the chains and set our workers free.",objectivesText="Free 10 workers.",rewardGold=257400,rewardXP=4115,rewardItems={31312,31313,31314,31315,33226,37959,38001,38044,38105,38230,38231,38232,38665,55004,65277,65297,65316,65335,65683,65703,65721,112591,112592,112593,112594,131699,142054,143498,158226,158635,158636,158724,160481,160668,177633,177634,177646,177648,177650,177651,177652,202283,203330,248563,248564,248565,248566},starts={{npcID=134720}},ends={{npcID=134720}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={52069},questLines={{id=740,name="Deadwash Line",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50812] = {id=50812,name="Awakened Elements",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={50771,50775,50812,51991,52129},description="It seems that all of this infernal blasting and hammering has stirred up... something. I heard some screaming from over in that direction. <He gestures vaguely to the north.> If you could go take care of the situation, that would be most appreciated.",objectivesText="Investigate the disturbance. Progress: Did you remove the impediment?",rewardGold=514800,rewardXP=5145,starts={{npcID=135180}},ends={{npcID=135180}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50775,51991},questLines={{id=5421,name="For Profit",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50813] = {id=50813,name="Cargo Reclamation",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={50813},rewardItems={158878},mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=6,objectID=158878},{orderIndex=1,type=0,amount=1,objectID=135377}},worldTaskTitle="Cargo Reclamation",db2PoiMapID=1642,db2PoiUiMapID=863,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50814] = {id=50814,name="A Horrible Place",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50814},description="This town is a horrible place full of bad people. All they care about is money! No one cares about the turtles! The turtles are out there, thirsty, drying up, and getting stepped on by monsters! You have to save the turtles for me!",objectivesText="Collect 6 Wetshell Turtles .",rewardGold=257400,rewardXP=4115,starts={{npcID=135367}},ends={{npcID=135367}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50691,50696,50697,50704}},
[50817] = {id=50817,name="A Charming Tail",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={50817,50818,50979,50980},series={50818},description="I think they would make great guardians, when they get older... with the proper training. However, it seems some of my trainees have wandered off. There are so many things nearby that could harm them! Between the walking sandstorms and angry plants... it's been safer to hide out here and look at night. I'm so exhausted! Could you take this flute with you and play them a little tune? It will remind them to come back to me.",objectivesText="Send 15 cobras to Jenoh .",rewardGold=257400,rewardXP=4115,rewardItems={158883,160847},starts={{npcID=135400}},ends={{npcID=135400}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50818},questLines={{id=5422,name="Feeding the Hungry",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50818] = {id=50818,name="A Lost Flute",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={50817,50818,50979,50980},series={50817},description="<This little flute, while dusty, appears to be well cared for. Its owner can't be too far away.>",objectivesText="Find the owner of the Desert Flute . Provided item:",rewardGold=25740,rewardXP=515,rewardItems={158882,160847,163036},ends={{npcID=135400}},startObjects={{objectID=282498,mapID=864,x=0.289,y=0.546}},coords={mapID=864,source="quest_giver",x=0.295,y=0.592},mapCandidates={npc={864},zone={8501}},questType="standard",questLines={{id=5422,name="Feeding the Hungry",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50823] = {id=50823,name="Ripe for the Picking",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=331,mapID=62,storyline={50476,50642,50646,50647,50738,50740,50772,50800,50823,50837,50878,50879,50880,52436,52437,52438,52806,52967,52970,52971,52981,53604,53605,53606,53608,53609,53610,53627},description="The kaldorei have finally halted our progress. In a perfect world, we could have marched all the way to Auberdine and taken Teldrassil before they could even slow us down - but it matters little. Malfurion will try to hold us back until his fleet returns from Silithus. Until then, his army is too small - if only we could find a path through these damned wisps. I have an idea. Let's have a chat with Saurfang.",objectivesText="Meet with Saurfang and Sylvanas in the Zoram'gar Outpost.",rewardGold=200,rewardXP=175,rewardItems={158075,158937,160251,163127,163128},starts={{npcID=134554}},ends={{npcID=135443}},mapCandidates={npc={62,63},zone={331}},questType="standard",sourceQuests={50800},questLines={{id=584,name="The Warchief's Command",orderIndex=8,flags=0}},db2PoiMapID=1,db2PoiUiMapID=63},
[50824] = {id=50824,name="Storm's End",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="I've no doubt he can feel our presence, but so long as Lord Stormsong maintains his spell the first move is ours. We have him surrounded, cornered like the rat he is. We must end this together.",rewardGold=772200,rewardXP=6175,rewardChoices={155177,155178,155179,155180,155186,155187,155188,155189},starts={{npcID=137506}},ends={{npcID=137691}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51319},questLines={{id=442,name="A House in Peril",orderIndex=40,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=40,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[50825] = {id=50825,name="Shrine of the Storm: Whispers Below",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9525,mapID=942,description="We must not let Lord Stormsong finish his work. If he delivers the fleet to Azshara, all of Kul Tiras will be vulnerable. Countless innocents will perish -- or worse. There is no time to wait for more of the Storm's Wake to arrive. We finish this now, for the good of all who call this valley home. We finish this for Samuel.",rewardGold=1029600,rewardXP=8230,rewardCurrencies={{id=1553,amount=600}},starts={{npcID=137691}},ends={{npcID=137691},{npcID=139970}},mapCandidates={npc={942},zone={9525}},questType="dungeon",sourceQuests={50824},questLines={{id=442,name="A House in Peril",orderIndex=41,flags=0}}},
[50834] = {id=50834,name="Keep It Down!",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={50834},description="There is a lot of noise and light coming from those filthy mechs down by the shore. No wonder my little hatchlings get so cranky! They are shaking up a coast that is already unstable. You never know what one might wake up that way! Let them know they should be careful.",objectivesText="Warn the goblins of danger.",rewardGold=25740,rewardXP=515,starts={{npcID=135400}},ends={{npcID=135179}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50980},nextQuests={50771,50775,52129}},
[50835] = {id=50835,name="The Port of Zandalar",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8670,mapID=1165,series={46926},description="King Rastakhan has given me orders to investigate de Harbor of Zandalar. De claim Princess Talanji has levied against General Jakra'zet for failing to maintain de safety of our kingdom is a serious accusation. For dis task, I would have you join me so dat I might have an outside perspective. When you are ready, meet me in de Grand Bazaar.",rewardGold=25740,rewardXP=175,starts={{npcID=122915}},ends={{npcID=135441}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={47514},nextQuests={46926},questLines={{id=5389,name="Unrest in Zuldazar",orderIndex=30,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[50837] = {id=50837,name="A Quick Flyover",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=148,mapID=62,storyline={50476,50642,50646,50647,50738,50740,50772,50800,50823,50837,50878,50879,50880,52436,52437,52438,52806,52967,52970,52971,52981,53604,53605,53606,53608,53609,53610,53627},series={50878,50879,50880,53604,53605},description="Malfurion knows that his wisp wall is a temporary measure. He is buying time for reinforcements to arrive in Teldrassil. It is imperative that we find a way through that wall, and quickly. I want you to take our explosive reserves and apply pressure. You will not be able to bring it down, but you may be able to find us an opening. I will have a squadron ready to strike once you break ground. Zarvik Blastwix should have a few bombardiers for the job.",objectivesText="Use explosives to fend off the Alliance army in Darkshore. Progress: Done?",rewardGold=2000,rewardXP=1415,rewardItems={158075,158937,160251,163127,163128},starts={{npcID=134554}},ends={{npcID=134554}},mapCandidates={npc={62},zone={148}},questType="standard",sourceQuests={50823},questLines={{id=584,name="The Warchief's Command",orderIndex=9,flags=0}},db2PoiMapID=1,db2PoiUiMapID=63},
[50838] = {id=50838,name="A Nose for Ptrouble",level=50,requiredLevel=50,faction="horde",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50838},description="Ah, so you noticed he is missing again. I would check de east this time. I heard some screeching from that direction. I am sure he will be fine- after all, what sort of trouble could he get in with you looking after him? < Wingminder Goja smiles just a touch sarcastically.> Best find out.",objectivesText="Find Kua'fon in Atal'Gral and rescue him from danger.",rewardGold=234000,rewardXP=6815,rewardItems={157782,159146},starts={{npcID=135308}},ends={{npcID=133679},{npcID=135464}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50412},db2VignetteID=2782,db2VignetteName="Kua'fon"},
[50839] = {id=50839,name="SKREEEEE!",level=50,requiredLevel=50,faction="horde",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50839},description="< Kua'fon opens his maw and issues a continuous screech.> SKREEEEEEEEE!! <You know what to do.>",objectivesText="Feed Kua'fon . Progress: < Kua'fon inspects your hands for food and shrieks demandingly at you.> Skree!",rewardGold=234000,rewardXP=6815,rewardItems={141605,157779,157780,157781,157782,159146},starts={{npcID=135455}},ends={{npcID=133679},{npcID=135455}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50412},db2VignetteID=2781,db2VignetteName="Kua'fon"},
[50841] = {id=50841,name="SKREEEEE!",level=50,requiredLevel=50,faction="horde",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50841},description="< Kua'fon opens his maw and issues a continuous screech.> SKREEEEEEEEE!! <You know what to do.>",objectivesText="Feed Kua'fon .",rewardGold=234000,rewardXP=6815,rewardItems={141605,157779,157780,157781,157782,159146},starts={{npcID=135502}},ends={{npcID=133680},{npcID=135502}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50900},db2VignetteID=2785,db2VignetteName="Kua'fon"},
[50842] = {id=50842,name="Mast Effect",level=50,requiredLevel=50,faction="horde",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50842},description="Kua'fon was peering over de edge and managed to fall off de cliff again. Normally he gets back up here on his own, but it be taking too long this time. Best go down to de beach and find him. He is probably stuck up one of de ship masts out there. If he will not come down, you can try bribing him with more fish.",objectivesText="Find Kua'fon in Talanji's Rebuke and bribe him down with fish.",rewardGold=234000,rewardXP=6815,rewardItems={109076,157782,158885,159146},starts={{npcID=135308}},ends={{npcID=133679},{npcID=135481}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50412},db2VignetteID=2783,db2VignetteName="Kua'fon"},
