[50860] = {id=50860,name="A Nose for Ptrouble",level=50,requiredLevel=50,faction="horde",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50860},description="Kua'fon is getting very large. Perhaps he thinks himself equal to de beasts of this jungle. He may well learn that he is not. You should find him before that lesson costs him his life. I heard a commotion to de north. Start there.",objectivesText="Find Kua'fon in the Savagelands and rescue him.",rewardGold=234000,rewardXP=6815,rewardItems={157782,159146},starts={{npcID=135308}},ends={{npcID=133680},{npcID=135504}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50900},db2VignetteID=2786,db2VignetteName="Kua'fon"},
