[50877] = {id=50877,name="Gahz'ralka",level=50,requiredLevel=50,faction="none",categories={},flags={"rare"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50877},rewardItems={161043},mapCandidates={npc={},zone={8499}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=129954}},worldTaskTitle="Gahz'ralka",db2PoiMapID=1642,db2PoiUiMapID=862,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
[50878] = {id=50878,name="Blurred Vision",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=148,mapID=62,storyline={50476,50642,50646,50647,50738,50740,50772,50800,50823,50837,50878,50879,50880,52436,52437,52438,52806,52967,52970,52971,52981,53604,53605,53606,53608,53609,53610,53627},series={50837,50879,50880,53604,53605},description="Look up. See them, scattered among the trees? Those brightly glowing owls are not living, breathing denizens of the forest... they are Kaldorei magic. Sentries. A ruse -- reporting everything they see back to Malfurion. We can't have that, now can we? Deal with them, <name>. But take care -- they aren't the only enemies in the forest. We cannot allow anything or anyone to stand in our way.",objectivesText="Eliminate the Sentry Owls in the trees and slay the frenzied furbolg of Darkshore.",rewardGold=2000,rewardXP=1415,rewardItems={158075,158937,160251,163127,163128},starts={{npcID=134554}},ends={{npcID=135003}},mapCandidates={npc={62},zone={148}},questType="standard",sourceQuests={53604,53605},questLines={{id=584,name="The Warchief's Command",orderIndex=13,flags=0}},db2PoiMapID=1,db2PoiUiMapID=62},
[50879] = {id=50879,name="The Trees Have Ears",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=148,mapID=62,storyline={50476,50642,50646,50647,50738,50740,50772,50800,50823,50837,50878,50879,50880,52436,52437,52438,52806,52967,52970,52971,52981,53604,53605,53606,53608,53609,53610,53627},series={50837,50878,50880,53604,53605},description="With the eyes of the forest shut, one thing remains: the ears. Ancients. They feel the vibrations of our footsteps and report our every move to Malfurion. Got that torch handy?",objectivesText="Defeat the Burning Ancient . Progress: These Ancients must be taken care of.",rewardGold=4000,rewardXP=1770,rewardItems={158075,158937,160251,163127,163128},starts={{npcID=135003}},ends={{npcID=135003}},mapCandidates={npc={62},zone={148}},questType="standard",sourceQuests={50878},questLines={{id=584,name="The Warchief's Command",orderIndex=14,flags=0}},db2PoiMapID=1,db2PoiUiMapID=62},
[50880] = {id=50880,name="An Unstoppable Force",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=1497,mapID=62,storyline={50476,50642,50646,50647,50738,50740,50772,50800,50823,50837,50878,50879,50880,52436,52437,52438,52806,52967,52970,52971,52981,53604,53605,53606,53608,53609,53610,53627},series={50837,50878,50879,53604,53605},description="Now is the time to strike, <name>. Passing through the wall will not be easy, but I think it's something you can handle. Do what you must to prevail, and meet me on the other side. I will lead a squad of sturdy soldiers and as many demolishers as can survive the passing. We may not make it to Darnassus today, but the outcome of this war does not rest on one victory alone -- it will come as the result of a thousand small victories. So let's get started, shall we?",objectivesText="Disrupt the Alliance forces in Darkshore.",rewardGold=2000,rewardXP=1415,rewardItems={158075,158937,160251,163127,163128},starts={{npcID=134554}},ends={{npcID=134554}},mapCandidates={npc={62},zone={1497}},questType="standard",sourceQuests={50837},questLines={{id=584,name="The Warchief's Command",orderIndex=10,flags=0}},db2PoiMapID=1,db2PoiUiMapID=62},
[50881] = {id=50881,name="Royal Report",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8670,mapID=1165,description="Blood magics practiced in de city, guards missing, and our chief spy, Yazma, is acting suspicious. We must present dis to Rastakhan, but without Yazma interfering. Luckily, Rastakhan is a clever king, which is something his opponents often forget. I have prepared a report in a code made by King Rastakhan and known only to myself and my brother, Habutu . Bring it to Habutu and he will see dat it gets to de king's ear.",rewardGold=22600,rewardXP=1415,rewardCurrencies={{id=1560,amount=50}},starts={{npcID=135441}},ends={{npcID=125953}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={46927,46928,46929},questLines={{id=594,name="Port of Zandalar",orderIndex=4,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=36,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[50882] = {id=50882,name="All to Ash",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,storyline={50882},description="All throughout our campaign here, I understood the warchief's objective. I saw her strategy... believed in its necessity. With Darnassus in Horde hands, the Alliance would be paralyzed. Anger and fear would fester in their hearts until they cracked and splintered like deadwood. But this... this will unite them. They will come for us. All of them. Return to the Undercity, . Speak to the warchief. We must make ready for what is to come.",objectivesText="Speak to Warchief Sylvanas Windrunner in Undercity.",rewardGold=200,rewardXP=175,rewardItems={31414,31415,31416,55009,55010,57477,57478,57479,94219,116415,120978,126924,131464,131866,137582,163036,163127,163128,180721,182165,183888,183889,183890,183891,183892,183893,198611,204584,204592,204600,204608,205989,210001,210951,211395,248042,248043,248044,248045,250352,263231},mapCandidates={npc={},zone={}},questType="standard"},
[50885] = {id=50885,name="Lei-zhi",level=50,requiredLevel=50,faction="none",categories={},flags={"rare"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50885},rewardItems={161033},mapCandidates={npc={},zone={8499}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=131233}},worldTaskTitle="Lei-zhi",db2PoiMapID=1642,db2PoiUiMapID=862,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
[50886] = {id=50886,name="Surrogate Wings",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50886},description="It is not my way to coddle the young of my brood. But I think I will make an exception for your little one. After all, I have seen you tend to him. It would be cruel to let your... efforts... go to waste. Venture into Zuldazar city proper and find something that can act as a surrogate wing for your young one. Wingminder Goja will know what to do next. Speak to him once you have it.",objectivesText="Acquire a Huge Dragon Kite . Progress: Did Pa'ku offer any useful advice?",rewardGold=234000,rewardXP=6815,rewardItems={158913},starts={{npcID=127377}},ends={{npcID=135308}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50396}},
[50887] = {id=50887,name="Ptrust Fall",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50887},description="I just want you to know how unusual this is for Pa'ku . She prefers to teach on the fly. What? It's true. This method might work. Sometimes when young pterrordax are not eager to fly, their mother will drag them from the nest and hold them in her claws until they are comfortable enough to spread their wings. Seeing as this little one has no mother, you will use the kite to act as one. Pa'ku has placed a trail for you to follow. Go and glide carefully- you may frighten your pterrordax more!",objectivesText="Board the Huge Dragon Kite and take your pterrordax on a flight to build his confidence.",rewardGold=234000,rewardXP=6815,starts={{npcID=135308}},ends={{npcID=135595}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50886}},
[50897] = {id=50897,name="Turn the Heat Around",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50897},description="<In standard goblin fashion, the Horde forces seem to be using flamethrowers to clear out the snow.> <This one is still usable despite being beaten on, you could use it to destroy some of the goblin mining machinery.>",objectivesText="Destroy 6 pieces of goblin machinery.",rewardGold=257400,rewardXP=2765,rewardItems={158918,158928},ends={{npcID=135815}},startObjects={{mapID=896,x=0.385,y=0.355}},coords={mapID=896,source="quest_giver",x=0.378,y=0.49},mapCandidates={npc={896},zone={8721}},questType="standard",startItems={158918}},
[50899] = {id=50899,name="Don't Stalk Me, Troll",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={50899},objectivesText="Portable Revealing Occular used Blood Troll invaders slain",rewardItems={158324,158924},mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{text="Portable Revealing Occular used",amount=1,type=0,objectID=134879,orderIndex=0},{text="Blood Troll invaders slain",amount=12,type=0,objectID=134868,orderIndex=1}},worldTaskTitle="Don't Stalk Me, Troll",db2PoiMapID=1642,db2PoiUiMapID=863,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50900] = {id=50900,name="Maybe When You're Older",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50900},description="< Pa'ku squints down at the young pterrordax.> Well, I am out of ideas. My son will take you back to the nest. Do not worry, this one can fly. YOUR little one will need to get back on his own. It builds character. Maybe he will grow out of this absurd deficiency in time.",objectivesText="Return to the nest at Pterror Rise. Progress: How did it go?",rewardGold=23400,rewardXP=850,rewardItems={109076},starts={{npcID=135595}},ends={{npcID=135308}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50887}},
[50901] = {id=50901,name="Saurid Surprise",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={50901},description="Da sands of Vol'dun be full of harsh creatures, but none so harsh as dey dat da Zandalari send. One of dese criminals be right here in da Scorched Sands. His name be Sezahjin, and he be da former chef ta da king. Did he tell ya dat he be famous for a dish called \"Saurid Surprise?\" Guess what da main ingredient be. He be fallin' far, but not far enough for Jani . It be time ta take his pride. Just be makin' sure dat da creatures of da sand not be seein' ya.",objectivesText="Survive Jani 's prank on Sezahjin. If you lose your saurid disguise, return to Jani for another. Progress: Ya taken dat accursed chef's hat yet, richmon?",rewardGold=257400,rewardXP=4115,rewardItems={152813},starts={{npcID=133859}},ends={{npcID=133859}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47442,51145}},
[50903] = {id=50903,name="A Missing Master",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={49939,50001,50036,50063,50090,50092,50172,50177,50238,50251,50903},description="Master Ashton had me grab some healing supplies and run to Mayor Royston when those things attacked town. He didn't make it behind the barricade. But if he's alive--and he's just crazy enough he might be--he's probably holed up in his cottage. With caustic compounds. And explosives. Look, why don't you go check out his basement and I'll stay out of the blast radi- I mean I'll go see if the garden can be salvaged. Try not to look flammable.",objectivesText="Find Master Ashton. Progress: Oh! You're not one of those monsters at all. Did you trounce those brutes?",rewardGold=25740,rewardXP=2765,rewardItems={156710,156828},starts={{npcID=131469}},ends={{npcID=131448}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={49939},questLines={{id=5442,name="Falconhurst",orderIndex=6,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50904] = {id=50904,name="The Abandoned Passage",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={50617,50702,50703,50904},description="My people have known about this ancient passageway for generations, but none have dared enter before now. The tunnel leads to the tomb of Mythrax the Unraveler and it is said that his power still radiates within the cavern. Who knows what horrors await us inside... It appears that your friends have already gone inside to face Jakra'zet and stop him from raising Mythrax from the dead. We don't have time to waste. We must find Kaja and Rakera before they confront Jakra'zet on their own!",objectivesText="Find Bladeguard Kaja and Warguard Rakera in Atul'Aman.",rewardXP=515,starts={{npcID=135625}},ends={{npcID=135625}},mapCandidates={npc={864},zone={8501}},questTurnInID=135625,questType="standard",sourceQuests={50617},questLines={{id=611,name="Atul'Aman",orderIndex=1,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=61,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50908] = {id=50908,name="Smells Like Trouble",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50908},description="The Horde spilled a lot of blood in Brennadam. Now it's time to spill some more. The scent of blood makes predators in these hills go crazy. We use it to lure animals when hunting. The Horde forces are occupying caves up in the hills. Toss these scent vials into the caves where the Force Commanders organize the attack. The smell should bring all the hills down upon them!",objectivesText="Slay Force Commanders Ogarth and Durmok. Progress: Those scent vials should help you eliminate both Force Commanders.",rewardGold=514800,rewardXP=5145,rewardItems={159144},rewardCurrencies={{id=1553,amount=50}},starts={{npcID=135682}},ends={{npcID=135682}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={52067}},
[50909] = {id=50909,name="Never Outgunned",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50909},description="This is our new home now, and we will fight to keep it! We may be outnumbered here, but we aren't going to be outgunned. Find us every axe, sword, spear, crossbow, and gun for our rebellion!",objectivesText="Find us 15 Rebel Weapons . Progress: We'll need more than that. Find us some weapons!",rewardGold=257400,rewardXP=4115,rewardItems={159713},starts={{npcID=135874}},ends={{npcID=135874}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={52067}},
[50910] = {id=50910,name="Dangerous Game",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50910},description="Most of these Horde don't scare us, but we lost two people today to a group of forsaken keenblades . We've had trouble tracking them down, we could really use your help. They're stealthy and dangerous fighters, so show no mercy.",objectivesText="Rid the hills of these Forsaken Keenblades .",rewardGold=257400,rewardXP=4115,starts={{npcID=135682}},ends={{npcID=135682}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={52067}},
[50911] = {id=50911,name="One Man Against the Horde",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50911},description="Me an' a few friends were trying to help some of the folks from Corlain flee safely to Arom's Stand after things started gettin' weird. I noticed some movement up the hill so I decided to come back and check it out. If the town goin' mad wasn't bad enough, now we have another problem to deal with. The Horde. <McKellis spits.> Those fools have no place on our lands. Wash the snow with their blood.",objectivesText="Kill 10 Horde forces.",rewardGold=257400,rewardXP=2765,starts={{npcID=135673}},ends={{npcID=135673}},mapCandidates={npc={896},zone={8721}},questType="standard"},
[50912] = {id=50912,name="Remix to Ignition",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,storyline={50912},description="<A goblin mining machine is halfway sticking out of the snow. Despite being buried, it seems to be in working condition. If only you had a key.>",objectivesText="Find the ignition key. Progress: <The machine lays lifeless on the snow.>",rewardGold=514800,rewardXP=3455,rewardItems={160101},startObjects={{objectID=284426,mapID=896,x=0.347,y=0.4}},endObjects={{objectID=284426,mapID=896,x=0.347,y=0.4}},coords={mapID=896,x=0.347,y=0.4},mapCandidates={npc={},zone={8721}},questType="standard"},
[50913] = {id=50913,name="Akunda's Blessing",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="You have proven worthy of my blessing, <name>. This means should you choose me as your loa, you can call upon my power when needed. Commune at my shrine to receive my gift. Know that whatever you choose, you will always be welcome within these walls.",objectivesText="Commune at Akunda 's Shrine. Progress: I bestow my blessing upon my followers.",rewardGold=25740,rewardXP=515,starts={{npcID=128152}},ends={{npcID=128152}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48996},questLines={{id=607,name="The Warguard's Fate",orderIndex=14,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=32,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50929] = {id=50929,name="Powder to the People",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50929},description="The Horde filth up on that hill seem to be mining some kind of ore I've not seen before. If they've come all the way out here to find it, it must be valuable. Take what you can find!",objectivesText="Gather Azerite from 6 crates. Progress: Did you figure out what they were doing up there?",rewardGold=257400,rewardXP=2765,rewardItems={159076},rewardCurrencies={{id=1553,amount=75}},starts={{npcID=135673}},ends={{npcID=135673}},mapCandidates={npc={896},zone={8721}},questType="standard"},
[50930] = {id=50930,name="Falling With Style",level=50,requiredLevel=50,faction="horde",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50930},description="< Kua'fon looks to the kite, then back at you. He looks to the kite again, poking his head forward deliberately. He slowly pans his gaze back to you.> Skree. <Time for another flight!>",objectivesText="Take Kua'fon on another flight on the Huge Dragon Kite . Progress: There is a method to Pa'ku's madness.",rewardGold=234000,rewardXP=6815,starts={{npcID=141026}},ends={{npcID=135308}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50900},db2VignetteID=2827,db2VignetteName="Huge Dragon Kite"},
[50933] = {id=50933,name="An Unfortunate Event",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={50933},series={49777},description="<You have no means of identifying the corpse, but the clothing appears to be that of an imperial guard from Zuldazar. A quick search of the area reveals a trail of blood that heads off to the west. Perhaps if you follow it you can discover the cause of death.>",objectivesText="Discover what happened to the Imperial Guard .",rewardGold=23870,rewardXP=345,starts={{npcID=135784}},ends={{npcID=130930}},mapCandidates={npc={863},zone={8500}},questType="standard"},
[50934] = {id=50934,name="A Chance Sighting",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={50934},series={49366},description="One of the lookouts said he saw a bunch of blood trolls chasing after a Zandalari on the other side of the river. He seemed to be dressed like your group. Why do you people keep running into trouble in this place? I'll mark on your map where he was last seen. Just don't bring a horde of blood trolls over here, alright?",objectivesText="Investigate the missing Zandalari.",rewardGold=25740,rewardXP=345,rewardItems={156566},starts={{npcID=131993}},ends={{npcID=131993}},mapCandidates={npc={863},zone={8500}},questTurnInID=131993,questType="standard",sourceQuests={47696},nextQuests={49366}},
[50936] = {id=50936,name="Survival Strategy",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={50936},objectivesText="Saurid Feathers collected Diremaw Hide collected Pterrordax Claws collected",rewardItems={158191,158192,158193},mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{text="Saurid Feathers collected",amount=30,type=1,objectID=158191,orderIndex=0},{text="Diremaw Hide collected",amount=5,type=1,objectID=158193,orderIndex=1},{text="Pterrordax Claws collected",amount=3,type=1,objectID=158192,orderIndex=2}},worldTaskTitle="Survival Strategy",db2PoiMapID=1642,db2PoiUiMapID=863,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50940] = {id=50940,name="Wisdom of the Wingless",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50940},description="< Kua'fon wheezes and quivers, exhausted.> It's not going anywhere. Maybe it's time to seek someone without wings for advice.",objectivesText="Seek out Hexlord Raal .",rewardGold=23400,rewardXP=850,starts={{npcID=133682}},ends={{npcID=135801}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50397}},
[50942] = {id=50942,name="Dress for the Slide, Not the Ride",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50942},description="If Kua'fon is serious about flying, we're going to need to protect him. Go get a berserker skull and some armor for it. Meet me down in Talanji's Rebuke and we'll get him dressed for success.",objectivesText="Collect a Berserker Skull and Lightweight Skyterror Barding . Progress: You got the things I asked for?",rewardGold=234000,rewardXP=6815,rewardItems={159138,159139},starts={{npcID=135801}},ends={{npcID=135801}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50940}},
[50943] = {id=50943,name="The Joy of Flight",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50943},description="You be ready, <name>? Kua'fon is ready to fly. Whether or not he can is another question, but all the same I will see you two back to the roost. Climb aboard and guide him. I can't imagine he can see very well through that skull. Ata and I will lead the way.",objectivesText="Follow Hexlord Raal and fly Kua'fon back to the roost",rewardGold=234000,rewardXP=6815,starts={{npcID=135801}},ends={{npcID=135744}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50942}},
[50944] = {id=50944,name="Down, But Not Out",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50944},description="< Kua'fon wiggles happily in his new armor. He starts to pace restlessly back and forth. A taste for adventure has surely awakened in this flightless creature.> Skree! Skree!!",objectivesText="Accept Kua'fon as your new traveling companion.",rewardGold=702000,rewardXP=10225,rewardItems={159146},starts={{npcID=135744}},ends={{npcID=135744}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50943}},
[50953] = {id=50953,name="Greenstalker",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50953},description="The mighty wolf Greenstalker was once a protector of these forests. He has fallen under the sway of dark forces. My brother and I attempted to calm his spirit, but he is too far gone. Use the charm I have constructed to weaken him. I ask you <class>, please, end his suffering. My brother is still weak and I must stay to protect him. Go now before the wolf consumes us all!",objectivesText="Slay Greenstalker . Progress: Did you free Greenstalker 's spirit?",rewardGold=514800,rewardXP=3455,rewardItems={159143},starts={{npcID=135861}},ends={{npcID=135861}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={51543}},
[50954] = {id=50954,name="Zandalar Forever!",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={50954},description="Bwonsamdi has whispered a warning to me: the enemy is on the move. I have gathered what defenses I could in the time allowed but we are dangerously under powered. I can only hope that, thanks to your efforts, the loa will be with us this day. Are you ready to defend Zandalar?",objectivesText="Complete the Zandalar Forever scenario.",rewardGold=772200,rewardXP=2125,starts={{npcID=135890}},ends={{npcID=135887}},mapCandidates={npc={862,1165},zone={8499}},questType="standard",sourceQuests={47229,49426,50087,50702},questLines={{id=779,name="Zandalar Forever",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[50955] = {id=50955,name="We're Not Friends",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50674,50675,50691,50696,50697,50704,50741,50742,50753,50774,50793,50802,50803,50810,50955,52132},description="I did some time in Tol Dagor with the captain of this crew, Calico McGee. He likes to hang back and direct his men from afar. I just happened to have spotted him across the flats. You and I should go pay him a visit!",objectivesText="Eliminate Calico McGee.",rewardGold=514800,rewardXP=5145,rewardItems={27749,27750,27751,27752,31666,38672,39816,39886,39889,39890,53566,53567,53568,59235,59236,59237,59238,61497,61499,61501,121594,121595,121596,121597,129986,129994,130002,130013,130209,131553,140255,142054,151493,155040,155041,155042,155043,158226,158635,158636,158724,160481,160668,160858,160859,160860,160861,168847,169903,169909,169910,169916,169919,169921,169922,200493,200494,200497,200499,200501,200502,208058,223424,223441,223456,223464,249783,254267,264182},starts={{npcID=135946}},ends={{npcID=135946}},mapCandidates={npc={942},zone={9042}},questTurnInID=135946,questType="standard",sourceQuests={50793},questLines={{id=740,name="Deadwash Line",orderIndex=13,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[50956] = {id=50956,name="Walking-Around Money",level=30,requiredLevel=30,faction="alliance",categories={},flags={"repeatable","weekly"},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50956},description="This is a lot of gold! It's gonna take me a while to split this up. I can give you some walking-around money to hold you over until I am done. Come back tomorrow, maybe I will have it figured out.",objectivesText="Accept the money.",rewardItems={161878},starts={{npcID=134720}},ends={{npcID=134720}},mapCandidates={npc={942},zone={9042}},questTurnInID=134720,questType="standard",sourceQuests={50742}},
[50957] = {id=50957,name="Wrath of Rezan",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50957},objectivesText="Climb aboard Old K'zlotec Deliver Rezan's Wrath Deliver Rezan's Wrath",rewardItems={160509},mapCandidates={npc={},zone={8499}},questType="world",db2Objectives={{text="Climb aboard Old K'zlotec",amount=1,type=0,objectID=135908,orderIndex=0},{text="Deliver Rezan's Wrath",amount=1,type=15,objectID=0,orderIndex=1},{text="Deliver Rezan's Wrath",amount=50,type=0,objectID=135922,orderIndex=2}},worldTaskTitle="Wrath of Rezan",db2PoiMapID=1642,db2PoiUiMapID=862,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
