[50959] = {id=50959,name="Plundering Pirates",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={50959},objectivesText="Drive back the Irontide",rewardGold=429840,rewardXP=1415,mapCandidates={npc={},zone={8721}},questType="standard",db2Objectives={{text="Drive back the Irontide",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Plundering Pirates",db2PoiMapID=1643,db2PoiUiMapID=896},
[50960] = {id=50960,name="Sweete's Orders",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50960},description="<Tucked into the pages of the captain's logbook is a letter bearing the seal of Harlon Sweete. It looks like these pirates have been ordered by Sweete to cause further disruption to House Waycrest. Lucille should be notified of this immediately!>",objectivesText="Bring Sweete's Orders to Lucille Waycrest in Drustvar . Progress: What have you brought, mainlander?",rewardGold=25740,rewardItems={159156},ends={{npcID=129642},{npcID=131638}},startObjects={{objectID=286016,mapID=896,x=0.274,y=0.116}},coords={mapID=896,source="quest_giver",x=0.368,y=0.5},mapCandidates={npc={896},zone={8721}},questType="standard"},
[50961] = {id=50961,name="Save Our Scrolls!",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={50961},objectivesText="Intact Tortollan Scroll collected",rewardItems={158176},mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{text="Intact Tortollan Scroll collected",amount=12,type=1,objectID=158176,orderIndex=0}},worldTaskTitle="Save Our Scrolls!",db2PoiMapID=1642,db2PoiUiMapID=863,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50962] = {id=50962,name="Cargo Reclamation",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={50962},rewardItems={158878},mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=6,objectID=158878},{orderIndex=1,type=0,amount=1,objectID=135377}},worldTaskTitle="Cargo Reclamation",db2PoiMapID=1642,db2PoiUiMapID=863,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50963] = {id=50963,name="Of Dark Deeds and Dark Days",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=9598,mapID=1165,description="I should have known better, and now Rezan is dead, and my own power is barely holding on. Soon Bwonsamdi himself will be coming to collect me. Talanji... she must know what has happened here. Go to her, tell her. Aid her where you can. I followed a god of strength and yet I have not de strength to face her with dis shame. For now, I must gather our forces and pursue Zul.",rewardGold=25740,rewardXP=175,rewardItems={245485},starts={{npcID=129757}},ends={{npcID=133050}},mapCandidates={npc={862,1165},zone={9598}},questType="standard",sourceQuests={49426},questLines={{id=5389,name="Unrest in Zuldazar",orderIndex=77,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[50964] = {id=50964,name="Ritual Combat",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8670,mapID=1165,mapCandidates={npc={},zone={8670}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=4,objectID=136017,text="Loa champions defeated"}},worldTaskTitle="Ritual Combat",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50965] = {id=50965,name="Those Who Remain",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50965},description="<The runes on the wooden plaque glow faintly with an ancient magic. It looks like it is a small piece of a larger record.> <One of the Thornspeakers at the Teller Farm would probably recognize what this is.>",objectivesText="Collect 8 Ashenwood Relics . Progress: Is there something more you need?",rewardGold=257400,rewardXP=2765,rewardItems={159350,160027},ends={{npcID=135976}},coords={mapID=896,source="quest_giver",x=0.3,y=0.404},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48622},startItems={160027}},
[50966] = {id=50966,name="Cleanup Crew",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={50966},rewardGold=309800,rewardXP=11765,rewardItems={160703},mapCandidates={npc={},zone={8499}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=10,objectID=135858},{orderIndex=1,type=1,amount=5,objectID=160703}},worldTaskTitle="Cleanup Crew",db2PoiMapID=1642,db2PoiUiMapID=862,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50967] = {id=50967,name="Lost in the Woods",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50967},description="My student, Amalie, and I have taken it upon ourselves to act as the keepers of these woods. We were away from Drustvar briefly, and upon our return, found the grove infested and the surrounding land corrupted. Amalie decided that she could deal with the grove infestation alone. It's been some time since she ran off, could you look for her while you're in the Ashenwood?",objectivesText="Find Amalie Oakseeker.",rewardGold=514800,rewardXP=3455,rewardCurrencies={{id=1553,amount=75}},starts={{npcID=135976}},ends={{npcID=135976}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48622}},
[50969] = {id=50969,name="Emergency Management",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=8499,mapID=862,mapCandidates={npc={},zone={8499}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=5,objectID=135886},{orderIndex=1,type=0,amount=5,objectID=136897,text="Injured Sailor Healed"}},worldTaskTitle="Emergency Management",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50970] = {id=50970,name="A Farmer's Fate",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50970},description="Old Jakob here was one of the few folks who were never wary of us. I have, on occasion, even helped him around his farm in return for supplies. It is an injustice just to ignore his plight even amidst our own problems. The corruption which holds him seems to be early in form. I believe I can cleanse it. Take this branch, and bring it to the three shrines around the Ashenwood. That should allow it to gather enough energy for the ritual.",objectivesText="Empower the Everliving Branch.",rewardGold=257400,rewardXP=2765,starts={{npcID=135976}},ends={{npcID=135976}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48622}},
[50972] = {id=50972,name="Proudmoore's Parley",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=1161,storyline={50787,50788,50789,50790,50795,50972},description="So, we meet again. I... apologize for how you were treated last time. I trusted Priscilla like a sister and-- <Katherine chokes up for a moment before regaining her composure.> Let us keep this brief, for I will make no promises nor any formal accords in this state. Return to your leaders. Tell them I wish to parley. That is all for now. My people have suffered a great deal today and I have much to reflect upon.",objectivesText="Report to Genn Greymane in Boralus Harbor.",rewardGold=146790,rewardXP=1060,rewardItems={155020,155021,155022,155031,155032,155033,155034,155039,162522,245271,252386,252400,252403,252406,252653,252654,252754},rewardChoices={155020,155021,155022,155031,155032,155033,155034,155039},starts={{npcID=121144}},ends={{npcID=120788}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={50790},questLines={{id=590,name="Enemies Within",orderIndex=5,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=45,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[50975] = {id=50975,name="Azerite Mining",expansion=7,mapID=864,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Azerite recovered"},{orderIndex=1,type=0,amount=7,objectID=136620,text="Elite kill credit"},{orderIndex=2,type=2,amount=100000,objectID=287086,text="Interact Credit - Small"},{orderIndex=3,type=2,amount=100000,objectID=287497,text="Interact Credit - Large"},{orderIndex=4,type=0,amount=17,objectID=136619,text="Lieutenant Kill Credit"},{orderIndex=5,type=0,amount=34,objectID=136618,text="Normal Credit"},{orderIndex=6,type=0,amount=100,objectID=136617,text="Minus Mob Kill Credit"}},worldTaskTitle="Azerite Mining",db2QuestInfoID=151,db2QuestInfoName="Magni World Quest - Azerite"},
[50976] = {id=50976,name="An Ancient Curse",level=20,requiredLevel=20,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8500,storyline={50976},description="<The harsh conditions of Nazmir have not been kind to the stone tablet. Most of the inscriptions have been worn away but you are able to make out a picture that shows a chest surrounded by glyphs. Above the chest you noticed what appears to be a large floating skull. Below the images you find a single word \"Aiji\". The ruins ahead seem foreboding, and you may want to bring some friends to help you. With their help, perhaps you can find the secret of this \"Aiji\" and its treasure within.>",objectivesText="Activate the braziers of Xal'vor and defeat Aiji the Accursed .",rewardGold=514800,rewardXP=3455,rewardItems={163506},rewardCurrencies={{id=1553,amount=115}},startObjects={{objectID=287081,mapID=863,x=0.529,y=0.759}},endObjects={{objectID=287081,mapID=863,x=0.529,y=0.759}},coords={mapID=863,x=0.529,y=0.759},mapCandidates={npc={},zone={8500}},questType="group"},
[50977] = {id=50977,name="Smuggler Shakedown",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={50977},rewardItems={159673},mapCandidates={npc={},zone={8568}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=5,objectID=159673},{orderIndex=1,type=0,amount=1,objectID=136198}},worldTaskTitle="Smuggler Shakedown",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[50978] = {id=50978,name="Out With the Old Boss",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50978,50988,51001,51018,51019,51020},description="Right so I talked to some people. You talked to some people. No one likes the Irontide. They're cutting in to profits and scaring off good, honest scoundrel- er customers! We take out the guy in charge and we'll be able to run the rest outta town! So a little change of management is in order. I'm not usually one for stabbin' people, I'm a lover not a fighter, but I can pay. You do this for me and I'll make sure you're welcome here whenever ya want? Sound good?",objectivesText="Slay Richard Tornsail .",rewardGold=514800,rewardXP=3455,rewardItems={158639,158640,158642,158643,158644,158645,158648,158649,160207},rewardChoices={158640,158642,158639,160207,158644,158649,158643,158648,158645},starts={{npcID=136234}},ends={{npcID=136234}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={51019,51020},questLines={{id=5449,name="Smuggler's Cove",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[50979] = {id=50979,name="Just a Nip",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={50817,50818,50979,50980},description="My tough-guys-in-training are quick learners! They do seem to get a bit... bitey... when they're grouchy, though. Too many, and I start to get a little light-headed. The nearby atrivax plants have a medicinal gel. It is great to treat fresh wounds and nullify venom. They don't like sharing it. Could you harvest a bit for me?",objectivesText="Get 10 samples of Atrivax Gel. Progress: How goes the juicing?",rewardGold=257400,rewardXP=4115,rewardItems={159675,160847},starts={{npcID=135400}},ends={{npcID=135400}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50818},questLines={{id=5422,name="Feeding the Hungry",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[50980] = {id=50980,name="My Hungry Neighbor",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={50817,50818,50979,50980},description="There is an angry hydra that has decided to make a nearby ridge his home. He keeps getting bigger, and meaner, and hungrier! My cobras are terrified. Please, <name>, take care of him before he comes after us!",objectivesText="Kill the Territorial Hydra .",rewardXP=5145,rewardItems={160004,160005,160006,160007,160008,160847},rewardChoices={160005,160006,160007,160008,160004},starts={{npcID=135400}},ends={{npcID=135400}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50817,50979},questLines={{id=5422,name="Feeding the Hungry",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
