[50988] = {id=50988,name="An Economic Opportunity",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50978,50988,51001,51018,51019,51020},description="You look savvy enough to jump on an opportunity when one comes by and, pal, do I have one for you. See that cove down there? It's run by entrepreneurs with an eye towards meeting the logistical shortfalls that might come up in your typical city or town situation. Well, it's normally run by them. We have a bit of an infestation by folks who are more mercenary minded if you catch my meaning. You help me win back control of the cove and I'll see you're treated well. Sound good?",objectivesText="Meet Cesi Loosecannon inside Anyport.",rewardGold=25740,rewardXP=345,rewardItems={159143},starts={{npcID=136234},{npcID=136458}},ends={{npcID=136234}},mapCandidates={npc={896},zone={8721}},questType="standard",questLines={{id=5449,name="Smuggler's Cove",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
