[50990] = {id=50990,name="Cutting Edge Poultry Science",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=210,storyline={50990},description="<Before you is a delicious chicken ... And yet, despite everything, there is something a little bit... lively about this creature. With a judicious application of science, there might be something that can still be done for this poor bird. You resolve to bring the chicken to Dr. Oglethorpe in Booty Bay with all haste.>",objectivesText="Take the Delicious Chicken to Dr. Oglethorpe in Booty Bay.",rewardGold=25740,rewardXP=175,rewardItems={160940},starts={{npcID=139372}},ends={{npcID=7406}},coords={mapID=210,source="quest_giver",x=0.43,y=0.72},mapCandidates={npc={210},zone={9424}},questType="standard"},
