[51016] = {id=51016,name="Seeking More Knowledge",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"herbalism"},categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=895,storyline={51016,51360,51361},description="It pains me to admit that I don't know everything about plants. I've taught you everything I know about Anchor Weed, but I think I know where you could look to learn more. Unfortunately, it's in Waycrest Manor, and that whole area's been crawling with monsters as of late. If you find yourself inside that manor, keep an eye out for a book called, \"The Treatise on Anchor Weed\". Its author spent decades studying that forsaken weed.",objectivesText="Retrieve the Treatise on Anchor Weed from within Waycrest Manor. Progress: Have you retrieved the book?",rewardItems={152505,152506,152507,152508,152509,152510,152511,159877,159956,159960,160035,160064,160117,163834},starts={{npcID=136096}},ends={{npcID=136096}},mapCandidates={npc={},zone={8568}},questGiverID=136096,questTurnInID=136096,questType="dungeon",questLines={{id=750,name="8.0 Professions - Gathering - Herbalism - Kul Tiras - Anchor Weed  - SCS",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[51017] = {id=51017,name="Supplies Needed: Monelite Ore",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=1161,storyline={51017},objectivesText="Progress: Are you here to deliver supplies?",rewardItems={152512,152668},rewardCurrencies={{id=1553,amount=174},{id=1553,amount=175},{id=1553,amount=177},{id=1553,amount=192}},starts={{npcID=142095}},ends={{npcID=142095}},mapCandidates={npc={},zone={8568}},questGiverID=142095,questTurnInID=142095,questType="world",db2Objectives={{orderIndex=0,type=1,amount=20,objectID=152512}},worldTaskTitle="Supplies Needed: Monelite Ore",db2PoiMapID=1643,db2PoiUiMapID=1161,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51018] = {id=51018,name="Asking for a Friend",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50978,50988,51001,51018,51019,51020},description="Hey! Since you helped Cesi I thought maybe you might do a favor for me. Well, uh, y'see Miss Sweetflower over there? Sweet as honey, sharp as a tack, and cooks like a goddess. I'm not much to look at, but the lady might think kindly on me if I could surprise her with a gift. A really great gift! But I can't leave m'post or these red-coated jerks might run off with the merchandise. This is where you come in. Find out what Miss Sweetflower wants, get it and bring it back to me.",objectivesText="Ask Xun Xun Sweetflower what she would like and acquire it in Anyport. Progress: Did you find something?",rewardGold=257400,rewardXP=2765,rewardItems={159678,159783},starts={{npcID=136184}},ends={{npcID=136184}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50978},questLines={{id=5449,name="Smuggler's Cove",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[51019] = {id=51019,name="She's Got it Where it Counts",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50978,50988,51001,51018,51019,51020},description="Word is you're looking to drum up support for Loosecannon. Well I'll buy in if you help me. They took my poor Miranda ! Boss Tornsail says I had too much to drink and bet her in cards. I don't really remember what happened last night, but I can hold my liquor and I'd never bet my bird! I suspect funny business. She might not look like much, but Miranda 's the fastest damn falcon you'll ever see. They're watching me, so you go free her. She'll fly someplace safe and I'll get her later. We got a deal?",objectivesText="Free Miranda the falcon.",rewardGold=257400,rewardXP=2765,starts={{npcID=136233}},ends={{npcID=136233}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50988},questLines={{id=5449,name="Smuggler's Cove",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[51020] = {id=51020,name="Cutthroat Business Practices",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={50978,50988,51001,51018,51019,51020},description="I used to run the inn here. Was a nice gig. I got first crack a lot of good stuff and all the best gossip and information came through my place. And then that jerk, Gary Cofferdam , came in and kicked me out! The new Boss laughed! I'm lookin' at my last few silvers here. Business is not good! Tell ya what, you remove my problem and I'll side up with Cesi. She'd never kick me out.",objectivesText="Slay Gary Cofferdam in Anyport.",rewardGold=514800,rewardXP=3455,rewardItems={69777},starts={{npcID=136227}},ends={{npcID=136227}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50988},questLines={{id=5449,name="Smuggler's Cove",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
