[51085] = {id=51085,name="WANTED: Dark Chronicler",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8499,storyline={51085},description="Champion wanted for an expedition into the depths of Xibala. Strange noises and wails come from the bones at night and our workers are terrified. Seek out the source of the strange noises and destroy it, and a reward will be yours.",objectivesText="Slay Dark Chronicler",rewardGold=514800,rewardXP=1770,rewardCurrencies={{id=1553,amount=115}},startObjects={{objectID=287228,mapID=862,x=0.407,y=0.711}},endObjects={{objectID=287228,mapID=862,x=0.407,y=0.711}},coords={mapID=862,x=0.407,y=0.711},mapCandidates={npc={},zone={8499}},questType="group"},
[51086] = {id=51086,name="Break's Over",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=9439,mapID=14,storyline={51086},description="It's come to my attention a few of our peons have been caught sleeping instead of hauling iron from the mine. We can't let our supplies get low. Take this club and get those lazy peons back on track.",objectivesText="Return 3 Lazy Peons to work.",rewardItems={159744},rewardCurrencies={{id=1541,amount=10}},ends={{npcID=131750}},mapCandidates={npc={14},zone={9439}},questType="standard"},
[51087] = {id=51087,name="WANTED: Dark Chronicler",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51087},description="Champion wanted for an expedition into the depths of Xibala. Strange noises and wails come from the bones at night and our workers are terrified. Seek out the source of the strange noises and destroy it, and a reward will be yours.",objectivesText="Slay Dark Chronicler Progress: Something stirs in the ruins. I hope you can discover its source!",rewardGold=514800,rewardXP=1770,rewardCurrencies={{id=1553,amount=115}},ends={{npcID=131582}},startObjects={{objectID=287229,mapID=862,x=0.443,y=0.722}},coords={mapID=862,source="quest_giver",x=0.438,y=0.72},mapCandidates={npc={862},zone={8499}},questType="group"},
[51088] = {id=51088,name="Heart of Darkness",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="We sent troops with Captain Conrad ahead to Nazmir to gain a foothold in that hellish jungle. The reports we've been receiving of the local troll population are... disconcerting. They're in over their heads, <name>. I have Brann Bronzebeard prepped and ready to head out. Accompany Brann to Nazmir so we can secure our position. The Wind's Redemption is at your disposal.",objectivesText="Accompany Brann to Fort Victory in Nazmir.",rewardGold=273848,rewardXP=4790,starts={{npcID=135612}},ends={{npcID=136432}},mapCandidates={npc={863,1161},zone={8568}},questType="standard",sourceQuests={51571},questLines={{id=603,name="Heart of Darkness",orderIndex=0,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=39,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=39,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=603,questLineOrder=5,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[51089] = {id=51089,name="WANTED: Tojek",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={51089},description="<This appears to be a list of threats in the immediate vicinity, a angry scribble grabs your attention.> A reward of gold be promised to de one dat slays da creature Tojek . You know what dey say, an eye for an eye! -Rovash",objectivesText="Hunt down Tojek .",rewardGold=772200,rewardXP=4150,rewardCurrencies={{id=1553,amount=115}},ends={{npcID=135740}},startObjects={{objectID=287232,mapID=863,x=0.395,y=0.799}},coords={mapID=863,source="quest_giver",x=0.392,y=0.798},mapCandidates={npc={863},zone={8500}},questType="group"},
