[51127] = {id=51127,name="Getting Out of Hand",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={51127},objectivesText="Undead destroyed",rewardItems={153058},mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{text="Undead destroyed",amount=40,type=0,objectID=127902,orderIndex=0}},worldTaskTitle="Getting Out of Hand",db2PoiMapID=1642,db2PoiUiMapID=863,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51129] = {id=51129,name="Dubious Offering",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51150,51167,51168,51169},description="Cannae be sure o' the wisdom o' this Captain Conrad. Sendin' our own on these blood troll bats with offerin's? Somethin' about this stinks more'n an armpit after a bar fight.",objectivesText="Take a bat from Fort Victory to Zalamar in Nazmir.",rewardGold=257400,rewardXP=4790,starts={{npcID=136432}},ends={{npcID=136641}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={51088},questLines={{id=603,name="Heart of Darkness",orderIndex=1,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=40,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=40,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=603,questLineOrder=5,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[51130] = {id=51130,name="Azerite for the Horde!",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,storyline={51130},rewardXP=2830,rewardItems={151557,166883,168615,169765},mapCandidates={npc={},zone={}},questType="standard"},
[51131] = {id=51131,name="Absolutely Barbaric",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=8500,mapID=863,mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Zal'amak razed"},{orderIndex=1,type=0,amount=25,objectID=134244,text="Zal'amak Trolls slain"},{orderIndex=2,type=0,amount=17,objectID=134259}},worldTaskTitle="Absolutely Barbaric",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51134] = {id=51134,name="If Bones Could Talk",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={51134},description="<These skeletons appear to be rising out of the ancient ruins that dot the land here. Their bones are covered with what looks like runes, but time has worn away all but fragments of the markings. If you could find some of these runes intact, Lucille might be able to decipher them to find out where these skeletons come from... ...and why they are no longer at rest.>",objectivesText="Collect a Pristine Rune-Etched Bone from Awakened Dead in Alpine Rise. Progress: What's this?",rewardGold=257400,rewardXP=2765,rewardItems={159746,159748},ends={{npcID=127715},{npcID=129642}},coords={mapID=896,source="quest_giver",x=0.4416,y=0.28},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48941},startItems={159748}},
[51139] = {id=51139,name="WANTED: Tojek",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={51139},description="<The tattered paper appears to include a list of known threats in the area. The top of the list reads: \" Tojek - Direhorn - Responsible for damages to 3 vehicles, 6 supply crates, and the tragic loss of Garrick Blacksteel 's mole machine, avoid at all costs.\" Perhaps you can hunt down this creature to prevent further attacks.>",objectivesText="Hunt down Tojek .",rewardGold=772200,rewardXP=4150,rewardCurrencies={{id=1553,amount=115}},ends={{npcID=135072}},startObjects={{objectID=287327,mapID=863,x=0.621,y=0.41}},coords={mapID=863,source="quest_giver",x=0.618,y=0.414},mapCandidates={npc={863},zone={8500}},questType="group"},
[51140] = {id=51140,name="Share the Wealth",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51140},description="<Though old and mud covered, this is still gold, lots of it! It's not enough to be Nedly's legendary lost treasure, but it's still several thousand in gold coins. It's a significant find, and should be returned to Shealds to be split among all the workers.>",objectivesText="Take the gold to Shealds.",rewardGold=25740,rewardXP=515,rewardItems={158226,158635,158636,158724,160481,160668},ends={{npcID=134720}},startObjects={{objectID=290765,mapID=942,x=0.508,y=0.568}},coords={mapID=942,source="quest_giver",x=0.43,y=0.565},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50697}},
[51142] = {id=51142,name="Pests",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51142},series={51145},description="Confound it all! These rat-faced thieves keep getting into all of our supplies! I swear, anything that's not tied down, and even some things that are, they nip off with'. You want to make a difference for the war effort in Zandalar? Pop off as many of those buggers as you can find. Otherwise, get on with it!",objectivesText="Slay 8 Thieving Snappers in the Alliance Docks.",rewardGold=257400,rewardXP=4115,starts={{npcID=136562}},ends={{npcID=136559}},mapCandidates={npc={864},zone={8501}},questType="standard"},
[51144] = {id=51144,name="A Bundle of Furs",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=1161,storyline={51144},description="You there! Would you happen to be passing by Hatherford? I have a delivery to make there, but my normal delivery person fell ill after a trip to Anglepoint. Would you mind taking this bundle of furs to Dandy Jones in Hatherford for me? I would go myself, but I must hold down my stall.",objectivesText="Deliver the Bundle of Warm Furs to Dandy Jones in Hatherford. Progress: Welcome to my inn, friend! How can I help ya?",rewardGold=64350,rewardXP=355,rewardItems={159751},starts={{npcID=124289}},ends={{npcID=133214}},mapCandidates={npc={895,1161},zone={8568}},questType="standard",sourceQuests={47189}},
[51145] = {id=51145,name="Curse of Jani",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51145},series={51142},description="Thief and killer, know dat ya be standin' before da Patron of Scavengers, da Lord of Thieves, da God of Garbage, Master of Minions, and da Keeper of Secrets. Ya be standin' before me in raiment worth entire kingdoms of gold, bearin' weapons dat cost more than even me most devout and renowned followers will ever earn. I tink now be a good time ta teach ya a lesson. Maybe show ya high and mighty greatness what it means ta be snappin' in da gutters.",objectivesText="Survive the Trial of Jani . Progress: You be bitin' that ratmon yet?",rewardGold=257400,rewardXP=4115,starts={{npcID=136559}},ends={{npcID=136559}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51142}},
[51146] = {id=51146,name="Kua'fon's Day Off",level=50,requiredLevel=50,faction="horde",categories={},flags={"repeatable","daily"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={51146},description="You know, I think Kua'fon might be lonely when you are not here. What makes me say that? Well, I got a very angry scroll from a Tortollan indicating he was stealing shiny things from their stalls, but that could mean anything. You should probably stop him before he damages your reputation, hm? < Wingminder Goja cackles.>",objectivesText="Stop Kua'fon from being a nuisance in the Port of Zandalar.",rewardGold=234000,rewardXP=6815,rewardItems={157782,159146},starts={{npcID=135308}},ends={{npcID=133679},{npcID=136589}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50412},db2VignetteID=2929,db2VignetteName="Kua'fon"},
[51147] = {id=51147,name="Kua'fon's Day Off",level=50,requiredLevel=50,faction="horde",categories={},flags={"repeatable","daily"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={51147},description="A messenger came from de Terrace of de Chosen. Your companion is at it again. < Wingminder Goja chuckles.> Not even de priests of Pa'ku seem to be able to convince him to leave. You should go and send him back home, where he belongs.",objectivesText="Find Kua'fon at the Terrace of the Chosen and send him home.",rewardGold=234000,rewardXP=6815,starts={{npcID=135308}},ends={{npcID=133680},{npcID=136581}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50900},db2VignetteID=2928,db2VignetteName="Kua'fon"},
[51149] = {id=51149,name="Left at the Port",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={51149},description="There was a mishap when we were loading the most recent shipment for the Southwind Station. Apparently some paperwork meant for the dockmaster was left behind. He can't hand over deliveries to the couriers without it, but the next cargo ferry won't be departing any time soon. Do you think you could deliver it by foot? The ferry dock is just a short ride down the road.",objectivesText="Deliver the package to Dockmaster Tyndall .",rewardGold=25740,rewardXP=175,starts={{npcID=136576}},ends={{npcID=129956}},mapCandidates={npc={895},zone={8567}},questType="standard"},
[51150] = {id=51150,name="Honoring the Fallen",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51129,51167,51168,51169},description="This is a shameful situation. Unforgivable! The soldiers weren't carryin' offerrin's to the blood trolls, they WERE the offerin'! It'd be right difficult to bury 'em proper in this hole. Best we can do is get their dog tags. Poor lads an' lassies.",objectivesText="Recover 7 Dog Tags from Fort Victory soldiers.",rewardGold=257400,rewardXP=4790,starts={{npcID=136641}},ends={{npcID=136641}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={51129},questLines={{id=603,name="Heart of Darkness",orderIndex=3,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=41,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=41,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=603,questLineOrder=5,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[51151] = {id=51151,name="A Letter to the League",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={51151},series={49225,50700},description="A researcher at the Resort up the hill was hoping to get a letter out to a group called the \"Explorers' League\". He claims that they have a camp set up near some old Drust ruins on the other side of the sound. There's no official station so it will have to be delivered by hand. If you happen to head in that direction, can you take it with you?",objectivesText="Find the Explorers' League members at the Thovas Base-Camp. Provided item:",rewardGold=25740,rewardXP=175,rewardItems={160574},starts={{npcID=129956}},ends={{npcID=128381}},mapCandidates={npc={895},zone={8567}},questType="standard",nextQuests={49225}},
[51153] = {id=51153,name="Mor'fani the Exile",level=50,requiredLevel=50,faction="none",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={51153},rewardItems={162616},mapCandidates={npc={},zone={8501}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=134694}},worldTaskTitle="Mor'fani the Exile",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
