[51159] = {id=51159,name="Bring out the Big Gun",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51159},description="<The cannon here is still in good condition. It's a lot of firepower to slow down the Horde. Taking this to Lea Martinel at Eckhart Lodge would really help their defenses.>",objectivesText="Cannon delivered.",rewardGold=257400,rewardXP=4115,rewardCurrencies={{id=1560,amount=50}},starts={{npcID=136481}},ends={{npcID=135874}},mapCandidates={npc={942},zone={9042}},questGiverID=136481,questType="standard",sourceQuests={50909}},
[51161] = {id=51161,name="WANTED: Za'roco",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51161},description="To any with honor and a sharp blade: Find and kill the thief, Za'roco. Those that betray their fellow exile don't deserve to live. Any who can cross his name off this list will earn a fitting reward.",objectivesText="Find and kill Za'roco the Grifter .",rewardGold=772200,rewardXP=6175,rewardCurrencies={{id=1553,amount=115}},ends={{npcID=126576}},startObjects={{objectID=287398,mapID=864,x=0.431,y=0.765}},coords={mapID=864,source="quest_giver",x=0.434,y=0.747},mapCandidates={npc={864},zone={8501}},questType="group",sourceQuests={51668}},
[51162] = {id=51162,name="WANTED: Taz'raka the Traitor",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51162},description="To all caravans and travelers: Beware Taz'raka the Traitor , a skeleton ambushing travelers on the road near Port of Zem'lan. If you must travel on that road, move quickly, and avoid entering any of the ruins. Several caravans have combined resources to offer a reward for Taz'raka's death. To collect, speak with Norah in Camp Lastwind.",objectivesText="Find and kill Taz'raka the Traitor . Progress: Be careful out there, <name>.",rewardGold=772200,rewardXP=6175,rewardCurrencies={{id=1553,amount=115}},ends={{npcID=125904}},startObjects={{objectID=287440,mapID=864,x=0.388,y=0.77}},coords={mapID=864,source="quest_giver",x=0.388,y=0.772},mapCandidates={npc={864},zone={8501}},questType="group"},
[51164] = {id=51164,name="WANTED: Cobra Excursion Participants",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51164},description="Attention guests of the Goldtusk Inn: We're proud to announce a surprise new addition to our lineup of excursion activities! The new Giant Deadly Unstoppable Killer Cobra Experience is now available! There's no need to sign up, you've all been automatically volunteered for this activity. To participate, simply travel into the dunes north of the inn and try not to be killed by the massive cobra now patrolling the area. We are not currently offering guided tours for this activity. Have fun!",objectivesText="Kill Sevriss . Progress: All of our excursion survivors receive a reward!",rewardGold=772200,rewardXP=6175,rewardCurrencies={{id=1553,amount=115}},ends={{npcID=122723},{npcID=129354}},startObjects={{objectID=287442,mapID=864,x=0.436,y=0.599}},coords={mapID=864,source="quest_giver",x=0.435,y=0.602},mapCandidates={npc={864},zone={8501}},questType="group"},
[51165] = {id=51165,name="WANTED: Sandscout Vesarik",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51165},description="To any and all who wish to see the Faithless empire fall: Sandscout Vesarik was spotted patrolling the dunes to the east. Gather a formidable force and strike him down! Those who succeed will be granted a fitting reward.",objectivesText="Find and kill Sandscout Vesarik . Progress: Sandscout Vesarik was last seen patrolling the dunes to the east.",rewardGold=772200,rewardXP=6175,rewardCurrencies={{id=1553,amount=115}},ends={{npcID=134613}},startObjects={{objectID=287441,mapID=864,x=0.269,y=0.527}},coords={mapID=864,source="quest_giver",x=0.268,y=0.528},mapCandidates={npc={864},zone={8501}},questType="group"},
[51166] = {id=51166,name="Down to the Roots",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={51166},objectivesText="Bloodlasher Seedling destroyed",rewardGold=309800,rewardXP=1415,rewardItems={209910},mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{text="Bloodlasher Seedling destroyed",amount=15,type=0,objectID=133855,orderIndex=0}},worldTaskTitle="Down to the Roots",db2PoiMapID=1642,db2PoiUiMapID=863,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51167] = {id=51167,name="Blood of Hir'eek",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51129,51150,51168,51169},description="Spooky chantin' in the next room can only mean one thing: someone's askin' for the ol' what-fer! I'd give ya a hand but I gotta drink a couple-a potions before I'm back on me feet. Take out that blood witch and I bet the magic'll dissipate.",objectivesText="Defeat Blood Witch Pakkala . Progress: Two things I can't abide in this world: witches an' tall chairs.",rewardGold=257400,rewardXP=4790,starts={{npcID=136641}},ends={{npcID=136641}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={51129},questLines={{id=603,name="Heart of Darkness",orderIndex=2,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=42,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=42,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=603,questLineOrder=5,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[51168] = {id=51168,name="Zealots of Zalamar",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51129,51150,51167,51169},description="We're surrounded by the enemy, <name>, and it's got me blood ragin'! I'm fit as a fi... instrument... and ready to help get us outta this forsaken cavern. Let's show 'em the end o' their miserable lives, eh?",objectivesText="Slay 10 Zalamar Zealots in The Fall. Progress: Smells like... Victory.",rewardGold=257400,rewardXP=4790,starts={{npcID=136641}},ends={{npcID=136641}},mapCandidates={npc={863},zone={8500}},questTurnInID=136641,questType="standard",sourceQuests={51150,51167},questLines={{id=603,name="Heart of Darkness",orderIndex=4,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=43,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=43,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=603,questLineOrder=5,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[51169] = {id=51169,name="Flight from the Fall",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51129,51150,51167,51168},description="Let's get outta this hole! Hairs on the back o' me neck won't settle down. Was hopin' I'd find some artifacts, or treasures, or haggis, or at least a few worthwhile trinkets down here. Those bats look like the ones that we came on... hopefully they'll take us back to Fort Victory and not some rotten grotto with no valuables inside.",objectivesText="Take a bat to Fort Victory.",rewardGold=257400,rewardXP=4790,starts={{npcID=136645}},ends={{npcID=136432}},mapCandidates={npc={863},zone={8500}},questGiverID=136645,questType="standard",sourceQuests={51168},questLines={{id=603,name="Heart of Darkness",orderIndex=5,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=44,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=44,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=603,questLineOrder=5,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[51170] = {id=51170,name="Ooh Rah!",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51229,51283},description="We're going to need a harbor for our base of operations. Those ruins across the way should be perfect for our needs. Unfortunately, it looks to be occupied by a hostile force so I'm sending the marines to secure the shore. As the most experienced soldier here I want you to go with them. I don't want to see a single hostile remain when our engineers arrive. Now, go take that harbor in the name of the Alliance!",objectivesText="Capture Shatterstone Harbor.",rewardGold=257400,rewardXP=4790,rewardItems={159958,160044,160045},starts={{npcID=137867}},ends={{npcID=137008}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51283},questLines={{id=613,name="The Sands of Vol'dun",orderIndex=1,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=23,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=22,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=613,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
