[51177] = {id=51177,name="Lessons of the Damned",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51279,51280,51281,51282},description="When I arrived here in disguise, the blood trolls thought me some sort of messenger of their Blood God. I seized the advantage and played into their primitive beliefs. I came here intending to open trade and learn how we can work with them against the Horde. What I discovered was altogether more compelling. I will show you.",objectivesText="Learn of Captain Conrad 's progress.",rewardGold=238680,rewardXP=4790,starts={{npcID=136568}},ends={{npcID=136432}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={51282},questLines={{id=603,name="Heart of Darkness",orderIndex=10,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=49,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=45,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=603,questLineOrder=5,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
