[51190] = {id=51190,name="Granting a Reprieve",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="Now, on to more pressing matters. The Forsaken have shown up and are preventing us from saving our people. All my soldiers are either injured, exhausted, or in no shape for fighting. It seems these trollish natives have joined them as well. I am spread too thin. Kill the Horde. Kill the Zandalari. Kill them all.",objectivesText="Slay 8 Forsaken and 8 Zandalari in Talanji's Rebuke.",rewardGold=257400,rewardXP=4790,rewardItems={159779,159910,160249,160433},starts={{npcID=136197}},ends={{npcID=136197}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51201},questLines={{id=621,name="Mole Machinations",orderIndex=2,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=11,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=9,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=621,questLineOrder=4,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[51191] = {id=51191,name="Save Them All",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="Reinforcements? Ah thank tha Light! We done the best we can triaging the injured, but we need help. We need more hands that can heal wounds or at the verra least apply bandages . How are yer hands? Here, take these bandages and do what ye can tae treat tha injured.",objectivesText="Heal 8 injured sailors. Progress: We've done what we can. Now all we can do is rest.",rewardGold=257400,rewardXP=4790,rewardItems={159779,159910,160249,160433},starts={{npcID=136195}},ends={{npcID=136195}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51201},questLines={{id=621,name="Mole Machinations",orderIndex=3,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=12,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=10,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=621,questLineOrder=4,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[51192] = {id=51192,name="A Lack of Surplus",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="Food, wood, cloth... we're short on everything. Of course, I'm always short, but that donna stop me. Heh. See what ya can salvage from tha shipwrecks.",objectivesText="Collect supplies from the shipwreck. Progress: Did ya find anything useful?",rewardGold=257400,rewardXP=4790,rewardItems={159779,159910,160249,160433},starts={{npcID=136192}},ends={{npcID=136192}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51201},questLines={{id=621,name="Mole Machinations",orderIndex=4,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=13,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=11,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=621,questLineOrder=4,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[51193] = {id=51193,name="That One's Mine",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="Yer here to help? I donna have anything... Well, maybe I do. I know it's just a simple hammer. I know it's not special. But it's mine. That disgustin undead, Alan Hawkins, is taunting me wi'it. I promised Feorea I wouldna run off tae fight him, but ye made no such promises. Kill him and retrieve me hammer.",objectivesText="Retrieve Degdod's Hammer from Alan Hawkins. Progress: Donna judge me. This is me best hammer.",rewardGold=514800,rewardXP=5990,rewardItems={159779,159910,160249,160433},starts={{npcID=136192}},ends={{npcID=136192}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51201},questLines={{id=621,name="Mole Machinations",orderIndex=6,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=14,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=12,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=621,questLineOrder=4,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[51198] = {id=51198,name="Fertilizer Duty",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8501,mapID=864,mapCandidates={npc={},zone={8501}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=10,objectID=136770,text="Fertilizer"}},worldTaskTitle="Fertilizer Duty",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51199] = {id=51199,name="The Glory of the Hunt",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={51199},series={48070,48077},description="You here for the festival, friend? We're still settin' up here, but the hunt should've started by now! If ya want to take part, go meet Abbey in Foxhollow Woods. She'll get you all set up. Happy huntin'!",objectivesText="Meet Abbey Watkins at the edge of Foxhollow Woods.",rewardGold=128700,rewardXP=710,starts={{npcID=125042}},ends={{npcID=125309}},mapCandidates={npc={895},zone={8567}},questType="standard"},
[51200] = {id=51200,name="The Black Sheep",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51200,51203,51205,51207,51208,51209,51214,51215,51251,51335,51492,51504},description="I'll admit, Millie has never really been one to follow the herd. Usually, it's no problem. She'll wander off for a bit, do her own thing and eventually make her way back to the flock. The hills have grown increasingly more dangerous lately, especially with the wolves and giants about. She's been gone awhile and I'm starting to worry. Could you please help me look for her?",objectivesText="Find and rescue Millie .",rewardGold=257400,rewardXP=4115,starts={{npcID=136414}},ends={{npcID=136414}},mapCandidates={npc={942},zone={9042}},questType="standard",questLines={{id=5452,name="Milstone Hamlet",orderIndex=6,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[51201] = {id=51201,name="The Troll's Tale",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51308},description="You've arrived at an... interesting time, <class>. All of my ships have been destroyed. Half of my men are feeding the fishes, and the rest aren't doing much better. We're as good as doomed. And still, the Alliance prevails. These Zandalari trolls are to blame for this carnage. I need to know how they did it before we kill them all and escape from this Light-forsaken island.",objectivesText="Speak with the Captured Zandalari Troll to find out how the Alliance fleet was sunk. Progress: <Thom sneers at the Zandalari troll kneeling before him.> Talk, you filthy brute!",rewardGold=257400,rewardXP=4790,rewardItems={159779,159910,160249,160433},starts={{npcID=136197}},ends={{npcID=136195},{npcID=136197}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51308},questLines={{id=621,name="Mole Machinations",orderIndex=1,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=10,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=13,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=621,questLineOrder=4,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[51203] = {id=51203,name="Cry Wolf",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51200,51203,51205,51207,51208,51209,51214,51215,51251,51335,51492,51504},description="Lately, the wolves have been terrorizing my flock. They weren't an issue until the giants moved in and pushed them out of their normal hunting grounds. I feel bad asking you to do this, but could you thin their ranks a bit? If there are fewer wolves competing for food, maybe they'll leave us alone.",objectivesText="Kill 10 Feral Razorclaws .",rewardGold=257400,rewardXP=4115,starts={{npcID=136414}},ends={{npcID=136414}},mapCandidates={npc={942},zone={9042}},questType="standard",questLines={{id=5452,name="Milstone Hamlet",orderIndex=7,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[51204] = {id=51204,name="WANTED: Razorclaw Alpha",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51204},description="Adventurers Needed! The wolves have been attacking my flock! I don't have the means to fight them back. I've seen one, much larger than the rest, leading a few of the attacks. Please, if anyone can help, I'll gladly offer whatever reward I can muster. - Shepherd Mary Ann Milbrooke",objectivesText="Slay the Razorclaw Alpha .",rewardGold=514800,rewardXP=5145,rewardCurrencies={{id=1553,amount=115}},ends={{npcID=136414}},startObjects={{objectID=287958,mapID=942,x=0.306,y=0.681}},coords={mapID=942,source="quest_giver",x=0.318,y=0.695},mapCandidates={npc={942},zone={9042}},questType="group"},
[51205] = {id=51205,name="Aww, Rats!",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51200,51203,51205,51207,51208,51209,51214,51215,51251,51335,51492,51504},description="I didn't sign up for this! I just want to get back to the simple things, like grinding wheat and drinking mead. As if things couldn't get any worse around here, there's an army of rats ransacking the shed and I don't have the stomach to exterminate them. Here, I got this off some crazy gnome that stopped into port recently. I thought maybe it'd help with the bees. Maybe you can try it on the rats?",objectivesText="Collect 8 Bilge Rats .",rewardGold=257400,rewardXP=4115,rewardItems={159882},starts={{npcID=136574}},ends={{npcID=136574}},mapCandidates={npc={942},zone={9042}},questType="standard",questLines={{id=5452,name="Milstone Hamlet",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[51207] = {id=51207,name="Ettin It Done",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51200,51203,51205,51207,51208,51209,51214,51215,51251,51335,51492,51504},description="Okay, now here's a little something I whipped up for you with those extra ingredients. We don't have much around here in the way of weapons, but we've got gunpowder and plenty of flour. A surprisingly explosive combination! Toss one of these goodies at those nasty ettins, should disorient them long enough to give 'em a good whack upside the head! You thought I was just a sweet old lady, baking delicious cookies for any ol' passerby? Hah, I'll have you know I was quite the firecracker in my day.",objectivesText="Use Flour Bombs to slay 8 Ettins.",rewardGold=257400,rewardXP=4115,rewardItems={160052,160063,160333,160336,160339,160342,160383,160386,160389,160392},rewardChoices={160333,160336,160339,160342,160383,160386,160389,160392},starts={{npcID=136658}},ends={{npcID=136658}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51335},questLines={{id=5452,name="Milstone Hamlet",orderIndex=9,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[51208] = {id=51208,name="Wheat A Minute",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51200,51203,51205,51207,51208,51209,51214,51215,51251,51335,51492,51504},description="With the storage shed ransacked by rats and the giants pillaging our shipments, we've been running low on food. When I was making my way out here, I saw a bunch of grain sacks littered about, near the wrecked wagons. I'd appreciate it if you could retrieve whatever you find while you're out here.",objectivesText="Collect 10 Grain Sacks .",rewardGold=238680,rewardXP=4115,starts={{npcID=136574}},ends={{npcID=136574}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51504},questLines={{id=5452,name="Milstone Hamlet",orderIndex=10,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[51209] = {id=51209,name="Mighty Grokkfist",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51200,51203,51205,51207,51208,51209,51214,51215,51251,51335,51492,51504},description="Grandma is always telling me I need to toughen up a little... how easy we've got it these days. I read a story about giants that are terrified of rats, so I thought, \"Hey Charles, here's a great idea, let's take all those rats $p gathered and let 'em loose on the ettins.\" I tried to be tough for once, but look how it turned out. Now, I'm stuck out here, just hoping I don't get squashed. Their leader is just up the hill there. Here, take the rats with you and let's hope I was right!",objectivesText="Use the Pack of Rats to kill Grokkfist .",rewardGold=514800,rewardXP=5145,rewardItems={160063},starts={{npcID=136574}},ends={{npcID=136574}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51504},questLines={{id=5452,name="Milstone Hamlet",orderIndex=11,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[51210] = {id=51210,name="Blast Back the Siege",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8501,mapID=864,mapCandidates={npc={},zone={8501}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=143720,text="Cannon controlled"},{orderIndex=1,type=0,amount=30,objectID=136895,text="Faithless attackers slain"}},worldTaskTitle="Blast Back the Siege",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51211] = {id=51211,name="The Heart of Azeroth",level=40,requiredLevel=40,faction="both",categories={"legendary","campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=81,storyline={51211,52428},description="Our world's dyin', <name>. Sargeras's sword has cut deep. Her pain is drivin' the elements into a frenzy! I can hear Azeroth's voice, but she needs more than her speaker. She needs her champion. Far below us lies an ancient titan vault called the Chamber of Heart. I sense she wishes tae speak tae ye there. Come with me into the chamber. It may be our only chance tae save her!",objectivesText="Travel to the Chamber of Heart and commune with Azeroth. Progress: Ye need tae hear from Azeroth herself, <name>.",rewardGold=25740,rewardXP=685,rewardItems={33226,158075,158937,159671,160251,160326,163127,163128},starts={{npcID=130216},{npcID=137323}},ends={{npcID=130216}},mapCandidates={npc={81,862},zone={8499}},questTurnInID=130216,questType="standard",sourceQuests={52946,53028},questLines={{id=743,name="The Heart of Azeroth",orderIndex=0,flags=0},{id=785,name="The Heart of Azeroth",orderIndex=1,flags=0},{id=5379,name="The Heart of Azeroth",orderIndex=1,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=743,questLineOrder=1,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=2,title="War Campaign",questLineID=785,questLineOrder=1,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5379,questLineOrder=1},{id=225,title="War Campaign",questLineID=5379,questLineOrder=1}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2DetailThemeID=14,db2PoiMapID=1929,db2PoiUiMapID=1021},
[51212] = {id=51212,name="Waycrest Manor: Witchy Kitchen",expansion=7,mapID=896,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=131601,text="Executive Chef Daniel slain"},{orderIndex=1,type=0,amount=1,objectID=131611,text="Roast Chef Rhonda slain"},{orderIndex=2,type=0,amount=1,objectID=131607,text="Sauciere Samuel slain"},{orderIndex=3,type=0,amount=1,objectID=131864,text="Gorak Tul slain"}},worldTaskTitle="Waycrest Manor: Witchy Kitchen",db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
[51213] = {id=51213,name="Waycrest Manor: No need to Hag-gle",expansion=7,mapID=896,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=134112,text="Matron Christiane slain"},{orderIndex=1,type=0,amount=1,objectID=131864,text="Gorak Tul slain"}},worldTaskTitle="Waycrest Manor: No need to Hag-gle",db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
[51214] = {id=51214,name="Be A Dear",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51200,51203,51205,51207,51208,51209,51214,51215,51251,51335,51492,51504},description="As you can plainly see by the rocks falling from the sky, we are under siege by those terrible ettins! If you could be obliged to lend us a hand, I'd be most grateful. We can't possibly hope to defeat them unless we properly prepare you first. Could you be a dear and fetch a few things for me from around the Hamlet? Some water, a sack of flour , and a bundle of logs should help. I've already sent my grandson, Charles, off to fetch a few other items. I've not seen him for quite a while though.",objectivesText="Collect a Water Bucket , Sack of Flour , and Logs , then return them to Marie Davenport . Progress: Did you have any trouble dear?",rewardGold=257400,rewardXP=4115,rewardItems={59073,59074,59075,131437},starts={{npcID=136658}},ends={{npcID=136658}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51218},questLines={{id=5452,name="Milstone Hamlet",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[51215] = {id=51215,name="Milking Goats",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51200,51203,51205,51207,51208,51209,51214,51215,51251,51335,51492,51504},description="Unfortunately, Milbrooke's flock hasn't been producing lately. What with all the wolves about, the poor things must be terrified. Wild goats wander the hills, and they are quite fearless compared to the sheep. If you can find a few with young ones about, you may be able to persuade them to offer some fresh, delicious goat milk!",objectivesText="Collect 6 Mountain Goat Milk . Progress: Were you able to collect enough milk?",rewardGold=257400,rewardXP=4115,rewardItems={159781,159782},starts={{npcID=136658}},ends={{npcID=136658}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51205,51251,51492},questLines={{id=5452,name="Milstone Hamlet",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[51216] = {id=51216,name="Waycrest Manor: Something to Crow About",expansion=7,mapID=896,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=136945,text="Corvus slain"},{orderIndex=1,type=0,amount=1,objectID=131864,text="Gorak Tul slain"}},worldTaskTitle="Waycrest Manor: Something to Crow About",db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
[51217] = {id=51217,name="WANTED: Yarsel'ghun",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51217},description="By the decree of the Storm's Wake. Find and kill the foreign spy, Yarsel'ghun . A foreigner agent hiding on our soil, she is responsible for acts of terrorism against the citizens of Stormsong. The individual that ends her existence will earn a fitting reward.",objectivesText="Find and kill Yarsel'ghun . Progress: The wanted poster is nailed to the wall, with tasks etched on it.",rewardGold=772200,rewardXP=6175,rewardCurrencies={{id=1553,amount=115}},ends={{npcID=135874}},startObjects={{objectID=288157,mapID=942,x=0.578,y=0.558}},coords={mapID=942,source="quest_giver",x=0.578,y=0.555},mapCandidates={npc={942},zone={9042}},questType="group"},
[51218] = {id=51218,name="Undelivered Package",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51218},description="< The ransacked cart has obviously seen better days. A single package remains, obscured by the spilled grain. It's addressed to Marie Davenport of Millstone Hamlet. >",objectivesText="Deliver the package to Marie Davenport .",rewardGold=128700,rewardXP=2060,ends={{npcID=136658}},startObjects={{objectID=288167,mapID=942,x=0.384,y=0.629}},coords={mapID=942,source="quest_giver",x=0.304,y=0.668},mapCandidates={npc={942},zone={9042}},questType="standard",nextQuests={51214}},
[51220] = {id=51220,name="Deep Sea Venture",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51220},description="As mighty as Ai'twen is, this Venture Company is still a threat to him. I need you to watch over Ai'twen and Toki as you continue your great adventure. Eliminate the Venture Company Seawrenches that lurk the waters you travel to.",objectivesText="Eliminate 6 Seawrenches Progress: Hurry to it, Ai'twen's saftey is important.",rewardGold=257400,rewardXP=4115,starts={{npcID=137453}},ends={{npcID=137453},{npcID=137554}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51427}},
[51221] = {id=51221,name="Response Required",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51221},description="Time is short and more creatures will die without your help. The Venture Company prepares a huge digging machine to tear the reef apart and destroy this cave. They've assigned a special operative to be sure the job is done right. You must act now, $p. Take out the operative in charge of the camp; this should buy us some time.",objectivesText="Eliminate Lithia Costcutter",rewardGold=514800,rewardXP=5145,starts={{npcID=137453}},ends={{npcID=137453}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51353}},
[51222] = {id=51222,name="What's Yours is Mined",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51222},description="During a visit to Pandaria, I witnessed the citizens of Halfhill defeat attacking hozen by flinging the hozen's excrement back at them. The hozen were unprepared to face the wrath of their own weaponry used against them. A similar strategy can be applied here. We will gather Venture Co. Sea Mines and use them against the invaders. You hook ropes to each mine, and Ai'twen and I will haul them up.",objectivesText="Collect 10 Sea Mines",rewardGold=257400,rewardXP=4115,rewardItems={80783,80784,80785,80786,80787,160429},starts={{npcID=137554},{npcID=137677}},ends={{npcID=137554}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51427}},
[51223] = {id=51223,name="Walking on Broken Glass",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={51223},objectivesText="Sea Glass collected",rewardItems={159790},mapCandidates={npc={},zone={8501}},questType="world",db2Objectives={{text="Sea Glass collected",amount=30,type=1,objectID=159790,orderIndex=0}},worldTaskTitle="Walking on Broken Glass",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51224] = {id=51224,name="Profit and Reconnaissance",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={51224,51231,51233,51234,51332,51340,51985,51987},series={51332,51340},description="This was supposed to be a covert operation. Unfortunately, our Trade Prince insisted on coming along... with the loudest, most conspicuous vehicle the Horde has ever conceived. At least you're here with me, <name>. Let's get going, then. We know next to nothing about the Drustvar territory. It's time to do some recon.",objectivesText="Escort Gallywix and Eitrigg on Gallywix's War Trike. If you become separated from Gallywix and Eitrigg , you can find them at Anyport. Progress: Let's get this over with.",rewardGold=514800,rewardXP=5990,starts={{npcID=136725}},ends={{npcID=136725}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={51340},questLines={{id=604,name="Drustvar Foothold",orderIndex=2,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=22,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=604,questLineOrder=5,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=896},
[51225] = {id=51225,name="Albatrocity",expansion=7,mapID=895,questType="world",db2Objectives={{orderIndex=0,type=0,amount=8,objectID=136284,text="Terrified Civilian calmed"}},worldTaskTitle="Albatrocity",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51226] = {id=51226,name="Death from Two Sides",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={49716,49720,49733,49734,50249,51226},description="The overgrown lizards from down on the beach decided to swarm the camp suddenly. We're used to dealing with one or two each week, but it seems like the whole brood came up the cliff. Wonder if the smell of blood drew them in. They're putting our remaining men at risk, wipe them out!",objectivesText="Kill 8 Brinefang Saurolisk . Progress: Have you thinned out those saurolisks yet?",rewardGold=257400,rewardXP=1415,starts={{npcID=132720}},ends={{npcID=132720}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49715},questLines={{id=5431,name="Greystone Keep",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[51228] = {id=51228,name="Instant Meat, Ready to Eat",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={51228},rewardItems={159794,159795,159796},mapCandidates={npc={},zone={8501}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=15,objectID=159794},{orderIndex=1,type=1,amount=15,objectID=159795}},worldTaskTitle="Instant Meat, Ready to Eat",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51229] = {id=51229,name="Establish a Beachhead",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51170,51283},description="I won't allow Private Leonard's sacrifice to be in vain. Let's get our men out here and fortify this place up before those... \"sethrak\" decide to come back. Here, plant this banner somewhere visible so the ship knows its safe. That platform over next to the dock should do the trick.",objectivesText="Plant the Alliance banner and establish your base in Vol'dun.",rewardItems={159958,160044,160045},starts={{npcID=137008}},ends={{npcID=137213}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51170},questLines={{id=613,name="The Sands of Vol'dun",orderIndex=2,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=24,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=23,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=613,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[51230] = {id=51230,name="Emergency Transplants",level=10,requiredLevel=10,faction="horde",requiredProfessions={"herbalism"},categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={51230,51243},description="Riverbud is a precious resource for us. Not only does it have potent magical properties, but it also feeds many of de beasts we train or eat ourselves. However, de Blood Trolls have been dumping a lot of cursed blood in de rivers. It may not be their goal, but if we do not act soon, de pollution may wipe out all de riverbud. I need you to take dis handful of seeds, and plant dem in de rivermud. In exchange, I will teach you how to harvest it more effectively.",objectivesText="Plant 10 Riverbud Seeds in rivermud.",rewardItems={152505,152506,152507,152508,152509,152510,152511,159877,160064,160117,160301,160550},starts={{npcID=122704}},ends={{npcID=122704}},mapCandidates={npc={1165},zone={8670}},questType="standard",questLines={{id=757,name="8.0 Professions - Gathering - Herbalism - Zandalar - Riverbud - SCS",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[51231] = {id=51231,name="Wiccaphobia",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={51224,51231,51233,51234,51332,51340,51985,51987},description="Do you see that... that shape up in the brambles up ahead? Is that... < Eitrigg shudders.> Is that goblin... wrapped up in that tree?",objectivesText="Investigate the shape up ahead, then protect Eitrigg and Gallywix. Progress: Huh?",rewardGold=257400,rewardXP=4790,starts={{npcID=136725}},ends={{npcID=136725}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={51224},questLines={{id=604,name="Drustvar Foothold",orderIndex=3,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=23,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=604,questLineOrder=5,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=896},
[51232] = {id=51232,name="Hundred Troll Holdout",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,mapCandidates={npc={},zone={8499}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=100,objectID=136699}},worldTaskTitle="Hundred Troll Holdout",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51233] = {id=51233,name="I Hope There's No Witches in the Mountains",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=862,storyline={51224,51231,51233,51234,51332,51340,51985,51987},description="<Gallywix looks flustered after his ordeal with the crone.> You know, ah... I think maybe we better set up our foothold somewhere else. Maybe, up in the mountains? You know, like... not here, where the witches are?",objectivesText="Drive Eitrigg and Gallywix to the mountains. Progress: Yes, <name>?",rewardGold=257400,rewardXP=4790,starts={{npcID=136683}},ends={{npcID=136725}},mapCandidates={npc={862,896},zone={8721}},questType="standard",sourceQuests={51231},questLines={{id=604,name="Drustvar Foothold",orderIndex=4,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=24,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=604,questLineOrder=5,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=896},
[51234] = {id=51234,name="Krazzlefrazz Outpost",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={51224,51231,51233,51234,51332,51340,51985,51987},description="I already did a bunch of the leg-work for settin' up our foothold. All we gotta do is finish deploying all the instant-base technology, and we'll be good to go here in Drustvar. Why don't you go finish the base building. I'm gonna see if I can salvage any wolfercycle parts.",objectivesText="Use the goblin devices in Krazzlefrazz Outpost to build your foothold in Drustvar. Progress: What?",rewardGold=772200,rewardXP=7185,rewardItems={118411},starts={{npcID=137613}},ends={{npcID=136683}},mapCandidates={npc={862,896},zone={8721}},questType="standard",sourceQuests={51233},questLines={{id=604,name="Drustvar Foothold",orderIndex=5,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=25,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=604,questLineOrder=5,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=896},
[51238] = {id=51238,name="Abandoned in the Burrows",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8501,mapID=864,mapCandidates={npc={},zone={8501}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=6,objectID=138966,text="Vulpera Captives rescued"},{orderIndex=1,type=0,amount=12,objectID=123772,text="Sethrak slain"}},worldTaskTitle="Abandoned in the Burrows",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51239] = {id=51239,name="Instructions Not Included",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8501,mapID=864,mapCandidates={npc={},zone={8501}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=8,objectID=124016,text="Brine Basin wildlife slain"}},worldTaskTitle="Instructions Not Included",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51240] = {id=51240,name="WANTED: Anchorface",level=20,requiredLevel=20,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={51240},description="Kill the blasted shark that ate me legs! And me crew! And me boat - even the anchor! He's been swimming around in the sea, looking for his next meal. Kill 'im. I've left a reward with Cesi Loosecannon if you do. <The poster is signed 'Captain Slagbolt'>",objectivesText="Slay Anchorface in the waters near Anyport. Progress: Oh, did you kill that shark that almost got Ole Slaggy?",rewardGold=828600,rewardXP=4150,rewardCurrencies={{id=1553,amount=115}},ends={{npcID=136579}},startObjects={{objectID=288214,mapID=896,x=0.1957,y=0.4365}},coords={mapID=896,source="quest_giver",x=0.192,y=0.435},mapCandidates={npc={896},zone={8721}},questType="group",db2VignetteID=2937,db2VignetteName="Anchorface"},
[51241] = {id=51241,name="The Bear Witch Project",expansion=7,mapID=895,questType="world",worldTaskTitle="The Bear Witch Project",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51243] = {id=51243,name="Breaking The Food Chain",level=10,requiredLevel=10,faction="horde",requiredProfessions={"herbalism"},categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={51230,51243},description="De extra riverbud you planted has helped, but it has not been enough. Some of de local beasts are consuming de riverbud before dey can mature. We need dese plants to germinate, or we could risk losing it entirely. The largest group of young riverbud consumers are de jacunda. If we are going to give de riverbud a chance to survive dis, you will need to thin their numbers. Do dat and I will teach you everything I know about riverbud.",objectivesText="Kill 12 Ravenous Jacunda .",rewardItems={152505,152506,152507,152508,152509,152510,152511,159877,160064,160117,160301,160550},starts={{npcID=122704}},ends={{npcID=122704}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={51230},questLines={{id=757,name="8.0 Professions - Gathering - Herbalism - Zandalar - Riverbud - SCS",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[51244] = {id=51244,name="What Rots Beneath",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Good job killin' Ateena and sendin' whatever dat construct was down ta da bottom of... whatever dis ting be. Me scouts be seein' Titan Keeper Hezrel marchin' down to sometin' called da Altar of Rot. Now dat we got rid of dat construct, we can be flyin' down dere ta see what Hezrel be up to. Dis be best handled by you and me. Da princess be havin' business back in da city.",rewardGold=25740,rewardXP=345,starts={{npcID=140656}},ends={{npcID=137112}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={50087},questLines={{id=630,name="The Altar of Rot",orderIndex=0,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=85,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[51245] = {id=51245,name="I'm a Lumberjack and I'm Okay",expansion=7,mapID=895,questType="world",db2Objectives={{orderIndex=0,type=0,amount=4,objectID=143791,text="Entangled Lumberjack freed"},{orderIndex=1,type=0,amount=8,objectID=137021,text="Wicker invaders slain"}},worldTaskTitle="I'm a Lumberjack and I'm Okay",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51246] = {id=51246,name="The Wreckoning",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51246},series={51555},description="I can't believe any of them survived the wreck. We were told to prevent any survivors from gaining a foothold. There are far more of them than expected. We need to weaken their forces. Well? What are you waiting for? An engraved invitation?",objectivesText="Kill 10 Shipwrecked 7th Legion.",rewardGold=257400,rewardXP=1415,starts={{npcID=137075}},ends={{npcID=137075}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51555}},
[51247] = {id=51247,name="The Things They Carried",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51247},description="We need to know more about these sailors before we report back. Ideally, we would invade their camp but there are too many for our small group to take on. Lucky for us, they are focused on their salvage operation over safety. See if you can find any intelligence on their leaders who are scavenging the derelicts.",objectivesText="Acquire intelligence from the Alliance. Progress: What have you found?",rewardGold=257400,rewardXP=1415,rewardItems={159835,159836,159837},starts={{npcID=137075}},ends={{npcID=137075}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51555}},
[51248] = {id=51248,name="Productive Pests",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51248},description="This jungle is a whole new habitat for creatures and critters. A shame we're here to deal with Alliance driftwood. I've got an idea and I think it's genius. Two words: Poison bugs. First, I need some bugs. Crawling and flying ones, just to be thorough for our test.",objectivesText="Gather 5 bugs",rewardGold=257400,rewardXP=1415,starts={{npcID=135855}},ends={{npcID=135855}},mapCandidates={npc={862},zone={8499}},questType="standard"},
[51249] = {id=51249,name="Crabulous Feast",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51249},description="The Forsaken didn't bring any food with them. I think they might be cannibals. At the very least, they don't need to eat! Teekay and I are going to starve out here! <name>, if you're not too busy, could you bring us something to eat? Maybe some fresh crab?",objectivesText="Gather 7 lumps of crab meat from the Derelict Hexopods. Progress: My stomach is rumbling already.",rewardGold=257400,rewardXP=1415,rewardItems={159934},starts={{npcID=135803}},ends={{npcID=135803}},mapCandidates={npc={862},zone={8499}},questType="standard"},
[51250] = {id=51250,name="Buzz Off!",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={51250},objectivesText="Bonepicker Summit cleared",rewardGold=105000,rewardXP=925,mapCandidates={npc={},zone={8501}},questType="world",db2Objectives={{text="Bonepicker Summit cleared",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Buzz Off!",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51251] = {id=51251,name="Basement Dwellers",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51200,51203,51205,51207,51208,51209,51214,51215,51251,51335,51492,51504},description="Ever since the untimely passing of dear, sweet Lizzie, rest her soul, the pests have multiplied like crazy! In recent days, giant spiders have begun crawling out of the cellar underneath the southern mill. No one has been able to go down there, for fear of being wrapped in web and eaten alive! Would you mind squashing a few arachnids and collecting any silk you find?",objectivesText="Collect 8 Spider Silk from the Cellar Crawlers. Progress: If only Lizzie were still here...",rewardGold=514800,rewardXP=5145,rewardItems={159839},rewardCurrencies={{id=1553,amount=50}},starts={{npcID=136574}},ends={{npcID=136574}},mapCandidates={npc={942},zone={9042}},questType="standard",questLines={{id=5452,name="Milstone Hamlet",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[51252] = {id=51252,name="Kiro's Desert Flower",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8501,mapID=864,mapCandidates={npc={},zone={8501}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=137027,text="Assist Kiro"},{orderIndex=1,type=0,amount=1,objectID=137046}},worldTaskTitle="Kiro's Desert Flower",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51278] = {id=51278,name="Lost and Forgotten",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="We have seen firsthand the depravity that has taken hold of my former brethren. The time has come to put an end to it. The path ahead is no doubt packed with Lord Stormsong's cultists and their soulwrought elementals. I will absorb their souls as they fall with the Dead Ringer, as you once did. However, there will be no release for these fiends... not this time. We will need them to pry open the final door to the Shrine.",rewardGold=257400,rewardXP=4115,starts={{npcID=136933}},ends={{npcID=136933}},mapCandidates={npc={942},zone={9042}},questTurnInID=136933,questType="standard",sourceQuests={50781},questLines={{id=442,name="A House in Peril",orderIndex=37,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=37,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[51279] = {id=51279,name="Nazmani Cultists",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51177,51280,51281,51282},description="The rumors o' the blood trolls from back in Boralus don't line up with the letters from Captain Conrad. Open to trade? Willin' to work with us against the Horde? Ready to teach us their magic? Hogwash. Only time worth spendin' with these evil trolls is time killin' 'em.",objectivesText="Kill 15 Nazmani trolls in Koramar. Progress: That chantin' noise won't leave my head, draenei.",rewardGold=257400,rewardXP=4790,starts={{npcID=136675}},ends={{npcID=136675}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={51281},questLines={{id=603,name="Heart of Darkness",orderIndex=7,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=46,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=46,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=603,questLineOrder=5,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[51280] = {id=51280,name="Offerings to G'huun",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51177,51279,51281,51282},description="Been watchin' these cultists with both good eyes. Those big glowin' jars o' theirs look important. Opened one up and it sent a shiver down me spine, but nothin' seemed worth the takin'. If it ain't worth stealin', I guess it's worth smashin'.",objectivesText="Destroy 8 Offerings to G'huun in Zul'Nazman.",rewardGold=238680,rewardXP=4790,starts={{npcID=136675}},ends={{npcID=136675}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={51281},questLines={{id=603,name="Heart of Darkness",orderIndex=8,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=47,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=47,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=603,questLineOrder=5,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[51281] = {id=51281,name="Zul'Nazman",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51177,51279,51280,51282},description="Not sure if I like this Harry fella. He's growin' on me, though. Got some wild ideas about the blood elves, but he's not all bad. What were we talkin' about? Ah, right. Captain Conrad. He said the Captain went to Zul'Nazman ta commune with the blood trolls there. Seems... less than well planned. Let's go see what there is to see, shall we?",objectivesText="Meet Brann Bronzebeard at Zul'Nazman in Nazmir.",rewardGold=238680,rewardXP=4790,starts={{npcID=136432}},ends={{npcID=136675}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={51169},questLines={{id=603,name="Heart of Darkness",orderIndex=6,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=45,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=48,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=603,questLineOrder=5,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[51282] = {id=51282,name="Captain Conrad",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51177,51279,51280,51281},description="Looks like there's couple o' guards posted by this hut. If I had ta guess, Captain Conrad 'll be in there. Somethin' still feels off about this place, though. Why don't ya go on ahead and I'll hang here in case things go south fast? I got yer back, <name>.",objectivesText="Meet with Captain Conrad at Tul'vor in Nazmir.",rewardGold=238680,rewardXP=4790,starts={{npcID=136675}},ends={{npcID=136568}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={51279,51280},questLines={{id=603,name="Heart of Darkness",orderIndex=9,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=48,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=49,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=603,questLineOrder=5,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[51283] = {id=51283,name="Voyage to the West",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51170,51229},description="Reconnaissance reports that the Horde has made inroads into the desert of Vol'dun. We can't allow the Horde to continue to work there unchecked, so we're preparing an expedition to establish a beachhead. <name>, as one of our most accomplished soldiers I'd appreciate if you joined us. Your help will be essential for the success of our mission. Wrap up your affairs here in the harbor and report to Grand Admiral Jes-Tereth. We will set sail when you're ready.",objectivesText="Speak with Grand Admiral Jes-Tereth and travel to Vol'dun.",rewardGold=25740,rewardXP=600,rewardItems={159958,160044,160045},starts={{npcID=135612}},ends={{npcID=137867}},mapCandidates={npc={864,1161},zone={8568}},questType="standard",sourceQuests={51572},questLines={{id=613,name="The Sands of Vol'dun",orderIndex=0,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=22,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=25,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=613,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[51284] = {id=51284,name="Falcon Hunt",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={51284},objectivesText="Hollowbeak Falcons shot down",rewardItems={152643},mapCandidates={npc={},zone={8567}},questType="world",db2Objectives={{text="Hollowbeak Falcons shot down",amount=8,type=0,objectID=127013,orderIndex=0}},worldTaskTitle="Falcon Hunt",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
