[51286] = {id=51286,name="Stop the Evacuation",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51286},description="This is a complete disaster. The intelligence you gathered seems to indicate that they already have footholds on this island and this is just another one. They have a boat and we need to stall them. Here's some seaforium. Plant it on their boat and sabotage their hopes of escape. If possible, take out their Captain leading the evacuation.",objectivesText="Stop the Alliance evacuation efforts. Progress: I hope you have good news for me. For once.",rewardGold=257400,rewardXP=1415,starts={{npcID=137075}},ends={{npcID=137075}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51246,51247}},
[51287] = {id=51287,name="Tol Dagor: Sealed Supplies",level=50,requiredLevel=50,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=9327,mapID=895,storyline={51287},objectivesText="Sealed Kul Tiran Crate collected Overseer Korgus slain",rewardItems={159831},mapCandidates={npc={},zone={9327}},questType="standard",db2Objectives={{text="Sealed Kul Tiran Crate collected",amount=6,type=1,objectID=159831,orderIndex=0},{text="Overseer Korgus slain",amount=1,type=0,objectID=127503,orderIndex=1}},worldTaskTitle="Tol Dagor: Sealed Supplies",db2PoiMapID=1643,db2PoiUiMapID=1169,db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
