[51297] = {id=51297,name="Tol Dagor: Shorefront Property",level=50,requiredLevel=50,faction="none",sharable=false,expansion=7,zoneID=9327,mapID=895,mapCandidates={npc={},zone={9327}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=137098,text="Liskorath slain"},{orderIndex=1,type=0,amount=1,objectID=127503,text="Overseer Korgus slain"}},worldTaskTitle="Tol Dagor: Shorefront Property",db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
[51302] = {id=51302,name="The Underrot: Sealing G'huun's Corruption",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={50808,51244,51302},description="Massive leak of G'huun corruption located nearby. Substance surrounding us indicator of G'huun corruption, named underrot. Initial scans suggest a massive abomination composed of underrot is ahead, releasing more corruption into Nazmir. Must destroy Unbound Abomination , contain G'huun's corruption. Function clear. Proceed inside.",objectivesText="Enter the Underrot and defeat the Unbound Abomination .",rewardGold=1029600,rewardXP=5530,rewardItems={159827},rewardCurrencies={{id=1553,amount=600}},starts={{npcID=137112}},ends={{npcID=141539}},mapCandidates={npc={863},zone={8500}},questType="dungeon",sourceQuests={51244},questLines={{id=630,name="The Altar of Rot",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[51305] = {id=51305,name="Jelly Clouds",level=26,requiredLevel=26,faction="none",sharable=false,expansion=7,zoneID=8499,mapID=862,mapCandidates={npc={},zone={8499}},questType="world"},
[51308] = {id=51308,name="Zuldazar Foothold",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51201},description="King Wrynn passed along orders to dispatch our finest to establish a foothold in Zandalar. That means you. Fortunately, we have a few choices as to where we can set up camp. Stick around. I'll go over the battle plan.",objectivesText="Listen to Commander Wyrmbane's battle plan, then speak with Grand Admiral Jes-Tereth to travel to Talanji's Rebuke in Zuldazar.",rewardGold=257400,rewardXP=4790,rewardItems={159779,159910,160249,160433},starts={{npcID=135612}},ends={{npcID=136197},{npcID=137401}},mapCandidates={npc={862,1161},zone={8568}},questType="standard",sourceQuests={51570},questLines={{id=621,name="Mole Machinations",orderIndex=0,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=9,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=14,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=621,questLineOrder=4,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[51309] = {id=51309,name="Rocks of Ragnaros",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="With me shaman still in their conveyances, a vital component o' our upcomin' ritual remains scattered among the supplies. I can only hope the Horde haven't taken 'em. They're rare an' precious... If you see any glowin' objects out there, recover 'em. They're o' tremendous value.",objectivesText="Recover 9 Firelands Slag from the beach in Xibala. Progress: I wasn't worried about 'em bein' broken. A little fire'd never hurt those rocks.",rewardGold=257400,rewardXP=4790,rewardItems={159779,159910,160249,160433},starts={{npcID=137401}},ends={{npcID=137401}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51418},questLines={{id=621,name="Mole Machinations",orderIndex=9,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=17,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=15,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=621,questLineOrder=4,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[51310] = {id=51310,name="Raiders of the Lost Crop",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51310},description="I could use a hand here! So there I was, mindin' my own business and collectin' my harvest when these big galoots show up on their wolves and start torching the town! Luckily I was delivering a sack o' grain, or they'd have caught me and run me down! I won't stand for having these orcs or their dogs chewing up my fields or my crop. What do you say, friend? Help a farmer run some looters off his land?",objectivesText="Slay 6 Orc Raiders .",rewardGold=257400,rewardXP=4115,starts={{npcID=137094}},ends={{npcID=137094}},mapCandidates={npc={942},zone={9042}},questType="standard"},
[51311] = {id=51311,name="Energizing Extract",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={51311},rewardItems={152849},mapCandidates={npc={},zone={8567}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=8,objectID=152849}},worldTaskTitle="Energizing Extract",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51312] = {id=51312,name="Aromatic Pollenator",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"herbalism"},categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={48755,48758,51312,51313},series={51313},description="While gathering the pollen, you found a dead bug absolutely covered in pollen. You know that this little creature is the secret to harvesting pollen easier, but the answer seems just out grasp. Maybe if you ask Declan about it, he might have an idea.",objectivesText="Bring the Dead Pollen-Covered Bee to Declan Senal . Provided item:",rewardItems={152505,152506,152507,152508,152509,152510,152511,159877,159956,160035,160064,160117},ends={{npcID=136096}},mapCandidates={npc={1161},zone={8568}},questType="standard",questLines={{id=754,name="8.0 Professions - Gathering - Herbalism - Kul Tiras - Siren's Pollen - SCS",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895,startItems={159877}},
[51313] = {id=51313,name="Learn From the Best",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"herbalism"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=895,storyline={48755,48758,51312,51313},series={51312},description="You want to learn how these bees are so good at harvesting pollen, but if you show up, they'll start swarming you. What you've got is a problem that can be solved with a little alchemy. I just so happen to have this potion that, once drunk, will turn the imbiber into a plant. Here's the deal: you go out and drink the potion, and you'll see firsthand how the bees do what they do. After the potion wears off, you tell me what happened. Oh, and don't ask why I have that potion on me.",objectivesText="Drink Declan's potion and allow bees to harvest your pollen.",rewardItems={152505,152506,152507,152508,152509,152510,152511,159877,159881,159956,160035,160064,160117},starts={{npcID=136096}},ends={{npcID=136096}},mapCandidates={npc={},zone={8568}},questGiverID=136096,questTurnInID=136096,questType="standard",sourceQuests={51312},questLines={{id=754,name="8.0 Professions - Gathering - Herbalism - Kul Tiras - Siren's Pollen - SCS",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[51314] = {id=51314,name="Grain Drain",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51314},description="We've got to salvage what we can. This valley is the breadbasket of Kul Tiras. We feed the citizens, the militia, the army, you name it! Perhaps you've heard of our famous Kul Tiran sourdough bread? Goes great with sausages. More importantly, those blasted Horde are getting in the way of our harvest! Lucky for us, the golems work 'round the clock to package the grain. I just need you to go out to the fields and grab as many bags as you can carry. I'll pay you for your trouble, of course.",objectivesText="Collect 8 Sacks of Grain . Progress: We need that grain!",rewardGold=257400,rewardXP=4115,rewardItems={155878},rewardCurrencies={{id=1560,amount=50}},starts={{npcID=137094}},ends={{npcID=137094}},mapCandidates={npc={942},zone={9042}},questType="standard"},
[51315] = {id=51315,name="Wild Flutterbies",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={51315},objectivesText="Vale Flutterby collected",rewardItems={162585},mapCandidates={npc={},zone={8501}},questType="world",db2Objectives={{text="Vale Flutterby collected",amount=10,type=0,objectID=150279,orderIndex=0}},worldTaskTitle="Wild Flutterbies",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51316] = {id=51316,name="Walking in a Spiderweb",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8501,mapID=864,mapCandidates={npc={},zone={8501}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=5,objectID=137172,text="Tortaka freed"},{orderIndex=1,type=0,amount=5,objectID=123813},{orderIndex=2,type=0,amount=30,objectID=123826}},worldTaskTitle="Walking in a Spiderweb",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51317] = {id=51317,name="Grounding the Grimestone",expansion=7,mapID=895,questType="world",db2Objectives={{orderIndex=0,type=0,amount=12,objectID=136765,text="Grimstone troggs slain"}},worldTaskTitle="Grounding the Grimestone",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51318] = {id=51318,name="Go for the Boat",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={51318},objectivesText="Sailboat Dummy sunk",rewardGold=169800,rewardXP=525,rewardItems={55121,63550,63551,63552,63553,63554,63555,63556,63557,63558,63559,63560,63561,63562,63563,63564,63565,131430,131431,131434,131435,138414,200878},mapCandidates={npc={},zone={8568}},questType="world",db2Objectives={{text="Sailboat Dummy sunk",amount=8,type=0,objectID=137159,orderIndex=0}},worldTaskTitle="Go for the Boat",db2PoiMapID=1643,db2PoiUiMapID=1161,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51319] = {id=51319,name="The Final Ascent",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="Beyond this gate lies Lord Stormsong... and our retribution. It seems he has sealed it tight, likely to buy himself time to finish whatever foul ritual awaits us. Release the souls within the Dead Ringer when you are ready. I will direct them into the binding holding the gate shut. From there, we find Stormsong and end this once and for all.",rewardGold=128700,rewardXP=2060,starts={{npcID=137506}},ends={{npcID=137506}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51278,51320},questLines={{id=442,name="A House in Peril",orderIndex=39,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=39,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[51320] = {id=51320,name="Sealed Fate",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="Three wards ahead threaten to block our entry into the Shrine. We call them the Tidemother's Wrath , Radiance, and Pride. Legends say the wards were gifts from the sea itself. They once protected our flagships against even the fiercest storms. Ever since we settled here they have instead kept the Shrine of the Storm safe. It seems Lord Stormsong has turned their power against us. I can feel their energy radiating out even from here, protecting his forces from our magic. We must destroy them.",rewardGold=309800,rewardXP=4115,rewardCurrencies={{id=1553,amount=75}},starts={{npcID=136933}},ends={{npcID=136933}},mapCandidates={npc={942},zone={9042}},questTurnInID=136933,questType="standard",sourceQuests={50781},questLines={{id=442,name="A House in Peril",orderIndex=38,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=38,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[51322] = {id=51322,name="Wings and Stingers",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={51322},rewardItems={159924,159925},mapCandidates={npc={},zone={8501}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=3,objectID=159925},{orderIndex=1,type=1,amount=5,objectID=159924}},worldTaskTitle="Wings and Stingers",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51330] = {id=51330,name="Resilient Seeds",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={51330},objectivesText="Resilient Seeds collected",rewardItems={159909},mapCandidates={npc={},zone={8501}},questType="world",db2Objectives={{text="Resilient Seeds collected",amount=8,type=1,objectID=159909,orderIndex=0}},worldTaskTitle="Resilient Seeds",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51331] = {id=51331,name="Mole Machinations",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51359},description="Seems the enemy's anticipated our moves. While we developed our refinin' techniques for Azerite, the goblins 'ave done the same. It wasn't five minutes after we established ourselves here that the Horde arrived to disrupt our progress. We've got several shaman of great import waitin' impatiently in the mole machines on that beach. You can take the key and clear the way so they arrive safely.",objectivesText="Free 4 Dark Iron Earthbreakers from mole machines in Xibala. Progress: Ain't my fault those lads seem to hate small spaces.",rewardGold=257400,rewardXP=4790,rewardItems={159779,159910,160249,160433},starts={{npcID=137401}},ends={{npcID=137401}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51418},questLines={{id=621,name="Mole Machinations",orderIndex=8,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=18,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=16,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=621,questLineOrder=4,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[51332] = {id=51332,name="A Trip Across the Ocean",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51224,51231,51233,51234,51332,51340,51985,51987},series={51224,51340},description="I understand you are to be establishing our foothold in Drustvar. You will be assisted on this mission by Trade Prince Gallywix . I know, a strange choice, but I am told that there is Azerite in Drustvar, and the Trade Prince was insistent.",objectivesText="Report to Trade Prince Gallywix in Zuldazar.",rewardGold=257400,rewardXP=4790,starts={{npcID=135691}},ends={{npcID=136683}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51801},questLines={{id=604,name="Drustvar Foothold",orderIndex=0,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=20,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=604,questLineOrder=5,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[51333] = {id=51333,name="Anchors Aweigh!",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={51333},objectivesText="Speak with Commander Norwood",rewardGold=280900,rewardXP=4115,rewardItems={158682,158684,159926,160332},mapCandidates={npc={},zone={8568}},questType="world",db2Objectives={{text="Speak with Commander Norwood",amount=1,type=3,objectID=137186,orderIndex=0}},worldTaskTitle="Anchors Aweigh!",db2PoiMapID=1643,db2PoiUiMapID=1161,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51335] = {id=51335,name="Cookies and Cream",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="Thank you for helping me collect everything. I couldn't let you go out there and battle those mean ettins on an empty stomach. Now, I would be no better than those terrible monsters if I did that, would I? $p, you just feel free to take a load off while I make you a fresh batch of cookies and some warm milk!",rewardGold=257400,rewardXP=4115,starts={{npcID=136658}},ends={{npcID=136658}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51215},questLines={{id=5452,name="Milstone Hamlet",orderIndex=5,flags=0}}},
[51339] = {id=51339,name="Cleaning Bills",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51339},description="The Venture Company contaminates our pristine waters with toxic oil. My people are strong and will endure this until the time is right to strike back. The creatures with soft skins cannot wait. We must act now and save them from this danger. Collect and scrub clean any oily sandbill pipers you see. Quickly, before it's too late!",objectivesText="Clean 8 Oily Sandbill Pipers",rewardGold=257400,rewardXP=4115,rewardItems={63688,155237,160384,160387,160390,160393},rewardChoices={155237,160384,160387,160390,160393},starts={{npcID=135794}},ends={{npcID=135794}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49832}},
[51340] = {id=51340,name="Drustvar Ho!",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=862,storyline={51224,51231,51233,51234,51332,51340,51985,51987},series={51224,51332},description="Azerite's in the air, <name>. Can ya smell it? Drustvar--way over in Kul Tiras--apparently has a real big seam o' Azerite beneath it. Azerite means profit, and profit means winning this war against the Alliance... which means even more profit. We gotta get that Azerite! Check in with Eitrigg an' Tattersail so we can get going soon. Time is money!",objectivesText="Speak with Eitrigg and Dread-Admiral Tattersail.",rewardGold=280900,rewardXP=4790,rewardItems={33226},starts={{npcID=136683}},ends={{npcID=136725}},mapCandidates={npc={862,896},zone={8721}},questType="standard",sourceQuests={51332},questLines={{id=604,name="Drustvar Foothold",orderIndex=1,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=21,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=604,questLineOrder=5,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=896},
[51341] = {id=51341,name="Daughter of the Sea",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=1161,storyline={46727,46728,46729,47098,47099,47186,47189,51341},series={46727,46728,46729,47098,47099,57766,58983,59641,60362},description="They're not letting us any closer to the keep. We'll have to walk from here. Returning to Boralus has stirred feelings I thought I'd left behind. Memories smoothed away by the years like stones in the tide. It all feels raw again. I do not know how this will end--only that we must try.",objectivesText="Accompany Jaina Proudmoore to an audience with Katherine Proudmoore.",rewardGold=193050,rewardXP=1060,rewardItems={158075,160326},starts={{npcID=120922}},ends={{npcID=121239}},mapCandidates={npc={895,1161},zone={8568}},questType="standard",sourceQuests={46728},questLines={{id=589,name="A Nation Divided",orderIndex=2,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=2,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=589,questLineOrder=2,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=1169},
[51342] = {id=51342,name="Battle for Stromgarde",level=50,requiredLevel=50,faction="none",categories={},flags={},sharable=false,expansion=7,storyline={51342},rewardGold=468000,rewardXP=8520,rewardItems={163578,163579,163644,163645,163646,163648,163650,163652,163677,163684,163689,163690,163691,163698,163700,163701,163706,163711,163712,163713,163735,163736,163738,163741,163744,163745,163750,163775,163828,163829,164577,164578,169196,169197},mapCandidates={npc={},zone={}},questType="standard"},
[51343] = {id=51343,name="Swimming Lessons",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51343},description="For millennia we have roamed Azeroth's depths, yet never has a land walker journeyed with us. In order to help us, you must learn to travel the waters as we do. The three scrolls of the sea shall grant you the energies to travel and survive underwater as we do. Bring me the Scrolls of Harmonious Fins, Endless Tides and Graceful Breaths.",objectivesText="Collect the three scrolls. Progress: You must collect the Scroll of Harmonious Fins , Endless Tides and Graceful Breaths.",rewardGold=257400,rewardXP=4115,rewardItems={160270,160327,160329},starts={{npcID=135794}},ends={{npcID=135794}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49832,50797}},
[51344] = {id=51344,name="To Matters at Hand",level=10,requiredLevel=10,faction="horde",categories={"legendary"},flags={},sharable=true,expansion=7,zoneID=9598,mapID=1165,storyline={51344},description="Ye need te get back te Zuldazar, Princess Talanji 's people are in desperate need of help. Now that ye got the heart, ye can absorb Azerite from all kinds of sources. Use the teleporter pad behind ye te return te Zuldazar. I be disablin' it when yer done... no need te have the likes of Nathanos walkin' in here. Just remember. Ye got the Heart of Azeroth around yer neck. Whatever happens... we must save the planet.",objectivesText="Use the Teleport Pad to return to Zuldazar",rewardGold=23870,rewardXP=175,rewardItems={159671},starts={{npcID=136907}},ends={{npcID=133050}},mapCandidates={npc={84,1165},zone={9598}},questType="standard"},
[51349] = {id=51349,name="Honor Bound",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51350,51351,51366},description="Sergeant Ermey is a man of honor, he would never leave one of his men behind. But one of these days that sentiment is going to get himself killed. We don't even know what threats we face in this land. We certainly don't have the resources to spend searching for a missing private. I want you to go after him. Do whatever it takes to give up this fool's errand and return to the camp. He was last seen headed to the south-east, I'd start your search there.",objectivesText="Find Sergeant Ermey in Vol'dun.",rewardGold=257400,rewardXP=4790,rewardItems={159958,160044,160045},starts={{npcID=137213}},ends={{npcID=137337}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51229},questLines={{id=613,name="The Sands of Vol'dun",orderIndex=3,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=26,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=26,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=613,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[51350] = {id=51350,name="Unexpected Aid",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51349,51351,51366},description="I was shadowing those sethrak when I saw this one left for dead beside the trail. I don't think he's like the others. Looks like they roughed him up pretty bad. I made contact and before he passed out he said he knew where our man was being taken! We need to find out what this thing knows! I'll need to make a salve for these wounds. There's some cactus I saw growing around here that should make a good base for it.",objectivesText="Harvest 8 Prickly Pear Roots in Bonetrail Gulch. Progress: Got the cactus for the salve?",rewardGold=257400,rewardXP=4790,rewardItems={159958,160044,160045},starts={{npcID=137337}},ends={{npcID=137337}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51349},questLines={{id=613,name="The Sands of Vol'dun",orderIndex=4,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=27,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=27,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=613,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[51351] = {id=51351,name="Poisoned Barbs",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51349,51350,51366},description="I'm surprised this snake-man is alive, let alone able to speak. Look at this! <Ermey holds up a needle-like barb.> It looks like it came from one of those giant insects wandering about in the bottom of the gulch. I'll bet my stripes it's poisoned. You know what they say, that which kills can also cure. Go get a few more of these barbs. I bet if I mix it in with that cactus he's wanting we will get a good antivenom to treat his wounds.",objectivesText="Collect 8 Saltspine Barbs in Bonetrail Gulch. Progress: Got those barbs for me?",rewardGold=257400,rewardXP=4790,rewardItems={159958,160044,160045},starts={{npcID=137337}},ends={{npcID=137337}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51349},questLines={{id=613,name="The Sands of Vol'dun",orderIndex=5,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=28,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=28,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=613,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[51352] = {id=51352,name="Don't Play with Matches",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51352},description="These Venture Co. thugs set flame to the very oils they harvest. They hope to drive us from this land. Their plan has a flaw. If a great wave extinguished every torch, their oil could not be lit. You can be our great wave! Extinguish all the flames here, and we shall be victorious this day.",objectivesText="Eliminate 10 Venture Co. Flame Starters and 2 Venture Co. Oilers . Progress: Get to work, the battle is not won yet!",rewardGold=257400,rewardXP=4115,starts={{npcID=135795},{npcID=137554},{npcID=137677}},ends={{npcID=135795},{npcID=137554},{npcID=137677}},mapCandidates={npc={942},zone={9042}},questType="standard"},
[51353] = {id=51353,name="Cave of Ai'twen",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51353},description="Toki has researched a strategy that is historically sound. However to defeat the Venture Company, we will have to awaken Ai'twen from the bubble of tranquil waters. Seek out Loroja in the Cave of Ai'twen and we shall begin the process.",objectivesText="Seek out Loroja in the Cave of Ai'twen.",rewardGold=25740,rewardXP=515,starts={{npcID=135794}},ends={{npcID=137453}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51339,51343}},
[51354] = {id=51354,name="Anger in a Bottle",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={50353,50354,50363,50365,50368,50622,50640,51354},description="These quilboar are tougher than normal and I think I found out why. They carry vials of some sort, filled with this nasty orange liquid. They'll quaff it and gain tremendous strength and stamina. I'll bet if we get some of it Hobbs could whip up a counter-agent, or whatever it is that alchemists do. Either way, deprive them of their strength potions and it'll make getting around here easier!",objectivesText="Collect 10 Foul-Smelling Samples . Progress: Do you have the samples yet?",rewardGold=257400,rewardXP=4115,rewardItems={157850},starts={{npcID=133953}},ends={{npcID=133953}},mapCandidates={npc={942},zone={9562}},questType="standard",questLines={{id=583,name="Storming the Kraul",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[51355] = {id=51355,name="Secretest Fish",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={51355},description="< Danielle Anglers in Mechagon may be interested in this fish.>",objectivesText="Take the fish to Danielle Anglers in Mechagon . Provided item:",rewardGold=772200,rewardXP=10225,rewardItems={133755,158932,161475,167698,167713,167726,167727,173032,177025,177027,177256,181623},ends={{npcID=151462}},coords={mapID=1462,source="quest_giver",x=0.37,y=0.472},mapCandidates={npc={1462},zone={10290}},questType="standard",startItems={158932}},
[51356] = {id=51356,name="WANTED: Sister Lilias",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={51356},description="The Waycrest Guard seeks an able-bodied soldier to eliminate a threat in Corlain. A witch by the name of Sister Lilias is wanted for the torture and killing of many of our townsfolk. Her end would prove a boon to all of Drustvar . Present her head to claim your reward.",objectivesText="Collect Sister Lilias' head from Sister Lilias in Corlain. Progress: Inquisitor?",rewardGold=772200,rewardXP=4150,rewardItems={156926,160026},rewardCurrencies={{id=1553,amount=115}},ends={{npcID=137368}},startObjects={{objectID=288622,mapID=896,x=0.317,y=0.307}},coords={mapID=896,source="quest_giver",x=0.315,y=0.3},mapCandidates={npc={896},zone={8721}},questType="group",sourceQuests={50253}},
[51357] = {id=51357,name="Armed and Ready",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="You must be special if the sethrak didn't kill you right away. Either that, or you'd fetch a good price at the slave market. Don't worry though. We're getting out of here. I have a wagon at the entrance, but no weapon to fight with. Luckily, it seems the sethrak have plenty.",objectivesText="Choose a weapon for Nisha . Progress: I'm good with whatever you pick, but let's hurry.",rewardGold=257400,rewardXP=4115,starts={{npcID=130455}},ends={{npcID=130455}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47315},questLines={{id=605,name="Unlikely Allies",orderIndex=3,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=4,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[51358] = {id=51358,name="WANTED: Gryphon 'Nappers",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={51358},description="A warning to all gryphon owners! Do not let your feathered companions out of your sight. We have received numerous reports about gryphons in the area being stolen in the night. If anybody can track down and stop these thieves, a reward awaits!",objectivesText="Kill Lindel the Snatcher and Silent Boris .",rewardGold=772200,rewardXP=2125,rewardItems={160452},rewardCurrencies={{id=1553,amount=115}},ends={{npcID=133214}},startObjects={{objectID=288641,mapID=895,x=0.668,y=0.243}},coords={mapID=895,source="quest_giver",x=0.662,y=0.242},mapCandidates={npc={895},zone={8567}},questType="group"},
[51359] = {id=51359,name="Fragment of the Firelands",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51331},description="The rumors o' yer capabilities seemed overblown, but it appears yer indeed a competent one, aren't ye? I underestimated ye, <name>. For that, I apologize. Don't tell Thaelin. The components for the ritual are now prepared. All ye need to do is add the Firelands Slag to the Unstable Magma an' a great bein' from the Firelands will heed our call. You'll gain control o' it and can eliminate the nearby goblin threat with nigh invincibility.",objectivesText="Stabilize the Unstable Magma then use the Magma Elemental to defeat 200 Bilgewater Goblins . Progress: Me shaman are gettin' better at this, aye? First couple o' summons and we had a hot fight on our hands.",rewardGold=257400,rewardXP=4790,rewardItems={159779,159910,160058,160249,160433},starts={{npcID=137401}},ends={{npcID=137401}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51309,51331},questLines={{id=621,name="Mole Machinations",orderIndex=10,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=19,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=17,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=621,questLineOrder=4,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[51360] = {id=51360,name="Enormous Anchor Pod",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"herbalism"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={51016,51360,51361},series={51361},description="In all the gathering you've done, you have never come across an anchor pod of this size. Whatever the reason that it has gotten so large, there is much that can be learned from it. Your mind wanders back to Declan, and if there is anything about it in the book you picked up earlier.",objectivesText="Bring the Enormous Anchor Pod to Declan Senal . Provided item:",rewardItems={152505,152506,152507,152508,152509,152510,152511,159877,159956,160035,160064,160117},ends={{npcID=136096}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={51016},questLines={{id=750,name="8.0 Professions - Gathering - Herbalism - Kul Tiras - Anchor Weed  - SCS",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895,startItems={160035}},
[51361] = {id=51361,name="More Anchor Pods",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"herbalism"},categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=895,storyline={51016,51360,51361},series={51360},description="Everyone in Kul Tiras knows that anchor weed is a blight that was brought here by merchants. It thrives in this weather and it leechs nutrients from other plants, so we work to keep it from spreading, but it also has a strong magical essence, keeping us from just eradicating it. However, if it has mutated so it can disperse more seeds, we may need to finally purge it. Bring me the biggest seed pods you can find, we need to see if this is a unique case. I'll dissect this one and learn what I can.",objectivesText="Harvest 9 Mature Anchor Pods from anchor weed. Progress: If the anchor weed is mutating, we may need to purge it from this land. Do you have the other seed pods for comparison?",rewardItems={152505,152506,152507,152508,152509,152510,152511,159877,159956,160035,160036,160064,160117},starts={{npcID=136096}},ends={{npcID=136096}},mapCandidates={npc={},zone={8568}},questGiverID=136096,questTurnInID=136096,questType="standard",sourceQuests={51360},questLines={{id=750,name="8.0 Professions - Gathering - Herbalism - Kul Tiras - Anchor Weed  - SCS",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[51364] = {id=51364,name="An Explosive Exit",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="Alright, $p. I think it's time we make a run for it. Hopefully my wagon's still nearby. I'll steer us to our hideaway. I just need you to lob explosives onto any sethrak who are brave enough to follow us.",objectivesText="Find Nisha's wagon and ride it to safety.",rewardGold=245700,rewardXP=4115,rewardItems={155443,161188,161189,161190,161191,161192,161193,161194,161195},rewardChoices={161188,155443,161189,161190,161191,161192,161193,161194,161195},starts={{npcID=130474}},ends={{npcID=123586}},mapCandidates={npc={864},zone={8501}},questGiverID=130474,questType="standard",sourceQuests={47327,49677},questLines={{id=605,name="Unlikely Allies",orderIndex=7,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=8,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[51365] = {id=51365,name="Cultural Significance",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"herbalism"},categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=895,storyline={48769,51365},description="I've noticed your skill with harvesting plants has improved, but I also noticed that you just treat each flower and leaf as a commodity. The flora of these islands have a rich history, with a deep cultural significance to us. Take this sea stalk, go around town, and ask some of the men and women what it means to them. Humor me, and I'll make it worth your while.",objectivesText="Learn the importance of sea stalks from people in Boralus.",rewardItems={152505,152506,152507,152508,152509,152510,152511,159877,159956,160035,160064,160117},starts={{npcID=136096}},ends={{npcID=136096}},mapCandidates={npc={},zone={8568}},questGiverID=136096,questTurnInID=136096,questType="standard",questLines={{id=753,name="8.0 Professions - Gathering - Herbalism - Kul Tiras - Sea Stalk - SCS",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[51366] = {id=51366,name="Antidote Application",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51349,51350,51351},description="The antidote's ready. It smells like death and tastes worse, but it should be potent enough. Let's hope that we're not too late for it to do any good. Here, administer the salve to his wounds. It should work nearly instantly.",objectivesText="Administer the Antivenom to Vorrik .",rewardGold=257400,rewardXP=4790,rewardItems={159958,160044,160045},starts={{npcID=137337}},ends={{npcID=137434}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51350,51351},questLines={{id=613,name="The Sands of Vol'dun",orderIndex=6,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=29,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=29,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=613,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[51367] = {id=51367,name="WANTED: Raging Earthguard",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={51367},description="Be careful when traveling toward Anglepoint! An immense creature of the earth has spawned on one of the hills, threatening all who go near. Any adventurers who take down this earthen guardian shall be rewarded greatly.",objectivesText="Kill the Raging Earthguard west of Norwington Estate.",rewardGold=772200,rewardXP=2125,rewardItems={160452},rewardCurrencies={{id=1553,amount=115}},ends={{npcID=124802}},startObjects={{objectID=289310,mapID=895,x=0.53,y=0.283}},coords={mapID=895,source="quest_giver",x=0.515,y=0.272},mapCandidates={npc={895},zone={8567}},questType="group"},
[51368] = {id=51368,name="WANTED: The Hornet",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={51368},description="That's it, I'm putting a bounty on that blasted hornet. Every time I try to do some good old fashioned bare-handed fishing, that son of a bear comes after me. Somebody take that bug down!",objectivesText="Kill The Hornet .",rewardGold=772200,rewardXP=2125,rewardItems={160452},rewardCurrencies={{id=1553,amount=115}},ends={{npcID=129003}},startObjects={{objectID=289313,mapID=895,x=0.422,y=0.229}},coords={mapID=895,source="quest_giver",x=0.424,y=0.222},mapCandidates={npc={895},zone={8567}},questType="group"},
[51369] = {id=51369,name="Friends in Strange Places",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="I saw a creature like your friend here. We both were being held captive by my ruthless kin, the Faithless. Before I was cast aside I gave him something to protect, something most precious. Naturally, I would also like to see your friend's safe return. My people will lend you their aid. Come, I will call for my pterrordax to take us. Together we shall find where your soldier friend was taken.",objectivesText="Fly to the Sanctuary of the Devoted.",rewardGold=128700,rewardXP=2395,rewardItems={159958,160044,160045},starts={{npcID=137434}},ends={{npcID=137537}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51366},questLines={{id=613,name="The Sands of Vol'dun",orderIndex=7,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=30,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=30,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=613,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[51370] = {id=51370,name="Short-Supply Reward",level=50,requiredLevel=50,faction="none",categories={},flags={},sharable=false,expansion=7,storyline={51370},rewardItems={69903,90818,103533,120334,128803,140591,141701,160054,184522,201326,224573,259086},rewardCurrencies={{id=1553,amount=100}},mapCandidates={npc={},zone={}},questType="standard"},
[51371] = {id=51371,name="Flavorable Offering",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51371},description="Ai'twen saved many Tortollans during the great purge of the Inky Grotto. He rests here in this tranquil bubble as a reward for his service. To entice him back to our world we'll need a flavorful offering. The seaweed that grows outside is Ai'twen's favorite meal. Its salty flavor will surely coax Ai'twen to leave the bubble for our world. Gather it from the creatures outside this cave, and where it grows wild on the reef.",objectivesText="Gather 50 Seaweed . Progress: Search for the Seaweed outside and on Makrura Brineshells",rewardGold=257400,rewardXP=4115,rewardItems={160055},starts={{npcID=137453}},ends={{npcID=137453}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51353}},
[51373] = {id=51373,name="Ears Everywhere",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=8499,mapID=862,mapCandidates={npc={},zone={8499}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=12,objectID=137489}},worldTaskTitle="Ears Everywhere",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51374] = {id=51374,name="Unending Gorilla Warfare",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=8499,mapID=862,mapCandidates={npc={},zone={8499}},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Disrupt Da'kani Gorillas"},{orderIndex=1,type=0,amount=17,objectID=130953,text="Da'kani Gorillas slain"},{orderIndex=2,type=0,amount=17,objectID=130954,text="Da'kani Gorillas slain"},{orderIndex=3,type=0,amount=13,objectID=130948,text="King Da'ka slain"},{orderIndex=4,type=0,amount=9,objectID=131476,text="Zayoos slain"},{orderIndex=5,type=0,amount=13,objectID=133404,text="Gorilla Totems destroyed"}},worldTaskTitle="Unending Gorilla Warfare",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51376] = {id=51376,name="Can't Teach on an Empty Stomach",level=10,requiredLevel=10,faction="both",requiredProfessions={"herbalism"},categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={48762,48763,51376},series={48762,51446},description="I would love to teach you, but it's so hard for me to concentrate right now. I haven't eaten anything all day, so it's all I can think about. However, if a helpful adventurer were to fish up some lane snapper from the ocean just behind me, I would owe them a something in return. Perhaps something valuable, such as advice in regards to effectively picking the notorious winter's kiss. If you don't feel like fishing, you could just buy some on the auction house, I don't mind.",objectivesText="Collect 7 Lane Snapper for Xun Xun Sweetflower . Lane Snapper can be fished from the ocean or purchased from the Auction House. Progress: Oh, do you have something for me?",rewardItems={6256,152505,152506,152507,152508,152509,152510,152511,152545,152546,154770,154788,154792,154796,154801,156833,159877,159956,160035,160064,160117,160301,160550,160930,168016},starts={{npcID=136141},{npcID=136269}},ends={{npcID=136141},{npcID=136269}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48762,51446},questLines={{id=756,name="8.0 Professions - Gathering - Herbalism - Kul Tiras - Winter's Kiss - SCS",orderIndex=1,flags=0},{id=761,name="8.0 Professions - Gathering - Herbalism - Zandalar - Winter's Kiss - SCS",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
