[51379] = {id=51379,name="Temple of Sethraliss: Navigating Currents",level=50,requiredLevel=50,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=9527,mapID=864,storyline={51379},objectivesText="Wrest a Focus From a Faithless Sorcerer Gain 100 power from Flowing Current Restore the Avatar of Sethraliss",rewardItems={163681},mapCandidates={npc={},zone={9527}},questType="standard",db2Objectives={{text="Wrest a Focus From a Faithless Sorcerer",amount=1,type=1,objectID=163681,orderIndex=0},{text="Gain 100 power from Flowing Current",amount=1,type=0,objectID=137515,orderIndex=1},{text="Restore the Avatar of Sethraliss",amount=1,type=14,objectID=66102,orderIndex=2}},worldTaskTitle="Temple of Sethraliss: Navigating Currents",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
[51380] = {id=51380,name="Back to Franklin",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={48770,51380,51889},description="Oh, good! You are still here! I heard you had built a rapport with Franklin. I'd be lying if I said talking about him didn't make me reminisce when we worked together. If you're not busy, could you go talk to him? Ask him if he can show you anything else. I'm sure he remembers more, if you're still looking for more information. And tell him that if he were to get his life sorted out, I'd like to talk to him about working together again.",objectivesText="Speak with Franklin The Drunk .",rewardItems={152512,152513,152579,160905,161078,161085},starts={{npcID=136091}},ends={{npcID=136091}},mapCandidates={npc={},zone={8568}},questGiverID=136091,questTurnInID=136091,questType="standard",sourceQuests={48770},questLines={{id=771,name="8.0 Professions - Gathering - Mining - Kul Tiras - Storm Silver Seam - SCS",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[51384] = {id=51384,name="WANTED: Quartermaster Ssylis",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={51384},description="Don't venture too far into the bay if you're not looking for a fight! A couple of Bilge Rats have taken up residence in a nearby cave, and they won't stand down from any challenge. They ain't harming anybody, 'long as you stay away. But if somebody wants to go take care of their leader, they will be rewarded.",objectivesText="Kill Quartermaster Ssylis in Krakenbane Cove. Progress: <Alby nods at you.>",rewardGold=772200,rewardXP=2125,rewardCurrencies={{id=1553,amount=115}},ends={{npcID=126308}},startObjects={{objectID=289361,mapID=895,x=0.422,y=0.272}},coords={mapID=895,source="quest_giver",x=0.3915,y=0.267},mapCandidates={npc={895},zone={8567}},questType="group"},
[51385] = {id=51385,name="A Supply of Stingers",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={51385},rewardItems={153486},mapCandidates={npc={},zone={8567}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=6,objectID=153486}},worldTaskTitle="A Supply of Stingers",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51386] = {id=51386,name="Battle Victorious",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51386},description="We have everything necessary to strike a blow against this Venture Company. Our plan is sound, we are well prepared and we have the element of surprise. We shall ride atop Ai'twen and reign chaos upon them with their very own weapons.",objectivesText="Ride Ai'twen and destroy the Venture Companies forces Progress: The Venture Companies defeat is at hand. Let's get to it!",rewardGold=772200,rewardXP=6175,rewardItems={160335,160338,160341,160344,160373,160376,160379,160382},rewardChoices={160335,160338,160341,160344,160373,160376,160379,160382},starts={{npcID=137554}},ends={{npcID=135795}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51220,51222}},
[51388] = {id=51388,name="Stopping the Infestation",expansion=7,mapID=895,questType="world",db2Objectives={{orderIndex=0,type=2,amount=5,objectID=289363,text="Infested Cargo burned"}},worldTaskTitle="Stopping the Infestation",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51389] = {id=51389,name="Breaking Free",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="Look, these guys are in a tough spot but let's not lose track of the mission. We've got to rescue Private James ! I saw a bunch of cages down in the camp of those snakes that are besieging the temple. If James is going to be anywhere, then it'll be there!",objectivesText="Find Private James and free him from his captors.",rewardGold=271500,rewardXP=4790,rewardItems={159958,160044,160045},starts={{npcID=137543}},ends={{npcID=137559}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51369},questLines={{id=613,name="The Sands of Vol'dun",orderIndex=8,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=31,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=31,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=613,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[51390] = {id=51390,name="WANTED: The Crimson Cutthroats",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={51390},description="For numerous and sinister crimes against the Lord Admiral: smuggling, forgery, sailing under false colors, looting, poaching, brigandage, sacking, pillaging, vandalism, impersonating Kul Tiran Naval officers, arson, kidnapping, torture, piracy, perjury, theft and ransacking multiple mead shipments. A reward is placed on the heads of The Crimson Cutthroats to be paid in full upon proof of their demise.",objectivesText="Slay the Crimson Cutthroats near Falconhurst. Progress: The Crimson Cutthroats are a nasty bunch. I wouldn't be sad to see them go.",rewardGold=772200,rewardXP=4150,rewardCurrencies={{id=1553,amount=115}},ends={{npcID=131442}},startObjects={{objectID=289365,mapID=896,x=0.264,y=0.722}},coords={mapID=896,source="quest_giver",x=0.258667,y=0.707333},mapCandidates={npc={896},zone={8721}},questType="group",sourceQuests={49939}},
[51391] = {id=51391,name="Defang the Faithless",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="Did you see them as we flew in? The Faithless are sieging the temple! Friend, I know we just met but I must ask for your aid once more. Please, help us break their ranks!",objectivesText="Kill 12 Faithless attackers within the Temple Grounds.",rewardGold=257400,rewardXP=4790,rewardItems={159958,160044,160045},starts={{npcID=137537}},ends={{npcID=129519}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51369},questLines={{id=613,name="The Sands of Vol'dun",orderIndex=9,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=32,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=32,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=613,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[51394] = {id=51394,name="Break the Siege",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="This isn't the first time the Faithless have attacked us, nor will it be the last, but the temple must be protected! Please, do whatever you can to destroy their siege equipment and push them back.",objectivesText="Disrupt the Faithless assault on the Sanctuary of the Devoted. Progress: We will not let them win!",rewardGold=257400,rewardXP=4790,rewardItems={159958,160044,160045},starts={{npcID=137537}},ends={{npcID=129519}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51369},questLines={{id=613,name="The Sands of Vol'dun",orderIndex=10,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=33,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=33,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=613,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[51395] = {id=51395,name="The Keepers' Keys",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="It's good to see that your companion is back unharmed. But more importantly, let's see if he still has my stone hidden in his pockets.",objectivesText="Speak to Private James and uncover the significance of Vorrik 's Stone.",rewardGold=257400,rewardXP=4790,rewardItems={159958,160044,160045},starts={{npcID=129519}},ends={{npcID=128694}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51389,51391,51394},questLines={{id=613,name="The Sands of Vol'dun",orderIndex=11,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=34,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=34,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=613,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[51397] = {id=51397,name="Up In Your Drill",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={51397},description="<The drill on the front of the machine is in good condition.> <This seems like the perfect type of work hazard.>",objectivesText="Use the Goblin Mining Machine to disrupt the excavation camp.",mapCandidates={npc={},zone={8721}},questType="world",db2Objectives={{text="Mining Machine commandeered",amount=1,type=0,objectID=137518,orderIndex=0},{text="Horde drilled",amount=1,type=15,objectID=0,orderIndex=1}},worldTaskTitle="Up In Your Drill",db2PoiMapID=1643,db2PoiUiMapID=896,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51398] = {id=51398,name="An Unusual Mentor",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"herbalism"},categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=864,storyline={51398,51399,51404,51408},series={51399,51408,51432},description="Hey <name>, you look like you're ready to handle hostile territory. Far away in the desert of Vol'dun, on the continent of Zandalar, there grows a plant called akunda's bite. You couldn't pay me enough to go there myself, and there's almost no mention of them in any of the books I've read, but all is not lost. I know of an herbalist who lives there in the desert and studies that plant. Find him, and I'm sure he'll be able to teach you a thing or two. Oh, and do be warned... He is a bit... eccentric.",objectivesText="Find Patu in Vol'dun.",rewardItems={152505,152506,152507,152508,152509,152510,152511,159877,159956,160035,160064,160117},starts={{npcID=136096}},ends={{npcID=137572}},mapCandidates={npc={864},zone={8568}},questGiverID=136096,questType="standard",nextQuests={51399},questLines={{id=748,name="8.0 Professions - Gathering - Herbalism - Kul Tiras - Akunda's Bite - SCS",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[51399] = {id=51399,name="Foul Harvest",level=10,requiredLevel=10,faction="both",requiredProfessions={"herbalism"},categories={},flags={},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={51398,51399,51404,51408},series={51398,51408,51432},description="You have traveled far to find knowledge, but you have found me instead. I am curious though, how much further you would travel for it. I will teach you, if you do something for me first. Iron sharpens iron, as they say, so too does adversity strengthen the seed. Go out and find seeds, ones that have been consumed by the wild beasts and have returned to the earth unscathed. Only those seeds will be strong enough to survive the desert sands of Vol'dun.",objectivesText="Collect 12 Digested Akunda's Bite Seeds . Progress: Were you able to get the seeds?",rewardItems={152505,152506,152507,152508,152509,152510,152511,159877,159956,160035,160064,160108,160117,160301,160550},starts={{npcID=137572}},ends={{npcID=137572}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51398,51432},questLines={{id=748,name="8.0 Professions - Gathering - Herbalism - Kul Tiras - Akunda's Bite - SCS",orderIndex=1,flags=0},{id=749,name="8.0 Professions - Gathering - Herbalism - Zandalar - Akunda's Bite - SCS",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[51401] = {id=51401,name="Carry On",level=30,requiredLevel=30,faction="alliance",sharable=false,expansion=7,zoneID=9042,mapID=942,description="Let's get to Brennadam right away. We need to find Brother Pike and get to the bottom of all of this before things get any worse. This road should take us right into town. Brennadam's the busiest market this side of Boralus, so there should be plenty of people there who can help us find Pike. Ready when you are!",rewardGold=30900,rewardXP=515,rewardItems={252395},starts={{npcID=137866}},ends={{npcID=129999}},mapCandidates={npc={942,1161},zone={9042}},questType="standard",sourceQuests={51490},questLines={{id=442,name="A House in Peril",orderIndex=5,flags=0},{id=5371,name="Secrets of Stormsong Valley",orderIndex=6,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5371,questLineOrder=2}}},
[51402] = {id=51402,name="Reporting In",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="I can't believe what we got ourselves in the middle of here. Keystones, C'Thraxxi, there's even a snake-man civil war going on! All I know is Wyrmbane is going to want a full report and if there's anything I hate more than inept privates getting themselves captured it's paperwork. Let's get going.",objectivesText="Report to High Commander Halford Wyrmbane .",rewardGold=514800,rewardXP=5990,rewardItems={159958,160044,160045},starts={{npcID=137543}},ends={{npcID=137213}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51395},questLines={{id=613,name="The Sands of Vol'dun",orderIndex=12,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=36,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=36,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=613,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[51404] = {id=51404,name="What Happens Next",level=10,requiredLevel=10,faction="none",requiredProfessions={"herbalism"},categories={},flags={},sharable=false,expansion=7,storyline={51398,51399,51404,51408},description="After feeling the bite of Akunda so many times, static electricity causes your hair to stand on end as you hold in your hands an intact lightning pod. You noticed that by wrapping the lightning pod in it's own leaves, you were able to remove it without discharging it. If you manage to develop this technique, harvesting this plant would become significantly less hazardous and provide additional material in pristine condition.",objectivesText="Harvest 10 Akunda's Bite without being shocked.",rewardItems={152505,152506,152507,152508,152509,152510,152511,159877,159956,160035,160064,160117,160301,160550},mapCandidates={npc={},zone={}},questType="standard",sourceQuests={51408},questLines={{id=748,name="8.0 Professions - Gathering - Herbalism - Kul Tiras - Akunda's Bite - SCS",orderIndex=3,flags=0},{id=749,name="8.0 Professions - Gathering - Herbalism - Zandalar - Akunda's Bite - SCS",orderIndex=3,flags=0}},startItems={160117}},
[51405] = {id=51405,name="Corruption in the Bay",expansion=7,mapID=895,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Purge the corruption"}},worldTaskTitle="Corruption in the Bay",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51406] = {id=51406,name="The Lord's Hunt",expansion=7,mapID=895,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Join in the hunt!"}},worldTaskTitle="The Lord's Hunt",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51407] = {id=51407,name="Find Their Words",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={49284,49285,49286,49287,49288,49289,51407},description="This portal will get you quickly back to the outpost. When there, present the orders to Akru . Her knowledge is vast, she will be able to discern the truth within.",objectivesText="Deliver the Orders from Nazjatar to Akru at Seekers' Outpost. Progress: Ah. Deyon is correct. I know many things. What do you have there?",rewardGold=25740,rewardXP=175,rewardItems={156871,157543},starts={{npcID=128925},{npcID=129717}},ends={{npcID=129717}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={49289},questLines={{id=5409,name="Dreadpearl Tidings",orderIndex=6,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[51408] = {id=51408,name="Giving Back to Nature",level=10,requiredLevel=10,faction="both",requiredProfessions={"herbalism"},categories={},flags={},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={51398,51399,51404,51408},series={51398,51399,51432},description="Perform one additional task, and I will give you the knowledge you seek. The seeds you have are strong, but they need time until they are ready to grow. However, one must always be prepared in the desert. This sapling is mature enough to live on its own, but it is frail. It needs the dry desert winds to build static so it may bite, but until it does, it is as helpless as grass. Plant it in the desert sands, near the fallen beast south of the Brine Basin, and protect it until it can defend itself.",objectivesText="Plant the Akunda's Bite Sapling and defend it until it builds a static charge. Progress: Have you planted the sapling yet? Has it taken root?",rewardItems={152505,152506,152507,152508,152509,152510,152511,159877,159956,160035,160064,160117,160187},starts={{npcID=137572}},ends={{npcID=137572}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51399},questLines={{id=748,name="8.0 Professions - Gathering - Herbalism - Kul Tiras - Akunda's Bite - SCS",orderIndex=2,flags=0},{id=749,name="8.0 Professions - Gathering - Herbalism - Zandalar - Akunda's Bite - SCS",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
