[51415] = {id=51415,name="Azerite Madness",level=50,requiredLevel=50,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=15946,mapID=863,storyline={51415},objectivesText="Absorb Azerite from defeated elementals",rewardItems={109644,158075},mapCandidates={npc={},zone={15946}},questType="standard",db2Objectives={{text="Absorb Azerite from defeated elementals",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Azerite Madness",db2PoiMapID=1642,db2PoiUiMapID=863,db2QuestInfoID=151,db2QuestInfoName="Magni World Quest - Azerite"},
[51418] = {id=51418,name="Xibala",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="<name>! How's things going over here? Oh. Wow. There's Horde soldiers everywhere. And Zandalari trolls. And hardly any machines at all. We should DEFINITELY head back to Xibala, with the dark iron dwarves. It's perfect for our foothold!",objectivesText="Use the rowboat in Talanji's Rebuke to travel to Xibala.",rewardGold=257400,rewardXP=4790,rewardItems={159779,159910,160249,160433},starts={{npcID=135620},{npcID=137400}},ends={{npcID=136197},{npcID=137401}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51190,51191,51192,51193,51544},questLines={{id=621,name="Mole Machinations",orderIndex=7,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=16,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=18,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=621,questLineOrder=4,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[51421] = {id=51421,name="Shiver Me Timbers",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51421,51435,51436,51437,51438,51439,51440,51441,51442,51975,51984},series={51435,51436},description="It seems our resident shadow hunter has managed to seize a small pirate sloop. We have sent him to Tiragarde Sound in a search for a foothold, and it seems that he has concocted a plan. Ty'jin has requested your help, personally. Do not keep him waiting.",objectivesText="Accompany Shadow Hunter Ty'jin to Tiragarde Sound.",rewardGold=27620,rewardXP=600,starts={{npcID=135691}},ends={{npcID=137675}},mapCandidates={npc={862,895},zone={8499}},questType="standard",sourceQuests={51800},questLines={{id=622,name="A Pirate's Life for We",orderIndex=0,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=9,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=622,questLineOrder=7,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[51422] = {id=51422,name="Azerite Madness",level=50,requiredLevel=50,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=15946,mapID=864,storyline={51422},objectivesText="Absorb Azerite from defeated elementals",rewardItems={109644,158075},mapCandidates={npc={},zone={15946}},questType="standard",db2Objectives={{text="Absorb Azerite from defeated elementals",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Azerite Madness",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=151,db2QuestInfoName="Magni World Quest - Azerite"},
[51425] = {id=51425,name="There's No Place Like Home",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=9734,storyline={51425},description="So, the Arathi Highlands. Quite a sprawl, isn't it? At some point, you may wish to return to this fair Stromgarde with haste. Might I offer a suggestion as to how...?",objectivesText="Talk to Captain Roderick Brewston",rewardItems={160219},ends={{npcID=137698}},mapCandidates={npc={},zone={9734}},questType="standard"},
[51426] = {id=51426,name="Inspection Gadget",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={51426},description="Some time ago, a good friend of mine who had a tinker shop in Boralus just stopped all correspondence. With the state of foreign affairs, I wasn't able to look for him myself until recently. It's not just him. It seems that all of the gnomes that were living in the city just up and vanished. I've decided to start my search with these ruins, but the machines here have gone haywire. Could you go get a good magnetic reading on the place?",objectivesText="Survey the Rusted Vault.",rewardGold=257400,rewardXP=1415,rewardItems={160245,163496},starts={{npcID=137694}},ends={{npcID=137694}},mapCandidates={npc={895},zone={8567}},questType="standard"},
[51427] = {id=51427,name="I Like Turtles",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51427},description="Excellent work, $p. Present the offering to Ai'twen. He will accept it and come to our aid.",objectivesText="Present the offering to Ai'twen. Progress: We are patient. When you are ready.",rewardGold=128700,rewardXP=2060,rewardItems={160349,160352,160355,160358,160395,160396},rewardChoices={160349,160352,160355,160358,160395,160396},starts={{npcID=137453}},ends={{npcID=137453}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51221,51371}},
[51428] = {id=51428,name="Azerite Wounds",level=50,requiredLevel=50,faction="none",sharable=false,expansion=7,zoneID=8501,mapID=864,mapCandidates={npc={},zone={8501}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=5,objectID=136306,text="Azeroth wounds healed"}},worldTaskTitle="Azerite Wounds",db2QuestInfoID=151,db2QuestInfoName="Magni World Quest - Azerite"},
