[51498] = {id=51498,name="Cultural Significance",level=10,requiredLevel=10,faction="horde",requiredProfessions={"herbalism"},categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={51498,51503},description="I have noticed dat your skill with harvesting plants has improved, but I have also noticed dat you just treat each flower and leaf as a commodity. De flora of dese islands have a rich history, with a deep cultural significance to us. Go down to the Port of Zandalar, and ask some of the men and women what a sea stalk means to them. Learn from us, and l will make it worth your while.",objectivesText="Learn the importance of sea stalks from people in the Port of Zandalar.",rewardItems={152505,152506,152507,152508,152509,152510,152511,159877,160064,160117,160301,160550},starts={{npcID=122704}},ends={{npcID=122704}},mapCandidates={npc={1165},zone={8670}},questType="standard",questLines={{id=758,name="8.0 Professions - Gathering - Herbalism - Zandalar - Sea Stalk - SCS",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[51500] = {id=51500,name="Kings' Rest: The Weaponmaster Walks Again",expansion=7,mapID=862,questType="world",worldTaskTitle="Kings' Rest: The Weaponmaster Walks Again",db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
[51501] = {id=51501,name="Kings' Rest: Malfunction Junction",expansion=7,mapID=862,questType="world",worldTaskTitle="Kings' Rest: Malfunction Junction",db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
[51502] = {id=51502,name="Kings' Rest: Kingsguard",expansion=7,mapID=862,questType="world",worldTaskTitle="Kings' Rest: Kingsguard",db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
[51503] = {id=51503,name="Gathering Mementos",level=10,requiredLevel=10,faction="horde",requiredProfessions={"herbalism"},categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={51498,51503},description="I have a task dat I can not really trust to anyone else, and I feel you could handle it with de reverence it deserves. An old friend came to me today, bringing a wilted sea stalk flower with her. Her husband was on a ship off the coast of Nazmir. I am unsure if de ship went down because of de naga, de Alliance, or a squall, but she said she did not want revenge. Only closure. If you could go get her something to remember him by, I will tell you everything I know about sea stalks.",objectivesText="Search through patches of sea weed to find a memento of the lost sailor. Progress: Have you had a chance to search de wreckage?",rewardItems={152505,152506,152507,152508,152509,152510,152511,159877,160064,160117,160301,160314,160550},starts={{npcID=122704}},ends={{npcID=122704}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={51498},questLines={{id=758,name="8.0 Professions - Gathering - Herbalism - Zandalar - Sea Stalk - SCS",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[51504] = {id=51504,name="Cookie Delivery",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51200,51203,51205,51207,51208,51209,51214,51215,51251,51335,51492,51504},description="Before you head out, dear, I have one more favor to ask of you. Please take these cookies with you to Charles. What sort of grandmother would I be if I didn't bake some for him too!? A terrible one, that's what, and I've no wish to be accused of that!",objectivesText="Deliver Box of Cookies to Charles Davenport in the Sprucewood. Progress: Are those cookies I smell!?",rewardGold=25740,rewardXP=515,rewardItems={160302},starts={{npcID=136658}},ends={{npcID=136574}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51335},questLines={{id=5452,name="Milstone Hamlet",orderIndex=8,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[51505] = {id=51505,name="Quillrat Matriarch",level=50,requiredLevel=50,faction="none",categories={},flags={"rare"},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={51505},rewardItems={158583},mapCandidates={npc={},zone={8721}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=125453}},worldTaskTitle="Quillrat Matriarch",db2PoiMapID=1643,db2PoiUiMapID=896,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
