[51530] = {id=51530,name="Wedding Crashers",expansion=7,mapID=896,questType="world",db2Objectives={{orderIndex=0,type=0,amount=12,objectID=137909,text="Terrified Guests rescued"},{orderIndex=1,type=0,amount=6,objectID=137938,text="Wedding Gifts collected"},{orderIndex=2,type=0,amount=10,objectID=137921,text="Invader slain"}},worldTaskTitle="Wedding Crashers",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51532] = {id=51532,name="Storming In",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51224,51231,51233,51234,51332,51340,51421,51435,51436,51437,51438,51439,51440,51441,51442,51526,51532,51536,51587,51643,51674,51675,51691,51696,51753,51800,51801,51802,51803,51916,51975,51979,51984,51985,51986,51987,52444,52451,52749,53050,53056,53064},series={51526,51536,51587,51643},description="Front and center, <name>! As of last night, we received word that Rexxar's force at Warfang Hold in Stormsong was surrounded by a Kul Tiran army and an attack is imminent. As soon as you have your things packed, go speak with Dread-Admiral Tattersail and we'll get underway. There's no time to waste!",objectivesText="Speak with Dread-Admiral Tattersail.",rewardGold=25740,rewardXP=600,rewardItems={155093,155094,155095,155112,155113,155114,155115,155116,168442,168578,168920,187175,229365},starts={{npcID=138352}},ends={{npcID=138365}},mapCandidates={npc={862,942},zone={8499}},questType="standard",sourceQuests={51526},questLines={{id=614,name="Storming In",orderIndex=1,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=29,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=614,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
[51533] = {id=51533,name="The Glaive of Vol'jin",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6453,mapID=463,storyline={51513,51514,51515,51516,51517,51533,52113,52114},description="When fighting someone who has escaped the grasp of Bwonsamdi, as Zalazane has, it is best to bring weapons that can hurt him. In Darkspear Hold you will find the Glaive of Vol'jin . It should have enough bond with Vol'jin's spirit to aid us in this fight.",objectivesText="Obtain the Glaive of Vol'jin . Progress: Did you find the glaive?",rewardGold=234000,rewardXP=6815,rewardItems={160323},starts={{npcID=120173}},ends={{npcID=120173}},mapCandidates={npc={463},zone={6453}},questType="standard",sourceQuests={51513},questLines={{id=734,name="The Fallen Chieftain",orderIndex=2,flags=0}},db2PoiMapID=1,db2PoiUiMapID=463},
[51534] = {id=51534,name="The Battle for Brennadam",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={51534},objectivesText="Collect 1 Salvaged Bullets.",rewardGold=455280,rewardXP=1415,rewardItems={133510,155824,155877,156577,156578,156648,157849,157850,160558,160561},mapCandidates={npc={},zone={9042}},questType="standard",sourceQuests={51401},db2Objectives={{text="Resist the Horde",amount=1,type=15,objectID=0,orderIndex=0},{text="Citizens Rescued",amount=20,type=0,objectID=130747,orderIndex=2}},worldTaskTitle="The Battle for Brennadam",db2PoiMapID=1643,db2PoiUiMapID=942},
[51535] = {id=51535,name="A Veteran's Summons",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,storyline={51535},description=", we received word from Orgrimmar. Eitrigg has requested a meeting. Says it's important. He left a letter for you. I wouldn't keep him waiting or he might expire of old age before you find out what he wants.",objectivesText="Meet Eitrigg at the Orgrimmar Embassy.",rewardGold=238680,rewardXP=5465,mapCandidates={npc={},zone={}},questType="standard"},
[51536] = {id=51536,name="On the Hunt",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51224,51231,51233,51234,51332,51340,51421,51435,51436,51437,51438,51439,51440,51441,51442,51526,51532,51536,51587,51643,51674,51675,51691,51696,51753,51800,51801,51802,51803,51916,51975,51979,51984,51985,51986,51987,52444,52451,52749,53050,53056,53064},series={51526,51532,51587,51643},description="Looks like the magic the Kul Tirans used on our ships is beginning to dissipate, but I'm sure what happened to our ships here is only just the beginning. Get to the shore. We need to contact the survivors and find out just what we're up against.",objectivesText="Search Seawatch Point for survivors.",rewardGold=257400,rewardXP=4790,rewardItems={17687,37226,37382,37435,37513,57316,57317,57318,57319,59256,59257,59258,59259,59284,59285,59286,59287,61124,61125,61126,61127,68644,121802,131202,131518,131546,139902,139932,139962,140002,155383,156945,159038,159039,159040,159041},starts={{npcID=138365}},ends={{npcID=138131}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51643},questLines={{id=614,name="Storming In",orderIndex=3,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=31,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=614,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
[51538] = {id=51538,name="Word from the Deep",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={48014,48015,48025,48026,49969,51538},series={48026},description="A dark soul has infiltrated the Zanchuli Council, seeking an accord with Queen Azshara. Some followed, through greed or fear. Others were too trusting and believed his lies. We fall, one by one. They will soon clear the path of resistance. Azshara's motives are hidden behind a vast darkness. She reaches into a place from where she cannot return. I would pity her, but she killed my followers... When the time comes, I will rip her apart.",objectivesText="Share Gral's warning with the Seekers.",rewardGold=25740,rewardXP=175,rewardItems={156871},starts={{npcID=131461}},ends={{npcID=125041}},mapCandidates={npc={862},zone={8499}},questGiverID=131461,questType="standard",sourceQuests={48026},questLines={{id=5410,name="The Sunken City",orderIndex=7,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[51539] = {id=51539,name="Inform the Horde!",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51539},description="This was all perpetrated by someone on the Zanchuli Council. They sacrificed their own people, Gral's followers, for Azshara. That is unconscionable! They weaken the foundation, so the kingdom will fall. One of your people must have direct access to the king. Anyone else could be the traitor.",objectivesText="Warn Baine of the betrayal.",rewardGold=25740,rewardXP=175,rewardItems={156871},starts={{npcID=125041}},ends={{npcID=125041}},mapCandidates={npc={862},zone={8499}},questTurnInID=125041,questType="standard",sourceQuests={48025,51538}},
[51540] = {id=51540,name="Explosive Situation",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51540},description="<This crate has fallen into the water. It contains bombs built to take out large mechanical devices.> <If we had more of them, we could destroy the Venture Company's Reef Breaker.>",objectivesText="Collect 5 Bot Buster Bombs . Progress: You'll need more of these bombs if we want to destroy the Reef Breaker.",rewardGold=257400,rewardXP=4115,rewardItems={160397,160556},ends={{npcID=137453}},startObjects={{objectID=290138,mapID=942,x=0.378,y=0.285}},coords={mapID=942,source="quest_giver",x=0.356,y=0.312},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51353}},
[51541] = {id=51541,name="Arclight",level=50,requiredLevel=50,faction="none",categories={},flags={"rare"},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={51541},rewardItems={160469},mapCandidates={npc={},zone={8721}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=137824}},worldTaskTitle="Arclight",db2PoiMapID=1643,db2PoiUiMapID=896,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
[51542] = {id=51542,name="Avalanche",level=50,requiredLevel=50,faction="none",categories={},flags={"rare"},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={51542},rewardGold=619600,rewardXP=5145,mapCandidates={npc={},zone={8721}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=137825}},worldTaskTitle="Avalanche",db2PoiMapID=1643,db2PoiUiMapID=896,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
[51543] = {id=51543,name="Saplings in the Snow",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={51543},description="Be wary mainlander, dangers lurk nearby. One such creature, Greenstalker, used to be an ally. In his corrupted, mindless rage he nearly killed my brother and I while we were trying to help someone in the wilds. There is something which might help but I must tend to my brother's wounds and cannot obtain the remaining item on my own. Please go onto the mountainside and pull some saplings out of the earth for me. The plants here are healthy and their roots run deep so they won't come easily.",objectivesText="Collect 6 Mountain Saplings . Progress: Did you find the mountain saplings I need?",rewardGold=257400,rewardXP=2765,rewardItems={160406},starts={{npcID=135861}},ends={{npcID=135861}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48622}},
[51544] = {id=51544,name="Disarming the Cannons",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="With your arrival, our salvation may have arrived. Your rowboats will serve as a way for us to evacuate the most critically injured. Unfortunately, the Horde have brought in a ship, and there's no way we can get our boats past their blockade. While the rest of us load our injured on the boats, we need you to infiltrate their ship and disable those cannons .",objectivesText="Disable the cannons on the Horde ship. Progress: What's the status of those cannons ?",rewardGold=257400,rewardXP=4790,rewardItems={159779,159910,160249,160433},starts={{npcID=136197}},ends={{npcID=136197}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51201},questLines={{id=621,name="Mole Machinations",orderIndex=5,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=15,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=19,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=621,questLineOrder=4,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[51545] = {id=51545,name="Breaker Bad",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51545},description="The combined fire power of all the bombs you have collected should be able to destroy the Venture Companies Reef Breaker . It's time to act and protect the reef and this sacred cave.",objectivesText="Destroy the Reef Breaker .",rewardGold=257400,rewardXP=4115,rewardItems={160556},starts={{npcID=137453}},ends={{npcID=137453}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51540}},
