[51547] = {id=51547,name="WANTED: Rindlewoe",level=20,requiredLevel=20,faction="alliance",categories={},flags={"loremaster"},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={51547},description="A monstrous beast of wood and flesh has been terrorizing the nearby river territories. If any adventurers are brave enough to vanquish this beast, the town of Fallhaven would gratefully proffer a reward. Please report to Mayor White if you wish to help.",objectivesText="Defeat Rindlewoe outside of Fallhaven. Progress: Yes?",rewardGold=514800,rewardXP=3455,rewardCurrencies={{id=1553,amount=115}},ends={{npcID=124417}},startObjects={{objectID=290419,mapID=896,x=0.557,y=0.349}},coords={mapID=896,source="quest_giver",x=0.558,y=0.35},mapCandidates={npc={896},zone={8721}},questType="group",sourceQuests={47982}},
