[51552] = {id=51552,name="The Days Are Just Packed",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51552},description="Hello there! Would you mind checking on someone for me? Sergeant Calvin was supposed to meet me here. We were going to go out looking for new alchemical reagents, but he hasn't shown up yet. I know the militia has been really busy lately so I guess he's busy, but he should still be in Brennadam Square. Would you mind checking in on him?",objectivesText="Find Sergeant Calvin in Brennadam Square.",rewardGold=25740,rewardXP=515,rewardItems={133510,155824,155877,156577,156578,156648,157849,157850,160558,160561},starts={{npcID=130786}},ends={{npcID=130190}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49791,49792,49793,49794},nextQuests={49744}},
[51554] = {id=51554,name="Reloading",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51554},description="Daryl's making every shot count, but there's just too many Horde. We're going to need more ammo soon! I need you to take this note to my uncle Leo at Deadwash, he'll be able to help.",objectivesText="Deliver the note to Leo Shealds .",rewardGold=25740,rewardXP=515,starts={{npcID=135874}},ends={{npcID=134720}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50909},nextQuests={50674}},
[51555] = {id=51555,name="Keep Them On Task",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51555},series={51246},description="Princess Talanji's actions have thrown off our pursuers. Her loa is powerful indeed. We need to be certain if there were survivors, they do not gain a foothold on Zandalar. I am concerned that our Forsaken compatriots might get... overzealous. Please keep an eye on them, and remind them of what is honorable.",objectivesText="Speak with Dennis Grimtale at Talanji's Rebuke.",rewardGold=25740,rewardXP=175,starts={{npcID=141555}},ends={{npcID=137075}},mapCandidates={npc={862},zone={9598}},questGiverID=141555,questType="standard",sourceQuests={47509,50433,51111},nextQuests={51246,51247}},
[51557] = {id=51557,name="Irontide Warning",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51557},description="Horde's taking this town! I'm not gonna stick around to watch! You could help me out though. Go see Leo Shealds in Deadwash. Tell him, Irontide is still coming and we're taking the gold!",objectivesText="Speak to Leo Shealds at Deadwash.",rewardGold=23870,rewardXP=515,mapCandidates={npc={},zone={9042}},questType="standard"},
