[51566] = {id=51566,name="Resurgence of the Beast",expansion=7,mapID=895,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=129456,text="Speak to Okri for a ride"},{orderIndex=1,type=0,amount=1,objectID=129494,text="Outrigger Cannon mounted"},{orderIndex=2,type=0,amount=10,objectID=132115,text="Erupting Darkness shot down"},{orderIndex=3,type=0,amount=1,objectID=129415,text="Talk to the Outrigger Engineer to repel Viq'Goth"},{orderIndex=4,type=0,amount=1,objectID=129580,text="Ride Outrigger Gryphon to town"}},worldTaskTitle="Resurgence of the Beast",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51568] = {id=51568,name="Ritualistic Preparations",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=895,storyline={48768,51568},series={51575,52014},description="Hey! I just got a request for a shipment of storm silver. Wanna help? As you know, storm silver is lightweight and resists corrosion. What you may not know is that we use it throughout our ships. It's so light our marines and pirates use it for armor because they can swim in it! However, any parts that go onto a ship have to be blessed by a tidesage, or it'll be cursed to a watery doom! Harvest a bucketful of ore, smelt it, and get it blessed for me, and I will teach you how to mine it easier.",objectivesText="Mine Unsanctified Storm Silver Ore , use a forge to smelt Unsanctified Storm Silver Ingots , then get them blessed by a tidesage. Progress: Did you get the storm silver? Don't forget that it needs to be blessed.",rewardItems={87216,152512,152513,152579,153431,160440,160905,160974,161078,161085,161133},starts={{npcID=136091}},ends={{npcID=136091}},mapCandidates={npc={},zone={8568}},questGiverID=136091,questTurnInID=136091,questType="standard",questLines={{id=770,name="8.0 Professions - Gathering - Mining - Kul Tiras - Storm Silver Deposit - SCS",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[51569] = {id=51569,name="The Zandalar Campaign",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="It is time that we begin to think of our enemy, <name>. The Horde spreads its influence throughout Zandalar unchecked. King Anduin has charged us with establishing footholds in the areas of Zuldazar, Nazmir, and Vol'dun. I have taken the liberty of deploying some of our forces in key locations, but each will need a firm hand--your hand--to direct our efforts. Which location shall we secure first?",objectivesText="Use the Zandalar Campaign Map to choose a foothold.",rewardGold=257400,rewardXP=4790,starts={{npcID=135612}},ends={{npcID=135612}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={52544},questLines={{id=624,name="The Zandalar Campaign",orderIndex=0,flags=0},{id=5374,name="The Zandalar Campaign",orderIndex=1,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=1,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=1,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=624,questLineOrder=3,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[51570] = {id=51570,name="Foothold: Zuldazar",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="Zuldazar is the seat o' power fer the Zandalar empire. I've deployed some o' me mole machines in a place called Xibala. There's a nearby Azerite deposit that'll be o' great interest to the King. My lads say they're under attack. - Moira Thaurissan",objectivesText="Assist Kelsey Steelspark in Zuldazar.",rewardGold=257400,rewardXP=4790,ends={{npcID=135612}},startObjects={{mapID=1161,x=0.694,y=0.269}},coords={mapID=1161,source="quest_giver",x=0.6945,y=0.2665},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={51569},questLines={{id=624,name="The Zandalar Campaign",orderIndex=6,flags=0},{id=5374,name="The Zandalar Campaign",orderIndex=7,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=6,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=6,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=624,questLineOrder=3,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2AdventureMapPoiID=151},
[51571] = {id=51571,name="Foothold: Nazmir",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="The swamp of Nazmir is home to the notorious blood trolls. Captain Conrad has been dispatched to determine how we can use their hatred toward the Zandalari to our advantage. Reports from the jungle have proven disconcerting at best. - Mathias Shaw",objectivesText="Assist Brann Bronzebeard in Nazmir.",ends={{npcID=135612}},startObjects={{mapID=1161,x=0.694,y=0.269}},coords={mapID=1161,source="quest_giver",x=0.6945,y=0.2665},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={51569},questLines={{id=624,name="The Zandalar Campaign",orderIndex=7,flags=0},{id=5374,name="The Zandalar Campaign",orderIndex=8,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=7,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=7,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=624,questLineOrder=3,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2AdventureMapPoiID=152},
[51572] = {id=51572,name="Foothold: Vol'dun",level=35,requiredLevel=35,faction="none",categories={"campaign"},flags={},sharable=false,expansion=7,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="The desert of Vol'dun has a promising harbor for our fleet. An indigenous snake people known as the sethrak occupy the area. They are aggressive and cannot be negotiated with. We have little choice but to eliminate them. - Magister Umbric",objectivesText="Assist Alliance forces in Vol'dun.",startObjects={{mapID=1161,x=0.694,y=0.269}},endObjects={{mapID=1161,x=0.694,y=0.269}},coords={mapID=1161,x=0.694,y=0.269},mapCandidates={npc={},zone={}},questType="standard",sourceQuests={51569},questLines={{id=624,name="The Zandalar Campaign",orderIndex=8,flags=0},{id=5374,name="The Zandalar Campaign",orderIndex=9,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=8,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=8,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=624,questLineOrder=3,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2AdventureMapPoiID=153},
[51573] = {id=51573,name="I've Got Your Back",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48529,48530,48531,48532,48533,48534,48585,48655,48656,48657,48790,48846,48847,48850,51573,51602,51668},description="It's good to see a new face around here. I've got a problem and you look like you can handle a fight. Dat group of murderous thugs over dere are looking for trouble and I need someone to back me up. De truth is dat I used to be one of dem myself, but I left for a second chance at an honest life. I need to convince Mojambo and his henchmons to leave before dey start causing trouble for de rest of de outcasts here.",objectivesText="Guard Razgaji while he meets with Mojambo. Progress: Mojambo isn't going to back down easily.",rewardGold=257400,rewardXP=4115,starts={{npcID=126576}},ends={{npcID=126576}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50794},questLines={{id=5424,name="Champion of the Arena",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[51574] = {id=51574,name="Freshly Squeezed",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={"loremaster"},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47316,47317,47319,47320,47321,47959,48549,48550,51574},description="Is this troll a friend of yours? I'm so glad Kiro let me keep her. He's a bit wary of outsiders, but he's a great healer. She'll wake up, I promise. And when she does, she'll be thirsty. The sands are short on water, but you're in luck. The grove that surrounds this camp is filled with pricklevines. You wouldn't want to eat the flesh, but the liquid inside can quench any thirst. Just give them a good squeeze to collect their juice.",objectivesText="Collect 8 Pricklevine Juice . Progress: Do you have the juice? Your friend will be thirsty when she wakes.",rewardGold=257400,rewardXP=4115,rewardItems={160448},starts={{npcID=122583}},ends={{npcID=122583}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51364},questLines={{id=606,name="Dangers in the Desert",orderIndex=1,flags=0},{id=5391,name="Dunes of Vol'dun",orderIndex=10,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=864},
[51575] = {id=51575,name="Lost But Not Forgotten",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={51575,52213},series={51568,52014},description="Hey, <name>, would you be interested in getting back a personal possession? Dere is a raptor in Xibala dat took an ancient and valuable artifact from my people. My attempts to negotiate with de beast have not gone well, resulting mostly in mutual screaming and biting. Find de raptor Bonescreamer, kill it, and bring me de lost artifact. In return, I will show you how to skin dese beasts of de land more effectively.",objectivesText="Kill Bonescreamer and bring the 'Ancient Artifact' to Rana the Cutta . Progress: Have you slain de beast yet? <Rana chuckles as she smiles slyly.>",rewardGold=280900,rewardXP=200,rewardItems={53372,53377,53393,60242,131409,152541,153050,161430,161431},starts={{npcID=122699}},ends={{npcID=122699}},mapCandidates={npc={1165},zone={8670}},questType="standard",questLines={{id=776,name="8.0 Professions - Gathering - Skinnin - Zandalar - Leather - SCS",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
