[51587] = {id=51587,name="Onward!",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51224,51231,51233,51234,51332,51340,51421,51435,51436,51437,51438,51439,51440,51441,51442,51526,51532,51536,51587,51643,51674,51675,51691,51696,51753,51800,51801,51802,51803,51916,51975,51979,51984,51985,51986,51987,52444,52451,52749,53050,53056,53064},series={51526,51532,51536,51643},description="I'm glad you came, <name>. With your help, we will show these Kul Tiran dogs what happens when you face a cornered beast! Warfang Hold is just up the path from here. Come, I'll fill you in on the details.",objectivesText="Accompany Rexxar .",rewardGold=257400,rewardXP=4790,starts={{npcID=138131}},ends={{npcID=138688}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51536},questLines={{id=614,name="Storming In",orderIndex=4,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=32,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=614,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
[51588] = {id=51588,name="Familiar Foes",expansion=7,mapID=896,questType="world",db2Objectives={{orderIndex=0,type=0,amount=4,objectID=125094,text="Lesser Effigy destroyed"},{orderIndex=1,type=0,amount=10,objectID=124885,text="Enthralled Wildlife slain"},{orderIndex=2,type=2,amount=5,objectID=302779,text="Bloody Banners burned"}},worldTaskTitle="Familiar Foes",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51589] = {id=51589,name="Breaking Kul Tiran Will",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51589,51590,51591,51592,51593,51594,51595,51596,51597,51598,51599,51601},series={51590,51591},description="Our partnership with the Zandalari will soon be secured. Took a little longer than I expected... but such is the way of things. Unfortunately, the Alliance seems intent on securing a naval force of their own. That can't be allowed to happen. We set sail for Tiragarde Sound when you're ready.",objectivesText="Sail to Tiragarde Sound.",rewardGold=234000,rewardXP=6815,starts={{npcID=135691}},ends={{npcID=138285}},mapCandidates={npc={862,895},zone={8499}},questType="standard",sourceQuests={51984,51985,51986},questLines={{id=625,name="The First Assault",orderIndex=0,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=625,questLineOrder=10,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=625,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[51590] = {id=51590,name="Into the Heart of Tiragarde",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={51589,51590,51591,51592,51593,51594,51595,51596,51597,51598,51599,51601},series={51589,51591},description="Step one is to establish a more suitable base of operations. A pirate's den will do in a pinch, but I believe the warchief expects better of us. Let's split up and push farther inland, to the west. Be on the lookout for something defensible and inconspicuous.",objectivesText="Rendezvous with Nathanos and Lilian in central Tiragarde Sound.",rewardGold=234000,rewardXP=6815,starts={{npcID=138285}},ends={{npcID=138285}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={51589},questLines={{id=625,name="The First Assault",orderIndex=1,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=625,questLineOrder=10,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=625,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[51591] = {id=51591,name="Our Mountain Now",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={51589,51590,51591,51592,51593,51594,51595,51596,51597,51598,51599,51601},series={51589,51590},description="<name>, go take care of those \"roughnecks.\" They might fashion themselves as tough, but a bit of your unique brand of Horde savagery should have them running in no time. Lilian, scout the area. We need to know about any nearby threats. Rangers, secure the perimeter. We'll reconvene in the roughneck camp once <name>'s work is done.",objectivesText="Slay 10 Roughnecks in Timberfell Outpost. Progress: Me? I'll go where I'm needed.",rewardGold=234000,rewardXP=6815,starts={{npcID=138285}},ends={{npcID=138285}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={51590},questLines={{id=625,name="The First Assault",orderIndex=2,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=625,questLineOrder=10,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=625,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[51592] = {id=51592,name="Making Ourselves at Home",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={51589,51590,51591,51592,51593,51594,51595,51596,51597,51598,51599,51601},description="Log cabins will do in a pinch, but... if we're going to be spending any time here, we might as well make ourselves comfortable. The roughnecks left us no shortage of lumber and food supplies, but we'll need canvas and chains to set up some proper Forsaken tents and banners. Bridgeport sounds rather lootable, doesn't it?",objectivesText="Obtain 7 Lengths of Chain and 7 bolts of Sail Canvas from the outskirts of Bridgeport. Progress: With a name like Bridgeport, I have to assume that the town has plenty of supplies in transit, ready for looting.",rewardGold=234000,rewardXP=6815,rewardItems={160511,160512},starts={{npcID=138285}},ends={{npcID=138285}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={51591},questLines={{id=625,name="The First Assault",orderIndex=3,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=625,questLineOrder=10,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=625,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[51593] = {id=51593,name="Bridgeport Investigation",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8567,mapID=895,series={51594,51595},description="While you're in Bridgeport, you might keep an ear out for any information that will be of aid to us. You'd be surprised what you can learn by staying quiet and listening to people who think they're alone...",rewardGold=234000,rewardXP=6815,starts={{npcID=138287}},ends={{npcID=138287}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={51591},questLines={{id=625,name="The First Assault",orderIndex=4,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=625,questLineOrder=10,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=625,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},
[51594] = {id=51594,name="Explosives in the Foundry",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={51589,51590,51591,51592,51593,51594,51595,51596,51597,51598,51599,51601},series={51593,51595},description="I'm most interested in those explosives, though. Meet me in the foundry, east of here. You probably passed through it on your way from Plunder Harbor.",objectivesText="Meet Lilian Voss at the Ashvane Foundry.",rewardGold=234000,rewardXP=6815,starts={{npcID=138287}},ends={{npcID=138287}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={51592,51593},questLines={{id=625,name="The First Assault",orderIndex=5,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=625,questLineOrder=10,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=625,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[51595] = {id=51595,name="Explosivity",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={51589,51590,51591,51592,51593,51594,51595,51596,51597,51598,51599,51601},series={51593,51594},description="I don't want to waste your time. Let's make absolutely sure that these are what we're looking for. Here, take this torch and toss it over onto those crates. If they explode, then we'll know what to do next.",objectivesText="Use Lilian's Torch on the Pile of Ashvane Crates near the Ashvane Foundry. Progress: Well?",rewardGold=234000,rewardXP=6815,rewardItems={88589},starts={{npcID=138287}},ends={{npcID=138287}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={51594},questLines={{id=625,name="The First Assault",orderIndex=6,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=625,questLineOrder=10,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=625,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[51596] = {id=51596,name="Ammunition Acquisition",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={51589,51590,51591,51592,51593,51594,51595,51596,51597,51598,51599,51601},series={51597,51598,51599,51601},description="First: we get as much of that gunpowder as we possibly can. Imagine the terror in the Kul Tirans' eyes when they realize the Horde has turned their own weapons against them. Imagine it, <name>. <Lilian's eyes briefly glaze over, and the corner of her lips turns upward in a half-smile.>",objectivesText="Obtain 8 crates of Ashvane Explosives . Progress: I've managed to round up a few crates myself. How did you do?",rewardGold=234000,rewardXP=6815,rewardItems={160555},starts={{npcID=138287}},ends={{npcID=138287}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={51595},questLines={{id=625,name="The First Assault",orderIndex=7,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=625,questLineOrder=10,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=625,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[51597] = {id=51597,name="Gunpowder Research",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={51589,51590,51591,51592,51593,51594,51595,51596,51597,51598,51599,51601},series={51596,51598,51599,51601},description="I suppose that, before we steal all the Kul Tirans' violently explosive gunpowder and use it against them, we should learn how they make the stuff.",objectivesText="Obtain the Ashvane Explosives Formula and the Gunpowder Manufacturing Guide . Progress: Let's see the paperwork.",rewardGold=468000,rewardXP=8520,rewardItems={160552,160553},starts={{npcID=138287}},ends={{npcID=138287}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={51595},questLines={{id=625,name="The First Assault",orderIndex=8,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=625,questLineOrder=10,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=625,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[51598] = {id=51598,name="A Bit of Chaos",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={51589,51590,51591,51592,51593,51594,51595,51596,51597,51598,51599,51601},series={51596,51597,51599,51601},description="This place seems fairly well-defended for a manufacturing facility, doesn't it? <Lilian shrugs.> I suppose we'll have to kill them, then.",objectivesText="Slay 15 workers at the Ashvane Foundry.",rewardGold=234000,rewardXP=6815,starts={{npcID=138287}},ends={{npcID=138287}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={51595},questLines={{id=625,name="The First Assault",orderIndex=9,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=625,questLineOrder=10,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=625,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[51599] = {id=51599,name="Death Trap",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={51589,51590,51591,51592,51593,51594,51595,51596,51597,51598,51599,51601},series={51596,51597,51598,51601},description="We started this mission with a goal, but not much of a plan. I think I can see the pieces coming together, though. <Lilian surveys the horizon, thinking.> Place these explosives over on the southwest edge of town. Somewhere inconspicuous. We'll meet again over there. In the meantime... I need to find a horse.",objectivesText="Place 8 Gunpowder Crates in a hidden location southwest of Bridgeport.",rewardGold=234000,rewardXP=6815,rewardItems={63648,63649,63650,63651},starts={{npcID=138287}},ends={{npcID=138287}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={51596,51597,51598},questLines={{id=625,name="The First Assault",orderIndex=10,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=625,questLineOrder=10,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=625,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[51601] = {id=51601,name="The Bridgeport Ride",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={51589,51590,51591,51592,51593,51594,51595,51596,51597,51598,51599,51601},series={51596,51597,51598,51599},description="Pay attention, <name>, because this isn't going to be our standard assassination mission. You and I are going to take this horse through Bridgeport and... cause a scene. I want every single guard on our tail, along with that Captain Stone character. Once we've rounded them up, it's over to those explosives, and... <Lilian's eyes grow wide with delight.> Boom.",objectivesText="Mount the Stolen Horse, then use it to round up 10 Bridgeport Guards and Captain Stone. Then escort them to the southwest corner of town. Getting knocked off of your horse could prove fatal, and will fail the mission.",rewardGold=234000,rewardXP=6815,rewardItems={245466},rewardCurrencies={{id=1553,amount=800}},starts={{npcID=138287}},ends={{npcID=138285}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={51599},questLines={{id=625,name="The First Assault",orderIndex=11,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=625,questLineOrder=10,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=625,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[51602] = {id=51602,name="Bandit Blades",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48529,48530,48531,48532,48533,48534,48585,48655,48656,48657,48790,48846,48847,48850,51573,51602,51668},description="We only have enough weapons to arm half of de tribe against Mojambo's gang. We're going to need more weapons if we are going to survive de approaching battle. Tongo's crew is sure to have a ready supply of weapons at their hideout. Search de hideout for any weapons you can find and bring dem back to de arena.",objectivesText="Retrieve 8 Sandworn Blades . Progress: Do you have de weapons?",rewardGold=257400,rewardXP=4115,rewardItems={160515},starts={{npcID=126576}},ends={{npcID=126576}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48846},questLines={{id=5424,name="Champion of the Arena",orderIndex=13,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
