[51668] = {id=51668,name="Mojambo",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={48529,48530,48531,48532,48533,48534,48585,48655,48656,48657,48790,48846,48847,48850,51573,51602,51668},description="Mojambo and his gang are attacking! We must defend de arena. Mojambo must be defeated! De outcasts will take care of his gang. Mojambo is all yours... Bring Tongo's head with you and use it to challenge Mojambo to a duel. His pride is too great to resist such a challenge!",objectivesText="Slay Mojambo . Progress: Mojambo must be defeated!",rewardGold=210000,rewardXP=5145,rewardItems={155419,155420,155424,155429,155441,155442,160029,160030,160031,160525},rewardChoices={155424,155419,160029,160030,160031,155441,155429,155442,155420},starts={{npcID=126576}},ends={{npcID=126576}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={48847},questLines={{id=5424,name="Champion of the Arena",orderIndex=16,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
