[51674] = {id=51674,name="Douse the Flames",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51224,51231,51233,51234,51332,51340,51421,51435,51436,51437,51438,51439,51440,51441,51442,51526,51532,51536,51587,51643,51674,51675,51691,51696,51753,51800,51801,51802,51803,51916,51975,51979,51984,51985,51986,51987,52444,52451,52749,53050,53056,53064},description="Do you smell it, <name>? Smoke! They're burning down Warfang Hold! There is little point to our battle if our base burns to the ground! Their tidesages use wands to control their constructs of water. In our hands they may give us a chance to save the Hold! Get those wands and put out the fires before the camp burns to ash!",objectivesText="Obtain a Fading Umbral Wand and use it to put out 4 flames around Warfang Hold. Progress: We're fortunate that the Kul Tirans have a greater affinity for water than they do for fire.",rewardGold=257400,rewardXP=4790,rewardItems={160565},starts={{npcID=138677}},ends={{npcID=138867}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51587},questLines={{id=614,name="Storming In",orderIndex=7,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=35,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=614,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
[51675] = {id=51675,name="Hunt Them Down",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51224,51231,51233,51234,51332,51340,51421,51435,51436,51437,51438,51439,51440,51441,51442,51526,51532,51536,51587,51643,51674,51675,51691,51696,51753,51800,51801,51802,51803,51916,51975,51979,51984,51985,51986,51987,52444,52451,52749,53050,53056,53064},description="These Kul Tirans, they don't seem normal. Humans can be a cruel bunch from what I've heard, but these ones seem to take pleasure in slaying the fallen. The worst of them was a woman wearing a peculiar mask. She seemed to be shouting orders to the others, so I guess she's their leader. Honor the fallen and ensure they and their leader don't survive.",objectivesText="Slay Captain Ara and 8 Storm's Wake Footmen.",rewardGold=257400,rewardXP=4790,starts={{npcID=138688}},ends={{npcID=138688},{npcID=138869}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51587},questLines={{id=614,name="Storming In",orderIndex=5,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=33,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=614,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
[51676] = {id=51676,name="What a Gull Wants",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={51676},objectivesText="Fishing Rod reeled in",rewardItems={136376,152631,152845,152865,167097},mapCandidates={npc={},zone={8721}},questType="world",db2Objectives={{text="Fishing Rod reeled in",amount=5,type=3,objectID=144217,orderIndex=2}},worldTaskTitle="What a Gull Wants",db2PoiMapID=1643,db2PoiUiMapID=896,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51677] = {id=51677,name="Mending Body and Soul",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,description="Good. You have brought me the last ingredients I will need to concoct a solution to close the king's wounds. You are not a moment too soon. He is fading. I am not comfortable working at an elevated pace, but the situation requires it. You must be my hands, for I am very slow. Bring me what I need, and let Jamil and I worry about the rest. Speak to me when you are ready to begin.",rewardGold=128700,rewardXP=710,starts={{npcID=124063}},ends={{npcID=124063}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47733,47735,47739,50235},questLines={{id=349,name="Among the People",orderIndex=5,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=60,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[51678] = {id=51678,name="Rastakhan's Might",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,series={47738,47742,51679,47737},description="Do you see de ship out in de bay, ? Dat is my flagship, Rastakhan's Might. It is not here under my orders. We will deal with de Prophet Zul in good time. For now, those who took my vessel must pay. You are to bring me de head of Windcaller Ula'jan. De ship does not move without him, and it will not be moving again once he is dead!",rewardGold=257400,rewardXP=1415,rewardChoices={155242,155243,155244,155245,158391,158392,158393,158394},starts={{npcID=124062}},ends={{npcID=124062}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47738},questLines={{id=349,name="Among the People",orderIndex=7,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=62,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[51679] = {id=51679,name="A Strange Port of Call",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=9772,mapID=862,series={47738,47742,51678,47737},description="I know Rastakhan is furious dat dey claimed his ship, of all de vessels in our navy. But dere is a better question to ask. Why did dey bring it here? Zeb'ahari is a small fishing village. Dere are no warriors here, no powerful supporters of de king. Dere must be another reason. Board de ship and have a good look around. See if you can find out why dey brought dat beast of a boat way out here.",rewardGold=257400,rewardXP=1415,starts={{npcID=124083}},ends={{npcID=124062}},mapCandidates={npc={862},zone={9772}},questType="standard",sourceQuests={47738},questLines={{id=349,name="Among the People",orderIndex=8,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=63,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
[51680] = {id=51680,name="In Bwonsamdi's Shadow",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=8499,mapID=862,series={51101,47735},description="Something is wrong, . My king is blessed by de loa in ways your kind cannot imagine. He has been given long life, swift healing, and strength beyond most trolls. But still, he lingers on death's door. I can practically hear Bwonsamdi laughing. Two of his most trusted menders are with him. Go and find out what is taking so long. I will make sure dey are not interrupted.",rewardGold=25740,rewardXP=175,starts={{npcID=124083}},ends={{npcID=124063}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51101},questLines={{id=349,name="Among the People",orderIndex=0,flags=0},{id=5389,name="Unrest in Zuldazar",orderIndex=55,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5389,questLineOrder=0}}},
