[51691] = {id=51691,name="Almost Worth Saving",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51224,51231,51233,51234,51332,51340,51421,51435,51436,51437,51438,51439,51440,51441,51442,51526,51532,51536,51587,51643,51674,51675,51691,51696,51753,51800,51801,51802,51803,51916,51975,51979,51984,51985,51986,51987,52444,52451,52749,53050,53056,53064},description="We tried to evacuate as many of our people from the hold as we could, but some of the peons weren't so lucky. They're worthless as fighters, but we'll need their labor in the times ahead. Please, save them if you can.",objectivesText="Rescue 6 Frightened Peons from Warfang Hold.",rewardGold=257400,rewardXP=4790,starts={{npcID=138688}},ends={{npcID=138688},{npcID=138869}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51587},questLines={{id=614,name="Storming In",orderIndex=6,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=34,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=614,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
