[51694] = {id=51694,name="Which Witch?",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={51694},objectivesText="Corlain Refugee tested Heartsbane objects destroyed",rewardGold=140450,rewardXP=1045,rewardItems={160571,163607},mapCandidates={npc={},zone={8721}},questType="world",db2Objectives={{text="Corlain Refugee tested",amount=10,type=0,objectID=129575,orderIndex=0},{text="Heartsbane objects destroyed",amount=10,type=0,objectID=131189,orderIndex=1}},worldTaskTitle="Which Witch?",db2PoiMapID=1643,db2PoiUiMapID=896,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51696] = {id=51696,name="Reclaiming What's Ours",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51224,51231,51233,51234,51332,51340,51421,51435,51436,51437,51438,51439,51440,51441,51442,51526,51532,51536,51587,51643,51674,51675,51691,51696,51753,51800,51801,51802,51803,51916,51975,51979,51984,51985,51986,51987,52444,52451,52749,53050,53056,53064},description="I'm impressed. You not only saved our people, but you also managed to kill the leader of the attacking forces. At the top of this tower is our warhorn. At the signal, our troops will come running and we'll get this hold back under our control. <name>, I think you've earned the honors.",objectivesText="Sound the warhorn and retake control of Warfang Hold in Stormsong Valley.",rewardGold=257400,rewardXP=4790,starts={{npcID=138867}},ends={{npcID=138876}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51674,51675,51691},questLines={{id=614,name="Storming In",orderIndex=8,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=36,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=614,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
