[51706] = {id=51706,name="Deadwood",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={51706},objectivesText="Use Greater Control Charm Destroy Witch Forces Kill Golems Kill Heavies Kill Small Wicker and witch",rewardGold=105000,rewardXP=2090,rewardItems={13444,13446,21316,21317,160584},mapCandidates={npc={},zone={8721}},questType="world",db2Objectives={{text="Use Greater Control Charm",amount=1,type=0,objectID=134323,orderIndex=0},{text="Destroy Witch Forces",amount=1,type=15,objectID=0,orderIndex=1},{text="Kill Golems",amount=100,type=0,objectID=134190,orderIndex=2},{text="Kill Heavies",amount=100,type=0,objectID=134189,orderIndex=3},{text="Kill Small Wicker and witch",amount=200,type=0,objectID=134211,orderIndex=4}},worldTaskTitle="Deadwood",db2PoiMapID=1643,db2PoiUiMapID=896,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
