[51770] = {id=51770,name="Mission from the Warchief",level=35,requiredLevel=35,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47332,51770,51771,52746,52749,53079,53333},series={51771,53079},description="Lady Sylvanas issued orders for Garona Halforcen to take on a task of great import. She will orchestrate missions from the Banshee's Wail, and is to assemble a strong force to execute on our plans. This effort will be vital to our war against the Alliance, and your assistance will certainly be necessary.",objectivesText="Walk with Garona Halforcen belowdecks on the Banshee's Wail.",rewardGold=257400,rewardXP=4790,starts={{npcID=135691}},ends={{npcID=138708}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={53333},questLines={{id=618,name="Mission from the Warchief",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[51771] = {id=51771,name="War of Shadows",level=35,requiredLevel=35,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=862,storyline={47332,51770,51771,52746,52749,53079,53333},series={51770,53079},description="I have begun to assemble heroes for our cause. Perhaps you already know Arcanist Valtrois? We will need to recruit more in the future, but this is a promising beginning. Our missions will be those of subterfuge, reconnaissance, assassination, and other focused strikes against our enemies. Let us test the mettle of this nightborne, shall we?",objectivesText="Send Arcanist Valtrois on a mission. Progress: I will not deviate from my mission.",rewardGold=257400,rewardXP=4790,starts={{npcID=138708}},ends={{npcID=138708}},mapCandidates={npc={862},zone={9042}},questType="standard",sourceQuests={51770},questLines={{id=618,name="Mission from the Warchief",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[51772] = {id=51772,name="The Tortaka Tribe",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51772},series={47577},description="Have you ever met a tortollan before? Dey have all kinds of useful scrolls and artifacts for sale. We used to trade often with de Tortaka tribe, but we haven't seen or heard from dem in weeks. De tribe has a village in Darkwood Shoal. We need someone to make contact with dem and reestablish our trading partnership.",objectivesText="Meet with Torka .",rewardGold=25740,rewardXP=515,starts={{npcID=126108}},ends={{npcID=134098}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51668},nextQuests={47570,47577,47943}},
[51773] = {id=51773,name="The Ashvane Threat",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51773},series={47870},description="De Ashvane Trading Company has a mining operation in Redrock Harbor. Don't let de fancy name fool you, dey are as dangerous a band of pirates as I've ever seen. Recently, one of their crew members has been trying to make contact with us. I need someone to meet with him and see what he wants. It might be a trap, but whatever information he has on de Ashvane Trading Company could prove useful to our survival.",objectivesText="Meet with Randall Redmond .",rewardGold=25740,rewardXP=515,rewardItems={160735},starts={{npcID=126576}},ends={{npcID=124468}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51668},nextQuests={47870,47871}},
[51774] = {id=51774,name="Ragna",level=50,requiredLevel=50,faction="none",categories={},flags={"rare"},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={51774},rewardGold=404400,rewardXP=7675,rewardItems={160465},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=134884}},worldTaskTitle="Ragna",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
[51775] = {id=51775,name="Camp Lastwind",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51775},series={48324},description="A vulpera caravan recently set up camp not far from here. Dis could be a good opportunity to establish new trade partners with de tribe. De desert is a dangerous place, <name>. Go see if dey need any assistance. I'm sure dey could use experienced hands like yours. In exchange, perhaps dey'd be willing to offer de tribe a discount on goods and services.",objectivesText="Speak with Norah .",rewardGold=25740,rewardXP=515,starts={{npcID=126085}},ends={{npcID=125904}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={51668},nextQuests={48324}},
