[51797] = {id=51797,name="Tracking Tidesages",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51797,51798,51805,51818,51819,51830,51837,52122,53066},series={51798,53066},description="Rexxar has been tracking a powerful tidesage to help us find the body of Marshal Valentine. He has sent word of a breakthrough. Travel to Stormsong. Help the half-ogre and Lilian find this tidesage, and bend him to the will of the Horde. Do not come back without a way to find Marshal Valentine.",objectivesText="Meet Rexxar within Warfang Hold in Stormsong.",rewardGold=234000,rewardXP=6815,starts={{npcID=135691}},ends={{npcID=138876}},mapCandidates={npc={862,942},zone={8499}},questType="standard",sourceQuests={51789,53066},questLines={{id=627,name="Death of a Tidesage",orderIndex=0,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=627,questLineOrder=12,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=627,questLineOrder=4}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
[51798] = {id=51798,name="No Price Too High",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51797,51798,51805,51818,51819,51830,51837,52122,53066},series={51797,53066},description="I have tracked a tidesage to a camp nearby. He has been staying there with his family. Be warned, tidesages are powerful foes. They have mastery over all the elements, and some even manipulate the Void. If this man is with his family, it means he may not give up so easily. Let us hope he's smart enough to keep them out of this. Come.",objectivesText="Help Rexxar track down a tidesage.",rewardGold=23400,rewardXP=850,starts={{npcID=138876}},ends={{npcID=139101}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51797},questLines={{id=627,name="Death of a Tidesage",orderIndex=1,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=627,questLineOrder=12,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=627,questLineOrder=4}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
[51800] = {id=51800,name="Foothold: Tiragarde Sound",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={51224,51231,51233,51234,51332,51340,51421,51435,51436,51437,51438,51439,51440,51441,51442,51526,51532,51536,51587,51643,51674,51675,51691,51696,51753,51800,51801,51802,51803,51916,51975,51979,51984,51985,51986,51987,52444,52451,52749,53050,53056,53064},description="Tiragarde Sound has lotsa pirates on da coastline. I made contact wit' a first mate of a crew, and she tinks we can take on da captain and get a nice outpost in de process. - Shadow Hunter Ty'jin",objectivesText="Assist Shadow-Hunter Ty'jin in Tiragarde Sound.",starts={{npcID=144630}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questGiverID=144630,questType="standard",questLines={{id=623,name="The Kul Tiras Campaign",orderIndex=6,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=6,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=623,questLineOrder=4,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2AdventureMapPoiID=148},
[51801] = {id=51801,name="Foothold: Drustvar",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={51224,51231,51233,51234,51332,51340,51421,51435,51436,51437,51438,51439,51440,51441,51442,51526,51532,51536,51587,51643,51674,51675,51691,51696,51753,51800,51801,51802,51803,51916,51975,51979,51984,51985,51986,51987,52444,52451,52749,53050,53056,53064},description="It seems Drustvar has a big seam of Azerite underground. Do you like profit? I LOVE profit. This seems like a golden opportunity, if ya catch my meanin'. Time is money! - Trade Prince Gallywix",objectivesText="Assist Gallywix and Eitrigg in Drustvar.",starts={{npcID=144630}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questGiverID=144630,questType="standard",questLines={{id=623,name="The Kul Tiras Campaign",orderIndex=7,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=8,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=623,questLineOrder=4,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2AdventureMapPoiID=149},
[51802] = {id=51802,name="Foothold: Stormsong Valley",level=35,requiredLevel=35,faction="none",categories={"campaign"},flags={},sharable=false,expansion=7,storyline={51224,51231,51233,51234,51332,51340,51421,51435,51436,51437,51438,51439,51440,51441,51442,51526,51532,51536,51587,51643,51674,51675,51691,51696,51753,51800,51801,51802,51803,51916,51975,51979,51984,51985,51986,51987,52444,52451,52749,53050,53056,53064},description="We established and fortified an outpost in Stormsong Valley called Warfang Hold. The Kul Tiran forces have it surrounded and an attack is imminent. We need reinforcements. Do not delay. - Rexxar",objectivesText="Assist Rexxar in Stormsong Valley.",starts={{npcID=144630}},ends={{npcID=144630}},mapCandidates={npc={},zone={}},questGiverID=144630,questTurnInID=144630,questType="standard",questLines={{id=623,name="The Kul Tiras Campaign",orderIndex=8,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=7,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=623,questLineOrder=4,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2AdventureMapPoiID=150},
[51803] = {id=51803,name="The Kul Tiras Campaign",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51224,51231,51233,51234,51332,51340,51421,51435,51436,51437,51438,51439,51440,51441,51442,51526,51532,51536,51587,51643,51674,51675,51691,51696,51753,51800,51801,51802,51803,51916,51975,51979,51984,51985,51986,51987,52444,52451,52749,53050,53056,53064},description="Our enemy spreads its influence throughout Kul Tiras, recruiting new allies to fight against the Horde. We must establish footholds in these enemy lands if we are to win this war. The Warchief requires your assistance in securing outposts in Stormsong Valley, Drustvar, and Tiragarde Sound. Which location shall we secure first?",objectivesText="Use the Kul Tiras Campaign Map to choose a foothold.",rewardGold=257400,rewardXP=4790,starts={{npcID=135691}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questType="standard",questLines={{id=623,name="The Kul Tiras Campaign",orderIndex=0,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=1,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=623,questLineOrder=4,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
