[51805] = {id=51805,name="They Will Know Fear",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51797,51798,51805,51818,51819,51830,51837,52122,53066},description="Finally, a chance to strike at the Alliance AND Kul Tirans! Sagehold is crawling with initiate tidesages studying magic and Kul Tirans trying to fortify the place against the Horde. Let's strike some fear into them. Make them rethink trying to help the Alliance fight the Horde. Take this horn. In my hands, it calls a val'kyr. In yours, it will sow terror amongst our enemies. I trust you above all others with this horn. Do not let me down.",objectivesText="Terrorize 20 Kul Tiran Builders or Tidesage Recruits with the Val'kyr Horn .",rewardGold=234000,rewardXP=6815,rewardItems={160901},starts={{npcID=139101}},ends={{npcID=139101}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51798},questLines={{id=627,name="Death of a Tidesage",orderIndex=2,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=627,questLineOrder=12,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=627,questLineOrder=4}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
[51806] = {id=51806,name="Pest Remover Mk. II",level=50,requiredLevel=50,faction="none",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={51806},rewardItems={160329},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=137649}},worldTaskTitle="Pest Remover Mk. II",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[51810] = {id=51810,name="Captain Hartford",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={47870,47871,47873,51810},description="I'm almost ready to leave Vol'dun once and for all. There's just one thing left to be done... We need to murder the captain of the ship. If Captain Hartford finds out I've deserted, I won't be safe in Boralus or anywhere else. He'll hunt me to the Eastern Kingdoms and back if he has to! This will be dangerous. So you'll want to disguise yourself before boarding The Siren's Call. This will be our last job together. Do it and I'll give you the code to the captain's lockbox. A pirate's bounty!",objectivesText="Slay Captain Hartford .",rewardGold=514800,rewardXP=5145,rewardItems={160735},starts={{npcID=124468},{npcID=139069}},ends={{npcID=139070}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={47870,47871},questLines={{id=5423,name="Ashvane Antics",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
