[51818] = {id=51818,name="Commander and Captain",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=9042,mapID=942,description="This brings me no joy, , but I will do what I must to make sure my family is happy and safe. I would prefer we avoid violence, but if we must... there are two targets. Their leaders. Captain Malia and Commander Augustine. Their loss should force the two groups to retreat from the area. Also, Augustine confiscated a book of mine. Recover it and my powers are yours, for however long I have left.",rewardGold=468000,rewardXP=8520,starts={{npcID=139098}},ends={{npcID=139098}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51798},questLines={{id=627,name="Death of a Tidesage",orderIndex=3,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=627,questLineOrder=12,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=627,questLineOrder=4}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},
[51819] = {id=51819,name="Scattering Our Enemies",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51797,51798,51805,51818,51819,51830,51837,52122,53066},description="We've been scouting the area of Sagehold for some time now. It was recently retaken by a large force of Alliance and Kul Tirans. We have been waiting for an opportunity to strike when their defenses were weakened. Now is that time. Go down to Sagehold and show the forces that remain what happens to those who take up arms against the Horde.",objectivesText="Kill 10 Alliance and Kul Tiran soldiers within Sagehold.",rewardGold=234000,rewardXP=6815,starts={{npcID=139102}},ends={{npcID=139102}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51798},questLines={{id=627,name="Death of a Tidesage",orderIndex=4,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=627,questLineOrder=12,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=627,questLineOrder=4}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
