[51830] = {id=51830,name="Zelling's Potential",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51797,51798,51805,51818,51819,51830,51837,52122,53066},description="<cough> My body won't last much longer, but Miss Voss insists I display what my powers truly are. I can instill within you a <cough> <wheeze> magical font that will absorb void essence from slain creatures. When the font is full, you can unleash devastating wind magic. Go to <cough> Port Fogtide. There you will find those tainted by the Void. Slay them, fill the font, and you will <wheeze> see my magic at work.",objectivesText="Fill Zelling's Void Font by slaying enemies in Port Fogtide and unleash his devastating wind magic. Progress: Is this <cough> enough for you?",rewardGold=234000,rewardXP=6815,starts={{npcID=139098}},ends={{npcID=139098}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51805,51818,51819},questLines={{id=627,name="Death of a Tidesage",orderIndex=5,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=627,questLineOrder=12,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=627,questLineOrder=4}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
