[51889] = {id=51889,name="The Wrath of Grapes",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=895,storyline={48770,51380,51889},description="You look familiar. Do you owe me money? Wait... no, that's not it. If you are here to learn, I could show you my secret mining technique, bu- Ugh... I'm a little busy trying to see straight right now. Ugh... it feels like someone is swinging a pick at my skull. The best cure for a hangover is pickle juice, a big greasy breakfast, and whatever I did not finish last night. Tell you what, get me those things, preferably quickly and quietly, and I will teach you whatever ya want.",objectivesText="Bring a Jar of Pickle Juice , a Mountain of Bacon , a Pile of Sausages , and a Hillock of Eggs to Franklin The Drunk . Progress: These shadows are loud. Can you fix that, too?",rewardItems={152512,152513,152579,160905,160995,160996,160997,160998,161078,161085,163836},starts={{npcID=139375}},ends={{npcID=139375}},mapCandidates={npc={},zone={8568}},questGiverID=139375,questTurnInID=139375,questType="standard",sourceQuests={51380},questLines={{id=771,name="8.0 Professions - Gathering - Mining - Kul Tiras - Storm Silver Seam - SCS",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
