[51961] = {id=51961,name="The Ongoing Campaign",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={53052},description="We have made excellent progress on Zandalar, <name>, but we must continue to expand our influence. It is time for us to cross the sea once again to exert pressure on enemy lands, lest they fall fully into Horde hands. Which location shall we secure next?",objectivesText="Use the Zandalar Campaign Map to choose a foothold.",rewardGold=255060,rewardXP=4790,rewardItems={159779,159910,160249,160433},starts={{npcID=135612}},ends={{npcID=135612}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={51967,53052},questLines={{id=624,name="The Zandalar Campaign",orderIndex=1,flags=0},{id=5374,name="The Zandalar Campaign",orderIndex=2,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=2,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=2,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=624,questLineOrder=3,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[51962] = {id=51962,name="Lumbering Away",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={51962,51964},description="The hardwoods in dis jungle are dense enough dat dey rival coal in terms of how much heat a skilled miner can get out of dem. The biggest problem using local timbers, however, is dat de jungle is always wet. If de wood is not stored properly, it takes weeks to dry out entirely. I bring dis up because my forge is starting to run low on fuel. Bring me some dry firewood to keep it going, and in exchange I will teach you a trick for mining monelite.",objectivesText="Collect 9 Pieces of Dry Firewood . Progress: Have you got more wood for me?",rewardItems={152512,152513,152579,160941,161078,161088,163837},starts={{npcID=122694}},ends={{npcID=122694}},mapCandidates={npc={1165},zone={8670}},questType="standard",questLines={{id=762,name="8.0 Professions - Gathering - Mining - Zandalar - Monelite Deposit - SCS",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[51963] = {id=51963,name="The Wrath of Vorrik",level=26,requiredLevel=26,faction="alliance",sharable=false,expansion=7,zoneID=8501,mapID=864,mapCandidates={npc={},zone={8501}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=100,objectID=135969,text="Faithless expunged"}},worldTaskTitle="The Wrath of Vorrik",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51964] = {id=51964,name="Insufferable Bloodsuckers",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=1165,storyline={51962,51964},description="<name>! I have some actual work that you could do for me. Since your mining skills are still not what Zandalari consider \"decent\", in exchange, I will show you how to mine monelite better. De blood trolls of Nazmir have dese enormous ticks that they keep as pets and I have heard dat dey have managed to get within de borders of Zuldazar to de north. Dis does not sit well with me. Thin their numbers for me, so I can happily die by being eaten by a pterrordax or something else respectable instead.",objectivesText="Kill 8 Bloodbelly Flyers and 8 Blood Trolls .",rewardItems={152512,152513,152579,161078,161088},starts={{npcID=122694}},ends={{npcID=122694}},mapCandidates={npc={1165},zone={8499}},questType="standard",sourceQuests={51962},questLines={{id=762,name="8.0 Professions - Gathering - Mining - Zandalar - Monelite Deposit - SCS",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[51965] = {id=51965,name="Lending a Hand",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={51965,51971},description="If you are looking for some work, I have something you can do. I went mining recently and a diemetradon managed to bite off my hand before I could get away from it. I do not care about the hand, I have already regenerated dat, but I did lose a couple rings dat I made. If you go get them back, I will show you how to harvest more monelite from a seam. Or not. I do not care, but if you were looking for a chance to finally impress me, dis could be it.",objectivesText="Retrieve Secott's Rings. Progress: For de record, those rings are worth more den your life. Empirically speaking, of course.",rewardGold=154900,rewardXP=710,rewardItems={152512,152513,152579,160943,161078,161088},starts={{npcID=122694}},ends={{npcID=122694}},mapCandidates={npc={1165},zone={8670}},questType="standard",questLines={{id=763,name="8.0 Professions - Gathering - Mining - Zandalar - Monelite Seam - SCS",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[51967] = {id=51967,name="Return to Boralus",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="I think that's enough excitement for today, <lad/lass>! Why don't ya get back ta Wyrmbane and tell the man we've got this place all under control. I'll make sure the blood trolls don't get any more of our folk! Ha!",objectivesText="Return to Halford Wyrmbane on the Wind's Redemption in Boralus Harbor. Desha Stormwallow can give you a ride.",rewardGold=25740,rewardXP=600,rewardItems={163653,163654,163655,163656,163657,163658,163659,163660,163661,163662,163663,163676},rewardChoices={163653,163654,163655,163656,163657,163658,163659,163660,163661,163662,163663,163676},rewardCurrencies={{id=1553,amount=250}},starts={{npcID=136432}},ends={{npcID=135612}},mapCandidates={npc={863,1161},zone={8500}},questType="standard",sourceQuests={52013},questLines={{id=603,name="Heart of Darkness",orderIndex=12,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=51,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=50,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=603,questLineOrder=5,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[51968] = {id=51968,name="Return to Boralus",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="You know, a lot has happened since you arrived in Zuldazar! I'm sure Mr. Wyrmbane would appreciate a report. Oh, not from me. Maybe somebody a bit more serious... like you! I bet Daria over here could get you back pretty quick!",objectivesText="Return to Halford Wyrmbane on the Wind's Redemption. Daria Smithson can give you a ride.",rewardGold=25740,rewardXP=600,rewardItems={159779,159910,160249,160433,163653,163654,163655,163656,163657,163658,163659,163660,163661,163662,163663,163676},rewardChoices={163653,163654,163655,163656,163657,163658,163659,163660,163661,163662,163663,163676},rewardCurrencies={{id=1553,amount=250}},starts={{npcID=135620}},ends={{npcID=135612}},mapCandidates={npc={862,1161},zone={8499}},questType="standard",sourceQuests={52003},questLines={{id=621,name="Mole Machinations",orderIndex=12,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=20,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=20,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=621,questLineOrder=4,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[51969] = {id=51969,name="Return to Boralus",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},description="Shatterstone Harbor is an expansive foothold, and one that we will use to great advantage against the Horde. I will leave Umbric and the others in charge here. Let's get back to the Wind's Redemption and return to Boralus.",objectivesText="Return to Halford Wyrmbane on the Wind's Redemption in Boralus.",rewardGold=25740,rewardXP=600,rewardItems={159958,160044,160045,163653,163654,163655,163656,163657,163658,163659,163660,163661,163662,163663,163676},rewardChoices={163653,163654,163655,163656,163657,163658,163659,163660,163661,163662,163663,163676},rewardCurrencies={{id=1553,amount=250}},starts={{npcID=137213}},ends={{npcID=135612}},mapCandidates={npc={864,1161},zone={8501}},questType="standard",sourceQuests={52008},questLines={{id=613,name="The Sands of Vol'dun",orderIndex=14,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=38,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=37,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=613,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
