[51971] = {id=51971,name="An Exquisite Brooch",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={51965,51971},description="You find a bloody brooch that features impeccable craftsmanship. The design and quality of work reminds you of rings you previously recovered for Secott. Perhaps this is another item he lost and would like to see returned.",objectivesText="Bring the Exquisitely Crafted Brooch to Secott. Provided item:",rewardItems={152512,152513,152579,160944,161078,161088},ends={{npcID=122694}},startObjects={{mapID=1165,x=0.44,y=0.39}},coords={mapID=1165,source="quest_giver",x=0.44,y=0.39},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={51965},questLines={{id=763,name="8.0 Professions - Gathering - Mining - Zandalar - Monelite Seam - SCS",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862,startItems={160944}},
