[51979] = {id=51979,name="The Ongoing Campaign",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51224,51231,51233,51234,51332,51340,51421,51435,51436,51437,51438,51439,51440,51441,51442,51526,51532,51536,51587,51643,51674,51675,51691,51696,51753,51800,51801,51802,51803,51916,51975,51979,51984,51985,51986,51987,52444,52451,52749,53050,53056,53064},series={53050},description="The Warchief wishes for us to continue spreading our influence throughout Kul Tiras. With our grip on Zandalar on the rise, now is the time to move forward with this objective in the lands of the enemy. Which location shall we secure next, <class>?",objectivesText="Use the Kul Tiras Campaign Map to choose a foothold.",rewardGold=257400,rewardXP=4790,starts={{npcID=135691}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51771},questLines={{id=623,name="The Kul Tiras Campaign",orderIndex=1,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=2,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=623,questLineOrder=4,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[51980] = {id=51980,name="WANTED: Jabra'kan",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51980},description="To any hunters worthy of the challenge: Find and defeat the troll known as Jabra'kan. His poaching ways have robbed Warbeast Kraal of valuable eggs, hides, and beasts for their pens. Seek out Wingrider Nivek for your reward.",objectivesText="Slay Jabra'kan the Poacher . Progress: If I see dat thieving wretch, I will wear his tusks for a necklace. Is it done?",rewardGold=772200,rewardXP=2125,rewardCurrencies={{id=1553,amount=115}},ends={{npcID=125486}},startObjects={{objectID=291291,mapID=862,x=0.69,y=0.409}},coords={mapID=862,source="quest_giver",x=0.69,y=0.405},mapCandidates={npc={862},zone={8499}},questType="group"},
[51981] = {id=51981,name="Earthcaller's Abode",expansion=7,mapID=942,questType="world",db2Objectives={{orderIndex=2,type=0,amount=5,objectID=139451,text="Binding Crystals Destroyed"}},worldTaskTitle="Earthcaller's Abode",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51982] = {id=51982,name="Storm's Rage",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={51982},description="Horde forces are pushing deeper into Stormsong Valley. We can not allow this aggression to go unchecked!",objectivesText="Repel the Horde forces assaulting Stormsong Valley. Progress: We cannot rest until the people of Stormsong Valley are protected from the Horde!",rewardXP=2125,rewardItems={165872,166459,166792},rewardCurrencies={{id=1717,amount=5},{id=1553,amount=400},{id=1560,amount=200}},starts={{npcID=135800}},ends={{npcID=135800}},mapCandidates={npc={942},zone={9042}},questGiverID=135800,questType="standard"},
