[51984] = {id=51984,name="Return to Zuldazar",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={51421,51435,51436,51437,51438,51439,51440,51441,51442,51975,51984},description="Look at dis place, boss-mon! We got da pirates, a location close to da Kul Tiran capital... I tink we should be bein' pretty proud of dis one. We should get goin' back and tell Nathanos about our success. Maybe we can even get him to crack a smile.",objectivesText="Return to Nathanos Blightcaller on the Banshee's Wail. Erul Dawnbrook can give you a ride.",rewardGold=25740,rewardXP=600,rewardItems={163664,163665,163666,163667,163668,163669,163670,163671,163672,163673,163674,163675,245465},rewardChoices={163664,163665,163666,163667,163668,163669,163670,163671,163672,163673,163674,163675},rewardCurrencies={{id=1553,amount=250}},starts={{npcID=137742}},ends={{npcID=135691}},mapCandidates={npc={862,895},zone={8567}},questType="standard",sourceQuests={51975},questLines={{id=622,name="A Pirate's Life for We",orderIndex=10,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=19,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=622,questLineOrder=7,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[51985] = {id=51985,name="Return to Zuldazar",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51224,51231,51233,51234,51332,51340,51985,51987},description="You know kid, I think I've got it all covered here. My guys will find all the Azerite they can here and make me rich! I mean, you know, make the Horde rich. With power! Anyway, you can go tell Nathanos we're done here. This base is the best place to launch any attacks against the Kul Tirans here in Drustvar -- that's a Gallywix guarantee!",objectivesText="Return to Nathanos Blightcaller on the Banshee's Wail. Swellthrasher in Anyport can give you a ride.",rewardGold=25740,rewardXP=600,rewardItems={163664,163665,163666,163667,163668,163669,163670,163671,163672,163673,163674,163675,245475},rewardChoices={163664,163665,163666,163667,163668,163669,163670,163671,163672,163673,163674,163675},rewardCurrencies={{id=1553,amount=250}},starts={{npcID=136683}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={51987},questLines={{id=604,name="Drustvar Foothold",orderIndex=7,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=27,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=604,questLineOrder=5,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[51986] = {id=51986,name="Return to Zuldazar",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51224,51231,51233,51234,51332,51340,51421,51435,51436,51437,51438,51439,51440,51441,51442,51526,51532,51536,51587,51643,51674,51675,51691,51696,51753,51800,51801,51802,51803,51916,51975,51979,51984,51985,51986,51987,52444,52451,52749,53050,53056,53064},series={51753},description="Warfang Hold is our most secured of the footholds we hold in Kul Tiras. Kaga and her forces will be able to keep fortifications running, thanks to you. The Alliance will never see us coming! Tell Nathanos that we have succeeded in our mission. I will help here until I am needed.",objectivesText="Return to Nathanos Blightcaller on the Banshee's Wail. Muka Stormbreaker can give you a ride.",rewardGold=25740,rewardXP=600,rewardItems={163664,163665,163666,163667,163668,163669,163670,163671,163672,163673,163674,163675,245473},rewardChoices={163664,163665,163666,163667,163668,163669,163670,163671,163672,163673,163674,163675},rewardCurrencies={{id=1553,amount=250}},starts={{npcID=138876}},ends={{npcID=135691}},mapCandidates={npc={862,942},zone={9042}},questType="standard",sourceQuests={51753},questLines={{id=614,name="Storming In",orderIndex=10,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=38,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=614,questLineOrder=6,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
