[51990] = {id=51990,name="Wings for the Kraal",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47226,47259,47261,47272,47310,47311,47312,47418,48527,48581,51990,51998},description="It seems your little one needs a moment to rest after dat adventure. I will look after it. If you want to make yourself useful while you wait, I heard de pterrordaxes to de north have been laying lots of eggs recently. Go collect de ones dat are wiggling and making noises. Dey are about to hatch. Our beasts breed well, but we always need more wings for de kraal.",objectivesText="Collect 8 Nearly-hatchling Pterrordax Eggs. Progress: Do you have de eggs I asked for?",rewardGold=257400,rewardXP=1415,rewardItems={150272,159146},starts={{npcID=121706}},ends={{npcID=121706}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47272,47311,47312},questLines={{id=5402,name="Warbeast Kraal",orderIndex=6,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[51991] = {id=51991,name="Charging the Batteries",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={50771,50775,50812,51991,52129},series={52129},description="These little fellas are ravenous whirlwinds of devouring destruction. When they get going, they consume anything in their path, without even stopping! When sated, they discharge power from them little 'lectric zingers on their heads! Then they nap. Lucky for us, we found just the right frequency to control their tiny bug brains. Hit that device, and you can take your own little zapper out for a spin... literally! Make sure ya bring it back full, so we can keep our rigs charged!",objectivesText="Fill that ranishu's belly. Progress: All juiced up?",rewardGold=257400,rewardXP=4115,starts={{npcID=140046}},ends={{npcID=140046}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={52129},questLines={{id=5421,name="For Profit",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[51995] = {id=51995,name="Vorrik's Vengeance",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=8501,mapID=864,mapCandidates={npc={},zone={8501}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=129763,text="Rakjan the Unbroken mounted"},{orderIndex=1,type=0,amount=50,objectID=135186,text="Faithless Slain"}},worldTaskTitle="Vorrik's Vengeance",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
