[51997] = {id=51997,name="Thar She Sinks",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8501,mapID=864,mapCandidates={npc={},zone={8501}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=139508,text="Stolen Canoe boarded"},{orderIndex=1,type=0,amount=6,objectID=139511,text="Canoes sunk"},{orderIndex=2,type=0,amount=3,objectID=139741,text="Cannons destroyed"},{orderIndex=3,type=0,amount=50,objectID=139629,text="Pirates slain"}},worldTaskTitle="Thar She Sinks",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[51998] = {id=51998,name="DGH: Now With Real Direhorn",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={47226,47259,47261,47272,47310,47311,47312,47418,48527,48581,51990,51998},description="...Listen, <name>. I need one more thing to finish making this supplement of mine. Direhorn Growth Hormone can't exactly be made without, you know, actual direhorn. But I floated the idea of harvesting a few of their beasts and all of a sudden I got a bunch of spears pointed at me. So I came up with another plan. Those flying beasts eat direhorns, right? The big green flappy ones. I'm sure if you kill a few of them you'll find all the direhorn bits I need.",objectivesText="Collect 8 Partially-Digested Direhorn Flesh. Progress: We'll keep this between you and me, okay?",rewardGold=257400,rewardXP=1415,rewardItems={159146,160975},starts={{npcID=122129}},ends={{npcID=122129}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47272,47311,47312},questLines={{id=5402,name="Warbeast Kraal",orderIndex=7,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
