[52012] = {id=52012,name="Wolves For The Den",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={52012},description="Our scouts have spotted a large pack of dire wolves not far from here. This is a good omen! We should send a beast master to capture the wolf pack and bring them to the outpost to be tamed. The dire wolves will make fine hunting companions and sniff out any Alliance spies that come poking around!",objectivesText="Complete the mission, \"Wolves For The Den.\"",rewardGold=23400,rewardXP=850,starts={{npcID=139561}},ends={{npcID=139561}},mapCandidates={npc={895},zone={8567}},questType="standard",startItems={160991}},
[52013] = {id=52013,name="Champion: John J. Keeshan",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},starts={{npcID=139609}},ends={{npcID=139609}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={51177},questLines={{id=603,name="Heart of Darkness",orderIndex=11,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=50,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=51,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=603,questLineOrder=5,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[52014] = {id=52014,name="Ritualistic Preparations",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={52014,52015},series={51568,51575},description="I have received a request for a shipment of storm silver. It is a fine metal, lightweight and resistant to corrosion. We use it althroughout our ships. It is so strong even de naga use it in some of their weapons! However, any parts that go into de ship have to be blessed by a wavesinger. I can not be bothered with dat nonsense. I do not believe it needs these extra blessings, but what do I know? Harvest a bucketful of ore and get it blessed for me, and I will teach you how to mine it easier.",objectivesText="Mine Unsanctified Storm Silver Ore , smelt it into Unsanctified Storm Silver Bars, and get them blessed by Wavesinger De'zan. Progress: Did you get those storm silver bars? Don't forget dat it needs to be blessed. Otherwise dey are 'land metal' and will curse a ship.",rewardItems={87216,152512,152513,152579,160440,160974,161078,161088,161133},starts={{npcID=122694}},ends={{npcID=122694}},mapCandidates={npc={1165},zone={8670}},questType="standard",questLines={{id=765,name="8.0 Professions - Gathering - Mining - Zandalar - Storm Silver Deposit - SCS",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[52015] = {id=52015,name="Brined Justice",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={52014,52015},description="<name>, I just got word dat one of our ships was attacked and a large amount of storm silver stolen! De sacred materials can not be replaced. Once it is blessed by de wavesinger, it is buried underwater for a year. While I do not care for such nonsense, others do, and will not sail on dat ship. From what I heard, a group of naga followed de ship to see where the metal was buried on de sea floor before killing de crew and taking her cargo. Kill de naga, and get me dat metal!",objectivesText="Collect 100 Stolen Storm Silver Bars . Progress: Loa damn de naga! Have you found de bars?",rewardItems={152512,152513,152579,160453,161078,161088},starts={{npcID=122694}},ends={{npcID=122694}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={52014},questLines={{id=765,name="8.0 Professions - Gathering - Mining - Zandalar - Storm Silver Deposit - SCS",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[52016] = {id=52016,name="Three Sheets to the Wind",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={52016,52017,52043},description="You want to know more about storm silver? Fine, if you are mining from a seam and make a mistake, you can make a deadly cloud of powderized metal. Now go. <After a moment Secott's face softens.> I am very busy, but if you insist on not dying, you should talk to my former apprentice, Biru. He is a drunk at Spirits Be With You, but he has some knowledge. Talk to Ximo, de Innkeeper, and buy him a drink. If he likes it, he'll talk, if not... well, I hope you have enough coin for more drinks.",objectivesText="Bring Biru The Drunk a drink he likes to learn his mining secrets. Progress: <Secott's former apprentice, Biru, drunkenly stares at you.> Whadda you wan?",rewardItems={152512,152513,152579,161078,161088,162574},starts={{npcID=122694}},ends={{npcID=139634}},mapCandidates={npc={1165},zone={8670}},questType="standard",questLines={{id=766,name="8.0 Professions - Gathering - Mining - Zandalar - Storm Silver Seam - SCS",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[52017] = {id=52017,name="Back to Biru",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={52016,52017,52043},description="Oh, you are still here? Well, I wish I could help you but being de only goldsmith in de city of gold, I am unsurprisingly busy. I heard you had built a rapport with Biru. I'm sure he remembers more, if you're still looking for more information. Ask him if he can show you anything else. Tell him if he keeps you from bothering me for the rest of de day, I will stop sending fool hardy miners to him.",objectivesText="Speak with Biru The Drunk .",rewardItems={152512,152513,152579,161078,161088},starts={{npcID=122694}},ends={{npcID=139634}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={52016},questLines={{id=766,name="8.0 Professions - Gathering - Mining - Zandalar - Storm Silver Seam - SCS",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[52023] = {id=52023,name="Informing the Horde",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=862,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="General Jakra'zet has been defeated, but his plan to summon Mythrax succeeded despite our best efforts. Were it not for the mercy of Sethraliss, I doubt we would have made it out of Atul'Aman alive. We must inform our allies of what has transpired in Vol'dun . I'll speak with princess Talanji myself. You should go and speak with the Horde. We need all the help we can get now. I'm sure our paths will cross again, <name>. It was an honor fighting with you.",objectivesText="Speak with Baine Bloodhoof .",rewardGold=772200,rewardXP=515,starts={{npcID=135133}},ends={{npcID=135133}},mapCandidates={npc={},zone={8670}},questGiverID=135133,questTurnInID=135133,questType="standard",sourceQuests={50702},questLines={{id=5391,name="Dunes of Vol'dun",orderIndex=64,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=862},
[52024] = {id=52024,name="Informing the Horde",level=30,requiredLevel=30,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=862,storyline={47313,47314,47315,47316,47317,47319,47320,47321,47324,47327,47513,47716,47874,47959,48313,48314,48315,48549,48550,48684,48715,48887,48888,48889,48894,48895,48896,48987,48988,48991,48992,48993,48996,49003,49005,49141,49327,49334,49340,49662,49664,49665,49666,49676,49677,50539,50550,50561,50617,50641,50702,50703,50745,50746,50748,50750,50751,50752,50770,50904,50913,51357,51364,51574,52023,52024},description="General Jakra'zet has been defeated, but his plan to summon Mythrax succeeded despite our best efforts. Were it not for the mercy of Sethraliss, I doubt we would have made it out of Atul'Aman alive. We must inform our allies of what has transpired in Vol'dun . I'll speak with princess Talanji myself. You should go and speak with the Horde. We need all the help we can get now. I'm sure our paths will cross again, <name>. It was an honor fighting with you.",objectivesText="Speak with Baine Bloodhoof.",rewardGold=772200,rewardXP=515,starts={{npcID=135133}},ends={{npcID=135133}},mapCandidates={npc={},zone={}},questGiverID=135133,questTurnInID=135133,questType="standard",sourceQuests={50702},questLines={{id=5391,name="Dunes of Vol'dun",orderIndex=65,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5391,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=862},
[52026] = {id=52026,name="Overseas Assassination",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={52026,52027,52028,52029,52030,52031,52032,52034,52035,52036,52038,52039,52040,52041,52042,52146},description="Ready to go to war, <name>? Mathias Shaw has assembled a list of priority Horde targets, and the first is an influential blood elf by the name of Arlethal Sunwatcher. Intelligence shows that he's the highest ranking member of the Reliquary, an elite blood elf excavation force. He's just standing out in the middle of the desert in Vol'dun, practically begging to be assassinated. Shall we?",objectivesText="Speak with Grand Admiral Jes-Tereth to sail to Vol'dun.",rewardGold=234000,rewardXP=6815,rewardItems={158075,161086,161087,161240,161241,161333,172812},starts={{npcID=135612}},ends={{npcID=139705}},mapCandidates={npc={864,1161},zone={8568}},questType="standard",questLines={{id=628,name="Blood on the Sand",orderIndex=0,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=628,questLineOrder=9,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=628,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[52027] = {id=52027,name="The Vol'dun Plan",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={52026,52027,52028,52029,52030,52031,52032,52034,52035,52036,52038,52039,52040,52041,52042,52146},description="Our target: Arlethal Sunwatcher, High Examiner of the Reliquary. Before we charge off blindly into the dunes, however, I'd like to hold a quick strategy meeting with you and the others.",objectivesText="Discuss strategy with Halford Wyrmbane and Shandris Feathermoon. Progress: Let's talk strategy, <name>.",rewardGold=234000,rewardXP=6815,rewardItems={161086,161087,161240,161241,161333},starts={{npcID=139705}},ends={{npcID=139705}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={52026},questLines={{id=628,name="Blood on the Sand",orderIndex=1,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=628,questLineOrder=9,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=628,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[52028] = {id=52028,name="Comb the Desert",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={52026,52027,52028,52029,52030,52031,52032,52034,52035,52036,52038,52039,52040,52041,52042,52146},description="It's time to mobilize, then. I'll stick with you, <name>. Keep an eye out for Horde activity.",objectivesText="Search Vol'dun for Horde activity.",rewardGold=234000,rewardXP=6815,rewardItems={161086,161087,161240,161241,161333},starts={{npcID=139705}},ends={{npcID=139719}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={52027},questLines={{id=628,name="Blood on the Sand",orderIndex=2,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=628,questLineOrder=9,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=628,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[52029] = {id=52029,name="Dirty Work",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={52026,52027,52028,52029,52030,52031,52032,52034,52035,52036,52038,52039,52040,52041,52042,52146},description="That surveyor is wearing a Reliquary tabard. Sunwatcher must be hiring goblins to do his dirty work while he lounges somewhere in the shade. <Shandris nocks an arrow in her bow.> Let's find out what she knows.",objectivesText="Slay Nazlara and find out what she knows. Progress: What is that goblin up to?",rewardGold=234000,rewardXP=6815,rewardItems={161086,161087,161240,161241,161333},starts={{npcID=139719}},ends={{npcID=139705}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={52028},questLines={{id=628,name="Blood on the Sand",orderIndex=3,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=628,questLineOrder=9,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=628,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[52030] = {id=52030,name="Keep Combing",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={52026,52027,52028,52029,52030,52031,52032,52034,52035,52036,52038,52039,52040,52041,52042,52146},description="Guzbert will be busy planting explosives for a while. We should continue south, looking for more signs of the Horde.",objectivesText="Search for more signs of the Horde.",rewardGold=234000,rewardXP=6815,rewardItems={161086,161087,161240,161241,161333},starts={{npcID=139705}},ends={{npcID=139719}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={52029},questLines={{id=628,name="Blood on the Sand",orderIndex=4,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=628,questLineOrder=9,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=628,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[52031] = {id=52031,name="Classic Reliquary",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={52026,52027,52028,52029,52030,52031,52032,52034,52035,52036,52038,52039,52040,52041,52042,52146},description="Another goblin surveyor, and this one's reporting to a blood elf overseer of some sort. We're closing in on them, <name>. You know the drill.",objectivesText="Help Shandris assassinate Elisa Veilsong and Daxx Bombhand, then find out what they know. Progress: Sunwatcher will be ours soon.",rewardGold=234000,rewardXP=6815,rewardItems={161086,161087,161240,161241,161333},starts={{npcID=139719}},ends={{npcID=139705}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={52030},questLines={{id=628,name="Blood on the Sand",orderIndex=5,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=628,questLineOrder=9,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=628,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[52032] = {id=52032,name="Never Stop Combing",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={52026,52027,52028,52029,52030,52031,52032,52034,52035,52036,52038,52039,52040,52041,52042,52146},description="<Halford eyes the map one last time before folding it up.> Onward to the south, then.",objectivesText="Continue searching for signs of the Horde.",rewardGold=234000,rewardXP=6815,rewardItems={161086,161087,161240,161241,161333},starts={{npcID=139705}},ends={{npcID=139705}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={52031},questLines={{id=628,name="Blood on the Sand",orderIndex=6,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=628,questLineOrder=9,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=628,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[52033] = {id=52033,name="WANTED: The Rime Huntress",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={52033},description="The Waycrest Guard is offering a reward for any hunter who can track down and eliminate the Rime Huntress from the vicinity of Highroad Pass. Track her with caution. She is a ferocious beast, and has been known to ambush even seasoned hunters.",objectivesText="Defeat The Rime Huntress near Highroad Pass.",rewardGold=514800,rewardXP=3455,rewardCurrencies={{id=1553,amount=115}},ends={{npcID=139714}},startObjects={{objectID=292523,mapID=896,x=0.412,y=0.409}},coords={mapID=896,source="quest_giver",x=0.372,y=0.494},mapCandidates={npc={896},zone={8721}},questType="group",sourceQuests={48622}},
[52034] = {id=52034,name="A Message to the Zandalari",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={52026,52027,52028,52029,52030,52031,52032,52034,52035,52036,52038,52039,52040,52041,52042,52146},description="I know we're here to hunt the Horde, but this is an opportunity. Exiles or not, these are Zandalari trolls, and the Zandalari have all but put in their lot with the Horde. Let's show them what we do to friends of the Horde.",objectivesText="Slay 12 Zandalari Exiles .",rewardGold=234000,rewardXP=6815,rewardItems={161086,161087,161240,161241,161333},starts={{npcID=139719}},ends={{npcID=139719}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={52032},questLines={{id=628,name="Blood on the Sand",orderIndex=7,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=628,questLineOrder=9,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=628,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[52035] = {id=52035,name="Improvised Survival",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={52026,52027,52028,52029,52030,52031,52032,52034,52035,52036,52038,52039,52040,52041,52042,52146},description="The entirety of our copter's hold was reserved for bombs. There's actually still a lot of bombs left inside. Unfortunately, that meant that we weren't able to pack sufficient water and rations for our survival. Desert natives hoard supplies efficiently. I'm certain the Zandalari trolls up ahead wouldn't miss a few lost supplies.",objectivesText="Gather 15 Zandalari Water Jugs and 15 Zandalari Rations. Progress: <Halford nods sternly at you.>",rewardGold=234000,rewardXP=6815,rewardItems={161086,161087,161240,161241,161333},starts={{npcID=139705}},ends={{npcID=139705}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={52032},questLines={{id=628,name="Blood on the Sand",orderIndex=8,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=628,questLineOrder=9,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=628,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[52036] = {id=52036,name="They Have Alpacas Here",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={52026,52027,52028,52029,52030,52031,52032,52034,52035,52036,52038,52039,52040,52041,52042,52146},description="Did you see? Did you see them? The floofy alpacas?! I'VE ALWAYS WANTED A... I mean, ahh, ahem! I would like to acquire an alpaca. To study. For scientific reasons. Nothing to do with floofiness at all. Here, this should help you wrangle one back here.",objectivesText="Use the Ultra-Safe Electrified Alpaca Lasso to obtain a Lost Alpaca, then bring it back to Explosioneer Zoidfuse . Progress: So... floofy...",rewardGold=234000,rewardXP=6815,rewardItems={161086,161087,161240,161241,161333},starts={{npcID=139722}},ends={{npcID=139722}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={52032},questLines={{id=628,name="Blood on the Sand",orderIndex=9,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=628,questLineOrder=9,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=628,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[52038] = {id=52038,name="Splitting Up",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={52026,52027,52028,52029,52030,52031,52032,52034,52035,52036,52038,52039,52040,52041,52042,52146},description="<Halford looks over the map again.> The final Reliquary digsite is southwest of here. <name>, you and Shandris are responsible for laying the explosives at the digsite. I'll work with Zoidfuse to establish a safe position to detonate from.",objectivesText="Continue traveling southwest across the desert.",rewardGold=234000,rewardXP=6815,rewardItems={161086,161087,161240,161241,161333,232762,232763},starts={{npcID=139705}},ends={{npcID=139719}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={52034,52035,52036},questLines={{id=628,name="Blood on the Sand",orderIndex=10,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=628,questLineOrder=9,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=628,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[52039] = {id=52039,name="Delayed Deathification",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={52026,52027,52028,52029,52030,52031,52032,52034,52035,52036,52038,52039,52040,52041,52042,52146},description="While we can handle the assassination portion on our own, I suppose there's no harm in distributing these gnomish bombs around the enemy's digsite. They're designed to be detonated remotely, so try to bury them in the sand where they won't be noticed.",objectivesText="Bury 8 Remote-Detonation Deathbombs . Progress: I hope you left them somewhere inconspicuous.",rewardGold=234000,rewardXP=6815,rewardItems={161086,161087,161240,161241,161333},starts={{npcID=139719}},ends={{npcID=139719}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={52038},questLines={{id=628,name="Blood on the Sand",orderIndex=11,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=628,questLineOrder=9,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=628,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[52040] = {id=52040,name="Full of Arrows",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={52026,52027,52028,52029,52030,52031,52032,52034,52035,52036,52038,52039,52040,52041,52042,52146},description="There's no need for Halford's overly-complicated desert explosion operation. We can take care of Arlethal Sunwatcher right here and now. He's right over there. We can just... kill him. You engage him. I'll join in when he least expects it. You ready?",objectivesText="Slay Arlethal Sunwatcher with Shandris. Progress: Whenever you're ready, <name>.",rewardGold=234000,rewardXP=6815,rewardItems={161086,161087,161240,161241,161333},starts={{npcID=139719}},ends={{npcID=139719}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={52038},questLines={{id=628,name="Blood on the Sand",orderIndex=12,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=628,questLineOrder=9,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=628,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[52041] = {id=52041,name="Report to Wyrmbane",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={52026,52027,52028,52029,52030,52031,52032,52034,52035,52036,52038,52039,52040,52041,52042,52146},description="Our work here is done. Halford and Zoidfuse should be further down the coast, to the east. If you don't mind, I'll meet you there.",objectivesText="Report to Halford Wyrmbane in Vol'dun.",rewardGold=234000,rewardXP=6815,rewardItems={161086,161087,161240,161241,161333},starts={{npcID=139719}},ends={{npcID=139705}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={52039,52040},questLines={{id=628,name="Blood on the Sand",orderIndex=13,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=628,questLineOrder=9,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=628,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[52042] = {id=52042,name="The Big Boom",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={52026,52027,52028,52029,52030,52031,52032,52034,52035,52036,52038,52039,52040,52041,52042,52146},description="Still, we've placed all those explosives, and there's nothing stopping us from detonating them and laying waste to the Horde's excavations. Speak with Zoidfuse when you're ready, and we'll get this explosive gnome tech going!",objectivesText="Speak with Explosioneer Zoidfuse to initiate the Vol'dun Explosion Protocol. Progress: Whenever you're ready.",rewardGold=234000,rewardXP=6815,rewardItems={161086,161087,161240,161241,161333},starts={{npcID=139705}},ends={{npcID=139705}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={52041},questLines={{id=628,name="Blood on the Sand",orderIndex=14,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=628,questLineOrder=9,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=628,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[52043] = {id=52043,name="The Wrath of Grapes",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={52016,52017,52043},description="You look familiar. Do you owe me money? Wait... no, that's not it. If you are here to learn, I could show you my secret mining technique, bu- Ugh... I am currently busy trying to see straight right now, amongst other things. Ugh... it feels like someone is swinging a pick at my skull. De best cure for a hangover is pickle juice and a big greasy breakfast. Tell you what, get me those things, preferably quickly and quietly, and I will teach you whatever want.",objectivesText="Bring a Jar of Pickle Juice , a Mountain of Bacon , a Pile of Sausages , and a Hillock of Eggs to Biru The Drunk . Progress: Dese shadows are loud. Can you fix dat, too?",rewardItems={152512,152513,152579,160995,160996,160997,160998,161078,161088},starts={{npcID=139634}},ends={{npcID=139634}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={52017},questLines={{id=766,name="8.0 Professions - Gathering - Mining - Zandalar - Storm Silver Seam - SCS",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[52044] = {id=52044,name="An Exceptional Platinum Shard",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={52044,52049,52050},description="Out of dumb luck, you've managed to extract an exceptionally large shard of platinum, instead of several smaller chunks. You wonder to yourself if Myra could teach you to harvest this much every time.",objectivesText="Bring the Exceptional Platinum Shard to Myra Cabot . Provided item:",rewardItems={152512,152513,152579,153431,160905,161078,161085},ends={{npcID=136091}},mapCandidates={npc={1161},zone={8568}},questType="standard",questLines={{id=769,name="8.0 Professions - Gathering - Mining - Kul Tiras - Platinum Deposit - SCS",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895,startItems={161078}},
[52045] = {id=52045,name="Boarder Patrol",expansion=7,mapID=942,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=134542,text="Ride an Ornery Battleboar"},{orderIndex=1,type=0,amount=50,objectID=134693,text="Briarback quilboar slain"}},worldTaskTitle="Boarder Patrol",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[52046] = {id=52046,name="An Exceptional Platinum Shard",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={52046,52053,52055},description="Out of dumb luck, you've managed to extract an exceptionally large shard of platinum, instead of several smaller chunks. You wonder to yourself if Secott could teach you to harvest this much every time.",objectivesText="Bring the Exceptional Platinum Shard to Secott the Goldsmith . Provided item:",rewardItems={152512,152513,152579,161078,161079,161088},ends={{npcID=122694}},coords={mapID=1165,source="quest_giver",x=0.44,y=0.39},mapCandidates={npc={1165},zone={8670}},questType="standard",questLines={{id=764,name="8.0 Professions - Gathering - Mining - Zandalar - Platinum Deposit - SCS",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862,startItems={161079}},
[52047] = {id=52047,name="Against the Storm",expansion=7,mapID=895,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Monastic Rituals disrupted"}},worldTaskTitle="Against the Storm",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[52049] = {id=52049,name="X Marks the Plat!",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={52044,52049,52050},description="You find a folded piece of aged paper next to the deposit Opening it up, you find a map of Drustvar with an X along the western coast. Several crude poems adorn the paper, with one in particular drawing your attention. \"Once I were a pirate, livin' for rum and pleasure. Since the mutiny, I've retired, an' now I mine for treasure.\" Whoever left this appears to have spent a significant time mining in these lands. They may have some insights you could benefit from.",objectivesText="Find the Tattered Map 's maker in Drustvar. Provided item:",rewardItems={152512,152513,152579,153431,160905,161078,161085},ends={{npcID=139746}},coords={mapID=896,source="quest_giver",x=0.198,y=0.445},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={52044},questLines={{id=769,name="8.0 Professions - Gathering - Mining - Kul Tiras - Platinum Deposit - SCS",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896,startItems={161085}},
[52050] = {id=52050,name="A More Challenging Career",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={52044,52049,52050},description="As ye can imagine, piratin' be in me blood. Spent many of the best years of me life lootin' and plunderin'. Me favorite part was when takin' a chest filled ta the brim with gold and jewels, and buryin' it where only ye know. Alas, that life be too chaotic for me nowadays. Swashbucklin' makes me tired, and grog makes me sick. But... I can still bury me treasure. Bring me some booty worth buryin', and I'll teach ya everythin' I've learned about minin' over the years. So, wanna be me scallywag?",objectivesText="Collect 20 Platinum Nuggets . Progress: The winds be fine for adventure!",rewardItems={152512,152513,152579,153431,160905,161078,161082,161085},starts={{npcID=139746}},ends={{npcID=139746}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={52049},questLines={{id=769,name="8.0 Professions - Gathering - Mining - Kul Tiras - Platinum Deposit - SCS",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[52051] = {id=52051,name="LFGDungeons - BFA - Raid Finder - 1st",level=50,requiredLevel=50,faction="none",categories={},flags={},sharable=false,expansion=7,storyline={52051},rewardGold=2340000,rewardCurrencies={{id=1553,amount=350}},mapCandidates={npc={},zone={}},questType="standard"},
[52053] = {id=52053,name="The Platinum Map",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={52046,52053,52055},description="Nestled within the fissures of the deposit, you find a small disc of pure platinum. Dusting it off, you see etchings in its surface and recognize it as a map of Vol'dun. You also notice what appears to be a small cave in the south west that has been circled. Whoever left this apparently has a wealth of knowledge of the metal and wants to be found.",objectivesText="Find the Platinum Map 's maker in Vol'dun. Provided item:",rewardItems={152512,152513,152579,161078,161088},ends={{npcID=139792}},coords={mapID=864,source="quest_giver",x=0.276,y=0.698},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={52046},questLines={{id=764,name="8.0 Professions - Gathering - Mining - Zandalar - Platinum Deposit - SCS",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864,startItems={161088}},
[52054] = {id=52054,name="Too Much To Bear",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={52054},objectivesText="Injured Hunters healed",rewardItems={161114},mapCandidates={npc={},zone={9042}},questType="world",db2Objectives={{text="Injured Hunters healed",amount=7,type=0,objectID=139802,orderIndex=1}},worldTaskTitle="Too Much To Bear",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[52055] = {id=52055,name="An Ore for an Eye",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={52046,52053,52055},description="I have one last request before I can go. I wish to see de sunset one last time. I have an enchantment in mind, and I have all the materials I need except de metal. I need you to bring me twenty platinum nuggets . I have asked de spirits to bring me de ore, but dey do not listen to me anymore. Dat is why I hid de map where only someone who could be of help would find it. If you help me out, I will teach you what I can about mining platinum.",objectivesText="Collect 20 Platinum Nuggets . Progress: De elements beckon me. Do you have de platinum nuggets ?",rewardItems={152512,152513,152579,161078,161082,161088},starts={{npcID=139792}},ends={{npcID=139792}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={52053},questLines={{id=764,name="8.0 Professions - Gathering - Mining - Zandalar - Platinum Deposit - SCS",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[52056] = {id=52056,name="The Tendrils of Fate",expansion=7,mapID=895,questType="world",worldTaskTitle="The Tendrils of Fate",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[52057] = {id=52057,name="Against the Storm",expansion=7,mapID=895,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Monastery damaged"}},worldTaskTitle="Against the Storm",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[52058] = {id=52058,name="A Short-Lived Peace",level=10,requiredLevel=10,faction="alliance",categories={},flags={"loremaster"},sharable=false,expansion=7,zoneID=1519,mapID=84,storyline={52058,52060,52062,52072,52116,52197,52234,52240,52242,52245,52256,52257,52279,52973,52974,52975,52977,53095,53310,53551,53616,53617,53619,53621,53622},series={52060,52062,52072,52116,53616},description="<name>, As the Legion's presence wanes from our world, a new threat has risen. It is with a heavy heart that I must ask you to put your life on the line for the Alliance once more. I have received a disturbing message from our operatives stationed in Orgrimmar. I await your arrival at Stormwind Keep to discuss matters further.",objectivesText="Report to King Anduin Wrynn in Stormwind Keep.",rewardGold=200,rewardXP=175,rewardItems={157832},starts={{npcID=107574}},ends={{npcID=107574}},mapCandidates={npc={84},zone={1519}},questType="standard",questLines={{id=637,name="The Warchief's Command",orderIndex=0,flags=0}},db2DetailThemeID=6,db2PoiUiMapID=84},
[52059] = {id=52059,name="Thar She Sinks",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=8501,mapID=864,mapCandidates={npc={},zone={8501}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=139508,text="Stolen Canoe boarded"},{orderIndex=1,type=0,amount=6,objectID=139511,text="Canoes sunk"},{orderIndex=2,type=0,amount=3,objectID=139741,text="Cannons destroyed"},{orderIndex=3,type=0,amount=50,objectID=139629,text="Pirates slain"}},worldTaskTitle="Thar She Sinks",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[52060] = {id=52060,name="The Horde Uprising",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=1519,mapID=84,storyline={52058,52060,52062,52072,52116,52197,52234,52240,52242,52245,52256,52257,52279,52973,52974,52975,52977,53095,53310,53551,53616,53617,53619,53621,53622},series={52058,52062,52072,52116,53616},description="Given the potential of Azerite to change the face of warfare, it comes as no surprise that the Warchief seeks to lay claim to it. Reports indicate that she is mobilizing an army to march on Silithus--the site of the great wound. Heroes of the Horde and the Alliance fought side-by-side during the Argus campaign. To think that Sylvanas is ready to cast that unity aside... Speak with Mathias Shaw. I want you to oversee our presence in Silithus.",objectivesText="Report to Master Mathias Shaw for further instruction.",rewardGold=200,rewardXP=175,rewardItems={157832},starts={{npcID=107574}},ends={{npcID=139798}},mapCandidates={npc={84},zone={1519}},questType="standard",sourceQuests={52058},questLines={{id=637,name="The Warchief's Command",orderIndex=1,flags=0}},db2PoiUiMapID=84},
[52061] = {id=52061,name="Taptaf the Pig!",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={52061},rewardItems={161081},starts={{npcID=139380},{npcID=139770}},ends={{npcID=139380}},mapCandidates={npc={896},zone={8721}},questType="standard"},
[52062] = {id=52062,name="A Disturbance in Ashenvale",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=1519,mapID=84,storyline={52058,52060,52062,52072,52116,52197,52234,52240,52242,52245,52256,52257,52279,52973,52974,52975,52977,53095,53310,53551,53616,53617,53619,53621,53622},series={52058,52060,52072,52116,53616},description="The damned Horde! Clever bastards, I'll give them that. They diverted at the north fork of the Barrens and are now marching on Ashenvale. The kaldorei forces already set sail for Silithus--must be halfway there by now. The only defenders still in the area are the Darnassian City Guard. They are en route to Astranaar, but they won't last long against an army. Their commander goes by the name of Delaryn Summermoon. Find her, <name>, and buy us time. We will get our fleet there as soon as we can.",objectivesText="Report to Captain Delaryn Summermoon in Astranaar.",rewardGold=1000,rewardXP=710,starts={{npcID=139798}},ends={{npcID=134578}},mapCandidates={npc={57,84},zone={1519}},questType="standard",sourceQuests={52060},questLines={{id=637,name="The Warchief's Command",orderIndex=2,flags=0}},db2PoiMapID=1,db2PoiUiMapID=63},
[52063] = {id=52063,name="Boarder Patrol",expansion=7,mapID=942,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=134542,text="Ride an Ornery Battleboar"},{orderIndex=1,type=0,amount=50,objectID=134693,text="Briarback quilboar slain"}},worldTaskTitle="Boarder Patrol",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[52064] = {id=52064,name="Fiendish Fields",expansion=7,mapID=942,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=132297,text="Seize the Repaired Farmhand"}},worldTaskTitle="Fiendish Fields",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[52065] = {id=52065,name="Worse Than It Looks",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={52065},description="As bad as things are here we're managing to hold on. Things are actually a lot worse at Beacon Hill. They're closer to the main attack, and will need all the help they can get. Head there and see if you can help.",objectivesText="Speak to Felicia Gladstone at Beacon Hill",rewardGold=25740,rewardXP=515,starts={{npcID=135682}},ends={{npcID=138735}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50908,50909,50910},nextQuests={51752}},
[52067] = {id=52067,name="Survivors",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={52067},description="Patrick and Daryl Eckhart have a place north of town. If I know them, they'll be taking in survivors from Brennadam. Check in with Patrick and see if they need any help.",objectivesText="Speak to Patrick Eckhart at the Eckhart Lodge.",rewardGold=25740,rewardXP=515,rewardItems={23389,25778,25779,25780},starts={{npcID=130190}},ends={{npcID=135682}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49755},nextQuests={50908,50909,50910}},
[52068] = {id=52068,name="Helping Out, Somewhere Else",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={52068},description="You've been a big help and now we've got a lot of gold to divvy up! You should go west to Seabreeze Village. Treat it like a vacation, keep your mind off the gold. We'll be fine here. When you come back later, we'll have your share all ready for you. You'd just be getting in the way here.",objectivesText="Speak to Lieutenant Bauer at Seabreeze Village.",rewardGold=25740,rewardXP=515,starts={{npcID=134720}},ends={{npcID=131002}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50742},nextQuests={50614}},
[52069] = {id=52069,name="More Fodder",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={52069},description="Leo Shealds at Deadwash is a crook, but he recognizes the threat the naga pose. He'll send men to help us if we ask, even if most are just fodder. Travel to Deadwash and ask for help.",objectivesText="Speak to Leo Shealds at Deadwash.",rewardGold=25740,rewardXP=515,starts={{npcID=131343}},ends={{npcID=134720}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49831},nextQuests={50802,50810}},
[52070] = {id=52070,name="Bauer Backup",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={52070},description="We've not heard anything from the coast since the Horde attack started. I need you to check in on Lieutenant Bauer at Seabreeze Village and see that they're safe.",objectivesText="Speak to Lieutenant Bauer at Seabreeze Village.",rewardGold=24570,rewardXP=515,starts={{npcID=138735}},ends={{npcID=131002}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={51712},nextQuests={50614}},
[52071] = {id=52071,name="Briarback Mountain",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=9562,mapID=942,storyline={52071},objectivesText="Battle-Piglets borrowed",rewardItems={161123},mapCandidates={npc={},zone={9562}},questType="world",db2Objectives={{text="Battle-Piglets borrowed",amount=8,type=0,objectID=134014,orderIndex=1}},worldTaskTitle="Briarback Mountain",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[52072] = {id=52072,name="The Light of Elune",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=1657,mapID=57,storyline={52058,52060,52062,52072,52116,52197,52234,52240,52242,52245,52256,52257,52279,52973,52974,52975,52977,53095,53310,53551,53616,53617,53619,53621,53622},series={52058,52060,52062,52116,53616},description="My sisters lie slain on the soft earth of Ashenvale. We are trained to expect losses. Soldiers die in battle. But this... this was a despicable attack, even for the Horde. We have little time to grieve, but we are not savages like our enemy. Please, <name>. Help me say a prayer to Elune in honor of the fallen. Their wisps deserve the light of her blessing.",objectivesText="Honor the bodies of the fallen soldiers in Astranaar.",rewardGold=2000,rewardXP=1415,starts={{npcID=134578}},ends={{npcID=134578}},mapCandidates={npc={57},zone={1657}},questType="standard",sourceQuests={52062},questLines={{id=637,name="The Warchief's Command",orderIndex=3,flags=0}},db2PoiMapID=1,db2PoiUiMapID=63},
[52073] = {id=52073,name="Petitioning Krag'wa",level=20,requiredLevel=20,faction="horde",sharable=false,expansion=7,zoneID=8500,mapID=863,description="Nothing! I cannot believe de weapon had no effect! Damn Ateena and her dark magic! We must get up there somehow, kill her for good, and remove dat barrier! But how can we get to de top of dat building... ah, of course! Krag'wa! De loa of frogs hates de blood trolls. I am sure he will lend us his aid. Then, finally, we will be able to put an end to Ateena's madness.",rewardGold=25740,rewardXP=345,starts={{npcID=133125}},ends={{npcID=133476}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={50082},questLines={{id=524,name="Bleeding the Blood Trolls",orderIndex=7,flags=0},{id=5390,name="Lost in Nazmir",orderIndex=83,flags=0}},campaigns={{id=226,title="Battle for Azeroth",questLineID=5390,questLineOrder=1}}},
[52074] = {id=52074,name="Deliverance",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48179,48180,48182,48183,52074,52075,53110},description="Mainlander! Stop a moment, I could really use a hand! My team and I were hunting in the ruins of Gol Koval when the stones began to attack us! I've never seen anything like that before. Ranger Wons sent Duke and I to get some medical supplies for our injured. Duke didn't get hit by those possessed stone monsters but he wasn't as fortunate with the spiders nearby. He'll be okay if he rests here for awhile, but my team needs these medical supplies! Please take these to Ranger Wons !",objectivesText="Bring supplies to Ranger Encampment in Gol Koval. Provided item:",rewardGold=257400,rewardXP=2765,rewardItems={67174,67191,67208,67222,161124},starts={{npcID=125457}},ends={{npcID=139912}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48947},questLines={{id=5441,name="Drustvar Ruins",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[52075] = {id=52075,name="Boned",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48179,48180,48182,48183,52074,52075,53110},description="If the living rocks weren't bad enough, it seems the undead are hauling themselves out of the ground, too! This used to be a Drust settlement, so those are probably Drust bones. They hated us and the feeling is definitely mutual right now. I don't know what has them stirred up, but they're a danger to us and everyone else. Take them out and I'll reward you for the work.",objectivesText="Defeat 8 Vengeful Bones .",rewardGold=241020,rewardXP=2765,starts={{npcID=139912}},ends={{npcID=139912}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={52074},questLines={{id=5441,name="Drustvar Ruins",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[52113] = {id=52113,name="Vol'jin, Son of Sen'jin",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51513,51514,51515,51516,51517,51533,52113,52114},series={51516,51517},description="Even in da Echo Isles we have heard of da traditions of da Golden Road. We must walk in da presence of royalty and hail da accomplishments of Vol'jin so dat his spirit be welcome here amongst da ancient kings. I shall carry da ashes, if you light da fires. Know that any member of any other tribe may contest us. As our champion, we will need you to fend them off if they do.",objectivesText="Escort Vol'jin's Ashes to Atal'Dazar.",rewardGold=234000,rewardXP=6815,starts={{npcID=139928}},ends={{npcID=138138}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={52114},questLines={{id=734,name="The Fallen Chieftain",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[52114] = {id=52114,name="Honoring a True Leader",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6453,mapID=463,storyline={51513,51514,51515,51516,51517,51533,52113,52114},description="Vol'jin. I have often felt our old chieftain's spirit whisperin' to me. His strength was da lifeblood of da Darkspear tribe. Some would even say he was da spirit of da true Horde. Princess Talanji's offer is a great one. I shall travel with Vol'jin's ashes to Atal'Dazar. If ya be wishin' to join us for dis procession, meet us upon da famed Golden Road.",objectivesText="Meet Master Gadrin at the Golden Road in Zuldazar.",rewardGold=23400,rewardXP=850,starts={{npcID=137878}},ends={{npcID=139928}},mapCandidates={npc={463,862},zone={6453}},questType="standard",sourceQuests={51515},questLines={{id=734,name="The Fallen Chieftain",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[52115] = {id=52115,name="In the Shadow of the Kraken",expansion=7,mapID=942,questType="world",worldTaskTitle="In the Shadow of the Kraken",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[52116] = {id=52116,name="A Soft Glow",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=148,mapID=57,storyline={52058,52060,52062,52072,52116,52197,52234,52240,52242,52245,52256,52257,52279,52973,52974,52975,52977,53095,53310,53551,53616,53617,53619,53621,53622},series={52058,52060,52062,52072,53616},description="The wisps... they sing with sorrow, but also with purpose. The forest stirs, aglow with their light. That sound... in the distance. Could it be our Shan'do? Quickly, <name>! Malfurion beckons!",objectivesText="Find Malfurion in Ashenvale.",rewardGold=200,rewardXP=175,starts={{npcID=134578}},ends={{npcID=133693}},mapCandidates={npc={57,62},zone={148}},questType="standard",sourceQuests={52072,53616},questLines={{id=637,name="The Warchief's Command",orderIndex=5,flags=0}},db2PoiMapID=1,db2PoiUiMapID=62},
[52117] = {id=52117,name="Briarback Mountain",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=9562,mapID=942,storyline={52117},objectivesText="Battle-Piglets borrowed",rewardItems={161123},mapCandidates={npc={},zone={9562}},questType="world",db2Objectives={{text="Battle-Piglets borrowed",amount=8,type=0,objectID=134014,orderIndex=1}},worldTaskTitle="Briarback Mountain",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[52118] = {id=52118,name="Cutting Out the Competition",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9734,storyline={52118},description="I've never cared much for battle, but I'll be damned if those fiends think they're gettin' this mill. Best if we clear the area quickly. Grab an axe and show me what you got.",objectivesText="Pick up a Sturdy Axe , then gather 5 Freshly-Chopped Wood from the nearby Sapling. Progress: What're you waiting for?",rewardGold=105000,rewardXP=3410,rewardItems={156531,161130},rewardCurrencies={{id=1540,amount=10}},starts={{npcID=139446}},ends={{npcID=139446}},mapCandidates={npc={},zone={9734}},questGiverID=139446,questTurnInID=139446,questType="standard"},
