[52122] = {id=52122,name="To Be Forsaken",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={51797,51798,51805,51818,51819,51830,51837,52122,53066},description="Let's move. Zelling is probably with his family now. Either they're happily reunited and he helps us find Valentine... or he just helps us find Valentine. Let's go.",objectivesText="Go with Lilian Voss to find Thomas Zelling.",rewardGold=117000,rewardXP=3410,rewardItems={245469},rewardCurrencies={{id=1553,amount=800}},starts={{npcID=139101}},ends={{npcID=135691}},mapCandidates={npc={862,942},zone={9042}},questType="standard",sourceQuests={51837},questLines={{id=627,name="Death of a Tidesage",orderIndex=7,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=627,questLineOrder=12,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=627,questLineOrder=4}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
