[52127] = {id=52127,name="The Wolf's Den",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=862,storyline={52127},series={52005},description="The raid you planned on Wolf's Den in Tiragarde Sound was successful. Well done. The outpost is ready to be claimed. Make your way to Wolf's Den in Tiragarde Sound and establish fortifications there. Wolf's Den will be an essential outpost in our campaign against the Alliance. Go with honor!",objectivesText="Claim Wolf's Den for the Horde.",rewardGold=117000,rewardXP=3410,rewardItems={161121,162530,162531,162532,162533,162534,162535,162536,163507},starts={{npcID=135691}},ends={{npcID=139561}},mapCandidates={npc={862,895},zone={8567}},questType="standard",sourceQuests={52005}},
[52128] = {id=52128,name="Ferry Pass",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=1161,storyline={46727,46728,46729,47098,47099,47181,47186,47189,47485,47486,47487,47488,47489,47960,48419,48505,48539,48558,48773,49239,49398,49399,49401,49404,49405,49736,49737,49738,49740,49741,49869,50110,50531,50573,50787,50788,50789,50790,50795,50972,51341,52128,52431,52750,52787,53041,59641},description="<Cyrus takes an official looking document from his jacket, signs it, then offers it to you.> Here, this will give you access to the ferry system.",objectivesText="Speak with Cyrus Crestfall and receive the Ferry Pass .",rewardItems={158075,160326},starts={{npcID=122370}},ends={{npcID=122370}},mapCandidates={npc={},zone={8568}},questGiverID=122370,questTurnInID=122370,questType="standard",sourceQuests={46729},questLines={{id=634,name="Ferry Pass",orderIndex=0,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=6,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[52129] = {id=52129,name="Power Problems",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={50771,50775,50812,51991,52129},series={51991},description="Rozzy , part of the extraction crew, headed out with some gear to work on a plan to keep these reconfigulators all charged up. Go see see if she could use some help!",objectivesText="Check in with Rozzy .",rewardGold=25740,rewardXP=515,starts={{npcID=135179}},ends={{npcID=140046}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={50834},questLines={{id=5421,name="For Profit",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[52130] = {id=52130,name="Deadliest Cache: Carpe Diem",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50376,50391,50418,52130},description="Bah, don't listen to these landlubbers. They haven't fished an honest day in their lives! Before they met me they were as dry as the sands o' the shoreline at low tide. I'll spin ye the tale o' the day we met. 'Twas also the day I saved the wharf from the biggest, meanest, largest monster o' the briny deep ye could imagine!",objectivesText="Listen to Coxswain Hook 's tale. Progress: These landlubbers owe me their lives, if ye ask me!",rewardGold=514800,rewardXP=5145,starts={{npcID=133576}},ends={{npcID=133576}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50418},questLines={{id=5450,name="Deadliest Cache",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[52131] = {id=52131,name="We Need Each Other",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,storyline={52131},description="My father believes he is indulging me. He has ruled for two hundred years, many lifetimes of trolls. In his mind, de threats dat face our kingdom are minor. I have seen too much to believe dat. So since my father and his advisors would not help, I turned to someone who would. Your warchief needs our fleet, and I need her champions. So here is what we need to do.",objectivesText="Listen to Princess Talanji .",rewardGold=25740,rewardXP=175,rewardItems={158075,158937,160251,163127,163128},starts={{npcID=133050}},ends={{npcID=133050}},mapCandidates={npc={},zone={9598}},questGiverID=133050,questTurnInID=133050,questType="standard",sourceQuests={46931,52139}},
[52132] = {id=52132,name="The Proof of Piracy",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50674,50675,50691,50696,50697,50704,50741,50742,50753,50774,50793,50802,50803,50810,50955,52132},description="One thing pirates love more than gold is rum. So we're going to find their rum stashes and blow them up. With the rum all gone, a lot of the pirates should move on. Use my special barrel busting bombs to destroy the pirates' hidden rum stashes.",objectivesText="Destroy 6 pirate Rum Stashes. Progress: Let's blow up some rum!",rewardGold=257400,rewardXP=4115,rewardItems={158226,158635,158636,158724,160481,160668},starts={{npcID=135946}},ends={{npcID=135946}},mapCandidates={npc={942},zone={9042}},questTurnInID=135946,questType="standard",sourceQuests={50793},questLines={{id=740,name="Deadwash Line",orderIndex=14,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
