[52146] = {id=52146,name="Blood on the Sand",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={52026,52027,52028,52029,52030,52031,52032,52034,52035,52036,52038,52039,52040,52041,52042,52146},description="And with that, our mission is done. Let's verify that Guzbert and Kelsey return safely from their demo sites, and then we can head back to friendlier shores.",objectivesText="Wait for Guzbert Gizmoflank and Kelsey Steelspark to return. Progress: Shouldn't be long now!",rewardGold=234000,rewardXP=6815,rewardItems={161086,161087,161240,161241,161333},rewardCurrencies={{id=1553,amount=800}},starts={{npcID=139705}},ends={{npcID=139705}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={52042},questLines={{id=628,name="Blood on the Sand",orderIndex=15,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=628,questLineOrder=9,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=628,questLineOrder=2}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=864},
[52147] = {id=52147,name="Crippling the Horde",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={52147,52150,52156,52158,52170,52171,52172,52208,52219,53069},series={53069},description="Our scouts report that one of Sylvanas's dark ranger captains is in Nazmir. The dark rangers are Sylvanas's deadliest fighters and scouts. Killing one of their leaders will cripple Horde operations. Shandris Feathermoon will be leading the operation in Nazmir. Head there now and strike before we lose this chance.",objectivesText="Speak with Grand Admiral Jes-Tereth to sail to Nazmir.",rewardGold=23400,rewardXP=850,rewardItems={161332,163196},starts={{npcID=135612}},ends={{npcID=140258}},mapCandidates={npc={863,1161},zone={8568}},questType="standard",sourceQuests={52146,53069},questLines={{id=632,name="Chasing Darkness",orderIndex=0,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=632,questLineOrder=10,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=632,questLineOrder=3}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[52148] = {id=52148,name="Freehold: A Pirate's End",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=895,storyline={52148},description="Hey, uh, I don't usually ask for help with personal business, but I know when I'm outmatched. Someone's gotta take down Harlan. He's a maniac. The things I saw him do back in the day... that's why I left Freehold in the first place. H-hey don't think of it as a favor for me--even though it would be a HUGE favor--think of it as making the seas safer for everyone, or something noble like that. <Flynn leans in and whispers.> Plus there's a big fat bounty on his head!",objectivesText="Slay Harlan Sweete in the Freehold dungeon. Progress: What's say sixty-forty split on the bounty? Eh? Seventy-thirty? How about a finder's fee?",rewardGold=1029600,rewardXP=2830,rewardCurrencies={{id=1553,amount=600}},starts={{npcID=121239},{npcID=131290}},ends={{npcID=121239},{npcID=131290}},mapCandidates={npc={895,1161},zone={8568}},questType="dungeon",sourceQuests={49741}},
[52149] = {id=52149,name="Everburning",level=20,requiredLevel=20,faction="alliance",sharable=false,expansion=7,zoneID=8721,mapID=896,description="My people have suffered loss and pain, struggling in the darkness that covered Drustvar . But now we have some light back. We have the means and the will to reclaim our lands from the lingering evils. Your help has brought much of that about. I will miss my parents. Though their end was dark, they were family. But my duty as the head of House Waycrest is clear. The dead can handle themselves. I must attend to the living and lead. There is a short ceremony I need to conduct. Would you assist me?",rewardGold=128700,rewardXP=1385,starts={{npcID=129642},{npcID=142651}},ends={{npcID=142651}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={50533,50639}},
[52150] = {id=52150,name="How to Kill a Dark Ranger",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={52147,52150,52156,52158,52170,52171,52172,52208,52219,53069},description="Let's go over the plan. We don't get many chances to kill a captain of Sylvanas's dark rangers.",objectivesText="Listen to Shandris Feathermoon 's plan. Progress: Well? Let's go over the plan.",rewardGold=23400,rewardXP=850,rewardItems={161332,163196},starts={{npcID=140258}},ends={{npcID=140258}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={52147},questLines={{id=632,name="Chasing Darkness",orderIndex=1,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=632,questLineOrder=10,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=632,questLineOrder=3}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[52151] = {id=52151,name="A Nation United",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=1161,storyline={52151},description="You've done a fine job here, $p. With the city secure and Jaina in command of the fleet, the time has come for Kul Tiras to formally join the Alliance. King Anduin has already departed for Unity Square to meet with Jaina, Katherine and the heads of the major Kul Tiran houses. They are waiting for you.",objectivesText="Attend the council meeting at Unity Square.",rewardGold=234000,rewardXP=6815,starts={{npcID=120788}},ends={{npcID=121144}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={52153}},
[52153] = {id=52153,name="Siege of Boralus: Lady Ashvane's Return",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={52153},description="If Ashvane thinks we will sit idly by as she attempts a coup, she is sorely mistaken. The citizens of Boralus will fight her to a man. I'll need you on the front lines to aid them, <class>. Go with Taelia to the docks and engage the enemy. With a little luck, we may just make it out of this alive.",objectivesText="Complete the Siege of Boralus dungeon.",rewardGold=1029600,rewardXP=2830,rewardCurrencies={{id=1553,amount=750}},starts={{npcID=141785}},ends={{npcID=121235}},mapCandidates={npc={1161},zone={8568}},questType="dungeon",sourceQuests={51445}},
[52154] = {id=52154,name="Our Next Target",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=8568,mapID=1161,series={53070},description="Welcome back, $p. We're ready to set sail on our next mission.... Now we just need to reach an agreement on where we're headed. General Feathermoon and I disagree on which Horde target we should prioritize next. But if you'll give me just a moment, I'm confident I can convince her the value of my strategy and we'll be swiftly on our way. I've considered every reasonable alternative. This is the best course of action.",rewardGold=117000,rewardXP=3410,starts={{npcID=135612}},ends={{npcID=135612}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={52219,53070},questLines={{id=633,name="A Golden Opportunity",orderIndex=0,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=633,questLineOrder=11,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=633,questLineOrder=4}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},
[52155] = {id=52155,name="Treasure in the Tides",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={52155},objectivesText="Loot 8 Shipwreck Supplies in the Wailing Tideway.",rewardItems={163099},mapCandidates={npc={},zone={8567}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=8,objectID=163099},{orderIndex=1,type=0,amount=6,objectID=126440}},worldTaskTitle="Treasure in the Tides",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[52156] = {id=52156,name="Tortollans in Distress",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={52147,52150,52156,52158,52170,52171,52172,52208,52219,53069},description="Our first task is to rescue the tortollans captured by the blood trolls. Keeshan's report indicates the tortollans are familiar with all things Nazmir. They should know about the Horde's operations here. The tortollans tend to stay neutral in most matters. They'll give us details on the Horde's plans if we make a fair trade. We'll meet afterwards at our other outpost, Redfield's Watch, north of Torga's Rest.",objectivesText="Rescue 6 Tortollan Captives from the blood trolls. Progress: What else do you need to know?",rewardGold=234000,rewardXP=6815,rewardItems={161332,163196},starts={{npcID=140258}},ends={{npcID=140258}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={52150},questLines={{id=632,name="Chasing Darkness",orderIndex=2,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=632,questLineOrder=10,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=632,questLineOrder=3}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[52157] = {id=52157,name="A Chilling Encounter",level=50,requiredLevel=50,faction="none",sharable=false,expansion=7,zoneID=8721,mapID=896,starts={{npcID=140252,mapID=896,x=0.4979,y=0.7301}},mapCandidates={npc={},zone={8721}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=140252}},worldTaskTitle="A Chilling Encounter",db2QuestInfoID=112,db2QuestInfoName="Epic Elite World Quest"},
[52158] = {id=52158,name="The Savage Hunt",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={52147,52150,52156,52158,52170,52171,52172,52208,52219,53069},description="The blood trolls in Nazmir are monsters, pure and simple. No culture, no empathy, they only exist to destroy. Let's kill 'em and let whatever dark god they worship sort them out.",objectivesText="Kill 15 blood trolls and their allies within Torga's Rest. Progress: The only good blood troll is a dead blood troll. And even that's stretching it.",rewardGold=234000,rewardXP=6815,rewardItems={161332,163196},starts={{npcID=139609}},ends={{npcID=139609}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={52150},questLines={{id=632,name="Chasing Darkness",orderIndex=3,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=632,questLineOrder=10,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=632,questLineOrder=3}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
