[52183] = {id=52183,name="When a Plan Comes Together",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={52183,52184,52185,52186,52187,52188,52189,52190,52191,52192,52861,52990,53003},series={53068},description="Having Derek Proudmoore's body in our possession is a greater boon than we had planned for. Valentine is risen, but I think it best to allow Derek to lay dead for a bit longer. It's time to use our new allies to our advantage.",objectivesText="Listen to Nathanos' plan, then travel to Plunder Harbor.",rewardGold=23400,rewardXP=850,starts={{npcID=135691}},ends={{npcID=140485}},mapCandidates={npc={862,895},zone={8499}},questType="standard",sourceQuests={52978,53068},questLines={{id=629,name="The Strike on Boralus",orderIndex=0,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=629,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=629,questLineOrder=6}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[52184] = {id=52184,name="Relics of Ritual",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=895,storyline={52183,52184,52185,52186,52187,52188,52189,52190,52191,52192,52861,52990,53003},description="There is a reason why I am accompanying you on this mission, and it's more than familiarity. The Abyssal Scepter is locked behind a ritual, the components for which are held by three separate lieutenants spread across the compound. You get the relics, I perform the ritual, we grab the Scepter and we get out.",objectivesText="Collect the Compass of Clarity , the Curio of the Depths , and the Key of the Sea in Stormsong Monastery. Progress: Have you collected the relics yet?",rewardGold=468000,rewardXP=8520,rewardItems={161334,161335,161336},starts={{npcID=140487}},ends={{npcID=140487}},mapCandidates={npc={895},zone={8568}},questType="standard",sourceQuests={52185},questLines={{id=629,name="The Strike on Boralus",orderIndex=4,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=629,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=629,questLineOrder=6}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[52185] = {id=52185,name="A Well Placed Portal",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={52183,52184,52185,52186,52187,52188,52189,52190,52191,52192,52861,52990,53003},series={52186},description="We have the front here under control. I am sending you and Zelling into Boralus to acquire the Abyssal Scepter. Oculeth has managed to pinpoint a safe location for a portal. Get moving.",objectivesText="Use the Portal to Boralus and meet with Thomas Zelling in Stormsong Monastery.",rewardGold=23400,rewardXP=850,starts={{npcID=140485}},ends={{npcID=140487}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={52186,52187},questLines={{id=629,name="The Strike on Boralus",orderIndex=3,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=629,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=629,questLineOrder=6}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[52186] = {id=52186,name="The Bulk of the Guard",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={52183,52184,52185,52186,52187,52188,52189,52190,52191,52192,52861,52990,53003},series={52185},description="If all has gone according to plan, Proudmoore has sent her elite forces to recapture her son's body. Let's make sure they stay out of the way of our real mission, hmm?",objectivesText="Kill 12 Proudmoore Guard on The Siren's Daughter and The Valorous Rose. Hobart Grapplehammer can fly you out to the ships. Progress: Oh, Katherine. You play right into our trap.",rewardGold=234000,rewardXP=6815,starts={{npcID=140485}},ends={{npcID=140485}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={52183},questLines={{id=629,name="The Strike on Boralus",orderIndex=1,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=629,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=629,questLineOrder=6}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[52187] = {id=52187,name="Old Colleagues",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=862,storyline={52183,52184,52185,52186,52187,52188,52189,52190,52191,52192,52861,52990,53003},description="The people in charge of those two ships are old colleagues of mine, <name>. They did not achieve their rank through hard work as I did, but rather through deception and blackmail. I think they deserve the hammer of karma. Or whatever weapon you prefer.",objectivesText="Kill Captain Gastrod and Guard-Commander Trunksal on The Siren's Daughter, and Helmsman Miria on the Valorous Rose. Hobart Grapplehammer can fly you out to the ships. Progress: I am not a vengeful person... but appropriate punishment? Consider me a fan.",rewardGold=468000,rewardXP=8520,starts={{npcID=140484}},ends={{npcID=140484}},mapCandidates={npc={862},zone={8567}},questType="standard",sourceQuests={52183},questLines={{id=629,name="The Strike on Boralus",orderIndex=2,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=629,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=629,questLineOrder=6}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[52188] = {id=52188,name="Tidesage Teachings",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=895,storyline={52183,52184,52185,52186,52187,52188,52189,52190,52191,52192,52861,52990,53003},description="These people are not tidesages anymore. They do not deserve to bear our title, our prestige, or our knowledge. So many of our teachings lay scattered around this monastery, potentially lost to those of us that remain. We must reclaim these writings. Better in my hands than theirs.",objectivesText="Collect 5 Tomes of Tidesage Research in Stormsong Monastery. Progress: I will not stand for my people's research to be used for evil.",rewardGold=234000,rewardXP=6815,rewardItems={162106},starts={{npcID=140487}},ends={{npcID=140487}},mapCandidates={npc={895},zone={8568}},questType="standard",sourceQuests={52185},questLines={{id=629,name="The Strike on Boralus",orderIndex=5,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=629,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=629,questLineOrder=6}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[52189] = {id=52189,name="Forfeit Souls",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=895,storyline={52183,52184,52185,52186,52187,52188,52189,52190,52191,52192,52861,52990,53003},description="The tidesages here have given in to dark magics. They have submitted themselves to powers they do not understand, and my people have suffered for it. I knew them once, my brothers and sisters in the tides. But now they are lost. I guess I am too. Redeem the name of the tidesages! Kill these betrayers!",objectivesText="Kill 8 Tidesage Archvists or Tidesage Summoners in Stormsong Monastery.",rewardGold=234000,rewardXP=6815,starts={{npcID=140487}},ends={{npcID=140487}},mapCandidates={npc={895},zone={8568}},questType="standard",sourceQuests={52185},questLines={{id=629,name="The Strike on Boralus",orderIndex=6,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=629,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=629,questLineOrder=6}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=1161},
[52190] = {id=52190,name="Gaining the Upper Hand",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=895,storyline={52183,52184,52185,52186,52187,52188,52189,52190,52191,52192,52861,52990,53003},series={52191,52192,52990,53003},description="We need to retrieve the Abyssal Scepter and get out of here before the Kul Tirans break our line in Plunder Harbor. I did some research while you were gone. I believe I uncovered the location where the ritual must take place. When you are ready to go, we can make our way over.",objectivesText="Aid Zelling in retrieving the Abyssal Scepter from Stormsong Monastery. Progress: Nathanos and I believe scepter will help us gain the upper hand on the Kul Tiran fleet. If you wish to win this war, the Abyssal Scepter is key.",rewardGold=468000,rewardXP=8520,rewardItems={162579},starts={{npcID=140487}},ends={{npcID=140487}},mapCandidates={npc={895},zone={8568}},questTurnInID=140487,questType="standard",sourceQuests={52184,52188,52189},questLines={{id=629,name="The Strike on Boralus",orderIndex=7,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=629,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=629,questLineOrder=6}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[52191] = {id=52191,name="Life Held Hostage",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={52183,52184,52185,52186,52187,52188,52189,52190,52191,52192,52861,52990,53003},series={52190,52192,52990,53003},description="As Lilian has pointed out, it seems we have a final visitor. Shall we go pay him a visit?",objectivesText="Help Nathanos Blightcaller with the last of Proudmoore's forces. Progress: There is nothing left for us here. Let us return.",rewardGold=468000,rewardXP=8520,starts={{npcID=140485}},ends={{npcID=140485}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={52990},questLines={{id=629,name="The Strike on Boralus",orderIndex=9,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=629,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=629,questLineOrder=6}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[52192] = {id=52192,name="The Aid of the Tides",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={52183,52184,52185,52186,52187,52188,52189,52190,52191,52192,52861,52990,53003},series={52190,52191,52990,53003},description="With Derek's body and the Abyssal Scepter in stow, our undertaking here today is complete. Let us escape under their noses. When you are ready, let us return to Zuldazar. Sylvanas will want to hear of our victories.",objectivesText="Talk to Nathanos Blightcaller and return to Zuldazar.",rewardGold=23400,rewardXP=850,starts={{npcID=140485}},ends={{npcID=135691}},mapCandidates={npc={862,895},zone={8567}},questType="standard",sourceQuests={52191},questLines={{id=629,name="The Strike on Boralus",orderIndex=10,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=629,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=629,questLineOrder=6}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[52194] = {id=52194,name="What You May Regret",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=895,storyline={51445,52194,52246,52252,52253,52311,52445,52449,52453,52481,52482,52483,52484,52485,52486,52487,52488,52508,52509,52510,52511,52512,52513,52762},description="<name>, Genn Greymane left this letter for you. He indicated it was urgent. I was just about to send for you. <Upon opening it, the letter reads as follows.> \"<name>, You have helped to unite the Kul Tirans and gained their support for the Alliance. Perhaps now you might be able to help reunite a mother with her daughter. Meet me at the family memorial by Proudmoore Keep. With luck we can convince Lord Admiral Proudmoore to grant her daughter a stay of execution. - Genn Greymane \"",objectivesText="Meet with Genn Greymane at the memorial by Proudmoore Keep. Progress: My daughter... My Jaina...",rewardGold=234000,rewardXP=6815,starts={{npcID=122370}},ends={{npcID=140495}},mapCandidates={npc={895},zone={8568}},questGiverID=122370,questType="standard",questLines={{id=745,name="The Pride of Kul Tiras",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[52196] = {id=52196,name="Sandswept Bones",level=50,requiredLevel=50,faction="none",sharable=false,expansion=7,zoneID=8501,mapID=864,starts={{npcID=138794,mapID=864,x=0.446,y=0.562},{npcID=136385},{npcID=132253},{npcID=132701}},mapCandidates={npc={},zone={8501}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=138794}},worldTaskTitle="Sandswept Bones",db2QuestInfoID=112,db2QuestInfoName="Epic Elite World Quest"},
[52197] = {id=52197,name="Long Away",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=148,mapID=62,storyline={52058,52060,52062,52072,52116,52197,52234,52240,52242,52245,52256,52257,52279,52973,52974,52975,52977,53095,53310,53551,53616,53617,53619,53621,53622},description="For every foe we slay, two more take their place. We are too few in number to stand toe to toe. We must fall back, <name>. Strategy can yet overcome numbers. We will regroup at Darnassus. I will send for Delaryn.",objectivesText="Regroup with Malfurion and Delaryn at Darnassus.",rewardGold=1000,rewardXP=710,starts={{npcID=133693}},ends={{npcID=134578}},mapCandidates={npc={57,62},zone={148}},questType="standard",sourceQuests={52257},questLines={{id=637,name="The Warchief's Command",orderIndex=16,flags=0}},db2PoiMapID=1,db2PoiUiMapID=89},
[52198] = {id=52198,name="Tank and Spank",expansion=7,mapID=942,questType="world",db2Objectives={{orderIndex=0,type=0,amount=30,objectID=140596,text="Horde reinforcements slain"},{orderIndex=1,type=0,amount=5,objectID=140597,text="Siege engines destroyed"}},worldTaskTitle="Tank and Spank",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[52199] = {id=52199,name="Rum- Paaaage!",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={52199},objectivesText="Irontide Rum Stash destroyed",rewardItems={161197},mapCandidates={npc={},zone={9042}},questType="world",db2Objectives={{text="Irontide Rum Stash destroyed",amount=8,type=0,objectID=140365,orderIndex=0}},worldTaskTitle="Rum- Paaaage!",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
