[52308] = {id=52308,name="Intercepted Orders",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={52308,52489,52490,52491,52492,52493,52494,52495,52496,53071,53131},series={53071},description="Good to see you again, $p. Mathias and I are discussing what to do with new intel that his SI:7 agents procured for us. The intercepted letter contains orders from Warchief Sylvanas for an operation the Horde is undertaking at sea. This could be a rare opportunity, or a distraction. The letter is purposefully light on details, and it's unclear if we should make this a top priority or focus on our other missions. Do you have a moment to talk through this with Mathias and me?",objectivesText="Discuss the plan with Alliance leadership. Progress: We cannot afford a distraction... or a missed opportunity.",rewardGold=117000,rewardXP=3410,rewardItems={162528,162529,162537},starts={{npcID=135612}},ends={{npcID=135612}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={52261,53071},questLines={{id=638,name="Blood in the Water",orderIndex=0,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=638,questLineOrder=12,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=638,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
