[52311] = {id=52311,name="Sweete's Strongbox",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={51445,52194,52246,52252,52253,52311,52445,52449,52453,52481,52482,52483,52484,52485,52486,52487,52488,52508,52509,52510,52511,52512,52513,52762},description="You've got the keys, and Taelia's still watching our backs. So let's head up to Sweete's, ah, \"office\" and liberate the documents in that strongbox. Come on, it's across the bridge with the rest of his treasure.",objectivesText="Open Harlan Sweete's Strongbox.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1553,amount=250}},starts={{npcID=141032}},ends={{npcID=140732}},mapCandidates={npc={895},zone={8567}},questGiverID=141032,questType="standard",sourceQuests={52253},questLines={{id=745,name="The Pride of Kul Tiras",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
