[52313] = {id=52313,name="Mission Report: Mudfisher Cove",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={52313},series={52314},description="Your followers have sent a report regarding the assault on Mudfisher Cove. It details that victory was hard-fought, but all of the guards previously defending the outpost have been slain. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.",objectivesText="Deliver the victory report to Nathanos Blightcaller . Progress: Do you have news regarding the mission to Drustvar?",rewardGold=23400,rewardXP=850,rewardItems={161482,161484,162530,162531,162532,162533,162534,162535,162536,163334},starts={{npcID=138704}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questGiverID=138704,questType="standard"},
