[52428] = {id=52428,name="Infusing the Heart",level=10,requiredLevel=10,faction="both",categories={"legendary","campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51211,52428},description="Azeroth's voice is growin' fainter and fainter. If the seal on this chamber shatters, her soul will be lost! We've got one chance tae save us all. Absorb the Azerite around the chamber into the Heart of Azeroth. Then unleash the amulet's power tae seal that crack in the center of the seal. Azerite can be a destructive force, but if it's channeled through yer amulet, it can heal the world!",objectivesText="Absorb Azerite to empower the Heart of Azeroth. Progress: What are ye waitin' fer?",rewardGold=25740,rewardXP=175,rewardItems={33226,158075,158937,159671,159901,159902,159903,159904,159905,159906,159907,159908,160251,160326,160906,160907,160908,160909,160910,160911,160912,160913,160914,160915,160916,160917,160918,160919,160920,160921,163127,163128,168611},rewardChoices={159901,159903,159902,160907,160909,160906,160908,159904,160917,160914,160915,160916,159908,160913,160921,159906,160911,160919,159907,160912,160920,159905,160910,160918},rewardCurrencies={{id=1553,amount=100}},starts={{npcID=137323}},ends={{npcID=137323}},mapCandidates={npc={862},zone={8499}},questTurnInID=137323,questType="standard",sourceQuests={51211},questLines={{id=743,name="The Heart of Azeroth",orderIndex=1,flags=0},{id=785,name="The Heart of Azeroth",orderIndex=2,flags=0},{id=5379,name="The Heart of Azeroth",orderIndex=2,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=743,questLineOrder=1,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=2,title="War Campaign",questLineID=785,questLineOrder=1,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5379,questLineOrder=1},{id=225,title="War Campaign",questLineID=5379,questLineOrder=1}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2DetailThemeID=14,db2PoiMapID=1929,db2PoiUiMapID=1021},
[52430] = {id=52430,name="Not So Bad Down Here",level=50,requiredLevel=50,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={52430},objectivesText="Defeat Grixis Tinypop in a pet battle.",starts={{npcID=141077}},ends={{npcID=141077}},mapCandidates={npc={},zone={8567}},questGiverID=141077,questTurnInID=141077,questType="world",db2Objectives={{text="Defeat Kwint",amount=1,type=11,objectID=141077,orderIndex=0}},worldTaskTitle="Not So Bad Down Here",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[52431] = {id=52431,name="No-Landing Zone",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={49405,49736,49737,49738,49740,49869,50110,52431,52750},series={49399,49401,49404,49405,49869},description="These pirates are ruthless - they're bringing in landing boats to cut off our escape! The guards are down at the riverside holding them off, but I'm afraid they'll be overrun before my family and I can get away!",objectivesText="Slay Burnsy the Blade , Wiley Jaki , and Skullcrusher Cotner . Progress: Please help the guards fend off those pirates!",rewardGold=309800,rewardXP=1415,rewardItems={156520},starts={{npcID=141078}},ends={{npcID=141078}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={49405},questLines={{id=588,name="Defenders of Daelin's Gate",orderIndex=1,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=30,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[52432] = {id=52432,name="Squall",level=50,requiredLevel=50,faction="none",categories={},flags={"rare"},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={52432},rewardItems={158224},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=141088}},worldTaskTitle="Squall",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
[52436] = {id=52436,name="The Blackwood Den",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=148,mapID=62,storyline={50476,50642,50646,50647,50738,50740,50772,50800,50823,50837,50878,50879,50880,52436,52437,52438,52806,52967,52970,52971,52981,53604,53605,53606,53608,53609,53610,53627},description="We have not moved all of our troops into Darkshore yet, but I think we have enough to justify establishing a foothold somewhere. I know just the place. Just south of here is the Blackwood Den. Its inhabitants, the Furbolgs, have been driven in to a hysteria. With our enemies pouring from the North, the Furbolg threat is a nuisance we cannot afford. I will lead another squad past the wall while you... negotiate with the Furbolgs.",objectivesText="Drive the furbolgs out of the Blackwood Den.",rewardGold=2000,rewardXP=1415,rewardItems={158075,158937,160251,163127,163128},starts={{npcID=135003}},ends={{npcID=134554}},mapCandidates={npc={62},zone={148}},questType="standard",sourceQuests={50879},questLines={{id=584,name="The Warchief's Command",orderIndex=15,flags=0}},db2PoiMapID=1,db2PoiUiMapID=62},
[52437] = {id=52437,name="The Start of Something Good",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=148,mapID=62,storyline={50476,50642,50646,50647,50738,50740,50772,50800,50823,50837,50878,50879,50880,52436,52437,52438,52806,52967,52970,52971,52981,53604,53605,53606,53608,53609,53610,53627},series={53608,53609},description="While the rest of our army sets up camp -- you should follow me. I spotted something... interesting... on my way back from Zoram'gar. I'll admit, not even I could have predicted such fortuitous happenstance. Come with me, <name>. And bring a pickaxe.",objectivesText="Follow Sylvanas to Nazj'vel.",rewardGold=2000,rewardXP=1415,rewardItems={158075,158937,160251,163127,163128},starts={{npcID=134554}},ends={{npcID=144346}},mapCandidates={npc={62},zone={148}},questType="standard",sourceQuests={52436,53606},questLines={{id=584,name="The Warchief's Command",orderIndex=17,flags=0}},db2PoiMapID=1,db2PoiUiMapID=62},
[52438] = {id=52438,name="A Wild Ride",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=148,mapID=62,storyline={50476,50642,50646,50647,50738,50740,50772,50800,50823,50837,50878,50879,50880,52436,52437,52438,52806,52967,52970,52971,52981,53604,53605,53606,53608,53609,53610,53627},series={52806,52967,52970,52971,52981,53610},description="Let me tell ya, kid... this may be some of the best work I've ever done! Now that the upgrades are in place, there's no time to waste. The battle is raging over at Wildbend River. Take the modified hellion into battle and give 'em hell!",objectivesText="Join the battle at Wildbend River.",rewardGold=2000,rewardXP=1415,rewardItems={52919,52964,57518,158075,158937,160251,163127,163128},starts={{npcID=135501}},ends={{npcID=134554}},mapCandidates={npc={62},zone={148}},questType="standard",sourceQuests={53627},questLines={{id=584,name="The Warchief's Command",orderIndex=21,flags=0}},db2PoiMapID=1,db2PoiUiMapID=62},
[52439] = {id=52439,name="Iron Stores",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9734,storyline={52439},description="While the mine is under Alliance banners our workers ensure the iron supply never runs dry. This key will provide access to the stores. Take what you need.",objectivesText="Use the Heavy Iron Key to access the Iron Stores. Progress: These old chests can be quite the bother.",rewardItems={159728},rewardCurrencies={{id=1541,amount=20}},starts={{npcID=139942},{npcID=141145}},ends={{npcID=141145}},mapCandidates={npc={},zone={9734}},questType="standard"},
[52440] = {id=52440,name="Resource Recruitment",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9734,storyline={52440},description="If we're to maintain our iron supply we'll need a bit of help. See if you can wrangle us up a few fresh recruits for the mine.",objectivesText="Recruit 3 Highlands Peasants to work.",rewardCurrencies={{id=1541,amount=10}},ends={{npcID=141145}},mapCandidates={npc={},zone={9734}},questType="standard"},
[52443] = {id=52443,name="The Final Foothold",level=40,requiredLevel=40,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={53055},description="We have established two critical footholds in Zandalar. The time has come to establish the third. Let's review the battle plan when you're ready.",objectivesText="Use the Zandalar Campaign Map to review the final foothold.",rewardGold=257400,rewardXP=5465,starts={{npcID=135612}},ends={{npcID=135612}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={51961},questLines={{id=624,name="The Zandalar Campaign",orderIndex=3,flags=0},{id=5374,name="The Zandalar Campaign",orderIndex=3,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=3,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=3,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=624,questLineOrder=3,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[52444] = {id=52444,name="The Final Foothold",level=40,requiredLevel=40,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={51224,51231,51233,51234,51332,51340,51421,51435,51436,51437,51438,51439,51440,51441,51442,51526,51532,51536,51587,51643,51674,51675,51691,51696,51753,51800,51801,51802,51803,51916,51975,51979,51984,51985,51986,51987,52444,52451,52749,53050,53056,53064},series={53056},description="We have established two critical footholds in Kul Tiras. The time has come to establish the third. Let's review the battle plan when you're ready.",objectivesText="Use the Kul Tiras Campaign Map to review the final foothold.",rewardGold=257400,rewardXP=5465,starts={{npcID=135691}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={53056},questLines={{id=623,name="The Kul Tiras Campaign",orderIndex=3,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=3,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=623,questLineOrder=4,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[52445] = {id=52445,name="Tol Dagor: The Fourth Key",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=895,storyline={51445,52194,52246,52252,52253,52311,52445,52449,52453,52481,52482,52483,52484,52485,52486,52487,52488,52508,52509,52510,52511,52512,52513,52762},description="Hey, wait a second. I know the type of key our fourth lock needs. This is the same sort of lock the Ashvane company uses. Resists lockpicks like nothing else, but they have a standard skeleton key. There was a set hanging on the wall in the Tol Dagor Armory. Given the state we left it in, it'd be easy to grab it. Taelia and I will take the chest back to the Harbormaster's office for safe keeping. You go in to Tol Dagor and get that last key!",objectivesText="Enter the Tol Dagor dungeon, recover the Ashvane Skeleton Key and kill Overseer Korgus , then return to Flynn Fairwind in the Harbormaster's Office in Boralus. Progress: I knew securing that last key wouldn't be a problem for you, <name>!",rewardGold=936000,rewardXP=13630,rewardItems={162008},rewardCurrencies={{id=1553,amount=600}},starts={{npcID=140732}},ends={{npcID=140732}},mapCandidates={npc={895},zone={8568}},questType="dungeon",sourceQuests={52311},questLines={{id=745,name="The Pride of Kul Tiras",orderIndex=6,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[52446] = {id=52446,name="Sister Absinthe",level=50,requiredLevel=50,faction="none",categories={},flags={"rare"},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={52446},rewardItems={155164},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=141143}},worldTaskTitle="Sister Absinthe",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
[52447] = {id=52447,name="Room To Grow",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={52447},description="Ah, I would not worry too much about de little one. Some beasts take longer than others to find their way, and Kua'fon is no exception. For now, continue to help him grow. Keep him fed, keep him out of danger, and strengthen your bond. He will let you know when he is ready to try again.",objectivesText="Tend to Kua'fon until he is ready to attempt another flight.",rewardGold=468000,rewardXP=8520,rewardItems={157782,159146},starts={{npcID=135308}},ends={{npcID=133679}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={50412}},
[52449] = {id=52449,name="The Mysterious Island",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=895,storyline={51445,52194,52246,52252,52253,52311,52445,52449,52453,52481,52482,52483,52484,52485,52486,52487,52488,52508,52509,52510,52511,52512,52513,52762},description="Fate's End is just that. It's where the very worst criminals are sent. No one ever comes back. I'm sorry Lady Katherine will have to hear this, but I'm glad it isn't my job to tell her. <Flynn hands you the document solemnly.> I'm certain she'll want an update, even if the news is as bad as this.",objectivesText="Report to Katherine Proudmoore in Boralus.",rewardGold=23400,rewardXP=850,starts={{npcID=140732}},ends={{npcID=140495}},mapCandidates={npc={895},zone={8568}},questType="standard",sourceQuests={52445},questLines={{id=745,name="The Pride of Kul Tiras",orderIndex=7,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[52450] = {id=52450,name="Uniting Kul Tiras",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},rewardGold=234000,rewardXP=6815,rewardItems={141605,158075},starts={{npcID=135612}},ends={{npcID=135612}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={52428},questLines={{id=616,name="Uniting Kul Tiras",orderIndex=1,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=53,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=616,questLineOrder=8,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
