[52453] = {id=52453,name="A Forlorn Hope",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=895,storyline={51445,52194,52246,52252,52253,52311,52445,52449,52453,52481,52482,52483,52484,52485,52486,52487,52488,52508,52509,52510,52511,52512,52513,52762},description="<Lady Katherine's jaw sets.> I refuse to believe I am too late. No one has ever come back from Fate's End, but if anyone could survive I have to believe it would be my Jaina. Go to Stormsong Valley and secure transit to Fate's End from the tidesages. Brother Pike is a good place to start. Hurry, <name>.",objectivesText="Go to Stormsong and speak with Brother Pike at Kraken's Reach.",rewardGold=23400,rewardXP=850,rewardItems={209900},rewardCurrencies={{id=1553,amount=250}},starts={{npcID=140495}},ends={{npcID=141223}},mapCandidates={npc={895,942},zone={8568}},questType="standard",sourceQuests={52449},questLines={{id=745,name="The Pride of Kul Tiras",orderIndex=8,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
