[52477] = {id=52477,name="WANTED: Ayame",level=20,requiredLevel=20,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={52477},description="Wanted: For the death of twelve pilgrims and their escort to Torga's Rest. A reward is offered to anyone who brings in the head of the great serpent, Ayame. - Korkush",objectivesText="Hunt down Ayame and obtain its head. Progress: Yeah, I put up the poster. Got anything for me?",rewardGold=772200,rewardXP=4150,rewardItems={162118},rewardCurrencies={{id=1553,amount=115}},ends={{npcID=131988}},startObjects={{objectID=293567,mapID=863,x=0.672,y=0.408}},coords={mapID=863,source="quest_giver",x=0.676,y=0.418},mapCandidates={npc={863},zone={8500}},questType="group"},
[52478] = {id=52478,name="Mission Report: Hillcrest Pasture",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={52478},series={52479},description="Your followers have sent a report regarding the assault on Hillcrest Pasture. It details that victory was hard-fought, but the Stormsong defenders have been slain. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.",objectivesText="Deliver the victory report to Nathanos Blightcaller . Progress: Do you have news regarding the mission to Stormsong Valley?",rewardGold=23400,rewardXP=850,rewardItems={162119,162123,162530,162531,162532,162533,162534,162535,162536},starts={{npcID=138704}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questGiverID=138704,questType="standard"},
[52479] = {id=52479,name="Hillcrest Pasture",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=862,storyline={52479},series={52478},description="The raid you planned for Hillcrest Pasture in Stormsong Valley was successful. Well done. The outpost is ready to be claimed. Make your way to Hillcrest Pasture in Stormsong Valley and establish fortifications there. Hillcrest Pasture will be an essential outpost in our campaign against the Alliance. Go with honor!",objectivesText="Claim Hillcrest Pasture for the Horde.",rewardGold=117000,rewardXP=3410,rewardItems={162119,162530,162531,162532,162533,162534,162535,162536},starts={{npcID=135691}},ends={{npcID=141308}},mapCandidates={npc={862,942},zone={9042}},questType="standard",sourceQuests={52478}},
[52480] = {id=52480,name="WANTED: Ayame",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={52480},description="Well equipped exterminator wanted. Huge snake seen lurking north of Fort Victory. Reward offered for anyone who brings in the head of the pest. - Garrick Blacksteel",objectivesText="Hunt down Ayame and obtain its head. Progress: Got anything fer me?",rewardGold=772200,rewardXP=4150,rewardItems={162118},rewardCurrencies={{id=1553,amount=115}},ends={{npcID=135072}},startObjects={{objectID=293568,mapID=863,x=0.623,y=0.413}},coords={mapID=863,source="quest_giver",x=0.618,y=0.414},mapCandidates={npc={863},zone={8500}},questType="group"},
[52481] = {id=52481,name="Of Myth and Fable",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=895,storyline={51445,52194,52246,52252,52253,52311,52445,52449,52453,52481,52482,52483,52484,52485,52486,52487,52488,52508,52509,52510,52511,52512,52513,52762},description="If Jaina is truly trapped in the Blighted Lands, that could mean we're not too late! We just need to find a way inside... We will need to enlist the help of Lucille Waycrest . The legends of that place are deeply rooted in Drustvar's culture. If anyone would know more about it, it would be she. I will send a raven ahead for her to prepare what knowledge she can gather. Make haste to Arom's Stand!",objectivesText="Meet with Lucille Waycrest at Arom's Stand in Drustvar.",rewardGold=23400,rewardXP=850,starts={{npcID=140495}},ends={{npcID=129642}},mapCandidates={npc={895,896},zone={8568}},questType="standard",sourceQuests={52513},questLines={{id=745,name="The Pride of Kul Tiras",orderIndex=15,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[52482] = {id=52482,name="The Old Bear",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={51445,52194,52246,52252,52253,52311,52445,52449,52453,52481,52482,52483,52484,52485,52486,52487,52488,52508,52509,52510,52511,52512,52513,52762},description="I cannot change your mind, can I? Very well, I may know where you can find your answers. High in the mountains, there is a hidden alcove of impossibly verdant growth. It is there that the druids of Kul Tiras train in the old ways of the Drust - from before the time of Gorak Tul. Their leader is a great bear named Ulfar . I know little about him, but few are more qualified to parse the magic of the Drust. You will find a path to his den along Highroad Pass. Good luck, Inquisitor.",objectivesText="Speak with Ulfar in Ulfar 's Den. Progress: Yes?",rewardGold=234000,rewardXP=6815,starts={{npcID=129642}},ends={{npcID=141894}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={52481},questLines={{id=745,name="The Pride of Kul Tiras",orderIndex=16,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[52483] = {id=52483,name="Nightmare Catcher",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={51445,52194,52246,52252,52253,52311,52445,52449,52453,52481,52482,52483,52484,52485,52486,52487,52488,52508,52509,52510,52511,52512,52513,52762},description="The effigies crafted by the followers of Gorak Tul were made not of wood, but of the bones and sinew of their enemies. This will be your first task. Travel to Gol Osigr where the ancient Drust have awoken from their slumber. The bones here belong to Gorak Tul's greatest soldiers who stood with him at the final battle against the first Lord Waycrest. Their bones seethe with hatred and anger. This will serve your needs well.",objectivesText="Collect 4 Intact Drust Bones and 9 Ancient Sinew from Drust skeletons in Gol Osigr. Progress: Do you have the materials?",rewardGold=234000,rewardXP=6815,rewardItems={162524,162525},rewardCurrencies={{id=1553,amount=250}},starts={{npcID=141894}},ends={{npcID=141159}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={52482},questLines={{id=745,name="The Pride of Kul Tiras",orderIndex=17,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[52484] = {id=52484,name="Buried Power",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={51445,52194,52246,52252,52253,52311,52445,52449,52453,52481,52482,52483,52484,52485,52486,52487,52488,52508,52509,52510,52511,52512,52513,52762},description="Since time immemorial, the Drust have used runes to shape their magics. This remains true of the spells woven by Gorak Tul and his ilk. You will need some of these runes for your effigy to be effective. It is likely that some still exist at the site of his final battle, buried under years of soot and snow. Take this stone. It is empowered with the magic of the Thornspeakers and will react to Tul's spells. With it, you should be able to locate the runes, no matter how deep the ages have buried them.",objectivesText="Use the Dowsing Stone to find and Collect 6 Drust Runestones in Gol Osigr. Progress: What have you uncovered beneath the snows of Gol Osigr?",rewardGold=234000,rewardXP=6815,rewardItems={162526},starts={{npcID=141159},{npcID=141894}},ends={{npcID=141159}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={52482},questLines={{id=745,name="The Pride of Kul Tiras",orderIndex=18,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[52485] = {id=52485,name="Hatred's Focus",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={51445,52194,52246,52252,52253,52311,52445,52449,52453,52481,52482,52483,52484,52485,52486,52487,52488,52508,52509,52510,52511,52512,52513,52762},description="An effigy requires a central focus. The coven are fond of using animal skulls for this purpose, but for your task you will need something much more potent. Korvash was a trusted lieutenant to Gorak Tul, as well as a powerful sorcerer, until he was defeated at the battle of Arom's Stand. His bones remain at the site of his demise, now buried by the years. Find them, and take his skull.",objectivesText="Collect Korvash's Skull from Korvash in Gol Osigr. Progress: Have you found Korvash's bones ?",rewardGold=468000,rewardXP=8520,rewardItems={162527},rewardCurrencies={{id=1553,amount=250}},starts={{npcID=141159},{npcID=141894}},ends={{npcID=141159}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={52482},questLines={{id=745,name="The Pride of Kul Tiras",orderIndex=19,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[52486] = {id=52486,name="Waycrest Manor: Draining the Heartsbane",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={51445,52194,52246,52252,52253,52311,52445,52449,52453,52481,52482,52483,52484,52485,52486,52487,52488,52508,52509,52510,52511,52512,52513,52762},description="The skull you have taken from Korvash needs to be steeped in Gorak Tul 's magic to grant the power needed to bridge the gap to Thros. You must take it to a font of his power, and let it absorb his magic. You will find one such font in Waycrest Manor - the epicenter of the coven's power. Here, their leader has tapped so freely into Tul's power that it emanates from the very walls. Bring Korvash's skull to the heart of the manor and let it feast. Then, the effigy will be complete.",objectivesText="Empower Korvash's Skull in the depths of Waycrest Manor.",rewardGold=936000,rewardXP=13630,rewardCurrencies={{id=1553,amount=600}},starts={{npcID=141159}},ends={{npcID=129642}},mapCandidates={npc={896},zone={8721}},questType="dungeon",sourceQuests={52483,52484,52485},questLines={{id=745,name="The Pride of Kul Tiras",orderIndex=20,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[52487] = {id=52487,name="Into Darkness",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={51445,52194,52246,52252,52253,52311,52445,52449,52453,52481,52482,52483,52484,52485,52486,52487,52488,52508,52509,52510,52511,52512,52513,52762},description="I didn't think you would find a way. Though at this point, I guess I shouldn't be surprised when you accomplish what seems impossible. I guess all that is left is to brave the Crimson Forest and see if this thing works. First, however, Katherine has ordered me to send word when you have found a way to Jaina. You can use one of our falcons to take a message to her.",objectivesText="Speak with Ensign Josey to send a message to Katherine, then meet her at Gol Inath in the Crimson Forest. Progress: We've made it this far. There's no turning back.",rewardGold=23400,rewardXP=850,rewardItems={26010,26024,26036,38734,39033,39060,39098,62849,62850,62851,131271,131640,184165},starts={{npcID=129642}},ends={{npcID=141785}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={52486},questLines={{id=745,name="The Pride of Kul Tiras",orderIndex=21,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[52488] = {id=52488,name="Runic Resistance",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={51445,52194,52246,52252,52253,52311,52445,52449,52453,52481,52482,52483,52484,52485,52486,52487,52488,52508,52509,52510,52511,52512,52513,52762},description="Whatever is going on with this effigy, I don't think it's going to open the gateway without our help. These runes must be the key. There must be some way we can use them to activate the effigy.",objectivesText="Solve the runic puzzle to activate the Drust Effigy in Gol Inath. Progress: There must be some trick to these runes...",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1553,amount=200}},starts={{npcID=141785}},ends={{npcID=141785}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={52487},questLines={{id=745,name="The Pride of Kul Tiras",orderIndex=22,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[52489] = {id=52489,name="Hunting Blood Prince Dreven",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={52308,52489,52490,52491,52492,52493,52494,52495,52496,53071,53131},description="Between the information I gathered from my scouting mission and Mathias Shaw's intel, we know exactly where Blood Prince Dreven is going to be. We will have our revenge, $p. For ourselves, for my sisters, for the Alliance. We won't underestimate the san'layn this time. We will keep the Horde off-balance and distracted with swift, targeted, ruthless attacks. Thankfully, the Wildhammer are masters of those combat tactics. I'm glad they'll be joining us. Are you ready to leave?",objectivesText="Ride Swiftwing to accompany Falstad and Shandris to the Great Sea. Progress: Our strikes will be swift and true. The san'layn will fall.",rewardGold=117000,rewardXP=3410,rewardItems={162528,162529,162537},starts={{npcID=141356}},ends={{npcID=141356}},mapCandidates={npc={1161},zone={8568}},questTurnInID=141356,questType="standard",sourceQuests={52308},questLines={{id=638,name="Blood in the Water",orderIndex=1,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=638,questLineOrder=12,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=638,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1954,db2PoiUiMapID=1156},
[52490] = {id=52490,name="Behind Enemy Boats",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9800,mapID=1156,storyline={52308,52489,52490,52491,52492,52493,52494,52495,52496,53071,53131},description="This is where our information ends, $p. Blood Prince Dreven is lurking in one of those Forsaken boats, but we don't know which boat or which section of that boat he's in. We'll split up and hit the boats simultaneously, so the Horde has less time to react. If Dreven isn't on the boat you scout, abandon it and join me on the other one. If he's not on my boat, I'll do the same. We'll take down Dreven together. Don't get distracted. Our resources are limited. Dreven is our only target today.",objectivesText="Search the Banshee's Wail for signs of Blood Prince Dreven.",rewardGold=468000,rewardXP=8520,rewardItems={162528,162529,162537},starts={{npcID=141567}},ends={{npcID=141567}},mapCandidates={npc={},zone={9800}},questGiverID=141567,questTurnInID=141567,questType="standard",sourceQuests={52489},questLines={{id=638,name="Blood in the Water",orderIndex=2,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=638,questLineOrder=12,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=638,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1954,db2PoiUiMapID=1156},
[52491] = {id=52491,name="Broadside Bedlam",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9800,mapID=1156,storyline={52308,52489,52490,52491,52492,52493,52494,52495,52496,53071,53131},description="<The ship's cannons are currently pointed at the other Forsaken ship across the water. However, it appears the crew hasn't loaded them with gunpowder or cannonballs yet... Probably to avoid any accidental firings while they're anchored here. Yes, it'd be a real shame if \"accidental\" cannon fire damaged the other ship.>",objectivesText="Collect gunpowder, cannonballs, and a torch, then fire the cannons. Progress: Ye find anything interesting down in the ship?",rewardGold=234000,rewardXP=6815,rewardItems={162528,162529,162537},startObjects={{objectID=293821,mapID=1156,x=0.368,y=0.524}},endObjects={{objectID=293821,mapID=1156,x=0.368,y=0.524}},coords={mapID=1156,x=0.368,y=0.524},mapCandidates={npc={},zone={9800}},questType="standard",sourceQuests={52490},questLines={{id=638,name="Blood in the Water",orderIndex=3,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=638,questLineOrder=12,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=638,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1954,db2PoiUiMapID=1156},
[52492] = {id=52492,name="The Wildhammer Specialty",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9800,mapID=1156,storyline={52308,52489,52490,52491,52492,52493,52494,52495,52496,53071,53131},description="Well, if ye didn't find Blood Prince Dreven on yer ship, he must be hiding on the other one. I can take ye down to it, but the Horde knows we're here now. What do ye say we create some distractions to hold their attention while we hunt down Dreven? Me Wildhammers are itchin' tae let the hammers fly. Ye want to join us for the first round?",objectivesText="Join Falstad and Swiftwing on a bombing run over the Horde ships.",rewardGold=234000,rewardXP=6815,rewardItems={162528,162529,162537},starts={{npcID=141541}},ends={{npcID=141541}},mapCandidates={npc={},zone={9800}},questGiverID=141541,questTurnInID=141541,questType="standard",sourceQuests={52490,52491},questLines={{id=638,name="Blood in the Water",orderIndex=4,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=638,questLineOrder=12,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=638,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1954,db2PoiUiMapID=1156},
[52493] = {id=52493,name="An Unnatural Crew",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9800,mapID=1156,storyline={52308,52489,52490,52491,52492,52493,52494,52495,52496,53071,53131},description="Blood Prince Dreven is here, and the situation's even worse than we thought. That monster's training other san'layn. Every neophyte you see on this ship is another future Blood Prince Dreven. His vile practices cannot be allowed to spread within the Horde. We're going to tear the san'layn out, right now, root and all.",objectivesText="Kill 12 Horde crew aboard the Crimson Squall. Progress: Every san'layn must be felled today, or we'll never be rid of them.",rewardGold=234000,rewardXP=6815,rewardItems={162528,162529,162537},starts={{npcID=142228}},ends={{npcID=142228}},mapCandidates={npc={},zone={9800}},questGiverID=142228,questTurnInID=142228,questType="standard",sourceQuests={52492},questLines={{id=638,name="Blood in the Water",orderIndex=5,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=638,questLineOrder=12,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=638,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1954,db2PoiUiMapID=1156},
[52494] = {id=52494,name="Foul Crystals for Foul People",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9800,mapID=1156,storyline={52308,52489,52490,52491,52492,52493,52494,52495,52496,53071,53131},description="Blood Prince Dreven and his followers are siphoning power from blood-infused crystals to bolster their unholy abilities. Destroying those crystals will weaken Dreven before we fight him. Take out as many as you can find.",objectivesText="Destroy 5 San'layn Crystals.",rewardGold=234000,rewardXP=6815,rewardItems={162528,162529,162537},starts={{npcID=142228}},ends={{npcID=142228}},mapCandidates={npc={},zone={9800}},questGiverID=142228,questTurnInID=142228,questType="standard",sourceQuests={52492},questLines={{id=638,name="Blood in the Water",orderIndex=6,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=638,questLineOrder=12,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=638,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1954,db2PoiUiMapID=1156},
[52495] = {id=52495,name="Ending the San'layn Threat",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9800,mapID=1156,storyline={52308,52489,52490,52491,52492,52493,52494,52495,52496,53071,53131},description="Blood Prince Dreven has barricaded himself in the lowest deck of this ship. He's trapped down there. Don't think that makes this easy for us. A cornered beast is more dangerous than a free one. But, if we have the will and wisdom, he can be slain. Follow me. I will break the barrier blocking his lair and we will face him together.",objectivesText="Kill Blood Prince Dreven .",rewardGold=702000,rewardXP=10225,rewardItems={133755,162528,162529,162537},starts={{npcID=142232}},ends={{npcID=142232}},mapCandidates={npc={},zone={9800}},questGiverID=142232,questTurnInID=142232,questType="standard",sourceQuests={52493,52494},questLines={{id=638,name="Blood in the Water",orderIndex=8,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=638,questLineOrder=12,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=638,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1954,db2PoiUiMapID=1156},
[52496] = {id=52496,name="A Clean Escape",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={52308,52489,52490,52491,52492,52493,52494,52495,52496,53071,53131},description="Our victory here will echo through the Horde like a warning shot. Grunts will whisper around the campfire that nowhere is safe from $p and the Alliance. Soldiers will doubt, even for a moment, the strength of their commanders. Sylvanas herself will hear the story of what we did here today, and it will infuriate her. The thought of her outraged roar when she hears the news will keep me warm tonight. Let's return to Boralus and inform the High Commander of the good news.",objectivesText="Return to Boralus and report to High Commander Halford Wyrmbane .",rewardGold=117000,rewardXP=3410,rewardItems={162528,162529,162537},rewardCurrencies={{id=1553,amount=800}},starts={{npcID=141567}},ends={{npcID=135612}},mapCandidates={npc={1161},zone={8568}},questGiverID=141567,questType="standard",sourceQuests={52495},questLines={{id=638,name="Blood in the Water",orderIndex=9,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=638,questLineOrder=12,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=638,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[52497] = {id=52497,name="Raiding the Boulderfist",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,storyline={52497},description="The Boulderfist have been rather active ever since the battle began. One of our scouts reported their recent raid on Galson's Lode proved rather lucrative. Scout the cave to the northeast, find the iron ore they stole and steal it back. We can't afford to let anyone else control our resources.",objectivesText="Obtain 200 pieces of Unprocessed Iron Ore .",rewardItems={159721},rewardCurrencies={{id=1541,amount=75}},mapCandidates={npc={},zone={}},questType="group"},
[52504] = {id=52504,name="So We Meat Again",level=1,requiredLevel=1,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=148,mapID=62,storyline={52504},rewardGold=280900,rewardXP=2090,rewardItems={53563,53564,53565,156996,162013},mapCandidates={npc={},zone={148}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=10,objectID=162013},{orderIndex=1,type=0,amount=8,objectID=142673}},worldTaskTitle="So We Meat Again",db2PoiMapID=1,db2PoiUiMapID=62,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[52505] = {id=52505,name="Pruning the Thorns",level=1,requiredLevel=1,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=148,mapID=62,storyline={52505},rewardItems={162990,163004},mapCandidates={npc={},zone={148}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=8,objectID=143902},{orderIndex=1,type=0,amount=1,objectID=141346}},worldTaskTitle="Pruning the Thorns",db2PoiMapID=1,db2PoiUiMapID=62,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
