[52760] = {id=52760,name="Like Fish in a Barrel",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={52760},objectivesText="Speak with Eaglemaster Dawnhorn Ship crew slain",rewardGold=169800,rewardXP=2090,mapCandidates={npc={},zone={8568}},questType="world",db2Objectives={{text="Speak with Eaglemaster Dawnhorn",amount=1,type=3,objectID=141578,orderIndex=0},{text="Ship crew slain",amount=10,type=0,objectID=141646,orderIndex=4}},worldTaskTitle="Like Fish in a Barrel",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[52761] = {id=52761,name="Siege of Boralus: Blood Money",expansion=7,mapID=895,questType="world",worldTaskTitle="Siege of Boralus: Blood Money",db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
[52762] = {id=52762,name="A Local Guide",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={51445,52194,52246,52252,52253,52311,52445,52449,52453,52481,52482,52483,52484,52485,52486,52487,52488,52508,52509,52510,52511,52512,52513,52762},description="I've spent a lot of time as a guest of the Harbormaster and I've come to understand a few things about Flynn Fairwind . If anyone can quickly help you to sort out any clues in Freehold, it will be him. Flynn's been doing work for Cyrus and can be found in the Harbormaster's office. Show him the contract and recruit him to our cause. Hurry, <name>.",objectivesText="Find Flynn Fairwind at the Harbormaster's office in Boralus. Progress: You fight monsters, unite kingdoms and now you're going to save a princess? You really do take on a lot of this 'hero' stuff. I just hope it doesn't catch.",rewardGold=23400,rewardXP=850,rewardItems={161437},starts={{npcID=140649}},ends={{npcID=140732}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={52246},questLines={{id=745,name="The Pride of Kul Tiras",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[52763] = {id=52763,name="Siege of Boralus: Breaking Their Ranks",expansion=7,mapID=895,questType="world",worldTaskTitle="Siege of Boralus: Breaking Their Ranks",db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
[52764] = {id=52764,name="Journey to the Middle of Nowhere",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={52764,52765,52766,52767,52768,52769,52770,52772,52773,52774,52978,53067,53121},series={52765,52766,52767,52768,52769,52770,52772,52773,52774,52978,53067},description="Our tidesage, Thomas Zelling, claims to have found the wreckage of Marshal Valentine's ship. Took him long enough. Marshal Valentine's body is the final piece of our plan, and it lies within that shipwreck. When you're ready, let us depart for his resting place.",objectivesText="Speak with Dread-Admiral Tattersail to sail to the Great Sea.",rewardGold=234000,rewardXP=6815,starts={{npcID=135691}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questTurnInID=135691,questType="standard",sourceQuests={52122,53067},questLines={{id=736,name="At the Bottom of the Sea",orderIndex=0,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=736,questLineOrder=13,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=736,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=2066,db2PoiUiMapID=1157},
[52765] = {id=52765,name="Deep Dive",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9937,mapID=1157,storyline={52764,52765,52766,52767,52768,52769,52770,52772,52773,52774,52978,53067,53121},series={52764,52766,52767,52768,52769,52770,52772,52773,52774,52978,53067},description="We need you to retrieve Marshal M. Valentine's body at the ocean floor below. I should warn you: this part of the ocean is going to be very deep, and very dark, and very cold. Speak with Hobart at the starboard side of the ship. He's brought all the machinery you'll need to get to the ocean floor.",objectivesText="Speak with Hobart Grapplehammer to dive to the ocean floor, then test your headlamp.",rewardGold=234000,rewardXP=6815,rewardItems={133755,166704},starts={{npcID=141644}},ends={{npcID=141644}},mapCandidates={npc={},zone={9937}},questGiverID=141644,questTurnInID=141644,questType="standard",sourceQuests={52764},questLines={{id=736,name="At the Bottom of the Sea",orderIndex=1,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=736,questLineOrder=13,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=736,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=2066,db2PoiUiMapID=1157},
[52766] = {id=52766,name="Seafloor Shipwreck",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=9937,mapID=1157,storyline={52764,52765,52766,52767,52768,52769,52770,52772,52773,52774,52978,53067,53121},series={52764,52765,52767,52768,52769,52770,52772,52773,52774,52978,53067},description="<static> ... look for shipwreck ... <static> ... east ... <static>",objectivesText="Look for a shipwreck somewhere to the east, apparently.",rewardGold=234000,rewardXP=6815,starts={{npcID=141645}},ends={{npcID=141645}},mapCandidates={npc={},zone={9937}},questGiverID=141645,questTurnInID=141645,questType="standard",sourceQuests={52765},questLines={{id=736,name="At the Bottom of the Sea",orderIndex=2,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=736,questLineOrder=13,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=736,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=2066,db2PoiUiMapID=1157},
[52767] = {id=52767,name="Checking Dog Tags",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=9937,mapID=1157,storyline={52764,52765,52766,52767,52768,52769,52770,52772,52773,52774,52978,53067,53121},series={52764,52765,52766,52768,52769,52770,52772,52773,52774,52978,53067},description="You are no longer able to hear Hobart's voice over the static. You can make out the outlines of several floating bodies nearby. They have significantly decomposed, but their dog tags should still be intact. Hopefully the dog tags can help identify Marshal Valentine.",objectivesText="Find and identify the captain of the shipwreck.",rewardGold=234000,rewardXP=6815,starts={{npcID=141645}},mapCandidates={npc={},zone={9937}},questGiverID=141645,questType="standard",sourceQuests={52766},questLines={{id=736,name="At the Bottom of the Sea",orderIndex=3,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=736,questLineOrder=13,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=736,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=2066,db2PoiUiMapID=1157},
[52768] = {id=52768,name="The Sunken Graveyard",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,mapID=1157,storyline={52764,52765,52766,52767,52768,52769,52770,52772,52773,52774,52978,53067,53121},series={52764,52765,52766,52767,52769,52770,52772,52773,52774,52978,53067},description="<static> ...wait ... more shipwrecks ... <static> ... lots of 'em ... northeast ... <static>",objectivesText="Look for more shipwrecks to the northeast of your current location.",rewardGold=309800,rewardXP=6815,starts={{npcID=141645}},mapCandidates={npc={},zone={}},questGiverID=141645,questType="standard",sourceQuests={52767},questLines={{id=736,name="At the Bottom of the Sea",orderIndex=4,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=736,questLineOrder=13,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=736,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=2066,db2PoiUiMapID=1157},
[52769] = {id=52769,name="Captain By Captain",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=9937,mapID=1157,storyline={52764,52765,52766,52767,52768,52769,52770,52772,52773,52774,52978,53067,53121},series={52764,52765,52766,52767,52768,52770,52772,52773,52774,52978,53067},description="Seems like you're on your own. More shipwrecks lie along the bottom of the sea. This must have been the location of a major battle. Time to start checking dog tags to find Marshal Valentine.",objectivesText="Identify the captains of the three nearby ships.",rewardGold=234000,rewardXP=6815,rewardItems={2842,3342,3343,23405,28144,28153,56867,56868,56869,56870,56871,56872,56873,56874,61484,61495,61500,118736,131242,163633,166704,176116,232771,232775,232779,232787},starts={{npcID=141645}},mapCandidates={npc={},zone={9937}},questGiverID=141645,questType="standard",sourceQuests={52768},questLines={{id=736,name="At the Bottom of the Sea",orderIndex=5,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=736,questLineOrder=13,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=736,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=2066,db2PoiUiMapID=1157},
[52770] = {id=52770,name="Biolumi-Nuisance",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=9937,mapID=1157,storyline={52764,52765,52766,52767,52768,52769,52770,52772,52773,52774,52978,53067,53121},series={52764,52765,52766,52767,52768,52769,52772,52773,52774,52978,53067},description="<static> ... having trouble hearing you ... <static> ... electrical interference ... bioluminescent creatures ... <static> ... getting annoying ... <static>",objectivesText="Kill 10 bioluminescent creatures to fix your communications issues with Hobart.",rewardGold=234000,rewardXP=6815,starts={{npcID=141645}},mapCandidates={npc={},zone={9937}},questGiverID=141645,questType="standard",sourceQuests={52768},questLines={{id=736,name="At the Bottom of the Sea",orderIndex=6,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=736,questLineOrder=13,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=736,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=2066,db2PoiUiMapID=1157},
[52771] = {id=52771,name="Siege of Boralus: Breaking Irons",expansion=7,mapID=895,questType="world",db2Objectives={{orderIndex=0,type=0,amount=5,objectID=44850,text="Rescue Civilians"}},worldTaskTitle="Siege of Boralus: Breaking Irons",db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
[52772] = {id=52772,name="The Undersea Ledge",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,mapID=1157,storyline={52764,52765,52766,52767,52768,52769,52770,52772,52773,52774,52978,53067,53121},series={52764,52765,52766,52767,52768,52769,52770,52773,52774,52978,53067},description="So, now that we can hear each other again, lemme tell you what's been goin' on up here. Apparently we were off by like, a league. Somethin' about undersea currents, somethin' about the tides of time, yadda yadda. I think Zelling is getting rusty. Point is, you're not far off now. We're SURE that Marshal Valentine is right to the east of ya, in a shipwreck up on a ledge. Zelling says there's something else big up there too, but he can't tell what it is.",objectivesText="Find Marshal Valentine's shipwreck on the undersea ledge nearby.",rewardGold=309800,rewardXP=6815,starts={{npcID=141645}},mapCandidates={npc={},zone={}},questGiverID=141645,questType="standard",sourceQuests={52769,52770},questLines={{id=736,name="At the Bottom of the Sea",orderIndex=7,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=736,questLineOrder=13,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=736,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=2066,db2PoiUiMapID=1157},
[52773] = {id=52773,name="Water-Breathing Dragon",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=9937,mapID=1157,storyline={52764,52765,52766,52767,52768,52769,52770,52772,52773,52774,52978,53067,53121},series={52764,52765,52766,52767,52768,52769,52770,52772,52774,52978,53067},description="Huh. A dragon, you say? I suppose that makes sense. I mean, the Horde did utilize red dragons as part of their army during the second war, but... well, we don't talk about that very much anymore. Still, Valentine is on that ship. You're gonna have to get past that dragon one way or another.",objectivesText="Slay Daenistrasz .",rewardGold=169800,rewardXP=6815,rewardItems={2944},starts={{npcID=141645}},mapCandidates={npc={},zone={9937}},questGiverID=141645,questType="standard",sourceQuests={52772},questLines={{id=736,name="At the Bottom of the Sea",orderIndex=8,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=736,questLineOrder=13,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=736,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=2066,db2PoiUiMapID=1157},
[52774] = {id=52774,name="Grab and Go",level=50,requiredLevel=50,faction="horde",requiredRaces={10},categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=9937,mapID=1157,storyline={52764,52765,52766,52767,52768,52769,52770,52772,52773,52774,52978,53067,53121},series={52764,52765,52766,52767,52768,52769,52770,52772,52773,52978,53067},description="Nothin' left to do but grab that Marshal and bring him back up to the surface, then. Though I guess you might as well search the shipwreck for anything else of value. You spent all that time gettin' down there, and time is money.",objectivesText="Grab Marshal M. Valentine's body, as well as the body of the other sailor aboard his ship.",rewardGold=234000,rewardXP=6815,rewardItems={7298,109258,111921,186201,228658,228741},starts={{npcID=141645}},ends={{npcID=141645}},mapCandidates={npc={},zone={9937}},questGiverID=141645,questTurnInID=141645,questType="standard",sourceQuests={52773},questLines={{id=736,name="At the Bottom of the Sea",orderIndex=9,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=736,questLineOrder=13,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=736,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=2066,db2PoiUiMapID=1157},
