[52776] = {id=52776,name="Mission Report: Stonetusk Watch",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={52776},series={52777},description="Your followers have sent a report regarding the assault on Stonetusk Watch. It details that victory was hard-fought, but the outpost has been secured. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.",objectivesText="Deliver the victory report to Nathanos Blightcaller . Progress: Do you have news regarding the mission to Stormsong Valley?",rewardGold=23400,rewardXP=850,rewardItems={162512,162530,162531,162532,162533,162534,162535,162536},starts={{npcID=138704}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questGiverID=138704,questType="standard"},
[52777] = {id=52777,name="Stonetusk Watch",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=862,storyline={52777},series={52776},description="The raid you planned for Stonetusk Watch in Stormsong Valley was successful. Well done. The outpost is ready to be claimed. Make your way to Stonetusk Watch in Stormsong Valley and establish fortifications there. The outpost will be essential in our campaign against the Alliance. Go with honor!",objectivesText="Claim Stonetusk Watch for the Horde.",rewardGold=117000,rewardXP=3410,rewardItems={162530,162531,162532,162533,162534,162535,162536},starts={{npcID=135691}},ends={{npcID=141598}},mapCandidates={npc={862,942},zone={9042}},questType="standard",sourceQuests={52776}},
[52778] = {id=52778,name="Siege of Boralus: Crushing the Horde",expansion=7,mapID=895,questType="world",db2Objectives={{orderIndex=0,type=0,amount=5,objectID=118593,text="Horde Heroes slain"}},worldTaskTitle="Siege of Boralus: Crushing the Horde",db2QuestInfoID=137,db2QuestInfoName="Dungeon World Quest"},
