[52782] = {id=52782,name="Call to Arms: Stormsong Valley",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=1161,storyline={52782},description="We've discovered a spike of Horde activity within Stormsong Valley . We cannot allow them to get the upper hand.",objectivesText="Slay Horde within Stormsong Valley .",rewardItems={167744,169614},rewardCurrencies={{id=1602,amount=50}},starts={{npcID=143559}},ends={{npcID=141698}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[52784] = {id=52784,name="The Horde Slayer",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,storyline={52784},description="Wow! Keep it up, soldier! Slay a bit more Horde and you will go down in the record books among the Alliance. But it won't be easy, the Horde have put a bounty on your head, so watch it! For the Alliance! See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(52784)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(52784))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="While being hunted by the Horde, slay 10 Horde without dying.",mapCandidates={npc={},zone={}},questType="standard"},
[52785] = {id=52785,name="Smashing Zalamar",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=8500,mapID=863,mapCandidates={npc={},zone={8500}},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Zalamar Disrupted"},{orderIndex=1,type=0,amount=34,objectID=127142},{orderIndex=2,type=0,amount=100,objectID=127176},{orderIndex=3,type=2,amount=10,objectID=281835},{orderIndex=4,type=0,amount=34,objectID=128071}},worldTaskTitle="Smashing Zalamar",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[52786] = {id=52786,name="The Alliance Slayer",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,storyline={52786},description="Yes! Keep going, keep slaying those Alliance dogs! Slay a bit more Alliance and you may set a new record, . But it won't be easy, the Alliance have put a bounty on your head, so watch it! For the Horde! See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(52786)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(52786))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="With a bounty on your head, slay 10 Alliance without dying.",mapCandidates={npc={},zone={}},questType="standard"},
[52787] = {id=52787,name="Numbing the Pain",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={46727,46728,46729,47098,47099,47181,47186,47189,47485,47486,47487,47488,47489,47960,48419,48505,48539,48558,48773,49239,49398,49399,49401,49404,49405,49736,49737,49738,49740,49741,49869,50110,50531,50573,50787,50788,50789,50790,50795,50972,51341,52128,52431,52750,52787,53041,59641},description="The medics here are doing their best, but they've suffered heavy casualties and are strapped for healing supplies. With a few clumps of evermoss I could mix a painkilling tincture to ease the suffering of the injured. Can you forage some from the nearby trees? I'll help get Flynn stabilized. The last thing these people need is another wounded man howling in pain.",objectivesText="Gather 5 Evermoss Clumps . Progress: Did you find any evermoss?",rewardGold=176280,rewardXP=1415,rewardItems={162522},starts={{npcID=142393}},ends={{npcID=121235},{npcID=142393}},mapCandidates={npc={895,1161},zone={8567}},questType="standard",sourceQuests={49869},questLines={{id=5372,name="Trouble in Tiragarde Sound",orderIndex=37,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[52788] = {id=52788,name="Leave None Alive",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=8499,mapID=862,description="Our initial assault was a success. The Dark Iron dwarves are holding the line. Now it's our turn. You and I must cleave a path through these Zandalari and eliminate them. Our forces will handle any that remain. Our goal is to weaken their forces and find two important targets: the ship's captain and its advisor. Let's go, . If we fail here, all of our efforts will be thwarted.",rewardGold=234000,rewardXP=6815,starts={{npcID=141719}},ends={{npcID=141719}},mapCandidates={npc={862},zone={8499}},questTurnInID=141719,questType="standard",sourceQuests={52291},questLines={{id=737,name="The Strike on Zuldazar",orderIndex=12,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=737,questLineOrder=13,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=737,questLineOrder=6}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},
[52789] = {id=52789,name="Silencing the Advisor",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=875,storyline={52281,52282,52283,52284,52285,52286,52287,52288,52289,52290,52291,52473,52788,52789,52790,53072,53098},description="The ship's captain is nowhere to be found. Shandris and Falstad will handle locating him. We must go after the ship's advisor. Kelsey's logs indicate her name is Ko'jan. She may have methods to reach out to the mainland. We have to move before she tries to use any of them.",objectivesText="Kill Advisor Ko'jan . Progress: Let's get moving.",rewardGold=468000,rewardXP=8520,rewardItems={162253,162450},starts={{npcID=144024}},mapCandidates={npc={},zone={8499}},questGiverID=144024,questType="standard",sourceQuests={52788},questLines={{id=737,name="The Strike on Zuldazar",orderIndex=13,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=737,questLineOrder=13,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=737,questLineOrder=6}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=875},
[52790] = {id=52790,name="An End to the Killing",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={52281,52282,52283,52284,52285,52286,52287,52288,52289,52290,52291,52473,52788,52789,52790,53072,53098},description="Let's return to the upper decks and see what our current status is. Shandris should be there by now. I know Shandris and Falstad well enough that they will be there with the captain of this ship, dead or alive.",objectivesText="Meet Shandris Feathermoon on the deck of Gral's Call.",rewardGold=468000,rewardXP=8520,rewardItems={162253,162450},rewardCurrencies={{id=1553,amount=800}},starts={{npcID=140257}},ends={{npcID=107574}},mapCandidates={npc={84,862},zone={8499}},questType="standard",sourceQuests={52789},questLines={{id=737,name="The Strike on Zuldazar",orderIndex=14,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=737,questLineOrder=13,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=737,questLineOrder=6}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiUiMapID=84},
[52792] = {id=52792,name="Arathi Donations: Akunda's Bite",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={52792},objectivesText="Progress: We be needin' an abundance of herbs to keep dem stockpiles up an' ready.",rewardItems={152507},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142159}},ends={{npcID=142159}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[52793] = {id=52793,name="Circle the Wagons",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={52793},description="Darion and the girls should have been back by now. Maybe they had trouble on the road, that old wagon is always breaking down. I need to be sure they are safe! Can you check on them for me?",objectivesText="Find Darion, Lorraine, and Mallory. Progress: I'm getting worried, they should have been here hours ago.",rewardGold=257400,rewardXP=3085,rewardItems={55121,63550,63551,63552,63553,63554,63555,63556,63557,131434,131435},starts={{npcID=141769}},ends={{npcID=141769}},mapCandidates={npc={942},zone={9042}},questType="standard"},
[52794] = {id=52794,name="Lizards and Ledgers",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={52794},rewardItems={162540},mapCandidates={npc={},zone={9042}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=8,objectID=162540},{orderIndex=1,type=0,amount=8,objectID=141641},{orderIndex=2,type=0,amount=1,objectID=141832}},worldTaskTitle="Lizards and Ledgers",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[52795] = {id=52795,name="A Saur Point",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={52795},description="That saurolisk has been a folktale in these hills for years. \" Sourtooth , you can smell his breath from miles away\". Today that folktale attacked my family, almost killed my father and sister. It's time for it to die.",objectivesText="Slay Sourtooth Progress: I'm not leaving till Sourtooth is dead!",rewardGold=514800,rewardXP=5145,starts={{npcID=141603}},ends={{npcID=141603}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={52793}},
[52796] = {id=52796,name="Sometimes Less Is More",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={52796},description="I don't really hate saurolisk, but there seem to be a lot more around lately. Stormsong's military used to thin out the population, but they didn't show up this year. Maybe you could do the job they didn't!",objectivesText="Eliminate 8 Saurolisk.",rewardGold=257400,rewardXP=3085,starts={{npcID=141769}},ends={{npcID=141769}},mapCandidates={npc={942},zone={9042}},questType="standard"},
[52798] = {id=52798,name="A Few More Charges",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8501,mapID=864,mapCandidates={npc={},zone={8501}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=143377,text="Use the Lectric Frequency Modulator"},{orderIndex=1,type=15,amount=1,objectID=0,text="Feed lashers to the ranishu"},{orderIndex=2,type=0,amount=100,objectID=139492},{orderIndex=3,type=0,amount=34,objectID=139772},{orderIndex=4,type=0,amount=20,objectID=139929},{orderIndex=5,type=0,amount=3,objectID=142895}},worldTaskTitle="A Few More Charges",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
