[52800] = {id=52800,name="Tol Dagor: The Ashvane Overseer",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,storyline={52800},description="Tol Dagor stands as a well fortified thorn in this nation's side. As you are no doubt aware, Ashvane has taken every opportunity she could to throw any opposition into those cells. Among those in the jail are members of the Alliance that arrived alongside you and Jaina. We now have permission and the needed muscle to free them. Meet up with Taelia on the eastern shore of the island, find the overseer, and take his key. With it, we will have access to the weapon vault and cells.",objectivesText="Retrieve the Tol Dagor Master Key from Overseer Korgus . Progress: Well?",rewardGold=1029600,rewardXP=2830,rewardItems={163161},rewardCurrencies={{id=1553,amount=600}},starts={{npcID=122370}},ends={{npcID=122370}},mapCandidates={npc={},zone={8568}},questGiverID=122370,questTurnInID=122370,questType="dungeon",sourceQuests={50972}},
[52801] = {id=52801,name="Mission Report: Veiled Grotto",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={52801},series={52802},description="Your followers have sent a report regarding the assault on Veiled Grotto. It details that victory was hard-fought, but the enemies guarding the outpost have been slain. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.",objectivesText="Deliver the victory report to Halford Wyrmbane . Progress: Do you have news regarding the mission to Zuldazar?",rewardGold=23400,rewardXP=850,rewardItems={162553,163048},starts={{npcID=138704}},ends={{npcID=135612}},mapCandidates={npc={1161},zone={8568}},questGiverID=138704,questType="standard"},
[52802] = {id=52802,name="Veiled Grotto",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=1161,storyline={52802},series={52801},description="The raid you planned for Veiled Grotto in Zuldazar was successful. Well done. The outpost is ready to be claimed. Make your way to Veiled Grotto in Zuldazar and establish fortifications there. Veiled Grotto will be an essential outpost in our campaign against the Horde. For the Alliance!",objectivesText="Claim Veiled Grotto for the Alliance.",rewardGold=117000,rewardXP=3410,rewardItems={162553,162577,162604,162646,162977,163039,163041,163043,163044,163046,163047,163048},starts={{npcID=135612}},ends={{npcID=141884}},mapCandidates={npc={862,1161},zone={8499}},questType="standard",sourceQuests={52801}},
