[52806] = {id=52806,name="A Looming Threat",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=1497,mapID=62,storyline={50476,50642,50646,50647,50738,50740,50772,50800,50823,50837,50878,50879,50880,52436,52437,52438,52806,52967,52970,52971,52981,53604,53605,53606,53608,53609,53610,53627},series={52438,52967,52970,52971,52981,53610},description="This stalemate is unwise to pursue. Let's regroup at the Blackwood Den.",objectivesText="Regroup with Lady Sylvanas Windrunner at the Blackwood Den. Progress: Death is an inevitability.",rewardGold=1000,rewardXP=710,rewardItems={158075,158937,160251,163127,163128},starts={{npcID=134554}},ends={{npcID=134554}},mapCandidates={npc={62},zone={1497}},questType="standard",sourceQuests={52438},questLines={{id=584,name="The Warchief's Command",orderIndex=22,flags=0}},db2PoiMapID=1,db2PoiUiMapID=62},
