[52852] = {id=52852,name="Mugamba Overlook",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=1161,storyline={52852},series={52851},description="The raid you planned for Mugamba Overlook in Zuldazar was successful. Well done. The outpost is ready to be claimed. Make your way to Mugamba Overlook in Zuldazar and establish fortifications there. Mugamba Overlook will be an essential outpost in our campaign against the Horde. For the Alliance!",objectivesText="Claim Mugamba Overlook for the Alliance.",rewardGold=117000,rewardXP=3410,rewardItems={109076,154166,162553,162577,162604,162646,162977,163039,163041,163043,163044,163046,163047,163048},starts={{npcID=135612}},ends={{npcID=141949}},mapCandidates={npc={862,1161},zone={8499}},questType="standard",sourceQuests={52851}},
[52855] = {id=52855,name="Alchemy is an Inexact Science",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={52855},description="Hey, look. It worked, right? Mostly. I mean, it DID get bigger. Don't look at me like that! So there are some... weird side effects going on. When has that ever gotten in the way of science before? Okay, okay, okay! I have an idea. Go and get me everything on this list. And be quick about it! I think these Zandalari might do something to me if you-- if WE-- don't fix this. <Alexxi hastily pens a list of ingredients and hands it to you.> Do me a solid, eh?",objectivesText="Gather 1 Crown of Torcali and 8 Glowfly Incandescence for Trader Alexxi in Warbeast Kraal. Progress: Those claws look really sharp, <name>. Do you have what I need?",rewardGold=234000,rewardXP=6815,rewardItems={162586,162587},starts={{npcID=122129}},ends={{npcID=122129}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={47260}},
