[52857] = {id=52857,name="Held For Observation",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={52857},description="<Trader Alexxi hurriedly combines the ingredients.> That should do it. Go on and get this down your direhorn's gullet. Don't worry, nothing could possibly go wrong with a concoction made under any kind of duress. Also, do I seem like the kind of goblin who would give you something dangerous? On purpose? ... Don't answer that. Hurry, before they stab me.",objectivesText="Administer the remedy to your direhorn. Progress: <The direhorn hiccoughs in distress.>",rewardGold=23400,rewardXP=850,rewardItems={69251,162589,168408},starts={{npcID=122129}},ends={{npcID=121706}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={52855}},
