[52886] = {id=52886,name="Mission Report: Verdant Hollow",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={52886},series={52888},description="Your followers have sent a report regarding the assault on Verdant Hollow. It details that victory was hard-fought, but the enemies guarding the outpost have been slain. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.",objectivesText="Deliver the victory report to Halford Wyrmbane . Progress: Do you have news regarding the mission to Zuldazar?",rewardGold=23400,rewardXP=850,rewardItems={162604,163046},starts={{npcID=138704}},ends={{npcID=135612}},mapCandidates={npc={1161},zone={8568}},questGiverID=138704,questType="standard"},
