[52942] = {id=52942,name="Restoring Old Bonds",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=85,storyline={51479,52942,52943,52945,52955,53353,53354,53355,53466,53467},description="We must speak to Grommash Hellscream and remind him of his debt to us. Everything rests on this mission, <name>. I hope your skills in diplomacy are greater than mine. Be on your guard; we do not know what to expect on the other side.",objectivesText="Speak with Oculeth to travel to Draenor and meet with the Mag'har.",rewardGold=341600,rewardXP=5465,rewardItems={161330},starts={{npcID=126066}},ends={{npcID=142422}},mapCandidates={npc={85,1170},zone={8670}},questType="standard",sourceQuests={53355},questLines={{id=780,name="Allies of the Horde: Mag'har Orc",orderIndex=5,flags=0}},db2PoiMapID=1917,db2PoiUiMapID=1170},
[52943] = {id=52943,name="Calling Out the Clans",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=9786,mapID=1170,storyline={51479,52942,52943,52945,52955,53353,53354,53355,53466,53467},description="This Overlord Geya'rah has a fire inside her. I may come to like her... if she doesn't kill us. We have but one chance. You pay homage to the symbol of each clan, and I will speak of it. Show respect--or they will show us the executioner's blade.",objectivesText="Pay homage to the orc clan symbols. Progress: I do not have time for this.",rewardGold=331700,rewardXP=5465,rewardItems={161330},starts={{npcID=142422}},ends={{npcID=142109}},mapCandidates={npc={1170},zone={9786}},questType="standard",sourceQuests={52942},questLines={{id=780,name="Allies of the Horde: Mag'har Orc",orderIndex=6,flags=0}},db2PoiMapID=1917,db2PoiUiMapID=1170},
[52944] = {id=52944,name="Call to Arms: Drustvar",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=1161,storyline={52944},description="We've discovered a spike of Horde activity within Drustvar . We cannot allow them to get the upper hand.",objectivesText="Slay Horde within Drustvar .",rewardCurrencies={{id=1602,amount=50}},starts={{npcID=143559}},ends={{npcID=143559}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[52945] = {id=52945,name="Bonds Forged Through Battle",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=9786,mapID=1170,storyline={51479,52942,52943,52945,52955,53353,53354,53355,53466,53467},description="Geya'rah has a fiery spirit... like her mother. Perhaps facing a common foe will ease her wariness. We subdued the ogre clans long ago. But every so often, one of their bravest--and stupidest--stirs the embers of rebellion. Today is such a day. You and Eitrigg will join Geya'rah in putting down the ogre uprising. Prove yourself in battle and you may earn her respect.",objectivesText="Assist Geya'rah in putting down the ogre uprising. Progress: Don't slow me down.",rewardGold=309800,rewardXP=5465,rewardItems={161330,162025},starts={{npcID=142275}},ends={{npcID=142275}},mapCandidates={npc={1170},zone={9786}},questTurnInID=142275,questType="standard",sourceQuests={52943},questLines={{id=780,name="Allies of the Horde: Mag'har Orc",orderIndex=7,flags=0}},db2PoiMapID=1917,db2PoiUiMapID=1170},
