[52955] = {id=52955,name="Tyranny of the Light",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=14,mapID=1,storyline={51479,52942,52943,52945,52955,53353,53354,53355,53466,53467},description="If it is not an uprising of ogres or the promise of starvation, it's the constant threat of the Lightbound. Should the reports prove true, this is the closest they have dared approach our stronghold in quite some time. Come or stay, but make your decision quickly.",objectivesText="Assist Geya'rah against the Tyranny of the Light.",rewardGold=169800,rewardXP=5465,rewardItems={161330},starts={{npcID=137837}},ends={{npcID=143845}},mapCandidates={npc={1},zone={14}},questGiverID=137837,questType="standard",sourceQuests={52945},questLines={{id=780,name="Allies of the Horde: Mag'har Orc",orderIndex=8,flags=0}},db2PoiMapID=1,db2PoiUiMapID=1},
[52956] = {id=52956,name="Call to Arms: Tiragarde Sound",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=862,storyline={52956},description="Its time to hit the Alliance at the source. Travel to Tiragarde Sound and slay every Alliance you find. It shouldn't be hard to find them in their own territory.",objectivesText="Slay Alliance within Tiragarde Sound .",rewardItems={169614},rewardCurrencies={{id=1602,amount=50}},starts={{npcID=143536}},ends={{npcID=143536}},mapCandidates={npc={862},zone={8499}},questType="standard"},
