[52962] = {id=52962,name="Mission Report: Mistvine Ledge",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={52962},series={52963},description="Your followers have sent a report regarding the assault on Mistvine Ledge. It details that victory was hard-fought, but the enemies surrounding the outpost have been slain. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.",objectivesText="Deliver the victory report to Halford Wyrmbane . Progress: Do you have news regarding the mission to Zuldazar?",rewardGold=23400,rewardXP=850,rewardItems={162646,163044},starts={{npcID=138704}},ends={{npcID=135612}},mapCandidates={npc={1161},zone={8568}},questGiverID=138704,questType="standard"},
[52963] = {id=52963,name="Mistvine Ledge",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=1161,storyline={52963},series={52962},description="The raid you planned for Mistvine Ledge in Zuldazar was successful. Well done. The outpost is ready to be claimed. Make your way to Mistvine Ledge in Zuldazar and establish fortifications there. Mistvine Ledge will be an essential outpost in our campaign against the Horde. For the Alliance!",objectivesText="Claim Mistvine Ledge for the Alliance.",rewardGold=117000,rewardXP=3410,rewardItems={109076,162553,162577,162604,162646,162977,163039,163041,163043,163044,163046,163047,163048},starts={{npcID=135612}},ends={{npcID=142288}},mapCandidates={npc={862,1161},zone={8499}},questType="standard",sourceQuests={52962}},
