[52965] = {id=52965,name="A Winter Veil Gift",level=10,requiredLevel=10,faction="both",categories={"seasonal"},flags={},sharable=true,event="Feast of Winter Veil",expansion=7,zoneID=1637,mapID=85,storyline={52965},rewardItems={34426,43504,46740,67443,70938,90892,104319,116761,128653,139341,151350,162642,162643,162644,172224,178528,187561,192094,209871,218311,244908},starts={{npcID=187236}},ends={{npcID=187236}},startObjects={{objectID=187236}},coords={x=0.335,y=0.66,source="quest_giver",mapID=85},mapCandidates={npc={85,87},zone={1637}},questType="standard"},
[52967] = {id=52967,name="Saurfang Returns",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=148,mapID=62,storyline={50476,50642,50646,50647,50738,50740,50772,50800,50823,50837,50878,50879,50880,52436,52437,52438,52806,52967,52970,52971,52981,53604,53605,53606,53608,53609,53610,53627},series={52438,52806,52970,52971,52981,53610},description="Saurfang! It's about time. Look around you, hero! What a lovely sight -- the wisps are scattering. One by one, the walls come crashing down. Now is the time. The World Tree is ours for the taking! Find Saurfang. We shall finish this once and for all.",objectivesText="Find Saurfang in Lor'danel.",rewardGold=1000,rewardXP=710,rewardItems={158075,158937,160251,163127,163128},starts={{npcID=134554}},ends={{npcID=142310}},mapCandidates={npc={62},zone={148}},questType="standard",sourceQuests={52806},questLines={{id=584,name="The Warchief's Command",orderIndex=23,flags=0}},db2PoiMapID=1,db2PoiUiMapID=62},
[52968] = {id=52968,name="Time for a Little Blood",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={52968},objectivesText="Assembly forces slain",rewardItems={162649},mapCandidates={npc={},zone={9042}},questType="world",db2Objectives={{text="Assembly forces slain",amount=12,type=0,objectID=142255,orderIndex=1}},worldTaskTitle="Time for a Little Blood",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[52970] = {id=52970,name="No Small Mercy",level=10,requiredLevel=10,faction="horde",sharable=false,expansion=7,zoneID=148,mapID=62,series={52438,52806,52967,52971,53610,52981},description="I will not slay innocents. If they do not raise arms against us, we shall spare them. Enter Lor'danel and capture any civilians you find there. They shall be questioned and then released.",rewardGold=2000,rewardXP=1415,starts={{npcID=142310}},ends={{npcID=142310}},mapCandidates={npc={62},zone={148}},questType="standard",sourceQuests={52967},questLines={{id=584,name="The Warchief's Command",orderIndex=24,flags=0}}},
[52971] = {id=52971,name="Seaside Rendezvous",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=148,mapID=62,storyline={50476,50642,50646,50647,50738,50740,50772,50800,50823,50837,50878,50879,50880,52436,52437,52438,52806,52967,52970,52971,52981,53604,53605,53606,53608,53609,53610,53627},series={52438,52806,52967,52970,52981,53610},description="Lor'danel has mustered significant reinforcements on its shore. Enough to drive us back. One swift strike and we can end this threat! You will break through their lines and slay the two commanders. Without leadership this force will crumble.",objectivesText="Kill Caranne Briarbow and Ariel Stagguard",rewardGold=2000,rewardXP=1415,rewardItems={158075,158937,160251,163127,163128},starts={{npcID=142310}},ends={{npcID=142310}},mapCandidates={npc={62},zone={148}},questType="standard",sourceQuests={52967},questLines={{id=584,name="The Warchief's Command",orderIndex=26,flags=0}},db2PoiMapID=1,db2PoiUiMapID=62},
[52972] = {id=52972,name="Favored Grandchild",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={52972},objectivesText="Speak to Shepherd Milbrooke",rewardItems={159781,162647},mapCandidates={npc={},zone={9042}},questType="world",db2Objectives={{text="Speak to Shepherd Milbrooke",amount=1,type=0,objectID=142932,orderIndex=0}},worldTaskTitle="Favored Grandchild",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[52973] = {id=52973,name="A Threat from the North",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=141,mapID=57,storyline={52058,52060,52062,52072,52116,52197,52234,52240,52242,52245,52256,52257,52279,52973,52974,52975,52977,53095,53310,53551,53616,53617,53619,53621,53622},series={52974,52975,52977,53622},description="The Horde must have scaled the mountains of Felwood in the North. The wisp wall is failing, it is only a matter of time before the Horde breaks through. They will attack us from both sides. We must weather this attack together.",objectivesText="Find Malfurion Stormrage in Lor'danel.",rewardGold=200,rewardXP=175,rewardItems={163127},starts={{npcID=134578}},ends={{npcID=140877}},mapCandidates={npc={57},zone={141}},questType="standard",sourceQuests={52279},questLines={{id=637,name="The Warchief's Command",orderIndex=18,flags=0}},db2PoiMapID=1,db2PoiUiMapID=62,db2QuestSortName="Paladin"},
[52974] = {id=52974,name="Rescue Effort",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=148,mapID=57,storyline={52058,52060,52062,52072,52116,52197,52234,52240,52242,52245,52256,52257,52279,52973,52974,52975,52977,53095,53310,53551,53616,53617,53619,53621,53622},series={52973,52975,52977,53622},description="The suddenness of the Horde's attack gave citizens here little time to flee. Many are hiding in Lor'danel, waiting for help. Locate these civilians and send them to safety. We're counting on you, <name>.",objectivesText="Rescue 8 Lor'danel citizens .",rewardGold=2000,rewardXP=1415,rewardItems={163127},starts={{npcID=140877}},ends={{npcID=134578}},mapCandidates={npc={57},zone={148}},questType="standard",sourceQuests={52973},questLines={{id=637,name="The Warchief's Command",orderIndex=19,flags=0}},db2PoiMapID=1,db2PoiUiMapID=62},
[52975] = {id=52975,name="Action This Day",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=148,mapID=57,storyline={52058,52060,52062,52072,52116,52197,52234,52240,52242,52245,52256,52257,52279,52973,52974,52975,52977,53095,53310,53551,53616,53617,53619,53621,53622},series={52973,52974,52977,53622},description="Two of the Horde's strongest warriors have led a charge to try and capture our fleet. We cannot allow this, <name>. If they take our ships, they will use them to sail to Darnassus! Slay the two warriors leading the attack, and the rest of them will give up the fight.",objectivesText="Eliminate Gormok Axefall , and Ragash Bloodwish .",rewardGold=2000,rewardXP=1415,rewardItems={163127},starts={{npcID=134578}},ends={{npcID=134578}},mapCandidates={npc={57},zone={148}},questType="standard",sourceQuests={52973},questLines={{id=637,name="The Warchief's Command",orderIndex=21,flags=0}},db2PoiMapID=1,db2PoiUiMapID=62},
[52977] = {id=52977,name="The Guidance of Our Shan'do",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=1657,mapID=57,storyline={52058,52060,52062,52072,52116,52197,52234,52240,52242,52245,52256,52257,52279,52973,52974,52975,52977,53095,53310,53551,53616,53617,53619,53621,53622},series={52973,52974,52975,53622},description="Lor'danel is overrun. The Horde... they -- they just don't relent. There is nothing we can do, <name>. We must find our Shan'do and ask for his guidance. He is the only one who can save us.",objectivesText="Find Malfurion Stormrage in Darkshore.",rewardGold=2000,rewardXP=1415,rewardItems={163127},starts={{npcID=134578}},ends={{npcID=142978}},mapCandidates={npc={57,89},zone={1657}},questType="standard",sourceQuests={52974,52975,53622},questLines={{id=637,name="The Warchief's Command",orderIndex=22,flags=0}},db2PoiMapID=1,db2PoiUiMapID=89},
[52978] = {id=52978,name="With Prince in Tow",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9937,mapID=862,storyline={52764,52765,52766,52767,52768,52769,52770,52772,52773,52774,52978,53067,53121},series={52764,52765,52766,52767,52768,52769,52770,52772,52773,52774,53067},description="Let's set sail for Zandalar. In case you hadn't noticed, we've been dealing with a bit of Alliance interference while you were gone.",objectivesText="Speak with Dread-Admiral Tattersail to return to Zuldazar.",rewardGold=234000,rewardXP=6815,rewardItems={245470},rewardCurrencies={{id=1553,amount=800}},starts={{npcID=141644}},ends={{npcID=135691}},mapCandidates={npc={862},zone={9937}},questGiverID=141644,questType="standard",sourceQuests={52774},questLines={{id=736,name="At the Bottom of the Sea",orderIndex=11,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=736,questLineOrder=13,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=736,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
