[52981] = {id=52981,name="Killer Queen",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=148,mapID=62,storyline={50476,50642,50646,50647,50738,50740,50772,50800,50823,50837,50878,50879,50880,52436,52437,52438,52806,52967,52970,52971,52981,53604,53605,53606,53608,53609,53610,53627},series={52438,52806,52967,52970,52971,53610},description="Lor'danel is now secure, but something is amiss... there has been no sign of Stormrage. Malfurion would have never let Lor'danel fall without a fight. He must have gone after her. My army has approached from the North, and our reinforcements have arrived from the South -- which means that they are not along any of the roads. Search the forest with me, <name>. We will find them and be done with this once and for all.",objectivesText="Scour the forest of Darkshore to find the Warchief. Progress: The Horde endures.",rewardGold=6000,rewardXP=2125,rewardItems={158075,158937,160251,163127,163128},starts={{npcID=142310}},ends={{npcID=144466}},mapCandidates={npc={62},zone={148}},questType="standard",sourceQuests={52970,52971,53610},questLines={{id=584,name="The Warchief's Command",orderIndex=27,flags=0}},db2PoiMapID=1,db2PoiUiMapID=62},
