[52990] = {id=52990,name="Return to the Harbor",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={52183,52184,52185,52186,52187,52188,52189,52190,52191,52192,52861,52990,53003},series={52190,52191,52192,53003},description="With the scepter in hand, let us return to the portal. I believe Stone would agree with me when I say that it is best for us to get away from Kul Tiras for a while.",objectivesText="Return to Nathanos Blightcaller in Plunder Harbor.",rewardGold=23400,rewardXP=850,starts={{npcID=141602}},ends={{npcID=140485}},mapCandidates={npc={895},zone={8567}},questGiverID=141602,questType="standard",sourceQuests={52190},questLines={{id=629,name="The Strike on Boralus",orderIndex=8,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=629,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=629,questLineOrder=6}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53003] = {id=53003,name="A Cycle of Hatred",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={52183,52184,52185,52186,52187,52188,52189,52190,52191,52192,52861,52990,53003},series={52190,52191,52192,52990},description="We have raised new champions for the Horde, established footholds on Kul Tiran soil, and stolen one of their precious artifacts. We hold greater power and sway over our enemies than we have before. Sylvanas has great plans for our Horde, <name>. I will allow you the pleasure of reporting our victories to her personally.",objectivesText="Report to Sylvanas Windrunner in Orgrimmar.",rewardGold=23400,rewardXP=850,rewardCurrencies={{id=1553,amount=800}},starts={{npcID=135691}},ends={{npcID=134711}},mapCandidates={npc={85,862},zone={8499}},questType="standard",sourceQuests={52192},questLines={{id=629,name="The Strike on Boralus",orderIndex=12,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=629,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=629,questLineOrder=6}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1,db2PoiUiMapID=85},
[53006] = {id=53006,name="Mission Report: Grimwatt's Crash",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={53006},series={53007},description="Your followers have sent a report regarding the rescue mission to Grimwatt's Crash. It details that the supplies were recovered and the enemies surrounding the crash site have been slain. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.",objectivesText="Deliver the victory report to Halford Wyrmbane . Progress: Do you have news regarding the mission to Nazmir?",rewardGold=23400,rewardXP=850,rewardItems={162977,163043},starts={{npcID=138704}},ends={{npcID=135612}},mapCandidates={npc={1161},zone={8568}},questGiverID=138704,questType="standard"},
[53007] = {id=53007,name="Grimwatt's Crash",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=1161,storyline={53007},series={53006},description="The rescue that you planned for Grimwatt's Crash in Nazmir was successful. Well done. I believe we should fortify the crash site and turn it into an outpost. Make your way to Grimwatt's Crash and establish fortifications there. Grimwatt's Crash will be an essential outpost in our campaign against the Horde. For the Alliance!",objectivesText="Claim Grimwatt's Crash for the Alliance.",rewardGold=117000,rewardXP=3410,rewardItems={162553,162577,162604,162646,162977,163039,163041,163043,163044,163046,163047,163048},starts={{npcID=135612}},ends={{npcID=142360}},mapCandidates={npc={863,1161},zone={8500}},questType="standard",sourceQuests={53006}},
