[53041] = {id=53041,name="Sampling the Goods",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={"loremaster"},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={47181,47485,47486,47487,47488,50531,50573,53041},series={47485,47486,47488,47489,50531,50573},description="Bridgeport is a major trade hub for this area. Naturally, Ashvane has offices and workshops here. Check around town and see if you can learn anything about this new material and how they're using it. If you can lift a sample for us to send back to Boralus, even better. I gotta stay here and keep an eye on someone.",objectivesText="Collect the Chemist's Notes and a Raw Azerite Sample . Progress: <Flynn side-eyes you while trying his best to look casual.> You get what we need?",rewardGold=128700,rewardXP=710,rewardItems={158065,158066,163032,163034},starts={{npcID=134166}},ends={{npcID=134166}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={50531},questLines={{id=585,name="The Ashvane Trading Company",orderIndex=7,flags=0},{id=5372,name="Trouble in Tiragarde Sound",orderIndex=17,flags=0}},campaigns={{id=215,title="Battle for Azeroth",questLineID=5372,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
