[53043] = {id=53043,name="Mission Report: Vulture's Nest",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={53043},series={53044},description="Your followers have sent a report regarding the mission to capture Vulture's Nest in Vol'dun. It details that the mission was a success and that the troops holding the outpost have requested reinforcements. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.",objectivesText="Deliver the victory report to Halford Wyrmbane . Progress: Do you have news regarding the mission to Vol'dun?",rewardGold=23400,rewardXP=850,rewardItems={163039,163041},starts={{npcID=138704}},ends={{npcID=135612}},mapCandidates={npc={1161},zone={8568}},questGiverID=138704,questType="standard"},
[53044] = {id=53044,name="Vulture's Nest",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=1161,storyline={53044},series={53043},description="The mission to take Vulture's Nest in Vol'dun was successful. Well done. The outpost is ready to be claimed. Make your way to Vulture's Nest and establish fortifications there. It will be an essential outpost in our campaign against the Horde. For the Alliance!",objectivesText="Claim Vulture's Nest for the Alliance.",rewardGold=117000,rewardXP=3410,rewardItems={162553,162577,162604,162646,162977,163039,163041,163043,163044,163046,163047,163048},starts={{npcID=135612}},ends={{npcID=142555}},mapCandidates={npc={864,1161},zone={8501}},questType="standard",sourceQuests={53043}},
[53045] = {id=53045,name="Surveying the Wharf",level=30,requiredLevel=30,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={53045},description="Thresher's Wharf is a bustling fishing hub just across the delta from Fort Daelin. It was also in the direct war path of the naga -- who knows what remains now. If you could stop in and check in on its leader, Coxswain Hook , you'd have my gratitude. I must focus on tending to the wounded here and preparing for the naga's next assault.",objectivesText="Speak to Coxswain Hook in Thresher's Wharf.",rewardGold=25740,rewardXP=515,starts={{npcID=131001}},ends={{npcID=133576}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={49831},nextQuests={50376}},
[53050] = {id=53050,name="Deeper Into Kul Tiras",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={"loremaster"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={51224,51231,51233,51234,51332,51340,51421,51435,51436,51437,51438,51439,51440,51441,51442,51526,51532,51536,51587,51643,51674,51675,51691,51696,51753,51800,51801,51802,51803,51916,51975,51979,51984,51985,51986,51987,52444,52451,52749,53050,53056,53064},series={51979},description="It is time for us to further our hold on Kul Tiras. Return to the Banshee's Wail. From there we shall plan our next course of action.",objectivesText="Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar.",rewardGold=13740,rewardXP=600,ends={{npcID=135691}},coords={mapID=862,source="quest_giver",x=0.584,y=0.626},mapCandidates={npc={862},zone={8499}},questType="standard",questLines={{id=623,name="The Kul Tiras Campaign",orderIndex=4,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=4,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=623,questLineOrder=4,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[53052] = {id=53052,name="Deeper Into Zandalar",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51961},description="Our advisors have decided that now is the correct time to further our hold on Zandalar. Return to the Wind's Redemption posthaste. We shall leave for new lands immediately.",objectivesText="Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.",rewardGold=13740,rewardXP=600,ends={{npcID=135612}},coords={mapID=1161,source="quest_giver",x=0.6945,y=0.2665},mapCandidates={npc={1161},zone={8568}},questType="standard",nextQuests={51961},questLines={{id=624,name="The Zandalar Campaign",orderIndex=4,flags=0},{id=5374,name="The Zandalar Campaign",orderIndex=4,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=4,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=4,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=624,questLineOrder=3,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53053] = {id=53053,name="To The Mugambala!",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={53053},description="The Rastari have proven to be formidable allies in combat, and reports are coming in that help explain how they've honed their battle prowess. Je'stry the Untamed has a fighting ring setup at the base of Mount Mugambala that could prove useful for getting ready for war. We've dispatched our troops to take advantage of these training grounds, go and see what High Warlord Volrath has uncovered.",objectivesText="Speak with High Warlord Volrath at The Mugambala.",starts={{npcID=138708}},ends={{npcID=143536}},mapCandidates={npc={862},zone={8499}},questType="standard"},
[53054] = {id=53054,name="Dueler's Guild",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={53054},description="I figured a war-torn <race> such as your self would find benefit in this Dueler's Guild. Speak with a nearby Rastari Guard to participate in the carnage.",objectivesText="Speak with a nearby Rastari Guard .",starts={{npcID=143536}},ends={{npcID=143536}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={53053}},
[53055] = {id=53055,name="Pushing Our Influence",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={52443},description="Our scouts have identified a location for a final major foothold in Zandalar. Return to the Wind's Redemption so we can ship out.",objectivesText="Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.",rewardGold=13740,rewardXP=600,ends={{npcID=135612}},coords={mapID=1161,source="quest_giver",x=0.6945,y=0.2665},mapCandidates={npc={1161},zone={8568}},questType="standard",questLines={{id=624,name="The Zandalar Campaign",orderIndex=5,flags=0},{id=5374,name="The Zandalar Campaign",orderIndex=5,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=5,flags=0},{id=5380,name="Gaining a Foothold",orderIndex=5,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=624,questLineOrder=3,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
