[53061] = {id=53061,name="The Azerite Advantage",level=35,requiredLevel=35,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={51903,51904,53061},series={51903,51904},description="<name>, we have received intelligence pointing us toward a reliable source of Azerite. We must acquire this precious resource before our enemies in the Horde. Report to the Wind's Redemption as soon as possible to aid in extraction.",objectivesText="Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.",rewardGold=23870,rewardXP=600,ends={{npcID=135612}},coords={mapID=1161,source="quest_giver",x=0.6945,y=0.2665},mapCandidates={npc={1161},zone={8568}},questType="standard",nextQuests={51903},questLines={{id=619,name="Island Expedition",orderIndex=2,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=619,questLineOrder=7,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53062] = {id=53062,name="The Azerite Advantage",level=35,requiredLevel=35,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={51870,51888,53062},series={51870,51888},description="We have received intelligence pointing us toward a reliable source of Azerite. We must move quickly to acquire these resources for the Horde. Report to the Banshee's Wail to aid in this urgent mission.",objectivesText="Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar.",rewardGold=13740,rewardXP=600,ends={{npcID=135691}},coords={mapID=862,source="quest_giver",x=0.584,y=0.626},mapCandidates={npc={862},zone={8499}},questType="standard",nextQuests={51870},questLines={{id=620,name="Island Expedition",orderIndex=2,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=620,questLineOrder=8,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[53063] = {id=53063,name="A Mission of Unity",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={51088,51129,51150,51167,51168,51169,51170,51177,51190,51191,51192,51193,51201,51229,51279,51280,51281,51282,51283,51308,51309,51331,51349,51350,51351,51359,51366,51369,51389,51391,51394,51395,51402,51418,51544,51569,51570,51571,51572,51918,51961,51967,51968,51969,52003,52008,52013,52443,52450,52654,53052,53055,53063},series={51918},description="You have done much for the Alliance during your time here in Kul Tiras, <name>. Today we must ask more of you. Return to the Wind's Redemption when you have the chance so that we can discuss.",objectivesText="Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor. Progress: The Alliance needs us to bring our new allies into the fold.",rewardGold=23400,rewardXP=850,starts={{npcID=135612}},ends={{npcID=135612}},mapCandidates={npc={1161},zone={8568}},questGiverID=135612,questType="standard",sourceQuests={51967,51968,51969},nextQuests={51918},questLines={{id=616,name="Uniting Kul Tiras",orderIndex=2,flags=0},{id=5378,name="Gaining a Foothold",orderIndex=54,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=616,questLineOrder=8,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=5378,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53064] = {id=53064,name="A Mission of Unity",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={51224,51231,51233,51234,51332,51340,51421,51435,51436,51437,51438,51439,51440,51441,51442,51526,51532,51536,51587,51643,51674,51675,51691,51696,51753,51800,51801,51802,51803,51916,51975,51979,51984,51985,51986,51987,52444,52451,52749,53050,53056,53064},series={51916},description="You have undertaken great journeys during your time here in Zandalar. It is time for your next mission. Report to the Banshee's Wail.",objectivesText="Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar. Progress: We must bring the Zandalari into the Horde.",rewardGold=23400,rewardXP=850,starts={{npcID=135691}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questGiverID=135691,questType="standard",sourceQuests={51984,51985,51986},nextQuests={51916},questLines={{id=617,name="Uniting Zandalar",orderIndex=2,flags=0},{id=5388,name="Gaining a Foothold",orderIndex=41,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=617,questLineOrder=9,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=5388,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
