[53068] = {id=53068,name="Operation: Hook and Line",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={53068},series={52183},description="Thanks to the help of our new allies, we have devised a plan to extract a powerful tidesage artifact from Boralus. I have already sent Valentine to get us started. Report to the Banshee's Wail posthaste.",objectivesText="Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar.",rewardGold=23400,rewardXP=850,starts={{npcID=141644}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questGiverID=141644,questType="standard",sourceQuests={52978},nextQuests={52183}},
[53069] = {id=53069,name="Operation: Blood Arrow",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={52147,52150,52156,52158,52170,52171,52172,52208,52219,53069},series={52147},description="We have uncovered the location of a high priority target in Nazmir. Return to the Wind's Redemption for your briefing.",objectivesText="Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.",rewardGold=23400,rewardXP=850,rewardItems={161332,163196},ends={{npcID=135612}},coords={mapID=1161,source="quest_giver",x=0.6945,y=0.2665},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={52146},nextQuests={52147},questLines={{id=632,name="Chasing Darkness",orderIndex=9,flags=1}},campaigns={{id=1,title="War Campaign",questLineID=632,questLineOrder=10,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=632,questLineOrder=3}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53070] = {id=53070,name="Operation: Cutpurse",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={52154,52173,52203,52204,52205,52241,52247,52259,52260,52261,53070},series={52154},description="It is time to reconvene for our next mission, though Shandris and I disagree on what exactly that should entail. Meet us on the Wind's Redemption.",objectivesText="Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.",rewardGold=23400,rewardXP=850,rewardItems={161422},ends={{npcID=135612}},coords={mapID=1161,source="quest_giver",x=0.6945,y=0.2665},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={52219},nextQuests={52154},questLines={{id=633,name="A Golden Opportunity",orderIndex=10,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=633,questLineOrder=11,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=633,questLineOrder=4}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53071] = {id=53071,name="Operation: Gryphon's Claw",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={52308,52489,52490,52491,52492,52493,52494,52495,52496,53071,53131},series={52308},description="SI:7 has procured some interesting intel. I request your presence on the Wind's Redemption immediately to help decide our next course of action.",objectivesText="Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.",rewardGold=23400,rewardXP=850,rewardItems={162528,162529,162537},ends={{npcID=135612}},coords={mapID=1161,source="quest_giver",x=0.6945,y=0.2665},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={52261},nextQuests={52308},questLines={{id=638,name="Blood in the Water",orderIndex=10,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=638,questLineOrder=12,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=638,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53072] = {id=53072,name="Operation: Heartstrike",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={52281,52282,52283,52284,52285,52286,52287,52288,52289,52290,52291,52473,52788,52789,52790,53072,53098},series={52473},description="We've taken out quite a number of high priority targets, <name>. All thanks to your help. It is time to strike directly at the heart of the Zandalari empire. Report to the Wind's Redemption as soon as you are able. We will get started from there.",objectivesText="Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.",rewardGold=23400,rewardXP=850,rewardItems={162253,162450},ends={{npcID=135612}},coords={mapID=1161,source="quest_giver",x=0.6945,y=0.2665},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={52496},nextQuests={52473},questLines={{id=737,name="The Strike on Zuldazar",orderIndex=16,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=737,questLineOrder=13,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=737,questLineOrder=6}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53073] = {id=53073,name="Hook Point Investigation",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53073},description="I'm sure you've heard the constant sound of battle coming from Hook Point. We sent scouts over to find out why the fighting never seems to end, and discovered an unexpected training ground. Daniel Poole at Hook Point is running some sort of fight circuit near the Tradewind Market. Seek out Grand Marshal Tremblade at our War Headquarters and find out what they've learned.",objectivesText="Speak with Grand Marshal Tremblade at Hook Point.",starts={{npcID=135614}},ends={{npcID=143559}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[53074] = {id=53074,name="Reinforcements",level=35,requiredLevel=35,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={47189,51714,51715,52544,52654,53074,53332},series={51714,51715},description="The resources you gather can be used to recruit new troops for the war effort. Return to me periodically to issue new recruitment orders for your missions. If you have available resources, you should use them now to issue your first recruitment order. The war effort rages on even as we speak. We have need of fresh recruits.",objectivesText="Speak with Mathias Shaw to issue a recruitment order. Progress: Have you issued the recruitment order?",rewardGold=128700,rewardXP=2395,rewardItems={29927,29932,29935,29939,29946,63909,63910,63911,175414,175427,175428,175429},starts={{npcID=135614}},ends={{npcID=135614}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={51715},questLines={{id=615,name="Mission from the King",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[53075] = {id=53075,name="Dueler's Guild",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53075},description="I figured a war-torn <race> such as your self would benefit from training in the Dueler's Guild. Speak with a nearby bouncer to participate in the carnage.",objectivesText="Speak with a nearby bouncer .",starts={{npcID=143559}},ends={{npcID=143559}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={53073}},
