[53079] = {id=53079,name="Reinforcements",level=35,requiredLevel=35,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=862,storyline={47332,51770,51771,52746,52749,53079,53333},series={51770,51771},description="The resources you gather can be used to recruit new troops for the war effort. Return to me periodically to issue new recruitment orders for your missions. If you have available resources, you should use them now to issue your first recruitment order. The war effort rages on even as we speak. We have need of fresh recruits.",objectivesText="Speak with Garona Halforcen to issue a recruitment order. Progress: Have you issued the recruitment order?",rewardGold=128700,rewardXP=2395,rewardItems={29927,29932,29935,29939,29946,63909,63910,63911,175414,175427,175428,175429},starts={{npcID=138708}},ends={{npcID=138708}},mapCandidates={npc={862},zone={9042}},questType="standard",sourceQuests={51771},questLines={{id=618,name="Mission from the Warchief",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[53081] = {id=53081,name="Mission Report: Spare Parts",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={53081},series={53082},description="Your followers have sent a report regarding the mission to collect salvage for Stonefist Watch. It details that the mission was a success and the necessary materials have been collected. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.",objectivesText="Deliver the victory report to Nathanos Blightcaller . Progress: Do you have news regarding the mission for Stonefist Watch?",rewardGold=23400,rewardXP=850,rewardItems={161385,162530,162531,162532,162533,162534,162535,162536,163184,163185},starts={{npcID=138704}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questGiverID=138704,questType="standard"},
[53082] = {id=53082,name="Spare Parts",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={53082},series={53081},description="An engineer has been assigned to Stonefist Watch to build a scrapping machine. The mission to salvage materials for the machine was a success thanks to your leadership. Make your way to Stonefist Watch in Tiragarde Sound and meet with Grizvek Gearsnap . He has been overseeing the upgrades for the outpost.",objectivesText="Speak with Grizvek Gearsnap .",rewardGold=117000,rewardXP=3410,rewardItems={24423,24424,24425,57489,57490,57491,131250,131472,161385,162530,162531,162532,162533,162534,162535,162536,163184},starts={{npcID=135691}},ends={{npcID=143015}},mapCandidates={npc={862,895},zone={8499}},questType="standard",sourceQuests={53081}},
[53095] = {id=53095,name="A Flicker of Hope",level=10,requiredLevel=10,faction="alliance",categories={},flags={"timed"},timerSeconds=180,sharable=false,expansion=7,zoneID=1657,mapID=89,storyline={52058,52060,52062,52072,52116,52197,52234,52240,52242,52245,52256,52257,52279,52973,52974,52975,52977,53095,53310,53551,53616,53617,53619,53621,53622},description="Champion, I need your help! We must evacuate Darnassus before it burns to ash! Many of the city's structures have already caught fire. Douse the flames and rescue the trapped civilians within! Please, do all that you can... we must save as many lives as possible.",objectivesText="Evacuate the Citizens of Darnassus.",rewardGold=2000,rewardXP=1415,rewardItems={163127,163189,206350,251719,251720,251721,251722},starts={{npcID=142978}},ends={{npcID=142978}},mapCandidates={npc={89},zone={1657}},questTurnInID=142978,questType="standard",sourceQuests={52977},questLines={{id=637,name="The Warchief's Command",orderIndex=23,flags=0}},db2PoiMapID=1,db2PoiUiMapID=89},
[53097] = {id=53097,name="Despondent Ablutions",level=30,requiredLevel=30,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={53097},description="You return. A surprise. Perhaps there is still hope. In victory or defeat, you bear the weight of this place. It hangs on you like a mantle. I see your struggle to bear it. There is, perhaps, a way to shrug off this burden. An altar, to the northwest. Built by the tidesages, seeking to wash away the corruption. Offer yourself to the idol. It will exact a price, as do all things. But in communion you may claw back from the brink.",objectivesText="Investigate the Purifying Effigy . Progress: Find the circle, pierce the veil. Only in oblivion can you find it.",rewardGold=514800,rewardXP=5145,starts={{npcID=133640},{npcID=143565}},ends={{npcID=133640},{npcID=143565}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50386}},
[53098] = {id=53098,name="Champion: Shandris Feathermoon",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={52281,52282,52283,52284,52285,52286,52287,52288,52289,52290,52291,52473,52788,52789,52790,53072,53098},rewardItems={162253,162450},starts={{npcID=141291}},ends={{npcID=141291}},mapCandidates={npc={84,862},zone={8499}},questType="standard",sourceQuests={52790},questLines={{id=737,name="The Strike on Zuldazar",orderIndex=15,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=737,questLineOrder=13,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=737,questLineOrder=6}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiUiMapID=84},
[53099] = {id=53099,name="A Mote of Cosmic Truth",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50385,50386,50387,50388,50389,50417,53099,53105},description="We stand on the brink, you and I. The final act looms over us, casting a terrible shadow. Deep we plumbed, seeking knowledge of the world. Deeper still we delved, until our fate was inevitable. Minds were shattered, my comrades ran screaming into the night. We are all lost, to that terrible Thing... Now, the malformed syzygy beckons. Complete the ritual and bring about the end.",objectivesText="Defeat the Ascendant Nightmare.",rewardGold=468000,rewardXP=8520,rewardItems={162011,163017},rewardCurrencies={{id=1553,amount=300}},starts={{npcID=133640},{npcID=143565}},ends={{npcID=133640},{npcID=143565}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50389},questLines={{id=577,name="The Forgotten Cove",orderIndex=7,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[53100] = {id=53100,name="Mission Report: Giant Slaying",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={53100},series={53101},description="Your followers have sent a report regarding the mission at Stonetusk Watch. It details that the mission was a success and that one of the ettins is being held captive. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.",objectivesText="Deliver the victory report to Nathanos Blightcaller . Progress: Do you have news regarding the mission for Stonetusk Watch?",rewardGold=23400,rewardXP=850,rewardItems={163191},starts={{npcID=138704}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questGiverID=138704,questType="standard"},
[53101] = {id=53101,name="Nettin' Ettin",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={53101},series={53100},description="An ettin has been captured by our troops at Stonetusk Watch. Apparently, the creature is being trained to work for the Horde as a beast of burden. Make your way to Stonetusk Watch in Stormsong Valley and meet with Wyna Breezehorn . She has been training the ettin to do her bidding.",objectivesText="Speak with Wyna Breezehorn .",rewardGold=117000,rewardXP=3410,rewardItems={162530,162531,162532,162533,162534,162535,162536},starts={{npcID=135691}},ends={{npcID=134844}},mapCandidates={npc={862,942},zone={8499}},questType="standard",sourceQuests={53100}},
[53102] = {id=53102,name="Mission Report: Nature Calls",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={53102},series={53103},description="Your followers have sent a report regarding the mission at Swiftwind Post. It details that the mission was a success and the druids there have upgraded their druidic knowledge as a result. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.",objectivesText="Deliver the victory report to Nathanos Blightcaller . Progress: Do you have news regarding the mission for Swiftwind Post?",rewardGold=23400,rewardXP=850,rewardItems={161449,162530,162531,162532,162533,162534,162535,162536,163193,163194},starts={{npcID=138704}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questGiverID=138704,questType="standard"},
[53103] = {id=53103,name="Wicker Magic",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={53103},series={53102},description="It seems that the druids at Swiftwind Post have learned much from the ancient Drust rituals you recovered. The druids are now able to offer improved services at the outpost. Make your way to Swiftwind Post in Drustvar and see what they have to offer.",objectivesText="Speak with Toska Eaglehorn .",rewardGold=117000,rewardXP=3410,rewardItems={161449,162530,162531,162532,162533,162534,162535,162536,163193},starts={{npcID=135691}},ends={{npcID=140778}},mapCandidates={npc={862,896},zone={8499}},questType="standard",sourceQuests={53102}},
[53105] = {id=53105,name="Misplaced Faith",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={50385,50386,50387,50388,50389,50417,53099,53105},description="The air is foul with corruption. It must be dealt with. The tidesages were fools, and I a fool to trust them. Belief in their god to perform miracles and deliver us from our folly. Nevertheless, their methods did serve to drive back the foul presence from these cliffs. A simple censer, loaded with select powders and oils. The vapors produce an effect that expels the miasma, if only for a time. Perhaps their ineffectual gesticulation will finally serve a purpose.",objectivesText="Use the Cleansing Thurible to purge 13 sources of corruption.",rewardGold=234000,rewardXP=6815,rewardItems={163212},starts={{npcID=133640},{npcID=143565}},ends={{npcID=133640},{npcID=143565}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={50388},questLines={{id=577,name="The Forgotten Cove",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
