[53107] = {id=53107,name="Plunder and Provisions",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={53107},objectivesText="Stolen Supplies retrieved Cave 1 cleared Cave 2 cleared Cave 3 cleared Cave 4 cleared Cave 5 cleared",rewardItems={157784},mapCandidates={npc={},zone={9042}},questType="world",db2Objectives={{text="Stolen Supplies retrieved",amount=3,type=1,objectID=157784,orderIndex=0},{text="Cave 1 cleared",amount=1,type=0,objectID=133757,orderIndex=1},{text="Cave 2 cleared",amount=1,type=0,objectID=133758,orderIndex=2},{text="Cave 3 cleared",amount=1,type=0,objectID=133759,orderIndex=3},{text="Cave 4 cleared",amount=1,type=0,objectID=141789,orderIndex=4},{text="Cave 5 cleared",amount=1,type=0,objectID=141790,orderIndex=5}},worldTaskTitle="Plunder and Provisions",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
