[53109] = {id=53109,name="House Waycrest",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={53109},description="You have done much for my home and the people of Drustvar , Tell your allies that House Waycrest will return to Boralus shortly.",objectivesText="Return to Taelia in the Harbormaster's Office in Boralus.",rewardGold=25740,rewardXP=345,starts={{npcID=129642},{npcID=142651}},ends={{npcID=121235}},mapCandidates={npc={896,1161},zone={8721}},questType="standard",sourceQuests={52149}},
[53110] = {id=53110,name="The High Thornspeaker",level=20,requiredLevel=20,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={48179,48180,48182,48183,52074,52075,53110},description="My teacher, Ulfar , the High Thornspeaker, must be informed of what's been going on here. I can't leave just yet. There are too many wounded and we'll need to handle the last few remaining constructs. You have proven trustworthy, friend. Take a few of these runic cores to Ulfar for me. Arthur will meet you at the head of the path to Ulfar 's den.",objectivesText="Take the Runic Power Cores to Ulfar . Progress: What do you have there, mainlander?",rewardGold=257400,rewardXP=2765,rewardCurrencies={{id=1553,amount=75}},starts={{npcID=139926}},ends={{npcID=141159}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={48179,48182,48183,52075},questLines={{id=5441,name="Drustvar Ruins",orderIndex=6,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
