[53122] = {id=53122,name="A Season for Celebration",level=10,requiredLevel=10,faction="horde",categories={"seasonal"},flags={},sharable=false,event="Hallow's End",expansion=7,zoneID=1637,mapID=94,storyline={53122},series={29376,29400},description="Well met, <class>. Hallow's End is a time for celebration and reflection, though some have no idea why. The burning of the Wickerman in particular is a mystery to many outside the Forsaken. Travel to the Ruins of Lordaeron and speak to Darkcaller Yanka . She can tell you more about the Wickerman ceremony.",objectivesText="Speak with Darkcaller Yanka in the Ruins of Lordaeron.",rewardGold=34100,rewardXP=175,starts={{npcID=19169},{npcID=19175},{npcID=19176},{npcID=19177},{npcID=19178},{npcID=20102}},ends={{npcID=15197}},mapCandidates={npc={10,18,85,90,94},zone={1637}},questType="standard",nextQuests={29374,29375,29376,29377}},
[53125] = {id=53125,name="Mission Report: Into The Wicker",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={53125},series={53126},description="Your followers have sent a report regarding the mission at Mudfisher Cove. It details that the mission was a success and the druids there have upgraded their druidic knowledge as a result. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.",objectivesText="Deliver the victory report to Nathanos Blightcaller . Progress: Do you have news regarding the mission at Fairwind Post?",rewardGold=23400,rewardXP=850,rewardItems={161482,162530,162531,162532,162533,162534,162535,162536,163334,163335},starts={{npcID=138704}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questGiverID=138704,questType="standard"},
[53126] = {id=53126,name="The Wicker Totem",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={53126},series={53125},description="The defense of Mudfisher Cove was successful. Well done, <name>. A mysterious totem was found in the aftermath of the battle that may prove useful to you during your adventures in Drustvar. Travel to Mudfisher Cove in Drustvar and see what power this totem contains.",objectivesText="Speak with Garn Blackwolf .",rewardGold=117000,rewardXP=3410,rewardItems={161482,162530,162531,162532,162533,162534,162535,162536,163334},starts={{npcID=135691}},ends={{npcID=140947}},mapCandidates={npc={862,896},zone={8499}},questType="standard",sourceQuests={53125}},
[53127] = {id=53127,name="The Lord Admiral's Lament",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=1637,mapID=85,storyline={53127},description="The footlocker contains a number of Lord Admiral Daelin Proudmoore's personal effects. Among them is a rolled letter, sealed with sea-green wax and stamped with the Proudmoore crest. The parchment tears easily and requires careful handling and it appears that the ink has been largely washed away by tide and time. Perhaps someone can restore the letter and reveal its contents.",objectivesText="Take the Illegible Correspondence to someone in Orgrimmar . Progress: What's this?",rewardXP=6815,rewardItems={163336},ends={{npcID=139093}},startObjects={{objectID=296479}},coords={mapID=85,source="quest_giver",x=0.48,y=0.715},mapCandidates={npc={85},zone={1637}},questType="standard"},
[53128] = {id=53128,name="The Lord Admiral's Lament",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=1519,mapID=84,storyline={53128},description="The footlocker contains a number of Lord Admiral Daelin Proudmoore's personal effects. Among them is a rolled letter, sealed with sea-green wax and stamped with the Proudmoore crest. The parchment tears easily and requires careful handling and it appears that the ink has been largely washed away by tide and time. Perhaps someone can restore the letter and reveal its contents.",objectivesText="Take the Illegible Correspondence to Kayla Mills in Stormwind City . Progress: What's this?",rewardXP=6815,rewardItems={163336},ends={{npcID=143208}},startObjects={{objectID=296479}},coords={mapID=84,source="quest_giver",x=0.859,y=0.243},mapCandidates={npc={84},zone={1519}},questType="standard"},
[53129] = {id=53129,name="Bloodied Sentinel's Glaive",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=1637,mapID=85,storyline={53129},description="The glaive rests inches from the sentinel's outstretched fingertips. Her eyes stare, sightless, at the ashen husk of Teldrassil on the horizon. Perhaps someone in Orgrimmar can tell you what happened here.",objectivesText="Take the Bloodied Sentinel's Glaive to Isabella in Orgrimmar . Progress: Yes?",rewardXP=6815,rewardItems={163386},ends={{npcID=139093}},startObjects={{objectID=296536,mapID=62,x=0.452,y=0.18}},coords={mapID=85,source="quest_giver",x=0.48,y=0.715},mapCandidates={npc={85},zone={148}},questType="standard"},
[53130] = {id=53130,name="Bloodied Sentinel's Glaive",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=1519,mapID=84,storyline={53130},description="The glaive rests inches from the sentinel's outstretched fingertips. Her eyes stare, sightless, at the ashen husk of Teldrassil on the horizon. Perhaps someone in Stormwind can tell you what happened here.",objectivesText="Take the Bloodied Sentinel's Glaive to Kayla Mills in Stormwind City . Progress: Can I help you?",rewardXP=6815,rewardItems={163386},ends={{npcID=143208}},startObjects={{objectID=296536,mapID=62,x=0.452,y=0.18}},coords={mapID=84,source="quest_giver",x=0.859,y=0.243},mapCandidates={npc={84},zone={148}},questType="standard"},
[53131] = {id=53131,name="Kings' Rest",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9800,mapID=1156,storyline={52308,52489,52490,52491,52492,52493,52494,52495,52496,53071,53131},rewardGold=23400,rewardXP=850,rewardItems={162528,162529,162537},starts={{npcID=142228}},ends={{npcID=142228}},mapCandidates={npc={1156},zone={9800}},questGiverID=142228,questType="standard",sourceQuests={52492},questLines={{id=638,name="Blood in the Water",orderIndex=7,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=638,questLineOrder=12,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=638,questLineOrder=5}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1954,db2PoiUiMapID=1156},
[53146] = {id=53146,name="Boulderfist Beatdown",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=9734,mapID=14,storyline={53146},description="The Boulderfist ogres have plagued Arathi since the Second War, and they still remain. You know what must be done.",objectivesText="Kill 20 Boulderfist clan ogres in Arathi Highlands . Progress: Boulderfist ogres still plague Arathi.",rewardXP=850,rewardCurrencies={{id=1560,amount=200}},starts={{npcID=143172}},ends={{npcID=143172}},mapCandidates={npc={14},zone={45}},questType="standard"},
[53148] = {id=53148,name="Boulderfist Beatdown",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=9734,mapID=14,storyline={53148},description="If the Boulderfist ogres will not join the Horde, there is no place for them in Arathi. You know what must be done.",objectivesText="Kill 20 Boulderfist clan ogres in Arathi Highlands .",rewardXP=850,rewardCurrencies={{id=1560,amount=200}},starts={{npcID=143381},{npcID=143388}},ends={{npcID=143381},{npcID=143388}},mapCandidates={npc={14,1165},zone={45}},questType="standard"},
[53149] = {id=53149,name="Wiping Out the Witherbark",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=9734,mapID=14,storyline={53149},description="The Witherbark tribe has a long and bloody history in the highlands of Arathi. Show them how much bloodier it can get.",objectivesText="Kill 20 Witherbark tribe trolls in Arathi Highlands . Progress: Witherbark drums still echo across the Highlands.",rewardXP=850,rewardCurrencies={{id=1560,amount=200}},starts={{npcID=143172}},ends={{npcID=143172}},mapCandidates={npc={14},zone={45}},questType="standard"},
[53150] = {id=53150,name="Wiping Out the Witherbark",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=9734,mapID=14,storyline={53150},description="The bloodthirsty Witherbark tribe has always refused to join the Horde... and now that the Horde holds Arathi, we will succeed where the Alliance has failed. Drive the forest trolls from the Highlands.",objectivesText="Kill 20 Witherbark tribe trolls in Arathi Highlands .",rewardXP=850,rewardCurrencies={{id=1560,amount=200}},starts={{npcID=143381},{npcID=143388}},ends={{npcID=143381},{npcID=143388}},mapCandidates={npc={14,1165},zone={45}},questType="standard"},
[53151] = {id=53151,name="Mission Report: Wolves For The Den",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={53151},series={53152},description="Your followers have sent a report regarding the mission at Wolf's Den. It details that the mission was a success and that a pack of direwolves now guard the outpost. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.",objectivesText="Deliver the mission report to Nathanos Blightcaller . Progress: Do you have news regarding the mission to Tiragarde Sound?",rewardGold=23400,rewardXP=850,rewardItems={161121,162530,162531,162532,162533,162534,162535,162536,163507,163519},starts={{npcID=138704}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questGiverID=138704,questType="standard"},
[53152] = {id=53152,name="Wolves for the Den",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={53152},series={53151},description="The mission at Wolf's Den in Tiragarde Sound was a success. Well done, <name>. A pack of direwolves now patrols the area surrounding the outpost. Travel to Wolf's Den and see that the training of the wolves is up to our standard.",objectivesText="Speak with Mukkral Blackvein .",rewardGold=234000,rewardXP=6815,rewardItems={161121,162530,162531,162532,162533,162534,162535,162536,163507},starts={{npcID=135691}},ends={{npcID=139561}},mapCandidates={npc={862,895},zone={8499}},questType="standard",sourceQuests={53151}},
[53153] = {id=53153,name="Death to The Defilers",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=9734,mapID=14,storyline={53153},description="Even with the destruction of Undercity, the Defilers continue to combat our hold on the Arathi Highlands . The farmland at Go'Shek will belong to the Alliance once more. Go, and defeat the Forsaken.",objectivesText="Kill 20 Defilers at Go'Shek Farm. Progress: The Defilers still hold Go'Shek Farm.",rewardXP=850,rewardItems={164578},starts={{npcID=143172}},ends={{npcID=143172}},mapCandidates={npc={14},zone={45}},questType="standard",sourceQuests={53198}},
[53154] = {id=53154,name="The League Will Lose",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=9734,mapID=14,storyline={53154},description="Even with the fall of Stromgarde, the League of Arathor continues to operate in the Highlands. The northern farmland will belong to the Horde. Go, and defeat the humans.",objectivesText="Kill 20 League of Arathor at Dabyrie's Farmstead.",rewardXP=850,starts={{npcID=143381},{npcID=143388}},ends={{npcID=143381},{npcID=143388}},mapCandidates={npc={14,1165},zone={45}},questType="standard"},
[53155] = {id=53155,name="Notched Coin",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=5785,mapID=371,storyline={53155},description="<This old, worn coin has clearly changed hands many times. The edges are rusty from years in the salty air of the Great Sea, and it features an unusual design. You saw a number of these coins scattered around the island, they appear to be quite commonly used.>",objectivesText="Bring the Notched Coin to Mili Wanderbrew in Jade Forest. Provided item:",rewardGold=128700,rewardXP=710,rewardItems={163466},rewardCurrencies={{id=1553,amount=700}},starts={{npcID=64365}},ends={{npcID=64365}},mapCandidates={npc={371},zone={5785}},questGiverID=64365,questType="standard",startItems={163466}},
[53159] = {id=53159,name="Arathi Donations: Coarse Leather",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53159},description="It's time we snuff out the competition, don't you agree? With your help we can ensure our allies receive the necessary goods and armor to prepare for the battle to come. Let's make sure our allies are well prepared.",objectivesText="Donate 60 Coarse Leather to Charlane in Boralus Harbor. Progress: Should you find any additional leather in your hunt, you know where to find me.",rewardItems={152541},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142995}},ends={{npcID=142995}},mapCandidates={npc={1161},zone={8568}},questGiverID=142995,questType="standard"},
[53160] = {id=53160,name="Ancient Crypt Key",level=10,requiredLevel=10,faction="both",sharable=false,expansion=7,zoneID=9105,mapID=1530,rewardGold=128700,rewardXP=710,rewardCurrencies={{id=1553,amount=700}},starts={{npcID=61962}},ends={{npcID=61962},{npcID=156003}},mapCandidates={npc={1530},zone={9105}},questGiverID=61962,questType="standard"},
[53161] = {id=53161,name="Ring of the Reefs",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=7541,mapID=634,storyline={53161},description="<A light mist twists and curls around this ring as if caressing it. Holding this object makes you uneasy, deep within your soul. It feels as if invisible, icy hands from the lands of the dead are pulling at you. There is no mistaking Helya's power. The Valarjar will want to hear about this.>",objectivesText="Solve the riddle. Provided item:",rewardGold=128700,rewardXP=710,rewardItems={163471},rewardCurrencies={{id=1553,amount=700}},starts={{npcID=106904}},ends={{npcID=106904}},mapCandidates={npc={634},zone={7541}},questGiverID=106904,questType="standard",startItems={163471}},
[53162] = {id=53162,name="Sins of the Syndicate",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=9734,mapID=14,storyline={53162},description="As if the Defilers were not trouble enough, Syndicate agents still slither down from the Alterac mountains to drive off honest Alliance farmers. Punish them.",objectivesText="Kill 20 Syndicate members at Dabyrie's Farmstead.",rewardXP=850,rewardCurrencies={{id=1560,amount=200}},starts={{npcID=143172}},ends={{npcID=143172}},mapCandidates={npc={14},zone={45}},questType="standard"},
[53163] = {id=53163,name="Bloodwake Drinking Horn",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=7541,mapID=634,storyline={53163},description="<A large drinking horn taken from one of the Bloodwake vrykul. The sturdy craftsmanship has allowed it to survive many years of hard travel on the Great Sea. As you hold the horn, you remember how fervently the vrykul you encountered were after the Azerite , but to what end? Other vrykul tribes may know more about the Bloodwake and their motivations.>",objectivesText="Bring the horn to the wise Vydhar . Provided item:",rewardGold=128700,rewardXP=710,rewardItems={140192,163472},rewardCurrencies={{id=1553,amount=700}},starts={{npcID=93231}},ends={{npcID=93231}},mapCandidates={npc={634},zone={7541}},questGiverID=93231,questType="standard",startItems={163472}},
[53164] = {id=53164,name="Sonic Stone",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=5842,mapID=388,storyline={53164},description="<The stone vibrates to your touch. The frequency resonates throughout your body, and you feel refreshed. The mantid likely use these stones to allow them to fly great distances across the sea. To see them on the island was strange, the mantid took a heavy blow when Shek'zeer was destroyed, they should not be swarming now. The denizens of Pandaria may have more information.>",objectivesText="Show the stone to Sentinel Commander Qipan in Townlong Steppes. Provided item:",rewardGold=128700,rewardXP=710,rewardItems={163473},rewardCurrencies={{id=1553,amount=700}},starts={{npcID=61584}},ends={{npcID=61584}},mapCandidates={npc={388},zone={5842}},questGiverID=61584,questType="standard",startItems={163473}},
[53165] = {id=53165,name="Stopping Antiquities Theft",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={53165},objectivesText="Goblin Treasure Thieves",rewardItems={163048},mapCandidates={npc={},zone={8499}},questType="world",db2Objectives={{text="Goblin Treasure Thieves",amount=10,type=0,objectID=140716,orderIndex=0}},worldTaskTitle="Stopping Antiquities Theft",db2PoiMapID=1642,db2PoiUiMapID=862,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[53167] = {id=53167,name="Icetusk Fur Cloak",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=65,mapID=115,storyline={53167},description="<The fur on this cloak is worn and tattered, but it is still warm. It has seen many years in the harsh, unforgiving blizzards of the north. The icetusk tribe has not been seen on Azeroth until now, someone in Northrend might know more about them.>",objectivesText="Show the fur to Tua'kea in Dragonblight. Provided item:",rewardGold=128700,rewardXP=710,rewardItems={163474},rewardCurrencies={{id=1553,amount=700}},starts={{npcID=26245}},ends={{npcID=26245}},mapCandidates={npc={115},zone={65}},questGiverID=26245,questType="standard",startItems={163474}},
[53168] = {id=53168,name="Magical Spyglass",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=5287,mapID=210,storyline={53168},description="<This spyglass allows you to see far off into the distance, but looking through it for too long gives you a headache. The lens appears to have been specifically crafted for someone else's eyes. Given the intricate detail on the spyglass, they'd likely provide a hefty reward for its return.>",objectivesText="Return the spyglass. Provided item:",rewardGold=128700,rewardXP=710,rewardItems={163475,163482},rewardCurrencies={{id=1553,amount=700}},starts={{npcID=2496}},ends={{npcID=2496}},mapCandidates={npc={210},zone={5287}},questGiverID=2496,questType="standard",startItems={163475}},
[53169] = {id=53169,name="Elemental Core",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,storyline={53169},description="<A burned-out core from the elementals you encountered. When you concentrate, you can sense that some elemental energy still exists, deep within the core. They were clearly after the Azerite , but why? It might be time to call in an old favor.>",objectivesText="Bring the core to Duke Hydraxis in Azshara. Provided item:",rewardGold=128700,rewardXP=710,rewardItems={163476},rewardCurrencies={{id=1553,amount=700}},starts={{npcID=13278}},ends={{npcID=13278}},mapCandidates={npc={},zone={}},questGiverID=13278,questTurnInID=13278,questType="standard",startItems={163476}},
[53170] = {id=53170,name="Unscarred Black Scale",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=5785,mapID=371,storyline={53170},description="<An utterly pristine black dragon scale taken from the dragons you recently encountered. The black dragonflight was completely decimated following Deathwing's demise and Wrathion's rise to power. Yet the size indicates a younger dragon. There is one person, one dragon, that you know will want to hear of this, but where IS Wrathion? You surmise he may be some place familiar, fortified, and abandoned.>",objectivesText="Attempt to find Wrathion in Blackrock Mountain. Provided item:",rewardGold=128700,rewardXP=710,rewardItems={163477},rewardCurrencies={{id=1553,amount=700}},starts={{npcID=66306}},ends={{npcID=66306}},mapCandidates={npc={371},zone={5785}},questGiverID=66306,questType="standard",startItems={163477}},
[53171] = {id=53171,name="Battered Twilight Scale",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=4922,mapID=241,storyline={53171},description="<The worn scale of a twilight dragon, it has seen many years of fighting. The twilight dragons were thought to have been defeated with the fall of Sinestra, how were there so many on the island? And who is leading the flight?>",objectivesText="Solve the riddle. Provided item:",rewardGold=128700,rewardXP=710,rewardItems={163478},rewardCurrencies={{id=1553,amount=700}},starts={{npcID=132888}},ends={{npcID=132888}},mapCandidates={npc={241},zone={4922}},questGiverID=132888,questType="standard",startItems={163478}},
[53172] = {id=53172,name="Venture Co. Business Plan",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=17,mapID=10,storyline={53172},description="<An enormous volume, and printed in very small print. You can't make it through even a few sentences before the words begin to swim before your eyes. The Venture Company's long-term plan appears to be quite complex and nearly impossible to understand. One thing is for certain: a competing enterprise would likely pay well to get their hands on this tome.>",objectivesText="Confront Lizzarik in Ratchet. Provided item:",rewardGold=26750,rewardXP=710,rewardItems={163479},rewardCurrencies={{id=1553,amount=700}},starts={{npcID=3658}},ends={{npcID=3658}},mapCandidates={npc={10},zone={17}},questGiverID=3658,questType="standard",startItems={163479}},
[53173] = {id=53173,name="Sins of the Syndicate",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=9734,mapID=14,storyline={53173},description="As if the League of Arathor was not trouble enough, Syndicate agents still slither down from the Alterac mountains to drive off honest Horde laborers. Punish them.",objectivesText="Kill 20 Syndicate members at Go'Shek Farm.",rewardXP=850,rewardCurrencies={{id=1560,amount=200}},starts={{npcID=143381},{npcID=143388}},ends={{npcID=143381},{npcID=143388}},mapCandidates={npc={14,1165},zone={45}},questType="standard"},
[53174] = {id=53174,name="Murloc Eye",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=7503,mapID=650,storyline={53174},description="<The murloc eye appears to have no magical properties of its own, but is still quite damp to the touch. You have seen naga sorcerers use similar objects in their casting rituals, but rarely do they dismember their murloc slaves for this purpose. This is unsettling, even for the naga.>",objectivesText="Solve the riddle. Provided item:",rewardGold=128700,rewardXP=710,rewardItems={730,163480},rewardCurrencies={{id=1553,amount=700}},starts={{npcID=98067}},ends={{npcID=98067}},mapCandidates={npc={650},zone={7503}},questGiverID=98067,questType="standard",startItems={163480}},
[53175] = {id=53175,name="The Warfront Looms",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={53175,53185,53194,53197,53198,53414},description="We cannot myopically focus all our efforts on Zandalar. Horde treachery simmers all across the globe. One particular hot spot lies in the Arathi Highlands, near the storied citadel of Stromgarde. The Horde has set up an encampment nearby, and intends to capture our territory. Speak with Ralston Karn , the recruitment officer for the division in charge of this particular warfront. He could use a good <class> like you.",objectivesText="Report to Ralston Karn in Boralus Harbor.",rewardGold=234000,rewardXP=6815,ends={{npcID=142721}},coords={mapID=1161,source="quest_giver",x=0.66,y=0.26},mapCandidates={npc={1161},zone={8568}},questType="standard",nextQuests={53194},questLines={{id=746,name="The Battle for Stromgarde",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[53176] = {id=53176,name="Glittering Scarab",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=5034,mapID=249,storyline={53176},description="<A magical trinket found on a tol'vir spellcaster, it appears to augment their casting abilities. It seems to be very old, but is nearly pristine in form. The tol'vir of Uldum may know more about the sudden appearance of the Amathet.>",objectivesText="Bring the scarab to High Commander Kamses in Uldum. Provided item:",rewardGold=138100,rewardXP=710,rewardItems={163481},rewardCurrencies={{id=1553,amount=700}},starts={{npcID=46134}},ends={{npcID=46134}},mapCandidates={npc={249},zone={5034}},questGiverID=46134,questType="standard",startItems={163481}},
[53177] = {id=53177,name="Broken Compass",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=5287,mapID=210,storyline={53177},description="<A compass found on a stranded pirate, it no longer functions. The metal and craftsmanship indicate an origin in Stormwind.>",objectivesText="Find the owner of the compass. Provided item:",rewardGold=1000,rewardXP=710,rewardItems={163482},rewardCurrencies={{id=1553,amount=700}},starts={{npcID=908}},ends={{npcID=908}},mapCandidates={npc={210},zone={5287}},questGiverID=908,questType="standard",startItems={163482}},
[53178] = {id=53178,name="Razorfin Hunting Spear",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=6134,mapID=418,storyline={53178},description="<This spear is razor sharp, though it has clearly seen many years of hunting in the open sea. The shaft has been broken in several places and repaired with what materials were available at the time. From the variety of repair materials, you surmise that the jinyu tribe you recently faced must travel extensively. The friendly jinyu of Pandaria might know more about this strange tribe.>",objectivesText="Take the spear to Tired Shushen in Krasarang Wilds. Provided item:",rewardGold=128700,rewardXP=710,rewardItems={163483},rewardCurrencies={{id=1553,amount=700}},starts={{npcID=58278}},ends={{npcID=58278}},mapCandidates={npc={418},zone={6134}},questGiverID=58278,questType="standard",startItems={163483}},
[53179] = {id=53179,name="Executing Exorcisms",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=9734,mapID=14,storyline={53179},description="Even in death, the Horde foolishly clings to Alliance territory. Drive their vengeful ghosts from the ruins of Ar'gorok before their foulness spreads.",objectivesText="Kill 20 Vengeful Ghosts in Ar'gorok. Progress: Vengeful ghosts remain in Ar'gorok.",rewardXP=850,rewardCurrencies={{id=1553,amount=300}},starts={{npcID=143172}},ends={{npcID=143172}},mapCandidates={npc={14},zone={45}},questType="standard"},
[53180] = {id=53180,name="Vorus'arak's Carapace",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=65,mapID=115,storyline={53180},description="<The carapace from the nerubian lord Vorus'arak, it looks ancient. It appears that Vorus'arak did not want to shed his shell, and instead wore the same scarred carapace for a very long time. All across the carapace, strange markings have been carved. It seems to be a language of some kind.>",objectivesText="Bring the carapace to Kilix the Unraveler in Dragonblight. Provided item:",rewardGold=121680,rewardXP=710,rewardItems={163484},rewardCurrencies={{id=1553,amount=700}},starts={{npcID=26653}},ends={{npcID=26653}},mapCandidates={npc={115},zone={65}},questGiverID=26653,questType="standard",startItems={163484}},
[53181] = {id=53181,name="Druidic Fur",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=493,mapID=80,storyline={53181},description="<This fur teems with natural magic. The beasts you fought on the island were clearly not beasts at all, but druids. At least they were before. What could have caused them to become feral? You did not want to slay them, but they gave you no choice, didn't they?>",objectivesText="Bring the fur to Loganaar in Moonglade. Provided item:",rewardGold=128700,rewardXP=710,rewardItems={163485},rewardCurrencies={{id=1553,amount=700}},starts={{npcID=12042}},ends={{npcID=12042}},mapCandidates={npc={80},zone={493}},questGiverID=12042,questType="standard",startItems={163485}},
[53182] = {id=53182,name="Strangling Root",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=493,mapID=80,storyline={53182},description="<The root twists and struggles in your grip, attempting to wrap itself around your arm. The keepers you encountered must be powerfully attuned to nature to imbue their creations with such longetivity. Remembering the ferocity with which they fought against you makes you suddenly uneasy. Why would these guardians of nature behave this way? Surely, someone must have the answers.>",objectivesText="Take the root to Keeper Remulos in Moonglade. Provided item:",rewardGold=144600,rewardXP=710,rewardItems={163486},rewardCurrencies={{id=1553,amount=700}},starts={{npcID=11832}},ends={{npcID=11832}},mapCandidates={npc={80},zone={493}},questGiverID=11832,questType="standard",startItems={163486}},
[53183] = {id=53183,name="Wriggling Mass",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=1377,mapID=81,storyline={53183},description="<The tendril writhes and pulsates in your hand as your mind is assailed by all manner of vicious thoughts. One vision in particular surfaces in your mind again and again. In your mind's eye, you picture a many-eyed goat laying in a pool of black water. As you approach, its eyes burst open, and in an instant you find yourself looking upward at the goat from deep within the puddle. As you sink into the icy darkness, everything goes black. You pocket the mass and shake the thoughts from your head.",objectivesText="Locate someone who can explain the visions. Provided item:",rewardGold=128700,rewardXP=710,rewardItems={163487},rewardCurrencies={{id=1553,amount=700}},starts={{npcID=132886}},ends={{npcID=132886}},mapCandidates={npc={81},zone={1377}},questGiverID=132886,questType="standard",startItems={163487}},
[53184] = {id=53184,name="Weathered Pamphlet",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=440,mapID=71,storyline={53184},description="<This pamphlet appears to be a mass-produced flier advertising an Azerite -buying service. You can make out a few faded but colorful phrases like \"Your fortune awaits in the Great Sea!\" and \"Everyone's getting rich, isn't it your time?\" There is no mention of any of the dangers involved. There is some information about who to contact at the bottom, however.>",objectivesText="Find the pamphlet's originator. Provided item:",rewardGold=128700,rewardXP=710,rewardItems={163488},rewardCurrencies={{id=1553,amount=700}},starts={{npcID=132832}},ends={{npcID=132832}},mapCandidates={npc={71},zone={440}},questGiverID=132832,questType="standard",db2QuestSortName="Nightborne",startItems={163488}},
[53185] = {id=53185,name="Warfront Contribution",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53175,53185,53194,53197,53198,53414},description="A well-trained army will only get us so far, <name>. We also need money, food, and supplies to keep our army funded, fed, and ready to fight. Alliance coffers fund most of the war effort, but the rest is paid for by the hard work of citizens like you and me. Loosen up those purse strings and do what you can. For the Alliance!",objectivesText="If you are looking for what contributions are up as of September 16th, please go to our list of Alliance Warfront Contribution Quests . Make a donation to the war effort. You can donate gold, War Resources, or crafted equipment. Only some NPCs will accept donations each day.",rewardGold=234000,rewardXP=6815,rewardItems={152875},rewardCurrencies={{id=1599,amount=150}},starts={{npcID=142721}},ends={{npcID=142721}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={53194},questLines={{id=746,name="The Battle for Stromgarde",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[53186] = {id=53186,name="Mission Report: Ambush at Grimwatt's Crash",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={53186},series={53187},description="Your followers have sent a report regarding the mission at Grimwatt''s Crash. It details that the mission was a success and the attacking blood trolls were defeated. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.",objectivesText="Deliver the mission report to Halford Wyrmbane . Progress: Do you have news regarding the mission for Grimwatt's Crash?",rewardGold=23400,rewardXP=850,rewardItems={163043,163547},starts={{npcID=138704}},ends={{npcID=135612}},mapCandidates={npc={1161},zone={8568}},questGiverID=138704,questType="standard",sourceQuests={53006}},
[53187] = {id=53187,name="An Unexpected Guest",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53187},series={53186},description="The mission to defend Grimwatt's Crash was a success. Well done, <name>. In addition to successfully holding the outpost, the troops at Grimwatt's Crash have captured a blood crawg. Noella Davenport is handling the beast's training. Make your way to Grimwatt's Crash in Nazmir and check-in with Noella on the crawg training.",objectivesText="Speak with Noella Davenport .",rewardGold=117000,rewardXP=3410,starts={{npcID=135612}},ends={{npcID=142478}},mapCandidates={npc={863,1161},zone={8568}},questType="standard",sourceQuests={53186}},
[53188] = {id=53188,name="Frozen Freestyle",expansion=7,mapID=895,questType="world",db2Objectives={{orderIndex=0,type=3,amount=1,objectID=131575,text="Talk to the Penguing Sledding Barker"},{orderIndex=1,type=0,amount=1,objectID=131573,text="Ride the pengling to the goal"}},worldTaskTitle="Frozen Freestyle",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[53189] = {id=53189,name="Slippery Slopes",expansion=7,mapID=895,questType="world",db2Objectives={{orderIndex=0,type=3,amount=1,objectID=131575,text="Talk to the Pengling Sledding Barker"},{orderIndex=1,type=0,amount=1,objectID=131573,text="Ride the pengling to the goal"}},worldTaskTitle="Slippery Slopes",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[53190] = {id=53190,name="Executing Exorcisms",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=9734,mapID=14,storyline={53190},description="Even in death, the Alliance foolishly clings to Horde territory. Drive their vengeful ghosts from the ruins of Stromgarde before their foulness spreads.",objectivesText="Kill 20 Vengeful Ghosts in Stromgarde. Progress: Vengeful ghosts remain in Stromgarde.",rewardXP=850,rewardCurrencies={{id=1553,amount=300}},starts={{npcID=143381},{npcID=143388}},ends={{npcID=143381},{npcID=143388}},mapCandidates={npc={14,1165},zone={45}},questType="standard"},
[53192] = {id=53192,name="Twice-Exiled",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=9734,mapID=14,storyline={53192},description="Elementals of all sorts are bursting free of their bonds across the Highlands. Return them to the primordial chaos from whence they came.",objectivesText="Kill 20 Burning, Cresting, Rumbling, or Thundering Exiles or Guardians in Arathi Highlands .",rewardXP=850,rewardCurrencies={{id=1560,amount=200}},starts={{npcID=143172}},ends={{npcID=143172}},mapCandidates={npc={14},zone={45}},questType="standard"},
[53193] = {id=53193,name="Twice-Exiled",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=9734,mapID=14,storyline={53193},description="Elementals of all sorts are bursting free of their bonds across the Highlands. Return them to the primordial chaos from whence they came.",objectivesText="Kill 20 Burning, Cresting, Rumbling, or Thundering Exiles or Guardians in Arathi Highlands . Progress: Hostile elementals still befoul the Highlands.",rewardXP=850,rewardCurrencies={{id=1560,amount=200}},starts={{npcID=143381},{npcID=143388}},ends={{npcID=143381},{npcID=143388}},mapCandidates={npc={14,1165},zone={45}},questType="standard"},
[53194] = {id=53194,name="To the Front",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53175,53185,53194,53197,53198,53414},description="I need you to see the Arathi Highlands. The battle has died down for now, but when it flares up again, we'll need you on the front. Yvera Dawnwing maintains a portal directly to Stromgarde. She can help you.",objectivesText="Speak with Yvera Dawnwing to teleport to Stromgarde, then report to Captain Roderick Brewston .",rewardGold=234000,rewardXP=6815,rewardItems={858,33792,34583,34584,57523,57524,57525,62837,62838,62839,131193,163280,163282,163283,163424,163426,163432,163435,163441,163446,163453,163456,163459,208067,210050,257352},starts={{npcID=142721}},ends={{npcID=143018}},mapCandidates={npc={14,1161},zone={8568}},questType="standard",sourceQuests={53175},questLines={{id=746,name="The Battle for Stromgarde",orderIndex=0,flags=0}},db2PoiUiMapID=14},
[53195] = {id=53195,name="Arathi Donations: Akunda's Bite",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9391,mapID=1161,storyline={53195},description="Greetings! With the war effort in full swing I'll be your point of contact for herbalism and alchemical donations! It's a pleasure to meet you! Now, let's see here... Ah, yes. Siren's Pollen. It appears our stockpiles reported a shortage as of late last night. It would be a great help to us all if you were able to donate to our efforts.",objectivesText="Gather 20 Siren's Pollen for Chelsea Strand in Boralus Harbor. Progress: Have some herbs for me?",rewardItems={152507},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142993}},ends={{npcID=142993}},mapCandidates={npc={1161},zone={9391}},questGiverID=142993,questType="standard"},
[53196] = {id=53196,name="Swab This!",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=8567,mapID=895,mapCandidates={npc={},zone={8567}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=100,objectID=145236,text="Pirates Bombed"}},worldTaskTitle="Swab This!",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[53197] = {id=53197,name="Touring the Front",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=45,mapID=14,storyline={53175,53185,53194,53197,53198,53414},description="The Horde haven't attacked for a while now. Neither have we, honestly. It should be safe to head on out and do some scouting. Check in with our foremen at the mine and the lumber mill. It'd be good to know that they haven't off and gotten themselves killed, and the trip should give you a bit of a lay of the land. Speaking of which, you might also talk to Grayson Bell , the flight master, who can give you a quick look at our enemy's base. \"Ar'gorok,\" or some other such orcish nonsense.",objectivesText="Report to Foreman Tully , Lumbering Leo , and Grayson Bell . Progress: Cheers!",rewardGold=234000,rewardXP=6815,starts={{npcID=143018}},ends={{npcID=143018}},mapCandidates={npc={14},zone={45}},questType="standard",sourceQuests={53194},questLines={{id=746,name="The Battle for Stromgarde",orderIndex=2,flags=0}},db2PoiUiMapID=14},
[53198] = {id=53198,name="Back to Boralus",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=45,mapID=14,storyline={53175,53185,53194,53197,53198,53414},description="That should just about do it for now, then. We'll be in touch if the fighting heats back up again. No doubt it'll be any day now.",objectivesText="Speak with Yvera Dawnwing to return to Boralus.",rewardGold=234000,rewardXP=6815,starts={{npcID=143018}},ends={{npcID=142721}},mapCandidates={npc={14,1161},zone={45}},questType="standard",sourceQuests={53197},nextQuests={53153},questLines={{id=746,name="The Battle for Stromgarde",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[53205] = {id=53205,name="Arathi Donations: Monelite Ore",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53205},description="Ye look like the kind o' <lad/lass> that ought ta be carryin' loads o' ore around with ya! If my assumption is right about ye, we could use yer help to gather a bit more ore for the war effort. Have ye any ore ta spare?",objectivesText="Gather 20 Monelite Ore to Brandal Darkbeard in Boralus Harbor. Progress: Ye look like the kind o' lad that ought ta be carryin' loads o' ore around with ye! Got any ta spare?",rewardItems={152512},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142994}},ends={{npcID=142994}},mapCandidates={npc={1161},zone={8568}},questGiverID=142994,questType="standard"},
[53207] = {id=53207,name="The Warfront Looms",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={53207,53208,53209,53210,53212,53416},description="Our focus must expand beyond Kul Tiras. The Alliance still presses against our forces in other parts of the globe. We are most interested in the Arathi Highlands, near Stromgarde. We've set up an encampment in the area, with the intent of capturing Stromgarde. Speak with Throk , the recruitment officer for the division in charge of this particular warfront. He could use a good <class> like you.",objectivesText="Report to Throk in Zuldazar.",rewardGold=238680,rewardXP=6815,starts={{npcID=138949}},ends={{npcID=138949}},mapCandidates={npc={1165},zone={8670}},questGiverID=138949,questType="standard",sourceQuests={52451},nextQuests={53208},questLines={{id=747,name="The Battle for Stromgarde",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[53208] = {id=53208,name="To the Front",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53207,53208,53209,53210,53212,53416},description="We're at war in the Arathi Highlands. The battle has died down for now, but when it flares up again, we'll need you on the front. Druza Netherfang maintains a portal directly to Ar'gorok. She can help you.",objectivesText="Speak with Druza Netherfang to teleport to Ar'gorok, then report to Wistel Silversnitch .",rewardGold=234000,rewardXP=6815,rewardItems={858,33792,34583,34584,57523,57524,57525,62837,62838,62839,131193,163280,163282,163283,163424,163426,163432,163435,163441,163446,163453,163456,163459,208067,210050,257352},starts={{npcID=138949}},ends={{npcID=143019}},mapCandidates={npc={14,1165},zone={8670}},questType="standard",sourceQuests={53207},questLines={{id=747,name="The Battle for Stromgarde",orderIndex=0,flags=0}},db2PoiUiMapID=14},
[53209] = {id=53209,name="Warfront Contribution",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53207,53208,53209,53210,53212,53416},description="A well-trained army will only get us so far, <name>. We also need money, food, and supplies to keep our army funded, fed, and ready to fight. Show some pride and give what you can. For the Horde!",objectivesText="Make a donation to the war effort. You can donate gold, War Resources, or crafted equipment. Only some NPCs will accept donations each day.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1600,amount=150}},starts={{npcID=138949}},ends={{npcID=138949}},mapCandidates={npc={1165},zone={8670}},questType="standard",questLines={{id=747,name="The Battle for Stromgarde",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[53210] = {id=53210,name="Touring the Front",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=45,mapID=14,storyline={53207,53208,53209,53210,53212,53416},description="The Alliance haven't attacked for a while now. Neither have we, actually. It should be safe to head on out and do some scouting. Check in with our foremen at the mine and the lumber mill. It'd be good to know that they haven't gone and gotten themselves killed, and the trip should give you a bit of a lay of the land. Speaking of which, you might also talk to Flightgineer Krazzle . He can give you a quick look at Stromgarde, so you can see what we're up against.",objectivesText="Report to Foreman Drogg , Graul , and Flightgineer Krazzle . Progress: Hey hey.",rewardGold=234000,rewardXP=6815,starts={{npcID=143019}},ends={{npcID=143019}},mapCandidates={npc={14},zone={45}},questType="standard",sourceQuests={53208},questLines={{id=747,name="The Battle for Stromgarde",orderIndex=2,flags=0}},db2PoiUiMapID=14},
[53211] = {id=53211,name="Arathi Donations: Coastal Healing Potion",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53211},description="I've received word our allies are looking to stash away a few supplementary items for the battle to come. If you happen to stumble across a few Coastal Healing Potions I'd be more than happy to add them to our stores.",objectivesText="Gather 10 Coastal Healing Potions for Chelsea Strand in Boralus Harbor. Progress: I don't suppose you have any healing potions to spare. I'm trying to maintain a healthy supply for the battle to come.",rewardItems={152494},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142993}},ends={{npcID=142993}},mapCandidates={npc={1161},zone={8568}},questGiverID=142993,questType="standard"},
[53212] = {id=53212,name="Back to Zuldazar",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=45,mapID=14,storyline={53207,53208,53209,53210,53212,53416},description="That should just about do it for now, then. We'll be in touch if the fighting heats back up again. Should be any day now, honestly.",objectivesText="Speak with Druza Netherfang to return to Zuldazar.",rewardGold=234000,rewardXP=6815,starts={{npcID=143019}},ends={{npcID=138949}},mapCandidates={npc={14,1165},zone={45}},questType="standard",sourceQuests={53210},nextQuests={53416,56137},questLines={{id=747,name="The Battle for Stromgarde",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[53213] = {id=53213,name="Arathi Donations: Coastal Mana Potion",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53213},description="One of our latest shipments of alchemical supplies was raided en route to storage. We're scrambling to get our stock back on track, but I'm worried we won't make our quota. You wouldn't happen to know where one can acquire additional mana potions, would you?",objectivesText="Bring 10 Coastal Mana Potions to Chelsea Strand in Boralus Harbor. Progress: I'm looking to acquire a few potions to sustain our allies in a long-fought battle. Have anything of the kind?",rewardItems={152495},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142993}},ends={{npcID=142993}},mapCandidates={npc={1161},zone={8568}},questGiverID=142993,questType="standard"},
[53216] = {id=53216,name="Arathi Donations: Shimmerscale",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53216},description="I'll keep it simple: we need more Shimmerscale ! I apologize for being so forward with you, but there's little time to waste. If you happen upon this item throughout your travels I'd be more than happy to put it to good use. Outfitting our allies is of the utmost importance in the battle to come, don't you agree?",objectivesText="Donate 100 Shimmerscale to Charlane in Boralus Harbor. Progress: Outfitting our allies is of the utmost importance. This provides us the necessary materials to ensure no one is left unprotected on the battlefield.",rewardItems={153050},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142995}},ends={{npcID=142995}},mapCandidates={npc={1161},zone={8568}},questGiverID=142995,questType="standard"},
[53217] = {id=53217,name="Arathi Donations: Coarse Leather Barding",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53217},description="It's not just our allies we need to protect in the upcoming battle, but our equine friends as well! Can you lend a hand and ensure our allies receive the best possible armor for the battle ahead?",objectivesText="Gather 5 Coarse Leather Barding for Charlane in Boralus Harbor. Progress: It's not just our allies needing protection in the battle to come, but our beasts as well.",rewardItems={154166},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142995}},ends={{npcID=142995}},mapCandidates={npc={1161},zone={8568}},questGiverID=142995,questType="standard"},
[53218] = {id=53218,name="Arathi Donations: Monel-Hardened Hoofplates",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53218},description="Battles aren't decided by which side has the best armor, or the sharpest blades, but it sure does help! Matter o' fact is it's not just ye allies needin' help, but our beasts of battle as well. If ye can provide any additional hoofplates fer our brave beasts I'll be sure ta have our farriers take good care of 'em.",objectivesText="Gather 2 Monel-Hardened Hoofplates for Brandal Darkbeard in Boralus Harbor. Progress: Battles aren't decided by which side has the best armor, or the sharpest blades, but it sure does help! Matter o' fact is it's not just ye allies who're needin' help, but our beasts of battle as well. If ye can provide any additional hoofplates fer our brave beasts I'll be sure ta have our farriers take good care of 'em.",rewardItems={152812},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142994}},ends={{npcID=142994}},mapCandidates={npc={1161},zone={8568}},questGiverID=142994,questType="standard"},
[53219] = {id=53219,name="Arathi Donations: Monel-Hardened Stirrups",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53219},description="In times like this it's important ta be ready fer battle at a moments notice. Outfittin' our beasts with proper stirrups is a step in the right direction. If yer able ta bring me a few I'll be sure they're put ta good use.",objectivesText="Gather 2 Monel-Hardened Stirrups for Brandal Darkbeard in Boralus Harbor. Progress: In times like this it's important ta be ready fer battle at a moments notice. Outfittin' our beasts with proper stirrups is a step in the right direction. If yer able ta bring me a few I'll be sure they're put ta good use.",rewardItems={152813},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142994}},ends={{npcID=142994}},mapCandidates={npc={1161},zone={8568}},questGiverID=142994,questType="standard"},
[53221] = {id=53221,name="Mission Report: Missing Supplies",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={53221},series={53222},description="Your followers have sent a report regarding the mission at Vulture's Nest. It details that the mission was a success and the lost supply shipment has been recovered. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.",objectivesText="Deliver the mission report to Halford Wyrmbane . Progress: Do you have news regarding the mission for Vulture's Nest?",rewardGold=23400,rewardXP=850,rewardItems={163572,163709},starts={{npcID=138704}},ends={{npcID=135612}},mapCandidates={npc={1161},zone={8568}},questGiverID=138704,questType="standard"},
[53222] = {id=53222,name="Necessary Supplies",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53222},series={53221},description="The mission to recover the supplies was a success. Well done, <name>. The supply shipment in question was ordered by Buzz Crankchug at Vulture's Nest. You should check in with the outpost in Vol'dun and ensure that all of the missing supplies have been accounted for. Make your way to Vulture's Nest in Vol'dun and speak with Buzz Crankchug .",objectivesText="Speak with Buzz Crankchug .",rewardGold=117000,rewardXP=3410,rewardItems={163709},starts={{npcID=135612}},ends={{npcID=138256}},mapCandidates={npc={864,1161},zone={8568}},questType="standard",sourceQuests={53221}},
[53223] = {id=53223,name="Arathi Donations: Grilled Catfish",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53223},description="Greetings, traveler. I was asked to ensure our food supplies are never left wanting and our fish supplies have been running low lately. Have anything you would care to donate?",objectivesText="Gather 5 Grilled Catfish for Senedras in Boralus Harbor. Progress: I was asked to ensure our food supplies are never left wanting, though lately our fish supplies have been running low. Have any fish you would care to donate?",rewardItems={154889},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142997}},ends={{npcID=142997}},mapCandidates={npc={1161},zone={8568}},questGiverID=142997,questType="standard"},
[53224] = {id=53224,name="Arathi Donations: Seasoned Loins",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53224},description="A nice, hearty meat provides the nourishment our allies deserve before shipping off to battle, not to mention it also makes quite a stew, something our troops seem to rather enjoy when the winds are at their best and the chill of night lingers in the air. If you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.",objectivesText="Gather 20 Seasoned Loins for Senedras in Boralus Harbor. Progress: A hearty meat provides the nourishment our allies deserve. If you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.",rewardItems={154891},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142997}},ends={{npcID=142997}},mapCandidates={npc={1161},zone={8568}},questGiverID=142997,questType="standard"},
[53225] = {id=53225,name="Arathi Donations: Great Sea Catfish",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1161,storyline={53225},description="Fish--it's what's for dinner! Or so say our supply officers. And this weeks meals are based around one delicious ingredient--catfish. If we're going to keep our allies well fed and full of fish we'll need to gather more stock and begin meal preparations soon. If you find yourself swimming in an abundance of catfish I'd be happy to send them along to our stores.",objectivesText="Gather 40 Great Sea Catfish for Senedras in Boralus Harbor. Progress: If we're going to keep our allies well fed and full of fish, we'll need to make sure our stockpile is ready. If you find yourself swimming in an abundance of catfish I'd be happy to send them along to our stores.",rewardItems={152547},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142997}},ends={{npcID=142997}},mapCandidates={npc={1161},zone={10052}},questGiverID=142997,questType="standard"},
[53226] = {id=53226,name="Arathi Donations: Tidespray Linen",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53226},objectivesText="Gather 40 Tidespray Linen for Faella in Boralus Harbor. Progress: There is no such thing as too much linen. It is better to maintain a strong supply than be left wanting.",rewardItems={152576},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142998}},ends={{npcID=142998}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[53227] = {id=53227,name="Arathi Donations: Battle Flag: Spirit of Freedom",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53227},objectivesText="Gather 2 Battle Flag: Spirit of Freedom for Faella in Boralus Harbor. Progress: I have a keen eye for quality when it comes to handcrafted items. I'm looking for one item in particular that may be of use to us on the field of battle.",rewardItems={154707},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142998}},ends={{npcID=142998}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[53228] = {id=53228,name="Arathi Donations: Battle Flag: Phalanx Defense",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53228},objectivesText="Gather 2 Battle Flag: Phalanx Defense for Faella in Boralus Harbor. Progress: Threading and craftsmanship are not all that matter. Our work speaks to the heart of our dedication, providing a beacon of hope on the field of battle. I am looking for such an item, one that is crafted by a highly skilled tailor. Have you seen anything of the sort?",rewardItems={154706},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142998}},ends={{npcID=142998}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[53229] = {id=53229,name="Arathi Donations: Enchant Ring - Seal of Critical Strike",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53229},objectivesText="Gather 2 Enchant Ring - Seal of Critical Strike for Mae Wagglewand in Boralus Harbor. Progress: I was just about done filling orders for the next shipment then realized I was out of materials! Do you think you can help me fill the remaining orders?",rewardItems={153438},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143007}},ends={{npcID=143007}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[53230] = {id=53230,name="Arathi Donations: Enchant Ring - Seal of Versatility",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53230},objectivesText="Gather 2 Enchant Ring - Seal of Versatility for Mae Wagglewand in Boralus Harbor. Progress: I know it's short notice, but I'm trying to find a few more enchantments to add to our next shipment.",rewardItems={153441},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143007}},ends={{npcID=143007}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[53231] = {id=53231,name="Arathi Donations: Gloom Dust",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53231},objectivesText="Gather 20 Enchant Weapon - Stalwart Navigation for Mae Wagglewand in Boralus Harbor. Progress: I've been able to keep pace with our orders until recently. Now I'm afraid I won't be able to keep up without help. Would you be willing to donate a few supplies?",rewardItems={152875},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143007}},ends={{npcID=143007}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[53232] = {id=53232,name="Arathi Donations: Incendiary Ammunition",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53232},description="Though our ammunition stockpiles are faring well, it's my duty to find additional resources, especially those that are harder to come by. Today I'm looking for a specific type of ammunition, one with incendiary properties. I could really use your help tracking a few of these down.",objectivesText="Gather 2 Incendiary Ammunition for Norber Togglesprocket in Boralus Harbor. Progress: Though our ammunition supplies are faring well, it's my duty to maintain a stockpile of additional resources, especially those that are harder to come by. Would you let me know if you stumble upon munitions with incendiary properties?",rewardItems={158203},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143008}},ends={{npcID=143008}},mapCandidates={npc={1161},zone={8568}},questGiverID=143008,questType="standard"},
[53233] = {id=53233,name="Arathi Donations: Frost-Laced Ammunition",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53233},description="Hey there! Transmission's come down from up top--we need more ammunition! Something with a bit more kick. Something really unexpected! From what I've heard there's a special frost-based ammunition crafted only by the most experienced engineers. If you were to bring me a few I'm sure our munitions officers would be ecstatic! Maybe they'd even let me keep one to examine!",objectivesText="Gather 2 Frost-Laced Ammunition for Norber Togglesprocket in Boralus Harbor. Progress: I've heard there's a special frost-based ammunition crafted only by the most experienced engineers. If you were to bring me a few of these I'm sure our munitions officers would be ecstatic!",rewardItems={158377},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143008}},ends={{npcID=143008}},mapCandidates={npc={1161},zone={8568}},questGiverID=143008,questType="standard"},
[53234] = {id=53234,name="Arathi Donations: F.R.I.E.D.",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53234},description="You never know when you'll need to deliver a big bang on the battlefield, if you know what I mean. Luckily we can plan for the unexpected! We've begun to store a special stockpile of explosives for scenarios where we'll need a little something extra to get our point across. I've added one particular item to the list. If you have any to spare I'll make sure they're put to good use.",objectivesText="Gather 3 F.R.I.E.D. for Norber Togglesprocket in Boralus Harbor. Progress: We've started a special stockpile of explosives for scenarios where we'll need a little something extra to get our point across. I've added one particular item to the list. If you have any to spare I'll make sure they're put to good use.",rewardItems={153490},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143008}},ends={{npcID=143008}},mapCandidates={npc={1161},zone={8568}},questGiverID=143008,questType="standard"},
[53235] = {id=53235,name="Arathi Donations: War-Scroll of Intellect",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53235},description="Enlightenment guides our path to victory. In battle, we fight as one. Share your knowledge and skills with me. Generosity is never forgotten.",objectivesText="Gather 3 War-Scroll of Intellect for Liao in Boralus Harbor. Progress: Enlightenment presents opportunity for victory.",rewardItems={158201},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143005}},ends={{npcID=143005}},mapCandidates={npc={1161},zone={8568}},questGiverID=143005,questType="standard"},
[53236] = {id=53236,name="Arathi Donations: War-Scroll of Fortitude",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53236},objectivesText="Gather 3 War-Scroll of Fortitude for Liao in Boralus Harbor. Progress: The opportunity for strength and fortitude present themselves when facing difficult situations.",rewardItems={158204},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143005}},ends={{npcID=143005}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[53237] = {id=53237,name="Arathi Donations: War-Scroll of Battle Shout",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53237},objectivesText="Gather 3 War-Scroll of Battle Shout for Liao in Boralus Harbor. Progress: With preparation comes success.",rewardItems={158202},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143005}},ends={{npcID=143005}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[53238] = {id=53238,name="Arathi Donations: Versatile Kyanite",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53238},objectivesText="Gather 20 Versatile Kyanite for Larold Kyne in Boralus Harbor. Progress: Our gem supplies are running low. Any you can spare would be greatly appreciated.",rewardItems={153712},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143004}},ends={{npcID=143004}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[53239] = {id=53239,name="Arathi Donations: Straddling Viridium",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53239},objectivesText="Gather 15 Straddling Viridium for Larold Kyne in Boralus Harbor. Progress: We need more gems!",rewardItems={153715},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143004}},ends={{npcID=143004}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
