[53241] = {id=53241,name="Arathi Donations: Coastal Mana Potion",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53241},objectivesText="Progress: I know ya be tinkin' I be runnin' out of supplies again. And I ain't here ta argue about you bein' right. So if ya can bring me some o' dem mana potions, I be gettin' back ta business and we be preparin' for de battle to come.",rewardItems={152495},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142159}},ends={{npcID=142159}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[53242] = {id=53242,name="Arathi Donations: Coastal Healing Potion",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53242},objectivesText="Progress: A few o' dem healin' potions be a nice addition ta our supply. Bring me a few and I be sure dey be gettin' where dey need ta be.",rewardItems={152494},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142159}},ends={{npcID=142159}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[53243] = {id=53243,name="Arathi Donations: Coarse Leather Barding",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53243},objectivesText="Progress: Our riders are not the only ones requiring protection on the field of battle, but our beasts as well. If you were to bring me a supply of barding I will personally see to it that our riders and their beasts are outfitted and ready for the battle to come.",rewardItems={154166},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142970}},ends={{npcID=142970}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
