[53265] = {id=53265,name="Arathi Donations: Gold",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53265},description="We've spent a great deal of time and resources preparing for the battle to come. As we begin final preparations, we'll be setting aside additional funding to ensure further training and supplies are available at a moment's notice. Would you like to make a donation?",objectivesText="Donate 1000000 Gold to Paymaster Vauldren in Boralus Harbor. Progress: As we begin final preparations, we'll be setting aside additional funding to ensure further training and supplies are available at a moment's notice. Would you like to make a donation?",rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142685}},ends={{npcID=142685}},mapCandidates={npc={1161},zone={8568}},questGiverID=142685,questType="standard"},
