[53267] = {id=53267,name="Mission Report: Dino Research",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={53267},series={53268},description="Your followers have sent a report regarding the mission at Verdant Hollow. It details that the mission was a success and a variety of dinasaur specimens have been recovered. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.",objectivesText="Deliver the mission report to Halford Wyrmbane . Progress: Do you have news regarding the mission for Verdant Hollow?",rewardGold=23400,rewardXP=850,rewardItems={163597},starts={{npcID=138704}},ends={{npcID=135612}},mapCandidates={npc={1161},zone={8568}},questGiverID=138704,questType="standard"},
[53268] = {id=53268,name="Dino Research",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53268},series={53267},description="The mission to gather research specimens was a success. Well done, <name>. You should check in with the outpost commander and inspect the specimens yourself. Make your way to Verdant Hollow in Zuldazar and speak with Argrim Stonedeep .",objectivesText="Speak with Argrim Stonedeep .",rewardGold=117000,rewardXP=3410,starts={{npcID=135612}},ends={{npcID=142101}},mapCandidates={npc={862,1161},zone={8568}},questType="standard",sourceQuests={53267}},
