[53330] = {id=53330,name="WANTED: Razorclaw Alpha",level=30,requiredLevel=30,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={53330},description="The Horde requires your contributions! We are in need of materials to craft and repair our arms and armor. There are bountiful resources in this land and they are but ours for the taking. Seek out the largest wolf you can find, slay it, and secure it's pelt so that we may craft a cloak befitting Rexxar! - Centurion Kaga Warmstone",objectivesText="Obtain a Razorclaw Alpha Pelt . Progress: Have you located a suitable pelt?",rewardGold=210000,rewardXP=5145,rewardItems={163636},rewardCurrencies={{id=1553,amount=115}},ends={{npcID=138886}},startObjects={{objectID=297492,mapID=942,x=0.51,y=0.336}},coords={mapID=942,source="quest_giver",x=0.52,y=0.336},mapCandidates={npc={942},zone={9042}},questType="group"},
