[53332] = {id=53332,name="Time for War",level=35,requiredLevel=35,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={47189,51714,51715,52544,52654,53074,53332},series={52544,52654},description="You should return to Commander Wyrmbane to begin working with the 7th Legion.",objectivesText="Report to Halford Wyrmbane in Boralus.",rewardGold=257400,rewardXP=4790,rewardCurrencies={{id=1553,amount=500}},starts={{npcID=135612}},ends={{npcID=135612}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={52544},questLines={{id=615,name="Mission from the King",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
