[53336] = {id=53336,name="WANTED: Sabertusk Empress",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={53336},description="To any and all brave enough to seek the challenge: Find and defeat a ferocious Sabertusk Empress , the strongest and most vicious of all sabertusks in Zuldazar . They can be found up and down the road from the Village in the Vines. A reward for any that succeed!",objectivesText="Slay a Sabertusk Empress",rewardGold=772200,rewardXP=2125,rewardCurrencies={{id=1553,amount=115}},ends={{npcID=141949}},startObjects={{objectID=287189,mapID=862,x=0.516,y=0.454}},coords={mapID=862,source="quest_giver",x=0.448,y=0.275},mapCandidates={npc={862},zone={8499}},questType="group"},
[53337] = {id=53337,name="WANTED: Prime Thumpknuckle",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={53337},description="To any and all brave enough to seek the challenge: Find and defeat a Prime Thumpknuckle , the largest and most dangerous of all the wild gorillas. They can be found up and down the road from the Village in the Vines. A reward for any that succeed!",objectivesText="Slay a Prime Thumpknuckle",rewardGold=6000,rewardXP=2125,rewardItems={163047},rewardCurrencies={{id=1553,amount=115}},ends={{npcID=141949}},startObjects={{objectID=287189,mapID=862,x=0.516,y=0.454}},coords={mapID=862,source="quest_giver",x=0.448,y=0.275},mapCandidates={npc={862},zone={8499}},questType="group"},
[53338] = {id=53338,name="Prove your Worth",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=9543,mapID=862,storyline={53338},description="See many Alliance out there, <race>? We're getting reports of more and more Alliance showing up here on Zandalar. Don't forget that this is a W-A-R. Prove your worth, and get out there and slay as many of them as you can. For the Horde!",objectivesText="Enable War Mode and slay 1 Alliance Player within the world.",rewardGold=128700,rewardXP=4085,rewardItems={163604},rewardCurrencies={{id=1602,amount=50}},starts={{npcID=143551}},ends={{npcID=143551}},mapCandidates={npc={862},zone={8499}},questType="standard"},
[53342] = {id=53342,name="Molten Core",level=40,requiredLevel=40,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=1519,mapID=84,storyline={51474,51813,53342,53351,53352,53566},series={51474,51813,53351,53352,53566},description="We'll need a fragment o' the core tae repair the Black Anvil an' who knows how much dark iron tae achieve the necessary purity. Thaelin can figure that part out. In fact, I think he oughta go with ye tae get yerself a Fragment o' the Molten Core . It's too dangerous tae go deep via mole machine, but he's got a hardy tank that can get ye the rest o' the way from the top. Talk tae me when yer ready.",objectivesText="Speak with Moira at the Stormwind Embassy to travel to Molten Core and retrieve a Fragment of the Molten Core. Progress: Sometimes it's hard tae understand Thaelin's ramblin's, but he's a smart one.",rewardGold=182760,rewardXP=5465,rewardItems={71096,163693},starts={{npcID=133197}},ends={{npcID=133197}},mapCandidates={npc={84},zone={1519}},questType="standard",sourceQuests={53351},questLines={{id=781,name="Allies of the Alliance: Dark Iron Dwarf",orderIndex=1,flags=0}},db2PoiUiMapID=84},
[53343] = {id=53343,name="Censership",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={53343},objectivesText="Sources of corruption cleansed Cave 1 cleared Cave 2 cleared Cave 3 cleared Cave 4 cleared Cave 5 cleared",rewardItems={163212},mapCandidates={npc={},zone={9042}},questType="world",db2Objectives={{text="Sources of corruption cleansed",amount=13,type=0,objectID=143127,orderIndex=0},{text="Cave 1 cleared",amount=1,type=0,objectID=133757,orderIndex=1},{text="Cave 2 cleared",amount=1,type=0,objectID=133758,orderIndex=2},{text="Cave 3 cleared",amount=1,type=0,objectID=133759,orderIndex=3},{text="Cave 4 cleared",amount=1,type=0,objectID=141789,orderIndex=4},{text="Cave 5 cleared",amount=1,type=0,objectID=141790,orderIndex=5}},worldTaskTitle="Censership",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
