[53701] = {id=53701,name="A Drust Cause",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={53701},description="Horde armies are pushing into the heart of Drustvar. Hold the line and drive them back to the holes they crawled out of. Kul Tiras is ours!",objectivesText="Repel the Horde forces assaulting Drustvar. Progress: We cannot rest while the Horde assault Drustvar!",rewardXP=2125,rewardItems={165872,166792},rewardCurrencies={{id=1717,amount=5}},ends={{npcID=135815}},coords={mapID=896,source="quest_giver",x=0.378,y=0.49},mapCandidates={npc={896},zone={8721}},questType="standard"},
