[53711] = {id=53711,name="A Sound Defense",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,storyline={53711},description="Horde forces are attacking Tiragarde Sound. Make them regret every footstep upon our soil!",objectivesText="Repel the Hordes forces assaulting Tiragarde Sound. Progress: The Horde dares to assault us here in Boralus?! Our response must be swift, massive, and merciless!",rewardXP=2125,rewardItems={165872,166792},rewardCurrencies={{id=1717,amount=5},{id=1553,amount=400}},starts={{npcID=135808}},ends={{npcID=135808}},mapCandidates={npc={},zone={8567}},questGiverID=135808,questTurnInID=135808,questType="standard"},
