[53719] = {id=53719,name="Allegiance of the Zandalari",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53719,53823,53824,53825,53826,53827,53828,53830,53831,54031,54032,54033,54034,54300,54301,54419,54925},description="It is decided, <name>. De Zandalari will join de Horde. Our path together has been a long and difficult one. We have lost much together. De Horde has sacrificed for de Zandalari, and vice versa. I can do nothing to honor that commitment except pledge our loyalty. Collect your Warchief and send them to my throne. I will extend de offer myself.",objectivesText="Bring the Zandalari into the Horde.",rewardGold=929400,rewardXP=8200,rewardItems={157870},starts={{npcID=146335}},ends={{npcID=145374}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={53830},questLines={{id=919,name="Allies of the Horde: Zandalari",orderIndex=16,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[53720] = {id=53720,name="Allegiance of Kul Tiras",level=40,requiredLevel=40,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=1519,mapID=84,storyline={53720,54706,54708,54721,54723,54725,54726,54727,54728,54729,54730,54731,54732,54733,54734,54735,54851,55039,55043,55136},description="It is time for her maiden voyage, <name>. This aptly named vessel will carry us and her crew across the vast sea to Stormwind Harbor. There we will meet Anduin and I will seal the pact we made so many moons ago. Kul Tiras will stand with the Alliance so long as I am Lord Admiral. Thank you for your assistance in this endeavor.",objectivesText="Sail to Stormwind Harbor and present Anduin with his gift.",rewardGold=1024800,rewardXP=8200,rewardItems={164762,245271,252386,252400,252403,252406,252653,252654,252754},starts={{npcID=148798}},ends={{npcID=149518}},mapCandidates={npc={84},zone={1519}},questType="standard",sourceQuests={54851},questLines={{id=916,name="Allies of the Alliance: Kul Tiran",orderIndex=0,flags=0}},db2PoiUiMapID=84},
[53721] = {id=53721,name="Heritage of the Zandalari",level=50,requiredLevel=50,faction="horde",requiredRaces={31},categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={53721},description="You have faced many challenges in your time among de Horde. You carried de pride of de Zandalari on your shoulders and triumphed! Return to me. I wish to recognize de example you have set for us all.",objectivesText="Meet Queen Talanji at the Golden Throne in Zuldazar City.",rewardGold=234000,rewardXP=6815,rewardItems={170063,174077,203176,208476,210054,218105,218118,218119,242520},starts={{npcID=146335}},ends={{npcID=146335}},mapCandidates={npc={1165},zone={8670}},questGiverID=146335,questType="standard"},
[53722] = {id=53722,name="Heritage of the Kul Tiran",level=50,requiredLevel=50,faction="alliance",requiredRaces={32},categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={53722},description="Gossip in Boralus has oft reached my ears of your exceptional conduct, <name>. Meet me before the keep. I wish to commend your efforts on behalf of Kul Tiras.",objectivesText="Meet Katherine Proudmoore in Boralus.",rewardGold=328500,rewardXP=6815,rewardItems={170063,174077,203176,208476,210054,218105,218118,218119,242520},starts={{npcID=150941}},ends={{npcID=150941}},mapCandidates={npc={1161},zone={8568}},questGiverID=150941,questType="standard"},
[53724] = {id=53724,name="Shadow Hunter Mutumba",level=10,requiredLevel=10,faction="alliance",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={53724},rewardXP=2125,starts={{npcID=144987,mapID=942,x=0.366,y=0.518}},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=144987}},worldTaskTitle="Shadow Hunter Mutumba",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3440,db2VignetteName="Shadow Hunter Mutumba"},
[53725] = {id=53725,name="A People Shattered",level=50,requiredLevel=50,faction="horde",requiredRaces={10},categories={},flags={},sharable=true,expansion=7,zoneID=9318,mapID=110,storyline={53725,53734,53735,53736,53737,53738,53791,53853,53882,54096},description="While the monument here was intended to honor the fallen members of the Shattered Sun, it quickly took on a second meaning for the sin'dorei. It was not far from here that we lost one of our greatest heroes: Anasterian Sunstrider, the last king of Quel'Thalas. He led our final effort against the Scourge and personally crossed blades with Arthas himself. As we remember the sacrifices it took to reclaim this land, we also remember the sacrifices made in its defense.",objectivesText="Light the final flame. Progress: Yes?",rewardGold=31200,rewardXP=850,rewardItems={166896},starts={{npcID=145793}},ends={{npcID=145793}},mapCandidates={npc={110},zone={9318}},questType="standard",sourceQuests={53738},questLines={{id=811,name="Blood Elf Heritage Armor",orderIndex=8,flags=0}},db2PoiMapID=530,db2PoiUiMapID=122},
[53726] = {id=53726,name="Mechinations",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={53726},objectivesText="Bot Scrambler obtained Siege Shredders scrambled Crawler Mines scrambled North Teleporter scrambled South Teleporter scrambled",rewardXP=2125,rewardItems={165841},mapCandidates={npc={},zone={8568}},questType="standard",db2Objectives={{text="Bot Scrambler obtained",amount=1,type=1,objectID=165841,orderIndex=0},{text="Siege Shredders scrambled",amount=4,type=0,objectID=144705,orderIndex=1},{text="Crawler Mines scrambled",amount=8,type=0,objectID=144994,orderIndex=2},{text="North Teleporter scrambled",amount=1,type=0,objectID=144718,orderIndex=3},{text="South Teleporter scrambled",amount=1,type=0,objectID=145413,orderIndex=4}},worldTaskTitle="Mechinations",db2PoiMapID=1643,db2PoiUiMapID=1161,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
