[53755] = {id=53755,name="Blight and Sound",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={53755},objectivesText="Blight Barrels destroyed Stacks of Blight Barrels destroyed Stack 1 Stack 2 Stack 3",rewardXP=2125,mapCandidates={npc={},zone={8567}},questType="standard",db2Objectives={{text="Blight Barrels destroyed",amount=5,type=2,objectID=307029,orderIndex=0},{text="Stacks of Blight Barrels destroyed",amount=3,type=0,objectID=145177,orderIndex=1},{text="Stack 1",amount=1,type=2,objectID=307032,orderIndex=2},{text="Stack 2",amount=1,type=2,objectID=278495,orderIndex=3},{text="Stack 3",amount=1,type=2,objectID=307429,orderIndex=4}},worldTaskTitle="Blight and Sound",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[53759] = {id=53759,name="Look Out Below!",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={53759},objectivesText="Use the Siege Cannon Boralus Defenders slain Buildings destroyed",rewardXP=2125,mapCandidates={npc={},zone={8567}},questType="standard",db2Objectives={{text="Use the Siege Cannon",amount=1,type=3,objectID=144930,orderIndex=0},{text="Boralus Defenders slain",amount=40,type=0,objectID=145241,orderIndex=1},{text="Buildings destroyed",amount=8,type=0,objectID=145253,orderIndex=2}},worldTaskTitle="Look Out Below!",db2PoiMapID=1643,db2PoiUiMapID=1161,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[53760] = {id=53760,name="Unintended Consequences",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=896,storyline={53760,53761,53762,53763,53765,53766,54058,54113,54114,54117,54118,54126,54141,54144,54172,54174,54265,54433,54438,54439,54682,54683},series={53761,53762,54058,54113,54114,54117,54118,54144,54174,54265,54433},description="< Xal'atath speaks once more.> The servants of N'Zoth prepare for their master's return. They intend to conjure a scouring storm to wash away all unbelievers. The particular ritual they will invoke requires three ancient artifacts. One of void, one of storm, and one of ocean. Even now, I hear the void relic calling to me. It is being empowered... or corrupted, I am not sure which. I see it upon a cliff, overlooking a vast sea. Come, <class>. We can find a much better use for such a prize.",objectivesText="Find the Void Stone in Drustvar. Progress: Yes... this form should do nicely.",rewardGold=234000,rewardXP=6815,rewardItems={164761,164911,165605,168123},rewardCurrencies={{id=1553,amount=250}},ends={{npcID=144773},{npcID=152589}},startObjects={{objectID=311218,mapID=862,x=0.78,y=0.367}},coords={mapID=896,source="quest_giver",x=0.198,y=0.362},mapCandidates={npc={896},zone={9042}},questType="standard",sourceQuests={54113,54117},questLines={{id=851,name="Crucible of Storms",orderIndex=10,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[53761] = {id=53761,name="The Pirate's Treasure",level=50,requiredLevel=50,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={53760,53761,53762,53763,53765,53766,54058,54113,54114,54117,54118,54126,54141,54144,54172,54174,54265,54433,54438,54439,54682,54683},series={53760,53762,54058,54113,54114,54117,54118,54144,54174,54265,54433},description="I sense another relic. A trident thought lost to the depths. It calls to me, <name>. Do you hear it too? Its song takes form. I see a harbor to the east. An ambitious pirate, greedy and proud. Completely unaware of the power hidden within her hoard of gold. The would-be-captain's hubris will not permit her to simply hand over her prize. I fear she must be taught a rather harsh lesson. But that is your specialty, is it not?",objectivesText="Find the second relic. Progress: Is the trident in your possession?",rewardGold=468000,rewardXP=8520,rewardItems={164761,164763,164976,165605,168123},rewardCurrencies={{id=1553,amount=250}},starts={{npcID=144773},{npcID=152589}},ends={{npcID=145396}},mapCandidates={npc={895,896},zone={8721}},questType="standard",sourceQuests={53760,54058},questLines={{id=851,name="Crucible of Storms",orderIndex=12,flags=0},{id=5673,name="Lorewalking: Xal'atath",orderIndex=6,flags=0}},campaigns={{id=266,title="Lorewalking: Xal'atath",questLineID=5673,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[53762] = {id=53762,name="The Tempest Crown",level=50,requiredLevel=50,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53760,53761,53762,53763,53765,53766,54058,54113,54114,54117,54118,54126,54141,54144,54172,54174,54265,54433,54438,54439,54682,54683},series={53760,53761,54058,54113,54114,54117,54118,54144,54174,54265,54433},description="< Xal'atath breathes in deeply and smiles.> My strength grows. I can see it clearly now... the third relic we seek. The crown known as Tempest Caller . How fitting that after the fall of Atal'Gral, the gluttonous Toatana would be the one to find the artifact. He was always scuttling about the depths, seeking treasures for his collection. Toatana 's greed has left him trapped within a cave he can never leave. The crown awaits us there.",objectivesText="Retrieve the third relic. Progress: The crown is far more useful in our hands than in the claws of an oversized bottom-feeder.",rewardGold=468000,rewardXP=8520,rewardItems={164761,165018,165605,168123},rewardCurrencies={{id=1553,amount=300}},starts={{npcID=145396}},ends={{npcID=146384}},mapCandidates={npc={864,895},zone={8567}},questType="standard",sourceQuests={53761},questLines={{id=851,name="Crucible of Storms",orderIndex=13,flags=0},{id=5673,name="Lorewalking: Xal'atath",orderIndex=7,flags=0}},campaigns={{id=266,title="Lorewalking: Xal'atath",questLineID=5673,questLineOrder=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[53763] = {id=53763,name="Twist the Knife",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={53760,53761,53762,53763,53766,54058,54117,54118,54172,54174,54433,54439,54683},description="The relics are ours... as it was meant to be. There is but one more step needed for the great truths to be revealed. The naga sought to summon their storm from a place that echoes with ancient power. Though this site has had countless names over the ages, you mortals know it as the Precipice of Oblivion. I will go on ahead and begin preparations. Join me there.",objectivesText="Meet Xal'atath at the Precipice of Oblivion. Progress: We are so close now... to the end.",rewardGold=468000,rewardXP=8520,rewardItems={164761,165605,168123},starts={{npcID=146384}},ends={{npcID=146335},{npcID=231891}},mapCandidates={npc={84,864,1165},zone={8501}},questType="standard",sourceQuests={53762},questLines={{id=851,name="Crucible of Storms",orderIndex=14,flags=0},{id=5673,name="Lorewalking: Xal'atath",orderIndex=8,flags=0}},campaigns={{id=266,title="Lorewalking: Xal'atath",questLineID=5673,questLineOrder=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[53765] = {id=53765,name="His Eye Upon You",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53760,53761,53762,53765,54058,54113,54114,54126,54141,54144,54265,54438,54682},description="Something dark has taken root within you, <name>. The tendrils of N'Zoth are burrowing into your mind and soul, eager to consume everything you are. I can perform a rite of cleansing, but only in a place that resonates with the very power that grips you. Meet me near the Crucible of Storms. The ritual will be perilous and painful, but it is your only chance to be free. The Old God has eyes everywhere. I do not wish you to become one of them.",objectivesText="Meet Brother Pike near the Crucible of Storms to cleanse your \"gift\". Progress: There can be no treating with the darkness, <name>.",rewardGold=202200,rewardXP=850,rewardItems={6286,21134,164761,165605,168123},starts={{npcID=146902}},ends={{npcID=148134}},mapCandidates={npc={942,1161},zone={8568}},questType="standard",sourceQuests={54126},questLines={{id=851,name="Crucible of Storms",orderIndex=16,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[53766] = {id=53766,name="His Eye Upon You",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=9598,mapID=1165,description="Dark mojo has fallen upon you, . I can sense de tendrils of N'Zoth delving deep into your mind. Dis evil must be purged... before it claims your very soul! Go to de Altar of Akunda in de Terrace of de Chosen. Seek out Nailok , one of de priests of Akunda. He is your best chance to be cleansed of de wicked curse dat grips you.",rewardXP=850,rewardItems={168123},starts={{npcID=133050},{npcID=146335}},ends={{npcID=146776}},mapCandidates={npc={1165},zone={9598}},questType="standard",sourceQuests={53763},questLines={{id=851,name="Crucible of Storms",orderIndex=17,flags=0}}},
[53768] = {id=53768,name="Furious Fracas",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={53768},objectivesText="Horde Soldiers slain",rewardXP=2125,rewardItems={166459},mapCandidates={npc={},zone={8500}},questType="standard",db2Objectives={{text="Horde Soldiers slain",amount=12,type=0,objectID=144958,orderIndex=0}},worldTaskTitle="Furious Fracas",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
