[53773] = {id=53773,name="Naga Attack!",level=10,requiredLevel=10,faction="none",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={53773},objectivesText="Repel the naga invaders Captives freed War supplies destroyed Banners removed",rewardXP=2125,rewardItems={165605,168003,168123},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{text="Repel the naga invaders",amount=1,type=15,objectID=0,orderIndex=0},{text="Captives freed",amount=34,type=0,objectID=145207,orderIndex=1},{text="War supplies destroyed",amount=34,type=0,objectID=145262,orderIndex=2},{text="Banners removed",amount=34,type=0,objectID=145265,orderIndex=3}},worldTaskTitle="Naga Attack!",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=111,db2QuestInfoName="Elite World Quest"},
[53774] = {id=53774,name="Wisdom of the Warchief",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=9598,mapID=1165,storyline={53774,53775,53776,53777,53778,53779,53780,53781,53782,54120,54145,54147},series={53775},description="Champion. For a brief moment after the battle with G'huun, the spirit of our old warchief, Vol'jin, appeared in view of all in Zuldazar. I had a hundred questions to ask my old friend, but his spirit faded before I could muster my voice. I have asked Talanji to perform her seance once more, so that I might speak with the spirit of Vol'jin. Will you collect the Glaive of Vol'jin from its resting place at the base of the pyramid and then join us at Zanchul?",objectivesText="Meet Princess Talanji in the Hall of High Priests at Zanchul. Progress: Have you brought the glaive?",rewardGold=23400,rewardXP=850,rewardItems={140192,164944,238818},starts={{npcID=141555}},ends={{npcID=141555}},mapCandidates={npc={},zone={9598}},questGiverID=141555,questTurnInID=141555,questType="standard",sourceQuests={51521,54165},questLines={{id=805,name="The Shadow Hunter",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[53775] = {id=53775,name="Shades of Disruption",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8726,mapID=1167,storyline={53774,53775,53776,53777,53778,53779,53780,53781,53782,54120,54145,54147},series={53774},description="Vol'jin's spirit is a slippery one. I have asked Master Gadrin and Spiritwalker Ebonhorn to aid us in calling him forth. Dis ritual will not be easy, and I ask you to be on your guard should anything other than Vol'jin appear.",objectivesText="Assist in the ritual to summon Vol'jin's spirit.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1553,amount=500}},starts={{npcID=145190}},ends={{npcID=145190}},mapCandidates={npc={},zone={8726}},questGiverID=145190,questTurnInID=145190,questType="standard",sourceQuests={53774},questLines={{id=805,name="The Shadow Hunter",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1167},
[53776] = {id=53776,name="To the Broken Shore",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8726,mapID=646,storyline={53774,53775,53776,53777,53778,53779,53780,53781,53782,54120,54145,54147},description="Da Broken Shore be where I fell in battle. We were overrun, demons everywhere. Sylvanas was doing what she could, but Thrall was down and I had fallen. It was horror. And now I need ya to take me back dere. Take me glaive to da battlefield, call to me, and I will come. Perhaps if I be in da spot where me blood was spilled, we might shine some light on dis mystery.",objectivesText="Take the Glaive of Vol'jin to Spiritwalker Ebonhorn at the Broken Shore.",rewardGold=23400,rewardXP=850,rewardItems={136582,136583,136584,136586,136587,136588,136589,136590,136591,136595,138764,138765,138766,138767,138768,138769,138770,138771,138772,139292,165401},starts={{npcID=145225}},ends={{npcID=146734}},mapCandidates={npc={646},zone={8726}},questGiverID=145225,questType="standard",sourceQuests={53775},questLines={{id=805,name="The Shadow Hunter",orderIndex=2,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=646},
[53777] = {id=53777,name="Where He Died",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=14,mapID=1,storyline={53774,53775,53776,53777,53778,53779,53780,53781,53782,54120,54145,54147},series={53779,54145},description="Dis time, I need to bring ya to my side. We gonna walk da shadows between life and death, see if we can't uncover some clues. Be careful, $p, and be armed. Not everything on dis side wants us to find answers. Prepare yourself, den speak with me when ya be ready.",objectivesText="Walk the shadows with Vol'jin. Progress: I not be scared away so easily. What dey gonna do, kill me again?",rewardGold=234000,rewardXP=6815,starts={{npcID=146290}},ends={{npcID=146290}},mapCandidates={npc={1},zone={14}},questTurnInID=146290,questType="standard",sourceQuests={54120},questLines={{id=805,name="The Shadow Hunter",orderIndex=5,flags=0}},db2PoiMapID=1,db2PoiUiMapID=85},
[53778] = {id=53778,name="Where He Fell",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=7543,mapID=646,storyline={53774,53775,53776,53777,53778,53779,53780,53781,53782,54120,54145,54147},series={54120},description="Dis be da spot, mon. Dis be where da Legion led our forces into a trap and drove a blade into me belly. Sylvanas pulled me from da ruin of da battlefield. She saved da Horde dat day. Come, let us walk around dis place and see what we can learn from da echoes of da past.",objectivesText="Search the Screaming Cliffs with the Spirit of Vol'jin .",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1553,amount=500}},starts={{npcID=145965}},ends={{npcID=145965}},mapCandidates={npc={646},zone={7543}},questTurnInID=145965,questType="standard",sourceQuests={53776},questLines={{id=805,name="The Shadow Hunter",orderIndex=3,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=646},
[53779] = {id=53779,name="The Lies of a Loa",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={53774,53775,53776,53777,53778,53779,53780,53781,53782,54120,54145,54147},series={53777,54145},description="Hidden memories, spirits attackin' us for investigating, and a long road of bodies in da wake of me makin' Sylvanas warchief. I be thinkin' it time ya speak with Ol' Bwonsamdi. Odd as it sounds, dis don't seem like his style. Dat don't mean he not be behind it. Ya best work with Talanji. From what little I been seein', da death loa got a soft spot for her highness. You can confront Bwonsamdi at his necropolis in Nazmir. Just... be respectful.",objectivesText="Meet Talanji at the Necropolis in Nazmir.",rewardGold=23400,rewardXP=850,starts={{npcID=146630}},ends={{npcID=146824}},mapCandidates={npc={863},zone={8500}},questGiverID=146630,questType="standard",sourceQuests={53777},questLines={{id=805,name="The Shadow Hunter",orderIndex=6,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[53780] = {id=53780,name="Jailor of the Damned",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={53774,53775,53776,53777,53778,53779,53780,53781,53782,54120,54145,54147},description="I be havin' many rivals when it comes to claimin' souls. But it takes some serious mojo to do to Vol'jin what ya describe. Dat kind of power smells of old magic. Icecrown. It be more dan a pretty throne. It be an anchor dat holds dis world to da next, ya might say. I gonna open a death gate, and ya can go through and ask da Lich King if he be treadin' on Ol' Bwonsamdi 's ground.",objectivesText="Confront the Lich King . Progress: Mind ya step. Ya be dancin' between powers dat may do more dan just kill ya.",rewardGold=468000,rewardXP=8520,starts={{npcID=122688}},ends={{npcID=122688}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={54145},questLines={{id=805,name="The Shadow Hunter",orderIndex=10,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[53781] = {id=53781,name="Eyir",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={53774,53775,53776,53777,53778,53779,53780,53781,53782,54120,54145,54147},series={53782,54147},description="Not many got da stones or da mojo to take what be mine. Ol' Bwonsamdi always be gettin' his share. Da way Talanji be tellin' it, Vol'jin's spirit may be gettin' help from some other power. And dere be few who love to mess with souls like Eyir. A meddlin' one she be, with her wings and her valor. Ya best be seein' her in person. She be found in her vault at Skold-Ashil. And ya best not mention me name, or she might be sendin' ya back to me faster dan any death gate.",objectivesText="Meet Talanji at Skold-Ashil in Stormheim.",rewardGold=23400,rewardXP=850,starts={{npcID=122688}},ends={{npcID=146877}},mapCandidates={npc={634,863},zone={8500}},questType="standard",sourceQuests={54145},questLines={{id=805,name="The Shadow Hunter",orderIndex=8,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=634},
[53782] = {id=53782,name="Mysteries of Death",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={53774,53775,53776,53777,53778,53779,53780,53781,53782,54120,54145,54147},series={53781,54147},description="Hmph. Well, da Lich King and dat bossy val'kyr not be me only rivals. But dey were da ones most likely ta be behind all dis. Someone be playin' with very ancient mojo. Tell Vol'jin's spirit dat da answers he be lookin' for not be found in da world of da living. He gonna need to go beyond da veil ta learn what needs knowin'. Dere be some places on dat side only he can go.",objectivesText="Speak with the Spirit of Vol'jin .",rewardGold=1014900,rewardXP=10225,rewardCurrencies={{id=1553,amount=1000}},starts={{npcID=122688}},ends={{npcID=147216}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={53780,54147},questLines={{id=805,name="The Shadow Hunter",orderIndex=11,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[53783] = {id=53783,name="In the Dunes",level=50,requiredLevel=50,faction="horde",requiredProfessions={"engineering"},categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={53783,53802,53806,53833,53848,53937,54930,55031},description="This schematic you found is encrypted. My tools are no good on it, not without risking the integrity of the data. However, I do know a guy who can definitely crack this cookie: Mr. Dataguru Gryzix . If I remember correctly, he's been vacationing on a beach in Vol'dun since the war broke out. Something about not getting the recognition he deserves. Anyways, I am sure you can convince him to help you.",objectivesText="Find Dataguru Gryzix at The Forgotten Marsh in Vol'dun. Provided item:",rewardGold=23400,rewardXP=850,rewardItems={164740,164919,253179,253700},starts={{npcID=131840}},ends={{npcID=145131}},mapCandidates={npc={864,1165},zone={8670}},questType="standard",sourceQuests={55031},questLines={{id=868,name="Tools of the Trade: The Ub3r-Spanner",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[53784] = {id=53784,name="Siege Engineer Krackleboom",level=10,requiredLevel=10,faction="alliance",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={53784},rewardXP=2125,mapCandidates={npc={},zone={8568}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=145161}},worldTaskTitle="Siege Engineer Krackleboom",db2PoiMapID=1643,db2PoiUiMapID=1161,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3419,db2VignetteName="Siege Engineer Krackleboom"},
[53787] = {id=53787,name="Modular Construction",level=50,requiredLevel=50,faction="none",requiredProfessions={"engineering"},categories={},flags={},sharable=false,expansion=7,storyline={53787},description="The Abandoned Junkheap is home to some seriously deadly gnomish constructs. These constructs contain Mecha-Cores which could come in handy for crafting the Ub3r-Spanner. Legend has it that it could forge creations unlike anything we've ever seen! You look like the adventurous type, . Can you go scrap up some mechs? Don't forget your Arclight Spanner!",objectivesText="Kill mechanical constructs in the Abandoned Junkheap and salvage 8 Mecha-Cores with an Arclight Spanner.",rewardGold=234000,rewardXP=6815,rewardItems={164768},mapCandidates={npc={},zone={}},questType="standard"},
[53791] = {id=53791,name="The Pride of the Sin'dorei",level=50,requiredLevel=50,faction="horde",requiredRaces={10},categories={"campaign"},flags={"important"},sharable=true,expansion=7,zoneID=1637,mapID=85,storyline={53725,53734,53735,53736,53737,53738,53791,53853,53882,54096},series={53734},description="<name>, Lor'themar Theron has requested your presence in Silvermoon. He's asking for your assistance with a ceremony of great importance.",objectivesText="Speak with Lor'themar in Silvermoon City.",rewardGold=30900,rewardXP=850,rewardItems={166896,170063,174077,203176,208476,210054,218105,218118,218119,242520},starts={{npcID=146939}},ends={{npcID=16802}},mapCandidates={npc={85,110},zone={1637}},questType="standard",questLines={{id=811,name="Blood Elf Heritage Armor",orderIndex=0,flags=0}},db2PoiMapID=530,db2PoiUiMapID=110},
[53800] = {id=53800,name="Battle for Darkshore",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,storyline={53800},rewardGold=315000,rewardXP=1110,rewardItems={52616,52655,131316,166369,166370},mapCandidates={npc={},zone={}},questType="standard"},
[53801] = {id=53801,name="Battle for Darkshore",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,storyline={53801},rewardGold=315000,rewardXP=1110,rewardItems={52616,52655,131316,166369,166370},mapCandidates={npc={},zone={}},questType="standard"},
[53802] = {id=53802,name="Sethrak Persuasion",level=50,requiredLevel=50,faction="both",requiredProfessions={"engineering"},categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={53783,53802,53806,53833,53848,53937,54930,55031},description="Let me see the schematic... Yeah, yeah, alright. I can help you. I am going to need a few things to power my decoder. I need a way to channel electricity from the air around us. What better than to steal...I mean borrow some lightning rods from the sethrak that have been trying to steal my tech for weeks now! I'm sure you'll have to do some \"convincing\", but you seem like a pretty convincing <race>.",objectivesText="Collect Faithless Lightning Rods in the Scalefang Outpost. Progress: I need those rods to do my work, <name>.",rewardGold=234000,rewardXP=6815,rewardItems={164740,164770},starts={{npcID=145131}},ends={{npcID=145131}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={53783,53947},questLines={{id=868,name="Tools of the Trade: The Ub3r-Spanner",orderIndex=2,flags=0},{id=869,name="Tools of the Trade: The Ub3r-Spanner",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[53803] = {id=53803,name="Fist of Orgrimmar - TBD OLD PORTAL QUEST",expansion=7,mapID=862,questType="world",worldTaskTitle="Fist of Orgrimmar - TBD OLD PORTAL QUEST",db2QuestInfoID=113,db2QuestInfoName="PvP World Quest"},
[53804] = {id=53804,name="Dinomancer Zakuru",level=10,requiredLevel=10,faction="alliance",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={53804},rewardXP=2125,starts={{npcID=145278,mapID=942,x=0.346,y=0.578}},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=145278}},worldTaskTitle="Dinomancer Zakuru",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3445,db2VignetteName="Dinomancer Zakuru"},
[53805] = {id=53805,name="A Friend in Needle",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"tailoring"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53805,53807,53881,55177},description="You can see me? Oh, thank goodness! I thought I was lost in the folds of time...again! But for one to see through the folds of time's fabric... you must be a very talented tailor, indeed. Would you bring me some cloth, then, tailor? I believe I'll be able to place just when I am with your help and right myself.",objectivesText="Collect 5 Tidespray Linen and 5 Deep Sea Satin . Progress: When in Azeroth am I...?",rewardGold=58500,rewardXP=1705,rewardItems={152576,152577,152668,159959,164733,168029,168128,168129,168130,168131},starts={{npcID=145022}},ends={{npcID=145022}},mapCandidates={npc={1161},zone={8568}},questType="standard",questLines={{id=904,name="8.1.5 Tailoring - Alliance",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[53806] = {id=53806,name="Heavy is the Head",level=50,requiredLevel=50,faction="both",requiredProfessions={"engineering"},categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={53783,53802,53806,53833,53848,53937,54930,55031},description="Okay, I am going to need one more thing from you. The sethrak leader, Warlord Surgios, has been a real pain for me. He stole my mind enhancer. I can't do my work without it. It will make me be able to think much more clearly, and make less...deadly mistakes.",objectivesText="Collect the Goblin \"Mind Enhancer\" from Warlord Surgios in the Scalefang Outpost. Progress: Do you have my mind enhancer?",rewardGold=234000,rewardXP=6815,rewardItems={164740,166882},starts={{npcID=145131}},ends={{npcID=145131}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={53783,53947},questLines={{id=868,name="Tools of the Trade: The Ub3r-Spanner",orderIndex=4,flags=0},{id=869,name="Tools of the Trade: The Ub3r-Spanner",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[53807] = {id=53807,name="A Stitch in Time",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"tailoring"},categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=115,storyline={53805,53807,53881,55177},series={55177},description="Hm...I don't know that I've ever been to this time, before. I suppose I should explain myself. My name is Delormi, and I'm the last remaining member of the Synchronous Tailors . We make sure the fabric of time stays, well, mended. But I've found a number of new tears cropping up. In fact, I believe that's why I've arrived here in this time. Perhaps you could assist me in tracking them down and repairing them?",objectivesText="Assist Delormi in repairing the Tears in Time. Progress: Something strange is happening. These tears have become too frequent as of late.",rewardGold=58500,rewardXP=1705,rewardItems={152576,152668,159959,164733,167231,168029,168128,168129,168130,168131},starts={{npcID=151134}},ends={{npcID=151134}},mapCandidates={npc={115},zone={9042}},questTurnInID=151134,questType="standard",sourceQuests={53805},questLines={{id=904,name="8.1.5 Tailoring - Alliance",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[53808] = {id=53808,name="Crawl To Victory",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={53808},objectivesText="Acquire transport from Paratrooper Jacobs Crawler parts collected Use remote mine controls Alliance bunker destroyed",rewardXP=2125,rewardItems={164742},mapCandidates={npc={},zone={8568}},questType="standard",db2Objectives={{text="Acquire transport from Paratrooper Jacobs",amount=1,type=3,objectID=139776,orderIndex=0},{text="Crawler parts collected",amount=8,type=1,objectID=164742,orderIndex=1},{text="Use remote mine controls",amount=1,type=2,objectID=307424,orderIndex=2},{text="Alliance bunker destroyed",amount=1,type=0,objectID=145314,orderIndex=3}},worldTaskTitle="Crawl To Victory",db2PoiMapID=1643,db2PoiUiMapID=1161,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[53810] = {id=53810,name="The Severed Thread",level=50,requiredLevel=50,faction="both",requiredProfessions={"tailoring"},categories={},flags={},sharable=true,expansion=7,zoneID=440,mapID=115,storyline={53810,53813,53858,53866,53868,53869,55214},description="Do you see that? There's a corpse just ahead. To think the caverns have been so badly overrun... We should look at the bodies. Maybe there will be something of use to us.",objectivesText="Investigate the corpses in the Caverns of Time.",rewardGold=234000,rewardXP=6815,rewardItems={152576,152668,159959,164733,168029,168128,168129,168130,168131,225247},starts={{npcID=151134}},ends={{npcID=151134}},mapCandidates={npc={115},zone={440}},questType="standard",sourceQuests={55177,55188},questLines={{id=906,name="8.1.5 Tailoring - Alliance/Horde",orderIndex=0,flags=0}},db2PoiMapID=1,db2PoiUiMapID=75,db2QuestSortName="Nightborne"},
[53811] = {id=53811,name="Children's Week",level=10,requiredLevel=10,faction="alliance",categories={"seasonal"},flags={},sharable=false,event="Children's Week",expansion=7,zoneID=8568,mapID=1161,storyline={53811},description="Thank you for coming by to celebrate Children's Week, <class>. You are going to make one little boy very happy! Take this whistle. With it, you will be able to call for the child you have agreed to take care of this week. It will serve no use after Children's Week ends, as is custom. When you are ready, use the whistle and meet your new ward! I know he is ecstatic to meet you.",objectivesText="Use the Kul Tiran Orphan Whistle to call for the ward that you will be looking after during Children's Week. Provided item:",rewardItems={23022,116202,164772,166445,167008,167009,167010,167011},starts={{npcID=145291}},ends={{npcID=145291}},mapCandidates={npc={1161},zone={8568}},questTurnInID=145291,questType="standard",packageItems={241215}},
[53812] = {id=53812,name="A Carefully Laid Trap",level=10,requiredLevel=10,faction="alliance",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={53812},rewardXP=2125,starts={{npcID=145286,mapID=895,x=0.77,y=0.4159}},mapCandidates={npc={},zone={8567}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=145286},{orderIndex=1,type=0,amount=1,objectID=145287},{orderIndex=2,type=0,amount=1,objectID=145292}},worldTaskTitle="A Carefully Laid Trap",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3424,db2VignetteName="Motega Bloodshield"},
[53813] = {id=53813,name="Rolling Up the Sleeves",level=50,requiredLevel=50,faction="both",requiredProfessions={"tailoring"},categories={},flags={},sharable=true,expansion=7,zoneID=440,mapID=115,storyline={53810,53813,53858,53866,53868,53869,55214},description="The Caverns of Time? Strange... I spent many timelines in this very place. What's special about here-- now? We'll have to discern as much later on. It looks like we aren't the only ones who've been affected by these rifts... Let's do the Bronze Dragonflight a favor and clear out these anomalies.",objectivesText="Kill 12 Chronal Anomalies .",rewardGold=234000,rewardXP=6815,rewardItems={152576,152668,159959,164733,168029,168128,168129,168130,168131},starts={{npcID=151134}},ends={{npcID=151134}},mapCandidates={npc={115},zone={440}},questType="standard",sourceQuests={55177,55188},questLines={{id=906,name="8.1.5 Tailoring - Alliance/Horde",orderIndex=1,flags=0}},db2PoiMapID=1,db2PoiUiMapID=75,db2QuestSortName="Nightborne"},
[53814] = {id=53814,name="First Sergeant Steelfang",level=10,requiredLevel=10,faction="alliance",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={53814},rewardXP=2125,starts={{npcID=145308,mapID=895,x=0.86,y=0.426}},mapCandidates={npc={},zone={8567}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=145308}},worldTaskTitle="First Sergeant Steelfang",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3422,db2VignetteName="First Sergeant Steelfang"},
[53815] = {id=53815,name="Whatever Happened to Saffy Flivvers?",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={53815},description="When Azerite was discovered, my friend Saffy was sent to investigate what it could do. There was an attack and we all thought she'd died. Then it turns out she was forced to work in some kind of goblin think tank in Tanaris! But before we could get her out, the whole place exploded. Now, my bosses have written her off as dead. But she wasn't dead the first time so I'm not sure she is now. I've been told not to go looking for her, but you could take a look. Find Saffy, or what's left of her?",objectivesText="Search for signs of Sapphronetta Flivvers in Tanaris",rewardGold=23400,rewardXP=850,rewardItems={165845},starts={{npcID=143851}},ends={{npcID=151132}},mapCandidates={npc={71,1161},zone={8568}},questType="standard",sourceQuests={55119}},
[53816] = {id=53816,name="Some Reassembly Required",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=440,mapID=71,storyline={53816},description="<The word \" Feathers \" has been etched onto the broken mechanical creature -- the sort of thing the person you are looking for might have created. Collecting the pieces and recreating the mechanical construct will surely give you a clue as to their fate. The area is crawling with Venture Co. scavengers and goons. Their pockets are probably filled with mechanical bits you could use to fix Feathers .>",objectivesText="Collect Mechanical Parts from Venture Co. personnel. Progress: <You seem to have collected all the pieces.>",rewardGold=234000,rewardXP=6815,rewardItems={165845,167232},starts={{npcID=151132}},ends={{npcID=151132}},mapCandidates={npc={71},zone={440}},questType="standard",sourceQuests={53815,53817},db2QuestSortName="Nightborne"},
[53817] = {id=53817,name="Whatever Happened to Grizzek Fizzwrench?",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=862,storyline={53817},description="When this whole Azerite mess began I had a goblin named Grizzek Fizzwrench do some research for me. He was bad for business and had to be removed from the picture. I thought it was a done deal, only now I'm hearing maybe he's not so dead. I need you to hunt this guy down and see what happened. If he's alive, eliminate him and I'll add the standard mercenary fee to your reward.",objectivesText="Search for signs of Grizzek Fizzwrench in Tanaris.",rewardGold=23400,rewardXP=850,rewardItems={18986,165845},starts={{npcID=136683}},ends={{npcID=151132}},mapCandidates={npc={71,862},zone={8721}},questType="standard"},
[53818] = {id=53818,name="Re-parrot",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=440,mapID=71,storyline={53818},description="<Though very damaged, and filled with insects, you can tell Feathers seems to have some sort of recall program. Fixing the mechanical bird and following it back to the source may bring you to the person you seek. You were able to put the thing back together. How hard could debugging a mechanical parrot be?>",objectivesText="Debug Feathers ' recall program.",rewardGold=234000,rewardXP=6815,rewardItems={165845},starts={{npcID=151132}},ends={{npcID=151132}},mapCandidates={npc={71},zone={440}},questType="standard",sourceQuests={53816},db2QuestSortName="Nightborne"},
[53819] = {id=53819,name="Return to the Nest",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=440,mapID=71,storyline={53819},description="<You decide to activate the recall subroutine. Perhaps the parrot will lead you to the person you are looking for.>",objectivesText="Activate the recall subroutine.",rewardGold=234000,rewardXP=6815,rewardItems={165845},starts={{npcID=151132}},ends={{npcID=151129}},mapCandidates={npc={71},zone={440}},questType="standard",sourceQuests={53818},db2QuestSortName="Nightborne"},
[53820] = {id=53820,name="She's in a Happier Place",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=440,mapID=71,storyline={53820},description="Aww, Kelsey...she's been such a good friend. I meant to let her know I was alive eventually, but I got distracted. Azerite, the war, the near-death experience... We've been really busy. Being presumed dead has some advantages, though. We've done a lot of research and we just need a better lab- Okay. New plan. Tell Kelsey we'll be in touch, but only Kelsey. Tell everyone else I'm dead - for now. If you keep quiet about Grizzek, you- you can have Feathers . Do we have a deal?",objectivesText="Return to Kelsey Steelspark in Boralus.",rewardGold=234000,rewardXP=6815,rewardItems={165845},rewardChoices={165845},starts={{npcID=151129}},ends={{npcID=143851}},mapCandidates={npc={71,1161},zone={440}},questType="standard",sourceQuests={53819},db2QuestSortName="Nightborne"},
[53821] = {id=53821,name="He's Dead, Jastor",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=440,mapID=71,storyline={53821},description="Hey, uh, so I got a good thing goin' on here, and I really don't want Gallywix to know I'm alive. I'll make you a deal. You spin some story about how you only found tiny pieces of me spread across Tanaris and that I am totally dead, and... And you can keep the bird. Deal?",objectivesText="Return to Gazlowe in Zandalar Harbor.",rewardGold=234000,rewardXP=6815,rewardItems={165845},rewardChoices={165845},starts={{npcID=151130}},ends={{npcID=137313}},mapCandidates={npc={71,1165},zone={440}},questType="standard",sourceQuests={53819},db2QuestSortName="Nightborne"},
[53823] = {id=53823,name="A Queen's Entourage",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53719,53823,53824,53825,53826,53827,53828,53830,53831,54031,54032,54033,54034,54300,54301,54419,54925},series={53831},description="Princess Talanji was very clear in her orders. You, <name>, are to join her at de steps of Zanchul. She wishes to have you at her side while she undergoes de rite of queens and kings. I hope you can comprehend what an honor that is. De queen-to-be will explain what it is you are to do. Now go, and Pa'ku's winds make you swift.",objectivesText="Meet Princess Talanji at the Zocalo.",rewardGold=34100,rewardXP=685,starts={{npcID=145414}},ends={{npcID=145359}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={53831},questLines={{id=919,name="Allies of the Horde: Zandalari",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[53824] = {id=53824,name="The Rite of Kings and Queens",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53719,53823,53824,53825,53826,53827,53828,53830,53831,54031,54032,54033,54034,54300,54301,54419,54925},description="Now that you are here, we can begin this sacred rite. Take your place beside Talanji, <name>. She has chosen you for an important task. I will explain while we make our way to Zanchul.",objectivesText="Ride in procession with Princess Talanji . Progress: Your have more than earned such an honor, <name>.",rewardGold=341600,rewardXP=5465,starts={{npcID=148096}},ends={{npcID=148096}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={53823},questLines={{id=919,name="Allies of the Horde: Zandalari",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[53825] = {id=53825,name="The New Zanchuli Council",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8726,mapID=1165,storyline={53719,53823,53824,53825,53826,53827,53828,53830,53831,54031,54032,54033,54034,54300,54301,54419,54925},description="These are sobering developments <name>. I wish to speak to my priests about what has transpired. I would like you to continue into de depths of Zanchul and up de steps into de Council Chambers. There you will find de new council I have assembled. Greet them, and make note of my choices. I hope you will find them adequate.",objectivesText="Greet the Zanchuli Council. Progress: What do you think of my choices, <name>?",rewardGold=156400,rewardXP=2735,starts={{npcID=145359}},ends={{npcID=145359}},mapCandidates={npc={1165},zone={8726}},questType="standard",sourceQuests={54300,54301,54925},questLines={{id=919,name="Allies of the Horde: Zandalari",orderIndex=8,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1166},
[53826] = {id=53826,name="The Instigator Among Us",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53719,53823,53824,53825,53826,53827,53828,53830,53831,54031,54032,54033,54034,54300,54301,54419,54925},description="This situation can be swiftly dealt with if we take out de one that incited this violence. I heard reports of an enforcer rousing de vagrants and drudges against de shopkeepers and guards in de Zocalo. One of my own would not do this without cause. See if you can determine de reason for this sudden change. I am told her name is Malzon. I hope for her sake that she surrenders.",objectivesText="Confront Enforcer Malzon in the Zocalo.",rewardGold=683200,rewardXP=6830,starts={{npcID=145360}},ends={{npcID=145359}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={53824},questLines={{id=919,name="Allies of the Horde: Zandalari",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[53827] = {id=53827,name="The Council Has Spoken",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8726,mapID=1165,storyline={53719,53823,53824,53825,53826,53827,53828,53830,53831,54031,54032,54033,54034,54300,54301,54419,54925},description="Now that you see who I have chosen for my council, it is time to receive their blessing. It is a symbolic demonstration of support, but I believe there is power in words as well as deeds. When they declare themselves to me, de eyes of de loa are also upon them. I hope they like what they see, <name>. I know I do.",objectivesText="Receive the Zanchuli Council's blessing.",rewardGold=619600,rewardXP=6830,starts={{npcID=145359}},ends={{npcID=145359}},mapCandidates={npc={1165},zone={8726}},questType="standard",sourceQuests={53825},questLines={{id=919,name="Allies of the Horde: Zandalari",orderIndex=9,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1166},
[53828] = {id=53828,name="Gaze of the Loa",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53719,53823,53824,53825,53826,53827,53828,53830,53831,54031,54032,54033,54034,54300,54301,54419,54925},description="My council has given their blessing and we have dealt with an enemy. All that remains is to face de judgment of my loa. I do not know what this part will be like. My father never spoke of it, at least not to me. Walk with me. I will explain what is expected of you through this final trial.",objectivesText="Follow Talanji.",rewardGold=156400,rewardXP=2735,starts={{npcID=145359}},ends={{npcID=146263}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={53827},questLines={{id=919,name="Allies of the Horde: Zandalari",orderIndex=10,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[53830] = {id=53830,name="Queen of the Zandalari",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53719,53823,53824,53825,53826,53827,53828,53830,53831,54031,54032,54033,54034,54300,54301,54419,54925},description="De loa have seen fit to grant me de crown. My council accepts me. My priests have given their blessing. My people have expressed their displeasure, but I am determined to right those wrongs. It is time to accept de responsibility of leadership. I will address them and speak on our future. I would be honored if you would take a place at my side while I do so.",objectivesText="Witness Talanji's ascension to Queen of the Zandalari.",rewardGold=156400,rewardXP=2735,starts={{npcID=145359}},ends={{npcID=146335}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={54034},questLines={{id=919,name="Allies of the Horde: Zandalari",orderIndex=15,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[53831] = {id=53831,name="A Royal Occasion",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=1637,mapID=85,storyline={53719,53823,53824,53825,53826,53827,53828,53830,53831,54031,54032,54033,54034,54300,54301,54419,54925},series={53823},description="You wish to hear how the Zandalari joined the Horde? My people have had a... difficult history with the Zandalari. However, I believe we dealt with the Zandalari of the past. The now Queen Talanji is much different from her father. I'm rambling, my apologies. Our tale begins after the Alliance sacked the city of Zuldazar and killed King Rastakhan. The Horde had been invited by the then Princess Talanji to witness her coronation in Zuldazar...",objectivesText="Meet the Zandalari emissary at The Great Seal in Dazar'alor.",rewardGold=84900,rewardXP=2735,starts={{npcID=133519},{npcID=133523}},ends={{npcID=145414}},mapCandidates={npc={85,1165},zone={1637}},questType="standard",sourceQuests={50242},questLines={{id=919,name="Allies of the Horde: Zandalari",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[53832] = {id=53832,name="Counter-Sabotage",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={53832},objectivesText="Pick up Hide-No-More 2000 Alliance saboteurs slain",rewardXP=2125,mapCandidates={npc={},zone={8567}},questType="standard",db2Objectives={{text="Pick up Hide-No-More 2000",amount=1,type=0,objectID=145355,orderIndex=0},{text="Alliance saboteurs slain",amount=6,type=0,objectID=145410,orderIndex=1}},worldTaskTitle="Counter-Sabotage",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[53833] = {id=53833,name="Vengeful Venture",level=50,requiredLevel=50,faction="horde",requiredProfessions={"engineering"},categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=1165,storyline={53783,53802,53806,53833,53848,53937,54930,55031},description="<You pick up the note and deduce that the Venture Co. are the killers of Dataguru Gryzix. You search his corpse, and find that his decoder and the Ub3r-Spanner schematic have been stolen. You need to retrieve his decoder and the schematic and bring them back to Shuga Blastcaps to have any hope of crafting the Ub3r-Spanner. That mech you have following you should prove itself useful.>",objectivesText="Locate the Venture Co. camp, then retrieve Gryzix's Decoder and the Encrypted Ub3r-Spanner schematic . Progress: What's up, <name>? Did Gryzix handle that schematic for you?",rewardGold=468000,rewardXP=8520,rewardItems={164740,164773,164919,166886},ends={{npcID=131840}},startObjects={{objectID=307748,mapID=864,x=0.263,y=0.473}},coords={mapID=1165,source="quest_giver",x=0.45,y=0.405},mapCandidates={npc={1165},zone={8501}},questType="standard",sourceQuests={53848},questLines={{id=868,name="Tools of the Trade: The Ub3r-Spanner",orderIndex=6,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[53835] = {id=53835,name="Something Valuable, Perhaps?",level=50,requiredLevel=50,faction="alliance",requiredRaces={3},categories={},flags={},sharable=true,expansion=7,zoneID=1,mapID=48,storyline={53835,53836,53837,53838,53839,53840,53841,53842,53844,53845,53846},description="<The tablet is too worn to be read. While some of the characters are legible, reading the tablet will be impossible without assistance. You can discern only a single word: Aegrim.>",objectivesText="Bring the tablet to Brann Bronzebeard in the Hall of Explorers in Ironforge.",rewardGold=23400,rewardXP=850,rewardItems={48933,164946,164960},ends={{npcID=145462}},startObjects={{objectID=311155,mapID=31,x=0.408,y=0.21}},coords={mapID=48,source="quest_giver",x=0.35,y=0.488},mapCandidates={npc={48},zone={1}},questType="standard",sourceQuests={53838},questLines={{id=804,name="Dwarven Heritage Armor",orderIndex=1,flags=0}},db2PoiUiMapID=87,db2QuestSortName="Epic"},
[53836] = {id=53836,name="Ancient Armor, Ancient Mystery",level=50,requiredLevel=50,faction="alliance",requiredRaces={3},categories={},flags={},sharable=true,expansion=7,zoneID=8161,mapID=48,storyline={53835,53836,53837,53838,53839,53840,53841,53842,53844,53845,53846},description="By my beard! Do you know what this is?! It's an ancient tablet that describes how to forge the Bulwark of the Mountain King! The last one to wear that armor was Aegrim Bronzebeard, my ancestor and thane of the Bronzebeard clan. Talk to Advisor Belgrum . He'll know more about Aegrim's past, and might be able to shine some light on the legends of his armor.",objectivesText="Speak to Advisor Belgrum in Old Ironforge.",rewardGold=23400,rewardXP=850,rewardItems={48933,164946,164960},starts={{npcID=145462}},ends={{npcID=145462}},mapCandidates={npc={48},zone={8161}},questTurnInID=145462,questType="standard",sourceQuests={53835},questLines={{id=804,name="Dwarven Heritage Armor",orderIndex=2,flags=0}},db2PoiUiMapID=1361},
[53837] = {id=53837,name="Watch Yer Back",level=50,requiredLevel=50,faction="alliance",requiredRaces={3},categories={},flags={},sharable=true,expansion=7,mapID=1361,storyline={53835,53836,53837,53838,53839,53840,53841,53842,53844,53845,53846},description="Aegrim, you say? Bulwark of the Mountain King? Well, if we are going to start anywhere, it has to be Aegrim's study. The entrance lies below us in the depths of Old Ironforge. The only trouble is the troggs in our way. How about you take the lead?",objectivesText="Kill 8 Trogg Invaders and Roc'maw the Burrower in Old Ironforge.",rewardGold=309800,rewardXP=6815,rewardItems={48933,164946,164960},starts={{npcID=145464}},ends={{npcID=145464}},mapCandidates={npc={},zone={}},questGiverID=145464,questTurnInID=145464,questType="standard",sourceQuests={53836},questLines={{id=804,name="Dwarven Heritage Armor",orderIndex=3,flags=0}},db2PoiUiMapID=1361},
[53838] = {id=53838,name="Keep Yer Feet On The Ground",level=50,requiredLevel=50,faction="alliance",requiredRaces={3},categories={"campaign"},flags={"important"},sharable=true,expansion=7,zoneID=1519,mapID=84,storyline={53835,53836,53837,53838,53839,53840,53841,53842,53844,53845,53846},description="<name>! The Explorers League is setting up a new exhibit in the Hall of Explorer. A team of dwarves went in search of new artifacts to display in it. They headed off to Gol'Bolar Quarry in Dun Morogh, but haven't returned. Would you mind checking in on them?",objectivesText="Search Gol'Bolar Quarry for the missing excavation crew.",rewardGold=341600,rewardXP=6815,rewardItems={48933,164946,164960,170063,174077,203176,208476,210054,218105,218118,218119,242520},starts={{npcID=146988}},ends={{npcID=146988}},mapCandidates={npc={84},zone={1519}},questTurnInID=146988,questType="standard",questLines={{id=804,name="Dwarven Heritage Armor",orderIndex=0,flags=0}},db2PoiUiMapID=31},
[53839] = {id=53839,name="Aegrim's Study",level=50,requiredLevel=50,faction="alliance",requiredRaces={3},categories={},flags={},sharable=true,expansion=7,zoneID=1537,mapID=1361,storyline={53835,53836,53837,53838,53839,53840,53841,53842,53844,53845,53846},description="This leads to Aegrim's study. I still have some scrolls to sort, so I will leave you to search the study at your leisure. I'm sure Brann would be most interested in any of your findings.",objectivesText="Search Aegrim's study for the Bulwark of the Mountain King.",rewardGold=23400,rewardXP=850,rewardItems={48933,164946,164960},starts={{npcID=145707}},ends={{npcID=145707}},mapCandidates={npc={},zone={1537}},questGiverID=145707,questTurnInID=145707,questType="standard",sourceQuests={53837},questLines={{id=804,name="Dwarven Heritage Armor",orderIndex=4,flags=0}},db2PoiUiMapID=1361},
[53840] = {id=53840,name="Interest Yah In A Pint?",level=50,requiredLevel=50,faction="alliance",requiredRaces={3},categories={},flags={},sharable=true,expansion=7,zoneID=38,mapID=48,storyline={53835,53836,53837,53838,53839,53840,53841,53842,53844,53845,53846},description="The armor may be shattered, but there's still hope. With the fragments you found, we might be able to forge it anew. This is far outside my area of expertise, but there may be someone who can help. We should speak with Grumnus Steelshaper . He retired to Thelsamar in Loch Modan. Go on ahead, I'll meet you there.",objectivesText="Find Grumnus Steelshaper in Loch Modan.",rewardGold=31200,rewardXP=850,rewardItems={48933,164946,164960},starts={{npcID=145462}},ends={{npcID=5164}},mapCandidates={npc={48},zone={38}},questType="standard",sourceQuests={53841},questLines={{id=804,name="Dwarven Heritage Armor",orderIndex=6,flags=0}},db2PoiUiMapID=48},
[53841] = {id=53841,name="Shards of the Past",level=50,requiredLevel=50,faction="alliance",requiredRaces={3},categories={},flags={},sharable=true,expansion=7,zoneID=1537,mapID=48,storyline={53835,53836,53837,53838,53839,53840,53841,53842,53844,53845,53846},description="<The armor that once was here has mysteriously shattered. Pieces of the ancient armor are scattered around the room.>",objectivesText="Collect the shattered pieces of armor. Progress: What do ye have here?",rewardGold=234000,rewardXP=6815,rewardItems={48933,164946,164960},ends={{npcID=145462}},startObjects={{objectID=309498,mapID=87,x=0.198,y=0.519}},coords={mapID=48,source="quest_giver",x=0.35,y=0.488},mapCandidates={npc={48},zone={1537}},questType="standard",sourceQuests={53839},questLines={{id=804,name="Dwarven Heritage Armor",orderIndex=5,flags=0}},db2PoiUiMapID=87},
[53842] = {id=53842,name="Earthen Blessing",level=50,requiredLevel=50,faction="alliance",requiredRaces={3},categories={},flags={},sharable=true,expansion=7,zoneID=38,mapID=48,storyline={53835,53836,53837,53838,53839,53840,53841,53842,53844,53845,53846},description="Ignis will help with smelting the metal, but the heat from the forge will cook you in yer boots! Our ancestors, the dwarves who forged Aegrim's armor, could sustain their stoneform for far longer than we can today. That's how they could forge the bulwark in the first place. Luckily, my friend Bouldercrag can help us with that. He'll need some materials for the ritual.",objectivesText="Find the Remnant of the Earthen Ritual in Old Ironforge. Progress: Do you have it?",rewardGold=234000,rewardXP=6815,rewardItems={48933,164946,164960},starts={{npcID=145462}},ends={{npcID=145866}},mapCandidates={npc={48},zone={38}},questType="standard",sourceQuests={53844},questLines={{id=804,name="Dwarven Heritage Armor",orderIndex=8,flags=0}},db2PoiUiMapID=87},
[53844] = {id=53844,name="Recruiting the Furnace Master",level=50,requiredLevel=50,faction="alliance",requiredRaces={3},categories={},flags={},sharable=true,expansion=7,zoneID=8161,mapID=48,storyline={53835,53836,53837,53838,53839,53840,53841,53842,53844,53845,53846},description="Grumnus says we're going to need some help smelting this metal. I just happen to know someone who's perfect for the job. We're heading to Ulduar! Years ago, we fought against a construct named Ignis the Furnace Master. I've heard tell that the titan keepers brought him back, and Ulduar's furnace is alive once more.",objectivesText="Recruit Ignis the Furnace Master to help smelt the metal. Progress: It's been a long time since I've been in Ulduar.",rewardGold=341600,rewardXP=6815,rewardItems={48933,164946,164960},starts={{npcID=145462}},ends={{npcID=145462}},mapCandidates={npc={48},zone={8161}},questType="standard",sourceQuests={53840},questLines={{id=804,name="Dwarven Heritage Armor",orderIndex=7,flags=0}},db2PoiUiMapID=48},
[53845] = {id=53845,name="Forging the Armor",level=50,requiredLevel=50,faction="alliance",requiredRaces={3},categories={},flags={},sharable=true,expansion=7,zoneID=1537,mapID=48,storyline={53835,53836,53837,53838,53839,53840,53841,53842,53844,53845,53846},description="It's time to begin. Bouldercrag, Ignis, and I are here to assist you. You'll be the first dwarf to forge the Bulwark of the Mountain King in generations. This ol' blacksmith is honored to be able to witness this. Are ye ready?",objectivesText="Forge the Bulwark of the Mountain King. Progress: Is it done?",rewardGold=309800,rewardXP=6815,rewardItems={48933,164946,164960,165704},starts={{npcID=5164}},ends={{npcID=5164}},mapCandidates={npc={48},zone={1537}},questType="standard",sourceQuests={53842},questLines={{id=804,name="Dwarven Heritage Armor",orderIndex=9,flags=0}},db2PoiUiMapID=87},
[53846] = {id=53846,name="Legacy of the Bronzebeard",level=50,requiredLevel=50,faction="alliance",requiredRaces={3},categories={},flags={},sharable=true,expansion=7,zoneID=1537,mapID=48,storyline={53835,53836,53837,53838,53839,53840,53841,53842,53844,53845,53846},description="You must present this armor to Muradin at once! This is an historic day for the dwarven people. This isn't just a suit of armor, it's a symbol of our heritage.",objectivesText="Present the Bulwark of the Mountain King to Muradin Bronzebeard in the High Seat.",rewardGold=702000,rewardXP=10225,rewardItems={48933,164946,164960,224449},starts={{npcID=145462}},ends={{npcID=42928}},mapCandidates={npc={48,87},zone={1537}},questType="standard",sourceQuests={53845},questLines={{id=804,name="Dwarven Heritage Armor",orderIndex=10,flags=0}},db2PoiUiMapID=87},
[53847] = {id=53847,name="On Whispered Winds",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={53847,53849,53988,53989,53990,53992,54006,54041,54871},description="<name>, I have need of you. Maiev and Shandris are en route to Stormwind to petition King Wrynn for aid in retaking Darkshore. You have proven a loyal ally to my people in times past. I ask that you join their audience with the king and lend your voice to our cause. I suspect we shall meet again soon. -Tyrande",objectivesText="Meet Maiev Shadowsong and Shandris Feathermoon in Stormwind Keep.",rewardGold=23400,rewardXP=850,rewardItems={165232,165233,165250},starts={{npcID=152000}},ends={{npcID=146050}},mapCandidates={npc={84,1161},zone={8568}},questType="standard",questLines={{id=797,name="In Darkest Night",orderIndex=0,flags=0}},db2PoiUiMapID=84},
[53848] = {id=53848,name="Tooling Around Vol'dun",level=50,requiredLevel=50,faction="both",requiredProfessions={"engineering"},categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={53802,53806,53848,53947,53948,53949,54930,55028},description="Okay, <name>. We got almost everything we need. Almost. You see, I lost my toolbox. I must have dropped it while running from the sethrak a couple days ago. Can ya fetch it for me? I'm not a very good engineer without my tools! And take a mech with ya. I've spied some mysterious dwarven and troll figures lurking around... better not be the Venture Co. One whiff of the schematic being here and we got trouble. You'll need the mind enhancer for it to follow you. Just put it on and you'll be good to go!",objectivesText="Put on the Goblin \"Mind Enhancer,\" then retrieve Gryzix's toolbox . Progress: <Gryzix appears to be dead.>",rewardGold=234000,rewardXP=6815,rewardItems={164740,166881},starts={{npcID=145131}},ends={{npcID=145279}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={53802,53806,54930},questLines={{id=868,name="Tools of the Trade: The Ub3r-Spanner",orderIndex=5,flags=0},{id=869,name="Tools of the Trade: The Ub3r-Spanner",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[53849] = {id=53849,name="Waning Hope",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=1519,mapID=84,storyline={53847,53849,53988,53989,53990,53992,54006,54041,54871},description="The kaldorei have been steadfast members of the Alliance since the end of the Third War. We have fought on distant shores and even on different worlds without protest. It is curious that in our moment of need, their resources are stretched too thin to lend so much as a single blade. Wrynn has already denied Tyrande aid. Witness it for yourself.",objectivesText="View Tyrande's audience with Anduin Wrynn. Progress: This will not stand.",rewardGold=117000,rewardXP=3410,rewardItems={165232,165233,165250},starts={{npcID=146050}},ends={{npcID=146050}},mapCandidates={npc={84},zone={1519}},questType="standard",sourceQuests={53847},questLines={{id=797,name="In Darkest Night",orderIndex=1,flags=0}},db2PoiUiMapID=84},
[53850] = {id=53850,name="Our War Continues",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=1637,mapID=85,storyline={53850},description="The work to stop the Alliance is far from over, <name>. But thanks to you, we have the methods necessary to break them. The Abyssal Scepter has been delivered to King Rastakhan, earning us more of his favor. There is a matter of greater importance that I would speak to you about... but not here. Meet me aboard the Banshee's Wail within Zuldazar.",objectivesText="Speak with Sylvanas Windrunner aboard the Banshee's Wail in Zuldazar.",rewardGold=23400,rewardXP=850,rewardItems={164778},starts={{npcID=134711}},ends={{npcID=135691}},mapCandidates={npc={85,862},zone={1637}},questType="standard",sourceQuests={53003}},
[53851] = {id=53851,name="Our War Continues",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={53851,53852,53856,53879,53880,53912,53913,53973,53981},description="The work to stop the Alliance is far from over, <name>. King Rastakhan now possesses the Abyssal Scepter that you recovered from the Kul Tirans. He has placed it... in his treasury. The Dark Lady wishes to speak with you regarding the corpse you found at the bottom of the ocean. Derek Proudmoore.",objectivesText="Speak with Sylvanas Windrunner aboard the Banshee's Wail.",rewardGold=23400,rewardXP=850,rewardItems={164778,164987,165702,165734,166309},starts={{npcID=135691}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={53003},questLines={{id=838,name="Norwington Assault",orderIndex=0,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=838,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=838,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[53852] = {id=53852,name="Azerite Denied",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={53851,53852,53856,53879,53880,53912,53913,53973,53981},description="The Kul Tirans and Alliance are amassing a vast amount of their Azerite and Azerite weapons within Tiragarde Sound. They have a new supply of the resource, thanks to the Kul Tirans' conquest over Lady Ashvane and her company. We must strike at their supplies of Azerite and destroy these weapons, or else we will be behind in this war. You and Zelling will travel to Tiragarde Sound and meet with Rexxar . Lead the assault on their Azerite supply. And do not return until you are victorious.",objectivesText="Meet Rexxar in Tiragarde Sound.",rewardGold=23400,rewardXP=850,rewardItems={164778,164987,165702,165734,166309},starts={{npcID=135691}},ends={{npcID=145422}},mapCandidates={npc={862,895},zone={8499}},questType="standard",sourceQuests={53850,53851},questLines={{id=838,name="Norwington Assault",orderIndex=1,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=838,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=838,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53853] = {id=53853,name="The Setting Sun",level=50,requiredLevel=50,faction="horde",requiredRaces={10},categories={},flags={},sharable=true,expansion=7,zoneID=4080,mapID=110,storyline={53725,53734,53735,53736,53737,53738,53791,53853,53882,54096},description="Remember the Sunwell. We ride into battle with those words for a reason. We lost so much that day... I lost so much that day. Shine the lantern on the southern side of the island, where the Dead Scar meets the sea. There you will see how the fall of the Sunwell began. And with it, the last act of the High Elves.",objectivesText="Witness the fall of Anasterian. Progress: Is it done, champion?",rewardGold=468000,rewardXP=8520,rewardItems={5232,19004,166896,194885},starts={{npcID=145793}},ends={{npcID=145793}},mapCandidates={npc={110},zone={4080}},questType="standard",sourceQuests={53725},questLines={{id=811,name="Blood Elf Heritage Armor",orderIndex=7,flags=0}},db2PoiMapID=530,db2PoiUiMapID=122},
[53856] = {id=53856,name="The Fury of the Horde",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53851,53852,53856,53879,53880,53912,53913,53973,53981},description="The Norwington Estate has a large cache of Azerite, along with the Alliance's latest Azerite weapons. We need to steal these weapons and all of their Azerite. Every weapon stolen is a Horde life saved. When you are ready to strike, let me know. I shall signal our warriors to begin the assault. The Alliance and Kul Tirans will see the true might of the Horde!",objectivesText="Command the Horde army to attack Norwington Manor. Progress: The Alliance will see our might.",rewardGold=23400,rewardXP=850,rewardItems={164778,164987,165702,165734,166309},starts={{npcID=145422}},ends={{npcID=145422}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={53852},questLines={{id=838,name="Norwington Assault",orderIndex=2,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=838,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=838,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53857] = {id=53857,name="Cap'n Gorok",level=10,requiredLevel=10,faction="alliance",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={53857},rewardXP=2125,starts={{npcID=145415,mapID=942,x=0.376,y=0.4759}},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=145415}},worldTaskTitle="Cap'n Gorok",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3446,db2VignetteName="Cap'n Gorok"},
[53858] = {id=53858,name="Step Into Her Shoes",level=50,requiredLevel=50,faction="both",requiredProfessions={"tailoring"},categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=115,storyline={53810,53813,53858,53866,53868,53869,55214},series={53866,55214},description="Another one of those rifts. Normally I'd repair it, but given the circumstances I wish to see where it leads. It isn't often I commune with versions of myself from other threads of time. But one particular self has been a dear friend for some time. I feel myself growing weaker. If she perishes... We don't have much time. We need to enter this rift now.",objectivesText="Enter the Time Rift with Timeweaver Delormi . Progress: We must hurry--I fear the worst, otherwise.",rewardGold=23400,rewardXP=850,rewardItems={152576,152668,159959,164733,168029,168128,168129,168130,168131},starts={{npcID=151134}},ends={{npcID=151134}},mapCandidates={npc={115},zone={9042}},questType="standard",sourceQuests={53810,53813},questLines={{id=906,name="8.1.5 Tailoring - Alliance/Horde",orderIndex=2,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=680},
[53859] = {id=53859,name="The Mountain Folk",level=10,requiredLevel=10,faction="alliance",categories={"seasonal"},flags={},sharable=false,event="Children's Week",expansion=7,storyline={53859},description="All Kul Tirans are really tough, but the Roughnecks are the roughest and toughest of them all! They can wrestle gryphons with their bare hands! They can knock down a yeti with a single punch! I wanna meet a Roughneck and prove that I can be really strong like them! Can you take me to their camp? I've heard it's up in the mountains by Anglepoint.",objectivesText="Take Liam to meet the Roughnecks at the Roughneck Camp in Tiragarde Sound. Make sure to call for him if he is not present when you get there. Progress: I'm gonna be big and strong and eat raw goat with my teeth!",rewardItems={23022,116202,164772,167008,167009,167010,167011},starts={{npcID=145394}},mapCandidates={npc={},zone={}},questGiverID=145394,questType="standard",sourceQuests={53811},packageItems={241215}},
[53860] = {id=53860,name="Azerite Transport (NOT USED)",expansion=7,mapID=895,questType="world",db2Objectives={{orderIndex=0,type=2,amount=1,objectID=307511,text="Azerite shipment secured"}},worldTaskTitle="Azerite Transport (NOT USED)",db2QuestInfoID=113,db2QuestInfoName="PvP World Quest"},
[53861] = {id=53861,name="Yo Ho, Yo Ho!",level=10,requiredLevel=10,faction="alliance",categories={"seasonal"},flags={},sharable=false,event="Children's Week",expansion=7,storyline={53861},description="The orphan matron is always telling us what to do! Study your books, practice your words, behave in public... What if I want to be a pirate when I grow up? A scourge of the high seas! Finding buried treasure, dueling my enemies on the mast, wearing cool hats! Pirates never come into Boralus, so I've only ever heard stories. I wanna meet a real one! Can you take me to Freehold? I'll practice my pirate voice on the way. YARRRRR!",objectivesText="Take Liam to meet a pirate outside of Freehold in Tiragarde Sound. Make sure to call for him if he is not present when you get there. Progress: Yo ho, yo ho!",rewardItems={23022,116202,164772,167008,167009,167010,167011},starts={{npcID=145394}},mapCandidates={npc={},zone={}},questGiverID=145394,questType="standard",sourceQuests={53811},packageItems={241215}},
[53862] = {id=53862,name="The Squid Shrine",level=10,requiredLevel=10,faction="alliance",categories={"seasonal"},flags={},sharable=false,event="Children's Week",expansion=7,storyline={53862},description="Sometimes tidesages come to the orphanage and tell us about the sea and how they can talk to it. I wanna talk to water! We've gone on field trips to their monastery here in Boralus, but I heard their home in Stormsong is much more impressive. Can you take me to go see it? I heard there's a great view from the Brineworks!",objectivesText="Take Liam to see Shrine of the Storms from the beach near Mariner's Strand in Stormsong Valley. Make sure to call for him if he is not present when you get there. Progress: The tidesages always say that the water talks to them. How does it talk without a mouth?",rewardItems={23022,116202,164772,167008,167009,167010,167011},starts={{npcID=145394}},mapCandidates={npc={},zone={}},questGiverID=145394,questType="standard",sourceQuests={53811},packageItems={241215}},
[53863] = {id=53863,name="Bird Friends",level=10,requiredLevel=10,faction="alliance",categories={"seasonal"},flags={},sharable=false,event="Children's Week",expansion=7,storyline={53863},description="My best friend at the orphanage is named Billy. He's just a kid like me, though. I heard that some people in Drustvar have FALCONS as their best friend. How cool is that?! Can we go meet a falconer? Pretty please? I want to have a bird friend too. I hear there's a big statue in Arom's Stand of some dead guy who was friends with birds. Maybe we can find a falconer there!",objectivesText="Take Liam to see the statue of Arom Waycrest at Arom's Stand in Drustvar. Make sure to call for him if he is not present when you get there. Progress: I wish I had feathers like a bird!",rewardItems={23022,116202,164772,167008,167009,167010,167011},starts={{npcID=145394}},mapCandidates={npc={},zone={}},questGiverID=145394,questType="standard",sourceQuests={53859,53861,53862},packageItems={241215}},
[53864] = {id=53864,name="Shapeshifters!",level=10,requiredLevel=10,faction="alliance",categories={"seasonal"},flags={},sharable=false,event="Children's Week",expansion=7,storyline={53864},description="Being a human is alright and all, but what if I could be a BEAR? Druids can be bears. And cats! And who knows what else! I've heard rumors of druids in the mountains of Drustvar. It would be so cool to meet one. I wanna see them turn into animals! Maybe they can teach me, too!",objectivesText="Take Liam to meet a druid at Ulfar's Den in Drustvar. Make sure to call for him if he is not present when you get there. Progress: Roar! Growl! Bear sounds!",rewardItems={23022,116202,164772,167008,167009,167010,167011},starts={{npcID=145394}},mapCandidates={npc={},zone={}},questGiverID=145394,questType="standard",sourceQuests={53859,53861,53862},packageItems={241215}},
[53865] = {id=53865,name="Return to the Orphanage",level=10,requiredLevel=10,faction="alliance",categories={"seasonal"},flags={},sharable=false,event="Children's Week",expansion=7,storyline={53865},description="This has been the best Children's Week ever! I was scared to grow up, but now I'm really excited! There are so many cool things I can be! But how can I choose? I think it's time for you to take me back to the orphanage , <name>. I'll think about what I want to be when I grow up on the way.",objectivesText="Bring Liam back to the orphanage in Boralus. Make sure to call for him if he is not present when you get there. Progress: What a great trip!",rewardItems={23022,116202,164772,167008,167009,167010,167011,241215},starts={{npcID=145291},{npcID=150098},{npcID=150126},{npcID=150119},{npcID=150120}},ends={{npcID=145291}},mapCandidates={npc={},zone={}},questGiverID=145291,questTurnInID=145291,questType="standard",sourceQuests={53863,53864}},
[53866] = {id=53866,name="If The Shoe Fits...",level=50,requiredLevel=50,faction="both",requiredProfessions={"tailoring"},categories={},flags={},sharable=true,expansion=7,zoneID=7637,mapID=115,storyline={53810,53813,53858,53866,53868,53869,55214},series={53858,55214},description="That thing is killing her...it's killing *me*! We need to stop it! Please, I need your help to save my self!",objectivesText="Stop the Shade of Delormi from killing Magistrix Delormi . Progress: Please, we need your help!",rewardGold=234000,rewardXP=6815,rewardItems={152576,152668,159959,164733,168029,168128,168129,168130,168131},starts={{npcID=151134}},ends={{npcID=151134}},mapCandidates={npc={115},zone={7637}},questType="standard",sourceQuests={53858},questLines={{id=906,name="8.1.5 Tailoring - Alliance/Horde",orderIndex=3,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=680},
[53867] = {id=53867,name="Engineer Bolthold",level=10,requiredLevel=10,faction="alliance",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={53867},rewardXP=2125,starts={{npcID=145465,mapID=896,x=0.286,y=0.432}},mapCandidates={npc={},zone={8721}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=145465}},worldTaskTitle="Engineer Bolthold",db2PoiMapID=1643,db2PoiUiMapID=896,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3456,db2VignetteName="Engineer Bolthold"},
[53868] = {id=53868,name="Saving Nine",level=50,requiredLevel=50,faction="both",requiredProfessions={"tailoring"},categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=115,storyline={53810,53813,53858,53866,53868,53869,55214},series={53869},description="I saw her in there, destroying another part of my timeline. With every thread she severs, I lose myself more and more... Perhaps I will perish, but I won't let her ruin the fabric of time. I need you to join me one last time. I can only end this with your support.",objectivesText="Enter the Time Rift. Progress: We can't fail. Not with what's at stake.",rewardGold=23400,rewardXP=850,rewardItems={152576,152668,159959,164733,168029,168128,168129,168130,168131},starts={{npcID=151134}},ends={{npcID=151134}},mapCandidates={npc={115},zone={9042}},questType="standard",sourceQuests={55214},questLines={{id=906,name="8.1.5 Tailoring - Alliance/Horde",orderIndex=5,flags=0}},db2PoiMapID=571,db2PoiUiMapID=115},
[53869] = {id=53869,name="Killing Time",level=50,requiredLevel=50,faction="both",requiredProfessions={"tailoring"},categories={},flags={},sharable=true,expansion=7,zoneID=65,mapID=115,storyline={53810,53813,53858,53866,53868,53869,55214},series={53868},description="Now, <name>, stand with me. I am weak. So many threads have been severed. I'll use what power I have left to mend the rift. Please...make sure the fabric of time is safe from her.",objectivesText="Kill the Infinite Shade of Delormi . Progress: Please...I need your help!",rewardGold=468000,rewardXP=8520,rewardItems={152576,152668,159959,164733,168029,168128,168129,168130,168131},starts={{npcID=151134}},ends={{npcID=151134}},mapCandidates={npc={115},zone={65}},questType="standard",sourceQuests={53868},questLines={{id=906,name="8.1.5 Tailoring - Alliance/Horde",orderIndex=6,flags=0}},db2PoiMapID=571,db2PoiUiMapID=115},
[53870] = {id=53870,name="Guests at Grommash Hold",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=1637,mapID=85,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="$p, I've received word that a vulpera caravan has arrived at Grommash Hold. They wish to address the Horde and have requested your presence. I'm afraid it is not the best time for guests, so please see them as soon as you are able.",objectivesText="Meet your guests within Grommash Hold.",rewardGold=30900,rewardXP=685,rewardItems={173727,174066},starts={{npcID=133523}},ends={{npcID=145416}},mapCandidates={npc={85},zone={1637}},questType="standard",sourceQuests={50242},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=0,flags=0}},db2PoiMapID=1,db2PoiUiMapID=85},
