[53875] = {id=53875,name="Fogsail for a Day",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={53875},objectivesText="Talk to Boatswain Mace Alliance supply chain disrupted Banner - Pick Up Banner - Use Banner - Buff Pirate Destroy Supplies Free Prisoner",rewardXP=2125,mapCandidates={npc={},zone={8567}},questType="standard",db2Objectives={{text="Talk to Boatswain Mace",amount=1,type=0,objectID=146293,orderIndex=0},{text="Alliance supply chain disrupted",amount=1,type=15,objectID=0,orderIndex=1},{text="Banner - Pick Up",amount=20,type=0,objectID=145534,orderIndex=2},{text="Banner - Use",amount=34,type=0,objectID=146393,orderIndex=3},{text="Banner - Buff Pirate",amount=50,type=0,objectID=146395,orderIndex=4},{text="Destroy Supplies",amount=10,type=0,objectID=147482,orderIndex=5},{text="Free Prisoner",amount=20,type=0,objectID=147525,orderIndex=6}},worldTaskTitle="Fogsail for a Day",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[53877] = {id=53877,name="Eastpoint Encounter",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={53877},objectivesText="Horde soldiers slain",rewardXP=2125,mapCandidates={npc={},zone={8500}},questType="standard",db2Objectives={{text="Horde soldiers slain",amount=12,type=0,objectID=144958,orderIndex=0}},worldTaskTitle="Eastpoint Encounter",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[53878] = {id=53878,name="Emergency Extrication",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={53878},objectivesText="Wounded Grunts bandaged Alliance soldiers slain",rewardXP=2125,mapCandidates={npc={},zone={8500}},questType="standard",db2Objectives={{text="Wounded Grunts bandaged",amount=6,type=0,objectID=144911,orderIndex=0},{text="Alliance soldiers slain",amount=8,type=0,objectID=144959,orderIndex=1}},worldTaskTitle="Emergency Extrication",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[53879] = {id=53879,name="Cleaning Out the Estate",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53851,53852,53856,53879,53880,53912,53913,53973,53981},description="We must keep moving forward. Our goal is to weaken the Alliance, destroy their weapons, and steal their Azerite . The three of us will carve a path of destruction through our enemies. Let us go!",objectivesText="Weaken the Norwington Estate defenders. Progress: Do not give in to the Alliance!",rewardGold=234000,rewardXP=6815,rewardItems={164987,165702,165734,166309},rewardCurrencies={{id=1553,amount=250}},starts={{npcID=145422}},ends={{npcID=145422}},mapCandidates={npc={895},zone={8567}},questTurnInID=145422,questType="standard",sourceQuests={53856},questLines={{id=838,name="Norwington Assault",orderIndex=3,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=838,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=838,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53880] = {id=53880,name="Machines of War and Azerite",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53851,53852,53856,53879,53880,53912,53913,53973,53981},description="The Norwington Estate... I remember taking walks here with my wife and children. Sorry, this isn't the time for remembering an old life. The Alliance have Azerite bombs and rifles scattered throughout the estate. I believe our goal is to recover them. If only the Alliance hadn't chosen to use the estate as a testing ground... this was meant to be a place of peace.",objectivesText="Recover 4 Azerite bombs and 3 Azerite rifles . Progress: Is it done?",rewardGold=234000,rewardXP=6815,rewardItems={164778,164917,164987,165225,165702,165734,166309},starts={{npcID=145423}},ends={{npcID=145423}},mapCandidates={npc={895},zone={8567}},questTurnInID=145423,questType="standard",sourceQuests={53856},questLines={{id=838,name="Norwington Assault",orderIndex=4,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=838,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=838,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53881] = {id=53881,name="Cut from the Same Cloth",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"tailoring"},categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=115,storyline={53805,53807,53881,55177},description="My Infinite self was right. I can no longer mend time. Too many of my threads have been purged. I can feel no others. I'm alone now. And my thread is gone. But not you. Take this recipe. You've proven yourself a talented tailor in your own time, and a savior in so many more. The fabric of time needs your hands to mend it. I trust you with that responsibility. Talk to me when you're ready. I'll take you back to when this all began.",objectivesText="Ask Timeweaver Delormi to return you to your time.",rewardGold=23400,rewardXP=850,rewardItems={152576,152668,159959,164733,168029,168128,168129,168130,168131},starts={{npcID=151134}},ends={{npcID=151134}},mapCandidates={npc={115},zone={9042}},questTurnInID=151134,questType="standard",sourceQuests={53869},questLines={{id=904,name="8.1.5 Tailoring - Alliance",orderIndex=3,flags=0}},db2PoiMapID=571,db2PoiUiMapID=115},
[53882] = {id=53882,name="Writing on the Wall",level=50,requiredLevel=50,faction="both",requiredRaces={4,10,28},categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=3433,mapID=95,storyline={53725,53734,53735,53736,53737,53738,53791,53853,53882,54096},description="Long has the southern wall separated Quel'Thalas from the once great kingdom of Lordaeron. We did not believe that anyone could breach it. That overconfidence was our undoing. When the Scourge arrived, the gate was not conquered by force. It was willingly opened by a traitor. Though caught unaware, every Farstrider, soldier, and magister in the area rushed to the defense of our homeland. Very few of them returned home. The gates now stand as a memorial in their name.",objectivesText="Light the first memorial's flame. Progress: Take the time you need.",rewardGold=341600,rewardXP=850,rewardItems={166896},starts={{npcID=145015}},ends={{npcID=145015}},mapCandidates={npc={95},zone={3433}},questTurnInID=145015,questType="standard",sourceQuests={53734},questLines={{id=811,name="Blood Elf Heritage Armor",orderIndex=2,flags=0},{id=5697,name="Lorewalking: Elves",orderIndex=1,flags=0}},campaigns={{id=274,title="Lorewalking:Elves",questLineID=5697,questLineOrder=0}},db2PoiMapID=530,db2PoiUiMapID=95},
[53883] = {id=53883,name="Shores of Zuldazar",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={53883},description="Alliance forces are attacking Zuldazar. Make them regret every step taken on our soil!",objectivesText="Repel the Alliance forces assaulting Zuldazar. Progress: The Alliance dares to assault us in Zuldazar?! We must crush these fools so cruelly and so swiftly that they never consider this again.",rewardXP=2125,rewardItems={152813,165871,166792,168419},rewardCurrencies={{id=1716,amount=5}},starts={{npcID=135447}},ends={{npcID=135447}},mapCandidates={npc={862},zone={8499}},questGiverID=135447,questType="standard"},
[53885] = {id=53885,name="Isolated Victory",level=10,requiredLevel=10,faction="horde",categories={},flags={"loremaster"},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={53885},description="Alliance forces are pushing deeper into Vol'dun. We can not allow this aggression to go unchecked!",objectivesText="Repel the Alliance forces assaulting Vol'dun. Progress: The vulpera appreciate the Horde's protection here. I didn't realize the Alliance could be so... relentless.",rewardXP=2125,rewardItems={165871},rewardCurrencies={{id=1716,amount=5}},starts={{npcID=135804}},ends={{npcID=135804}},mapCandidates={npc={864},zone={8501}},questGiverID=135804,questType="standard"},
[53886] = {id=53886,name="Self Guided Tour",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={53886},objectivesText="Use the cargo rope to board the airship Nazmir Battleplans stolen Escape the airship",rewardXP=2125,rewardItems={165011},mapCandidates={npc={},zone={8500}},questType="standard",db2Objectives={{text="Use the cargo rope to board the airship",amount=1,type=2,objectID=307749,orderIndex=0},{text="Nazmir Battleplans stolen",amount=6,type=1,objectID=165011,orderIndex=3},{text="Escape the airship",amount=1,type=0,objectID=149628,orderIndex=4}},worldTaskTitle="Self Guided Tour",db2PoiMapID=1642,db2PoiUiMapID=863,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[53887] = {id=53887,name="War Marches On",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53887,53888,53896,53909,53910,53916,53919,53936,53978,53986,54518,54519,54559,54703,54787},description="I hope the Horde will think twice about attacking Kul Tiras in the future, but given the actions of its leadership, it is a faint hope at best. Still, what matters most is my people are safe now. The fleet and marines should be here soon to help the Outriggers clear out what remains of the Horde forces. Please return to High Commander Wyrmbane and let him know I will join everyone as soon as I am able. Thank you for your swift actions today, <name>.",objectivesText="Return to Halford Wyrmbane on the Wind's Redemption.",rewardGold=23400,rewardXP=1705,rewardItems={164921,164968,166280,166682,245271,252386,252400,252403,252406,252653,252654,252754},starts={{npcID=145580}},ends={{npcID=135612}},mapCandidates={npc={895,1161},zone={8567}},questType="standard",sourceQuests={54703},questLines={{id=843,name="Beware the Daughter of the Sea",orderIndex=14,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=843,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=843,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=1161},
[53888] = {id=53888,name="To Anglepoint",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53887,53888,53896,53909,53910,53916,53919,53936,53978,53986,54518,54519,54559,54703,54787},description="An attack on Anglepoint Wharf can only mean one thing: the Horde seeks to destroy the seagate there. This is my home. These are my people. I cannot turn my attention to our operations in Zandalar until we've routed the Horde. The military will take a little time to mobilize, but in the meantime you and I can face these monsters. If we can't stop them, we can slow them down. War has come to my shores once more. I will not stand aside.",objectivesText="Accompany Jaina Proudmoore to Anglepoint Wharf and assist her there. Progress: The Horde has overrun the area. We cannot let this continue.",rewardGold=117000,rewardXP=3410,rewardItems={164921,164968,166280,166682},starts={{npcID=145580}},ends={{npcID=145580}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={53986},questLines={{id=843,name="Beware the Daughter of the Sea",orderIndex=1,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=843,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=843,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53889] = {id=53889,name="A Declaration of Intent",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=1637,mapID=85,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="Our caravan is ready to explore the world beyond the sands, but Nisha's blade can't be our only defense against the dangers we know await us. This is why we've come. To declare our intent to join the Horde.",objectivesText="Witness Kiro 's declaration to join the Horde.",rewardGold=34100,rewardXP=685,rewardItems={173727,174066},starts={{npcID=145416}},ends={{npcID=145416}},mapCandidates={npc={85},zone={1637}},questType="standard",sourceQuests={53870},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=1,flags=0}},db2PoiMapID=1,db2PoiUiMapID=85},
[53890] = {id=53890,name="New Allies, New Problems",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=1637,mapID=85,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="Baine certainly has his hands full. Taking on new allies means taking on new problems. Let us find out what troubles those within the Horde and see what we can do to help. Perhaps when Baine isn't so overwhelmed, he'll be able see our true value.",objectivesText="Find out what troubles Commander Dresh , Bladeguard Sonji , and First Arcanist Thalyssra . Progress: Let us find out what troubles those within the Horde and see what we can do to help.",rewardGold=170800,rewardXP=2735,rewardItems={173727,174066},starts={{npcID=145416}},ends={{npcID=145416}},mapCandidates={npc={85},zone={1637}},questType="standard",sourceQuests={53889},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=2,flags=0}},db2PoiMapID=1,db2PoiUiMapID=85},
[53891] = {id=53891,name="No Problem Too Small",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=1637,mapID=85,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="These problems might seem small, but they will eat away at the Horde over time if they remain unaddressed. We must offer our help. The vulpera are skilled at solving problems, no matter their size. I will investigate the outpost. Nisha and Meerah will see to the others. Meet me in the Twilight Highlands when you're ready.",objectivesText="Meet Kiro in Twilight Highlands.",rewardGold=16980,rewardXP=685,rewardItems={173727,174066},starts={{npcID=145416}},ends={{npcID=163488}},mapCandidates={npc={85,241},zone={1637}},questType="standard",sourceQuests={53890},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=3,flags=0}},db2PoiUiMapID=241},
[53892] = {id=53892,name="Where Are the Workers?",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=4922,mapID=241,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="Look at this axe, $p. There's still sweat on the hilt. The workers were here not too long ago. Let's see if Sasha can track their scent.",objectivesText="Find out where the Crushblow Peons went. Progress: This must be the place.",rewardGold=170800,rewardXP=2735,rewardItems={173727,174066},starts={{npcID=163488}},ends={{npcID=145641}},mapCandidates={npc={241},zone={4922}},questType="standard",sourceQuests={53891},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=4,flags=0}},db2PoiUiMapID=241},
[53893] = {id=53893,name="A Little Goodwill",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=4922,mapID=241,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="It sounds like the peons are feeling undervalued. They do important work for the Horde, but their diligence is often overlooked. A little goodwill would go a long way. Let's plan a feast in their honor. We'll need quite a bit of meat to sate their enormous appetites, luckily, I have a totem that can help with that. You acquire the ingredients, and I will make a meal guaranteed to boost morale.",objectivesText="Collect 100 Saber Flanks , 100 Worg Meat , and 100 Clucker Tidbits . Progress: Did you bring the meat?",rewardGold=341600,rewardXP=5465,rewardItems={164926,171356,171357,171358,173727,174066},starts={{npcID=145641}},ends={{npcID=145641}},mapCandidates={npc={241},zone={4922}},questType="standard",sourceQuests={53892},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=5,flags=0}},db2PoiUiMapID=241},
[53894] = {id=53894,name="Worthwhile Repairs",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=4922,mapID=241,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="The peons are right. These tools are inexcusable. How can they be expected to complete a job without the proper tools for their trade? I can make the needed repairs, but I'll need some ore first.",objectivesText="Collect 15 Twilight Ore so Kiro can repair the peon's tools. Progress: Have you found any ore?",rewardGold=238680,rewardXP=5465,rewardItems={164927,173727,174066},starts={{npcID=145641}},ends={{npcID=145641}},mapCandidates={npc={241},zone={4922}},questType="standard",sourceQuests={53892},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=6,flags=0}},db2PoiUiMapID=241},
[53895] = {id=53895,name="Peon Promotions!",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=4922,mapID=241,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="I agree with the plight of the peons. They should be rewarded for the work they do. It's unlikely that the Horde will agree to increase their wages, but there's no reason they can't be given a promotion. Any title other than peon would help build some confidence.",objectivesText="Give promotions to a few of the Crushblow Peons at Peon Hideout. Progress: Have the peons been promoted yet?",rewardGold=170800,rewardXP=2735,rewardItems={173727,174066},starts={{npcID=145641}},ends={{npcID=145641}},mapCandidates={npc={241},zone={4922}},questType="standard",sourceQuests={53892},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=7,flags=0}},db2PoiUiMapID=241},
[53896] = {id=53896,name="Stand Fast",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53887,53888,53896,53909,53910,53916,53919,53936,53978,53986,54518,54519,54559,54703,54787},description="The Horde will pay for what it has done, but first I have to attend to the people here. <name>, I need to hold a portal open so the injured can evacuate to Boralus. Keep the Horde's forces off me while the wounded get to safety. We can deal with them once the civilians are safe.",objectivesText="Protect Jaina Proudmoore. Progress: That's the last of the wounded.",rewardGold=468000,rewardXP=8520,rewardItems={164921,164968,166280,166682},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=145580}},ends={{npcID=145580}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={53888},questLines={{id=843,name="Beware the Daughter of the Sea",orderIndex=2,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=843,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=843,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53897] = {id=53897,name="A Party in Your Honor",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=4922,mapID=241,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="I think I have everything needed to make tonight a success. We just need to make sure the peons show up. Tell their leader that the Horde is throwing a party in their honor. I'm sure they won't decline a night of free food and drink.",objectivesText="Inform Foreman Magrok that the Horde is throwing a party for the peons.",rewardGold=156400,rewardXP=2735,rewardItems={173727,174066},starts={{npcID=145641}},ends={{npcID=163489}},mapCandidates={npc={241},zone={4922}},questType="standard",sourceQuests={53893,53894,53895},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=8,flags=0}},db2PoiUiMapID=241},
[53898] = {id=53898,name="Strength and Honor",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=4922,mapID=241,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="Those peons certainly look happy, don't they? I have no doubt they'll return to work in the morning. However, if their leader goes unchallenged, there will always be risk of revolt. You need to face him to battle. Show him the true strength of the Horde, but also the honor that comes with showing mercy.",objectivesText="Battle Foreman Magrok , showing both strength and honor. Progress: Why don't you go show Foreman Magrok the true strength of your Horde?",rewardGold=683200,rewardXP=6830,rewardItems={173727,174066},starts={{npcID=163489}},ends={{npcID=163489}},mapCandidates={npc={241},zone={4922}},questType="standard",sourceQuests={53897},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=9,flags=0}},db2PoiUiMapID=241},
[53899] = {id=53899,name="On the Outskirts",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=1637,mapID=85,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="If things are settled for the Commander, you should check in on Nisha . I'm sure she could use your help.",objectivesText="Find Nisha on the southern coast of Zuldazar.",rewardGold=30900,rewardXP=685,rewardItems={173727,174066},starts={{npcID=146261}},ends={{npcID=145980}},mapCandidates={npc={85,862},zone={1637}},questType="standard",sourceQuests={54026},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=11,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[53900] = {id=53900,name="We'll Use Their Weapons",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="We're going to need special weapons to take down Tidecaller Nezara. Good thing it looks like the naga have plenty. We'll use their weapons against them. You and I know a thing or two about that. Grab an assortment. We'll need more than one.",objectivesText="Collect 10 Nazeshi Weaponry from forces within Dreadpearl Shallows. Progress: You got those weapons?",rewardGold=169800,rewardXP=5465,rewardItems={171968,173727,174066},starts={{npcID=145980}},ends={{npcID=145980}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={53899},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=13,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[53901] = {id=53901,name="Explosions Always Work",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="The area surrounding Tidecaller Nezara is heavily guarded, so I'll need you to create a distraction. Take these explosives. Plant them on the naga's harpoon launchers. Once they've been detonated, the blast should be more than enough to send the guards running!",objectivesText="Place Volatile Explosives on naga Harpoon Launchers, and then detonate them to create a distraction. Progress: A fiery distraction is just what we need!",rewardGold=341600,rewardXP=5465,rewardItems={173727,174066},starts={{npcID=145980}},ends={{npcID=145980}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={53899},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=12,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[53902] = {id=53902,name="Taking Out the Tidecaller",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="Nezara's shield might be down, but that doesn't mean she's defenseless. There's a brute by her side that may cause trouble. I'll take a stab at him so you can take down the Tidecaller.",objectivesText="Kill Tidecaller Nezara .",rewardGold=683200,rewardXP=6830,rewardItems={173727,174066},starts={{npcID=145980}},ends={{npcID=145980}},mapCandidates={npc={862},zone={8499}},questTurnInID=145980,questType="standard",sourceQuests={53900,53901,58087},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=15,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[53903] = {id=53903,name="Meet with Meerah",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=1637,mapID=85,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="It appears we're making good progress. Would you meet up with Meerah ? I want to be sure she's found her way to the vintner in Suramar.",objectivesText="Find Meerah within Suramar's Twilight Vineyards.",rewardGold=30900,rewardXP=685,rewardItems={173727,174066},starts={{npcID=146261}},ends={{npcID=146264}},mapCandidates={npc={85,680},zone={1637}},questType="standard",sourceQuests={54027},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=17,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=680},
[53904] = {id=53904,name="The Vintner's Assistants",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=7637,mapID=680,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="Vintner Iltheux oversees all arcwine production for the Horde. He's used to making wine himself, but the Horde sent in help to speed up the process. It's had the opposite effect. We need to get to the bottom of this. How about you tour the vineyards and see how things are running? I have a few more questions for the vintner.",objectivesText="Speak to Micah Broadhoof , Boss Mida , and Nomi . Progress: Have you had a chance to see how things are running?",rewardGold=156400,rewardXP=2735,rewardItems={173727,174066},starts={{npcID=146264}},ends={{npcID=146264}},mapCandidates={npc={680},zone={7637}},questType="standard",sourceQuests={53903},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=18,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=680},
[53905] = {id=53905,name="Playing to Their Strengths",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=7637,mapID=680,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="Iltheux isn't properly utilizing the help he's been given. Let's fix that. Assign new roles to the workers, ones more suited to their strengths. If you need suggestions, I'm happy to help.",objectivesText="Assign new roles to Micah Broadhoof , Boss Mida , and Nomi .",rewardGold=84900,rewardXP=2735,rewardItems={173727,174066},starts={{npcID=146264}},ends={{npcID=157668}},mapCandidates={npc={680},zone={7637}},questType="standard",sourceQuests={53904},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=19,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=680},
[53906] = {id=53906,name="Fermented for the Horde",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=7637,mapID=680,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="Vintner Iltheux's recipe doesn't need much improvement. Some unique ingredients and slight modifications to the winemaking process is all that's needed. I'm thinking adding fermented firebloom should do the trick. Then, filter it though a special cloth made from silkwing fibers . There are plenty of silkwings roaming the vineyard, and I have no doubt that Boss Mida can acquire the flowers, for a price.",objectivesText="Collect the needed ingredients to create a wine worthy of the Horde. Progress: Together, we will make a wine worthy of the Horde.",rewardGold=391000,rewardXP=5465,rewardItems={165012,165013,173727,174066},starts={{npcID=146301}},ends={{npcID=146301}},mapCandidates={npc={680},zone={7637}},questType="standard",sourceQuests={54036},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=21,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=680},
[53907] = {id=53907,name="Sip and Savor",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=7637,mapID=680,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="I think we're making wine, $p! Let's see if the vintner approves of our vintage. Take a sample to Iltheux and see what he thinks.",objectivesText="Deliver a sample of Nomi's Wine to Vintner Iltheux and gain his approval. Progress: I hope he likes the wine.",rewardGold=170800,rewardXP=2735,rewardItems={165014,173727,174066},starts={{npcID=146301}},ends={{npcID=157668}},mapCandidates={npc={680},zone={7637}},questType="standard",sourceQuests={53906},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=22,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=680},
[53908] = {id=53908,name="Awaiting Our Arrival",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=7637,mapID=680,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="Let's head back to Orgrimmar. I'm sure Kiro's expecting us. We really shouldn't make him wait.",objectivesText="Return to Grommash Hold within Orgrimmar.",rewardGold=31200,rewardXP=685,rewardItems={173727,174066},starts={{npcID=157668}},ends={{npcID=145424}},mapCandidates={npc={85,680},zone={7637}},questType="standard",sourceQuests={53907},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=23,flags=0}},db2PoiMapID=1,db2PoiUiMapID=85},
[53909] = {id=53909,name="Besieged Allies",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53887,53888,53896,53909,53910,53916,53919,53936,53978,53986,54518,54519,54559,54703,54787},description="Seawalls can be rebuilt, but lives are lost for good. We need to secure the rest of the people here first. The Outriggers have been known as some of the fiercest hunters in these waters. Find their leader, Rosaline Madison , and enlist her aid in liberating Anglepoint. Together, clear the north shore of the Horde, save anyone in danger, and rally the dock workers. You handle the north shore, <name>. I will handle the south. We'll meet in the middle and crush the Horde between us.",objectivesText="Find Rosaline Madison .",rewardGold=234000,rewardXP=6815,rewardItems={164921,164968,166280,166682},starts={{npcID=145580}},ends={{npcID=145593}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={53896},questLines={{id=843,name="Beware the Daughter of the Sea",orderIndex=3,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=843,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=843,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53910] = {id=53910,name="Repel the Horde!",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53887,53888,53896,53909,53910,53916,53919,53936,53978,53986,54518,54519,54559,54703,54787},description="The Horde has overrun Anglepoint, killing my people and destroying their livelihoods. Its raiders have come to Kul Tiras with killing on their minds. I cannot allow that to happen. Slay any Horde Axe Throwers or Berserkers you see on the north shore. I will do the same on the south. Together we will stop this invasion.",objectivesText="Defeat Horde Axe Throwers or Berserkers on the north shore of Anglepoint Wharf.",rewardGold=234000,rewardXP=6815,rewardItems={164921,164968,166280,166682},starts={{npcID=145580}},ends={{npcID=145593}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={53896},questLines={{id=843,name="Beware the Daughter of the Sea",orderIndex=4,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=843,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=843,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53912] = {id=53912,name="The Hunt Never Ends",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53851,53852,53856,53879,53880,53912,53913,53973,53981},description="We have our victory, but we must move quickly to take the remaining Azerite from the estate. Our forces should already be moving the Azerite from the manor into our gyrocopter support. Let us move and ensure we get every ounce of Azerite away from the Alliance.",objectivesText="Travel to the Norwington manor.",rewardGold=23400,rewardXP=850,rewardItems={164987,165702,165734,166309},starts={{npcID=146462}},ends={{npcID=145422}},mapCandidates={npc={895},zone={8567}},questGiverID=146462,questType="standard",sourceQuests={53913},questLines={{id=838,name="Norwington Assault",orderIndex=6,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=838,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=838,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53913] = {id=53913,name="With Honor",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53851,53852,53856,53879,53880,53912,53913,53973,53981},description="The Alliance and Kul Tiran forces are in disarray. I can hear the Azerite tank powering up. Lieutenant Cole intends to fight us... now that his forces are destroyed. Let me know when you are ready to fight. The three of us shall destroy this tank while our warriors watch on!",objectivesText="Defeat Lieutenant Cole . Progress: Are you ready?",rewardGold=468000,rewardXP=8520,rewardItems={114687,114688,114689,114690,114691,114692,114693,114694,164987,165702,165734,166309,234744,234745,234746,235262},starts={{npcID=146462}},ends={{npcID=146462}},mapCandidates={npc={},zone={8567}},questGiverID=146462,questType="standard",sourceQuests={53879,53880},questLines={{id=838,name="Norwington Assault",orderIndex=7,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=838,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=838,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53914] = {id=53914,name="Murder at the Brawl'gar Arena",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6298,storyline={53914},series={53915,53917,53918,53920,53921},description="The Brawl'gar quartermaster lies dead in front of you. He was murdered in broad daylight! He must have been assassinated while someone was fighting in the arena. Maybe even during one of your fights. Perhaps there are some clues nearby as to who might have killed him.",objectivesText="Investigate the scene of the crime.",rewardGold=309800,rewardXP=11765,rewardItems={166724},starts={{npcID=68364}},ends={{npcID=68364}},mapCandidates={npc={},zone={6298}},questGiverID=68364,questTurnInID=68364,questType="standard"},
[53915] = {id=53915,name="Put Up Your Dukes",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6298,storyline={53915},series={53914,53917,53918,53920,53921},description="You know what? <The commander puts his notebook away.> I COULD use a good <class> on my investigations team. We've had some personnel issues lately and, frankly, I can use all the help I can get. But first: why don't you go hop into the arena for a few fights so I can get a good look at your skills?",objectivesText="Win any 3 fights in the Brawl'gar Arena.",rewardGold=309800,rewardXP=11765,rewardItems={166724},starts={{npcID=145581}},ends={{npcID=145581}},mapCandidates={npc={},zone={6298}},questGiverID=145581,questTurnInID=145581,questType="standard",sourceQuests={53914}},
[53916] = {id=53916,name="Outrigger Outfitters",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53887,53888,53896,53909,53910,53916,53919,53936,53978,53986,54518,54519,54559,54703,54787},description="My people met the Horde head on when they arrived, but we've been scattered over the wharf. The Horde has been relentless. We haven't been able to form a solid resistance force using just our fists as weapons. But now the Lord Admiral is here with the champion of the Alliance. That's just the spark we need to rise up and kick these sorry mongrels out of our lands. If you can get my men some weapons, they'll join the fight! Find those weapons and meet me back here. I'm working on a plan.",objectivesText="Recover 10 Outrigger Weapons . Progress: For Kul Tiras! For the Lord Admiral!",rewardGold=234000,rewardXP=6815,rewardItems={164921,164968,166280,166682},starts={{npcID=145593}},ends={{npcID=145593}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={53909},questLines={{id=843,name="Beware the Daughter of the Sea",orderIndex=7,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=843,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=843,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53917] = {id=53917,name="Undercover Agent: Sharisanda",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6298,storyline={53917},series={53914,53915,53918,53920,53921},description="Pit Boss Buxdoggle is one of our primary suspects in this case. Buxdoggle is an infamously aggressive speculator, and has a list of debts a mile long. He may be in need of money, which is consistent with the evidence you found earlier. Sharisanda has taken point on the case. I'd like you to assist her. I think you'll work well together.",objectivesText="Report to Sharisanda in the Brawl'gar Arena.",rewardGold=309800,rewardXP=11765,rewardItems={166724},starts={{npcID=145581}},ends={{npcID=145581}},mapCandidates={npc={},zone={6298}},questGiverID=145581,questTurnInID=145581,questType="standard",sourceQuests={53915}},
[53918] = {id=53918,name="The Financial Participation Incentive",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6298,storyline={53918},series={53914,53915,53917,53920,53921},description="I see Buxdoggle running some sort of game over dere. Getting people to guess de fight's winner in exchange for Brawler's Gold. See if you can figure out how his game works. If you win enough money from him, he might start talking...",objectivesText="Win 100 Brawler's Gold from Pit Boss Buxdoggle 's guessing game. If the game is not currently active, anyone can activate it by purchasing a High Roller's Contract from Tiana Nevermorn. Progress: Lookin' to make some gold, bub?",rewardGold=309800,rewardXP=11765,rewardItems={142318,143762,166724},starts={{npcID=145582}},ends={{npcID=145582}},mapCandidates={npc={},zone={6298}},questGiverID=145582,questTurnInID=145582,questType="standard",sourceQuests={53917}},
[53919] = {id=53919,name="Shots Fired",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53887,53888,53896,53909,53910,53916,53919,53936,53978,53986,54518,54519,54559,54703,54787},description="Horde invaders keep sailing in through the seagate, but we have a nasty surprise for them! The Outriggers are good at fighting monsters of any sort, the Horde included. We'll keep them off you while you take out their boats. Send 'em to the bottom of the harbor! For Kul Tiras! For the Lord Admiral!",objectivesText="Destroy Horde Motorboats. Progress: That will hold the Horde for now.",rewardGold=234000,rewardXP=6815,rewardItems={164921,164968,166280,166682},starts={{npcID=145593}},ends={{npcID=145580}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={53910,53978,54559,54787},questLines={{id=843,name="Beware the Daughter of the Sea",orderIndex=11,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=843,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=843,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53920] = {id=53920,name="A Favor for Your Ol' Pal Buxdoggle",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6298,storyline={53920},series={53914,53915,53917,53918,53921},description="Hey, listen, I was thinkin' about somethin'... You know how you won all that money from me? Well, funny story, that may have been slightly more money than I actually have, and now some very powerful people want to break my elbows and my knees. I can't pay 'em! I'm broke! Heh heh! All I need to get out of this hole is for you to lose your next fight. Flop like a fish. Please.",objectivesText="Lose a fight in Brawl'gar Arena. Progress: Please, ya gotta help me! They said they're gonna break my money bone! I don't even know where that is!",rewardGold=309800,rewardXP=11765,rewardItems={166724},starts={{npcID=68372}},ends={{npcID=68372}},mapCandidates={npc={},zone={6298}},questGiverID=68372,questTurnInID=68372,questType="standard",sourceQuests={53918}},
[53921] = {id=53921,name="The Pit Boss's Debts",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6298,storyline={53921},series={53914,53915,53917,53918,53920},description="I'm not too proud to commit a few acts of violence to set a wrong right. And you know what's wrong? I'm out of money! Only one person's won more gold from me than you have, and his name's Lord Sylysthrel. Real skeezy guy. I think he was cheating. Sure would be nice if I could get that gold back...",objectivesText="Obtain a Huge Pile of Legitimately-Earned Brawler's Gold from Lord Sylysthrel. You can challenge Lord Sylysthrel by purchasing his Challenge Card from Card Trader Ami. Progress: Once I get back the gold I lost, then I can REALLY start gambling!",rewardGold=341600,rewardXP=11765,rewardItems={164935,164939,164941,166724},starts={{npcID=68372}},ends={{npcID=68372}},mapCandidates={npc={},zone={6298}},questGiverID=68372,questTurnInID=68372,questType="standard",sourceQuests={53920}},
[53922] = {id=53922,name="Evidence Packet: Pit Boss Buxdoggle",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6298,storyline={53922},series={53923},description="I heard everything. That goblin sure does talk loudly about his crimes and debts, doesn't he? It sounds like we have enough to bring him in for questioning. I've put together a packet of evidence for Commander Ravenhide to review. Good job out dere.",objectivesText="Bring the Evidence Packet to Commander Arlu Ravenhide . Progress: Find anything on Buxdoggle?",rewardGold=309800,rewardXP=11765,rewardItems={164962,166724},starts={{npcID=145582}},ends={{npcID=145582}},mapCandidates={npc={},zone={6298}},questGiverID=145582,questTurnInID=145582,questType="standard",sourceQuests={53921}},
[53923] = {id=53923,name="Undercover Agent: Stone Guard Mollivox",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6298,storyline={53923},series={53922},description="I believe you've met one of my other agents: Stone Guard Mollivox . She's investigating our second suspect: Shadowmaster Skrizzik. You'll find Mollivox near the arena's entrance.",objectivesText="Speak with Stone Guard Mollivox at the Brawl'gar Arena.",rewardGold=309800,rewardXP=11765,rewardItems={166724},starts={{npcID=145581}},ends={{npcID=145581}},mapCandidates={npc={},zone={6298}},questGiverID=145581,questTurnInID=145581,questType="standard",sourceQuests={53922}},
[53924] = {id=53924,name="Soul Splinters",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6298,storyline={53924},series={53925},description="<Skrizzik mumbles to himself.> Oh dear, oh dear... it's getting hungry again. Where am I going to find enough souls to feed it? Ohh... if only I could get my hands on some of those brawler's purses... <He notices you.> Oh! Hello there! Pay no attention to the mindless babbling of an innocent warlock. Nothing suspicious going on here!",objectivesText="Search inside Brawler's Purses for something \"soul\"-related. Brawler's Purses are awarded to victors in the Brawl'gar Arena. Some types of purses may be more lucrative than others. Progress: Oh dear, oh dear... must not let it get too hungry...",rewardGold=309800,rewardXP=11765,rewardItems={92718,164928,164931,166724},starts={{npcID=145691}},ends={{npcID=145691}},mapCandidates={npc={},zone={6298}},questGiverID=145691,questTurnInID=145691,questType="standard",sourceQuests={53923}},
[53925] = {id=53925,name="Super Soul Splinters",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6298,storyline={53925},series={53924},description="<Skrizzik mutters to himself again:> Will these be big enough, though? It gets SO hungry for souls, and when it doesn't get enough, it gets angry, and we definitely don't want to trigger a void apocalypse in the middle of Orgrimmar. Oh dear, oh dear... <He notices you lingering.> Oh! The <race> is still here! Heh heh. Never mind me! Nothing evil going on here!!",objectivesText="Obtain 3 Super Soul Splinters from Rumbler's Purses, which are rewarded from winning rumbles. Rumbles are large group fights that pit all players in the Brawl'gar Arena queue against a challenging enemy. Anyone can start a rumble by purchasing a Rumble Card from Tiana Nevermorn. Progress: <Skrizzik looks around the arena in a panic.> Where can I find more souls? Maybe the quartermaster sells some? Oh, right, he's dead. Hmm...",rewardGold=309800,rewardXP=11765,rewardItems={164929,164931,166724},starts={{npcID=145691}},ends={{npcID=145691}},mapCandidates={npc={},zone={6298}},questGiverID=145691,questTurnInID=145691,questType="standard",sourceQuests={53924}},
[53926] = {id=53926,name="Cause for Concern",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=6298,mapID=109,storyline={53926},series={53927,53928,53929,53930},description="Shadowmaster Skrizzik's behavior was unusual. His repeated mutterings about \"shadow magic\" and \"void apocalypses\" and \"ancient creatures hungering for the souls of the living\" certainly warrant further investigation. You should report back to Stone Guard Mollivox .",objectivesText="Report to Stone Guard Mollivox .",rewardGold=30900,rewardXP=1470,rewardItems={166724},mapCandidates={npc={},zone={6298}},questType="standard",sourceQuests={53925}},
[53927] = {id=53927,name="The Precious 13-Tooth Gogglegear",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6298,storyline={53927},series={53926,53928,53929,53930},description="We're going to have to invent something. Something capable of seeing into alternate dimensions. Something explosive that you strap directly onto your eyes. That's right, I'm talking about goggles. I already have all the goggle parts except for one: a 13-tooth gear. They're nearly impossible to find, but I KNOW that the G.G. Engineering boys have one, and Card Trader Ami has their challenge card.",objectivesText="Obtain a 13-Tooth Gogglegear from G.G. Engineering. You can purchase their challenge card from Card Trader Ami. Progress: Are you ready to goggle up?",rewardGold=312800,rewardXP=11765,rewardItems={94178,164937,164938,166724},starts={{npcID=145583}},ends={{npcID=145583}},mapCandidates={npc={},zone={6298}},questGiverID=145583,questTurnInID=145583,questType="standard",sourceQuests={53926}},
[53928] = {id=53928,name="The Mollivox Goggle Experiment",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6298,storyline={53928},series={53926,53927,53929,53930},description="Okay, before we start, I've got a few rules: First, these goggles will only work at close range. We're looking for something INSIDE the arena, so you'll have to be inside the arena to use them. Second rule: if you feel something starting to explode, try to blink real hard. Lastly, remember, we're looking for an evil shadow monster. You don't need to kill it, we just need you to see it so we can report it as evidence. Alright, go get in that arena and try them out!",objectivesText="Put on Mollivox's Goggles while fighting in the Brawl'gar Arena and look for evidence against Shadowmaster Skrizzik.",rewardGold=309800,rewardXP=11765,rewardItems={164943,166724},starts={{npcID=145583}},ends={{npcID=145583}},mapCandidates={npc={},zone={6298}},questGiverID=145583,questTurnInID=145583,questType="standard",sourceQuests={53927}},
[53929] = {id=53929,name="Evidence Packet: Shadowmaster Skrizzik",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6298,storyline={53929},series={53926,53927,53928,53930},description="Sounds like we've found our perp, <name>. This guy's sketchy, desperate, and his shadow magic is consistent with that shadowy scroll you found earlier. Bring this packet to Arlu, and we can bring him in. Good work out there!",objectivesText="Bring the Evidence Packet to Commander Arlu Ravenhide . Progress: Any news on Skrizzik?",rewardGold=309800,rewardXP=11765,rewardItems={164963,166724},starts={{npcID=145583}},ends={{npcID=145583}},mapCandidates={npc={},zone={6298}},questGiverID=145583,questTurnInID=145583,questType="standard",sourceQuests={53928}},
[53930] = {id=53930,name="Undercover Agent: Nugg Lumbo",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6298,storyline={53930},series={53926,53927,53928,53929},description="I've got one more suspect I'm investigating: Libbiara Blightrunner. She's a wealthy blood elf death knight socialite who spends most of her time spectating the arena from the zeppelin up above. I've got my best agent on the case: Nugg Lumbo . Check in with him to see how his report is coming along.",objectivesText="Report to Nugg Lumbo aboard the Skybag, the zeppelin above Brawl'gar Arena. The Skybag teleporter is located just outside of the Brawl'gar Arena bar. To use the teleporter, you must either be Rank 6 in Brawl'gar Arena, or someone must purchase a Zeppelin Rental Form from Tiana Nevermorn.",rewardGold=312800,rewardXP=11765,rewardItems={166724},starts={{npcID=145581}},ends={{npcID=145581}},mapCandidates={npc={},zone={6298}},questGiverID=145581,questTurnInID=145581,questType="standard",sourceQuests={53929}},
[53931] = {id=53931,name="Flaunt It If You Got It",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6298,storyline={53931},series={53952},description="Sigh... so dull... Oh, it's you! <name>, was it? I've seen a few of your fights. They're slightly less tedious than the standard humdrum bloodsport this arena has been producing lately. Let's spice things up a bit. Maybe buy some expensive drinks for ourselves? Buy a round of the cheap stuff for the riffraff below? Maybe even toss a few amberseed buns off the boat?",objectivesText="Drink a bottle of Moneybrau, purchase a round of drinks at the bar in Brawl'gar Arena, and hit a fighting player with an Amberseed Bun while standing on the deck of the Skybag. Progress: <The death knight socialite sighs.>",rewardGold=309800,rewardXP=11765,rewardItems={98121,166724},starts={{npcID=70716}},ends={{npcID=70716}},mapCandidates={npc={},zone={6298}},questGiverID=70716,questTurnInID=70716,questType="standard",sourceQuests={53930}},
[53932] = {id=53932,name="Evidence Packet: Libbiara Blightrunner",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6298,storyline={53932},series={53933,53934,53935},description="Nugg got what Nugg need. Give stupid blood elf one drink and she start getting all self-incriminatey. You bring packet to Commander. Nugg gonna buy some expensive snacks.",objectivesText="Bring the Evidence Packet to Commander Arlu Ravenhide . Provided item:",rewardGold=309800,rewardXP=11765,rewardItems={164964,166724},starts={{npcID=145584}},ends={{npcID=145584}},mapCandidates={npc={},zone={6298}},questGiverID=145584,questTurnInID=145584,questType="standard",sourceQuests={53952}},
[53933] = {id=53933,name="The Brawl'gar Trial",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6298,storyline={53933},series={53932,53934,53935},description="I've issued three warrants. Nugg, Mollivox, and Sharisanda are apprehending the suspects as we speak. It's time to go to court. You may be called on to testify. Just answer as honestly as you can, and let the wheels of justice do the rest.",objectivesText="Reach a verdict in the Brawl'gar Trial.",rewardGold=309800,rewardXP=11765,rewardItems={166724},starts={{npcID=145581}},ends={{npcID=145581}},mapCandidates={npc={},zone={6298}},questGiverID=145581,questTurnInID=145581,questType="standard",sourceQuests={53932}},
[53934] = {id=53934,name="A Clue from Area 52",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6298,mapID=109,storyline={53934},series={53932,53933,53935},description="We've received a letter from Area 52, the goblin outpost in Netherstorm. The author claims to know details about what they call \"the situation in Brawl'gar\". They don't say more than that. I'm tied to my paperwork here. Go check out this lead and see if anything turns up.",objectivesText="Investigate Area 52 in Netherstorm for a sign of the letter's writer.",rewardGold=309800,rewardXP=11765,rewardItems={30542,30544,166724},starts={{npcID=145581}},ends={{npcID=149808}},mapCandidates={npc={109},zone={6298}},questGiverID=145581,questType="standard",sourceQuests={53933}},
[53935] = {id=53935,name="Solving the Mystery",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=3523,mapID=109,storyline={53935},series={53932,53933,53934},description="<Bazzelflange produces a challenge card from her pocket.> I grabbed this challenge card from my attackers while we were fighting each other! I'm sure that you can use it to challenge my attacker to some sort of ultimate showdown!",objectivesText="Bring the Mysterious Challenge Card to Brawl'gar Arena to confront Boss Bazzelflange 's captor.",rewardGold=1239200,rewardXP=23530,rewardItems={164936,164942,166724},rewardChoices={166724},starts={{npcID=149808}},ends={{npcID=149808}},mapCandidates={npc={109},zone={3523}},questTurnInID=149808,questType="standard",sourceQuests={53934}},
[53936] = {id=53936,name="Stopping the Sappers",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53887,53888,53896,53909,53910,53916,53919,53936,53978,53986,54518,54519,54559,54703,54787},description="The ice should keep the Horde out while we handle the sapper teams gathered on the beach. I'm going to keep those Horde galleons busy. I need you to handle whoever is in charge and bring all the Azerite bombs you find back to me. Then we'll handle disposing of their weapons.",objectivesText="Kill Nebbik Megafuel , collect Azerite bombs, and bring them to Jaina on top of the seagate. Progress: Were you able to recover the bombs?",rewardGold=468000,rewardXP=8520,rewardItems={164921,164968,166280,166682},starts={{npcID=145580}},ends={{npcID=145580}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={53919},questLines={{id=843,name="Beware the Daughter of the Sea",orderIndex=12,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=843,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=843,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53937] = {id=53937,name="The Ub3r-Spanner",level=50,requiredLevel=50,faction="horde",requiredProfessions={"engineering"},categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={53783,53802,53806,53833,53848,53937,54930,55031},description="It's a shame that Gryzix had to die. Those Venture Co. make all of us enterprising types look bad! At least we can still decode the Ub3r-Spanner schematic. Here, hand me that schematic and his decoder and I'll get this whipped up in just a second.",objectivesText="Wait for Shuga Blastcaps to decode the schematic.",rewardGold=23400,rewardXP=850,rewardItems={164740},starts={{npcID=131840}},ends={{npcID=131840}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={53833},questLines={{id=868,name="Tools of the Trade: The Ub3r-Spanner",orderIndex=7,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[53938] = {id=53938,name="A Friend in Needle",level=50,requiredLevel=50,faction="horde",requiredProfessions={"tailoring"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53938,53940,53962,55188},description="You can see me? Oh, thank goodness! I thought I was lost in the folds of time...again! But for one to see through the folds of time's fabric... you must be a very talented tailor, indeed. Would you bring me some cloth, then, tailor? I believe I'll be able to place just when I am with your help and right myself.",objectivesText="Collect 5 Tidespray Linen and 5 Deep Sea Satin . Progress: When in Azeroth am I...?",rewardGold=58500,rewardXP=1705,rewardItems={152576,152577},starts={{npcID=145022}},ends={{npcID=145022}},mapCandidates={npc={1161},zone={8568}},questType="standard",questLines={{id=905,name="8.1.5 Tailoring - Horde",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[53939] = {id=53939,name="Breaching Boralus",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=862,storyline={53939},description="Finally! There's no place on Kul Tiras with a stronger Alliance presence. We must be bold and unrelenting if we're going to drive them out here. Lok-tar ogar!",objectivesText="Lead the Horde assault into Tiragarde Sound. Progress: What are you doing here? The Horde needs you in Tiragarde Sound!",rewardXP=2125,rewardItems={165871,166792},rewardCurrencies={{id=1553,amount=400},{id=1716,amount=5}},starts={{npcID=135447}},ends={{npcID=135447}},mapCandidates={npc={862},zone={8567}},questGiverID=135447,questType="standard"},
[53940] = {id=53940,name="A Stitch in Time",level=50,requiredLevel=50,faction="horde",requiredProfessions={"tailoring"},categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=115,storyline={53938,53940,53962,55188},series={55188},description="Hm...I don't know that I've ever been to this time, before. I suppose I should explain myself. My name is Delormi, and I'm the last remaining member of the Synchronous Tailors . We make sure the fabric of time stays, well, mended. But I've found a number of new tears cropping up. In fact, I believe that's why I've arrived here in this time. Perhaps you could assist me in tracking them down and repairing them?",objectivesText="Assist Delormi in repairing the Tears in Time. Progress: Something strange is happening. These tears have become too frequent as of late.",rewardGold=58500,rewardXP=1705,rewardItems={167231},starts={{npcID=151134}},ends={{npcID=151134}},mapCandidates={npc={115},zone={9042}},questTurnInID=151134,questType="standard",sourceQuests={53938},questLines={{id=905,name="8.1.5 Tailoring - Horde",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[53941] = {id=53941,name="A Mech for a Goblin",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={53941,53942,54004,54007,54008,54009,54022,54028,54094,54123,54124,54128,54635},description="Gallywix has a plan to deal with the Alliance and has requested your help. It involves the Azerite you reclaimed. Speak with him down at Bilgewater Bonanza, and do whatever you can to help him... when it comes to the interest of the Horde. Oh, and make sure Gallywix stays alive. The Alliance already tried to kill him.",objectivesText="Meet Gallywix at Bilgewater Bonanza.",rewardGold=23400,rewardXP=850,rewardItems={164987,165702,165734,166309},starts={{npcID=135691}},ends={{npcID=145751}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={53981},questLines={{id=839,name="Adventures of Gallywix and the G.M.O.D.",orderIndex=0,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=839,questLineOrder=16,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=839,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[53942] = {id=53942,name="The Right Mech for the Job",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={53941,53942,54004,54007,54008,54009,54022,54028,54094,54123,54124,54128,54635},description="Okay, <name>, we're good to go. The G.M.O.D has plenty of Azerite to cause some trouble! We gotta head to my, er, OUR base in Drustvar. Mekkatorque, that freakin' king of the gnomes, is attacking our Azerite supply! After we take care of the base, we're gonna take care of him! You get what I'm sayin'?",objectivesText="Fly in the G.M.O.D to Drustvar and defend Krazzlefrazz Outpost.",rewardGold=468000,rewardXP=8520,rewardItems={164987,165702,165734,166309},rewardCurrencies={{id=1553,amount=300}},starts={{npcID=145751}},ends={{npcID=145786}},mapCandidates={npc={862,896},zone={8499}},questType="standard",sourceQuests={54123,54124},questLines={{id=839,name="Adventures of Gallywix and the G.M.O.D.",orderIndex=3,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=839,questLineOrder=16,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=839,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=896},
[53943] = {id=53943,name="Modular Construction",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"engineering"},categories={},flags={},sharable=false,expansion=7,storyline={53943},description="The Abandoned Junkheap is home to some seriously deadly gnomish constructs. These constructs contain Mecha-Cores which could come in handy for crafting the Ub3r-Spanner. Legend has it that it could forge creations unlike anything we've ever seen! You look like the adventurous type, . Can you go scrap up some mechs? Don't forget your Arclight Spanner!",objectivesText="Kill mechanical constructs in the Abandoned Junkheap and salvage 8 Mecha-Cores with an Arclight Spanner.",rewardGold=234000,rewardXP=6815,rewardItems={164768},mapCandidates={npc={},zone={}},questType="standard"},
[53945] = {id=53945,name="Naga Attack!",level=10,requiredLevel=10,faction="none",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={53945},objectivesText="Repel the naga invaders Rescue prisoners Banners removed Supplies Destroyed",rewardXP=2125,rewardItems={165605,168003,168123},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{text="Repel the naga invaders",amount=1,type=15,objectID=0,orderIndex=0},{text="Rescue prisoners",amount=34,type=0,objectID=145214,orderIndex=1},{text="Banners removed",amount=34,type=0,objectID=145856,orderIndex=2},{text="Supplies Destroyed",amount=34,type=0,objectID=145855,orderIndex=3}},worldTaskTitle="Naga Attack!",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=111,db2QuestInfoName="Elite World Quest"},
[53947] = {id=53947,name="In the Dunes",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"engineering"},categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=864,storyline={53802,53806,53848,53947,53948,53949,54930,55028},description="This schematic you found is encrypted. My tools are no good on it, not without risking the integrity of the data. However, I do know a guy who can definitely crack this cookie: Mr. Dataguru Gryzix . If I remember correctly, he's been vacationing on a beach in Vol'dun since the war broke out. Something about not getting the recognition he deserves. Anyways, I am sure you can convince him to help you.",objectivesText="Find Dataguru Gryzix at The Forgotten Marsh in Vol'dun. Provided item:",rewardGold=23400,rewardXP=850,rewardItems={164740,164919,253179,253700},starts={{npcID=136059}},ends={{npcID=145131}},mapCandidates={npc={864},zone={8568}},questGiverID=136059,questType="standard",sourceQuests={55028},questLines={{id=869,name="Tools of the Trade: The Ub3r-Spanner",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[53948] = {id=53948,name="Vengeful Venture",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"engineering"},categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=1161,storyline={53802,53806,53848,53947,53948,53949,54930,55028},description="<You pick up the note and deduce that the Venture Co. are the killers of Dataguru Gryzix. You search his corpse, and find that his decoder and the Ub3r-Spanner schematic have been stolen. You need to retrieve his decoder and the schematic and bring them back to Layla Evenkeel to have any hope of crafting the Ub3r-Spanner. That mech you have following you should prove itself useful.>",objectivesText="Locate the Venture Co. camp, then retrieve Gryzix's Decoder and the Encrypted Ub3r-Spanner Schematic . Progress: What's up, <name>? Did Gryzix handle that schematic for you?",rewardGold=468000,rewardXP=8520,rewardItems={164740,164773,164919,166886},startObjects={{objectID=307748,mapID=864,x=0.263,y=0.473}},endObjects={{objectID=307748,mapID=864,x=0.263,y=0.473}},coords={mapID=864,x=0.263,y=0.473},mapCandidates={npc={},zone={8501}},questType="standard",sourceQuests={53848},questLines={{id=869,name="Tools of the Trade: The Ub3r-Spanner",orderIndex=6,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[53949] = {id=53949,name="The Ub3r-Spanner",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"engineering"},categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={53802,53806,53848,53947,53948,53949,54930,55028},description="It's a shame that Gryzix had to die. Those Venture Co. make all of us enterprising types look bad! At least we can still decode the Ub3r-Spanner schematic. Here, hand me that recipe and his decoder and I'll get this whipped up in just a second.",objectivesText="Wait for Layla Evenkeel to decode the schematic.",rewardGold=23400,rewardXP=850,rewardItems={164740},starts={{npcID=136059}},ends={{npcID=136059}},mapCandidates={npc={},zone={8568}},questGiverID=136059,questTurnInID=136059,questType="standard",sourceQuests={53948},questLines={{id=869,name="Tools of the Trade: The Ub3r-Spanner",orderIndex=7,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[53950] = {id=53950,name="Explosive Relief",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={53950},objectivesText="Alliance soldiers slain",rewardXP=2125,mapCandidates={npc={},zone={8500}},questType="standard",db2Objectives={{text="Alliance soldiers slain",amount=10,type=0,objectID=144959,orderIndex=1}},worldTaskTitle="Explosive Relief",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[53951] = {id=53951,name="Explosive Relief",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={53951},objectivesText="Horde soldiers slain",rewardXP=2125,mapCandidates={npc={},zone={8500}},questType="standard",db2Objectives={{text="Horde soldiers slain",amount=10,type=0,objectID=144958,orderIndex=1}},worldTaskTitle="Explosive Relief",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[53952] = {id=53952,name="Simply Dying of Boredom",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6298,storyline={53952},series={53931},description="Up until now, I've been dying of boredom up here. I think maybe we need some new blood here in the arena. Boss Bazzelflange can be so stingy with her invitations, can't she? I've had one of my servants write up a few slightly-counterfeit invitations to hand out. Maybe you could help me get them distributed? There's always plenty of tough-looking characters hanging out in front of the auction house near Grommash Hold...",objectivesText="Use the Brawl'gar Arena Sign in Orgrimmar's Valley of Strength.",rewardGold=309800,rewardXP=11765,rewardItems={164947,166724},starts={{npcID=70716}},ends={{npcID=70716}},mapCandidates={npc={},zone={6298}},questGiverID=70716,questTurnInID=70716,questType="standard",sourceQuests={53931}},
[53953] = {id=53953,name="Brawl'gar Awaits!",level=80,requiredLevel=80,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=6298,mapID=109,storyline={53953},description="Tired of standing around in the boring old Valley of Strength? Come on over to the Brawl'gar Arena, and fight for the amusement of others! You might win, or you might get killed, but either way, you're going to have a great time. Grab an invitation and bring it to Skuglor , near the front door. Brawl'gar awaits!",objectivesText="Bring an invitation to the Brawl'gar Arena. Provided item:",rewardGold=309800,rewardXP=11765,rewardItems={164949},mapCandidates={npc={},zone={6298}},questType="standard"},
[53955] = {id=53955,name="Warfront: The Battle for Darkshore",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53955,54042,54043,54044,54045,54046,54047,54049,54050,54059,54416},description="Darkshore belongs to the Horde! We must hold that ground to maintain our dominance over Kalimdor. Prepare yourselves. Battle awaits!",objectivesText="Defeat the Alliance at the Battle for Darkshore. Progress: We must do what we can to claim Darkshore for the Horde.",rewardGold=468000,rewardXP=8520,rewardItems={166369,166370},rewardCurrencies={{id=1716,amount=15},{id=1553,amount=750}},starts={{npcID=138949}},ends={{npcID=138949}},mapCandidates={npc={1165},zone={8670}},questType="standard",questLines={{id=856,name="In Darkest Night",orderIndex=10,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[53957] = {id=53957,name="Darkshore Recruits",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10058,storyline={53957},description="We've got a few recruits that can help us take back Darkshore! But first, we need our Ancient of War to be back up to good health. To help him, contribute resources to him and he'll perk right up! Once the Ancient of War is restored, talk to Jarod Shadowsong and recruit a troop. I'm sure they could learn a lot from fighting alongside you.",objectivesText="Restore the Ancient of War, then speak with Jarod Shadowsong to recruit an ally. Progress: Did you get those recruits?",rewardCurrencies={{id=1540,amount=10}},starts={{npcID=145770}},ends={{npcID=145770}},mapCandidates={npc={},zone={10058}},questGiverID=145770,questTurnInID=145770,questType="standard",sourceQuests={53976,54436}},
[53959] = {id=53959,name="Armor for Armies",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10058,storyline={53959},description="We need to make sure our soldiers have the best equipment possible in the battle against the Horde. Once the Hunter's Hall is constructed, speak with Cordressa Briarbow about how to improve the weapons and armor of our troops.",objectivesText="Speak with Cordressa Briarbow to learn what the Hunter's Hall has to offer. Progress: I regret many things that took us to this moment, but we will do what needs to be done.",starts={{npcID=145783}},ends={{npcID=145783}},mapCandidates={npc={},zone={10058}},questGiverID=145783,questTurnInID=145783,questType="standard",sourceQuests={53957}},
[53960] = {id=53960,name="The Altar of Elders",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10058,storyline={53960},description="Now that contributions are in full swing, the Altar of Elders has been rebuilt. Go, speak with Moon Priestess Lasara to see what the Altar has to offer.",objectivesText="Speak with Moon Priestess Lasara to learn what the Altar of Elders has to offer. Progress: Have you visited the Altar of Elders yet?",starts={{npcID=145783}},ends={{npcID=145783}},mapCandidates={npc={},zone={10058}},questGiverID=145783,questTurnInID=145783,questType="standard",sourceQuests={53959}},
[53961] = {id=53961,name="Glaiveworks For Me",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10058,storyline={53961},description="We've all been on edge since Teldrassil, but Erion took it hard. He jumped at the chance to help out. Why don't you talk to him and see what he's got going at the Glaiveworks?",objectivesText="Speak with Erion to learn what the Glaiveworks has to offer. Progress: How may I help?",starts={{npcID=145784}},ends={{npcID=145784}},mapCandidates={npc={},zone={10058}},questGiverID=145784,questTurnInID=145784,questType="standard",sourceQuests={53960,53974}},
[53962] = {id=53962,name="Cut from the Same Cloth",level=50,requiredLevel=50,faction="horde",requiredProfessions={"tailoring"},categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=115,storyline={53938,53940,53962,55188},description="My Infinite self was right--I can no longer mend time. Too many of my threads have been purged. I can feel no others. I'm alone now. And my thread is gone. But not you. Take this recipe. You've proven yourself a talented tailor in your own time, and a savior in so many more. The fabric of time needs your hands to mend it. I trust you with that responsibility. Talk to me when you're ready. I'll take you back to when this all began.",objectivesText="Ask Timeweaver Delormi to return you to your time.",rewardGold=23400,rewardXP=850,starts={{npcID=151134}},ends={{npcID=151134}},mapCandidates={npc={115},zone={9042}},questTurnInID=151134,questType="standard",sourceQuests={53869},questLines={{id=905,name="8.1.5 Tailoring - Horde",orderIndex=3,flags=0}},db2PoiMapID=571,db2PoiUiMapID=115},
[53963] = {id=53963,name="Naga Attack!",level=10,requiredLevel=10,faction="none",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={53963},objectivesText="Repel the naga invaders Prisoners freed War supplies destroyed",rewardXP=2125,rewardItems={165605,168003,168123},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{text="Repel the naga invaders",amount=1,type=15,objectID=0,orderIndex=0},{text="Prisoners freed",amount=34,type=0,objectID=145891,orderIndex=1},{text="War supplies destroyed",amount=34,type=0,objectID=145875,orderIndex=2}},worldTaskTitle="Naga Attack!",db2PoiMapID=1643,db2PoiUiMapID=896,db2QuestInfoID=111,db2QuestInfoName="Elite World Quest"},
[53965] = {id=53965,name="Children's Week",level=10,requiredLevel=10,faction="horde",categories={"seasonal"},flags={},sharable=false,event="Children's Week",expansion=7,zoneID=8670,mapID=1165,storyline={53965},description="Thank you for offering your help with Children's Week, <name>. We have a little girl who is excited to explore Zandalar! Take dis whistle. With it, you will be able to call de child you have agreed to take care of dis week. It will serve no use after Children's Week ends. When you are ready, use de whistle and meet your new ward! She is a feisty one.",objectivesText="Use the Zandalari Orphan Whistle to call for the ward that you will be looking after during Children's Week. Provided item:",rewardItems={23022,116202,164965,167008,167009,167010,167011},starts={{npcID=131346}},ends={{npcID=131346}},mapCandidates={npc={1165},zone={8670}},questTurnInID=131346,questType="standard",packageItems={241215}},
[53966] = {id=53966,name="Loa of Winds",level=10,requiredLevel=10,faction="horde",categories={"seasonal"},flags={},sharable=false,event="Children's Week",expansion=7,storyline={53966},description="I heard dat Pa'ku lives somewhere in Zuldazar. Her priests tell stories about her when dey come to de Hall of Castes. She's a pretty popular loa. I mean, she's in charge of de sky AND de sea! Dat's a lot of blue, and blue is my favorite color! Maybe I could be one of her followers?",objectivesText="Take Azala to Pterror Rise in Zuldazar. Make sure to call for her if she is not present when you get there. Progress: Do you think dat I'll get wings if I follow Pa'ku?",rewardItems={23022,116202,164965,167008,167009,167010,167011},starts={{npcID=145463}},mapCandidates={npc={},zone={}},questGiverID=145463,questType="standard",sourceQuests={53965},packageItems={241215}},
[53967] = {id=53967,name="The Frogmarsh",level=10,requiredLevel=10,faction="horde",categories={"seasonal"},flags={},sharable=false,event="Children's Week",expansion=7,storyline={53967},description="De caretakers are always telling us stories in de Hall of Castes. Sometimes dey warn us about danger, sometimes dey're about de loa... dere's usually a point to dem. One time, dey told us about Krag'wa, and how blood trolls killed his followers, and how he hasn't been seen since. But I heard dat he's back! He's in Nazmir again, and he's plotting his revenge against de blood trolls. Can we go see him?",objectivesText="Take Azala to Krag'wa's Burrow in the Frogmarsh in Nazmir. Make sure to call for her if she is not present when you get there. Progress: Where do loa go when dey don't have followers? I hope dey aren't too sad.",rewardItems={23022,116202,164965,167008,167009,167010,167011},starts={{npcID=145463}},mapCandidates={npc={},zone={}},questGiverID=145463,questType="standard",sourceQuests={53965},packageItems={241215}},
[53968] = {id=53968,name="The Shifting Pack",level=10,requiredLevel=10,faction="horde",categories={"seasonal"},flags={},sharable=false,event="Children's Week",expansion=7,storyline={53968},description="Dere's one loa I'm extra interested in seeing: Gonk! I've heard de priests say dat he's de most welcoming of de loa. He even lets his followers worship other loa as well! But de best thing about him is dat he and his followers can change into many forms. I want to do dat! Will you take me to meet him?",objectivesText="Take Azala to the Lair of Gonk at the Garden of the Loa in Zuldazar. Make sure to call for her if she is not present when you get there. Progress: Gonk's followers can turn into lots of different things. I think dey're pretty great.",rewardItems={23022,116202,164965,167008,167009,167010,167011},starts={{npcID=145463}},mapCandidates={npc={},zone={}},questGiverID=145463,questType="standard",sourceQuests={53965},packageItems={241215}},
[53969] = {id=53969,name="Hunting for Gold",level=10,requiredLevel=10,faction="horde",categories={"seasonal"},flags={},sharable=false,event="Children's Week",expansion=7,storyline={53969},description="I know dis trip is supposed to focus on de loa... But I want to see de island of gold! I heard stories of undead pirates and an island covered in gold coins and treasure! Can we go see it?! Pleeeease?",objectivesText="Take Azala to The Golden Isle in Vol'dun. Make sure to call for her if she is not present when you get there. Progress: An island made entirely of gold? I gotta see it!",rewardGold=202200,rewardXP=6140,rewardItems={23022,85500,116202,164965,167008,167009,167010,167011},starts={{npcID=145463}},mapCandidates={npc={},zone={}},questGiverID=145463,questType="standard",sourceQuests={53966,53967,53968},packageItems={241215}},
[53970] = {id=53970,name="The Sethrak Queen",level=10,requiredLevel=10,faction="horde",categories={"seasonal"},flags={},sharable=false,event="Children's Week",expansion=7,storyline={53970},description="De caretakers are always talking about how de sethrak attack caravans... but dey say dat de sethrak and de Zandalari used to be friends! I heard dat dere are some sethrak who still want to be friends, and dat dey have a loa who wants peace more dan anything! Can you take me to meet de sethrak and deir loa? I want to meet dem for myself!",objectivesText="Take Azala to the Terrace of the Devoted in Vol'dun. Make sure to call for her if she is not present when you get there. Progress: Do you think de sethrak queen is pretty? Do you think she has shinies?",rewardItems={23022,116202,164965,167008,167009,167010,167011},starts={{npcID=145463}},mapCandidates={npc={},zone={}},questGiverID=145463,questType="standard",sourceQuests={53966,53967,53968},packageItems={241215}},
[53971] = {id=53971,name="Return to the Hall of Castes",level=10,requiredLevel=10,faction="horde",categories={"seasonal"},flags={},sharable=false,event="Children's Week",expansion=7,storyline={53971},description="I can't believe I got to visit so many places. I've never even left Zuldazar before! I may be casteless, but now dat I've met so many loa, maybe I can follow one and have a future off of de streets. But for now, we should go back to de Hall of Castes. De caretakers must be waiting for me.",objectivesText="Take Azala back to the Hall of Castes in Zuldazar. Make sure to call for her if she is not present when you get there. Progress: Wait til de others hear about my trip!",rewardItems={23022,116202,164965,167008,167009,167010,167011,241215},starts={{npcID=131346},{npcID=150098},{npcID=150126},{npcID=150119},{npcID=150120}},ends={{npcID=131346}},mapCandidates={npc={},zone={}},questGiverID=131346,questTurnInID=131346,questType="standard",sourceQuests={53969,53970}},
[53973] = {id=53973,name="Ride Out to Meet Them",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53851,53852,53856,53879,53880,53912,53913,53973,53981},description="We must defend our warriors from the Alliance army while we recover this Azerite. Take the Azerite weapons you stole and load them onto one of these gyrocopters. Misha and I will ride out and fight the reinforcements from the ground, while you provide air support. We need to hold them off until our warriors can retreat with the Azerite.",objectivesText="Ride the Goblin Gyrocopter and fend off the Alliance army.",rewardGold=468000,rewardXP=8520,rewardItems={164987,165702,165734,166309},starts={{npcID=145422}},ends={{npcID=145422}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={53912},questLines={{id=838,name="Norwington Assault",orderIndex=8,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=838,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=838,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53974] = {id=53974,name="Druids of Gloomtide",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10058,storyline={53974},description="The latent power at Gloomtide Strand presents us with an opportunity to harness great power. One of our allies, Edgard, has great knowledge into what this might mean for our efforts. Seek him out and discover the power of nature.",objectivesText="Capture Gloomtide Strand, then speak with Edgard to learn what he has to offer. Progress: Discover anything?",starts={{npcID=145779}},ends={{npcID=145779}},mapCandidates={npc={},zone={10058}},questGiverID=145779,questTurnInID=145779,questType="standard",sourceQuests={53957}},
[53975] = {id=53975,name="Flying at Night",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10058,storyline={53975},description="Now that we control Ashwood Depot, it will be much more convenient to travel about the battlefield. I've drafted plans for a flight network. It's a rather brilliant plan, if I do say so myself. You don't seem busy. Take my notes and deliver them to our commander at once. Speak to Fidelio and he will provide you with a hippogryph.",objectivesText="Deliver Evenshade's Note to your commander in Bashal'Aran.",rewardItems={164991},starts={{npcID=144786}},ends={{npcID=144786}},mapCandidates={npc={},zone={10058}},questGiverID=144786,questTurnInID=144786,questType="standard",sourceQuests={53957}},
[53976] = {id=53976,name="Iron in Hand",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10058,storyline={53976},description="This won't work at all! We need to gather iron if we want to make any kind of headway against the Horde. Go down to the ruins at Lornesta and grab that iron . We need it!",objectivesText="Gather Iron from a nearby Ore Crate. Progress: We need to collect that iron !",rewardXP=3410,rewardItems={165659},rewardCurrencies={{id=1541,amount=10}},starts={{npcID=145770}},ends={{npcID=145770}},mapCandidates={npc={},zone={10058}},questGiverID=145770,questTurnInID=145770,questType="standard",sourceQuests={53977}},
[53977] = {id=53977,name="The War Chest",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10058,storyline={53977},description="Welcome to the warfront, <name>! We finally get to see some action. Any resources we've collected will go to the War Chest. Once enough has been gathered there, you can grab it! Why don't you pay it a visit and see what you get?",objectivesText="Collect resources from the War Chest in Bashal'Aran. Progress: Got any of those resources from the War Chest?",rewardCurrencies={{id=1541,amount=10}},starts={{npcID=145770}},ends={{npcID=145770}},mapCandidates={npc={},zone={10058}},questGiverID=145770,questTurnInID=145770,questType="standard"},
[53978] = {id=53978,name="Gunpowder Plots",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53887,53888,53896,53909,53910,53916,53919,53936,53978,53986,54518,54519,54559,54703,54787},description="Since the Lord Admiral iced all of their zeppelins, the Horde are rowing in through the seagate. The nice, narrow seagate entrance that makes for a great choke point. I'll have my people haul over a cannon and some ammunition. If you collect some gunpowder, we'll set up behind the gate where they won't expect the attack. We'll blast the Horde to the bottom of the harbor!",objectivesText="Collect 6 Kegs of Gunpowder. Progress: Did you find enough gunpowder?",rewardGold=234000,rewardXP=6815,rewardItems={164921,164968,166280,166682},rewardCurrencies={{id=1553,amount=350}},starts={{npcID=145593}},ends={{npcID=145593}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={53909,53916,54518,54519},questLines={{id=843,name="Beware the Daughter of the Sea",orderIndex=8,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=843,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=843,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[53979] = {id=53979,name="Naga Attack!",level=10,requiredLevel=10,faction="none",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={53979},objectivesText="Repel the naga invaders Captives freed Banners removed War Supplies destroyed",rewardXP=2125,rewardItems={165605,168003,168123},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{text="Repel the naga invaders",amount=1,type=15,objectID=0,orderIndex=0},{text="Captives freed",amount=34,type=0,objectID=145950,orderIndex=1},{text="Banners removed",amount=34,type=0,objectID=145974,orderIndex=2},{text="War Supplies destroyed",amount=34,type=0,objectID=145959,orderIndex=3}},worldTaskTitle="Naga Attack!",db2PoiMapID=1643,db2PoiUiMapID=896,db2QuestInfoID=111,db2QuestInfoName="Elite World Quest"},
[53981] = {id=53981,name="The Day is Won",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={53851,53852,53856,53879,53880,53912,53913,53973,53981},description="The majority of our warriors survived and we have the Alliance's Azerite and weapons. Be proud of yourself, <name>. You fought with honor today. Go and inform Nathanos of our victory here. The Azerite should reach them shortly.",objectivesText="Return to Nathanos Blightcaller on the Banshee's Wail.",rewardGold=23400,rewardXP=850,rewardItems={164987,165702,165734,166309},starts={{npcID=145422}},ends={{npcID=135691}},mapCandidates={npc={862,895},zone={8567}},questType="standard",sourceQuests={53973},questLines={{id=838,name="Norwington Assault",orderIndex=9,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=838,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=838,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[53982] = {id=53982,name="Supplies From The Unshackled",level=50,requiredLevel=50,faction="horde",categories={"emissary","paragon"},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={53982},description="Your aid has given us hope. Your courage has given us strength. You have given us an entirely new vision of our future, <name>. For that we will be forever grateful. I hope we can continue to repay you for all you have done!",objectivesText="Speak with Atolia Seapearl in Newhome for your reward.",rewardItems={169940},rewardCurrencies={{id=1553,amount=2500}},starts={{npcID=154002}},ends={{npcID=154002}},mapCandidates={npc={1355},zone={10052}},questGiverID=154002,questType="standard",worldSystems={paragonReputation={{factionID=2374,threshold=10000}}}},
[53983] = {id=53983,name="Wet Work: Fort Knight",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={53983},objectivesText="Speak with a Shadow Hunter Scout Target slain",rewardXP=2125,rewardItems={164731},mapCandidates={npc={},zone={8721}},questType="standard",db2Objectives={{text="Speak with a Shadow Hunter Scout",amount=1,type=3,objectID=147381,orderIndex=0},{text="Target slain",amount=1,type=0,objectID=147001,orderIndex=1}},worldTaskTitle="Wet Work: Fort Knight",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[53986] = {id=53986,name="The Calm Before",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53887,53888,53896,53909,53910,53916,53919,53936,53978,53986,54518,54519,54559,54703,54787},description="A word, <name>. There was a raid on the Norwington Estate, where we were testing some new designs of Azerite systems. Lady Jaina asked SI:7 to look into the matter. I have the report here. I know the Proudmoore family wants a moment together before they're pulled apart again, but the war is still ongoing. You have been a friend to her family. Take the report to Jaina. I believe they went to pay respects at the family memorial.",objectivesText="Take the SI:7 report to Lady Jaina Progress: The Horde cannot be allowed to think it can come to our lands without resistence.",rewardGold=23400,rewardXP=1705,rewardItems={158075,164921,164968,166280,166682,197649,197650,197651,197652},starts={{npcID=135614}},ends={{npcID=145580}},mapCandidates={npc={895,1161},zone={8568}},questType="standard",sourceQuests={53098},questLines={{id=843,name="Beware the Daughter of the Sea",orderIndex=0,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=843,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=843,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=1161},
[53988] = {id=53988,name="Shores of Fate",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=1519,mapID=84,storyline={53847,53849,53988,53989,53990,53992,54006,54041,54871},description="So be it. You are more trustworthy an ally than any army Wrynn would have sent. We will reclaim Darkshore together, but first we must find Tyrande. Without her at the front, our forces will crumble against the Horde. She left for the Zoram Strand with a small force not long ago. If we move now, we may be able to find her before the Horde does.",objectivesText="Take the Stormwind portal to Darnassus and meet Maiev Shadowsong at the Zoram Strand in Ashenvale.",rewardGold=23400,rewardXP=850,rewardItems={18230,113364,165232,165233,165250},starts={{npcID=146050}},ends={{npcID=146373}},mapCandidates={npc={62,84},zone={1519}},questType="standard",sourceQuests={53849},questLines={{id=797,name="In Darkest Night",orderIndex=2,flags=0}},db2PoiMapID=1,db2PoiUiMapID=63},
[53989] = {id=53989,name="Hope",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=331,mapID=62,storyline={53847,53849,53988,53989,53990,53992,54006,54041,54871},description="No... it is not possible. She would not have died like this! Search for signs of her departure along the strand. Personal effects. Weapons. Anything! Tyrande is still out there, <name>. We must not lose hope.",objectivesText="Search for signs of Tyrande. Progress: Anything?",rewardGold=234000,rewardXP=6815,rewardItems={11475,13444,13446,28168,28169,28172,28173,28175,57247,59741,59742,59743,59744,59745,59746,131717,140235,140244,155117,155118,155119,155120,155158,158667,159124,159152,159153,159154,159155,165232,165233,165250,166525,168436,168573,175713,175740,177633,177634,177646,177648,177650,177651,177652,179532,179562,181402,181407,181408,181409,181410,181429,181458,181477,181479,181541,183486,184378,184381,184382,184383,184384,184487,184519,194338,194381,194382,194383,206350,206960,208047,208067,209900,210180,210774,210916,211131,219459,219920,237864,237869,237877,237885,242713,246863,246936,249400,251719,251720,251721,251722,253035,253443,254267,254579,258264,260450,260451,263467,265995},starts={{npcID=146374}},ends={{npcID=146374}},mapCandidates={npc={62},zone={331}},questType="standard",sourceQuests={53988},questLines={{id=797,name="In Darkest Night",orderIndex=3,flags=0}},db2PoiMapID=1,db2PoiUiMapID=63},
[53990] = {id=53990,name="In Darkest Night",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=331,mapID=62,storyline={53847,53849,53988,53989,53990,53992,54006,54041,54871},description="<name>, I will not mince words. Tyrande foolishly risks her life with the ritual she intends to perform. If she falls, our entire war effort will fall with her. We must set off for Darkshore and come to her aid. Only then can we march forward and reclaim our homeland. We have lost Teldrassil. Fool or not, our people cannot afford to lose Tyrande as well.",objectivesText="Find Tyrande in Darkshore and lend her aid.",rewardGold=468000,rewardXP=8520,rewardItems={165232,165233,165250},starts={{npcID=146373}},ends={{npcID=149612}},mapCandidates={npc={62,1161},zone={331}},questType="standard",sourceQuests={53989,54041},questLines={{id=797,name="In Darkest Night",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[53992] = {id=53992,name="Warfront: The Battle for Darkshore",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53847,53849,53988,53989,53990,53992,54006,54041,54871},description="We will not tolerate further Horde aggression in our territories. The night elves will not stand alone this day. Darkshore will be theirs once more. For the Alliance!",objectivesText="Defeat the Horde at the Battle for Darkshore. Progress: Darkshore will be ours.",rewardGold=468000,rewardXP=8520,rewardItems={158075,166369,166370},rewardCurrencies={{id=1717,amount=15},{id=1553,amount=750}},starts={{npcID=142721}},ends={{npcID=142721}},mapCandidates={npc={1161},zone={8568}},questType="standard",questLines={{id=797,name="In Darkest Night",orderIndex=7,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[53993] = {id=53993,name="A Voice on the Wind",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={53993,54005},description="<A distant, mysterious voice fills your mind.> My enchantments are not lost... Find me... Drustvar... Fallhaven...",objectivesText="Seek out the source of the mysterious voice in Drustvar.",rewardGold=25740,rewardXP=175,rewardItems={152668,152876,152877,164766,168125,168126,168127},starts={{npcID=147014}},ends={{npcID=146053}},mapCandidates={npc={896},zone={8721}},questGiverID=147014,questType="standard",sourceQuests={54005},questLines={{id=909,name="8.1.5 Enchanting - Alliance",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[53994] = {id=53994,name="Naga Attack!",level=10,requiredLevel=10,faction="none",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={53994},objectivesText="Repel the naga invaders Prisoners freed Banners removed War supplies destroyed",rewardXP=2125,rewardItems={165605,168003,168123},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{text="Repel the naga invaders",amount=1,type=15,objectID=0,orderIndex=0},{text="Prisoners freed",amount=34,type=0,objectID=146055,orderIndex=1},{text="Banners removed",amount=34,type=0,objectID=146056,orderIndex=2},{text="War supplies destroyed",amount=34,type=0,objectID=146057,orderIndex=3}},worldTaskTitle="Naga Attack!",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=111,db2QuestInfoName="Elite World Quest"},
[53995] = {id=53995,name="The Tauren Tanner",level=50,requiredLevel=50,faction="horde",requiredProfessions={"leatherworking"},categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={53995,55216,55221,55222,55223},description="Hey, rich mon. One of ya Tauren stopped by and asked who was de best leatherworker I knew who doesn't mind gettin' their hands dirty. I give 'im ya name, and he asked for an introduction. Said dat he would be in de Bazaar, by de docks. He did not say what he needed ma best student for, but de way he was actin' makes me think it is somedin' big. Head on down to de docks and find dis Tauren. Show 'im what I taught ya. And focus! Needn't be havin' ya make me look bad!",objectivesText="Meet the Tauren Leatherworker in the Port of Zandalar.",rewardGold=23400,rewardXP=850,starts={{npcID=122698}},ends={{npcID=151162}},mapCandidates={npc={1165},zone={8670}},questType="standard",questLines={{id=908,name="8.1.5 Leatherworking - Horde",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[53996] = {id=53996,name="Pick Up Sticks",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={53996,53997,53998,53999,54000,54001,54002},description="In order for my enchantment to work, we'll need wood from these forests. When I was alive, I would wander these woods and tend to the trees. While those trees are long gone, perhaps their grandseeds have heard their stories and would be willing to help me. But don't cut down any of the trees! Please! There are loggers that cut and hew without care for the wilds. Take their hard work so that they will think twice before felling another tree. Bring me as much wood as you can muster.",objectivesText="Collect 9 Bundles of Hard Wood Progress: I miss the voices of the old forest.",rewardGold=257400,rewardXP=1415,rewardItems={152668,152876,152877,164766,164979,168125,168126,168127},starts={{npcID=146053}},ends={{npcID=146053}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={53993,55635},questLines={{id=911,name="8.1.5 Enchanting - Alliance/Horde",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[53997] = {id=53997,name="The Sixth Sense",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={53996,53997,53998,53999,54000,54001,54002},description="For my plan to work, we need to break the spell on my body that is anchoring my spirit to this place. However, my mortal remains are buried deep within this forest. There are wards within it that are designed to trap spirits who are still attached to the material world. Once my remains are cleansed, I will be able to move freely through the woods. Until then, I'll need you to disenchant the wards we come across. Speak to me when you are ready, and I will lead you to my grave.",objectivesText="Escort Sef Iwen to her grave.",rewardGold=257400,rewardXP=1415,rewardItems={152668,152876,152877,164766,168125,168126,168127},starts={{npcID=146053}},ends={{npcID=146091}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={53996},questLines={{id=911,name="8.1.5 Enchanting - Alliance/Horde",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[53998] = {id=53998,name="Exhumed",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={53996,53997,53998,53999,54000,54001,54002},description="As I've said, I'm unable to interact with the material world. I am able to dominate a creature to control its body, but I find it deplorable. In essence, it is enslaving the poor creature. What I want is a body of my own. If you build and animate a golem, it would be devoid of intelligence. A shell. One that I could inhabit without issue. Doing so will require that my soul is not anchored to anything else in this world, so I need you to remove the spell binding my spirit to my physical remains.",objectivesText="Cleanse Sef Iwen 's remains. Progress: Seeing my old self brings back memories.",rewardGold=25740,rewardXP=175,rewardItems={152668,152876,152877,164766,168125,168126,168127},starts={{npcID=146091}},ends={{npcID=146091}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={53997},questLines={{id=911,name="8.1.5 Enchanting - Alliance/Horde",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[53999] = {id=53999,name="The Threads That Bind",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={53996,53997,53998,53999,54000,54001,54002},description="Our destination is near Gol Koval, but there is something else you could pick up along the way. I don't want to ask because I hate them, but you cannot dispute the resilience of that horrible webbing that they manage to get everywhere. <Sef grimaces at the thought.> There are spiders to the southeast. As a guardian of nature, I don't want to say kill them, but if you could... 'obtain' some fresh silk from their bodies, we could use it to bind the limbs of the golem together.",objectivesText="Collect 55 Durable Spider Silk . Progress: Did you get the silk?",rewardGold=257400,rewardXP=1415,rewardItems={152668,152876,152877,164766,164985,168125,168126,168127},starts={{npcID=146091}},ends={{npcID=146093}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={53998},questLines={{id=911,name="8.1.5 Enchanting - Alliance/Horde",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[54000] = {id=54000,name="The Beat Goes On",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={53996,53997,53998,53999,54000,54001,54002},description="We have most of the materials we need, but we require one final item. A heart. Don't worry. I don't mean one of flesh, but of stone; to bind the materials of the body into a single form. Find a smooth stone, and enchant it to hold a life force. It will require some reagents, but I would expect a powerful enchanter such as yourself to have some on hand or know where to find them. Once that's done, it will need to be powered. The souls animating the elementals and undead here should do the trick.",objectivesText="Create a runic power core and charge it from the corpses of Awoken Guardians and Vengeful Bones.",rewardGold=257400,rewardXP=1415,rewardItems={152668,152876,152877,164766,165022,165023,168125,168126,168127},starts={{npcID=146093}},ends={{npcID=146094}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={53999},questLines={{id=911,name="8.1.5 Enchanting - Alliance/Horde",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[54001] = {id=54001,name="We're Going In",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={53996,53997,53998,53999,54000,54001,54002},description="This used to be a Drust shrine. There is a series of sigils that, once invoked, will allow us to teleport to my old sanctum. <Sef looks around somewhat confused and clears her throat.> It has been centuries since I've been here, I'm having a bit of trouble remembering the order in which the sigils need to be activated to open the portal. I hope you're feeling adventurous. Oh, and be cautious. I enchanted the runes to keep would be intruders out by force.",objectivesText="Activate the teleportation runes to enter Sef's Retreat.",rewardGold=25740,rewardXP=175,rewardItems={3316,37223,37391,37427,37507,61517,61518,61519,61520,61521,61522,63151,63152,63153,63154,63155,84281,84282,84283,84284,84285,121440,121441,121442,121443,131530,131531,132936,141386,152668,152876,152877,164766,168125,168126,168127,169903,175713,175728,175740,179562,181398,181411,181412,181413,181457,181458,181459,181477,181479,181541,182559,184378,184381,184382,184383,184384,184519,246458,248583,251783,251784,251786,251788,251791,259085,259896,269010,274069,274070,274071},starts={{npcID=146094}},ends={{npcID=152255}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={54000},questLines={{id=911,name="8.1.5 Enchanting - Alliance/Horde",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[54002] = {id=54002,name="Putting It All Together",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={53996,53997,53998,53999,54000,54001,54002},description="Hmm... Everything seems untouched. We can begin construction of my new body over here. Afterwards, I'll teach you how to make my enchanting rod. <Sef smiles at you, beaming with joy.>",objectivesText="Assemble the golem for Sef Iwen . Progress: This has been a long time coming.",rewardGold=514800,rewardXP=1770,rewardItems={55924,55925,55926,55927,55928,55929,152668,152876,152877,164766,168125,168126,168127,180935,181377,181572,181573,181581,181599,181609,181610,181703,181843,181866,182127,182385,182470,182667,183132,183480,183506,184294,184362,184363,184766,184767,184768,184839},starts={{npcID=152255}},ends={{npcID=152255}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={54001},questLines={{id=911,name="8.1.5 Enchanting - Alliance/Horde",orderIndex=6,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[54005] = {id=54005,name="What the Drust Knew",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=895,storyline={53993,54005},description="Ahoy, <name>! If you have a moment, I could use your assistance. I've recently received a large shipment of Drust relics that I've been processing. Most of them have been nothing out of the ordinary, but there is this one that is special. Just holding it makes my hair stand on end. With you being my best pupil, I was thinking that it would be fun if we disenchanted it together, to see how it was made. What do you say?",objectivesText="Carefully remove the enchantment from the Ancient Drust relic to learn about its construction.",rewardGold=23400,rewardXP=850,rewardItems={152668,152876,152877,164766,168125,168126,168127},starts={{npcID=136041}},ends={{npcID=136041}},mapCandidates={npc={},zone={8568}},questGiverID=136041,questTurnInID=136041,questType="standard",questLines={{id=909,name="8.1.5 Enchanting - Alliance",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[54006] = {id=54006,name="A New Hope",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=148,mapID=62,storyline={53847,53849,53988,53989,53990,53992,54006,54041,54871},description="Darkshore belongs to our people once more, in no small part due to your efforts. And, while I disagree with her methods, we would not have succeeded without Tyrande as well. Differences aside, she is our leader--and an incarnation of the Night Warrior herself. She is about to begin. You may stand here beside me.",objectivesText="Witness Tyrande's address to the kaldorei.",rewardGold=117000,rewardXP=3410,rewardItems={166525,219459,258264},starts={{npcID=149418},{npcID=149662},{npcID=149659}},ends={{npcID=147255}},mapCandidates={npc={62},zone={148}},questType="standard",sourceQuests={54871},questLines={{id=797,name="In Darkest Night",orderIndex=8,flags=0}},db2PoiMapID=1,db2PoiUiMapID=62},
[54007] = {id=54007,name="Insurance Policy",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53941,53942,54004,54007,54008,54009,54022,54028,54094,54123,54124,54128,54635},description="Mekkatorque called us idiots, can you believe that? Well, if I'm an idiot, then why did I buy an insurance policy on my mech, huh? I bet that radioactive dimwit doesn't have an insurance policy on HIS mech! We're gonna be outta here in no time. I just gotta give a quick call for roadside assistance to come out and fix this thing up. I need you to go hit the button for roadside assistance on my mech. Just, uh, don't hit the wrong one.",objectivesText="Activate the roadside assistance button on the G.M.O.D. Progress: You gonna call these guys up or what?",rewardGold=23400,rewardXP=850,rewardItems={164987,165702,165734,166309},starts={{npcID=146073}},ends={{npcID=146073}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={54004},questLines={{id=839,name="Adventures of Gallywix and the G.M.O.D.",orderIndex=6,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=839,questLineOrder=16,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=839,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[54008] = {id=54008,name="Insurance Renewal",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53941,53942,54004,54007,54008,54009,54022,54028,54094,54123,54124,54128,54635},description="You know, all I wanna do is blow up Mekkatorque and whatever airship he's ridin' in. Of course it ain't gonna be easy! I need you to go rescue my roadside assistance so they can fix this mech! They're probably in the Alliance camp near here. Meanwhile, I'm gonna cook us up a plan. We're gonna give Mekkatorque a real nice surprise! And by real nice surprise, I mean we're gonna blow him up. Oh, and also his airship.",objectivesText="Rescue Gallywix's Roadside Assistance",rewardGold=234000,rewardXP=6815,rewardItems={164987,165702,165734,166309},starts={{npcID=146073}},ends={{npcID=146073}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={54007},questLines={{id=839,name="Adventures of Gallywix and the G.M.O.D.",orderIndex=7,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=839,questLineOrder=16,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=839,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[54009] = {id=54009,name="Killing on the Side",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53941,53942,54004,54007,54008,54009,54022,54028,54094,54123,54124,54128,54635},description="Those annoying Alliance nearby are definitely takin' orders from Mekkatorque. That means they gotta die! And any of their Kul Tiran friends, too. They gotta know the Horde is number one. And that you don't kidnap someone's roadside assistance!",objectivesText="Kill 15 Alliance and Kul Tiran soldiers in Vigil Hill.",rewardGold=234000,rewardXP=6815,rewardItems={164987,165702,165734,166309},starts={{npcID=146073}},ends={{npcID=146073}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={54007},questLines={{id=839,name="Adventures of Gallywix and the G.M.O.D.",orderIndex=8,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=839,questLineOrder=16,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=839,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[54011] = {id=54011,name="Wet Work: Arom's Stand",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={54011},objectivesText="Speak with a Shadow Hunter Scout Target slain",rewardXP=2125,mapCandidates={npc={},zone={8499}},questType="standard",db2Objectives={{text="Speak with a Shadow Hunter Scout",amount=1,type=3,objectID=147381,orderIndex=0},{text="Target slain",amount=1,type=0,objectID=144892,orderIndex=1}},worldTaskTitle="Wet Work: Arom's Stand",db2PoiMapID=1643,db2PoiUiMapID=896,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[54012] = {id=54012,name="Fortunate Souls",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={54012,54015,54018,54021,55053,55054,55092,55094,55481,56063,56429},description="$p, I am glad to see that you survived the wreck. Many were not as fortunate... I am capable of stalling the enemy here for now, but this position is not defensible long term. We need to find somewhere safe for our forces. Once we have taken measure of the wounded we will push on. In the meantime, find as many survivors as you can. Nazjatar will claim no more Horde lives today!",objectivesText="Rescue 7 captive soldiers in Spears of Azshara. Progress: Save as many as you can. We are sorely outnumbered here.",rewardGold=234000,rewardXP=6815,starts={{npcID=150196}},ends={{npcID=150196}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={54021},questLines={{id=886,name="Azshara's Trap",orderIndex=4,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=4,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=886,questLineOrder=23,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1718,db2PoiUiMapID=1355},
[54014] = {id=54014,name="Wet Work: Blood in the Sand",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={54014},objectivesText="Speak with an SI:7 Infiltrator Target slain",rewardXP=2125,mapCandidates={npc={},zone={8499}},questType="standard",db2Objectives={{text="Speak with an SI:7 Infiltrator",amount=1,type=3,objectID=147369,orderIndex=0},{text="Target slain",amount=1,type=0,objectID=144892,orderIndex=1}},worldTaskTitle="Wet Work: Blood in the Sand",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[54015] = {id=54015,name="In Deep",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=10052,mapID=1355,description="I can keep this barrier up here for a time after our departure, but we cannot remain here. These soldiers will not be safe for long. We must go deeper into this place to seek a more defensible position.",rewardGold=23400,rewardXP=850,starts={{npcID=150196}},ends={{npcID=150196}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={54012,55092,56063},questLines={{id=886,name="Azshara's Trap",orderIndex=6,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=7,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=886,questLineOrder=23,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},
[54016] = {id=54016,name="Azerite Transport",level=10,requiredLevel=10,faction="horde",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={54016},objectivesText="Azerite shipment secured",rewardXP=2125,starts={{npcID=145391,mapID=862,x=0.7733,y=0.3737}},mapCandidates={npc={},zone={8721}},questType="standard",db2Objectives={{text="Azerite shipment secured",amount=1,type=2,objectID=313780,orderIndex=1}},worldTaskTitle="Azerite Transport",db2PoiMapID=1642,db2PoiUiMapID=862,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3466,db2VignetteName="Caravan Leader"},
[54017] = {id=54017,name="Wet Work: Warbeast Kraal",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={54017},objectivesText="Speak with an SI:7 Infiltrator Target slain",rewardXP=2125,mapCandidates={npc={},zone={8499}},questType="standard",db2Objectives={{text="Speak with an SI:7 Infiltrator",amount=1,type=3,objectID=147369,orderIndex=0},{text="Target slain",amount=1,type=0,objectID=144892,orderIndex=1}},worldTaskTitle="Wet Work: Warbeast Kraal",db2PoiMapID=1642,db2PoiUiMapID=862,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[54018] = {id=54018,name="Descent",level=50,requiredLevel=50,faction="horde",sharable=false,expansion=7,zoneID=10052,mapID=1355,description="What has transpired! That is to say, what has transpired?! Yes, that is the appropriate response, is it not? I find our circumstances enthralling! Yet, tragic. I prattle on... Yes, Lor'themar asked me to send you to him at once. He is in need of your expertise, $p. I'll lower you down the falls safely. Good luck!",rewardGold=30900,rewardXP=850,starts={{npcID=150206}},ends={{npcID=150207}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55054},questLines={{id=886,name="Azshara's Trap",orderIndex=1,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=2,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=886,questLineOrder=23,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},
[54020] = {id=54020,name="Wet Work: Gloomwater Span",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={54020},objectivesText="Speak with an SI:7 Infiltrator Target slain",rewardXP=2125,mapCandidates={npc={},zone={8499}},questType="standard",db2Objectives={{text="Speak with an SI:7 Infiltrator",amount=1,type=3,objectID=147369,orderIndex=0},{text="Target slain",amount=1,type=0,objectID=144892,orderIndex=1}},worldTaskTitle="Wet Work: Gloomwater Span",db2PoiMapID=1642,db2PoiUiMapID=863,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[54021] = {id=54021,name="The First Arcanist",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={54012,54015,54018,54021,55053,55054,55092,55094,55481,56063,56429},description="Our situation is dire, $p. The Horde fleet was decimated by the attack on Dazar'alor. This naga trap has claimed much of what we had left. Survivors report seeing the naga taking captives. Thalyssra has gone on ahead to see what she can do to help them. I will finish up here while you aid the First Arcanist's efforts. My rangers will provide what little aid they can.",objectivesText="Meet with First Arcanist Thalyssra in Nazjatar .",rewardGold=154900,rewardXP=3410,starts={{npcID=150207}},ends={{npcID=150196}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={54018},questLines={{id=886,name="Azshara's Trap",orderIndex=2,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=3,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=886,questLineOrder=23,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1718,db2PoiUiMapID=1355},
[54022] = {id=54022,name="Mekkatorque's Battle Plans",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53941,53942,54004,54007,54008,54009,54022,54028,54094,54123,54124,54128,54635},description="<You find part of plans that indicate where Mekkatorque will be in Tiragarde Sound, along with his airship. If you could find the other half of these plans, you would be able to launch an ambush against the gnomish king.>",objectivesText="Recover Mekkatorque's Battle Plans Progress: What're you lookin' into?",rewardGold=234000,rewardXP=6815,rewardItems={164987,164989,165702,165734,166309},ends={{npcID=146073}},coords={mapID=895,source="quest_giver",x=0.546,y=0.645},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={54007},questLines={{id=839,name="Adventures of Gallywix and the G.M.O.D.",orderIndex=9,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=839,questLineOrder=16,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=839,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895,startItems={164987}},
[54026] = {id=54026,name="Job's Done",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=4922,mapID=241,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="I'll stick around here a bit longer to ensure the peons get back to work. You should return to Orgrimmar and let Commander Dresh know that he does not need to fret about the outpost any longer.",objectivesText="Return to Commander Dresh at Grommash Hold in Orgrimmar.",rewardGold=31200,rewardXP=685,rewardItems={173727,174066},starts={{npcID=163489}},ends={{npcID=145532}},mapCandidates={npc={85,241},zone={4922}},questType="standard",sourceQuests={53898},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=10,flags=0}},db2PoiMapID=1,db2PoiUiMapID=85},
[54027] = {id=54027,name="Threat Contained",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=1637,mapID=85,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="That should keep those naga down! You can have the honor of telling Bladeguard Sonji that the threat to Zuldazar's coast has been contained.",objectivesText="Return to Bladeguard Sonji at Grommash Hold in Orgrimmar.",rewardGold=34100,rewardXP=685,rewardItems={173727,174066},starts={{npcID=145980}},ends={{npcID=145533}},mapCandidates={npc={85},zone={1637}},questGiverID=145980,questType="standard",sourceQuests={53902},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=16,flags=0}},db2PoiMapID=1,db2PoiUiMapID=85},
[54028] = {id=54028,name="Mech versus Airship",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53941,53942,54004,54007,54008,54009,54022,54028,54094,54123,54124,54128,54635},description="We're all set to go, thanks to them battle plans ya found. Looks like Mekko ain't gonna be at his airship right now. Here's the plan. We're gonna go seriously mess up his ship, then Mekko is gonna swing by to try to save his friends. But instead, he's gonna find you and me standin' on the deck of his burnin' ship, waitin' to take him out! Get in to the mech, <name>, we're blowin' up an airship and a gnome!",objectivesText="Ride the G.M.O.D to blow up an Alliance airship and confront Mekkatorque.",rewardGold=468000,rewardXP=8520,rewardItems={164987,165702,165734,166309},rewardCurrencies={{id=1553,amount=750}},starts={{npcID=146073}},ends={{npcID=146623}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={54008,54009,54022},questLines={{id=839,name="Adventures of Gallywix and the G.M.O.D.",orderIndex=10,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=839,questLineOrder=16,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=839,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[54031] = {id=54031,name="Gaze of the Loa: Krag'wa",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53719,53823,53824,53825,53826,53827,53828,53830,53831,54031,54032,54033,54034,54300,54301,54419,54925},description="Hello again, small one. I see Talanji has chosen a worthy witness. I must test Talanji's willingness to sacrifice for her people. I will weigh her commitment to defending the weak. Many great rulers have failed this challenge and still gone on to make powerful monarchs. But the most beloved, those that find themselves surrounded by loyal followers, always understand the value of devotion to their people. You will help me with this trial. Speak to me when you are ready to begin.",objectivesText="\"Witness\" Krag'wa's trial. Progress: It is my hope that Talanji will honor your faith in her this day.",rewardGold=312800,rewardXP=5465,starts={{npcID=146208}},ends={{npcID=146208}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={53828},questLines={{id=919,name="Allies of the Horde: Zandalari",orderIndex=11,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[54032] = {id=54032,name="Gaze of the Loa: Pa'ku",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53719,53823,53824,53825,53826,53827,53828,53830,53831,54031,54032,54033,54034,54300,54301,54419,54925},description="Two more loa have declared their intent to test Talanji. The next is Pa'ku . She awaits you both at the top of these steps. I need not warn you about her tempestuous nature, nor her love for watching others fall from great heights. Good luck, <name>.",objectivesText="Complete Pa'ku 's trial. Progress: I am not yet satisfied, <name>.",rewardGold=312800,rewardXP=5465,starts={{npcID=146214}},ends={{npcID=146209}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={54033},questLines={{id=919,name="Allies of the Horde: Zandalari",orderIndex=13,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[54033] = {id=54033,name="Gaze of the Loa: Gonk",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53719,53823,53824,53825,53826,53827,53828,53830,53831,54031,54032,54033,54034,54300,54301,54419,54925},description="The Lord of the Pack has requested to be the next to speak to Talanji. He is just up the steps on the next terrace. I do not think he will require quite as much of you as I did, but I believe his words will be relevant to your purposes here. <Krag'wa winks one massive eye.> Do not think we are not aware of your intentions, <name>.",objectivesText="Complete Gonk 's trial. Progress: Hello again, <name>.",rewardGold=154900,rewardXP=2735,starts={{npcID=146208}},ends={{npcID=146214}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={54031},questLines={{id=919,name="Allies of the Horde: Zandalari",orderIndex=12,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[54034] = {id=54034,name="Gaze of the Loa: Bwonsamdi",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53719,53823,53824,53825,53826,53827,53828,53830,53831,54031,54032,54033,54034,54300,54301,54419,54925},description="< Pa'ku 's levity subsides.> Ordinarily the final trial would be given by Rezan. But the loa of kings is no more. It seems ol' Rastakhan picked a new favorite to take his place. < Pa'ku sneers.> Enjoy that. Bwonsamdi waits for you in the temple.",objectivesText="Complete Bwonsamdi 's trial.",rewardGold=154900,rewardXP=2735,starts={{npcID=146209}},ends={{npcID=145359}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={54032},questLines={{id=919,name="Allies of the Horde: Zandalari",orderIndex=14,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[54036] = {id=54036,name="A Particular Process",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=7637,mapID=680,storyline={53870,53889,53890,53891,53892,53893,53894,53895,53897,53898,53899,53900,53901,53902,53903,53904,53905,53906,53907,53908,54026,54027,54036,57448,58087},description="As you might have noticed, Vintner Iltheux is very particular about his wine making process, but his ancient recipe was crafted with only the Nightborne in mind. We need something different to please the diverse palates of the Horde! Talk to Nomi and see what he has in mind to spice things up.",objectivesText="Speak to Nomi .",rewardGold=31200,rewardXP=685,rewardItems={173727,174066},starts={{npcID=157668}},ends={{npcID=146301}},mapCandidates={npc={680},zone={7637}},questType="standard",sourceQuests={53905},questLines={{id=796,name="Allies of the Horde: Vulpera",orderIndex=20,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=680},
[54041] = {id=54041,name="No Survivors",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=331,mapID=62,storyline={53847,53849,53988,53989,53990,53992,54006,54041,54871},description="Do you see the encampment on the beach below? The Horde followed Tyrande here. No doubt some of them have remained here in the shadows in case she returned. Kill them.",objectivesText="Kill 8 Veiled Deathstalkers . Progress: The Horde will pay the ultimate price for crossing the kaldorei.",rewardGold=234000,rewardXP=6815,rewardItems={23389,25778,25779,25780,165232,165233,165250},starts={{npcID=146375}},ends={{npcID=146375}},mapCandidates={npc={62},zone={331}},questType="standard",sourceQuests={53988},questLines={{id=797,name="In Darkest Night",orderIndex=4,flags=0}},db2PoiMapID=1,db2PoiUiMapID=63},
[54042] = {id=54042,name="Trouble in Darkshore",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10226,mapID=1165,storyline={53955,54042,54043,54044,54045,54046,54047,54049,54050,54059,54416},description="We have received some disturbing reports from Darkshore . What was once a secure stronghold for the Horde is now beset by an unnatural darkness. The moon has turned completely black. The outposts there have yet to be reinforced with our main force and we are suddenly outnumbered. Nathanos wants you to meet him in Darkshore and find out what happened.",objectivesText="Speak with Dread-Admiral Tattersail to travel to Darkshore and report to Nathanos. Progress: Have you traveled to Darkshore ?",rewardGold=23400,rewardXP=850,starts={{npcID=149471}},ends={{npcID=149471}},mapCandidates={npc={1165},zone={8670}},questTurnInID=149471,questType="standard",questLines={{id=856,name="In Darkest Night",orderIndex=0,flags=0}},db2PoiMapID=2129,db2PoiUiMapID=1333},
[54043] = {id=54043,name="Dark Ranger Round-Up",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10226,mapID=1333,storyline={53955,54042,54043,54044,54045,54046,54047,54049,54050,54059,54416},description="These night elf ambushes have left us undermanned. We need reinforcements if we are to hold Darkshore . Brynja, one of the Dark Lady's val'kyr, can provide us with those reinforcements. Slay the night elves and command her to raise them into our service. Should any prove unwilling... deal with them. Did I not make myself clear? Go. The Dark Lady has plans for these dark rangers.",objectivesText="Slay Vindictive Sentinels and Archers and command Brynja to raise them as Dark Rangers.",rewardGold=234000,rewardXP=6815,rewardItems={166544},starts={{npcID=146323}},ends={{npcID=146323}},mapCandidates={npc={},zone={10226}},questGiverID=146323,questTurnInID=146323,questType="standard",sourceQuests={54042},questLines={{id=856,name="In Darkest Night",orderIndex=2,flags=0}},db2PoiMapID=2129,db2PoiUiMapID=1333},
[54044] = {id=54044,name="Black Moon Rising",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10226,mapID=1333,storyline={53955,54042,54043,54044,54045,54046,54047,54049,54050,54059,54416},description="Darkshore has never been known for being bright and sunny, but something strange has happened here. A black moon hangs over everything. None of the scouts I sent into the forest have returned. The night elves are up to something. And I need to know what it is. Their rank-and-file won't have the information we seek. Hunt down their lieutenants and get them to talk by any means necessary.",objectivesText="Interrogate Lieutenants Golras, Ivyth, and Maliyra. Progress: <The wisp appears lost and disoriented. It follows you.>",rewardGold=234000,rewardXP=6815,starts={{npcID=146323}},ends={{npcID=146323}},mapCandidates={npc={},zone={10226}},questGiverID=146323,questTurnInID=146323,questType="standard",sourceQuests={54042},questLines={{id=856,name="In Darkest Night",orderIndex=1,flags=0}},db2PoiMapID=2129,db2PoiUiMapID=1333},
[54045] = {id=54045,name="Quit Vining!",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10226,mapID=1333,storyline={53955,54042,54043,54044,54045,54046,54047,54049,54050,54059,54416},description="This is terrible, <name>! We got harvesters that ain't harvestin'! We've been busting our rumps chopping down all these trees, but someone keeps tangling up our machines in the vines! I ain't going out there with those night elves stalkin' around. See if you can get in there and free up my equipment!",objectivesText="Free Goblin Harvesters from vines.",rewardGold=234000,rewardXP=6815,starts={{npcID=146325}},ends={{npcID=146325}},mapCandidates={npc={},zone={10226}},questGiverID=146325,questTurnInID=146325,questType="standard",sourceQuests={54042},questLines={{id=856,name="In Darkest Night",orderIndex=3,flags=0}},db2PoiMapID=2129,db2PoiUiMapID=1333},
[54046] = {id=54046,name="We're Not Out of the Woods Yet",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10226,mapID=1333,storyline={53955,54042,54043,54044,54045,54046,54047,54049,54050,54059,54416},description="<The wisp flickers at you in a confused manner. It seems to want to follow you. Perhaps it has the information Nathanos seeks.>",objectivesText="Bring the Lost Wisp to Nathanos Blightcaller in Lor'danel Landing. Progress: Have you found anything useful?",rewardGold=23400,rewardXP=850,starts={{npcID=146536}},mapCandidates={npc={},zone={10226}},questGiverID=146536,questType="standard",sourceQuests={54044},questLines={{id=856,name="In Darkest Night",orderIndex=4,flags=0}},db2PoiMapID=2129,db2PoiUiMapID=1333},
[54047] = {id=54047,name="Where Hope Dies",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10226,mapID=1333,storyline={53955,54042,54043,54044,54045,54046,54047,54049,54050,54059,54416},description="We must carry out the Dark Lady's orders before we are overrun by these newly-invigorated elves. There is one night elf in particular that we seek. You may remember her from our last venture into Darkshore . Lucky for you, she is already dead... so she should prove less troublesome than the living ones you've already encountered. Signal me when you find her corpse.",objectivesText="Find the body of Delaryn Summermoon. Progress: Have you found her yet?",rewardGold=234000,rewardXP=6815,starts={{npcID=146323}},ends={{npcID=146323}},mapCandidates={npc={},zone={10226}},questGiverID=146323,questTurnInID=146323,questType="standard",sourceQuests={54059},questLines={{id=856,name="In Darkest Night",orderIndex=6,flags=0}},db2PoiMapID=2129,db2PoiUiMapID=1333},
[54048] = {id=54048,name="To Kill A Warden",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10226,mapID=1333,storyline={54048},description="See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(54048)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(54048))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Defeat Sira Moonwarden .",mapCandidates={npc={},zone={10226}},questType="standard"},
[54049] = {id=54049,name="The Dead of Night",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10226,mapID=1333,storyline={53955,54042,54043,54044,54045,54046,54047,54049,54050,54059,54416},description="This is the crux of the Dark Lady's plan for Darkshore . We will raise new champions for the Forsaken and the Horde on this very spot. Guard the val'kyr. We cannot allow anything or anyone to interrupt them.",objectivesText="Protect the val'kyr as they resurrect Delaryn and Sira.",rewardGold=468000,rewardXP=6815,starts={{npcID=147187}},ends={{npcID=147187}},mapCandidates={npc={},zone={10226}},questGiverID=147187,questTurnInID=147187,questType="standard",sourceQuests={54047},questLines={{id=856,name="In Darkest Night",orderIndex=7,flags=0}},db2PoiMapID=2129,db2PoiUiMapID=1333},
[54050] = {id=54050,name="Aftermath",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10226,mapID=1333,storyline={53955,54042,54043,54044,54045,54046,54047,54049,54050,54059,54416},description="We all have our reasons for accepting the val'kyr's gift. But now is not the time for those discussions. Sylvanas has been dealt a heavy blow today with the loss of Brynja. We will have no time to rest before the Alliance descends on this place. Nathanos has summoned you. There is something you must see.",objectivesText="Speak to Nathanos Blightcaller . Progress: Have you spoken with Nathanos?",rewardGold=23400,rewardXP=850,rewardItems={86143,116374,116416,116417,116418,116419,116420,116421,116422,116423,116424,116429,127755,163036,166678},starts={{npcID=146601}},ends={{npcID=146601}},mapCandidates={npc={},zone={10226}},questGiverID=146601,questTurnInID=146601,questType="standard",sourceQuests={54049},questLines={{id=856,name="In Darkest Night",orderIndex=8,flags=0}},db2PoiMapID=2129,db2PoiUiMapID=1333},
[54051] = {id=54051,name="Naga Attack!",level=10,requiredLevel=10,faction="none",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={54051},objectivesText="Repel the naga invaders Captives freed War supplies destroyed Banners removed",rewardXP=2125,rewardItems={165605,168003,168123},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{text="Repel the naga invaders",amount=1,type=15,objectID=0,orderIndex=0},{text="Captives freed",amount=34,type=0,objectID=146376,orderIndex=1},{text="War supplies destroyed",amount=34,type=0,objectID=146392,orderIndex=2},{text="Banners removed",amount=34,type=0,objectID=146397,orderIndex=3}},worldTaskTitle="Naga Attack!",db2PoiMapID=1642,db2PoiUiMapID=862,db2QuestInfoID=111,db2QuestInfoName="Elite World Quest"},
[54052] = {id=54052,name="Questfall",level=1,requiredLevel=1,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=40,mapID=52,storyline={54052},description="Me apologies, matey! New to the bow! More of a sword arm, yeah?! Didn't mean ta give ya such a start! It's just that we're in a bit of a bind, me an' the crew here! Can ya give us a bit of a hand?! Some upright dogs attacked us in the dead of night! Chased us out of camp in our skivvies! Maybe ya can help?! They had some sort of big one as their boss! We've been callin' him Barkpaw on account of he was barkin' at us and had big ol' paws! See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(54052)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(54052))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Slay 8 Riverpaw Gnolls and defeat Barkpaw .",mapCandidates={npc={},zone={40}},questType="standard"},
[54058] = {id=54058,name="Unintended Consequences",level=50,requiredLevel=50,faction="both",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=896,storyline={53760,53761,53762,53763,53765,53766,54058,54113,54114,54117,54118,54126,54141,54144,54172,54174,54265,54433,54438,54439,54682,54683},series={53760,53761,53762,54113,54114,54117,54118,54144,54174,54265,54433},description="< Xal'atath speaks once more.> The servants of N'Zoth prepare for their master's return. They intend to conjure a scouring storm to wash away all unbelievers. The particular ritual they will invoke requires three ancient artifacts. One of void, one of storm, and one of ocean. Even now, I hear the void relic calling to me. It is being empowered... or corrupted, I am not sure which. I see it upon a cliff, overlooking a vast sea. Come, priest. We can find a much better use for such a prize.",objectivesText="Find the Void Stone in Drustvar. Progress: A change of pace can be invigorating, eh, High Priest?",rewardGold=234000,rewardXP=6815,rewardItems={162011,164911,165605,168123},rewardCurrencies={{id=1553,amount=250}},ends={{npcID=144773},{npcID=152589}},startObjects={{objectID=311885,mapID=862,x=0.78,y=0.367}},coords={mapID=896,source="quest_giver",x=0.198,y=0.362},mapCandidates={npc={896},zone={9042}},questType="standard",sourceQuests={54114,54118},questLines={{id=851,name="Crucible of Storms",orderIndex=11,flags=0},{id=5673,name="Lorewalking: Xal'atath",orderIndex=5,flags=0}},campaigns={{id=266,title="Lorewalking: Xal'atath",questLineID=5673,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[54059] = {id=54059,name="The Night Warrior",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10226,mapID=1333,storyline={53955,54042,54043,54044,54045,54046,54047,54049,54050,54059,54416},description="It appears these night elves won't give up the information easily... but perhaps that wisp you captured will. See if you can get it to reveal what happened here. I don't care how you do it. Father Norlath will handle the wisp from there.",objectivesText="Speak with the Lost Wisp to find out why the moon turned dark. Progress: Have you made that wisp cooperate?",rewardGold=23400,rewardXP=850,starts={{npcID=146323}},ends={{npcID=146323}},mapCandidates={npc={},zone={10226}},questGiverID=146323,questTurnInID=146323,questType="standard",sourceQuests={54046},questLines={{id=856,name="In Darkest Night",orderIndex=5,flags=0}},db2PoiMapID=2129,db2PoiUiMapID=1333},
[54060] = {id=54060,name="Naga Attack!",level=10,requiredLevel=10,faction="none",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={54060},objectivesText="Repel the naga invaders",rewardXP=2125,rewardItems={165605,168003,168123},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{text="Repel the naga invaders",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Naga Attack!",db2PoiMapID=1642,db2PoiUiMapID=862,db2QuestInfoID=111,db2QuestInfoName="Elite World Quest"},
[54082] = {id=54082,name="More Power",level=10,requiredLevel=10,faction="both",categories={},flags={"daily","repeatable"},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={54082},description="Welcome back, dear test subject. My dear sister has kindly asked me to administer today's experiment, which falls below our typical standards of legality... You may, as always, choose not to participate and we will acquire sufficient replacement test subjects. Our new project requires more energy than our generator can manage. We must supercharge it with a jolt of power from the outside. Bondo's Yard has the best power line in Mechagon , so we shall siphon what we need from those rapscallions.",objectivesText="Connect power lines from Bondo's Yard to the Quickcharge laboratory.",rewardGold=257400,rewardXP=1415,rewardItems={129759,166970,169114},starts={{npcID=150630}},ends={{npcID=150630}},mapCandidates={npc={1462},zone={10290}},questType="standard",db2LabelIDs={5672}},
[54083] = {id=54083,name="Grease The Wheels",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={54083,54086,54922,54929,55373,55608,55622,55696,55697,55753,56168,56175},description="Kerchunk said you guys was working on getting that mechaspider running again. Well I'm not gonna let you have all the fun! That rusty old thing's gonna need a lot of grease to get moving again. So I jury-rigged a special Grease Trap to help you gather grease from the slimes nearby.",objectivesText="Use the Grease Trap to collect 12 Cog Grease from slimes around The Outflow.",rewardGold=257400,rewardXP=1415,rewardItems={167076,168827},starts={{npcID=149815}},ends={{npcID=149815}},mapCandidates={npc={1462},zone={10290}},questType="standard",sourceQuests={56168},questLines={{id=925,name="Making a Mount",orderIndex=7,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[54086] = {id=54086,name="Right Bot for the Job",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={54083,54086,54922,54929,55373,55608,55622,55696,55697,55753,56168,56175},description="We don't waste anything around here. Every defeated bot gets a second chance! If I'm going to fix this mechaspider, I'm going to need a few extra wrenchbots working with me. Use my Bot Re-Energizer on three dead Repeating Wrenchbots and bring them to me, and I'll put them to work.",objectivesText="Bring three Repeating Wrenchbots to Recycler Kerchunk Progress: Did you find those Repeating Wrenchbots yet?",rewardGold=257400,rewardXP=1415,rewardItems={168827},starts={{npcID=150573}},ends={{npcID=150573}},mapCandidates={npc={1462},zone={10290}},questType="standard",sourceQuests={55608},questLines={{id=925,name="Making a Mount",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[54087] = {id=54087,name="You Must be This Height",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={54087,54088,54945,54946,54947,54992,55040,55096,55609,55645,55729,55730,55731,55734,55736,55995,56131},description="The moment is here <name>. For such a historic moment I feel a gnome, such as myself, should be the one to activate the device. Let me know when you think we should begin.",objectivesText="Let me know when I can activate the device. Progress: This is quite an important discovery!",rewardGold=2000,rewardXP=1770,rewardItems={167039},starts={{npcID=149877}},ends={{npcID=152864}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={54945},questLines={{id=940,name="Expedition to Mechagon",orderIndex=3,flags=0},{id=5376,name="Welcome to Mechagon",orderIndex=4,flags=0},{id=6060,name="Mechagon Intro",orderIndex=0,flags=0}},campaigns={{id=218,title="Mechagon",questLineID=5376,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6060,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[54088] = {id=54088,name="The Legend of Mechagon",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=1161,storyline={54087,54088,54945,54946,54947,54992,55040,55096,55609,55645,55729,55730,55731,55734,55736,55995,56131},series={57009,58708},description="I came as soon as I heard! A mysterious vault has been discovered in Tiragarde. Centuries ago, the last king of the gnomes, King Mechagon, led his followers in search of a mythical land of technology. He left no clue as to where he was headed, and over time his legend faded into history. This vault could be the first step to discovering King Mechagon's true fate! I must examine it firsthand. Meet me there, Champion. I could use your assistance.",objectivesText="Meet Tinkmaster Overspark outside the mysterious vault.",rewardGold=257400,rewardXP=1415,starts={{npcID=150208}},ends={{npcID=149864}},mapCandidates={npc={895,1161},zone={8568}},questType="standard",sourceQuests={57009,58708},questLines={{id=940,name="Expedition to Mechagon",orderIndex=0,flags=0},{id=5376,name="Welcome to Mechagon",orderIndex=2,flags=0},{id=6060,name="Mechagon Intro",orderIndex=1,flags=0}},campaigns={{id=218,title="Mechagon",questLineID=5376,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6060,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[54089] = {id=54089,name="Omgar Doombow",level=10,requiredLevel=10,faction="alliance",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={54089},rewardXP=2125,starts={{npcID=146607,mapID=896,x=0.318,y=0.33}},mapCandidates={npc={},zone={8721}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=146607}},worldTaskTitle="Omgar Doombow",db2PoiMapID=1643,db2PoiUiMapID=896,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3455,db2VignetteName="Omgar Doombow"},
[54090] = {id=54090,name="Toys For Destruction",level=10,requiredLevel=10,faction="both",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={54090},description="Ricket sent word that she was here in Mechagon , so I came right away to help with the uh... research. I had the peons scour the island for any technology they could find. With da stuff we got here, we gonna make some amazing weapons to fight King Mechagon . Then afterwards, we get rich selling 'em! Help me wrangle everyone's ideas into one perfect weapon!",objectivesText="Help Rocket-Chief Fuselage build the perfect weapon. Progress: You build an amazing weapon yet?",rewardGold=257400,rewardXP=1415,rewardItems={166846},starts={{npcID=151006}},ends={{npcID=151006}},mapCandidates={npc={1462},zone={10290}},questType="standard",questLines={{id=965,name="Visit from B.O.O.M.",orderIndex=0,flags=0}},db2LabelIDs={5672},db2PoiMapID=1643,db2PoiUiMapID=1462},
[54091] = {id=54091,name="Strong Arm John",level=10,requiredLevel=10,faction="horde",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={54091},rewardXP=2125,starts={{npcID=146611,mapID=895,x=0.7798,y=0.4915}},mapCandidates={npc={},zone={8567}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=146611}},worldTaskTitle="Strong Arm John",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3416,db2VignetteName="Strong Arm John"},
[54094] = {id=54094,name="A Goblin's Definition of Success",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53941,53942,54004,54007,54008,54009,54022,54028,54094,54123,54124,54128,54635},description="I'm all set here, I'm just gonna play around with the mech, I think I got a good idea how it works thanks to ya. Nathanos \"prince of all that's death and destruction\" Blightcaller is gonna want you back on that boat, the Banshee's Scream or whatever it is. He'll be happy to know we took care of business. Then again, I got no idea if he even feels happy anymore.",objectivesText="Meet with Nathanos on the Banshee's Wail.",rewardGold=23400,rewardXP=850,rewardItems={164987,165702,165734,166309},starts={{npcID=146623}},ends={{npcID=135691}},mapCandidates={npc={862,895},zone={8567}},questType="standard",sourceQuests={54028},questLines={{id=839,name="Adventures of Gallywix and the G.M.O.D.",orderIndex=11,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=839,questLineOrder=16,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=839,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54096] = {id=54096,name="The Fall of the Sunwell",level=50,requiredLevel=50,faction="horde",requiredRaces={10},categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=3487,mapID=110,storyline={53725,53734,53735,53736,53737,53738,53791,53853,53882,54096},description="The flame of the lantern dims. Your final task is to rekindle it. In order to do so, you must walk one remaining path. While we are fortunate to hold the Sunwell once again, we must always remember that it was yet another part of us that Arthas took away... and that our late prince was forced to find us a new way of life. Enter the Sunwell Plateau, and witness its fall.",objectivesText="Complete the Fall of the Sunwell scenario.",rewardGold=683200,rewardXP=8520,rewardItems={166896},starts={{npcID=145793}},ends={{npcID=16802}},mapCandidates={npc={110},zone={3487}},questType="standard",sourceQuests={53853},questLines={{id=811,name="Blood Elf Heritage Armor",orderIndex=9,flags=0},{id=5697,name="Lorewalking: Elves",orderIndex=4,flags=0}},campaigns={{id=274,title="Lorewalking:Elves",questLineID=5697,questLineOrder=0}},db2PoiMapID=530,db2PoiUiMapID=110},
[54097] = {id=54097,name="The Dark Lady Calls",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={54097,54099,54100,54101,54102,54103,54104,54105,54106,54107,54108,54109,54754},description="Champion, the Dark Lady has need of you. We cannot speak more of this here. Make haste to Orgrimmar at once. Best not to keep her waiting.",objectivesText="Meet with Lady Sylvanas Windrunner in Orgrimmar.",rewardGold=23400,rewardXP=850,starts={{npcID=146013}},ends={{npcID=146654}},mapCandidates={npc={85,862},zone={8499}},questType="standard",sourceQuests={54165},questLines={{id=802,name="Lost Honor",orderIndex=0,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=802,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=802,questLineOrder=12}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1,db2PoiUiMapID=85},
[54099] = {id=54099,name="The High Overlord",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=1637,mapID=85,storyline={54097,54099,54100,54101,54102,54103,54104,54105,54106,54107,54108,54109,54754},description="I have asked you here to discuss a matter of great importance to the Horde. Varok Saurfang is no longer in Stormwind. Let us discuss this turn of events.",objectivesText="Discuss Saurfang's fate with Lady Sylvanas Windrunner in Orgrimmar. Progress: I trust your discretion in this matter.",rewardGold=23400,rewardXP=850,starts={{npcID=146654}},ends={{npcID=146654}},mapCandidates={npc={85},zone={1637}},questType="standard",sourceQuests={54097},questLines={{id=802,name="Lost Honor",orderIndex=1,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=802,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=802,questLineOrder=12}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1,db2PoiUiMapID=85},
[54100] = {id=54100,name="A Way Out",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=1637,mapID=85,storyline={54097,54099,54100,54101,54102,54103,54104,54105,54106,54107,54108,54109,54754},description="My spies report that our High Overlord did not leave the way he entered, nor any other way we know of. No signs of him were seen at any of the known exits from the Stockades or the sewers. He simply was in his cell one moment, and gone the next. Begin your investigation around the city of Stormwind. There must be another way out that we do not know of. Dark Ranger Lyana will meet you there. Her tracking skills are second to none. Do not fail me, my champion.",objectivesText="Meet with Dark Ranger Lyana in Elwynn Forest.",rewardGold=23400,rewardXP=850,rewardItems={2411,12050,12051,25470,25474,25948,25949,25951,26009,26023,26035,31725,49927,52920,52937,52965,61463,61464,61465,66898,66899,66900,66915,66917,66921,81552,81553,81554,81555,81556,81557,81834,81835,81836,81837,81838,88384,90546,90547,90622,112595,112596,112597,112598,131273,131835,140255,142054,153726,153747,153773,153792,153814,153830,153835,153856,153859,153889,153891,153892,153893,153934,153944,153959,153960,153961,153973,153983,154005,154024,154025,154035,154036,160513,165638,165791,170514,170515,170516,170517,170518,170519,170520,170521,170522,170523,170524,170525,170526,170527,170528,170529,170530,170531,170532,170533,170534,170535,170536,170537,173340,173341,173342,173343,175588,179768,179887,180924,180925,180926,180927,181912,185073,185074,185075,185076,185077,185078,185079,185080,185107,185108,185109,185110,185111,185112,185113,185114,185115,186201,186205,186206,187329,187330,187331,187467,191984,191986,191988,191989,191990,191991,191992,191994,191995,191996,191998,191999,192002,192004,192005,192006,192007,192008,192009,192010,192011,192012,192013,192015,192037,194522,197943,198542,231839,245707,245708,245709,245710,247234,254878},starts={{npcID=146654}},ends={{npcID=146010}},mapCandidates={npc={51,85},zone={1637}},questType="standard",sourceQuests={54099},questLines={{id=802,name="Lost Honor",orderIndex=2,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=802,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=802,questLineOrder=12}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiUiMapID=37},
[54101] = {id=54101,name="On Track",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=12,mapID=37,storyline={54097,54099,54100,54101,54102,54103,54104,54105,54106,54107,54108,54109,54754},description="Keep your head down. We do not want to be seen out here. Our spies keep watch over Stormwind day and night, and saw no signs of Saurfang. Nor did we notice any oddly-oversized carts or strange ships in the night, if that was what you were thinking. How then, did he make his escape? Let's look around.",objectivesText="Follow the trail of Varok Saurfang in Elwynn Forest. Progress: Let us keep investigating.",rewardGold=234000,rewardXP=6815,rewardItems={165638,165791},starts={{npcID=146010}},ends={{npcID=146010}},mapCandidates={npc={37},zone={12}},questTurnInID=146010,questType="standard",sourceQuests={54100},questLines={{id=802,name="Lost Honor",orderIndex=3,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=802,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=802,questLineOrder=12}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiUiMapID=37},
[54102] = {id=54102,name="Eastern Escape",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=44,mapID=49,storyline={54097,54099,54100,54101,54102,54103,54104,54105,54106,54107,54108,54109,54754},description="It's not unusual to see SI:7 spies lurking around the city, but something about this doesn't feel right. We need to find where Saurfang's trail picks up. The last tracks were heading east, towards Redridge. The path to Redridge crosses the Three Corners, one of the Alliance's more well-defended towers. I have an idea. Meet me there.",objectivesText="Meet Dark Ranger Lyana at Three Corners in Redridge Mountains.",rewardGold=23400,rewardXP=850,rewardItems={165638,165791},starts={{npcID=146791}},ends={{npcID=146806}},mapCandidates={npc={49},zone={44}},questGiverID=146791,questType="standard",sourceQuests={54101},questLines={{id=802,name="Lost Honor",orderIndex=4,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=802,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=802,questLineOrder=12}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiUiMapID=49},
[54103] = {id=54103,name="Corner Crossing",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=44,mapID=49,storyline={54097,54099,54100,54101,54102,54103,54104,54105,54106,54107,54108,54109,54754},description="If Saurfang was headed in this direction, it would have been difficult for him to avoid the Three Corners watchpost. We could simply walk in there and demand information, but I have a feeling that they would not part with it willingly. So we will take another approach. I have procured this potion from our alchemists. It will turn us into--ugh--humans for a while. We can then question the guards. Perhaps someone saw something.",objectivesText="Drink the Humanizing Potion , then question the citizens of Redridge Mountains. Progress: Let's find out everything we can.",rewardGold=117000,rewardXP=3410,rewardItems={20576,110505,165638,165791},starts={{npcID=146806}},ends={{npcID=146806}},mapCandidates={npc={49},zone={44}},questTurnInID=146806,questType="standard",sourceQuests={54102},questLines={{id=802,name="Lost Honor",orderIndex=5,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=802,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=802,questLineOrder=12}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiUiMapID=49},
[54104] = {id=54104,name="Signs of Saurfang",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=44,mapID=49,storyline={54097,54099,54100,54101,54102,54103,54104,54105,54106,54107,54108,54109,54754},description="With the guards drunk at their posts, and others out of position, Saurfang would have had little trouble passing Three Corners undetected. The path splits just south of town. The back roads of Redridge are poorly patrolled, and are infested with gnolls and spiders. In other words, perfect for an orc trying not to be noticed. His most likely path is Lakeridge Highway. We should continue our investigation there.",objectivesText="Follow the trail of Varok Saurfang in Redridge. Progress: Well? What are you waiting for?",rewardGold=234000,rewardXP=6815,rewardItems={165638,165791},starts={{npcID=146937}},ends={{npcID=146937}},mapCandidates={npc={},zone={44}},questGiverID=146937,questTurnInID=146937,questType="standard",sourceQuests={54103},questLines={{id=802,name="Lost Honor",orderIndex=6,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=802,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=802,questLineOrder=12}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiUiMapID=49},
[54105] = {id=54105,name="Ever Eastward",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=44,mapID=49,storyline={54097,54099,54100,54101,54102,54103,54104,54105,54106,54107,54108,54109,54754},description="All signs point to our quarry heading farther east. To what end, I am not sure. But I have my suspicions. I am going to scout the area from the air. Let's meet up at Redridge Pass.",objectivesText="Find Dark Ranger Lyana at Redridge Pass in Redridge Mountains.",rewardGold=23400,rewardXP=850,rewardItems={165638,165791},starts={{npcID=146937}},ends={{npcID=147210}},mapCandidates={npc={49},zone={44}},questGiverID=146937,questType="standard",sourceQuests={54104},questLines={{id=802,name="Lost Honor",orderIndex=7,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=802,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=802,questLineOrder=12}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiUiMapID=49},
[54106] = {id=54106,name="Tracking Tipoff",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=44,mapID=49,storyline={54097,54099,54100,54101,54102,54103,54104,54105,54106,54107,54108,54109,54754},description="Look there, down the hill. One of the Alliance hunters that roam the area. No one knows these pathways like them. If our quarry passed through here, that hunter would certainly have seen the tracks. His dogs may even have caught Saurfang's scent. Here is another dose of the potion. Let us question this one while he is alone.",objectivesText="Drink the Humanizing Potion , then question Hunter McAlister at Redridge Pass in Redridge Mountains. Progress: Let's find out everything we can.",rewardGold=234000,rewardXP=6815,rewardItems={165638,165791},starts={{npcID=147210}},ends={{npcID=147210}},mapCandidates={npc={49},zone={44}},questTurnInID=147210,questType="standard",sourceQuests={54105},questLines={{id=802,name="Lost Honor",orderIndex=8,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=802,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=802,questLineOrder=12}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiUiMapID=49},
[54107] = {id=54107,name="Grim Tidings",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=44,mapID=49,storyline={54097,54099,54100,54101,54102,54103,54104,54105,54106,54107,54108,54109,54754},description="Ey mon, dat dark ranger, she be lyin' to ya! Saurfang knew dey'd be comin' for him. He sent me to watch da pass, see who his assassins be. Try to warn him if I could. She not be reportin' back nothin'... she gonna kill him. Most likely got a whole buncha deathguards just waitin' for her signal. We gotta stop dem! Ya wit' me?",objectivesText="Meet with Zekhan in Swamp of Sorrows.",rewardGold=23400,rewardXP=850,rewardItems={165638,165791},starts={{npcID=146012}},ends={{npcID=147297}},mapCandidates={npc={49,51},zone={44}},questType="standard",sourceQuests={54106},questLines={{id=802,name="Lost Honor",orderIndex=9,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=802,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=802,questLineOrder=12}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiUiMapID=51},
[54108] = {id=54108,name="A Warrior's Death",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8,mapID=51,storyline={54097,54099,54100,54101,54102,54103,54104,54105,54106,54107,54108,54109,54754},description="She gonna try an' take him in, and den no one ever gonna see Varok Saurfang again. Dis was never a rescue mission. Dis be about power, an' control, an' Sylvanas think she be holdin' all da cards. But she didn't count on us! Let's go!",objectivesText="Defend Varok Saurfang in Swamp of Sorrows. Progress: Will you stand with us?",rewardGold=309800,rewardXP=6815,rewardItems={165638,165791},starts={{npcID=147297}},ends={{npcID=146011}},mapCandidates={npc={51},zone={8}},questType="standard",sourceQuests={54107},questLines={{id=802,name="Lost Honor",orderIndex=11,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=802,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=802,questLineOrder=12}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiUiMapID=51},
[54109] = {id=54109,name="Queen's Favor",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8,mapID=51,storyline={54097,54099,54100,54101,54102,54103,54104,54105,54106,54107,54108,54109,54754},description="I have two things to ask of you, and I do not ask them lightly. First, I need you to retain the favor of the warchief. She will undoubtedly have questions, and seeds of distrust may begin to grow, but she cannot lose you as an ally. Not now. She would not so willingly part with one of her greatest champions. In order to do so, it will have to look like you faced me in combat, and lost. I trust you can take a hit. Second, I ask you not to follow me further. I must make this journey alone.",objectivesText="Take a hit from Varok Saurfang , then report to Warchief Sylvanas Windrunner in Orgrimmar.",rewardGold=468000,rewardXP=8520,rewardItems={165638,165791},starts={{npcID=146011}},ends={{npcID=134711}},mapCandidates={npc={51,85},zone={8}},questType="standard",sourceQuests={54108},questLines={{id=802,name="Lost Honor",orderIndex=12,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=802,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=802,questLineOrder=12}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1,db2PoiUiMapID=85},
[54112] = {id=54112,name="Mistweaver Nian",level=10,requiredLevel=10,faction="horde",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={54112},rewardXP=2125,starts={{npcID=146651,mapID=895,x=0.7448,y=0.4494}},mapCandidates={npc={},zone={8567}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=146651}},worldTaskTitle="Mistweaver Nian",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3415,db2VignetteName="Mistweaver Nian"},
[54113] = {id=54113,name="Every Little Death Helps",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={53760,53761,53762,53765,54058,54113,54114,54126,54141,54144,54265,54438,54682},series={53760,53761,53762,54058,54114,54117,54118,54144,54174,54265,54433},description="<The whispers are faint, but grow louder as you hold the blade in your hand.> So weak... need... blood... souls... <The voice trails off, but you can still sense the dagger urging you on.>",objectivesText="Assist Xal'atath in recovering its strength.",rewardGold=234000,rewardXP=6815,rewardItems={128827,164761,165605,168123},startObjects={{objectID=311218,mapID=942,x=0.342,y=0.318}},endObjects={{objectID=311218,mapID=942,x=0.342,y=0.318}},coords={mapID=942,x=0.342,y=0.318},mapCandidates={npc={},zone={9042}},questType="standard",sourceQuests={54144},questLines={{id=851,name="Crucible of Storms",orderIndex=6,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
