[54119] = {id=54119,name="Hartford Sternbach",level=10,requiredLevel=10,faction="horde",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={54119},rewardXP=2125,starts={{npcID=146675,mapID=895,x=0.8028,y=0.3685}},mapCandidates={npc={},zone={8567}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=146675}},worldTaskTitle="Hartford Sternbach",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3414,db2VignetteName="Hartford Sternbach"},
[54120] = {id=54120,name="To Orgrimmar",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=1637,mapID=1,storyline={53774,53775,53776,53777,53778,53779,53780,53781,53782,54120,54145,54147},series={53778},description="A darkness in me mind be keeping me from remembering what happened da day I named Sylvanas warchief. Take me glaive and travel to da pyre where I was cremated in Orgrimmar . Master Gadrin be packin' enough juju to call me to dat place. Go, and I be seein' ya dere.",objectivesText="Take the Glaive of Vol'jin to Master Gadrin at Drannosh'ar Blockade, Durotar. Provided item:",rewardGold=23400,rewardXP=850,rewardItems={23211,23246,23247,23326,23327,23435,34684,111660,118776,118777,118778,118779,118780,165371},starts={{npcID=145965}},ends={{npcID=146268}},mapCandidates={npc={1},zone={14}},questGiverID=145965,questType="standard",sourceQuests={53778},questLines={{id=805,name="The Shadow Hunter",orderIndex=4,flags=0}},db2PoiMapID=1,db2PoiUiMapID=1},
[54121] = {id=54121,name="Breaking Out Ashvane",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54121,54175,54176,54177,54178,54179},description="The Dark Lady wishes to gain another potential ally in the fight against the Alliance. Lady Ashvane, head of the Ashvane Company, was one of the greatest enemies of Kul Tiras until her capture. We are going to release her. Meet Valtrois in Tiragarde Sound. She and Rexxar are working out a plan to break Ashvane out.",objectivesText="Meet Valtrois in Tiragarde Sound.",rewardGold=23400,rewardXP=850,rewardItems={164987,165702,165734,166309},starts={{npcID=135691}},ends={{npcID=147088}},mapCandidates={npc={862,895},zone={8499}},questType="standard",sourceQuests={54094},questLines={{id=848,name="Escape from Tol Dagor",orderIndex=0,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=848,questLineOrder=17,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=848,questLineOrder=9}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[54123] = {id=54123,name="It Belongs in My Mech!",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={53941,53942,54004,54007,54008,54009,54022,54028,54094,54123,54124,54128,54635},description="Check this out! It's my latest creation that someone else came up with and built, Gallywix's Mech of Death! I got it fueled with all that Azerite you found, but I still need more of the stuff to give it that extra kick. I was SUPPOSED to have the stuff from our operations here, but there's some sorta Azerite goop causin' a mess! My guy Patch made an Azerite vacuum device. I want you to suck the Azerite outta these slimes!",objectivesText="Recover Azerite from Azerite slimes using the Azerite Vacuumizer .",rewardGold=234000,rewardXP=6815,rewardItems={164987,165702,165734,166309},rewardCurrencies={{id=1553,amount=250}},starts={{npcID=145751}},ends={{npcID=145751}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={53941},questLines={{id=839,name="Adventures of Gallywix and the G.M.O.D.",orderIndex=1,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=839,questLineOrder=16,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=839,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54124] = {id=54124,name="Avoiding Lawsuits 101",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={53941,53942,54004,54007,54008,54009,54022,54028,54094,54123,54124,54128,54635},description="Yo, <name>! I leave the A.M.O.D. for two seconds to deal with old Gallywix and now I'm knee-deep in Azerite goo! Listen, here's the deal. I need ya to rescue some of these goblins from these monsters. I'll be honest, I skimped on the money that covers their insurance in the event of Azerite-monster-related injuries. What? Who knew that these slimes would appear and attack these guys! Do me a solid and get these goblins outta there!",objectivesText="Rescue 6 Uninsured Goblin Workers . Progress: Ya help those guys?",rewardXP=6815,rewardItems={164987,165702,165734,166309,166850},starts={{npcID=148339}},ends={{npcID=148339}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={53941},questLines={{id=839,name="Adventures of Gallywix and the G.M.O.D.",orderIndex=2,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=839,questLineOrder=16,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=839,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54126] = {id=54126,name="Twist the Knife",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={53760,53761,53762,53765,54058,54113,54114,54126,54141,54144,54265,54438,54682},description="The relics are ours... as it was meant to be. There is but one more step needed for the great truths to be revealed. The naga sought to summon their storm from a place that echoes with ancient power. Though this site has had countless names over the ages, you mortals know it as the Precipice of Oblivion. I will go on ahead and begin preparations. Join me there.",objectivesText="Meet Xal'atath at the Precipice of Oblivion.",rewardGold=468000,rewardXP=8520,rewardItems={164761,165605,168123},starts={{npcID=146384}},ends={{npcID=146902},{npcID=231891}},mapCandidates={npc={84,864,1161},zone={8501}},questType="standard",sourceQuests={53762},questLines={{id=851,name="Crucible of Storms",orderIndex=15,flags=0},{id=5673,name="Lorewalking: Xal'atath",orderIndex=9,flags=0}},campaigns={{id=266,title="Lorewalking: Xal'atath",questLineID=5673,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[54127] = {id=54127,name="Rocket Hop",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={54127},description="Horde forces are attacking Tiragarde Sound. Make them regret every footstep upon our soil!",objectivesText="Repel the Hordes forces attacking Tiragarde Sound.",rewardXP=2125,rewardItems={165943},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{text="Grizzek's Rocket Hop obtained",amount=1,type=1,objectID=165943,orderIndex=0},{text="West Zeppelin destroyed",amount=1,type=0,objectID=147043,orderIndex=1},{text="East Zeppelin destroyed",amount=1,type=0,objectID=147042,orderIndex=2},{text="Siege Cannon destroyed",amount=4,type=0,objectID=147050,orderIndex=5}},worldTaskTitle="Rocket Hop",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[54128] = {id=54128,name="Necessary Precautions",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={53941,53942,54004,54007,54008,54009,54022,54028,54094,54123,54124,54128,54635},description="That was freakin' awesome! We decimated Mekkatorque's puny little army. We got a location on where that little punk and his airship is. That's where he's controllin' all his FORMER mechs. Here's the plan, we're gonna fly over there, blow up that freak, then destroy his airship! Now, I ain't no idiot, <name>, I'm the smartest goblin alive. First, we gotta take what they call necessary precautions. Take this manual, I want you to make sure the G.M.O.D is ready to go!",objectivesText="Review the G.M.O.D 's systems. Progress: Well? This thing ain't gonna double check itself! Although... maybe it should.",rewardGold=23400,rewardXP=850,rewardItems={164987,165702,165734,166309},starts={{npcID=145816}},ends={{npcID=145816}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={53942},questLines={{id=839,name="Adventures of Gallywix and the G.M.O.D.",orderIndex=4,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=839,questLineOrder=16,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=839,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=896},
[54129] = {id=54129,name="First Mate Malone",level=10,requiredLevel=10,faction="alliance",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={54129},rewardXP=2125,starts={{npcID=146773,mapID=895,x=0.8459,y=0.4759}},mapCandidates={npc={},zone={8567}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=146773}},worldTaskTitle="First Mate Malone",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3423,db2VignetteName="First Mate Malone"},
[54130] = {id=54130,name="Our New Friends",level=10,requiredLevel=10,faction="alliance",categories={"seasonal"},flags={},sharable=true,event="Children's Week",expansion=7,storyline={54130},description="I heard that the Alliance is growing! More and more different kinds of people are joining all the time to fight the mean Horde. I'm not sure where the embassy is, but I heard it's somewhere here in Stormwind. Can you show me how to get there? I want to see all our new friends!",objectivesText="Take your Human Orphan to the Stormwind Embassy. If your orphan is not present when you arrive, call for him. Progress: I bet all of our new friends came from really far away!",rewardGold=309800,rewardXP=1415,rewardItems={18598},starts={{npcID=14305}},mapCandidates={npc={},zone={}},questGiverID=14305,questType="standard",sourceQuests={1468}},
[54132] = {id=54132,name="Horde of Heroes",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=9042,mapID=862,storyline={54132},description="The Alliance has begun a coordinated assault against our forces in Stormsong Valley. Attack the enemy forces and drive them back!",objectivesText="Lead the Horde assault into Stormsong Valley.",rewardGold=1123600,rewardXP=2125,rewardItems={165871},rewardCurrencies={{id=1716,amount=5}},starts={{npcID=135447}},ends={{npcID=135447}},mapCandidates={npc={862},zone={9042}},questGiverID=135447,questType="standard"},
[54134] = {id=54134,name="Many Fine Heroes",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8501,storyline={54134},description="The Alliance has the upper hand in Vol'dun. We strike now! You will lead our forces to victory!",objectivesText="Lead the Alliance assault into Vol'dun. Progress: Have we pushed the Horde out of Vol'dun?",rewardXP=2125,rewardItems={165872},rewardCurrencies={{id=1717,amount=5},{id=1553,amount=400},{id=1560,amount=200}},starts={{npcID=135446}},mapCandidates={npc={},zone={8501}},questGiverID=135446,questType="standard"},
[54135] = {id=54135,name="Romp in the Swamp",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={54135},description="Alliance armies are landing on the shores of Nazmir. Drive them back to the sea. Zandalar is ours!",objectivesText="Repel the Alliance forces assaulting Nazmir. Progress: Nazmir belongs to the Zandalari, and the Horde!",rewardXP=2125,rewardItems={109076,163857,165871,166792},rewardCurrencies={{id=1716,amount=5}},starts={{npcID=135459}},ends={{npcID=135459}},mapCandidates={npc={863},zone={8500}},questGiverID=135459,questType="standard"},
[54136] = {id=54136,name="March on the Marsh",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8500,storyline={54136},description="The Alliance has begun a coordinated assault against the Horde in Nazmir. Defeat the enemy forces and drive them out!",objectivesText="Lead the Alliance assault into Nazmir. Progress: What news do you bring from the front lines of Drustvar?",rewardXP=2125,rewardItems={165872},rewardCurrencies={{id=1717,amount=5}},starts={{npcID=135446}},mapCandidates={npc={},zone={8500}},questGiverID=135446,questType="standard"},
[54137] = {id=54137,name="In Every Dark Corner",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=862,storyline={54137},description="The Alliance's hold on Drustvar is weak. We will conquer it for the Horde!",objectivesText="Lead the Horde assault into Drustvar. Progress: What news do you bring from the front lines of Drustvar?",rewardXP=2125,rewardItems={165871},rewardCurrencies={{id=1716,amount=5}},ends={{npcID=135447}},coords={mapID=862,source="quest_giver",x=0.58,y=0.625},mapCandidates={npc={862},zone={8721}},questType="standard"},
[54138] = {id=54138,name="Ritual Rampage",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8499,storyline={54138},description="The Alliance has launched an assault into the very heart of the Zandalari empire. Defeat the Horde on their own soil to show them our strength!",objectivesText="Lead the Alliance assault into Zuldazar.",rewardXP=2125,rewardItems={165872},rewardCurrencies={{id=1717,amount=5}},starts={{npcID=135446}},mapCandidates={npc={},zone={8499}},questGiverID=135446,questType="standard"},
[54139] = {id=54139,name="War Is Here",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8670,mapID=862,storyline={54139,54140,54156,54157,54207,54208,54211,54212,54213,54224,54244,54249,54269,54270,54271,54275,54280},description="We need to move, <name>. We've received word that the Alliance have mounted an attack through Nazmir. Make for the Great Seal. King Rastakhan and Princess Talanji are there forming a plan of attack. Make no mistake, we will crush the Alliance. They are fools to attack us through Nazmir.",objectivesText="Meet King Rastakhan within the Great Seal. Progress: Let's get moving.",rewardGold=23400,rewardXP=850,starts={{npcID=135691}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8670}},questTurnInID=135691,questType="standard",sourceQuests={54179},questLines={{id=841,name="The Fury of the Zandalari",orderIndex=0,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=841,questLineOrder=18,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=841,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=1165},
[54140] = {id=54140,name="Ride of the Zandalari",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8670,mapID=862,storyline={54139,54140,54156,54157,54207,54208,54211,54212,54213,54224,54244,54249,54269,54270,54271,54275,54280},description="It is time de Alliance see de full fury of de Zandalari. Dey are fools to try an attack in Nazmir. We must tell de fleet, our warriors, and our flyers dat dey must move out and go to Nazmir at once. I will go aid our forces at de Blood Gate. Here is a list of dose you must speak with to mobilize our forces. Move as fast as you can, we must stop de Alliance as quickly as possible.",objectivesText="Mobilize the Zandalari fleet, warriors, and flyers.",rewardGold=117000,rewardXP=3410,starts={{npcID=133050}},ends={{npcID=146921}},mapCandidates={npc={862},zone={8670}},questGiverID=133050,questType="standard",sourceQuests={54139},questLines={{id=841,name="The Fury of the Zandalari",orderIndex=1,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=841,questLineOrder=18,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=841,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54141] = {id=54141,name="The Azsharan Medallion",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=942,storyline={53760,53761,53762,53765,54058,54113,54114,54126,54141,54144,54265,54438,54682},description="<On the naga's body you find an ornate metal disc. The writing on its surface resembles elven script, but you cannot decipher it. You suspect the words are written in the Nazja tongue. Perhaps someone with a knowledge of naga artifacts could translate the text.>",objectivesText="Take the Medallion to Collector Kojo .",rewardGold=23400,rewardXP=850,rewardItems={164761,165605,168123},rewardCurrencies={{id=1553,amount=400}},ends={{npcID=135793}},coords={mapID=942,source="quest_giver",x=0.404667,y=0.364667},mapCandidates={npc={942},zone={8567}},questType="standard",questLines={{id=851,name="Crucible of Storms",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942,startItems={165605}},
[54143] = {id=54143,name="Bird's-Eye View",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={54143},objectivesText="Grizzek's Rocket Hop obtained Spy Gear collected",rewardXP=2125,rewardItems={165656,165943},mapCandidates={npc={},zone={8721}},questType="standard",db2Objectives={{text="Grizzek's Rocket Hop obtained",amount=1,type=1,objectID=165943,orderIndex=0},{text="Spy Gear collected",amount=8,type=1,objectID=165656,orderIndex=2}},worldTaskTitle="Bird's-Eye View",db2PoiMapID=1643,db2PoiUiMapID=896,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[54144] = {id=54144,name="Orders from Azshara",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={53760,53761,53762,53765,54058,54113,54114,54126,54141,54144,54265,54438,54682},series={53760,53761,53762,54058,54113,54114,54117,54118,54174,54265,54433},description="<Kojo studies the medallion and grimaces.> Ugh... naga. This medallion is inscribed with orders. Looks like naga have been commanded to invade our shores and seize artifacts of great power. You know, I recently came upon one such object. See that dagger over there? Nasty thing. Gives me the willies. I swear I hear it whispering to me. I found it on an island in Stormsong Valley, on a makeshift altar. Maybe if you take it there, you'll get an idea of how the naga intended to use it.",objectivesText="Take the Dagger to the Makeshift Altar. Progress: <As you place the dagger upon the altar, it seems to shudder and blink at you.>",rewardGold=23400,rewardXP=850,rewardItems={164761,165605,168123},starts={{npcID=135793}},ends={{npcID=135793}},mapCandidates={npc={942},zone={9042}},questTurnInID=135793,questType="standard",sourceQuests={54141},questLines={{id=851,name="Crucible of Storms",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[54145] = {id=54145,name="The Loa of Death",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={53774,53775,53776,53777,53778,53779,53780,53781,53782,54120,54145,54147},series={53777,53779},description="Bwonsamdi is a dangerous loa, but even I do not believe he whispered to Vol'jin on his deathbed. To appoint Sylvanas sounds, well... he is not fond of de undead. And from what I have seen of de warchief, she is no fan of death. We must be respectful when we speak to Bwonsamdi , or dere will be consequences. Come, stay close.",objectivesText="Confront Bwonsamdi .",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1553,amount=750}},starts={{npcID=146824}},ends={{npcID=122688}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={53779},questLines={{id=805,name="The Shadow Hunter",orderIndex=7,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[54146] = {id=54146,name="Strong New Allies",level=10,requiredLevel=10,faction="horde",categories={"seasonal"},flags={},sharable=true,event="Children's Week",expansion=7,storyline={54146},description="I heard some adventurers saying that there are new members of the Horde, unlike all the rest! And the best part? They're right here in Orgrimmar! I don't know where the embassy is... but I bet you do! Can you take me? I heard there are orcs from another planet!",objectivesText="Take your Orcish Orphan to the Orgrimmar Embassy. If your orphan is not present when you arrive, call for him. Progress: New friends in Orgrimmar! That means I can come back and visit them all the time.",rewardXP=1415,rewardItems={18597},starts={{npcID=14444}},mapCandidates={npc={},zone={}},questGiverID=14444,questType="standard",sourceQuests={172}},
[54147] = {id=54147,name="Confront The Val'kyr",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=7541,mapID=634,storyline={53774,53775,53776,53777,53778,53779,53780,53781,53782,54120,54145,54147},series={53781,53782},description="Vol'jin's spirit is growing in power. I should no longer have to maintain a ritual to keep him here. Dis is fortunate, since Bwonsamdi warned me dat Eyir will likely not be pleased with my presence. Apparently she and Bwonsamdi have a past de loa was unwilling to discuss. We can proceed when you are ready.",objectivesText="Escort the Spirit of Vol'jin to Eyir.",rewardGold=234000,rewardXP=6815,starts={{npcID=146877}},ends={{npcID=122688}},mapCandidates={npc={634,863},zone={7541}},questType="standard",sourceQuests={53781},questLines={{id=805,name="The Shadow Hunter",orderIndex=9,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=640},
[54154] = {id=54154,name="The Hills Have Spies",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={54154},objectivesText="Gallywix's Getaway Pack obtained SI:7 Scouts slain Spy Gear collected",rewardXP=2125,rewardItems={165656,165942},mapCandidates={npc={},zone={8501}},questType="standard",db2Objectives={{text="Gallywix's Getaway Pack obtained",amount=1,type=1,objectID=165942,orderIndex=0},{text="SI:7 Scouts slain",amount=8,type=0,objectID=146946,orderIndex=1},{text="Spy Gear collected",amount=8,type=1,objectID=165656,orderIndex=2}},worldTaskTitle="The Hills Have Spies",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[54156] = {id=54156,name="A Path of Blood",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54139,54140,54156,54157,54207,54208,54211,54212,54213,54224,54244,54249,54269,54270,54271,54275,54280},description="De main fleet of de Alliance and Kul Tirans are off de coast in Nazmir. But we cannot ignore de forces here. Dere seems to be a strange fog coming in from Nazmir. De Kul Tirans must be using some of their voodoo to weaken us. We must carve a path of blood through dese Alliance fools. Help our forces by weakening de Alliance.",objectivesText="Slay 15 Alliance soldiers within the Blood Gate.",rewardGold=234000,rewardXP=6815,rewardItems={264299,264300,264301,264302},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=147075}},ends={{npcID=147075}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={54140},questLines={{id=841,name="The Fury of the Zandalari",orderIndex=2,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=841,questLineOrder=18,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=841,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54157] = {id=54157,name="No One Left Behind",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54139,54140,54156,54157,54207,54208,54211,54212,54213,54224,54244,54249,54269,54270,54271,54275,54280},description="De warriors here tell me Rokhan made a heroic stand, holding off de Alliance and their champions before being defeated. Rokhan is still here within de Blood Gate, held captive by some strange creature called a Lightforged. I must stay here and help hold de line. I need you to rescue Rokhan!",objectivesText="Rescue Rokhan.",rewardGold=234000,rewardXP=6815,starts={{npcID=146921}},ends={{npcID=146921}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={54140},questLines={{id=841,name="The Fury of the Zandalari",orderIndex=3,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=841,questLineOrder=18,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=841,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54161] = {id=54161,name="What the Drust Knew",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={54161,55635},description="Bal'a dash, <name>. If you have a moment, I could use your assistance. I've recently received a shipment of Drust relics that were smuggled out of Kul Tiras. Most have our usual enchantments, but there is one that is unique. Just holding it makes my hair stand on end. With you being my best pupil, I was thinking that it would be enlightening if we disenchanted it together, to see how it was made. What do you say?",objectivesText="Carefully remove the enchantment from the Ancient Drust relic to learn about its construction.",rewardGold=23400,rewardXP=850,starts={{npcID=122702}},ends={{npcID=122702}},mapCandidates={npc={1165},zone={8670}},questType="standard",questLines={{id=910,name="8.1.5 Enchanting - Horde",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[54162] = {id=54162,name="Hard Landing",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={54162},objectivesText="BOOM-O-MATIC 9000 obtained Alliance Gyrocopters repelled",rewardXP=2125,rewardItems={165877},mapCandidates={npc={},zone={8499}},questType="standard",db2Objectives={{text="BOOM-O-MATIC 9000 obtained",amount=1,type=1,objectID=165877,orderIndex=0},{text="Alliance Gyrocopters repelled",amount=10,type=0,objectID=147778,orderIndex=1}},worldTaskTitle="Hard Landing",db2PoiMapID=1642,db2PoiUiMapID=862,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[54163] = {id=54163,name="As the Dust Settles",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54163,54183},description="We have achieved a great victory, <name>, though at a cost. King Wrynn is gathering the Alliance leadership in Unity Square to discuss matters. He has requested our presence as well. Go to Unity Square. I'll meet you there shortly.",objectivesText="Meet with Anduin Wrynn in Unity Square.",rewardGold=23400,rewardXP=850,starts={{npcID=135612}},ends={{npcID=147885}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={54459},questLines={{id=847,name="The Price of Victory",orderIndex=0,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=847,questLineOrder=18,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=847,questLineOrder=11}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=1161},
[54164] = {id=54164,name="The King's Death",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8670,mapID=862,storyline={54164,54165},description="King Rastakhan is dead, the Zandalari fleet has been decimated, and we have lost valuable soldiers. The Dark Lady is on her way from Orgrimmar to assess the situation. We must figure out our next move before the Alliance strike again. I believe protocol now would be to pay respects to the fallen king. We will determine our next move afterwards.",objectivesText="Pay respects to King Rastakhan .",rewardGold=23400,rewardXP=850,rewardItems={44358,44359,44360,44361},starts={{npcID=135691}},ends={{npcID=145411}},mapCandidates={npc={862,1165},zone={8670}},questType="standard",sourceQuests={54280},questLines={{id=842,name="Diverging Paths",orderIndex=0,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=842,questLineOrder=19,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=842,questLineOrder=11}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=1165},
[54165] = {id=54165,name="The Return of Derek Proudmoore",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8499,mapID=1165,storyline={54164,54165},description="I'll admit, I did not think the Little Lion had it in him to kill King Rastakhan. Blood has been spilled, and vengeance must be had. Give me a moment to express my condolences, then come with me. We have more to do to win this war.",objectivesText="Observe Sylvanas's discussion with Princess Talanji.",rewardGold=23400,rewardXP=850,rewardCurrencies={{id=1553,amount=750}},starts={{npcID=145411}},ends={{npcID=135691}},mapCandidates={npc={862,1165},zone={8499}},questType="standard",sourceQuests={54164},questLines={{id=842,name="Diverging Paths",orderIndex=1,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=842,questLineOrder=19,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=842,questLineOrder=11}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54166] = {id=54166,name="Set Sail",level=10,requiredLevel=10,faction="horde",categories={},flags={"weekly","repeatable"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={54166},description="Assist the Horde by collecting Azerite on Island Expeditions.",objectivesText="Collect Azerite on Island Expeditions.",rewardXP=2830,rewardCurrencies={{id=1553,amount=350}},mapCandidates={npc={},zone={8499}},questType="world",db2Objectives={{text="Win 1 Island Expedition",amount=1,type=0,objectID=147590,orderIndex=0}},worldTaskTitle="Set Sail",db2PoiMapID=1642,db2PoiUiMapID=1165,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[54167] = {id=54167,name="Set Sail",level=1,requiredLevel=1,faction="alliance",categories={},flags={"weekly","repeatable"},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={54167},description="Assist the Alliance by collecting Azerite on Island Expeditions.",objectivesText="Collect Azerite on Island Expeditions.",rewardXP=400,rewardCurrencies={{id=1553,amount=350}},mapCandidates={npc={},zone={8567}},questType="world",db2Objectives={{text="Win 1 Island Expedition",amount=1,type=0,objectID=147590,orderIndex=0}},worldTaskTitle="Set Sail",db2PoiMapID=1643,db2PoiUiMapID=1161,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[54169] = {id=54169,name="The Treasury Heist",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54169,54171,54510},description="The Abyssal Scepter is a powerful tidesage artifact and a serious threat to the fleet. The Horde stole it, but it is being held by the Zandalari in their treasury. The Storm's Wake has crafted a fake Scepter. Your first job is to obtain the real one without alerting suspicion. Speak to me when you are ready to go over the plan.",objectivesText="Retrieve the Abyssal Scepter from the Zandalari Treasury. Progress: Were you successful?",rewardGold=702000,rewardXP=10225,rewardCurrencies={{id=1553,amount=750}},starts={{npcID=146982}},ends={{npcID=146982}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={54171},questLines={{id=849,name="The Treasury Heist",orderIndex=1,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=849,questLineOrder=16,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=849,questLineOrder=9}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54170] = {id=54170,name="Ormin Rocketbop",level=10,requiredLevel=10,faction="horde",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={54170},rewardXP=2125,starts={{npcID=146979,mapID=864,x=0.3604,y=0.4961}},mapCandidates={npc={},zone={8501}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=146979}},worldTaskTitle="Ormin Rocketbop",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3513,db2VignetteName="Ormin Rocketbop"},
[54171] = {id=54171,name="The Abyssal Scepter",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54169,54171,54510},description="The Lord Admiral has proposed our next move. It's something we don't think the Horde will expect, but it's dangerous: We're going to steal back the Abyssal Scepter. Your name came up as someone who could see it through, if you're willing to take the chance. Meet Lady Jaina at our base in Xibala. She'll have more information for you there.",objectivesText="Meet with Jaina Proudmoore in Xibala in Zuldazar.",rewardGold=23400,rewardXP=1705,starts={{npcID=135612}},ends={{npcID=146982}},mapCandidates={npc={862,1161},zone={8568}},questType="standard",sourceQuests={54206},questLines={{id=849,name="The Treasury Heist",orderIndex=0,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=849,questLineOrder=16,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=849,questLineOrder=9}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54172] = {id=54172,name="The Azsharan Medallion",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=862,storyline={53760,53761,53762,53763,53766,54058,54117,54118,54172,54174,54433,54439,54683},description="<On the naga's body you find an ornate metal disc. The writing on its surface resembles elven script, but you cannot decipher it. You suspect the words are written in the Nazja tongue. Perhaps someone with a knowledge of naga artifacts could translate the text.>",objectivesText="Take the Medallion to Collector Kojo .",rewardGold=23400,rewardXP=850,rewardItems={164761,165605,165668,168123},rewardCurrencies={{id=1553,amount=400}},ends={{npcID=134345}},coords={mapID=862,source="quest_giver",x=0.714,y=0.302},mapCandidates={npc={862},zone={8567}},questType="standard",questLines={{id=851,name="Crucible of Storms",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862,startItems={165668}},
[54174] = {id=54174,name="Orders from Azshara",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={53760,53761,53762,53763,53766,54058,54117,54118,54172,54174,54433,54439,54683},series={53760,53761,53762,54058,54113,54114,54117,54118,54144,54265,54433},description="<Kojo studies the medallion and grimaces.> Ugh... naga. This medallion is inscribed with orders. Looks like naga have been commanded to invade our shores and seize artifacts of great power. You know, I recently came upon one such object. See that dagger over there? Nasty thing. Gives me the willies. I swear I hear it whispering to me. I found it nearby at Atal'Gral, on a makeshift altar. Maybe if you take it there, you'll get an idea of how the naga intended to use it.",objectivesText="Take the Dagger to the Makeshift Altar. Progress: <As you place the dagger upon the altar, it seems to shudder and blink at you.>",rewardGold=23400,rewardXP=850,rewardItems={164761,165605,168123},starts={{npcID=134345}},ends={{npcID=134345}},mapCandidates={npc={862},zone={8499}},questTurnInID=134345,questType="standard",sourceQuests={54172},questLines={{id=851,name="Crucible of Storms",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[54175] = {id=54175,name="Face Your Enemy",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={54121,54175,54176,54177,54178,54179},description="We have decided that our best course of action would be to enter the prison disguised as Proudmoore military. Rexxar will be our prisoner. We want to keep a low profile until we break Ashvane out. I find that I work better with reference when undertaking this type of endeavor. I have chosen some humans that interest me. I would like to examine their faces. Use the Shard of Vesara on them, and they will be... encouraged to find their way to me.",objectivesText="Send the targets chosen by Valtrois back for examination.",rewardGold=234000,rewardXP=6815,rewardItems={164987,165702,165734,166309},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=147088}},ends={{npcID=147088}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={54121},questLines={{id=848,name="Escape from Tol Dagor",orderIndex=1,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=848,questLineOrder=17,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=848,questLineOrder=9}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[54176] = {id=54176,name="Be More Uniform",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={54121,54175,54176,54177,54178,54179},description="Head into the foundry. Proudmoore's guards have taken over there. They will provide excellent accessories for our disguises. I can recreate their faces, but without the clothing, we won't make it far. Gather enough gear to cover us. We'll need the Captain's jacket as well. There will be less of a challenge at the gate if we outrank them.",objectivesText="Collect gear from Proudmoore forces in the foundry. Progress: Was the harvest successful?",rewardGold=234000,rewardXP=6815,rewardItems={164987,165697,165698,165702,165734,166309},starts={{npcID=147088}},ends={{npcID=147088}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={54121},questLines={{id=848,name="Escape from Tol Dagor",orderIndex=2,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=848,questLineOrder=17,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=848,questLineOrder=9}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[54177] = {id=54177,name="A Brilliant Distraction",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10272,mapID=895,storyline={54121,54175,54176,54177,54178,54179},description="We plan to be cautious on entry to Tol Dagor. I imagine our exit will not be as... subtle. That foundry to the west... I hear they made Azerite explosives there. Stock up, we will need them.",objectivesText="Retrieve the Volatile Azerite . Progress: Did you find them all?",rewardGold=234000,rewardXP=6815,rewardItems={164987,165690,165702,165734,166309},starts={{npcID=146931}},ends={{npcID=146931}},mapCandidates={npc={895},zone={10272}},questType="standard",sourceQuests={54121},questLines={{id=848,name="Escape from Tol Dagor",orderIndex=3,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=848,questLineOrder=17,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=848,questLineOrder=9}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[54178] = {id=54178,name="Catching a Ride",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={54121,54175,54176,54177,54178,54179},series={54179},description="Nathanos should have found a boat by now. Let us hasten to meet him in the harbor. It behooves us to take care of this business quickly. There are better ways for us to support the Horde's effort here.",objectivesText="Find Nathanos at the dock in Plunder Harbor.",rewardGold=23400,rewardXP=850,rewardItems={164987,165702,165734,166309},starts={{npcID=147088}},ends={{npcID=147135}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={54175,54176,54177},questLines={{id=848,name="Escape from Tol Dagor",orderIndex=4,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=848,questLineOrder=17,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=848,questLineOrder=9}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[54179] = {id=54179,name="Through the Front Door",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={54121,54175,54176,54177,54178,54179},series={54178},description="We would like the least amount of risk during your retrieval of Priscilla Ashvane. You will arrive on the docks during a shift change. From there, you will prepare and enter the prison. Find me in Zuldazar when you are successful.",objectivesText="Complete \"Escape from Tol Dagor\".",rewardGold=468000,rewardXP=8520,rewardItems={163280,163282,163283,163424,163426,163432,163435,163441,163446,163453,163456,163459,164987,165702,165734,166309},rewardChoices={163280,163282,163283,163424,163426,163432,163435,163441,163446,163453,163456,163459},rewardCurrencies={{id=1553,amount=750}},starts={{npcID=147135}},ends={{npcID=135691}},mapCandidates={npc={862,895},zone={8567}},questType="standard",sourceQuests={54178},questLines={{id=848,name="Escape from Tol Dagor",orderIndex=5,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=848,questLineOrder=17,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=848,questLineOrder=9}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54182] = {id=54182,name="Bilgewater Bash Brothers",level=10,requiredLevel=10,faction="alliance",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={54182},rewardXP=2125,starts={{npcID=147061,mapID=895,x=0.8419,y=0.352}},mapCandidates={npc={},zone={8567}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=147061},{orderIndex=1,type=0,amount=1,objectID=147062}},worldTaskTitle="Bilgewater Bash Brothers",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3420,db2VignetteName="Grubb"},
[54183] = {id=54183,name="Dead Reckoning",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54163,54183},description="While I have some concerns, I cannot deny the bravery, heroism and sacrifices we have made. That you have made, <name>. Thank you for all the aid you have given to the Alliance. The future of our ongoing war campaign is why I have asked everyone here. I wish to look at what we've done, so we can decide on the best way forward.",objectivesText="Attend the discussion in Unity Square. Progress: This war may have been necessary, but it is my hope it will be over soon. Then we can begin rebuilding.",rewardGold=117000,rewardXP=3410,rewardCurrencies={{id=1553,amount=750}},starts={{npcID=147885}},ends={{npcID=147885}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={54163},questLines={{id=847,name="The Price of Victory",orderIndex=1,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=847,questLineOrder=18,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=847,questLineOrder=11}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=1161},
[54184] = {id=54184,name="Trouble in Gnomeregan",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54184},series={54185,54276},description="Some strange spikes of electric usage have been happening in Gnomeregan recently. We need you to investigate what is going in there as soon as possible. We've received contact from one of the chief engineers in charge of keeping things in Gnomeregan under control, and he has offered to assist us in getting inside to see what's going on.",objectivesText="Find Micro Zoox outside of Gnomeregan in Dun Morogh.",rewardGold=23400,rewardXP=850,starts={{npcID=147645}},ends={{npcID=147645}},mapCandidates={npc={1161},zone={8568}},questTurnInID=147645,questType="standard",nextQuests={54185}},
[54185] = {id=54185,name="Gnomeregan's New Guardians",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=1,storyline={54185},series={54184,54276},description="My personally-modified Mayhem Detection Device has been giving readings off the charts for the last few days. You might be thinking that mayhem and Gnomeregan are synonymous, and to an extent they are, but these readings are beyond anything I've seen before! I'm not totally sure what's going on inside of Gnomeregan, but something is different. If you are feeling brave enough, I can teleport you deep in there and you can see for yourself. Let me know when you are ready.",objectivesText="Defeat Pulverizer Bot Mk 6001 in Gnomeregan. Progress: I can teleport you in. Getting out might be more of a challenge.",rewardGold=936000,rewardXP=13630,rewardItems={103670,122457},starts={{npcID=147070}},ends={{npcID=147070}},mapCandidates={npc={},zone={1}},questGiverID=147070,questTurnInID=147070,questType="standard",sourceQuests={54184,54276},db2QuestSortName="Epic"},
[54186] = {id=54186,name="Pet Battle Challenge: Gnomeregan",level=50,requiredLevel=50,faction="both",categories={},flags={"weekly","repeatable"},sharable=false,expansion=7,zoneID=1,storyline={54186},description="Gnomeregan's at Mayhem Level Maximum again. Those machines just don't give up, and keep coming back. I can teleport us in there again, but all of those crazy robots are back. You sure you want this? I don't. I mean, maybe I want to watch robots smash things for some entertainment. I'm sure you will be fine. Lets go!",objectivesText="Defeat Pulverizer Bot Mk 6001 in Gnomeregan. Progress: I can teleport you in. Getting out might be more of a challenge.",rewardGold=234000,rewardXP=6815,rewardItems={93351,109076,165835},starts={{npcID=147070}},ends={{npcID=147070}},mapCandidates={npc={},zone={1}},questGiverID=147070,questTurnInID=147070,questType="standard",sourceQuests={54185},db2QuestSortName="Epic"},
[54187] = {id=54187,name="Tea for Two",expansion=7,mapID=896,questType="world",worldTaskTitle="Tea for Two",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[54188] = {id=54188,name="Scrambled Bots",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={54188},objectivesText="Bot Scrambler obtained Siege Shredders destroyed Crawler Mines destroyed Power Control disabled",rewardXP=2125,rewardItems={165841},mapCandidates={npc={},zone={8568}},questType="standard",db2Objectives={{text="Bot Scrambler obtained",amount=1,type=1,objectID=165841,orderIndex=0},{text="Siege Shredders destroyed",amount=4,type=0,objectID=144705,orderIndex=1},{text="Crawler Mines destroyed",amount=8,type=0,objectID=144994,orderIndex=2},{text="Power Control disabled",amount=1,type=0,objectID=147147,orderIndex=3}},worldTaskTitle="Scrambled Bots",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[54189] = {id=54189,name="Desert Crawl",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={54189},objectivesText="Crawler parts collected Use remote mine controls Ace Steam Tank destroyed",rewardXP=2125,rewardItems={164742},mapCandidates={npc={},zone={8501}},questType="standard",db2Objectives={{text="Crawler parts collected",amount=8,type=1,objectID=164742,orderIndex=0},{text="Use remote mine controls",amount=1,type=2,objectID=311183,orderIndex=1},{text="Ace Steam Tank destroyed",amount=1,type=0,objectID=147115,orderIndex=2}},worldTaskTitle="Desert Crawl",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[54190] = {id=54190,name="Tea for Two",expansion=7,mapID=896,questType="world",worldTaskTitle="Tea for Two",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[54191] = {id=54191,name="Changing Course",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54191,54192,54193,54194,54195,54196,54197,54198,54199,54200,54201,54202,54203,54204,54205,54206},series={54192},description="Champion, the time for action is upon us. Developments are underway that will change the course of this war. Report to me aboard Wind's Redemption as soon as possible.",objectivesText="Report to Halford Wyrmbane aboard Wind's Redemption in Boralus Harbor.",rewardGold=23400,rewardXP=850,rewardItems={43185,43186},ends={{npcID=135612}},coords={mapID=1161,source="quest_giver",x=0.6945,y=0.2665},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={53887},nextQuests={54192},questLines={{id=810,name="Serious Monkey Business",orderIndex=15,flags=1}},campaigns={{id=1,title="War Campaign",questLineID=810,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=810,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=1161},
[54192] = {id=54192,name="Sensitive Intel",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54191,54192,54193,54194,54195,54196,54197,54198,54199,54200,54201,54202,54203,54204,54205,54206},series={54191},description="I've received a report from Kelsey Steelspark . She claims to have discovered something that will aid our war effort. She's refused to go into specifics, citing a need for secrecy with such sensitive intel. It looks like you'll need to speak to her in person. She's expecting you in Xibala.",objectivesText="Meet Kelsey Steelspark in Zuldazar.",rewardGold=23400,rewardXP=850,starts={{npcID=135612}},ends={{npcID=147151}},mapCandidates={npc={862,1161},zone={8568}},questType="standard",sourceQuests={54191},questLines={{id=810,name="Serious Monkey Business",orderIndex=0,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=810,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=810,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54193] = {id=54193,name="This is Huge!",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54191,54192,54193,54194,54195,54196,54197,54198,54199,54200,54201,54202,54203,54204,54205,54206},description="$p, allow me to introduce Megs and Morton, the gnomes who are going to shake things up for the Alliance in a big way! They've been perfecting a device that can take any ordinary animal and turn it into a humongous, unstoppable beast that we can then unleash on our enemies! I'll let Megs and Morton fill you in on the specifics, but I promise you, this tech is a game changer!",objectivesText="Listen to Megs and Morton's plan. Progress: Wait until you hear their big plan. It's perfect!",rewardGold=117000,rewardXP=3410,starts={{npcID=147151}},ends={{npcID=147151}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={54192},questLines={{id=810,name="Serious Monkey Business",orderIndex=1,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=810,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=810,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54194] = {id=54194,name="Real Big Power",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54191,54192,54193,54194,54195,54196,54197,54198,54199,54200,54201,54202,54203,54204,54205,54206},description="We're still building a harness for the Embiggifier, but we need to test its core first. That's where the real power is! This technology is years ahead of the Horde's, but it's so easy to use that even an orc could do it! Just point and click!",objectivesText="Test the Embiggifier on a Kul Tiran Clucker . Progress: I love this part! When we get to see all our hard work pay off in a big way!",rewardGold=234000,rewardXP=6815,rewardItems={165723},rewardCurrencies={{id=1553,amount=115}},starts={{npcID=147148}},ends={{npcID=147148}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={54193},questLines={{id=810,name="Serious Monkey Business",orderIndex=2,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=810,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=810,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54195] = {id=54195,name="A Beast with Brains",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54191,54192,54193,54194,54195,54196,54197,54198,54199,54200,54201,54202,54203,54204,54205,54206},description="For optimal results, the Embiggifier should be used on someone with substantial intellect. Good thing our partner is as smart as they come. He and his kind have been empowered by kaja'mite, granting them exceptional intelligence! Head up to the gorge and let Grong know we're ready to begin the embiggifying!",objectivesText="Find Grong within Gorilla Gorge.",rewardGold=117000,rewardXP=3410,starts={{npcID=147148}},ends={{npcID=147228}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={54194},questLines={{id=810,name="Serious Monkey Business",orderIndex=3,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=810,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=810,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54196] = {id=54196,name="Out of Options",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54191,54192,54193,54194,54195,54196,54197,54198,54199,54200,54201,54202,54203,54204,54205,54206},description="My kind are hunted like animals. We've tried to reach a resolution through civil discourse, but these poachers recoil from rational thought. They revel in brutality. I ask you, $p: Who are the real animals? It pains me to descend to their level, but I fear I've exhausted all other options.",objectivesText="Kill 12 Bilgewater goblins within Gorilla Gorge. Progress: It pains me to descend to their level, but I fear I've exhausted all other options.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1553,amount=500}},starts={{npcID=147228}},ends={{npcID=147228}},mapCandidates={npc={862},zone={8499}},questTurnInID=147228,questType="standard",sourceQuests={54195},questLines={{id=810,name="Serious Monkey Business",orderIndex=4,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=810,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=810,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54197] = {id=54197,name="Freedom for the Da'kani",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54191,54192,54193,54194,54195,54196,54197,54198,54199,54200,54201,54202,54203,54204,54205,54206},description="Have you seen the barbaric conditions to which the Da'kani are subjected? Corralled and caged, awaiting slaughter, or worse... I cannot leave here in good faith without first seeing that my kind are liberated.",objectivesText="Free 8 Da'kani Highbrows within Gorilla Gorge.",rewardGold=234000,rewardXP=6815,starts={{npcID=147228}},ends={{npcID=147228}},mapCandidates={npc={862},zone={8499}},questTurnInID=147228,questType="standard",sourceQuests={54195},questLines={{id=810,name="Serious Monkey Business",orderIndex=5,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=810,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=810,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54198] = {id=54198,name="Bittersweet Goodbyes",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54191,54192,54193,54194,54195,54196,54197,54198,54199,54200,54201,54202,54203,54204,54205,54206},description="You've helped me prepare my village for my departure, but now I must prepare myself. Meet me within the grotto, where I will say my farewells.",objectivesText="Meet Grong within Grong 's Grotto.",rewardGold=23400,rewardXP=850,starts={{npcID=147293}},ends={{npcID=147228}},mapCandidates={npc={862},zone={8499}},questGiverID=147293,questType="standard",sourceQuests={54196,54197},questLines={{id=810,name="Serious Monkey Business",orderIndex=6,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=810,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=810,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54199] = {id=54199,name="The Needs of the Many",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54191,54192,54193,54194,54195,54196,54197,54198,54199,54200,54201,54202,54203,54204,54205,54206},description="Ever since the kaja'mite began bubbling around the gorge, I have been searching for meaning. Why was I burdened with intelligence? What is my purpose? I have found my answers in the Embiggifier. I was meant to help the Alliance defeat the Horde. If I can save lives by volunteering, then my choice is clear. The needs of the many outweigh the needs of one. I am ready, $p.",objectivesText="Accompany Grong to Xibala.",rewardGold=23400,rewardXP=850,rewardCurrencies={{id=1553,amount=500}},starts={{npcID=147228}},ends={{npcID=147149}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={54198},questLines={{id=810,name="Serious Monkey Business",orderIndex=7,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=810,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=810,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54200] = {id=54200,name="Bring the Base",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54191,54192,54193,54194,54195,54196,54197,54198,54199,54200,54201,54202,54203,54204,54205,54206},description="We'll need to collect some baseline statistics before we use the Embiggifier. Grong will be asked to perform basic tasks pertaining to speed, intelligence, and strength. This will help us measure the increase once he's been embiggified.",objectivesText="Help collect baseline stats for Grong's speed, intelligence, and strength.",rewardGold=234000,rewardXP=6815,starts={{npcID=147149}},ends={{npcID=147311}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={54199},questLines={{id=810,name="Serious Monkey Business",orderIndex=8,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=810,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=810,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54201] = {id=54201,name="Fit for Grong",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54191,54192,54193,54194,54195,54196,54197,54198,54199,54200,54201,54202,54203,54204,54205,54206},description="Grong is already impressively large. In fact, I don't think our Embiggifier is going to fit around his noggin without some modification. I'll require an ample supply of ore to make the necessary adjustments, but we're in luck. The goblins nearby have already done the work of mining it; we just need to take it off their hands! Secure an ample amount of Azerite-infused ore, and we'll be back in business!",objectivesText="Collect 12 Azerite Infused Ore . Progress: Have you acquired the ore?",rewardGold=234000,rewardXP=6815,rewardItems={165759},starts={{npcID=147311}},ends={{npcID=147311}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={54200},questLines={{id=810,name="Serious Monkey Business",orderIndex=9,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=810,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=810,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54202] = {id=54202,name="Calibrate the Core",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54191,54192,54193,54194,54195,54196,54197,54198,54199,54200,54201,54202,54203,54204,54205,54206},description="The Embiggifier is nearly ready! All that's left to do is calibrate its core. The best way to do that without catastrophic results is to use it on things that are already dead. This should be a simple task! I have a hunch you excel at making things dead.",objectivesText="Calibrate the Embiggifier's core by using it on dead things within Bilgewater Bonanza. Progress: Have you calibrated the core yet?",rewardGold=234000,rewardXP=6815,rewardItems={165762},rewardCurrencies={{id=1553,amount=350}},starts={{npcID=147148}},ends={{npcID=147148}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={54200},questLines={{id=810,name="Serious Monkey Business",orderIndex=10,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=810,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=810,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54203] = {id=54203,name="The Embiggining",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54191,54192,54193,54194,54195,54196,54197,54198,54199,54200,54201,54202,54203,54204,54205,54206},description="I'll give you the quick rundown before we get started. The Embiggifier is remotely controlled. See this big red button? < Megs gestures to the device in her hand.> This jolts the wearer with a surge of power, making them bigger. For safety reasons, you should remain here at camp. I think that's it! Are you ready to science?",objectivesText="Test Grong's stats while embiggified. Progress: Let's see what Grong can do once he's been embiggified!",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1553,amount=500}},starts={{npcID=147148}},ends={{npcID=147148}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={54201,54202},questLines={{id=810,name="Serious Monkey Business",orderIndex=11,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=810,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=810,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54204] = {id=54204,name="Total Temple Destruction",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54191,54192,54193,54194,54195,54196,54197,54198,54199,54200,54201,54202,54203,54204,54205,54206},description="Grong is our greatest achievement, and he's ready to be unleashed! The Horde is staging its troops at a temple to the north. Magister Umbric's portal will get you there fast. Then Grong can get to work!",objectivesText="Command Grong to defeat the Horde at Temple of the Prophet.",rewardGold=468000,rewardXP=8520,rewardCurrencies={{id=1553,amount=500}},starts={{npcID=147148}},ends={{npcID=147519}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={54203},questLines={{id=810,name="Serious Monkey Business",orderIndex=12,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=810,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=810,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54205] = {id=54205,name="A Nice Nap",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54191,54192,54193,54194,54195,54196,54197,54198,54199,54200,54201,54202,54203,54204,54205,54206},description="I'm not sure how much longer those chains will hold. Grong 's going to have to take a little nap until he's ready to be deployed. Use this dart. It's been double-dipped in something potent enough to take down a direhorn, so it should do the trick. Grong would want you to be the one to do it.",objectivesText="Use the Tranquilizer Dart on Grong . Progress: Go ahead, use the dart on Grong . He won't feel a thing, I promise.",rewardGold=117000,rewardXP=3410,rewardItems={165815},starts={{npcID=147519}},ends={{npcID=147519}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={54204},questLines={{id=810,name="Serious Monkey Business",orderIndex=13,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=810,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=810,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54206] = {id=54206,name="The Sleeper Agent",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54191,54192,54193,54194,54195,54196,54197,54198,54199,54200,54201,54202,54203,54204,54205,54206},description="Your work here is done, $p. Morton and Megs can take it from here. Head back to Boralus and let Halford know we've secured the weapon. Don't you worry one wink about Grong. Morton and Megs will make sure he's well looked after.",objectivesText="Report back to Halford Wyrmbane in Boralus Harbor.",rewardGold=702000,rewardXP=10225,starts={{npcID=147519}},ends={{npcID=135612}},mapCandidates={npc={862,1161},zone={8499}},questType="standard",sourceQuests={54205},questLines={{id=810,name="Serious Monkey Business",orderIndex=14,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=810,questLineOrder=15,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=810,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=1161},
[54207] = {id=54207,name="Retaking the Outpost",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=862,storyline={54139,54140,54156,54157,54207,54208,54211,54212,54213,54224,54244,54249,54269,54270,54271,54275,54280},description="We can handle de rest of de Alliance. I received a report that Hexlord Raal 's forces are having issues up ahead. He claims dat dere is an even thicker fog enveloping Nazmir. De Alliance must be using some tricks to slow us down. Go to Nazmir to see what can be done to help Hexlord Raal . We must reach dat fleet and destroy de Alliance!",objectivesText="Meet Hexlord Raal in Nazmir.",rewardGold=23400,rewardXP=850,starts={{npcID=147075}},ends={{npcID=147139}},mapCandidates={npc={862,863},zone={8500}},questType="standard",sourceQuests={54156,54157},questLines={{id=841,name="The Fury of the Zandalari",orderIndex=4,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=841,questLineOrder=18,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=841,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[54208] = {id=54208,name="Minesweeper",level=50,requiredLevel=50,faction="horde",requiredClasses={4},categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8670,mapID=863,storyline={54139,54140,54156,54157,54207,54208,54211,54212,54213,54224,54244,54249,54269,54270,54271,54275,54280},description="The Alliance are stalling our efforts here with this irritating fog, as well as layering the entire area with traps. We will suffer too many casualties if we try marching our army through this trap-infested area. I've heard you're good at sneaking around. Use your talents to disarm the traps in this area. I'll deal with getting the goblin's parts back from the Alliance while you disarm those traps.",objectivesText="Disarm 10 traps within the Fallen Outpost.",rewardGold=234000,rewardXP=6815,starts={{npcID=147145}},ends={{npcID=147145}},mapCandidates={npc={863},zone={8670}},questType="standard",sourceQuests={54207},questLines={{id=841,name="The Fury of the Zandalari",orderIndex=5,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=841,questLineOrder=18,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=841,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[54211] = {id=54211,name="Putting the Gob in Gob Squad",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={54139,54140,54156,54157,54207,54208,54211,54212,54213,54224,54244,54249,54269,54270,54271,54275,54280},description="Yo! We gotta get the rest of the Gob Squad back if we wanna fix the A.F.M.O.D.! So, our mech got trashed. It was rough. The rest of the Gob Squad are hidin' out there, waiting for word when it's safe. Take this tracker. It'll tell ya when you're getting close to one of the squad. When you get real close, you should see 'em. That'll tell any of the squad nearby that it's safe to come outta hidin' and come back here. With the right goblins and parts, we'll be killing Alliance in no time!",objectivesText="Rescue the Gob Squad. Progress: You didn't blow up the Gob Squad tracker, did you?",rewardGold=234000,rewardXP=6815,starts={{npcID=147155}},ends={{npcID=147155}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={54207},questLines={{id=841,name="The Fury of the Zandalari",orderIndex=6,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=841,questLineOrder=18,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=841,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[54212] = {id=54212,name="Re-rebuilding the A.F.M.O.D.",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={54139,54140,54156,54157,54207,54208,54211,54212,54213,54224,54244,54249,54269,54270,54271,54275,54280},description="Alright, so, we're goin' after the Alliance through this crazy fog. We gotta retake Zo'bal ruins up ahead. We can do that real easy if we fix up our mech, A.F.M.O.D. - a flying mech of death! The Alliance wrecked it in their initial attack and took a bunch of its parts. Get those parts back and we'll have this thing fixed in no time!",objectivesText="Recover 10 A.F.M.O.D. parts from Gilnean Ambushers and Night Elf Sentinels. Progress: You got the parts? We'll figure out what goes where when it's all done.",rewardGold=234000,rewardXP=6815,rewardItems={165710},rewardCurrencies={{id=1553,amount=350}},starts={{npcID=147155}},ends={{npcID=147155}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={54207},questLines={{id=841,name="The Fury of the Zandalari",orderIndex=7,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=841,questLineOrder=18,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=841,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[54213] = {id=54213,name="It's Alive!",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={54139,54140,54156,54157,54207,54208,54211,54212,54213,54224,54244,54249,54269,54270,54271,54275,54280},description="We got the A.F.M.O.D. repaired and it works perfectly! Eh, except that it's got no power. Princess Talanji seems like she can help us out with this. Ask her if she can give the mech a jumpstart! Once we're set, we can use this thing to mow down the Alliance, take back Zul'jan ruins, and push forward to blow up that fleet!",objectivesText="Speak with Talanji to power up the A.F.M.O.D. Progress: Uh, can we get this thing started or what?",rewardGold=234000,rewardXP=6815,rewardItems={30226,30252,36884,36885,36886,36887,58915,58916,58917,131497},starts={{npcID=147155}},ends={{npcID=147155}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={54211,54212},questLines={{id=841,name="The Fury of the Zandalari",orderIndex=8,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=841,questLineOrder=18,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=841,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[54224] = {id=54224,name="The Battle of Zul'jan Ruins",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=862,storyline={54139,54140,54156,54157,54207,54208,54211,54212,54213,54224,54244,54249,54269,54270,54271,54275,54280},description="General Rakera has pushed forward with de army. Raal and his forces are still grounded until we remove dis fog. You must pilot de A.F.M.O.D. and help our forces retake Zul'jan ruins. Only den can we move ahead to stop de Alliance and dis fog. Rokhan, and I will join you. De Alliance must see dat our victory is swift and decisive. I would have our enemies cower before us when dey meet dere ends. Such is de price for defiling our lands.",objectivesText="Pilot the A.F.M.O.D. and retake Zul'jan ruins.",rewardGold=468000,rewardXP=8520,rewardCurrencies={{id=1553,amount=500}},starts={{npcID=146921}},ends={{npcID=146921}},mapCandidates={npc={862},zone={8500}},questType="standard",sourceQuests={54213},questLines={{id=841,name="The Fury of the Zandalari",orderIndex=9,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=841,questLineOrder=18,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=841,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[54225] = {id=54225,name="Mission Report: The Great Seal",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={54225},series={54231},description="Your followers have sent a report regarding the mission at The Great Seal. It details that the mission was a success and that a Mission Command Table has been constructed. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.",objectivesText="Deliver the mission report to Nathanos Blightcaller . Progress: Do you have news regarding the mission to The Great Seal?",rewardGold=23400,rewardXP=850,rewardItems={165726},starts={{npcID=138706}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questGiverID=138706,questType="standard"},
[54231] = {id=54231,name="Outpost Upgrade: The Great Seal",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54231},series={54225},description="The mission at The Great Seal was a success. Well done, <name>. A Mission Command Table is now ready for use. Travel to The Great Seal and see that the troops quality of work is up to our standard.",objectivesText="Inspect the Mission Command Table at The Great Seal.",rewardGold=234000,rewardXP=6815,starts={{npcID=135691}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questTurnInID=135691,questType="standard",sourceQuests={54225}},
