[54239] = {id=54239,name="Mission Report: Zul'jan Ruins",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={54239},series={54240},description="Your followers have sent a report regarding the mission at Zul'jan Ruins. It details that the mission was a success and that the power of the Loa has increased, allowing for Boons to persist longer. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.",objectivesText="Deliver the mission report to Nathanos Blightcaller . Progress: Do you have news regarding the mission to Zul'jan Ruins?",rewardItems={165752},starts={{npcID=138704}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questGiverID=138704,questType="standard"},
[54240] = {id=54240,name="Outpost Upgrade: Zul'jan Ruins",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54240},series={54239},description="The mission at Zul'jan Ruins was a success. Well done, <name>. The Boons of the Loa are now more powerful and will be granted whenever you are in Zandalar. Travel to the Zul'jan Ruins and honor an altar of your choice.",objectivesText="Choose a Loa Boon from the altars at Zul'jan Ruins.",starts={{npcID=135691}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questTurnInID=135691,questType="standard",sourceQuests={54239}},
