[54244] = {id=54244,name="We Have Them Cornered",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=862,storyline={54139,54140,54156,54157,54207,54208,54211,54212,54213,54224,54244,54249,54269,54270,54271,54275,54280},description="General Rakera has already begun mobilizing our forces to our next target: Zalamar. Once we destroy de Alliance dere, we can push forward to de coast and destroy de source of dis fog. De Alliance will have nowhere to hide. We will surround their fleet and end dis war, once for all. Dey will wish dey never stepped foot in Nazmir. Come. We shall ride together to Zalamar and ensure our victory!",objectivesText="Ride with Princess Talanji and Rokhan to Zalamar. Progress: We must move!",rewardGold=23400,rewardXP=850,starts={{npcID=146921}},ends={{npcID=146921}},mapCandidates={npc={862},zone={8500}},questType="standard",sourceQuests={54224},questLines={{id=841,name="The Fury of the Zandalari",orderIndex=10,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=841,questLineOrder=18,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=841,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
