[54249] = {id=54249,name="Zandalari Justice",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=862,storyline={54139,54140,54156,54157,54207,54208,54211,54212,54213,54224,54244,54249,54269,54270,54271,54275,54280},description="We must wipe out whatever is left of de Alliance in Zalamar. Den we can find de source of dis fog and dere fleet. Rokhan will scout ahead to find dis Telaamon. He appears to be de general leading de forces here. I need you to go in and wipe out de Alliance forces within Zalamar so dat we can crush dem once and for all. Find Rokhan in Zalamar after dey have been weakened.",objectivesText="Defeat 15 Alliance forces within Zalamar. Progress: We must keep up de pressure on de Alliance.",rewardGold=234000,rewardXP=6815,starts={{npcID=146921}},ends={{npcID=147233}},mapCandidates={npc={862},zone={8500}},questType="standard",sourceQuests={54244},questLines={{id=841,name="The Fury of the Zandalari",orderIndex=11,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=841,questLineOrder=18,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=841,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
