[54269] = {id=54269,name="None Shall Escape",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=862,storyline={54139,54140,54156,54157,54207,54208,54211,54212,54213,54224,54244,54249,54269,54270,54271,54275,54280},description="De Alliance are using de Dark Iron's mole machines to transport troops in and out of Zalamar. We need dose machines destroyed. We are going to establish Zalamar as our forward base to attack de Alliance's main fleet. Take out dem machines, den find Rokhan within Zalamar. He be tracking down where de Alliance general be hidin'.",objectivesText="Destroy 4 Mole Machines.",rewardGold=234000,rewardXP=6815,starts={{npcID=147075}},ends={{npcID=147233}},mapCandidates={npc={862},zone={8500}},questType="standard",sourceQuests={54244},questLines={{id=841,name="The Fury of the Zandalari",orderIndex=12,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=841,questLineOrder=18,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=841,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[54270] = {id=54270,name="Breaking Mirrors",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=862,storyline={54139,54140,54156,54157,54207,54208,54211,54212,54213,54224,54244,54249,54269,54270,54271,54275,54280},description="We have reports dat Telaamon, de Lightforged in charge of dis attack, can create mirror images of himself to strike us down. Two Zandalari, Witch Doctor Kejabu and Jo'chunga, have offered to go in and help fight his mirror images. I want you to ensure dey survive. Eliminating dese strange images should make Telaamon weaker, allowing you and Rokhan to slay him.",objectivesText="Defeat Telaamon's mirror images within Zalamar. Progress: Are de Zandalari safe?",rewardGold=468000,rewardXP=8520,starts={{npcID=147075}},ends={{npcID=147233}},mapCandidates={npc={862},zone={8500}},questType="standard",sourceQuests={54244},questLines={{id=841,name="The Fury of the Zandalari",orderIndex=13,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=841,questLineOrder=18,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=841,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[54271] = {id=54271,name="Telaamon's Purge",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=862,storyline={54139,54140,54156,54157,54207,54208,54211,54212,54213,54224,54244,54249,54269,54270,54271,54275,54280},description="Telaamon, de Lightbringer leadin' dis assault, be in Hir'eek's cave. He must be thinkin' he can take us all by himself. When he is dead, we be sendin' dis assault force into chaos, allowin' us ta be marchin' on de Alliance along de shore. And hopefully, we can be findin' de source of de fog and destroyin' it. Da three of us be ambushin' Telaamon once ya start fightin'. He ain't gettin' outta here alive.",objectivesText="Defeat Telaamon.",rewardGold=468000,rewardXP=8520,rewardCurrencies={{id=1553,amount=1000}},starts={{npcID=147233}},ends={{npcID=147233}},mapCandidates={npc={862},zone={8500}},questType="standard",sourceQuests={54249,54269,54270},questLines={{id=841,name="The Fury of the Zandalari",orderIndex=14,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=841,questLineOrder=18,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=841,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[54272] = {id=54272,name="Battle Bots",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={54272},objectivesText="Alkalescent Salt collected Give Salts to Binny",rewardXP=2125,rewardItems={165852,165879,166715,166732,166733,166734},mapCandidates={npc={},zone={8501}},questType="standard",db2Objectives={{text="Alkalescent Salt collected",amount=10,type=1,objectID=165852,orderIndex=0},{text="Give Salts to Binny",amount=1,type=0,objectID=147649,orderIndex=1}},worldTaskTitle="Battle Bots",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[54273] = {id=54273,name="Battle Bots",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={54273},objectivesText="Alkalescent Salt collected Give Salts to Blixthraz",rewardXP=2125,rewardItems={165852},mapCandidates={npc={},zone={8501}},questType="standard",db2Objectives={{text="Alkalescent Salt collected",amount=10,type=1,objectID=165852,orderIndex=0},{text="Give Salts to Blixthraz",amount=1,type=0,objectID=147638,orderIndex=1}},worldTaskTitle="Battle Bots",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[54275] = {id=54275,name="Parting Mists",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=862,storyline={54139,54140,54156,54157,54207,54208,54211,54212,54213,54224,54244,54249,54269,54270,54271,54275,54280},description="It be time ta face de main Alliance fleet. Dey be on da beachhead nearby. I can be feelin' da dark voodoo from dat fog nearby. Princess Talanji be wantin' ta destroy dat mojo as soon as we can. I can be gettin' us outta dis cave real fast, den we be ridin' with da princess and Rakera ta put an end ta all dis.",objectivesText="Ride with Princess Talanji and destroy the Alliance fleet.",rewardGold=23400,rewardXP=850,starts={{npcID=147233}},ends={{npcID=146921}},mapCandidates={npc={862},zone={8500}},questType="standard",sourceQuests={54271},questLines={{id=841,name="The Fury of the Zandalari",orderIndex=15,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=841,questLineOrder=18,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=841,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[54276] = {id=54276,name="Trouble in Gnomeregan",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54276},series={54184,54185},description="Our engineers have reported surges of electric usage in Gnomeregan recently. We need you to investigate what is going in there as soon as possible. We made contact with one of the chief engineers in charge of keeping the robots in Gnomeregan under control, and he has offered to assist us in getting inside to see what's going on.",objectivesText="Find Micro Zoox outside of Gnomeregan in Dun Morogh.",rewardGold=23400,rewardXP=850,starts={{npcID=147641}},ends={{npcID=147641}},mapCandidates={npc={1165},zone={8670}},questTurnInID=147641,questType="standard",nextQuests={54185}},
[54280] = {id=54280,name="Fly Out to Meet Them",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=862,storyline={54139,54140,54156,54157,54207,54208,54211,54212,54213,54224,54244,54249,54269,54270,54271,54275,54280},description="De Alliance scum will pay for dis! Our army is moving as fast as it can to defend our city. Ride with Raal to get back to de entrance to our city. We must stop de Alliance!",objectivesText="Ride back to Zuldazar with Hexlord Raal .",rewardGold=23400,rewardXP=850,starts={{npcID=147075}},ends={{npcID=146921}},mapCandidates={npc={862},zone={8500}},questType="standard",sourceQuests={54271},questLines={{id=841,name="The Fury of the Zandalari",orderIndex=16,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=841,questLineOrder=18,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=841,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=862},
[54281] = {id=54281,name="Bombing Ballistae",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={54281},objectivesText="Horde invaders slain Ballistae destroyed",rewardXP=2125,mapCandidates={npc={},zone={8567}},questType="standard",db2Objectives={{text="Horde invaders slain",amount=8,type=0,objectID=147720,orderIndex=0},{text="Ballistae destroyed",amount=6,type=0,objectID=147706,orderIndex=1}},worldTaskTitle="Bombing Ballistae",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[54282] = {id=54282,name="Battle of Dazar'alor",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=10076,mapID=862,storyline={54282},description="Zandalar is already under attack! My people are fleeing and de Alliance are infesting my streets. Rakera's scouts say dat Jaina Proudmoore is leading de assault. She and her kind will pay for dis brazen assault on my people. Gather your allies and push de Alliance back. We must protect my father and destroy de Alliance!",objectivesText="Defeat Jaina Proudmoore in the Battle of Dazar'alor raid.",rewardGold=936000,rewardXP=13630,rewardCurrencies={{id=1553,amount=2000}},starts={{npcID=146921}},ends={{npcID=135691}},mapCandidates={npc={862},zone={8499}},questType="raid",sourceQuests={54280}},
[54284] = {id=54284,name="Mission Report: Castaway Point",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={54284},series={54288},description="Your followers have sent a report regarding the mission at Castaway Point. It details that they were successful in gaining access to an extremely large cannon. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.",objectivesText="Deliver the report to Halford Wyrmbane . Progress: Do you have news regarding the mission to Castaway Point?",rewardItems={165873,165875},starts={{npcID=138704}},ends={{npcID=135612}},mapCandidates={npc={1161},zone={8568}},questGiverID=138704,questType="standard"},
[54287] = {id=54287,name="Naga Attack!",level=10,requiredLevel=10,faction="none",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={54287},objectivesText="Repel the naga invaders",rewardXP=2125,rewardItems={165605,168003,168123},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{text="Repel the naga invaders",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Naga Attack!",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=111,db2QuestInfoName="Elite World Quest"},
[54288] = {id=54288,name="Outpost Upgrade: Castaway Point",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54288},series={54284},description="The mission at Castaway Point was a success. Well done, <name>. We now have access to a very large cannon which promises to be a fast way to travel to Tiragarde Sound. Glad that's not how I plan to get around. Travel to Castaway Point and enquire about this upgrade.",objectivesText="Talk to Dynamite Jack in Castaway Point.",rewardItems={165873},starts={{npcID=135612}},ends={{npcID=147747}},mapCandidates={npc={895,1161},zone={8568}},questType="standard",sourceQuests={54284}},
[54295] = {id=54295,name="Artillery Master Goodwin",level=10,requiredLevel=10,faction="horde",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={54295},rewardXP=2125,starts={{npcID=147750,mapID=895,x=0.8319,y=0.405}},mapCandidates={npc={},zone={8567}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=147750}},worldTaskTitle="Artillery Master Goodwin",db2PoiMapID=1643,db2PoiUiMapID=895,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3412,db2VignetteName="Artillery Master Goodwin"},
[54298] = {id=54298,name="Gravity Matters",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={54298},objectivesText="X-52 Delevitator obtained Pterrordax repelled",rewardXP=2125,rewardItems={165878},mapCandidates={npc={},zone={8499}},questType="standard",db2Objectives={{text="X-52 Delevitator obtained",amount=1,type=1,objectID=165878,orderIndex=0},{text="Pterrordax repelled",amount=10,type=0,objectID=147839,orderIndex=1}},worldTaskTitle="Gravity Matters",db2PoiMapID=1642,db2PoiUiMapID=862,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[54300] = {id=54300,name="Breaking the Faith",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53719,53823,53824,53825,53826,53827,53828,53830,53831,54031,54032,54033,54034,54300,54301,54419,54925},description="De faithful are among de most revered in Zandalari society. They are an example for others to aspire to. This is not de example we want others to follow. We must respond in kind. Princess Talanji wishes for us to spare them that will see reason. Do so, if you can find any willing to surrender. For de rest, give them a swift death.",objectivesText="Subdue 12 angered priests, druids, or prelates in the Terrace of the Chosen.",rewardGold=341600,rewardXP=5465,starts={{npcID=145360}},ends={{npcID=145360}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={53826,54419},questLines={{id=919,name="Allies of the Horde: Zandalari",orderIndex=7,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[54301] = {id=54301,name="Talanji's Mercy",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53719,53823,53824,53825,53826,53827,53828,53830,53831,54031,54032,54033,54034,54300,54301,54419,54925},description="I know my priests, <name>. Such an uproar did not appear out of thin air. There is much I have to atone for, but I am not yet ruler. I have not had de time to do what is needed for de faithful of Zandalar. That does not mean they deserve to suffer. Go into de Terrace of de Chosen and find them that refuse to fight. See that they get out safely. I will hold none of them accountable for de actions of others.",objectivesText="Evacuate 10 innocent bystanders in the Terrace of the Chosen. Progress: De people of Zandalar are my first priority, <name>.",rewardGold=312800,rewardXP=5465,starts={{npcID=145359}},ends={{npcID=145359}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={53826,54419},questLines={{id=919,name="Allies of the Horde: Zandalari",orderIndex=6,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[54302] = {id=54302,name="The Fall of Zuldazar",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54302,54303,54310,54312,54404,54407,54412,54417,54418,54421,54441,54459},description="It's time, <name>. We have the Abyssal Scepter, along with confirmation that the bombs placed amongst the Zandalari fleet are still active. Unfortunately, even with everything at our disposal, we would still lose a frontal assault against the Zandalari empire. For that reason, we plan to lure the forces of the Horde and the Zandalari away from the harbor. Mathias Shaw is holding a meeting nearby, and he has requested your presence.",objectivesText="Speak with Mathias Shaw in the garden within Proudmoore Keep. Progress: I take it you and the Lord Admiral were able to send the Horde packing?",rewardGold=23400,rewardXP=850,starts={{npcID=135612}},ends={{npcID=147798}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={54510},questLines={{id=845,name="Fog of War",orderIndex=0,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=845,questLineOrder=17,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=845,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=1161},
[54303] = {id=54303,name="The March to Nazmir",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={54302,54303,54310,54312,54404,54407,54412,54417,54418,54421,54441,54459},description="Greetings, <name>. I am Blademaster Telaamon , and I have volunteered to lead this mission against the Horde. Our forces will be gathering off the coast of Nazmir. Go now and we shall all meet there. If all goes according to plan, we will lure the Horde away from Zandalar and bring an end to this war.",objectivesText="Meet Jaina Proudmoore and the Alliance army in Nazmir.",rewardGold=23400,rewardXP=850,starts={{npcID=147819}},ends={{npcID=147842}},mapCandidates={npc={863,1161},zone={8568}},questType="standard",sourceQuests={54302},questLines={{id=845,name="Fog of War",orderIndex=1,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=845,questLineOrder=17,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=845,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[54306] = {id=54306,name="Mission Report: Arom's Stand",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={54306},series={54307},description="Your followers have sent a report regarding the mission at Arom's Stand. It details that they were successful in gaining access to a blessing from the Order of Embers. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.",objectivesText="Deliver the report to Halford Wyrmbane . Progress: Do you have news regarding the mission to Arom's Stand?",rewardItems={165880,165882},starts={{npcID=138704}},ends={{npcID=135612}},mapCandidates={npc={1161},zone={8568}},questGiverID=138704,questType="standard"},
[54307] = {id=54307,name="Outpost Upgrade: Arom's Stand",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54307},series={54306},description="The mission at Arom's Stand was a success. Well done, <name>. We now have access to a blessing from the Order of Embers. Travel to Arom's Stand and enquire about this blessing.",objectivesText="Talk to Cleric Loriette in Arom's Stand.",rewardItems={165880},starts={{npcID=135612}},ends={{npcID=147773}},mapCandidates={npc={896,1161},zone={8568}},questType="standard",sourceQuests={54306}},
[54308] = {id=54308,name="Mine Your Business",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=9698,mapID=942,storyline={54308},objectivesText="Blackpowder Ore collected",rewardXP=2125,rewardItems={165889},mapCandidates={npc={},zone={9698}},questType="standard",db2Objectives={{text="Blackpowder Ore collected",amount=16,type=1,objectID=165889,orderIndex=0}},worldTaskTitle="Mine Your Business",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[54310] = {id=54310,name="Repurposing Their Village",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={54302,54303,54310,54312,54404,54407,54412,54417,54418,54421,54441,54459},description="Myself and Shaw will provide support for Telaamon's army until our distraction is set up. First, we need to clear the blood trolls out of their nearby village, Zalamar, in order to move our army forward. That's where you come in. We need you to assault the blood trolls there to weaken their forces, then our army will arrive. Telaamon will be on site to help you, meet with him once you've weakened their forces. I will be here with Shaw ensuring our forces aren't seen.",objectivesText="Defeat 12 blood trolls within Zalamar. Progress: We must move, time is of the essence.",rewardGold=234000,rewardXP=6815,starts={{npcID=147842}},ends={{npcID=147844}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={54303},questLines={{id=845,name="Fog of War",orderIndex=2,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=845,questLineOrder=17,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=845,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[54312] = {id=54312,name="Fog of War",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={54302,54303,54310,54312,54404,54407,54412,54417,54418,54421,54441,54459},description="Do not mind this, I am finishing off this insect. You have bigger matters to handle. Our army is moving within Zalamar as we speak. But the Horde will know our army's true size without aid. Speak with Brother Pike and have him perform the ritual with the Abyssal Scepter to cover Nazmir in a thick fog. He claims the illusion will also mimic an entire fleet off the beach. Let us hope he is right. I will join you once I finish with this stain upon Azeroth.",objectivesText="Have Brother Pike use the Abyssal Scepter. Progress: We don't have time to discuss this, <name>. We must begin.",rewardGold=23400,rewardXP=850,rewardItems={81814,81815,81816,81817,81818},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=147844}},ends={{npcID=147842}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={54310,54404},questLines={{id=845,name="Fog of War",orderIndex=4,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=845,questLineOrder=17,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=845,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[54328] = {id=54328,name="Knight-Captain Joesiph",level=10,requiredLevel=10,faction="horde",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={54328},rewardXP=2125,starts={{npcID=147923,mapID=942,x=0.3178,y=0.5848}},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=147923}},worldTaskTitle="Knight-Captain Joesiph",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3438,db2VignetteName="Knight-Captain Joesiph"},
[54329] = {id=54329,name="Darkshore Donations: War Resources",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54329},objectivesText="Progress: Our forces are gathering for the battle to come. Do you wish to help further our efforts?",rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142158}},ends={{npcID=142158}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54330] = {id=54330,name="Darkshore Donations: Platinum Ore",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54330},objectivesText="Progress: Certain ore is harder to come by these days. If you find any platinum in your travels, it would go a long way in helping our cause.",rewardItems={152513},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142969}},ends={{npcID=142969}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54331] = {id=54331,name="Darkshore Donations: Winter's Kiss",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54331},objectivesText="Progress: Our herb stocks be runnin' low. Got any ta spare?",rewardItems={152508},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142159}},ends={{npcID=142159}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54332] = {id=54332,name="Darkshore Donations: Star Moss",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54332},objectivesText="Progress: It be better ta be well prepared dan be in short supply. If ya have any star moss ta spare, we'll be makin' good use of it.",rewardItems={152506},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142159}},ends={{npcID=142159}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54333] = {id=54333,name="Darkshore Donations: Storm Silver Ore",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54333},objectivesText="Progress: We produce blades and armor for our troops night and day, and such work requires materials. We need ore, all you can spare.",rewardItems={152579},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142969}},ends={{npcID=142969}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54334] = {id=54334,name="Darkshore Donations: Electroshock Mount Motivator",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54334},objectivesText="Progress: Our allies need to get to the front lines faster. Any thoughts on how we can accomplish this?",rewardItems={153573},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142983}},ends={{npcID=142983}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54335] = {id=54335,name="Darkshore Donations: Unstable Temporal Time Shifter",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54335},objectivesText="Progress: Our healers are spread thin and we need alternative methods to handle our fallen troops.",rewardItems={158379},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142983}},ends={{npcID=142983}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54336] = {id=54336,name="Darkshore Donations: XA-1000 Surface Skimmer",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54336},objectivesText="Progress: The enemy believes we will only attack by land. But we shall also flank them by sea. Have you any crafts that can help with this endeavor?",rewardItems={153512},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142983}},ends={{npcID=142983}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54337] = {id=54337,name="Darkshore Donations: Umbra Shard",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54337},objectivesText="Progress: Battles are won by dose wit powah. Powah comes from witin oneself. But enchantments help too and our supplies be runnin' low.",rewardItems={152876},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142992}},ends={{npcID=142992}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54338] = {id=54338,name="Darkshore Donations: Thermo-Accelerated Plague Spreader",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54338},objectivesText="Progress: Soldiers rely upon each other in battle. What do say we provide them with a little boost on the battlefield?",rewardItems={153494},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142983}},ends={{npcID=142983}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54339] = {id=54339,name="Darkshore Donations: Potion of Rising Death",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54339},objectivesText="Progress: I'd love to get my hands on a few combat potions. Da ya have any to spare?",rewardItems={152559},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142159}},ends={{npcID=142159}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54340] = {id=54340,name="Darkshore Donations: Enchant Ring - Seal of Haste",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54340},objectivesText="Progress: You be havin' any enchantments for me?",rewardItems={153439},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142992}},ends={{npcID=142992}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54341] = {id=54341,name="Darkshore Donations: Enchant Ring - Seal of Mastery",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54341},objectivesText="Progress: Any interesting finds lately?",rewardItems={153440},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142992}},ends={{npcID=142992}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54342] = {id=54342,name="Darkshore Donations: Potion of Bursting Blood",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54342},objectivesText="Progress: Not everyone is born a courageous warrior, but who says you can't temporarily behave as such?",rewardItems={152560},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142159}},ends={{npcID=142159}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54343] = {id=54343,name="Darkshore Donations: Potion of Replenishment",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54343},objectivesText="Progress: Years of study have allowed us to produce potions capable of enhancing one's magical regeneration. Have you seen such an item recently? I would die to get my hands on one.",rewardItems={152561},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142159}},ends={{npcID=142159}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54344] = {id=54344,name="Darkshore Donations: Crimson Ink",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54344},objectivesText="Progress: This particular ink has quite a powerful effect. Perhaps you're able to acquire such an item?",rewardItems={158188},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142981}},ends={{npcID=142981}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54345] = {id=54345,name="Darkshore Donations: Contract: The Honorbound",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54345},objectivesText="Progress: Have some contracts for me?",rewardItems={165017},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142981}},ends={{npcID=142981}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54346] = {id=54346,name="Darkshore Donations: Gold",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54346},description="Our friends here are accepting all kinds of donations on behalf of the war effort, but if ya ask me, no battle was ever won without proper funding. That's right, bub. I'm talking about money! And lots of it. If you got it, we need it!",objectivesText="Donate 1000000 Gold to Paymaster Grintooth in the Port of Zandalar. Progress: A <class> like you's surely gotta have a little extra cash in your stash. Waddaya say? Lemme help lighten your load a bit?",rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142157}},ends={{npcID=142157}},mapCandidates={npc={1165},zone={8670}},questGiverID=142157,questType="standard"},
[54347] = {id=54347,name="Darkshore Donations: Ultramarine Ink",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54347},objectivesText="Progress: Our scribes' ink supplies are in short supply. Would you be able to help with this problem?",rewardItems={158187},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142981}},ends={{npcID=142981}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54348] = {id=54348,name="Darkshore Donations: Deep Sea Satin",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54348},objectivesText="Progress: If we're going to keep our casters clothed, we'll need to make sure our stockpile is ready. If you find yourself swimming in an abundance of deep sea satin I'd be happy to send them along to our stores.",rewardItems={152577},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142975}},ends={{npcID=142975}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54349] = {id=54349,name="Darkshore Donations: Tidespray Linen Bandage",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54349},objectivesText="Progress: Bandages go a long way on the battlefield, especially when our healers are spread thin. Do you have any to spare?",rewardItems={158381},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142975}},ends={{npcID=142975}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54350] = {id=54350,name="Darkshore Donations: Tidespray Linen Net",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54350},objectivesText="Progress: If we're going to handle our enemies rushing our allies, we'll need something sturdy to slow them down. I've heard tailors can produce some fine netting. Would you happen to have any?",rewardItems={159791},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142975}},ends={{npcID=142975}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54351] = {id=54351,name="Darkshore Donations: Deep Sea Bandage",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54351},objectivesText="Progress: We've started a special stockpile of bandages for scenarios where we'll need a little something extra to keep our allies going. I've added one particular item to the list. If you have any to spare I'll make sure they're put to good use.",rewardItems={158382},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142975}},ends={{npcID=142975}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54352] = {id=54352,name="Darkshore Donations: Shimmerscale Diving Suit",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54352},objectivesText="Progress: Ya know what'll really surprise our enemies? The unexpected. And I know just the thing.",rewardItems={154168},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142970}},ends={{npcID=142970}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54353] = {id=54353,name="Darkshore Donations: Blood-Stained Bone",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54353},objectivesText="Gather 20 Enchant Weapon - Stalwart Navigation for Uma'wi in the Port of Zandalar. Progress: Bones are abundant these days, but only within our fallen allies and foes. We need stronger bones, from the beasts of these lands. Have you come across any in your travels?",rewardItems={154164},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142970}},ends={{npcID=142970}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54354] = {id=54354,name="Darkshore Donations: Shimmerscale Diving Helmet",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54354},objectivesText="Gather 5 Enchant Ring - Seal of Critical Strike for Uma'wi in the Port of Zandalar. Progress: I was just about done filling orders for the next shipment then realized I was out of diving helmets! Do you think you can help me fill the remaining orders?",rewardItems={154169},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142970}},ends={{npcID=142970}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54355] = {id=54355,name="Darkshore Donations: Mistscale",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54355},objectivesText="Gather 100 Enchant Ring - Seal of Versatility for Uma'wi in the Port of Zandalar. Progress: Our leatherworking supplies having been running low. If you're able to spare any, it would go a long way in preparing our allies for the battle to come.",rewardItems={153051},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142970}},ends={{npcID=142970}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54356] = {id=54356,name="Darkshore Donations: Quick Golden Beryl",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54356},objectivesText="Progress: Enhancement gems go a long way. If we're to endure the battle, we've got to be prepared.",rewardItems={153711},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142977}},ends={{npcID=142977}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54357] = {id=54357,name="Darkshore Donations: Masterful Kubiline",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54357},objectivesText="Progress: Have any cut kubiline you would like to donate?",rewardItems={153713},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142977}},ends={{npcID=142977}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54358] = {id=54358,name="Darkshore Donations: Scarlet Diamond",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54358},objectivesText="Progress: A few more gems and the next shipment will be ready. I'll be here if you find any in your travels.",rewardItems={154121},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142977}},ends={{npcID=142977}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54359] = {id=54359,name="Darkshore Donations: Sand Shifter",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54359},objectivesText="Progress: Our food supplies are running low. Would you have any on you to spare for the battle to come?",rewardItems={152543},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142973}},ends={{npcID=142973}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54360] = {id=54360,name="Darkshore Donations: Stringy Loins",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54360},objectivesText="Progress: If you can bring me some of those stringy loins , I can get back to business and prepare for the battle to come.",rewardItems={154897},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142973}},ends={{npcID=142973}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54361] = {id=54361,name="Darkshore Donations: Wild Berry Bread",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54361},objectivesText="Progress: A few of those new desserts would be a nice addition to our supply. Bring me a few and I'll be sure they get to where they need to be.",rewardItems={166343},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142973}},ends={{npcID=142973}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54362] = {id=54362,name="Darkshore Donations: Seasoned Steak and Potatoes",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54362},objectivesText="Progress: Some of the best meals give our allies a fighting chance. If you come across any, come and see me.",rewardItems={166344},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142973}},ends={{npcID=142973}},mapCandidates={npc={1165},zone={8670}},questType="standard"},
[54363] = {id=54363,name="Darkshore Donations: War Resources",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54363},objectivesText="Progress: We are part of a great effort. Let us stand together in the battle to come.",rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142700}},ends={{npcID=142700}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[54364] = {id=54364,name="Darkshore Donations: Star Moss",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54364},objectivesText="Gather 30 Tidespray Linen for Faella in Boralus Harbor. Progress: There is no such thing as too much star moss . It is better to maintain a strong supply than be left wanting.",rewardItems={152506},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142993}},ends={{npcID=142993}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[54365] = {id=54365,name="Darkshore Donations: Storm Silver Ore",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54365},objectivesText="Gather 30 Battle Flag: Spirit of Freedom for Faella in Boralus Harbor. Progress: Our miners work their hands down to the bone gathering materials fer us, but they can only find so much. Ye wouldn't happen ta have any spare storm silver, would ye?",rewardItems={152579},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142994}},ends={{npcID=142994}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[54366] = {id=54366,name="Darkshore Donations: Winter's Kiss",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54366},objectivesText="Gather 30 Battle Flag: Phalanx Defense for Faella in Boralus Harbor. Progress: Our winter's kiss supplies are running low. You wouldn't happen to be an herbalist? Or know an herbalist? Or have some winter's kiss with you?",rewardItems={152508},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142993}},ends={{npcID=142993}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[54367] = {id=54367,name="Darkshore Donations: Platinum Ore",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54367},objectivesText="Gather 10 Battle Flag: Phalanx Defense for Faella in Boralus Harbor. Progress: Ore isn't easy ta come by nowadays and platinum ore is even harder. But if ye have any ta spare, it would go a long way.",rewardItems={152513},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142994}},ends={{npcID=142994}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[54368] = {id=54368,name="Darkshore Donations: Unstable Temporal Time Shifter",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54368},description="It's time we snuff out the competition, don't you agree? With your help we can ensure our allies receive the necessary goods and armor to prepare for the battle to come. Let's make sure our allies are well prepared.",objectivesText="Donate 2 Coarse Leather to Charlane in Boralus Harbor. Progress: Our healers are spread thin and we need alternative methods to handle our fallen troops.",rewardItems={158379},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143008}},ends={{npcID=143008}},mapCandidates={npc={1161},zone={8568}},questGiverID=143008,questType="standard"},
[54369] = {id=54369,name="Darkshore Donations: Electroshock Mount Motivator",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54369},description="I'll keep it simple: we need more Shimmerscale! I apologize for being so forward with you, but there's little time to waste. If you happen upon this item throughout your travels I'd be more than happy to put it to good use. Outfitting our allies is of the utmost importance in the battle to come, don't you agree?",objectivesText="Donate 2 Shimmerscale to Charlane in Boralus Harbor. Progress: Outfitting our allies is of the utmost importance. This provides us the necessary materials to ensure no one is left lagging behind on the battlefield.",rewardItems={153573},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143008}},ends={{npcID=143008}},mapCandidates={npc={1161},zone={8568}},questGiverID=143008,questType="standard"},
[54370] = {id=54370,name="Darkshore Donations: XA-1000 Surface Skimmer",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54370},description="Ye look like the kind o' <lad/lass> that ought ta be carryin' loads o' ore around with ya! If my assumption is right about ye, we could use yer help to gather a bit more ore for the war effort. Have ye any ore ta spare?",objectivesText="Gather 2 Monelite Ore to Brandal Darkbeard in Boralus Harbor. Progress: The battle may take to the sea, and we need deployable means of dealing with our enemies.",rewardItems={153512},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143008}},ends={{npcID=143008}},mapCandidates={npc={1161},zone={8568}},questGiverID=143008,questType="standard"},
[54371] = {id=54371,name="Darkshore Donations: Thermo-Accelerated Plague Spreader",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54371},description="It's not just our allies we need to protect in the upcoming battle, but our equine friends as well! Can you lend a hand and ensure our allies receive the best possible armor for the battle ahead?",objectivesText="Gather 3 Coarse Leather Barding for Charlane in Boralus Harbor. Progress: Our allies are in need of offensive choices in the battle to come.",rewardItems={153494},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143008}},ends={{npcID=143008}},mapCandidates={npc={1161},zone={8568}},questGiverID=143008,questType="standard"},
[54372] = {id=54372,name="Darkshore Donations: Umbra Shard",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54372},objectivesText="Donate 3 Drums of the Maelstrom to Charlane in Boralus Harbor. Progress: Battles are won by those with power. Power comes from within oneself. But enchantments help too and our supplies are running low.",rewardItems={152876},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143007}},ends={{npcID=143007}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[54373] = {id=54373,name="Darkshore Donations: Enchant Ring - Seal of Haste",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54373},objectivesText="Gather 2 Straddling Viridium for Larold Kyne in Boralus Harbor. Progress: We need more enchantments for our troops!",rewardItems={153439},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143007}},ends={{npcID=143007}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[54374] = {id=54374,name="Darkshore Donations: Potion of Rising Death",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54374},objectivesText="Gather 2 Versatile Kyanite for Larold Kyne in Boralus Harbor. Progress: Our combat potions are running low. Any you can spare would be greatly appreciated.",rewardItems={152559},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142993}},ends={{npcID=142993}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[54375] = {id=54375,name="Darkshore Donations: Enchant Ring - Seal of Mastery",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54375},objectivesText="Gather 2 Deadly Solstone for Larold Kyne in Boralus Harbor. Progress: Have you seen any of these lately?",rewardItems={153440},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143007}},ends={{npcID=143007}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[54376] = {id=54376,name="Darkshore Donations: Potion of Replenishment",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54376},objectivesText="Gather 2 War-Scroll of Battle Shout for Liao in Boralus Harbor. Progress: With preparation comes success.",rewardItems={152561},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142993}},ends={{npcID=142993}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[54377] = {id=54377,name="Darkshore Donations: Crimson Ink",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54377},description="Enlightenment guides our path to victory. In battle, we fight as one. Share your knowledge and skills with me. Generosity is never forgotten.",objectivesText="Gather 20 War-Scroll of Intellect for Liao in Boralus Harbor. Progress: Enlightenment presents opportunity for victory.",rewardItems={158188},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143005}},ends={{npcID=143005}},mapCandidates={npc={1161},zone={8568}},questGiverID=143005,questType="standard"},
[54378] = {id=54378,name="Darkshore Donations: Potion of Bursting Blood",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54378},objectivesText="Gather 2 War-Scroll of Fortitude for Liao in Boralus Harbor. Progress: The opportunity for strength and fortitude present themselves when facing difficult situations.",rewardItems={152560},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142993}},ends={{npcID=142993}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[54379] = {id=54379,name="Darkshore Donations: Contract: 7th Legion",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54379},description="Greetings! With the war effort in full swing I'll be your point of contact for herbalism and alchemical donations! It's a pleasure to meet you! Now, let's see here... Ah, yes. Siren's Pollen. It appears our stockpiles reported a shortage as of late last night. It would be a great help to us all if you were able to donate to our efforts.",objectivesText="Gather 3 Siren's Pollen for Chelsea Strand in Boralus Harbor. Progress: Have some contracts for me?",rewardItems={165016},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143005}},ends={{npcID=143005}},mapCandidates={npc={1161},zone={8568}},questGiverID=143005,questType="standard"},
[54380] = {id=54380,name="Darkshore Donations: Gold",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54380},description="We've spent a great deal of time and resources preparing for the battle to come. As we begin final preparations, we'll be setting aside additional funding to ensure further training and supplies are available at a moment's notice. Would you like to make a donation?",objectivesText="Donate 1000000 Gold to Paymaster Vauldren in Boralus Harbor. Progress: As we begin final preparations, we'll be setting aside additional funding to ensure further training and supplies are available at a moment's notice. Would you like to make a donation?",rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142685}},ends={{npcID=142685}},mapCandidates={npc={1161},zone={8568}},questGiverID=142685,questType="standard"},
[54381] = {id=54381,name="Darkshore Donations: Ultramarine Ink",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54381},description="Greetings, traveler. I was asked to ensure our food supplies are never left wanting and our fish supplies have been running low lately. Have anything you would care to donate?",objectivesText="Gather 60 Grilled Catfish for Senedras in Boralus Harbor. Progress: I was asked to ensure our inscription supplies are never left wanting, though lately they have been running low. Have any ink you would care to donate?",rewardItems={158187},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143005}},ends={{npcID=143005}},mapCandidates={npc={1161},zone={8568}},questGiverID=143005,questType="standard"},
[54382] = {id=54382,name="Darkshore Donations: Deep Sea Satin",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54382},description="Fish--it's what's for dinner! Or so say our supply officers. And this weeks meals are based around one delicious ingredient--catfish. If we're going to keep our allies well fed and full of fish we'll need to gather more stock and begin meal preparations soon. If you find yourself swimming in an abundance of catfish I'd be happy to send them along to our stores.",objectivesText="Gather 30 Great Sea Catfish for Senedras in Boralus Harbor. Progress: If we're going to keep our casters clothed, we'll need to make sure our stockpile is ready. If you find yourself swimming in an abundance of deep sea satin I'd be happy to send them along to our stores.",rewardItems={152577},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142998}},ends={{npcID=142998}},mapCandidates={npc={1161},zone={8568}},questGiverID=142998,questType="standard"},
[54383] = {id=54383,name="Darkshore Donations: Shimmerscale Diving Suit",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54383},description="Hey there! Transmission's come down from up top--we need more ammunition! Something with a bit more kick. Something really unexpected! From what I've heard there's a special frost-based ammunition crafted only by the most experienced engineers. If you were to bring me a few I'm sure our munitions officers would be ecstatic! Maybe they'd even let me keep one to examine!",objectivesText="Gather 3 Frost-Laced Ammunition for Norber Togglesprocket in Boralus Harbor. Progress: I've heard there's a special underwater suit that's crafted by the most experienced of leatherworkers. If you were to bring me a few of these I'm sure our aquatic forces would be ecstatic!",rewardItems={154168},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142995}},ends={{npcID=142995}},mapCandidates={npc={1161},zone={8568}},questGiverID=142995,questType="standard"},
[54384] = {id=54384,name="Darkshore Donations: Tidespray Linen Net",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54384},description="Though our ammunition stockpiles are faring well, it's my duty to find additional resources, especially those that are harder to come by. Today I'm looking for a specific type of ammunition, one with incendiary properties. I could really use your help tracking a few of these down.",objectivesText="Gather 5 Incendiary Ammunition for Norber Togglesprocket in Boralus Harbor. Progress: If we're going to handle our enemies rushing our allies, we'll need something sturdy to slow them down. I've heard tailors can produce some fine netting. Would you happen to have any?",rewardItems={159791},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142998}},ends={{npcID=142998}},mapCandidates={npc={1161},zone={8568}},questGiverID=142998,questType="standard"},
[54385] = {id=54385,name="Darkshore Donations: Tidespray Linen Bandage",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54385},objectivesText="Progress: Bandages go a long way on the battlefield, especially when our healers are spread thin. Do you have any to spare?",rewardItems={158381},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142998}},ends={{npcID=142998}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[54386] = {id=54386,name="Darkshore Donations: Deep Sea Bandage",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54386},description="You never know when you'll need to deliver a big bang on the battlefield, if you know what I mean. Luckily we can plan for the unexpected! We've begun to store a special stockpile of explosives for scenarios where we'll need a little something extra to get our point across. I've added one particular item to the list. If you have any to spare I'll make sure they're put to good use.",objectivesText="Gather 10 F.R.I.E.D. for Norber Togglesprocket in Boralus Harbor. Progress: We've started a special stockpile of bandages for scenarios where we'll need a little something extra to keep our allies going. I've added one particular item to the list. If you have any to spare I'll make sure they're put to good use.",rewardItems={158382},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142998}},ends={{npcID=142998}},mapCandidates={npc={1161},zone={8568}},questGiverID=142998,questType="standard"},
[54387] = {id=54387,name="Darkshore Donations: Blood-Stained Bone",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54387},objectivesText="Gather 20 Enchant Ring - Seal of Versatility for Mae Wagglewand in Boralus Harbor. Progress: I know it's short notice, but I'm trying to find a few more bones to add to our next shipment.",rewardItems={154164},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142995}},ends={{npcID=142995}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[54388] = {id=54388,name="Darkshore Donations: Shimmerscale Diving Helmet",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54388},objectivesText="Gather 5 Enchant Ring - Seal of Critical Strike for Mae Wagglewand in Boralus Harbor. Progress: I was just about done filling orders for the next shipment then realized I was out of diving helmets! Do you think you can help me fill the remaining orders?",rewardItems={154169},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142995}},ends={{npcID=142995}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[54389] = {id=54389,name="Darkshore Donations: Mistscale",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54389},objectivesText="Gather 100 Enchant Weapon - Stalwart Navigation for Mae Wagglewand in Boralus Harbor. Progress: I've been able to keep pace with our orders until recently. Now I'm afraid I won't be able to keep up without help. Would you be willing to donate a few supplies?",rewardItems={153051},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142995}},ends={{npcID=142995}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[54390] = {id=54390,name="Darkshore Donations: Masterful Kubiline",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54390},description="A nice, hearty meat provides the nourishment our allies deserve before shipping off to battle, not to mention it also makes quite a stew, something our troops seem to rather enjoy when the winds are at their best and the chill of night lingers in the air. If you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.",objectivesText="Gather 20 Seasoned Loins for Senedras in Boralus Harbor. Progress: Our jewelcrafters work night and day preparing gems for the battle to come. If you have any spare cut gems, it would help alleviate their burden.",rewardItems={153713},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143004}},ends={{npcID=143004}},mapCandidates={npc={1161},zone={8568}},questGiverID=143004,questType="standard"},
[54391] = {id=54391,name="Darkshore Donations: Quick Golden Beryl",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54391},description="A nice, hearty meat provides the nourishment our allies deserve before shipping off to battle, not to mention it also makes quite a stew, something our troops seem to rather enjoy when the winds are at their best and the chill of night lingers in the air. If you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.",objectivesText="Gather 20 Seasoned Loins for Senedras in Boralus Harbor. Progress: Enhancement gems go a long way. If we're to endure the battle, we've got to be prepared.",rewardItems={153711},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143004}},ends={{npcID=143004}},mapCandidates={npc={1161},zone={8568}},questGiverID=143004,questType="standard"},
[54392] = {id=54392,name="Darkshore Donations: Sand Shifter",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54392},description="In times like this it's important ta be ready fer battle at a moments notice. Outfittin' our beasts with proper stirrups is a step in the right direction. If yer able ta bring me a few I'll be sure they're put ta good use.",objectivesText="Gather 30 Monel-Hardened Stirrups for Brandal Darkbeard in Boralus Harbor. Progress: Our food supplies are running low. Specifically our supply of fish. Would you happen to be a master angler?",rewardItems={152543},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142997}},ends={{npcID=142997}},mapCandidates={npc={1161},zone={8568}},questGiverID=142997,questType="standard"},
[54393] = {id=54393,name="Darkshore Donations: Scarlet Diamond",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54393},description="Battles aren't decided by which side has the best armor, or the sharpest blades, but it sure does help! Matter o' fact is it's not just ye allies needin' help, but our beasts of battle as well. If ye can provide any additional hoofplates fer our brave beasts I'll be sure ta have our farriers take good care of 'em.",objectivesText="Gather 20 Monel-Hardened Hoofplates for Brandal Darkbeard in Boralus Harbor. Progress: We have our own jewelcrafters hard at work, adoring armor with their special cuts. However, our supply of raw gems is rather low. Have you any to spare?",rewardItems={154121},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=143004}},ends={{npcID=143004}},mapCandidates={npc={1161},zone={8568}},questGiverID=143004,questType="standard"},
[54394] = {id=54394,name="Darkshore Donations: Stringy Loins",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54394},description="One of our latest shipments of alchemical supplies was raided en route to storage. We're scrambling to get our stock back on track, but I'm worried we won't make our quota. You wouldn't happen to know where one can acquire additional mana potions, would you?",objectivesText="Bring 30 Coastal Mana Potions to Chelsea Strand in Boralus Harbor. Progress: Our food stock has been running low trying to keep everyone fed. Do you have any supplies you can spare?",rewardItems={154897},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142997}},ends={{npcID=142997}},mapCandidates={npc={1161},zone={8568}},questGiverID=142997,questType="standard"},
[54395] = {id=54395,name="Darkshore Donations: Seasoned Steak and Potatoes",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54395},description="I've received word our allies are looking to stash away a few supplementary items for the battle to come. If you happen to stumble across a few Coastal Healing Potions I'd be more than happy to add them to our stores.",objectivesText="Gather 40 Coastal Healing Potions for Chelsea Strand in Boralus Harbor. Progress: A hearty meal provides the nourishment our allies deserve. If you bring me some freshly seasoned steak and potatoes I would be more than happy to deliver it to our supply officers.",rewardItems={166344},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142997}},ends={{npcID=142997}},mapCandidates={npc={1161},zone={8568}},questGiverID=142997,questType="standard"},
[54396] = {id=54396,name="Darkshore Donations: Wild Berry Bread",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54396},objectivesText="Gather 40 Steelskin Potions for Chelsea Strand in Boralus Harbor. Progress: Have you heard of this new dessert the chefs are making? I think it's called Wild Berry Bread . You wouldn't happen to have any, would you?",rewardItems={166343},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=142997}},ends={{npcID=142997}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[54402] = {id=54402,name="Shifting Gears",level=50,requiredLevel=50,faction="alliance",requiredRaces={7},categories={"campaign"},flags={"important"},sharable=true,expansion=7,zoneID=1519,mapID=84,storyline={54402,54576,54577,54580,54581,54582,54639,54640,54641,54642,54850},description="<name>! The Alliance has made a new request for Gnomeregan's might. Captain Sparknozzle wishes for your expert assistance in the matter. He'll be waiting for you in New Tinkertown, outside of Gnomeregan.",objectivesText="Meet Captain Tread Sparknozzle in New Tinkertown.",rewardGold=154900,rewardXP=3410,rewardItems={168862,170063,174077,203176,208476,210054,218105,218118,218119,242520},starts={{npcID=147939}},ends={{npcID=147943}},mapCandidates={npc={84,469},zone={1519}},questType="standard",questLines={{id=858,name="Gnome Heritage Armor",orderIndex=0,flags=0}},db2PoiUiMapID=469},
[54403] = {id=54403,name="Tidesage Clarissa",level=10,requiredLevel=10,faction="horde",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={54403},rewardXP=2125,starts={{npcID=147941,mapID=942,x=0.4146,y=0.5205}},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=147941},{orderIndex=1,type=0,amount=1,objectID=147951}},worldTaskTitle="Tidesage Clarissa",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3434,db2VignetteName="Tidesage Clarissa"},
[54404] = {id=54404,name="Dark Iron Machinations",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={54302,54303,54310,54312,54404,54407,54412,54417,54418,54421,54441,54459},description="We have some additional support for our plan to deceive the Horde and assault the Blood Gates, but we need your help. The Dark Iron dwarves have several mole machines waiting to erupt and supply fresh troops. I've determined several spots within Zalamar that would be perfect for them to use. Take this device and plant it in the following areas. It will send a message to the Dark Iron dwarves to erupt from there. They will stay safely in their machines until our army arrives.",objectivesText="Mark 3 areas within Zalamar for mole machines to appear.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1553,amount=250}},starts={{npcID=147843}},ends={{npcID=147844}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={54303},questLines={{id=845,name="Fog of War",orderIndex=3,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=845,questLineOrder=17,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=845,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[54407] = {id=54407,name="Lurking in the Swamp",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={54302,54303,54310,54312,54404,54407,54412,54417,54418,54421,54441,54459},description="We have Zalamar, and we've got our fog. Now, we have to take the attack to the Horde. Our goal is to take as much land in Nazmir as possible to make the Horde think our main fleet is here. The first target is Zul'jan ruins, one of the Horde's main bases in Nazmir. We'll have to make our way through the swamps to our attack position. Meet us there.",objectivesText="Meet with Jaina Proudmoore outside of Zul'jan ruins.",rewardGold=23400,rewardXP=850,starts={{npcID=147842}},ends={{npcID=147842}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={54312},questLines={{id=845,name="Fog of War",orderIndex=5,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=845,questLineOrder=17,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=845,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[54412] = {id=54412,name="Zul'jan Deluge",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={54302,54303,54310,54312,54404,54407,54412,54417,54418,54421,54441,54459},description="Through the mists is Zul'jan ruins, a major Horde outpost in Nazmir. We need to take it over to help our forces push forward. The Horde needs to believe a large Alliance army is here, so we're going to throw everything we've got at taking the ruins. Our army will charge forward to attack, while you join them using my water elemental . Meet me outside of the ruins when you're done, we'll need to keep pushing forward.",objectivesText="Use Jaina's Water Elemental to clear out Zul'jan Ruins.",rewardGold=468000,rewardXP=8520,rewardCurrencies={{id=1553,amount=250}},starts={{npcID=147842}},ends={{npcID=147842}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={54407},questLines={{id=845,name="Fog of War",orderIndex=6,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=845,questLineOrder=17,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=845,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[54414] = {id=54414,name="Gale's Unrest",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={54414},objectivesText="Alliance Invocation interrupted",rewardXP=2125,mapCandidates={npc={},zone={8721}},questType="standard",db2Objectives={{text="Alliance Invocation interrupted",amount=1,type=0,objectID=148022,orderIndex=0}},worldTaskTitle="Gale's Unrest",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[54415] = {id=54415,name="Vulpera for a Day",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={54415},objectivesText="Talk to Nisha Voldunai protected Pick Up Banner Use Banner Inspire Voldunai Extinguish Fires Free Prisoners Kill Alliance Small Kill Medium Alliance Kill Large Alliance",rewardXP=2125,mapCandidates={npc={},zone={8501}},questType="standard",db2Objectives={{text="Talk to Nisha",amount=1,type=0,objectID=148458,orderIndex=0},{text="Voldunai protected",amount=1,type=15,objectID=0,orderIndex=1},{text="Pick Up Banner",amount=20,type=0,objectID=148447,orderIndex=2},{text="Use Banner",amount=50,type=0,objectID=148448,orderIndex=3},{text="Inspire Voldunai",amount=100,type=0,objectID=148449,orderIndex=4},{text="Extinguish Fires",amount=13,type=0,objectID=148503,orderIndex=5},{text="Free Prisoners",amount=20,type=0,objectID=148461,orderIndex=6},{text="Kill Alliance Small",amount=34,type=0,objectID=148462,orderIndex=7},{text="Kill Medium Alliance",amount=20,type=0,objectID=148463,orderIndex=8},{text="Kill Large Alliance",amount=13,type=0,objectID=148464,orderIndex=9}},worldTaskTitle="Vulpera for a Day",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[54416] = {id=54416,name="Warfront Preparations",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10226,mapID=1165,storyline={53955,54042,54043,54044,54045,54046,54047,54049,54050,54059,54416},description="We must make our preparations. Return to Zandalar immediately and rally our forces. Any contributions to our cause must be made. Go. We will hold for now.",objectivesText="Take the portal back to the Port of Zandalar to prepare for the Battle for Darkshore .",rewardGold=23400,starts={{npcID=146323}},ends={{npcID=138949}},mapCandidates={npc={1165},zone={10226}},questGiverID=146323,questType="standard",sourceQuests={54050},questLines={{id=856,name="In Darkest Night",orderIndex=9,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[54417] = {id=54417,name="Showing Our Might",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={54302,54303,54310,54312,54404,54407,54412,54417,54418,54421,54441,54459},description="We are within reach of the Blood Gate in Zandalar. Once we take that, the Horde and Zandalari will believe our full invasion has begun. Our forces have already engaged the Zandalari within the Fallen Outpost. We'll need your help to push them back. I'll be focusing on finishing off what remains of the Horde and Zandalari back in Zul'jan ruins.",objectivesText="Defeat 12 Zandalari forces within the Fallen Outpost.",rewardGold=234000,rewardXP=6815,starts={{npcID=147842}},ends={{npcID=147842}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={54412},questLines={{id=845,name="Fog of War",orderIndex=7,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=845,questLineOrder=17,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=845,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[54418] = {id=54418,name="The Mech of Death",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={54302,54303,54310,54312,54404,54407,54412,54417,54418,54421,54441,54459},description="We have reports of a goblin machine causing havoc among our troops up ahead. They call it the A.M.O.D. It is a crude machine compared to what the Lightforged have aboard the Vindicaar. Together, you and I will bring down this machine. Go, I will await for you near the machine and engage it when you are ready.",objectivesText="Defeat the A.M.O.D.",rewardGold=468000,rewardXP=8520,starts={{npcID=147844}},ends={{npcID=147844}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={54412},questLines={{id=845,name="Fog of War",orderIndex=8,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=845,questLineOrder=17,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=845,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[54419] = {id=54419,name="Quelling the Masses",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53719,53823,53824,53825,53826,53827,53828,53830,53831,54031,54032,54033,54034,54300,54301,54419,54925},description="One of my own in de Rastari has seen fit to rile de drudges and guards in de Zocalo. They threaten de stability of our empire with this foolishness. If they are angry, we can address it. But this wanton destruction will not stand. Go down into de market of de Zocalo and bring about calm however you can. Choose de method that works for you. I care only for de result: Peace, so Talanji can finally be crowned.",objectivesText="Subdue 12 rioters in the Zocalo.",rewardGold=341600,rewardXP=5465,starts={{npcID=145360}},ends={{npcID=145359}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={53824},questLines={{id=919,name="Allies of the Horde: Zandalari",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[54421] = {id=54421,name="Taming their Beasts",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={54302,54303,54310,54312,54404,54407,54412,54417,54418,54421,54441,54459},description="Our goal is to assault the Blood Gate, but to be blunt, we don't have the force necessary for this. That's why we have gnomish technology. The Zandalari have battle beasts, direhorns mounted with powerful weapons. Several of these beasts are resting within the Fallen Outpost. This device, the Re-Discombobulator , will give us control over these animals. Take this device and use it on these battle beasts. We'll assault the Blood Gates once we have them under our control.",objectivesText="Use the Re-Discombobulator to control 3 battle beasts.",rewardGold=23400,rewardXP=850,rewardItems={166230},rewardCurrencies={{id=1553,amount=250}},starts={{npcID=147843}},ends={{npcID=147843}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={54412},questLines={{id=845,name="Fog of War",orderIndex=9,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=845,questLineOrder=17,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=845,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[54424] = {id=54424,name="A Shady Character",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8717,mapID=1161,storyline={54424},description="Your followers tell of a smuggler of wit and guile, who was able to charm them with stories of lands far and wide. Though it cost a fair sum to retrieve, they managed to obtain a token which when displayed to the smuggler, will allow the bearer to purchase his wares.",objectivesText="Deliver the token to the shady character under the bridge. Progress: Do you really think you should be talking to me?",rewardGold=23400,rewardXP=850,rewardItems={165946},ends={{npcID=148024}},coords={mapID=1161,source="quest_giver",x=0.695333,y=0.184},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[54433] = {id=54433,name="Orders from Azshara",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={53760,53761,53762,53763,53766,54058,54117,54118,54172,54174,54433,54439,54683},series={53760,53761,53762,54058,54113,54114,54117,54118,54144,54174,54265},description="This medallion is inscribed with orders commanding the naga to invade our shores and seize artifacts of power. <Kojo studies you thoughtfully.> I've heard tales of a priest who used a horrifying dagger to fight the Burning Legion. It is said this blade... Xal'atath ... whispers secrets of the deep. It might be our best chance of uncovering what the naga seek. I recently came upon a makeshift naga altar in Atal'Gral. If you take Xal'atath there, the dagger may reveal crucial information.",objectivesText="Retrieve Xal'atath and find the Makeshift Altar.",rewardGold=23400,rewardXP=850,rewardItems={164761,165605,168123},starts={{npcID=134345}},ends={{npcID=134345}},mapCandidates={npc={862},zone={8499}},questTurnInID=134345,questType="standard",sourceQuests={54172},questLines={{id=851,name="Crucible of Storms",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[54434] = {id=54434,name="Voidmaster Evenshade",level=10,requiredLevel=10,faction="horde",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={54434},rewardXP=2125,starts={{npcID=147998,mapID=942,x=0.4135,y=0.5397}},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=147998}},worldTaskTitle="Voidmaster Evenshade",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3433,db2VignetteName="Voidmaster Evenshade"},
[54436] = {id=54436,name="Wisp'd Into Shape",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10058,storyline={54436},description="We're off to a good start, but we're going to need more wood if we want to win this battle! The Horde has set up a lumber mill to the north of Bashal'Aran, past Forlorn Crossing. If we take it, we can stop them from destroying the forest while also getting the wisps to help us out. It's a two-for-one!",objectivesText="Capture Cinderfall Grove and inspire the wisps to help you. Progress: We need that additional wood from Cinderfall!",rewardXP=3410,rewardCurrencies={{id=1540,amount=10}},starts={{npcID=145770}},ends={{npcID=145770}},mapCandidates={npc={},zone={10058}},questGiverID=145770,questTurnInID=145770,questType="standard",sourceQuests={53977}},
[54437] = {id=54437,name="Owynn Graddock",level=10,requiredLevel=10,faction="horde",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={54437},rewardGold=309800,rewardXP=2125,starts={{npcID=148044,mapID=942,x=0.5089,y=0.5228}},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=148044}},worldTaskTitle="Owynn Graddock",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3436,db2VignetteName="Owynn Graddock"},
[54438] = {id=54438,name="Crucible of Storms: Relics of Shadow",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53760,53761,53762,53765,54058,54113,54114,54126,54141,54144,54265,54438,54682},description="Your intention to stop the naga attacks was noble, <name>. But that shadowy dagger tricked you into delivering powerful relics into the hands of a great enemy. No doubt those artifacts will be well defended. Gather your allies, <class>, and return to the Crucible of Storms. Defeat any opponents that stand in your way. Ensure the relics cannot be used against the Alliance. The naga cannot be allowed to summon their storm... or to call forth something even worse.",objectivesText="Stop Uu'nat within the Crucible of Storms.",rewardGold=936000,rewardXP=13630,rewardItems={164761,165605,168123},rewardCurrencies={{id=1553,amount=1500}},starts={{npcID=146902}},ends={{npcID=146902}},mapCandidates={npc={1161},zone={8568}},questType="raid",sourceQuests={54126},questLines={{id=851,name="Crucible of Storms",orderIndex=18,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[54439] = {id=54439,name="Crucible of Storms: Relics of Shadow",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53760,53761,53762,53763,53766,54058,54117,54118,54172,54174,54433,54439,54683},description="Your intention to stop de naga attacks was noble, <name>. But de talking dagger tricked you into delivering powerful relics into de hands of our enemies. No doubt dese artifacts will be well defended. Gather your allies, <class>, and return to de Crucible of Storms. Defeat any opponents dat stand in your way. Ensure dese relics cannot be used against de Horde. And if any shadowy weapons ask you to do favors for dem in de future... I suggest you decline.",objectivesText="Stop Uu'nat within the Crucible of Storms.",rewardGold=936000,rewardXP=13630,rewardItems={164761,165605,168123},rewardCurrencies={{id=1553,amount=1500}},starts={{npcID=146335}},ends={{npcID=146335}},mapCandidates={npc={1165},zone={8670}},questType="raid",sourceQuests={53763},questLines={{id=851,name="Crucible of Storms",orderIndex=19,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[54441] = {id=54441,name="Taking the Blood Gate",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8500,mapID=863,storyline={54302,54303,54310,54312,54404,54407,54412,54417,54418,54421,54441,54459},description="We have our forces spread out throughout Nazmir, but we need to do something that will force Rastakhan into action. We must personally march into Zuldazar and take the Blood Gate. This will cause them to throw their full army at us. As you can see, we're the only ones left that can assault the Blood Gate. Shaw and Telaamon will stay behind to help the rest of the army move up. You and I will ride the battle beast into the Blood Gate and take it by force.",objectivesText="Ride the battlebeast and defeat the Zandalari army at the Blood Gates.",rewardGold=23400,rewardXP=850,rewardItems={166230},rewardCurrencies={{id=1553,amount=400}},starts={{npcID=147842}},ends={{npcID=147843}},mapCandidates={npc={863},zone={8500}},questType="standard",sourceQuests={54417,54418,54421},questLines={{id=845,name="Fog of War",orderIndex=10,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=845,questLineOrder=17,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=845,questLineOrder=10}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=863},
[54442] = {id=54442,name="Beast Tamer Watkins",level=10,requiredLevel=10,faction="horde",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={54442},rewardXP=2125,starts={{npcID=148075,mapID=942,x=0.3499,y=0.603}},mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=148075}},worldTaskTitle="Beast Tamer Watkins",db2PoiMapID=1643,db2PoiUiMapID=942,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3439,db2VignetteName="Beast Tamer Watkins"},
