[54510] = {id=54510,name="Mischief Managed",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={54169,54171,54510},description="Thank you for returning this artifact to us, <name>. Now that we have the Abyssal Scepter, the fleet can advance without fear of the seas being turned against us. Please report our success to High Commander Wyrmbane.",objectivesText="Report to High Commander Wyrmbane in Boralus.",rewardGold=23400,rewardXP=1705,rewardItems={163248,163251,163337,163339,163377,163380,163389,163394,163398,163405,163410,163418},rewardChoices={163248,163251,163337,163339,163377,163380,163389,163394,163398,163405,163410,163418},starts={{npcID=146982}},ends={{npcID=135612}},mapCandidates={npc={862,1161},zone={8499}},questType="standard",sourceQuests={54169},questLines={{id=849,name="The Treasury Heist",orderIndex=2,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=849,questLineOrder=16,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=849,questLineOrder=9}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=1161},
