[54518] = {id=54518,name="Zero Zeppelins",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53887,53888,53896,53909,53910,53916,53919,53936,53978,53986,54518,54519,54559,54703,54787},description="The Horde zeppelins proved to be problematic for our forces here. I tried to construct something quickly, but while the weapon had power, it didn't have the range necessary to take them out. The Lord Admiral has provided us with an expedient solution to the problem! Use this jury-rigged hand cannon on the zeppelins. A quick application of high energy and heat will cause thermal shock and critical failure! To simplify, blow them up while they're grounded!",objectivesText="Destroy Horde Zeppelins in Anglepoint Wharf. Progress: If you could take out those Zeppelins before they can thaw and fly out of range, we'd be assured of victory!",rewardGold=234000,rewardXP=6815,rewardItems={164921,164968,166280,166682},starts={{npcID=145632}},ends={{npcID=145632}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={54519},questLines={{id=843,name="Beware the Daughter of the Sea",orderIndex=5,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=843,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=843,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[54519] = {id=54519,name="Squad Goals",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53887,53888,53896,53909,53910,53916,53919,53936,53978,53986,54518,54519,54559,54703,54787},description="My patrol squad fought off the Horde so Galeheart and I could fly free. I have to stay with the Lord Admiral, so I can't look for them on my own. With any luck, they're out there fighting and waiting for reinforcements. Well, we're here to help save them. Would you find the rest of my patrol squad for me?",objectivesText="Find the members of Taelia's patrol squad.",rewardGold=234000,rewardXP=6815,rewardItems={164921,164968,166280,166682},rewardCurrencies={{id=1553,amount=500}},starts={{npcID=148015}},ends={{npcID=145593}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={53896},questLines={{id=843,name="Beware the Daughter of the Sea",orderIndex=6,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=843,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=843,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
