[54559] = {id=54559,name="Free Plumeria!",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53887,53888,53896,53909,53910,53916,53919,53936,53978,53986,54518,54519,54559,54703,54787},description="My poor Plumeria has been captured by an exceptionally brutal villain. He has been overseeing the spread of pestilence along the wharf. Rosaline needs my mechanical expertise in fixing our weapons. Would you free my poor Plumeria and slay the vile knight tormenting her?",objectivesText="Defeat Maurizio Deaththrill and free Plumeria .",rewardGold=468000,rewardXP=8520,rewardItems={164921,164968,166280,166682},starts={{npcID=145632}},ends={{npcID=145632}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={53909,53916,54518,54519},questLines={{id=843,name="Beware the Daughter of the Sea",orderIndex=9,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=843,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=843,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
