[54614] = {id=54614,name="Executing Exorcisms",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=45,mapID=14,storyline={54614},description="Even in death, the Alliance foolishly clings to Horde territory. Drive their vengeful ghosts from the ruins of Stromgarde before their foulness spreads.",objectivesText="Kill 12 Vengeful Ghosts in Stromgarde.",rewardXP=850,rewardCurrencies={{id=1716,amount=1}},mapCandidates={npc={},zone={45}},questType="world",db2Objectives={{text="Vengeful Ghosts slain",amount=12,type=0,objectID=142723,orderIndex=0}},worldTaskTitle="Executing Exorcisms",db2PoiUiMapID=14,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
