[54619] = {id=54619,name="Wiping Out the Witherbark",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=45,mapID=14,storyline={54619},description="The bloodthirsty Witherbark tribe has always refused to join the Horde... and now that the Horde holds Arathi, we will succeed where the Alliance has failed. Drive the forest trolls from the Highlands.",objectivesText="Kill 12 Witherbark tribe trolls in Arathi Highlands .",rewardXP=850,rewardCurrencies={{id=1716,amount=1}},mapCandidates={npc={},zone={45}},questType="world",db2Objectives={{text="Witherbark tribe trolls slain",amount=12,type=0,objectID=143237,orderIndex=0}},worldTaskTitle="Wiping Out the Witherbark",db2PoiUiMapID=14,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
