[54635] = {id=54635,name="Mekkatorque's Battle Plans",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53941,53942,54004,54007,54008,54009,54022,54028,54094,54123,54124,54128,54635},description="So we almost got everythin' we need, except for where that airship went! My insurance pals found out where they're hidin' that primo-info. Go and get me Mekkatorque's battle plans , then we can begin the REALLY fun part!",objectivesText="Recover Mekkatorque's Battle Plans Progress: You get me that thing yet?",rewardGold=303800,rewardXP=6815,rewardItems={164987,164989},starts={{npcID=146073}},ends={{npcID=146073}},mapCandidates={npc={895},zone={8567}},questType="standard",questLines={{id=839,name="Adventures of Gallywix and the G.M.O.D.",orderIndex=12,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=839,questLineOrder=16,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=839,questLineOrder=8}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
