[54638] = {id=54638,name="Beat Up the Drums",level=10,requiredLevel=10,faction="alliance",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={54638},rewardGold=34350,rewardXP=2125,starts={{npcID=148510,mapID=864,x=0.368,y=0.638}},mapCandidates={npc={},zone={8501}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=148510}},worldTaskTitle="Beat Up the Drums",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3479,db2VignetteName="Drox'ar Morgar"},
[54639] = {id=54639,name="A Signal in Storm Peaks",level=50,requiredLevel=50,faction="alliance",requiredRaces={7},categories={},flags={},sharable=true,expansion=7,zoneID=3537,mapID=114,storyline={54402,54576,54577,54580,54581,54582,54639,54640,54641,54642,54850},description="It looks like the signal is being transmitted from Storm Peaks. Time to put these flying machines to work! I'll keep tracking the signal en route in order to get a cleaner read.",objectivesText="Fly with your squadron to Storm Peaks. Progress: Need something, Commander?",rewardGold=170800,rewardXP=3410,starts={{npcID=147952}},ends={{npcID=147950}},mapCandidates={npc={114},zone={3537}},questType="standard",sourceQuests={54579},questLines={{id=858,name="Gnome Heritage Armor",orderIndex=6,flags=0}},db2PoiMapID=571,db2PoiUiMapID=120},
[54640] = {id=54640,name="Gnomercy!",level=50,requiredLevel=50,faction="alliance",requiredRaces={7},categories={},flags={},sharable=true,expansion=7,zoneID=67,mapID=114,storyline={54402,54576,54577,54580,54581,54582,54639,54640,54641,54642,54850},description="We need to give Tinkerbow some cover while she figures out our new trajectory. <The Cog Captain hands you a miniature spider tank.> It may not look like much, but this is a fully functional spider tank. You'll just need to de-shrinkify it. Use it to distract the troggs down below by thinning their numbers.",objectivesText="De-shrinkify the Assault Tank and use it to slay troggs. Progress: Give those troggs something to worry about, Captain!",rewardGold=283700,rewardXP=6815,rewardItems={24430,24431,24432,24433,24434},starts={{npcID=147950}},ends={{npcID=147950}},mapCandidates={npc={114},zone={67}},questType="standard",sourceQuests={54639},questLines={{id=858,name="Gnome Heritage Armor",orderIndex=7,flags=0}},db2PoiMapID=571,db2PoiUiMapID=120},
[54641] = {id=54641,name="For Gnomeregan!",level=50,requiredLevel=50,faction="alliance",requiredRaces={7},categories={},flags={},sharable=false,expansion=7,zoneID=67,mapID=114,storyline={54402,54576,54577,54580,54581,54582,54639,54640,54641,54642,54850},description="It's time to bring down Sparkspanner, Commander. Just give me the word, and I'll turn this machine straight towards the Halls of Stone!",objectivesText="Enter the Halls of Stone and defeat Telzo Sparkspanner. Progress: Sparkspanner needs to be defeated, for the sake of all Gnomanity.",rewardGold=567400,rewardXP=8520,rewardItems={59039,59040,59041,59042,59043,122457,134123,165835},starts={{npcID=147950},{npcID=149503}},ends={{npcID=149503}},mapCandidates={npc={114,120},zone={67}},questType="standard",sourceQuests={54850},questLines={{id=858,name="Gnome Heritage Armor",orderIndex=9,flags=0}},db2PoiMapID=571,db2PoiUiMapID=120},
[54642] = {id=54642,name="G.E.A.R. Up",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=6457,mapID=27,description="That was a close one, but we managed to defeat Sparkspanner! Gnomanity and Azeroth are saved from a threat they didn't even know about. Hopefully, that's the last time we'll hear from any of Thermaplugg's old goons. We should return to Captain Sparknozzle. He will want a full report.",rewardGold=117000,rewardXP=3410,rewardItems={168862},starts={{npcID=149503}},ends={{npcID=147943}},mapCandidates={npc={27,120},zone={6457}},questType="standard",sourceQuests={54641},questLines={{id=858,name="Gnome Heritage Armor",orderIndex=10,flags=0}}},
