[54682] = {id=54682,name="The Missing Blade",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10057,mapID=84,storyline={53760,53761,53762,53765,54058,54113,54114,54126,54141,54144,54265,54438,54682},description="<The echo of the blade Xal'atath lingers before you. Though the consciousness that resided within the dagger is gone, the place it once occupied still resonates with power. You sense the weapon now speaks another voice. Another purpose.... You feel compelled to warn the king that the blade may now reside in the hands of the enemy.>",objectivesText="Inform King Anduin about the absence of Xal'atath.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1553,amount=500}},ends={{npcID=107574}},startObjects={{objectID=316443,mapID=1346,x=0.27,y=0.54}},coords={mapID=84,source="quest_giver",x=0.856,y=0.316667},mapCandidates={npc={84},zone={10057}},questType="standard",sourceQuests={54438},questLines={{id=851,name="Crucible of Storms",orderIndex=20,flags=0}},db2PoiUiMapID=84},
[54683] = {id=54683,name="The Black Blade",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10057,mapID=85,storyline={53760,53761,53762,53763,53766,54058,54117,54118,54172,54174,54433,54439,54683},description="<The blade that was known as Xal'atath rests on the ground before you. Though the consciousness that resided within the dagger is gone, it still resonates with power. Almost as if the weapon speaks with another voice. Another purpose.... You feel a compulsion to bring this artifact to the warchief.>",objectivesText="Bring the Dagger to Warchief Sylvanas Windrunner.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1553,amount=500}},ends={{npcID=134711}},startObjects={{objectID=316443,mapID=1346,x=0.27,y=0.54}},coords={mapID=85,source="quest_giver",x=0.485,y=0.715},mapCandidates={npc={85},zone={10057}},questType="standard",sourceQuests={54439},questLines={{id=851,name="Crucible of Storms",orderIndex=21,flags=0}},db2PoiMapID=1,db2PoiUiMapID=85},
