[54703] = {id=54703,name="Express Delivery",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53887,53888,53896,53909,53910,53916,53919,53936,53978,53986,54518,54519,54559,54703,54787},description="The Horde appears to have misplaced some of its Azerite . It would be rude of us not to return it, don't you think? The most efficient way is for me to teleport it back. I've enchanted the harpoons in that launcher over there. Fire them onto the Horde ships in the bay. I can use them as beacons to return the Azerite to the Horde... and send its ships on their way.",objectivesText="Mark locations on the Horde ships to direct Jaina's spell. Progress: Well done, <name>.",rewardGold=234000,rewardXP=6815,rewardItems={164921,164968,166280,166682},rewardCurrencies={{id=1553,amount=750}},starts={{npcID=145580}},ends={{npcID=145580}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={53936},questLines={{id=843,name="Beware the Daughter of the Sea",orderIndex=13,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=843,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=843,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[54706] = {id=54706,name="Made in Kul Tiras",level=40,requiredLevel=40,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=1519,mapID=84,storyline={53720,54706,54708,54721,54723,54725,54726,54727,54728,54729,54730,54731,54732,54733,54734,54735,54851,55039,55043,55136},series={54708,54721,55039,55043},description="Are you curious about how the Kul Tirans joined the Alliance? It was assumed that Kul Tiras would rejoin the Alliance after everything that was done to stabilize their nation. Lady Jaina Proudmoore wanted to cement the allegiance by building King Anduin a ship worthy of the Kul Tiran navy. She wished for help in finding the best shipwright in Kul Tiras, Dorian Atwater. It wouldn't be easy, as Dorian was retired. It all began with a trip to see Cyrus in Boralus Harbor...",objectivesText="Speak to Cyrus in Boralus Harbor. Progress: Yes?",rewardGold=170800,rewardXP=2735,rewardItems={164762},starts={{npcID=126332},{npcID=148798}},ends={{npcID=126332}},mapCandidates={npc={84},zone={1519}},questTurnInID=126332,questType="standard",sourceQuests={50239},questLines={{id=916,name="Allies of the Alliance: Kul Tiran",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[54707] = {id=54707,name="Siegeotron",level=10,requiredLevel=10,faction="horde",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={54707},rewardXP=2125,starts={{npcID=148842,mapID=863,x=0.542,y=0.078}},mapCandidates={npc={},zone={8500}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=148842}},worldTaskTitle="Siegeotron",db2PoiMapID=1642,db2PoiUiMapID=863,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3496,db2VignetteName="Siegeotron"},
[54708] = {id=54708,name="Home, Home On the Range",level=40,requiredLevel=40,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={53720,54706,54708,54721,54723,54725,54726,54727,54728,54729,54730,54731,54732,54733,54734,54735,54851,55039,55043,55136},series={54706,54721,55039,55043},description="<Cyrus peruses a map.> Hmm... Along the road to Fort Daelin... to the north... somewhere in the Deadwash. <He points to a section of road on the map.> I've marked a spot on your map that seems likely. I think that will get you close enough. I'll report back to the Lord Admiral with what we've learned. Good luck, and I hope our shipwright is willing.",objectivesText="Track down the shipwright in Stormsong Valley and deliver the Lord Admiral's Letter. Progress: Now what's this?",rewardGold=161000,rewardXP=2735,rewardItems={164762,166462},starts={{npcID=150515}},ends={{npcID=148870}},mapCandidates={npc={895,942},zone={9042}},questType="standard",sourceQuests={55043},questLines={{id=916,name="Allies of the Alliance: Kul Tiran",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
