[54754] = {id=54754,name="For the Queen",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=1637,mapID=85,storyline={54097,54099,54100,54101,54102,54103,54104,54105,54106,54107,54108,54109,54754},description="<You chose not to side with the traitor Saurfang and his troll lackey. Now that you know where Saurfang is, and who is with him, you should report to Sylvanas to see if she has any further orders.>",objectivesText="Meet with Lady Sylvanas Windrunner in Orgrimmar.",rewardGold=23400,rewardXP=850,rewardItems={19971,39346,39387,39436,39450,54996,54997,54998,57492,57493,59269,59270,59271,59272,59306,59307,59308,59309,106143,106153,106176,107314,121482,121488,124124,131369,131526,131527,131549,131550,132269,132279,132280,132281,132282,132283,132284,132285,132286,132287,132288,132289,132290,132294,132295,132296,132297,132298,132299,132302,132303,133803,137865,137866,138855,138856,138857,138858,138859,138860,138861,138862,141387,141403,163128,165638,181501,181502,181503,181507,181625,181626,181645,181647,181649,181650,181652,181653,181654,181661,181662,181663,181679,181680,181682,181694,184194,184305,184772,184773,184774,184775,184776,198353,224072,225896,236956,260583},rewardCurrencies={{id=1553,amount=426},{id=1553,amount=427},{id=1553,amount=428},{id=1553,amount=429}},ends={{npcID=134711}},startObjects={{mapID=49,x=0.814,y=0.524}},coords={mapID=85,source="quest_giver",x=0.485,y=0.715},mapCandidates={npc={85},zone={1637}},questType="standard",sourceQuests={54106},questLines={{id=802,name="Lost Honor",orderIndex=10,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=802,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=802,questLineOrder=12}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1,db2PoiUiMapID=85},
[54755] = {id=54755,name="Not My Table",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,storyline={54755},description="<You have decided to neither follow Zekhan to Swamp of Sorrows, nor report this event back to Sylvanas. Instead, you find yourself longing to spend a sun-soaked afternoon relaxing, and you know just the spot. Sometimes, it's nice to let others take care of things.>",objectivesText="Head to the Steam Pools, obtain a burger and a beverage, and lay out in the sun.",rewardGold=23400,rewardXP=850,rewardItems={56897,56898,56899,56900,56901,56902},mapCandidates={npc={},zone={}},questType="standard"},
[54756] = {id=54756,name="Garbage for the Garbage God",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=1165,storyline={54756},series={54757},description="Richmon, you found a thing I been looking for for a long time. Bring it to me in the Port of Zandalar, and I will grant you my favor.",objectivesText="Bring Jani's First Offering to Jani 's Trashpile in the Port of Zandalar. Provided item:",rewardGold=2000,rewardXP=1415,rewardItems={166506,166507},ends={{npcID=149006}},coords={mapID=1165,source="quest_giver",x=0.455,y=0.945},mapCandidates={npc={1165},zone={8670}},questType="standard",startItems={166507}},
[54757] = {id=54757,name="The Loa of Scavengers",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=1165,storyline={54757},series={54756},description="Richmon, you bring me many shiny things. You helped some of those that no one else would. And ya dumb enough to keep comin' back to me trash piles. I like ya style. Now for da big one. Go to the steps of Dazar'alor, and find the Chronicler Ash'tari . Her chisel makes da shrines there. Tell her to build me a shrine and I will grant you my boon. Unlike the flappy Pa'ku or running Gonk, I just gonna let ya scrap your trash in my pile and I'll give ya stuff back. Anywhere my trash piles be.",objectivesText="Speak with Chronicler Ash'tari at Dazar'alor.",rewardGold=25740,rewardXP=175,starts={{npcID=149006}},ends={{npcID=137510}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={54756}},
[54759] = {id=54759,name="When Spirits Whisper",level=50,requiredLevel=50,faction="horde",requiredRaces={6},categories={"campaign"},flags={"important"},sharable=true,expansion=7,zoneID=1637,mapID=85,storyline={54759,54760,54761,54762,54763,54764,54765,54766},series={54760},description="Ah, <name>! I have a message for you. Baine Bloodhoof asks that you join him in Thunder Bluff at once. I suggest you hurry.",objectivesText="Meet with Baine Bloodhoof in Thunder Bluff.",rewardGold=30900,rewardXP=850,rewardItems={166899,167860,170063,174077,203176,208476,210054,218105,218118,218119,242520},starts={{npcID=149088}},ends={{npcID=36648}},mapCandidates={npc={85,88},zone={1637}},questType="standard",questLines={{id=860,name="Tauren Heritage",orderIndex=0,flags=0}},db2PoiMapID=1,db2PoiUiMapID=88},
[54760] = {id=54760,name="The Spiritwalkers",level=50,requiredLevel=50,faction="horde",requiredRaces={6},categories={},flags={},sharable=true,expansion=7,zoneID=1638,mapID=88,storyline={54759,54760,54761,54762,54763,54764,54765,54766},series={54759},description="As you know, the spiritwalkers commune with our ancestors and maintain balance within the spirit realm. It is a sacred duty that links our present to our past. But lately the spiritwalkers have been troubled by visions of chaos and turmoil. Of a rising darkness. They tell me that the spirits have whispered your name. We are unsure why, but Spiritwalker Ussoh means to find out. Seek Ussoh on Fargaze Mesa to the south. Good luck, <name>. I believe you may need it.",objectivesText="Speak with Spiritwalker Ussoh at Fargaze Mesa in Camp Narache.",rewardGold=31200,rewardXP=850,rewardItems={166899,167860},starts={{npcID=36648}},ends={{npcID=149084}},mapCandidates={npc={1,88},zone={1638}},questType="standard",sourceQuests={54759},questLines={{id=860,name="Tauren Heritage",orderIndex=1,flags=0}},db2PoiMapID=1,db2PoiUiMapID=462},
[54761] = {id=54761,name="Spirit Guide",level=50,requiredLevel=50,faction="horde",requiredRaces={6},categories={},flags={},sharable=true,expansion=7,zoneID=6452,mapID=1,storyline={54759,54760,54761,54762,54763,54764,54765,54766},description="The ancestors have whispered your name, <name>. Now it is time for you to reach out to them. Here in this sacred place, we spiritwalkers commune with those who came before us. Sit within the circle and light the incense. If you open your heart, a spirit guide will present itself to you. Let us hope it will lead you to the answers we seek.",objectivesText="Light the Spiritwalker's Incense at Fargaze Mesa in Camp Narache. Progress: Have you found your guide?",rewardGold=234000,rewardXP=6815,rewardItems={166899,167860},starts={{npcID=149084}},ends={{npcID=149084}},mapCandidates={npc={1},zone={6452}},questType="standard",sourceQuests={54760},questLines={{id=860,name="Tauren Heritage",orderIndex=2,flags=0}},db2PoiMapID=1,db2PoiUiMapID=462},
[54762] = {id=54762,name="A Small Retreat",level=50,requiredLevel=50,faction="horde",requiredRaces={6},categories={},flags={},sharable=true,expansion=7,zoneID=6452,mapID=1,storyline={54759,54760,54761,54762,54763,54764,54765,54766},description="I believe your guide was delivering a warning. The unrest within the spirit realm may be even more dire than first feared. We must cross over at once, from a place with a strong bond to the spirit realm. In ages past, tauren made pilgrimages to Sun Rock Retreat to engage in such a ritual. It is said that long ago, An'she himself kissed the mountain where the retreat now stands. Meet me there and we will begin the crossing.",objectivesText="Meet with Spiritwalker Ussoh at Sun Rock Retreat in Stonetalon Mountains.",rewardGold=23400,rewardXP=850,rewardItems={166899,167860},starts={{npcID=149084}},ends={{npcID=149529}},mapCandidates={npc={1,65},zone={6452}},questType="standard",sourceQuests={54761},questLines={{id=860,name="Tauren Heritage",orderIndex=3,flags=0}},db2PoiMapID=1,db2PoiUiMapID=65},
[54763] = {id=54763,name="Crossing Over",level=50,requiredLevel=50,faction="horde",requiredRaces={6},categories={},flags={},sharable=true,expansion=7,zoneID=406,mapID=65,storyline={54759,54760,54761,54762,54763,54764,54765,54766},description="We are ready to begin. You will be crossing into the spirit realm. Take caution, for it can be a place of both tranquility and danger. Make contact with your spirit guide. There must be a reason it was in pain when it revealed itself to you. When you are ready, raise this vessel to enter the spirit realm.",objectivesText="Enter the spirit realm and make contact with your spirit guide. Progress: Are you ready to enter the spirit realm?",rewardGold=309800,rewardXP=6815,rewardItems={166899,167860},starts={{npcID=149529}},ends={{npcID=149529}},mapCandidates={npc={65},zone={406}},questType="standard",sourceQuests={54762},questLines={{id=860,name="Tauren Heritage",orderIndex=4,flags=0}},db2PoiMapID=1,db2PoiUiMapID=65,db2QuestSortName="Artifact"},
[54764] = {id=54764,name="Storm in Bloodhoof",level=50,requiredLevel=50,faction="horde",requiredRaces={6},categories={},flags={},sharable=true,expansion=7,zoneID=406,mapID=65,storyline={54759,54760,54761,54762,54763,54764,54765,54766},description="This is worse than I feared. The people of Bloodhoof Village are in grave danger. Even the brave young tauren who train there are woefully unprepared for the danger that is coming. Do what you can to stop this threat. I will go to Thunder Bluff to warn the High Chieftain.",objectivesText="Travel to Bloodhoof Village in Mulgore and stop the spirit attack.",rewardGold=234000,rewardXP=6815,rewardItems={166899,167860},starts={{npcID=149529}},ends={{npcID=149528}},mapCandidates={npc={65,88},zone={406}},questType="standard",sourceQuests={54763},questLines={{id=860,name="Tauren Heritage",orderIndex=5,flags=0}},db2PoiMapID=1,db2PoiUiMapID=88,db2QuestSortName="Artifact"},
[54765] = {id=54765,name="Thank Your Guide",level=50,requiredLevel=50,faction="horde",requiredRaces={6},categories={},flags={},sharable=true,expansion=7,zoneID=1638,mapID=88,storyline={54759,54760,54761,54762,54763,54764,54765,54766},series={54766},description="The balance has been restored, and Thunder Bluff is safe. Thank you. We owe our victory to your spirit's guidance. We must honor the old ways by giving thanks to the ones who came before us. To the southwest lies a beautiful vista where my father once took me. It would be a fitting place to reflect upon all that has transpired. Please take this offering there to honor our ancestors.",objectivesText="Deliver the offering to your spirit guide on the cliffs southwest of Thunder Bluff.",rewardGold=638000,rewardXP=8520,rewardItems={166899,167860},starts={{npcID=36648}},ends={{npcID=36648}},mapCandidates={npc={88},zone={1638}},questTurnInID=36648,questType="standard",sourceQuests={54766},questLines={{id=860,name="Tauren Heritage",orderIndex=7,flags=0}},db2PoiMapID=1,db2PoiUiMapID=88},
[54766] = {id=54766,name="Answer the Call",level=50,requiredLevel=50,faction="horde",requiredRaces={6},categories={},flags={},sharable=true,expansion=7,zoneID=1638,mapID=88,storyline={54759,54760,54761,54762,54763,54764,54765,54766},series={54765},description="It is fortunate that Spiritwalker Ussoh passed along your spirit guide's warning. We were able to evacuate most of the citizens. This cursed spirit is full of malevolence and hatred. It must be destroyed, <name>! We attack on your command.",objectivesText="Stop the Malevolent Spirit .",rewardGold=234000,rewardXP=6815,rewardItems={166899,167030,167860},starts={{npcID=149528}},ends={{npcID=36648}},mapCandidates={npc={88},zone={1638}},questType="standard",sourceQuests={54764},questLines={{id=860,name="Tauren Heritage",orderIndex=6,flags=0}},db2PoiMapID=1,db2PoiUiMapID=88},
[54781] = {id=54781,name="What's For Lunch?",level=90,requiredLevel=90,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=15458,mapID=2405,storyline={54781},description="My Shadowtrade Mercenaries will fight for Stormarion Cores , no questions asked, but they do get hungry also! Food is quite scarce here, so we need supplies! Take a mercenary out with you and find some food for them to eat. I'll make it worth your while!",objectivesText="Slay Lurking Stormrays for 6 Stormray Fins and search Stormarion Supply crates for 6 Domanaar Snack Packs . Progress: Is that mercenary well fed?",rewardGold=341600,rewardXP=20540,rewardItems={246951,248927,248929},starts={{npcID=244749}},ends={{npcID=244749}},mapCandidates={npc={2405},zone={15458}},questType="standard",worldTaskTitle="What's For Lunch?",db2PoiMapID=2771,db2PoiUiMapID=2405},
[54784] = {id=54784,name="Blackwood Liberation",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=148,mapID=62,rewardCurrencies={{id=1717,amount=1}},mapCandidates={npc={},zone={148}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=149179,text="Ride with the Ancient Protector"},{orderIndex=1,type=0,amount=20,objectID=147816,text="Kor'gar forces slain"},{orderIndex=2,type=2,amount=1,objectID=316899,text="Furbolgs freed"}},worldTaskTitle="Blackwood Liberation",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[54786] = {id=54786,name="Stop the Shipments",level=10,requiredLevel=10,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8501,mapID=864,storyline={54786},objectivesText="Talk with Sandwalker Vaakara Hired vulpera scared off Transported Supplies destroyed",rewardXP=2125,mapCandidates={npc={},zone={8501}},questType="standard",db2Objectives={{text="Talk with Sandwalker Vaakara",amount=1,type=0,objectID=149305,orderIndex=0},{text="Hired vulpera scared off",amount=6,type=0,objectID=149304,orderIndex=1},{text="Transported Supplies destroyed",amount=6,type=0,objectID=149298,orderIndex=2}},worldTaskTitle="Stop the Shipments",db2PoiMapID=1642,db2PoiUiMapID=864,db2QuestInfoID=259,db2QuestInfoName="Faction Assault World Quest"},
[54787] = {id=54787,name="Masking For a Friend",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={53887,53888,53896,53909,53910,53916,53919,53936,53978,53986,54518,54519,54559,54703,54787},description="The Outriggers have fought some pretty tough monsters and Horde savages aren't so much different. The Blight Specialists they brought weren't especially tough, but they were the most dangerous. Kill a few of them and bring back their face masks. Okri can work his mechanical wizardry and build us better masks of our own in case any Horde scum dare show their blight-spreading faces around here again.",objectivesText="Collect 4 Blight Specialist Masks . Progress: Did you get rid of those blighted wretches?",rewardGold=234000,rewardXP=6815,rewardItems={164921,164968,166280,166682},rewardCurrencies={{id=1553,amount=350}},starts={{npcID=145593}},ends={{npcID=145593}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={53909,53916,54518,54519},questLines={{id=843,name="Beware the Daughter of the Sea",orderIndex=10,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=843,questLineOrder=14,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=843,questLineOrder=7}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[54795] = {id=54795,name="Aman",level=50,requiredLevel=50,faction="horde",categories={},flags={"elite","rare"},sharable=false,expansion=7,zoneID=148,mapID=62,storyline={54795},rewardGold=105000,rewardXP=200,rewardItems={69598,69599,251970,264257,264334,264460,264461,264462,264463,264464,264465,264466,264467,264914,269980,272125},rewardCurrencies={{id=1716,amount=1}},mapCandidates={npc={},zone={148}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=147966}},worldTaskTitle="Aman",db2PoiMapID=1,db2PoiUiMapID=62,db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
