[54839] = {id=54839,name="Rightfully Ours",level=10,requiredLevel=10,faction="alliance",categories={},flags={"elite"},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={54839},objectivesText="Alliance Supplies retrieved",rewardXP=2125,rewardItems={166726},starts={{npcID=149383,mapID=863,x=0.506,y=0.176}},mapCandidates={npc={},zone={8500}},questType="standard",db2Objectives={{text="Alliance Supplies retrieved",amount=1,type=1,objectID=166726,orderIndex=1}},worldTaskTitle="Rightfully Ours",db2PoiMapID=1642,db2PoiUiMapID=863,db2QuestInfoID=260,db2QuestInfoName="Faction Assault Elite World Quest",db2VignetteID=3505,db2VignetteName="Xizz Gutshank"},
[54843] = {id=54843,name="Remaining Threats",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10288,mapID=62,storyline={54843},description="Though our forces maintain a steady hold on Darkshore , this land still festers with enemies at every turn. Do what you can to keep them at bay, and you will be well rewarded.",objectivesText="Defeat 12 rare enemies in Darkshore . Progress: Is the deed done?",rewardCurrencies={{id=1560,amount=200}},starts={{npcID=149410}},ends={{npcID=149410}},mapCandidates={npc={62},zone={148}},questType="group"},
[54844] = {id=54844,name="Tapping the Breach",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10288,mapID=62,storyline={54844},description="Darkshore is home to several elemental breaches which hold massive amounts of power. The remnants of the Twilight's Hammer know this. While we were preoccupied with the Kaldorei, their elementalists have moved to exploit these locations of power, calling forth massive elementals to do their bidding. Their actions must not go unchecked.",objectivesText="Defeat 20 Twilight elementalists in Darkshore . Progress: What of the cultist threat?",rewardCurrencies={{id=1553,amount=300}},starts={{npcID=149411}},ends={{npcID=149411}},mapCandidates={npc={62},zone={148}},questType="standard"},
[54845] = {id=54845,name="Buzzkill",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10288,mapID=62,storyline={54845},description="Some gnome's been goin about planting these strange machines in the woods here. I don't know what they do, but I'll be dead before I let gnomish machines sully goblin territory! Find these \"buzzboxes\" and reduce them to scrap. I'll make sure you're compensated for your troubles.",objectivesText="Destroy 4 Buzzboxes in Darkshore . Progress: Did you take care of our gnomish problem?",rewardGold=464700,rewardXP=1415,rewardItems={178021,178022,178023,178024,178025,178027,178030,180473,180474},rewardCurrencies={{id=1560,amount=200}},starts={{npcID=149412}},ends={{npcID=149412}},mapCandidates={npc={62},zone={148}},questType="standard"},
[54850] = {id=54850,name="Operation: Troggageddon",level=50,requiredLevel=50,faction="alliance",requiredRaces={7},categories={},flags={},sharable=true,expansion=7,zoneID=67,mapID=114,storyline={54402,54576,54577,54580,54581,54582,54639,54640,54641,54642,54850},description="Tinkerbow has finished installing the guns on our flying machines, so it's time to give them a trial by fire. We've got confirmation that our target is in fact within the Halls of Stone. Let's start clearing out the forces out in front. We'll take the earliest opportunity to bring the fight to Sparkspanner!",objectivesText="Clear out Sparkspanner's army.",rewardGold=567400,rewardXP=8520,starts={{npcID=147950}},ends={{npcID=147950}},mapCandidates={npc={114},zone={67}},questTurnInID=147950,questType="standard",sourceQuests={54640},questLines={{id=858,name="Gnome Heritage Armor",orderIndex=8,flags=0}},db2PoiMapID=571,db2PoiUiMapID=120},
[54851] = {id=54851,name="Blessing of the Tides",level=40,requiredLevel=40,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=84,storyline={53720,54706,54708,54721,54723,54725,54726,54727,54728,54729,54730,54731,54732,54733,54734,54735,54851,55039,55043,55136},description="Dorian certainly lives up to her reputation, <name>. This magnificent vessel is complete and now it has a crew. Two pieces remain. First, we must give the ship a name. Then it falls to Brother Pike to bless this vessel. As is tradition, a tidesage's blessing fortifies the ship against storms and encourages fair weather and smooth seas. It is as much ceremonial as it is practical. Once that is done, we will set sail for Stormwind.",objectivesText="Choose a name for the new vessel, then witness Brother Pike 's blessing. Progress: I chose you for this honor to thank you for all you have done for my people, and all that you have done for me.",rewardGold=170800,rewardXP=2735,rewardItems={164762},starts={{npcID=148798}},ends={{npcID=148798}},mapCandidates={npc={84},zone={9042}},questType="standard",sourceQuests={54735},questLines={{id=916,name="Allies of the Alliance: Kul Tiran",orderIndex=19,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[54856] = {id=54856,name="Bilgewater Bandits",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=148,mapID=62,storyline={54856},rewardItems={166475},rewardCurrencies={{id=1717,amount=1}},mapCandidates={npc={},zone={148}},questType="world",db2Objectives={{orderIndex=0,type=1,amount=100,objectID=166475}},worldTaskTitle="Bilgewater Bandits",db2PoiMapID=1,db2PoiUiMapID=62,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[54858] = {id=54858,name="Glaive Consequences",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=148,mapID=62,rewardCurrencies={{id=1717,amount=1}},mapCandidates={npc={},zone={148}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=149609,text="Ride the Kaldorei Hippogryph"},{orderIndex=1,type=0,amount=50,objectID=149597,text="Shatterpear trolls slain"}},worldTaskTitle="Glaive Consequences",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[54871] = {id=54871,name="We Are Coming",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={53847,53849,53988,53989,53990,53992,54006,54041,54871},description="We must press our advantage before the Horde can further its hold on Darkshore. The kaldorei stand ready to fight for our home, and the Gilneans stand alongside us. We will show our enemies our fury. They will learn to fear us. Rally any you can. We march at once.",objectivesText="Inform Ralston Karn to prepare for the assault on Darkshore.",rewardGold=23400,rewardXP=850,rewardItems={174292,175063,177053,178156,179942,199680,199681,199682,199683,199684},starts={{npcID=149612}},ends={{npcID=142721}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={53990},questLines={{id=797,name="In Darkest Night",orderIndex=6,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[54875] = {id=54875,name="Remaining Threats",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10288,mapID=62,storyline={54875},description="We have managed to route the Horde presence in Darkshore , but several threats remain throughout the countryside. If we wish to hold this land, they must be eliminated.",objectivesText="Defeat 12 rare enemies in Darkshore . Progress: How's your progress?",rewardCurrencies={{id=1560,amount=200}},starts={{npcID=149623}},ends={{npcID=149623}},mapCandidates={npc={62},zone={148}},questType="group"},
[54876] = {id=54876,name="Tapping the Breach",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10288,mapID=62,storyline={54876},description="We had thought the Twilight's Hammer's presence in Darkshore was snuffed out with the defeat of Deathwing. Apparently, we were mistaken. Remnants of their cult have used the conflict in Darkshore as an opportunity to re-establish their presence here. Darkshore is home to several breaches of elemental power, and it looks like they aim to use these to unleash powerful elementals to devastate the land. This must not stand.",objectivesText="Defeat 20 Twilight elementalists in Darkshore .",rewardCurrencies={{id=1553,amount=300}},starts={{npcID=149624}},ends={{npcID=149624}},mapCandidates={npc={62},zone={148}},questType="standard"},
[54878] = {id=54878,name="Buzzkill",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10288,mapID=62,storyline={54878},description="Some nefarious no-goodnik is tampering with my Buzzboxes! I've been trying to get the Buzzbox network back online since we were able to drive the Horde out of Darkshore , but I'm getting no reading from boxes 456, 627, 111, and 854! I'd be willing to bet that some stragglers from the Bilgewater Cartel are to blame! See if you can get those Buzzboxes back online, will you? We'll need their readings if we ever want to permanently fix the corruption problem here.",objectivesText="Repair 4 Buzzboxes in Darkshore .",rewardGold=464700,rewardXP=1415,rewardItems={178021,178022,178023,178024,178025,178027,178030,180473,180474},rewardCurrencies={{id=1560,amount=200}},starts={{npcID=149631}},ends={{npcID=149631}},mapCandidates={npc={62},zone={148}},questType="standard"},
[54913] = {id=54913,name="Spark of Genius",level=50,requiredLevel=50,faction="both",requiredClasses={3},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1161,storyline={54913,54915,54916,54917,54918,54919,54920,55195,55516},description="<name>, I have wondrous news! A recent energy signature tripped several detection relays I installed after that unfortunate incident with Sargeras. I require further data to know for certain, but initial diagnostics suggest that these energies are coming from Hati! We might still be able to save him! Hati's spirit is still bound to your own, so I'll need your help. Meet me at my library in the Storm Peaks right away!",objectivesText="Meet Mimiron at the Inventor's Library in the Storm Peaks.",rewardGold=23400,rewardXP=850,starts={{npcID=152002}},ends={{npcID=149736}},mapCandidates={npc={120,1161},zone={8670}},questType="standard",questLines={{id=862,name="Never Hunt Alone",orderIndex=0,flags=0}},db2PoiMapID=571,db2PoiUiMapID=120},
[54915] = {id=54915,name="Telemetry Online",level=50,requiredLevel=50,faction="both",requiredClasses={3},categories={},flags={},sharable=false,expansion=7,zoneID=67,mapID=120,storyline={54913,54915,54916,54917,54918,54919,54920,55195,55516},description="When Titanstrike's power was expended in Silithus, Hati's essence managed to sever itself from the Thunderspark just in time to avoid destruction. The only problem is that his essence was then scattered across Azeroth, and we don't know where. Now that we've locked onto his energy signature, we should be able to triangulate Hati's position!",objectivesText="Assist Mimiron in locating Hati's essence. Progress: Everything is possible with science!",rewardGold=234000,rewardXP=6815,starts={{npcID=149736}},ends={{npcID=149799}},mapCandidates={npc={120},zone={67}},questType="standard",sourceQuests={54913,55516},questLines={{id=862,name="Never Hunt Alone",orderIndex=2,flags=0}},db2PoiMapID=571,db2PoiUiMapID=120},
[54916] = {id=54916,name="The Huntsman's Creed",level=50,requiredLevel=50,faction="both",requiredClasses={3},categories={},flags={},sharable=false,expansion=7,zoneID=67,mapID=120,storyline={54913,54915,54916,54917,54918,54919,54920,55195,55516},description="Through the glorious wonder of science, I have managed to keep the Thunderspark powered precisely for this purpose. All you need to do is get to the Temple of Storms and absorb Hati's essence into it. Just... kind of point it in his general direction. Oh, and do keep in mind that this is only one part of Hati. You may run into a few... technical difficulties before he's subdued enough for the absorption protocol.",objectivesText="Absorb Hati's essence into the Thunderspark at the Temple of Storms.",rewardGold=234000,rewardXP=6815,rewardItems={166895},starts={{npcID=149736}},ends={{npcID=149870}},mapCandidates={npc={120},zone={67}},questType="standard",sourceQuests={54915},questLines={{id=862,name="Never Hunt Alone",orderIndex=3,flags=0}},db2PoiMapID=571,db2PoiUiMapID=120},
[54917] = {id=54917,name="Paid in Blood",level=50,requiredLevel=50,faction="both",requiredClasses={3},categories={},flags={},sharable=false,expansion=7,zoneID=1377,mapID=120,storyline={54913,54915,54916,54917,54918,54919,54920,55195,55516},description="If Mimiron's fancy gadgets be right, then the other half o' Hati is near the wound in Silithus. We'll have tae move quickly. Even with part o' his essence contained, I can feel him fadin' away fast! 'Tis a long trip, <lad/lass>. Let's get movin'!",objectivesText="Absorb Hati's essence into the Thunderspark at the Wound in Silithus. Progress: Yes?",rewardGold=234000,rewardXP=6815,rewardItems={46874,64457,167061},starts={{npcID=149870}},ends={{npcID=150391}},mapCandidates={npc={81,120},zone={1377}},questType="standard",sourceQuests={54916},questLines={{id=862,name="Never Hunt Alone",orderIndex=4,flags=0}},db2PoiMapID=1,db2PoiUiMapID=81},
[54918] = {id=54918,name="Spark of Imagination",level=50,requiredLevel=50,faction="both",requiredClasses={3},categories={},flags={},sharable=false,expansion=7,zoneID=1377,mapID=81,storyline={54913,54915,54916,54917,54918,54919,54920,55195,55516},series={54919},description="I've diverted all non-essential power to prepare for Hati's reformation, so I cannot teleport you to Ulduar from here. Be extremely careful with the Thunderspark on your way. It is charged with highly volatile energy. One wrong bump could lead to serious complications!",objectivesText="Use the Teleportation Pad outside Ulduar to rendezvous with Mimiron in his workshop.",rewardGold=23400,rewardXP=850,starts={{npcID=150391}},ends={{npcID=150391}},mapCandidates={npc={81},zone={1377}},questTurnInID=150391,questType="standard",sourceQuests={54917},questLines={{id=862,name="Never Hunt Alone",orderIndex=5,flags=0}},db2PoiMapID=1579,db2PoiUiMapID=745},
[54919] = {id=54919,name="Bonds of Thunder",level=50,requiredLevel=50,faction="both",requiredClasses={3},categories={},flags={},sharable=false,expansion=7,zoneID=8161,mapID=745,storyline={54913,54915,54916,54917,54918,54919,54920,55195,55516},series={54918},description="While you infused Hati's essence into the Thunderspark, I have concocted a flawless plan the likes of which the scientific world has never seen! I'll spare you the technical details. Just follow my instructions and Hati will be back in one piece in no time at all! ...Or we will all explode. But risks must be taken in the pursuit of knowledge and the well-being of our furry companions, wouldn't you agree?",objectivesText="Reform Hati. Progress: I know how long you have been waiting for this day, <name>.",rewardGold=234000,rewardXP=6815,rewardItems={167799,167800},starts={{npcID=151061}},ends={{npcID=151061}},mapCandidates={npc={},zone={8161}},questGiverID=151061,questTurnInID=151061,questType="standard",sourceQuests={54918},questLines={{id=862,name="Never Hunt Alone",orderIndex=6,flags=0}},db2PoiMapID=1579,db2PoiUiMapID=745},
[54920] = {id=54920,name="Homeward Bound",level=50,requiredLevel=50,faction="both",requiredClasses={3},categories={},flags={},sharable=false,expansion=7,zoneID=8161,mapID=120,storyline={54913,54915,54916,54917,54918,54919,54920,55195,55516},description="The reformation procedure went positively flawlessly! Most excellent results indeed--and plenty of data to analyze! I'm not sure what it is Thorim has to show you, but I suggest you get to the Temple of Storms right away. He gets a bit destructive when he's kept waiting. Take my teleporter pad directly out of Ulduar. I'm afraid the normal route to the entrance is... inoperable at the moment.",objectivesText="Meet Thorim at the Temple of Storms.",rewardGold=23400,rewardXP=850,rewardItems={142054,233056},starts={{npcID=151061}},ends={{npcID=29445}},mapCandidates={npc={120},zone={8161}},questGiverID=151061,questType="standard",sourceQuests={54919},questLines={{id=862,name="Never Hunt Alone",orderIndex=7,flags=0}},db2PoiMapID=571,db2PoiUiMapID=120},
[54922] = {id=54922,name="The Nuts and Bolts of It",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={54083,54086,54922,54929,55373,55608,55622,55696,55697,55753,56168,56175},description="I started working on the leg gearing. Most the gearing around here is built from spare parts we find in the scrap heaps. We're going to need a lot of spare parts to fix this thing. See what you can find.",objectivesText="Collect 1000 spare parts . Progress: Bring me those spare parts !",rewardGold=257400,rewardXP=1415,rewardItems={166846,168827,169610},starts={{npcID=150573}},ends={{npcID=150573}},mapCandidates={npc={1462},zone={10290}},questType="standard",sourceQuests={55697},questLines={{id=925,name="Making a Mount",orderIndex=5,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[54925] = {id=54925,name="Heresy!",level=40,requiredLevel=40,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53719,53823,53824,53825,53826,53827,53828,53830,53831,54031,54032,54033,54034,54300,54301,54419,54925},description="My own prelates are among them that revolted against Talanji. This is an unspeakable heresy. I will not tolerate it! <She gestures to the prelate before her with her spear.> This one has wisely told me who is to blame. My second, Kaj'ra. I would have heard her, had she used any other means to make her concerns known. Now she must be disposed of. You will find her in de Terrace of de Chosen.",objectivesText="Slay Prelate Kaj'ra . Progress: Death is too good for that heretic.",rewardGold=339600,rewardXP=6830,starts={{npcID=148096}},ends={{npcID=148096}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={53826,54419},questLines={{id=919,name="Allies of the Horde: Zandalari",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[54929] = {id=54929,name="Ready to Rumble",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={54083,54086,54922,54929,55373,55608,55622,55696,55697,55753,56168,56175},description="We're going to need a new Sixteen-Servo-Actuator if we're going to fix the controls on this thing. Bondo's gang at the yard probably has one, but they usually aren't too helpful. Talk to Bondo, see if you can get us one.",objectivesText="Acquire a Sixteen-Servo-Actuator from Bondo Bigblock. Progress: Did you head over to the yard yet?",rewardGold=257400,rewardXP=1415,rewardItems={167175,167176,168827},starts={{npcID=150573}},ends={{npcID=150573}},mapCandidates={npc={1462},zone={10290}},questType="standard",sourceQuests={54086},questLines={{id=925,name="Making a Mount",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[54930] = {id=54930,name="Mechanical Liberation",level=50,requiredLevel=50,faction="both",requiredProfessions={"engineering"},categories={},flags={},sharable=true,expansion=7,zoneID=8501,mapID=864,storyline={53783,53802,53806,53833,53848,53937,54930,55031},description="Since you successfully interrupted my nap, my defenses are obviously lacking to say the least. That's because the sethrak, in addition to stealing my gadgets and gizmos, stole my mechs! Those morons don't even have the keys! <Gryzix laughs> Here, take my keys and get my mechs back.",objectivesText="Free Mecha-Golems in the Scalefang Outpost.",rewardGold=234000,rewardXP=6815,rewardItems={164740},starts={{npcID=145131}},ends={{npcID=145131}},mapCandidates={npc={864},zone={8501}},questType="standard",sourceQuests={53783,53947},questLines={{id=868,name="Tools of the Trade: The Ub3r-Spanner",orderIndex=3,flags=0},{id=869,name="Tools of the Trade: The Ub3r-Spanner",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[54933] = {id=54933,name="Freeing the Light",level=6,requiredLevel=6,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={54933,54951,54952,55122,55173,55174,55184,55186,55193,55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56034,56344,56775,56839,58208,58209,58908,58909,58910,58911,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59254,59339,59342,59347,59349,59350,59352,59354,59355,59356,59583,59586,59587,59588,59589,59590,59591,59592,59593,59594,60168,85678,87547,87555,87560,87562},description="Ah... you are not in league with the ogres. Please, you must aid me. I have been bound against my will by dark magic. I ask only that you free me. Take a piece of my light. Use it to dispel the shadow energies that are keeping me captive.",objectivesText="Use the Lightspawn 's light to dispel nearby shadow energy. Progress: Use my light to dispel the necrotic energies binding me to this place.",rewardGold=170,rewardXP=110,starts={{npcID=157114}},ends={{npcID=157114}},mapCandidates={npc={},zone={10424}},questGiverID=157114,questTurnInID=157114,questType="standard",sourceQuests={55879,59942},questLines={{id=926,name="The Missing Expedition",orderIndex=66,flags=0}},db2PoiMapID=2175,db2PoiUiMapID=1409},
[54938] = {id=54938,name="A Brother's Help",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=9667,mapID=81,storyline={54938,54939,54940,54964},description="We're gonna need all the help we can get te save the planet. I've got an idea. Meet me in Nazmir, outside the Heart of Darkness. Together, we'll seek guidance from someone who may be able to help.",objectivesText="Travel to Nazmir and meet Magni outside Uldir.",rewardGold=23400,starts={{npcID=130216}},ends={{npcID=149867}},mapCandidates={npc={81,863},zone={9667}},questType="standard",sourceQuests={53406},questLines={{id=880,name="The Speaker's Resolve",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[54939] = {id=54939,name="Stubborn as a Bronzebeard",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=8500,mapID=863,storyline={54938,54939,54940,54964},description="It's kind o' Brann tae offer, but his flying machine would drop like a rock with me aboard. Best if it carry just the two of ye. Brann will fly ye down to Uldir. I'll find me own way and meet ye inside.",objectivesText="Take Brann's Flying Machine to Uldir. If you get lost, use the teleporter pad outside the entrance to Uldir.",rewardGold=117000,starts={{npcID=149867}},ends={{npcID=149867}},mapCandidates={npc={863},zone={8500}},questTurnInID=149867,questType="standard",sourceQuests={54938},questLines={{id=880,name="The Speaker's Resolve",orderIndex=1,flags=0}},db2PoiMapID=2169,db2PoiUiMapID=1382},
[54940] = {id=54940,name="Necessity is the MOTHER",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=false,expansion=7,mapID=1382,storyline={54938,54939,54940,54964},description="I may be Azeroth's speaker, but Brann's the expert on titan archaeology. If he says that MOTHER can help us save Azeroth, then I'm more than willing tae place my faith in her. Come, champion. Let's hear what guidance she has tae offer.",objectivesText="Take Magni to meet MOTHER and activate Waygate Consoles Progress: I'll never understand exactly how all these machines work. That's what Brann does!",rewardGold=117000,starts={{npcID=149823}},ends={{npcID=149823}},mapCandidates={npc={},zone={}},questGiverID=149823,questTurnInID=149823,questType="standard",sourceQuests={54939},questLines={{id=880,name="The Speaker's Resolve",orderIndex=2,flags=0}},db2PoiMapID=2169,db2PoiUiMapID=1382},
[54941] = {id=54941,name="Scouting The Strand",level=50,requiredLevel=50,faction="none",categories={},flags={"weekly","repeatable"},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={54941},description="It has been a long time since we have heard from our scouts at the outpost. They may have been cut off from us due to the naga attack. I need to check in with them and get an update on the movements of the naga forces. You should come with me, this will be a good opportunity for you to meet more of the clan and get a closer look at our operation.",objectivesText="Locate the Ankoan scouts at the Ashen Strand.",rewardGold=234000,rewardXP=6815,mapCandidates={npc={},zone={10052}},questType="standard"},
[54943] = {id=54943,name="The Dark Ranger's Pupil",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8317,mapID=18,storyline={54943},description="Thank the abyss you're here, Huntmaster ! I'm concerned about Dark Ranger Velonara. We have become good friends during our time together in the Trueshot Lodge, and I fear she is in peril. She's been training an apprentice dark ranger, a lad named Prelus. Newly raised, she said. At any rate, Prelus ran off after receiving a letter from his brother, and now Velonara has gone to Tirisfal Glades to find him. I have a bad feeling about all this. Could you check on her safety?",objectivesText="Find Dark Ranger Velonara in Tirisfal Glades.",rewardGold=58500,mapCandidates={npc={},zone={8317}},questType="standard",questLines={{id=884,name="Memento of the Dark Rangers",orderIndex=0,flags=0}},db2PoiUiMapID=18},
[54944] = {id=54944,name="The Dark Ranger's Pupil",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8317,mapID=18,storyline={54944},description="Thank the abyss you're here, fellow hunter! I'm concerned about Dark Ranger Velonara, who frequents the Trueshot Lodge. Velonara is a good friend, and I fear she is in peril. She's been training an apprentice dark ranger, a lad named Prelus. Newly raised, she said. At any rate, Prelus ran off after receiving a letter from his brother, and now Velonara has gone to Tirisfal Glades to find him. I have a bad feeling about all this. Would you be willing to check on her safety?",objectivesText="Find Dark Ranger Velonara in Tirisfal Glades.",rewardGold=58500,mapCandidates={npc={},zone={8317}},questType="standard",questLines={{id=884,name="Memento of the Dark Rangers",orderIndex=1,flags=0}},db2PoiUiMapID=18},
[54945] = {id=54945,name="Let's Get It Started",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={54087,54088,54945,54946,54947,54992,55040,55096,55609,55645,55729,55730,55731,55734,55736,55995,56131},description="I theorize this to be a communication relay. It is non-operational, but gnomish ingenuity and your strong back shall soon solve that problem! I need you to help get this device functional.",objectivesText="Repair the device. Progress: We need this device repaired.",rewardGold=257400,rewardXP=1415,starts={{npcID=149877}},ends={{npcID=149877}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={55040},questLines={{id=940,name="Expedition to Mechagon",orderIndex=2,flags=0},{id=5376,name="Welcome to Mechagon",orderIndex=5,flags=0},{id=6060,name="Mechagon Intro",orderIndex=2,flags=0}},campaigns={{id=218,title="Mechagon",questLineID=5376,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6060,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[54946] = {id=54946,name="Report to Gila",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={54087,54088,54945,54946,54947,54992,55040,55096,55609,55645,55729,55730,55731,55734,55736,55995,56131},description="I was quite fortunate that King Mechagon found me worthy! I will send my assistant Gila Crosswires ahead to Boralus to gather a new team. Meet up with her and help out as you can. I will join both of you shortly.",objectivesText="Meet up with Gila Crosswires in Boralus.",rewardGold=257400,rewardXP=1415,starts={{npcID=152864}},ends={{npcID=151100}},mapCandidates={npc={895,1161},zone={8567}},questType="standard",sourceQuests={54087},questLines={{id=940,name="Expedition to Mechagon",orderIndex=4,flags=0},{id=5376,name="Welcome to Mechagon",orderIndex=6,flags=0},{id=6060,name="Mechagon Intro",orderIndex=3,flags=0}},campaigns={{id=218,title="Mechagon",questLineID=5376,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6060,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[54947] = {id=54947,name="A Small Team",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=1161,storyline={54087,54088,54945,54946,54947,54992,55040,55096,55609,55645,55729,55730,55731,55734,55736,55995,56131},description="I've determined the single attribute that is most important for a team member to survive an expedition to Mechagon. That attribute is...being a gnome! Gather these gnomes and meet Tinkmaster Overspark and myself at the departure point.",objectivesText="Gather the team members.",rewardGold=257400,rewardXP=1415,starts={{npcID=151100}},ends={{npcID=150145}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={54946},questLines={{id=940,name="Expedition to Mechagon",orderIndex=5,flags=0},{id=5376,name="Welcome to Mechagon",orderIndex=7,flags=0},{id=6060,name="Mechagon Intro",orderIndex=4,flags=0}},campaigns={{id=218,title="Mechagon",questLineID=5376,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6060,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[54949] = {id=54949,name="More Mouths To Feed",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={54949},description="The naga attack us relentlessly, so there is precious little time to hunt for food and supplies. You have brought many soldiers to our camp, so we must hunt while we have the chance or we will soon run out of food.",objectivesText="Collect 30 Snapshell Flesh . Progress: The meat from this hunt shall nourish our bones.",rewardGold=309800,rewardItems={166904,166905},rewardCurrencies={{id=1721,amount=3},{id=1749,amount=100},{id=1721,amount=2}},starts={{npcID=150123}},ends={{npcID=150123}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56156},worldTaskTitle="More Mouths To Feed",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[54951] = {id=54951,name="Emergency First Aid",level=1,requiredLevel=1,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={54933,54951,54952,55122,55173,55174,55184,55186,55193,55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56034,56344,56775,56839,58208,58209,58908,58909,58910,58911,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59254,59339,59342,59347,59349,59350,59352,59354,59355,59356,59583,59586,59587,59588,59589,59590,59591,59592,59593,59594,60168,85678,87547,87555,87560,87562},description="We have to patch everyone up before we can begin the search for the missing expedition. Take this first aid kit and tend to the wounded.",objectivesText="Use a First Aid Kit on Austin Huxworth , Bjorn Stouthands , and Kee-la . Progress: Walk up to Austin, Bjorn, and Kee-La and use the first aid kit to heal them. Do not move while using it.",rewardGold=565,rewardXP=200,rewardItems={168410,174780},starts={{npcID=156626}},ends={{npcID=156626}},mapCandidates={npc={},zone={10424}},questGiverID=156626,questTurnInID=156626,questType="standard",sourceQuests={55122},questLines={{id=926,name="The Missing Expedition",orderIndex=4,flags=0},{id=1070,name="The Missing Expedition",orderIndex=4,flags=0},{id=5366,name="The Missing Expedition",orderIndex=4,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5366,questLineOrder=0,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[54952] = {id=54952,name="Finding the Lost Expedition",level=1,requiredLevel=1,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={54933,54951,54952,55122,55173,55174,55184,55186,55193,55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56034,56344,56775,56839,58208,58209,58908,58909,58910,58911,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59254,59339,59342,59347,59349,59350,59352,59354,59355,59356,59583,59586,59587,59588,59589,59590,59591,59592,59593,59594,60168,85678,87547,87555,87560,87562},description="Captain Garrick went ahead to find survivors. It looks like she lit a fire. Meet her up ahead to see what she found. I'll look further within the island for survivors... and the source of the magic that attacked us.",objectivesText="Search the nearby camp for expedition survivors.",rewardGold=285,rewardXP=100,starts={{npcID=156626}},ends={{npcID=156626}},mapCandidates={npc={},zone={10424}},questGiverID=156626,questTurnInID=156626,questType="standard",sourceQuests={54951},questLines={{id=926,name="The Missing Expedition",orderIndex=5,flags=0},{id=1070,name="The Missing Expedition",orderIndex=5,flags=0},{id=5366,name="The Missing Expedition",orderIndex=5,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5366,questLineOrder=0,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[54958] = {id=54958,name="Ships in the Night",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=70,storyline={54958,54959,54960,54961,54997,54999,55034,55124},description="Sylvanas has gone too far this time. We may be at war with the Alliance, but there are certain lines we cannot cross. I must right this situation, but I need your assistance. Derek Proudmoore is being held on the Swift Vengeance, which is moored in the harbor here for supplies. We must take him and bring him back to his family. Are you with me?",objectivesText="Take the boat to the Swift Vengeance and find Derek Proudmoore. Progress: There's no time to waste.",rewardGold=468000,rewardXP=8520,starts={{npcID=150309}},ends={{npcID=150309}},mapCandidates={npc={70},zone={8567}},questTurnInID=150309,questType="standard",sourceQuests={54961,55124},questLines={{id=873,name="Testing Loyalties",orderIndex=2,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=873,questLineOrder=21,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=873,questLineOrder=13}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[54959] = {id=54959,name="Under Lock and Keys",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={54958,54959,54960,54961,54997,54999,55034,55124},description="Three keys? It seems Sylvanas didn't trust any one member of this crew to have access to Proudmoore. We won't be able to rescue Derek Proudmoore if we can't get his cage open. We'll need to keep an eye out for keys while we clear the ship.",objectivesText="Collect the Captain's Key , Apothecary's Key , and Navigator's Key on the Swift Vengeance, then use them to open the Reinforced Cage. Progress: This will all be for nothing if we can't open that lock...",rewardGold=468000,rewardXP=8520,rewardItems={167072,167073,167074},starts={{npcID=149842}},ends={{npcID=149842}},mapCandidates={npc={},zone={8567}},questGiverID=149842,questTurnInID=149842,questType="standard",sourceQuests={54958},questLines={{id=873,name="Testing Loyalties",orderIndex=3,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=873,questLineOrder=21,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=873,questLineOrder=13}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[54960] = {id=54960,name="A Bitter Reunion",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=15,mapID=70,storyline={54958,54959,54960,54961,54997,54999,55034,55124},description="We've done it! Zelling will guide the ship to Theramore, and we can put an end to this foul business once and for all. Speak to Zelling when you are ready to leave, and we will set sail.",objectivesText="Speak to Thomas Zelling to set sail to Theramore. Progress: We sail at your command, <class>.",rewardGold=23400,rewardXP=850,rewardCurrencies={{id=1553,amount=750},{id=1560,amount=20}},starts={{npcID=149842}},ends={{npcID=150309}},mapCandidates={npc={70},zone={15}},questGiverID=149842,questType="standard",sourceQuests={54959,54997},questLines={{id=873,name="Testing Loyalties",orderIndex=5,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=873,questLineOrder=21,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=873,questLineOrder=13}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1,db2PoiUiMapID=70},
[54961] = {id=54961,name="Righting Wrongs",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54958,54959,54960,54961,54997,54999,55034,55124},description="Champion! I come with an urgent request from Baine Bloodhoof . He asks that you meet him at Plunder Harbor to help him with a... sensitive situation. You must tell no one of this request, <class>. Ancestors watch over you.",objectivesText="Meet with Baine Bloodhoof at Plunder Harbor in Tiragarde Sound. Progress: I see you've received my message.",rewardGold=23400,rewardXP=850,starts={{npcID=150433}},ends={{npcID=150309}},mapCandidates={npc={70,1165},zone={8670}},questType="standard",sourceQuests={54165,54754},questLines={{id=873,name="Testing Loyalties",orderIndex=0,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=873,questLineOrder=21,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=873,questLineOrder=13}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[54964] = {id=54964,name="A One-Way Ticket to the Heart",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=9667,mapID=1021,storyline={54938,54939,54940,54964},description="These titan facilities never cease tae amaze me. I can only imagine how many of their secrets Brann has yet tae uncover. I just hope that one o' them holds the answer tae saving Azeroth. It's time tae bring MOTHER tae the Chamber of Heart. Be prepared for anythin', champion. Ye can never be quite sure what will happen when ye activate a titan machine.",objectivesText="Evacuate MOTHER from Uldir",rewardGold=234000,starts={{npcID=149823}},ends={{npcID=149823}},mapCandidates={npc={},zone={9667}},questGiverID=149823,questTurnInID=149823,questType="standard",sourceQuests={54940},questLines={{id=880,name="The Speaker's Resolve",orderIndex=3,flags=0}},db2PoiMapID=1929,db2PoiUiMapID=1021},
[54965] = {id=54965,name="Chopped Bots",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={54965},description="Chopping up bots is my business. Any bots you bring to my scrapper will be broken up into useful parts. It's a win for both of us! Use the Bot-Energizer to bring me dead bots, and we'll break them into spare parts .",objectivesText="12 Re-animated bots delivered to Bolten Springspark . Progress: Re-animate dead bots and bring them to me!",rewardGold=257400,rewardXP=1415,rewardItems={166846,166970,166971,246697},starts={{npcID=150086}},ends={{npcID=150086}},mapCandidates={npc={1462},zone={10290}},questType="standard",worldTaskTitle="Chopped Bots",db2LabelIDs={5672},db2PoiMapID=1643,db2PoiUiMapID=1462},
[54969] = {id=54969,name="Descent",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=10052,mapID=1355,description="We've lost the bulk of our forces already; any more and we won't have enough to make a stand. This wreckage won't keep the naga at bay, so we must find safety elsewhere. You will have to trust me here, $p. Leap off the falls and you will descend safely.",rewardGold=23400,rewardXP=850,starts={{npcID=150101}},ends={{npcID=150101}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55095},questLines={{id=949,name="Welcome to Nazjatar",orderIndex=1,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=2,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=949,questLineOrder=21,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},
[54972] = {id=54972,name="A Way Home",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={54969,54972,55095,55175,56350,56640,56641,56642,56643,56644},description="We are only alive thanks to the ankoan and Azshara's desire to toy with us. We will learn more of Okani's people in the times ahead, I am sure. For now, we must establish a portal home. While Azshara is blocking our traditional methods of magical travel, I can sense a powerful convergence of energies nearby. I believe we can use it to open a way home.",objectivesText="Help Jaina open a portal to Boralus.",rewardGold=117000,rewardXP=3410,rewardItems={66898,66899,66900,69217,69223,131709,163337,163339,170514,170515,170516,170517,170518,170519,170520,170521,170522,170523,170524,170525,170526,170527,170528,170529,170530,170531,170532,170533,170534,170535,170536,170537},rewardChoices={170514,170515,170519,170520,170521,170522,170523,170524,170525,170526,170527,170528},starts={{npcID=150101}},ends={{npcID=150101}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55175},questLines={{id=949,name="Welcome to Nazjatar",orderIndex=8,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=9,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=949,questLineOrder=21,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1718,db2PoiUiMapID=1355},
[54975] = {id=54975,name="A Brief Respite",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={54969,54972,54975,55095,55175,55361,55363,55374,55400,55407,55425,55497,55533,55558,55561,55570,55573,55574,55593,55595,55597,55598,55599,55600,55601,55618,55694,55851,55860,55861,55937,56037,56038,56039,56043,56156,56234,56325,56350,56640,56641,56642,56643,56644,56741,57010},description="We have much to do, <name>. However, we are all weary and require rest. Decisions made while fatigued are almost always the wrong ones to make. The Ankoan have offered their home to us, yet they are barely holding on themselves. We should do what we can to support them while we think about our next move. See what you can do to aid their hunting parties, it may be the only way we survive in this place.",objectivesText="Support your allies in Nazjatar by getting one to rank 3.",rewardGold=23400,rewardXP=850,rewardItems={168846},rewardCurrencies={{id=1553,amount=200}},starts={{npcID=150101}},ends={{npcID=150101}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56156},questLines={{id=1022,name="Welcome to Nazjatar",orderIndex=0,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=24,flags=0}},campaigns={{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[54976] = {id=54976,name="The Shadow of Gilneas",level=50,requiredLevel=50,faction="alliance",requiredRaces={22},categories={"campaign"},flags={"important"},sharable=true,expansion=7,zoneID=1519,mapID=84,storyline={54976,54977,54980,54981,54982,54983,54984,54990},description="Champion of Gilneas! I have a letter for you from Princess Tess Greymane . She requests your presence in Stormwind Keep.",objectivesText="Meet with Tess Greymane at Stormwind Keep.",rewardGold=34100,rewardXP=850,rewardItems={170063,173998,173999,174000,174001,174002,174003,174004,174005,174006,174077,203176,208476,210054,218105,218118,218119,242520},starts={{npcID=150200}},ends={{npcID=155313}},mapCandidates={npc={84},zone={1519}},questType="standard",questLines={{id=957,name="Worgen Heritage Armor",orderIndex=0,flags=0}},db2PoiUiMapID=84},
[54977] = {id=54977,name="Into Duskwood",level=50,requiredLevel=50,faction="alliance",requiredRaces={22},categories={},flags={},sharable=true,expansion=7,zoneID=1519,mapID=84,storyline={54976,54977,54980,54981,54982,54983,54984,54990},description="There is a night elf I met in Teldrassil, Vassandra Stormclaw , who may be able to teach Tess without resorting to such an extreme measure. She is the one who originally helped our people with their affliction. Vassandra is currently in Duskwood, assisting the residents of Raven Hill with their attempts to cure the feral worgen in the area. If anyone knows about the curse, it is her. As a more personal request, do not let my daughter do anything too rash. She takes after her father in that way.",objectivesText="Speak with Vassandra Stormclaw in Duskwood.",rewardGold=34100,rewardXP=850,rewardItems={173998,173999,174000,174001,174002,174003,174004,174005,174006},starts={{npcID=151784}},ends={{npcID=151761}},mapCandidates={npc={47,84},zone={1519}},questType="standard",sourceQuests={54976},questLines={{id=957,name="Worgen Heritage Armor",orderIndex=1,flags=0}},db2PoiUiMapID=47},
[54978] = {id=54978,name="Against Overwhelming Odds",level=50,requiredLevel=50,faction="alliance",categories={},flags={"weekly","repeatable"},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={54978},description="We've received numerous reports of the Horde overwhelming our forces within both Kul Tiras and Zandalar. Brute forcing the Alliance with sheer numbers is an age-old tactic of the Horde, but we can't allow them to get the upper hand. Venture forth throughout and thin their numbers the best you can. I recommend bringing reinforcements.",objectivesText="Slay 25 Level 50+ Horde anywhere within Kul Tiras, Zandalar, Nazjatar, Uldum or Vale of Eternal Blossoms.",rewardCurrencies={{id=1553,amount=2000},{id=1553,amount=1000},{id=1602,amount=50}},starts={{npcID=135614}},ends={{npcID=143559}},mapCandidates={npc={1161},zone={8568}},questType="standard"},
[54979] = {id=54979,name="Against Overwhelming Odds",level=50,requiredLevel=50,faction="horde",categories={},flags={"weekly","repeatable"},sharable=true,expansion=7,zoneID=9042,mapID=862,storyline={54979},description="It appears we've allowed the Alliance forces to fester. If these reports are correct, they're outnumbering us in nearly every bastion we hold. Arm yourself, grab a few of your most trusted allies and put them into the ground, <class>!",objectivesText="Slay 25 Level 50+ Alliance anywhere within Kul Tiras, Zandalar, Nazjatar, Uldum or Vale of Eternal Blossoms.",rewardCurrencies={{id=1553,amount=2000}},starts={{npcID=138708}},ends={{npcID=138708}},mapCandidates={npc={862},zone={9042}},questTurnInID=138708,questType="standard"},
[54980] = {id=54980,name="Bane of the Nightbane",level=50,requiredLevel=50,faction="alliance",requiredRaces={22},categories={},flags={},sharable=true,expansion=7,zoneID=10,mapID=47,storyline={54976,54977,54980,54981,54982,54983,54984,54990},description="Princess Greymane has informed me of the situation and I do have an idea of how to help. But first, a favor for a favor. The residents of Duskwood have been plagued recently by a particularly ferocious member of the Nightbane pack that they call 'Bloodeyes'. Take Master Harris's sedative and bring the worgen back to me alive. She will be a perfect subject to test cures on.",objectivesText="Subdue Bloodeyes and return with her to Raven Hill. Progress: If we can cure even the most feral of <race>, then the curse will mean nothing to us.",rewardGold=505440,rewardXP=8520,rewardItems={173998,173999,174000,174001,174002,174003,174004,174005,174006},starts={{npcID=151761}},ends={{npcID=151761}},mapCandidates={npc={47},zone={10}},questType="standard",sourceQuests={54977},questLines={{id=957,name="Worgen Heritage Armor",orderIndex=2,flags=0}},db2PoiUiMapID=47},
[54981] = {id=54981,name="Cry to the Moon",level=50,requiredLevel=50,faction="alliance",requiredRaces={22},categories={},flags={},sharable=true,expansion=7,zoneID=10,mapID=47,storyline={54976,54977,54980,54981,54982,54983,54984,54990},description="Duskwood has a direct connection to the Emerald Dream. Through this connection, I may be able to call forth the Ancient Goldrinn. He will be able to give the princess a taste of the curse she so dangerously chases. A rare bloom grows on the east side of the woods, gather its bloom and meet me in Twilight Grove. It will help me with this ritual.",objectivesText="Gather a bloom of Elune's Grace . Progress: Such flowers have been known to attract wolves, but I doubt you will have a problem with that.",rewardGold=234000,rewardXP=6815,rewardItems={60928,60929,60930,131597,167032,173998,173999,174000,174001,174002,174003,174004,174005,174006,245624},starts={{npcID=151761}},ends={{npcID=151761}},mapCandidates={npc={47},zone={10}},questType="standard",sourceQuests={54980},questLines={{id=957,name="Worgen Heritage Armor",orderIndex=3,flags=0}},db2PoiUiMapID=47},
[54982] = {id=54982,name="The Spirit of the Hunter",level=50,requiredLevel=50,faction="alliance",requiredRaces={22},categories={},flags={},sharable=true,expansion=7,zoneID=10,mapID=47,storyline={54976,54977,54980,54981,54982,54983,54984,54990},description="The other thing I may need for this ritual are the fangs of a wolf. There is a pack that has newly settled in around Manor Mistmantle. Bring me their fangs. I will await your return at Twilight Grove.",objectivesText="Retrieve the fangs from Mistfang wolves. Progress: Did you claim your trophy?",rewardGold=468000,rewardXP=8520,rewardItems={167031,173998,173999,174000,174001,174002,174003,174004,174005,174006},starts={{npcID=151761}},ends={{npcID=151761}},mapCandidates={npc={47},zone={10}},questType="standard",sourceQuests={54980},questLines={{id=957,name="Worgen Heritage Armor",orderIndex=4,flags=0}},db2PoiUiMapID=47},
[54983] = {id=54983,name="Waking a Dreamer",level=50,requiredLevel=50,faction="alliance",requiredRaces={22},categories={},flags={},sharable=true,expansion=7,zoneID=10,mapID=47,storyline={54976,54977,54980,54981,54982,54983,54984,54990},description="This should be all I need to call upon the Ancient. Some unwanted visitors may answer the call first. Protect me as I perform the ritual!",objectivesText="Defend Vassandra Stormclaw as she summons Goldrinn .",rewardGold=341600,rewardXP=6815,rewardItems={173998,173999,174000,174001,174002,174003,174004,174005,174006},starts={{npcID=151761}},ends={{npcID=150106}},mapCandidates={npc={47},zone={10}},questType="standard",sourceQuests={54981,54982},questLines={{id=957,name="Worgen Heritage Armor",orderIndex=5,flags=0}},db2PoiUiMapID=47},
[54984] = {id=54984,name="Let Sleeping Wolves Lie",level=50,requiredLevel=50,faction="alliance",requiredRaces={22},categories={},flags={},sharable=true,expansion=7,zoneID=10,mapID=47,storyline={54976,54977,54980,54981,54982,54983,54984,54990},description="Tess's essence now wanders a section of the Emerald Dream I have twisted into her thoughts. And I have given her my gift, but she could still use a guide. Enter the Dream through the portal behind me. It will place you near where she sleeps. See if you can help show her how rage may blind a mortal.",objectivesText="Enter the Dream Portal and guide Tess.",rewardGold=468000,rewardXP=8520,rewardItems={173998,173999,174000,174001,174002,174003,174004,174005,174006},starts={{npcID=150106}},ends={{npcID=150115}},mapCandidates={npc={47},zone={10}},questType="standard",sourceQuests={54983},questLines={{id=957,name="Worgen Heritage Armor",orderIndex=6,flags=0}},db2PoiUiMapID=47},
[54986] = {id=54986,name="Vision of N'zoth Reward",level=50,requiredLevel=50,faction="none",categories={},flags={},sharable=false,expansion=7,storyline={54986},rewardItems={169154},mapCandidates={npc={},zone={}},questType="standard"},
[54990] = {id=54990,name="The New Guard",level=50,requiredLevel=50,faction="alliance",requiredRaces={22},categories={},flags={},sharable=false,expansion=7,zoneID=10,mapID=47,storyline={54976,54977,54980,54981,54982,54983,54984,54990},description="I need to speak with my parents again. I think my father and I have a bit to discuss. Meet me back at Stormwind Keep. I would like to thank you in a more formal manner.",objectivesText="Meet Tess Greymane at Stormwind Keep. Progress: Yes?",rewardGold=117000,rewardXP=3410,rewardItems={122457,173998,173999,174000,174001,174002,174003,174004,174005,174006},starts={{npcID=150115}},ends={{npcID=155313}},mapCandidates={npc={47,84},zone={10}},questType="standard",sourceQuests={54984},questLines={{id=957,name="Worgen Heritage Armor",orderIndex=7,flags=0}},db2PoiUiMapID=84},
[54992] = {id=54992,name="The Start of Something Bigger",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=1161,storyline={54087,54088,54945,54946,54947,54992,55040,55096,55609,55645,55729,55730,55731,55734,55736,55995,56131},description="We have coordinates locked into the gyrocopters. You and Captain Winklespring will fly the lead. If we run into any trouble, Tinkmaster Overspark wants the most experienced pilots out front. Board whenever you are ready to go.",objectivesText="Board the Expedition Gyrocopter .",rewardGold=257400,rewardXP=1415,rewardItems={246701},starts={{npcID=150145}},ends={{npcID=152484}},mapCandidates={npc={1161,1462},zone={8568}},questType="standard",sourceQuests={54947},questLines={{id=940,name="Expedition to Mechagon",orderIndex=6,flags=0},{id=5376,name="Welcome to Mechagon",orderIndex=8,flags=0},{id=6060,name="Mechagon Intro",orderIndex=5,flags=0}},campaigns={{id=218,title="Mechagon",questLineID=5376,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6060,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[54996] = {id=54996,name="Remembrance",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=1638,mapID=1,storyline={54996},description="You may remember the day Thunder Bluff was attacked. It was your efforts and your guide who saved us. Now we take time to honor our ancestors and give thanks for the path they have set for us. Bring this offering to the cliffs overlooking Thunder Bluff and give thanks to your guide and all our ancestors. A simple gesture to commemorate our past. This is our way.",objectivesText="Deliver the offering to your spirit guide on the cliffs overlooking Thunder Bluff.",rewardGold=312800,rewardXP=6815,rewardItems={46325,52641,52645,55132,156966,223439,223444,223450,223462},starts={{npcID=149084}},ends={{npcID=36648}},mapCandidates={npc={1,88},zone={1638}},questType="standard"},
[54997] = {id=54997,name="Dead in the Water",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={54958,54959,54960,54961,54997,54999,55034,55124},description="Once Proudmoore is freed, we will need to commandeer this ship to transport him to Theramore, where his sister awaits us. Zelling's magic can guide the ship there, but first we'll need to take care of the crew.",objectivesText="Defeat 6 crew members aboard the Swift Vengeance.",rewardGold=234000,rewardXP=6815,starts={{npcID=149842}},ends={{npcID=149842}},mapCandidates={npc={},zone={8567}},questGiverID=149842,questTurnInID=149842,questType="standard",sourceQuests={54958},questLines={{id=873,name="Testing Loyalties",orderIndex=4,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=873,questLineOrder=21,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=873,questLineOrder=13}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[54999] = {id=54999,name="Under False Colors",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=70,storyline={54958,54959,54960,54961,54997,54999,55034,55124},description="If we wish to stay the executioner's axe, we'll need to throw Sylvanas off of our scent. I will take the ship near Chandlery Wharf, which has recently been taken by Irontide pirates. There, I will leave it under the guise of a pirate raid gone wrong. Your task will be to ensure that Sylvanas' forces find this ship. You must report to Nathanos that you spotted a stolen Forsaken vessel in that area. You have no connection to Derek Proudmoore, so it should raise no suspicions.",objectivesText="Start the mission \"Casting the Bait\" then report to Nathanos Blightcaller aboard the Banshee's Wail in the Port of Zandalar. Progress: Out with it, <class>.",rewardGold=23400,rewardXP=850,rewardItems={167228},starts={{npcID=150311}},ends={{npcID=135691}},mapCandidates={npc={70,862},zone={8567}},questType="standard",sourceQuests={54960},questLines={{id=873,name="Testing Loyalties",orderIndex=7,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=873,questLineOrder=21,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=873,questLineOrder=13}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=1165},
[55002] = {id=55002,name="Murder at the Brawlpub",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=2257,storyline={55002},series={55003,55004,55005,55006,55007},description="The Brawlpub quartermaster lies dead in front of you. He was murdered in broad daylight! He must have been assassinated while someone was fighting in the arena. Maybe even during one of your fights. Perhaps there are some clues nearby as to who might have killed him.",objectivesText="Investigate the scene of the crime.",rewardGold=309800,rewardXP=11765,rewardItems={92718,164931},starts={{npcID=68363}},ends={{npcID=68363}},mapCandidates={npc={},zone={2257}},questGiverID=68363,questTurnInID=68363,questType="standard"},
[55003] = {id=55003,name="Put Up Your Dukes",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=2257,storyline={55003},series={55002,55004,55005,55006,55007},description="You know what? <The commander puts his notebook away.> I COULD use a good <class> on my investigations team. We've had some personnel issues lately and, frankly, I can use all the help I can get. But first: why don't you go hop into the arena for a few fights so I can get a good look at your skills?",objectivesText="Win any 3 fights in Bizmo's Brawlpub.",rewardGold=309800,rewardXP=11765,starts={{npcID=150313}},ends={{npcID=150313}},mapCandidates={npc={},zone={2257}},questGiverID=150313,questTurnInID=150313,questType="standard",sourceQuests={55002}},
[55004] = {id=55004,name="Undercover Agent: Ann Dennyson",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=2257,storyline={55004},series={55002,55003,55005,55006,55007},description="Lord Winifred Browne is one of our primary suspects in this case. Browne is an infamously aggressive speculator, and has a list of debts a mile long. He may be in need of money, which is consistent with the evidence you found earlier. My associate Ann has taken point on the case. I'd like you to assist her. I think you'll work well together.",objectivesText="Report to Ann Dennyson in Bizmo's Brawlpub.",rewardGold=309800,rewardXP=11765,starts={{npcID=150313}},ends={{npcID=150313}},mapCandidates={npc={},zone={2257}},questGiverID=150313,questTurnInID=150313,questType="standard",sourceQuests={55003}},
[55005] = {id=55005,name="The Financial Participation Incentive",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=2257,storyline={55005},series={55002,55003,55004,55006,55007},description="I see Lord Browne running some sort of game over there. Getting people to guess the fight's winner in exchange for Brawler's Gold. See if you can figure out how his game works. If you win enough money from him, he might start talking...",objectivesText="Win 100 Brawler's Gold from Lord Winifred Browne 's guessing game. If the game is not currently active, anyone can activate it by purchasing a High Roller's Contract from Ulaani. Progress: Lookin' to make some gold, old chap?",rewardGold=309800,rewardXP=11765,rewardItems={143762},starts={{npcID=150314}},ends={{npcID=150314}},mapCandidates={npc={},zone={2257}},questGiverID=150314,questTurnInID=150314,questType="standard",sourceQuests={55004}},
[55006] = {id=55006,name="A Favor for Your Old Chum Winifred",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=2257,storyline={55006},series={55002,55003,55004,55005,55007},description="A moment of your time, <good sir/madam>. It's about all that money you won from me. Interestingly enough, that may have been slightly more money than I actually have, and now it would appear that some very powerful people want to break my elbows and my knees. I cannot pay them! I am quite broke! Ha ha! All I need to get back above water is for you to lose your next fight. Flop like a fish, as they say. Please.",objectivesText="Lose a fight in Bizmo's Brawlpub. Progress: You must help me! Their threats were quite descriptive, and slightly scatological!",rewardGold=341600,rewardXP=11765,starts={{npcID=68365}},ends={{npcID=68365}},mapCandidates={npc={},zone={2257}},questGiverID=68365,questTurnInID=68365,questType="standard",sourceQuests={55005}},
[55007] = {id=55007,name="Lord Browne's Debts",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=2257,storyline={55007},series={55002,55003,55004,55005,55006},description="I've always said that I'm not too proud to commit a few acts of violence to set a wrong right. And you know what's wrong? I'm out of money! Only one person's won more gold from me than you have, and his name's Lord Sylysthrel. Quite the scoundrel, that one. I believe he was cheating. It sure would be nice if I could get that gold back...",objectivesText="Obtain a Huge Pile of Legitimately-Earned Brawler's Gold from Lord Sylysthrel. You can challenge Lord Sylysthrel by purchasing his Challenge Card from Card Trader Leila. Progress: Once I get back the gold I lost, then I can REALLY start gambling!",rewardGold=309800,rewardXP=11765,rewardItems={164935,164941},starts={{npcID=68365}},ends={{npcID=68365}},mapCandidates={npc={},zone={2257}},questGiverID=68365,questTurnInID=68365,questType="standard",sourceQuests={55006}},
[55008] = {id=55008,name="Evidence Packet: Lord Winifred Browne",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=2257,storyline={55008},series={55009},description="I heard everything. That guy sure does talk loudly about his crimes and debts, doesn't he? It sounds like we have enough to bring him in for questioning. I've put together a packet of evidence for Commander Daalo to review. Good job out there.",objectivesText="Bring the Evidence Packet to Commander Daalo . Progress: Find anything on Browne?",rewardGold=309800,rewardXP=11765,rewardItems={167034},starts={{npcID=150314}},ends={{npcID=150314}},mapCandidates={npc={},zone={2257}},questGiverID=150314,questTurnInID=150314,questType="standard",sourceQuests={55007}},
[55009] = {id=55009,name="Undercover Agent: Saralara Fizzlesprang",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=2257,storyline={55009},series={55008},description="I believe you've met one of my other agents: Saralara Fizzlesprang . She's investigating our second suspect: Shadowmaster O'Flannerty. You'll find Saralara near the scene of the crime.",objectivesText="Speak with Saralara Fizzlesprang at Bizmo's Brawlpub.",rewardGold=309800,rewardXP=11765,starts={{npcID=150313}},ends={{npcID=150313}},mapCandidates={npc={},zone={2257}},questGiverID=150313,questTurnInID=150313,questType="standard",sourceQuests={55008}},
[55010] = {id=55010,name="Soul Splinters",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=2257,storyline={55010},series={55011},description="<O'Flannerty mumbles to himself.> Achh, what a mess... it's getting hungry again. Where am I going to find enough souls to feed it? Ohh... if only I could get my hands on some of those brawler's purses... <He notices you.> Oh! Ahoy there! Pay no attention to the mindless babbling of an innocent warlock. Nothing suspicious going on here!",objectivesText="Search inside Brawler's Purses for something \"soul\"-related. Brawler's Purses are awarded to victors in Bizmo's Brawlpub. Some types of purses may be more lucrative than others. Progress: Oh dear, oh dear... must not let it get too hungry...",rewardGold=309800,rewardXP=11765,rewardItems={92718,142289,142290,164928,164931},starts={{npcID=150317}},ends={{npcID=150317}},mapCandidates={npc={},zone={2257}},questGiverID=150317,questTurnInID=150317,questType="standard",sourceQuests={55009}},
[55011] = {id=55011,name="Super Soul Splinters",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=2257,storyline={55011},series={55010},description="<O'Flannerty mutters to himself again:> Will these be big enough, though? It gets SO hungry for souls, and when it doesn't get enough, it gets angry, and we definitely don't want to trigger a void apocalypse in the middle of Stormwind. Oh dear, oh dear... <He notices you lingering.> Oh! The <race> is still here! Heh heh. Never mind me! Nothing evil going on here!!",objectivesText="Obtain 3 Super Soul Splinters from Rumbler's Purses, which are rewarded from winning rumbles. Rumbles are large group fights that pit all players in Bizmo's Brawlpub queue against a challenging enemy. Anyone can start a rumble by purchasing a Rumble Card from Ulaani. Progress: <O'Flannerty looks around the arena in a panic.> Where can I find more souls? Maybe the quartermaster sells some? Oh, right, he's dead. Hmm...",rewardGold=309800,rewardXP=11765,rewardItems={164929,164931},starts={{npcID=150317}},ends={{npcID=150317}},mapCandidates={npc={},zone={2257}},questGiverID=150317,questTurnInID=150317,questType="standard",sourceQuests={55010}},
[55012] = {id=55012,name="Cause for Concern",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=2257,mapID=500,storyline={55012},series={55013,55014,55015,55016},description="Shadowmaster O'Flannerty's behavior was unusual. His repeated mutterings about \"shadow magic\" and \"void apocalypses\" and \"ancient creatures hungering for the souls of the living\" certainly warrant further investigation. You should report back to Saralara Fizzlesprang .",objectivesText="Report to Saralara Fizzlesprang .",rewardGold=30900,rewardXP=1470,mapCandidates={npc={},zone={2257}},questType="standard",sourceQuests={55011}},
[55013] = {id=55013,name="The Precious 13-Tooth Gogglegear",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=2257,storyline={55013},series={55012,55014,55015,55016},description="We're going to have to invent something. Something capable of seeing into alternate dimensions. Something explosive that you strap directly onto your eyes. That's right, I'm talking about goggles. I already have all the goggle parts except for one: a 13-tooth gear. They're nearly impossible to find, but I KNOW that the G.G. Engineering boys have one, and Card Trader Leila has their challenge card.",objectivesText="Obtain a 13-Tooth Gogglegear from G.G. Engineering. You can purchase their challenge card from Card Trader Leila. Progress: Are you ready to goggle up?",rewardGold=309800,rewardXP=11765,rewardItems={94178,164937},starts={{npcID=150315}},ends={{npcID=150315}},mapCandidates={npc={},zone={2257}},questGiverID=150315,questTurnInID=150315,questType="standard",sourceQuests={55012}},
[55014] = {id=55014,name="The Fizzlesprang Goggle Experiment",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=2257,storyline={55014},series={55012,55013,55015,55016},description="Okay, before we start, I've got a few rules: First, these goggles will only work at close range. We're looking for something INSIDE the arena, so you'll have to be inside the arena to use them. Second rule: if you feel something starting to explode, try to blink real hard. Lastly, remember, we're looking for an evil shadow monster. You don't need to kill it, we just need you to see it so we can report it as evidence. Alright, go get in that arena and try them out!",objectivesText="Put on Saralara's Goggles while fighting in Bizmo's Brawlpub and look for evidence against Shadowmaster O'Flannerty.",rewardGold=309800,rewardXP=11765,rewardItems={167033},starts={{npcID=150315}},ends={{npcID=150315}},mapCandidates={npc={},zone={2257}},questGiverID=150315,questTurnInID=150315,questType="standard",sourceQuests={55013}},
[55015] = {id=55015,name="Evidence Packet: Shadowmaster O'Flannerty",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=2257,storyline={55015},series={55012,55013,55014,55016},description="Sounds like we've found our perp, <name>. This guy's sketchy, desperate, and his shadow magic is consistent with that shadowy scroll you found earlier. Bring this packet to Daalo, and we can bring him in. Good work out there!",objectivesText="Bring the Evidence Packet to Commander Daalo . Progress: Any news on O'Flannerty?",rewardGold=309800,rewardXP=11765,rewardItems={167035},starts={{npcID=150315}},ends={{npcID=150315}},mapCandidates={npc={},zone={2257}},questGiverID=150315,questTurnInID=150315,questType="standard",sourceQuests={55014}},
[55016] = {id=55016,name="Undercover Agent: Silent Jussho",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=2257,storyline={55016},series={55012,55013,55014,55015},description="I've got one more suspect I'm investigating: Grant Lazarby. He's a wealthy worgen death knight socialite who spends most of his time spectating the arena from the VIP area. I've got my best agent on the case: Silent Jussho . Check in with him to see how his report is coming along.",objectivesText="Report to Silent Jussho in the Brawlpub VIP Lounge. To enter the VIP Lounge, you must either be Rank 6 in Bizmo's Brawlpub, or someone must purchase a VIP Room Rental Form from Ulaani.",rewardGold=309800,rewardXP=11765,starts={{npcID=150313}},ends={{npcID=150313}},mapCandidates={npc={},zone={2257}},questGiverID=150313,questTurnInID=150313,questType="standard",sourceQuests={55015}},
[55017] = {id=55017,name="Flaunt It If You Got It",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=2257,storyline={55017},series={55018},description="Sigh... so dull... Oh, it's you! <name>, was it? I've seen a few of your fights. They're slightly less tedious than the standard humdrum bloodsport this arena has been producing lately. Let's spice things up a bit. Maybe buy some expensive drinks for ourselves? Buy a round of the cheap stuff for the riffraff below? Maybe even toss a few amberseed buns at the combatants?",objectivesText="Drink a bottle of Moneybrau, purchase a round of drinks at the bar in Bizmo's Brawlpub, and hit a fighting player with an Amberseed Bun while standing in the VIP Lounge.",rewardGold=309800,rewardXP=11765,rewardItems={98117,98121,143758},starts={{npcID=70722}},ends={{npcID=70722}},mapCandidates={npc={},zone={2257}},questGiverID=70722,questTurnInID=70722,questType="standard",sourceQuests={55016}},
[55018] = {id=55018,name="Simply Dying of Boredom",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=2257,storyline={55018},series={55017},description="Up until now, I've been dying of boredom up here. I think maybe we need some new blood here in the arena. Bizmo can be so stingy with his invitations, can't he? I've had one of my servants write up a few slightly-counterfeit invitations to hand out. Maybe you could help me get them distributed? There's always plenty of tough-looking characters hanging out in front of the auction house in the Trade District...",objectivesText="Use the Bizmo's Brawlpub Sign in Stormwind's Trade District.",rewardGold=309800,rewardXP=11765,rewardItems={167038},starts={{npcID=70722}},ends={{npcID=70722}},mapCandidates={npc={},zone={2257}},questGiverID=70722,questTurnInID=70722,questType="standard",sourceQuests={55017}},
[55019] = {id=55019,name="Evidence Packet: Grant Lazarby",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=2257,storyline={55019},series={55020,55021,55022},description="Good work. I never expected Lazarby to be so... self-incriminating. You may bring the packet to Commander. I'm going to go buy some expensive snacks at the VIP bar.",objectivesText="Bring the Evidence Packet to Commander Daalo . Provided item:",rewardGold=309800,rewardXP=11765,rewardItems={167036},starts={{npcID=150316}},ends={{npcID=150316}},mapCandidates={npc={},zone={2257}},questGiverID=150316,questTurnInID=150316,questType="standard",sourceQuests={55018}},
[55020] = {id=55020,name="The Brawlpub Trial",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=2257,storyline={55020},series={55019,55021,55022},description="I've issued three warrants. Jussho, Saralara, and Anne are apprehending the suspects as we speak. It's time to go to court. You may be called on to testify. Just answer as honestly as you can, and let the wheels of justice do the rest.",objectivesText="Reach a verdict in the Brawlpub Trial.",rewardGold=309800,rewardXP=11765,starts={{npcID=150313}},ends={{npcID=150313}},mapCandidates={npc={},zone={2257}},questGiverID=150313,questTurnInID=150313,questType="standard",sourceQuests={55019}},
[55021] = {id=55021,name="A Clue from Area 52",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=2257,mapID=109,storyline={55021},series={55019,55020,55022},description="We've received a letter from Area 52, the goblin outpost in Netherstorm. The author claims to know details about what they call \"the situation in the Brawlpub\". They don't say more than that. I'm tied to my paperwork here. Go check out this lead and see if anything turns up.",objectivesText="Investigate Area 52 in Netherstorm for a sign of the letter's writer.",rewardGold=309800,rewardXP=11765,rewardItems={162973},starts={{npcID=150313}},ends={{npcID=150320}},mapCandidates={npc={109},zone={2257}},questGiverID=150313,questType="standard",sourceQuests={55020}},
[55022] = {id=55022,name="Solving the Mystery",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=3523,mapID=109,storyline={55022},series={55019,55020,55021},description="< Bizmo produces a challenge card from his pocket.> I grabbed this challenge card from my attackers while we were fighting each other! I'm sure that you can use it to challenge my attacker to some sort of ultimate showdown!",objectivesText="Bring the Mysterious Challenge Card to Bizmo 's Brawlpub to confront Bizmo 's captor.",rewardGold=1239200,rewardXP=23530,rewardItems={164936,166724},rewardChoices={166724},starts={{npcID=150320}},ends={{npcID=150320}},mapCandidates={npc={109},zone={3523}},questTurnInID=150320,questType="standard",sourceQuests={55021}},
[55023] = {id=55023,name="Bizmo's Brawlpub Awaits!",level=80,requiredLevel=80,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=2257,mapID=500,storyline={55023},description="Tired of standing around in the boring old Trade District? Come on over to Bizmo's Brawlpub, and fight for the amusement of others! You might win, or you might get killed, but either way, you're going to have a great time. Grab an invitation and bring it to Han Heavypaw , near the front door. The Brawlpub awaits!",objectivesText="Bring an invitation to Bizmo's Brawlpub. Provided item:",rewardGold=309800,rewardXP=11765,rewardItems={164949},mapCandidates={npc={},zone={2257}},questType="standard"},
[55028] = {id=55028,name="It's Scrap Work...",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"engineering"},categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={53802,53806,53848,53947,53948,53949,54930,55028},description="<name>, I'm glad you stopped by. The Ub3r-Spanner, capable of crafting powerful constructs, and its schematic have been lost for years. Intel tells us that its schematic is located in a locked cache in The Abandoned Junkheap. You'll need to overcharge its electric barrier to gain access. Take my Current Culler and soak up some of the latent current from the sentries there and zap that chest open! <Layla makes finger guns and explosion sounds> Up for some treasure huntin'?",objectivesText="Use the Coiled Current Culler on dead V-300 SENTRIES at the Abandoned Junkheap, then use it to collect the Ub3r-Spanner schematic from the Reinforced Schematic Cache. Progress: Did you find the schematic?",rewardGold=234000,rewardXP=6815,rewardItems={164740,167037,167041,168152},starts={{npcID=136059}},ends={{npcID=136059}},mapCandidates={npc={},zone={8568}},questGiverID=136059,questTurnInID=136059,questType="standard",questLines={{id=869,name="Tools of the Trade: The Ub3r-Spanner",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[55030] = {id=55030,name="Blueprint: Scrap Trap",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={55030},description="<This blueprint details how to build what appears to be some sort of land mine using little more than scrap metal. You should be able to upload the blueprint to Pascal-K1N6 's database in Rustbolt.>",objectivesText="Upload the blueprint to Pascal-K1N6 's database. Provided item:",rewardGold=257400,rewardItems={167042},starts={{npcID=149847,mapID=1462,x=0.8245,y=0.2093}},ends={{npcID=150359}},coords={mapID=1462,source="quest_giver",x=0.714,y=0.325},mapCandidates={npc={1462},zone={10290}},questType="standard",startItems={167042}},
[55031] = {id=55031,name="It's Scrap Work...",level=50,requiredLevel=50,faction="horde",requiredProfessions={"engineering"},categories={},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={53783,53802,53806,53833,53848,53937,54930,55031},description="<name>, I'm glad you stopped by. The Ub3r-Spanner, capable of crafting powerful constructs, and its schematic have been lost for years. Intel tells us that its schematic is located in a locked cache in The Abandoned Junkheap. You'll need to overcharge its electric barrier to gain access. Take my Current Culler and soak up some of the latent current from the sentries there and zap that chest open! <Shuga makes finger guns and explosion sounds> Up for some treasure huntin'?",objectivesText="Use the Coiled Current Culler on dead V-300 SENTRIES at the Abandoned Junkheap, then use it to collect the Ub3r-Spanner schematic from the Reinforced Schematic Cache. Progress: Did you find the schematic?",rewardGold=234000,rewardXP=6815,rewardItems={164740,167037,167041},starts={{npcID=131840}},ends={{npcID=131840}},mapCandidates={npc={1165},zone={8670}},questType="standard",questLines={{id=868,name="Tools of the Trade: The Ub3r-Spanner",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[55032] = {id=55032,name="Unchained Resistance",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={55032},description="The naga have enslaved a tribe of makrura and sent them to labor as mindless thralls. The naga forces may be more in number, but the makrura have an innate advantage in both size and strength. If we break the makrura from their chains, they will surely overwhelm their naga overseers and put a dent in Queen Azshara's plans.",objectivesText="Free 6 Makrura Slaves. Progress: The makrura will make short work of their former masters.",rewardGold=234000,rewardItems={167070},rewardCurrencies={{id=1721,amount=3},{id=1749,amount=100},{id=1721,amount=2}},starts={{npcID=150553}},ends={{npcID=150553}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56156},worldTaskTitle="Unchained Resistance",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55033] = {id=55033,name="Ashes to Ashvane",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={55033,55044,55045,55116,55117,55118,55119},description="This place is just crawling with Ashvane loyalists, <name>. How about we do the Kul Tirans a favor and get rid of some of them. <Kelsey grins.> I got a head start on the way here, but there's plenty to go around!",objectivesText="Slay Ashvane Loyalists in Freehold.",rewardGold=468000,rewardXP=8520,starts={{npcID=150796}},ends={{npcID=150796}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={55118},questLines={{id=921,name="My Brother's Keeper",orderIndex=1,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=921,questLineOrder=19,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=921,questLineOrder=12}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[55034] = {id=55034,name="Under False Colors",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=70,storyline={54958,54959,54960,54961,54997,54999,55034,55124},description="If we wish to stay the executioner's axe, we'll need to throw Sylvanas off of our scent. You'll need to have your men take the ship to Chandlery Wharf, where they can disguise it as a pirate's bounty. Your task will be to ensure that Sylvanas' forces find the ship there. You must report to Nathanos that you spotted a stolen Forsaken vessel in that area. You have no connection to Derek Proudmoore, so it should raise no suspicions.",objectivesText="Start the mission \"Casting the Bait\" then report to Nathanos Blightcaller aboard the Banshee's Wail in the Port of Zandalar.",rewardGold=23400,rewardXP=850,rewardItems={167228},starts={{npcID=150311}},ends={{npcID=135691}},mapCandidates={npc={70,862},zone={8567}},questType="standard",sourceQuests={54960,54961},questLines={{id=873,name="Testing Loyalties",orderIndex=6,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=873,questLineOrder=21,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=873,questLineOrder=13}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1642,db2PoiUiMapID=1165},
[55036] = {id=55036,name="A Terrible Place",level=50,requiredLevel=50,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=10348,storyline={55036},description="You may have noticed all the disturbances happening around Azeroth. The Old God is rising, and its bad news for all of us. On occasion, one of these Pillars of Endless Truth will appear. Wonderful name don't you think? I have a knack for naming things. Where was I? Oh yes, right, these Pillars grant one access to the very mind of the Old God himself. They will show you a hint of what might yet come, what this world will look like should we fail to defeat him. Are you willing to see for yourself? See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(55036)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(55036))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Complete a Vision of N'Zoth.",mapCandidates={npc={},zone={10348}},questType="standard"},
[55039] = {id=55039,name="The Master Shipwright",level=40,requiredLevel=40,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=942,storyline={53720,54706,54708,54721,54723,54725,54726,54727,54728,54729,54730,54731,54732,54733,54734,54735,54851,55039,55043,55136},series={54706,54708,54721,55043},description="Now I am starting to remember... Dorian Atwater was a very secretive builder. Their slips were famously warded against prying eyes until the vessel was complete. It made something of a stir any time one of their works was revealed. Last I heard, they retired in Stormsong Valley. I am not certain how reliable that information is. Hm. We should head to Brennadam. It is a crossroads of sorts. If anyone knows where to find our shipwright, they will be there.",objectivesText="Acquire the Letter from the Lord Admiral and meet Cyrus Crestfall in Brennadam. Progress: You've got that letter? I have a feeling we'll be needing it before long.",rewardGold=170800,rewardXP=2735,rewardItems={164762,166462},starts={{npcID=122370}},ends={{npcID=150515}},mapCandidates={npc={942},zone={8568}},questGiverID=122370,questType="standard",sourceQuests={54706},questLines={{id=916,name="Allies of the Alliance: Kul Tiran",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[55040] = {id=55040,name="Looking Inside",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={54087,54088,54945,54946,54947,54992,55040,55096,55609,55645,55729,55730,55731,55734,55736,55995,56131},description="This vault screams of ancient gnomish tech! I believe this could be the key that leads us to King Mechagon! I can't risk putting myself in danger though, so you will lead the way into the vault. Well, what are we waiting for? Let's see what's inside!",objectivesText="Enter the vault.",rewardGold=257400,rewardXP=1415,starts={{npcID=149864}},ends={{npcID=149877}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={54088},questLines={{id=940,name="Expedition to Mechagon",orderIndex=1,flags=0},{id=5376,name="Welcome to Mechagon",orderIndex=3,flags=0},{id=6060,name="Mechagon Intro",orderIndex=6,flags=0}},campaigns={{id=218,title="Mechagon",questLineID=5376,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6060,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[55043] = {id=55043,name="Fish Tales and Distant Sails",level=40,requiredLevel=40,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={53720,54706,54708,54721,54723,54725,54726,54727,54728,54729,54730,54731,54732,54733,54734,54735,54851,55039,55043,55136},series={54706,54708,54721,55039},description="I have an idea where to start, but it couldn't hurt to ask the locals. I hope it goes without saying that you shouldn't believe everything you hear, <name>. My people are very fond of embellishing the truth. I will meet you in The Golden Flagon when you've had a chance to ask around .",objectivesText="Ask for information about the shipwright in Brennadam. Progress: Did you learn anything useful?",rewardGold=169800,rewardXP=5465,rewardItems={164762},starts={{npcID=150515}},ends={{npcID=150515}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={55039},questLines={{id=916,name="Allies of the Alliance: Kul Tiran",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[55044] = {id=55044,name="Don't Shoot the Messenger",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={55033,55044,55045,55116,55117,55118,55119},description="While he was the gladiator known as Lo'Gosh, King Varian fought beside Valeera Sanguinar . He trusted her and that allowed SI:7 to have a... cordial relationship with her. Valeera's loyalty has carried on to King Anduin. During the fight with the Legion, I came to know her as a capable if... independent operative. She can go where even some of my agents cannot. We should listen to whatever message she brings. I imagine the source will be interesting.",objectivesText="Listen to Valeera's message. Progress: This is... surprising news.",rewardGold=117000,rewardXP=3410,starts={{npcID=135614}},ends={{npcID=150574}},mapCandidates={npc={70,1161},zone={8568}},questType="standard",sourceQuests={55119},questLines={{id=921,name="My Brother's Keeper",orderIndex=5,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=921,questLineOrder=19,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=921,questLineOrder=12}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=1161},
[55045] = {id=55045,name="My Brother's Keeper",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=70,storyline={55033,55044,55045,55116,55117,55118,55119},description="While I trust Valeera believes she is not leading us into a trap, I do not trust this isn't a Horde manipulation. <name>, I want you to come with me. I will meet with Baine, but I will not do so alone.",objectivesText="Sail with Jaina to meet Baine off the coast of Theramore. Progress: This is... surprising news.",rewardGold=117000,rewardXP=3410,rewardItems={245271,252386,252400,252403,252406,252653,252654,252754},rewardCurrencies={{id=1553,amount=750},{id=1560,amount=20}},starts={{npcID=150574}},ends={{npcID=135612}},mapCandidates={npc={70,1161},zone={8568}},questType="standard",sourceQuests={55044},questLines={{id=921,name="My Brother's Keeper",orderIndex=6,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=921,questLineOrder=19,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=921,questLineOrder=12}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[55047] = {id=55047,name="Securing Warfang Hold",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={55047,55048,55049,55050,55051,55052},description="The Dark Lady has important work for you, <name>. Preparations are beginning for a meeting of the Horde's leadership at Warfang Hold. I trust I don't need to emphasize that security is of the highest import for this gathering. The goblin, Gallywix, has sent his underlings to make sure the area is swept of any... unwanted guests. I need you to make sure they succeed in their task.",objectivesText="Meet with Boss Mida at Warfang Hold in Stormsong Valley.",rewardGold=23400,rewardXP=850,starts={{npcID=146013}},ends={{npcID=150690}},mapCandidates={npc={862,942},zone={8499}},questType="standard",sourceQuests={54999},questLines={{id=881,name="Dark Consequences",orderIndex=0,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=881,questLineOrder=22,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=881,questLineOrder=14}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
[55048] = {id=55048,name="Spy Games",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={55047,55048,55049,55050,55051,55052},description="The Alliance must've got wind of this meeting and they've sent SI:7 spies to try to listen in. The problem is, they're using some kind of gnomish tech to sneak past our detectors. One of our techs was able to put together something that should be able to neutralize whatever they're using, but the range is short. I'll need you to take it out into the field and look for evidence of SI:7 activity. Just mash the button on that thing when you think they're close, and it should zap 'em back into view.",objectivesText="Use the Electronic Mayhem Projector to reveal and kill 10 SI:7 spies in the Clearcut.",rewardGold=234000,rewardXP=6815,rewardItems={167078},starts={{npcID=150690}},ends={{npcID=150690}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={55047,55052},questLines={{id=881,name="Dark Consequences",orderIndex=2,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=881,questLineOrder=22,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=881,questLineOrder=14}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
[55049] = {id=55049,name="Communication Breakdown",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={55047,55048,55049,55050,55051,55052},description="It looks like the stealth generators aren't the only tech that SI:7 is bringing into the field. Our scouts have reported what look like listening devices set up at key points around Warfang. Obviously, these things have to go, but the goons haven't been able to get close to them on account of the hidden spies. While you're out there, make sure to trash 'em.",objectivesText="Destroy 3 SI:7 Listening Devices near Warfang Hold.",rewardGold=234000,rewardXP=6815,starts={{npcID=150690}},ends={{npcID=150690}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={55047,55052},questLines={{id=881,name="Dark Consequences",orderIndex=3,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=881,questLineOrder=22,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=881,questLineOrder=14}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
[55050] = {id=55050,name="Tickets, Please?",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={55047,55048,55049,55050,55051,55052},description="There's another problem we could use your help with, <class>. Gallywix knew this meeting was going to be a big deal, so naturally he decided to sell tickets. The thing is, I've done a headcount here, and we've got a lot more people here than tickets sold, so some of these spectators are trying to pull a fast one. Most of our muscle is out in the Clearcut getting killed by spies, so we could use the help. Care to make an honest wage?",objectivesText="Eject 5 ticketless Visiting Spectators from Warfang Hold. Progress: The nerve of these people!",rewardGold=117000,rewardXP=3410,rewardItems={167096},starts={{npcID=150691}},ends={{npcID=150691}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={55047,55052},questLines={{id=881,name="Dark Consequences",orderIndex=4,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=881,questLineOrder=22,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=881,questLineOrder=14}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
[55051] = {id=55051,name="A Display of Power",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={55047,55048,55049,55050,55051,55052},description="It looks like all the big players are here. This thing's gonna be starting any moment now. You'll probably want to get a good seat.",objectivesText="Speak to Nathanos Blightcaller to witness the meeting of leaders in Warfang Hold.",rewardGold=23400,rewardXP=850,rewardCurrencies={{id=1553,amount=750}},starts={{npcID=150690}},ends={{npcID=150678}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={55048,55049,55050},questLines={{id=881,name="Dark Consequences",orderIndex=5,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=881,questLineOrder=22,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=881,questLineOrder=14}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
[55052] = {id=55052,name="Securing Warfang Hold",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={55047,55048,55049,55050,55051,55052},description="<name>, the Dark Lady has need of your services once more. The traitor, Baine, is being brought before the leaders of the Horde at Warfang Hold. Preparations are underway as we speak to secure the area. The efforts are headed up by Gallywix's minions, who I wouldn't trust to secure a kennel. You will need to go to Warfang Hold and make sure the area is locked down. We are counting on you, <name>.",objectivesText="Meet with Boss Mida at Warfang Hold in Stormsong Valley.",rewardGold=23400,rewardXP=850,starts={{npcID=135691}},ends={{npcID=150690}},mapCandidates={npc={862,942},zone={8499}},questType="standard",sourceQuests={55034},questLines={{id=881,name="Dark Consequences",orderIndex=1,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=881,questLineOrder=22,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=881,questLineOrder=14}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
[55053] = {id=55053,name="A Way Home",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={54012,54015,54018,54021,55053,55054,55092,55094,55481,56063,56429},description="We can harness the power within this place to open a portal home. I will require your assistance. Isn't this fun? You get to be my assistant! Ah, yes. Just come with me and all you have to do is wave that Heart of Azeroth of yours around. I'll handle the rest.",objectivesText="Help Oculeth open a portal to Zuldazar.",rewardGold=154900,rewardXP=3410,rewardItems={66898,66899,66900,69217,69223,131709,170514,170515,170516,170517,170518,170519,170520,170521,170522,170523,170524,170525,170526,170527,170528,170529,170530,170531,170532,170533,170534,170535,170536,170537},rewardChoices={170516,170517,170518,170529,170530,170531,170532,170533,170534,170535,170536,170537},starts={{npcID=151851}},ends={{npcID=151851}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55094},questLines={{id=886,name="Azshara's Trap",orderIndex=9,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=10,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=886,questLineOrder=23,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1718,db2PoiUiMapID=1355},
[55054] = {id=55054,name="Upheaval",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={54012,54015,54018,54021,55053,55054,55092,55094,55481,56063,56429},description="We're surrounded by the dead, dying, and other detritus. Feels like war, does it not? Oculeth and others have gone ahead to see to the soldiers. Perhaps you ought to see to them as well?",objectivesText="Speak with Chief Telemancer Oculeth at the top of the waterfall.",rewardGold=30900,rewardXP=850,starts={{npcID=150187}},ends={{npcID=150206}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56044},questLines={{id=886,name="Azshara's Trap",orderIndex=0,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=1,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=886,questLineOrder=23,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1718,db2PoiUiMapID=1355},
[55055] = {id=55055,name="Build A Bigger Fish Trap",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={55055,55298,55339,56305},description="With those minnows and some spare parts, you should be able to build a Hundred-Fathom Lure . Visit Pascal-K1N6 in Rustbolt and build one. Then come back here, and we'll catch a huge fish!",objectivesText="Build the Hundred-Fathom lure . Progress: Get to it, we have a fish to catch!",rewardGold=257400,rewardXP=1415,rewardItems={166846,167649,169610},starts={{npcID=151462}},ends={{npcID=151462}},mapCandidates={npc={1462},zone={10290}},questType="standard",sourceQuests={55339},questLines={{id=924,name="Mechagon Fishing",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1462,startItems={167652}},
