[55087] = {id=55087,name="The Gathering Storm",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={55087,55088,55089,55090,55171,55179,55182,55183,55185},description="While I deal with the naga incursions, Lady Proudmoore is going to take on handling the Horde in Stormsong Valley and figuring out what happened to our spies there. You'll find her near Proudmoore Keep.",objectivesText="Report to Jaina Proudmoore near Proudmoore Keep in Boralus.",rewardGold=23400,rewardXP=850,rewardItems={21398,21399,21400},starts={{npcID=135612}},ends={{npcID=150633}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={55171},questLines={{id=922,name="The Gathering Storm",orderIndex=1,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=922,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=922,questLineOrder=13}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=1161},
[55088] = {id=55088,name="Lost in the Field",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={55087,55088,55089,55090,55171,55179,55182,55183,55185},description="When Shaw and I got here we discovered most of our operatives were dead. Most, but not all. Go into the field and get any of our operatives out of there. They might have more intel on what the Horde are planning here in Warfang Hold.",objectivesText="Assist injured spies in Stormsong Valley.",rewardGold=234000,rewardXP=6815,starts={{npcID=150637}},ends={{npcID=150637}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={55179},questLines={{id=922,name="The Gathering Storm",orderIndex=3,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=922,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=922,questLineOrder=13}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
[55089] = {id=55089,name="Shaw's Shank Redemption",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={55087,55088,55089,55090,55171,55179,55182,55183,55185},description="Hmm. Shaw said he'd check in when we got communications back but he hasn't. He's probably run into the same trouble the rest of our spies did. I'll stay here and guard the listening post. You find Shaw. He was headed for the cliff above Warfang Hold near the top of the waterfall. The peons called that area \"The Screaming Pit\" for some reason. I bet it's a real pleasant place. Stab whatever he's fighting for me, okay?",objectivesText="Find Mathias Shaw in The Screaming Pit above Warfang Hold. Progress: Just in time, <name>.",rewardGold=468000,rewardXP=8520,starts={{npcID=150637}},ends={{npcID=150640}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={55185},questLines={{id=922,name="The Gathering Storm",orderIndex=7,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=922,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=922,questLineOrder=13}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
[55090] = {id=55090,name="A Gathering of Foes",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={55087,55088,55089,55090,55171,55179,55182,55183,55185},description="Before I was distracted, I was able to find out more about this Horde gathering. Sylvanas has summoned the leaders of the Horde and its allies. For what purpose, I cannot say. We aren't in a position to strike her down--she is too well-protected. But perhaps we can learn something that will prove useful in the ongoing war. Keep your head low and take a look. I'll keep an eye out for more guards.",objectivesText="Witness the Horde gathering.",rewardGold=117000,rewardXP=3410,rewardCurrencies={{id=1553,amount=750}},starts={{npcID=150640}},ends={{npcID=150633}},mapCandidates={npc={942,1161},zone={9042}},questType="standard",sourceQuests={55089},questLines={{id=922,name="The Gathering Storm",orderIndex=8,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=922,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=922,questLineOrder=13}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=1161},
[55092] = {id=55092,name="Disruption of Power",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={54012,54015,54018,54021,55053,55054,55092,55094,55481,56063,56429},description="The naga tap into the power within nearby ley lines and have found a way to harness it. Destroy their devices before they can put that power to use against us.",objectivesText="Destroy 5 Ley Line Accumulators in Spears of Azshara.",rewardGold=234000,rewardXP=6815,starts={{npcID=150196}},ends={{npcID=150196}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={54021,54969},questLines={{id=886,name="Azshara's Trap",orderIndex=5,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=5,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=886,questLineOrder=23,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1718,db2PoiUiMapID=1355},
[55094] = {id=55094,name="Stay Low, Stay Fast!",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={54012,54015,54018,54021,55053,55054,55092,55094,55481,56063,56429},description="It's a straight shot home. We just need to be careful. Neri's rule of survival number six: always be prepared! Let's go!",objectivesText="Follow Neri Sharpfin .",rewardGold=234000,rewardXP=6815,starts={{npcID=150209}},ends={{npcID=151849}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56429},questLines={{id=886,name="Azshara's Trap",orderIndex=8,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=9,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=886,questLineOrder=23,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1718,db2PoiUiMapID=1355},
[55095] = {id=55095,name="Upheaval",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={54969,54972,55095,55175,56350,56640,56641,56642,56643,56644},description="So many lives lost... And the attacks from the naga are relentless! I apologize, $p. This attitude is unbecoming of a king. We have no time to lose musing of our own plight. Let us meet with Jaina and descend from this perilous place into the unknown.",objectivesText="Speak with Lady Jaina Proudmoore above the waterfall.",rewardGold=30900,rewardXP=850,starts={{npcID=150087}},ends={{npcID=150101}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56043},questLines={{id=949,name="Welcome to Nazjatar",orderIndex=0,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=1,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=949,questLineOrder=21,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1718,db2PoiUiMapID=1355},
[55096] = {id=55096,name="Send My Father a Message",level=10,requiredLevel=10,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={54087,54088,54945,54946,54947,54992,55040,55096,55609,55645,55729,55730,55731,55734,55736,55995,56131},description="My people are once again safe... for now. King Mechagon won't stop sending his armies at us as long as he does not fear us. We must send him a message. Climb to the top of the ramparts, and hack one of my father's projectors to proudly shine the banner of the Rustbolt Resistance big enough for the whole island to see. I'm sure that'll attract the attention of my father, King Mechagon .",objectivesText="Hack a projector to display the Rustbolt Resistance emblem and defend it.",rewardGold=772200,rewardXP=2125,starts={{npcID=153670}},ends={{npcID=151947}},mapCandidates={npc={1462},zone={10290}},questGiverID=153670,questType="standard",sourceQuests={55730,55731,55734},questLines={{id=940,name="Expedition to Mechagon",orderIndex=13,flags=0},{id=941,name="Expedition to Mechagon",orderIndex=15,flags=0},{id=5376,name="Welcome to Mechagon",orderIndex=15,flags=0},{id=5384,name="Welcome to Mechagon",orderIndex=16,flags=0},{id=6062,name="Mechagon Intro - On Island",orderIndex=0,flags=0}},campaigns={{id=218,title="Mechagon",questLineID=5376,questLineOrder=0},{id=222,title="Mechagon",questLineID=5384,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6062,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55099] = {id=55099,name="TBD NOT USED",level=10,requiredLevel=10,faction="none",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55099},description="The fabled workbench of Rustbolt - MY workbench - has fallen into disrepair! This tragedy was no doubt caused by the same ruffians and miscreants who kidnapped me and Princess Wiggles. The VERY same ruffians and miscreants, in fact, who still show their faces in this very town on the regular. Their presence here is a veritable slap to our collective faces! Dispatch the snatchers quickly and recover my binder of blueprints. We may then commence crafting what we shall need to repair this.",objectivesText="Collect the Junkyard Blueprint Book from Scrapthief Grillin.",rewardGold=257400,rewardXP=1415,rewardItems={167093},mapCandidates={npc={},zone={10290}},questType="standard"},
[55101] = {id=55101,name="Junkyard Tinkering and You",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55101,55103,56181},description="Behold, the fabled Pascal Workshop of Rustbolt -- MY workshop! Countless inventions have sprung forth into existence on this very spot, including my very finest invention, Pascal -K1N6! Pascal -K1N6 can craft anything... as long as you have the blueprints for it. And since I have you to thank for the K1N6's safe return to Rustbolt, would you like to learn how to access his blueprints database?",objectivesText="Use Pascal -K1N6 to craft a Scrap Grenade. Progress: Remember, you can collect Spare Parts from almost anything on Mechagon .",rewardGold=2000,rewardXP=1415,rewardItems={166846,167846},starts={{npcID=152295}},ends={{npcID=152295}},mapCandidates={npc={1462},zone={10290}},questType="standard",sourceQuests={55736},questLines={{id=954,name="Junkyard Tinkering",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55103] = {id=55103,name="Ideas Can Come from Anywhere",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55101,55103,56181},description="I didn't notice the tinkerer's spark in you when we first met. But look at all of the blueprints you've recovered and uploaded to Pascal -K1N6's database. I was wrong. And happily so, my budding junkyard tinkering apprentice! But this is a dangerous moment in your creative development. You must avoid complacency! Take time off to find new ideas. Speak with builders that inspire you, reverse-engineer bots on the island, and be open to new ideas - no matter where they come from!",objectivesText="Find people and things to inspire 1 new ideas in Mechagon .",rewardGold=257400,rewardXP=1415,rewardItems={166972,166973,168057,168222,168496,168497,168821,168843,168907,169224,169225,169226,169227,169228,169229,169230,169231,169232,169233,169235,169236,169237,169238,169239,169240,169246,169247,169248,169249,169250,169251,169252,169253,169255,169257,169383,169384,169649,169874,170541,170542},starts={{npcID=152295}},ends={{npcID=152295}},mapCandidates={npc={1462},zone={10290}},questType="standard",questLines={{id=954,name="Junkyard Tinkering",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55111] = {id=55111,name="Creature Study: Zanj'ir Naga",level=50,requiredLevel=50,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={55111},description="<Scrawled upon the magical scroll are Maedin's incomplete notes on the Zanj'ir naga.>",objectivesText="Use Maedin's Scroll to collect data from various creatures within Nazjatar .",rewardGold=468000,rewardXP=8520,rewardItems={167091,169444},rewardCurrencies={{id=1721,amount=5}},mapCandidates={npc={},zone={10052}},questType="standard",startItems={167090}},
[55116] = {id=55116,name="Getting a Clue",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={55033,55044,55045,55116,55117,55118,55119},description="I'm betting that one page of jibberish is a coded message. We can send it back to Stormwind to be cracked by our codebreakers or we could break some heads and find the cipher here. I'm thinking we'll just save some time and do that. The guy in charge here probably has what we're looking for. Why don't you take him out and see if you can't find it. Even if you don't, without a leader the loyalists won't be much trouble. It's a win-win! Well, for us I guess.",objectivesText="Slay Haughton Francis and recover his cipher. Progress: Did you find a cipher? Or some kind of decoding gadget?",rewardGold=468000,rewardXP=8520,rewardItems={167155},starts={{npcID=150796}},ends={{npcID=150796}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={55033,55117},questLines={{id=921,name="My Brother's Keeper",orderIndex=3,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=921,questLineOrder=19,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=921,questLineOrder=12}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[55117] = {id=55117,name="Correspondence Conundrum",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={55033,55044,55045,55116,55117,55118,55119},description="I think Ashvane has been in contact with her loyalists, but I don't know what their orders are. Go into their camp and see if you can't read their mail. We might find something that leads back to where Lady Ashvane is hiding or what their next move is going to be.",objectivesText="Discover information about Lady Ashvane's plans.",rewardGold=468000,rewardXP=8520,rewardItems={167065,167149,167151,167153,167154},starts={{npcID=150796}},ends={{npcID=150796}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={55118},questLines={{id=921,name="My Brother's Keeper",orderIndex=2,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=921,questLineOrder=19,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=921,questLineOrder=12}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[55118] = {id=55118,name="Loose Ends",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={55033,55044,55045,55116,55117,55118,55119},description="Our campaign against the Horde is going strong, but there are some loose threads to take care of. Lady Ashvane was broken out of Tol Dagor - by the Horde. We don't know where she's gone or what she is planning. I sent Kelsey out to track down some Ashvane Loyalists to get answers. She found them and has requested backup. She's waiting for you in Freehold.",objectivesText="Meet Kelsey Steelspark in Freehold.",rewardGold=23400,rewardXP=850,rewardItems={202201},starts={{npcID=135612}},ends={{npcID=150796}},mapCandidates={npc={895,1161},zone={8568}},questType="standard",sourceQuests={54459},questLines={{id=921,name="My Brother's Keeper",orderIndex=0,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=921,questLineOrder=19,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=921,questLineOrder=12}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[55119] = {id=55119,name="Reporting In!",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=895,storyline={55033,55044,55045,55116,55117,55118,55119},description="Well it looks like Ashvane's been out of contact for some time but this 'Patron' thing could be a problem. You did excellent work today, <name>. Those Loyalists aren't going to be thinking about causing trouble for awhile, heh. I'll make my way back. You take the letter to the High Commander.",objectivesText="Report to Halford Wyrmbane in Boralus. Progress: Did you find anything on Ashvane?",rewardGold=23400,rewardXP=850,rewardItems={167102},starts={{npcID=150796}},ends={{npcID=135612}},mapCandidates={npc={895,1161},zone={8567}},questType="standard",sourceQuests={55116},questLines={{id=921,name="My Brother's Keeper",orderIndex=4,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=921,questLineOrder=19,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=921,questLineOrder=12}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=1161},
[55121] = {id=55121,name="The Laboratory of Mardivas",level=50,requiredLevel=50,faction="both",categories={},flags={"repeatable","weekly"},sharable=true,expansion=7,zoneID=10052,storyline={55121},description="<Several pages are devoted to notes on an experiment, a hastily written journal entry follows.> At last, my research into the base elements has begun to bear fruit! With careful application of the right base reagents and some arcane power I've managed to combine the essence of the elements in such a way as to create life! Further investigation will be needed to determine what the various mixes of the elements will yield. <The writing ends here.>",objectivesText="Activate the Elemental Essence Amalgamator in Mardivas's Laboratory. Progress: <The remaining pages are filled with gibberish and strange doodles.>",rewardGold=234000,rewardItems={166888,167012,167059,167077,169332,169333,169334,170068,170124,170125,170126,170127,170128,170129,170130,170131,170132,170137,170138,170166,170192,170383,170477,170512},rewardCurrencies={{id=1721,amount=10},{id=1721,amount=5}},starts={{npcID=13699,mapID=1355,x=0.6068,y=0.3221}},startObjects={{objectID=322533,mapID=1355,x=0.607,y=0.324}},endObjects={{objectID=322533,mapID=1355,x=0.607,y=0.324}},coords={mapID=1355,x=0.607,y=0.324},mapCandidates={npc={},zone={10052}},questType="standard",sourceQuests={57086}},
[55122] = {id=55122,name="Murloc Mania",level=1,requiredLevel=1,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={54933,54951,54952,55122,55173,55174,55184,55186,55193,55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56034,56344,56775,56839,58208,58209,58908,58909,58910,58911,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59254,59339,59342,59347,59349,59350,59352,59354,59355,59356,59583,59586,59587,59588,59589,59590,59591,59592,59593,59594,60168,85678,87547,87555,87560,87562},description="I'm glad you made it out in one piece. Judging by the nearby shipwrecks, I think it's safe to say the missing expedition ran aground here, too. We can't move until we've got the remaining survivors back on their feet. Unfortunately, our remaining supplies have been stolen by murlocs! I need you to recover enough first aid supplies for the wounded. Then we can begin searching for the missing expedition.",objectivesText="Recover 6 First Aid Kits from Murlocs. Progress: Did you recover the first aid kits ? Don't take the murlocs lightly.",rewardGold=200,rewardXP=200,rewardItems={170549},starts={{npcID=156626}},ends={{npcID=156626}},mapCandidates={npc={},zone={10424}},questGiverID=156626,questTurnInID=156626,questType="standard",sourceQuests={58208},questLines={{id=926,name="The Missing Expedition",orderIndex=3,flags=0},{id=1070,name="The Missing Expedition",orderIndex=3,flags=0},{id=5366,name="The Missing Expedition",orderIndex=3,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5366,questLineOrder=0,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[55123] = {id=55123,name="Hunting Season",level=10,requiredLevel=10,faction="none",sharable=false,expansion=7,zoneID=7503,mapID=650,mapCandidates={npc={},zone={7503}},questType="standard"},
[55124] = {id=55124,name="Righting Wrongs",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={54958,54959,54960,54961,54997,54999,55034,55124},description="Champion! I come with an urgent request from Baine Bloodhoof . He asks that you meet him at Plunder Harbor to help him with a... sensitive situation. You must tell no one of this request, <class>. Ancestors watch over you.",objectivesText="Meet with Baine Bloodhoof at Plunder Harbor in Tiragarde Sound.",rewardGold=23400,rewardXP=850,starts={{npcID=150433}},ends={{npcID=150309}},mapCandidates={npc={70,1165},zone={8670}},questType="standard",sourceQuests={54109,54165},questLines={{id=873,name="Testing Loyalties",orderIndex=1,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=873,questLineOrder=21,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=873,questLineOrder=13}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=895},
[55125] = {id=55125,name="Hunting Season",level=10,requiredLevel=10,faction="none",sharable=false,expansion=7,zoneID=7503,mapID=650,mapCandidates={npc={},zone={7503}},questType="standard"},
[55136] = {id=55136,name="Her Dog Days Are Over",level=40,requiredLevel=40,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={53720,54706,54708,54721,54723,54725,54726,54727,54728,54729,54730,54731,54732,54733,54734,54735,54851,55039,55043,55136},series={54729,54732},description="<The Wicker Beast gently nudges the dog's body with its snout. The creature whines plaintively and moves to your side. It gives a hopeful twitch of its bony tail.>",objectivesText="Walk the Wicker Beast . Progress: What's this...? I see you found my keys, but...",rewardGold=309800,rewardXP=5465,rewardItems={164762,167168,167172,167173,167174},starts={{npcID=150885}},ends={{npcID=150884}},mapCandidates={npc={896},zone={8721}},questType="standard",sourceQuests={54732},questLines={{id=916,name="Allies of the Alliance: Kul Tiran",orderIndex=13,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[55137] = {id=55137,name="For the Horde",level=10,requiredLevel=10,faction="horde",requiredRaces={31},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={55137,55138},description="Thank you for meeting me upon my throne, <name>. With our recent partnerin' with de Horde, I need worthy champions to represent the might of the Zandalari. I have chosen you to be among their ranks, <name>. Go and meet with the ambassador in Orgrimmar. We have prepared a portal just behind you. When you are ready, step through to a new world. Remember, you bow only to the throne of Zandalar. Hold your head high, <name>.",objectivesText="Meet with Ambassador Blackguard in the Orgrimmar Embassy.",rewardGold=2260,rewardXP=175,rewardItems={23002,23007,23015,23022,29928,29930,29931,29934,29938,29941,29943,29945,37956,37964,37998,38006,38041,38048,38081,38102,38110,57509,57510,57511,57512,65680,65701,65719,65728,66073,94220,111535,111536,111537,111538,111539,111540,111541,111542,116202,118761,118762,118763,118764,118765,131486,131696,131697,151557,155662,157028,157757,157759,161328,165001,165871,166883,167169,168615,168850,169765,174069,174508,223907,241215},starts={{npcID=146335}},ends={{npcID=133407}},mapCandidates={npc={85,1165},zone={8670}},questType="standard",questLines={{id=918,name="Allies of the Horde",orderIndex=0,flags=0}},db2PoiMapID=1,db2PoiUiMapID=85},
[55138] = {id=55138,name="Stranger in a Strange Land",level=10,requiredLevel=10,faction="horde",requiredRaces={31},categories={},flags={},sharable=true,expansion=7,zoneID=1637,mapID=85,storyline={55137,55138},description="Hi. I'm Ambassador Blackguard . I am honored to welcome you to Orgrimmar, <race>. <He smiles unconvincingly.> As a lifetime of adventure unfolds before you, be assured that... uh... You know what? I've been saying this same greeting all day. Enough's enough. Talk to Chromie on top of the hourglass, then talk to your emissary. Run along.",objectivesText="Find the Warchief's Command Board in Orgrimmar. Progress: Dis land is much less... fertile than Zandalar.",rewardGold=34100,rewardXP=175,rewardItems={246740,246795},starts={{npcID=133407}},ends={{npcID=150909}},mapCandidates={npc={85},zone={1637}},questType="standard",sourceQuests={55137},questLines={{id=918,name="Allies of the Horde",orderIndex=1,flags=0}},db2PoiMapID=1,db2PoiUiMapID=85},
[55142] = {id=55142,name="For the Alliance",level=10,requiredLevel=10,faction="alliance",requiredRaces={32},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={55142,55146},description="Thank you for meeting with me, <name>. I need representatives to go to Stormwind to represent our loyalty and commitment to our newly forged bond with the Alliance. I've had Yvia and her magi prepare a portal to the city for you in the Sanctum of the Sages. Once there, go to the Stormwind Embassy and meet with Ambassador Moorgard . You will face many challenges on the long journey ahead. Remember where you came from and make your people proud!",objectivesText="Take the portal to Stormwind in the Sanctum of the Sages and meet with Ambassador Moorgard in the Stormwind Embassy. Progress: Welcome to Stormwind, <race>.",rewardGold=30900,rewardXP=175,rewardItems={23002,23007,23015,23022,37500,42792,42805,42817,42830,65618,65625,65639,65642,66073,94219,108908,108909,108910,108912,108913,108914,108918,108919,116202,151557,157022,157756,157758,161329,165010,165872,166883,168615,168850,169764,174068,174507,204616,204617,204618,204619,223907,241215},starts={{npcID=150941}},ends={{npcID=133362}},mapCandidates={npc={84,1161},zone={8568}},questType="standard",questLines={{id=917,name="Allies of the Alliance",orderIndex=0,flags=0}},db2PoiUiMapID=84},
[55146] = {id=55146,name="Stranger in a Strange Land",level=10,requiredLevel=10,faction="alliance",requiredRaces={32},categories={},flags={},sharable=true,expansion=7,zoneID=1519,mapID=84,storyline={55142,55146},description="Welcome to Stormwind, <race>. I invite you to explore our fair city. Since you hail from Kul Tiras, might I suggest visiting our lovely docks? They are home to our majestic fleet. I would be shocked if you were not impressed! Ah, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things! After that, an emissary of Kul Tiras is waiting to welcome you to the city. Sounds like a busy day for you! Have a pleasant stay.",objectivesText="Find Chromie in Stormwind City. Progress: Enjoying your stay in Stormwind?",rewardGold=28090,rewardXP=175,rewardItems={246740,246795},starts={{npcID=133362}},ends={{npcID=150947}},mapCandidates={npc={84},zone={1519}},questType="standard",sourceQuests={55142},questLines={{id=917,name="Allies of the Alliance",orderIndex=1,flags=0}},db2PoiUiMapID=84},
[55148] = {id=55148,name="Reclamation Rig",level=0,requiredLevel=0,faction="none",sharable=false,expansion=7,zoneID=10290,mapID=1462,rewardGold=683200,starts={{npcID=150448,mapID=1462,x=0.6997,y=0.6201}},mapCandidates={npc={},zone={10290}},questType="standard"},
[55153] = {id=55153,name="Collaborative Construction",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55153},description="Construction projects can be found all over the island. You'll be able to build some of 'em yourself, but you're gonna need help with the bigger projects. Ask around and see what others are already working on, or just head out on your own and find a project you're interested in. Construction projects move around and even change day-to-day, so keep an eye out for new ones while you're exploring. If you're ever curious what construction projects are available on a given day, just ask me!",objectivesText="Find a construction project in Mechagon and help build it.",rewardGold=257400,rewardXP=1415,starts={{npcID=150555}},ends={{npcID=150555}},mapCandidates={npc={1462},zone={10290}},questType="standard",sourceQuests={55707},questLines={{id=960,name="Construction Projects",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55171] = {id=55171,name="Spy Versus Spy",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={55087,55088,55089,55090,55171,55179,55182,55183,55185},description="Naga attacks are on the rise, but that isn't all we have to deal with. We've received word of increased Horde activity near Warfang Hold in Stormsong Valley. Send some of our operatives to investigate what they are doing.",objectivesText="Complete the mission \"Spy on Warfang Hold\" Progress: Hopefully we can gather information on what they're up to in Stormsong Valley.",rewardGold=117000,rewardXP=3410,rewardItems={165748},starts={{npcID=135612}},ends={{npcID=135612}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={55045},questLines={{id=922,name="The Gathering Storm",orderIndex=0,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=922,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=922,questLineOrder=13}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=1161},
[55173] = {id=55173,name="Northbound",level=1,requiredLevel=1,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={54933,54951,54952,55122,55173,55174,55184,55186,55193,55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56034,56344,56775,56839,58208,58209,58908,58909,58910,58911,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59254,59339,59342,59347,59349,59350,59352,59354,59355,59356,59583,59586,59587,59588,59589,59590,59591,59592,59593,59594,60168,85678,87547,87555,87560,87562},description="The quilboar kidnapped the rest of the expedition and took them to the north. I heard mention of needing more sacrifices for some sort of ritual... Please, you must rescue them!",objectivesText="Scout northward and find Austin Huxworth .",rewardGold=285,rewardXP=100,rewardItems={167206},starts={{npcID=175031}},ends={{npcID=175031}},mapCandidates={npc={},zone={10424}},questGiverID=175031,questTurnInID=175031,questType="standard",sourceQuests={55174,59254,59339},questLines={{id=926,name="The Missing Expedition",orderIndex=9,flags=0},{id=1070,name="The Missing Expedition",orderIndex=8,flags=0},{id=5366,name="The Missing Expedition",orderIndex=9,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5366,questLineOrder=0,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[55174] = {id=55174,name="Cooking Meat",level=1,requiredLevel=1,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={54933,54951,54952,55122,55173,55174,55184,55186,55193,55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56034,56344,56775,56839,58208,58209,58908,58909,58910,58911,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59254,59339,59342,59347,59349,59350,59352,59354,59355,59356,59583,59586,59587,59588,59589,59590,59591,59592,59593,59594,60168,85678,87547,87555,87560,87562},description="Alaria is nearly starved to death. We need to get her something to eat! Slay some of the nearby wildlife for their meat. Bring whatever you find here to cook. If we can help Alaria regain her strength, she might be able to tell us what happened to the others. I'll stay here and help stabilize her wounds.",objectivesText="Get 5 Raw Meat from wildlife around the Abandoned Camp, then cook it on the campfire. Progress: Please... I need... some food...",rewardGold=565,rewardXP=200,rewardItems={117,172052,174072,174074},starts={{npcID=156651}},ends={{npcID=156651}},mapCandidates={npc={},zone={10424}},questGiverID=156651,questTurnInID=156651,questType="standard",sourceQuests={54952},questLines={{id=926,name="The Missing Expedition",orderIndex=6,flags=0},{id=1070,name="The Missing Expedition",orderIndex=6,flags=0},{id=5366,name="The Missing Expedition",orderIndex=6,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5366,questLineOrder=0,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[55175] = {id=55175,name="Where the Road Leads",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={54969,54972,55095,55175,56350,56640,56641,56642,56643,56644},description="My people know many secrets about this place. If you prove yourselves worthy allies, you will be privy to them. First, we must regroup in Mezzamere. There, we at least have a foothold against the tide.",objectivesText="Travel to Mezzamere with Okani.",rewardGold=234000,rewardXP=6815,starts={{npcID=151000}},ends={{npcID=150101}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56644},questLines={{id=949,name="Welcome to Nazjatar",orderIndex=7,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=8,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=949,questLineOrder=21,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1718,db2PoiUiMapID=1355},
[55177] = {id=55177,name="Tearing at the Seams",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"tailoring"},categories={},flags={},sharable=true,expansion=7,zoneID=65,mapID=115,storyline={53805,53807,53881,55177},series={53807},description="I feel odd... weak. As though something is affecting my very existence. Would you come with me, <name>? I may need your help. At the very least, you could be a witness to whatever happens should something dire occur.",objectivesText="Speak with Delormi when you're ready to leave and investigate the disturbance.",rewardGold=23400,rewardXP=850,rewardItems={152576,152668,159959,164733,168029,168128,168129,168130,168131},starts={{npcID=145022}},ends={{npcID=151134}},mapCandidates={npc={115},zone={65}},questGiverID=145022,questType="standard",sourceQuests={53807},questLines={{id=904,name="8.1.5 Tailoring - Alliance",orderIndex=2,flags=0}},db2PoiMapID=1,db2PoiUiMapID=71},
[55179] = {id=55179,name="Retaliation Coordination",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={55087,55088,55089,55090,55171,55179,55182,55183,55185},description="Master Shaw deployed a number of Alliance spies near a base the Horde have made in Stormsong Valley. When our spies stopped checking in, he took Kelsey Steelspark and went to investigate. Now Master Shaw is the one who hasn't checked in. I need someone to go in and find our missing people and give them whatever help they clearly need.",objectivesText="Find Kelsey Steelspark in Stormsong Valley.",rewardGold=23400,rewardXP=850,starts={{npcID=150633}},ends={{npcID=150637}},mapCandidates={npc={942,1161},zone={8568}},questType="standard",sourceQuests={55087},questLines={{id=922,name="The Gathering Storm",orderIndex=2,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=922,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=922,questLineOrder=13}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
[55182] = {id=55182,name="Reassembly Required",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={55087,55088,55089,55090,55171,55179,55182,55183,55185},description="Master Shaw wanted me to rebuild the listening posts the Horde destroyed when they started to clear the area in preparation for whatever they are planning. I managed to salvage most of the parts for one, but I'm missing a few. Fortunately for us, I've been watching the workers and they've been picking up the pieces of the destroyed machines. Go get our tech back and I can take care of the rest.",objectivesText="Collect Spy Salvage from Horde Forces. Progress: I am so excited! I love getting to work with our spy tech! Did you find what we need?",rewardGold=234000,rewardXP=6815,rewardItems={167216},starts={{npcID=150637}},ends={{npcID=150637}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={55179},questLines={{id=922,name="The Gathering Storm",orderIndex=4,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=922,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=922,questLineOrder=13}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
[55183] = {id=55183,name="Seeking Higher Ground",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={55087,55088,55089,55090,55171,55179,55182,55183,55185},description="We've only got one shot at reestablishing our communication network, so we've got to pick the right spot and I found just the right place! While you've been busy down here, I set up some camouflage and hauled the bulk of the machinery up there. What? Did you think I was just sitting here polishing my knives while you were gone? Well, okay I did that too. Anyway, I'll meet you up the hill!",objectivesText="Meet Kelsey Steelspark on the hill south of Warfang Hold.",rewardGold=23400,rewardXP=850,starts={{npcID=150637}},ends={{npcID=150637}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={55088,55182},questLines={{id=922,name="The Gathering Storm",orderIndex=5,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=922,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=922,questLineOrder=13}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
[55184] = {id=55184,name="Quilboar Shadow Magic",level=1,requiredLevel=1,faction="alliance",sharable=false,expansion=7,zoneID=10424,mapID=1409,description="Quilboar are primitive and savage. They rarely practice any magic other than geomancy. But these particular quilboar seem to be dabbling in shadow magic. They must be stopped. Slay the quilboar in the den. They cannot spread this magic in the island!",rewardGold=55,rewardXP=200,rewardChoices={175181,175213,175183,175215,175182,175214,175180,175212},starts={{npcID=154327}},ends={{npcID=149915}},mapCandidates={npc={1409},zone={10424}},questType="standard",sourceQuests={55173,59342},questLines={{id=1070,name="The Missing Expedition",orderIndex=10,flags=0},{id=926,name="The Missing Expedition",orderIndex=12,flags=0},{id=5366,name="The Missing Expedition",orderIndex=12,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5366,questLineOrder=0,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."},
[55185] = {id=55185,name="Listen Up!",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=9042,mapID=942,storyline={55087,55088,55089,55090,55171,55179,55182,55183,55185},description="Okay! Once we get this up and running we should be able to send messages! In the valley at least. It's gonna be a little bit tricky, but I've read the manual for these things cover to cover. <Kelsey slaps the top of the listening device.> I'm gonna put this thing back together. You watch out for the Horde.",objectivesText="Protect Kelsey Steelspark in Stormsong Valley. Progress: Woohoo! We are up and operational!",rewardGold=234000,rewardXP=6815,rewardItems={208929},starts={{npcID=150637}},ends={{npcID=150637}},mapCandidates={npc={942},zone={9042}},questType="standard",sourceQuests={55183},questLines={{id=922,name="The Gathering Storm",orderIndex=6,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=922,questLineOrder=20,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=922,questLineOrder=13}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1643,db2PoiUiMapID=942},
[55186] = {id=55186,name="Down with the Quilboar",level=1,requiredLevel=1,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={54933,54951,54952,55122,55173,55174,55184,55186,55193,55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56034,56344,56775,56839,58208,58209,58908,58909,58910,58911,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59254,59339,59342,59347,59349,59350,59352,59354,59355,59356,59583,59586,59587,59588,59589,59590,59591,59592,59593,59594,60168,85678,87547,87555,87560,87562},description="From what I can gather, the quilboar are performing a shadow ritual on one of the expedition members. Their chief is Geolord Grek'og . He is the one who seeks to drain the life from our friend. Slay Grek'og and save the captive member of the expedition. He may know where the others were taken.",objectivesText="Slay Geolord Grek'og .",rewardGold=55,rewardXP=200,starts={{npcID=154327}},ends={{npcID=154327}},mapCandidates={npc={},zone={10424}},questGiverID=154327,questTurnInID=154327,questType="standard",sourceQuests={55173,59342},questLines={{id=926,name="The Missing Expedition",orderIndex=11,flags=0},{id=1070,name="The Missing Expedition",orderIndex=9,flags=0},{id=5366,name="The Missing Expedition",orderIndex=11,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5366,questLineOrder=0,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[55188] = {id=55188,name="Tearing at the Seams",level=50,requiredLevel=50,faction="horde",requiredProfessions={"tailoring"},categories={},flags={},sharable=true,expansion=7,zoneID=65,mapID=115,storyline={53938,53940,53962,55188},series={53940},description="I feel odd... weak. As though something is affecting my very existence. Would you come with me, <name>? I may need your help. At the very least, you could be a witness to whatever happens should something dire occur.",objectivesText="Speak with Delormi when you're ready to leave and investigate the disturbance.",rewardGold=23400,rewardXP=850,starts={{npcID=145022}},ends={{npcID=151134}},mapCandidates={npc={115},zone={65}},questGiverID=145022,questType="standard",sourceQuests={53940},questLines={{id=905,name="8.1.5 Tailoring - Horde",orderIndex=2,flags=0}},db2PoiMapID=1,db2PoiUiMapID=71},
[55193] = {id=55193,name="The Scout-o-Matic 5000",level=1,requiredLevel=1,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={54933,54951,54952,55122,55173,55174,55184,55186,55193,55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56034,56344,56775,56839,58208,58209,58908,58909,58910,58911,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59254,59339,59342,59347,59349,59350,59352,59354,59355,59356,59583,59586,59587,59588,59589,59590,59591,59592,59593,59594,60168,85678,87547,87555,87560,87562},description="You look like a <race> that needs help finding the scattered members of our alliance expedition! Luckily, you have happened to rescue the one and only Lindie Springstock , inventor extraordinaire! I've got my Scout-o-Matic 5000 all set to go. It'll fly up in the air and let you scout the entire area. I'll give you the honors. Use my Scout-o-Matic 5000 to find the rest of the expedition.",objectivesText="Use the Scout-o-Matic 5000 to find Henry Garrick. Progress: Give me a moment to re-size the Scout-o-Matic, then you can ride it!",rewardGold=285,rewardXP=100,starts={{npcID=149899}},ends={{npcID=149899}},mapCandidates={npc={},zone={10424}},questGiverID=149899,questTurnInID=149899,questType="standard",sourceQuests={55184,55186},questLines={{id=926,name="The Missing Expedition",orderIndex=13,flags=0},{id=1070,name="The Missing Expedition",orderIndex=11,flags=0},{id=5366,name="The Missing Expedition",orderIndex=13,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5366,questLineOrder=0,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[55194] = {id=55194,name="Stocking Up on Supplies",level=1,requiredLevel=1,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56344,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59347,59349,59350,59352,59354,59355,59356,60168,85678},description="Quartermaster Richter was able to scavenge supplies from the wreckages on this island. Why don't you visit her and see if she has anything that you need? You'll want to be well equipped for whatever we encounter next.",objectivesText="Purchase any item from Quartermaster Richter and sell any of your items to her. Progress: Quartermaster Richter should have a few supplies that you could use.",rewardGold=1500,rewardXP=150,rewardItems={175239},starts={{npcID=245394}},ends={{npcID=245394}},mapCandidates={npc={},zone={10424}},questGiverID=245394,questTurnInID=245394,questType="standard",sourceQuests={55879},questLines={{id=926,name="The Missing Expedition",orderIndex=20,flags=0},{id=1072,name="What Lurks Below",orderIndex=0,flags=0},{id=5367,name="A Dark Ritual",orderIndex=2,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5367,questLineOrder=1,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[55195] = {id=55195,name="Reverberation",level=50,requiredLevel=50,faction="both",requiredClasses={3},categories={},flags={},sharable=false,expansion=7,zoneID=67,mapID=120,storyline={54913,54915,54916,54917,54918,54919,54920,55195,55516},description="Hati's spirit is bound to yours forevermore, hunter. But it also now carries a link to the Temple of Storms--as well as Silithus, I fear. The Thunderspark shares these same bonds. By physically linking it here, you can call upon the different aspects of Hati's spirit and bind them to yourself as well. Do not worry. Skoll and I will guard the Thunderspark with our very lives! It will be safe.",objectivesText="Use the Thunderspark to summon an Essence of Hati. Progress: It warms my heart to see Hati by your side once more.",rewardGold=117000,rewardXP=3410,rewardItems={167799,167800},starts={{npcID=29445}},ends={{npcID=29445}},mapCandidates={npc={120},zone={67}},questType="standard",sourceQuests={54920},questLines={{id=862,name="Never Hunt Alone",orderIndex=8,flags=0}},db2PoiMapID=571,db2PoiUiMapID=120},
[55196] = {id=55196,name="The Harpy Problem",level=6,requiredLevel=6,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56344,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59347,59349,59350,59352,59354,59355,59356,60168,85678},description="We need to find the remaining survivors of my expedition before the ogres sacrifice them for their dark ritual! I saw one of the survivors being dragged away by some harpies. They have a roost to the north. Kee-La and I will meet you up there with a scouting report.",objectivesText="Meet with Henry Garrick near the Harpy Roost.",rewardGold=735,rewardXP=440,starts={{npcID=156833}},ends={{npcID=156833}},mapCandidates={npc={},zone={10424}},questGiverID=156833,questTurnInID=156833,questType="standard",sourceQuests={55194},questLines={{id=926,name="The Missing Expedition",orderIndex=16,flags=0},{id=1071,name="The Harpy Problem",orderIndex=0,flags=0},{id=5367,name="A Dark Ritual",orderIndex=3,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5367,questLineOrder=1,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[55210] = {id=55210,name="Batteries Not Included",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55210,55211,56319,56320},description="You will not be sorry that you rescued my dear sister and me, $p. We are the vanguard of a new technological revolution, creating opportunities for all to enhance their lives with incredible technology! But, before we can do that, we need our laboratory to be fully powered. Those ruffians from Mechagon really did a number on our equipment. Fully charged energy cells are exceptionally rare around here, but I can make do with broken ones. Check around town, in the wreckage from the last attack.",objectivesText="Collect 10 Damaged Energy Cells . Progress: Everything old can be made new again.",rewardGold=128700,rewardXP=710,rewardItems={53270,53281,53285,53303,131400,166971,167233},starts={{npcID=150630}},ends={{npcID=150630}},mapCandidates={npc={1462},zone={10290}},questType="standard",questLines={{id=953,name="Rustbolt Energy",orderIndex=0,flags=0},{id=959,name="Quickcharge Experiments",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55211] = {id=55211,name="Recharging Rustbolt",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55210,55211,56319,56320},description="Our personal generator is worthless until we recharge its empty energy cells . As my dear brother says, energy cells are the lifeblood of innovation. Everything in Mechagon needs power, and energy cells deliver that power in a wonderfully universal format. But, once they're drained of power, most people toss the empty cells away. Most people are fools, dear test subject. We have perfected the technology to recharge small numbers of energy cells back to full power. Will you help us test it?",objectivesText="Use the NRG-100 to charge 6 generator energy cells . Progress: We only test the best!",rewardGold=257400,rewardXP=1415,rewardItems={166970,168122},starts={{npcID=150631}},ends={{npcID=150631}},mapCandidates={npc={1462},zone={10290}},questType="standard",sourceQuests={56319},questLines={{id=959,name="Quickcharge Experiments",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55213] = {id=55213,name="Energy Cells for Everyone",level=10,requiredLevel=10,faction="both",categories={},flags={"daily","repeatable"},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55213},description="The wondrous scuttlebutt around town is that the charging station in Bondo's Yard is going to be repaired today! That charging station is the best way to recharge all the Empty Energy Cells that've been piling up in your bag. Or in other people's bag. Or inside the mechanical innards of robots you don't own but are legally allowed to destroy. After you've acquired Empty Energy Cells, help build the charging station in Bondo's Yard and charge all of your Empty Energy Cells!",objectivesText="Find 5 Empty Energy Cells in Mechagon . Then, help build the Charging Station construction project and use it to charge your Empty Energy Cells. Progress: Empty Energy Cells can always be found on the island, but the Charging Station isn't always available. Chat with that wondrous Miss Gearhart if you want to know more.",rewardGold=2000,rewardXP=1415,rewardItems={166846,166970},starts={{npcID=150631}},ends={{npcID=150631}},mapCandidates={npc={1462},zone={10290}},questType="standard"},
[55214] = {id=55214,name="Seam Stress",level=50,requiredLevel=50,faction="both",requiredProfessions={"tailoring"},categories={},flags={},sharable=true,expansion=7,zoneID=9042,mapID=115,storyline={53810,53813,53858,53866,53868,53869,55214},series={53858,53866},description="I...I need a moment, <name>. <Delormi seems disoriented and grabs your shoulder for support. She presses her hand against her forehead and stands there for a minute. Finally shaking off whatever she was feeling, she stands up straight and faces you.> There are gaps in my memories. Things important to me, lost now. We must stop her at all costs, <name>.",objectivesText="Follow Delormi through the Time Rift. Progress: I feel so weak...",rewardGold=234000,rewardXP=6815,rewardItems={152576,152668,159959,164733,167231,168029,168128,168129,168130,168131},starts={{npcID=151134}},ends={{npcID=151134}},mapCandidates={npc={115},zone={9042}},questType="standard",sourceQuests={53866},questLines={{id=906,name="8.1.5 Tailoring - Alliance/Horde",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[55215] = {id=55215,name="The Cycle of Life",level=50,requiredLevel=50,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=9042,mapID=942,storyline={55215},objectivesText="Speak to Scrollsage Nola Stop Juvenile Turtles From Reaching the Ocean",rewardGold=280900,rewardXP=2090,mapCandidates={npc={},zone={9042}},questType="standard",db2Objectives={{text="Speak to Scrollsage Nola",amount=1,type=3,objectID=150759,orderIndex=0},{text="Stop Juvenile Turtles From Reaching the Ocean",amount=20,type=0,objectID=150646,orderIndex=1}},worldTaskTitle="The Cycle of Life",db2PoiMapID=1643,db2PoiUiMapID=896,db2QuestInfoID=152,db2QuestInfoName="Tortollan World Quest - 8.0"},
[55216] = {id=55216,name="The Audition",level=10,requiredLevel=10,faction="horde",requiredProfessions={"leatherworking"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53995,55216,55221,55222,55223},description="Xanjo has spoken highly of your skills, but I need to be certain of what you can do. I mean no offense, this is as much for your benefit as it is our own, as if you are not ready the task could kill you. If you are willing, I would like to provide you with a test to see how well you can work leather. Bring me three Drums of the Maelstrom that you have crafted yourself. This will prove your skill and consistency. If your work is up to par, I will inform you of my plan.",objectivesText="Craft 3 Drums of the Maelstrom and bring them to Atikka Moonchaser. Progress: <Atikka breathes audibly in anticipation of your return.> Have you got the drums?",rewardGold=128700,rewardXP=710,rewardItems={154167},starts={{npcID=151162}},ends={{npcID=151162}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={53995},questLines={{id=908,name="8.1.5 Leatherworking - Horde",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[55217] = {id=55217,name="Repaying the Life Debt",level=10,requiredLevel=10,faction="horde",requiredProfessions={"leatherworking"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={55217,55218},description="When I heard that the Alliance attacked Dazar'alor, I couldn't help but think of those lost when they attacked Camp Taurajo. No longer can I sit idly while they continue to slaughter us! I need you to go to Thunder Bluff, find Sheza Wildmane on the Elder Rise, and ask for some of her personal collection. I won't go into detail, but she owes me a life debt, and seeing her would... bring back too many painful memories... for both of us. Find her, tell her I sent you, and that this absolves her debt.",objectivesText="Speak with Sheza Wildmane in Thunder Bluff.",rewardGold=200,rewardXP=175,starts={{npcID=151162}},ends={{npcID=3037}},mapCandidates={npc={88,1165},zone={8670}},questType="standard",sourceQuests={55216},questLines={{id=931,name="8.1.5 Leatherworking - Horde - Classic Content",orderIndex=0,flags=0}},db2PoiMapID=1,db2PoiUiMapID=88},
[55218] = {id=55218,name="Sheza's Prized Leather",level=10,requiredLevel=10,faction="horde",requiredProfessions={"leatherworking"},categories={},flags={},sharable=false,expansion=7,zoneID=1638,mapID=88,storyline={55217,55218},description="I have a stash of extremely rare leathers, or... rather, I did. I don't know how, but the Venture Company must have heard how valuable my collection was because they stole it! And THEN they had the audacity to leave a note offering to sell it back to me for 1,000 gold! As the \"former owner\", I'm able to \"best appreciate the value of their new acquisition.\" The note states they'll be in the bluffs to the East until someone buys them. However you get the skins, consider them yours.",objectivesText="Retrieve the Rare Hides . Progress: How was she?",rewardGold=2000,rewardXP=1415,rewardItems={167541,167673},starts={{npcID=3037}},ends={{npcID=151162}},mapCandidates={npc={88,1165},zone={1638}},questType="standard",sourceQuests={55217},questLines={{id=931,name="8.1.5 Leatherworking - Horde - Classic Content",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[55219] = {id=55219,name="Dropping by the Base",level=10,requiredLevel=10,faction="horde",requiredProfessions={"leatherworking"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={55219,55220},description="When the Legion was attacking, I met with a member of the Highmountain Tauren who had a knack for making and playing drums. Torv usually keeps to himself, but he is as brilliant as he is insane. If there is anyone who would know where we could get the raw materials for something of this magnitude, it would be him. Head to Thunder Totem, and ask Torv Dubstomp if he can think of a suitable source of scales. Preferably something still living, so its power is still fresh.",objectivesText="Speak with Torv Dubstomp in Thunder Totem.",rewardGold=200,rewardXP=175,starts={{npcID=151162}},ends={{npcID=151162}},mapCandidates={npc={1165},zone={8670}},questTurnInID=151162,questType="standard",sourceQuests={55216},questLines={{id=932,name="8.1.5 Leatherworking - Horde - Legion Content",orderIndex=0,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=650},
[55220] = {id=55220,name="Bass Fishing",level=10,requiredLevel=10,faction="horde",requiredProfessions={"leatherworking"},categories={},flags={},sharable=true,expansion=7,zoneID=7503,mapID=1165,storyline={55219,55220},description="Have you heard of people taking small golden carp as pets? Well, if it is kept in a pond free of predators, over time it can grow enormous, only limited by the food present. Centuries ago, one of these fish lived in the pond atop a mountain. It ate everything and began to starve, so my people dug a river that connected the pond to the ocean so the fish could be free. Now, fishermen talk of being attacked by an enormous golden fish in the Rockaway Shelf. Kill it. Take his scales back to Atikka.",objectivesText="Collect Brilliant Golden Scales . Progress: Did you meet with Torv yet?",rewardGold=2000,rewardXP=1415,rewardItems={167543},starts={{npcID=108017}},ends={{npcID=151162}},mapCandidates={npc={1165},zone={7503}},questGiverID=108017,questType="standard",sourceQuests={55219},questLines={{id=932,name="8.1.5 Leatherworking - Horde - Legion Content",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[55221] = {id=55221,name="Picking Bones",level=10,requiredLevel=10,faction="horde",requiredProfessions={"leatherworking"},categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=1165,storyline={53995,55216,55221,55222,55223},description="When I was sailing in, I noticed the remains of an unbelievably large beast on the nearby peninsula. Whatever it was, it must have been strong, making it the perfect source for the bone elements of the drums. Go to the peninsula, 'Xibala' I've heard it called, and fill a bag with the bones you find. If you come across any of those damned Alliance, show them no mercy. They did this to themselves.",objectivesText="Collect 18 Unwaning Bones . Progress: Did you get the bones? Did the Alliance give you any trouble?",rewardGold=2000,rewardXP=1415,rewardItems={165231},starts={{npcID=151162}},ends={{npcID=151162}},mapCandidates={npc={1165},zone={8499}},questType="standard",sourceQuests={55216},questLines={{id=908,name="8.1.5 Leatherworking - Horde",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[55222] = {id=55222,name="Make Some Noise",level=10,requiredLevel=10,faction="horde",requiredProfessions={"leatherworking"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53995,55216,55221,55222,55223},description="We have everything we need to craft the drum, except the Earth Mother's blessing. The drum is but a vessel, like a cup. We need her to imbue the drum with power, filling the cup so that we may drink. It will not be easy to convince her to assist us in creating a weapon of war, but I will implore her to protect her children. While I'm doing that, you will need to craft the drum itself. Not too big, though. The larger the vessel, the more power it can hold, but the harder it becomes to carry.",objectivesText="Craft 6 Drums of Primal Might . Progress: <Clearly exhausted, Atikka is trying to remain composed.>",rewardGold=25740,rewardXP=175,rewardItems={167558,167559,167560,167561},starts={{npcID=151162}},ends={{npcID=151162}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={55218,55220,55221},questLines={{id=908,name="8.1.5 Leatherworking - Horde",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[55223] = {id=55223,name="Instruments of Destruction",level=10,requiredLevel=10,faction="horde",requiredProfessions={"leatherworking"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={53995,55216,55221,55222,55223},description="Our work is almost finished. These drums, while powerful, are practically useless here in port. If you want to get the most benefit from them, you'll need to spread them out. I'd suggest one for each territory here and in Kul Tiras, to help you when you are on a quest and to keep you at your strongest when you're behind enemy lines. Look for someplace centralized in each territory to place drums. Once you return, I'll show you how to make the mallet needed to utilize the drums.",objectivesText="Place the Drums of Primal Might throughout Zandalar and Kul Tiras.",rewardGold=2000,rewardXP=1415,starts={{npcID=151162}},ends={{npcID=151162}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={55222},questLines={{id=908,name="8.1.5 Leatherworking - Horde",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[55225] = {id=55225,name="Special Juices",level=50,requiredLevel=50,faction="none",categories={},flags={"daily","repeatable"},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55225},series={55226},mapCandidates={npc={},zone={10052}},questType="standard"},
[55226] = {id=55226,name="Drive the Enemy",level=50,requiredLevel=50,faction="none",categories={},flags={"daily","repeatable"},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55226},series={55225},mapCandidates={npc={},zone={10052}},questType="standard"},
[55227] = {id=55227,name="The Aeonian Artisan",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"leatherworking"},categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={55227,55228,55233,55234,55235},description="Good day, friend! A Night Elf woman stopped by and asked who was the best leatherworker I knew who didn't mind getting their hands dirty. I gave her your name, and she asked me to ask you to find her in Boralus Harbor. She didn't say what she needed my best student for, but the way she acted makes me think that it is for something big. Head on down to the docks and look for her. She has white hair, purple tattoos, and a pet turtle named \"Gouge\". Show her what I've taught you!",objectivesText="Meet the Night Elf Leatherworker in Boralus Harbor.",rewardGold=23400,rewardXP=850,starts={{npcID=136063}},ends={{npcID=151173}},mapCandidates={npc={1161},zone={8568}},questGiverID=136063,questType="standard",questLines={{id=907,name="8.1.5 Leatherworking - Alliance",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[55228] = {id=55228,name="The Audition",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"leatherworking"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={55227,55228,55233,55234,55235},description="Cassandra has spoken highly of your skills, but I need to be certain of what you can do. I mean no offense, this is as much for your benefit as it is our own, as if you are not ready the task could kill you. If you are willing, I would like provide you with a test to see how well you can work leather. Bring me three Drums of the Maelstrom that you have crafted yourself. This will prove your skill and consistency. If your work is up to par, I will inform you of my plan.",objectivesText="Craft 3 Drums of the Maelstrom and bring them to Daniss Ghostdancer . Progress: Do you have the drums?",rewardGold=128700,rewardXP=710,rewardItems={154167},starts={{npcID=151173}},ends={{npcID=151173}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={55227},questLines={{id=907,name="8.1.5 Leatherworking - Alliance",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[55229] = {id=55229,name="Repaying the Debt",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"leatherworking"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={55229,55230},description="I was in Teldrassil when it was set alight. Through the panic and chaos, I knew I could not rest as long as those who did this were unpunished. I need you to go to Stormwind, find Telonis near the Lion's Rest, and ask for some of his personal collection. I managed to save him from the fires, so he owes me a great deal. I would go myself, but the loss of Teldrassil is still a fresh wound. I still need to give it time to heal. Find him, tell him I sent you, and that this will absolve his debt to me.",objectivesText="Speak with Telonis in Stormwind.",rewardGold=25740,rewardXP=175,starts={{npcID=151173}},ends={{npcID=151287}},mapCandidates={npc={84,1161},zone={8568}},questType="standard",sourceQuests={55228},questLines={{id=929,name="8.1.5 Leatherworking - Alliance - Classic Content",orderIndex=0,flags=0}},db2PoiUiMapID=84},
[55230] = {id=55230,name="Telonis' Prized Leather",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"leatherworking"},categories={},flags={},sharable=false,expansion=7,zoneID=1519,mapID=84,storyline={55229,55230},description="I have a stash of extremely rare leathers, or... rather, I did. A group of thieves must have heard how valuable my collection was because they stole it! And THEN they had the audacity to leave a note offering to sell it back to me! As the \"former owner\", I'm able to \"best appreciate the value of their new acquisition.\" The note states they'll be waiting in the foothills behind the castle, to the east, until they find another buyer. However you get the skins, consider them yours.",objectivesText="Retrieve the Rare Hides . Progress: How is he holding up?",rewardGold=257400,rewardXP=1415,rewardItems={167541,167550},starts={{npcID=151287}},ends={{npcID=151173}},mapCandidates={npc={84,1161},zone={1519}},questType="standard",sourceQuests={55229},questLines={{id=929,name="8.1.5 Leatherworking - Alliance - Classic Content",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[55231] = {id=55231,name="The Other Ghostdancer",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"leatherworking"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={55231,55232},description="When the Legion was attacking, my partner went to Val'sharah to fight the demons. Mevris may be cold and headstrong, but he's goal oriented, and willing to sacrifice to achieve them. That's part of why I fell in love with him. If there is anyone who would know where we could get the raw materials for something of this magnitude, it would be him. Head to Val'sharah, and look for him in the Temple of Elune. Tell him of our plan, and that we need his help securing scales.",objectivesText="Speak with Mevris Ghostdancer in Val'sharah.",rewardGold=200,rewardXP=175,starts={{npcID=151173}},ends={{npcID=151285}},mapCandidates={npc={641,1161},zone={8568}},questType="standard",sourceQuests={55228},questLines={{id=930,name="8.1.5 Leatherworking - Alliance - Legion Content",orderIndex=0,flags=0}},db2PoiMapID=1220,db2PoiUiMapID=641},
[55232] = {id=55232,name="Mevris' Menace",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"leatherworking"},categories={},flags={},sharable=true,expansion=7,zoneID=7558,mapID=641,storyline={55231,55232},description="There is a hydra that has been something of a nuisance for us as of late. It lives out on the Gloaming Reef, almost directly due west of here. It's been attacking ships that pass by, making it difficult to get supplies to and from Bradensbrook. I sent a team to handle it, but they haven't returned. Go out there, kill it, and take its scales to Daniss. And when you see her, tell her that I said... <Mevris pauses as he thinks of his words, and the meaning they carry.> Nothing.",objectivesText="Collect Brilliant Azure Scales . Progress: Have you met with Mevris?",rewardGold=2000,rewardXP=1415,rewardItems={167542},starts={{npcID=151285}},ends={{npcID=151173}},mapCandidates={npc={641,1161},zone={7558}},questType="standard",sourceQuests={55231},questLines={{id=930,name="8.1.5 Leatherworking - Alliance - Legion Content",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[55233] = {id=55233,name="Picking Bones",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"leatherworking"},categories={},flags={},sharable=true,expansion=7,zoneID=8567,mapID=1161,storyline={55227,55228,55233,55234,55235},description="When I was sailing in, I heard some of the sailors talking about the Horde presence here in Tiragarde Sound. Apparently they're scrounging around the remains of a massive creature that has washed ashore. Whatever it was, if the Horde wants it, we need to make sure they don't get it. Find the Horde, keep them from taking anything, and see if there are any bones from the creature we can use for our drums. Show them no mercy, <name>.",objectivesText="Collect 18 Unwaning Bones . Progress: Have you dealt with our mutual problem?",rewardGold=257400,rewardXP=1415,rewardItems={167549},starts={{npcID=151173}},ends={{npcID=151173}},mapCandidates={npc={1161},zone={8567}},questType="standard",sourceQuests={55228},questLines={{id=907,name="8.1.5 Leatherworking - Alliance",orderIndex=2,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[55234] = {id=55234,name="Make Some Noise",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"leatherworking"},categories={},flags={},sharable=false,expansion=7,zoneID=8568,mapID=1161,storyline={55227,55228,55233,55234,55235},description="We have everything we need to craft the drum, except Elune's blessing. The drum is but a vessel, like a cup. We need her to imbue the drum with power, filling the cup so that we may drink. With Tyrande donning the mantle of the Night Warrior, much of Elune's power is taxed. Asking for another favor is not insignificant, but I must try. While I'm doing that, I need you to craft the drum. Try to keep it small. The larger the vessel, the more power it can hold, but the harder it becomes to move.",objectivesText="Craft 6 Drums of Primal Might . Progress: <Clearly exhausted, Daniss is trying to remain composed.>",rewardGold=1745,rewardXP=175,rewardItems={167558,167559,167560,167561},starts={{npcID=151173}},ends={{npcID=151173}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={55230,55232,55233},questLines={{id=907,name="8.1.5 Leatherworking - Alliance",orderIndex=3,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[55235] = {id=55235,name="Instruments of Destruction",level=10,requiredLevel=10,faction="alliance",requiredProfessions={"leatherworking"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={55227,55228,55233,55234,55235},description="There is one last thing we need to do. These drums, while powerful, are practically useless here in town. If you want to get the most benefit from them, you'll need to spread them out. I'd suggest one for each territory here and in Zandalar, to help you when you are on a quest and to keep you at your strongest when you're behind enemy lines. Look for someplace centralized in each territory to place drums. Once you return, I'll show you how to make the mallet needed to utilize the drums.",objectivesText="Place the Drums of Primal Might throughout Zandalar and Kul Tiras.",rewardGold=17450,rewardXP=1415,starts={{npcID=151173}},ends={{npcID=151173}},mapCandidates={npc={1161},zone={8568}},questType="standard",sourceQuests={55234},questLines={{id=907,name="8.1.5 Leatherworking - Alliance",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[55242] = {id=55242,name="A Goblin in Need",level=10,requiredLevel=10,faction="none",sharable=false,expansion=7,zoneID=7503,mapID=650,mapCandidates={npc={},zone={7503}},questType="standard"},
[55243] = {id=55243,name="A Daughter of Torcali",level=50,requiredLevel=50,faction="horde",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={55243},description="It has long been remarked upon that a direhorn is de bravest beast in de jungle. That is why they are chosen as mounts for our warriors. In this case, that bravery may not be in your favor. De little one has run off and I do not think she is hungry this time. Best find her before she gets hurt.",objectivesText="Find the Child of Torcali in the Savagelands and rescue her from danger.",rewardGold=234000,rewardXP=6815,starts={{npcID=151319}},ends={{npcID=152258}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={55507}},
[55244] = {id=55244,name="Away From the Herd",level=50,requiredLevel=50,faction="horde",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={55244},description="<The Child of Torcali stares longingly out of her pen. Her gaze seems to be following the other nearby direhorns. Perhaps she could use a distraction.>",objectivesText="Play with your direhorn.",rewardGold=234000,rewardXP=6815,rewardItems={168304},starts={{npcID=152258}},ends={{npcID=152258}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={55507}},
[55245] = {id=55245,name="Eat Like a Direhorn",level=50,requiredLevel=50,faction="horde",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={55245},description="<The Child of Torcali investigates your hands for traces of food and makes a small sound of distress.>",objectivesText="Feed the Child of Torcali . Progress: <The Child of Torcali wiggles impatiently.>",rewardGold=234000,rewardXP=6815,rewardItems={157780,157781,168408},starts={{npcID=152258}},ends={{npcID=152258}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={55507}},
[55246] = {id=55246,name="Even Greener Pastures",level=50,requiredLevel=50,faction="horde",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={55246},description="Ever since Torcali gave her boon to de little one, she has been growing like a weed. Dat makes her very hungry. She got out again to look for more things to eat. Before you ask, it is not my role to stop her from doing what she wants. Only to ensure she is safe. She is probably fine. Bring her home, and if you have trouble bringing her home, you might try a bribe.",objectivesText="Find the Child of Torcali and lead her back to her pen.",rewardGold=234000,rewardXP=6815,starts={{npcID=151319}},ends={{npcID=152258}},mapCandidates={npc={862},zone={8499}},questType="standard"},
[55247] = {id=55247,name="The Trust You've Earned",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={55247,55252,55253,55254,55258,55462,55503,55504,55505,55506,55507,55795,55796,55797,55798},description="I believe my loa will agree with me when I say that you have proven yourself worthy of this one's companionship. She is large enough now that she can bear you wherever it is that you wish to go. I had de Beastlord craft a saddle for you. Go and get it and I will help you put it on your new steed's back. Congratulations, <name>.",objectivesText="Retrieve the Direhorn Saddle in Warbeast Kraal. Progress: < Li'zal rubs her head and groans.>",rewardGold=117000,rewardXP=3410,rewardItems={168325,168408},starts={{npcID=151319}},ends={{npcID=154673}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={55507},questLines={{id=935,name="How to Train Your Direhorn",orderIndex=10,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[55248] = {id=55248,name="Greener Pastures",level=50,requiredLevel=50,faction="horde",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={55248},description="You have done an adequate job keeping de little one fed, but sometimes they just want something else. I did not see where de hatchling went, but you should start where de grass is real green. You will likely find her eating it. If you have trouble bringing her home, you might try a bribe.",objectivesText="Find the Child of Torcali and lead her back to her pen.",rewardGold=234000,rewardXP=6815,starts={{npcID=151319}},ends={{npcID=151286}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={55258}},
[55249] = {id=55249,name="Away From the Herd",level=50,requiredLevel=50,faction="horde",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={55249},description="<The Child of Torcali stares longingly out of her pen. Her gaze seems to be following the other nearby direhorns. Perhaps she could use a distraction.>",objectivesText="Help your direhorn cheer up.",rewardGold=234000,rewardXP=6815,rewardItems={168304},starts={{npcID=151286}},ends={{npcID=151286}},mapCandidates={npc={862},zone={8499}},questType="standard"},
[55250] = {id=55250,name="A Growing Appetite",level=50,requiredLevel=50,faction="horde",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={55250},description="<The Child of Torcali investigates your hands for traces of food and makes a small sound of distress.>",objectivesText="Feed the Child of Torcali . Progress: <The Child of Torcali wiggles impatiently.>",rewardGold=234000,rewardXP=6815,starts={{npcID=151286}},ends={{npcID=151286}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={55258}},
[55251] = {id=55251,name="A Daughter of Torcali",level=50,requiredLevel=50,faction="horde",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={55251},description="It has long been remarked upon that a direhorn is de bravest beast in de jungle. That is why they are chosen as mounts for our warriors. In this case, that bravery may not be in your favor. De little one has run off and I do not think she is hungry this time. Best find her before she gets hurt.",objectivesText="Find the Child of Torcali in the Slough and rescue her from danger.",rewardGold=234000,rewardXP=6815,starts={{npcID=151319}},ends={{npcID=151286}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={55258}},
[55252] = {id=55252,name="A Loa Without a Temple",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={55247,55252,55253,55254,55258,55462,55503,55504,55505,55506,55507,55795,55796,55797,55798},series={55253,55254,55258},description="I have given some thought about your situation, <name>. It is not your fault dat de goblin deceived us. I followed along with his scheme as well. From today, you have my forgiveness. But dat cannot help de little one. I fear we may lose it, if we do not act. We must ask de wanderer's loa, de mountain dat moves, de great bulwark, de greatmother of direhorns, to save her child. Take dis offering to her shrine and ask for her boon... and her forgiveness.",objectivesText="Deliver L'kala's offering to Torcali . Progress: <The great direhorn looks down upon you.>",rewardGold=117000,rewardXP=3410,rewardItems={157779,167545},starts={{npcID=121706}},ends={{npcID=151257}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={55254},questLines={{id=935,name="How to Train Your Direhorn",orderIndex=1,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[55253] = {id=55253,name="A Show of Faith",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={55247,55252,55253,55254,55258,55462,55503,55504,55505,55506,55507,55795,55796,55797,55798},series={55252,55254,55258},description="< Torcali 's voice enters your mind.> I have watched your efforts from afar, small thing. You have made mistakes, and one of my young has suffered for it. I do not forget, but I can forgive. <The enormous direhorn touches the offering bundle with her nose.> As my people place faith in me, I place my faith in you. Take my blessing to my child and she will wake.",objectivesText="Deliver the Blessed Offering to your direhorn hatchling in Warbeast Kraal.",rewardGold=117000,rewardXP=3410,rewardItems={157779,167546},starts={{npcID=151257}},ends={{npcID=151286}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={55252},questLines={{id=935,name="How to Train Your Direhorn",orderIndex=2,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[55254] = {id=55254,name="An Unending Sleep",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={55247,55252,55253,55254,55258,55462,55503,55504,55505,55506,55507,55795,55796,55797,55798},series={55252,55253,55258},description="<The direhorn hatchling continues to sleep soundly, despite any efforts on your part to wake it. It's probably been too long. You should speak to Beastlord L'kala .>",objectivesText="Speak to Beastlord L'kala in Warbeast Kraal.",rewardGold=23400,rewardXP=850,starts={{npcID=151283}},ends={{npcID=121706}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={52857},questLines={{id=935,name="How to Train Your Direhorn",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[55258] = {id=55258,name="Sleep, Eat, Repeat",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=8499,mapID=862,storyline={55247,55252,55253,55254,55258,55462,55503,55504,55505,55506,55507,55795,55796,55797,55798},series={55252,55253,55254},description="<The Child of Torcali pushes the sack of herbs around with her snout. She then looks to you and stomps eagerly in place.>",objectivesText="Feed the Child of Torcali . Progress: <The Child of Torcali pushes her snout into your hand in search of food.>",rewardGold=234000,rewardXP=6815,rewardItems={157779},starts={{npcID=151286}},ends={{npcID=151286}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={55253},questLines={{id=935,name="How to Train Your Direhorn",orderIndex=3,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[55264] = {id=55264,name="Calligraphy",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={55264},objectivesText="Speak to Scrollsage Nola Complete the Tracing Challenge",rewardItems={44413,54860},mapCandidates={npc={},zone={8721}},questType="standard",db2Objectives={{text="Speak to Scrollsage Nola",amount=1,type=0,objectID=151489,orderIndex=0},{text="Complete the Tracing Challenge",amount=1,type=0,objectID=151379,orderIndex=1}},worldTaskTitle="Calligraphy",db2PoiMapID=1643,db2PoiUiMapID=896,db2QuestInfoID=152,db2QuestInfoName="Tortollan World Quest - 8.0"},
[55298] = {id=55298,name="Fishing For Something Bigger",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55055,55298,55339,56305},description="There's a huge fish lurking these waters, and it's been causing lots of problems! It eats other fish, fishermen, and a lot of expensive gear. I saw it swallow a beautiful Zigby 300 Fishing Rod along with its owner just the other day! I've got a plan, but I've lost a lot of my equipment in the waters around here. Can you help fish up some of these items for me?",objectivesText="Find the Anodized Sentry Fish , Jarmouthed Goby and the Suction Tube . Progress: Did you get me the items?",rewardGold=257400,rewardXP=1415,rewardItems={167669,167670,167671},starts={{npcID=151462}},ends={{npcID=151462}},mapCandidates={npc={1462},zone={10290}},questType="standard",questLines={{id=924,name="Mechagon Fishing",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1462},
