[55381] = {id=55381,name="Rustbolt Requisitions: Storm Silver Ore",level=10,requiredLevel=10,faction="horde",categories={},flags={"daily","repeatable"},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55381},objectivesText="Bring 10 Storm Silver Ore to Skaggit . Progress: Gazlowe's orders are in: He wants these supplies ASAP. Ya got the goods?",rewardGold=2000,rewardXP=1415,rewardItems={152579,152668,166846},rewardCurrencies={{id=1560,amount=40},{id=1560,amount=45},{id=1560,amount=50},{id=1560,amount=55}},starts={{npcID=150563}},ends={{npcID=150563}},mapCandidates={npc={1462},zone={10290}},questType="standard",db2LabelIDs={5672}},
