[55462] = {id=55462,name="The Wanderer's Call",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={55247,55252,55253,55254,55258,55462,55503,55504,55505,55506,55507,55795,55796,55797,55798},description="Greetings, small thing. De Great Wanderer asked this one to collect you. She has a task for you and de little beast to complete. Jo'nok's loa is patient, but he would not keep her waiting.",objectivesText="Speak to Torcali in the Savagelands.",rewardGold=117000,rewardXP=3410,starts={{npcID=151999}},ends={{npcID=151257}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={55258},questLines={{id=935,name="How to Train Your Direhorn",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[55463] = {id=55463,name="Aid From Nordrassil",level=10,requiredLevel=10,faction="both",categories={},flags={"daily","repeatable"},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55463},description="Look at what they've done to this island, <name>. Nature is nearly extinguished, its death cry falling on the deaf ears of mechagnomes. But I have heard the teeny tiny animals of Mechagon , and bring aid from afar! It won't be easy to restore balance to a land so severely wounded. Nature's scars run deep here. Thankfully, we are not alone. I've brought living sap from Nordrassil, the World Tree of Mount Hyjal. Use it to regrow the forests and speed nature's recovery in this land.",objectivesText="Kill 8 Sawblade Clearcutters and use the Living Sap of Nordrassil to regrow 8 stumps.",rewardGold=257400,rewardXP=1415,rewardItems={166846,166970,166971,167793,168582,169379,246697},starts={{npcID=151936}},ends={{npcID=151936}},mapCandidates={npc={1462},zone={10290}},questType="standard",questLines={{id=962,name="Visit from Mylune",orderIndex=0,flags=0}},db2LabelIDs={5672},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55465] = {id=55465,name="We Must Go Deeper",level=50,requiredLevel=50,faction="both",categories={"legendary"},flags={},sharable=false,expansion=7,zoneID=10474,mapID=1475,storyline={55390,55392,55393,55394,55395,55396,55397,55398,55465},series={55390,55392,55393,55394,55395,55396,55397,55398},description="These shards can only do so much in their current state. They are broken and scattered... not unlike my kin. We must bring them together. Let us go deeper into the Emerald Dream. I know of a place where we can reforge the shards into a dragonscale. With it, you can empower the Heart of Azeroth with the essence of my dragonflight. We must go to the ancient heart of the Dream, where my mother once rested. Speak with me when you are ready to delve deeper.",objectivesText="Speak to Merithra to travel deeper into the Emerald Dream.",rewardGold=234000,rewardItems={167831},starts={{npcID=151693}},ends={{npcID=151693}},mapCandidates={npc={},zone={10474}},questGiverID=151693,questTurnInID=151693,questType="standard",sourceQuests={55393,55394,55395},questLines={{id=912,name="The Stuff Dreams Are Made Of",orderIndex=5,flags=0}},db2PoiMapID=2209,db2PoiUiMapID=1475},
[55469] = {id=55469,name="To Zin-Azshari",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55469,55482,55485,55486,55488,55489,55490,55799,56356},description="We need something to deal with the guardian of the Tidestone, <name>. Our new allies here say that there is a naga enclave located in the ruins of Zin-Azshari. If there is anything potent enough to counter Azshara's sorcery, it will be in the ruins of her capital city. The First Arcanist will accompany you, champion. She will be best equipped to assist you in matters both historical and magical while you search. Good luck.",objectivesText="Meet First Arcanist Thalyssra in the ruins of Zin-Azshari.",rewardGold=23400,rewardXP=850,starts={{npcID=151848}},ends={{npcID=152066}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56236},questLines={{id=938,name="Turning the Tide",orderIndex=0,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=39,flags=0}},campaigns={{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55481] = {id=55481,name="Scouting the Palace",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={54012,54015,54018,54021,55053,55054,55092,55094,55481,56063,56429},description="We cannot hide here forever, <name>. We have to deal with Azshara. We will need to assault her palace but we do not know what defenses she has in place. I dispatched a scouting team while you were gone and they have not reported back. I cannot afford to lose any more people. Speak with Spiritwalker Ussoh. His abilities will let us see where the scouts are.",objectivesText="Speak with Spiritwalker Ussoh to observe the scouting party. Progress: Have you spoken with Ussoh yet?",rewardXP=10225,rewardItems={169482,169483,169485},rewardChoices={169482,169483,169485},rewardCurrencies={{id=1721,amount=20}},starts={{npcID=151848}},ends={{npcID=151848}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56161,57010},questLines={{id=886,name="Azshara's Trap",orderIndex=10,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=20,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=886,questLineOrder=23,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1718,db2PoiUiMapID=1355},
[55482] = {id=55482,name="Making the Connection",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55469,55482,55485,55486,55488,55489,55490,55799,56356},description="A communication crystal! Have they survived this long? We used to use these to communicate. They allowed us to project images of ourselves to other nearby crystals to see and speak with those on the other end. <Thalyssra examines the crystal for a few moments.> The magic has long since depleted from the crystal. We will need a power source, preferably something just as old as this. Check our surroundings, but be careful. It is too quiet out here....",objectivesText="Search the ruins of Kal'methir for magical relics. Progress: Have you found anything to power the crystal?",rewardGold=234000,rewardXP=6815,rewardItems={168002,169147,169148},starts={{npcID=152066}},ends={{npcID=152066}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55469},questLines={{id=938,name="Turning the Tide",orderIndex=1,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=40,flags=0}},campaigns={{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55485] = {id=55485,name="Terrors in the Deep",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55469,55482,55485,55486,55488,55489,55490,55799,56356},description="Azshara knows we are here. Still, we must press on. Be careful, though. There is a... wrongness coming from the water. It is unlike the magic of old, but more ancient and terrible. Traverse the canals and find the source of corruption. If we are to search Zin-Azshari, we cannot let any relics fall into the hands of even darker powers.",objectivesText="Defeat 10 corrupted creatures and the source of the corruption.",rewardGold=468000,rewardXP=8520,starts={{npcID=152066}},ends={{npcID=152316}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55482},questLines={{id=938,name="Turning the Tide",orderIndex=2,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=41,flags=0}},campaigns={{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55486] = {id=55486,name="Secrets of Telemancy",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55469,55482,55485,55486,55488,55489,55490,55799,56356},description="The nightborne are no strangers to this place. It was once our capital too, long ago. Before the Sundering and erecting the shield over Suramar we used to travel freely to Zin-Azshari. Oculeth had a workshop in these estates. Perhaps it might contain some secrets or magic that went undisturbed by the survivors.",objectivesText="Investigate Oculeth's old workshop. Progress: Have you found the workshop yet?",rewardGold=234000,rewardXP=6815,rewardItems={168201},starts={{npcID=152316}},ends={{npcID=152316}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55485},questLines={{id=938,name="Turning the Tide",orderIndex=3,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=42,flags=0}},campaigns={{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55488] = {id=55488,name="Speak with the Dead",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55469,55482,55485,55486,55488,55489,55490,55799,56356},description="So many souls perished beneath the waves. Too many sacrificed for her ambition. It is strange that the spirits here have not departed. I wonder if they even know they are dead? Still, their knowledge might be useful to us. If you could question the spirits, they might be able to point us in the right direction.",objectivesText="Question the spirits in the Highborne Estates to discover something useful.",rewardGold=234000,rewardXP=6815,starts={{npcID=152316}},ends={{npcID=152316}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55485},questLines={{id=938,name="Turning the Tide",orderIndex=4,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=43,flags=0}},campaigns={{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55489] = {id=55489,name="The Handmaiden's Tale",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55469,55482,55485,55486,55488,55489,55490,55799,56356},description="The Javelins of Suramar! Wielded by Azshara herself, they contain immense magical power. She has always had a fondness for bestowing favors on her favorites, but I never suspected she would give one something so valuable as one of her Javelins. This foe must be formidable indeed. Nevertheless, <name>, we cannot let this opportunity pass us. Defeat the handmaiden and retrieve the relic!",objectivesText="Retrieve the Javelin of Suramar . Progress: We cannot let her get away.",rewardGold=468000,rewardXP=8520,rewardItems={168212},rewardCurrencies={{id=1553,amount=750}},starts={{npcID=152316}},ends={{npcID=152316}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55486,55488},questLines={{id=938,name="Turning the Tide",orderIndex=5,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=44,flags=0}},campaigns={{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55490] = {id=55490,name="We'll Poke Their Eye Out",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55469,55482,55485,55486,55488,55489,55490,55799,56356},series={55799},description="The Javelins were some of Suramar's finest creations before the Sundering. Their magic is ancient and potent. Perhaps strong enough to defeat Azshara's wards. Hurry back to Newhome. We must tell the others of our success here. You have done well.",objectivesText="Return to Lor'themar Theron in Newhome.",rewardGold=23400,rewardXP=850,starts={{npcID=152316}},ends={{npcID=151848}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55489},questLines={{id=938,name="Turning the Tide",orderIndex=6,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=45,flags=0}},campaigns={{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55497] = {id=55497,name="A Friendly Face",level=50,requiredLevel=50,faction="both",categories={"legendary","campaign"},flags={},sharable=true,expansion=7,zoneID=9667,mapID=1473,storyline={55374,55400,55407,55425,55497,55533,55618,55851,57010},description="An essence of black dragonflight magic is not to be trifled with, <name>. My flight has been the pawn of dark forces in the past. I owe it to my fallen kin to see that our power is never used for evil again. I would like to journey with you and meet your allies. Perhaps my knowledge can help you use this essence to defend our world.",objectivesText="Meet with Spiritwalker Ebonhorn and Magni Bronzebeard in the Chamber of Heart. Progress: Was MOTHER's analysis correct?",rewardGold=468000,rewardXP=8520,rewardItems={168611},starts={{npcID=152385}},ends={{npcID=152385}},mapCandidates={npc={},zone={9667}},questGiverID=152385,questTurnInID=152385,questType="standard",sourceQuests={55425},questLines={{id=923,name="Empowering the Heart",orderIndex=6,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=16,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=17,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=923,questLineOrder=22,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=2,title="War Campaign",questLineID=923,questLineOrder=24,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0},{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=2215,db2PoiUiMapID=1473},
[55498] = {id=55498,name="The Shimmering Crystal",level=1,requiredLevel=1,faction="alliance",categories={},flags={"repeatable","weekly"},sharable=false,expansion=7,zoneID=7332,storyline={55498},description="Though the crystal appears familiar at first, upon contact with your finger it reveals itself as so much more. A grand, lost civilization appears in front of you. Fixtures of gold shimmer in every direction, bright feathers of purple occasionally falling from overhead. You hear the distant sounds of battle, culminating in a thunderous explosion that overwhelms all of your senses and turns your vision white. When your vision returns, you feel something within you pulling you toward Ashran .",objectivesText="Bring the Shimmering Timewarped Crystal to Tempra in Stormshield.",rewardGold=309800,rewardXP=200,rewardItems={167921},rewardCurrencies={{id=1166,amount=500}},ends={{npcID=151955}},mapCandidates={npc={},zone={7332}},questType="standard",startItems={167921}},
[55499] = {id=55499,name="The Shimmering Crystal",level=1,requiredLevel=1,faction="horde",categories={},flags={"repeatable","weekly"},sharable=false,expansion=7,zoneID=7333,storyline={55499},description="Though the crystal appears familiar at first, upon contact with your finger it reveals itself as so much more. A grand, lost civilization appears in front of you. Fixtures of gold shimmer in every direction, bright feathers of purple occasionally falling from overhead. You hear the distant sounds of battle, culminating in a thunderous explosion that overwhelms all of your senses and turns your vision white. When your vision returns, you feel something within you pulling you toward Ashran .",objectivesText="Bring the Shimmering Timewarped Crystal to Kronnus in Warspear.",rewardGold=303800,rewardXP=200,rewardItems={167922},rewardCurrencies={{id=1166,amount=500}},ends={{npcID=151987}},mapCandidates={npc={},zone={7333}},questType="standard",startItems={167922}},
[55500] = {id=55500,name="Save A Friend",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55384,55385,55500},description="In the cave ahead is where they are holding Mak . They torture us. They break us. Don't let them take her, too.",objectivesText="Kill the Herald of the Queen to release Mak .",rewardGold=234000,rewardXP=6815,rewardItems={170512},starts={{npcID=152047}},ends={{npcID=149902}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55385},questLines={{id=944,name="Making a Friend",orderIndex=2,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=23,flags=0}},campaigns={{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55503] = {id=55503,name="The Direhorn and the Saurid",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={55247,55252,55253,55254,55258,55462,55503,55504,55505,55506,55507,55795,55796,55797,55798},description="<A gentle voice enters your mind.> I am pleased with your efforts. He will not soon forget the kindness you have shown him, and so he will not soon forget me. Now your journey will take you south. I can no longer sense one of my wayshrines. If you can determine what has happened to it and restore it, I would be grateful.",objectivesText="Discover the fate of the central wayshrine. Progress: What did you learn?",rewardGold=234000,rewardXP=6815,starts={{npcID=154607}},ends={{npcID=154607}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={55504},questLines={{id=935,name="How to Train Your Direhorn",orderIndex=5,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[55504] = {id=55504,name="Wayshrines of Zuldazar",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={55247,55252,55253,55254,55258,55462,55503,55504,55505,55506,55507,55795,55796,55797,55798},description="<A calm but thunderous voice enters your mind.> My child grows under your care. I am pleased. Now, I would have your aid. There was a time long ago when the roads of Zandalar were under my protection. Those who walked them gave praise, and in return I gave them my blessing. Fewer wander now. My shrines remain, their purpose forgotten. You will help me to restore them. Begin in the north. See to the wayshrine there. If you find any lost travelers, see that they know my blessing through you.",objectivesText="Restore the northern wayshrine and assist any travelers you come across. Progress: Do you have de herbs?",rewardGold=234000,rewardXP=6815,rewardItems={168005},starts={{npcID=151257}},ends={{npcID=152041}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={55462},questLines={{id=935,name="How to Train Your Direhorn",orderIndex=6,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[55505] = {id=55505,name="Roo'li's Memory",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={55247,55252,55253,55254,55258,55462,55503,55504,55505,55506,55507,55795,55796,55797,55798},series={55506},description="I was going to be a Dinomancer. Roo'li was going to grow with me as I learned. < Koo'li shakes her head.> Dat future is gone now. Please, take him. Find a proper place to bury him. I... can't. De shame is too great.",objectivesText="Take Roo'li 's remains to Torcali . Progress: <The great direhorn loa stares down at you.> What do you bring me, <name>?",rewardGold=117000,rewardXP=3410,starts={{npcID=152115}},ends={{npcID=151257}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={55506},questLines={{id=935,name="How to Train Your Direhorn",orderIndex=8,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[55506] = {id=55506,name="One Road Ends",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={55247,55252,55253,55254,55258,55462,55503,55504,55505,55506,55507,55795,55796,55797,55798},series={55505},description="<A warm voice enters your mind.> There is one more wayshrine in this region that requires your attention. Follow this road until you near its end at the Port of Zandalar. It is there, at the start and end of so many journeys, that one of my most trafficked shrines was established. Restore it and see that any weary travelers have my blessing. We will speak again when you are finished.",objectivesText="Restore the southern wayshrine and assist any travelers you come across. Progress: Roo'li... Oh, Roo'li....",rewardGold=234000,rewardXP=6815,starts={{npcID=154607}},ends={{npcID=152115}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={55503},questLines={{id=935,name="How to Train Your Direhorn",orderIndex=7,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[55507] = {id=55507,name="Torcali's Blessing",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={55247,55252,55253,55254,55258,55462,55503,55504,55505,55506,55507,55795,55796,55797,55798},description="< Torcali 's voice enters your mind.> Your actions speak to your intentions, <name>. I can see that my child will have the care she needs to grow strong, and grow she will. In the coming days she will recover the strength that would have been hers, if nature had been allowed to take its course. Tend to her, earn her loyalty, and I will allow you to keep her at your side. This is my gift to you. You may go now. She will bring you to me when it is time.",objectivesText="Return the Child of Torcali to her nest in Warbeast Kraal.",rewardGold=117000,rewardXP=3410,starts={{npcID=151257}},ends={{npcID=151286}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={55505},questLines={{id=935,name="How to Train Your Direhorn",orderIndex=9,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[55508] = {id=55508,name="Victory in Wintergrasp",faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10176,mapID=123,storyline={55508},description="Commander Zanneth might be satisfied with a pile of Horde corpses at his feet, but controlling Wintergrasp is of the utmost importance to the Valiance Expedition. Make sure it remains in our control. However, don't think we'll just let you stand around while your allies do your dirty work for you. If you're not at least a second level recruit by the end of the battle, don't come back.",objectivesText="Win a Wintergrasp battleground match. You must have participated in the battle to be credited for the victory. Quest can only be auto completed while within the Battle for Wintergrasp .",rewardGold=341600,rewardXP=3440,starts={{npcID=152003}},ends={{npcID=31153}},mapCandidates={npc={123},zone={10176}},questGiverID=152003,questType="pvp"},
[55509] = {id=55509,name="Victory in Wintergrasp",faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10176,mapID=123,storyline={55509},description="While Dardosh might be content with slaying our foes, it is of the utmost importance that we control Wintergrasp Fortress. Do whatever it takes to ensure Wintergrasp is ours. However, don't think we'll just let you stand around while your allies do your dirty work for you. If you're not at least a second level recruit by the end of the battle, don't come back.",objectivesText="Win a Wintergrasp battleground match. You must have participated in the battle to gain credit for the victory. Quest can only be auto completed while within the Battle for Wintergrasp .",rewardGold=341600,rewardXP=3440,starts={{npcID=152004}},ends={{npcID=31151}},mapCandidates={npc={123},zone={10176}},questGiverID=152004,questType="pvp"},
[55510] = {id=55510,name="No Mercy for the Merciless",faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10176,mapID=123,storyline={55510},description="Welcome to Wintergrasp , <name>. Your mission is simple. Defeat ten of the Horde's finest. Now, go! Bring victory to the Alliance!",objectivesText="Commander Zanneth in Wintergrasp Fortress wants you to slay 10 members of the Horde. Quest can only be auto completed while within the Battle for Wintergrasp .",rewardGold=341600,rewardXP=3440,rewardCurrencies={{id=1602,amount=250}},starts={{npcID=151795}},ends={{npcID=31036}},mapCandidates={npc={123},zone={10176}},questGiverID=151795,questType="pvp"},
[55511] = {id=55511,name="Slay them all!",faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10176,mapID=123,storyline={55511},description="Welcome to the Wintergrasp , <name>. Warlord Garrosh demands one thing: Slay them all! Return to me when ten of the strongest members of the Alliance are dead.",objectivesText="Commander Dardosh in Wintergrasp wants you to slay 10 members of the Alliance. Quest can only be auto completed while within the Battle for Wintergrasp .",rewardGold=341600,rewardXP=3440,rewardCurrencies={{id=1602,amount=250},{id=1602,amount=150}},starts={{npcID=151611}},ends={{npcID=31091}},mapCandidates={npc={123},zone={10176}},questGiverID=151611,questType="pvp"},
[55516] = {id=55516,name="Spark of Genius",level=50,requiredLevel=50,faction="both",requiredClasses={3},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1161,storyline={54913,54915,54916,54917,54918,54919,54920,55195,55516},description="<name>, I require your assistance. A recent energy signature tripped several detection relays I installed after that unfortunate incident with Sargeras. Initial diagnostics suggest that these energies emanate from Hati, a legendary creature of lightning magic. This wolf was linked to the Titanstrike artifact, a weapon that proved instrumental in defeating the Legion! Hati's spirit is still bound to Titanstrike's core, so I'll need your help. Meet me at my library in the Storm Peaks right away!",objectivesText="Meet Mimiron at the Inventor's Library in the Storm Peaks.",rewardGold=23400,rewardXP=850,starts={{npcID=152002}},ends={{npcID=149736}},mapCandidates={npc={120,1161},zone={8670}},questType="standard",questLines={{id=862,name="Never Hunt Alone",orderIndex=1,flags=0}},db2PoiMapID=571,db2PoiUiMapID=120},
[55517] = {id=55517,name="Paint Vial: Big-ol Bronze",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={55517},description="< Marvelous Martini could make use of this item.>",objectivesText="Deliver the item to Marvelous Martini . Provided item:",rewardGold=2000,rewardItems={168001},starts={{npcID=150575,mapID=1462,x=0.3983,y=0.5302}},ends={{npcID=151777}},coords={mapID=1462,source="quest_giver",x=0.631,y=0.414},mapCandidates={npc={1462},zone={10290}},questType="standard",startItems={168001}},
[55519] = {id=55519,name="A Fresh Trauma",level=50,requiredLevel=50,faction="both",categories={"legendary"},flags={},sharable=false,expansion=7,zoneID=9667,mapID=198,storyline={55519,55520,55521},description="Azeroth is strugglin' tae survive, but new wounds are formin' at a rapid pace. I can sense her cries o' pain risin' from the north... in a place o' ancient power... <Magni closes his eyes, as if listening to an unseen voice.> By the Forge! Somethin's gone wrong in Mount Hyjal. The World Tree, Nordrassil, is in danger! Meet me there, $p. There's no time tae lose!",objectivesText="Meet Magni at Nordrassil in Mount Hyjal.",rewardGold=23400,starts={{npcID=152206}},ends={{npcID=152095}},mapCandidates={npc={198},zone={9667}},questGiverID=152206,questType="standard",sourceQuests={55522,56261},questLines={{id=920,name="8.2 Heart - HoA Progression - Level I",orderIndex=0,flags=0}},db2PoiMapID=1,db2PoiUiMapID=198},
[55520] = {id=55520,name="Healing Nordrassil",level=50,requiredLevel=50,faction="both",categories={"legendary"},flags={},sharable=false,expansion=7,zoneID=616,mapID=198,storyline={55519,55520,55521},description="Azerite elementals are runnin' wild, driven mad by Azeroth's pain. They're menacin' the spirits o' nature that protect the World Tree. The roots o' Nordrassil run deep, nurtured by these sacred waters. For the sake o' Azeroth's world soul, the tree must be defended. Quiet the restless elementals and use yer Heart o' Azeroth tae mend the wounds ye find. We cannae let Hyjal become another gapin' scar like Silithus!",objectivesText="Defeat Azerite elementals and seal Azeroth's injuries at Nordrassil. Progress: This just keeps gettin' worse. If too many wounds open up, we may not be able tae stop the cascade.",rewardGold=468000,starts={{npcID=152095}},ends={{npcID=152095}},mapCandidates={npc={198},zone={616}},questType="standard",sourceQuests={55519},questLines={{id=920,name="8.2 Heart - HoA Progression - Level I",orderIndex=1,flags=0}},db2PoiMapID=1,db2PoiUiMapID=198,db2QuestSortName="Engine of Innovation"},
[55521] = {id=55521,name="Do It the Azerite Way",level=50,requiredLevel=50,faction="both",categories={"legendary"},flags={},sharable=false,expansion=7,zoneID=9667,mapID=198,storyline={55519,55520,55521},description="Incredible! Ye stopped the wound from spreadin' before it could get out o' control! Nordrassil should be safe again, fer now. This is a good sign that we may just be able tae reverse all the damage done tae Azeroth. Let's get back tae the Chamber o' Heart, an' see if we can put any o' that azerite ye absorbed tae good use.",objectivesText="Return to the Chamber of Heart.",rewardGold=23400,rewardCurrencies={{id=1553,amount=1500}},starts={{npcID=152095}},ends={{npcID=152095}},mapCandidates={npc={198},zone={9667}},questTurnInID=152095,questType="standard",sourceQuests={55520},questLines={{id=920,name="8.2 Heart - HoA Progression - Level I",orderIndex=2,flags=0}},db2PoiMapID=2215,db2PoiUiMapID=1473},
[55522] = {id=55522,name="Return to the Heart",level=50,requiredLevel=50,faction="horde",categories={"legendary"},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={55522},description="Greetings, Champion of Azeroth. MOTHER's been monitorin' yer progress with the Heart of Azeroth, and is mighty pleased with the work you've done tae make it stronger. At least, we think she's pleased. It's difficult tae tell at times. Regardless, come back tae the Chamber of Heart when ye've got a chance. There's more that needs doin'.",objectivesText="Return to the Chamber of Heart.",rewardGold=23400,starts={{npcID=154465}},ends={{npcID=154465}},mapCandidates={npc={1165},zone={8670}},questTurnInID=154465,questType="standard",sourceQuests={57010},nextQuests={55519}},
[55523] = {id=55523,name="Bring Him Some...",level=50,requiredLevel=50,faction="none",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55523},description="<Mrrl points at your backpack then draws some pictures in the sand. He pulls out a pretty object from behind a rock then furiously points to himself then back at you then your bag. You believe it might want to make a trade.>",objectivesText="Locate murloc traders and obtain the items that Mrrl requires.",rewardGold=175500,rewardXP=5110,rewardItems={167902,167907,167913},mapCandidates={npc={},zone={10052}},questType="standard"},
[55524] = {id=55524,name="Bring Him Some...",level=50,requiredLevel=50,faction="none",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55524},description="<Mrrl points at your backpack then draws some pictures in the sand. He pulls out a pretty object from behind a rock then furiously points to himself then back at you then your bag. You believe it might want to make a trade.>",objectivesText="Bring Mrrl 5 Ghost Food , 5 Smelly Piles of Gloop , and 5 Sea Giant Foot Dust .",rewardGold=175500,rewardXP=5110,rewardItems={167904,167908,167909},mapCandidates={npc={},zone={10052}},questType="standard"},
