[55528] = {id=55528,name="Playtime's Over",level=10,requiredLevel=10,faction="both",categories={},flags={"daily","repeatable"},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55528},description="The troggs have been raiding our supplies since we got here, but now that we got some fire power you're going to put a stop to that! Let's teach them troggs to stay away from our stuff!",objectivesText="Eliminate 12 Troggs. Progress: Take out some troggs.",rewardGold=2000,rewardXP=1415,rewardItems={166846,166970,166971,246697},starts={{npcID=151006}},ends={{npcID=151006}},mapCandidates={npc={1462},zone={10290}},questType="standard",sourceQuests={54090},db2LabelIDs={5672}},
[55529] = {id=55529,name="No Backs",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55529},description="<The murloc seems hungry. Next to it is a series of crude drawings which seems like a shopping list. Perhaps you can help the creature.>",objectivesText="Bring Mrrl a Sweet Sea Vegetable , an Unidentified Mass , a Flatulent Fish , and a Slimy Naga Eyeball . Progress: Locate murloc traders and obtain the items that Mrrl requires.",rewardGold=234000,rewardXP=6815,rewardItems={167896,167906,167912,167915,170505},starts={{npcID=152084}},ends={{npcID=152084}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55530,55983}},
[55530] = {id=55530,name="A Safer Place",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55530},description="<The murloc seems to be in rough shape. Perhaps it would be safer with your allies in Newhome.>",objectivesText="Escort Mrrl back to Newhome.",rewardGold=234000,rewardXP=6815,rewardItems={141605},starts={{npcID=152084}},ends={{npcID=152084}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500}},
[55531] = {id=55531,name="What Will It Mine?",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={55531},description="<Although worn from repeated use, the pickaxe still seems salvageable. Perhaps there's something nearby that can be mined?>",objectivesText="Complete the Brinestone Cove event. Progress: What have you brought me?",rewardGold=468000,rewardXP=8520,rewardItems={167012,168037,168038,168048,168049,168050,168051,168081,168185,169612,169613},rewardCurrencies={{id=1721,amount=3}},ends={{npcID=153509},{npcID=153512}},coords={mapID=1355,source="quest_giver",x=0.378,y=0.556},mapCandidates={npc={1355},zone={10052}},questType="standard",startItems={168081}},
[55533] = {id=55533,name="MOTHER Knows Best",level=50,requiredLevel=50,faction="both",categories={"legendary","campaign"},flags={},sharable=true,expansion=7,zoneID=9667,mapID=1473,storyline={55374,55400,55407,55425,55497,55533,55618,55851,57010},series={55851},description="Now that this chamber's not fallin' tae pieces anymore, we can focus on makin' the Heart stronger! MOTHER says she's finished her fancy calculations. Have a word with her, champion. See if we can further empower the amazin' gift Azeroth gave ye.",objectivesText="Speak to MOTHER in the Chamber of Heart. Progress: Report: Ready for dissemination. Champion's response: Critical.",rewardGold=23400,rewardXP=850,starts={{npcID=152206}},ends={{npcID=152206}},mapCandidates={npc={},zone={9667}},questGiverID=152206,questTurnInID=152206,questType="standard",questLines={{id=923,name="Empowering the Heart",orderIndex=1,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=11,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=12,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=923,questLineOrder=22,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=2,title="War Campaign",questLineID=923,questLineOrder=24,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0},{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=2215,db2PoiUiMapID=1473},
[55534] = {id=55534,name="Rustbolt Gramophone",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={55534},description="<The large gramophone that you crafted is capable of blasting music across all of Rustbolt. Now, you just need to find a good place to install it.>",objectivesText="Install the gramophone in the Rustbolt bar, The Tipsy Tinkerer. Provided item:",rewardGold=2000,rewardXP=1415,rewardItems={167069,168047,168062,168063},ends={{npcID=155181}},startObjects={{mapID=1462,x=0.714,y=0.326}},coords={mapID=1462,source="quest_giver",x=0.702,y=0.305},mapCandidates={npc={1462},zone={10290}},questType="standard",startItems={167069}},
[55535] = {id=55535,name="The Tipsy Tinkerer",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,storyline={55535},description="The massive kegerator that you built should be able to house all of the Rustbolt Resistance's beverages. Find a spot to set it up in Rustbolt, and let the town know it's ready for use!",objectivesText="Install the Rustbolt Kegerator in Rustbolt's bar, The Tipsy Tinkerer.",rewardGold=169800,rewardXP=1415,rewardItems={168047,168063},startObjects={{mapID=1462,x=0.714,y=0.326}},endObjects={{mapID=1462,x=0.714,y=0.326}},coords={mapID=1462,x=0.714,y=0.326},mapCandidates={npc={},zone={}},questType="standard",startItems={168047}},
[55558] = {id=55558,name="A Bolt Hole",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55558,55560,55561,55565,55569,55570,55571,55573,55574,55694,56325,56358,56741},description="<name>, we must seek out a powerful weapon to combat the naga who guard the Tidal Conflux. I am certain such an object would be in the hands of one of Azshara's minions. Thanks to our new allies, we've tracked down the location of one of her handmaidens within the ruins of Zin-Azshari. The journey will be quite dangerous. Thankfully our allies have a location nearby that we can use as a staging ground. I've marked the location on your map, meet with me there as soon as you can.",objectivesText="Meet with Shandris Feathermoon at Utama's Stand.",rewardGold=23400,rewardXP=850,starts={{npcID=153617}},ends={{npcID=153617}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56234},questLines={{id=975,name="Turning the Tide",orderIndex=0,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=39,flags=0}},campaigns={{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55560] = {id=55560,name="Utama's Vengeance",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55558,55560,55561,55565,55569,55570,55571,55573,55574,55694,56325,56358,56741},description="We Ankoan are a small tribe. There are not that many of us remaining. This place was once overrun with makrura, before Utama. They tried to hide here, from the naga, but found the makrura. They fell, in battle, to the Kil'karrok. If you wish to show your dedication to the Ankoan, become a force of vengeance in Utama's memory. Destroy the makrura.",objectivesText="Kill 10 Makrura. Progress: We remember Utama. And honor their memory here.",rewardGold=234000,rewardXP=6815,starts={{npcID=151000}},ends={{npcID=151000}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55558},questLines={{id=975,name="Turning the Tide",orderIndex=1,flags=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55561] = {id=55561,name="What Remains of Zin-Azshari",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55558,55560,55561,55565,55569,55570,55571,55573,55574,55694,56325,56358,56741},description="Zin-Azshari, once the capital of night elf civilization, was lost during the Sundering. Queen Azshara betrayed her people and allowed N'Zoth to corrupt them, turning them into naga. It has now fallen into ruin and chaos. We must see what it has become. Meet me by the statue of Azshara.",objectivesText="Meet Shandris at the statue of Azshara.",rewardGold=23400,rewardXP=850,starts={{npcID=153617}},ends={{npcID=153617}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55558},questLines={{id=975,name="Turning the Tide",orderIndex=2,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=40,flags=0}},campaigns={{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55565] = {id=55565,name="Shoring Up Mana Reserves",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55558,55560,55561,55565,55569,55570,55571,55573,55574,55694,56325,56358,56741},description="Holding back the tide walls is not an easy task, even using the Tidestone. The ebb and flow of the magical energies in the area are too inconsistent. We need to shore up our magical reserves, which requires mana batteries, if you will. The befouled elementals along the canal here are created with exactly the elemental cores we need. The goal is two fold. Clearing out the befouled elementals, before their corruption spreads, but also retrieving their cores, so we can keep the water at bay.",objectivesText="Collect 10 Elemental cores . Progress: How goes your hunt?",rewardGold=234000,rewardXP=6815,rewardItems={168241},starts={{npcID=153617}},ends={{npcID=153617}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55561},questLines={{id=975,name="Turning the Tide",orderIndex=3,flags=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55569] = {id=55569,name="Echoes of Pain",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55558,55560,55561,55565,55569,55570,55571,55573,55574,55694,56325,56358,56741},description="These spirits... they are the Highborne. They were those Azshara held close. Azshara often played favorites, but these people... they were her favorites. I do not know why their spirits are here. We should investigate further. See if you can communicate with them and find out why their spirits cling to these ruins. How could she abandon them?",objectivesText="Speak with the spirits who wander around the Highborne Estates.",rewardGold=234000,rewardXP=6815,starts={{npcID=153617}},ends={{npcID=153617}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55560,55565,55694},questLines={{id=975,name="Turning the Tide",orderIndex=4,flags=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55570] = {id=55570,name="Secrets in the Ruins",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55558,55560,55561,55565,55569,55570,55571,55573,55574,55694,56325,56358,56741},description="This was once a place of great power. The highborne who lived here would host lavish parties, living in splendor. Zin-Azshari was once on the shores of the Well of Eternity and drew powerful mages from all over the empire to study here. I suspect, despite the many years at the bottom of the sea, there are still treasures and powerful artifacts hidden away here. Speak with the spirits that remain and see what you can find. There must be something to help us overcome the Guardian of the Tidestone.",objectivesText="Search for items of power. Progress: What have you discovered, <name>?",rewardGold=234000,rewardXP=6815,starts={{npcID=153617}},ends={{npcID=153617}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55560,55565,55694},questLines={{id=975,name="Turning the Tide",orderIndex=5,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=42,flags=0}},campaigns={{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55571] = {id=55571,name="Help Them See the Truth",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55558,55560,55561,55565,55569,55570,55571,55573,55574,55694,56325,56358,56741},series={56739},description="The information you have gleaned concerns me, <name>. These spirits cling to this place because they still, even now, believe in Azshara and her reign. She sold their lives to the void and they still believe in her. I know we have concerns that outweigh this, but I cannot leave them here like this. Show them. Confront them and tell them of Azshara's betrayal.",objectivesText="Confront the spirits about Azshara. Progress: Have the spirits been put to rest?",rewardGold=234000,rewardXP=6815,starts={{npcID=153617}},ends={{npcID=153617}},mapCandidates={npc={1355},zone={10052}},questTurnInID=153617,questType="standard",sourceQuests={55569,55570},questLines={{id=975,name="Turning the Tide",orderIndex=6,flags=0}},db2PoiMapID=1718,db2PoiUiMapID=1499},
[55573] = {id=55573,name="Purging the Defilers",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55558,55560,55561,55565,55569,55570,55571,55573,55574,55694,56325,56358,56741},description="Azshara always did need everything to be about her. Everything had to have her name on it. Everything was for her glory. She forgot our people's connection to Elune. Or perhaps she believed it did not matter? Azshara and her minions have too long defiled this place with their heresy. Let us show them Elune's vengeance.",objectivesText="Purge the naga from Elun'alor.",rewardGold=234000,rewardXP=6815,starts={{npcID=153617}},ends={{npcID=153617}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55569,55570},questLines={{id=975,name="Turning the Tide",orderIndex=7,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=43,flags=0}},campaigns={{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55574] = {id=55574,name="The Javelins of Azshara",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55558,55560,55561,55565,55569,55570,55571,55573,55574,55694,56325,56358,56741},series={56325,56741},description="These spirits keep speaking of the Javelins of Azshara. At first, I believed it to be referring to the handmaidens, who are currently holed up in Elun'alor. But -- now I think they are referring to the Javelins of Suramar . They were powerful weapons -- long thought lost. Azshara does like to claim things as her own. We need to defeat her handmaiden in Elun'alor regardless. Seizing the Javelins would be an amazing stroke of fortune.",objectivesText="Kill the Handmaiden of Azshara. Progress: Killing her handmaidens will drive the naga back and out of Zin-Azshari.",rewardGold=468000,rewardXP=8520,rewardItems={168212},rewardCurrencies={{id=1553,amount=750}},starts={{npcID=153617}},ends={{npcID=153617}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55573,56739},questLines={{id=975,name="Turning the Tide",orderIndex=8,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=44,flags=0}},campaigns={{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55575] = {id=55575,name="One Gnome's Trash",level=10,requiredLevel=10,faction="both",categories={},flags={"daily","repeatable"},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55575},description="The garbage in these trash heaps is full of rare metals : Dalaranium, Suramarite, even Gnomeisium! I've not seen this much easy gold to be had, since they left the vault door open in Boralus! You help me collect some of the metal, and my friend Gao will sell it on the black market. I've got a device that can tear the metal right out of the trash!",objectivesText="Collect 100 rare metals using the rare metal collector . Progress: There's gold to be made!",rewardGold=238680,rewardXP=1415,rewardItems={166846,166970,166971,168183,168184,168204,170148,174926,246697},starts={{npcID=152499}},ends={{npcID=152499}},mapCandidates={npc={1462},zone={10290}},questType="standard",questLines={{id=963,name="Visit from Moxie",orderIndex=0,flags=0}},db2LabelIDs={5672},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55578] = {id=55578,name="Tol Dagor: Jewel of the Tides",level=50,requiredLevel=50,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=9327,mapID=895,storyline={55578},description="<As you peer at the shrine in front of you, you can't help but revel at the construction of it. Seamlessly constructed with azure jewels placed just so in a radial pattern, collapsing towards a single point. A single, empty point. An absence you assume to be a mistake. Quickly surveying the area for something that might fit there, you find nothing. However, there appears to be a drunk here shouting at the shrine. Perhaps he might know the whereabouts of the shrine's missing piece.>",objectivesText="Speak with \"Slippery\" Salton and learn what you can about the missing centerpiece. Progress: <Perhaps finding the missing centerpiece will give you a clue into the shrine's operation?>",rewardGold=936000,rewardXP=13630,rewardItems={153716,155648},starts={{npcID=150893}},ends={{npcID=150893}},mapCandidates={npc={},zone={9327}},questGiverID=150893,questTurnInID=150893,questType="dungeon",sourceQuests={49599},questLines={{id=889,name="8.1.5 Jewelcrafting - Shrine of the Sea",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=895},
[55579] = {id=55579,name="Cracking the Surface",level=50,requiredLevel=50,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,mapID=942,storyline={55579},description="<Upon your investigation you discover that the shrine has a couple locations where jewels appeared to have been located, but no longer exist. Additionally, the center jewel appears to have several cracks in it as well. Checking your notes, the earthen mentions having prospected the jewels from a nearby mountain to the northwest. Perhaps you can prospect the earth in that area to find more of those jewels.>",objectivesText="Go to the Windshorn Hills and gather 20 Shard of Golden Beryl . Progress: <The placement of the jewels on this shrine appear to be placed in a rather intricate fashion.>",rewardGold=234000,rewardXP=6815,rewardItems={153716,155590},starts={{npcID=150898}},ends={{npcID=150898}},mapCandidates={npc={},zone={}},questGiverID=150898,questTurnInID=150898,questType="standard",sourceQuests={49599},questLines={{id=894,name="8.1.5 Jewelcrafting - Shrine of Storms",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=942},
[55580] = {id=55580,name="High Prospects",level=50,requiredLevel=50,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8721,mapID=896,storyline={55580},description="<Inspecting the shrine, you realize that several of the gems embedded on its surface are cracked and need to be replaced. Checking your notes, you find that the earthen had extracted the gems from some earth elementals to the south. Looking at your map, you wonder if he was referring to the now ruins of a once ancient settlement that has become littered with constructs and undead. Perhaps investigating there will yield some clues as to where to find these jewels.>",objectivesText="Investigate Gol Osigir for clues about the jewels that were used to construct the shrine. Progress: <All of the cracked jewels will definitely need to be replaced.>",rewardGold=234000,rewardXP=6815,rewardItems={153716,155661,155830},starts={{npcID=150896}},ends={{npcID=150896}},mapCandidates={npc={},zone={8721}},questGiverID=150896,questTurnInID=150896,questType="standard",sourceQuests={49599},questLines={{id=890,name="8.1.5 Jewelcrafting - Shrine of the Eventide",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[55581] = {id=55581,name="Sun-Speckled Dunes",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,mapID=864,storyline={55581},description="<Surveying the shrine, you believe that the sandy winds in this area have worn down the embedded gems, producing odd shapes and cracks in some. Looking at your notes, the earthen mentions coming across dunes sprinkled with orange gems. He said it reminded him of the soft sunlight in this area. Checking your notes, it appears that these dunes were located south of your current location.>",objectivesText="Go to the location on your map where you believe these gems to be and recover 8 of them. Polish and shape them when you've collected enough. Progress: <These gems have a very strong structure. Time, in addition to the winds, must have also taken its toll on them.>",rewardGold=234000,rewardXP=6815,rewardItems={153716,155664,155665},starts={{npcID=150895}},ends={{npcID=150895}},mapCandidates={npc={},zone={}},questGiverID=150895,questTurnInID=150895,questType="standard",sourceQuests={49584},questLines={{id=892,name="8.1.5 Jewelcrafting - Shrine of the Sands",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=864},
[55582] = {id=55582,name="Atal'Dazar: Not All That Glitters...",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=9028,mapID=862,storyline={55582},description="<As you observe the shrine, it's quite clear that the central jewel is badly broken and in need of replacement. You reference your notes on the shrine and discover that these jewels came from a \"golden sanctuary\". Given your location, that can only mean Atal'Dazar. Perhaps you could find a replacement from that ancient city.>",objectivesText="Travel to Atal'Dazar and find a replacement for the broken jewel. Progress: <When you're done replacing the central gem, you think you might still be able to sell the old one.>",rewardGold=936000,rewardXP=13630,rewardItems={153716,155666},starts={{npcID=150894}},ends={{npcID=150894}},mapCandidates={npc={},zone={9028}},questGiverID=150894,questTurnInID=150894,questType="dungeon",sourceQuests={49584},questLines={{id=893,name="8.1.5 Jewelcrafting - Shrine of Nature",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[55583] = {id=55583,name="Out With the Old",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,mapID=863,storyline={55583},description="<Upon inspection of the shrine, you notice something... familiar. The cut of the gems looks like a primitive or simple version of the way you've learned to cut rubellites. It's clear though that time has had its way with these gems, some eroded and chipped in places. Repairing this shrine may be as simple as replacing the old gems with newer ones of the same type and cut.>",objectivesText="Cut 4 Natant Rubellites and replace the old ones with the new. Progress: <Interesting that the cut should be so similar, you wonder how the design has persisted all these years.>",rewardGold=23400,rewardXP=850,rewardItems={153714,153716,158639,158640,158642,158643,158644,158645,158648,158649,160207},starts={{npcID=150897}},ends={{npcID=150897}},mapCandidates={npc={},zone={}},questGiverID=150897,questTurnInID=150897,questType="standard",sourceQuests={49584},questLines={{id=895,name="8.1.5 Jewelcrafting - Shrine of the Dawning",orderIndex=0,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[55585] = {id=55585,name="A Promising Beginning",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={49570,49571,49572,49573,49574,49575,49576,49577,49584,55585,55586,55590},description="<The shrine now repaired, you find yourself eager to seek out the next shrine. Perhaps Samuel has come across more locations.>",objectivesText="Return to Samuel D. Colton III in Boralus and report on your discovery.",rewardGold=23400,rewardXP=850,starts={{npcID=152489}},ends={{npcID=152489}},mapCandidates={npc={},zone={8568}},questGiverID=152489,questTurnInID=152489,questType="standard",sourceQuests={49577},questLines={{id=887,name="8.1.5 Jewelcrafting - Alliance",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[55586] = {id=55586,name="Polished Up",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={49570,49571,49572,49573,49574,49575,49576,49577,49584,55585,55586,55590},description="<Samuel will surely want to hear about your progress on this shrine. You feel as though you should report back to him as soon as you're able.>",objectivesText="Return to Samuel D. Colton III in Boralus and report on your discovery.",rewardGold=23400,rewardXP=850,rewardItems={171828},starts={{npcID=152497}},ends={{npcID=152497}},mapCandidates={npc={},zone={8568}},questGiverID=152497,questTurnInID=152497,questType="standard",sourceQuests={49576},questLines={{id=887,name="8.1.5 Jewelcrafting - Alliance",orderIndex=7,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[55590] = {id=55590,name="Setting Things Right",level=50,requiredLevel=50,faction="alliance",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8568,mapID=1161,storyline={49570,49571,49572,49573,49574,49575,49576,49577,49584,55585,55586,55590},description="<Samuel will surely be interested to hear about your investigation into this shrine. Most assuredly the part where you had to fight your way through a prison.>",objectivesText="Return to Samuel D. Colton III in Boralus and report on your discovery.",rewardGold=23400,rewardXP=850,starts={{npcID=152495}},ends={{npcID=152495}},mapCandidates={npc={},zone={8568}},questGiverID=152495,questTurnInID=152495,questType="standard",sourceQuests={49575},questLines={{id=887,name="8.1.5 Jewelcrafting - Alliance",orderIndex=10,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1161},
[55591] = {id=55591,name="Expedition Demolisher",level=10,requiredLevel=10,faction="none",sharable=false,expansion=7,zoneID=7503,mapID=650,mapCandidates={npc={},zone={7503}},questType="standard"},
[55592] = {id=55592,name="A Promising Beginning",level=50,requiredLevel=50,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={49581,49582,49583,49585,49586,49587,49588,49589,49599,55592,55594,55596},description="<The shrine now repaired, you find yourself eager to seek out the next shrine. Perhaps Seshuli has come across more locations.>",objectivesText="Return to Seshuli in Dazar'alor and report on your discovery.",rewardGold=23400,rewardXP=850,starts={{npcID=152490}},ends={{npcID=122695}},mapCandidates={npc={1165},zone={8670}},questGiverID=152490,questType="standard",sourceQuests={49583},questLines={{id=888,name="8.1.5 Jewelcrafting - Horde",orderIndex=4,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[55593] = {id=55593,name="Insight into Our Enemies",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55593,55595,55597,55598,55599,55600,55601,55860,55861,55937,56037,56038,56039,56234},description="There's no telling what awaits us within this land. We cannot press forward without first knowing exactly what we're up against. Our new allies have long been embattled with the naga. They would know best how to navigate these waters. Speak with Blademaster Okani and see if they can provide some insight into how our enemies operate.",objectivesText="Speak to Blademaster Okani to learn more about the naga within Nazjatar .",rewardGold=23400,rewardXP=850,starts={{npcID=150101}},ends={{npcID=151000}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={54975},questLines={{id=942,name="Secrets in the Sea",orderIndex=0,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=25,flags=0}},campaigns={{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55594] = {id=55594,name="Polished Up",level=50,requiredLevel=50,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={49581,49582,49583,49585,49586,49587,49588,49589,49599,55592,55594,55596},description="< Seshuli will surely want to hear about your progress on this shrine. You feel as though you should report back to her as soon as you're able.>",objectivesText="Return to Seshuli in Dazar'alor and report on your discovery.",rewardGold=23400,rewardXP=850,rewardItems={171828},starts={{npcID=152493}},ends={{npcID=122695}},mapCandidates={npc={1165},zone={8670}},questGiverID=152493,questType="standard",sourceQuests={49581},questLines={{id=888,name="8.1.5 Jewelcrafting - Horde",orderIndex=7,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[55595] = {id=55595,name="Deteriorating Knowledge",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55593,55595,55597,55598,55599,55600,55601,55860,55861,55937,56037,56038,56039,56234},description="My clan came to Nazjatar , eager to destroy the naga queen. We were not prepared for the darkness that she commands. Our scouts knew this land best, but their knowledge now deteriorates as their minds are controlled by Azshara's forces. Find and free our scouts, and you may still have a chance to access their knowledge.",objectivesText="Rescue Imara, Adaru , and Umai from the clutches of mind-leeching Zoatroids.",rewardGold=234000,rewardXP=6815,starts={{npcID=151000}},ends={{npcID=153496}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55593},questLines={{id=942,name="Secrets in the Sea",orderIndex=1,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=26,flags=0}},campaigns={{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55596] = {id=55596,name="Setting Things Right",level=50,requiredLevel=50,faction="horde",requiredProfessions={"jewelcrafting"},categories={},flags={},sharable=true,expansion=7,zoneID=8670,mapID=1165,storyline={49581,49582,49583,49585,49586,49587,49588,49589,49599,55592,55594,55596},description="< Seshuli will surely be interested to hear about your investigation into this shrine. Most assuredly the part where you had to fight your way through Atal'Dazar.>",objectivesText="Return to Seshuli in Dazar'alor and report on your discovery.",rewardGold=23400,rewardXP=850,starts={{npcID=152496}},ends={{npcID=122695}},mapCandidates={npc={1165},zone={8670}},questGiverID=152496,questType="standard",sourceQuests={49582},questLines={{id=888,name="8.1.5 Jewelcrafting - Horde",orderIndex=10,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[55597] = {id=55597,name="Bound by Honor",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55593,55595,55597,55598,55599,55600,55601,55860,55861,55937,56037,56038,56039,56234},description="It is true that my clan has been battling the naga for generations, but it was only in recent times that we took the fight to Nazjatar . Our leader was slain by the vile queen, and now honor binds my clan to this deep ocean. We will avenge their death or die here trying. It is our way. Your mission aligns with our duty, so we will fight the naga together. Slay their forces and bring us one step closer to honoring our promise.",objectivesText="Kill 10 naga within Zanj'ir Wash and the Deepsea Slave Pens.",rewardGold=234000,rewardXP=6815,starts={{npcID=151000}},ends={{npcID=153499}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55593},questLines={{id=942,name="Secrets in the Sea",orderIndex=2,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=27,flags=0}},campaigns={{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55598] = {id=55598,name="What We Know of the Naga",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55593,55595,55597,55598,55599,55600,55601,55860,55861,55937,56037,56038,56039,56234},description="I owe you a debt. That much is clear. My mind still reels from the zoatroid's influence, but I fear the others suffer more visible wounds. Apply this salve to their wounds, and I will do my best to share what I know of the naga.",objectivesText="Tend to the Ankoan's wounds and hear what Adaru has to say about the naga. Progress: I will tell you what I know of the naga.",rewardGold=117000,rewardXP=3410,rewardItems={168948,169477,169478,169481},rewardChoices={169477,169478,169481},starts={{npcID=153496}},ends={{npcID=153496}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55595,55597},questLines={{id=942,name="Secrets in the Sea",orderIndex=3,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=28,flags=0}},campaigns={{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55599] = {id=55599,name="Scouting Undercover",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55593,55595,55597,55598,55599,55600,55601,55860,55861,55937,56037,56038,56039,56234},description="Entering the stronghold alone would be a death wish. The Zanj'ir slaughter outsiders on sight. The only way to get in without being killed is to appear to be under the effects of a zoatroid . Even then, the mind-shackled are put to work. You must obey all commands, or they will know your mind is still your own. Once the Zanj'ir believe you are mind-shackled, it should be easier to navigate their domain and uncover their secret.",objectivesText="Scout Zanj'ir Terrace while pretending to be mind-shackled.",rewardGold=23400,rewardXP=850,starts={{npcID=153496}},ends={{npcID=153936}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55598},questLines={{id=942,name="Secrets in the Sea",orderIndex=4,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=29,flags=0}},campaigns={{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55600] = {id=55600,name="Sating Snapdragons",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55593,55595,55597,55598,55599,55600,55601,55860,55861,55937,56037,56038,56039,56234},description="It's time for the snapdragons to feed, but it's a job best left to someone a little more expendable. The beasts will eat anything, including your arm if you don't move it away quickly enough. Luckily for you, they've developed a taste for Chitterspine Roe .",objectivesText="Collect Chitterspine Roe and feed it to Savage Snapdragons.",rewardGold=234000,rewardXP=6815,rewardItems={168753},starts={{npcID=153936}},ends={{npcID=153936}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55599},questLines={{id=942,name="Secrets in the Sea",orderIndex=5,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=30,flags=0}},campaigns={{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55601] = {id=55601,name="Coveted Crystals",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55593,55595,55597,55598,55599,55600,55601,55860,55861,55937,56037,56038,56039,56234},description="Locating the weapons cache should not be a problem once we have the proper tools. A little light and a lot of bioluminescent fluid is all that is needed. It all seems rather simple, does it not? But the key is in the Deepsea Crystal used to refract the light. The Bloodfin tribe covets these crystals, so you should have no trouble obtaining one.",objectivesText="Collect a Deepsea Crystal from Hoarder Moarrgl. Progress: Have you found the crystal?",rewardGold=468000,rewardXP=8520,rewardItems={168540},rewardCurrencies={{id=1721,amount=5}},starts={{npcID=153385}},ends={{npcID=153385}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56037},questLines={{id=942,name="Secrets in the Sea",orderIndex=10,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=35,flags=0}},campaigns={{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55602] = {id=55602,name="What Will It Lure?",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={55602},description="<Putrid and pungent, this lump of bait is the preferred food of skittering eels. Perhaps you can find infested waters nearby?>",objectivesText="Chum the Eel Infested Waters . Progress: What have you brought me?",rewardGold=468000,rewardXP=8520,rewardItems={168155,168157,168159,168650},rewardCurrencies={{id=1721,amount=3}},ends={{npcID=153509},{npcID=153512}},coords={mapID=1355,source="quest_giver",x=0.378,y=0.556},mapCandidates={npc={1355},zone={10052}},questType="standard",startItems={168155}},
[55605] = {id=55605,name="NOT USED",level=10,requiredLevel=10,faction="none",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55605},description="TBD Collect Spare Parts from anything on the island.",objectivesText="Collect 200 Spare Parts in Mechagon .",rewardGold=134000,rewardXP=200,rewardItems={166846,182489,182498,182507,182516,183744,184843,195219},mapCandidates={npc={},zone={10290}},questType="standard"},
[55608] = {id=55608,name="Shop Project",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={54083,54086,54922,54929,55373,55608,55622,55696,55697,55753,56168,56175},description="As a reward for all your help here, I was planning to fix this old mechaspider mount to give to you. I could use some more of your help though to get this project started! I'll need parts off a few of the bots nearby, and maybe you could talk to Cork Stuttgard at Bondo's Yard and see if you can get a Mechanobot Ignition system.",objectivesText="Acquire Shellsteel Plating, Multi-Leg Chaindrive , and a Mechanobot Ignition . Progress: Did you find those parts yet?",rewardGold=2000,rewardXP=1415,rewardItems={168113,168114,168115,168327,168827},starts={{npcID=150573}},ends={{npcID=150573}},mapCandidates={npc={1462},zone={10290}},questType="standard",sourceQuests={55736},questLines={{id=925,name="Making a Mount",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55609] = {id=55609,name="Operation: Mechagon - The Mechoriginator",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={54087,54088,54945,54946,54947,54992,55040,55096,55609,55645,55729,55730,55731,55734,55736,55995,56131},description="My father's madness won't be contained to this island. King Mechagon is creating a massive device capable of reversing the Curse of Flesh across the entirety of Azeroth! Any races forged by the Titans will return to their original state. For us gnomes, that means fully mechanical. For dwarves and troggs, stone. Vrykul, iron. The list goes on, but most races aren't even ON the list. Anything not forged by the titans will be completely obliterated. We must stop King Mechagon before it's too late!",objectivesText="Enter Mechagon and defeat King Mechagon . Progress: King Mechagon 's madness threatens all of us. We must stop my father!",rewardGold=1029600,rewardXP=2830,rewardItems={169610},rewardCurrencies={{id=1553,amount=2500}},starts={{npcID=149816}},ends={{npcID=149816}},mapCandidates={npc={1462},zone={10225}},questType="dungeon",sourceQuests={55736},questLines={{id=940,name="Expedition to Mechagon",orderIndex=16,flags=0},{id=941,name="Expedition to Mechagon",orderIndex=18,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55617] = {id=55617,name="Expedition Siege Engine",level=10,requiredLevel=10,faction="none",sharable=false,expansion=7,zoneID=7503,mapID=650,mapCandidates={npc={},zone={7503}},questType="standard"},
[55618] = {id=55618,name="The Heart Forge",level=50,requiredLevel=50,faction="both",categories={"legendary","campaign"},flags={},sharable=false,expansion=7,zoneID=9667,mapID=1473,storyline={55374,55400,55407,55425,55497,55533,55618,55851,57010},series={57010},description="Rise in Heart Forge energy levels indicates presence of black dragon essence. Recommendation: Initiate Heart Forge activation sequence.",objectivesText="Speak with MOTHER to activate the Heart Forge . Progress: Data calculations complete. Awaiting initiation of forge activation sequence.",rewardGold=23400,rewardXP=850,rewardItems={168611},starts={{npcID=152194}},ends={{npcID=152194}},mapCandidates={npc={},zone={9667}},questGiverID=152194,questTurnInID=152194,questType="standard",sourceQuests={55497},questLines={{id=923,name="Empowering the Heart",orderIndex=7,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=17,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=18,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=923,questLineOrder=22,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=2,title="War Campaign",questLineID=923,questLineOrder=24,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0},{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=2215,db2PoiUiMapID=1473},
[55619] = {id=55619,name="Upgrade Your Vehicle (Optional)",level=10,requiredLevel=10,faction="none",sharable=false,expansion=7,zoneID=7503,mapID=650,mapCandidates={npc={},zone={7503}},questType="standard"},
[55622] = {id=55622,name="Drive It Away Today",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={54083,54086,54922,54929,55373,55608,55622,55696,55697,55753,56168,56175},description="The mount's all polished up and looking great. We are almost done! I gave the Powercore Schematics to PASCAL-K1N6. He's ready to build us a new 500S-Cybergenic Powercore , once you get him the parts. We install that powercore and you can drive this bot away today!",objectivesText="500S-Cybergenic Powercore obtained. Progress: Did you get the core?",rewardGold=257400,rewardXP=1415,rewardItems={166970,167064,168327,168823,168827,169610},starts={{npcID=150573}},ends={{npcID=150573}},mapCandidates={npc={1462},zone={10290}},questType="standard",sourceQuests={55753},questLines={{id=925,name="Making a Mount",orderIndex=11,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55625] = {id=55625,name="Pearls of Unimaginable Power",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=10052,mapID=1355,description="Thousands of years ago, when the Well of Eternity was destroyed and this land plummeted to the depths of the ocean, a great storm of magical energy was unleashed. Remnants of this magical energy still exist today. Gather the pearls from the ancient mana-infused clams. These enchanted pearls may be powerful weapons in our fight against the naga!",rewardGold=234000,rewardCurrencies={{id=1721,amount=3},{id=1750,amount=100},{id=1721,amount=2}},starts={{npcID=152407}},ends={{npcID=152407}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56156},worldTaskTitle="Pearls of Unimaginable Power",db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55630] = {id=55630,name="Let's Get It Started",level=10,requiredLevel=10,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={55096,55609,55630,55632,55646,55647,55648,55649,55650,55651,55652,55685,55729,55730,55731,55734,55736,55995,56131},description="Those gnomes think busting up machinery is gonna stop a goblin like me from figuring out what all the tech in this place does? I ain't never seen a hunk of junk so busted up that ol' Skaggit and I can't get running smoother than the day it was made. Tell ya what. You head around with Skaggit and see what you can piece back together. Meanwhile, I'll have a chat with our gnome friend here and see what she knows about all this tech.",objectivesText="Repair the vault's machinery. Progress: We'll have this place up and running in no time.",rewardGold=2000,rewardXP=1415,starts={{npcID=149809}},ends={{npcID=149809}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={55648},questLines={{id=941,name="Expedition to Mechagon",orderIndex=3,flags=0},{id=5384,name="Welcome to Mechagon",orderIndex=4,flags=0},{id=6061,name="Mechagon Intro",orderIndex=0,flags=0}},campaigns={{id=222,title="Mechagon",questLineID=5384,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6061,questLineOrder=2}},db2PoiMapID=1643,db2PoiUiMapID=895},
[55632] = {id=55632,name="You Must be This Height",level=10,requiredLevel=10,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=8567,mapID=895,storyline={55096,55609,55630,55632,55646,55647,55648,55649,55650,55651,55652,55685,55729,55730,55731,55734,55736,55995,56131},description="You and the Greasemonkeys got this machine up and running even faster than I expected. The gnome we captured is keeping her mouth shut, but that shouldn't be a problem. I can take it from here. Let me know when you're ready. I'll crank up this machine to max and we'll finally see what it can do. I hope it prints gold coins...",objectivesText="Tell Gazlowe to activate the device. Progress: That's the best use of a gnome I've ever seen!",rewardGold=257400,rewardXP=1770,rewardItems={168218},starts={{npcID=149809}},ends={{npcID=152652}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={55630},questLines={{id=941,name="Expedition to Mechagon",orderIndex=4,flags=0},{id=5384,name="Welcome to Mechagon",orderIndex=5,flags=0},{id=6061,name="Mechagon Intro",orderIndex=1,flags=0}},campaigns={{id=222,title="Mechagon",questLineID=5384,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6061,questLineOrder=2}},db2PoiMapID=1643,db2PoiUiMapID=895},
[55633] = {id=55633,name="The Sunken Chest",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={55633},description="<This waterlogged chest appears to be in salvageable condition, but it is too heavy to move due to the contents within. The lock on the device appears to be operational. Perhaps there is a key nearby...>",objectivesText="Locate the Brass Key at the bottom of the lagoon. Progress: <The chest is locked and requires a key.>",rewardGold=234000,rewardItems={168167},rewardCurrencies={{id=1721,amount=3},{id=1748,amount=100},{id=1721,amount=2}},startObjects={{objectID=325795,mapID=1355,x=0.457,y=0.837}},endObjects={{objectID=325795,mapID=1355,x=0.457,y=0.837}},coords={mapID=1355,x=0.457,y=0.837},mapCandidates={npc={},zone={10052}},questType="standard",sourceQuests={56156},worldTaskTitle="The Sunken Chest",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55635] = {id=55635,name="A Voice on the Wind",level=10,requiredLevel=10,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8721,mapID=896,storyline={54161,55635},description="<A distant, mysterious voice fills your mind.> My enchantments are not lost... Find me... Drustvar... Fallhaven...",objectivesText="Seek out the source of the mysterious voice in Drustvar.",rewardGold=25740,rewardXP=175,starts={{npcID=147014}},ends={{npcID=146053}},mapCandidates={npc={896},zone={8721}},questGiverID=147014,questType="standard",sourceQuests={54161},questLines={{id=910,name="8.1.5 Enchanting - Horde",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=896},
[55636] = {id=55636,name="A Life's Work",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=10052,mapID=1355,description="I spent more than one-thousand years researching the mysteries of the arcane before the Great Sundering tore our world apart. I perished amidst the destruction and my work was lost. Search the area for my ancient writings and put my spirit to rest...",rewardGold=234000,rewardCurrencies={{id=1721,amount=3},{id=1750,amount=100},{id=1721,amount=2}},starts={{npcID=325853}},ends={{npcID=325853}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56156},worldTaskTitle="A Life's Work",db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55637] = {id=55637,name="Poor, Unfortunate Souls",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={55637},description="Countless lives were lost in the Great Sundering when this great city was plunged into the depths of the abyss. The fortunate among us died quickly in the explosion, but some survived only to cling onto dear life as the cold, unforgiving ocean waves crashed down upon them. Those poor, unfortunate souls suffer a fate worse than death to this day. They drown endlessly, forced to relive the torture of their death. Put them to rest so that they may have peace at last.",objectivesText="Put 8 Tortured Souls to rest. Progress: I hear them as we speak... crying out for help. Yet, I am powerless to save them...",rewardGold=234000,rewardCurrencies={{id=1721,amount=3},{id=1748,amount=100},{id=1721,amount=2}},starts={{npcID=152494}},ends={{npcID=152494}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56156},worldTaskTitle="Poor, Unfortunate Souls",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55638] = {id=55638,name="Making Kelpberry Wine",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55638},description="<This is an empty kelpberry juice cask. There is someone nearby that may appreciate a refill.>",objectivesText="Deliver Kelpberry Wine to Maedin in Maedin 's Challenge. Progress: Did you bring me something?",rewardGold=309800,rewardItems={168173,168174},rewardCurrencies={{id=1721,amount=3},{id=1745,amount=100},{id=1721,amount=2}},ends={{npcID=150344}},startObjects={{objectID=325869,mapID=1355,x=0.595,y=0.42}},coords={mapID=1355,source="quest_giver",x=0.582,y=0.356},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500},worldTaskTitle="Making Kelpberry Wine",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55639] = {id=55639,name="Who Lurks in the Pit",level=6,requiredLevel=6,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56344,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59347,59349,59350,59352,59354,59355,59356,60168,85678},description="The winds whisper of people being trapped in the pit. It seems there may be more members of the expedition within. I fear it will be up to you to make the descent and save the survivors. There should be six in total... though the winds say that one is farther away from the others... With our luck, the last survivor is at the bottom of the pit. Good luck, <name>. And... make sure no spiders follow you back out.",objectivesText="Rescue 5 Trapped Expedition Members.",rewardGold=3440,rewardXP=1095,rewardItems={175203,175204,175205,175206,175234,175235,175236,175237},rewardChoices={175203,175234,175206,175237,175205,175236,175204,175235},starts={{npcID=156803}},ends={{npcID=156803}},mapCandidates={npc={},zone={10424}},questGiverID=156803,questTurnInID=156803,questType="standard",sourceQuests={55965},questLines={{id=926,name="The Missing Expedition",orderIndex=28,flags=0},{id=1072,name="What Lurks Below",orderIndex=2,flags=0},{id=5367,name="A Dark Ritual",orderIndex=21,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5367,questLineOrder=1,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[55640] = {id=55640,name="Vision of Stormwind",level=50,requiredLevel=50,faction="none",categories={},flags={"repeatable","weekly","rare"},sharable=false,expansion=7,zoneID=15942,mapID=2339,storyline={55640},description="Weaken N'Zoth by delving into his mind. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(55640)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(55640))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }",objectivesText="Complete the Vision of Stormwind.",mapCandidates={npc={},zone={15942}},questType="standard",db2Objectives={{text="Vision of Stormwind completed",amount=1,type=0,objectID=152112,orderIndex=0}},worldTaskTitle="Vision of Stormwind",db2PoiUiMapID=37,db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
[55645] = {id=55645,name="Princely Visit",level=10,requiredLevel=10,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=8567,mapID=1462,storyline={54087,54088,54945,54946,54947,54992,55040,55096,55609,55645,55729,55730,55731,55734,55736,55995,56131},description="This is it! The fabled Mechagon! The greatest discovery of our age, and you're here to witness me accomplish it! < Tinkmaster Overspark puffs out his chest, brushes off his robes, and smiles confidently.> I am ready to address the Mechagon people. You may accompany me.",objectivesText="Explore the nearby town with Tinkmaster Overspark . Progress: Mechagon is not like the legends you were told.",rewardGold=514800,rewardXP=1415,starts={{npcID=152484}},ends={{npcID=152851}},mapCandidates={npc={1462},zone={10290}},questType="standard",sourceQuests={54992},questLines={{id=940,name="Expedition to Mechagon",orderIndex=7,flags=0},{id=5376,name="Welcome to Mechagon",orderIndex=9,flags=0},{id=6060,name="Mechagon Intro",orderIndex=7,flags=0}},campaigns={{id=218,title="Mechagon",questLineID=5376,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6060,questLineOrder=0}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55646] = {id=55646,name="The Legend of Mechagon",level=10,requiredLevel=10,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1165,storyline={55096,55609,55630,55632,55646,55647,55648,55649,55650,55651,55652,55685,55729,55730,55731,55734,55736,55995,56131},description="Heya, $p. I was just tellin' Skaggit that I was hoping I'd run into you up here! I caught wind of an Alliance operation into some old vault that opened in Tiragarde Sound. In typical gnomish fashion, Tinkmaster Overspark is overreacting like crazy, claiming it's some lost connection to the gnome fairytale land of Mechagon . < Gazlowe scoffs.> I don't buy that for a second, but I am very interested in getting my hands on whatever tech's in that vault. You in?",objectivesText="Meet Gazlowe at the Abandoned Junkheap in Tiragarde Sound.",rewardGold=257400,rewardXP=1415,starts={{npcID=152522}},ends={{npcID=152578}},mapCandidates={npc={895,1165},zone={8670}},questType="standard",sourceQuests={57024},questLines={{id=941,name="Expedition to Mechagon",orderIndex=0,flags=0},{id=5384,name="Welcome to Mechagon",orderIndex=1,flags=0},{id=6061,name="Mechagon Intro",orderIndex=2,flags=0}},campaigns={{id=222,title="Mechagon",questLineID=5384,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6061,questLineOrder=2}},db2PoiMapID=1643,db2PoiUiMapID=895},
[55647] = {id=55647,name="A Quick Ear Hustle",level=10,requiredLevel=10,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10290,mapID=895,storyline={55096,55609,55630,55632,55646,55647,55648,55649,55650,55651,55652,55685,55729,55730,55731,55734,55736,55995,56131},description="Bad news. We're late. The Alliance was already crawling all over the vault when we got here. Lucky for us, some big commotion inside sent some of 'em running for the hills. Most of 'em are still down in that vault, though, including that crazy braggart Tinkmaster Overspark. Let's give 'em a few more minutes to clear out, so we don't have to go in guns blazing.",objectivesText="Wait for the Alliance to leave the vault. Progress: What'd they find down there?",rewardGold=257400,rewardXP=1415,starts={{npcID=152578}},ends={{npcID=152578}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={55646},questLines={{id=941,name="Expedition to Mechagon",orderIndex=1,flags=0},{id=5384,name="Welcome to Mechagon",orderIndex=2,flags=0},{id=6061,name="Mechagon Intro",orderIndex=3,flags=0}},campaigns={{id=222,title="Mechagon",questLineID=5384,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6061,questLineOrder=2}},db2PoiMapID=1643,db2PoiUiMapID=895},
[55648] = {id=55648,name="This is Our Vault Now",level=10,requiredLevel=10,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10290,mapID=895,storyline={55096,55609,55630,55632,55646,55647,55648,55649,55650,55651,55652,55685,55729,55730,55731,55734,55736,55995,56131},description="Looks like the coast is clear with Overspark gone. Let's get inside that vault and see what's really going on here. Mechagon or not, there'd better be some quality hardware in there to make this trip worth our time.",objectivesText="Lead Gazlowe 's crew into the vault.",rewardGold=257400,rewardXP=1415,starts={{npcID=152578}},ends={{npcID=149809}},mapCandidates={npc={895},zone={8567}},questType="standard",sourceQuests={55647},questLines={{id=941,name="Expedition to Mechagon",orderIndex=2,flags=0},{id=5384,name="Welcome to Mechagon",orderIndex=3,flags=0},{id=6061,name="Mechagon Intro",orderIndex=4,flags=0}},campaigns={{id=222,title="Mechagon",questLineID=5384,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6061,questLineOrder=2}},db2PoiMapID=1643,db2PoiUiMapID=895},
[55649] = {id=55649,name="Machinations for Mechagon",level=10,requiredLevel=10,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10290,mapID=895,storyline={55096,55609,55630,55632,55646,55647,55648,55649,55650,55651,55652,55685,55729,55730,55731,55734,55736,55995,56131},description="So Mechagon ain't just a fairy tale? Gotta admit I'm surprised. But, if the tech on that king is any indication of what they've got out there for us to swipe, I am very, very happy to be wrong! We can't rush into this. A good crew died today. That ain't happening again on my watch. Meet me and Skaggit back in Zuldazar Harbor, and we'll build this expedition up right.",objectivesText="Ride the Greasemonkey Skysneaker to Zuldazar Harbor.",rewardGold=280900,rewardXP=1415,starts={{npcID=152652}},ends={{npcID=152504}},mapCandidates={npc={895,1165},zone={8567}},questType="standard",sourceQuests={55632},questLines={{id=941,name="Expedition to Mechagon",orderIndex=5,flags=0},{id=5384,name="Welcome to Mechagon",orderIndex=6,flags=0},{id=6061,name="Mechagon Intro",orderIndex=5,flags=0}},campaigns={{id=222,title="Mechagon",questLineID=5384,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6061,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[55650] = {id=55650,name="Only the Best Will Do",level=10,requiredLevel=10,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10290,mapID=1165,storyline={55096,55609,55630,55632,55646,55647,55648,55649,55650,55651,55652,55685,55729,55730,55731,55734,55736,55995,56131},description="You heard Gazlowe. The boss wants this expedition to go smoothly. No cutting corners, no slush. I know you've worked with Gallywix in the past. We don't run our operations like that. We expect the best from our crews, so we pay 'em what they're worth and treat 'em well. In return, we got the best goblin crews on the planet, and they ain't goin' over to any competition. Here's a list of who and what we're gonna need to pull this off. Don't worry, Gazlowe'll cover all the costs.",objectivesText="Get everything needed to launch the expedition for Mechagon . Progress: Look, <name>, I ain't got time to hold your hand through all this. Figure it out or I'll find someone else who will.",rewardGold=257400,rewardXP=1415,rewardItems={200551},starts={{npcID=152505}},ends={{npcID=152505}},mapCandidates={npc={1165},zone={8670}},questType="standard",sourceQuests={55649},questLines={{id=941,name="Expedition to Mechagon",orderIndex=6,flags=0},{id=5384,name="Welcome to Mechagon",orderIndex=7,flags=0},{id=6061,name="Mechagon Intro",orderIndex=6,flags=0}},campaigns={{id=222,title="Mechagon",questLineID=5384,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6061,questLineOrder=2}},db2PoiMapID=1642,db2PoiUiMapID=1165},
[55651] = {id=55651,name="To Mechagon!",level=10,requiredLevel=10,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10290,mapID=1165,storyline={55096,55609,55630,55632,55646,55647,55648,55649,55650,55651,55652,55685,55729,55730,55731,55734,55736,55995,56131},description="Whatever's waiting for us on the shores of Mechagon , we're going to be ready for it with this crew. I don't hold any misconceptions about how that crazy king is going to welcome us. Guns blazin', I'm sure. So we're going in quietly on this submarine. Low profile'll keep us all safe. When you're ready to go, talk to Captain Krooz.",objectivesText="Talk with Captain Krooz to travel to Mechagon .",rewardGold=257400,rewardXP=1415,rewardItems={246701},starts={{npcID=152504}},ends={{npcID=152783}},mapCandidates={npc={1165,1462},zone={8670}},questType="standard",sourceQuests={55650},questLines={{id=941,name="Expedition to Mechagon",orderIndex=7,flags=0},{id=5384,name="Welcome to Mechagon",orderIndex=8,flags=0},{id=6061,name="Mechagon Intro",orderIndex=7,flags=0}},campaigns={{id=222,title="Mechagon",questLineID=5384,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6061,questLineOrder=2}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55652] = {id=55652,name="Prospectus Bay",level=10,requiredLevel=10,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={55096,55609,55630,55632,55646,55647,55648,55649,55650,55651,55652,55685,55729,55730,55731,55734,55736,55995,56131},description="Looks like we made it in unnoticed. Skaggit's crew can set up shop on that beach, but we gotta make sure it's safe for 'em to land first. Let's do a quick flyover to scout out how we're going to crack this place wide open. That town up on the hill looks promising...",objectivesText="Jetpack into Prospectus Bay with Gazlowe and the crew.",rewardGold=280900,rewardXP=1415,starts={{npcID=152783}},ends={{npcID=152845}},mapCandidates={npc={1462},zone={10290}},questType="standard",sourceQuests={55651},questLines={{id=941,name="Expedition to Mechagon",orderIndex=8,flags=0},{id=5384,name="Welcome to Mechagon",orderIndex=9,flags=0},{id=6061,name="Mechagon Intro",orderIndex=8,flags=0}},campaigns={{id=222,title="Mechagon",questLineID=5384,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6061,questLineOrder=2}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55657] = {id=55657,name="In the Shadow of Crimson Wings",level=50,requiredLevel=50,faction="both",categories={"legendary"},flags={},sharable=false,expansion=7,zoneID=4922,mapID=114,storyline={55657,56167},description="It is unlike Alexstrasza to remain out of contact for so long, particularly when the very essences of the dragonflights' power are being made manifest. While our allies here tend to the injured, we must seek out the Life-Binder at once. When you are ready, we shall ride to the Vermillion Redoubt together.",objectivesText="Speak with Kalecgos to fly to the Vermillion Redoubt, locate Alexstrasza and discover the source of the threat. Progress: We must rely on your aid once more, champion.",rewardXP=10225,rewardItems={168280,168613},rewardCurrencies={{id=1553,amount=1800}},starts={{npcID=152720}},ends={{npcID=152720}},mapCandidates={npc={114},zone={4922}},questTurnInID=152720,questType="standard",sourceQuests={56167},questLines={{id=958,name="In the Shadow of Crimson Wings",orderIndex=1,flags=0}},db2PoiMapID=2215,db2PoiUiMapID=1473},
[55658] = {id=55658,name="Clues Abound",level=10,requiredLevel=10,faction="both",categories={},flags={"daily","repeatable"},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55658},description="Before King Mechagon claimed this island, someone else lived here. Buried beneath this filth and garbage is the history of a forgotten people. With your help, we shall learn about these previous inhabitants. Sir Finley has marked a location where he's seen unusual artifacts. Meet him there and see if you can discover any clues.",objectivesText="Discover a clue about the island's history. Progress: Get to it, history is waiting for you!",rewardGold=238680,rewardXP=1415,rewardItems={152813,166846,168223,168234,168235,168236,168256,169864},starts={{npcID=152501}},ends={{npcID=152501}},mapCandidates={npc={1462},zone={10290}},questTurnInID=152501,questType="standard",questLines={{id=964,name="Visit from Explorer's League",orderIndex=0,flags=0}},db2LabelIDs={5672},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55659] = {id=55659,name="Relics of the Sundering",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={55659},description="It's not every day that you encounter the remnants of a lost civilization beneath the ocean! I never would have imagined that I'd have the opportunity to explore the lost city of Nazjatar ... and on solid ground at that! There are many secrets here to uncover. If you come across any ancient highborne artifacts, please bring them to me. These relics could provide us with valuable clues regarding the mysteries of the Great Sundering. I feel as though we are barely scratching the surface so far...",objectivesText="Collect 10 Highborne Relics . Progress: Whatever mysteries were hidden here beneath the ocean are now waiting to be revealed!",rewardGold=309800,rewardItems={124640,168186,170187,204370},rewardCurrencies={{id=1721,amount=3},{id=1749,amount=100},{id=1721,amount=2}},starts={{npcID=152532}},ends={{npcID=152532}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56156},worldTaskTitle="Relics of the Sundering",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55661] = {id=55661,name="Fighting Venomous With Venom",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55661},description="There are many uses for the poison of the snapdragons. Immediate use would be to create antivenin for healing, or harvesting poison for attacking the naga. Let's get to the root of the issue, literally. Use some collected venom against a Terrormaw to weaken it. Kill one and bring me their fangs. I think we can come up with something handy from there.",objectivesText="Use collected venom to weaken and kill a Snapdragon Terrormaw for their fangs. Progress: Did you get the fangs?",rewardGold=234000,rewardItems={168198,168404,168525},rewardCurrencies={{id=1721,amount=3},{id=1745,amount=100},{id=1721,amount=2}},starts={{npcID=153777}},ends={{npcID=153777}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500},worldTaskTitle="Fighting Venomous With Venom",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55662] = {id=55662,name="Arcane Cache",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={55662},description="<The heavily reinforced chest is of naga construction and appears to be reinforced with a magical lock of some kind. Magical reinforcement aside, the cache still requires a key to unlock. The key is most likely being held by one of the nearby naga soldiers.>",objectivesText="Locate the key to the Arcane Cache . Progress: <The chest is locked and requires a key.>",rewardGold=309800,rewardItems={168199},rewardCurrencies={{id=1721,amount=3},{id=1749,amount=100},{id=1721,amount=2}},startObjects={{objectID=325894,mapID=1355,x=0.531,y=0.283}},endObjects={{objectID=325894,mapID=1355,x=0.531,y=0.283}},coords={mapID=1355,x=0.531,y=0.283},mapCandidates={npc={},zone={10052}},questType="standard",sourceQuests={56156},worldTaskTitle="Arcane Cache",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55663] = {id=55663,name="Broken Controller",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55663},description="It is too late for me, my friends. The Controllers work us and work us and we have no rest. We have lost so many. Please, free the others! Don't let them share my fate!",objectivesText="Free the slaves and destroy the Merciless Controller .",rewardGold=234000,rewardCurrencies={{id=1721,amount=3},{id=1745,amount=100},{id=1721,amount=2}},starts={{npcID=152717}},ends={{npcID=151614}},mapCandidates={npc={1355},zone={10052}},questType="standard",worldTaskTitle="Broken Controller",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55664] = {id=55664,name="A Blow to Morale",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55664},description="This place is the source of all of our corruption. The kelfin are taken and broken here. Hit them where it hurts. Break their power, kill every naga you see, wreak havoc! Every little crack we make, weakens their foundation.",objectivesText="Disrupt all activities in the Shirakess Repository. Progress: Did you damage their morale?",rewardGold=234000,rewardCurrencies={{id=1721,amount=3},{id=1746,amount=100},{id=1721,amount=2}},starts={{npcID=154064}},ends={{npcID=154064}},mapCandidates={npc={1355},zone={10052}},questType="standard",worldTaskTitle="A Blow to Morale",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55665] = {id=55665,name="The Dark Garden",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55665},description="Look, <name>, I know we have bigger battles ahead, but these gardens are horrific. Innocent creatures captured and imprisoned for the naga's amusement. They bring them out, torture them, change them, break them... you get the idea. Help me free those the naga have taken, and punish them for their hubris!",objectivesText="Kill naga and release the poor tortured creatures held in the Imperial Garden. Progress: Were you able to wreak some havoc in there?",rewardGold=309800,rewardItems={169345},rewardCurrencies={{id=1721,amount=3},{id=1747,amount=100},{id=1721,amount=2}},starts={{npcID=152787}},ends={{npcID=152787}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500},worldTaskTitle="The Dark Garden",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55667] = {id=55667,name="Short-Supply Reward",level=50,requiredLevel=50,faction="none",categories={},flags={},sharable=false,expansion=7,storyline={55667},rewardItems={69903,90818,103533,120334,128803,140591,141701,160054,184522,201326,224573,259086},mapCandidates={npc={},zone={}},questType="standard"},
