[55669] = {id=55669,name="Encrypted Radio Receiver TBD",level=10,requiredLevel=10,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={55669},description="NYI - Will add Black Market viewing NPC in town",rewardGold=257400,rewardXP=1415,mapCandidates={npc={},zone={10290}},questType="standard",startItems={168221}},
[55672] = {id=55672,name="A Historical Mess",level=10,requiredLevel=10,faction="both",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=10290,storyline={55672},description="The text on this parchment appears to be Tortollan. Is it possible that Tortollans once resided on this island? We need to act quickly, before the creatures in this area destroy anymore evidence. Search the area for any signs of Tortollan relics .",objectivesText="12 Tortollan Relics collected. Progress: Get to it, history is waiting for you!",rewardGold=89550,rewardXP=1415,rewardItems={166846,166970,166971,168223,168224,168234,168236},starts={{npcID=152633}},mapCandidates={npc={},zone={10290}},questGiverID=152633,questType="standard",db2LabelIDs={5672}},
[55681] = {id=55681,name="Crab Marks The Spot",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={55681},description="<This appears to be the remains of some kind of treasure map. However, the map is in poor condition after so many years of being subjected to the ocean. According to the map, the treasure should be somewhere nearby; but it's impossible to tell what exact location is from the ruined map.>",objectivesText="Locate the buried treasure .",rewardGold=234000,rewardItems={168230},rewardCurrencies={{id=1721,amount=3},{id=1748,amount=100}},startObjects={{objectID=325954,mapID=1355,x=0.438,y=0.545}},endObjects={{objectID=325954,mapID=1355,x=0.438,y=0.545}},coords={mapID=1355,x=0.438,y=0.545},mapCandidates={npc={},zone={10052}},questType="standard",sourceQuests={56156},worldTaskTitle="Crab Marks The Spot",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55683] = {id=55683,name="Forgotten Memories",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=10052,mapID=1355,description="Have we met before? I'm sorry... but I don't remember your name. My name is... Arylina ... I think. My memory has been so foggy since the great explosion happened that sent us underwater. Oh! But look! I can see the sun and the stars again... I wonder what happened? I used to keep a diary, but I can't find it anywhere. If I just had my diary back, I'm sure I could remember more. Will you help me find it?",rewardGold=309800,rewardCurrencies={{id=1721,amount=3},{id=1750,amount=100},{id=1721,amount=2}},starts={{npcID=152716}},ends={{npcID=152716}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56156},worldTaskTitle="Forgotten Memories",db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55685] = {id=55685,name="We Come in Peace... and Profit",level=10,requiredLevel=10,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={55096,55609,55630,55632,55646,55647,55648,55649,55650,55651,55652,55685,55729,55730,55731,55734,55736,55995,56131},description="King Mechagon won't be happy we're on his island. But a cruel king like that is gonna have enemies. You and I know that better than most, yeah? While Skaggit and the crew get our foothold dug in here, you and I are gonna find some potential allies to shield us from King Mechagon 's wrath. Those two guards ran into that junkheap town up the hill. That place don't smell of royalty to me... Let's check there first.",objectivesText="Explore the nearby town with Gazlowe . Progress: Mechagon is not like the legends you were told.",rewardGold=514800,rewardXP=1415,starts={{npcID=152845}},ends={{npcID=152851}},mapCandidates={npc={1462},zone={10290}},questType="standard",sourceQuests={55652},questLines={{id=941,name="Expedition to Mechagon",orderIndex=9,flags=0},{id=5384,name="Welcome to Mechagon",orderIndex=10,flags=0},{id=6061,name="Mechagon Intro",orderIndex=9,flags=0}},campaigns={{id=222,title="Mechagon",questLineID=5384,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6061,questLineOrder=2}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55686] = {id=55686,name="Upgrade Your Jetpack (Optional)",level=10,requiredLevel=10,faction="none",sharable=false,expansion=7,zoneID=7503,mapID=650,mapCandidates={npc={},zone={7503}},questType="standard"},
[55687] = {id=55687,name="Expedition GG-118 Micro-Jetpack",level=10,requiredLevel=10,faction="none",sharable=false,expansion=7,zoneID=7503,mapID=650,mapCandidates={npc={},zone={7503}},questType="standard"},
[55688] = {id=55688,name="A Growing Mystery",level=10,requiredLevel=10,faction="both",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={55688},description="This runestone could be of Vrykul origins. Is it possible that Vrykul once visited this island? Where there's one runestone, there's usually more. The roots of lashers are drawn to the magic of runestones. If there are more buried here, the Lasher roots maybe wrapped around them! Clear these lashers and see if any have runestones tangled in their roots.",objectivesText="10 Ancient Runestones collected. Progress: Get to it, history is waiting for you!",rewardGold=238680,rewardXP=1415,rewardItems={166846,166970,166971,168223,168234,168236,168243,168256,169864,246697},mapCandidates={npc={},zone={10290}},questType="standard",db2LabelIDs={5672}},
[55694] = {id=55694,name="There's Something in the Water",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55558,55560,55561,55565,55569,55570,55571,55573,55574,55694,56325,56358,56741},description="The Ankoan must contend with threats from not only the naga, but also the horrors of N'Zoth. We learned early that if we allow his infection even the smallest purchase, he will grow and corrupt everything. There is a great evil who is lingering near the waterway that flows through this place. It must be dealt with.",objectivesText="Kill the Eye of the Corruptor .",rewardGold=234000,rewardXP=6815,starts={{npcID=151000}},ends={{npcID=151000}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55558},questLines={{id=975,name="Turning the Tide",orderIndex=9,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=41,flags=0}},campaigns={{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55695] = {id=55695,name="That New Mount Smell",level=10,requiredLevel=10,faction="both",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={55695},description="Once every week, Mechagon expels a lot of excess oils through the outflow. That's why the place is a toxic mess! Today they expelled a batch of Golden Cogpaste . The stuff is amazing! I make air fresheners out of it. Makes any mount smell like it's brand new! Check all the pipes in the outflow, and see if you can collect some of this paste.",objectivesText="Collect 8 Golden Cogpaste . Progress: I still could use that cogpaste.",rewardGold=257400,rewardXP=1415,rewardItems={166846,166970,166971,168246,246697},starts={{npcID=152321}},ends={{npcID=152321}},mapCandidates={npc={1462},zone={10290}},questType="standard",worldTaskTitle="That New Mount Smell",db2LabelIDs={5672},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55697] = {id=55697,name="A Little Leg Work",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={54083,54086,54922,54929,55373,55608,55622,55696,55697,55753,56168,56175},description="The legs and shocks on this mount are shot! We'll need some new ones if we're going to get this mount crawling. A few weeks ago, Bondo and his gang rode into the Scrapbone Den hoping to scare the Troggs off. The Troggs tore their crawlers apart! The parts for those crawlers are still laying all around Scrapbone Den. See if you can get us some of those parts from the Troggs.",objectivesText="Collect 4 Mechaspider Leg and 12 Toe Springs . Progress: We need those legs.",rewardGold=2000,rewardXP=1415,rewardItems={168281,168299,168827},starts={{npcID=150573}},ends={{npcID=150573}},mapCandidates={npc={1462},zone={10290}},questType="standard",sourceQuests={55373},questLines={{id=925,name="Making a Mount",orderIndex=4,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55701] = {id=55701,name="Snapdragon Claws",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={55701},description="Snapdragons are savage creatures that hunt in packs. Their presence in Nazjatar requires us to stay vigilant at all times. They are crafty beasts, preferring to ambush their prey when it is weak or wounded. We will need to reduce the number of snapdragons in the area. The last thing we need after a battle with the naga is to be finished off by a pack of blood-thirsty snapdragons! Hunt down any nearby snapdragons and bring me a claw from each kill so that I may keep track of their numbers.",objectivesText="Collect 10 Snapdragon Claws . Progress: The snapdragon threat cannot be underestimated.",rewardGold=309800,rewardItems={168247},rewardCurrencies={{id=1721,amount=3},{id=1749,amount=100},{id=1721,amount=2}},starts={{npcID=152737}},ends={{npcID=152737}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56156},worldTaskTitle="Snapdragon Claws",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55707] = {id=55707,name="First One's Free",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55707,55708},description="The pocket-sized computational device can accept punch cards to upgrade and modify its performance. I could give you a punch card, but a particularly crafty trogg, Moch'k Eight-Thumbs, stole my satchel full of cards. Kill Moch'k Eight-Thumbs, recover my satchel, and I'll set you up with a punch card for free.",objectivesText="Punchcard Satchel recovered. Progress: Get that satchel back!",rewardItems={167556,168252,168752},starts={{npcID=152747}},ends={{npcID=152747}},mapCandidates={npc={1462},zone={10290}},questType="standard",sourceQuests={55708},questLines={{id=952,name="Upgrades for All",orderIndex=1,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55708] = {id=55708,name="Upgraded",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55707,55708},description="Well, look at you, <race>... <Christy's mechanical eyes quickly scan your body.> Not as impressive as I had hoped. King Mechagon 's armies are fully mechanized. But, you... you have a severe excess of flesh and matching machinery deficiency. Yes, we simply must make a few changes... Maybe a neural-cranial upgrade! Bring me a few microcogs from the motospiders nearby and I'll fix you up!",objectivesText="Collect 20 Microcogs . Progress: You must be able to out-think King Mechagon in battle. Get me those parts.",rewardItems={167555,168250},starts={{npcID=152747},{npcID=160232}},ends={{npcID=152747}},mapCandidates={npc={1462},zone={10290}},questType="standard",sourceQuests={55736},questLines={{id=952,name="Upgrades for All",orderIndex=0,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55712] = {id=55712,name="Upgrade Your A.T.O.M.I.K. Mk. II (Optional)",level=10,requiredLevel=10,faction="none",sharable=false,expansion=7,zoneID=7503,mapID=650,mapCandidates={npc={},zone={7503}},questType="standard"},
[55713] = {id=55713,name="Expedition A.T.O.M.I.K. Mk. II",level=10,requiredLevel=10,faction="none",sharable=false,expansion=7,zoneID=7503,mapID=650,mapCandidates={npc={},zone={7503}},questType="standard"},
[55714] = {id=55714,name="Void Cache",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=10052,mapID=1355,rewardGold=309800,rewardCurrencies={{id=1721,amount=3},{id=1750,amount=100},{id=1721,amount=2}},starts={{npcID=326026}},ends={{npcID=326026}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56156},worldTaskTitle="Void Cache",db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55715] = {id=55715,name="Feed Them All",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55715},description="When we're doing our job right, we always have more mouths to feed! If you could help with my stock, we could care for even more. Big, strong friends are what this revolution needs!",objectivesText="Collect 10 Fathom Flesh . Progress: Do we have enough protein?",rewardGold=234000,rewardItems={168253,168254},rewardCurrencies={{id=1721,amount=3},{id=1747,amount=100},{id=1721,amount=2}},starts={{npcID=152786}},ends={{npcID=152786}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500},worldTaskTitle="Feed Them All",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55717] = {id=55717,name="Time for Heroics",level=10,requiredLevel=10,faction="both",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=10290,storyline={55717},description="That card you found was a gold rare Huolon! I think that card belonged to Adalin Halfheight , one of our junior explorer league members. If he dropped it, he and our other junior members maybe in trouble! We need to find Leona Mistcaller , Dunkin Crackjaw , and Adalin Halfheight immediately!",objectivesText="Leona Mistcaller , Dunkin Crackjaw , and Adalin Halfheight rescued. Progress: Let's find these people!",rewardGold=238680,rewardXP=1415,rewardItems={166846,166970,166971,168223,168234,168236,168256,169864},starts={{npcID=152633}},mapCandidates={npc={},zone={10290}},questGiverID=152633,questType="standard",db2LabelIDs={5672}},
[55718] = {id=55718,name="Strange Discovery",level=10,requiredLevel=10,faction="both",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={55718},description="<A very old ring of Nightelf origin. Seems out of place on this island, perhaps Elise Starseeker will know what to make of it>",objectivesText="Deliver the ring to Elise Starseeker . Provided item:",rewardGold=2000,rewardXP=1415,rewardItems={166846,168223,168234,168236,168256,169864},ends={{npcID=152501}},coords={mapID=1462,source="quest_giver",x=0.705,y=0.312},mapCandidates={npc={1462},zone={10290}},questType="standard",db2LabelIDs={5672},startItems={168256}},
[55719] = {id=55719,name="Requisition: A Few Starfish",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55719},description="Our forward scouts have been using starfish scales as camouflage. The trouble is that the scales deteriorate too quickly. We are going to need more scales if we want to keep tabs on naga movements. If you happen upon any Angel Scale Starfish , please deliver them to the quartermaster as soon as possible.",objectivesText="Collect 3 Angel Scale Starfish .",rewardXP=6815,rewardCurrencies={{id=1553,amount=86},{id=1553,amount=89},{id=1553,amount=90},{id=1553,amount=91}},starts={{npcID=151633},{npcID=154436}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500,56156}},
[55720] = {id=55720,name="Requisition: A Few Seaweed",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55720},description="We have so many wounded and we are dangerously low on seaweed bandages. If you find Sticky Seaweed , please give it to the quartermaster.",objectivesText="Collect 3 Sticky Seaweed .",rewardXP=6815,rewardCurrencies={{id=1553,amount=85},{id=1553,amount=86},{id=1553,amount=88},{id=1553,amount=89}},starts={{npcID=151614},{npcID=151763}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500,56156}},
[55721] = {id=55721,name="Requisition: A Few Kelp Buds",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55721},description="We need rations for our forces. While kelp buds do not have the same delicious taste as other options, it is nutritious and plentiful near any kelp forests. This makes it our first choice for making rations. If you happen to find any around Nazjatar , please leave your stores with the quartermaster. The ones freshly fallen from kelp are best.",objectivesText="Collect 3 Fallen Kelp Buds .",rewardXP=6815,rewardCurrencies={{id=1553,amount=85},{id=1553,amount=87},{id=1553,amount=91},{id=1553,amount=92}},starts={{npcID=151635},{npcID=153591}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500,56156}},
[55723] = {id=55723,name="Requisition: A Few Carp",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55723},description="Our local sea life is in danger! If you spot a fish out of water, please return it to the nearest lake, stream, or river. Conservation is everyone's responsibility!",objectivesText="Return 3 Struggling Carps to water.",rewardXP=6815,rewardCurrencies={{id=1553,amount=88},{id=1553,amount=89},{id=1553,amount=90},{id=1553,amount=91}},starts={{npcID=151352},{npcID=155941}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500,56156}},
[55724] = {id=55724,name="Requisition: A Few Deepcoral Buds",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55724},description="Many species feed on the deepcoral buds from the tall columns that grow in the east. Fathom rays feed on these buds especially. We use the buds as lures for fathom rays to use as mounts. But with our stores so low, we will not be able to provide the air support we need across Nazjatar . If you could gather more deepcoral buds and return them to the quartermaster, you will surely be rewarded.",objectivesText="Collect 3 Deepcoral Buds .",rewardXP=6815,rewardCurrencies={{id=1553,amount=85},{id=1553,amount=86},{id=1553,amount=87},{id=1553,amount=88}},starts={{npcID=151772},{npcID=153772}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500,56156}},
[55725] = {id=55725,name="Requisition: A Few Spiral Leaf",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55725},description="We are dangerously low on our medicine stores. If you find any Spiral Leaf, please leave your stores with the quartermaster. I should warn you, Spiral Leaf is immensely poisonous. Make sure to handle it with care. Some symptoms of spiral leaf poisoning include bouts of rage, immense bursts of strength, and murderous impulses. If you are exposed, find some naga and use your murderous energy for good.",objectivesText="Collect 3 Poisonous Spiral Leaf .",rewardXP=6815,rewardCurrencies={{id=1553,amount=85},{id=1553,amount=86},{id=1553,amount=87},{id=1553,amount=88}},starts={{npcID=151614},{npcID=151763}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500,56156}},
[55726] = {id=55726,name="Requisition: A Few Cone Shells",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55726},description="If we are going to arm ourselves against the naga, we will need far more supplies and armaments. Cone Shells make most of our armor and weapons. It's light, it's strong, and it's plentiful in this region. However, our supplies are running short and our forces need support. If you find yourself carrying Impregnable Cone Shells , please leave your stores with the quartermaster.",objectivesText="Collect 3 Impregnable Cone Shell .",rewardXP=6815,rewardCurrencies={{id=1553,amount=85},{id=1553,amount=89},{id=1553,amount=90},{id=1553,amount=91}},starts={{npcID=151633},{npcID=154436}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500,56156}},
[55727] = {id=55727,name="Requisition: A Few Flotsam",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55727},description="I have seen piles of flotsam in the sands to the west. If you could go out and scrounge anything useful from the debris, it could prove useful. Beware, that area is a hydra breeding ground and they have been growing more aggressive since the water receded. Once you've gathered some supplies, return to the quartermaster for your reward.",objectivesText="Collect 3 Piles of Flotsam.",rewardXP=6815,rewardCurrencies={{id=1553,amount=85},{id=1553,amount=91},{id=1553,amount=92},{id=1553,amount=93}},starts={{npcID=153509},{npcID=153512}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500,56156}},
[55728] = {id=55728,name="Reinforced Cache",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={55728},description="<The heavily reinforced chest is of naga construction and appears to be reinforced with a heavy-duty lock of some kind. Reinforcement aside, the cache still requires a key to unlock. The key is most likely being held by one of the nearby naga soldiers.>",objectivesText="Locate the key to the Reinforced Cache . Progress: <The chest is locked and requires a key.>",rewardGold=234000,rewardItems={168261},rewardCurrencies={{id=1721,amount=3},{id=1748,amount=100},{id=1721,amount=2}},startObjects={{objectID=326047,mapID=1355,x=0.45,y=0.221}},endObjects={{objectID=326047,mapID=1355,x=0.45,y=0.221}},coords={mapID=1355,x=0.45,y=0.221},mapCandidates={npc={},zone={10052}},questType="standard",sourceQuests={56156},worldTaskTitle="Reinforced Cache",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55729] = {id=55729,name="The Resistance Needs YOU!",level=10,requiredLevel=10,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={54087,54088,54945,54946,54947,54992,55040,55096,55609,55645,55729,55730,55731,55734,55736,55995,56131},description="Rustbolt isn't usually in this level of malfunction. King Mechagon attacked our town last night. His mechanical armies captured many members of the Rustbolt Resistance and destroyed as much as they could before we drove them out. The prisoners are being processed at Junkwatt Depot. After that, they'll be transferred down into King Mechagon 's underground city... for full mechanization. We can't let that happen. Will you help me rescue them?",objectivesText="Ride with Prince Erazmin to Junkwatt Depot.",rewardGold=257400,rewardXP=1415,starts={{npcID=152851}},ends={{npcID=152820}},mapCandidates={npc={1462},zone={10290}},questType="standard",sourceQuests={55645,55685},questLines={{id=940,name="Expedition to Mechagon",orderIndex=8,flags=0},{id=941,name="Expedition to Mechagon",orderIndex=10,flags=0},{id=5376,name="Welcome to Mechagon",orderIndex=10,flags=0},{id=5384,name="Welcome to Mechagon",orderIndex=11,flags=0},{id=6062,name="Mechagon Intro - On Island",orderIndex=1,flags=0}},campaigns={{id=218,title="Mechagon",questLineID=5376,questLineOrder=0},{id=222,title="Mechagon",questLineID=5384,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6062,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55730] = {id=55730,name="Rescuing the Resistance",level=10,requiredLevel=10,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={54087,54088,54945,54946,54947,54992,55040,55096,55609,55645,55729,55730,55731,55734,55736,55995,56131},description="King Mechagon is ruthlessly efficient. He only expends resources to kidnap those he deems worthy. The rest, he... discards. < Prince Erazmin grimaces.> We will deal with my father, King Mechagon , another day. This information is more immediately relevant in that my father's predictability means our top scientists, engineers, and tinkerers should all be trapped, alive, somewhere in this depot. We will find them, and break them out.",objectivesText="Rescue the Rustbolt Resistance members. Progress: My father is short-sighted. He judges the worthiness of an individual in its current state. He fails to truly see their potential.",rewardGold=257400,rewardXP=1415,starts={{npcID=152820}},ends={{npcID=152820}},mapCandidates={npc={1462},zone={10290}},questTurnInID=152820,questType="standard",sourceQuests={55729},questLines={{id=940,name="Expedition to Mechagon",orderIndex=9,flags=0},{id=941,name="Expedition to Mechagon",orderIndex=11,flags=0},{id=5376,name="Welcome to Mechagon",orderIndex=11,flags=0},{id=5384,name="Welcome to Mechagon",orderIndex=12,flags=0},{id=6062,name="Mechagon Intro - On Island",orderIndex=2,flags=0}},campaigns={{id=218,title="Mechagon",questLineID=5376,questLineOrder=0},{id=222,title="Mechagon",questLineID=5384,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6062,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55731] = {id=55731,name="My Father's Armies",level=10,requiredLevel=10,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={54087,54088,54945,54946,54947,54992,55040,55096,55609,55645,55729,55730,55731,55734,55736,55995,56131},description="My father was once a good leader. He envisioned a brighter future for his people, and did everything in his power to help us acquire it. But when his vision became misaligned with the dreams of his people, he failed to adapt. Instead, he grew rigid, forcing his will on others. In secret experiments, he began fully mechanizing the bodies of those who resisted him. It was horrible to watch... there was nothing left of the original gnomes who followed him willingly. Only robots remained. Slaves.",objectivesText="Kill 12 Mechagon forces in Junkwatt Depot. Progress: If we don't stop my father here, we will all share these poor gnomes' fates.",rewardGold=257400,rewardXP=1415,starts={{npcID=152820}},ends={{npcID=152820}},mapCandidates={npc={1462},zone={10290}},questTurnInID=152820,questType="standard",sourceQuests={55729},questLines={{id=940,name="Expedition to Mechagon",orderIndex=10,flags=0},{id=941,name="Expedition to Mechagon",orderIndex=12,flags=0},{id=5376,name="Welcome to Mechagon",orderIndex=12,flags=0},{id=5384,name="Welcome to Mechagon",orderIndex=13,flags=0},{id=6062,name="Mechagon Intro - On Island",orderIndex=3,flags=0}},campaigns={{id=218,title="Mechagon",questLineID=5376,questLineOrder=0},{id=222,title="Mechagon",questLineID=5384,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6062,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55732] = {id=55732,name="An Old Scar",level=50,requiredLevel=50,faction="both",categories={"legendary"},flags={},sharable=false,expansion=7,zoneID=9667,mapID=1474,storyline={55732,55735,55737},description="We've got a new problem, champion. Another grievous wound has opened up, this time at the Maelstrom! The shaman there are in deep trouble, an' they need our help! Speak tae MOTHER . She'll get ye tae the Maelstrom. I'll meet ye there.",objectivesText="Speak to MOTHER to travel to the Maelstrom.",rewardGold=23400,rewardXP=11765,rewardItems={248019,248020,248021,248022},starts={{npcID=152206}},ends={{npcID=152206}},mapCandidates={npc={},zone={9667}},questGiverID=152206,questTurnInID=152206,questType="standard",sourceQuests={55521,55739,56262},questLines={{id=934,name="8.2 Heart - HoA Progression - Level II",orderIndex=0,flags=0}},db2PoiMapID=2214,db2PoiUiMapID=1474},
[55734] = {id=55734,name="Drill Rig Construction",level=10,requiredLevel=10,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={54087,54088,54945,54946,54947,54992,55040,55096,55609,55645,55729,55730,55731,55734,55736,55995,56131},description="<Prince Erazmin sifts through the resources you both collected.> Yes... This appears to be sufficient material to repair that drill rig. I'll do what I can with the parts that I have, but you will need to complete the repairs with yours. When you're ready, return to that broken drill rig we found and open it up. Together, we'll have it up and running in no time.",objectivesText="Contribute Spare Parts and Energy Cells to the Broken Drill Rig construction project. Progress: You didn't lose your parts did you?",rewardGold=257400,rewardXP=1415,starts={{npcID=153670}},ends={{npcID=153670}},mapCandidates={npc={},zone={}},questGiverID=153670,questTurnInID=153670,questType="standard",sourceQuests={55995},questLines={{id=940,name="Expedition to Mechagon",orderIndex=12,flags=0},{id=941,name="Expedition to Mechagon",orderIndex=14,flags=0},{id=5376,name="Welcome to Mechagon",orderIndex=14,flags=0},{id=5384,name="Welcome to Mechagon",orderIndex=15,flags=0},{id=6062,name="Mechagon Intro - On Island",orderIndex=4,flags=0}},campaigns={{id=218,title="Mechagon",questLineID=5376,questLineOrder=0},{id=222,title="Mechagon",questLineID=5384,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6062,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55735] = {id=55735,name="Defending the Maelstrom",level=50,requiredLevel=50,faction="both",categories={"legendary"},flags={},sharable=false,expansion=7,mapID=1474,storyline={55732,55735,55737},description="The shaman of the Earthen Ring are powerful, but this is more than even they can handle! And from the sound o' it, some o' their own are still trapped down below. Like ye did in Nordrassil, use yer Heart of Azeroth tae seal up the wounds inflicted here. An' lay any crazed elementals tae rest before they make even more o' a mess.",objectivesText="Defeat Azerite elementals and seal Azeroth's injuries at the Maelstrom. Progress: This just keeps gettin' worse. If too many of these wounds open up, we may not be able tae heal the damage.",rewardGold=468000,starts={{npcID=152815}},ends={{npcID=152815}},mapCandidates={npc={},zone={}},questGiverID=152815,questTurnInID=152815,questType="standard",sourceQuests={55732},questLines={{id=934,name="8.2 Heart - HoA Progression - Level II",orderIndex=1,flags=0}},db2PoiMapID=2214,db2PoiUiMapID=1474},
[55736] = {id=55736,name="Welcome to the Resistance",level=10,requiredLevel=10,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={54087,54088,54945,54946,54947,54992,55040,55096,55609,55645,55729,55730,55731,55734,55736,55995,56131},description="Life in the Rustbolt Resistance is not easy, <name>. But it is yours. We will not order you around or force you to fight. Mechagon is a land of endless opportunities, and you may chase whichever opportunities you see fit. Of course, if you'd like suggestions for which improvements you most require, myself or any of the other mechagnomes in town will be happy to advise you of your current weaknesses. But, for now, I ask simply that you walk with me to my workshop.",objectivesText="Tour Rustbolt with Prince Erazmin .",rewardGold=257400,rewardXP=1415,rewardItems={166846,166970,246703},starts={{npcID=151947}},ends={{npcID=149816}},mapCandidates={npc={1462},zone={10290}},questType="standard",sourceQuests={55096},questLines={{id=940,name="Expedition to Mechagon",orderIndex=14,flags=0},{id=941,name="Expedition to Mechagon",orderIndex=16,flags=0},{id=5376,name="Welcome to Mechagon",orderIndex=16,flags=0},{id=5384,name="Welcome to Mechagon",orderIndex=17,flags=0},{id=6062,name="Mechagon Intro - On Island",orderIndex=5,flags=0}},campaigns={{id=218,title="Mechagon",questLineID=5376,questLineOrder=0},{id=222,title="Mechagon",questLineID=5384,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6062,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55737] = {id=55737,name="At the Azerite Time",level=50,requiredLevel=50,faction="both",categories={"legendary"},flags={},sharable=false,expansion=7,zoneID=9667,mapID=1473,storyline={55732,55735,55737},description="Ye did it! Ye stopped the damage before it could get any worse! The Maelstrom will always be a place o' great history an' pain fer Azeroth, but any little bit we do will make things better. Who knows, maybe we can even heal Silithus one day! I'll meet ye back in the Chamber o' Heart. MOTHER 's sure tae be interested in what happened here.",objectivesText="Return to the Chamber of Heart.",rewardGold=23400,rewardCurrencies={{id=1553,amount=1500},{id=1579,amount=500}},starts={{npcID=152815}},ends={{npcID=152815}},mapCandidates={npc={},zone={9667}},questGiverID=152815,questTurnInID=152815,questType="standard",sourceQuests={55735},questLines={{id=934,name="8.2 Heart - HoA Progression - Level II",orderIndex=2,flags=0}},db2PoiMapID=2215,db2PoiUiMapID=1473},
[55738] = {id=55738,name="TBD NOT USED",level=10,requiredLevel=10,faction="none",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55738},description="TBD",objectivesText="TBD",rewardGold=257400,rewardXP=1415,mapCandidates={npc={},zone={10290}},questType="standard"},
[55739] = {id=55739,name="Back to the Chamber",level=50,requiredLevel=50,faction="horde",categories={"legendary"},flags={},sharable=false,expansion=7,zoneID=8670,mapID=1165,storyline={55739},description="The Heart o' Azeroth is gettin' stronger every day, and it's makin' a difference. Make yer way tae the Chamber o' Heart, champion. Yer talents are needed.",objectivesText="Return to the Chamber of Heart.",rewardGold=23400,starts={{npcID=154465}},ends={{npcID=154465}},mapCandidates={npc={1165},zone={8670}},questTurnInID=154465,questType="standard",nextQuests={55732}},
[55740] = {id=55740,name="TBD NOT USED",level=10,requiredLevel=10,faction="none",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55740},description="TBD",objectivesText="TBD",rewardGold=257400,rewardXP=1415,mapCandidates={npc={},zone={10290}},questType="standard"},
