[55743] = {id=55743,name="More Recycling",level=10,requiredLevel=10,faction="both",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=10290,storyline={55743},description="<Recycling is fun and profitable. The Recyclerizer DX-82 stands ready to receive more scrap metal.>",objectivesText="Collect 1 Bundle of Recyclable Parts Progress: <WARNING 3.6.4 - Y: Keep all appendages clear of doors or risk irreversible limb recyclerization.>",rewardGold=257400,rewardItems={168215,168216,168217,168258,168264,168266,168823,168827,168946,168950,168951,168952,169153,169692},starts={{npcID=13708,mapID=1462,x=0.5348,y=0.6145}},startObjects={{objectID=326027,mapID=1462,x=0.535,y=0.615}},endObjects={{objectID=326027,mapID=1462,x=0.535,y=0.615}},coords={mapID=1462,x=0.535,y=0.615},mapCandidates={npc={},zone={10290}},questType="standard",db2LabelIDs={5672}},
[55750] = {id=55750,name="WANTED: Lady Naz'jess",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={55750},description="Wanted for attacks against the Alliance! Lady Naz'jess is responsible for leading several raids and ambushes against our soldiers. Extreme caution advised! Upon completion of the mission, report to Lieutenant Hawkins for commendation.",objectivesText="Retrieve the head of Lady Naz'jess. Progress: Have anything to report?",rewardGold=468000,rewardItems={168265},rewardCurrencies={{id=1721,amount=3},{id=1748,amount=100},{id=1721,amount=2}},ends={{npcID=152942}},startObjects={{objectID=326142,mapID=1355,x=0.391,y=0.541}},coords={mapID=1355,source="quest_giver",x=0.4,y=0.555},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56156},worldTaskTitle="WANTED: Lady Naz'jess",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55751] = {id=55751,name="The Heart of the Water",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55751},description="You see a lot up here. Even the water is a slave to the will of the naga. I believe we can help them reform away from here. Bring back what you can!",objectivesText="Collect 15 Living Droplets from water elementals in Azsh'ari Terrace. Progress: Did you free them?",rewardGold=234000,rewardItems={168809},rewardCurrencies={{id=1721,amount=3},{id=1747,amount=100},{id=1721,amount=2}},starts={{npcID=153685}},ends={{npcID=153685}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500},worldTaskTitle="The Heart of the Water",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55752] = {id=55752,name="We Stand United",level=50,requiredLevel=50,faction="both",categories={"legendary"},flags={},sharable=false,expansion=7,zoneID=9667,mapID=114,storyline={55752},description="The work ye've done tae empower the Heart o' Azeroth cannae be understated! With this power, we might just stand a chance o' savin' the world. It's been a long fight fer certain, an' there is still more tae do. But fer now, we've got a little gift fer ye! Let me know when yer ready, champion.",objectivesText="Speak to Magni. Progress: Ain' it incredible, champion? There's no tellin' how powerful the Heart may yet become!",rewardGold=23400,rewardItems={158075,168614,169292,169768},starts={{npcID=152206}},ends={{npcID=152206}},mapCandidates={npc={},zone={9667}},questGiverID=152206,questTurnInID=152206,questType="standard",sourceQuests={56401},questLines={{id=976,name="8.2 Heart - HoA Progression - Level III",orderIndex=0,flags=0}},db2PoiMapID=571,db2PoiUiMapID=114},
[55753] = {id=55753,name="Knock His Bot Off",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={54083,54086,54922,54929,55373,55608,55622,55696,55697,55753,56168,56175},description="I need to rebuild the main powercore. It's a 500S Mekronic so I'll need the operational schematics to get the work done. Only person I know who has a copy of that is Bondo Bigblock. We're going to need Bondo's help to finish this. Maybe if you ask him, he'll lend us his schematics.",objectivesText="Acquire the powercore schematics from Bondo Bigblock. Progress: Did you make a deal with Bondo?",rewardGold=257400,rewardXP=1415,rewardItems={168305,168827},starts={{npcID=150573}},ends={{npcID=150573}},mapCandidates={npc={1462},zone={10290}},questType="standard",sourceQuests={55696},questLines={{id=925,name="Making a Mount",orderIndex=10,flags=0}},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55763] = {id=55763,name="The Rescue of Meredy Huntswell",level=6,requiredLevel=6,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56344,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59347,59349,59350,59352,59354,59355,59356,60168,85678},description="Our expedition's mage, Meredy Huntswell , is being held by the harpies! We've got to stop their ritual and rescue Meredy. You lead the charge. Kee-La and I will back you up if things look dire.",objectivesText="Rescue Meredy Huntswell from the harpy's necromantic ritual.",rewardGold=1720,rewardXP=875,rewardItems={168410},starts={{npcID=156859}},ends={{npcID=156859}},mapCandidates={npc={},zone={10424}},questGiverID=156859,questTurnInID=156859,questType="standard",sourceQuests={55196},questLines={{id=926,name="The Missing Expedition",orderIndex=29,flags=0},{id=1071,name="The Harpy Problem",orderIndex=1,flags=0},{id=5367,name="A Dark Ritual",orderIndex=4,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5367,questLineOrder=1,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[55764] = {id=55764,name="Harpy Culling",level=6,requiredLevel=6,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56344,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59347,59349,59350,59352,59354,59355,59356,60168,85678},description="The harpies are preparing for a dreadful assault, <name>. They plan to attack our allies back at camp! Harpies swoop in and snatch their victims before bringing them back to their nests... to feast. We have to stop them. Slay the harpies and their worgs to ensure their forces are too weak to stage an assault.",objectivesText="Defeat 10 harpies and their allies. Progress: We must do what we can to fight the harpy menace. Take them down, as well as their worgs.",rewardGold=1720,rewardXP=875,starts={{npcID=156860}},ends={{npcID=156860}},mapCandidates={npc={},zone={10424}},questGiverID=156860,questTurnInID=156860,questType="standard",sourceQuests={55196},questLines={{id=926,name="The Missing Expedition",orderIndex=30,flags=0},{id=1071,name="The Harpy Problem",orderIndex=2,flags=0},{id=5367,name="A Dark Ritual",orderIndex=24,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5367,questLineOrder=1,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[55765] = {id=55765,name="Bugs, Lots of 'Em!",level=10,requiredLevel=10,faction="both",categories={},flags={"daily","repeatable"},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55765},description="You got a problem with mechanical bugs, so the Roughriders are here to sort this mess out! In my experience, this big of an outbreak must have some sort of queen bug behind it all. We gonna go in, kill a lot of bugs till we find the leader of 'em all. Horde or Alliance don't matter, you're with the Roughriders today. Let's kill some bugs!",objectivesText="Exterminate 20 motospiders . Progress: Do your job!",rewardGold=257400,rewardXP=1415,rewardItems={166846,166970,166971},starts={{npcID=152932}},ends={{npcID=152932}},mapCandidates={npc={1462},zone={10290}},questType="standard",questLines={{id=966,name="Visit from Razak's Roughriders",orderIndex=0,flags=0}},db2LabelIDs={5672},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55766] = {id=55766,name="She Sells These Shells",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55766},description="Suva is so proud of her seashells. After everything she has done for our people, helping her supplies is the least we can do! Head down the hill and pick up some of the shiniest seashells you can find! You will make her day.",objectivesText="Collect 8 seashells. Progress: <Excited clicks and squeaks.>",rewardGold=234000,rewardItems={167538},rewardCurrencies={{id=1721,amount=3},{id=1747,amount=100},{id=1721,amount=2}},starts={{npcID=153006}},ends={{npcID=153024}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500},worldTaskTitle="She Sells These Shells",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55767] = {id=55767,name="Misdirection",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55767},description="We came in friendship and those pesky murlocs jumped us and stole my treasure. They threw it in one of those big clams and ran off into the village. They keep moving them around and I have no idea where it is now! Can you please help?",objectivesText="Find Dani's Treasure . Progress: Any luck?",rewardGold=234000,rewardItems={168300},rewardCurrencies={{id=1721,amount=3},{id=1747,amount=100},{id=1721,amount=2}},starts={{npcID=152985}},ends={{npcID=152985}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500},worldTaskTitle="Misdirection",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55768] = {id=55768,name="Emergent Sea Weeds",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55768},description="There is a special kind of kelp that only grows near the vents. Our healers use these to help treat our friends in Newhome. My kind don't have much of a chance down there, but you do! Gather up some of the vent kelp sprouts in the Dragon's Teeth Basin and bring them to Nevin.",objectivesText="Gather 10 vent kelp sprouts . Progress: Were you able to find the special vent kelp?",rewardGold=234000,rewardItems={168433},rewardCurrencies={{id=1721,amount=3},{id=1745,amount=100},{id=1721,amount=2}},starts={{npcID=153006}},ends={{npcID=151614}},mapCandidates={npc={1355},zone={10052}},questType="standard",worldTaskTitle="Emergent Sea Weeds",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55770] = {id=55770,name="WANTED: Commander Sarj'eth",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={55770},description="Wanted for attacks against the Alliance! Commander Sarj'eth is responsible for leading several raids and ambushes against our soldiers. Last seen near the vicinity of this command poster. Extreme caution advised! Upon completion of the mission, report to Lieutenant Hawkins for commendation.",objectivesText="Retrieve the head of Commander Sarj'eth. Progress: Have anything to report?",rewardGold=468000,rewardItems={168317},rewardCurrencies={{id=1721,amount=3},{id=1750,amount=100},{id=1721,amount=2}},ends={{npcID=152942}},startObjects={{objectID=326141,mapID=1355,x=0.391,y=0.541}},coords={mapID=1355,source="quest_giver",x=0.4,y=0.555},mapCandidates={npc={1355},zone={10052}},questType="standard",worldTaskTitle="WANTED: Commander Sarj'eth",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
