[55778] = {id=55778,name="Visions of Danger",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={55778,55779,55780,55781,55782},description="<name>, Spiritwalker Ussoh has revealed a disturbing vision to me regarding Baine Bloodhoof. He has asked that you speak with him as soon as you can. Return to me after. We will have much to discuss.",objectivesText="Speak with Spiritwalker Ussoh.",rewardGold=23400,rewardXP=850,starts={{npcID=151848}},ends={{npcID=151848}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55051},questLines={{id=973,name="Stay of Execution",orderIndex=0,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=973,questLineOrder=25,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=973,questLineOrder=15}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1718,db2PoiUiMapID=1355},
[55779] = {id=55779,name="Stay of Execution",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=1637,mapID=1355,storyline={55778,55779,55780,55781,55782},description="Come. It is time to save a friend.",objectivesText="Complete the \"Stay of Execution\" Scenario.",rewardGold=468000,rewardXP=8520,rewardCurrencies={{id=1553,amount=1000}},starts={{npcID=152977}},ends={{npcID=151848}},mapCandidates={npc={1355},zone={1637}},questGiverID=152977,questType="standard",sourceQuests={55781},questLines={{id=973,name="Stay of Execution",orderIndex=1,flags=0},{id=6016,name="Lorewalking: Thrall",orderIndex=3,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=973,questLineOrder=25,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=973,questLineOrder=15},{id=319,title="Lorewalking: Thrall",questLineID=6016,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1718,db2PoiUiMapID=1355},
[55780] = {id=55780,name="Old Allies",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55778,55779,55780,55781,55782},description="Sylvanas was my Ranger-General. I have respected her for millennia. Making this choice is something I have been wrestling with for some time. Baine's death will tear the Horde apart. The Tauren will not stand for it and if they leave, I know they will not be the last. We must save Baine. Not just for his life, but for the Horde. I can only hope once the time pressure is gone we may be able to reason with her but... I have contacted allies who will help. Meet them in the Cleft of Shadows.",objectivesText="Meet with allies in the Cleft of Shadows.",rewardGold=117000,rewardXP=3410,starts={{npcID=151848}},ends={{npcID=151848}},mapCandidates={npc={1355},zone={10052}},questTurnInID=151848,questType="standard",sourceQuests={55052,55778},questLines={{id=973,name="Stay of Execution",orderIndex=2,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=973,questLineOrder=25,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=973,questLineOrder=15}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1,db2PoiUiMapID=86},
[55781] = {id=55781,name="Old Allies",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55778,55779,55780,55781,55782},description="Sylvanas Windrunner was once my ranger-general. Now she is my warchief. Through peacetime and war, I followed her orders. Until now. Baine is a noble soul. His execution would drive a blade into the very heart of the Horde. We must save him, <name>. It is the only way to preserve who we are. What we stand for. I have reached out to allies who will help you. But in siding with them, you will put your own life in peril. If you feel as I do, then meet them in the Cleft of Shadows. Good luck.",objectivesText="Meet with allies in the Cleft of Shadows in Orgrimmar. Progress: Once again, we face dark times, <name>.",rewardGold=117000,rewardXP=3410,starts={{npcID=151848}},ends={{npcID=151848}},mapCandidates={npc={1355},zone={10052}},questTurnInID=151848,questType="standard",sourceQuests={55778},questLines={{id=973,name="Stay of Execution",orderIndex=3,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=973,questLineOrder=25,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=973,questLineOrder=15}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1,db2PoiUiMapID=86},
[55782] = {id=55782,name="Stay of Execution",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=1637,mapID=1355,storyline={55778,55779,55780,55781,55782},description="Baine's time is short. We must act now.",objectivesText="Complete the \"Stay of Execution\" Scenario.",rewardGold=468000,rewardXP=8520,rewardCurrencies={{id=1553,amount=1000}},starts={{npcID=152977}},ends={{npcID=153949}},mapCandidates={npc={1355},zone={1637}},questGiverID=152977,questType="standard",sourceQuests={55780},questLines={{id=973,name="Stay of Execution",orderIndex=4,flags=0}},campaigns={{id=2,title="War Campaign",questLineID=973,questLineOrder=25,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=225,title="War Campaign",questLineID=973,questLineOrder=15}},campaignLockText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue.",db2PoiMapID=1718,db2PoiUiMapID=1355},
[55783] = {id=55783,name="Stay of Execution",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=1519,mapID=84,storyline={55783,55784},description="When I was younger, Baine Bloodhoof and I began exchanging letters. Through our unlikely friendship, I learned that there was nobility in the Horde. He proved that by defying Sylvanas when she planned to strip the free will from Derek Proudmoore. That act of nobility will cost him his life... unless we intervene. If there is to be peace in Azeroth, our hope depends upon good people doing the right thing. People like Baine. People like you. Please, go with Jaina. Save my friend and see him home.",objectivesText="Complete the \"Stay of Execution\" Scenario.",rewardGold=468000,rewardXP=8520,rewardCurrencies={{id=1553,amount=1000}},starts={{npcID=107574}},ends={{npcID=150101}},mapCandidates={npc={84,1355},zone={1519}},questType="standard",sourceQuests={55784},questLines={{id=972,name="Stay of Execution",orderIndex=1,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=972,questLineOrder=23,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=972,questLineOrder=14}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=1718,db2PoiUiMapID=1355},
[55784] = {id=55784,name="Payment in Kind",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55783,55784},description="<name>, King Anduin has requested our presence in Stormwind. We've sent him reports on our situation here in Nazjatar, and he understands the severity of the threat we're facing. For him to pull both of us back from the front lines, it must be a matter of grave importance. I will meet you in Stormwind Keep.",objectivesText="Meet with Anduin Wrynn in Stormwind Keep. Progress: Thank you for coming, <name>.",rewardGold=23400,rewardXP=850,starts={{npcID=150101}},ends={{npcID=107574}},mapCandidates={npc={84,1355},zone={10052}},questType="standard",sourceQuests={54183,55937},questLines={{id=972,name="Stay of Execution",orderIndex=0,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=972,questLineOrder=23,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=216,title="War Campaign",questLineID=972,questLineOrder=14}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiUiMapID=84},
[55785] = {id=55785,name="Requisition: More Starfish",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55785},description="Our forward scouts have been using starfish scales as camouflage. The trouble is that the scales deteriorate too quickly. We are going to need more scales if we want to keep tabs on naga movements. If you happen upon any Angel Scale Starfish , please deliver them to the quartermaster as soon as possible.",objectivesText="Collect 5 Angel Scale Starfish .",rewardXP=6815,rewardItems={168242},rewardCurrencies={{id=1553,amount=85},{id=1553,amount=87},{id=1553,amount=89},{id=1553,amount=90}},starts={{npcID=151633},{npcID=154436}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500,56156}},
[55786] = {id=55786,name="Requisition: More Seaweed",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55786},description="We have so many wounded and we are dangerously low on seaweed bandages. If you find Sticky Seaweed , please give it to the quartermaster.",objectivesText="Collect 5 Sticky Seaweed .",rewardXP=6815,rewardCurrencies={{id=1553,amount=85},{id=1553,amount=86},{id=1553,amount=92},{id=1553,amount=93}},starts={{npcID=151614},{npcID=151763}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500,56156}},
[55787] = {id=55787,name="Requisition: More Kelp Buds",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55787},description="We need rations for our forces. While kelp buds do not have the same delicious taste as other options, it is nutritious and plentiful near any kelp forests. This makes it our first choice for making rations. If you happen to find any around Nazjatar , please leave your stores with the quartermaster. The ones freshly fallen from kelp are best.",objectivesText="Collect 5 Fallen Kelp Buds .",rewardXP=6815,rewardCurrencies={{id=1560,amount=20},{id=1553,amount=85},{id=1553,amount=86},{id=1553,amount=87}},starts={{npcID=151635},{npcID=153591}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500,56156}},
[55789] = {id=55789,name="Requisition: More Carp",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55789},description="Our local sea life is in danger! If you spot a fish out of water, please return it to the nearest lake, stream, or river. Conservation is everyone's responsibility!",objectivesText="Return 5 Struggling Carps to water.",rewardXP=6815,rewardCurrencies={{id=1553,amount=85},{id=1553,amount=88},{id=1553,amount=90},{id=1553,amount=92}},starts={{npcID=151352},{npcID=155941}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500,56156}},
[55790] = {id=55790,name="Requisition: More Deepcoral Buds",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55790},description="Many species feed on the deepcoral buds from the tall columns that grow in the east. Fathom rays feed on these buds especially. We use the buds as lures for fathom rays to use as mounts. But with our stores so low, we will not be able to provide the air support we need across Nazjatar . If you could gather more deepcoral buds and return them to the quartermaster, you will surely be rewarded.",objectivesText="Collect 5 Deepcoral Buds .",rewardXP=6815,rewardCurrencies={{id=1553,amount=85},{id=1553,amount=88},{id=1553,amount=90},{id=1553,amount=93}},starts={{npcID=151772},{npcID=153772}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500,56156}},
[55791] = {id=55791,name="Requisition: More Spiral Leaf",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55791},description="We are dangerously low on our medicine stores. If you find any Spiral Leaf, please leave your stores with the quartermaster. I should warn you, Spiral Leaf is immensely poisonous. Make sure to handle it with care. Some symptoms of spiral leaf poisoning include bouts of rage, immense bursts of strength, and murderous impulses. If you are exposed, find some naga and use your murderous energy for good.",objectivesText="Collect 5 Poisonous Spiral Leaf .",rewardXP=6815,rewardCurrencies={{id=1553,amount=85},{id=1553,amount=86},{id=1553,amount=89},{id=1553,amount=91}},starts={{npcID=151614},{npcID=151763}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500,56156}},
[55792] = {id=55792,name="Requisition: More Cone Shells",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55792},description="If we are going to arm ourselves against the naga, we will need far more supplies and armaments. Cone Shells make most of our armor and weapons. It's light, it's strong, and it's plentiful in this region. However, our supplies are running short and our forces need support. If you find yourself carrying Impregnable Cone Shells , please leave your stores with the quartermaster.",objectivesText="Collect 5 Impregnable Cone Shell .",rewardXP=6815,rewardCurrencies={{id=1553,amount=85},{id=1553,amount=86},{id=1553,amount=88},{id=1553,amount=89}},starts={{npcID=151633},{npcID=154436}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500,56156}},
[55793] = {id=55793,name="Requisition: More Flotsam",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55793},description="I have seen piles of flotsam in the sands to the west. If you could go out and scrounge anything useful from the debris, it could prove useful. Beware, that area is a hydra breeding ground and they have been growing more aggressive since the water receded. Once you've gathered some supplies, return to the quartermaster for your reward.",objectivesText="Collect 5 Piles of Flotsam.",rewardXP=6815,rewardCurrencies={{id=1553,amount=85},{id=1553,amount=86},{id=1553,amount=88},{id=1553,amount=89}},starts={{npcID=153509},{npcID=153512}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500,56156}},
[55795] = {id=55795,name="Mountain On the Move",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={55247,55252,55253,55254,55258,55462,55503,55504,55505,55506,55507,55795,55796,55797,55798},description="I have seen such fervor only once before. In times of peril, Torcali may call upon her children to defend her and those she looks after. It is likely she called your beast away. Go to her and see how you can help.",objectivesText="Speak to Torcali .",rewardGold=117000,rewardXP=3410,rewardItems={168408},starts={{npcID=154673}},ends={{npcID=151257}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={55247},questLines={{id=935,name="How to Train Your Direhorn",orderIndex=11,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=862},
[55796] = {id=55796,name="Heresy at the Crossroad",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={55247,55252,55253,55254,55258,55462,55503,55504,55505,55506,55507,55795,55796,55797,55798},description="< Torcali 's voice enters your mind.> My followers undertook a pilgrimage to a place called the Antul'Mita Plateau. It is regarded as the crossroads of Zandalar among my faithful and is the site of a Greater Wayshrine. I sense some great peril has fallen upon them. I have sent my children and my champion, Jo'nok, to their aid. Your charge is among them. Go to her and ensure that my acolytes reach the shrine safely. Let nothing stand in your way.",objectivesText="Meet Jo'nok at the Antul'Mita Plateau in Nazmir.",rewardGold=117000,rewardXP=3410,rewardItems={168408},starts={{npcID=151257}},ends={{npcID=151999}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={55795},questLines={{id=935,name="How to Train Your Direhorn",orderIndex=12,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[55797] = {id=55797,name="The Direhorn Mother's Fury",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={55247,55252,55253,55254,55258,55462,55503,55504,55505,55506,55507,55795,55796,55797,55798},description="This one protects de faithful who still seek de shrine. You will take your companion and show them de fury of a mother direhorn. Trust in your young friend. She has always known how to fight. Open de way. Slay de heretics that defile our loa's shrine.",objectivesText="Clear a path to the Greater Wayshrine in the Antul'Mita Plateau. Progress: A direhorn is gentle until it is provoked. Their mistake.",rewardGold=702000,rewardXP=10225,rewardItems={168408},starts={{npcID=151999}},ends={{npcID=151999}},mapCandidates={npc={862},zone={8500}},questType="standard",sourceQuests={55796},questLines={{id=935,name="How to Train Your Direhorn",orderIndex=13,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[55798] = {id=55798,name="Wander Not Alone",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=false,expansion=7,zoneID=8499,mapID=862,storyline={55247,55252,55253,55254,55258,55462,55503,55504,55505,55506,55507,55795,55796,55797,55798},description="She is here. I can feel her eyes upon us. My loa is generous. She will reward you for de service you have given her. Great Wanderer guide your path, <name>.",objectivesText="Speak to Torcali .",rewardGold=117000,rewardXP=3410,rewardItems={168408},starts={{npcID=151999}},ends={{npcID=151257}},mapCandidates={npc={862},zone={8499}},questType="standard",sourceQuests={55797},questLines={{id=935,name="How to Train Your Direhorn",orderIndex=14,flags=0}},db2PoiMapID=1642,db2PoiUiMapID=863},
[55799] = {id=55799,name="The Tide Turns",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={55469,55482,55485,55486,55488,55489,55490,55799,56356},series={55490},description="The time to strike is now. We must take the Tidestone of Golganneth and the Javelin of Suramar is our best chance of piercing the barrier around it. Every minute we wait is another minute when the sea can come crashing down on us. What forces we have will be arrayed below, just outside their encampment. We will need your strength in addition to the Javelin, <name>. We do not have enough forces to take it on our own.",objectivesText="Assault the naga camp and seize control of the Tidestone of Golganneth.",rewardGold=702000,rewardXP=10225,rewardCurrencies={{id=1721,amount=25}},starts={{npcID=151848}},ends={{npcID=153183}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55490},questLines={{id=938,name="Turning the Tide",orderIndex=7,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=46,flags=0}},campaigns={{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55801] = {id=55801,name="Requisition: We Need It All",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55801},description="We are dangerously low on all of our supplies. Please, you must go out and collect as much as you can. Please return with any resources you find to the quartermaster!",objectivesText="Collect resources from around Nazjatar .",rewardXP=6815,rewardCurrencies={{id=1560,amount=50},{id=1553,amount=135},{id=1553,amount=136},{id=1553,amount=137}},starts={{npcID=151618},{npcID=155940}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500,56156}},
[55813] = {id=55813,name="Aim High",level=10,requiredLevel=10,faction="both",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={55813},description="This conspiracy of ravens is preying on citizens of Rustbolt, it's unacceptable! Prince Erazmin has asked me to reduce their numbers, but I could really use your help. Can you help me kill some of them? Use my marker gun if you need it. I'll blast the ones you mark, and help bring them down.",objectivesText="12 Rustwing Ravens slain. Progress: Let's get to it!",rewardGold=2000,rewardXP=1415,rewardItems={166846,166970,166971,169279,246697},starts={{npcID=154568}},ends={{npcID=154568}},mapCandidates={npc={1462},zone={10290}},questType="standard",worldTaskTitle="Aim High",db2LabelIDs={5672},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55815] = {id=55815,name="Other Interests",level=10,requiredLevel=10,faction="both",categories={},flags={},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={55815},description="Madam Goya is interested in many unusual items other than just rare metals. Keep an eye out for these particular items during your travels in Nazjatar. Deliver them to me and Madam Goya will consider you for special access.",objectivesText="Deliver 5 Particularly Dense Rock to Steelsage Gao . Progress: Have you found these items?",rewardGold=257400,rewardXP=1415,rewardItems={166846,167902,167906,167910,167914,168222,202046},starts={{npcID=152575}},ends={{npcID=152575}},mapCandidates={npc={1462},zone={10290}},questType="standard",db2LabelIDs={5672}},
[55816] = {id=55816,name="The Other Place",level=10,requiredLevel=10,faction="both",categories={},flags={"daily","repeatable"},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55816},description="In my travels of the many possible futures, I discovered another place much like Rustbolt, but different. In this other time and place, very little is alive, everything is machines. You must travel to this other place. You will scan the memory banks of the Clockwork Giants you find there. Then we will use that data to ensure that our Rustbolt never becomes the other place.",objectivesText="Scan 10 Clockwork Giants. Progress: You must accomplish this task, for all of our sakes.",rewardGold=257400,rewardXP=1415,rewardItems={104304,153594,166846,166970,166971,168491,168813,169114,169870,170147,186974,246697},starts={{npcID=153993}},ends={{npcID=153993}},mapCandidates={npc={1462},zone={10290}},questType="standard",questLines={{id=968,name="Visit from Chromie",orderIndex=0,flags=0}},db2LabelIDs={5672},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55818] = {id=55818,name="Bounty: A Few Naga",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55818},description="The naga are our true enemy. All other efforts in Nazjatar are second to disrupting the naga's operations. If you want to be an asset to our cause then destroying the enemy is a quick way to earn your way here. When you have completed your task, report to the quartermaster to claim your reward.",objectivesText="Kill 15 naga. Progress: I know it is dirty work, but someone must do it.",rewardXP=6815,rewardCurrencies={{id=1553,amount=85},{id=1553,amount=86},{id=1553,amount=87},{id=1553,amount=88}},starts={{npcID=151614},{npcID=152942}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard"},
[55819] = {id=55819,name="Bounty: A Few Murlocs",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55819},description="While murlocs are often only a nuisance, certain factions are becoming more of a danger to our people. It is time we work together to preserve our safety while moving about Nazjatar . Put an end to some of the more aggressive murlocs and the quartermaster will award you.",objectivesText="Kill 15 murlocs.",rewardXP=6815,rewardCurrencies={{id=1553,amount=87},{id=1553,amount=88},{id=1553,amount=89},{id=1553,amount=91}},starts={{npcID=151352},{npcID=155941}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard"},
[55820] = {id=55820,name="Bounty: A Few Hydras",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55820},description="Our forces are desperately outmatched when it comes to the hydras. They are ferocious, tenacious, and deadly. We have retreated almost entirely out of the western region of Nazjatar . If we are going to hold the line against the naga, we need to make sure the western region is safe for our forces. Destroy as many hydras as you can manage, then report to the quartermaster.",objectivesText="Kill 10 hydras.",rewardXP=6815,rewardCurrencies={{id=1553,amount=85},{id=1553,amount=86},{id=1553,amount=87},{id=1553,amount=90}},starts={{npcID=151614},{npcID=152942}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard"},
[55821] = {id=55821,name="Bounty: A Few Coral Ancients",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55821},description="Coral ancients are beginning to awaken from their long slumber. I warn you, these are very dangerous creatures of immense size and power. If more of them begin to awaken, our forces will be in great danger. Once you have defeated some of these ancients, report to the quartermaster to claim your reward.",objectivesText="Kill 3 Coral Ancients.",rewardXP=6815,rewardItems={169377},rewardCurrencies={{id=1553,amount=85},{id=1553,amount=86},{id=1553,amount=87},{id=1553,amount=88}},starts={{npcID=153509},{npcID=153512}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard"},
[55822] = {id=55822,name="Bounty: A Few Makrura",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55822},description="The makrura have been a thorn in our side for too long. They are aggressive towards almost all species in Nazjatar and are very dangerous in groups. Less of them in our waters would certainly benefit our cause. Once you are done, report to the quartermaster to claim your reward.",objectivesText="Kill 10 makrura.",rewardXP=6815,rewardCurrencies={{id=1553,amount=85},{id=1553,amount=86},{id=1553,amount=89},{id=1553,amount=90}},starts={{npcID=151352},{npcID=155941}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard"},
[55823] = {id=55823,name="Bounty: A Few Crabs",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55823},description="The crab population is expanding too quickly within Nazjatar , endangering local plant life. Cull their numbers in our conservation effort. Report to the quartermaster to claim your reward.",objectivesText="Kill 15 crabs.",rewardXP=6815,rewardCurrencies={{id=1553,amount=87},{id=1553,amount=88},{id=1553,amount=89},{id=1553,amount=90}},starts={{npcID=151635},{npcID=153591}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard"},
[55824] = {id=55824,name="Bounty: A Few Snapdragons",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55824},description="Snapdragons are one of the most dangerous species on Nazjatar . The naga breed them for the viciousness and their ability as trackers. If we hope to keep our positions hidden from the naga, we must take out these groups of snapdragons immediately. After you are done, report to the quartermaster to claim your reward.",objectivesText="Kill 10 snapdragons.",rewardXP=6815,rewardCurrencies={{id=1553,amount=85},{id=1553,amount=86},{id=1553,amount=88},{id=1553,amount=89}},starts={{npcID=151618},{npcID=155940}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard"},
[55825] = {id=55825,name="Bounty: A Few Fathom Rays",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55825},description="The fathom ray population is eating all of the coral buds to the east. If we do not cull their numbers, we may have an environmental catastrophe on our hands. Once you have finished, report to the quartermaster to claim your reward.",objectivesText="Kill 10 fathom rays .",rewardXP=6815,rewardCurrencies={{id=1553,amount=86},{id=1553,amount=87},{id=1553,amount=88},{id=1553,amount=89}},starts={{npcID=151772},{npcID=153772}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard"},
[55827] = {id=55827,name="Bounty: More Naga",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55827},description="The naga are our true enemy. All other efforts in Nazjatar are second to disrupting the naga's operations. If you want to be an asset to our cause then destroying the enemy is a quick way to earn your way here. When you have completed your task, report to the quartermaster to claim your reward.",objectivesText="Kill 25 naga.",rewardXP=6815,rewardCurrencies={{id=1553,amount=85},{id=1553,amount=86},{id=1553,amount=91},{id=1553,amount=95}},starts={{npcID=151614},{npcID=152942}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard"},
