[55829] = {id=55829,name="Bounty: More Hydras",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55829},description="Our forces are desperately outmatched when it comes to the hydras. They are ferocious, tenacious, and deadly. We have retreated almost entirely out of the western region of Nazjatar . If we are going to hold the line against the naga, we need to make sure the western region is safe for our forces. Destroy as many hydras as you can manage, then report to the quartermaster.",objectivesText="Kill 15 hydras.",rewardXP=6815,rewardCurrencies={{id=1553,amount=86},{id=1553,amount=87},{id=1553,amount=88},{id=1553,amount=89}},starts={{npcID=151614},{npcID=152942}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard"},
