[55836] = {id=55836,name="Bounty: Elite Naga Forces",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55836},description="Strike at the elite naga forces within Nazjatar . Once we remove some of their leadership, our people will be able to move about more freely. Report to the quartermaster to claim your reward.",objectivesText="Kill 5 elite naga. Progress: I know it is dirty work, but someone must do it.",rewardXP=6815,rewardItems={170476},rewardCurrencies={{id=1560,amount=45},{id=1560,amount=50},{id=1721,amount=5},{id=1553,amount=135}},starts={{npcID=151614},{npcID=152942}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard"},
[55837] = {id=55837,name="Bounty: Dangerous Creatures",level=50,requiredLevel=50,faction="both",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55837},description="There are creatures in Nazjatar that are far more dangerous than their peers. I leave it to you to find them and defeat them. When you've done your part, report to the quartermaster to claim your reward.",objectivesText="Kill 1 rare creature in Nazjatar . Progress: I know it is dirty work, but someone must do it.",rewardXP=6815,rewardItems={167059},rewardCurrencies={{id=1721,amount=5},{id=1721,amount=6},{id=1553,amount=135},{id=1553,amount=136}},starts={{npcID=151352},{npcID=155941}},ends={{npcID=154002},{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questType="standard"},
[55845] = {id=55845,name="Plans of Attack",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={55845},description="<The attack plans are written on the parchment in fluorescent squid-ink and bound together with Azshara's seal.> Orders from our queen: Queen Azshara has commanded that all naga forces prepare for a full assault upon the Alliance invaders in our land. Details for the attack have been distributed to your various unit commanders. The Alliance shall tremble at the might of our queen!",objectivesText="Collect 8 Assault Plans . Progress: What news do you bring from the front?",rewardGold=234000,rewardXP=1415,rewardItems={35232,168396},rewardCurrencies={{id=1721,amount=3},{id=1748,amount=100},{id=1721,amount=2}},ends={{npcID=152942}},startObjects={{objectID=326148,mapID=1355,x=0.372,y=0.192}},coords={mapID=1355,source="quest_giver",x=0.4,y=0.555},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56156},worldTaskTitle="Plans of Attack",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55846] = {id=55846,name="Forbidden Rituals",level=50,requiredLevel=50,faction="alliance",sharable=false,expansion=7,zoneID=10052,mapID=1355,description="The naga use dark, forbidden rituals to subjugate the elements to their will. But such rituals threaten to destroy the elemental balance that binds this world together. The rituals must be stopped. Fortunately, the rituals the naga use are too elaborate to commit to memory. The ritual instructions are contained within ancient texts. If we destroy the ancient tomes that contain the rituals, the knowledge will be lost to the naga forever. Retrieve the tomes and I will see that they are destroyed",rewardGold=234000,rewardCurrencies={{id=1721,amount=3},{id=1750,amount=100},{id=1721,amount=2}},starts={{npcID=153147}},ends={{npcID=153147}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56156},worldTaskTitle="Forbidden Rituals",db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55851] = {id=55851,name="Essential Empowerment",level=50,requiredLevel=50,faction="both",categories={"legendary","campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55374,55400,55407,55425,55497,55533,55618,55851,57010},series={55533},description="Champion, excitin' news! I know yer busy dealin' with the naga threat right now, but we need ye to come back tae the Chamber of Heart! MOTHER's finally finished her calculations and she's got an idea of what tae do next! Hurry back tae Silithus as quick as ye can. Azeroth needs ye!",objectivesText="Meet Magni in the repaired Chamber of Heart in Silithus. Progress: There ye are! Chamber's lookin' better, eh?",rewardGold=23400,rewardXP=850,rewardItems={158075},starts={{npcID=154166},{npcID=154167}},ends={{npcID=154166}},mapCandidates={npc={1355},zone={10052}},questTurnInID=154166,questType="standard",sourceQuests={54972,55053},questLines={{id=923,name="Empowering the Heart",orderIndex=0,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=10,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=11,flags=0}},campaigns={{id=1,title="War Campaign",questLineID=923,questLineOrder=22,stallText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue."},{id=2,title="War Campaign",questLineID=923,questLineOrder=24,stallText="Scouts are searching for another suitable foothold on Kul Tiras.  Reach level 118 to continue."},{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0},{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},campaignLockText="Scouts are searching for another suitable foothold on Zandalar.  Reach level 118 to continue.",db2PoiMapID=2215,db2PoiUiMapID=1473},
[55860] = {id=55860,name="Sea Slug Liquidation",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55593,55595,55597,55598,55599,55600,55601,55860,55861,55937,56037,56038,56039,56234},description="My brief studies have shown that the refinement process creates a byproduct that is invisible to the naked eye, but is easily seen with refracted bioluminescent light. The sea floor is littered with creatures that produce just what we need to track down this weapons cache.",objectivesText="Collect 8 Bioluminescent Ooze from Luminescent Sea Slugs within Bloodfin Village. Progress: Do you have the ooze?",rewardGold=234000,rewardXP=6815,rewardItems={168539},starts={{npcID=153385}},ends={{npcID=153385}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56037},questLines={{id=942,name="Secrets in the Sea",orderIndex=9,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=34,flags=0}},campaigns={{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55861] = {id=55861,name="Let the Residue Lead You",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55593,55595,55597,55598,55599,55600,55601,55860,55861,55937,56037,56038,56039,56234},description="I have fashioned a device that will emit bioluminescent light when toggled on, allowing you to see any Azerite residue that lingers. It should give you a clear trail to the weapons cache. Good luck, <name>.",objectivesText="Follow the residue trail to locate the Azerite Weapons Cache .",rewardGold=234000,rewardXP=6815,rewardItems={168541},starts={{npcID=153385}},ends={{npcID=153385}},mapCandidates={npc={1355},zone={10052}},questTurnInID=153385,questType="standard",sourceQuests={55601,55860},questLines={{id=942,name="Secrets in the Sea",orderIndex=11,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=36,flags=0}},campaigns={{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55862] = {id=55862,name="Insight into Our Enemies",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55862,55863,55864,55865,55866,55867,55868,55869,55870,55967,56045,56046,56047,56236},description="There's no telling what awaits us within this land. We cannot press forward without first knowing exactly what we're up against. Although our new allies have suffered greatly at the hands of the naga, their hardships will not be in vain. The kelfin should have invaluable knowledge of Azshara's forces. With their help, we might be able to learn more about how our enemies operate. Speak with Neri and see what insight she can provide.",objectivesText="Speak to Neri to learn more about the naga within Nazjatar .",rewardGold=23400,rewardXP=850,starts={{npcID=151848}},ends={{npcID=149904}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56235},questLines={{id=943,name="Secrets in the Sea",orderIndex=0,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=25,flags=0}},campaigns={{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55863] = {id=55863,name="Deteriorating Knowledge",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55862,55863,55864,55865,55866,55867,55868,55869,55870,55967,56045,56046,56047,56236},description="The kelfin are no strangers to Azshara's cruelty. She commands creatures of darkness that entrap my kind and warp their minds. They eat away at their memories until nothing's left but an empty husk. If you can get to them soon, perhaps they'll still be in a state worth saving.",objectivesText="Rescue Fenn , Kono, and Esma from the clutches of mind-leeching Zoatroids.",rewardGold=234000,rewardXP=6815,starts={{npcID=149904}},ends={{npcID=153492}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55862},questLines={{id=943,name="Secrets in the Sea",orderIndex=1,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=26,flags=0}},campaigns={{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55864] = {id=55864,name="The Price is Death",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55862,55863,55864,55865,55866,55867,55868,55869,55870,55967,56045,56046,56047,56236},description="We've long believed that the ocean is big enough for all that wish to call it home. Unfortunately, the naga don't see it that way. They kill and capture our kind without remorse, and it's about time they paid the price.",objectivesText="Kill 10 naga within Zanj'ir wash and the Deepsea Slave Pens.",rewardGold=234000,rewardXP=6815,starts={{npcID=149904}},ends={{npcID=153495}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55862},questLines={{id=943,name="Secrets in the Sea",orderIndex=2,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=27,flags=0}},campaigns={{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55865] = {id=55865,name="What We Know of the Naga",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55862,55863,55864,55865,55866,55867,55868,55869,55870,55967,56045,56046,56047,56236},description="It feels good to be me again. I have you to thank for that. My head still hurts from the zoatroid's influence, but I think the others are worse off. Put some of this salve on their wounds, and I'll do my best to tell you what I know about the naga.",objectivesText="Tend to the Kelfin's wounds and hear what Fenn has to say about the naga. Progress: You're interrupting.",rewardGold=117000,rewardXP=3410,rewardItems={168948,169477,169478,169481},rewardChoices={169477,169478,169481},starts={{npcID=153492}},ends={{npcID=153492}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55863,55864},questLines={{id=943,name="Secrets in the Sea",orderIndex=3,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=28,flags=0}},campaigns={{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55866] = {id=55866,name="Scouting Undercover",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55862,55863,55864,55865,55866,55867,55868,55869,55870,55967,56045,56046,56047,56236},description="Entering the stronghold alone would be a death wish. The Zanj'ir slaughter outsiders on sight. The only way to get in without being killed is to appear to be under the effects of a zoatroid . Even then, the mind-shackled are put to work. You must obey all commands, or they will know your mind is still your own. Once the Zanj'ir believe you are mind-shackled, it should be easier to navigate their domain and uncover their secret.",objectivesText="Scout Zanj'ir Terrace while pretending to be mind-shackled.",rewardGold=23400,rewardXP=850,starts={{npcID=153492}},ends={{npcID=153936}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55865},questLines={{id=943,name="Secrets in the Sea",orderIndex=4,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=29,flags=0}},campaigns={{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55867] = {id=55867,name="Coveted Crystals",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55862,55863,55864,55865,55866,55867,55868,55869,55870,55967,56045,56046,56047,56236},description="Locating the weapons cache shouldn't be a problem once we have the proper tools. A little light and a lot of bioluminescent fluid is all we need! It all seems rather simple, doesn't it? But the key is in the Deepsea Crystal used to refract the light. I am told that the Bloodfin tribe covets these crystals, so it shouldn't be too much trouble to get your hands on one.",objectivesText="Collect a Deepsea Crystal from Hoarder Moarrgl. Progress: Have you found the crystal?",rewardGold=468000,rewardXP=8520,rewardItems={168540},rewardCurrencies={{id=1721,amount=5}},starts={{npcID=153422}},ends={{npcID=153422}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56045},questLines={{id=943,name="Secrets in the Sea",orderIndex=10,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=35,flags=0}},campaigns={{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55868] = {id=55868,name="Let the Residue Lead You",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55862,55863,55864,55865,55866,55867,55868,55869,55870,55967,56045,56046,56047,56236},description="I've fashioned a device that will emit bioluminescent light when toggled on, allowing you to see any Azerite residue that lingers. It should give you a clear trail to the weapons cache. Good luck, <name>.",objectivesText="Follow the residue trail to locate the Azerite Weapons Cache .",rewardGold=234000,rewardXP=6815,rewardItems={168541},starts={{npcID=153422}},ends={{npcID=153422}},mapCandidates={npc={1355},zone={10052}},questTurnInID=153422,questType="standard",sourceQuests={55867,55870},questLines={{id=943,name="Secrets in the Sea",orderIndex=11,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=36,flags=0}},campaigns={{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55869] = {id=55869,name="Clearing Out the Cache",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55862,55863,55864,55865,55866,55867,55868,55869,55870,55967,56045,56046,56047,56236},series={56236},description="<While inspecting the crate, a commotion can be heard within the cavern. A familiar voice, shouting orders.>",objectivesText="Deal with Priscilla Ashvane and her minions.",rewardGold=702000,rewardXP=10225,rewardCurrencies={{id=1553,amount=600}},ends={{npcID=151848}},startObjects={{objectID=326588,mapID=1355,x=0.46,y=0.519}},coords={mapID=1355,source="quest_giver",x=0.485,y=0.622},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55868},questLines={{id=943,name="Secrets in the Sea",orderIndex=12,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=37,flags=0}},campaigns={{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55870] = {id=55870,name="Sea Slug Liquidation",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55862,55863,55864,55865,55866,55867,55868,55869,55870,55967,56045,56046,56047,56236},description="The Azerite refinement process creates a byproduct that is invisible to the naked eye, but is easily seen with refracted bioluminescent light. The sea floor is littered with creatures that produce just what we need to track down this weapons cache.",objectivesText="Collect 8 Bioluminescent Ooze from Luminescent Sea Slugs within Bloodfin Village. Progress: Do you have the ooze?",rewardGold=234000,rewardXP=6815,rewardItems={168539},starts={{npcID=153422}},ends={{npcID=153422}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56045},questLines={{id=943,name="Secrets in the Sea",orderIndex=9,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=34,flags=0}},campaigns={{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55871] = {id=55871,name="Gather Friends",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55871},description="Outside is dangerous. It is safe in the Kelfin Pocket. We find the lost crabs, and slugs, and other friends. Here they get a new name and a new home. Find friends like these, and bring them home.",objectivesText="Collect Sandclaw Crabs and Muck Creepers for Narm . Progress: Did you bring us friends?",rewardGold=234000,rewardItems={168406,168407},rewardCurrencies={{id=1721,amount=3},{id=1747,amount=100},{id=1721,amount=2}},starts={{npcID=151311}},ends={{npcID=151311}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500},worldTaskTitle="Gather Friends",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55872] = {id=55872,name="Where They Hide",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55872},description="Those sneaky snakes have started to send assassins. They hide nearby and kill those they cannot take away to the slave pens. Even the sponges want to be rid of them! The spores will reveal the naga treachery... and then you can go ahead and kill them. We must keep our people safe!",objectivesText="Use the Fresh Sponge to reveal and kill 5 Zanj'ir Assassins . Progress: Did you find them all?",rewardGold=234000,rewardItems={168432},rewardCurrencies={{id=1721,amount=3},{id=1746,amount=100},{id=1721,amount=2}},starts={{npcID=153364}},ends={{npcID=153364}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500},worldTaskTitle="Where They Hide",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55873] = {id=55873,name="Kill the Kritch",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55873},description="Mrgglrr! Mrlg rmglr grlmrrgrr, grmm mrgl grrmrrgllrr. < Rlgmrr jumps around anxiously and points toward the cave.> Grrmrlgr mrg lrglgllmrrglm mlr mrlglmrgm mrl Kriiitchrglgr. <He makes a scary face and pinching motions with his hands.> Mrglrmgr lrg, mrgglmmmr! Mrlg grrrrml lrg.",objectivesText="Kill the Kritch . Progress: Mrgglrmr grm?",rewardGold=234000,rewardCurrencies={{id=1721,amount=3},{id=1745,amount=100},{id=1721,amount=2}},starts={{npcID=153537}},ends={{npcID=153537}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500},worldTaskTitle="Kill the Kritch",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55874] = {id=55874,name="Plug the Geysers",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55874},description="We're getting a geyser hit any minute now. The effects of the Tidestone are far-reaching. We have to do what we can to prevent any further destruction. Use this sealant to stall off the next round of eruptions!",objectivesText="Seal all of the unstable geysers. Progress: Did you take care of all of them?",rewardGold=234000,rewardItems={168482},rewardCurrencies={{id=1721,amount=3},{id=1746,amount=100},{id=1721,amount=2}},starts={{npcID=153524}},ends={{npcID=153524}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500},worldTaskTitle="Plug the Geysers",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55875] = {id=55875,name="Plug the Geysers",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55875},description="Just keep watching this spot... any second now... Once those geysers start firing, get in there and seal them up. The more they shake, the more everything breaks apart! We have to keep these things under control.",objectivesText="Seal all of the unstable geysers. Progress: Is it all sealed up?",rewardGold=234000,rewardItems={168482},rewardCurrencies={{id=1721,amount=3},{id=1746,amount=100},{id=1721,amount=2}},starts={{npcID=153834}},ends={{npcID=153834}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500},worldTaskTitle="Plug the Geysers",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55876] = {id=55876,name="Plug the Geysers",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55876},description="Earthquakes! Snakes! Water coming from every direction. What is going on around here? Neri said to plug some holes in the defenses - didn't think she'd mean it literally. Take some of this goo, next eruption, stick it in the hole.",objectivesText="Seal all of the unstable geysers. Progress: Goop them all up?",rewardGold=309800,rewardItems={168482},rewardCurrencies={{id=1721,amount=3},{id=1746,amount=100},{id=1721,amount=2}},starts={{npcID=153833}},ends={{npcID=153833}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500},worldTaskTitle="Plug the Geysers",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55877] = {id=55877,name="Plug the Geysers",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55877},description="We have been keeping an eye out for these unstable geysers. Since the water went away, the ocean has been trying to find a way back in. If we let it burst up just anywhere, we could all be doomed! Help me plug these up! Be careful, though, I found out the hard way they have a bit of a kick.",objectivesText="Seal all of the unstable geysers. Progress: Did you prevent the disaster?",rewardGold=234000,rewardItems={168482},rewardCurrencies={{id=1721,amount=3},{id=1746,amount=100},{id=1721,amount=2}},starts={{npcID=153522}},ends={{npcID=153522}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500},worldTaskTitle="Plug the Geysers",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55878] = {id=55878,name="Plug the Geysers",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55878},description="Have you heard about the geysers? All over the newly exposed areas, water trying to fill where it was pulled away. The ocean, she is angry. I don't think she likes Azshara either. We will keep filling this in until we can find a permanent fix.",objectivesText="Seal all of the unstable geysers. Progress: Get them stopped up for now?",rewardGold=234000,rewardItems={168482},rewardCurrencies={{id=1721,amount=3},{id=1746,amount=100},{id=1721,amount=2}},starts={{npcID=153819}},ends={{npcID=153819}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500},worldTaskTitle="Plug the Geysers",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55879] = {id=55879,name="Ride of the Scientifically Enhanced Boar",level=1,requiredLevel=1,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56344,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59347,59349,59350,59352,59354,59355,59356,60168,85678},description="We don't know how long the re-sizing will last, so let's get moving. You're going to ride this giant boar and mow down the army of undead between us and Wrathion . The large ones are pulsing with shadow magic. If you kill them, I bet it they'll take out any enemies near them. Let's hope Wrathion is willing to help us find Kalecgos.",objectivesText="Ride the Giant Boar to destroy the undead army. Progress: Please... help! I won't last much longer!",rewardGold=1130,rewardXP=250,rewardItems={175161,175162,175163,175164,175165,175166,175167,175168,175169,175170,175171,175172,175173,175174},rewardChoices={175161,175172,175171,175170,175173,175174,175162,175169,175165,175168,175163,175167,175164,175166},starts={{npcID=156280}},ends={{npcID=156280}},mapCandidates={npc={},zone={10424}},questGiverID=156280,questTurnInID=156280,questType="standard",sourceQuests={56034},questLines={{id=926,name="The Missing Expedition",orderIndex=15,flags=0},{id=1070,name="The Missing Expedition",orderIndex=13,flags=0},{id=5366,name="The Missing Expedition",orderIndex=15,flags=0},{id=5367,name="A Dark Ritual",orderIndex=0,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5366,questLineOrder=0,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."},{id=212,title="Exile's Reach",questLineID=5367,questLineOrder=1,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[55880] = {id=55880,name="Redistribution of Power",level=10,requiredLevel=10,faction="both",categories={},flags={"daily","repeatable"},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55880},description="Welcome back, dear test subject. Today's experiment is... <Pristy flips through some papers and smiles.> ...My pet project, the NRG-100 ! I am quite pleased with the potential improvements I've made to efficiency, potency, and destructivity. And the only thing I had to sacrifice was stability! When you're ready to proceed, strap on the NRG-100 .",objectivesText="Use the NRG-100 to charge 6 energy cells . Progress: Let's experiment!",rewardGold=257400,rewardXP=1415,rewardItems={166970,168122},starts={{npcID=150631}},ends={{npcID=150631}},mapCandidates={npc={1462},zone={10290}},questType="standard",db2LabelIDs={5672}},
[55881] = {id=55881,name="Purge the Totems",level=6,requiredLevel=6,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56344,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59347,59349,59350,59352,59354,59355,59356,60168,85678},description="The harpies' totems are scattered throughout the area. Harpies are known for using their magic to corrupt those nearby. Even now, I can hear foul whispers in the air... We must destroy these totems before any of us are tainted by their dark magic!",objectivesText="Set fire to 5 Harpy Totems . Progress: The totems are not particularly powerful. A simple light and tinder should do.",rewardGold=1015,rewardXP=875,rewardItems={168445,175199,175200,175201,175202,175231,175232,175233,175238},rewardChoices={175200,175238,175202,175233,175201,175232,175199,175231},starts={{npcID=156859}},ends={{npcID=156859}},mapCandidates={npc={},zone={10424}},questGiverID=156859,questTurnInID=156859,questType="standard",sourceQuests={55196},questLines={{id=926,name="The Missing Expedition",orderIndex=31,flags=0},{id=1071,name="The Harpy Problem",orderIndex=3,flags=0},{id=5367,name="A Dark Ritual",orderIndex=25,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5367,questLineOrder=1,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[55882] = {id=55882,name="Message to Base",level=6,requiredLevel=6,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56344,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59347,59349,59350,59352,59354,59355,59356,60168,85678},description="We did it! We're one step closer to getting off this island. Let's get back to camp and inform the captain of our success.",objectivesText="Return to the Alliance Camp and speak with Captain Garrick .",rewardGold=735,rewardXP=440,rewardItems={175191,175192,175193,175194,175223,175224,175225,175226},rewardChoices={175192,175224,175194,175226,175193,175225,175191,175223},starts={{npcID=156859}},ends={{npcID=156859}},mapCandidates={npc={},zone={10424}},questGiverID=156859,questTurnInID=156859,questType="standard",sourceQuests={55763,55764,55881},questLines={{id=926,name="The Missing Expedition",orderIndex=32,flags=0},{id=1071,name="The Harpy Problem",orderIndex=4,flags=0},{id=5367,name="A Dark Ritual",orderIndex=26,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5367,questLineOrder=1,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[55883] = {id=55883,name="To Soar Like a Ray",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55883},description="I like to find the eggs of the fathom rays before they hatch so we can form a bond with them. At least, when we can't swim, we can fly! Bring me a few more eggs to start a new thing - we'll call them Rayriders!",objectivesText="Bring back 7 fathom ray eggs . Progress: Did you find many eggs?",rewardGold=309800,rewardItems={168421,168425},rewardCurrencies={{id=1721,amount=3},{id=1747,amount=100},{id=1721,amount=2}},starts={{npcID=153321}},ends={{npcID=153321}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500},worldTaskTitle="To Soar Like a Ray",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55884] = {id=55884,name="Infestation of Madness",level=50,requiredLevel=50,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={55884},objectivesText="Kil'karrok makrura slain",rewardItems={167893},mapCandidates={npc={},zone={10052}},questType="world",db2Objectives={{text="Kil'karrok makrura slain",amount=10,type=0,objectID=153125,orderIndex=0}},worldTaskTitle="Infestation of Madness",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[55885] = {id=55885,name="Rico's Rescue",level=10,requiredLevel=10,faction="both",categories={},flags={"daily","repeatable"},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55885},description="Some of our Roughriders are missing, I tried to find them, but got pinned down here by the bugs! I could really use your help, <name>. See if you can save my missing troopers.",objectivesText="Rescue Trooper Levy , Katrin, and Bybee.",rewardGold=257400,rewardXP=1415,rewardItems={166846},starts={{npcID=153324}},ends={{npcID=152932}},mapCandidates={npc={1462},zone={10290}},questType="standard",db2LabelIDs={5672}},
[55886] = {id=55886,name="The Zanj'ir Brutalizer",expansion=7,mapID=1355,questType="world",worldTaskTitle="The Zanj'ir Brutalizer",db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
