[55901] = {id=55901,name="Rustbolt Rebellion",level=10,requiredLevel=10,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={55901},description="Aid the Rustbolt resistance.",objectivesText="Aid the Rustbolt resistance.",rewardXP=1415,rewardItems={168832},mapCandidates={npc={},zone={10290}},questType="world",db2Objectives={{text="Complete activities in Mechagon",amount=1,type=15,objectID=0,orderIndex=0}},worldTaskTitle="Rustbolt Rebellion",db2PoiMapID=1643,db2PoiUiMapID=1462,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[55905] = {id=55905,name="Abduction Reduction",level=10,requiredLevel=10,faction="both",categories={},flags={"daily","repeatable"},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55905},description="We got actual ABDUCTIONS happenin' here, <name>! Honest to gold, flying robots are swoopin' into town and snatchin' up people like it's closin' time at Gallywix's buffet! Lucky for the Rustbolt Resistance, Gazlowe called in me and my explosives to save the day. You wanna pitch in? Take one of my rocket launchers and blast those containment crates outta the sky. Whatever they've got trapped inside will come tumblin' down real fast, so you gotta run underneath and catch 'em.",objectivesText="Free 6 captured Mechagnomes and catch them before they hit the ground.",rewardGold=289300,rewardXP=1415,rewardItems={166846,166970,166971,168052,168430,169868,246697},starts={{npcID=153373}},ends={{npcID=153373}},mapCandidates={npc={1462},zone={10290}},questType="standard",questLines={{id=969,name="Visit from Penny Clobberbottom",orderIndex=0,flags=0}},db2LabelIDs={5672},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55937] = {id=55937,name="Clearing Out the Cache",level=50,requiredLevel=50,faction="alliance",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55593,55595,55597,55598,55599,55600,55601,55860,55861,55937,56037,56038,56039,56234},description="<While inspecting the crate, a commotion can be heard within the cavern. A familiar voice, shouting orders.>",objectivesText="Deal with Priscilla Ashvane and her minions.",rewardGold=702000,rewardXP=10225,rewardCurrencies={{id=1553,amount=600}},ends={{npcID=150101}},startObjects={{objectID=326588,mapID=1355,x=0.46,y=0.519}},coords={mapID=1355,source="quest_giver",x=0.458,y=0.7655},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55861},questLines={{id=942,name="Secrets in the Sea",orderIndex=12,flags=0},{id=5375,name="Welcome to Nazjatar",orderIndex=37,flags=0}},campaigns={{id=217,title="Nazjatar",questLineID=5375,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55965] = {id=55965,name="Westward Bound",level=6,requiredLevel=6,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56344,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59347,59349,59350,59352,59354,59355,59356,60168,85678},description="Captain Garrick wants us tae search west o' camp fer any other members of the expedition. Alaria and I will go on ahead. Meet us tae the west and we'll see what we can find.",objectivesText="Meet Bjorn Stouthands west of the Alliance Camp.",rewardGold=860,rewardXP=440,starts={{npcID=154300}},ends={{npcID=154300}},mapCandidates={npc={},zone={10424}},questGiverID=154300,questTurnInID=154300,questType="standard",sourceQuests={55194},questLines={{id=926,name="The Missing Expedition",orderIndex=17,flags=0},{id=1072,name="What Lurks Below",orderIndex=1,flags=0},{id=5367,name="A Dark Ritual",orderIndex=27,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5367,questLineOrder=1,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[55967] = {id=55967,name="Sating Snapdragons",level=50,requiredLevel=50,faction="horde",categories={"campaign"},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55862,55863,55864,55865,55866,55867,55868,55869,55870,55967,56045,56046,56047,56236},description="It's time for the snapdragons to feed, but it's a job best left to someone a little more expendable. The beasts will eat anything, including your arm if you don't move it away quickly enough. Luckily for you, they've developed a taste for Chitterspine Roe .",objectivesText="Collect Chitterspine Roe and feed it to Savage Snapdragons.",rewardGold=234000,rewardXP=6815,rewardItems={168753},starts={{npcID=153936}},ends={{npcID=153936}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55866},questLines={{id=943,name="Secrets in the Sea",orderIndex=5,flags=0},{id=5385,name="Welcome to Nazjatar",orderIndex=30,flags=0}},campaigns={{id=223,title="Nazjatar",questLineID=5385,questLineOrder=0}},db2PoiMapID=1718,db2PoiUiMapID=1355},
[55970] = {id=55970,name="Attrition",level=50,requiredLevel=50,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={55970},objectivesText="Naga waves defeated Tadpole Collectors destroyed",rewardGold=309800,rewardXP=1415,mapCandidates={npc={},zone={10052}},questType="world",db2Objectives={{text="Naga waves defeated",amount=4,type=0,objectID=153802,orderIndex=0},{text="Tadpole Collectors destroyed",amount=4,type=0,objectID=153758,orderIndex=1}},worldTaskTitle="Attrition",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[55973] = {id=55973,name="Deepcoil Experiments",level=50,requiredLevel=50,faction="none",categories={},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={55973},objectivesText="Void-touched Egg transported",rewardItems={168634},mapCandidates={npc={},zone={10052}},questType="world",db2Objectives={{text="Void-touched Egg transported",amount=20,type=0,objectID=153835,orderIndex=0}},worldTaskTitle="Deepcoil Experiments",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[55976] = {id=55976,name="Supplies From the Waveblade Ankoan",level=50,requiredLevel=50,faction="alliance",categories={"emissary","paragon"},flags={},sharable=false,expansion=7,zoneID=10052,mapID=1355,storyline={55976},description="The Waveblade Ankoan appreciate all the aid you've provided. Please take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.",objectivesText="Speak with Speaker Utia in Mezzamere for your reward.",rewardItems={169939},rewardCurrencies={{id=1553,amount=2500}},starts={{npcID=154140}},ends={{npcID=154140}},mapCandidates={npc={1355},zone={10052}},questGiverID=154140,questType="standard",worldSystems={paragonReputation={{factionID=2401,threshold=10000}}}},
[55979] = {id=55979,name="Iteration is Key",level=10,requiredLevel=10,faction="both",requiredProfessions={"engineering"},categories={},flags={},sharable=true,expansion=7,zoneID=10290,mapID=1462,storyline={55979},description="You've been holding out on me! Here I was, thinking that we're friends now and yet you neglected to tell me about your magnificient wrench! <Christy inspects it closely.> Well, not too magnificient... I recognize the Ub3r-Spanner from its blueprints, but whoever built this lacks a certain level of craftsmanship. I will upgrade it for you. Bring me the Overcharged Mecha-core from a mechanocrawler. No excuses. I will fix your mistakes.",objectivesText="Collect an Overcharged Mecha-core from the Overcharged Mechanocrawler. Progress: Imagine crafting an Ub3r-Spanner without an overcharged mecha-core ... Ha!",rewardGold=257400,rewardXP=1415,rewardItems={164740,168532,168533,168534,168535},starts={{npcID=152747}},ends={{npcID=152747}},mapCandidates={npc={1462},zone={10290}},questType="standard"},
[55980] = {id=55980,name="Turn the Scale",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55980},description="I have been trying to gather some of the scales from the young hydra nearby. Their flexibility and strength makes them incredibly versatile. With all the cranky old hydra tromping around, I don't stand much of a chance. Can you gather some up for me?",objectivesText="Collect 20 Hydra Scales from nearby hydra. Progress: Do you have enough?",rewardGold=341600,rewardItems={168519},rewardCurrencies={{id=1721,amount=3},{id=1746,amount=100},{id=1721,amount=2}},starts={{npcID=153543}},ends={{npcID=153543}},mapCandidates={npc={1355},zone={10052}},questType="standard",worldTaskTitle="Turn the Scale",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55981] = {id=55981,name="Right Beneath Their Eyes",level=7,requiredLevel=7,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56344,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59347,59349,59350,59352,59354,59355,59356,60168,85678},description="We need to get inside Darkmaul Citadel, rescue the captain of the expedition, and stop the ogre behind all of this. Meredy is going to cast an illusion to make you look like an ogre, and you're going to take us all in as \"prisoners.\" I'll be hiding my efforts to suppress the shadow magic in the meantime. Speak with Meredy when you're ready for her to cast the spell. Her illusion spell should be temporary, as long as she casts it in the proper way.",objectivesText="Have Meredy transform you into an ogre, then scout the nearby ogre citadel.",rewardGold=1470,rewardXP=1010,starts={{npcID=245397}},ends={{npcID=245397}},mapCandidates={npc={},zone={10424}},questGiverID=245397,questTurnInID=245397,questType="standard",sourceQuests={56344},questLines={{id=926,name="The Missing Expedition",orderIndex=23,flags=0},{id=1083,name="To Darkmaul",orderIndex=1,flags=0},{id=5367,name="A Dark Ritual",orderIndex=29,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5367,questLineOrder=1,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[55982] = {id=55982,name="The Lords of Water",expansion=7,mapID=1355,questType="world",db2Objectives={{orderIndex=1,type=15,amount=1,objectID=0,text="Naga forces broken"},{orderIndex=0,type=0,amount=1,objectID=153595,text="Choose a Water Lord"}},worldTaskTitle="The Lords of Water",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[55983] = {id=55983,name="A Safer Place",level=50,requiredLevel=50,faction="alliance",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55983},description="<The murloc seems to be in rough shape. Perhaps it would be safer with your allies in Mezzamere.>",objectivesText="Escort Mrrl back to Mezzamere.",rewardGold=234000,rewardXP=6815,starts={{npcID=152084}},ends={{npcID=152084}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={56156}},
[55984] = {id=55984,name="A Good Offense",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55984},description="Korl was told to watch the naga, so watching the naga I am. They're bad, friend, you know... just... terrible, horrible, bad monsters. I don't think I can just watch any more. They say the best defense is.. something... Help me teach them being being bad gets you smashed!",objectivesText="Kill 50 naga. Progress: Did you have fun?",rewardGold=309800,rewardCurrencies={{id=1721,amount=3},{id=1746,amount=100},{id=1721,amount=2}},starts={{npcID=153623}},ends={{npcID=153623}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500},worldTaskTitle="A Good Offense",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55985] = {id=55985,name="Extra Shiny",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55985},description="In the pools below are some small, lovely pearls. They were tossed in during some Azsh'ari ritual. Do they mean something? I have no idea. But I would like to have some of them. Be a lovely heavyfoot and go grab some for me, please!",objectivesText="Collect 10 Imbued Pearls . Progress: Did you find all of the pearls?",rewardGold=234000,rewardItems={168577},rewardCurrencies={{id=1721,amount=3},{id=1745,amount=100},{id=1721,amount=2}},starts={{npcID=153685}},ends={{npcID=153685}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500},worldTaskTitle="Extra Shiny",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55986] = {id=55986,name="Break a Few Eggs",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55986},description="This chamber is lovely and terrifying. What is born here will ruin the lives of so many. We cannot hurt the pods, but we can destroy the eggs of the serpents that guard them. Take out the eggs, every little bit helps. Poor eggs...",objectivesText="Destroy 10 Deepcoil Eggs . Progress: Did you destroy the eggs?",rewardGold=234000,rewardXP=1415,rewardCurrencies={{id=1721,amount=3},{id=1745,amount=100},{id=1721,amount=2}},starts={{npcID=153684}},ends={{npcID=153684}},mapCandidates={npc={1355},zone={10052}},questType="standard",sourceQuests={55500},worldTaskTitle="Break a Few Eggs",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55988] = {id=55988,name="Like Ogres to the Slaughter",level=7,requiredLevel=7,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56344,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59347,59349,59350,59352,59354,59355,59356,60168,85678},description="This is bad, <name>. Captain Kelra is bound by magic, the ogres are preparing to attack our friends, and the ritual is almost complete! I have to stay calm. We can't give up now, right? This may sound risky, but we need to take the fight to the ogres. We're behind enemy lines, so we'll be able to get the jump on them and draw their focus away from the camp. Take down any ogres that you can. That should keep them away from our friends.",objectivesText="Slay 8 ogres within Darkmaul Citadel. Progress: You need to slay the ogres so they don't go after our friends back at the camp.",rewardGold=2000,rewardXP=1010,rewardItems={175184,175185,175186,175187,175216,175217,175218,175219},rewardChoices={175186,175218,175184,175216,175187,175219,175185,175217},starts={{npcID=156942}},ends={{npcID=156942}},mapCandidates={npc={},zone={10424}},questGiverID=156942,questTurnInID=156942,questType="standard",sourceQuests={55981},questLines={{id=926,name="The Missing Expedition",orderIndex=24,flags=0},{id=1083,name="To Darkmaul",orderIndex=2,flags=0},{id=5367,name="A Dark Ritual",orderIndex=30,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5367,questLineOrder=1,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[55989] = {id=55989,name="Catapult Destruction",level=7,requiredLevel=7,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56344,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59347,59349,59350,59352,59354,59355,59356,60168,85678},description="Did you notice the catapults on our way up? It appears the ogres plan to attack our allies below. Lindie anticipated something like this and provided several bombs to handle siege weapons. Just don't shake them too hard.",objectivesText="Blow up 4 catapults within Darkmaul Citadel. Progress: Don't worry about the bombs. They'll blow up those catapults just fine.",rewardGold=1720,rewardXP=1010,starts={{npcID=156960}},ends={{npcID=156960}},mapCandidates={npc={},zone={10424}},questGiverID=156960,questTurnInID=156960,questType="standard",sourceQuests={55981},questLines={{id=926,name="The Missing Expedition",orderIndex=25,flags=0},{id=1083,name="To Darkmaul",orderIndex=3,flags=0},{id=5367,name="A Dark Ritual",orderIndex=31,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5367,questLineOrder=1,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[55990] = {id=55990,name="Controlling their Stones",level=7,requiredLevel=7,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56344,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59347,59349,59350,59352,59354,59355,59356,60168,85678},description="Captain Kelra won't last much longer. We need to acquire the ward stones to break the ritual before it kills her. I'll continue weakening the main ritual. Get those ward stones from the ogre lieutenants nearby.",objectivesText="Recover the Ward Stones from Jugnug, Wug, and Grunk, then use them to free Captain Kelra . Progress: So, these were the stones used to bind me? The ogres clearly were concerned about you thwarting their plans.",rewardGold=1720,rewardXP=1010,rewardItems={168599,168600,168601},starts={{npcID=156961}},ends={{npcID=156961}},mapCandidates={npc={},zone={10424}},questGiverID=156961,questTurnInID=156961,questType="standard",sourceQuests={55981},questLines={{id=926,name="The Missing Expedition",orderIndex=26,flags=0},{id=1083,name="To Darkmaul",orderIndex=4,flags=0},{id=5367,name="A Dark Ritual",orderIndex=32,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5367,questLineOrder=1,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[55991] = {id=55991,name="An End to Beginnings",level=7,requiredLevel=7,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=84,storyline={55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56344,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59347,59349,59350,59352,59354,59355,59356,60168,85678},description="You've done fine work within Exile's Reach , recruit. You should continue on to the Dragon Isles. I'm afraid I must change my plans and go back to Stormwind. I need to find out how the ogres found such powerful shadow magic. I'm sure we'll meet again. I can tell you've got many adventures ahead of you.",objectivesText="Speak with Kalecgos to travel to the Dragon Isles.",rewardGold=2000,rewardXP=2020,rewardItems={175176,175177,175178,175179,175208,175209,175210,175211,248336,256330},rewardChoices={175179,175211,175178,175210,175177,175209,175176,175208},starts={{npcID=245686}},ends={{npcID=154169},{npcID=238913}},mapCandidates={npc={84,2022},zone={10424}},questGiverID=245686,questType="standard",sourceQuests={55992},questLines={{id=926,name="The Missing Expedition",orderIndex=48,flags=0},{id=1083,name="To Darkmaul",orderIndex=6,flags=0},{id=5367,name="A Dark Ritual",orderIndex=34,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5367,questLineOrder=1,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[55992] = {id=55992,name="Dungeon: Darkmaul Citadel",level=7,requiredLevel=7,faction="alliance",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10424,mapID=1409,storyline={55194,55196,55639,55763,55764,55879,55881,55882,55965,55981,55988,55989,55990,55991,55992,56344,58914,58915,58917,58923,58933,58946,58953,58960,58962,59002,59347,59349,59350,59352,59354,59355,59356,60168,85678},description="You've slown down Gor'groth's efforts to control Kalecgos atop the citadel, but the ritual itself needs to be thwarted. You must storm the citadel and stop him from completing the ritual. His dark magic is an affront to the Light. We will need all the help we can get. Gor'groth's most elite lieutenants await within the citadel.",objectivesText="Complete the dungeon, \"Darkmaul Citadel\". Progress: You must go and slay Gor'groth before it is too late!",rewardGold=8000,rewardXP=2020,rewardItems={175175,175188,175189,175190,175207,175220,175221,175222,178162,178163,178164,178165,178166,178167,178168,178169,178171,178176,179360,179362},rewardChoices={175188,175220,175190,175222,175189,175221,175175,175207},starts={{npcID=156965}},ends={{npcID=156965}},mapCandidates={npc={},zone={10424}},questGiverID=156965,questTurnInID=156965,questType="standard",sourceQuests={55988,55989,55990},questLines={{id=926,name="The Missing Expedition",orderIndex=27,flags=0},{id=1083,name="To Darkmaul",orderIndex=5,flags=0},{id=5367,name="A Dark Ritual",orderIndex=33,flags=0}},campaigns={{id=212,title="Exile's Reach",questLineID=5367,questLineOrder=1,stallText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole."}},campaignLockText="Continue the campaign by accepting the quest Stand Your Ground from Private Cole.",db2PoiMapID=2175,db2PoiUiMapID=1409},
[55993] = {id=55993,name="A Little Edge",level=50,requiredLevel=50,faction="horde",categories={},flags={},sharable=true,expansion=7,zoneID=10052,mapID=1355,storyline={55993},description="In the darkest cavern. Below the naga city. You will find them. Creepy little crabs with sharp and pointy spines. I think we can find a way to use them. Projectiles didn't work so well in water, but now... Harvest some for us! Be careful, some of them are much sneakier than they have any right to be.",objectivesText="Collect 12 Chitterspine Spines . Progress: Did you gather the spines?",rewardGold=234000,rewardItems={168605},rewardCurrencies={{id=1721,amount=3},{id=1745,amount=100},{id=1721,amount=2}},starts={{npcID=153743}},ends={{npcID=153743}},mapCandidates={npc={1355},zone={10052}},questType="standard",worldTaskTitle="A Little Edge",db2PoiMapID=1718,db2PoiUiMapID=1355,db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[55994] = {id=55994,name="Do Not Drink",level=10,requiredLevel=10,faction="both",categories={},flags={"daily","repeatable"},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={55994},description="These troggs watch everything we do. They see us pouring oil into various machines, so now they're stealing the oil and drinking it. I think they believe it's going to turn them into machines! We need that oil back, before they drink it all!",objectivesText="Recover 12 containers of Stolen Oil . Progress: Get that oil back quick!",rewardGold=257400,rewardXP=1415,rewardItems={4536,64588,64598,64607,64616,64622,64639,157012,166846,166970,166971,168608,181802,183744,184843,246697},starts={{npcID=153750}},ends={{npcID=153750}},mapCandidates={npc={1462},zone={10290}},questType="standard",packageItems={159},worldTaskTitle="Do Not Drink",db2LabelIDs={5672},db2PoiMapID=1643,db2PoiUiMapID=1462},
[55995] = {id=55995,name="We Can Fix It",level=10,requiredLevel=10,faction="both",categories={"campaign"},flags={},sharable=false,expansion=7,zoneID=10290,mapID=1462,storyline={54087,54088,54945,54946,54947,54992,55040,55096,55609,55645,55729,55730,55731,55734,55736,55995,56131},description="<This drill rig looks capable of breaking through the nearby debris, but is clearly broken. If you can collect the parts required, Prince Erazmin should be able to show you how to repair it.>",objectivesText="Collect 40 Spare Parts and 1 Energy Cell from enemies in Junkwatt Depot. Progress: Us mechagnomes are always building something. Mechagon is littered with broken or half-completed construction projects.",rewardGold=257400,rewardXP=1415,rewardItems={166846,166970,170500},starts={{npcID=150956}},ends={{npcID=150956}},mapCandidates={npc={},zone={}},questGiverID=150956,questTurnInID=150956,questType="standard",sourceQuests={55729},questLines={{id=940,name="Expedition to Mechagon",orderIndex=11,flags=0},{id=941,name="Expedition to Mechagon",orderIndex=13,flags=0},{id=5376,name="Welcome to Mechagon",orderIndex=13,flags=0},{id=5384,name="Welcome to Mechagon",orderIndex=14,flags=0},{id=6062,name="Mechagon Intro - On Island",orderIndex=6,flags=0}},campaigns={{id=218,title="Mechagon",questLineID=5376,questLineOrder=0},{id=222,title="Mechagon",questLineID=5384,questLineOrder=0},{id=328,title="Mechagon Passport Control",questLineID=6062,questLineOrder=1}},db2PoiMapID=1643,db2PoiUiMapID=1462},
